-- PRENDERE I DATI DAL RESPONSABILE DELLA TRASMISSIONE ALLA STREGUA DELLE ALTRE TRASMISISONI
	DECLARE @idtrasmissiondocument varchar(10)
	SET @idtrasmissiondocument = 'MISSCSA'
	DECLARE @COD_FISC_SOSTITUTO varchar(16) --p_iva o CF
	DECLARE @DESCR_SOSTITUTO varchar(60)
	SELECT
		@COD_FISC_SOSTITUTO = ISNULL(registry.p_iva, registry.cf),
		@DESCR_SOSTITUTO = registry.title
		FROM trasmissionmanager
		JOIN trasmissiondocument
			ON trasmissionmanager.idtrasmissiondocument = trasmissiondocument.idtrasmissiondocument
		JOIN registry
			ON registry.idreg = trasmissionmanager.idreg
	WHERE trasmissionmanager.idtrasmissiondocument = @idtrasmissiondocument AND ayear = @ayear
