--------------------
-- SELECT FINALE
--------------------
-- convert(decimal(19,2), Round( ,2))
SELECT 
	F.codefin as Capitolo,
-- incassato/pagato in conto competenza 
	_01PagatoCompetenza as 'Gen. Comp.',
-- incassato/pagato in conto conto residui 
	_01PagatoResiduo as 'Gen.Res.',
