if object_id('[exp_contrattopassivo_pagato]') is not null
	drop PROCEDURE [exp_contrattopassivo_pagato]
go


CREATE                  PROCEDURE [exp_contrattopassivo_pagato]
(
	@ayear int,
	@idmankind varchar(10)
)
AS BEGIN
DECLARE @expenselevel INT
DECLARE @maxlevel INT
SELECT @expenselevel = expenseregphase FROM uniconfig
SELECT @maxlevel = MAX(nphase) FROM expensephase
DECLARE @yman int
DECLARE @nman int
--DECLARE @number decimal(19,2)
DECLARE @rownum int
DECLARE @ypay int
DECLARE @npay int

CREATE TABLE #mandate_detail 
( yman int, nman int, adate datetime, manager varchar (150), registry varchar(100), detaildescription varchar(150), npackage decimal(19,2), imponibile decimal(19,2), 
 taxrate decimal(19,2), discount varchar(11), total decimal(19,2) , ypay int, npay varchar(100), idmankind varchar(50), rownum int, idexp_pay int )
IF (SELECT multireg from mandatekind WHERE idmankind = @idmankind) = 'N'
BEGIN
		INSERT INTO #mandate_detail (idmankind, nman, yman, rownum, adate, detaildescription,manager, registry,npackage, imponibile, taxrate,
						discount, total )
		SELECT distinct MD.idmankind, MD.nman, MD.yman,MD.rownum, M.adate,  MD.detaildescription, MG.title, RG.title, MD.npackage,
			 MD.taxable,
			isnull(MD.taxrate * 100 , 0), 
			convert(varchar(10),isnull( MD.discount * 100, 0))+ '%', 
				ROUND(MD.taxable * MD.npackage * 
				  CONVERT(DECIMAL(19,6),M.exchangerate) *
				  (1 - CONVERT(DECIMAL(19,6),ISNULL(MD.discount, 0.0))),2
				)+
			ROUND(MD.tax,2)
			FROM mandatedetail MD
			JOIN mandate M
				ON MD.idmankind= M.idmankind 
				AND MD.nman = M.nman
				AND MD.yman = M.yman
			JOIN expensemandate EM
				ON MD.idmankind=EM.idmankind
				AND MD.nman=EM.nman
				AND MD.yman=EM.yman
				AND MD.idexp_taxable=EM.idexp
/*			JOIN expenselink EL
				ON EL.idparent = EM.idexp
				AND nlevel = 1
			JOIN expenselink EL2
				ON EL2.idparent = EL.idchild
				AND EL2.nlevel = 2	*/			
			LEFT OUTER JOIN manager MG
				ON M.idman = MG.idman
			LEFT OUTER JOIN  registry RG
				ON ISNULL(M.idreg,MD.idreg) = RG.idreg 
		WHERE MD.yman = @ayear
		AND EM.idmankind=@idmankind
		AND MD.stop IS NULL
END
ELSE 
BEGIN
		INSERT INTO #mandate_detail (idmankind, nman, yman, rownum, adate, detaildescription,manager, registry,npackage, imponibile, taxrate,
						discount, taxrate.total )
		SELECT distinct MD.idmankind, MD.nman, MD.yman,MD.rownum, M.adate,  MD.detaildescription, MG.title, RG.title, MD.npackage,
			 MD.taxable,
			isnull(MD.taxrate * 100 , 0), 
			convert(varchar(10),isnull( MD.discount * 100, 0))+ '%', 
				ROUND(MD.taxable * MD.npackage * 
				  CONVERT(DECIMAL(19,6),M.exchangerate) *
				  (1 - CONVERT(DECIMAL(19,6),ISNULL(MD.discount, 0.0))),2
				)+
			ROUND(MD.tax,2)
			FROM mandatedetail MD
			JOIN mandate M
				ON MD.idmankind= M.idmankind 
				AND MD.nman = M.nman
				AND MD.yman = M.yman
			JOIN expensemandate EM
				ON MD.idmankind=EM.idmankind
				AND MD.nman=EM.nman
				AND MD.yman=EM.yman
				AND MD.idexp_taxable=EM.idexp
/*			JOIN expenselink EL
				ON EL.idparent = EM.idexp
				AND nlevel = 1
			JOIN expenselink EL2
				ON EL2.idparent = EL.idchild
				AND EL2.nlevel = 2		*/
			LEFT OUTER JOIN manager MG
				ON M.idman = MG.idman
			LEFT OUTER JOIN  registry RG
				ON ISNULL(M.idreg,MD.idreg) = RG.idreg 
		WHERE MD.yman = @ayear
		AND EM.idmankind=@idmankind
		AND MD.stop IS NULL
END

DECLARE cursore CURSOR FORWARD_ONLY for 
SELECT MD.idmankind, MD.nman, MD.yman,MD.rownum, P.ypay , P.npay 
	FROM mandatedetail MD
	JOIN expensemandate EM
		ON MD.idmankind=EM.idmankind
		AND MD.nman=EM.nman
		AND MD.yman=EM.yman
		AND MD.idexp_taxable=EM.idexp
	JOIN expenselink EL
		ON EL.idparent = EM.idexp
		AND nlevel = @expenselevel
	JOIN expenselink EL2
		ON EL2.idparent = EL.idchild
		AND EL2.nlevel = @maxlevel
	JOIN expenselast ET
		ON ET.idexp = EL.idchild
	JOIN payment P
		ON ET.kpay = P.kpay
WHERE MD.yman = @ayear
AND EM.idmankind=@idmankind
AND MD.stop IS NULL
OPEN cursore
FETCH NEXT FROM cursore 
INTO 	@idmankind, @nman, @yman,@rownum, @ypay , @npay 
WHILE (@@fetch_status=0) 
BEGIN
	UPDATE #mandate_detail SET
	npay = ISNULL(npay, '') + CONVERT (varchar(4),@ypay) + '/' + convert (varchar(10),@npay) + ', '
	WHERE #mandate_detail.idmankind = @idmankind
	AND  #mandate_detail.yman = @yman
	AND #mandate_detail.nman = @nman
	AND #mandate_detail.rownum = @rownum
	--AND #mandate_detail.idexp_taxable = @idexp_taxable 
	FETCH NEXT FROM cursore 
	INTO @idmankind, @nman, @yman,@rownum, @ypay , @npay 
END
CLOSE cursore
DEALLOCATE cursore
-- Toglie la virgola finale
UPDATE #mandate_detail SET 
npay = substring (npay,1, len(npay)-1) 
WHERE npay IS NOT NULL
SELECT mandatekind.description AS 'Tipo Contratto', yman AS 'Esercizio', nman AS 'N.ordine', rownum AS 'N.dettaglio', adate AS 'Data contabile',
	 manager AS 'Nome responsabile', registry AS 'Nome fornitore',detaildescription AS 'Descrizione detaglio', npackage AS 'Quantità', 
	imponibile AS 'Imponibile', taxrate AS 'Iva %', discount AS 'Sconto',total AS 'Totale', npay AS 'Mandato'
FROM #mandate_detail 
JOIN mandatekind
	ON #mandate_detail.idmankind = mandatekind.idmankind
ORDER BY #mandate_detail.idmankind, #mandate_detail.yman, #mandate_detail.nman, #mandate_detail.rownum
END





GO

print '[exp_contrattopassivo_pagato] OK'

GO
if object_id('[closeyear_epsetupcopy]') is not null
	drop PROCEDURE [closeyear_epsetupcopy]
go
CREATE PROCEDURE [closeyear_epsetupcopy]
(
	@ayear int
)
AS BEGIN
CREATE TABLE #log (message varchar(255))
-- closeyear_epsetupcopy 2000
CREATE TABLE #accountlookup (oldidacc varchar(38), newidacc varchar(38))
INSERT #accountlookup
EXECUTE closeyear_fillaccountlookup @ayear

DECLARE @nextayear int
SET @nextayear = @ayear + 1
DECLARE @nextayearstr varchar(4)
SET @nextayearstr = CONVERT(varchar(4), @nextayear)
IF EXISTS (SELECT * FROM config WHERE ayear = @nextayear)
BEGIN
	UPDATE 	config SET 
		idacc_customer	    	= CUST.newidacc,
		idacc_deferredcredit	= DEF_C.newidacc,
		idacc_deferreddebit	= DEF_D.newidacc,
		idacc_ivapayment	= IVA_P.newidacc,
		idacc_ivarefund		= IVA_R.newidacc,
		idacc_supplier		= SUPP.newidacc,
		idacc_accruedrevenue	= ACCR.newidacc,
		idacc_accruedcost	= ACCC.newidacc,
		idacc_deferredcost	= DEFEC.newidacc,
		idacc_deferredrevenue	= DEFER.newidacc,
		idacc_pl		= PL.newidacc,
		idacc_patrimony		= PAT.newidacc,
		flagepexp		= oldconfig.flagepexp,
		idacc_unabatable = IND_C.newidacc,
		idacc_unabatable_refund = IND_R.newidacc,
		mainidacc_unabatable = MAININD_C.newidacc,
		mainidacc_unabatable_refund = MAININD_R.newidacc,
		idacc_mainivapayment = MAINIVA_P.newidacc,
		idacc_mainivapayment_internal = MAINIVA_P_INT.newidacc,
		idacc_mainivarefund =  MAINIVA_R.newidacc,
		idacc_mainivarefund_internal = MAINIVA_R_INT.newidacc,
		idacc_ivapayment12		= IVA_P12.newidacc,
		idacc_ivarefund12		= IVA_R12.newidacc,
		idacc_mainivapayment12	= MAINIVA_P12.newidacc,
		idacc_mainivapayment_internal12 = MAINIVA_P_INT12.newidacc,
		idacc_mainivarefund12	=  MAINIVA_R12.newidacc,
		idacc_mainivarefund_internal12 = MAINIVA_R_INT12.newidacc,
		idacc_revenue_gross_csa = REVENUE_GROSS_CSA.newidacc,
		idacc_invoicetoreceive = fatt_ricevere.newidacc,
		idacc_invoicetoemit = fatt_emettere.newidacc
	FROM  config, config oldconfig
	LEFT OUTER JOIN #accountlookup CUST
		ON CUST.oldidacc = oldconfig.idacc_customer
	LEFT OUTER JOIN #accountlookup DEF_C
		ON DEF_C.oldidacc = oldconfig.idacc_deferredcredit
	LEFT OUTER JOIN #accountlookup DEF_D
		ON DEF_D.oldidacc = oldconfig.idacc_deferreddebit
	LEFT OUTER JOIN #accountlookup IVA_P
		ON IVA_P.oldidacc = oldconfig.idacc_ivapayment
	LEFT OUTER JOIN #accountlookup IVA_R
		ON IVA_R.oldidacc = oldconfig.idacc_ivarefund
	LEFT OUTER JOIN #accountlookup SUPP
		ON SUPP.oldidacc = oldconfig.idacc_supplier
	LEFT OUTER JOIN #accountlookup ACCR
		ON ACCR.oldidacc = oldconfig.idacc_accruedrevenue
	LEFT OUTER JOIN #accountlookup ACCC
		ON ACCC.oldidacc = oldconfig.idacc_accruedcost
	LEFT OUTER JOIN #accountlookup DEFEC
		ON DEFEC.oldidacc = oldconfig.idacc_deferredcost
	LEFT OUTER JOIN #accountlookup DEFER
		ON DEFER.oldidacc = oldconfig.idacc_deferredrevenue
	LEFT OUTER JOIN #accountlookup PL
		ON PL.oldidacc = oldconfig.idacc_pl
	LEFT OUTER JOIN #accountlookup PAT
		ON PAT.oldidacc = oldconfig.idacc_patrimony
	LEFT OUTER JOIN #accountlookup IND_C
		ON IND_C.oldidacc = oldconfig.idacc_unabatable	
	LEFT OUTER JOIN #accountlookup IND_R
		ON IND_R.oldidacc = oldconfig.idacc_unabatable_refund 
	LEFT OUTER JOIN #accountlookup MAININD_C
		ON MAININD_C.oldidacc = oldconfig.mainidacc_unabatable 
	LEFT OUTER JOIN #accountlookup MAININD_R
		ON MAININD_R.oldidacc = oldconfig.mainidacc_unabatable_refund 
	LEFT OUTER JOIN #accountlookup MAINIVA_P
		ON MAINIVA_P.oldidacc = oldconfig.idacc_mainivapayment
	LEFT OUTER JOIN #accountlookup MAINIVA_P_INT
		ON MAINIVA_P_INT.oldidacc = oldconfig.idacc_mainivapayment_internal 
	LEFT OUTER JOIN #accountlookup MAINIVA_R
		ON MAINIVA_R.oldidacc = oldconfig.idacc_mainivarefund 
	LEFT OUTER JOIN #accountlookup MAINIVA_R_INT
		ON MAINIVA_R_INT.oldidacc = oldconfig.idacc_mainivarefund_internal
	LEFT OUTER JOIN #accountlookup IVA_P12
		ON IVA_P12.oldidacc = oldconfig.idacc_ivapayment12
	LEFT OUTER JOIN #accountlookup IVA_R12
		ON IVA_R12.oldidacc = oldconfig.idacc_ivarefund12
	LEFT OUTER JOIN #accountlookup MAINIVA_P12
		ON MAINIVA_P12.oldidacc = oldconfig.idacc_mainivapayment12
	LEFT OUTER JOIN #accountlookup MAINIVA_P_INT12
		ON MAINIVA_P_INT12.oldidacc = oldconfig.idacc_mainivapayment_internal12 
	LEFT OUTER JOIN #accountlookup MAINIVA_R12
		ON MAINIVA_R12.oldidacc = oldconfig.idacc_mainivarefund12 
	LEFT OUTER JOIN #accountlookup MAINIVA_R_INT12
		ON MAINIVA_R_INT12.oldidacc = oldconfig.idacc_mainivarefund_internal12
	LEFT OUTER JOIN #accountlookup REVENUE_GROSS_CSA
		ON REVENUE_GROSS_CSA.oldidacc = oldconfig.idacc_revenue_gross_csa
	LEFT OUTER JOIN #accountlookup fatt_ricevere
		ON fatt_ricevere.oldidacc = oldconfig.idacc_invoicetoreceive
	LEFT OUTER JOIN #accountlookup fatt_emettere
		ON fatt_emettere.oldidacc = oldconfig.idacc_invoicetoemit
	WHERE 	config.ayear = @nextayear
	AND	oldconfig.ayear = @ayear
	
	INSERT INTO #log
	VALUES('Trasferita configurazione E/P per esercizio ' + @nextayearstr)
END

INSERT INTO invoicekindyear
(
	ayear, idinvkind,
	idacc,
	idacc_deferred,
	idacc_discount,
	idacc_unabatable,
	idacc_deferred_intra,
	idacc_intra,
	idacc_unabatable_intra,
	cu, ct, lu, lt
)
SELECT
	@nextayear, idinvkind,
	ACC.newidacc,
	DEF.newidacc,
	DIS.newidacc,
	UNA.newidacc,
	DEFINTRA.newidacc,
	ACCINTRA.newidacc,
	UNAINTRA.newidacc,
	cu, GETDATE(), lu, GETDATE()
FROM invoicekindyear
LEFT OUTER JOIN #accountlookup ACC
	ON ACC.oldidacc = invoicekindyear.idacc
LEFT OUTER JOIN #accountlookup DEF
	ON DEF.oldidacc = invoicekindyear.idacc_deferred
LEFT OUTER JOIN #accountlookup DIS
	ON DIS.oldidacc = invoicekindyear.idacc_discount
LEFT OUTER JOIN #accountlookup UNA
	ON UNA.oldidacc = invoicekindyear.idacc_unabatable
LEFT OUTER JOIN #accountlookup ACCINTRA
	ON ACCINTRA.oldidacc = invoicekindyear.idacc_intra
LEFT OUTER JOIN #accountlookup DEFINTRA
	ON DEFINTRA.oldidacc = invoicekindyear.idacc_deferred_intra
LEFT OUTER JOIN #accountlookup UNAINTRA
	ON UNAINTRA.oldidacc = invoicekindyear.idacc_unabatable_intra
WHERE ayear = @ayear
AND NOT EXISTS
	(SELECT * FROM invoicekindyear I
	WHERE I.idinvkind = invoicekindyear.idinvkind
		AND I.ayear = @nextayear)
INSERT INTO #log
VALUES('Trasferita configurazione fatture per esercizio ' + @nextayearstr)
SELECT * FROM #log
END


