CREATE                                PROCEDURE rpt_missione_indkm
	@yitineration	smallint, 
	@nitineration			int
AS
	DECLARE @textclause varchar(1000)
	SELECT	@textclause = 	itinerationclause
	FROM	web_config
	
	BEGIN
		SELECT 
			admincarkmcost,
			admincarkm,
			owncarkmcost,
			owncarkm,
			footkmcost,
			footkm,
			clause_accepted,
