if object_id('[rpt_certritacconto_dett]') is not null
	drop PROCEDURE [rpt_certritacconto_dett]
go

CREATE     PROCEDURE [rpt_certritacconto_dett]
(
	@ayear smallint, 
	@start datetime,
	@stop datetime,
	@idreg int, 
	@certificatekind char(1)--@idser int,
	
)
AS BEGIN
-- exec [rpt_certritacconto_dett] 2010,{ts '2010-01-20 00:00:00'},{ts '2010-12-31 00:00:00'},21,'F'
CREATE TABLE #expensetax
(
	idexp varchar(40),
	idreg int,
	registry varchar(100),
	--taxcode int,
	taxdescription varchar(50),
	expensedescription varchar(150),	
	commondetail char(1),
	taxablenet decimal(19,2),
	employtax decimal(19,2),
	grossamount decimal (19,2),
	taxablegross decimal (19,2),
	service varchar(50),
	--idser int,
	npay int,
	countidser int,
	taxkind int
)
IF @ayear = 0
BEGIN
	SET @ayear='1900'
END
INSERT INTO #expensetax
(
	idexp,
	idreg,
	registry,
	--taxcode,
	taxdescription,
	expensedescription,
	taxablenet,
	employtax, 
	taxablegross,
	grossamount,
	service,
	--idser,
	npay,
	taxkind
)
SELECT
	T.idexp,
	T.idreg,
	registry.title,
	--T.taxcode,
	T.taxdescription,
	T.expensedescription,
	SUM(T.taxablenet),
	SUM(T.employtax),
	T.taxablegross,
	expensetotal.curramount,
	service.description,
	--service.idser,
	payment.npay,
	T.taxkind
FROM
	(SELECT
		SUM(ISNULL(E.taxablenet,0)) AS taxablenet,
		SUM(ISNULL(E.employtax,0)) AS employtax,
		isnull(E.taxablegross,0) as taxablegross,
		E.idexp,
		--E.taxcode,
		expense.idreg,
		E.description as taxdescription,
		expense.description as expensedescription,
		expense.idman,
		expenselast.idser,
		expenselast.kpay,
		case 
			when E.taxkind in (1,2,3) then E.taxkind
			Else 99
		end as taxkind
	FROM expensetaxofficialview AS E
	JOIN expense 
		ON expense.idexp = E.idexp
	JOIN expenselast
		ON expense.idexp = expenselast.idexp
	JOIN service
		ON service.idser = expenselast.idser
	JOIN tax T
		ON T.taxcode = E.taxcode
	WHERE expense.ymov = @ayear  
		AND expense.idreg=@idreg 
		--AND expenselast.idser = @idser   
		AND service.certificatekind = @certificatekind
		AND T.taxkind = 1 
		AND E.stop IS NULL
	GROUP BY expense.idreg,E.idexp,--E.taxcode,
		E.description,expense.description,
		expense.idman, expenselast.idser,
		expense.ymov,expenselast.kpay,e.taxablegross,E.taxkind	) AS T
JOIN registry 
	ON T.idreg = registry.idreg  
JOIN expensetotal
	ON T.idexp = expensetotal.idexp  
JOIN expenseyear
	ON T.idexp = expenseyear.idexp
JOIN service
	ON T.idser = service.idser  
JOIN payment 
	ON T.kpay = payment.kpay  
JOIN paymenttransmission
	ON payment.kpaymenttransmission = paymenttransmission.kpaymenttransmission  
WHERE (paymenttransmission.transmissiondate BETWEEN @start AND @stop)
	--AND service.idser = @idser
	AND service.certificatekind = @certificatekind
	AND expensetotal.ayear = @ayear
	AND expenseyear.ayear = @ayear
GROUP BY T.idreg, T.idexp, registry.title, registry.birthdate, registry.cf,
	--T.taxcode, 
	T.taxdescription, expensetotal.curramount, service.description,
	service.idser,
	payment.npay,
	T.taxablegross,T.expensedescription,T.taxkind		
	
/*
Nel report non è + usato
update #expensetax set countidser = (select count(distinct i.idexp)
					from #expensetax i
					where i.idreg = #expensetax.idreg
					)	
*/ 
SELECT countidser,
	#expensetax.idreg,
	#expensetax.registry,
	-- #expensetax.taxcode,   
	#expensetax.taxdescription,
	isnull(#expensetax.taxablenet,0) AS taxablenet,
	isnull(#expensetax.taxablegross,0) AS taxablegross ,
	isnull(#expensetax.employtax,0) as employtax,
	taxkind
FROM #expensetax
ORDER BY #expensetax.registry,taxkind
END


GO

print '[rpt_certritacconto_dett] OK'

GO
if object_id('[exp_proceeds_not_transmitted]') is not null
	drop PROCEDURE [exp_proceeds_not_transmitted]
go

--[exp_proceeds_not_transmitted] 2009,'27-11-2009','T','T'
CREATE   PROCEDURE [exp_proceeds_not_transmitted]
(
	@ayear int,	  			-- esercizio
	@printdate datetime,    -- filtro sulla data di stampa ufficiale
	@kind  char(1),         -- T: tutti, R:a regolarizzazione, N:non a regolarizzazione
	@annulled char(1)		-- T: tutti, S:annullate, N: non annullate
)
AS BEGIN
	CREATE TABLE #proceeds
	(
	phase varchar(50),
	idinc int,
	idreg int,
	registry varchar(100),
	ymov int,
	nmov int,
	doc varchar(35),
	docdate smalldatetime,
	description varchar(150),
	finance varchar(150),
	upb varchar(150),
	curramount decimal(19,2),
	ypro int,
	npro int,
	flagarrear char(1),
	adate smalldatetime,
	printdate smalldatetime,
	transmissiondate smalldatetime,
	annulmentdate	smalldatetime
	)

	INSERT INTO #proceeds
	(phase,idinc,idreg,registry,ymov,nmov,doc,docdate, 
	description,finance,upb,curramount,ypro,npro,
	flagarrear,adate,printdate,transmissiondate, annulmentdate)
	SELECT 
	IL.phase,IL.idinc, IL.idreg,IL.registry, IL.ymov, IL.nmov,
	IL.doc, IL.docdate, IL.description,IL.finance, IL.upb, IL.curramount,
	IL.ypro,IL.npro, IL.flagarrear,P.adate,P.printdate,PT.transmissiondate,P.annulmentdate
	FROM incomelastview IL
	JOIN proceeds P
		ON P.kpro = IL.kpro
	LEFT OUTER JOIN proceedstransmission PT
		ON PT.kproceedstransmission = P.kproceedstransmission
	WHERE IL.ypro = @ayear 
	AND P.printdate <= @printdate AND
	(
		(IL.nbill IS NULL AND @kind = 'N') OR
		(IL.nbill IS NOT NULL AND @kind = 'R') OR
		(@kind = 'T')
	)
	AND
	(
		((IL.curramount > 0) AND @annulled = 'N') OR
		((IL.curramount = 0) AND @annulled = 'S') OR
		(@annulled = 'T')
	)
	AND ISNULL(PT.transmissiondate,'2079-01-01')>@printdate
	ORDER BY IL.ymov, IL.nmov,IL.ypro,IL.npro
	SELECT 
		phase as 'Fase',
		ymov as 'Eserc. Mov.' ,
		nmov as 'Num. Mov',
		registry as 'Anagrafica',
		description as 'Descrizione',
		finance as 'Bilancio',
		upb as 'UPB',
		curramount as 'Importo Corrente',
		flagarrear as 'Compet.',
		ypro as 'Eserc. Reversale',
		npro as 'Num. Reversale',
		adate as 'Emissione',
		printdate as 'Stampa Uff.',
		transmissiondate as 'Trasmissione',
		annulmentdate	as 'Annullamento'
	FROM #proceeds
	ORDER BY ymov, nmov,ypro, npro
END

GO

print '[exp_proceeds_not_transmitted] OK'

