CREATE   	PROCEDURE exp_partitependenti
	@ayear 	int,
	@date 	datetime,
	@kind	char(1)
AS
BEGIN
CREATE TABLE #partitependenti(
	ybill smallint,
	nbill int,
	billkind varchar(10),
	tot_partite_pendenti decimal(19,2),					-- Importo totale delle partite pendenti attive		
	covered_partite_pendenti decimal(19,2),				-- Importo regolarizzato
	covered_partite_pendenti_PostDate decimal(19,2),	-- P.P.regolarizzate le cui reversali sono state trasmesse DOPO la data di stampa
	partite_pendenti decimal(19,2)						--Importo scoperto (da regolarizzare) => Importo totale visualizzato nella stampa			
)	
--		PARTITE PENDENTI ATTIVE (importo non regolarizzato delle partite pendenti aperte per chi usa tale gestione)
--		= Importo TOTALE delle partite pendenti attive
--		- calcolo l'importo REGOLARIZZATO delle partite pendenti attive
--		+ 	P.P.regolarizzate le cui reversali sono state trasmesse DOPO la data di stampa
INSERT INTO #partitependenti(ybill,nbill,billkind)
SELECT 	ybill,nbill,billkind
FROM bill
WHERE ybill = @ayear AND billkind = @kind AND adate <= @date 
IF (@kind = 'C')
BEGIN
	UPDATE #partitependenti SET tot_partite_pendenti = 
		ISNULL((SELECT bill.total
				FROM bill 
				WHERE bill.ybill = @ayear 
					AND bill.billkind = @kind 
					AND active = 'S'
					AND bill.adate <= @date
					and bill.nbill = #partitependenti.nbill	)
		,0)
		
	UPDATE #partitependenti SET covered_partite_pendenti = 
		ISNULL((SELECT SUM(bt.amount)
				FROM banktransaction bt
				JOIN proceeds p
					ON p.kpro = bt.kpro
				JOIN incomelast
					ON incomelast.kpro = p.kpro
				JOIN bill 
					ON bill.ybill  = @ayear
					AND bill.nbill = incomelast.nbill
				WHERE 	bt.transactiondate <= @date
					AND bt.yban = @ayear
					AND bt.idinc = incomelast.idinc
					AND bill.billkind = @kind
					AND bill.active = 'S'
					AND bill.adate <= @date
					AND bill.nbill = #partitependenti.nbill
					)
				,0)
	
	UPDATE #partitependenti SET covered_partite_pendenti_PostDate = 
		ISNULL((SELECT	SUM(bt.amount)
			FROM banktransaction bt
			JOIN proceeds p
				ON p.kpro = bt.kpro
			JOIN incomelast
				ON incomelast.kpro = p.kpro
			JOIN bill 
				ON bill.ybill  = @ayear
				AND bill.nbill = incomelast.nbill
			JOIN proceedstransmission t
				ON t.kproceedstransmission = p.kproceedstransmission
			WHERE t.transmissiondate > @date
				AND bt.yban = @ayear
				AND bt.idinc = incomelast.idinc
				AND bill.billkind = @kind
				AND bill.active <> 'S'
				AND bill.adate <= @date
				AND bill.nbill = #partitependenti.nbill
				)
			,0)
END
ELSE
BEGIN
	UPDATE #partitependenti SET tot_partite_pendenti = 
		ISNULL((SELECT bill.total
		FROM bill WHERE bill.ybill = @ayear 
			AND bill.billkind = @kind
			AND active = 'S'
			AND bill.adate <= @date
			AND bill.nbill = #partitependenti.nbill	)
		,0)
	UPDATE #partitependenti SET covered_partite_pendenti =
	ISNULL((SELECT
		SUM(bt.amount)
		FROM banktransaction bt
		JOIN payment p
			ON p.kpay = bt.kpay
		JOIN expenselast
			ON expenselast.kpay = p.kpay
		JOIN bill 
			ON bill.ybill  = @ayear
			AND bill.nbill = expenselast.nbill
		WHERE 	bt.transactiondate <= @date
			AND bt.yban = @ayear
			AND bt.idexp = expenselast.idexp
			AND bill.active = 'S'
			AND bill.adate <= @date
			AND bill.billkind = @kind
			AND bill.nbill = #partitependenti.nbill
			)
		,0)
	UPDATE #partitependenti SET covered_partite_pendenti_PostDate = 
	ISNULL((SELECT
		SUM(bt.amount)
		FROM banktransaction bt
		JOIN payment p 
			ON p.kpay = bt.kpay
		JOIN expenselast
			ON expenselast.kpay = p.kpay
		JOIN bill 
			ON bill.ybill  = @ayear
			AND bill.nbill = expenselast.nbill
		JOIN paymenttransmission t
			ON t.kpaymenttransmission = p.kpaymenttransmission
		WHERE t.transmissiondate > @date 
			AND bt.yban = @ayear
			AND bt.idexp = expenselast.idexp
			AND bill.active <> 'S'
			AND bill.adate <= @date
			AND bill.billkind = @kind
			AND bill.nbill = #partitependenti.nbill
			)
		,0)
END

UPDATE #partitependenti SET partite_pendenti =  tot_partite_pendenti - covered_partite_pendenti + covered_partite_pendenti_PostDate
-- Rimuovo quelle bollette per cui l'importo è stato tutto regolarizzato.
DELETE FROM #partitependenti WHERE partite_pendenti = 0
-- Inserisco la riga dei totali, per poter fare un confronto immediato ocn  la stampa della concordanza.
INSERT INTO #partitependenti(
	billkind ,
	tot_partite_pendenti,				
	covered_partite_pendenti,			
	covered_partite_pendenti_PostDate,	
	partite_pendenti 		)
SELECT
	'TOTALE',
	SUM(tot_partite_pendenti) ,				
	SUM(covered_partite_pendenti) ,			
	SUM(covered_partite_pendenti_PostDate),	
	SUM(partite_pendenti) 		
FROM #partitependenti
SELECT 
	billkind as 'Tipo',
	ybill as 'Esercizio',
	nbill as 'Numero',
	tot_partite_pendenti as 'Importo totale',
	covered_partite_pendenti as 'Importo regolarizzato',
	covered_partite_pendenti_PostDate as 'Importo trasmesso dopo la data di stampa',
	partite_pendenti as 'Importo scoperto'		
FROM #partitependenti
ORDER BY billkind,nbill

END 

GO

print 'exp_partitependenti OK'

GO
if object_id('[rpt_registro_ammortamenti_ente]') is not null
	drop PROCEDURE [rpt_registro_ammortamenti_ente]
go

-- exec rpt_registro_ammortamenti_ente 2009,1

CREATE      PROCEDURE [rpt_registro_ammortamenti_ente]
(
	@year int,
	@idinventory int
)
AS BEGIN
declare @SS1 datetime
declare @SS2 datetime
-------------------------------------------------------------------------------------
-------------- Elenco cespiti e accessori  ammortizzati nell'anno -------------------
-------------------------------------------------------------------------------------
DECLARE @firstday datetime
SET @firstday = CONVERT(datetime, '01-01-' + CONVERT(char(4),@year), 105)
DECLARE @lastday datetime
SET @lastday = CONVERT(datetime, '31-12-' + CONVERT(char(4),@year), 105)
DECLARE @MostraClassificazioneCompleta char(1)
SELECT @MostraClassificazioneCompleta = isnull(paramvalue,'N') 
FROM reportadditionalparam WHERE paramname = 'MostraClassificazioneCompleta'
 
		
-- Tabella temporanea destinata a contenere gli ammortamenti dell'esercizio corrente
CREATE TABLE #assetamortization
(
	idasset int,
	idpiece int,
	idinventoryagency int,
	acquirekind varchar(20),
	inventoryagency varchar(150),
	inventory varchar(50),
	inventorykind varchar(50),   
	ninventory int,
	assetloadkind varchar(50), 
	idassetloadkind int,
	yassetload int,
	nassetload int,
	category varchar(150),
	idinv int,
	description varchar(150),
	assetdescription varchar(150),
	assetoriginalvalue decimal(19,2),
	startvalue decimal(19,2),
	finalvalue decimal(19,2),
	namortization int,
	amortizationquota float,
	assetvalue decimal(19,2),
	adate smalldatetime,
	amortizationvalue decimal(19,2) 
)
	
set @ss1= getdate()
print 'INSERT INTO #assetamortization'
INSERT INTO #assetamortization
(	
	idasset,
	idpiece,
	acquirekind,
	idinventoryagency,
	inventoryagency,
	inventory,
	inventorykind,
	ninventory,
	description,
	assetdescription,
	idinv,
	category,
	assetloadkind,
	idassetloadkind,  
	yassetload,  
	nassetload,
	namortization,
	amortizationquota,
	assetvalue,
	adate,
	assetoriginalvalue
)
	SELECT  
	cespite_o_accessorio.idasset,
	cespite_o_accessorio.idpiece,
	CASE 
		WHEN cespite_o_accessorio.idpiece = 1 THEN 'Cespite' 
		WHEN cespite_o_accessorio.idpiece > 1 THEN 'Accessorio'
	END,
	inventory.idinventoryagency,
	inventoryagency.description,
	inventory.description,
	inventorykind.description,
	cespite.ninventory,
	carico.description,
	CASE 
		WHEN cespite_o_accessorio.idpiece = 1 THEN NULL
		WHEN cespite_o_accessorio.idpiece > 1 THEN caricocespite.description
	END,
	inventorytree.idinv, 
	inventorytree.description,
	assetloadkind.description,
	buono_carico.idassetloadkind,
	buono_carico.yassetload,
	buono_carico.nassetload,
	assetamortization.namortization,
	assetamortization.amortizationquota,
	assetamortization.assetvalue,
	CASE 
		WHEN assetamortization.flag & 1 =0 THEN assetamortization.adate
		WHEN assetamortization.flag & 1<>0 THEN isnull(assetunload.adate,assetload.ratificationdate)
	END,
	CASE	
			----------------------------------------------------------------------------------
			----------------- Considera i buoni di carico cespiti precedenti al 2005   -------
			----------------------------------------------------------------------------------
			WHEN cespite_o_accessorio.idpiece=1 AND
		 		((inventorykind.flag & 1 <> 0) OR ISNULL(buono_carico.yassetload,2006)<2005 
					OR(carico.idassetload IS NULL AND (carico.flag & 2 <> 0)))	
			THEN
			CONVERT(decimal(19,2),ROUND(
				ROUND(ISNULL(carico.taxable, 0)
				* (1 - CONVERT(decimal(19,6),ISNULL(carico.discount, 0))),2)
				+ ROUND(ISNULL(carico.tax,0) / carico.number,2)
				- ROUND(ISNULL(carico.abatable,0) / carico.number,2) 
			,2))
			----------------------------------------------------------------------------------
			------- Considera i buoni di carico del 2005 e i successivi  SENZA SCONTO --------
			----------------------------------------------------------------------------------			
			WHEN cespite_o_accessorio.idpiece= 1 AND
					NOT ((inventorykind.flag & 1 <> 0) OR ISNULL(buono_carico.yassetload,2006)<2005
							 OR  (carico.idassetload IS NULL AND (carico.flag & 2 <> 0)) )	
			THEN
			CONVERT(decimal(19,2),ROUND(
			ROUND(ISNULL(carico.taxable, 0),2)
			+ ROUND(ISNULL(carico.tax,0) / carico.number,2)
			- ROUND(ISNULL(carico.abatable,0) / carico.number,2) 
			,2))
			WHEN cespite_o_accessorio.idpiece>1 THEN
			CONVERT(decimal(19,2),ROUND(
			        ROUND(ISNULL(carico.taxable, 0)
			        * (1 - CONVERT(decimal(19,6),ISNULL(carico.discount, 0))),2)
				+ ROUND(ISNULL(carico.tax,0) / carico.number,2)
				- ROUND(ISNULL(carico.abatable,0) / carico.number,2) 
				,2))				
		 
		
	END
FROM  assetacquire as carico
JOIN	asset as cespite_o_accessorio
	ON carico.nassetacquire = cespite_o_accessorio.nassetacquire
LEFT OUTER JOIN assetload buono_carico
	ON buono_carico.idassetload = carico.idassetload
JOIN asset as cespite
	ON cespite.idasset = cespite_o_accessorio.idasset and cespite.idpiece = 1 
JOIN assetacquire as caricocespite
	ON caricocespite.nassetacquire = cespite.nassetacquire
LEFT OUTER JOIN assetloadkind
	ON  buono_carico.idassetloadkind = assetloadkind.idassetloadkind
JOIN inventory
	ON carico.idinventory = inventory.idinventory
JOIN inventoryagency
	ON inventory.idinventoryagency = inventoryagency.idinventoryagency
JOIN inventorykind
	ON inventory.idinventorykind = inventorykind.idinventorykind   
JOIN inventorytreelink
	ON inventorytreelink.idchild = carico.idinv
JOIN inventorytree
	ON inventorytree.idinv = inventorytreelink.idparent
JOIN assetamortization
	ON assetamortization.idasset = cespite_o_accessorio.idasset
	AND assetamortization.idpiece = cespite_o_accessorio.idpiece 
JOIN inventoryamortization
	ON assetamortization.idinventoryamortization = inventoryamortization.idinventoryamortization
LEFT OUTER JOIN assetunload
		ON  assetamortization.idassetunload = assetunload.idassetunload
LEFT OUTER JOIN assetload
		ON  assetamortization.idassetload = assetload.idassetload
WHERE   carico.idinventory = @idinventory
	AND (carico.idassetload IS NOT NULL OR ((carico.flag & 1 = 0) ))   --AND (carico.flag & 2 = 0)
	AND (inventoryamortization.flag & 2 <> 0)
	--AND assetamortization.adate >= @firstday
	AND ( 
        ( @MostraClassificazioneCompleta = 'N' AND inventorytreelink.nlevel = 1 )
        OR
        (@MostraClassificazioneCompleta = 'S' AND inventorytreelink.idparent = inventorytreelink.idchild )
        )
	AND (
	 		     (assetamortization.amortizationquota >0 AND 
			      (
			       ((assetamortization.flag & 1 = 0) AND YEAR(assetamortization.adate)= @year) OR 
			       ((assetamortization.flag & 1 <> 0) AND YEAR(assetload.ratificationdate)= @year)
				  )
			     )
				OR
	 		     (assetamortization.amortizationquota <0 AND 
			      (
			       ((assetamortization.flag & 1 = 0) AND YEAR(assetamortization.adate) = @year) OR 
			       ((assetamortization.flag & 1 <> 0) AND YEAR(assetunload.adate)= @year)
				  )
			     )
			    )
	
--ORDER BY carico.nassetacquire
set @ss2= getdate()
print datediff(ms,@ss1,@ss2)

UPDATE #assetamortization
SET amortizationvalue =
ISNULL(
	(SELECT ROUND(ISNULL(#assetamortization.assetvalue,0) * 
	ISNULL(#assetamortization.amortizationquota,0),2))
, 0.0)
UPDATE #assetamortization
SET finalvalue = assetoriginalvalue

print '	UPDATE #assetamortization SET amortizationvalue + '
set @ss1= getdate()
UPDATE #assetamortization
SET finalvalue = finalvalue + 
ISNULL(
	(SELECT
		SUM(ROUND(ISNULL(assetamortization.assetvalue,0) * 
		ISNULL(assetamortization.amortizationquota,0),2))
	FROM assetamortization
	JOIN inventoryamortization
		ON assetamortization.idinventoryamortization=inventoryamortization.idinventoryamortization
	LEFT OUTER JOIN assetunload
		ON  assetamortization.idassetunload = assetunload.idassetunload
	LEFT OUTER JOIN assetload
		ON  assetamortization.idassetload = assetload.idassetload
	WHERE assetamortization.idasset = #assetamortization.idasset AND assetamortization.idpiece = 1
		
			AND (
	 		     (assetamortization.amortizationquota >0 AND 
			      (
			       ((assetamortization.flag & 1 = 0) AND assetamortization.adate <= @lastday) OR 
			       ((assetamortization.flag & 1 <> 0) AND assetload.ratificationdate <= @lastday)
				  )
			     )
				OR
	 		     (assetamortization.amortizationquota <0 AND 
			      (
			       ((assetamortization.flag & 1 = 0) AND assetamortization.adate <= @lastday) OR 
			       ((assetamortization.flag & 1 <> 0) AND assetunload.adate <= @lastday)
				  )
			     )
			    )
		
		AND (inventoryamortization.flag & 2 <> 0)  
		
		)
,0)
WHERE #assetamortization.idpiece = 1
set @ss2= getdate()
print datediff(ms,@ss1,@ss2)

			
	-------------------------------------------------------------------------------------------------
	------ CARICHI ACCESSORI  DI BENI ---------------------------------------------------------------
	-------------------------------------------------------------------------------------------------
print '	UPDATE #assetamortization SET finalvalue '
set @ss1= getdate()
UPDATE #assetamortization
SET finalvalue = finalvalue +
ISNULL(
	(SELECT 
		SUM(
		ROUND(ISNULL(caricoaccessorio.taxable, 0)
		* (1 - CONVERT(decimal(19,6),ISNULL(caricoaccessorio.discount, 0))),2)
		+ ROUND(ISNULL(caricoaccessorio.tax,0) / caricoaccessorio.number,2)
		- ROUND(ISNULL(caricoaccessorio.abatable,0) / caricoaccessorio.number,2))
	FROM assetacquire as caricoaccessorio 
	JOIN asset as accessorio 
		ON caricoaccessorio.nassetacquire = accessorio.nassetacquire
	WHERE accessorio.idpiece > 1
		AND caricoaccessorio.adate <= @lastday --
		AND accessorio.idasset = #assetamortization.idasset
		AND caricoaccessorio.idassetload IS NOT NULL
		)
,0.0)
WHERE #assetamortization.idpiece = 1
	
set @ss2= getdate()
print datediff(ms,@ss1,@ss2)
print '	UPDATE #assetamortization SET finalvalue +'
set @ss1= getdate()
	-------------------------------------------------------------------------------------------------
	------ RIVALUTAZIONI DEGLI ACCESSORI DEI BENI ---------------------------------------------------
	-------------------------------------------------------------------------------------------------
UPDATE #assetamortization
SET finalvalue = finalvalue +
ISNULL(
	(SELECT
		SUM(ROUND(ISNULL(assetamortization.assetvalue,0) * 
			  ISNULL(assetamortization.amortizationquota,0),2))
	FROM assetacquire as caricoaccessorio 
	JOIN asset as accessorio 
		ON caricoaccessorio.nassetacquire = accessorio.nassetacquire
	JOIN assetamortization
		ON assetamortization.idasset = accessorio.idasset and assetamortization.idpiece = accessorio.idpiece
	LEFT OUTER JOIN assetunload
		ON assetamortization.idassetunload = assetunload.idassetunload
	LEFT OUTER JOIN assetload
		ON assetamortization.idassetload = assetload.idassetload
	JOIN inventoryamortization
		ON inventoryamortization.idinventoryamortization = assetamortization.idinventoryamortization
	WHERE accessorio.idasset = #assetamortization.idasset
		AND assetamortization.idpiece > 1
		AND (
				(
			     (ISNULL(assetamortization.amortizationquota,0)>0) AND 
		             ((assetamortization.flag & 1 = 0) OR 
			      (assetamortization.idassetload IS NOT NULL))
			     )		
			OR 
		       (
			     (ISNULL(assetamortization.amortizationquota,0)<0) AND 
		             ((assetamortization.flag & 1 = 0) OR 
			      (assetamortization.idassetunload IS NOT NULL))
			     )
			    )
		AND (inventoryamortization.flag & 2 <> 0)
		AND caricoaccessorio.adate <= @lastday
		AND caricoaccessorio.idassetload IS NOT NULL
		)
, 0.0)
WHERE #assetamortization.idpiece = 1

set @ss2= getdate()
print datediff(ms,@ss1,@ss2)
print '	UPDATE #assetamortization SET finalvalue -'
set @ss1= getdate()
	
	-------------------------------------------------------------------------------------------------
	--------------------- SCARICHI ACCESSORI  DI BENI -----------------------------------------------
	-------------------------------------------------------------------------------------------------
	-- Non consideriamo gli scarichi accessori associati allo scarico cespite
	-- ossia il valore del cespite rimane congelato al momento dello scarico
UPDATE #assetamortization
SET finalvalue = finalvalue -
ISNULL(
	(SELECT 
		SUM(
		ROUND(ISNULL(caricoaccessorio.taxable, 0)
		* (1 - CONVERT(decimal(19,6),ISNULL(caricoaccessorio.discount, 0))),2)
		+ ROUND(ISNULL(caricoaccessorio.tax,0) / caricoaccessorio.number,2)
		- ROUND(ISNULL(caricoaccessorio.abatable,0) / caricoaccessorio.number,2))
	FROM assetacquire as caricoaccessorio 
	JOIN asset as accessorio 
		ON caricoaccessorio.nassetacquire = accessorio.nassetacquire
	JOIN asset as cespite 
		ON cespite.idasset = #assetamortization.idasset
		AND cespite.idpiece = 1
	WHERE 
		accessorio.idpiece > 1 
		AND  accessorio.idasset = #assetamortization.idasset 
		AND (accessorio.idassetunload IS NOT NULL OR (accessorio.flag & 1 = 0))  --accessorio scaricato    
		AND (accessorio.idassetunload IS NULL OR       -- accessorio non scaricato esplicitamente
		    (cespite.idassetunload IS NULL AND (cespite.flag & 1 <> 0))  OR --cespite non scaricato
		    (cespite.idassetunload <> accessorio.idassetunload) --buono scarico distinto
		)
		)
, 0.0)
WHERE #assetamortization.idpiece = 1
	
set @ss2= getdate()
print datediff(ms,@ss1,@ss2)
print '	UPDATE #assetamortization SET finalvalue -'
set @ss1= getdate()
	-------------------------------------------------------------------------------------------------
	-------------------- RIVALUTAZIONI DEGLI ACCESSORI SCARICATI DEI BENI ---------------------------
	-------------------------------------------------------------------------------------------------
UPDATE #assetamortization
SET finalvalue = finalvalue - 
ISNULL(
	(SELECT
	SUM(ROUND(ISNULL(assetamortization.assetvalue,0) * 
		  ISNULL(assetamortization.amortizationquota,0),2))
	FROM assetacquire as caricoaccessorio 
	JOIN asset as accessorio 
		ON caricoaccessorio.nassetacquire = accessorio.nassetacquire
	JOIN asset as cespite 
		ON cespite.idasset = #assetamortization.idasset
		AND cespite.idpiece = 1
	JOIN assetamortization
		ON assetamortization.idasset = accessorio.idasset
		AND assetamortization.idpiece = accessorio.idpiece
	JOIN inventoryamortization
		ON inventoryamortization.idinventoryamortization = assetamortization.idinventoryamortization
	WHERE accessorio.idasset = #assetamortization.idasset 
		AND assetamortization.idpiece > 1
		AND (inventoryamortization.flag & 2 <> 0)
		AND (
	            (
			     (ISNULL(assetamortization.amortizationquota,0)>0) AND 
		             ((assetamortization.flag & 1 = 0) OR 
			      (assetamortization.idassetload IS NOT NULL))
			     )
			 OR 
	            (
			     (ISNULL(assetamortization.amortizationquota,0)<0) AND 
		             ((assetamortization.flag & 1 = 0) OR 
			      (assetamortization.idassetunload IS NOT NULL))
			     )
			    )
		AND (accessorio.idassetunload IS NOT NULL OR (accessorio.flag & 1 = 0)) 
		AND (accessorio.idassetunload IS NULL OR      --accessorio non scaricato esplicitamente
		    (cespite.idassetunload IS NULL AND (cespite.flag & 1 <> 0))  OR --cespite non scaricato
		    (cespite.idassetunload <> accessorio.idassetunload) --buono scarico distinto
		 )
		)
, 0.0)
WHERE #assetamortization.idpiece = 1

set @ss2= getdate()
print datediff(ms,@ss1,@ss2)
print '	UPDATE #assetamortization SET finalvalue +'
set @ss1= getdate()
UPDATE #assetamortization
SET finalvalue = finalvalue +
ISNULL(
	(SELECT
		 SUM(ROUND(ISNULL(assetamortization.assetvalue,0) * 
		 ISNULL(assetamortization.amortizationquota,0),2))
	FROM assetamortization
	JOIN asset
		ON  assetamortization.idasset=asset.idasset
		AND assetamortization.idpiece=asset.idpiece
	JOIN inventoryamortization
		ON assetamortization.idinventoryamortization=inventoryamortization.idinventoryamortization
	LEFT OUTER JOIN assetunload
		ON assetamortization.idassetunload = assetunload.idassetunload
	LEFT OUTER JOIN assetload
		ON assetamortization.idassetload = assetload.idassetload
	WHERE asset.idasset = #assetamortization.idasset AND asset.idpiece > 1
		AND (
	 	     (assetamortization.amortizationquota >0 AND 
				(	
				 ((assetamortization.flag & 1 = 0) AND assetamortization.adate <= @lastday) OR 
				 ((assetamortization.flag & 1 <> 0) AND assetload.ratificationdate <= @lastday)
				)
	 	     )
			OR
	 	     (assetamortization.amortizationquota <0 AND 
				(	
				 ((assetamortization.flag & 1 = 0) AND assetamortization.adate <= @lastday) OR 
				 ((assetamortization.flag & 1 <> 0) AND assetunload.adate <= @lastday)
				)
	 	     )
		    )
		AND (inventoryamortization.flag & 2 <> 0)
		AND asset.idasset = #assetamortization.idasset
		AND asset.idpiece = #assetamortization.idpiece),0)
WHERE #assetamortization.idpiece > 1
	
UPDATE #assetamortization
SET startvalue = finalvalue - amortizationvalue

set @ss2= getdate()
print datediff(ms,@ss1,@ss2)

SELECT 
	idasset,
	idpiece,
	idinventoryagency,
	acquirekind,
	inventoryagency,
	inventory,
	inventorykind,
	ninventory,
	assetloadkind, 
	idassetloadkind,
	yassetload,
	nassetload,
	category,
	#assetamortization.idinv,
	inventorytree.codeinv,
	#assetamortization.description,
	assetdescription,
	assetoriginalvalue,
	startvalue,
	finalvalue,
	namortization,
	amortizationquota,
	assetvalue,
	adate,
	amortizationvalue
FROM #assetamortization
JOIN inventorytree
	on #assetamortization.idinv = inventorytree.idinv
ORDER BY adate, ninventory
END

GO

print '[rpt_registro_ammortamenti_ente] OK'

GO
if object_id('rpt_unified_bilconsuntivo') is not null
	drop procedure rpt_unified_bilconsuntivo
go

CREATE   procedure rpt_unified_bilconsuntivo
(
	@ayear int,
	@date datetime,
	@finpart char(1),
	@levelusable tinyint,
	@suppressifblank char(1),
	@officialvar  char(1)
) as begin
	DECLARE @idupb varchar(36)
	SET @idupb = '%' -- non deve filtrare su UPB
	-- lettura del livello di bilancio consolidato
	DECLARE @unifiedlevel tinyint
	SELECT @unifiedlevel = MIN(unifiedfinlevel) FROM commonconfig WHERE ayear = @ayear 
	IF(@levelusable > @unifiedlevel)
	BEGIN
		SET @levelusable = @unifiedlevel
	END
	create table #bilconsuntivo (
		code1 varchar(50), desc1 varchar(150), descliv1 varchar(50), order1 varchar(50), 
		code2 varchar(50), desc2 varchar(150), descliv2 varchar(50), order2 varchar(50), 
		code3 varchar(50), desc3 varchar(150), descliv3 varchar(50), order3 varchar(50),
		code4 varchar(50), desc4 varchar(150), descliv4 varchar(50), order4 varchar(50),
		code5 varchar(50), desc5 varchar(150), descliv5 varchar(50), order5 varchar(50),
		codeupb			varchar(50),
		idupb 			varchar(36),
		upb   			varchar(150),
		upbprintingorder	varchar(50),
		initialprevision	decimal(19,2),
		variation	decimal(19,2),
		secondaryprevision decimal(19,2),
		secondaryvariation decimal(19,2),
		currentarrears decimal(19,2),
		mov_finphase_C decimal(19,2),
		var_finphase_C decimal(19,2),
		mov_maxphase_C decimal(19,2),
		var_maxphase_C decimal(19,2),
		mov_finphase_R decimal(19,2),
		var_finphase_R decimal(19,2),
		mov_maxphase_R decimal(19,2),
		var_maxphase_R decimal(19,2),
		previsionkind char(1),
		showincomesurplus char(1),
		supposed_ff_jan01 decimal(19,2),
		supposed_aa_jan01 decimal(19,2),
		ff_jan01 decimal(19,2),
		aa_jan01 decimal(19,2),
		tosuppress char,
		nlevel tinyint,
		floatfund_01_jan_used decimal(19,2),
		supposed_aa_01_jan_used decimal(19,2),
		aa_01_jan_used decimal(19,2),
		supposed_ff_01_jan_used decimal(19,2)
	)
	declare @iddbdepartment varchar(50)
	declare @crsdepartment cursor
	set @crsdepartment = cursor for select  iddbdepartment from dbdepartment
						 where (start is null or start <= @ayear ) AND ( stop is null or stop >= @ayear)
	open @crsdepartment
	fetch next from @crsdepartment into @iddbdepartment
	while @@fetch_status=0 begin
		declare @s varchar(400)
		set @s = @iddbdepartment + '.rpt_bilconsuntivo'
		insert into #bilconsuntivo 
			(
			code1, desc1, descliv1, order1, 
			code2, desc2, descliv2, order2, 
			code3, desc3, descliv3, order3,
			code4, desc4, descliv4, order4,
			code5, desc5, descliv5, order5,
			codeupb, idupb,	upb, upbprintingorder,
			initialprevision, variation,
			secondaryprevision, secondaryvariation,
			currentarrears,
			mov_finphase_C,	var_finphase_C,	mov_maxphase_C,
			var_maxphase_C,	mov_finphase_R,	var_finphase_R,	mov_maxphase_R,	var_maxphase_R,
			previsionkind, showincomesurplus, supposed_ff_jan01, supposed_aa_jan01,
			ff_jan01, aa_jan01, tosuppress,	nlevel,
			floatfund_01_jan_used, supposed_aa_01_jan_used,
			aa_01_jan_used,supposed_ff_01_jan_used
			)
			exec @s @ayear,	@date, @finpart, @levelusable, @idupb, 'N', 'S', @suppressifblank, @officialvar
		fetch next from @crsdepartment into @iddbdepartment
	end
	select 
		code1, desc1, descliv1, order1, 
		code2, desc2, descliv2, order2, 
		code3, desc3, descliv3, order3,
		code4, desc4, descliv4, order4,
		code5, desc5, descliv5, order5,
		null as codeupb, null as idupb,	null as upb, null as upbprintingorder,
		sum(initialprevision) as initialprevision, sum(variation) as variation,
		sum(secondaryprevision) as secondaryprevision, sum(secondaryvariation) as secondaryvariation,
		sum(currentarrears) as currentarrears,
		sum(mov_finphase_C) as mov_finphase_C, sum(var_finphase_C) as var_finphase_C, 
		sum(mov_maxphase_C) as mov_maxphase_C,
		sum(var_maxphase_C) as var_maxphase_C , sum(mov_finphase_R) as mov_finphase_R,
		sum(var_finphase_R) as var_finphase_R, sum(mov_maxphase_R) as mov_maxphase_R, 
		sum(var_maxphase_R) as var_maxphase_R,
		previsionkind, showincomesurplus, 
		sum(supposed_ff_jan01) as supposed_ff_jan01, sum(supposed_aa_jan01) as supposed_aa_jan01,
		sum(ff_jan01) as ff_jan01, sum(aa_jan01) as aa_jan01, 
		tosuppress, nlevel,
		sum(floatfund_01_jan_used) as floatfund_01_jan_used,
		sum(supposed_aa_01_jan_used) as supposed_aa_01_jan_used,
		sum(aa_01_jan_used) as aa_01_jan_used,
		sum(supposed_ff_01_jan_used) as supposed_ff_01_jan_used
		from #bilconsuntivo
		group by
		code1, desc1, descliv1, order1, 
		code2, desc2, descliv2, order2, 
		code3, desc3, descliv3, order3,
		code4, desc4, descliv4, order4,
		code5, desc5, descliv5, order5,
		previsionkind, showincomesurplus, 
		tosuppress, nlevel
end		



GO

print 'rpt_unified_bilconsuntivo OK'

