if object_id('[trg_upd_upbmovtotal]') is not null
	drop PROCEDURE [trg_upd_upbmovtotal]
go

CREATE                 PROCEDURE [trg_upd_upbmovtotal]
(
	@movkind char(1),
	@idfin int,
	@idupb varchar(36),
	@flagarrear char(1),
	@nphase tinyint,
	@amount decimal(19,2)
)
AS BEGIN
DECLARE @countyear int
IF @idfin IS NOT NULL
BEGIN
	DECLARE @nlevel tinyint
	SELECT @nlevel = nlevel FROM fin WHERE idfin = @idfin
	WHILE (@nlevel >= 1)
	BEGIN
		IF (@movkind = 'I')
		BEGIN
			SELECT @countyear = COUNT(*) 
			FROM upbincometotal
			WHERE idfin = @idfin 
				AND idupb = @idupb
				AND nphase = @nphase
			IF (@countyear = 0)
			BEGIN
				IF (@flagarrear = 'C')
				BEGIN
					INSERT INTO upbincometotal (idfin, idupb, nphase, totalcompetency)
					VALUES (@idfin, @idupb, @nphase, @amount)
				END
				ELSE
				BEGIN
					INSERT INTO upbincometotal (idfin, idupb, nphase, totalarrears)
					VALUES (@idfin, @idupb, @nphase, @amount)
				END
			END
			ELSE
			BEGIN
				IF (@flagarrear = 'C')
				BEGIN
					UPDATE upbincometotal SET
					totalcompetency = ISNULL(totalcompetency, 0) + @amount
					WHERE idfin = @idfin
						AND idupb = @idupb
						AND nphase = @nphase
				END
				ELSE
				BEGIN
					UPDATE upbincometotal SET
					totalarrears = ISNULL(totalarrears, 0) + @amount
					WHERE idfin = @idfin
						AND idupb = @idupb
						AND nphase = @nphase
				END
			END
		END
		IF (@movkind = 'E')
		BEGIN
			SELECT @countyear = COUNT(*)
			FROM upbexpensetotal
			WHERE idfin = @idfin
				AND idupb = @idupb 
				AND nphase = @nphase
			IF (@countyear = 0)
			BEGIN
				IF (@flagarrear = 'C')
				BEGIN
					INSERT INTO upbexpensetotal (idfin, idupb, nphase, totalcompetency)
					VALUES (@idfin, @idupb, @nphase, @amount)
				END
				ELSE
				BEGIN
					INSERT INTO upbexpensetotal (idfin, idupb, nphase, totalarrears)
					VALUES (@idfin, @idupb, @nphase, @amount)
				END
			END
			ELSE
			BEGIN
				IF (@flagarrear = 'C')
				BEGIN
					UPDATE upbexpensetotal SET
					totalcompetency = ISNULL(totalcompetency, 0) + @amount
					WHERE idfin = @idfin
						AND idupb = @idupb
						AND nphase = @nphase
				END
				ELSE
				BEGIN
					UPDATE upbexpensetotal SET
					totalarrears = ISNULL(totalarrears, 0) + @amount
					WHERE idfin = @idfin
						AND idupb = @idupb
						AND nphase = @nphase
				END
			END
		END
		SET @nlevel = @nlevel - 1
		SELECT @idfin = idparent FROM finlink WHERE idchild = @idfin AND nlevel = @nlevel
	END
END
END



GO

print '[trg_upd_upbmovtotal] OK'

