		declare @epsilon_iva float
		set @epsilon_iva  = @epsilon_c /*@epsilon_impon */
		set @fmin = 0		
		select @fmax =	 CONVERT(DECIMAL(19,2),
				ISNULL(SUM(Round(Round(tax,2)
				*CONVERT(decimal(19,6), @exchangerate),2)	
				   ),0)
				)
			from #invoicedetail
