		select @detraibiletotale =  SUM(ROUND(
						(tax - ISNULL(unabatable,0)) * @exchangerate * @rapporto
					      * ISNULL(@prorata,0) *
					    CASE
					     WHEN @flagmixed = 'S' THEN ISNULL(@mixed,0)
					     ELSE 1
