					    ,2))
		from invoicedetail
		where idinvkind = @idinvkind and yinv = @yinv and ninv =@ninv
		and idexp_taxable is null and idexp_iva is null
		/*select @detraibiledesiderato =  SUM(ROUND(
						(tax - ISNULL(unabatable,0)) * @exchangerate * @rapporto
					      * ISNULL(@prorata,0) *
					    CASE
