if object_id('rpt_rendicontomagazzino') is not null
	drop PROCEDURE rpt_rendicontomagazzino
go

CREATE         PROCEDURE rpt_rendicontomagazzino(
	@idstore int,
	@idlist int,
	@start datetime,
	@stop datetime
)
AS BEGIN
-- exec rpt_rendicontomagazzino NULL, 646, {ts '2011-06-15 00:00:00'}, {ts '2011-06-20 00:00:00'}
--exec rpt_rendicontomagazzino NULL, 72, {ts '2011-06-15 00:00:00'}, {ts '2011-06-20 00:00:00'}
CREATE TABLE #INVENTARIO(
	idlist int,
	idstore int,
	consistenzainiziale decimal(19,2),
	carico decimal(19,2),
	scarico decimal(19,2),
	data datetime,
	descScarico varchar(150),
	idmankind varchar(20),
	nman int,
	yman int,
	man_idgroup int,
	idman int
	
)
--  Rendiconto di fine esercizio che riporti per ogni articolo la consistenza iniziale, i carichi, gli scarichi e la consistenza finale.
-- La CONSISTENZA INIZIALE è data da tutti i carichi fatti alla data Inizio meno tutti gli scarichi fatti alla data Inizio
INSERT INTO #INVENTARIO(
	idlist,
	idstore ,
	consistenzainiziale
)
SELECT
	L.idlist,
	S.idstore,
	SUM( ISNULL(S.number,0) - ISNULL(storeunloaddetail.number,0)) 
FROM list L
JOIN stock S
	ON L.idlist = S.idlist
LEFT OUTER JOIN storeunloaddetail
	ON  storeunloaddetail.idstock = S.idstock
LEFT OUTER JOIN storeunload
	ON storeunload.idstoreunload = storeunloaddetail.idstoreunload AND storeunload.adate < @start
WHERE ( S.idstore = @idstore OR @idstore IS NULL )
	AND ( L.idlist = @idlist OR @idlist IS NULL )
	AND S.number >0
	AND S.adate < @start
GROUP BY S.idstore, L.idlist
-- Inseriamo i Carichi
INSERT INTO #INVENTARIO(
	idlist ,
	idstore ,
	carico, 
	data,
	idmankind,
	nman,
	yman,
	man_idgroup
)
SELECT
	L.idlist, -- codice articolo
	S.idstore,
	S.number,
	S.adate,
	S.idmankind,
	S.nman,
	S.yman,
	S.man_idgroup
FROM list L
JOIN stock S
	ON L.idlist = S.idlist
WHERE ( S.idstore = @idstore OR @idstore IS NULL )
	AND ( L.idlist = @idlist OR @idlist IS NULL )
	AND S.number >0
	AND S.adate between @start AND @stop

-- Inseriamo gli scarichi
INSERT INTO #INVENTARIO(
	idlist ,
	idstore ,
	scarico, 
	data,
	descScarico,
	idman
)
SELECT
	L.idlist, -- codice articolo
	S.idstore,
	SUM(UD.number),
	U.adate,
	U.description,
	UD.idman
FROM list L
JOIN stock S
	ON L.idlist = S.idlist
jOIN storeunloaddetail UD
	ON UD.idstock = S.idstock 
JOIN storeunload U
	ON U.idstoreunload = UD.idstoreunload
WHERE ( S.idstore = @idstore OR @idstore IS NULL )
	AND ( L.idlist = @idlist OR @idlist IS NULL )
	AND S.number >0
	AND U.adate between @start AND @stop
GROUP BY S.idstore, L.idlist,U.adate, U.description,UD.idman

SELECT
	L.intcode, -- codice articolo
	L.description as 'list', --- descrizione  articolo
	U.description as 'unit', -- unita di carico/scarico
	M.description as 'store',
	ISNULL(I.consistenzainiziale,0) as 'consistenzainiziale',
	ISNULL(I.carico,0) as 'carico',
	ISNULL(I.scarico,0) as 'scarico',
	I.data ,	-- Data Arrivo / Data Scarico
	I.descScarico,
	MK.description as 'mandatekind',
	I.nman,
	I.yman,
	manager.title as 'manager',
	I.man_idgroup
FROM #INVENTARIO I
JOIN list L
	ON L.idlist =  I.idlist
JOIN store M
	ON I.idstore = M.idstore
JOIN unit U
	ON U.idunit = L.idunit
LEFT OUTER JOIN mandatekind MK
	ON MK.idmankind = I.idmankind	
LEFT OUTER JOIN manager 
	ON manager.idman = I.idman
END


GO

print 'rpt_rendicontomagazzino OK'

