if object_id('exp_check_siope') is not null
	drop procedure exp_check_siope
go

CREATE   procedure exp_check_siope(
	@ayear int,
	@kind char(1),		-- Expense / Income
	@userkind char(1)	-- D = dipartimento; A = amministrazione 
) as 
begin
DECLARE @iSIOPE INT
DECLARE @eSIOPE INT
DECLARE @iSIOPEtitle varchar(50)
DECLARE @eSIOPEtitle varchar(50)
IF (@userkind = 'A')
Begin
-- Amministrazione
	SELECT @iSIOPE = idsorkind, @iSIOPEtitle = description from sortingkind where codesorkind = '10E_MACROSIOPE_AMMIN'
	SELECT @eSIOPE = idsorkind, @eSIOPEtitle = description from sortingkind where codesorkind = '10S_MACROSIOPE_AMMIN'
end
Else
Begin
-- Dipartimento
	SELECT @iSIOPE = idsorkind, @iSIOPEtitle = description from sortingkind where codesorkind = '10E_MACROSIOPE_DIP'
	SELECT @eSIOPE = idsorkind, @eSIOPEtitle = description from sortingkind where codesorkind = '10S_MACROSIOPE_DIP'
End
DECLARE @minoplevel tinyint
SELECT @minoplevel = min(nlevel)
FROM finlevel
WHERE ayear = @ayear and (flag&2)<>0
DECLARE @idfinincomesurplus int --> L'avanzo di amministrazione è attribuito in previsione a questo capitolo di entrata.
SELECT @idfinincomesurplus = isnull(idfinincomesurplus,0) 
FROM config
WHERE ayear = @ayear
CREATE TABLE #error (msg varchar(1000))
-- CONTROLLO N.1
INSERT INTO #error
SELECT 'La voce di bilancio Entrata: ' + F.codefin + ', pur avendo un valore di previsione, NON è stata classificata con alcun codice "' + @iSIOPEtitle + '"'
FROM fin F 
JOIN finyear FY
	ON F.idfin = FY.idfin
WHERE F.codefin NOT IN (SELECT Fcap.codefin
				FROM fin Fpar -- All
				JOIN finlink FLK 
					ON FLK.idparent = Fpar.idfin 
				JOIN finlink FLK2
					ON FLK2.idchild = FLK.idchild AND FLK2.nlevel = 3
				JOIN Fin Fcap
					ON Fcap.idfin = FLK2.idchild
				JOIN finyear FY2
					ON FY2.idfin = Fcap.idfin	
				JOIN finsorting FSp
					ON FSp.idfin = Fpar.idfin 
				JOIN sorting Sp
					ON Sp.idsor = FSp.idsor
				WHERE ISNULL(FY2.prevision,0) > 0
					AND Sp.idsorkind = @iSIOPE
					AND Fcap.nlevel = F.nlevel
					AND Fcap.idfin =  F.idfin)
 	AND ((F.flag&1) = 0) -- solo la parte Entrata
	AND ISNULL(FY.prevision,0) > 0 -- Potrebbero anche essere in finyear perchè hanno una var. a noi interessa solo se la previsione è >0
	AND FY.ayear = @ayear
	AND @kind = 'I'
	AND F.idfin <>@idfinincomesurplus
	AND F.nlevel = @minoplevel
GROUP BY F.codefin
INSERT INTO #error
SELECT 'La voce di bilancio Spesa: ' + F.codefin + ', pur avendo un valore di previsione, NON è stata classificata con alcun codice "'+ @eSIOPEtitle +'"'
FROM fin F 
JOIN finyear FY
	ON F.idfin = FY.idfin
WHERE F.codefin NOT IN (SELECT Fcap.codefin
				FROM fin Fpar -- All
				JOIN finlink FLK 
					ON FLK.idparent = Fpar.idfin 
				JOIN finlink FLK2
					ON FLK2.idchild = FLK.idchild AND FLK2.nlevel = @minoplevel
				JOIN Fin Fcap
					ON Fcap.idfin = FLK2.idchild
				JOIN finyear FY2
					ON FY2.idfin = Fcap.idfin	
				JOIN finsorting FSp
					ON FSp.idfin = Fpar.idfin 
				JOIN sorting Sp
					ON Sp.idsor = FSp.idsor
				WHERE ISNULL(FY2.prevision,0) > 0
					AND Sp.idsorkind = @eSIOPE
					AND Fcap.nlevel = F.nlevel
					AND Fcap.idfin =  F.idfin)
 	AND ((F.flag&1) <> 0) -- solo la parte Spesa
	AND ISNULL(FY.prevision,0) > 0 -- Potrebbero anche essere in finyear perchè hanno una var. a noi interessa solo se la previsione è >0
	AND FY.ayear = @ayear
	AND @kind = 'E'
	AND F.nlevel = @minoplevel
GROUP BY F.codefin
-- CONTROLLO N.2
-- Sta prendendo tutto ciò che è classificato. Verifica se la SUM del class sul Macro Siope è < 100% , se la voce
-- è presente in FINYEAR (quindi parliamo di un capitolo) oppure in FINYEAR è presente un suo figlio, e quidi ci riferiamo alla categoria,
-- nel senso, la class. della catagoria, per cui esitse un figlio in FY con previsione, è < 100%.. 
INSERT INTO #error
SELECT 'La voce di bilancio Entrata: ' + F.codefin + ' non è stata interamente classificata con la Class. "' + @iSIOPEtitle + '"'
FROM fin F 
JOIN finsorting FS 
	ON FS.idfin = F.idfin
JOIN sorting S
    ON S.idsor = FS.idsor 
WHERE ((F.flag&1) = 0) -- solo la parte Entrata
	AND S.idsorkind = @iSIOPE
	AND @kind = 'I'
	AND EXISTS (SELECT * FROM finyear FY
				JOIN FINLINK Fp
					ON FY.idfin = Fp.idchild
				WHERE ISNULL(FY.prevision,0) > 0 AND (FY.idfin = F.idfin OR Fp.idparent = F.idfin)
				)
	AND F.ayear= @ayear
GROUP BY F.codefin
HAVING ISNULL( convert(decimal(19,2), round(SUM (FS.quota),2)),0) < 1
INSERT INTO #error
SELECT 'La voce di bilancio Spesa: ' + F.codefin + ' non è stata interamente classificata con la Class. "' + @eSIOPEtitle + '"'
FROM fin F 
JOIN finsorting FS 
	ON FS.idfin = F.idfin
JOIN sorting S
    ON S.idsor = FS.idsor 
WHERE ((F.flag&1) <> 0) -- solo la parte Spesa
	AND S.idsorkind = @eSIOPE
	AND @kind = 'E'
	AND EXISTS (SELECT * 
				FROM finyear FY
				JOIN FINLINK Fp
					ON FY.idfin = Fp.idchild
				WHERE ISNULL(FY.prevision,0) > 0 AND (FY.idfin = F.idfin OR Fp.idparent = F.idfin )
				)
	AND F.ayear= @ayear
GROUP BY F.codefin
HAVING ISNULL( convert(decimal(19,2), round(SUM (FS.quota),2)),0) < 1
-- CONTROLLO N.3
-- Sta prendendo tutto ciò che è classificato. Verifica se la SUM del class sul Macro Siope è < 100% , se la voce
-- è presente in FINYEAR (quindi parliamo di un capitolo) oppure in FINYEAR è presente un suo figlio, e quidi ci riferiamo alla categoria,
-- nel senso, la class. della catagoria, per cui esitse un figlio in FY con previsione, è < 100%.. 
INSERT INTO #error
SELECT 'La voce di bilancio Entrata: ' + F.codefin + ' è stata classificata con la Class. "' + @iSIOPEtitle + '" con una percentuale superiore a 100%'
FROM fin F 
JOIN finsorting FS 
	ON FS.idfin = F.idfin
JOIN sorting S
    ON S.idsor = FS.idsor 
WHERE ((F.flag&1) = 0) -- solo la parte Entrata
	AND S.idsorkind = @iSIOPE
	AND @kind = 'I'
	AND EXISTS (SELECT * FROM finyear FY
				JOIN FINLINK Fp
					ON FY.idfin = Fp.idchild
				WHERE ISNULL(FY.prevision,0) > 0 AND (FY.idfin = F.idfin OR Fp.idparent = F.idfin)
				)
	AND F.ayear= @ayear
GROUP BY F.codefin
HAVING ISNULL( convert(decimal(19,2), round(SUM (FS.quota),2)),0) > 1
INSERT INTO #error
SELECT 'La voce di bilancio Spesa: ' + F.codefin + ' è stata classificata con la Class. "' + @eSIOPEtitle + '" con una percentuale superiore a 100%'
FROM fin F 
JOIN finsorting FS 
	ON FS.idfin = F.idfin
JOIN sorting S
    ON S.idsor = FS.idsor 
WHERE ((F.flag&1) <> 0) -- solo la parte Spesa
	AND S.idsorkind = @eSIOPE
	AND @kind = 'E'
	AND EXISTS (SELECT * 
				FROM finyear FY
				JOIN FINLINK Fp
					ON FY.idfin = Fp.idchild
				WHERE ISNULL(FY.prevision,0) > 0 AND  (FY.idfin = F.idfin OR Fp.idparent = F.idfin)
				)
	AND F.ayear= @ayear
GROUP BY F.codefin
HAVING ISNULL( convert(decimal(19,2), round(SUM (FS.quota),2)),0) > 1
SELECT * FROM #error
ORDER BY msg
DROP TABLE #error
end


GO

print 'exp_check_siope OK'

GO
if object_id('[rpt_unified_certificazioneprestazioni]') is not null
	drop PROCEDURE [rpt_unified_certificazioneprestazioni]
go

CREATE       PROCEDURE [rpt_unified_certificazioneprestazioni]
(
	@ayear smallint, 
	@idreg int, 
	@start datetime,
	@stop datetime,
	@idser int,
	@unified char(1),   -- consolidamento dei dati
	@showallser char(1) -- mostra le prestazioni non associate a certificazioni specifiche non CUD
	/*
	------------------------------------------------
	--------- ELENCO CERTIFICAZIONI SPECIFICHE------
	------------------------------------------------
	A	Certificazione Retribuzioni Aggiuntive	
	C	Certificazione stranieri in Convenzione	
	F	Certificazione Ritenuta d'Acconto	
	I	Certificazione INPS a gestione separata	
	P	Certificazione Premi di Studio e altri Premi	
	S	Modello Assegnisti	
	T	Certificazione a Titolo d'imposta	
	U	Modello CUD	
	------------------------------------------------
	------------------------------------------------
	------------------------------------------------
	*/
)
AS BEGIN
IF (@unified <> 'S')
BEGIN
        EXEC rpt_certificazioneprestazioni @ayear, @idreg, @start, @stop, @idser, @showallser
        RETURN
END 
CREATE TABLE #unified (
        departmentname  varchar(150),
	idexp int,
	idreg int ,
	registry varchar(100),
	b_city varchar(120),
   	birthdate smalldatetime,
	b_province varchar(2),
	b_nation varchar(65),
	cf varchar(16),
        taxcode int,
	taxdescription varchar(50),
	expensedescription varchar(150),	
	service varchar(50),
	idser int,
	npay int,
	taxablenet decimal(19,2),
	grossamount decimal(19,2), --Importo Lordo del Pagamento
	employtax decimal(19,2),
	admintax decimal(19,2),
	taxablegross decimal(19,2), -- Imponibile Lordo
	sent_office varchar(50),
	sent_address varchar(100),
	sent_idaddresskind varchar(20),
	sent_location varchar(120),
	sent_cap varchar(20),
	sent_province varchar(2),
	sent_nation varchar(65)
)
DECLARE @iddbdepartment varchar(50)
DECLARE @crsdepartment cursor
SET @crsdepartment = cursor FOR SELECT iddbdepartment FROM dbdepartment
								 where (start is null or start <= @ayear ) AND ( stop is null or stop >= @ayear)
OPEN @crsdepartment
FETCH NEXT FROM @crsdepartment INTO @iddbdepartment
WHILE @@fetch_status=0 begin
	DECLARE @dip_nomesp varchar(300)
	SET @dip_nomesp = @iddbdepartment + '.rpt_certificazioneprestazioni'
PRINT @iddbdepartment
		INSERT INTO #unified (
                        departmentname,
                	idexp,
                	idreg,
                	registry,
                	b_city,
                   	birthdate,
                	b_province,
                	b_nation,
                	cf,
                        taxcode,
                	taxdescription,
                	expensedescription,	
                	service,
                	idser,
                	npay,
                	taxablenet,
                	grossamount,--Importo Lordo del Pagamento
                	employtax,
                	admintax,
                	taxablegross, -- Imponibile Lordo
                	sent_office,
                	sent_address,
                	sent_idaddresskind, 
                	sent_location,
                	sent_cap,
                	sent_province,
                	sent_nation
		)
		EXEC @dip_nomesp @ayear, @idreg, @start, @stop, @idser, @showallser
	FETCH NEXT FROM @crsdepartment INTO @iddbdepartment
END
SELECT 
        departmentname,
	idexp,
	idreg,
	registry,
	b_city,
   	birthdate,
	b_province,
	b_nation,
	cf,
        taxcode,
	taxdescription,
	expensedescription,	
	service,
	idser,
	npay,
	taxablenet,
	grossamount,--Importo Lordo del Pagamento
	employtax,
	admintax,
	taxablegross, -- Imponibile Lordo
	sent_office,
	sent_address,
	sent_idaddresskind, 
	sent_location,
	sent_cap,
	sent_province,
	sent_nation
FROM #unified
END



GO

print '[rpt_unified_certificazioneprestazioni] OK'

