if object_id('[trigger_d_invoice]') is not null
	drop TRIGGER [trigger_d_invoice]
go

CREATE               TRIGGER [trigger_d_invoice] ON invoice FOR DELETE
AS BEGIN
	DECLARE @idinvkind int
	DECLARE @yinv int
	DECLARE @ninv int
	
	SELECT	
	@idinvkind = idinvkind,
	@yinv = yinv,
	@ninv = ninv
	FROM deleted
	
	DELETE FROM incomeinvoice
	WHERE idinvkind = @idinvkind
	AND yinv = @yinv
	AND ninv = @ninv
	
	DELETE FROM expenseinvoice
	WHERE idinvkind = @idinvkind
	AND yinv = @yinv
	AND ninv = @ninv
	DELETE FROM pettycashoperationinvoice
	WHERE idinvkind = @idinvkind
	AND yinv = @yinv
	AND ninv = @ninv
	
	UPDATE incomevar
	SET idinvkind = NULL, yinv = NULL, ninv = NULL, movkind = NULL
	WHERE idinvkind = @idinvkind
	AND yinv = @yinv
	AND ninv = @ninv
	
	UPDATE expensevar
	SET idinvkind = NULL, yinv = NULL, ninv = NULL, movkind = NULL
	WHERE idinvkind = @idinvkind
	AND yinv = @yinv
	AND ninv = @ninv
	DELETE FROM unifiedivaregister
	WHERE idinvkind = @idinvkind
	AND yinv = @yinv
	AND ninv = @ninv
	AND iddbdepartment = system_user
END



