if object_id('[rpt_unified_certritacconto_dett]') is not null
	drop PROCEDURE [rpt_unified_certritacconto_dett]
go

CREATE     PROCEDURE [rpt_unified_certritacconto_dett]
(
	@ayear smallint, 
	@start datetime,
	@stop datetime,
	@idreg int, 
	@certificatekind char(1),
    @unified char(1)
	
)
AS BEGIN
IF (@unified <> 'S')
BEGIN
        EXEC rpt_certritacconto_dett @ayear, @start, @stop, @idreg, @certificatekind
        RETURN
END 
 
CREATE TABLE #unified_dett (
    countidser int,
	idreg int ,
	registry varchar(100),
	taxdescription varchar(50),
	taxablenet decimal(19,2),
	taxablegross decimal(19,2),
	employtax decimal(19,2),
	taxkind int
)
DECLARE @iddbdepartment varchar(50)
DECLARE @crsdepartment cursor
SET @crsdepartment = cursor FOR SELECT iddbdepartment FROM dbdepartment
WHERE (start is null or start <= @ayear ) AND ( stop is null or stop >= @ayear)
OPEN @crsdepartment
FETCH NEXT FROM @crsdepartment INTO @iddbdepartment
WHILE @@fetch_status=0 begin
	DECLARE @dip_nomesp varchar(300)
	SET @dip_nomesp = @iddbdepartment + '.rpt_certritacconto_dett'
PRINT @iddbdepartment
		INSERT INTO #unified_dett (
                    countidser,
                	idreg,
                	registry,
                	taxdescription,
                	taxablenet,
                	taxablegross ,
                	employtax,
                	taxkind
        		)
		EXEC @dip_nomesp @ayear, @start, @stop,@idreg, @certificatekind
	FETCH NEXT FROM @crsdepartment INTO @iddbdepartment
end
SELECT 
    countidser,
	idreg,
	registry,
	taxdescription,
	sum(isnull(taxablenet,0)) AS taxablenet,
	sum(isnull(taxablegross,0)) AS taxablegross ,
	sum(isnull(employtax,0)) as employtax,
	taxkind
FROM #unified_dett
GROUP BY idreg,registry,taxdescription,countidser,taxkind
ORDER BY registry,taxkind
END


GO

print '[rpt_unified_certritacconto_dett] OK'

