CREATE              TRIGGER [trigger_d_treasurer] ON treasurer FOR DELETE
AS BEGIN
	IF @@ROWCOUNT > 0
	BEGIN
		DECLARE @idtreasurer int
		SELECT @idtreasurer = idtreasurer FROM deleted
		DELETE FROM treasurerstart WHERE idtreasurer = @idtreasurer
	END
END


