if object_id('exp_fg_riclassificatosuesitato') is not null
	drop procedure exp_fg_riclassificatosuesitato
go

CREATE   procedure exp_fg_riclassificatosuesitato(
	@idsorkindmaster int,--class origine
    	@idsorkindchild int,-- class destinazione
	@start datetime, 
	@stop datetime,
	@ayear smallint
) as 
begin
DECLARE @finexpensephase tinyint
DECLARE @finincomephase tinyint
SELECT @finexpensephase = expensefinphase, @finincomephase = incomefinphase FROM uniconfig
	SELECT 
		CASE banktransaction.kind 
			WHEN 'C' THEN 'Entrate' 
			WHEN 'D' THEN 'Spese' 
		END	as 'Tipo mov.',
		sortingkind.description as 'Tipo class.',
		SIRGS.sortcode as 'Codice class.', 
		SIRGS.description as 'Classificazione', 
		sum(banktransactionsorting.amount) as 'Importo',
		-- Previsione alla data
		ISNULL((select sum(FY.prevision * FS.quota) 
		from finyear FY	
		join finsorting FS
			on FY.idfin = FS.idfin
		where FY.ayear = @ayear
			AND FS.idsor = SIRGS.idsor),0)
		+
		ISNULL((select sum(FVD.amount * FS.quota)
		from finvar FV
		join finvardetail FVD
			ON FV.yvar = FVD.yvar
			AND FV.nvar = FVD.nvar
		join finsorting FS
			on FVD.idfin = FS.idfin
		where FS.idsor = SIRGS.idsor
			AND FV.adate <= @stop 
			AND FV.idfinvarstatus = 5),0)
		+
		-- Residui Spesa
		ISNULL((SELECT SUM(EY.amount * FS.quota)
		FROM expenseyear EY
		JOIN expense E
			ON E.idexp = EY.idexp AND EY.ayear = @ayear
		JOIN expensetotal ET
			ON ET.idexp = EY.idexp AND ET.ayear = EY.ayear
		JOIN finsorting FS
			ON EY.idfin = FS.idfin
		WHERE ((ET.flag & 1) <> 0) 
			AND E.nphase = @finexpensephase
			AND E.adate <= @stop
			AND FS.idsor = SIRGS.idsor
			AND banktransaction.kind = 'D'-- è un filtro in più, sarebbe sufficiente l'idsor che intrinsicamente è associato a entrate o a spese.
			),0)
		+
		-- Residui Entrata
		ISNULL((SELECT SUM(EY.amount * FS.quota)
		FROM incomeyear EY
		JOIN income E
			ON E.idinc = EY.idinc AND EY.ayear = @ayear
		JOIN incometotal ET
			ON ET.idinc = EY.idinc AND ET.ayear = EY.ayear
		JOIN finsorting FS
			ON EY.idfin = FS.idfin
		WHERE ((ET.flag & 1) <> 0) 
			AND E.nphase = @finincomephase
			AND E.adate <= @stop
			AND FS.idsor = SIRGS.idsor
			AND banktransaction.kind = 'C'
			),0)
		 as 'Previsione alla data '
	from banktransactionsorting 
	join banktransaction 
                on banktransaction.yban = banktransactionsorting.yban 
                and banktransaction.nban = banktransactionsorting.nban
	join sortingtranslation 
                on sortingtranslation.idsortingchild = banktransactionsorting.idsor 
	join sorting SIRGS 
                on SIRGS.idsor = sortingtranslation.idsortingmaster -- SIRGS
	join sortingkind 
                on sortingkind.idsorkind = SIRGS.idsorkind
	join sorting SIOPE 
                on SIOPE.idsor = sortingtranslation.idsortingchild -- SIOPE
	where banktransaction.transactiondate between @start and @stop
        	AND SIRGS.idsorkind = @idsorkindmaster
            AND SIOPE.idsorkind = @idsorkindchild
	group by banktransaction.kind, sortingkind.description, SIRGS.sortcode, SIRGS.description,
			SIRGS.idsorkind, SIRGS.idsor
	order by banktransaction.kind, sortingkind.description, SIRGS.sortcode
end



GO

print 'exp_fg_riclassificatosuesitato OK'

GO
if object_id('rpt_liquidazioneiva') is not null
	drop PROCEDURE rpt_liquidazioneiva
go

CREATE   PROCEDURE rpt_liquidazioneiva
(
	@ayear int,
	@number int,
	@official char(1)
)
AS BEGIN
-- exec rpt_liquidazioneiva 2010,2 ,'N'
CREATE TABLE #ivapayed
(
	idivapayperiodicity varchar(50),
	yivapay int,
	nivapay int,
	start datetime,
	stop datetime,
	description varchar(50),
	motive varchar(50),
	debitamount decimal(19,2),
	debitamountdeferred decimal(19,2),
	creditamount decimal(19,2),
	creditamountdeferred decimal(19,2),
	previouscredit decimal(19,2),
	previousdebit decimal(19,2),
	currentcredit decimal(19,2),
	currentdebit decimal(19,2),
	refundamount decimal(19,2),
	paymentamount decimal(19,2),
	paymentdetails varchar(150),
	prorata float,
	iva decimal(19,2),
	ivadeferred decimal(19,2),
	unabatable decimal(19,2), 
	unabatabledeferred decimal(19,2)
)
DECLARE @idivapayperiodicity varchar(50)
SELECT @idivapayperiodicity = ivapayperiodicity.description
FROM config
JOIN ivapayperiodicity
	ON config.idivapayperiodicity = ivapayperiodicity.idivapayperiodicity
WHERE config.ayear = @ayear
DECLARE @start_period datetime
DECLARE @stop_period datetime
DECLARE @paymentdetails varchar(150)
DECLARE @prorata float
DECLARE @refundamount decimal(19,2)
DECLARE @paymentamount decimal(19,2)
DECLARE @flag tinyint
SELECT @start_period = start,
	@stop_period = stop,
	@paymentdetails = paymentdetails,
	@prorata = prorata * 100,
	@refundamount = ISNULL(refundamount, 0),
	@paymentamount = ISNULL(paymentamount, 0),
	@flag = ISNULL(flag,3)
FROM ivapay
WHERE yivapay = @ayear
	AND nivapay = @number
DECLARE @saldo_iniziale decimal (19,2)
DECLARE @saldo_precedente decimal (19,2)
DECLARE @prev_debitcredit decimal(19,2)
DECLARE @prevcredit decimal(19,2)
DECLARE @prevdebit decimal(19,2)
SELECT @saldo_iniziale = ISNULL(-startivabalance,0) from config where ayear = @ayear
SELECT
	 @prev_debitcredit = ISNULL(SUM(totaldebit),0) - ISNULL(SUM(paymentamount),0)  -  ISNULL(SUM(totalcredit),0) + ISNULL(SUM(refundamount),0)
FROM ivapay
WHERE yivapay = @ayear
	AND nivapay < @number
SET @saldo_precedente = @saldo_iniziale + @prev_debitcredit
IF @saldo_precedente > 0
BEGIN
	SET @prevdebit = @saldo_precedente
	SET @prevcredit = 0 
END
ELSE
BEGIN
	SET @prevdebit = 0
	SET @prevcredit = - @saldo_precedente 
END
INSERT INTO #ivapayed
(
	idivapayperiodicity,
	yivapay,
	nivapay,
	start,
	stop,
	description,
	motive,
	debitamount,
	debitamountdeferred,
	previouscredit,
	previousdebit,
	paymentdetails
)
SELECT 
	@idivapayperiodicity,
	@ayear,
	@number,
	@start_period,
	@stop_period,
	ivaregisterkind.description,
	'IVA esigibile su vendite',
	ISNULL(ivapaydetail.ivanet,0),
	ISNULL(ivapaydetail.ivanetdeferred,0),
	@prevcredit,
	@prevdebit,
	@paymentdetails
FROM ivapaydetail
JOIN ivaregisterkind
	ON ivapaydetail.idivaregisterkind = ivaregisterkind.idivaregisterkind
WHERE ivaregisterkind.registerclass = 'V' AND flagactivity <> 1
	AND ivapaydetail.yivapay = @ayear
	AND ivapaydetail.nivapay = @number
	AND (ISNULL(ivapaydetail.ivanet,0) <> 0 OR ISNULL(ivapaydetail.ivanetdeferred,0) <> 0)
INSERT INTO #ivapayed
(
	idivapayperiodicity,
	yivapay,
	nivapay,
	start,
	stop,
	description,
	motive,
	creditamount,
	creditamountdeferred,
	previouscredit,
	previousdebit,
	paymentdetails,
	iva,
	ivadeferred,
	unabatable, 
	unabatabledeferred
)
SELECT
	@idivapayperiodicity,
	@ayear,
	@number,
	@start_period,
	@stop_period,
	ivaregisterkind.description,
	'IVA detraibile su acquisti',
	ISNULL(ivapaydetail.ivanet,0),
	ISNULL(ivapaydetail.ivanetdeferred,0),
	@prevcredit,
	@prevdebit,
	@paymentdetails,
	ISNULL(ivapaydetail.iva,0),
	ISNULL(ivapaydetail.ivadeferred,0),
	ISNULL(ivapaydetail.unabatable,0),
	ISNULL(ivapaydetail.unabatabledeferred,0)
FROM ivapaydetail
JOIN ivaregisterkind
	ON ivapaydetail.idivaregisterkind = ivaregisterkind.idivaregisterkind
WHERE ivaregisterkind.registerclass = 'A' AND flagactivity <> 1
	AND ivapaydetail.yivapay = @ayear
	AND ivapaydetail.nivapay = @number
	AND (ISNULL(ivapaydetail.ivanet,0) <> 0 OR ISNULL(ivapaydetail.ivanetdeferred,0) <> 0)
DECLARE @pre_credittotal decimal(19,2)
SELECT @pre_credittotal = ISNULL(SUM(iva), 0) - ISNULL(SUM(unabatable),0) + ISNULL(SUM(ivadeferred),0) - ISNULL(SUM(unabatabledeferred),0)
FROM #ivapayed 
DECLARE @credittotal decimal(19,2) -- Somma dell'IVA detraibile dopo l'applicazione prorata/promuscuo
DECLARE @debittotal decimal(19,2) -- Somma dell'IVA esigibile
SELECT @credittotal = ISNULL(SUM(creditamount), 0) + ISNULL(SUM(creditamountdeferred),0),
	   @debittotal = ISNULL(SUM(debitamount), 0) + ISNULL(SUM(debitamountdeferred),0)
FROM #ivapayed
DECLARE @currentcredit decimal(19,2)
DECLARE @currentdebit decimal(19,2)
-- In currentcredit e currentdebit sono memorizzati i saldi correnti, valorizzando il maggiore fra essi "crediti - debiti" o viceversa
IF @prevcredit + @credittotal >= @prevdebit + @debittotal
Begin
	SET @currentcredit = ISNULL(@prevcredit, 0) + ISNULL(@credittotal, 0) - ISNULL(@debittotal, 0) - @prevdebit
	SET @currentdebit = 0
End
ELSE
Begin
	SET @currentcredit = 0
	SET @currentdebit = ISNULL(@prevdebit, 0) + ISNULL(@debittotal, 0) - ISNULL(@credittotal, 0) -ISNULL(@prevcredit, 0)
End 
UPDATE #ivapayed
SET currentcredit = @currentcredit,
currentdebit = @currentdebit,
refundamount = @refundamount,
paymentamount = @paymentamount,
prorata = @prorata
SELECT
	idivapayperiodicity,
	yivapay,
	nivapay,
	start,
	stop,
	description,
	motive,
	ISNULL(debitamount,0) as debitamount,
	ISNULL(debitamountdeferred,0) as debitamountdeferred,
	ISNULL(creditamount,0) as creditamount,
	ISNULL(creditamountdeferred,0) as creditamountdeferred,
	previouscredit,
	previousdebit,
	currentcredit,
	currentdebit,
	refundamount,
	paymentamount,
	paymentdetails,
	prorata,
	@pre_credittotal AS precredittotal,
	CASE 
		WHEN (((@flag&1) <> 0)AND((@flag&2) = 0)) THEN 'Iva Commerciale e Promiscua'
		WHEN (((@flag&1) = 0)AND((@flag&2) <> 0)) THEN 'Iva Istituzionale (INTRA12)'
		ELSE  'Iva Commerciale, Promiscua e Istituzionale (INTRA12)'
	END as  'ivapaykind'
FROM #ivapayed
ORDER BY description ASC
END


GO

print 'rpt_liquidazioneiva OK'

GO
if object_id('compute_resetincomeavailability') is not null
	drop PROCEDURE compute_resetincomeavailability
go

CREATE                       PROCEDURE compute_resetincomeavailability
(
	@ayear int,
	@idinc int
)
AS BEGIN
declare @nlevel tinyint
select @nlevel = nphase from income where idinc = @idinc 
CREATE TABLE #toreset (idinc int,nphase tinyint, amount decimal(19,2))
INSERT INTO #toreset (idinc,nphase,amount)
SELECT idparent,nlevel,0
FROM incomelink
WHERE idchild = @idinc and nlevel<@nlevel

UPDATE #toreset SET amount = 
		(SELECT - SUM (ET.available) 
		FROM incometotal ET
		JOIN incomelink EL
		ON EL.idparent = ET.idinc
		WHERE EL.idchild = @idinc  AND ET.ayear = @ayear AND EL.nlevel>=#toreset.nphase AND EL.idparent<>@idinc)

SELECT 
	#toreset.nphase ,
	incomephase.description as phase,
      	#toreset.idinc,
      	I.ymov,
	I.nmov,
	'Minore entrata' AS description,
	#toreset.amount
FROM #toreset 
LEFT OUTER JOIN income I
	ON #toreset.idinc = I.idinc 
LEFT OUTER JOIN incomephase
	ON #toreset.nphase = incomephase.nphase
ORDER BY #toreset.nphase
END


GO

print 'compute_resetincomeavailability OK'

GO
if object_id('exp_fg_riclassificatosupagatoconprev') is not null
	drop procedure exp_fg_riclassificatosupagatoconprev
go

CREATE   procedure exp_fg_riclassificatosupagatoconprev(
	@idsorkindmaster int,--class origine
    	@idsorkindchild int,-- class destinazione
	@ayear smallint,
	@date datetime,
	@kind char(1)-- Expense / Income
) as 
begin
-- EXEC  prova_claa 	14,29,	2009,{ts '2009-12-31 00:00:00'},'E'
-- Bilancio SIRGS - SIOPE Spesa
-- EXEC  prova_claa 	14,6,	2009,{ts '2009-12-31 00:00:00'},'I'

CREATE TABLE #CLASSIFICATO(
	tipoclass varchar(50),
	codiceclass varchar(50), 
	classificazione varchar(200),
	bilancio varchar(50),
	perc_prev_prevista  decimal(19,4),
	pagatosullacoppia  decimal(19,2),
	previsionesulcapitolo  decimal(19,2),
	perc_pagata  decimal(19,4)
)
CREATE TABLE #OUT(
	tipoclass varchar(50),
	codiceclass varchar(50), 
	classificazione varchar(200),
	bilancio varchar(50),
	perc_prev_prevista  decimal(19,4),
	pagatosullacoppia  decimal(19,2),
	previsionesulcapitolo  decimal(19,2),
	perc_pagata  decimal(19,4)
)
IF (@kind='E')
Begin
	INSERT INTO #CLASSIFICATO(
		tipoclass,
		codiceclass, 
		classificazione,
		bilancio,
		perc_prev_prevista,
		previsionesulcapitolo,		
		pagatosullacoppia
	)
	SELECT 
		sortingkind.description,
		sortmaster.sortcode, 
		sortmaster.description, 
		F.codefin,
		--perc_prev_prevista
		FS.quota,
		-- Previsione alla data sul capitolo
		ISNULL((SELECT sum(FY.prevision ) 
		FROM finyear FY	
		WHERE FY.ayear = @ayear
			AND FY.idfin = F.idfin),0)
		+
		ISNULL((SELECT sum(FVD.amount)
		FROM finvar FV
		JOIN finvardetail FVD
			ON FV.yvar = FVD.yvar
			AND FV.nvar = FVD.nvar
		WHERE FVD.idfin = F.idfin
			AND FV.adate <= @date
			AND FV.yvar = @ayear 
			AND FV.idfinvarstatus = 5),0),
		-- Somma del pagato sulla coppia
		ISNULL((SELECT sum(BKS.amount) 
		FROM banktransactionsorting BKS
		JOIN banktransaction BKT
                on BKT.yban = BKS.yban 
                and BKT.nban = BKS.nban
		JOIN expenseyear EY
			on BKT.idexp = EY.idexp
		JOIN finsorting FS
			on EY.idfin = FS.idfin
		JOIN sorting S
			on S.idsor = FS.idsor
		WHERE EY.ayear = @ayear
			AND EY.idfin = F.idfin
			AND BKS.idsor = SORTCHILD.idsor		-- SIOPE
			AND S.idsorkind = SORTMASTER.idsorkind	-- SIRGS
			AND S.idsor = SORTMASTER.idsor),0)
	FROM finsorting FS 
	JOIN sortingtranslation 
		ON sortingtranslation.idsortingmaster = FS.idsor 
	JOIN fin F
		ON FS.idfin = F.idfin
	JOIN sorting SORTMASTER
                on SORTMASTER.idsor = sortingtranslation.idsortingmaster -- SIRGS
	JOIN sortingkind 
                on sortingkind.idsorkind = SORTMASTER.idsorkind
	JOIN sorting SORTCHILD
                on SORTCHILD.idsor = sortingtranslation.idsortingchild -- S I O P E
	WHERE ((F.flag&1)<>0) -- solo la parte spesa
		AND F.ayear = @ayear
        AND SORTMASTER.idsorkind = @idsorkindmaster
        AND SORTCHILD.idsorkind = @idsorkindchild
	ORDER BY sortingkind.description, sortmaster.sortcode
End
Else
Begin
	INSERT INTO #CLASSIFICATO(
		tipoclass,
		codiceclass, 
		classificazione,
		bilancio,
		perc_prev_prevista,
		previsionesulcapitolo,		
		pagatosullacoppia
	)
	SELECT 
		sortingkind.description,
		sortmaster.sortcode, 
		sortmaster.description, 
		F.codefin,
		--perc_prev_prevista
		FS.quota,
		-- Previsione alla data sul capitolo
		ISNULL((SELECT sum(FY.prevision ) 
		FROM finyear FY	
		WHERE FY.ayear = @ayear
			AND FY.idfin = F.idfin),0)
		+
		ISNULL((SELECT sum(FVD.amount)
		FROM finvar FV
		JOIN finvardetail FVD
			ON FV.yvar = FVD.yvar
			AND FV.nvar = FVD.nvar
		WHERE FVD.idfin = F.idfin
			AND FV.adate <= @date
			AND FV.yvar = @ayear 
			AND FV.idfinvarstatus = 5),0),
		-- Somma del pagato sulla coppia
		ISNULL((SELECT sum(BKS.amount) 
		FROM banktransactionsorting BKS
		JOIN banktransaction BKT
                on BKT.yban = BKS.yban 
                and BKT.nban = BKS.nban
		JOIN incomeyear EY
			on BKT.idinc = EY.idinc
		JOIN finsorting FS
			on EY.idfin = FS.idfin
		JOIN sorting S
			on S.idsor = FS.idsor
		WHERE EY.ayear = @ayear
			AND EY.idfin = F.idfin
			AND BKS.idsor = SORTCHILD.idsor		-- SIOPE
			AND S.idsorkind = SORTMASTER.idsorkind	-- SIRGS
			AND S.idsor = SORTMASTER.idsor),0)
	FROM finsorting FS 
	JOIN sortingtranslation 
		ON sortingtranslation.idsortingmaster = FS.idsor 
	JOIN fin F
		ON FS.idfin = F.idfin
	JOIN sorting SORTMASTER
                on SORTMASTER.idsor = sortingtranslation.idsortingmaster -- SIRGS
	JOIN sortingkind 
                on sortingkind.idsorkind = SORTMASTER.idsorkind
	JOIN sorting SORTCHILD
                on SORTCHILD.idsor = sortingtranslation.idsortingchild -- S I O P E
	WHERE ((F.flag&1)=0) -- solo la parte entrata
		AND F.ayear = @ayear
        AND SORTMASTER.idsorkind = @idsorkindmaster
        AND SORTCHILD.idsorkind = @idsorkindchild
	ORDER BY sortingkind.description, sortmaster.sortcode
End
INSERT INTO #OUT(
	tipoclass,
	codiceclass, 
	classificazione,
	bilancio,
	perc_prev_prevista,
	previsionesulcapitolo,		
	pagatosullacoppia
)
SELECT
	tipoclass,
	codiceclass, 
	classificazione,
	bilancio,
	perc_prev_prevista,
	previsionesulcapitolo,		
	SUM(pagatosullacoppia)
FROM #CLASSIFICATO
GROUP BY tipoclass,	codiceclass, classificazione, bilancio, perc_prev_prevista,	previsionesulcapitolo		
UPDATE #OUT SET perc_pagata = pagatosullacoppia / previsionesulcapitolo where previsionesulcapitolo<>0
-- qualora ci fosse un pagamento senza una previsione mostreremo: 100% pagamenti, 0% previsione 
UPDATE #OUT SET perc_pagata = 1, 
			perc_prev_prevista = 0 
WHERE previsionesulcapitolo = 0
 
-- IMPORTANTE --
-- Devo fornire in OUT nella #tab SOLO QUELLE RIGHE PER CUI CI SONO CAPITOLI AVENTI RIGHE CON 'SIRGS' SFORATO
-- Cancella le righe per cui la % pagata è UGUALE alla % prevista, ossia ho pagato tutto ciò che prevedevo di pagare
DELETE FROM #OUT WHERE perc_prev_prevista = perc_pagata
-- Cancella quelle righe per cui la voce di bilancio non ha previsione sforata. Se esiste per la stessa voce di bilancio
-- anche una sola riga con previsione sforata, non deve visualizzare solo quella riga, ma tutte le righe di quella voce di bilancio
-- per avere una visione generale della situazione e quindi agevolare la correzione.
DELETE FROM #OUT 
WHERE bilancio not in  (SELECT c1.bilancio FROM #OUT c1
					WHERE c1.bilancio = #OUT.bilancio 
					AND c1.perc_pagata > c1.perc_prev_prevista)	

-- Inserisce le class. SIRGS utilizzate ma senza previsioni, ossia non associate ad alcuna vose di bilancio
IF (@kind='E')
Begin
	INSERT INTO #OUT(
		tipoclass,
		codiceclass, 
		classificazione,
		bilancio,
		perc_prev_prevista,
		previsionesulcapitolo,		
		pagatosullacoppia
	)
	SELECT 
		sortingkind.description,
		SIRGS.sortcode, 
		SIRGS.description, 
		NULL,
		--perc_prev_prevista
		0,
		-- Previsione alla data sul capitolo
		0,
		-- Somma del pagato sulla coppia
		SUM(BKS.amount) 
	FROM banktransactionsorting BKS
		JOIN banktransaction BKT
			ON BKT.yban = BKS.yban 
            AND BKT.nban = BKS.nban
		JOIN expenseyear EY
			ON BKT.idexp = EY.idexp
		JOIN sorting SIOPE
			ON SIOPE.idsor = BKS.idsor
		JOIN sortingtranslation 
			ON SIOPE.idsor = sortingtranslation.idsortingchild	-- SIOPE
		JOIN sorting SIRGS
            ON SIRGS.idsor = sortingtranslation.idsortingmaster -- SIRGS
		JOIN sortingkind 
				on sortingkind.idsorkind = SIRGS.idsorkind
	WHERE EY.ayear = @ayear
		AND SIRGS.idsorkind = @idsorkindmaster
        AND SIOPE.idsorkind = @idsorkindchild
		AND NOT EXISTS (SELECT * FROM finsorting FS WHERE  FS.idfin = EY.idfin and FS.idsor = SIRGS.idsor)
	GROUP BY sortingkind.description, SIRGS.sortcode,SIRGS.description
End
Else
Begin 
	INSERT INTO #OUT(
		tipoclass,
		codiceclass, 
		classificazione,
		bilancio,
		perc_prev_prevista,
		previsionesulcapitolo,		
		pagatosullacoppia
	)
	SELECT 
		sortingkind.description,
		SIRGS.sortcode, 
		SIRGS.description, 
		NULL,
		--perc_prev_prevista
		0,
		-- Previsione alla data sul capitolo
		0,
		-- Somma del pagato sulla coppia
		SUM(BKS.amount) 
	FROM banktransactionsorting BKS
		JOIN banktransaction BKT
			ON BKT.yban = BKS.yban 
            AND BKT.nban = BKS.nban
		JOIN incomeyear EY
			ON BKT.idinc = EY.idinc
		JOIN sorting SIOPE
			ON SIOPE.idsor = BKS.idsor
		JOIN sortingtranslation 
			ON SIOPE.idsor = sortingtranslation.idsortingchild	-- SIOPE
		JOIN sorting SIRGS
            ON SIRGS.idsor = sortingtranslation.idsortingmaster -- SIRGS
		JOIN sortingkind 
				on sortingkind.idsorkind = SIRGS.idsorkind
	WHERE EY.ayear = @ayear
		AND SIRGS.idsorkind = @idsorkindmaster
        AND SIOPE.idsorkind = @idsorkindchild
		AND NOT EXISTS (SELECT * FROM finsorting FS WHERE  FS.idfin = EY.idfin and FS.idsor = SIRGS.idsor)
	GROUP BY sortingkind.description, SIRGS.sortcode,SIRGS.description
End
IF (@kind='E')
Begin
-- Parte spesa
	SELECT 
		tipoclass as 'Tipo Class',
		codiceclass as 'Codice Class', 
		classificazione as 'Classificazione',
		bilancio 'Bilancio',
		perc_prev_prevista *100 as '% Prevista',
		perc_pagata *100 as '% Pagata',
		(perc_prev_prevista * previsionesulcapitolo) as 'Importo Previsto',
		pagatosullacoppia as 'Importo Pagato'
	FROM #OUT
	ORDER BY bilancio, codiceclass,classificazione
End
Else
Begin
-- Parte entrata
	SELECT 
		tipoclass as 'Tipo Class',
		codiceclass as 'Codice Class', 
		classificazione as 'Classificazione',
		bilancio 'Bilancio',
		perc_prev_prevista *100 as '% Prevista',
		perc_pagata *100 as '% Incassata',
		(perc_prev_prevista * previsionesulcapitolo) as 'Importo Previsto',
		pagatosullacoppia as 'Importo Incassato'
	FROM #OUT
	ORDER BY bilancio, codiceclass,classificazione
End
		
END


GO

print 'exp_fg_riclassificatosupagatoconprev OK'

GO
if object_id('rpt_partitario_classificazione_sub_variazioni') is not null
	drop PROCEDURE rpt_partitario_classificazione_sub_variazioni
go

CREATE                          PROCEDURE rpt_partitario_classificazione_sub_variazioni
	@ayear int,	
	@stop datetime,		
	@idsorkind int,
	@idsor int
AS
BEGIN
DECLARE @firstday datetime
SET @firstday = CONVERT(datetime, '01-01-' + CONVERT(varchar(4),@ayear), 105)

DECLARE @MostraVarprevisione varchar(50)
SELECT @MostraVarprevisione = isnull(paramvalue,'N') 
FROM reportadditionalparam WHERE paramname='MostraVarPrevisione'
and reportname='partitarioperclassificazione'
IF ( @MostraVarprevisione='S')
BEGIN
	SELECT
		sortingprevexpensevar.yvar,
		sortingprevexpensevar.nvar,
		sortingkind.codesorkind,
		sortingprevexpensevar.idsor,
		sorting.sortcode,
		sortingprevexpensevar.description,
		sortingprevexpensevar.amount,
		sortingprevexpensevar.adate
	FROM sortingprevexpensevar 
	JOIN sorting 
		ON sortingprevexpensevar.idsor = sorting.idsor
	JOIN sortingkind
		ON sortingkind.idsorkind = sorting.idsorkind
	WHERE sortingprevexpensevar.adate BETWEEN @firstday AND @stop
		AND (sorting.idsorkind  = @idsorkind)
		AND (sortingprevexpensevar.idsor = @idsor)
	ORDER BY sortingprevexpensevar.adate,sortingprevexpensevar.idsor
END
ELSE
Begin
	SELECT 										
	null as yvar,
	null as nvar,
	null as codesorkind,
	null as idsor,
	null as sortcode,
	null as description,
	null as amount,
	null as adate
End
END


GO

print 'rpt_partitario_classificazione_sub_variazioni OK'

