if object_id('exp_prevavailable_sorting') is not null
	drop PROCEDURE exp_prevavailable_sorting
go

CREATE        PROCEDURE exp_prevavailable_sorting
(
	@ayear int,
	@idsorkind int
)
AS BEGIN
CREATE TABLE #previsionsor
(
	ayear int,
	idsor int,
	idsorkind int,
	expenseprevision decimal(19,2),	
	incomeprevision decimal(19,2),	
	expense_var decimal(19,2),	
	income_var decimal(19,2),	
	expense decimal(19,2),	
	income decimal(19,2),	
	incomeprevavailable decimal(19,2),	
	expenseprevavailable decimal(19,2)
)
INSERT INTO #previsionsor
(
	ayear,
	idsor,
	idsorkind,
	expenseprevision,
	incomeprevision
)
SELECT 	@ayear,
       	SORT.idsor,
       	SORT.idsorkind,
   	SUM(ISNULL(PREV.expenseprevision,0)),
	SUM(ISNULL(PREV.incomeprevision,0))
FROM sortingprev PREV
JOIN sorting SORT
	ON PREV.idsor = SORT.idsor
JOIN sortinglink SORLINK 
	ON SORLINK.idchild =  PREV.idsor
WHERE SORT.idsor = PREV.idsor
	AND SORT.idsorkind = @idsorkind
	AND PREV.ayear = @ayear
	AND SORLINK.nlevel = SORT.nlevel
	AND SORT.nlevel = (SELECT  MIN(nlevel) 
			FROM    sortinglevel                 
			WHERE   idsorkind = @idsorkind 
			AND     ((flag&2)<>0))
GROUP BY SORT.idsor,SORT.idsorkind
-- inserisce quelle imputate alle var. che non hanno la previsione. Il distinct serve perchè le var possono essere + di 2
INSERT INTO #previsionsor
(
	ayear,
	idsor,
	idsorkind,
	expenseprevision,
	incomeprevision
)
SELECT DISTINCT
	@ayear,
       	SORT.idsor,
       	SORT.idsorkind,
   	0,
	0
FROM sortingprevincomevar SORVAR
JOIN    sorting SORT
	ON SORVAR.idsor = SORT.idsor
JOIN sortinglink SORLINK 
	ON SORLINK.idchild =  SORVAR.idsor
WHERE   SORT.idsor = SORVAR.idsor
	AND SORT.idsorkind = @idsorkind
	AND SORLINK.nlevel = SORT.nlevel
	AND SORT.nlevel = (SELECT  MIN(nlevel) 
			FROM sortinglevel 
	  		WHERE   idsorkind = @idsorkind 	AND ((flag&2)<>0))
	AND SORVAR.ayear = @ayear 
	AND NOT EXISTS (select * from #previsionsor where ayear = @ayear and idsor = SORVAR.idsor)
INSERT INTO #previsionsor
(
	ayear,
	idsor,
	idsorkind,
	expenseprevision,
	incomeprevision
)
SELECT 	DISTINCT
	@ayear,
       	SORT.idsor,
       	SORT.idsorkind,
   	0,
	0
FROM sortingprevexpensevar SORVAR
JOIN    sorting SORT
	ON SORVAR.idsor = SORT.idsor
JOIN sortinglink SORLINK 
	ON SORLINK.idchild =  SORVAR.idsor
WHERE   SORT.idsor = SORVAR.idsor
	AND SORT.idsorkind = @idsorkind
	AND SORLINK.nlevel = SORT.nlevel
	AND SORT.nlevel = (SELECT  MIN(nlevel) 
			FROM sortinglevel 
	  		WHERE   idsorkind = @idsorkind 	AND ((flag&2)<>0))
	AND SORVAR.ayear = @ayear 
	AND NOT EXISTS (select * from #previsionsor where ayear = @ayear and idsor = SORVAR.idsor)
UPDATE #previsionsor SET
	income_var  = ( SELECT SUM(amount)
		FROM    sortingprevincomevar SORVAR
		JOIN    sorting SORT
			ON SORVAR.idsor = SORT.idsor
		JOIN sortinglink SORLINK 
			ON SORLINK.idchild =  SORVAR.idsor
		WHERE   SORT.idsorkind = #previsionsor.idsorkind
			AND SORLINK.idparent = #previsionsor.idsor	
			AND ayear = @ayear 
	),
	expense_var  = ( SELECT SUM(amount)
		FROM    sortingprevexpensevar SORVAR
		JOIN    sorting SORT
			ON SORVAR.idsor = SORT.idsor
		JOIN sortinglink SORLINK 
			ON SORLINK.idchild =  SORVAR.idsor
		WHERE   SORT.idsorkind = #previsionsor.idsorkind
			AND SORLINK.idparent = #previsionsor.idsor	
			AND ayear = @ayear 
	),
	income = ( SELECT  SUM(amount) 
		FROM    incomesorted SORT
		JOIN sortinglink SORLINK 
			ON SORLINK.idchild = SORT.idsor
		WHERE idsorkind = #previsionsor.idsorkind
		AND SORLINK.idparent = #previsionsor.idsor	
		AND SORT.ayear = @ayear 
	), 
	expense = ( SELECT SUM(amount) 
		FROM    expensesorted SORT
		JOIN sortinglink SORLINK 
			ON SORLINK.idchild = SORT.idsor
		WHERE idsorkind = #previsionsor.idsorkind
		AND SORLINK.idparent = #previsionsor.idsor	
		AND SORT.ayear = @ayear )
UPDATE #previsionsor 
	SET expenseprevavailable = ( 
		ISNULL(expenseprevision,0) + 
		ISNULL(expense_var,0) - 
		ISNULL(expense,0) 
	),
		
	incomeprevavailable = ( 
		ISNULL(incomeprevision,0) + 
		ISNULL(income_var,0) - 
		ISNULL(income,0) 
	)
-----------------------------------------
-- Ora fa l'UPDATE o la INSERT nel DB nell'esercizio successivo
-----------------------------------------
DECLARE @nextayear int
SET @nextayear = @ayear +1
UPDATE sortingprev SET 
		expenseprevision = isnull(#previsionsor.expenseprevavailable,0),
		incomeprevision = isnull(#previsionsor.incomeprevavailable,0),
		lu = 'TRASEFRIMENTO'
		FROM #previsionsor
	WHERE sortingprev.ayear = @nextayear
		AND sortingprev.idsor = #previsionsor.idsor
INSERT INTO sortingprev (ayear,idsor,expenseprevision,incomeprevision,lt,lu,ct,cu) 
SELECT  @nextayear,
	idsor,
	isnull(expenseprevavailable,0),
	isnull(incomeprevavailable,0),
	getdate(),'TRASFERIMENTO',getdate(),'TRASEFRIMENTO'
FROM #previsionsor
WHERE NOT EXISTS (SELECT * FROM sortingprev 
		WHERE sortingprev.ayear = @nextayear 
		AND sortingprev.idsor = #previsionsor.idsor
		)
	AND (isnull(expenseprevavailable,0)> 0 OR isnull(incomeprevavailable,0)>0)

END

GO

print 'exp_prevavailable_sorting OK'

GO
if object_id('exp_f24ep') is not null
	drop procedure exp_f24ep
go

CREATE procedure exp_f24ep(@idf24ep int) as
begin

	create table #tributi (
		tiporiga char(1),
		codicetributo varchar(4),
		tipoente varchar(4),
		rifA varchar(4),
		rifB  varchar(4)
	)

	--exec exp_f24ep 16

	
	insert into #tributi values ('S','384E','CCCC','00MM','AAAA') -- Addizionale comunale Irpef trattenuta dai sostituti d’imposta -saldo  
	insert into #tributi values ('S','385E','CCCC','00MM','AAAA') -- Addizionale comunale Irpef trattenuta dai sostituti d’imposta- acconto 
	insert into #tributi values ('S','891E','CCCC',  null,'AAAA') -- Sanzioni per ravvedimento su Addizionale comunale Irpef trattenuta dai sostituti d’imposta 
	--insert into #tributi values ('382E',  'EE','00MM','AAAA') -- Addizionale comunale Irpef trattenuta dai sostituti d’imposta  su emolumenti corrisposti nell’anno solare 2007–saldo  	
	--insert into #tributi values ('383E',  'EE','00MM','AAAA') -- Addizionale comunale Irpef trattenuta dai sostituti d’imposta su emolumenti corrisposti nell’anno solare 2007- acconto    
	
	insert into #tributi values ('R','380E',  'RR','00MM','AAAA') -- IRAP  	
	insert into #tributi values ('R','381E',  'RR','00MM','AAAA') -- Addizionale regionale Irpef trattenuta dai sostituti d’imposta  
	insert into #tributi values ('R','892E',  'RR',  null,'AAAA') -- Sanzioni per ravvedimento su IRAP 
	insert into #tributi values ('R','893E',  'RR',  null,'AAAA') -- Sanzioni per ravvedimento Addizionale regionale Irpef trattenuta dai sostituti d’imposta  
	
	insert into #tributi values ('F','100E',  null,'00MM','AAAA') -- Ritenute sui redditi da lavoro dipendente ed assimilati  
	insert into #tributi values ('F','104E',  null,'00MM','AAAA') -- Ritenute sui redditi da lavoro autonomo  
	insert into #tributi values ('F','105E',  null,'00MM','AAAA') -- Ritenute sulle indennità di esproprio, occupazione , etc. - articolo 11, legge 413/91  
	insert into #tributi values ('F','106E',  null,'00MM','AAAA') -- Ritenute sui contributi corrisposti alle imprese - articolo 28 D.P.R. 600/73 
	insert into #tributi values ('F','107E',  null,'00MM','AAAA') -- Altre ritenute alla fonte  
	insert into #tributi values ('F','890E',  null,  null,'AAAA') -- Sanzioni per ravvedimento su ritenute erariali 

	insert into #tributi values ('I','C10',  null,  'MMAAAA',null) -- Sanzioni per ravvedimento su ritenute erariali 
	insert into #tributi values ('I','CXX',  null,  'MMAAAA',null) -- Sanzioni per ravvedimento su ritenute erariali 
	insert into #tributi values ('Q','P101',  null,  'MMAAAA','MMAAAA') -- Sanzioni per ravvedimento su ritenute erariali 
	insert into #tributi values ('Q','P909',  null,  'MMAAAA','MMAAAA') -- Sanzioni per ravvedimento su ritenute erariali 

	
	--declare @annodichiarazione int
	--set @annodichiarazione = 2008
	
	--select * from #tributi

	create table #f24 (
		tiporiga char(1),
		codicetributo varchar(4),
		codice  varchar(4), -- ex codiceEnte
		estremi varchar(17),
		riferimentoA varchar(6),
		riferimentoB varchar(6),
		importoADebito decimal(19,2),
		
	)
           



	create table #errori (
		taxcode int,
		idexp int,
		ytaxpay smallint,
		ntaxpay int,
		message varchar(200)
	)


	insert into #errori (taxcode, idexp, ytaxpay, ntaxpay, message)
		select taxpay.taxcode, null, taxpay.ytaxpay, taxpay.ntaxpay,
		'Il tributo '+isnull(tax.taxref,'')+' ha il codice '+
		isnull(tax.fiscaltaxcode,'')+
		' che non è gestito dalla procedura di generazione del modello f24ep'
		from taxpay 
		join tax on tax.taxcode = taxpay.taxcode
		where idf24ep = @idf24ep
		and not exists (select * from #tributi where #tributi.codicetributo = tax.fiscaltaxcode)

	if (select count(*) from #errori) > 0
	begin
		select * from #errori
		return
	end

	declare @codiceTributo varchar(4)
	declare @importoADebito decimal(19,2)
	declare @tiporiga char(1)
	declare @codice  varchar(4) --ex codiceEnte
	declare @estremi varchar(17)
	declare @riferimentoA varchar(6)
	declare @riferimentoB varchar(6)

	declare @rifA varchar(4)
	declare @rifB varchar(4)


	declare @taxcode int
	declare @idexp int
	declare @transmissiondate datetime
	declare @ytaxpay smallint
	declare @ntaxpay int
	declare @idcity int
	declare @idfiscaltaxregion varchar(5)
	declare @idcountry int
	declare @geoappliance char(1)
	declare @tipoEnte varchar(4)
	declare @sanctioncode varchar(4)
	declare @ayearsanction smallint
	declare @idreg int
	declare @fiscalyear int
	declare @annotrasmissione smallint
	declare @iniziocompetenza datetime
	declare @finecompetenza datetime
	declare @mese int
	declare @anno smallint

	--declare @12gen08 datetime
	--select  @12gen08 = dateadd(yy, @annodichiarazione-2000, {d '2000-01-12'})
						
	--declare @idf24ep int
	--set @idf24ep = 1
	create table #versamenti (
		maintaxcode int,
		idcity  int,
		idfiscaltaxregion varchar(5),
		taxcode int,
		idexp int,
		idreg int,
		ytaxpay smallint,
		ntaxpay int,
		sanctioncode varchar(4),
		ayearsanction smallint,
		importoadebito decimal(19,2),
		datatrasmissione datetime,
		annotrasmissione smallint,
		iniziocompetenza datetime,--da expenselast
		finecompetenza datetime, --da expenselast
		anno smallint,
		meseriferimento int
		)
	
	INSERT INTO  #versamenti
	(maintaxcode, idcity, idfiscaltaxregion, taxcode, idexp,idreg, ytaxpay, ntaxpay, 
	importoadebito, datatrasmissione, annotrasmissione, meseriferimento,iniziocompetenza,finecompetenza, anno)
	select  maintaxcode = taxpay.taxcode, expensetax.idcity,
		expensetax.idfiscaltaxregion,expensetax.taxcode, 
		expensetax.idexp, expense.idreg, taxpay.ytaxpay, taxpay.ntaxpay,
		importoadebito = isnull(sum(isnull(admintax,0)+isnull(employtax,0)),0),
		paymenttransmission.transmissiondate, 
		year(paymenttransmission.transmissiondate),
		month(paymenttransmission.transmissiondate),
		expenselast.servicestart,expenselast.servicestop,
		isnull(expensetax.ayear,year(paymenttransmission.transmissiondate))
		--expensetax.ayear
		from taxpay 
		join tax on isnull(tax.maintaxcode, tax.taxcode) = taxpay.taxcode
		join expensetax 
			on expensetax.taxcode = tax.taxcode
			and expensetax.ytaxpay = taxpay.ytaxpay
			and expensetax.ntaxpay = taxpay.ntaxpay
		join expense
			on expense.idexp = expensetax.idexp
		join expenselast 
			on expenselast.idexp = expense.idexp
		join payment 
			on payment.kpay = expenselast.kpay
		join paymenttransmission 
			on paymenttransmission.kpaymenttransmission = 
			payment.kpaymenttransmission
		where taxpay.idf24ep = @idf24ep
		group by expensetax.taxcode, taxpay.taxcode, expensetax.idcity,
		expensetax.idfiscaltaxregion,expensetax.idexp, taxpay.ytaxpay, taxpay.ntaxpay,
		paymenttransmission.transmissiondate, year(paymenttransmission.transmissiondate), 
		month(paymenttransmission.transmissiondate), expenselast.servicestart,expenselast.servicestop,
		isnull(expensetax.ayear,year(paymenttransmission.transmissiondate)), expense.idreg

	--select 1,* from #versamenti
	--insert da expensetaxcorrige
	INSERT INTO  #versamenti
	(maintaxcode, idcity, idfiscaltaxregion, taxcode, idexp, idreg, ytaxpay, ntaxpay, importoadebito,
	 datatrasmissione, annotrasmissione, meseriferimento,iniziocompetenza,finecompetenza, anno)
	select  maintaxcode = taxpay.taxcode, expensetaxcorrige.idcity,
		expensetaxcorrige.idfiscaltaxregion, expensetaxcorrige.taxcode, 
		expensetaxcorrige.idexp,expense.idreg, taxpay.ytaxpay, taxpay.ntaxpay,
		importoadebito = isnull(sum(isnull(adminamount,0)+isnull(employamount,0)),0),
		paymenttransmission.transmissiondate, 
		year(paymenttransmission.transmissiondate),
		month(paymenttransmission.transmissiondate),
		expenselast.servicestart,expenselast.servicestop,
		isnull(expensetaxcorrige.ayear,year(paymenttransmission.transmissiondate))
		--expensetax.ayear
		from taxpay 
		join tax on isnull(tax.maintaxcode, tax.taxcode) = taxpay.taxcode
		join expensetaxcorrige 
			on expensetaxcorrige.taxcode = tax.taxcode
			and expensetaxcorrige.ytaxpay = taxpay.ytaxpay
			and expensetaxcorrige.ntaxpay = taxpay.ntaxpay
		join expense
			on expense.idexp = expensetaxcorrige.idexp
		join expenselast 
			on expenselast.idexp = expense.idexp
		join payment 
			on payment.kpay = expenselast.kpay
		join paymenttransmission 
			on paymenttransmission.kpaymenttransmission = 
			payment.kpaymenttransmission
		where taxpay.idf24ep = @idf24ep
		group by expensetaxcorrige.taxcode, taxpay.taxcode, expensetaxcorrige.idcity,
		expensetaxcorrige.idfiscaltaxregion,expensetaxcorrige.idexp, taxpay.ytaxpay, taxpay.ntaxpay,
		paymenttransmission.transmissiondate, year(paymenttransmission.transmissiondate), 
		month(paymenttransmission.transmissiondate),expenselast.servicestart,expenselast.servicestop,
		isnull(expensetaxcorrige.ayear,year(paymenttransmission.transmissiondate)),expense.idreg

		update #versamenti set meseriferimento=12 where anno<year(datatrasmissione)
		update #versamenti set anno=year(datatrasmissione)-1 where anno<year(datatrasmissione)

	--select 2,* from #versamenti
	-- Sanzioni per Ravvedimento Operoso
	INSERT INTO  #versamenti
		(sanctioncode,idcity,idfiscaltaxregion,importoadebito, ayearsanction)
	SELECT  fiscaltaxcode,
		ISNULL(idcity,0),
		idfiscaltaxregion,
		importoadebito = isnull(amount,0),
		f24epsanction.ayear
		FROM   f24epsanction 
		JOIN   f24epsanctionkind  
		ON f24epsanction.idsanction = f24epsanctionkind.idsanction
		WHERE  f24epsanction.idf24ep = @idf24ep
	
	--select 2,* from #versamenti
	--select * from #versamenti
	--drop table #versamenti
	declare  @myfiscalregion int
	declare @myidcity int
	select @myidcity=max(idcity) from	license
	select @myfiscalregion= idfiscaltaxregion from geo_cityfiscalview where idcity=@myidcity

	declare @cursore cursor

	set @cursore = cursor for 
		select taxcode, idexp, idreg, idcity,idfiscaltaxregion, ytaxpay, ntaxpay, 
		importoadebito, datatrasmissione, annotrasmissione, meseriferimento, anno,
		sanctioncode, ayearsanction, iniziocompetenza,finecompetenza
		from #versamenti
	
	open @cursore
	fetch next from @cursore into @taxcode, @idexp, @idreg, @idcity,
			@idfiscaltaxregion, @ytaxpay, @ntaxpay, 
			@importoADebito, @transmissiondate, @annotrasmissione, 
			@mese, @anno,
			@sanctioncode, @ayearsanction, @iniziocompetenza, @finecompetenza
	while @@fetch_status = 0
	begin
		set @codice = null --ex @codiceEnte
		set @geoappliance = null
		set @riferimentoA=null
		set @riferimentoB=null
		set @estremi=null
		set @tiporiga=null
		set @codiceTributo =null
		set @tipoente=null

		set @rifA =null
		set @rifB =null

		select  @codiceTributo = tax.fiscaltaxcode, 
			@tiporiga = #tributi.tiporiga,
			@tipoente = #tributi.tipoente, 
			@rifA = #tributi.rifA,
			@rifB= #tributi.rifB,
			@geoappliance = tax.geoappliance
			from tax 
			join #tributi on #tributi.codicetributo = tax.fiscaltaxcode
			where tax.taxcode = @taxcode
		
		

		--SANZIONI PER RAVVEDIMENTO OPEROSO
		IF      @sanctioncode IS NOT NULL
		BEGIN
			SELECT @codiceTributo = @sanctioncode,
			@tiporiga = #tributi.tiporiga,
			@tipoente = #tributi.tipoente, 
			@rifA = #tributi.rifA,
			@rifB = #tributi.rifB,
			@geoappliance = tax.geoappliance,
			@anno = @ayearsanction
			from tax 
			join #tributi on #tributi.codicetributo = tax.fiscaltaxcode
			where #tributi.codicetributo = @sanctioncode
			--FROM #tributi 
			--WHERE #tributi.codicetributo = @sanctioncode
		END



		--Per l'irap (380e) facciamo un calcolo a parte 
		if (@codiceTributo='380E' )			
		begin
			set @idcity= @myidcity
			set @idfiscaltaxregion=@myfiscalregion
		end

	
		
		if (@geoappliance ='C' and @idcity is null)
		begin 
		insert into #errori (taxcode, idexp, ytaxpay, ntaxpay, message)
			values (@taxcode, @idexp, @ytaxpay, @ntaxpay, 
			'Per il tributo con codice ' + isnull(@codiceTributo, '')
			+ ' non è stato valorizzato il comune di riferimento');
		end


		if (@geoappliance ='R' and @idfiscaltaxregion is null )
		begin 
		insert into #errori (taxcode, idexp, ytaxpay, ntaxpay, message)
			values (@taxcode, @idexp, @ytaxpay, @ntaxpay, 
			'Per il tributo con codice ' + isnull(@codiceTributo, '')
			+ ' non è stato valorizzata la regione di riferimento');
		end

		if (@rifA = '00MM')
		begin
			if (@mese>9) set @riferimentoA= '00'+convert(varchar(2),@mese)
			if (@mese<=9) set @riferimentoA= '000'+convert(varchar(2),@mese)
		end

		if (@rifA = 'MMAAAA' and @rifB is null)
		begin
			if (@mese>9) set @riferimentoA= convert(varchar(2),month(@mese))+convert(varchar(4),@anno)
			if (@mese<=9) set @riferimentoA= '0'+convert(varchar(2),month(@mese))+convert(varchar(4),@anno)
		end
		if (@rifA = 'MMAAAA' and @rifB is not null)
		begin
			if (month(@iniziocompetenza)>9) set @riferimentoA= 
				convert(varchar(2),month(@iniziocompetenza))+convert(varchar(4),year(@iniziocompetenza))
			if (month(@iniziocompetenza)<=9) set @riferimentoA= '0'+
				convert(varchar(2),month(@iniziocompetenza))+convert(varchar(4),year(@iniziocompetenza))
		end

		if (@rifA='00MM' and @riferimentoA is null)
			insert into #errori (taxcode, idexp, ytaxpay, ntaxpay, message)
					values (@taxcode, @idexp, @ytaxpay, @ntaxpay, 
					'Per il tributo con codice ' + isnull(@codiceTributo, '')
					+ ' la procedura non è stata in grado di ricavare il mese di riferimento');

		if (@rifA='MMAAAA' and @riferimentoA is null and @rifB is null)
			insert into #errori (taxcode, idexp, ytaxpay, ntaxpay, message)
					values (@taxcode, @idexp, @ytaxpay, @ntaxpay, 
					'Per il tributo con codice ' + isnull(@codiceTributo, '')
					+ ' la procedura non è stata in grado di ricavare la data di pagamento');

		if (@rifA='MMAAAA' and @riferimentoA is null and @rifB is not null)
			insert into #errori (taxcode, idexp, ytaxpay, ntaxpay, message)
					values (@taxcode, @idexp, @ytaxpay, @ntaxpay, 
					'Per il tributo con codice ' + isnull(@codiceTributo, '')
					+ ' la procedura non è stata in grado di ricavare la data di inizio competenza');



		if (@rifB = 'MMAAAA' )
		begin
			if (month(@finecompetenza)>9) set @riferimentoB= 
				convert(varchar(2),month(@finecompetenza))+convert(varchar(4),year(@finecompetenza))
			if (month(@finecompetenza)<=9) set @riferimentoB= '0'+
				convert(varchar(2),month(@finecompetenza))+convert(varchar(4),year(@finecompetenza))
		end

		if (@rifB = 'AAAA' )
		begin
			set @riferimentoB=convert(varchar(4),@anno)
		end


		if (@rifB='AAAA' and @riferimentoB is null)
			insert into #errori (taxcode, idexp, ytaxpay, ntaxpay, message)
					values (@taxcode, @idexp, @ytaxpay, @ntaxpay, 
					'Per il tributo con codice ' + isnull(@codiceTributo, '')
					+ ' la procedura non è stata in grado di ricavare l''anno di riferimento');

		if (@rifB='MMAAAA' and @riferimentoB is null)
			insert into #errori (taxcode, idexp, ytaxpay, ntaxpay, message)
					values (@taxcode, @idexp, @ytaxpay, @ntaxpay, 
					'Per il tributo con codice ' + isnull(@codiceTributo, '')
					+ ' la procedura non è stata in grado di ricavare la data di fine competenza');


				
		
--sezione: ENTI LOCALI
		if @tipoente in ('CCCC','EE')
		begin
			
			select @fiscalyear = @anno  -- anno fiscale letto da expensetax e non da payroll o dal contratto
			
			
			-- CODICE ENTE LOCALE TAB T1 (EE)  
			-- SOLO 
			if @tipoEnte = 'EE'
			begin
				select @codice = case 
						when geo_country.idcountry = 21 then '03'--Bolzano
						when geo_country.idregion = 6 then '07'--Friuli Venezia Giulia
						when geo_country.idcountry = 22 then '18'--Trento
						when geo_country.idregion = 2 then '20'--Valle d'Aosta
						else '99' 
					end
					from geo_country
					join geo_city 
						on geo_city.idcountry = geo_country.idcountry
					where geo_city.idcity = @idcity
				
				if @codice is null
					begin 
					insert into #errori (taxcode, idexp, ytaxpay, ntaxpay, message)
						values (@taxcode, @idexp, @ytaxpay, @ntaxpay, 
						'Per il tributo con codice ' + isnull(@codiceTributo, '')
						+ ' la procedura non è stata in grado di ricavare il codice dell''ente 
						(provincia autonoma/regione)');
					end
			end
			
			
		end
		
		
		
		
		-- CODICE CATASTALE COMUNE (CCCC)  
		if @tipoEnte = 'CCCC'
		begin
			select @codice = geo_city_agency.value
				from geo_city_agency
				where geo_city_agency.idcity = @idcity
				and geo_city_agency.idagency = 1
				and geo_city_agency.idcode = 1
			
			if @codice is null
				begin 
				insert into #errori (taxcode, idexp, ytaxpay, ntaxpay, message)
					values (@taxcode, @idexp, @ytaxpay, @ntaxpay, 
					'Per il tributo con codice ' + isnull(@codiceTributo, '')
					+ ' la procedura non è stata in grado di ricavare il codice dell''ente 
					(comune)');
				end
		end
			
		--sezione: REGIONI  
		if @tipoente = 'RR'
		begin
			select  @codice = @idfiscaltaxregion
			
			if @codice is null
			begin 
				insert into #errori (taxcode, idexp, ytaxpay, ntaxpay, message)
					values (@taxcode, @idexp, @ytaxpay, @ntaxpay, 
					'Per il tributo con codice ' + isnull(@codiceTributo, '')
					+ ' la procedura non è stata in grado di ricavare il codice dell''ente (regione)');
			end
		end
						

		insert into #f24 (tiporiga,codicetributo, codice, estremi, riferimentoA, riferimentoB, importoADebito)
			values (@tiporiga, @codiceTributo, @codice, @estremi, @riferimentoA, @riferimentoB, @importoADebito)


		fetch next from  @cursore into @taxcode, @idexp, @idreg, @idcity,
			@idfiscaltaxregion, @ytaxpay, @ntaxpay, 
			@importoADebito, @transmissiondate, @annotrasmissione, @mese, @anno,
			@sanctioncode, @ayearsanction
	end
	
	if (select count(*) from #errori) > 0
	begin
		select 
			'Ritenuta' = tax.taxref,
			'Eserc.liquidaz.' = #errori.ytaxpay,
			'Num.liquidaz.' = #errori.ntaxpay,
			'Fase spesa' = expensephase.description,
			'Eserc.movim.' = expense.ymov,
			'Num.movim.' = expense.nmov,
			'Problema riscontrato' = #errori.message
			from #errori
			join expense on expense.idexp = #errori.idexp
			join expensephase on expensephase.nphase = expense.nphase
			join tax on tax.taxcode = #errori.taxcode
	end else begin
		select tiporiga,codicetributo, codice, estremi,riferimentoA,riferimentoB,
		importoadebito = sum(importoADebito)
		from #f24
		group by tiporiga,codicetributo, codice,  estremi,riferimentoA,riferimentoB

	

	end
	
end


GO

print 'exp_f24ep OK'

GO
if object_id('rpt_scaricoperunitaorganizzativa') is not null
	drop PROCEDURE rpt_scaricoperunitaorganizzativa
go

CREATE     PROCEDURE rpt_scaricoperunitaorganizzativa(
	@ayear	smallint ,
	@idstore int,
	@idsor1 int,-- configurare % come default, ossia se % vedi tutto
	@idsor2 int,
	@idsor3 int,
	@start datetime,
	@stop datetime
)
-- exec rpt_scaricoperunitaorganizzativa 2011, 1, null,null, null, '01/01/2011', '24/11/2011'
AS BEGIN
IF @idsor1 = 0 SET @idsor1 = NULL
IF @idsor2 = 0 SET @idsor2 = NULL
IF @idsor3 = 0 SET @idsor3 = NULL
DECLARE @idsortingkind1 varchar(20)
DECLARE @idsortingkind2 varchar(20)
DECLARE @idsortingkind3 varchar(20)
SELECT
	@idsortingkind1 = idsortingkind1,
	@idsortingkind2 = idsortingkind2,
	@idsortingkind3 = idsortingkind3
FROM config WHERE ayear = @ayear
DECLARE @sortingkind1 varchar(50)
SELECT @sortingkind1 = description FROM sortingkind WHERE idsorkind = @idsortingkind1
DECLARE @sortingkind2 varchar(50)
SELECT @sortingkind2 = description FROM sortingkind WHERE idsorkind = @idsortingkind2
DECLARE @sortingkind3 varchar(50)
SELECT @sortingkind3 = description FROM sortingkind WHERE idsorkind = @idsortingkind3
DECLARE @lencodesor int
SET @lencodesor = 50
SELECT
	D.ystoreunload,
	D.nstoreunload, 
	D.adate,--> data bolla
	D.description, -- decrizione dello scarico
	L.intcode, -- codice articolo
	L.description as list, --- descrizione  articolo
	U.description as unit,-- unita di carico/scarico
	isnull(sum(Det.number),0) as number,	-- q.tà Scaricata
	R.title as registry,-- fornitore per il Reso
	M.description as store,
	S1.nlevel as nlevel1, 
	K1.description as level1,
	S1.idsor as idsor1,
	S1.sortcode as sortcode1, 
	S1.description as description1, 
	
	S2.nlevel as nlevel2, 
	K2.description as level2,
	S2.idsor as idsor2,
	S2.sortcode as sortcode2, 
	S2.description as description2,
	S3.nlevel as nlevel3, 
	K3.description as level3,
	S3.idsor as idsor3,
	S3.sortcode as sortcode3, 
	S3.description as description3,
	
	round(S.amount/S.number,5) * isnull(sum(Det.number),0) as 'costototale' ,
	Det.idman,
	G.title
FROM storeunload D
JOIN storeunloaddetail Det
	ON D.idstoreunload = Det.idstoreunload
JOIN stock S
	ON Det.idstock = S.idstock
JOIN list L
	ON L.idlist = S.idlist
JOIN unit U
	ON U.idunit = L.idunit
JOIN store M
	ON M.idstore = D.idstore	
LEFT OUTER JOIN registry R
	ON R.idreg = D.idreg
LEFT OUTER JOIN sorting S1
	ON Det.idsor1 = S1.idsor AND S1.idsorkind = @idsortingkind1 
LEFT OUTER JOIN sortinglevel K1
	ON S1.nlevel = K1.nlevel AND K1.idsorkind = @idsortingkind1 
LEFT OUTER JOIN sorting S2
	ON Det.idsor2 = S2.idsor AND S2.idsorkind = @idsortingkind2 
LEFT OUTER JOIN sortinglevel K2
	ON S2.nlevel = K2.nlevel AND K2.idsorkind = @idsortingkind2 
LEFT OUTER JOIN sorting S3
	ON Det.idsor3 = S3.idsor AND S3.idsorkind = @idsortingkind3 
LEFT OUTER JOIN sortinglevel K3
	ON S3.nlevel = K3.nlevel AND K3.idsorkind = @idsortingkind3 
LEFT OUTER JOIN manager G
	ON G.idman = Det.idman
WHERE
	( D.idstore = @idstore OR @idstore IS NULL )
	AND D.ystoreunload = @ayear
	AND (@idsor1 IS NULL OR Det.idsor1 = @idsor1  )
	AND (@idsor2 IS NULL OR Det.idsor2 = @idsor2  )
	AND (@idsor3 IS NULL OR Det.idsor3 = @idsor3  )
	AND D.adate between @start AND @stop
GROUP BY 
	D.ystoreunload,
	D.nstoreunload, 
	D.adate,-- data bolla
	D.description, -- decrizione dello scarico
	L.intcode, -- codice articolo
	L.description, --- descrizione  articolo
	U.description,-- unita di carico/scarico
	R.title,-- fornitore per il Reso
	M.description ,
	K1.description, S1.nlevel, S1.idsor, S1.sortcode, S1.description ,
	K2.description, S2.nlevel, S2.idsor, S2.sortcode, S2.description ,
	K3.description, S3.nlevel, S3.idsor, S3.sortcode, S3.description,
	S.amount, S.number, Det.idman, G.title 
ORDER BY S1.sortcode, S2.sortcode, S3.sortcode,  L.intcode, D.adate
END

GO

print 'rpt_scaricoperunitaorganizzativa OK'

GO
if object_id('exp_fin_with_nozero_balance') is not null
	drop PROCEDURE exp_fin_with_nozero_balance
go

CREATE   PROCEDURE exp_fin_with_nozero_balance
(
	@ayear int,
	@finpart char(1)
)
AS BEGIN
CREATE TABLE #dip
(
	idfin int,
	kind char(1),
	total decimal(19,2)
)
INSERT INTO #dip (idfin, kind, total)
SELECT D.idfin, 'P', SUM(D.amount)
FROM finvar V
JOIN finvardetail D
	ON V.yvar = D.yvar
	AND V.nvar = D.nvar
JOIN fin F
	ON F.idfin = D.idfin
WHERE D.idupb = '0001'
	AND V.variationkind = 4
	AND V.yvar = @ayear
	AND V.flagprevision = 'S'
	AND V.idfinvarstatus = 5
	AND (
		(((F.flag & 1) = 0) AND (@finpart = 'E'))
		OR
		(((F.flag & 1) <> 0) AND (@finpart = 'S'))
	)
GROUP BY D.idfin
INSERT INTO #dip (idfin, kind, total)
SELECT D.idfin, 'P', SUM(D.amount)
FROM finvar V
JOIN finvardetail D
	ON V.yvar = D.yvar
	AND V.nvar = D.nvar
JOIN fin F
	ON F.idfin = D.idfin
WHERE D.idupb <> '0001'
	AND V.variationkind = 4
	AND V.yvar = @ayear
	AND V.flagprevision = 'S'
	AND V.idfinvarstatus = 5
	AND (
		(((F.flag & 1) = 0) AND (@finpart = 'E'))
		OR
		(((F.flag & 1) <> 0) AND (@finpart = 'S'))
	)
GROUP BY D.idfin
DECLARE @fin_kind int
SELECT @fin_kind = fin_kind FROM config WHERE ayear = @ayear
IF (@fin_kind = 3)
BEGIN
	INSERT INTO #dip (idfin, kind, total)
	SELECT D.idfin, 'S', SUM(D.amount)
	FROM finvar V
	JOIN finvardetail D
		ON V.yvar = D.yvar
		AND V.nvar = D.nvar
	JOIN fin F
		ON F.idfin = D.idfin
	WHERE D.idupb = '0001'
		AND V.variationkind = 4
		AND V.yvar = @ayear
		AND V.flagsecondaryprev = 'S'
		AND V.idfinvarstatus = 5
		AND (
			(((F.flag & 1) = 0) AND (@finpart = 'E'))
			OR
			(((F.flag & 1) <> 0) AND (@finpart = 'S'))
		)
	GROUP BY D.idfin
	
	INSERT INTO #dip (idfin, kind, total)
	SELECT D.idfin, 'S', SUM(D.amount)
	FROM finvar V
	JOIN finvardetail D
		ON V.yvar = D.yvar
		AND V.nvar = D.nvar
	JOIN fin F
		ON F.idfin = D.idfin
	WHERE D.idupb <> '0001'
		AND V.variationkind = 4
		AND V.yvar = @ayear
		AND V.flagsecondaryprev = 'S'
		AND V.idfinvarstatus = 5
		AND (
			(((F.flag & 1) = 0) AND (@finpart = 'E'))
			OR
			(((F.flag & 1) <> 0) AND (@finpart = 'S'))
		)
	GROUP BY D.idfin
END
IF (@fin_kind <> 3)
BEGIN
	-- Vengono considerate solo le variazioni di storno
	SELECT F.codefin as 'Codice Bilancio',
	F.title AS 'Descrizione', SUM(#dip.total) as 'Saldo'
	FROM #dip
	JOIN fin F
		ON F.idfin = #dip.idfin
	GROUP BY #dip.idfin, F.codefin, F.title
	HAVING SUM(#dip.total) <> 0
END
ELSE
BEGIN
	-- Vengono considerate solo le variazioni di storno
	SELECT F.codefin as 'Codice Bilancio',
	F.title AS 'Descrizione', SUM(#dip.total) as 'Saldo',
	CASE
		WHEN #dip.kind = 'P'
		THEN 'Competenza'
		ELSE 'Cassa'
	END AS 'Previsione'
	FROM #dip
	JOIN fin F
		ON F.idfin = #dip.idfin
	GROUP BY #dip.idfin, F.codefin, F.title, #dip.kind
	HAVING SUM(#dip.total) <> 0
END
END


GO

print 'exp_fin_with_nozero_balance OK'

GO
if object_id('[rpt_missione_authagency]') is not null
	drop PROCEDURE [rpt_missione_authagency]
go

CREATE    PROCEDURE [rpt_missione_authagency]
	@yitineration smallint, 
	@nitineration int
AS BEGIN
SELECT 
	authagency.title AS authagency_title,
	authagency.description AS authagency_desc,
	itinerationauthagency.lt AS authagency_date,
	authagency.priority,
	CASE WHEN itinerationauthagency.flagstatus = 'S' THEN 'Approvata'
		 WHEN itinerationauthagency.flagstatus = 'N' THEN 'Non Approvata'
		 WHEN itinerationauthagency.flagstatus = 'D' THEN 'Da Esaminare'
	END AS 'status'
FROM itineration
	JOIN itinerationauthagency 
		ON itineration.iditineration = itinerationauthagency.iditineration
	JOIN authagency
		ON itinerationauthagency.idauthagency = authagency.idauthagency
WHERE itineration.yitineration = @yitineration
AND itineration.nitineration = @nitineration
ORDER BY authagency.priority
END

GO

print '[rpt_missione_authagency] OK'

GO
if object_id('[closeyear_check_fincopy]') is not null
	drop PROCEDURE [closeyear_check_fincopy]
go

CREATE    PROCEDURE [closeyear_check_fincopy]
(
	@ayear int
)
AS BEGIN
CREATE TABLE #errors (errordescr varchar(255))
DECLARE @nextayear int
SET @nextayear = @ayear + 1
	
DECLARE @nextayearstr varchar(4)
SET @nextayearstr = CONVERT(varchar(4), @nextayear)
DECLARE @unifiedfinlevel int
SET @unifiedfinlevel = ISNULL((SELECT unifiedfinlevel FROM commonconfig WHERE ayear = @nextayear),0)
DECLARE @minlevop tinyint
SELECT  @minlevop = MIN(nlevel) FROM finlevel WHERE flag&2 <> 0 AND ayear = @nextayear 
IF EXISTS (SELECT * FROM finlevel WHERE ayear = @nextayear AND nlevel > @minlevop AND nlevel > @unifiedfinlevel)
BEGIN
	INSERT INTO #errors VALUES('Livelli del bilancio annuale per esercizio ' + @nextayearstr + ' esistenti.')
END
IF EXISTS (SELECT * FROM fin WHERE ayear = @nextayear AND nlevel > @minlevop AND nlevel > @unifiedfinlevel)
BEGIN
	INSERT INTO #errors VALUES('Voci del bilancio annuale per esercizio ' + @nextayearstr + ' esistenti.')
END
IF EXISTS (SELECT * FROM sortingprev WHERE ayear = @nextayear)
BEGIN
	INSERT INTO #errors VALUES('Previsioni classificazioni movimenti per esercizio ' + @nextayearstr + ' esistenti.')
END
SELECT * FROM #errors
END


GO

print '[closeyear_check_fincopy] OK'

