	CASE
		WHEN DATALENGTH(ISNULL(address,'')) <= @lenindirizzo
		THEN ISNULL(address,'') + SUBSTRING(SPACE(@lenindirizzo),1,@lenindirizzo - DATALENGTH(ISNULL(address,'')))
