if object_id('compute_sortingvariation') is not null
	drop PROCEDURE compute_sortingvariation
go

CREATE       PROCEDURE compute_sortingvariation
(
	@ayear int,
	@idsorkind int
)
AS BEGIN
DECLARE @nextayear int
SET @nextayear = @ayear + 1
CREATE TABLE #sortingprevexpensevar
(
	nvar int identity (1,1),
	idsor int,
	amount decimal(19,2)
)
INSERT INTO #sortingprevexpensevar
(
	idsor,
	amount
)
SELECT expensesorted.idsor, SUM(expensesorted.amount)
FROM expensesorted
JOIN sorting
	ON expensesorted.idsor = sorting.idsor
JOIN expensetotal
	ON expensetotal.idexp = expensesorted.idexp
	AND expensetotal.ayear = expensesorted.ayear
WHERE sorting.idsorkind = @idsorkind
	AND expensesorted.ayear = @nextayear
	AND (expensetotal.flag & 1 <> 0)
GROUP BY expensesorted.idsor
HAVING SUM(expensesorted.amount) <> 0
DECLARE @maxnvar_exp int
SET @maxnvar_exp = 1 + ISNULL((SELECT MAX(nvar) FROM sortingprevexpensevar WHERE ayear = @nextayear),0)
DECLARE @firstday datetime
SET @firstday = CONVERT(datetime, '01-01-' + CONVERT(char(4),@nextayear), 105)
INSERT INTO sortingprevexpensevar
(
	yvar,
	nvar,
	adate,
	idsor,
	amount,
	ayear,
	description,
	ct, cu, lt, lu
)
SELECT 
	@nextayear,
	nvar + @maxnvar_exp,
	@firstday,
	idsor,
	amount,
	@nextayear,
	'Variazioni sui residui',
	GETDATE(), 'SA', GETDATE(), 'SA'
FROM #sortingprevexpensevar
CREATE TABLE #sortingprevincomevar
(
	nvar int identity (1,1),
	idsor int,
	amount decimal(19,2)
)
INSERT INTO #sortingprevincomevar
(
	idsor,
	amount
)
SELECT incomesorted.idsor, SUM(incomesorted.amount)
FROM incomesorted
JOIN sorting
	ON incomesorted.idsor = sorting.idsor
JOIN incometotal
	ON incometotal.idinc = incomesorted.idinc
	AND incometotal.ayear = incomesorted.ayear
WHERE sorting.idsorkind = @idsorkind
	AND incomesorted.ayear = @nextayear
	AND (incometotal.flag & 1 <> 0)
GROUP BY incomesorted.idsor
HAVING SUM(incomesorted.amount) <> 0
DECLARE @maxnvar_inc int
SET @maxnvar_inc = 1 + ISNULL((SELECT MAX(nvar) FROM sortingprevincomevar WHERE ayear = @nextayear),0)
INSERT INTO sortingprevincomevar
(
	yvar,
	nvar,
	adate,
	idsor,
	amount,
	ayear,
	description,
	ct, cu, lt, lu
)
SELECT 
	@nextayear,
	nvar + @maxnvar_inc,
	@firstday,
	idsor,
	amount,
	@nextayear,
	'Variazioni sui residui',
	GETDATE(), 'SA', GETDATE(), 'SA'
FROM #sortingprevincomevar
END

GO

print 'compute_sortingvariation OK'

GO
if object_id('[closeyear_check_yearcreate]') is not null
	drop PROCEDURE [closeyear_check_yearcreate]
go

CREATE                     PROCEDURE [closeyear_check_yearcreate]
(
	@ayear int
)
AS BEGIN
CREATE TABLE #errorlog (errordescr varchar(255))
DECLARE @nextayear int
SET @nextayear = @ayear + 1
	
DECLARE @nextayearstr varchar(4)
SET @nextayearstr = CONVERT(varchar(4), @nextayear)
	
IF EXISTS (SELECT * FROM accountingyear WHERE ayear = @nextayear)
BEGIN
	INSERT INTO #errorlog VALUES('Esercizio ' + @nextayearstr + ' esistente.')
END
IF EXISTS (SELECT * FROM config WHERE ayear = @nextayear)
BEGIN
	INSERT INTO #errorlog VALUES('Configurazione generale per esercizio ' + @nextayearstr + ' esistente.')
END
IF EXISTS (SELECT * FROM trasmissionmanager WHERE ayear = @nextayear)
BEGIN
	INSERT INTO #errorlog VALUES('Responsabile della trasmissione per esercizio ' + @nextayearstr + ' esistenti.')
END
SELECT * FROM #errorlog
END



GO

print '[closeyear_check_yearcreate] OK'

