if object_id('[rpt_compensoprestocc_ritenuta]') is not null
	drop PROCEDURE [rpt_compensoprestocc_ritenuta]
go

CREATE    PROCEDURE [rpt_compensoprestocc_ritenuta]
	@ayear		int,
	@ycon		int, 
	@ncon		int
AS
BEGIN
CREATE TABLE #allpayed
( ayear int,
  idexp int,
  taxcode int,
  description varchar(50),
  taxkind int,
  deduction decimal(19,2),
  taxablegross decimal(19,2),
  taxablenet decimal(19,2),
  taxablenumerator decimal(19,6),
  taxabledenominator decimal(19,6),
  adminrate  decimal(19,6), 
  employrate decimal(19,6), 
  admintax decimal(19,2), 
  employtax decimal(19,2)
)
DECLARE @feegross decimal(19,2)
set     @feegross = (SELECT ISNULL(feegross,0) 
			    FROM casualcontract 
			   WHERE casualcontract.ycon = @ycon
	   		     AND casualcontract.ncon = @ncon)
	INSERT INTO #allpayed
	(ayear,idexp,taxcode,description, taxkind,
	 taxablegross, taxablenet, taxablenumerator,taxabledenominator, 
	adminrate, employrate, admintax, employtax)
	(SELECT  E.ymov,ETO.idexp, ETO.taxcode,T.description, T.taxkind, 
	 EY.amount, ETO.taxablenet, ISNULL(ETO.taxablenumerator,100), ISNULL(ETO.taxabledenominator,100),
	 ETO.adminrate, ETO.employrate, ETO.admintax, ETO.employtax
	 FROM expensetaxofficial ETO
	 JOIN expenselast EL
		ON EL.idexp = ETO.idexp
	 JOIN expense E
		ON E.idexp = EL.idexp
	 JOIN  expenseyear EY
		ON EY.idexp = EL.idexp
		--AND EY.ayear = @ayear
	 JOIN expenselink ELI
		ON  ELI.idchild = EL.idexp
		AND ELI.nlevel = 
			( SELECT expensephase 
		     	  FROM config WHERE ayear = @ycon) 
	 JOIN expensecasualcontract EC 
		ON EC.idexp  = ELI.idparent 
	 JOIN casualcontract C 
		ON C.ycon = EC.ycon
		AND C.ncon = EC.ncon 
	 JOIN dbo.tax T
		ON T.taxcode = ETO.taxcode
	 JOIN dbo.service S
		ON S.idser = EL.idser
	 WHERE 
	 S.module   = 'OCCASIONALE'
	 AND ETO.stop IS NULL 
	 AND C.ycon =@ycon AND C.ncon = @ncon
	)

IF EXISTS (SELECT * 
	   FROM pettycashoperationcasualcontract 
	   WHERE pettycashoperationcasualcontract.ycon = @ycon
	   AND pettycashoperationcasualcontract.ncon = @ncon )
BEGIN
	UPDATE #allpayed set taxablegross = @feegross
END
-- 
UPDATE #allpayed SET deduction = 
(SELECT 
		ISNULL(SUM (T.alldeduction),0)
		FROM
		(	SELECT (MAX(taxablegross)  - 
			SUM (ISNULL(taxablenet,0) /(taxablenumerator/taxabledenominator))) 
			AS alldeduction
			FROM #allpayed P WHERE #allpayed.ayear= P.ayear and #allpayed.taxcode = P.taxcode
			GROUP BY idexp,taxcode
		) as T)
--select * from #allpayed
IF (@ayear IS NULL)
BEGIN
	SELECT 
		ETO.ayear,
		taxcode,
		ETO.description,
		'taxkind' = CASE ETO.taxkind
			WHEN  1 THEN 'Fiscale'
			WHEN  2 THEN 'Assistenziale'
			WHEN  3 THEN 'Previdenziale'
			WHEN  4 THEN 'Assicurativa'
			WHEN  5 THEN 'Arretrati'
			WHEN  6 THEN 'Altro'
		ELSE ''
		END,
		SUM(taxablegross) as 'taxablegross',
		SUM(ISNULL(taxablenet,0) /(ISNULL(taxablenumerator,1)/ISNULL(taxabledenominator,1)))  as 'taxablenet',
		MAX(deduction) as 'deduzioni',
		adminrate*100 	  as 'aliquotaamministrazione' ,
		employrate*100    as 'aliquotadipendente',
		SUM(admintax) 	  as 'admintax',
		SUM(employtax) 	  as 'employtax'
	FROM  #allpayed ETO
	GROUP BY ETO.ayear, ETO.taxcode, ETO.description,ETO.taxkind, adminrate, employrate 
	ORDER BY ETO.ayear, ETO.taxcode
END
ELSE
BEGIN
	SELECT 
		ETO.ayear,
		taxcode,
		ETO.description,
		'taxkind' = CASE ETO.taxkind
			WHEN  1 THEN 'Fiscale'
			WHEN  2 THEN 'Assistenziale'
			WHEN  3 THEN 'Previdenziale'
			WHEN  4 THEN 'Assicurativa'
			WHEN  5 THEN 'Arretrati'
			WHEN  6 THEN 'Altro'
		ELSE ''
		END,
		SUM(taxablegross) as 'taxablegross',
		SUM(ISNULL(taxablenet,0) /(ISNULL(taxablenumerator,1)/ISNULL(taxabledenominator,1)))  as 'taxablenet',
		MAX(deduction) as 'deduzioni',
		adminrate*100 	  as 'aliquotaamministrazione' ,
		employrate*100    as 'aliquotadipendente',
		SUM(admintax) 	  as 'admintax',
		SUM(employtax) 	  as 'employtax'
	FROM  #allpayed ETO
	WHERE ETO.ayear = @ayear 
	GROUP BY ETO.ayear, ETO.taxcode, ETO.description,ETO.taxkind, adminrate, employrate 
	ORDER BY ETO.ayear, ETO.taxcode
END
END

GO

print '[rpt_compensoprestocc_ritenuta] OK'

GO
if object_id('[rpt_compensoprestprof_imponibili]') is not null
	drop PROCEDURE [rpt_compensoprestprof_imponibili]
go


CREATE    PROCEDURE [rpt_compensoprestprof_imponibili]
	@ycon int,
	@ncon int
AS
BEGIN
	SELECT
		profservice.ycon,
		profservice.ncon,
		profservice.feegross as 'feegross',
		profservice.pensioncontributionrate as 'pensioncontributionrate',
		profservice.socialsecurityrate as 'socialsecurityrate',
		profservice.ivarate as 'ivarate',
		profservice.ivaamount as 'ivaamount',
		profservicetax.taxablenet as 'taxablegross',
		profservicetax.employrate,
		profservicetax.employtax,
		profservice.totalcost,
		-- Tipo IVA idivakind
		ivakind.description,
		-- Spese imponibili previdenzialmente
		(SELECT sum(amount)			
		FROM  profservicerefund  
		JOIN  profrefund 
		      ON profservicerefund.idlinkedrefund = profrefund.idlinkedrefund
		WHERE ycon = @ycon 
		AND   ncon = @ncon
		AND  ISNULL(flagsecuritydeduction,'N') = 'N') as 'nosecuritydedrefund',	
		-- Spese imponibili ai fini IVA
		(SELECT sum(amount)			
		FROM  profservicerefund  
		JOIN  profrefund 
		      ON profservicerefund.idlinkedrefund = profrefund.idlinkedrefund
		WHERE ycon = @ycon 
		AND   ncon = @ncon
		AND  ISNULL(flagivadeduction,'N')= 'N') as 'noivadedrefund',
		-- Spese imponibili fiscalmente
		(SELECT sum(amount)			
		FROM  profservicerefund  
		JOIN  profrefund 
		      ON profservicerefund.idlinkedrefund = profrefund.idlinkedrefund
		WHERE ycon = @ycon 
		AND   ncon = @ncon
		AND  ISNULL(flagfiscaldeduction,'N') = 'N') as 'nofiscaldedrefund',
		-- Spese non imponibili
		(SELECT sum(amount)			
		FROM profservicerefund  
		JOIN  profrefund 
		      ON profservicerefund.idlinkedrefund = profrefund.idlinkedrefund
		WHERE 	ycon = @ycon 
		AND ncon = @ncon
		AND  ISNULL(flagfiscaldeduction,'N')= 'S'
		AND  ISNULL(flagivadeduction,'N')= 'S'
		AND  ISNULL(flagsecuritydeduction,'N')= 'S'
		) as 'totdedrefund',
		(SELECT sum(amount)			
		FROM profservicerefund  
		WHERE 	ycon = @ycon 
		AND ncon = @ncon) as 'totalrefund'
	FROM  	profservice
		LEFT OUTER JOIN  profservicetax 
		ON    profservice.ycon = profservicetax.ycon AND
		      profservice.ncon = profservicetax.ncon 
		LEFT OUTER JOIN  ivakind 
		ON    profservice.idivakind = ivakind.idivakind 
	WHERE 
		profservice.ycon = @ycon AND  profservice.ncon = @ncon
END 


GO

print '[rpt_compensoprestprof_imponibili] OK'

