if object_id('[trigger_i_budgetprevision]') is not null
	drop TRIGGER [trigger_i_budgetprevision]
go

CREATE             TRIGGER [trigger_i_budgetprevision] ON [budgetprevision] FOR INSERT
AS BEGIN
	DECLARE @ayear int
	DECLARE	@idsor int
	DECLARE	@idsorkind int
	DECLARE @idupb varchar(36)
	DECLARE	@prevision decimal(19, 2)
	DECLARE	@previousprevision decimal(19,2)
	DECLARE	@cu varchar(64)
	DECLARE	@ct datetime
	DECLARE	@lu varchar(64)
	DECLARE	@lt datetime
	SELECT	@idsor=idsor, @ayear=ayear, @idupb=idupb,
		@prevision=prevision, @previousprevision=previousprevision, 
		@cu=cu, @ct=ct, @lu=lu, @lt=lt
	FROM inserted
	SELECT	@idsorkind=idsorkind
	FROM sorting WHERE 	idsor=@idsor
	
	DECLARE @nlevel tinyint
	SELECT @nlevel = nlevel FROM sorting WHERE idsor = @idsor
	DECLARE @minoplevel tinyint
	SELECT  @minoplevel = MIN(nlevel) FROM sortinglevel WHERE (flag & 2) <> 0 AND idsorkind=@idsorkind
-- Inserimento righe in budgetprevision a zero sugli UPB padre di quello che sto inserendo nel caso in cui
-- tale voce non esiste
	DECLARE @curridupb varchar(36)
	SET @curridupb = SUBSTRING(@idupb,1,LEN(@idupb)-4)
	IF (LEN(@curridupb) >= 4)
	BEGIN
		IF NOT EXISTS(SELECT * FROM budgetprevision WHERE idupb = @curridupb AND idsor = @idsor)
		BEGIN
			INSERT INTO budgetprevision
			(
				idsor, idupb,
				prevision, 
				previousprevision,
				prevision2, prevision3, prevision4, prevision5,
				ct, cu, lt, lu,
				ayear
			)
			VALUES
			(
				@idsor, @curridupb,
				0,  
				0,
				0, 0, 0, 0,
				GETDATE(), 'TRIGGER', GETDATE(), '''TRIGGER''',
				@ayear
			)
			SET @curridupb = SUBSTRING(@curridupb,1,LEN(@curridupb)-4)
		END
	END
END

