		AND assetamortization.idpiece = asset.idpiece
	JOIN assetunload
		ON assetunload.idassetunload = asset.idassetunload
	WHERE   asset.idasset = @idasset AND asset.idpiece = 1
		AND ((ISNULL(assetamortization.amortizationquota,0)>0) OR 
