INSERT INTO #situation
VALUES ('C A S S A',NULL,'N')
INSERT INTO #situation	
VALUES ('Previsione iniziale di cassa', @secondaryprev, '')
INSERT INTO #situation	
VALUES ('Variazioni di bilancio e Storni di previsione', @var_secondaryprev, '')
INSERT INTO #situation	
VALUES ('Previsione attuale di cassa', ISNULL(@current_secprevision, 0), 'S')
IF (@finpart = 'S')
	AND (EXISTS	
		(SELECT	* 
		FROM proceedspart
		WHERE yproceedspart = @ayear
			AND adate <= @date) OR
			EXISTS (SELECT * FROM finvar
		WHERE yvar = @ayear
			AND flagproceeds = 'S'
			AND adate <= @date
			AND variationkind <> 5 
			AND idfinvarstatus = 5))
			AND @assured <> 'S'
