CREATE    PROCEDURE rebuild_budgetprevision
(
	@ayear int = null
)
AS BEGIN
-- rebuild_budgetprevision 2013
CREATE TABLE #budgetprevision
(
	ayear int,
	idsor int,
	idupb varchar(36)
)
IF (SELECT COUNT(*) FROM budgetprevision b1
WHERE LEN(idupb) > 4
	AND NOT EXISTS
		(SELECT * FROM budgetprevision b2
		WHERE b2.idsor = b1.idsor
			AND b2.idupb = SUBSTRING(b1.idupb,1,LEN(b1.idupb) - 4)
	AND ayear = @ayear)
) > 0
BEGIN
	INSERT INTO budgetprevision (ayear, idsor, idupb, prevision, previousprevision,
				prevision2, prevision3, prevision4, prevision5)
	SELECT ayear, idsor, SUBSTRING(idupb,1,LEN(idupb)-4),
	0, 0,0, 0, 0, 0
	FROM budgetprevision b1
	WHERE LEN(idupb) > 4
		AND NOT EXISTS
			(SELECT * FROM budgetprevision b2
			WHERE b2.idsor = b1.idsor
				AND b2.idupb = SUBSTRING(b1.idupb,1,LEN(b1.idupb) - 4)
	AND ayear = @ayear)
	INSERT INTO budgetprevision (ayear, idsor, idupb, prevision, previousprevision,
				prevision2, prevision3, prevision4, prevision5)
	SELECT ayear, idsor, SUBSTRING(idupb,1,LEN(idupb)-4),
	0, 0,0, 0, 0, 0
	FROM budgetprevision b1
	WHERE LEN(idupb) > 4
		AND NOT EXISTS
			(SELECT * FROM budgetprevision b2
			WHERE b2.idsor = b1.idsor
				AND b2.idupb = SUBSTRING(b1.idupb,1,LEN(b1.idupb) - 4)
	AND ayear = @ayear)
 
END
END

