if object_id('closeyear_casualcontract') is not null
	drop PROCEDURE closeyear_casualcontract
go

CREATE    PROCEDURE closeyear_casualcontract
(
	@ayear int
)
AS BEGIN
DECLARE @maxexpensephase int
SELECT @maxexpensephase = MAX(nphase) FROM expensephase
DECLARE @nextayear int
SET @nextayear = @ayear + 1
DECLARE @ycon int
DECLARE @ncon int
DECLARE @feegross decimal(19,2)
DECLARE @cascon_crs cursor
SET @cascon_crs = CURSOR FOR
	SELECT ycon, ncon, feegross FROM casualcontract WHERE ycon <= @ayear 
		AND NOT EXISTS
			(SELECT * FROM casualcontractyear
			WHERE casualcontract.ycon = casualcontractyear.ycon
				AND casualcontract.ncon = casualcontractyear.ncon
				AND ayear = @nextayear)
OPEN @cascon_crs
FETCH NEXT FROM @cascon_crs INTO @ycon, @ncon, @feegross
WHILE (@@FETCH_STATUS = 0)
BEGIN
	DECLARE @idexp varchar(40)
	DECLARE @curramount decimal(19,2)
	DECLARE @pettycashamount decimal(19,2)
	DECLARE @amount decimal(19,2)
	DECLARE @exp_crs cursor
	SET @exp_crs = CURSOR FOR
		SELECT expense.idexp, ISNULL(expenseyear_starting.amount, 0)
		FROM expensecasualcontract
		JOIN expenselink
			ON expenselink.idparent = expensecasualcontract.idexp
		JOIN expense
			ON expense.idexp = expenselink.idchild 
		LEFT OUTER JOIN expensetotal expensetotal_firstyear(NOLOCK)
  			ON expensetotal_firstyear.idexp = expense.idexp
  			AND ((expensetotal_firstyear.flag & 2) <> 0 )
		LEFT OUTER JOIN expenseyear expenseyear_starting(NOLOCK) 
			ON expenseyear_starting.idexp = expensetotal_firstyear.idexp
  			AND expenseyear_starting.ayear = expensetotal_firstyear.ayear
		WHERE ycon = @ycon
			AND ncon = @ncon
			AND expense.nphase = @maxexpensephase
	OPEN @exp_crs
	FETCH NEXT FROM @exp_crs into @idexp, @amount
	SET @curramount = 0
	WHILE (@@FETCH_STATUS = 0)
	BEGIN
		SELECT @curramount = ISNULL(@curramount,0) + @amount + ISNULL(SUM(amount), 0)
		FROM expensevar
		WHERE idexp=@idexp
			AND ISNULL(autokind,0)<> 4 --RITENUTA
		FETCH NEXT FROM @exp_crs INTO @idexp, @amount
	END
        
        SELECT 	@pettycashamount = pettycashoperation.amount
                FROM pettycashoperationcasualcontract
                JOIN pettycashoperation
                	ON pettycashoperation.idpettycash = pettycashoperationcasualcontract.idpettycash
                	AND pettycashoperation.yoperation = pettycashoperationcasualcontract.yoperation
                	AND pettycashoperation.noperation = pettycashoperationcasualcontract.noperation
                WHERE 	pettycashoperationcasualcontract.ycon = @ycon AND pettycashoperationcasualcontract.ncon = @ncon
        
        DECLARE @residual decimal(19,2)
	SET @residual = @feegross - @curramount - isnull(@pettycashamount,0)
	IF (@residual>0)
	BEGIN
		DECLARE @activitycode varchar(20)
		DECLARE @idotherinsurance varchar(20)
		DECLARE @idemenscontractkind varchar(2)
		SELECT 
			@activitycode = casualcontractyear.activitycode, 
			@idotherinsurance = casualcontractyear.idotherinsurance, 
			@idemenscontractkind = casualcontractyear.idemenscontractkind
			FROM casualcontractyear 
			WHERE casualcontractyear.ayear = @ayear 
				AND casualcontractyear.ycon = @ycon
				AND casualcontractyear.ncon = @ncon
		INSERT INTO casualcontractyear
		(ayear, ycon, ncon, activitycode, idotherinsurance, idemenscontractkind,
		 taxableotheragency,flaghigherrate,higherrate)
		VALUES (@nextayear, @ycon, @ncon, @activitycode, @idotherinsurance, @idemenscontractkind,
			null,null,null)
	END
	FETCH NEXT FROM @cascon_crs into @ycon, @ncon, @feegross
END
END




GO

print 'closeyear_casualcontract OK'

GO
if object_id('[getassetvalue]') is not null
	drop PROCEDURE [getassetvalue]
go

CREATE               PROCEDURE [getassetvalue]
(
 @idasset int,
 @idpiece int,
 @totale  decimal (19,2) OUTPUT
)
AS
BEGIN
----------------------------------------------------------------------------------
-------------------- Valore iniziale se cespite ----------------------------------
----------------------------------------------------------------------------------	
DECLARE @initialamount decimal(19,2) 
IF      (@idpiece = 1) --Cespite principale
	BEGIN
	SET @initialamount = ISNULL((
	       SELECT 
		CASE	
			----------------------------------------------------------------------------------
			----------------- Considera i buoni di carico precedenti al 2005 -----------------
			----------------------------------------------------------------------------------
			WHEN 
		 	((inventorykind.flag & 1 <> 0) OR ISNULL(assetload.yassetload,2006)<2005 OR(
			assetacquire.idassetload IS NULL AND (assetacquire.flag & 2 <> 0)))	
			THEN
			CONVERT(decimal(19,2),ROUND(
				ROUND(ISNULL(assetacquire.taxable, 0)
				* (1 - CONVERT(decimal(19,6),ISNULL(assetacquire.discount, 0))),2)
				+ ROUND(ISNULL(assetacquire.tax,0) / assetacquire.number,2)
				- ROUND(ISNULL(assetacquire.abatable,0) / assetacquire.number,2) 
			,2))
			----------------------------------------------------------------------------------
			------- Considera i buoni di carico del 2005 e i successivi  SENZA SCONTO --------
			----------------------------------------------------------------------------------			
			WHEN NOT ((inventorykind.flag & 1 <> 0) OR ISNULL(assetload.yassetload,2006)<2005 OR  
			(assetacquire.idassetload IS NULL AND (assetacquire.flag & 2 <> 0)) )	
			THEN
			CONVERT(decimal(19,2),ROUND(
			ROUND(ISNULL(assetacquire.taxable, 0),2)
			+ ROUND(ISNULL(assetacquire.tax,0) / assetacquire.number,2)
			- ROUND(ISNULL(assetacquire.abatable,0) / assetacquire.number,2) 
			,2))
			ELSE 0
			END
		 FROM asset 
		 JOIN assetacquire 
		   ON assetacquire.nassetacquire = asset.nassetacquire
		 LEFT OUTER JOIN assetload
		   ON assetload.idassetload = assetacquire.idassetload
		 JOIN inventory 
		   ON inventory.idinventory = assetacquire.idinventory
		 JOIN inventorykind
		   ON inventory.idinventorykind= inventorykind.idinventorykind  
		WHERE asset.idasset = @idasset
		  AND asset.idpiece = @idpiece),0.0)
	END
----------------------------------------------------------------------------------
---------------------- Valore iniziale se accessorio -----------------------------
----------------------------------------------------------------------------------			
IF   (@idpiece > 1)
	BEGIN
	SET @initialamount = ISNULL((SELECT  CONVERT(decimal(19,2),ROUND(
			        ROUND(ISNULL(assetacquire.taxable, 0)
			        * (1 - CONVERT(decimal(19,6),ISNULL(assetacquire.discount, 0))),2)
				+ ROUND(ISNULL(assetacquire.tax,0) / assetacquire.number,2)
				- ROUND(ISNULL(assetacquire.abatable,0) / assetacquire.number,2) 
				,2))
			 FROM asset 
			 JOIN assetacquire 
			   ON assetacquire.nassetacquire = asset.nassetacquire
			 JOIN inventory 
			   ON inventory.idinventory = assetacquire.idinventory
			 JOIN inventorykind
			   ON inventory.idinventorykind= inventorykind.idinventorykind  
			WHERE asset.idasset = @idasset
			  AND asset.idpiece = @idpiece
			  AND ((assetacquire.flag & 1 <> 1) OR assetacquire.idassetload IS NOT NULL)
			      
			),0.0)
	END

----------------------------------------------------------------------------------
--------- Considera le svalutazioni/rivalutazioni ufficiali-----------------------
----------------------------------------------------------------------------------	
DECLARE  @totamortization  decimal(19,2) 
	 SET @totamortization = ISNULL(
				(SELECT SUM(ROUND(
					ISNULL(assetamortization.assetvalue, 0.0) *
					ISNULL(assetamortization.amortizationquota,0.0)
					,2))
				FROM  assetamortization
				JOIN  inventoryamortization
				ON    assetamortization.idinventoryamortization = 
				      inventoryamortization.idinventoryamortization
				WHERE assetamortization.idasset = @idasset
				AND   assetamortization.idpiece = @idpiece
				AND ((ISNULL(assetamortization.amortizationquota,0)>0) OR 
			            (
				     (ISNULL(assetamortization.amortizationquota,0)<0) AND 
			             ((assetamortization.flag & 1 <> 1) OR 
				      (assetamortization.idassetunload IS NOT NULL))
				     )
				    )
				AND   (inventoryamortization.flag & 2 <> 0))
			,0)
------------------------------------------------------------------------------------------
-- Sottrae gli accessori scaricati caricati come posseduti e già inclusi nel cespite -----
------------------------------------------------------------------------------------------	
DECLARE @totpieceunloaded decimal(19,2) 
IF      (@idpiece = 1)
	BEGIN
	SET @totpieceunloaded = ISNULL(
			(SELECT SUM(ROUND(ISNULL(B.taxable, 0)
			* (1 - CONVERT(decimal(19,6),ISNULL(B.discount, 0))),2)
			+ ROUND(ISNULL(B.tax,0) / B.number,2)
			- ROUND(ISNULL(B.abatable,0) / B.number,2))
			 from assetacquire B
				join asset A
				on B.nassetacquire = A.nassetacquire
				where A.idasset = @idasset
				and   A.idpiece >1
				and   A.idassetunload IS NOT NULL
				and  ((B.flag & 1 <> 1) AND (B.flag & 2 <> 0)))
			,0)
	END
ELSE  SET @totpieceunloaded = 0
--print @initialamount
--print @totamortization
--print @totpieceunloaded
SET @totale = @initialamount + @totamortization - @totpieceunloaded
END


GO

print '[getassetvalue] OK'

