CREATE    PROCEDURE [trg_del_curr_floatfund]
(
	@ayear int,
	@movkind char(1),
	@idmov int,
	@amount decimal(19,2)
)
AS BEGIN
IF ISNULL( (SELECT locked from surplus where  ayear = @ayear),'N') = 'S' return

IF (@movkind = 'I')
BEGIN
	UPDATE currentcashtotal SET currentfloatfund = ISNULL(currentfloatfund,0) - @amount
	WHERE ayear = @ayear
END
IF (@movkind = 'E')
BEGIN
	IF (ISNULL(@amount,0) <> 0)
	BEGIN
		UPDATE currentcashtotal SET currentfloatfund = ISNULL(currentfloatfund ,0) - @amount
		WHERE ayear = @ayear
	END
END
END


