CREATE                                                      procedure [allineaASinistra](@stringa varchar(150), @lunghezza int, @result varchar(150) output)
AS
BEGIN
	declare @lenstr int
	set @lenStr=len(@stringa)
	if (@lenStr>@lunghezza) 
	begin
		set @result = substring(@stringa,1,@lunghezza)
	end else begin
		set @result = @stringa+space(@lunghezza-@lenStr)
	end
END


