if object_id('[exp_unified_sitpatrim_totale]') is not null
	drop PROCEDURE [exp_unified_sitpatrim_totale]
go

CREATE       PROCEDURE [exp_unified_sitpatrim_totale]
(
	@Year int,
	@azione char(1),	--D dettagli  T totale  A distingui amm da tot dip  Q differenze da anno successivo 
	@cat char(1)
)
AS BEGIN
--exp_unified_sitpatrim_totale 2010,'Q',null
--rpt_sitpatrim_totale 2008, '2008-12-31', 'S', 'S'
CREATE TABLE #unified (
	anno int,
	iddbdepartment  varchar(50),
    departmentname  varchar(150),
	idsor int,
	codesor varchar(50),
	nlevel tinyint,
	description varchar(150),
	initial_amount decimal(19,2),
	idmot int,
	motive varchar(50),
	var_aum decimal(19,2),
	var_dim decimal(19,2),
	amortization decimal(19,2),
	initial_succ decimal(19,2),
	date datetime	
)


declare @date datetime
set @date =DateAdd(yy, @Year-1900,  
       DateAdd(month,  12 - 1, 31 - 1))
declare @year2 int
set @year2= @year+1

declare @date2 datetime
set @date2 =DateAdd(yy, @year2-1900,  
       DateAdd(month,  12 - 1, 31 - 1))
DECLARE @iddbdepartment varchar(50)
DECLARE crsdepartment  cursor LOCAL STATIC FOR 
SELECT iddbdepartment FROM dbdepartment 
WHERE (start is null or start <= @year ) AND ( stop is null or stop >= @year)
FOR READ ONLY
OPEN crsdepartment
FETCH NEXT FROM crsdepartment INTO @iddbdepartment
WHILE @@fetch_status=0 begin
	DECLARE @dip_nomesp varchar(300)
        SET @dip_nomesp = '['+@iddbdepartment+']'+ '.rpt_sitpatrim_totale'
PRINT @iddbdepartment
		INSERT INTO #unified (
                   idsor,
				   codesor,
				   nlevel,
				   idmot,
				   motive,
				   description,
				   initial_amount,
				   var_aum,
				   var_dim,
				   amortization,
				   date
		)
		EXEC @dip_nomesp @year, @date, 'S', 'N'
		update #unified set anno=@year where anno is null
		if (@azione='Q') 
		BEGIN
		INSERT INTO #unified (
                   idsor,
				   codesor,
				   nlevel,
				   idmot,
				   motive,
				   description,
				   initial_amount,
				   var_aum,
				   var_dim,
				   amortization,
				   date
		)
		EXEC @dip_nomesp @year2, @date2, 'S', 'N'
		update #unified set initial_succ = 
			(select U.initial_amount from #unified U where U.codesor=#unified.codesor 
							and U.iddbdepartment is null 
							and U.anno is null)
		where iddbdepartment is null and anno=@year
		delete from #unified where anno is null
		END
		UPDATE #unified set iddbdepartment = @iddbdepartment,  departmentname  = dbdepartment.description 
		FROM dbdepartment 
		WHERE dbdepartment.iddbdepartment=@iddbdepartment
		AND   #unified.iddbdepartment is null
		
	FETCH NEXT FROM crsdepartment INTO @iddbdepartment
end
DEALLOCATE crsdepartment
--SELECT * FROM #unified
if  (@azione='T') update #unified set iddbdepartment=null, departmentname= null
if  (@azione='A') update #unified set iddbdepartment='dip', departmentname= 'dipartimenti' where iddbdepartment<>'amministrazione'
if (@cat is not null) delete #unified where codesor<> @cat
if (@azione='D' or @azione='A' )
SELECT
		iddbdepartment  as 'codice dip',
		departmentname  as 'dip',
		#unified.codesor AS 'codice inv.',
		#unified.description as 'descrizione',
		ISNULL(SUM(#unified.initial_amount),0) AS 'Sit.iniziale',
		ISNULL(SUM(#unified.var_aum),0) AS 'aumenti',
		ISNULL(SUM(#unified.var_dim),0) AS 'diminuzioni',
		ISNULL(SUM(#unified.amortization),0) as 'sval.',
		ISNULL(SUM(#unified.initial_amount),0)+ISNULL(SUM(#unified.var_aum),0)
					-ISNULL(SUM(#unified.var_dim),0)-ISNULL(SUM(#unified.amortization),0) as 'finale'		
	FROM #unified	 where codesor is not null 
		group by iddbdepartment,departmentname,#unified.codesor,#unified.description				
	ORDER BY #unified.codesor,iddbdepartment
if (@azione='T' )
SELECT
		#unified.codesor AS 'codice inv.',
		#unified.description as 'descrizione',
		ISNULL(SUM(#unified.initial_amount),0) AS 'Sit.iniziale',
		ISNULL(SUM(#unified.var_aum),0) AS 'aumenti',
		ISNULL(SUM(#unified.var_dim),0) AS 'diminuzioni',
		ISNULL(SUM(#unified.amortization),0) as 'sval.',
		ISNULL(SUM(#unified.initial_amount),0)+ISNULL(SUM(#unified.var_aum),0)
					-ISNULL(SUM(#unified.var_dim),0)-ISNULL(SUM(#unified.amortization),0) as 'finale'
	FROM #unified	 where codesor is not null 
		group by #unified.codesor,#unified.description				
	ORDER BY #unified.codesor
if (@azione='Q')
SELECT
		iddbdepartment  as 'codice dip',
		departmentname  as 'dip',
		#unified.codesor AS 'codice inv.',
		#unified.description as 'descrizione',
		ISNULL(SUM(#unified.initial_amount),0) AS 'Sit.iniziale',
		ISNULL(SUM(#unified.var_aum),0) AS 'aumenti',
		ISNULL(SUM(#unified.var_dim),0) AS 'diminuzioni',
		ISNULL(SUM(#unified.amortization),0) as 'sval.',
		ISNULL(SUM(#unified.initial_amount),0)+ISNULL(SUM(#unified.var_aum),0)
					-ISNULL(SUM(#unified.var_dim),0)-ISNULL(SUM(#unified.amortization),0) as 'finale',
		ISNULL(SUM(#unified.initial_succ),0) as 'iniziale anno succ',
		ISNULL(SUM(#unified.initial_succ),0)-
				(ISNULL(SUM(#unified.initial_amount),0)+ISNULL(SUM(#unified.var_aum),0)
					-ISNULL(SUM(#unified.var_dim),0)-ISNULL(SUM(#unified.amortization),0)) as 'differenze'		
	FROM #unified	 where codesor is not null 
		group by iddbdepartment,departmentname,#unified.codesor,#unified.description				
	having
				ISNULL(SUM(#unified.initial_succ),0)-
				(ISNULL(SUM(#unified.initial_amount),0)+ISNULL(SUM(#unified.var_aum),0)
					-ISNULL(SUM(#unified.var_dim),0)-ISNULL(SUM(#unified.amortization),0)) <>0
	ORDER BY iddbdepartment,#unified.codesor


DROP TABLE #unified
END

GO

print '[exp_unified_sitpatrim_totale] OK'

