if object_id('[closeyear_incomearrearscopy]') is not null
	drop PROCEDURE [closeyear_incomearrearscopy]
go


CREATE      PROCEDURE [closeyear_incomearrearscopy]
(
	@ayear int
)
AS BEGIN
	
DECLARE @idinc 		int
DECLARE @idfin 		int
DECLARE @idupb 		varchar(36)
DECLARE @nlevel 	tinyint
DECLARE @nphase 	tinyint
DECLARE @curramount 	decimal(19,2)
DECLARE @available 	decimal(19,2)
DECLARE @proceeded 	decimal(19,2)
DECLARE @newidfin 	int	
DECLARE @nextayear 	int
SET 	@nextayear = @ayear + 1
DECLARE @nextayearstr 	varchar(4)
SET 	@nextayearstr = CONVERT(varchar(4),@nextayear)
DECLARE @maxincomephase int
SELECT  @maxincomephase = MAX(nphase) FROM incomephase
DECLARE inc_crs INSENSITIVE CURSOR FOR
SELECT  income.idinc, curramount, available,nphase
FROM 	incometotal
JOIN    income
	ON income.idinc= incometotal.idinc
WHERE   ayear = @ayear
	AND income.nphase < @maxincomephase
ORDER BY income.idinc
FOR READ ONLY
	
OPEN inc_crs
FETCH NEXT FROM inc_crs 
INTO @idinc, @curramount, @available,  @nlevel
	
WHILE (@@FETCH_STATUS = 0)
BEGIN
	IF @nlevel = @maxincomephase - 1
	BEGIN
		SET @proceeded = @curramount - @available
	END
	ELSE
	BEGIN
		SELECT @proceeded = ISNULL(SUM(curramount), 0)
		FROM   incometotal
		JOIN   incomelast
		ON     incomelast.idinc = incometotal.idinc
		JOIN   incomelink
		ON     nlevel = @nlevel and idparent = @idinc
		AND    incomelink.idchild = incomelast.idinc
		WHERE  incometotal.ayear = @ayear
		       
	END
	IF (@curramount - @proceeded) > 0
	BEGIN
		IF NOT EXISTS(SELECT * FROM incomeyear WHERE idinc = @idinc AND ayear = @nextayear)
		BEGIN
			SELECT @idfin = idfin, @idupb = idupb FROM incomeyear WHERE idinc = @idinc AND ayear = @ayear
	
			SET  @newidfin = NULL
			IF @idfin IS NOT NULL
			BEGIN
				SELECT @newidfin = newidfin FROM finlookup WHERE oldidfin = @idfin
				
			END		
			
			INSERT INTO incomeyear	(idinc, ayear, idfin, idupb,-- nphase, 
						amount, cu, ct, lu,  lt)
			VALUES(
				@idinc, @nextayear, @newidfin, @idupb, --@nlevel, 
				@curramount - @proceeded,
				'ArrearsCopy', GETDATE(), 'ArrearsCopy', GETDATE()
			)
	
		END
	END
	FETCH NEXT FROM inc_crs 
	INTO @idinc, @curramount, @available, @nlevel
END
CLOSE inc_crs
DEALLOCATE inc_crs
	
UPDATE incometotal
   SET partitioned = curramount
	WHERE (flag&1)<>0 and partitioned=0 
		and ayear= @nextayear
CREATE TABLE #info (msg varchar(800))
INSERT INTO #info VALUES('I residui attivi sono stati trasferiti all'' esercizio ' + @nextayearstr)
-- azzero i bit da 0 a 3 e imposto il valore 4 nell'esercizio corrente. 
UPDATE accountingyear SET flag = flag&0xF0 WHERE ayear = @ayear
UPDATE accountingyear SET flag = flag|0x04 WHERE ayear = @ayear
	
	
SELECT * FROM #info
END


GO

print '[closeyear_incomearrearscopy] OK'

