if object_id('[rpt_contabprestprof]') is not null
	drop PROCEDURE [rpt_contabprestprof]
go

CREATE                                                    PROCEDURE [rpt_contabprestprof]
	@ayear smallint,
	@ycon  smallint,  
	@ncon  int
AS
BEGIN
DECLARE @phasebilancio		tinyint
DECLARE @phasecontrattocont	tinyint
CREATE TABLE #impcontratto
(
	eserccontratto		smallint,
	numcontratto		integer,
	fasespesa		varchar(35),
	esercmovimento		smallint,
	nummovimento		integer,
	datacontabile		smalldatetime,
	descrizione		varchar(150),	
	codicebilancio		varchar(30),
	codicefondo		varchar(10),
	codiceripartizione	varchar(10),
	codicecentrospesa	varchar(30),
	importo			decimal(19,2)
)
SELECT @phasebilancio = expensefinphase 
	FROM uniconfig
SELECT @phasecontrattocont = expensephase FROM config WHERE ayear = @ayear
			
	
		INSERT INTO #impcontratto
		(
			eserccontratto,
			numcontratto,
			fasespesa,
			esercmovimento,
			nummovimento,
			datacontabile,
			descrizione,
			codicebilancio,
			codiceupb,
			importo
		)
		SELECT
		@ycon,
		@ncon,
		expensephase.description,
		expense.ymov,
		expense.nmov,
		expense.adate,
		expense.description,
		fin.codefin,
		upb.codeupb,
		expenseyear.amount
		FROM expenseprofservice
		JOIN expense
		ON expense.idexp = expenseprofservice.idexp
		AND expense.nphase = @phasecontrattocont 
		JOIN expenseyear
		ON expenseyear.idexp = expenseprofservice.idexp
		AND expenseyear.ayear = @ayear
		JOIN expensephase
		ON expensephase.nphase = expense.nphase
		LEFT OUTER JOIN fin
		ON fin.idfin = expenseyear.idfin
		LEFT OUTER JOIN upb
		ON upb.idupb = expenseyear.idupb
		WHERE expenseprofservice.ycon = @ycon
		AND expenseprofservice.ncon = @ncon
		SELECT * 
      FROM #impcontratto
      ORDER BY fasespesa ASC,
      esercmovimento ASC,
      nummovimento ASC
	END




GO

print '[rpt_contabprestprof] OK'

GO
if object_id('[exp_dettagli_contrattopassivo_non_invent]') is not null
	drop PROCEDURE [exp_dettagli_contrattopassivo_non_invent]
go


CREATE           PROCEDURE [exp_dettagli_contrattopassivo_non_invent]
(
	@ayear int,
	@idmankind varchar(10)
)
AS BEGIN
DECLARE @expenselevel INT
DECLARE @maxlevel INT
SELECT @expenselevel = expenseregphase FROM uniconfig
SELECT @maxlevel = MAX(nphase) FROM expensephase
DECLARE @yman int
DECLARE @nman int
DECLARE @npackage decimal(19,2)
DECLARE @idgroup int
DECLARE @idexp_taxable int
DECLARE @ypay int
DECLARE @npay int

CREATE TABLE #mandate_detail 
( yman int, nman int, adate datetime, manager varchar (150), registry varchar(100), detaildescription varchar(150), npackage decimal(19,2), imponibile decimal(19,2), 
  taxrate decimal(19,2), discount varchar(10), total decimal(19,2) , ypay int, npay varchar(100), idmankind varchar(50), idgroup int, idexp_taxable int )

IF (SELECT multireg from mandatekind WHERE idmankind = @idmankind) = 'N'
BEGIN
	INSERT INTO #mandate_detail (yman, nman, adate, manager, registry, detaildescription, npackage, imponibile, 
					taxrate, discount, total,idmankind , idgroup,idexp_taxable)
	SELECT  MD.yman, MD.nman, M.adate, MG.title, RG.title, MD.detaildescription, MD.npackage, 
		SUM(MD.taxable),isnull(MD.taxrate * 100 , 0),convert(varchar(10),isnull( MD.discount * 100, 0))+ '%', 
		sum(MD.taxable  * MD.npackage + MD.tax - (MD.taxable * MD.npackage * isnull(MD.discount,0))),
		MD.idmankind, MD.idgroup, MD.idexp_taxable
	FROM mandatedetail MD
	JOIN mandate M
		ON MD.idmankind= M.idmankind 
		AND MD.nman = M.nman
		AND MD.yman = M.yman
	LEFT OUTER JOIN manager MG
		ON M.idman = MG.idman
	JOIN  registry RG
		ON M.idreg = RG.idreg
	WHERE MD.assetkind !='A'
	AND M.yman = @ayear and M.idmankind = @idmankind
	GROUP BY MD.idmankind, MD.yman, MD.nman, MD.assetkind, MD.idgroup, MD.idreg, MD.npackage, M.adate, MG.title, 
		RG.title, MD.detaildescription, MD.taxrate, MD.discount,MD.idexp_taxable
END
ELSE 
BEGIN
	INSERT INTO #mandate_detail (yman, nman, adate, manager, registry, detaildescription, npackage, imponibile, 
					taxrate, discount, total,idmankind , idgroup,idexp_taxable)
	SELECT  MD.yman, MD.nman, M.adate, MG.title, RG.title, MD.detaildescription, MD.npackage, SUM(MD.taxable),
		isnull(MD.taxrate * 100 , 0), convert(varchar(10),isnull( MD.discount * 100, 0))+ '%', 
		sum(MD.taxable  * MD.npackage + MD.tax - (MD.taxable * MD.npackage * isnull(MD.discount,0))),
		MD.idmankind, MD.idgroup, MD.idexp_taxable
	FROM mandatedetail MD
	JOIN mandate M
		ON MD.idmankind= M.idmankind 
		AND MD.nman = M.nman
		AND MD.yman = M.yman
	LEFT OUTER JOIN manager MG
		ON M.idman = MG.idman
	JOIN  registry RG
		ON MD.idreg = RG.idreg  
	WHERE MD.assetkind !='A' 
	AND M.yman = @ayear AND M.idmankind = @idmankind
	GROUP BY MD.idmankind, MD.yman, MD.nman, MD.assetkind, MD.idgroup, MD.idreg, MD.npackage, M.adate, MG.title, RG.title, MD.detaildescription, MD.taxrate, 
		MD.discount,idexp_taxable
END
DECLARE cursore CURSOR FORWARD_ONLY for 
SELECT #mandate_detail.yman,#mandate_detail.nman, #mandate_detail.npackage, #mandate_detail.idgroup,#mandate_detail.idexp_taxable, P1.ypay, P1.npay
FROM #mandate_detail 
	JOIN mandatedetail MD 
		ON #mandate_detail.idmankind = MD.idmankind
		AND  #mandate_detail.yman = MD.yman
		AND #mandate_detail.nman = MD.nman
		AND #mandate_detail.idgroup = MD.idgroup
		AND #mandate_detail.idexp_taxable = MD.idexp_taxable
	LEFT OUTER JOIN expenselink ELK1
		ON ELK1.idparent = MD.idexp_taxable
	LEFT OUTER JOIN expenselink ELK2
		ON ELK2.idparent = ELK1.idchild
		AND ELK2.idchild = ELK2.idchild
		AND ELK2.nlevel=@maxlevel
	LEFT OUTER JOIN expenselast EL1
		ON ELK2.idparent = EL1.idexp
	LEFT OUTER JOIN payment P1
		ON EL1.kpay = P1.kpay
WHERE ELK1.nlevel = @expenselevel
AND ELK2.idchild is not null
GROUP BY #mandate_detail.yman,#mandate_detail.nman, #mandate_detail.npackage, #mandate_detail.idgroup,#mandate_detail.idexp_taxable, P1.ypay, P1.npay
OPEN cursore
FETCH NEXT FROM cursore 
INTO 	@yman,@nman, @npackage, @idgroup,@idexp_taxable, @ypay, @npay
WHILE (@@fetch_status=0) 
BEGIN
	UPDATE #mandate_detail SET
	npay = ISNULL(npay, '') + CONVERT (varchar(4),@ypay) + '/' + convert (varchar(10),@npay) + ', '
	WHERE #mandate_detail.idmankind = @idmankind
	AND  #mandate_detail.yman = @yman
	AND #mandate_detail.nman = @nman
	AND #mandate_detail.idgroup = @idgroup
	AND #mandate_detail.idexp_taxable = @idexp_taxable 
	FETCH NEXT FROM cursore 
	INTO @yman,@nman, @npackage, @idgroup,@idexp_taxable, @ypay, @npay
END
CLOSE cursore
DEALLOCATE cursore
-- Toglie la virgola finale
UPDATE #mandate_detail SET 
npay = substring (npay,1, len(npay)-1) 
WHERE npay IS NOT NULL

SELECT yman AS 'Esercizio', nman AS 'N.ordine', adate AS 'Data contabile', manager AS 'Nome responsabile', 
	registry AS 'Nome fornitore',detaildescription AS 'Descrizione detaglio', npackage AS 'Quantità', 
	imponibile AS 'Imponibile', taxrate AS 'Iva %', discount AS 'Sconto',total AS 'Totale', npay AS 'Mandato'
FROM #mandate_detail 
END


GO

print '[exp_dettagli_contrattopassivo_non_invent] OK'

