print 'closeyear_fillaccountlookup OK'

GO
if object_id('[rpt_bilprevisione_riep]') is not null
	drop PROCEDURE [rpt_bilprevisione_riep]
go

--exec rpt_bilprevisione_riep 2011,'S',3,'%','S','S','S'

CREATE  	PROCEDURE [rpt_bilprevisione_riep]
	@ayear 		int,
	@finpart 	char(1),
	@levelusable 	tinyint,	
	@idupb		varchar(36),
	@showupb 	char(1),
	@showchildupb 	char(1),
	@suppressifblank char(1),
	@idsor01 int=null,
	@idsor02 int=null,
	@idsor03 int=null,
	@idsor04 int=null,
	@idsor05 int=null
AS  BEGIN
/* Versione 1.0.2 del 12/10/2007 ultima modifica: MARIA */

DECLARE @idupboriginal 		varchar(36)
SET @idupboriginal= @idupb

IF (@showchildupb = 'S') SET @idupb = @idupb + '%' 

declare @fixedidupb varchar(36)
set @fixedidupb= null
if (@showupb='N') set @fixedidupb='0001'


DECLARE	@finpart_bit  tinyint  -- Parte del bilancio (Entrata / Spesa)
if @finpart='E' set @finpart_bit = 0
if @finpart='S' set @finpart_bit = 1

DECLARE @idfinincomesurplus int -- Flag indicante se l'avanzo di amministrazione è attribuito in previsione ad un capitolo di entrata o no --M. Smaldino
SELECT @idfinincomesurplus = isnull(idfinincomesurplus,0) 
	FROM config
	WHERE ayear = @ayear

CREATE TABLE #data
(
	idfin 			int		, 
	idupb 			varchar(36)	,
	prevision		decimal(19,2)	,
	previousprevision	decimal(19,2)	,
	secondaryprevision	decimal(19,2)	,
	previoussecprevision	decimal(19,2)	,
	currentarrears		decimal(19,2)	,
	previousarrears		decimal(19,2)	,
	accretion_var		decimal(19,2)	,
	diminution_var		decimal(19,2)	,
	sec_accretion_var	decimal(19,2)	,
	sec_diminution_var	decimal(19,2)	,
	rep_accretion_var	decimal(19,2)	,
	rep_diminution_var	decimal(19,2)	
)
	

CREATE TABLE #finyear
(
	idfin int, 
	idupb varchar(36),
	prevision		decimal(19,2)	,
	previousprevision	decimal(19,2)	,
	secondaryprev		decimal(19,2)	,
	currentarrears		decimal(19,2)	,
	previousarrears		decimal(19,2)	,
	accretion_var		decimal(19,2)	,
	diminution_var		decimal(19,2)	
)
	

	DECLARE @infoadvance		char(1)
	SELECT  @infoadvance = paramvalue FROM    generalreportparameter
	WHERE   idparam = 'MostraAvanzo'
	DECLARE @minlevelusable		tinyint
	SELECT  @minlevelusable = min(nlevel) FROM finlevel WHERE ayear = @ayear and (flag&2)<>0
	
	IF(@levelusable < @minlevelusable)
	begin
		SET @levelusable = @minlevelusable
	end


IF @levelusable > @minlevelusable
BEGIN
print 'then'
-- se la stampa è per articolo : 4 > 3 : legge le prev dalle foglie e somma sino al livello desiderato
--   [ex: finusable degli articoli, laddove non esiste l'articolo -- legge il capitolo]
	INSERT INTO #data
	(
		idfin,
		idupb,
		initialprevision,previousprevision,secondaryprevision,currentarrears,previousarrears,accretion_var,diminution_var
	)
	SELECT
		finlink.idparent,	isnull(@fixedidupb,fy2.idupb),
		SUM(fy2.prevision),
		SUM(fy2.previousprevision),
		SUM(fy2.secondaryprev),
		SUM(fy2.currentarrears),
		SUM(fy2.previousarrears),
		SUM (case when fy2.prevision-fy2.previousprevision > 0 then fy2.prevision-fy2.previousprevision else 0 end),
		SUM (case when fy2.previousprevision-fy2.prevision > 0 then fy2.previousprevision-fy2.prevision else 0 end)

	FROM  finyear fy2
		JOIN finlast
			ON finlast.idfin = fy2.idfin
		JOIN finlink 
			ON finlink.idchild = finlast.idfin AND finlink.nlevel = 1
		JOIN fin 
			on fin.idfin=finlink.idparent	
		JOIN upb U
			ON fy2.idupb = U.idupb		
	WHERE (fy2.idupb LIKE @idupb)
		AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
		AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
		AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
		AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
		AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
		AND fy2.ayear = @ayear
		
		AND ((fin.flag & 1)= @finpart_bit) -- AND fin.finpart = @finpart
		AND fin.nlevel = 1
		AND (@infoadvance = 'N' OR @infoadvance = 'B' OR @idfinincomesurplus <> fin.idfin )  
	GROUP BY isnull(@fixedidupb,fy2.idupb),finlink.idparent,
	U.idsor01,  U.idsor02,  U.idsor03,  U.idsor04, U.idsor05
				
END
ELSE
BEGIN
print'Else'
	INSERT INTO #data
	(
		idfin,
		idupb,
		initialprevision,previousprevision,secondaryprevision,currentarrears,previousarrears,accretion_var,diminution_var
	)
	SELECT
		finlink.idparent,	isnull(@fixedidupb,fy2.idupb),
		SUM(fy2.prevision),
		SUM(fy2.previousprevision),
		SUM(fy2.secondaryprev),
		SUM(fy2.currentarrears),
		SUM(fy2.previousarrears),
		SUM (case when fy2.prevision-fy2.previousprevision > 0 then fy2.prevision-fy2.previousprevision else 0 end),
		SUM (case when fy2.previousprevision-fy2.prevision > 0 then fy2.previousprevision-fy2.prevision else 0 end)
	FROM finyear fy2
	JOIN fin f2
		ON f2.idfin = fy2.idfin 

	JOIN finlink
		ON fy2.idfin = finlink.idchild AND finlink.nlevel = 1
	JOIN fin
		ON fin.idfin = finlink.idparent 	
	JOIN upb U
		ON fy2.idupb = U.idupb			
	WHERE f2.nlevel=@levelusable
		AND (fy2.idupb LIKE @idupb)
		AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
		AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
		AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
		AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
		AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
		AND fy2.ayear = @ayear
		AND ((fin.flag & 1)= @finpart_bit)
		AND (@infoadvance = 'N' OR @infoadvance = 'B'  OR @idfinincomesurplus <> fin.idfin)
		GROUP BY isnull(@fixedidupb,fy2.idupb),finlink.idparent,
		U.idsor01,  U.idsor02,  U.idsor03,  U.idsor04, U.idsor05
END


----------------------------------------------------------------------------------------------------------------------------------------------------------------
------------------------------------------------- SE SI è DECISO DI NON VEDERE  UPB ---------------------------------------------------------------------------------
IF (@showupb <>'S') and (@idupboriginal = '%') 
BEGIN 

	INSERT INTO #budget
		(
		idfin,
		idupb
		)
	SELECT 
		idfin,
		null
	FROM fin 
	WHERE 	nlevel = 1
		AND ayear = @ayear AND ((flag & 1)= @finpart_bit)

  IF @levelusable > @minlevelusable
  BEGIN	 --print 'then'  --stampa per articolo (ovvero nodi foglia)
	INSERT INTO #finyear	
	(
		idfin , 
		prevision,
		previousprevision,
		secondaryprev,
		currentarrears,
		previousarrears,
		accretion_var,
		diminution_var
	)
	SELECT  
		f6.idfin,
		SUM(fy.prevision),
		SUM(fy.previousprevision),
		SUM(fy.secondaryprev),
		SUM(fy.currentarrears),
		SUM(fy.previousarrears),
		SUM (case when prevision-previousprevision > 0 then prevision-previousprevision else 0 end),
		SUM (case when previousprevision-prevision > 0 then previousprevision-prevision else 0 end)
	FROM fin f6
	JOIN finlevel fl
		ON f6.nlevel = fl.nlevel AND  f6.ayear = fl.ayear
	JOIN finyear fy
		ON fy.idfin = f6.idfin
	WHERE f6.ayear = @ayear
		AND ((f6.flag & 1)= @finpart_bit) 
		AND (f6.nlevel = @levelusable
			OR (f6.nlevel < @levelusable
			AND EXISTS
			(SELECT * FROM finlast WHERE finlast.idfin = f6.idfin)
			AND (fl.flag&2)<>0
			)
			)
		AND (@infoadvance = 'N' OR @infoadvance = 'B' OR f6.idfin <> @idfinincomesurplus )
	GROUP BY f6.idfin
	-- accretion_var = prevision-previousprevision when > 0 else 0
	-- diminution_var = previousprevision-prevision when > 0 else 0
	
	

						
	END
	ELSE
	
	BEGIN  -- Stampa per capitolo
	INSERT INTO #finyear	(
	idfin , 
	prevision,
	previousprevision,
	secondaryprev,
	currentarrears,
	previousarrears	
	)
	SELECT  
		f6.idfin,SUM(fy.prevision),
		SUM(fy.previousprevision),
		SUM(fy.secondaryprev),
		SUM(fy.currentarrears),
		SUM(fy.previousarrears)
	FROM fin f6
	JOIN finlevel fl
		ON f6.nlevel = fl.nlevel AND  f6.ayear = fl.ayear
	JOIN finyear fy
		ON fy.idfin = f6.idfin
	WHERE f6.ayear = @ayear
		AND ((f6.flag & 1)= @finpart_bit) 
		AND (f6.nlevel = @levelusable
			OR (f6.nlevel < @levelusable
			AND EXISTS
			(SELECT * FROM finlast WHERE finlast.idfin = f6.idfin)
			AND (fl.flag&2)<>0
			)
			)
		AND (@infoadvance = 'N' OR @infoadvance = 'B' OR f6.idfin <> @idfinincomesurplus )
	GROUP BY f6.idfin

	UPDATE #budget set 
		prevision = 
				ISNULL((SELECT SUM(ISNULL(fy2.prevision,0.0))
				FROM #finyear as fy2
				JOIN finlink 
					ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
				JOIN fin
					ON fin.idfin = finlink.idchild
				WHERE	fy2.idfin =  finlink.idchild  
					AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
					AND  fin.nlevel = @levelusable 
					),0),
		previousprevision =
				ISNULL((SELECT SUM(ISNULL(fy2.previousprevision,0.0))
				FROM #finyear as fy2
				JOIN finlink 
					ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
				JOIN fin
					ON fin.idfin = finlink.idchild
				WHERE	fy2.idfin =  finlink.idchild  
					AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
					AND  fin.nlevel = @levelusable 
					),0),
		secondaryprevision =
				 ISNULL((SELECT SUM(ISNULL(fy2.secondaryprev,0.0))
				    FROM #finyear as fy2
				    JOIN finlink 
					ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
				    JOIN fin
					ON fin.idfin = finlink.idchild
				  WHERE	fy2.idfin =  finlink.idchild  
					AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
					AND  fin.nlevel = @levelusable 
					),0),
		previoussecprevision = 0,
		currentarrears =
				 ISNULL((SELECT SUM(ISNULL(fy2.currentarrears,0.0))
				    FROM #finyear as fy2
				    JOIN finlink 
					ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
				    JOIN fin
					ON fin.idfin = finlink.idchild
				  WHERE	fy2.idfin =  finlink.idchild  
					AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
					AND  fin.nlevel = @levelusable 
					),0),
		previousarrears = ISNULL((SELECT SUM(ISNULL(fy2.previousarrears,0.0))
				    FROM #finyear as fy2
				    JOIN finlink 
					ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
				    JOIN fin
					ON fin.idfin = finlink.idchild
				  WHERE	fy2.idfin =  finlink.idchild  
					AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
					AND  fin.nlevel = @levelusable 
					),0),

	accretion_var  =
			--previsione principale variazioni in aumento 
			ISNULL((SELECT SUM(ISNULL(fy2.prevision, 0.0) - ISNULL(fy2.previousprevision, 0.0))
			 FROM #finyear as fy2
			 JOIN finlink 
				ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
		   	 JOIN fin
				ON fin.idfin = finlink.idchild
		  	WHERE	fy2.idfin =  finlink.idchild  
			AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
			AND (ISNULL(fy2.prevision, 0.0) - ISNULL(fy2.previousprevision, 0.0)) > 0
			AND  fin.nlevel = @levelusable 
			),0),						
	diminution_var = 
			--previsione principale variazioni in diminuzione 
			ISNULL((SELECT SUM(ISNULL(fy2.previousprevision, 0.0) - ISNULL(fy2.prevision, 0.0))
			 FROM #finyear as fy2
			 JOIN finlink 
				ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
		   	 JOIN fin
				ON fin.idfin = finlink.idchild
		  	WHERE	fy2.idfin =  finlink.idchild  
			AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
			AND (ISNULL(fy2.previousprevision, 0.0) - ISNULL(fy2.prevision, 0.0)) > 0
			AND  fin.nlevel = @levelusable 
			),0)
	END


END --(@showupb <>'S') and (@idupboriginal = '%') 
---------------------------------------------- SE INVECE SI è DECISO DI VEDERE UPB   ------------------------------------
ELSE
BEGIN 

	INSERT INTO #budget
		(
		idfin,
		idupb
		)
	SELECT 
		b1.idfin,
		upb.idupb
	FROM fin b1 cross join upb
	WHERE 	b1.nlevel = 1
		AND (upb.idupb like @idupb)
		AND b1.ayear = @ayear AND ((b1.flag & 1)= @finpart_bit)
	
	IF @levelusable > @minlevelusable
	BEGIN print 'then'  --stampa per articolo (ovvero nodi foglia)
	UPDATE #budget  
	SET
			prevision = 	ISNULL((SELECT SUM(ISNULL(fy2.prevision,0.0))
					FROM finyear as fy2
					JOIN finlink 
						ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
					JOIN finlast
						ON finlast.idfin = finlink.idchild
					JOIN fin
						ON finlast.idfin = fin.idfin
					WHERE	fy2.idfin =  finlink.idchild  
						AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
						AND fy2.ayear = @ayear
						AND fy2.idupb = #budget.idupb),0),

			previousprevision = 	ISNULL((SELECT SUM(ISNULL(fy2.previousprevision,0.0))
						FROM finyear as fy2
						JOIN finlink 
							ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
						JOIN finlast
							ON finlast.idfin = finlink.idchild
						JOIN fin
							ON finlast.idfin = fin.idfin
						WHERE	fy2.idfin =  finlink.idchild  
						AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
						AND fy2.ayear = @ayear
						AND fy2.idupb = #budget.idupb
						),0),
			secondaryprevision =
						ISNULL((SELECT SUM(ISNULL(fy2.secondaryprev,0.0))
						FROM finyear as fy2
						JOIN finlink 
							ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
						JOIN finlast
							ON finlast.idfin = finlink.idchild
						JOIN fin
							ON finlast.idfin = fin.idfin
						WHERE	fy2.idfin =  finlink.idchild  
						AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
						AND fy2.ayear = @ayear
						AND fy2.idupb = #budget.idupb
						),0),
			previoussecprevision = 
						ISNULL((SELECT SUM(ISNULL(fy2.previoussecondaryprev,0.0))
						FROM finyear as fy2
						JOIN finlink 
							ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
						JOIN finlast
							ON finlast.idfin = finlink.idchild
						JOIN fin
							ON finlast.idfin = fin.idfin
						WHERE	fy2.idfin =  finlink.idchild  
						AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
						AND fy2.ayear = @ayear
						AND fy2.idupb = #budget.idupb
						),0),
			currentarrears = 	
						ISNULL((SELECT SUM(ISNULL(fy2.currentarrears,0.0))
						FROM finyear as fy2
						JOIN finlink 
							ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
						JOIN finlast
							ON finlast.idfin = finlink.idchild
						JOIN fin
							ON finlast.idfin = fin.idfin
						WHERE	fy2.idfin =  finlink.idchild  
						AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
						AND fy2.ayear = @ayear
						AND fy2.idupb = #budget.idupb
						),0),
			previousarrears = 	
						ISNULL((SELECT SUM(ISNULL(fy2.previousarrears,0.0))
						FROM finyear as fy2
						JOIN finlink 
							ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
						JOIN finlast
							ON finlast.idfin = finlink.idchild
						JOIN fin
							ON finlast.idfin = fin.idfin
						WHERE	fy2.idfin =  finlink.idchild  
						AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
						AND fy2.ayear = @ayear
						AND fy2.idupb = #budget.idupb
						),0),
			accretion_var = 	
						--previsione principale variazioni in aumento 
						ISNULL((SELECT SUM(ISNULL(fy2.prevision, 0.0) - ISNULL(fy2.previousprevision, 0.0))
						FROM finyear as fy2
						JOIN finlink 
							ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
						JOIN finlast
							ON finlast.idfin = finlink.idchild
						JOIN fin
							ON finlast.idfin = fin.idfin
						WHERE	fy2.idfin =  finlink.idchild  
						AND (ISNULL(fy2.prevision, 0.0) - ISNULL(fy2.previousprevision, 0.0)) > 0
						AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
						AND fy2.ayear = @ayear
						AND fy2.idupb = #budget.idupb
						),0),
			diminution_var = 
						--previsione principale variazioni in diminuzione 
						ISNULL((SELECT SUM(ISNULL(fy2.previousprevision, 0.0) - ISNULL(fy2.prevision, 0.0))
						FROM finyear as fy2
						JOIN finlink 
							ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
						JOIN finlast
							ON finlast.idfin = finlink.idchild
						JOIN fin
							ON finlast.idfin = fin.idfin
						WHERE	fy2.idfin =  finlink.idchild  
						AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
						AND (ISNULL(fy2.previousprevision, 0.0) - ISNULL(fy2.prevision, 0.0)) > 0
						AND fy2.ayear = @ayear
						AND fy2.idupb = #budget.idupb
						),0),
			sec_accretion_var =
						--previsione secondaria variazioni in aumento
						ISNULL((SELECT SUM(ISNULL(fy2.secondaryprev, 0.0) - ISNULL(fy2.previoussecondaryprev, 0.0))
						FROM finyear as fy2
						JOIN finlink 
							ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
						JOIN finlast
							ON finlast.idfin = finlink.idchild
						JOIN fin
							ON finlast.idfin = fin.idfin
						WHERE	fy2.idfin =  finlink.idchild  
						AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
						AND (ISNULL(fy2.secondaryprev, 0.0) - ISNULL(fy2.previoussecondaryprev, 0.0)) > 0
						AND fy2.ayear = @ayear
						AND fy2.idupb = #budget.idupb
						),0),
			sec_diminution_var =
						--previsione secondaria variazioni in diminuzione
						ISNULL((SELECT SUM(ISNULL(fy2.previoussecondaryprev, 0.0) - ISNULL(fy2.secondaryprev, 0.0))
						FROM finyear as fy2
						JOIN finlink 
							ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
						JOIN finlast
							ON finlast.idfin = finlink.idchild
						JOIN fin
							ON finlast.idfin = fin.idfin
						WHERE	fy2.idfin =  finlink.idchild  
						AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
						AND (ISNULL(fy2.previoussecondaryprev, 0.0) - ISNULL(fy2.secondaryprev, 0.0)) > 0
						AND fy2.ayear = @ayear
						AND fy2.idupb = #budget.idupb
						),0),
			rep_accretion_var =
						-- variazioni in aumento ripartizione
						ISNULL((SELECT SUM(ISNULL(fy2.currentarrears, 0.0) - ISNULL(fy2.previousarrears, 0.0))
						FROM finyear as fy2
						JOIN finlink 
							ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
						JOIN finlast
							ON finlast.idfin = finlink.idchild
						JOIN fin
							ON finlast.idfin = fin.idfin
						WHERE	fy2.idfin =  finlink.idchild  
						AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
						AND (ISNULL(fy2.currentarrears, 0.0) - ISNULL(fy2.previousarrears, 0.0)) > 0
						AND fy2.ayear = @ayear
						AND fy2.idupb = #budget.idupb
						),0),
			rep_diminution_var =
						-- variazioni in diminuzione ripartizione
						ISNULL((SELECT SUM(ISNULL(fy2.previousarrears, 0.0) - ISNULL(fy2.currentarrears, 0.0))
						FROM finyear as fy2
						JOIN finlink 
							ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
						JOIN finlast
							ON finlast.idfin = finlink.idchild
						JOIN fin
							ON finlast.idfin = fin.idfin
						WHERE	fy2.idfin =  finlink.idchild  
						AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
						AND (ISNULL(fy2.previousarrears, 0.0) - ISNULL(fy2.currentarrears, 0.0)) > 0
						AND fy2.ayear = @ayear
						AND fy2.idupb = #budget.idupb
						),0)
						
	END
	ELSE
	
	BEGIN print 'else'  --stampa per capitolo
	UPDATE #budget  
	SET
			prevision = 
					ISNULL((SELECT SUM(ISNULL(fy2.prevision,0.0))
					FROM finyear as fy2
					JOIN finlink 
						ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
					JOIN fin
						ON fin.idfin = finlink.idchild
					WHERE	fy2.idfin =  finlink.idchild  
						AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
						AND  fin.nlevel = @levelusable 
						AND fy2.ayear = @ayear
						AND fy2.idupb = #budget.idupb
						),0),
			previousprevision =
					ISNULL((SELECT SUM(ISNULL(fy2.previousprevision,0.0))
					FROM finyear as fy2
					JOIN finlink 
						ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
					JOIN fin
						ON fin.idfin = finlink.idchild
					WHERE	fy2.idfin =  finlink.idchild  
						AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
						AND  fin.nlevel = @levelusable 
						AND fy2.ayear = @ayear
						AND fy2.idupb = #budget.idupb
						),0),
			secondaryprevision =
					 ISNULL((SELECT SUM(ISNULL(fy2.secondaryprev,0.0))
					    FROM finyear as fy2
					    JOIN finlink 
						ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
					    JOIN fin
						ON fin.idfin = finlink.idchild
					  WHERE	fy2.idfin =  finlink.idchild  
						AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
						AND  fin.nlevel = @levelusable 
						AND fy2.ayear = @ayear
						AND fy2.idupb = #budget.idupb
						),0),
			previoussecprevision =
					 ISNULL((SELECT SUM(ISNULL(fy2.previoussecondaryprev,0.0))
					    FROM finyear as fy2
					    JOIN finlink 
						ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
					    JOIN fin
						ON fin.idfin = finlink.idchild
					  WHERE	fy2.idfin =  finlink.idchild  
						AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
						AND  fin.nlevel = @levelusable 
						AND fy2.ayear = @ayear
						AND fy2.idupb = #budget.idupb
						),0),
			currentarrears =
					 ISNULL((SELECT SUM(ISNULL(fy2.currentarrears,0.0))
					    FROM finyear as fy2
					    JOIN finlink 
						ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
					    JOIN fin
						ON fin.idfin = finlink.idchild
					  WHERE	fy2.idfin =  finlink.idchild  
						AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
						AND  fin.nlevel = @levelusable 
						AND fy2.ayear = @ayear
						AND fy2.idupb = #budget.idupb
						),0),
			previousarrears =
					 ISNULL((SELECT SUM(ISNULL(fy2.previousarrears,0.0))
					    FROM finyear as fy2
					    JOIN finlink 
						ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
					    JOIN fin
						ON fin.idfin = finlink.idchild
					  WHERE	fy2.idfin =  finlink.idchild  
						AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
						AND  fin.nlevel = @levelusable 
						AND fy2.ayear = @ayear
						AND fy2.idupb = #budget.idupb
						),0),
			accretion_var  =
					--previsione principale variazioni in aumento 
					ISNULL((SELECT SUM(ISNULL(fy2.prevision, 0.0) - ISNULL(fy2.previousprevision, 0.0))
					 FROM finyear as fy2
					 JOIN finlink 
						ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
				   	 JOIN fin
						ON fin.idfin = finlink.idchild
				  	WHERE	fy2.idfin =  finlink.idchild  
					AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
					AND (ISNULL(fy2.prevision, 0.0) - ISNULL(fy2.previousprevision, 0.0)) > 0
					AND  fin.nlevel = @levelusable 
					AND fy2.ayear = @ayear
					AND fy2.idupb = #budget.idupb
					),0),						
			diminution_var = 
					--previsione principale variazioni in diminuzione 
					ISNULL((SELECT SUM(ISNULL(fy2.previousprevision, 0.0) - ISNULL(fy2.prevision, 0.0))
					 FROM finyear as fy2
					 JOIN finlink 
						ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
				   	 JOIN fin
						ON fin.idfin = finlink.idchild
				  	WHERE	fy2.idfin =  finlink.idchild  
					AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
					AND (ISNULL(fy2.previousprevision, 0.0) - ISNULL(fy2.prevision, 0.0)) > 0
					AND  fin.nlevel = @levelusable 
					AND fy2.ayear = @ayear
					AND fy2.idupb = #budget.idupb
					),0),		
			sec_accretion_var = 
					--previsione secondaria variazioni in aumento 
					ISNULL((SELECT SUM(ISNULL(fy2.secondaryprev, 0.0) - ISNULL(fy2.previoussecondaryprev, 0.0))
					 FROM finyear as fy2
					 JOIN finlink 
						ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
				   	 JOIN fin
						ON fin.idfin = finlink.idchild
				  	WHERE	fy2.idfin =  finlink.idchild  
					AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
					AND (ISNULL(fy2.secondaryprev, 0.0) - ISNULL(fy2.previoussecondaryprev, 0.0)) > 0
					AND  fin.nlevel = @levelusable 
					AND fy2.ayear = @ayear
					AND fy2.idupb = #budget.idupb
					),0),		
			sec_diminution_var =
					--previsione secondaria variazioni in diminuzione 
					ISNULL((SELECT SUM(ISNULL(fy2.previoussecondaryprev, 0.0) - ISNULL(fy2.secondaryprev, 0.0))
					 FROM finyear as fy2
					 JOIN finlink 
						ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
				   	 JOIN fin
						ON fin.idfin = finlink.idchild
				  	WHERE	fy2.idfin =  finlink.idchild  
					AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
					AND (ISNULL(fy2.previoussecondaryprev, 0.0) - ISNULL(fy2.secondaryprev, 0.0)) > 0
					AND  fin.nlevel = @levelusable 
					AND fy2.ayear = @ayear
					AND fy2.idupb = #budget.idupb
					),0),		
			rep_accretion_var =
					-- variazioni in aumento ripartizione
					ISNULL((SELECT SUM(ISNULL(fy2.currentarrears, 0.0) - ISNULL(fy2.previousarrears, 0.0))
					 FROM finyear as fy2
					 JOIN finlink 
						ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
				   	 JOIN fin
						ON fin.idfin = finlink.idchild
				  	WHERE	fy2.idfin =  finlink.idchild  
					AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
					AND (ISNULL(fy2.currentarrears, 0.0) - ISNULL(fy2.previousarrears, 0.0)) > 0
					AND  fin.nlevel = @levelusable 
					AND fy2.ayear = @ayear
					AND fy2.idupb = #budget.idupb
					),0),			
			rep_diminution_var = 
					-- variazioni in diminuzione ripartizione
					ISNULL((SELECT SUM(ISNULL(fy2.previousarrears, 0.0) - ISNULL(fy2.currentarrears, 0.0))
					 FROM finyear as fy2
					 JOIN finlink 
						ON finlink.idparent = #budget.idfin AND finlink.nlevel = 1
				   	 JOIN fin
						ON fin.idfin = finlink.idchild
				  	WHERE	fy2.idfin =  finlink.idchild  
					AND (@idfinincomesurplus <> fin.idfin OR @infoadvance = 'N' OR @infoadvance = 'B')
					AND (ISNULL(fy2.previousarrears, 0.0) - ISNULL(fy2.currentarrears, 0.0)) > 0
					AND  fin.nlevel = @levelusable 
					AND fy2.ayear = @ayear
					AND fy2.idupb = #budget.idupb
					),0)	
	END 
END--(@showupb <>'S') and (@idupboriginal = '%') 
	
	
	UPDATE #budget SET 
		codeupb = (SELECT codeupb FROM upb 
			WHERE idupb=#budget.idupb),
		upb = (SELECT title FROM upb 
			WHERE idupb=#budget.idupb),
		upbprintingorder = (SELECT  printingorder FROM upb
			WHERE idupb=#budget.idupb)

	IF (@showupb <>'S') AND (@idupboriginal <> '%' ) AND (@showchildupb = 'S')
		UPDATE #budget SET  
			upbprintingorder = (SELECT TOP 1 upbprintingorder
				FROM #budget
				WHERE idupb = @idupboriginal),
			upb = (SELECT TOP 1 upb
				FROM #budget
				WHERE idupb = @idupboriginal),
			idupb = @idupboriginal,
			codeupb =(SELECT TOP 1 codeupb
				FROM #budget	
				WHERE idupb = @idupboriginal)
			
	IF (@showupb <>'S') and (@idupboriginal = '%') 
		UPDATE #budget SET  
		upbprintingorder = null	,
		upb =  null,
		idupb = null,
		codeupb = null
	DECLARE @supposed_ff_prec	decimal(19,2)
	DECLARE @supposed_aa_prec	decimal(19,2)
	
	DECLARE @supposed_ff		decimal(19,2)
	DECLARE @supposed_aa		decimal(19,2)

	DECLARE @floatfund_01_jan_used decimal(19,2) 
	DECLARE @supposed_aa_01_jan_used decimal(19,2) 
	DECLARE @aa_01_jan_used decimal(19,2) 
	DECLARE @supposed_ff_01_jan_used decimal(19,2) 

	DECLARE @aa_prec_used decimal(19,2) 
	DECLARE @ff_prec_used decimal(19,2)

	IF 	@finpart = 'E'
	BEGIN
		-- Bilancio di Previsione 2014 --
		-- Fondo cassa al 01/01/2013
		SELECT	@supposed_ff_prec = ISNULL(startfloatfund, 0) 
		FROM surplus
		WHERE ayear = @ayear - 1
		
		-- Avanzo di amministrazione al 01/01/2013 = AA al 31/12/2012 = fondo cassa 31/12/2012 + Residui Attivi 2012 - Residui Passivi 2012 = fondo cassa 01/01/2013 + RA 2012 - RP 2012
		SELECT @supposed_aa_prec = (SELECT ISNULL(startfloatfund, 0) FROM surplus	WHERE ayear = @ayear - 1)
			+	
			ISNULL(previousrevenue, 0) +
			ISNULL(currentrevenue , 0) -
			ISNULL(previousexpenditure, 0) -
			ISNULL(currentexpenditure, 0)
		FROM surplus
		WHERE ayear = @ayear - 2
	-- Per ulteriori dettagli in merito a questa modifica leggere la Documentazione del task n.4077
	
		SELECT
		@supposed_ff =
			ISNULL(startfloatfund, 0.0) 	+ ISNULL(proceedstilldate, 0.0) -
			ISNULL(paymentstilldate, 0.0) 	+ ISNULL(proceedstoendofyear, 0.0) -
			ISNULL(paymentstoendofyear, 0.0),
		@supposed_aa =
			ISNULL(startfloatfund, 0.0) 	+ ISNULL(proceedstilldate, 0.0) -
			ISNULL(paymentstilldate, 0.0) 	+	ISNULL(proceedstoendofyear, 0.0) -
			ISNULL(paymentstoendofyear, 0.0) + ISNULL(supposedpreviousrevenue, 0.0) +				
			ISNULL(supposedcurrentrevenue , 0.0) - ISNULL(supposedpreviousexpenditure, 0.0) -
			ISNULL(supposedcurrentexpenditure, 0.0)
		FROM 	surplus
		WHERE 	ayear = @ayear - 1

		SELECT @floatfund_01_jan_used = isnull(paramvalue,0) 
		FROM generalreportparameter 
		WHERE idparam='ff_jan01'
		
		SELECT @aa_01_jan_used = isnull(paramvalue,0) 
		FROM generalreportparameter 
		WHERE idparam='aa_jan01'
	
		SELECT @supposed_ff_01_jan_used = isnull(paramvalue,0) 
		FROM generalreportparameter 
		WHERE idparam='supposed_ff_jan01'
		
		SELECT @supposed_aa_01_jan_used = isnull(paramvalue,0) 
		FROM generalreportparameter 
		WHERE idparam='supposed_aa_jan01'

		SELECT @aa_prec_used = isnull(paramvalue,0) 
		FROM generalreportparameter 
		WHERE idparam='aa_prec'

		SELECT @ff_prec_used = isnull(paramvalue,0) 
		FROM generalreportparameter 
		WHERE idparam='ff_prec'
	
	END
	

DECLARE @MostraTutteVoci char(1)
SELECT @MostraTutteVoci = isnull(paramvalue,'N') 
FROM generalreportparameter WHERE idparam = 'MostraTutteVoci'
-- se vuoi nascondere le voci inutilizzate e vuoi nasccondere anche i totoli e la e categorie(mostra tutte le voci), allora
-- cancella le righe a zero, se invece vuoi nascondere solo le voci inutilizzate fino alla categoria,
-- (quindi nel report principale saranno nascosti solo capitoli e articoli) non fa  nulla
IF(Upper(@MostraTutteVoci)='N' AND @suppressifblank = 'S' )
BEGIN
	DELETE FROM #budget 
	WHERE ISNULL(prevision,0)= 0
		AND ISNULL(previousprevision,0)= 0
		AND ISNULL(secondaryprevision,0)= 0
		-- AND ISNULL(previoussecprevision,0) = 0 nel rpeort non è mia usato
		AND ISNULL(currentarrears,0)= 0
		-- AND ISNULL(previousarrears,0)= 0 
		AND ISNULL(accretion_var,0)= 0
		AND ISNULL(diminution_var,0)= 0
		--AND ISNULL(sec_accretion_var,0)= 0
		--AND ISNULL(sec_diminution_var,0)= 0
		--AND ISNULL(rep_accretion_var,0)= 0
		--AND ISNULL(rep_diminution_var,0)= 0
	AND idupb <> '0001'
END

	SELECT 
		#budget.idfin,
		fin.codefin AS code1,
		fin.title AS desc1,
		fin.printingorder AS printorder1,
		codeupb			,
		idupb 			,
		upb   			,
		upbprintingorder	,
		prevision		,
		previousprevision	,
		secondaryprevision	,
		previoussecprevision	,
		currentarrears		,
		previousarrears		,
		accretion_var		,
		diminution_var		,
		sec_accretion_var	,
		sec_diminution_var	,
		rep_accretion_var	,
		rep_diminution_var	,
	   	(select CASE
		when (fin_kind = 1 or fin_kind = 3 ) then 'C'
		when (fin_kind = 2 ) then 'S'
		End FROM config WHERE ayear = @ayear) as 'previsionkind',
		null 			as 'display_aa',
		@supposed_ff 		as 'supposed_ff',
		@supposed_aa 		as 'supposed_aa',
		@supposed_ff_prec 	as 'supposed_ff_prec',
		@supposed_aa_prec 	as 'supposed_aa_prec',
		isnull(@floatfund_01_jan_used,0) as floatfund_01_jan_used,
		isnull(@supposed_aa_01_jan_used,0) as supposed_aa_01_jan_used,
		isnull(@aa_01_jan_used,0) as aa_01_jan_used,
		isnull(@supposed_ff_01_jan_used,0) as supposed_ff_01_jan_used,
		isnull(@aa_prec_used,0) as  aa_prec_used,
		isnull(@ff_prec_used,0) as ff_prec_used	
	FROM 	#budget
	JOIN fin
		ON #budget.idfin = fin.idfin	
	ORDER BY printorder1
END





