		ON IY.idinc = I.idinc
	JOIN fin F
		ON IY.idfin = F.idfin
	JOIN incometotal IT
		ON IT.idinc = IY.idinc
		AND IT.ayear = IY.ayear
	JOIN finlink FLK
		ON FLK.idchild = IY.idfin
	JOIN upb U
		ON IY.idupb = U.idupb
	WHERE
		(IY.idupb LIKE @idupb)
		AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
		AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
		AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
		AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
		AND (@idsor05 IS NULL OR U.idsor05 = @idsor05) 
		AND I.adate <= @date
		AND IY.ayear = @ayear
		AND ((IT.flag & 1) =0)-- Competenza
		AND I.nphase = @finphase
		AND (F.idfin <> @idfinincomesurplus OR @infoadvance = 'N' OR @infoadvance = 'B')
		AND FLK.nlevel = 1
	GROUP BY isnull(@fixedidupb,iy.idupb),FLK.idparent,
	U.idsor01,  U.idsor02,  U.idsor03,  U.idsor04, U.idsor05
	
