		AND FLK.nlevel = 1
	GROUP BY isnull(@fixedidupb,ey.idupb),FLK.idparent
	,U.idsor01,  U.idsor02,  U.idsor03,  U.idsor04, U.idsor05
		
	IF (@cashvaliditykind <> 4)
	BEGIN
