			SUM(EV.amount)
		FROM expensevar EV
		JOIN expenseyear EY
			ON EY.idexp = EV.idexp
		JOIN fin F
			ON F.idfin = EY.idfin
		JOIN upb U
			ON EY.idupb = U.idupb
		JOIN historypaymentview HPV
			ON HPV.idexp = EV.idexp
		JOIN finlink FLK
			ON FLK.idchild = EY.idfin
		WHERE EV.yvar = @ayear
			AND (EY.idupb LIKE @idupb)
