if object_id('rebuild_epexptotal') is not null
	drop PROCEDURE rebuild_epexptotal
go

CREATE             PROCEDURE rebuild_epexptotal
AS BEGIN
	DECLARE @curryear int
	DELETE FROM epexptotal
	
	INSERT INTO epexptotal 
	(
		nepexp,
		yepexp,
		amount
	)
	SELECT
	nepexp,
	yepexp,
	amount
	FROM epexp
	
	UPDATE epexptotal
	SET curramount = ISNULL(amount, 0) +
	ISNULL(
		(SELECT SUM(amount) 
		FROM epexpvar
		WHERE epexpvar.yepexp = epexptotal.yepexp
		AND epexpvar.nepexp = epexptotal.nepexp)
	, 0)
END


GO

