if object_id('[rpt_buono_ordine_integrazioni]') is not null
	drop PROCEDURE [rpt_buono_ordine_integrazioni]
go


CREATE       PROCEDURE [rpt_buono_ordine_integrazioni]
	@yman int,
	@nman int,
	@mandatekind varchar(20),
	@datarifer smalldatetime
AS BEGIN
CREATE TABLE #mandatedetail
(
	yman int,
	nman int,
	idmankind varchar(20),
	detaildescription varchar(150),
	annotations varchar(400),
	npackage decimal(19,2),
	taxable decimal(19,5),
	taxrate float,
	tax decimal(19,2),
	discount float,
	start datetime,
	stop datetime
)
INSERT INTO #mandatedetail
(
	yman,
	nman,
	idmankind ,
	detaildescription,
	annotations,
	npackage,
	taxable,
	taxrate,
	tax,
	discount,
	start,
	stop 
)
SELECT 
	@yman,
	@nman,
	@mandatekind,
	detaildescription,
	annotations,
	npackage,
	sum(taxable),
	taxrate,
	sum(tax),
	discount,
	start,
	stop
FROM    mandatedetail
WHERE   mandatedetail.yman = @yman
	AND mandatedetail.idmankind= @mandatekind
	AND mandatedetail.nman = @nman
GROUP BY  detaildescription,annotations,npackage,
	taxrate,discount,start,stop,idgroup
--select * from #mandatedetail
SELECT 
	@yman,
	@nman,
	mandatekind.description as mandatekind,
	mandate.exchangerate as exchangerate,
	#mandatedetail.detaildescription + ' ' + isnull(#mandatedetail.annotations,'') as uniondescr,
	ISNULL(#mandatedetail.npackage, 0) as number ,
	ISNULL(#mandatedetail.taxable, 0.0) as taxable,
	ISNULL(#mandatedetail.taxrate, 0.0)  as taxrate,
	ISNULL(#mandatedetail.discount, 0.0) as discount ,
	CASE 
		WHEN ((currency.codecurrency IS NULL) OR (currency.codecurrency = 'ITL') OR (currency.codecurrency = 'EUR')) THEN 'N'
		ELSE 'S'
	END as is_english,
	#mandatedetail.start,
	#mandatedetail.stop,
-- Imponibile totale della riga di dettaglio
	CONVERT(DECIMAL(19,2),
		ROUND(
		      #mandatedetail.taxable*
		      #mandatedetail.npackage*
		      CONVERT(DECIMAL(19,6),mandate.exchangerate)*
		      (1-CONVERT(DECIMAL(19,6),ISNULL(#mandatedetail.discount,0.0))),2
  		     )
	) as rowtaxable,
-- Per evitare perdita di informazione, da cui conseguono errori di arrotondamento, il campo totaleriga 
-- deve essere calcolato come la somma dell'imponibile scontato + il calcolo dell'aliquota
	CONVERT(DECIMAL(19,2),
		ROUND(
		      #mandatedetail.taxable*
		      #mandatedetail.npackage*
		      CONVERT(DECIMAL(19,6),mandate.exchangerate)*
		      (1-CONVERT(DECIMAL(19,6),ISNULL(#mandatedetail.discount,0.0))),2
  		     )
	)
	+
	ROUND(#mandatedetail.tax,2) as totalrow,
----------------------------------------------------------------------------------------------------------
--------------------------------------- ORDINI IN VALUTA ESTERA ------------------------------------------
----------------------------------------------------------------------------------------------------------
	CONVERT(DECIMAL(19,2),
		ROUND(
			  #mandatedetail.taxable*
			  #mandatedetail.npackage*
			  (1-CONVERT(DECIMAL(19,6),ISNULL(#mandatedetail.discount,0))),2
			 )
	) 
	AS rowtaxable_fcurrency,
	-- Il campo totaleriga in valuta estera  deve essere calcolato come la somma dell'imponibile scontato + l'iva 
	-- non considera iva
	CONVERT(DECIMAL(19,2),
		ROUND(
			  #mandatedetail.taxable*
			  #mandatedetail.npackage*
			  (1-CONVERT(DECIMAL(19,6),ISNULL(#mandatedetail.discount,0))),2
			 )
	+
	ROUND(#mandatedetail.tax,2) 
	)
 AS totalrow_fcurrency
----------------------------------------------------------------------------------------------------------
----------------------------------------------------------------------------------------------------------
----------------------------------------------------------------------------------------------------------
FROM mandate
JOIN #mandatedetail
	ON  mandate.yman = #mandatedetail.yman
	AND mandate.nman = #mandatedetail.nman
	AND mandate.idmankind = #mandatedetail.idmankind
JOIN mandatekind 
	ON  mandatekind.idmankind = mandate.idmankind
LEFT OUTER JOIN currency
	ON currency.idcurrency = mandate.idcurrency
WHERE mandate.yman = @yman
	AND mandate.nman = @nman
	AND mandate.idmankind = @mandatekind
	AND #mandatedetail.start is not  null   
	AND #mandatedetail.start <= @datarifer
ORDER BY #mandatedetail.start ASC
	
END


GO

print '[rpt_buono_ordine_integrazioni] OK'

GO
if object_id('[rpt_missione_impegni]') is not null
	drop PROCEDURE [rpt_missione_impegni]
go

CREATE             PROCEDURE [rpt_missione_impegni]
(
	@ayear smallint,
	@yitineration smallint,
	@nitineration int
)
AS BEGIN
-- exec  rpt_missione_impegni 2007,2007,5
CREATE TABLE #itinerationyear
(
	yitineration smallint,
	nitineration int,
	expensephase varchar(50),
	ymov smallint,
	nmov int,
	adate smalldatetime,
	description varchar(200),
	codefin varchar(50),
	codeupb varchar(50),
	amount decimal(19,2)
)
DECLARE @itinerationphase tinyint
SELECT @itinerationphase = expensephase FROM config WHERE ayear = @ayear
INSERT INTO #itinerationyear
(
	yitineration,
	nitineration,
	expensephase,
	ymov,
	nmov,
	adate,
	description,
	codefin,
	codeupb,
	amount
)
SELECT
	@yitineration,
	@nitineration,
	expensephase.description,
	expense.ymov,
	expense.nmov,
	expense.adate,
	expense.description,
	fin.codefin,
	upb.codeupb,
	expenseyear.amount
FROM expenseitineration
join itineration
on itineration.iditineration = expenseitineration.iditineration
JOIN expense
	ON expense.idexp = expenseitineration.idexp
JOIN expenseyear
	ON expenseyear.idexp = expenseitineration.idexp
JOIN expensephase
	ON expensephase.nphase = expense.nphase
JOIN fin
	ON fin.idfin = expenseyear.idfin
LEFT OUTER JOIN upb
	ON upb.idupb = expenseyear.idupb
WHERE itineration.yitineration = @yitineration
	AND itineration.nitineration = @nitineration
	AND expenseitineration.movkind IN (4, 6)
	AND expense.nphase = @itinerationphase 
	AND expenseyear.ayear = @ayear
INSERT INTO #itinerationyear
(
	yitineration,
	nitineration,
	expensephase,
	ymov,
	nmov,
	adate,
	description,
	codefin,
	codeupb,
	amount
)
SELECT 
	@yitineration,
	@nitineration,	
	pettycash.description,
	pettycashoperation.yoperation,
	pettycashoperation.noperation,
	pettycashoperation.adate,
	pettycashoperation.description,
	ISNULL(f2.codefin, fin.codefin),
	ISNULL(u2.codeupb,upb.codeupb),
	pettycashoperation.amount
FROM pettycashoperationitineration
	join itineration on itineration.iditineration = pettycashoperationitineration.iditineration
JOIN pettycashoperation
	ON pettycashoperation.idpettycash = pettycashoperationitineration.idpettycash
	AND pettycashoperation.yoperation = pettycashoperationitineration.yoperation
	AND pettycashoperation.noperation = pettycashoperationitineration.noperation
JOIN pettycash 
	ON pettycash.idpettycash = pettycashoperation.idpettycash
LEFT OUTER JOIN expenseyear
	ON pettycashoperation.idexp = expenseyear.idexp
	AND expenseyear.ayear = @ayear
LEFT OUTER JOIN fin f2
	ON f2.idfin = expenseyear.idfin
LEFT OUTER JOIN upb u2
	ON u2.idupb = expenseyear.idupb
LEFT OUTER JOIN fin
	ON fin.idfin = pettycashoperation.idfin
LEFT OUTER JOIN upb
	ON upb.idupb = pettycashoperation.idupb
WHERE itineration.yitineration = @yitineration
	AND itineration.nitineration = @nitineration
	AND pettycashoperationitineration.movkind = 6
SELECT * 
FROM #itinerationyear
ORDER BY adate, expensephase ASC,
	ymov ASC,
	nmov ASC
END


GO

print '[rpt_missione_impegni] OK'

