if object_id('rpt_atto_previsione_crediti_cassa') is not null
	drop PROCEDURE rpt_atto_previsione_crediti_cassa
go

--	exec rpt_atto_previsione_crediti_cassa 2013, 2, 'S','S','S','previsione','P',null,null,null,null,null
CREATE   PROCEDURE rpt_atto_previsione_crediti_cassa
	@yvar          	int, 
	@nenactment		int,
	@showupb char(1),
	@layoutupb char(1),-- Code, Title,All
--	@compress char(1),
	@showcategory char(1),
	@reportkind    	varchar(20),
	@kindnumeration varchar(1),-- O Official, P Protocollo
	@idsor01 int,
	@idsor02 int,
	@idsor03 int,
	@idsor04 int,
	@idsor05 int 
	AS
	BEGIN
	
	DECLARE @yenactment   		int
	DECLARE @idenactment	int
	
	SET 	@yenactment = @yvar
	SET     @idenactment = 
			 (SELECT idenactment
			    FROM enactment 
			   WHERE enactment.yenactment = @yenactment
	   		     AND enactment.nenactment = @nenactment)
	
	DECLARE @nlevelcategory tinyint
	SET @nlevelcategory = 2
	
	DECLARE @fin_kind tinyint
	SELECT  @fin_kind = isnull(fin_kind,0) FROM config WHERE ayear = @yvar
	DECLARE @previsionkind char(1) 
	SELECT  @previsionkind =  
		 CASE 
			WHEN fin_kind IN (1,3) THEN 'C'
			WHEN fin_kind = 2 THEN 'S'
		 END
	FROM  config 
	WHERE config.ayear = @yvar
	DECLARE @secprevisionkind    char(1) 
	SELECT  @secprevisionkind  = 
		 CASE 
			WHEN fin_kind = 3 THEN 'S'
			ELSE 'N'
		END
	FROM config 
	WHERE config.ayear = @yvar
	CREATE TABLE #detail
	(
		idfin int,
		finpart char(1),
		codefin varchar(50),
		title varchar(150),
		idupb varchar(36),
		codeupb varchar(50),	
		upb varchar(150),
		descriptionvar varchar(150),
		flagprevision char(1),
		flagsecondaryprev char(1),
		description varchar(8000),
		amount decimal(19,2),
		nvar int
	)
IF @reportkind = 'PREVISIONE'
BEGIN
	insert into #detail(
		idfin,
		finpart ,
		codefin ,
		title ,
		idupb ,
		codeupb,	
		upb ,
		descriptionvar,
		flagprevision,
		flagsecondaryprev,
		description ,
		amount ,
		nvar
	)
	SELECT   	
		fin.idfin,
		CASE
		when (( fin.flag & 1)=0) then 'E'
		when (( fin.flag & 1)=1) then 'S'
		End,
		fin.codefin,
		fin.title,
		upb.idupb,
		upb.codeupb,
		upb.title,
		finvar.description,
		finvar.flagprevision,
		finvar.flagsecondaryprev,
		finvardetail.description,
		finvardetail.amount,
		CASE
		when (@kindnumeration='P') then finvar.nvar
		when (@kindnumeration='O') then finvar.nofficial
		End
	FROM finvardetail
	JOIN finvar 
		ON finvardetail.yvar = finvar.yvar AND finvardetail.nvar = finvar.nvar
	JOIN fin
		ON fin.idfin = finvardetail.idfin
	JOIN upb
		ON upb.idupb = finvardetail.idupb 
	WHERE finvardetail.yvar = @yvar
		AND (finvar.idenactment = @idenactment)
		AND (@idsor01 IS NULL OR upb.idsor01 = @idsor01)
		AND (@idsor02 IS NULL OR upb.idsor02 = @idsor02)
		AND (@idsor03 IS NULL OR upb.idsor03 = @idsor03)
		AND (@idsor04 IS NULL OR upb.idsor04 = @idsor04)
		AND (@idsor05 IS NULL OR upb.idsor05 = @idsor05)
	ORDER BY finvardetail.nvar, fin.flag, fin.codefin,upb.codeupb
END
IF (@showupb='S') --> Rimane come prima
  Begin
	SELECT 
		finpart ,
		CASE 
			WHEN (@showcategory)='S'
			   THEN fin.codefin 
			ELSE  #detail.codefin
		END as codefin,
		CASE 
			WHEN (@showcategory)='S'
			   THEN fin.title 
			ELSE  #detail.title
		END as title,
		idupb ,
		codeupb,	
		upb ,
		descriptionvar,
		flagprevision,
		flagsecondaryprev,
		description ,
		amount,
		nvar,
		@previsionkind as 'previsionkind',
		@secprevisionkind as 'secprevisionkind'
	FROM #detail
	JOIN finlink
		ON #detail.idfin = finlink.idchild and finlink.nlevel = @nlevelcategory
	JOIN fin
		ON finlink.idparent=fin.idfin
	ORDER BY nvar,finpart, #detail.codefin
  End
ELSE  --> Ora non vogliamo vedere l'upb e dobbiamo analizzare @compress
  Begin
		CREATE TABLE #detailcompact
		(
			idfin int ,
			finpart char(1),
			codefin varchar(50),
			title varchar(150),
			descriptionvar varchar(150),
			flagprevision char(1),
			flagsecondaryprev char(1),
			description varchar(8000),
			amount decimal(19,2),
			nvar int	
		)
		INSERT INTO #detailcompact(idfin,finpart,codefin,title,descriptionvar,flagprevision,
			flagsecondaryprev,amount, nvar)
		SELECT 
			idfin, 
		  	finpart,
			codefin ,
			title ,
			descriptionvar,
			flagprevision,
			flagsecondaryprev,
			isnull(sum(amount),0),
			nvar 
		FROM #detail
		GROUP BY nvar,finpart,idfin, codefin,title,descriptionvar,flagprevision,flagsecondaryprev
		DECLARE @finpart char(1)
		DECLARE @idfin int
		DECLARE @nvar int
		
		DECLARE @description varchar(200)
		DECLARE @descriptioncompact varchar(8000) 
		DECLARE rowcursor INSENSITIVE CURSOR FOR
			SELECT DISTINCT finpart,idfin,description,nvar
			FROM #detail
			FOR READ ONLY
		OPEN rowcursor FETCH  NEXT FROM rowcursor INTO @finpart,@idfin,@description, @nvar 
		WHILE @@FETCH_STATUS = 0
		BEGIN 
			UPDATE #detailcompact 
			SET description = 
			CASE 
				WHEN ((len(isnull(#detailcompact.description,'')) + len(@description)) < 8000 )
				   THEN ISNULL(#detailcompact.description,'') + @description + ';'
				ELSE  ISNULL(#detailcompact.description,'') + '...;'
			END
			WHERE (idfin = @idfin and finpart = @finpart and nvar = @nvar)
		
			FETCH NEXT FROM rowcursor INTO  @finpart,@idfin,@description,@nvar 
		END 
		DEALLOCATE rowcursor
		
		SELECT 	finpart ,
			CASE 
				WHEN (@showcategory)='S'
				   THEN fin.codefin 
				ELSE  #detailcompact.codefin
			END as codefin,
			CASE 
				WHEN (@showcategory)='S'
				   THEN fin.title
				ELSE  #detailcompact.title
			END as title,
			null as idupb ,
			null as codeupb,	
			null as upb ,
			descriptionvar, 
			flagprevision,
			flagsecondaryprev,
			substring(description,1,len(description)-1) as description,    
			isnull(amount,0) as amount,
			#detailcompact.nvar,
			@previsionkind as 'previsionkind',
			@secprevisionkind as 'secprevisionkind'
		FROM #detailcompact
		JOIN finlink
			ON #detailcompact.idfin = finlink.idchild and finlink.nlevel = @nlevelcategory
		JOIN fin
			ON finlink.idparent=fin.idfin
		ORDER BY nvar,finpart, #detailcompact.codefin
	  End	
	 
END

GO

print 'rpt_atto_previsione_crediti_cassa OK'

GO
if object_id('[rpt_buono_ordine_annullamenti]') is not null
	drop PROCEDURE [rpt_buono_ordine_annullamenti]
go


CREATE        PROCEDURE [rpt_buono_ordine_annullamenti]
	@yman int,
	@nman int,
	@mandatekind varchar(20),
	@datarifer smalldatetime
AS BEGIN
CREATE TABLE #mandatedetail
(
	yman int,
	nman int,
	idmankind varchar(20),
	detaildescription varchar(150),
	annotations varchar(400),
	npackage decimal(19,2),
	taxable decimal(19,5),
	taxrate float,
	tax decimal(19,2),
	discount float,
	start datetime,
	stop datetime
)
INSERT INTO #mandatedetail
(
	yman,
	nman,
	idmankind ,
	detaildescription,
	annotations,
	npackage,
	taxable,
	taxrate,
	tax,
	discount,
	start,
	stop 
)
SELECT 
	@yman,
	@nman,
	@mandatekind,
	detaildescription,
	annotations,
	npackage,
	sum(taxable),
	taxrate,
	sum(tax),
	discount,
	start,
	stop
FROM    mandatedetail
WHERE   mandatedetail.yman = @yman
	AND mandatedetail.idmankind= @mandatekind
	AND mandatedetail.nman = @nman
GROUP BY  detaildescription,annotations,npackage,
	taxrate,discount,start,stop,idgroup
SELECT 
	@yman,
	@nman,
	mandatekind.description as mandatekind,
	mandate.exchangerate ,
	#mandatedetail.detaildescription + ' ' + isnull( #mandatedetail.annotations,'') as uniondescr,
	ISNULL(#mandatedetail.npackage, 0) as number,
	ISNULL(#mandatedetail.taxable, 0.0) as taxable,
	ISNULL(#mandatedetail.taxrate, 0.0) as taxrate,
	ISNULL(#mandatedetail.discount, 0.0)as discount ,
	CASE 
		WHEN ((currency.codecurrency IS NULL) OR (currency.codecurrency = 'ITL') OR (currency.codecurrency = 'EUR')) THEN 'N'
		ELSE 'S'
	END as is_english,
	#mandatedetail.start,
	#mandatedetail.stop,
	CONVERT(DECIMAL(19,2),
		ROUND(
		      #mandatedetail.taxable*
		      #mandatedetail.npackage*
		      CONVERT(DECIMAL(19,6),mandate.exchangerate)*
		      (1-CONVERT(DECIMAL(19,6),ISNULL(#mandatedetail.discount,0.0))),2
  		     )
	) as rowtaxable,
-- Per evitare perdita di informazione, da cui conseguono errori di arrotondamento, il campo totaleriga 
-- deve essere calcolato come la somma dell'imponibile scontato + il calcolo dell'aliquota
	CONVERT(DECIMAL(19,2),
		ROUND(
		      #mandatedetail.taxable*
		      #mandatedetail.npackage*
		      CONVERT(DECIMAL(19,6),mandate.exchangerate)*
		      (1-CONVERT(DECIMAL(19,6),ISNULL(#mandatedetail.discount,0.0))),2
  		     )
	)+
	ROUND(#mandatedetail.tax,2) as rowtotal,
----------------------------------------------------------------------------------------------------------
--------------------------------------- ORDINI IN VALUTA ESTERA ------------------------------------------
----------------------------------------------------------------------------------------------------------
	CONVERT(DECIMAL(19,2),
		ROUND(
			  #mandatedetail.taxable*
			  #mandatedetail.npackage*
			  (1-CONVERT(DECIMAL(19,6),ISNULL(#mandatedetail.discount,0))),2
			 )
	) AS rowtaxable_fcurrency,
	-- Il campo totaleriga in valuta estera  deve essere calcolato come la somma dell'imponibile scontato + l'iva  
	-- non considera iva
	CONVERT(DECIMAL(19,2),
		ROUND(
			  #mandatedetail.taxable*
			  #mandatedetail.npackage*
			  (1-CONVERT(DECIMAL(19,6),ISNULL(#mandatedetail.discount,0))),2
			 )
	+
	ROUND(#mandatedetail.tax,2) )
 AS totalrow_fcurrency
----------------------------------------------------------------------------------------------------------
----------------------------------------------------------------------------------------------------------
----------------------------------------------------------------------------------------------------------
FROM mandate
JOIN #mandatedetail
	ON mandate.yman = #mandatedetail.yman
	AND mandate.nman = #mandatedetail.nman
	AND mandate.idmankind = #mandatedetail.idmankind
JOIN mandatekind
	ON mandatekind.idmankind = mandate.idmankind
LEFT OUTER JOIN currency
	ON currency.idcurrency = mandate.idcurrency
WHERE mandate.yman = @yman
	AND   mandate.idmankind = @mandatekind
	AND mandate.nman = @nman
	AND #mandatedetail.stop is not  null      
	AND #mandatedetail.stop <= @datarifer 
ORDER BY #mandatedetail.stop ASC
	
END


GO

print '[rpt_buono_ordine_annullamenti] OK'

GO
if object_id('[rpt_missione_ritenuta]') is not null
	drop PROCEDURE [rpt_missione_ritenuta]
go

CREATE               PROCEDURE [rpt_missione_ritenuta]
	@yitineration smallint, 
	@nitineration int
AS
BEGIN
SELECT 
	tax.description AS ritenuta,
	CASE tax.taxkind
		WHEN 1 THEN 'Fiscale'
		WHEN 2 THEN 'Assistenziale'
		WHEN 3 THEN 'Previdenziale'
		WHEN 4 THEN 'Assicurativa'
		WHEN 5 THEN 'Arretrati'
		WHEN 6 THEN 'Altro'
	ELSE ''
	END AS taxkind,
	itinerationtax.taxable,
	itinerationtax.adminrate*100 AS aliquotaamministrazione,
	itinerationtax.employrate*100 AS aliquotadipendente,
	itinerationtax.admintax,
	itinerationtax.employtax
FROM itinerationtax
join itineration on itineration.iditineration = itinerationtax.iditineration 
JOIN tax
	ON itinerationtax.taxcode = tax.taxcode
WHERE yitineration = @yitineration	
	AND nitineration = @nitineration	
ORDER BY ritenuta ASC
END


GO

print '[rpt_missione_ritenuta] OK'

GO
if object_id('[rpt_buono_ordine_contabilizzato]') is not null
	drop PROCEDURE [rpt_buono_ordine_contabilizzato]
go

CREATE          PROCEDURE [rpt_buono_ordine_contabilizzato]
	@ayear	int,
	@printkind	char(1),
	@mandatekind    varchar(20),
	@startnman	int,
	@stopnman	int,
	@official	char(1),
	@includevariation	char(1),
	@variationdate	smalldatetime
AS BEGIN
IF (@ayear=0)
BEGIN
	SET @ayear='1900'
END
CREATE TABLE #printing
(
	nman int  
)
IF @printkind = 'A' 
	INSERT INTO #printing (nman) 
	SELECT nman from  mandate  where (yman=@ayear) and (idmankind =@mandatekind) and (officiallyprinted <>'S')
	
IF @printkind <> 'A'
	INSERT INTO #printing (nman) 
	SELECT nman from  mandate where (yman=@ayear) and (idmankind =@mandatekind) and (nman BETWEEN @startnman AND @stopnman)
CREATE TABLE #mandate
(
	yman int,
	nman int,
	idmankind varchar(20),
	idreg int,
	idexpirationkind int,
	idcurrency int,
	exchangerate decimal(19,6),
	idman int,
	numintegration int ,
	numannulled int  
)
INSERT INTO #mandate
(
	yman,
	nman,
	idmankind,
	idreg,
	idexpirationkind,
	idcurrency,
	exchangerate,
	idman,
	numintegration,
	numannulled
)
SELECT 
	mandate.yman,
	mandate.nman,
	mandate.idmankind,
	mandate.idreg,
	mandate.idexpirationkind,
	mandate.idcurrency,
	mandate.exchangerate,
	mandate.idman,
	0,
	0
FROM mandate
WHERE mandate.yman = @ayear
	AND mandate.nman in (SELECT nman FROM #printing)
	AND mandate.idmankind= @mandatekind
DECLARE @dateindi smalldatetime
SELECT @dateindi= convert( smalldatetime, '31-12-'+ convert(varchar(4),@ayear), 105)
DECLARE @codenostand varchar(20)
SET @codenostand = '07_SW_ORD'
DECLARE @codestand varchar(20)
SET @codestand = '07_SW_DEF'
DECLARE @STAND int
SELECT @STAND = idaddress FROM address WHERE codeaddress = @codestand
DECLARE @NOSTAND int
SELECT @NOSTAND = idaddress FROM address WHERE codeaddress = @codenostand
CREATE TABLE #address_mandate
( 
	idaddresskind int,
	idreg int,
	officename varchar(50),
	address varchar(100),
	location varchar(120),
	cap varchar(20),
	province varchar(2),
	nation varchar(65)	 
)
INSERT INTO #address_mandate
(
	idaddresskind,
	idreg,
	officename,
	address,
	location,
	cap,
	province,
	nation
)
SELECT
	idaddresskind,
	idreg, 
	officename, 
	address,
	location = isnull(geo_city.title,'')+' ' +isnull(registryaddress.location,'')  ,
	registryaddress.cap,
	geo_country.province,
	nation =
	case 
		when flagforeign = 'N' then 'Italia'
		else geo_nation.title
	end
FROM registryaddress
left outer join geo_city
	ON geo_city.idcity = registryaddress.idcity
left outer join geo_country
	ON geo_city.idcountry = geo_country.idcountry
left outer join geo_nation
	ON geo_nation.idnation = registryaddress.idnation
WHERE ( registryaddress.active <>'N' 
	AND registryaddress.start = 
	(SELECT MAX(cdi.start) 
		FROM registryaddress cdi 
		WHERE cdi.idaddresskind = registryaddress.idaddresskind
		AND cdi.active <>'N' 
		AND cdi.start <= @dateindi
		and cdi.idreg = registryaddress.idreg))
	AND
	(idreg in (SELECT idreg from #mandate))
delete #address_mandate
	where #address_mandate.idaddresskind != @nostand
	and exists (
		select * from #address_mandate r2 
		where #address_mandate.idreg=r2.idreg
		and r2.idaddresskind = @nostand
	)
delete #address_mandate
	where #address_mandate.idaddresskind not in (@nostand, @stand)
	and exists (
		select * from #address_mandate r2 
		where #address_mandate.idreg=r2.idreg
		and r2.idaddresskind = @stand
	)
delete #address_mandate
	where (
		select count(*) from #address_mandate r2 
		where #address_mandate.idreg=r2.idreg
	)>1
	
-- Elimino dalla tabella tutti gli ordini non totalmente impegnati
DELETE FROM #mandate WHERE #mandate.nman NOT IN
(	
	SELECT nman from mandateavailable where yman=@ayear 
	and (idmankind =@mandatekind) and residual=0
)
UPDATE  #mandate 
SET numannulled= (SELECT count(*) 
		FROM mandatedetail 
	       WHERE yman = #mandate.yman AND
		     nman = #mandate.nman AND 
		     idmankind =@mandatekind AND
		     mandatedetail.stop is not null and 
		     mandatedetail.stop <= @variationdate
		)
UPDATE  #mandate 
SET numintegration= (SELECT count(*) 
		FROM mandatedetail 
	       WHERE yman = #mandate.yman AND
		     nman = #mandate.nman AND 
		     idmankind =@mandatekind AND
		     mandatedetail.start is not null and 
		     mandatedetail.start <= @variationdate
		)
SELECT
	#mandate.yman ,
	#mandate.nman ,
	mandatekind.description AS mandatekind,
	mandate.adate ,
	mandate.description ,
	mandatekind.office,
	mandatekind.phonenumber AS phonenumber_office,
	mandatekind.faxnumber AS faxnumber_office,
	mandatekind.email AS email_office,
	#mandate.idreg ,
	registry.title ,
	#address_mandate.officename, 
	#address_mandate.address, 
   	#address_mandate.location, 
  	#address_mandate.cap,
	#address_mandate.province,  
	#address_mandate.nation,
	ISNULL(registryreference.phonenumber,'') as phone,
	ISNULL(registryreference.faxnumber,'') as fax,
	registryreference.email,
	registry.p_iva,
	mandate.paymentexpiring ,
	#mandate.idexpirationkind ,
	mandate.registryreference ,
	mandate.deliveryexpiration ,
	mandate.deliveryaddress ,
	manager.title as manager,
	currency.codecurrency as idcurrency ,
	#mandate.exchangerate ,
	isnull(mandatedetail.detaildescription,'') + ' ' + isnull(mandatedetail.annotations,'') as uniondescr,
	ISNULL(mandatedetail.npackage, 0)as number ,
	upb.title as upb,
	ISNULL(mandatedetail.taxable, 0)  as taxable,
	ISNULL(mandatedetail.taxrate, 0) as taxrate ,
	ISNULL(mandatedetail.discount, 0) as discount,
		CASE 
			WHEN ((currency.codecurrency IS NULL) OR (currency.codecurrency = 'ITL') OR (currency.codecurrency = 'EUR')) THEN 'N'
			ELSE 'S'
		END 
		as is_english,
		mandatedetail.start,
		mandatedetail.stop,
		mandate.txt as notes,
		CONVERT(DECIMAL(19,2),
		ROUND(
		      mandatedetail.taxable*
		      mandatedetail.npackage*
		      CONVERT(DECIMAL(19,6),mandate.exchangerate)*
		      (1-CONVERT(DECIMAL(19,6),ISNULL(mandatedetail.discount,0.0))),2
			     )
	) as rowtaxable,
	-- Per evitare perdita di informazione, da cui conseguono errori di arrotondamento, il campo totaleriga 
	-- deve essere calcolato come la somma dell'imponibile scontato + il calcolo dell'aliquota
			CONVERT(DECIMAL(19,2),
		ROUND(
		      mandatedetail.taxable*
		      mandatedetail.npackage*
		      CONVERT(DECIMAL(19,6),mandate.exchangerate)*
		      (1-CONVERT(DECIMAL(19,6),ISNULL(mandatedetail.discount,0.0))),2
			     )
	)+
	ROUND(mandatedetail.tax,2) as rowtotal,
	#mandate.numannulled,
	#mandate.numintegration
FROM #mandate
JOIN mandate
	ON mandate.yman = #mandate.yman
	AND mandate.nman = #mandate.nman
	and mandate.idmankind = #mandate.idmankind
JOIN mandatekind  
	ON #mandate.idmankind = mandatekind.idmankind 
JOIN mandatedetail
	ON #mandate.yman = mandatedetail.yman
	AND #mandate.nman = mandatedetail.nman
	AND #mandate.idmankind = mandatedetail.idmankind
LEFT OUTER JOIN upb
	ON upb.idupb = mandatedetail.idupb
LEFT OUTER JOIN registry
	ON #mandate.idreg = registry.idreg
LEFT OUTER JOIN manager
	ON manager.idman = #mandate.idman
LEFT OUTER JOIN registryreference
	ON registryreference.idreg = #mandate.idreg
	AND registryreference.flagdefault = 'S'
LEFT OUTER JOIN expirationkind 
	ON expirationkind.idexpirationkind = #mandate.idexpirationkind
LEFT OUTER JOIN #address_mandate
	ON #mandate.idreg = #address_mandate.idreg
LEFT OUTER JOIN currency
	ON currency.idcurrency = #mandate.idcurrency
WHERE mandatedetail.start is null 
END

GO

print '[rpt_buono_ordine_contabilizzato] OK'

