if object_id('rpt_propostevarprevisione_crediti_cassa') is not null
	drop PROCEDURE rpt_propostevarprevisione_crediti_cassa
go

--exec rpt_propostevarprevisione_crediti_cassa 2013, 10,10,'cassa','S','N','N','2',null,null,null,null,null
CREATE   PROCEDURE rpt_propostevarprevisione_crediti_cassa
	@yvar          	int, 
	@nvarbegin   	int,
	@nvarend     	int,
	@reportkind    	varchar(20),
	@showupb char(1),
	@compress char(1),
	@showcategory char(1),
	@nenactment		int,
	@idman			int,
	@idsor01 int,
	@idsor02 int,
	@idsor03 int,
	@idsor04 int,
	@idsor05 int 
	AS
	BEGIN
	
	DECLARE @yenactment   		int
	DECLARE @idenactment	int
	
	SET 	@yenactment = @yvar
	SET     @idenactment = 
			 (SELECT idenactment
			    FROM enactment 
			   WHERE enactment.yenactment = @yenactment
	   		     AND enactment.nenactment = @nenactment)	
	
	IF @reportkind = 'PREVISIONE'
	BEGIN
		SELECT  --report variazioni della previsione
			finvar.yvar,
			finvar.nvar,
			finvar.description,
			finvar.enactment,
			finvar.variationkind,
			finvar.nenactment,
			finvar.enactmentdate,
			finvar.adate,
			finvar.flagprevision,
			finvar.flagcredit,
			finvar.flagproceeds,
			finvar.flagsecondaryprev,
			CASE 
				WHEN config.fin_kind IN (1,3) THEN 'C'
				WHEN config.fin_kind = 2 THEN 'S'
			END as 'previsionkind',
			CASE 
				WHEN config.fin_kind = 3 THEN 'S'
				ELSE NULL
			END as 'secprevisionkind',
			finvar.idfinvarstatus,
			finvarstatus.description as finvarstatus,
			finvar.idman,
			manager.title as manager
		FROM finvar 
		JOIN config 
			ON finvar.yvar=config.ayear	
		JOIN finvardetail
			ON finvar.yvar = finvardetail.yvar
			AND finvar.nvar = finvardetail.nvar
		JOIN upb
			ON finvardetail.idupb = upb.idupb				
		LEFT OUTER JOIN finvarstatus
				ON finvar.idfinvarstatus = finvarstatus.idfinvarstatus
		LEFT OUTER JOIN manager
				ON finvar.idman = manager.idman
		WHERE
			finvar.yvar = @yvar
			AND (flagprevision = 'S' OR flagsecondaryprev = 'S')
			AND finvar.variationkind <> 5
			AND (finvar.idenactment = @idenactment OR @idenactment IS NULL)	
			AND (finvar.idman = @idman OR @idman IS NULL)	
			AND ((finvar.nvar BETWEEN @nvarbegin AND @nvarend) OR 
		     	     (@nvarbegin IS NULL) OR (@nvarend IS NULL))
			AND (@idsor01 IS NULL OR upb.idsor01 = @idsor01)
			AND (@idsor02 IS NULL OR upb.idsor02 = @idsor02)
			AND (@idsor03 IS NULL OR upb.idsor03 = @idsor03)
			AND (@idsor04 IS NULL OR upb.idsor04 = @idsor04)
			AND (@idsor05 IS NULL OR upb.idsor05 = @idsor05)			     	     
		GROUP BY finvar.yvar, finvar.nvar, finvar.description, finvar.enactment, finvar.variationkind, finvar.nenactment,
			finvar.enactmentdate, finvar.adate, finvar.flagprevision, finvar.flagcredit,
			finvar.flagproceeds, finvar.flagsecondaryprev, config.fin_kind,	finvar.idfinvarstatus,	finvarstatus.description,finvar.idman,
			manager.title 
		ORDER BY finvar.nvar
		
	END
	IF @reportkind = 'CREDITI'
	BEGIN
		SELECT  --report variazioni dei crediti
			finvar.yvar,
			finvar.nvar,
			finvar.description,
			finvar.enactment,
			finvar.variationkind,
			finvar.flagcredit,
			finvar.flagproceeds,
			finvar.nenactment,
			finvar.enactmentdate,
			finvar.adate,
			NULL as 'flagprevision',
			NULL as 'flagsecondaryprev',
			NULL as 'previsionkind' ,
			NULL as 'secprevisionkind',
			finvar.idfinvarstatus,
			finvarstatus.description as finvarstatus,
			finvar.idman,
			manager.title as manager
		FROM finvar 
		JOIN finvardetail
			ON finvar.yvar = finvardetail.yvar
			AND finvar.nvar = finvardetail.nvar
		JOIN upb
			ON finvardetail.idupb = upb.idupb				
		LEFT OUTER JOIN finvarstatus
				ON finvar.idfinvarstatus = finvarstatus.idfinvarstatus
		LEFT OUTER JOIN manager
				ON finvar.idman = manager.idman
			WHERE
				finvar.yvar = @yvar
				and finvar.flagcredit = 'S'
				and (finvar.idenactment = @idenactment or @idenactment IS NULL)	
				AND (finvar.idman = @idman OR @idman IS NULL)	
				and ((finvar.nvar BETWEEN @nvarbegin and @nvarend) or 
			     	     (@nvarbegin IS NULL) or (@nvarend IS NULL))
				AND (@idsor01 IS NULL OR upb.idsor01 = @idsor01)
				AND (@idsor02 IS NULL OR upb.idsor02 = @idsor02)
				AND (@idsor03 IS NULL OR upb.idsor03 = @idsor03)
				AND (@idsor04 IS NULL OR upb.idsor04 = @idsor04)
				AND (@idsor05 IS NULL OR upb.idsor05 = @idsor05)		
		GROUP BY finvar.yvar, finvar.nvar,finvar.description,finvar.enactment,finvar.variationkind,
			finvar.flagcredit,	finvar.flagproceeds,finvar.nenactment,finvar.enactmentdate,	finvar.adate,
			finvar.idfinvarstatus,	finvarstatus.description ,finvar.idman,manager.title
		ORDER BY finvar.nvar
		END
	IF @reportkind = 'CASSA'
	BEGIN
		SELECT  --report variazioni della cassa
			finvar.yvar,
			finvar.nvar,
			finvar.description,
			finvar.enactment,
			finvar.variationkind,
			finvar.flagcredit,
			finvar.flagproceeds,
			finvar.nenactment,
			finvar.enactmentdate,
			finvar.adate,
			NULL as 'flagprevision',
			NULL as 'flagsecondaryprev',
			NULL as 'previsionkind' ,
			NULL as 'secprevisionkind',
			finvar.idfinvarstatus,
			finvarstatus.description as finvarstatus,
			finvar.idman,
			manager.title as manager
		FROM finvar 
		JOIN finvardetail
			ON finvar.yvar = finvardetail.yvar
			AND finvar.nvar = finvardetail.nvar
		JOIN upb
			ON finvardetail.idupb = upb.idupb				
		LEFT OUTER JOIN finvarstatus
			ON finvar.idfinvarstatus = finvarstatus.idfinvarstatus
		LEFT OUTER JOIN manager
			ON finvar.idman = manager.idman
			WHERE
				finvar.yvar = @yvar
				and flagproceeds = 'S'
				and (finvar.idenactment = @idenactment or @idenactment IS NULL)	
				AND (finvar.idman = @idman OR @idman IS NULL)	
				and ((finvar.nvar BETWEEN @nvarbegin AND @nvarend) or 
			     	     (@nvarbegin IS NULL) or (@nvarend IS NULL))
				AND (@idsor01 IS NULL OR upb.idsor01 = @idsor01)
				AND (@idsor02 IS NULL OR upb.idsor02 = @idsor02)
				AND (@idsor03 IS NULL OR upb.idsor03 = @idsor03)
				AND (@idsor04 IS NULL OR upb.idsor04 = @idsor04)
				AND (@idsor05 IS NULL OR upb.idsor05 = @idsor05)	
			GROUP BY finvar.yvar,finvar.nvar,finvar.description,finvar.enactment,finvar.variationkind,
			finvar.flagcredit,finvar.flagproceeds,	finvar.nenactment,	finvar.enactmentdate,
			finvar.adate,	finvar.idfinvarstatus,	finvarstatus.description,	finvar.idman,		manager.title			     	     
			ORDER BY finvar.nvar
		END 
END



GO

print 'rpt_propostevarprevisione_crediti_cassa OK'

GO
if object_id('[compute_ivapayincome]') is not null
	drop PROCEDURE [compute_ivapayincome]
go

CREATE             PROCEDURE [compute_ivapayincome]
	@ayear int,
	@datebegin datetime,
	@dateend datetime,
	@prorata decimal(19,6),
	@mixed decimal(19,6)
AS BEGIN
	-- Tabella di output (dei documenti)
	CREATE TABLE #invoice
	(
		idinvkind int,
		yinv int,
		ninv int,
		idivaregisterkind int,
		registerclass char(1),
		flagmixed char(1),
		flagdeferred char(1),
		ivatotal decimal(19,2),
		totivaunabatable decimal(19,2),
		currivaunabatable decimal(19,2),
		mixedamount decimal(19,2),
		taxabletotal decimal(19,2),
		previvatotalpayed decimal(19,2),
		prevtotalpayed decimal(19,2),
		currivagrosspayed decimal(19,2),
		currivapayed decimal(19,2),
		currtotalpayed decimal(19,2)
	)
	-- Tabella delle vecchie liquidazioni
	CREATE TABLE #oldivapay
	(
		idivaregisterkind int,
		iva decimal(19,2),
		unabatable decimal(19,2),
		flagmixed char(1)
	)
	
	-- Riempimento delle vecchie liquidazioni
	-- Si selezionano solamente le liquidazioni che ricadono nello stesso
	-- periodo della liquidazione corrente
	INSERT INTO #oldivapay (idivaregisterkind, iva, unabatable)
	(SELECT
		ivapaydetail.idivaregisterkind, SUM(ivapaydetail.iva), SUM(ivapaydetail.unabatable)
	FROM ivapay
	JOIN ivapaydetail
		ON ivapay.yivapay = ivapaydetail.yivapay
		AND ivapay.nivapay = ivapaydetail.nivapay
	JOIN ivaregisterkind
		ON ivaregisterkind.idivaregisterkind = ivapaydetail.idivaregisterkind
	WHERE ivapay.start >= @datebegin
		AND ivapay.stop <= @dateend
		AND ivaregisterkind.registerclass = 'A'
	GROUP BY ivapaydetail.idivaregisterkind)
	-- Si aggiorna la tabella delle liquidazioni impostando il flagmixed
	-- in base al tipo del registro
	UPDATE #oldivapay SET flagmixed = 'S'
	WHERE EXISTS(
		(SELECT * FROM invoicekind
		JOIN invoicekindregisterkind
		ON invoicekind.idinvkind = invoicekindregisterkind.idinvkind
		JOIN ivaregisterkind
		ON ivaregisterkind.idivaregisterkind = invoicekindregisterkind.idivaregisterkind
		WHERE invoicekindregisterkind.idivaregisterkind = #oldivapay.idivaregisterkind
		AND ivaregisterkind.registerclass = 'A'
		AND ((invoicekind.flag & 2) <> 0)))
	UPDATE #oldivapay SET flagmixed = 'N'
	WHERE NOT EXISTS(
		(SELECT * FROM invoicekind
		JOIN invoicekindregisterkind
		ON invoicekind.idinvkind = invoicekindregisterkind.idinvkind
		JOIN ivaregisterkind
		ON ivaregisterkind.idivaregisterkind = invoicekindregisterkind.idivaregisterkind
		WHERE invoicekindregisterkind.idivaregisterkind = #oldivapay.idivaregisterkind
		AND ivaregisterkind.registerclass = 'A'
		AND ((invoicekind.flag & 2) <> 0)))
	-- Sezione 2. Calcolo dell'IVA a Credito
	-- Sezione 2.1. IVA Immediata
	-- Sezione 2.1.1. IVA Immediata Non Promiscua
	-- Calcolo sulle Fatture
	-- Si considerano tutte le fatture di acquisto la cui data di registrazione
	-- ricade nel range di date fornito in input alla SP
	INSERT INTO #invoice
	(
		idinvkind, yinv, ninv, registerclass, flagdeferred, flagmixed, idivaregisterkind,
		currivagrosspayed,currivaunabatable, currivapayed
	)
	(SELECT
		I.idinvkind,I.yinv, I.ninv, 'A', 'N', 'N', IRK.idivaregisterkind,
		ISNULL(SUM(ROUND(I_DET.tax * I.exchangerate, 2)), 0),
		ISNULL(SUM(ROUND(I_DET.unabatable * I.exchangerate, 2)), 0),
		ISNULL(SUM(ROUND((ISNULL(I_DET.tax,0) - ISNULL(I_DET.unabatable,0)) * I.exchangerate
		* ISNULL(@prorata,0)
		, 2)), 0)
	FROM ivaregister IR
	JOIN invoice I
		ON I.idinvkind = IR.idinvkind
		AND I.yinv = IR.yinv
		AND I.ninv = IR.ninv
	JOIN ivaregisterkind IRK
		ON IRK.idivaregisterkind = IR.idivaregisterkind
	JOIN invoicekind IK
		ON IK.idinvkind = IR.idinvkind
	JOIN invoicedetail I_DET
		ON I_DET.idinvkind = IR.idinvkind
		AND I_DET.yinv = IR.yinv
		AND I_DET.ninv = IR.ninv
	LEFT OUTER JOIN #oldivapay OIP
		ON IR.idivaregisterkind = OIP.idivaregisterkind
	WHERE IRK.registerclass = 'A'
		AND ((IK.flag & 2) = 0)
		AND ((IK.flag & 4) = 0)
		AND I.adate BETWEEN @datebegin AND @dateend
		AND I.flagdeferred = 'N'
	GROUP BY I.idinvkind,I.yinv, I.ninv, IRK.idivaregisterkind,
	OIP.iva, OIP.unabatable)
	
	-- Calcolo sulle Note di Credito
	-- Si considerano tutte le note di credito la cui data di registrazione
	-- ricade nel range di date fornito in input alla SP
	INSERT INTO #invoice
	(
		idinvkind, yinv, ninv, registerclass, flagdeferred, flagmixed, idivaregisterkind,
		currivagrosspayed,currivaunabatable, currivapayed
	)
	(SELECT
		I.idinvkind,I.yinv, I.ninv, 'A', 'N', 'N', IRK.idivaregisterkind,
		- ISNULL(SUM(ROUND(I_DET.tax * I.exchangerate, 2)), 0),
		- ISNULL(SUM(ROUND(I_DET.unabatable * I.exchangerate, 2)), 0),
		- ISNULL(SUM(ROUND((ISNULL(I_DET.tax,0) - ISNULL(I_DET.unabatable,0)) * I.exchangerate
		* ISNULL(@prorata,0)
		, 2)), 0)
	FROM ivaregister IR
	JOIN invoice I
		ON I.idinvkind = IR.idinvkind
		AND I.yinv = IR.yinv
		AND I.ninv = IR.ninv
	JOIN ivaregisterkind IRK
		ON IRK.idivaregisterkind = IR.idivaregisterkind
	JOIN invoicekind IK
		ON IK.idinvkind = IR.idinvkind
	JOIN invoicedetail I_DET
		ON I_DET.idinvkind = IR.idinvkind
		AND I_DET.yinv = IR.yinv
		AND I_DET.ninv = IR.ninv
	LEFT OUTER JOIN #oldivapay OIP
	ON IR.idivaregisterkind = OIP.idivaregisterkind
	WHERE IRK.registerclass = 'A'
		AND ((IK.flag & 2) = 0)
		AND ((IK.flag & 4) <> 0)
		AND I.adate BETWEEN @datebegin AND @dateend
		AND I.flagdeferred = 'N'
	GROUP BY I.idinvkind,I.yinv, I.ninv, IRK.idivaregisterkind,
	OIP.iva, OIP.unabatable)
	-- Sezione 2.1.2. IVA Immediata Promiscua
	-- Calcolo sulle Fatture
	INSERT INTO #invoice
	(
		idinvkind,yinv,ninv,registerclass,flagdeferred, flagmixed, idivaregisterkind,
		currivagrosspayed,currivaunabatable, mixedamount, currivapayed
	)
	(SELECT
		I.idinvkind,I.yinv, I.ninv, 'A', 'N', 'S', IRK.idivaregisterkind,
		ISNULL(SUM(ROUND(I_DET.tax * I.exchangerate, 2)), 0),
		ISNULL(SUM(ROUND(I_DET.unabatable * I.exchangerate, 2)), 0),
		ISNULL(SUM(ROUND((I_DET.tax - I_DET.unabatable) * I.exchangerate
		* ISNULL(@mixed,0)
		, 2)), 0),
		ISNULL(SUM(ROUND((I_DET.tax - I_DET.unabatable) * I.exchangerate
		* ISNULL(@mixed,0) * ISNULL(@prorata,0)
		, 2)), 0)
	FROM ivaregister IR
	JOIN invoice I
		ON I.idinvkind = IR.idinvkind
		AND I.yinv = IR.yinv
		AND I.ninv = IR.ninv
	JOIN ivaregisterkind IRK
		ON IRK.idivaregisterkind = IR.idivaregisterkind
	JOIN invoicekind IK
		ON IK.idinvkind = IR.idinvkind
	JOIN invoicedetail I_DET
		ON I_DET.idinvkind = IR.idinvkind
		AND I_DET.yinv = IR.yinv
		AND I_DET.ninv = IR.ninv
	LEFT OUTER JOIN #oldivapay OIP
		ON IR.idivaregisterkind = OIP.idivaregisterkind
	WHERE IRK.registerclass = 'A'
		AND ((IK.flag & 2) <> 0)
		AND ((IK.flag & 4) = 0)
		AND I.adate BETWEEN @datebegin AND @dateend
		AND I.flagdeferred = 'N'
	GROUP BY I.idinvkind,I.yinv, I.ninv, IRK.idivaregisterkind,
	OIP.iva, OIP.unabatable)
	
	-- Calcolo sulle Note di Credito
	INSERT INTO #invoice
	(
		idinvkind,yinv,ninv,registerclass,flagdeferred, flagmixed, idivaregisterkind,
		currivagrosspayed,currivaunabatable, mixedamount, currivapayed
	)
	(SELECT
		I.idinvkind,I.yinv, I.ninv, 'A', 'N', 'S', IRK.idivaregisterkind,
		- ISNULL(SUM(ROUND(I_DET.tax * I.exchangerate, 2)), 0),
		- ISNULL(SUM(ROUND(I_DET.unabatable * I.exchangerate, 2)), 0),
		- ISNULL(SUM(ROUND((I_DET.tax - I_DET.unabatable) * I.exchangerate
		* ISNULL(@mixed,0), 2)), 0),
		- ISNULL(SUM(ROUND((I_DET.tax - I_DET.unabatable) * I.exchangerate
		* ISNULL(@mixed,0) * ISNULL(@prorata,0), 2)), 0)
	FROM ivaregister IR
	JOIN invoice I
		ON I.idinvkind = IR.idinvkind
		AND I.yinv = IR.yinv
		AND I.ninv = IR.ninv
	JOIN ivaregisterkind IRK
		ON IRK.idivaregisterkind = IR.idivaregisterkind
	JOIN invoicekind IK
		ON IK.idinvkind = IR.idinvkind
	JOIN invoicedetail I_DET
		ON I_DET.idinvkind = IR.idinvkind
		AND I_DET.yinv = IR.yinv
		AND I_DET.ninv = IR.ninv
	LEFT OUTER JOIN #oldivapay OIP
		ON IR.idivaregisterkind = OIP.idivaregisterkind
	WHERE IRK.registerclass = 'A'
		AND ((IK.flag & 2) <> 0)
		AND ((IK.flag & 4) <> 0)
		AND I.adate BETWEEN @datebegin AND @dateend
		AND I.flagdeferred = 'N'
	GROUP BY I.idinvkind,I.yinv, I.ninv, IRK.idivaregisterkind, OIP.iva, OIP.unabatable)
	
	DECLARE @expensemaxphase char(1)
	SELECT @expensemaxphase = MAX(nphase) FROM expensephase
	
	-- Sezione 2.2. IVA Differita
	-- Calcolo sulle Fatture
	-- Si selezionano tutti i dettagli delle fatture di acquisto con contabilizzazione dell'imposta e/o totale (IMPOS e DOCUM)
	-- il cui mandato è stato trasmesso nel range di date fornite in input alla SP
	INSERT INTO #invoice
	(
		idinvkind, yinv, ninv, flagdeferred, registerclass, flagmixed, idivaregisterkind,
		ivatotal, taxabletotal, totivaunabatable,
		previvatotalpayed, prevtotalpayed,
		currivagrosspayed,
		currivaunabatable,
		mixedamount,
		currivapayed
	)
	(SELECT
		I.idinvkind, I.yinv, I.ninv, 'S', 'A',
		CASE
			WHEN (IK.flag & 2) <> 0 THEN 'S'
			ELSE 'N'
		END,
		IRK.idivaregisterkind, 
		TIV.ivatotal, TIV.taxabletotal, TIV.unabatabletotal, 
		SUM(I_D.ivatotalpayed), SUM(I_D.totalpayed),
		ISNULL(
			(SELECT SUM(ROUND(ISNULL(I_DET.tax,0) * I2.exchangerate,2))
			FROM invoicedetail I_DET
			JOIN invoice I2
				ON I2.idinvkind = I_DET.idinvkind
				AND I2.yinv = I_DET.yinv
				AND I2.ninv = I_DET.ninv
			JOIN paymentcommunicated PC1
				ON PC1.idexp = I_DET.idexp_iva
			WHERE I.idinvkind = I_DET.idinvkind
				AND I.yinv = I_DET.yinv
				AND I.ninv = I_DET.ninv
				AND I_DET.paymentcompetency IS  NULL
				AND PC1.competencydate BETWEEN @datebegin AND @dateend)
		,0) -
		ISNULL(
			(SELECT ISNULL(SUM(I_D1.ivatotalpayed),0)
			FROM invoicedeferred I_D1
			JOIN ivapay IP
				ON I_D1.yivapay = IP.yivapay
				AND I_D1.nivapay = IP.nivapay
			WHERE IP.start >= @datebegin AND IP.stop <= @dateend
				AND I_D1.idinvkind = I.idinvkind
				AND I_D1.yinv = I.yinv
				AND I_D1.ninv = I.ninv)
		,0),
		-- currivaunabatable
		ISNULL(
			(SELECT SUM(ROUND(ISNULL(I_DET.unabatable,0) * I2.exchangerate,2))
			FROM invoicedetail I_DET
			JOIN invoice I2
				ON I2.idinvkind = I_DET.idinvkind
				AND I2.yinv = I_DET.yinv
				AND I2.ninv = I_DET.ninv
			JOIN paymentcommunicated PC1
				ON PC1.idexp = I_DET.idexp_iva
			WHERE I.idinvkind = I_DET.idinvkind
				AND I.yinv = I_DET.yinv
				AND I.ninv = I_DET.ninv
				AND I_DET.paymentcompetency IS  NULL
				AND PC1.competencydate BETWEEN @datebegin AND @dateend)
		,0) -
		ISNULL(
			(SELECT ISNULL(TIV2.unabatabletotal,0)
				* SUM(I_D2.ivatotalpayed)
				/ ISNULL(TIV2.ivatotal,0)
			FROM invoicedeferred I_D2
			JOIN totinvoiceview TIV2
				ON I_D2.idinvkind = TIV2.idinvkind
				AND I_D2.yinv = TIV2.yinv
				AND I_D2.ninv = TIV2.ninv
			JOIN ivapay IP
				ON I_D2.yivapay = IP.yivapay
				AND I_D2.nivapay = IP.nivapay
			WHERE IP.start >= @datebegin AND IP.stop <= @dateend
				AND I_D2.idinvkind = I.idinvkind
				AND I_D2.yinv = I.yinv
				AND I_D2.ninv = I.ninv
			GROUP BY I_D2.idinvkind, I_D2.yinv, I_D2.ninv, TIV2.unabatabletotal, TIV2.ivatotal)
		,0),
		-- mixedamount (Calcolo dell'IVA prima di applicare il prorata)
		CASE
			WHEN (IK.flag & 2) <> 0
			THEN
				ISNULL(
					(SELECT
						SUM(
							ROUND(
								(ISNULL(I_DET.tax,0) - ISNULL(I_DET.unabatable,0))
								* I2.exchangerate
								* ISNULL(@mixed,0)
							,2)
						)
					FROM invoicedetail I_DET
					JOIN invoice I2
						ON I2.idinvkind = I_DET.idinvkind
						AND I2.yinv = I_DET.yinv
						AND I2.ninv = I_DET.ninv
					JOIN paymentcommunicated PC1
						ON PC1.idexp = I_DET.idexp_iva
					WHERE I.idinvkind = I_DET.idinvkind
						AND I.yinv = I_DET.yinv
						AND I.ninv = I_DET.ninv
						AND I_DET.paymentcompetency IS  NULL
						AND PC1.competencydate BETWEEN @datebegin AND @dateend)
				,0) -
				ISNULL(
					(SELECT
						SUM(I_D2.ivatotalpayed) -
						(
							ISNULL(TIV2.unabatabletotal,0) *
							SUM(I_D2.ivatotalpayed) / ISNULL(TIV2.ivatotal,0)
						) * ISNULL(@mixed,0)
					FROM invoicedeferred I_D2
					JOIN totinvoiceview TIV2
						ON I_D2.idinvkind = TIV2.idinvkind
						AND I_D2.yinv = TIV2.yinv
						AND I_D2.ninv = TIV2.ninv
					JOIN ivapay IP
						ON I_D2.yivapay = IP.yivapay
						AND I_D2.nivapay = IP.nivapay
					WHERE IP.start >= @datebegin AND IP.stop <= @dateend
						AND I_D2.idinvkind = I.idinvkind
						AND I_D2.yinv = I.yinv
						AND I_D2.ninv = I.ninv
					GROUP BY I_D2.idinvkind, I_D2.yinv, I_D2.ninv, TIV2.unabatabletotal, TIV2.ivatotal)
				,0)
			ELSE NULL
		END,
		-- currivapayed
		ISNULL(
			(SELECT
				SUM(
					ROUND(
						(ISNULL(I_DET.tax,0) - ISNULL(I_DET.unabatable,0))
						* I2.exchangerate
						* ISNULL(@prorata,0) *
						CASE
							WHEN (IK2.flag & 2) <> 0 THEN ISNULL(@mixed,0)
							ELSE 1
						END
					,2)
				)
			FROM invoicedetail I_DET
			JOIN invoice I2
				ON I2.idinvkind = I_DET.idinvkind
				AND I2.yinv = I_DET.yinv
				AND I2.ninv = I_DET.ninv
			JOIN invoicekind IK2
				ON IK2.idinvkind = I2.idinvkind
			JOIN paymentcommunicated PC1
				ON PC1.idexp = I_DET.idexp_iva
			WHERE I.idinvkind = I_DET.idinvkind
				AND I.yinv = I_DET.yinv
				AND I.ninv = I_DET.ninv
				AND I_DET.paymentcompetency IS  NULL
				AND PC1.competencydate BETWEEN @datebegin AND @dateend)
		,0) -
		ISNULL(
			(SELECT
				SUM(I_D2.ivatotalpayed) -
				(
					ISNULL(TIV2.unabatabletotal,0) *
					SUM(I_D2.ivatotalpayed) / ISNULL(TIV2.ivatotal,0)
				) *
				CASE
					WHEN (IK2.flag & 2) <> 0 THEN ISNULL(@mixed,0)
					ELSE 1
				END * ISNULL(@prorata,0)
			FROM invoicedeferred I_D2
			JOIN invoicekind IK2
				ON IK2.idinvkind = I_D2.idinvkind
			JOIN totinvoiceview TIV2
				ON I_D2.idinvkind = TIV2.idinvkind
				AND I_D2.yinv = TIV2.yinv
				AND I_D2.ninv = TIV2.ninv
			JOIN ivapay IP
				ON I_D2.yivapay = IP.yivapay
				AND I_D2.nivapay = IP.nivapay
			WHERE IP.start >= @datebegin AND IP.stop <= @dateend
				AND I_D2.idinvkind = I.idinvkind
				AND I_D2.yinv = I.yinv
				AND I_D2.ninv = I.ninv
			GROUP BY I_D2.idinvkind, I_D2.yinv, I_D2.ninv, TIV2.unabatabletotal, TIV2.ivatotal, (IK2.flag & 2))
		,0)
	FROM expenseinvoice MOV
	JOIN paymentcommunicated PC
		ON PC.idexp = MOV.idexp
	JOIN invoice I
		ON MOV.idinvkind = I.idinvkind
		AND MOV.yinv = I.yinv
		AND MOV.ninv = I.ninv
	JOIN invoicekind IK
		ON IK.idinvkind = I.idinvkind
	LEFT OUTER JOIN invoicedeferred I_D
		ON I_D.idinvkind = I.idinvkind
		AND I_D.yinv = I.yinv
		AND I_D.ninv = I.ninv
	JOIN totinvoiceview TIV
		ON TIV.idinvkind = I.idinvkind
		AND TIV.yinv = I.yinv
		AND TIV.ninv = I.ninv
	JOIN ivaregister IR
		ON IR.idinvkind = I.idinvkind 
		AND IR.yinv = I.yinv
		AND IR.ninv = I.ninv
	JOIN ivaregisterkind IRK
		ON IRK.idivaregisterkind = IR.idivaregisterkind
	WHERE MOV.movkind IN (1, 2)
		AND IRK.registerclass = 'A'
		AND PC.competencydate BETWEEN @datebegin AND @dateend
		AND I.flagdeferred = 'S'
	GROUP BY I.idinvkind,I.yinv,I.ninv,MOV.movkind, (IK.flag & 2), IRK.idivaregisterkind,
	TIV.ivatotal, TIV.taxabletotal, TIV.unabatabletotal)
	
	-- Si selezionano tutti i dettagli delle fatture di acquisto ai quali è stata specificata una data di competenza
	-- ricadente nel range di date fornite in input alla SP
	INSERT INTO #invoice
	(
		idinvkind, yinv, ninv, flagdeferred, registerclass, flagmixed, idivaregisterkind,
		ivatotal, taxabletotal, totivaunabatable,
		previvatotalpayed, prevtotalpayed,
		currivagrosspayed,
		currivaunabatable,
		mixedamount,
		currivapayed
	)
	(SELECT
		I.idinvkind, I.yinv, I.ninv, 'S', 'A',
		CASE
			WHEN (IK.flag & 2) <> 0 THEN 'S'
			ELSE 'N'
		END,
		IRK.idivaregisterkind, 
		TIV.ivatotal, TIV.taxabletotal, TIV.unabatabletotal, 
		SUM(I_D.ivatotalpayed), SUM(I_D.totalpayed),
		ISNULL(
			(SELECT SUM(ROUND(ISNULL(I_DET.tax,0) * I2.exchangerate,2))
			FROM invoicedetail I_DET
			JOIN invoice I2
				ON I2.idinvkind = I_DET.idinvkind
				AND I2.yinv = I_DET.yinv
				AND I2.ninv = I_DET.ninv
			WHERE I.idinvkind = I_DET.idinvkind
				AND I.yinv = I_DET.yinv
				AND I.ninv = I_DET.ninv
				AND I_DET.paymentcompetency BETWEEN @datebegin AND @dateend
				)
		,0) -
		ISNULL(
			(SELECT ISNULL(SUM(I_D1.ivatotalpayed),0)
			FROM invoicedeferred I_D1
			JOIN ivapay IP
				ON I_D1.yivapay = IP.yivapay
				AND I_D1.nivapay = IP.nivapay
			WHERE IP.start >= @datebegin AND IP.stop <= @dateend
				AND I_D1.idinvkind = I.idinvkind
				AND I_D1.yinv = I.yinv
				AND I_D1.ninv = I.ninv)
		,0),
		-- currivaunabatable
		ISNULL(
			(SELECT SUM(ROUND(ISNULL(I_DET.unabatable,0) * I2.exchangerate,2))
			FROM invoicedetail I_DET
			JOIN invoice I2
				ON I2.idinvkind = I_DET.idinvkind
				AND I2.yinv = I_DET.yinv
				AND I2.ninv = I_DET.ninv
			WHERE I.idinvkind = I_DET.idinvkind
				AND I.yinv = I_DET.yinv
				AND I.ninv = I_DET.ninv
				AND I_DET.paymentcompetency BETWEEN @datebegin AND @dateend
				)
		,0) -
		ISNULL(
			(SELECT ISNULL(TIV2.unabatabletotal,0)
				* SUM(I_D2.ivatotalpayed)
				/ ISNULL(TIV2.ivatotal,0)
			FROM invoicedeferred I_D2
			JOIN totinvoiceview TIV2
				ON I_D2.idinvkind = TIV2.idinvkind
				AND I_D2.yinv = TIV2.yinv
				AND I_D2.ninv = TIV2.ninv
			JOIN ivapay IP
				ON I_D2.yivapay = IP.yivapay
				AND I_D2.nivapay = IP.nivapay
			WHERE IP.start >= @datebegin AND IP.stop <= @dateend
				AND I_D2.idinvkind = I.idinvkind
				AND I_D2.yinv = I.yinv
				AND I_D2.ninv = I.ninv
			GROUP BY I_D2.idinvkind, I_D2.yinv, I_D2.ninv, TIV2.unabatabletotal, TIV2.ivatotal)
		,0),
		-- mixedamount (Calcolo dell'IVA prima di applicare il prorata)
		CASE
			WHEN (IK.flag & 2) <> 0
			THEN
				ISNULL(
					(SELECT
						SUM(
							ROUND(
								(ISNULL(I_DET.tax,0) - ISNULL(I_DET.unabatable,0))
								* I2.exchangerate
								* ISNULL(@mixed,0)
							,2)
						)
					FROM invoicedetail I_DET
					JOIN invoice I2
						ON I2.idinvkind = I_DET.idinvkind
						AND I2.yinv = I_DET.yinv
						AND I2.ninv = I_DET.ninv
					WHERE I.idinvkind = I_DET.idinvkind
						AND I.yinv = I_DET.yinv
						AND I.ninv = I_DET.ninv
						AND I_DET.paymentcompetency BETWEEN @datebegin AND @dateend
						)
				,0) -
				ISNULL(
					(SELECT
						SUM(I_D2.ivatotalpayed) -
						(
							ISNULL(TIV2.unabatabletotal,0) *
							SUM(I_D2.ivatotalpayed) / ISNULL(TIV2.ivatotal,0)
						) * ISNULL(@mixed,0)
					FROM invoicedeferred I_D2
					JOIN totinvoiceview TIV2
						ON I_D2.idinvkind = TIV2.idinvkind
						AND I_D2.yinv = TIV2.yinv
						AND I_D2.ninv = TIV2.ninv
					JOIN ivapay IP
						ON I_D2.yivapay = IP.yivapay
						AND I_D2.nivapay = IP.nivapay
					WHERE IP.start >= @datebegin AND IP.stop <= @dateend
						AND I_D2.idinvkind = I.idinvkind
						AND I_D2.yinv = I.yinv
						AND I_D2.ninv = I.ninv
					GROUP BY I_D2.idinvkind, I_D2.yinv, I_D2.ninv, TIV2.unabatabletotal, TIV2.ivatotal)
				,0)
			ELSE NULL
		END,
		-- currivapayed
		ISNULL(
			(SELECT
				SUM(
					ROUND(
						(ISNULL(I_DET.tax,0) - ISNULL(I_DET.unabatable,0))
						* I2.exchangerate
						* ISNULL(@prorata,0) *
						CASE
							WHEN (IK2.flag & 2) <> 0 THEN ISNULL(@mixed,0)
							ELSE 1
						END
					,2)
				)
			FROM invoicedetail I_DET
			JOIN invoice I2
				ON I2.idinvkind = I_DET.idinvkind
				AND I2.yinv = I_DET.yinv
				AND I2.ninv = I_DET.ninv
			JOIN invoicekind IK2
				ON IK2.idinvkind = I2.idinvkind
			WHERE I.idinvkind = I_DET.idinvkind
				AND I.yinv = I_DET.yinv
				AND I.ninv = I_DET.ninv
				AND I_DET.paymentcompetency BETWEEN @datebegin AND @dateend
				)
		,0) -
		ISNULL(
			(SELECT
				SUM(I_D2.ivatotalpayed) -
				(
					ISNULL(TIV2.unabatabletotal,0) *
					SUM(I_D2.ivatotalpayed) / ISNULL(TIV2.ivatotal,0)
				) *
				CASE
					WHEN (IK2.flag & 2) <> 0 THEN ISNULL(@mixed,0)
					ELSE 1
				END * ISNULL(@prorata,0)
			FROM invoicedeferred I_D2
			JOIN invoicekind IK2
				ON IK2.idinvkind = I_D2.idinvkind
			JOIN totinvoiceview TIV2
				ON I_D2.idinvkind = TIV2.idinvkind
				AND I_D2.yinv = TIV2.yinv
				AND I_D2.ninv = TIV2.ninv
			JOIN ivapay IP
				ON I_D2.yivapay = IP.yivapay
				AND I_D2.nivapay = IP.nivapay
			WHERE IP.start >= @datebegin AND IP.stop <= @dateend
				AND I_D2.idinvkind = I.idinvkind
				AND I_D2.yinv = I.yinv
				AND I_D2.ninv = I.ninv
			GROUP BY I_D2.idinvkind, I_D2.yinv, I_D2.ninv, TIV2.unabatabletotal, 
				 TIV2.ivatotal, (IK2.flag & 2))
		,0)
	FROM invoice I
	JOIN invoicekind IK
		ON IK.idinvkind = I.idinvkind
	LEFT OUTER JOIN invoicedeferred I_D
		ON I_D.idinvkind = I.idinvkind
		AND I_D.yinv = I.yinv
		AND I_D.ninv = I.ninv
	JOIN invoicedetail I_DET1
		ON I.idinvkind = I_DET1.idinvkind
		AND I.yinv = I_DET1.yinv
		AND I.ninv = I_DET1.ninv
	JOIN totinvoiceview TIV
		ON TIV.idinvkind = I.idinvkind
		AND TIV.yinv = I.yinv
		AND TIV.ninv = I.ninv
	JOIN ivaregister IR
		ON IR.idinvkind = I.idinvkind 
		AND IR.yinv = I.yinv
		AND IR.ninv = I.ninv
	JOIN ivaregisterkind IRK
		ON IRK.idivaregisterkind = IR.idivaregisterkind
	WHERE 	(IK.flag & 1 = 0)
		AND (IK.flag & 4 = 0)
		AND IRK.registerclass = 'A'
		AND I_DET1.paymentcompetency BETWEEN @datebegin AND @dateend
		AND I.flagdeferred = 'S'
	GROUP BY I.idinvkind,I.yinv,I.ninv, (IK.flag & 2), IRK.idivaregisterkind,
	TIV.ivatotal, TIV.taxabletotal, TIV.unabatabletotal)
