					ELSE 1
				END * ISNULL(@prorata,0)
			FROM invoicedeferred I_D2
			JOIN invoicekind IK2
				ON IK2.idinvkind = I_D2.idinvkind
			JOIN totinvoiceview TIV2
				ON I_D2.idinvkind = TIV2.idinvkind
				AND I_D2.yinv = TIV2.yinv
				AND I_D2.ninv = TIV2.ninv
			JOIN ivapay IP
				ON I_D2.yivapay = IP.yivapay
				AND I_D2.nivapay = IP.nivapay
			WHERE IP.start >= @datebegin AND IP.stop <= @dateend
				AND I_D2.idinvkind = I.idinvkind
				AND I_D2.yinv = I.yinv
				AND I_D2.ninv = I.ninv
			GROUP BY I_D2.idinvkind, I_D2.yinv, I_D2.ninv, TIV2.unabatabletotal, 
			TIV2.ivatotal, (IK2.flag & 2))
		,0)
	FROM expensevar MOV
	JOIN paymentcommunicated PC
		ON PC.idexp = MOV.idexp
	JOIN invoice I
		ON MOV.idinvkind = I.idinvkind
		AND MOV.yinv = I.yinv
		AND MOV.ninv = I.ninv
	JOIN invoicekind IK
		ON IK.idinvkind = I.idinvkind
	LEFT OUTER JOIN invoicedeferred I_D
		ON I_D.idinvkind = I.idinvkind
		AND I_D.yinv = I.yinv
		AND I_D.ninv = I.ninv
	JOIN totinvoiceview TIV
		ON TIV.idinvkind = I.idinvkind
		AND TIV.yinv = I.yinv
		AND TIV.ninv = I.ninv
	JOIN ivaregister IR
		ON IR.idinvkind = I.idinvkind 
		AND IR.yinv = I.yinv
		AND IR.ninv = I.ninv
	JOIN ivaregisterkind IRK
		ON IRK.idivaregisterkind = IR.idivaregisterkind
	WHERE MOV.movkind IN (1, 2)
		AND IRK.registerclass = 'A'
		AND PC.competencydate BETWEEN @datebegin AND @dateend
		AND I.flagdeferred = 'S'
	GROUP BY I.idinvkind,I.yinv,I.ninv,MOV.movkind, (IK.flag & 2),IRK.idivaregisterkind,
		TIV.ivatotal, TIV.taxabletotal, TIV.unabatabletotal)
	
	-- Si selezionano tutte le note di credito ai quali è stata specificata una data di competenza
	-- ricadente nel range di date fornite in input alla SP
	INSERT INTO #invoice
	(
		idinvkind, yinv, ninv, flagdeferred, 
		registerclass, flagmixed, idivaregisterkind,
		ivatotal, taxabletotal, totivaunabatable,
		previvatotalpayed, prevtotalpayed,
		currivagrosspayed,
		currivaunabatable,
		mixedamount,
		currivapayed
	)
	(SELECT
		I.idinvkind, I.yinv, I.ninv, 'S', 'A',
		CASE
			WHEN IK.flag & 2 <> 0 THEN 'S'
			ELSE 'N'
		END, IRK.idivaregisterkind,
		TIV.ivatotal, TIV.taxabletotal, TIV.unabatabletotal, 
		SUM(I_D.ivatotalpayed), SUM(I_D.totalpayed),
			- ISNULL(
			(SELECT SUM(ROUND(ISNULL(I_DET.tax,0) * I2.exchangerate,2))
			FROM invoicedetail I_DET
			JOIN invoice I2
				ON I2.idinvkind = I_DET.idinvkind
				AND I2.yinv = I_DET.yinv
				AND I2.ninv = I_DET.ninv
			WHERE I.idinvkind = I_DET.idinvkind
				AND I.yinv = I_DET.yinv
				AND I.ninv = I_DET.ninv
				AND I_DET.paymentcompetency BETWEEN @datebegin AND @dateend
				)
		,0) -
		ISNULL(
			(SELECT ISNULL(SUM(I_D1.ivatotalpayed),0)
			FROM invoicedeferred I_D1
			JOIN ivapay IP
				ON I_D1.yivapay = IP.yivapay
				AND I_D1.nivapay = IP.nivapay
			WHERE IP.start >= @datebegin AND IP.stop <= @dateend
				AND I_D1.idinvkind = I.idinvkind
				AND I_D1.yinv = I.yinv
				AND I_D1.ninv = I.ninv)
		,0),
		-- currivaunabatable
		- ISNULL(
			(SELECT SUM(ROUND(ISNULL(I_DET.unabatable,0) * I2.exchangerate,2))
			FROM invoicedetail I_DET
			JOIN invoice I2
				ON I2.idinvkind = I_DET.idinvkind
				AND I2.yinv = I_DET.yinv
				AND I2.ninv = I_DET.ninv
			WHERE I.idinvkind = I_DET.idinvkind
				AND I.yinv = I_DET.yinv
				AND I.ninv = I_DET.ninv
				AND I_DET.paymentcompetency BETWEEN @datebegin AND @dateend
				)
		,0) -
		ISNULL(
			(SELECT ISNULL(TIV2.unabatabletotal,0)
				* SUM(I_D2.ivatotalpayed)
				/ ISNULL(TIV2.ivatotal,0)
			FROM invoicedeferred I_D2
			JOIN totinvoiceview TIV2
				ON I_D2.idinvkind = TIV2.idinvkind
				AND I_D2.yinv = TIV2.yinv
				AND I_D2.ninv = TIV2.ninv
			JOIN ivapay IP
				ON I_D2.yivapay = IP.yivapay
				AND I_D2.nivapay = IP.nivapay
			WHERE IP.start >= @datebegin AND IP.stop <= @dateend
				AND I_D2.idinvkind = I.idinvkind
				AND I_D2.yinv = I.yinv
				AND I_D2.ninv = I.ninv
			GROUP BY I_D2.idinvkind, I_D2.yinv, I_D2.ninv, TIV2.unabatabletotal, TIV2.ivatotal)
		,0),
		-- mixedamount (Calcolo dell'IVA prima di applicare il prorata)
		CASE
			WHEN (IK.flag & 2) <> 0
			THEN
				- ISNULL(
					(SELECT 
						SUM(
							ROUND(
								(ISNULL(I_DET.tax,0) - ISNULL(I_DET.unabatable,0))
								* I2.exchangerate
								* ISNULL(@mixed,0)
							,2)
						)
					FROM invoicedetail I_DET
					JOIN invoice I2
						ON I2.idinvkind = I_DET.idinvkind
						AND I2.yinv = I_DET.yinv
						AND I2.ninv = I_DET.ninv
					WHERE I.idinvkind = I_DET.idinvkind
						AND I.yinv = I_DET.yinv
						AND I.ninv = I_DET.ninv
						AND I_DET.paymentcompetency BETWEEN @datebegin AND @dateend
						)
				,0) -
				ISNULL(
					(SELECT
						SUM(I_D2.ivatotalpayed) -
						(
							ISNULL(TIV2.unabatabletotal,0) *
							SUM(I_D2.ivatotalpayed) / ISNULL(TIV2.ivatotal,0)
						) * ISNULL(@mixed,0)
					FROM invoicedeferred I_D2
					JOIN totinvoiceview TIV2
						ON I_D2.idinvkind = TIV2.idinvkind
						AND I_D2.yinv = TIV2.yinv
						AND I_D2.ninv = TIV2.ninv
					JOIN ivapay IP
						ON I_D2.yivapay = IP.yivapay
						AND I_D2.nivapay = IP.nivapay
					WHERE IP.start >= @datebegin AND IP.stop <= @dateend
						AND I_D2.idinvkind = I.idinvkind
						AND I_D2.yinv = I.yinv
						AND I_D2.ninv = I.ninv
					GROUP BY I_D2.idinvkind, I_D2.yinv, I_D2.ninv, 
					TIV2.unabatabletotal, TIV2.ivatotal)
				,0)
			ELSE NULL
		END,
		-- currivapayed
		- ISNULL(
			(SELECT 
				SUM(
					ROUND(
						(ISNULL(I_DET.tax,0) - ISNULL(I_DET.unabatable,0))
						* I2.exchangerate
						* ISNULL(@prorata,0) *
						CASE
							WHEN (IK2.flag & 2) <> 0 THEN ISNULL(@mixed,0)
							ELSE 1
						END
					,2)
				)
			FROM invoicedetail I_DET
			JOIN invoice I2
				ON I2.idinvkind = I_DET.idinvkind
				AND I2.yinv = I_DET.yinv
				AND I2.ninv = I_DET.ninv
			JOIN invoicekind IK2
				ON IK2.idinvkind = I2.idinvkind
			WHERE I.idinvkind = I_DET.idinvkind
				AND I.yinv = I_DET.yinv
				AND I.ninv = I_DET.ninv
				AND I_DET.paymentcompetency BETWEEN @datebegin AND @dateend)
		,0) -
		ISNULL(
			(SELECT
				SUM(I_D2.ivatotalpayed) -
				(
					ISNULL(TIV2.unabatabletotal,0) *
					SUM(I_D2.ivatotalpayed) / ISNULL(TIV2.ivatotal,0)
				) *
				CASE
					WHEN (IK2.flag & 2) <> 0 THEN ISNULL(@mixed,0)
					ELSE 1
				END * ISNULL(@prorata,0)
			FROM invoicedeferred I_D2
			JOIN invoicekind IK2
				ON IK2.idinvkind = I_D2.idinvkind
			JOIN totinvoiceview TIV2
				ON I_D2.idinvkind = TIV2.idinvkind
				AND I_D2.yinv = TIV2.yinv
				AND I_D2.ninv = TIV2.ninv
			JOIN ivapay IP
				ON I_D2.yivapay = IP.yivapay
				AND I_D2.nivapay = IP.nivapay
			WHERE IP.start >= @datebegin AND IP.stop <= @dateend
				AND I_D2.idinvkind = I.idinvkind
				AND I_D2.yinv = I.yinv
				AND I_D2.ninv = I.ninv
			GROUP BY I_D2.idinvkind, I_D2.yinv, I_D2.ninv, TIV2.unabatabletotal, 
			TIV2.ivatotal, (IK2.flag & 2))
		,0)
	FROM invoice I
	JOIN invoicekind IK
		ON IK.idinvkind = I.idinvkind
	LEFT OUTER JOIN invoicedeferred I_D
		ON I_D.idinvkind = I.idinvkind
		AND I_D.yinv = I.yinv
		AND I_D.ninv = I.ninv
	JOIN invoicedetail I_DET1
		ON I.idinvkind = I_DET1.idinvkind
		AND I.yinv = I_DET1.yinv
		AND I.ninv = I_DET1.ninv
	JOIN totinvoiceview TIV
		ON TIV.idinvkind = I.idinvkind
		AND TIV.yinv = I.yinv
		AND TIV.ninv = I.ninv
	JOIN ivaregister IR
		ON IR.idinvkind = I.idinvkind 
		AND IR.yinv = I.yinv
		AND IR.ninv = I.ninv
	JOIN ivaregisterkind IRK
		ON IRK.idivaregisterkind = IR.idivaregisterkind
	WHERE 	(IK.flag & 1 = 0)
		AND (IK.flag & 4 <> 0)
		AND IRK.registerclass = 'A'
		AND I_DET1.paymentcompetency BETWEEN @datebegin AND @dateend
		AND I.flagdeferred = 'S'
	GROUP BY I.idinvkind,I.yinv,I.ninv, (IK.flag & 2),IRK.idivaregisterkind,
		TIV.ivatotal, TIV.taxabletotal, TIV.unabatabletotal)
	-- Selezione finale che visualizza gli importi IVA raggruppati per tipo di registro, 
	-- tempo dell'IVA (se immediata o differita) e sulla gestione promiscua
	SELECT #invoice.idivaregisterkind, ivaregisterkind.description,
	SUM(currivagrosspayed)
	- ISNULL(
		(SELECT iva FROM #oldivapay
		WHERE #invoice.idivaregisterkind = #oldivapay.idivaregisterkind
		AND #invoice.flagdeferred = 'N')
	,0)
	AS iva,
	SUM(#invoice.currivaunabatable)
	- ISNULL(
		(SELECT unabatable FROM #oldivapay
		WHERE #invoice.idivaregisterkind = #oldivapay.idivaregisterkind
		AND #invoice.flagdeferred = 'N')
	,0)
	AS unabatable,
	SUM(mixedamount)
	- ISNULL(
		(SELECT ROUND((ISNULL(iva,0) - ISNULL(unabatable,0)) * ISNULL(@mixed,0),2) FROM #oldivapay
		WHERE #invoice.idivaregisterkind = #oldivapay.idivaregisterkind
		AND #invoice.flagdeferred = 'N'
		AND #oldivapay.flagmixed = 'S')
	,0)
	AS mixed,
	SUM(currivapayed)
	- ISNULL(
		(SELECT
			CASE
				WHEN #oldivapay.flagmixed = 'S'
				THEN ROUND((ISNULL(iva,0) - ISNULL(unabatable,0)) * ISNULL(@mixed,0) * ISNULL(@prorata,0),2)
				WHEN #oldivapay.flagmixed = 'N'
				THEN ROUND((ISNULL(iva,0) - ISNULL(unabatable,0)) * ISNULL(@prorata,0),2)
			END
		FROM #oldivapay
		WHERE #invoice.idivaregisterkind = #oldivapay.idivaregisterkind
		AND #invoice.flagdeferred = 'N')
	,0) AS prorata, #invoice.flagdeferred, #invoice.flagmixed
	FROM #invoice
	JOIN ivaregisterkind
	ON ivaregisterkind.idivaregisterkind = #invoice.idivaregisterkind
	GROUP BY #invoice.idivaregisterkind, ivaregisterkind.description, #invoice.flagdeferred, #invoice.flagmixed
	HAVING (SUM(currivagrosspayed)
	- ISNULL(
		(SELECT iva FROM #oldivapay
		WHERE #invoice.idivaregisterkind = #oldivapay.idivaregisterkind
		AND #invoice.flagdeferred = 'N')
	,0)) <> 0
END


