if object_id('[exp_sitbilancio_entrata]') is not null
	drop PROCEDURE [exp_sitbilancio_entrata]
go

CREATE     PROCEDURE [exp_sitbilancio_entrata]
	@ayear			int,
	@date			datetime,
	@nlevel			tinyint,
	@hierarchy		char(1),
	@idupb			varchar(36),
	@showupb 		char(1),
	@showchildupb 		char(1),
	@suppressifblank 	char(1),
	@idfin			int
AS
BEGIN
/* Versione 1.0.3 del 30/06/2008 ultima modifica: PIERO */
-- exec [exp_sitbilancio_entrata] 2008, {ts '2008-05-13 00:00:00'}, 1, 'S', '%', 'N', 'N', 'S',null
/*
Per le entrate
identificazione del bilancio (tit. cat. cap. art. denominazione e responsabile)
previsione iniziale
variazioni di bilancio
previsione attuale 
disponibile in previsione
Accertamenti (non incassati)
disponibile di previsione  per accertamento
*/
DECLARE @level_input tinyint
SET  @level_input = ISNULL((SELECT nlevel from fin where idfin = @idfin) ,@nlevel)
-- ho scelto come livello 2 e poi ho specificato il capitolo, lui corregge @nlevel dandogli 3
IF (@nlevel < @level_input) AND (@idfin is not null)
	BEGIN
	SET  @nlevel = @level_input
	END
declare @idfinincomesurplus int
select  @idfinincomesurplus=idfinincomesurplus from config where ayear=@ayear
CREATE TABLE #fin_residual
	(
	idupb 			varchar(36),
	codeupb			varchar(50),
	upb   			varchar(150),
	upbprintingorder	varchar(50),
	idfin			int,
	codefin			varchar(50),
	title			varchar(150),
	finprintingorder	varchar(50),
	flagadvance		char(1),
	nlevel			tinyint,
	initialprevision	decimal(19,2),
	var_prevision		decimal(19,2),
	sec_initial_prevision	decimal(19,2),
	varprevsec		decimal(19,2),
	assessments		decimal(19,2),
	var_assessments		decimal(19,2),
	proceeds         	decimal(19,2),
	var_proceeds          	decimal(19,2),
	flagconsider 		char(1), 	
	fin_ph_comp		decimal(19,2), 
	var_fin_ph_comp		decimal(19,2), 
	fin_ph_resid		decimal(19,2), 
	var_fin_ph_resid	decimal(19,2), 
	registry_ph_comp	decimal(19,2), 
	var_registry_ph_comp	decimal(19,2), 
	registry_ph_resid	decimal(19,2), 
	var_registry_ph_resid	decimal(19,2),
	max_ph_comp		decimal(19,2),
	max_ph_resid		decimal(19,2),
	var_max_ph_comp		decimal(19,2),
	var_max_ph_resid	decimal(19,2)
	)
IF (@ayear IS NULL) 
BEGIN
	SELECT * FROM  #fin_residual 
	RETURN
END
	
	
DECLARE @levelusable tinyint
SELECT  @levelusable = MIN(nlevel) FROM finlevel
WHERE 	ayear =@ayear and (flag&2)<>0
DECLARE @idupboriginal 	varchar(36)
SET 	@idupboriginal= @idupb
IF 	(@showchildupb = 'S') SET @idupb=@idupb+'%' 
	
DECLARE @assessmentphase     	tinyint
SELECT  @assessmentphase = assessmentphasecode
FROM 	config
WHERE 	ayear = @ayear
IF 	@assessmentphase IS NULL
BEGIN
	SELECT @assessmentphase = incomefinphase FROM uniconfig
END
DECLARE @fin_phase  tinyint -- fase accantonamento precedente alla fase di impegno, Modifica Sara
SELECT 	@fin_phase = incomefinphase FROM uniconfig
DECLARE @desc_fin_phase varchar(50)
SELECT  @desc_fin_phase=description
FROM 	incomephase WHERE nphase=@fin_phase 
DECLARE @registry_phase tinyint
SELECT  @registry_phase = incomeregphase FROM uniconfig
DECLARE @desc_registry_phase varchar(50)
SELECT  @desc_registry_phase=description
FROM    incomephase WHERE nphase=@registry_phase 

DECLARE @phasemax         	tinyint
SELECT  @phasemax = MAX(nphase)
FROM 	incomephase
DECLARE @desc_max_phase    	varchar(50)
SELECT  @desc_max_phase=description 
FROM 	incomephase WHERE nphase=@phasemax 

DECLARE @cashvaliditykind	int
SELECT 	@cashvaliditykind = cashvaliditykind
FROM 	config
WHERE 	ayear = @ayear
DECLARE @flag_cs     		char(1)
SELECT 	@flag_cs =  CASE 
		WHEN fin_kind IN (1,3) THEN 'C'
		WHEN fin_kind = 2 THEN 'S'
	 END
FROM 	config
WHERE 	ayear = @ayear
DECLARE @previsionkind char(1) 
SELECT  @previsionkind =  
	 CASE 
		WHEN fin_kind IN (1,3) THEN 'C'
		WHEN fin_kind = 2 THEN 'S'
	 END
FROM  config 
WHERE config.ayear = @ayear
DECLARE @secprevisionkind    char(1) 
SELECT  @secprevisionkind  = 
	 CASE 
		WHEN fin_kind = 3 THEN 'S'
		ELSE 'N'
	END
FROM config 
WHERE config.ayear = @ayear
IF (@hierarchy='N')
BEGIN
	IF (@suppressifblank = 'S')
	BEGIN
		INSERT INTO #fin_residual
      		(
			idfin, 
			idupb,
			flagadvance,
			var_prevision,
			varprevsec,  
			flagconsider,
			nlevel
		)
		SELECT
			F.idfin, 
			U.idupb,
			case when F.idfin=@idfinincomesurplus then 'S' else 'N' end,
			SUM(CASE WHEN finvar.flagprevision = 'S' then isnull(finvardetail.amount,0) else 0 END),
			SUM(CASE WHEN finvar.flagsecondaryprev = 'S' then isnull(finvardetail.amount,0) ELSE 0 END),
			'S',
			@nlevel
		--FROM fin F cross join upb U
		FROM upbtotal
		JOIN upb U
			ON upbtotal.idupb = U.idupb
		JOIN fin F
			ON upbtotal.idfin = F.idfin
		JOIN finlink FLK1
			ON FLK1.idchild = F.idfin AND FLK1.nlevel = @level_input
		LEFT OUTER JOIN finlink FLK2
			ON FLK2.idparent = F.idfin AND FLK2.nlevel = @nlevel
		LEFT OUTER JOIN finvardetail
		  	ON finvardetail.idfin = FLK2.idchild  
		  	AND finvardetail.idupb=U.idupb 	
		LEFT OUTER JOIN finvar
		  	ON finvar.yvar = finvardetail.yvar  and finvar.yvar = @ayear	
	  	  	AND finvar.nvar = finvardetail.nvar and finvar.adate <= @date
			AND finvar.idfinvarstatus = 5 AND finvar.variationkind <> 5
		WHERE  	((F.flag & 1 ) = 0)  and F.ayear =@ayear	
			AND (@idfin IS NULL OR FLK1.idparent = @idfin)
			AND (U.idupb like @idupb and U.active = 'S') 
			AND (F.nlevel = @nlevel)
		GROUP BY U.idupb, F.idfin, case when F.idfin=@idfinincomesurplus then 'S' else 'N' end
		
		
		-- Inserisco le coppie che hanno solo i RESIDUI
		INSERT INTO #fin_residual
	      	(
			idfin, 
			idupb,
			flagadvance,
			var_prevision,
			varprevsec,
			flagconsider,
			nlevel
		)
		SELECT DISTINCT
			F.idfin, 
			U.idupb,
			case when F.idfin=@idfinincomesurplus then 'S' else 'N' end,
			0,
			0,
			'S',
			@nlevel
		FROM incomeyear
		JOIN upb U
			ON  incomeyear.idupb = U.idupb 
		JOIN fin F
			ON  incomeyear.idfin = F.idfin 
		JOIN incometotal 
			ON incometotal.idinc = incomeyear.idinc
			AND incometotal.ayear = incomeyear.ayear
		JOIN finlink 
			ON finlink.idparent = F.idfin AND finlink.nlevel = @level_input
		WHERE  	((F.flag & 1 ) = 0) and F.ayear =@ayear	
			AND (@idfin IS NULL OR finlink.idparent = @idfin)
			AND (U.idupb like @idupb and U.active = 'S')
			AND (F.nlevel = @nlevel)
			AND NOT EXISTS (SELECT *
					  FROM #fin_residual
					  LEFT OUTER JOIN finlink FLK1 ON FLK1.idchild = incomeyear.idfin
					 WHERE incomeyear.idupb = #fin_residual.idupb 
					   AND ISNULL(FLK1.idparent,F.idfin) =  #fin_residual.idfin)
			AND incomeyear.ayear=@ayear
			AND ((incometotal.flag & 1) = 1) -- Residuo

	END
	ELSE
	BEGIN
		INSERT INTO #fin_residual
      		(
			idfin, 
			idupb,
			flagadvance,
			var_prevision,
			varprevsec,  
			flagconsider,
			nlevel
		)
		SELECT distinct
			F.idfin,
			U.idupb,
			case when F.idfin=@idfinincomesurplus then 'S' else 'N' end,
			SUM(CASE WHEN finvar.flagprevision = 'S' then isnull(finvardetail.amount,0) else 0 END),
			SUM(CASE WHEN finvar.flagsecondaryprev = 'S' then isnull(finvardetail.amount,0) ELSE 0 END),
			'S',
			@nlevel
		FROM fin F
		CROSS JOIN upb U
		JOIN finlink  FLK
			ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
		LEFT OUTER JOIN finlink FLK2
			ON FLK2.idparent = F.idfin AND FLK.nlevel = @nlevel
		LEFT OUTER JOIN finvardetail
		  	ON finvardetail.idfin = FLK2.idchild
			AND finvardetail.idupb=U.idupb 	
		LEFT OUTER JOIN finvar
		  	ON finvar.yvar = finvardetail.yvar  and finvar.yvar = @ayear	
	  	  	AND finvar.nvar = finvardetail.nvar and finvar.adate <= @date
			AND finvar.idfinvarstatus = 5 AND finvar.variationkind <> 5
		WHERE 	((F.flag & 1 ) = 0)  and F.ayear =@ayear	
			AND (@idfin IS NULL OR FLK.idparent = @idfin)
			AND (U.idupb like @idupb and U.active = 'S' )
			AND (F.nlevel = @nlevel)
		GROUP BY U.idupb, F.idfin, case when F.idfin=@idfinincomesurplus then 'S' else 'N' end
		--select 'maria',* from #fin_residual
	END
END 
ELSE 
BEGIN
	IF (@suppressifblank = 'S')
	BEGIN
		INSERT INTO #fin_residual
		(
			idfin, 
			idupb,
			flagadvance,
			var_prevision,
			varprevsec,
			flagconsider,
			nlevel
		)
		SELECT
			F.idfin,
			U.idupb,
			case when F.idfin=@idfinincomesurplus then 'S' else 'N' end,
			SUM(CASE WHEN finvar.flagprevision = 'S' then isnull(finvardetail.amount,0) else 0 END),
			SUM(CASE WHEN finvar.flagsecondaryprev = 'S' THEN isnull(finvardetail.amount,0) ELSE 0 END),
			CASE WHEN F.nlevel >= @levelusable and finlast.idfin is not null then 'S' else 'N' END,
			F.nlevel
		--FROM fin F cross join upb U
		FROM upbtotal
		JOIN upb U
			ON upbtotal.idupb = U.idupb
		JOIN fin F
			ON upbtotal.idfin = F.idfin
		JOIN finlink FLK
			ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
		LEFT OUTER JOIN finlink FLK2
			ON FLK2.idparent = F.idfin 
		LEFT OUTER JOIN finvardetail
	   		ON ISNULL(FLK2.idchild,F.idfin) = finvardetail.idfin
			AND finvardetail.idupb=U.idupb 
		LEFT OUTER JOIN finvar
		  	ON finvar.yvar = finvardetail.yvar  AND finvar.yvar = @ayear	
	  	  	AND finvar.nvar = finvardetail.nvar AND finvar.adate <= @date
			AND finvar.idfinvarstatus = 5 AND finvar.variationkind <> 5	
		LEFT OUTER JOIN finlast
				on F.idfin = finlast.idfin
		WHERE  ((F.flag & 1 ) = 0) AND F.ayear = @ayear
			AND (@idfin IS NULL OR FLK.idparent = @idfin)
			AND (U.idupb LIKE @idupb and U.active = 'S')
			AND (F.nlevel >=  @nlevel)
		GROUP BY U.idupb,F.idfin,F.nlevel,F.ayear,finlast.idfin, case when F.idfin=@idfinincomesurplus then 'S' else 'N' end
		
		-- Inserisco le coppie che hanno solo i RESIDUI
		INSERT INTO #fin_residual
      		(
			idfin, 
			idupb,
			flagadvance,
			var_prevision,
			varprevsec,
			flagconsider,
			nlevel
		)
		SELECT distinct
			F.idfin,
			U.idupb,
			case when F.idfin=@idfinincomesurplus then 'S' else 'N' end,
			0,
			0,
			CASE WHEN F.nlevel >= @levelusable and finlast.idfin is not null then 'S' else 'N' END,
			F.nlevel
		FROM incomeyear
		join upb U
			on  incomeyear.idupb = U.idupb 
		join fin F
			on  incomeyear.idfin = F.idfin 
		JOIN incometotal 
			ON incometotal.idinc = incomeyear.idinc
			AND incometotal.ayear = incomeyear.ayear
		JOIN finlink
			ON finlink.idchild = F.idfin AND finlink.nlevel = @level_input
		LEFT OUTER JOIN finlast
			ON F.idfin = finlast.idfin
		WHERE  (F.flag & 1) = 0  AND F.ayear = @ayear
			AND (@idfin IS NULL OR finlink.idparent = @idfin)
			AND (U.idupb like @idupb and U.active = 'S')
			AND (F.nlevel >=  @nlevel)
			AND NOT EXISTS (SELECT *
					  FROM #fin_residual
					   LEFT OUTER JOIN finlink FLK1 ON FLK1.idchild = incomeyear.idfin
					 WHERE incomeyear.idupb = #fin_residual.idupb 
					   AND ISNULL(FLK1.idparent,f.idfin) =  #fin_residual.idfin)			
			AND incomeyear.ayear = @ayear
			AND ((incometotal.flag & 1) = 1)
		GROUP BY U.idupb,F.idfin,F.nlevel,F.ayear, finlast.idfin, case when F.idfin=@idfinincomesurplus then 'S' else 'N' end
	END
	ELSE
	BEGIN
		INSERT INTO #fin_residual
		(
			idfin, 
			idupb,
			flagadvance,
			var_prevision,
			varprevsec,
			flagconsider,
			nlevel
		)
		SELECT
			F.idfin,
			U.idupb,
			case when F.idfin=@idfinincomesurplus then 'S' else 'N' end,
			SUM(CASE WHEN finvar.flagprevision = 'S' then isnull(finvardetail.amount,0) else 0 END),
			SUM(CASE WHEN finvar.flagsecondaryprev = 'S' THEN isnull(finvardetail.amount,0) ELSE 0 END),
			CASE WHEN F.nlevel >= @levelusable and finlast.idfin is not null then 'S' else 'N' END,
			F.nlevel
		FROM fin F cross join upb U
		LEFT OUTER JOIN finlink FLK2
			ON FLK2.idparent = F.idfin 
		LEFT OUTER JOIN finlast
			on F.idfin = finlast.idfin
		LEFT OUTER JOIN finvardetail
			ON ISNULL(FLK2.idchild,F.idfin) = finvardetail.idfin 
   		  	AND finvardetail.idupb=U.idupb 
		LEFT OUTER JOIN finvar
		  	ON finvar.yvar = finvardetail.yvar  and finvar.yvar = @ayear	
	  	  	AND finvar.nvar = finvardetail.nvar and finvar.adate <= @date
			AND finvar.idfinvarstatus = 5 AND finvar.variationkind <> 5
		JOIN finlink FLK
			ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
		WHERE  ((F.flag & 1) = 0) and F.ayear = @ayear
			AND (@idfin IS NULL OR isnull(FLK.idparent, F.idfin) = @idfin)
			AND (U.idupb LIKE @idupb and U.active = 'S')
			AND (F.nlevel >=  @nlevel)
		GROUP BY U.idupb,F.idfin,F.nlevel,F.ayear, finlast.idfin, case when F.idfin=@idfinincomesurplus then 'S' else 'N' end
	END
END
	UPDATE #fin_residual
		SET initialprevision = 
			ISNULL((SELECT SUM(finyear.prevision)
			FROM finyear 
			JOIN fin 
				on finyear.idfin = fin.idfin  				
			JOIN upb
				on finyear.idupb = upb.idupb 
			JOIN finlevel 
				ON finlevel.ayear = fin.ayear
				AND finlevel.nlevel = fin.nlevel
				AND (finlevel.flag&2)<>0
			JOIN finlast 
				ON finlast.idfin = fin.idfin
			JOIN finlink
				ON finlink.idchild = fin.idfin
			WHERE finlink.idparent= #fin_residual.idfin
				AND upb.idupb = #fin_residual.idupb 
				AND fin.ayear = @ayear
				AND finyear.ayear = @ayear), 0.0),
		 sec_initial_prevision= 
			ISNULL((
			SELECT SUM(finyear.secondaryprev)
			FROM finyear 
			JOIN fin 
				ON finyear.idfin = fin.idfin 
			JOIN upb
				ON finyear.idupb = upb.idupb  
			JOIN finlevel 
				ON finlevel.ayear = fin.ayear
				AND finlevel.nlevel = fin.nlevel
				AND (finlevel.flag&2)<>0
			JOIN finlast 
				ON finlast.idfin = fin.idfin
			JOIN finlink
				ON finlink.idchild = fin.idfin
			WHERE finlink.idparent = #fin_residual.idfin
				AND finyear.idupb =  #fin_residual.idupb 
				AND finyear.ayear = @ayear
				), 0.0),
		assessments = 
			ISNULL((SELECT SUM(incomeyear.amount)
				FROM incomeyear
				JOIN income
					ON  income.idinc = incomeyear.idinc
					AND incomeyear.ayear = @ayear
				JOIN incometotal
					ON  incomeyear.idinc = incometotal.idinc
					AND incomeyear.ayear = incometotal.ayear
				JOIN finlink
					ON  finlink.idchild  = incomeyear.idfin 
				WHERE 	income.adate <= @date 
					AND income.nphase = @assessmentphase
					AND ((incometotal.flag&1)= 0 OR @flag_cs = 'S') --Competenza
					AND finlink.idparent = #fin_residual.idfin
					AND incomeyear.idupb = #fin_residual.idupb), 0.0),
		var_assessments =
			ISNULL((SELECT SUM(incomevar.amount)
				FROM incomevar
				JOIN incomeyear
					ON  incomeyear.idinc = incomevar.idinc
					AND incomeyear.ayear = @ayear
				JOIN income
					ON income.idinc = incomeyear.idinc
				JOIN finlink
					ON  finlink.idchild = incomeyear.idfin 
				JOIN incometotal
					ON incomeyear.idinc = incometotal.idinc
					AND incomeyear.ayear = incometotal.ayear
				WHERE incomevar.yvar = @ayear
    				AND incomevar.adate <= @date
    				AND income.nphase = @assessmentphase
				AND ((incometotal.flag&1)= 0 OR @flag_cs = 'S') -- Competenza
				AND finlink.idparent = #fin_residual.idfin
				AND incomeyear.idupb = #fin_residual.idupb), 0.0)
	UPDATE #fin_residual
		SET proceeds = 
			ISNULL((SELECT SUM(IY.amount)
				FROM incomeyear IY
				JOIN historyproceedsview HPV
					ON  HPV.idinc = IY.idinc
					AND HPV.ymov = @ayear
					AND HPV.competencydate <= @date
				JOIN finlink
					ON  finlink.idchild = IY.idfin 
				JOIN incometotal 
					ON IY.idinc = incometotal.idinc
					AND IY.ayear = incometotal.ayear
				WHERE 	IY.ayear = @ayear
					AND HPV.competencydate <= @date
					AND ((incometotal.flag&1)= 0 OR @flag_cs = 'S') 
					AND finlink.idparent = #fin_residual.idfin
					AND IY.idupb = #fin_residual.idupb), 0.0)

UPDATE #fin_residual 
	SET fin_ph_comp =                                                
		ISNULL((
		SELECT SUM(incomeyear.amount)
		FROM income
		JOIN incomeyear
			ON incomeyear.idinc = income.idinc
			AND incomeyear.ayear = @ayear
		JOIN incometotal 
			ON incometotal.idinc = incomeyear.idinc
			AND incometotal.ayear = incomeyear.ayear
		JOIN finlink
			ON finlink.idchild = incomeyear.idfin
		WHERE finlink.idparent = #fin_residual.idfin 
			AND ((incometotal.flag&1)=0) -- Competenza
			AND incomeyear.idupb = #fin_residual.idupb
			AND income.adate <= @date 
			AND income.nphase = @fin_phase), 0.0),
	 var_fin_ph_comp=					
		ISNULL((
		SELECT SUM(incomevar.amount)
		FROM incomevar
		JOIN income
			ON incomevar.idinc = income.idinc
		JOIN incomeyear
			ON incomeyear.idinc = incomevar.idinc
		JOIN incometotal 
			ON incometotal.idinc = incomeyear.idinc
			AND incometotal.ayear = incomeyear.ayear
		JOIN finlink
			ON finlink.idchild = incomeyear.idfin
		WHERE incomevar.adate <= @date 
			AND incomeyear.ayear = @ayear
			AND income.nphase= @fin_phase
			AND ((incometotal.flag&1)=0) -- Competenza
			AND finlink.idparent = #fin_residual.idfin 
			AND incomeyear.idupb = #fin_residual.idupb
			AND incomevar.yvar = @ayear), 0.0),
	fin_ph_resid = 
		ISNULL((
		SELECT SUM(incomeyear.amount)
		FROM income
		JOIN incomeyear
			ON incomeyear.idinc = income.idinc
			AND incomeyear.ayear = @ayear
		JOIN incometotal 
			ON incometotal.idinc = incomeyear.idinc
			AND incometotal.ayear = incomeyear.ayear
		JOIN finlink
			ON finlink.idchild = incomeyear.idfin
		WHERE income.adate <= @date 
			AND ((incometotal.flag&1)=1) -- Residuo
			AND finlink.idparent  = #fin_residual.idfin 
			AND incomeyear.idupb = #fin_residual.idupb
			AND income.nphase = @fin_phase), 0.0),
 	var_fin_ph_resid=					
		ISNULL((
		SELECT SUM(incomevar.amount)
		FROM incomevar
		JOIN income
			ON incomevar.idinc = income.idinc
		JOIN incomeyear
			ON incomeyear.idinc = incomevar.idinc
			AND incomeyear.ayear = @ayear
		JOIN incometotal 
			ON incometotal.idinc = incomeyear.idinc
			AND incometotal.ayear = incomeyear.ayear
		JOIN finlink
			ON finlink.idchild = incomeyear.idfin
		WHERE incomevar.adate <= @date 
			AND income.nphase= @fin_phase
			AND ((incometotal.flag&1)=1) -- Residuo
			AND finlink.idparent = #fin_residual.idfin 
			AND incomeyear.idupb = #fin_residual.idupb
			AND incomevar.yvar = @ayear), 0.0),
 	registry_ph_comp = 
		ISNULL((
		SELECT SUM(incomeyear.amount)
		FROM income
		JOIN incomeyear
			ON incomeyear.idinc = income.idinc
			AND incomeyear.ayear = @ayear
		JOIN incometotal 
			ON incometotal.idinc = incomeyear.idinc
			AND incometotal.ayear = incomeyear.ayear
		JOIN finlink
			ON finlink.idchild = incomeyear.idfin
		WHERE income.adate <= @date 
			AND ((incometotal.flag&1)=0) -- Competenza
			AND finlink.idparent  = #fin_residual.idfin 
			AND incomeyear.idupb = #fin_residual.idupb
			AND income.nphase = @registry_phase), 0.0),
	var_registry_ph_comp =
		ISNULL((
		SELECT SUM(incomevar.amount)
		FROM incomevar
		JOIN income
			ON incomevar.idinc = income.idinc
		JOIN incomeyear
			ON incomeyear.idinc = incomevar.idinc
			AND incomeyear.ayear = @ayear
		JOIN incometotal 
			ON incometotal.idinc = incomeyear.idinc
			AND incometotal.ayear = incomeyear.ayear
		JOIN finlink
			ON finlink.idchild = incomeyear.idfin
		WHERE incomevar.adate <= @date 
			AND income.nphase= @registry_phase
			AND ((incometotal.flag&1)=0) -- Competenza
			AND finlink.idparent  = #fin_residual.idfin 
			AND incomeyear.idupb = #fin_residual.idupb
			AND incomevar.yvar = @ayear), 0.0),
	registry_ph_resid = 
		ISNULL((
		SELECT SUM(incomeyear.amount)
		FROM income
		JOIN incomeyear
			ON incomeyear.idinc = income.idinc
			AND incomeyear.ayear = @ayear
		JOIN incometotal 
			ON incometotal.idinc = incomeyear.idinc
			AND incometotal.ayear = incomeyear.ayear
		JOIN finlink
			ON finlink.idchild = incomeyear.idfin
		WHERE income.adate <= @date 
			AND ((incometotal.flag&1)=1) -- Residuo
			AND finlink.idparent  = #fin_residual.idfin 
			AND incomeyear.idupb = #fin_residual.idupb
			AND income.nphase = @registry_phase), 0.0),
	var_registry_ph_resid =
		ISNULL((
		SELECT SUM(incomevar.amount)
		FROM incomevar
		JOIN income
			ON incomevar.idinc = income.idinc
		JOIN incomeyear
			ON incomeyear.idinc = incomevar.idinc
			AND incomeyear.ayear = @ayear
		JOIN incometotal 
			ON incometotal.idinc = incomeyear.idinc
			AND incometotal.ayear = incomeyear.ayear
		JOIN finlink
			ON finlink.idchild = incomeyear.idfin
		WHERE incomevar.adate <= @date 
			AND income.nphase= @registry_phase
			AND ((incometotal.flag&1)=1) -- Residuo
			AND finlink.idparent  = #fin_residual.idfin 
			AND incomeyear.idupb = #fin_residual.idupb
			AND incomevar.yvar = @ayear), 0.0)

UPDATE #fin_residual
	SET	
	max_ph_comp =	 
		ISNULL((SELECT SUM(HPV.amount)	
		FROM historyproceedsview HPV
		JOIN finlink
			ON finlink.idchild = HPV.idfin	 
		WHERE  HPV.ymov = @ayear
			AND HPV.competencydate <= @date
			AND ((HPV.totflag&1)=0) -- Competenza
			AND finlink.idparent  = #fin_residual.idfin
			AND HPV.idupb = #fin_residual.idupb), 0.0),
	max_ph_resid =	 
		ISNULL((SELECT SUM(HPV.amount)
		FROM historyproceedsview HPV
		JOIN finlink
			ON finlink.idchild = HPV.idfin	 
		WHERE  HPV.ymov = @ayear
			AND HPV.competencydate <= @date
			AND ((HPV.totflag&1)=1) -- Residuo
			AND finlink.idparent  = #fin_residual.idfin
			AND HPV.idupb = #fin_residual.idupb), 0.0)


IF @cashvaliditykind <> 4
BEGIN
	UPDATE #fin_residual	
	SET var_proceeds =
		ISNULL((SELECT SUM(incomevar.amount)
				FROM incomevar
				join income on income.idinc = incomevar.idinc
				JOIN incomeyear
					ON incomeyear.idinc = incomevar.idinc
					AND incomeyear.ayear = @ayear
				JOIN historyproceedsview HPV 						
					ON HPV.idinc = incomeyear.idinc
					AND HPV.ymov = @ayear
				JOIN finlink
					ON  finlink.idchild = incomeyear.idfin 
				JOIN incometotal
					ON incomeyear.idinc = incometotal.idinc
					AND incomeyear.ayear = incometotal.ayear
			WHERE 	incomevar.yvar = @ayear
				AND incomevar.adate <= @date
				AND HPV.competencydate <= @date
				AND income.nphase = @phasemax
				AND ((incometotal.flag&1)= 0 OR @flag_cs = 'S') -- Residuo
				AND finlink.idparent = #fin_residual.idfin
				AND incomeyear.idupb = #fin_residual.idupb), 0.0)
	UPDATE #fin_residual
		SET	
		var_max_ph_comp = 
			ISNULL((
			SELECT SUM(incomevar.amount)
			FROM incomevar
			JOIN historyproceedsview HPV
				ON HPV.idinc = incomevar.idinc
			JOIN finlink
				ON finlink.idchild = HPV.idfin	 
			WHERE incomevar.yvar = @ayear
				AND incomevar.adate <= @date
				AND HPV.ymov = @ayear AND HPV.competencydate <= @date
				AND ((HPV.totflag&1)=0) -- Competenza
				AND finlink.idparent  = #fin_residual.idfin
				AND HPV.idupb = #fin_residual.idupb), 0.0),
		var_max_ph_resid = 
			ISNULL((
			SELECT SUM(incomevar.amount)
			FROM incomevar
			JOIN historyproceedsview HPV
				ON HPV.idinc = incomevar.idinc
			JOIN finlink
				ON finlink.idchild = HPV.idfin	
			WHERE incomevar.yvar = @ayear
				AND HPV.ymov = @ayear AND HPV.competencydate <= @date
				AND ((HPV.totflag&1)=1) --residuo   
				AND incomevar.adate <= @date
				AND finlink.idparent  = #fin_residual.idfin
				AND HPV.idupb = #fin_residual.idupb), 0.0)

END
IF @flag_cs = 'S'
BEGIN
	UPDATE #fin_residual
		SET proceeds = ISNULL(initialprevision, 0.0) + ISNULL(var_prevision, 0.0),
		assessments = ISNULL(initialprevision, 0.0) + ISNULL(var_prevision, 0.0)
		WHERE flagadvance='S'
-- Aggiorna le voci non operative di conseguenza-- qualora ci siano...quindi questa agisce solo se stiamo espandendo la gerarchia
	UPDATE #fin_residual
		SET proceeds= ISNULL(proceeds,0.0) + 
			ISNULL(( SELECT SUM(rp.proceeds) 
				   FROM #fin_residual rp  
				   LEFT OUTER JOIN finlink 
				     ON finlink.idchild = rp.idfin 
				  WHERE 
				(	(ISNULL(finlink.idparent,rp.idfin)= #fin_residual.idfin) AND
					(rp.idupb like #fin_residual.idupb + '%') AND
					(rp.nlevel > #fin_residual.nlevel) AND
					idfin =  @idfinincomesurplus  )
				),0.0)
	UPDATE #fin_residual
		SET assessments=  ISNULL(assessments,0.0) +
			ISNULL(( SELECT SUM(rp.assessments) 
				   FROM #fin_residual rp 
				   LEFT OUTER JOIN finlink 
				     ON finlink.idchild = rp.idfin 
				 WHERE 
			    (	(ISNULL(finlink.idparent,rp.idfin)= #fin_residual.idfin) AND
				(rp.idupb like #fin_residual.idupb + '%') AND
				(rp.nlevel > #fin_residual.nlevel) AND
				idfin = @idfinincomesurplus
                                                            )
			),0.0)
END
-- VALORIZZA CAMPI upb
IF (@showupb = 'S')	
	UPDATE 	#fin_residual 
	SET  	upbprintingorder = upb.printingorder,
		upb = upb.title,
		codeupb = upb.codeupb
	FROM upb
	WHERE upb.idupb = #fin_residual.idupb
IF (@showupb <>'S') AND (@idupboriginal <> '%' ) AND (@showchildupb = 'S')
	UPDATE 	#fin_residual 
	SET  	idupb = @idupboriginal,
		upbprintingorder = (SELECT TOP 1 printingorder FROM upb
					WHERE idupb = @idupboriginal),
		upb = (SELECT TOP 1 title FROM upb
				WHERE idupb = @idupboriginal),
		codeupb =(SELECT TOP 1 codeupb FROM upb
				WHERE idupb = @idupboriginal)
	
IF (@showupb <>'S') and (@idupboriginal = '%') 
	UPDATE #fin_residual 
		SET  
		idupb = null,
		upbprintingorder = null,
		upb =  null,
		codeupb = null
IF (@suppressifblank = 'S') AND @nlevel>=2	--> se la stampa è x un livello uguale o sottostante la categoria cancella le righe
BEGIN
	DELETE FROM #fin_residual 
	WHERE 
		(isnull(initialprevision,0) =0 AND isnull(var_prevision,0) =0 AND 
		isnull(sec_initial_prevision,0) =0 AND isnull(varprevsec,0)= 0 AND
		isnull(assessments,0) =0 AND isnull(var_assessments,0) =0 AND 
		isnull(proceeds,0) =0 AND isnull(var_proceeds,0) =0 AND
		isnull(registry_ph_comp,0) =0 AND isnull(var_registry_ph_comp,0) =0 AND 
		isnull(registry_ph_resid,0) =0 AND isnull(var_registry_ph_resid,0) =0 AND 
		isnull(max_ph_comp,0) =0 AND isnull(var_max_ph_comp,0) =0 AND 
		isnull(max_ph_resid,0) =0 AND isnull(var_max_ph_resid,0) =0 AND 
		nlevel >=2)
		--LEN(idfin)>=11)
END
IF (@showupb <>'S') 
BEGIN
		SELECT
		finlevel.description					as 'Livello',
		fin.codefin								as 'Cod. Bilancio',	
		fin.title								as 'Bilancio',	
		manager.title							as 'Responsabile',
		codeupb									as 'Cod. UPB',
		upb										as 'UPB',
		sum(isnull(initialprevision,0.0)) 		as 'Previsione iniziale principale',	
		sum(isnull(var_prevision,0.0)) 			as 'Variazioni previsione principale',
		sum(isnull(initialprevision,0.0)) + sum(isnull(var_prevision,0.0)) as 'Previsione principale definitiva',
		sum(isnull(assessments,0.0)) + sum(isnull(var_assessments,0.0))	   as 'Accertamenti',
		sum(isnull(proceeds,0.0))  + sum(isnull(var_proceeds,0.0)) 		   as 'Incassi',
		sum(isnull(initialprevision,0.0)) + sum(isnull(var_prevision,0.0)) -
		(sum(isnull(proceeds,0.0))   +  sum(isnull(var_proceeds,0.0)) ) as 'Previsione Disponibile ad Incassare'
		FROM #fin_residual  JOIN fin 
		ON #fin_residual.idfin = fin.idfin		
		left outer join finlast on #fin_residual.idfin = finlast.idfin  
		left outer join manager on manager.idman = finlast.idman  
		join finlevel on fin.nlevel = finlevel.nlevel and finlevel.ayear = @ayear
		
		GROUP BY upbprintingorder,
			finprintingorder,
			#fin_residual.idfin,
			finlevel.description, manager.title,
			codeupb,
			idupb,
			upb,
			fin.codefin,
			fin.title,
			fin.printingorder,
			#fin_residual.nlevel,
			flagconsider
		ORDER BY upbprintingorder,finprintingorder,fin.printingorder
END
ELSE 
		SELECT 
			finlevel.description					as 'Livello',
			fin.codefin								as 'Cod. Bilancio',	
			fin.title								as 'Bilancio',	
			manager.title							as 'Responsabile',
			codeupb									as 'Cod. UPB',
			upb										as 'UPB',
			isnull(initialprevision,0.0)	 		as 'Previsione iniziale principale',	
			isnull(var_prevision,0.0)	 			as 'Variazioni previsione principale',
			isnull(initialprevision,0) + isnull(var_prevision,0) as 'Previsione definitiva',
			isnull(assessments,0)	 + isnull(var_assessments,0) as 'Accertamenti',
			isnull(proceeds,0) + isnull(var_proceeds,0)	as 'Incassi',
			isnull(initialprevision,0.0) + isnull(var_prevision,0.0) -
			(isnull(proceeds,0) + isnull(var_proceeds,0))
			as 'Previsione Disponibile ad Incassare'
      
		 FROM #fin_residual JOIN fin 
		 ON #fin_residual.idfin = fin.idfin
			left outer join finlast on #fin_residual.idfin = finlast.idfin  
			left outer join manager on manager.idman = finlast.idman  
			join finlevel on fin.nlevel = finlevel.nlevel and finlevel.ayear = @ayear
		
		 ORDER BY upbprintingorder,fin.printingorder
END



GO

print '[exp_sitbilancio_entrata] OK'

GO
if object_id('rpt_varprevisione_crediti_cassa') is not null
	drop PROCEDURE rpt_varprevisione_crediti_cassa
go

--	exec rpt_varprevisione_crediti_cassa 2013, 10,10,'cassa','S','N','N','2',null,null,null,null,null
CREATE   PROCEDURE rpt_varprevisione_crediti_cassa
	@yvar          	int, 
	@nvarbegin   	int,
	@nvarend     	int,
	@reportkind    	varchar(20),
	@showupb char(1),
	@compress char(1),
	@showcategory char(1),
	@nenactment		int,
	@idsor01 int,
	@idsor02 int,
	@idsor03 int,
	@idsor04 int,
	@idsor05 int 
	AS
	BEGIN
	
	DECLARE @yenactment   		int
	DECLARE @idenactment	int
	
	SET 	@yenactment = @yvar
	SET     @idenactment = 
			 (SELECT idenactment
			    FROM enactment 
			   WHERE enactment.yenactment = @yenactment
	   		     AND enactment.nenactment = @nenactment)	
	
	IF @reportkind = 'PREVISIONE'
	BEGIN
		SELECT  --report variazioni della previsione
			finvar.yvar,
			finvar.nvar,
			finvar.description,
			finvar.enactment,
			finvar.variationkind,
			finvar.nenactment,
			finvar.enactmentdate,
			finvar.adate,
			finvar.flagprevision,
			finvar.flagcredit,
			finvar.flagproceeds,
			finvar.flagsecondaryprev,
			CASE 
				WHEN config.fin_kind IN (1,3) THEN 'C'
				WHEN config.fin_kind = 2 THEN 'S'
			END as 'previsionkind',
			CASE 
				WHEN config.fin_kind = 3 THEN 'S'
				ELSE NULL
			END as 'secprevisionkind'
		FROM finvar 
		JOIN config 
			ON finvar.yvar=config.ayear	
		JOIN finvardetail
			ON finvar.yvar = finvardetail.yvar
			AND finvar.nvar = finvardetail.nvar
		JOIN upb
			ON finvardetail.idupb = upb.idupb		
		WHERE
			finvar.yvar = @yvar
			AND finvar.variationkind <> 5
			AND (flagprevision = 'S' OR flagsecondaryprev = 'S')
			AND (finvar.idenactment = @idenactment OR @idenactment IS NULL)	
			AND ((finvar.nvar BETWEEN @nvarbegin AND @nvarend) OR 
		     	     (@nvarbegin IS NULL) OR (@nvarend IS NULL))
			AND (@idsor01 IS NULL OR upb.idsor01 = @idsor01)
			AND (@idsor02 IS NULL OR upb.idsor02 = @idsor02)
			AND (@idsor03 IS NULL OR upb.idsor03 = @idsor03)
			AND (@idsor04 IS NULL OR upb.idsor04 = @idsor04)
			AND (@idsor05 IS NULL OR upb.idsor05 = @idsor05)		     	     
		GROUP BY finvar.yvar, finvar.nvar,finvar.description, finvar.enactment,finvar.variationkind,finvar.nenactment,finvar.enactmentdate,finvar.adate,
			finvar.flagprevision,	finvar.flagcredit,	finvar.flagproceeds,finvar.flagsecondaryprev, config.fin_kind     	     
		ORDER BY finvar.nvar
		
	END
	IF @reportkind = 'CREDITI'
	BEGIN
		SELECT  --report variazioni dei crediti
			finvar.yvar,
			finvar.nvar,
			finvar.description,
			finvar.enactment,
			finvar.variationkind,
			finvar.flagcredit,
			finvar.flagproceeds,
			finvar.nenactment,
			finvar.enactmentdate,
			finvar.adate,
			NULL as 'flagprevision',
			NULL as 'flagsecondaryprev',
			NULL as 'previsionkind' ,
			NULL as 'secprevisionkind'
		FROM finvar 
		JOIN finvardetail
			ON finvar.yvar = finvardetail.yvar
			AND finvar.nvar = finvardetail.nvar
		JOIN upb
			ON finvardetail.idupb = upb.idupb		
		WHERE
			finvar.yvar = @yvar
			and finvar.flagcredit = 'S'
			and (finvar.idenactment = @idenactment or @idenactment IS NULL)	
			and ((finvar.nvar BETWEEN @nvarbegin and @nvarend) or 
		     	     (@nvarbegin IS NULL) or (@nvarend IS NULL))
			AND (@idsor01 IS NULL OR upb.idsor01 = @idsor01)
			AND (@idsor02 IS NULL OR upb.idsor02 = @idsor02)
			AND (@idsor03 IS NULL OR upb.idsor03 = @idsor03)
			AND (@idsor04 IS NULL OR upb.idsor04 = @idsor04)
			AND (@idsor05 IS NULL OR upb.idsor05 = @idsor05)		 
		GROUP BY finvar.yvar,finvar.nvar,finvar.description,finvar.enactment,
			finvar.variationkind,finvar.flagcredit,finvar.flagproceeds,finvar.nenactment,
			finvar.enactmentdate,finvar.adate			    	     
		ORDER BY finvar.nvar
		END
	IF @reportkind = 'CASSA'
	BEGIN
		SELECT  --report variazioni della cassa
			finvar.yvar,
			finvar.nvar,
			finvar.description,
			finvar.enactment,
			finvar.variationkind,
			finvar.flagcredit,
			finvar.flagproceeds,
			finvar.nenactment,
			finvar.enactmentdate,
			finvar.adate,
			NULL as 'flagprevision',
			NULL as 'flagsecondaryprev',
			NULL as 'previsionkind' ,
			NULL as 'secprevisionkind'
			FROM finvar 
			JOIN finvardetail
				ON finvar.yvar = finvardetail.yvar
				AND finvar.nvar = finvardetail.nvar
			JOIN upb
				ON finvardetail.idupb = upb.idupb			
			WHERE
				finvar.yvar = @yvar
				and finvar.flagproceeds = 'S'
				and (finvar.idenactment = @idenactment or @idenactment IS NULL)	
				and ((finvar.nvar BETWEEN @nvarbegin AND @nvarend) or 
			     	     (@nvarbegin IS NULL) or (@nvarend IS NULL))
				AND (@idsor01 IS NULL OR upb.idsor01 = @idsor01)
				AND (@idsor02 IS NULL OR upb.idsor02 = @idsor02)
				AND (@idsor03 IS NULL OR upb.idsor03 = @idsor03)
				AND (@idsor04 IS NULL OR upb.idsor04 = @idsor04)
				AND (@idsor05 IS NULL OR upb.idsor05 = @idsor05)				     	     
			GROUP BY finvar.yvar,finvar.nvar,finvar.description,finvar.enactment,
			finvar.variationkind,finvar.flagcredit,finvar.flagproceeds,finvar.nenactment,
			finvar.enactmentdate,finvar.adate			     	     
			ORDER BY finvar.nvar
		END 
END



GO

print 'rpt_varprevisione_crediti_cassa OK'

GO
if object_id('[compute_ivapayexpense]') is not null
	drop PROCEDURE [compute_ivapayexpense]
go

CREATE           PROCEDURE [compute_ivapayexpense]
	@ayear int,
	@datebegin datetime,
	@dateend datetime
AS BEGIN
	-- Tabella di output (dei documenti)
	CREATE TABLE #invoice
	(
		idinvkind int,
		yinv int,
		ninv int,
		idivaregisterkind int,
		registerclass char(1),
		flagmixed char(1),
		flagdeferred char(1),
		ivatotal decimal(19,2),
		taxabletotal decimal(19,2),
		previvatotalpayed decimal(19,2),
		prevtotalpayed decimal(19,2),
		currivagrosspayed decimal(19,2),
		currivapayed decimal(19,2),
		currtotalpayed decimal(19,2)
	)
	-- Tabella delle vecchie liquidazioni
	CREATE TABLE #oldivapay
	(
		idivaregisterkind varchar(20),
		iva decimal(19,2)
	)
	
	-- Riempimento delle vecchie liquidazioni
	-- Si selezionano solamente le liquidazioni che ricadono nello stesso
	-- periodo della liquidazione corrente
	INSERT INTO #oldivapay (idivaregisterkind, iva)
	(SELECT ivapaydetail.idivaregisterkind, SUM(ivapaydetail.iva)
	FROM ivapay
	JOIN ivapaydetail
		ON ivapay.yivapay = ivapaydetail.yivapay
		AND ivapay.nivapay = ivapaydetail.nivapay
	JOIN ivaregisterkind
		ON ivaregisterkind.idivaregisterkind = ivapaydetail.idivaregisterkind
	WHERE ivapay.start >= @datebegin
		AND ivapay.stop <= @dateend
		AND ivaregisterkind.registerclass = 'V'
	GROUP BY ivapaydetail.idivaregisterkind)
	-- Calcolo dell'IVA a debito
	-- Sezione 1. Calcolo dell'IVA a Debito
	-- Sezione 1.1. IVA Immediata
	-- Calcolo sulle Fatture
	-- Si considerano tutte le fatture di vendita la cui data di registrazione
	-- ricade nel range di date fornito in input alla SP
	INSERT INTO #invoice
	(
		idinvkind, yinv, ninv, registerclass, flagdeferred, idivaregisterkind,
		currivagrosspayed,
		currivapayed
	)
	(SELECT I.idinvkind, I.yinv, I.ninv, 'V', 'N', IRK.idivaregisterkind,
		ISNULL(SUM(ROUND(I_DET.tax * I.exchangerate, 2)),0), 
		ISNULL(SUM(ROUND(I_DET.tax * I.exchangerate, 2)),0)
	FROM ivaregister IR
	JOIN invoice I
		ON I.idinvkind = IR.idinvkind
		AND I.yinv = IR.yinv
		AND I.ninv = IR.ninv
	JOIN ivaregisterkind IRK
		ON IRK.idivaregisterkind = IR.idivaregisterkind
	JOIN invoicekind IK
		ON IK.idinvkind = IR.idinvkind
	JOIN invoicedetail I_DET
		ON I_DET.idinvkind = IR.idinvkind
		AND I_DET.yinv = IR.yinv
		AND I_DET.ninv = IR.ninv
	LEFT OUTER JOIN #oldivapay OIP
		ON IR.idivaregisterkind = OIP.idivaregisterkind
	WHERE IRK.registerclass = 'V'
		AND (IK.flag & 4) = 0
		AND I.adate BETWEEN @datebegin AND @dateend
		AND I.flagdeferred = 'N'
	GROUP BY I.idinvkind, I.yinv, I.ninv, IRK.idivaregisterkind, OIP.iva)
	
	
	-- Calcolo sulle Note di Credito
	-- Si considerano tutte le note di credito emesse la cui data di registrazione
	-- ricade nel range di date fornito in input alla SP
	INSERT INTO #invoice
	(
		idinvkind, yinv, ninv, registerclass, flagdeferred, idivaregisterkind,
		currivagrosspayed,
		currivapayed
	)
	(SELECT I.idinvkind, I.yinv, I.ninv, 'V', 'N', IRK.idivaregisterkind,
	- ISNULL(SUM(ROUND(I_DET.tax * I.exchangerate, 2)),0), 
	- ISNULL(SUM(ROUND(I_DET.tax * I.exchangerate, 2)),0)
	FROM ivaregister IR
	JOIN invoice I
		ON I.idinvkind = IR.idinvkind
		AND I.yinv = IR.yinv
		AND I.ninv = IR.ninv
	JOIN ivaregisterkind IRK
		ON IRK.idivaregisterkind = IR.idivaregisterkind
	JOIN invoicekind IK
		ON IK.idinvkind = IR.idinvkind
	JOIN invoicedetail I_DET
		ON I_DET.idinvkind = IR.idinvkind
		AND I_DET.yinv = IR.yinv
		AND I_DET.ninv = IR.ninv
	LEFT OUTER JOIN #oldivapay OIP
		ON IR.idivaregisterkind = OIP.idivaregisterkind
	WHERE IRK.registerclass = 'V'
		AND (IK.flag & 4) <> 0
		AND I.adate BETWEEN @datebegin AND @dateend
		AND I.flagdeferred = 'N'
	GROUP BY I.idinvkind, I.yinv, I.ninv, IRK.idivaregisterkind, OIP.iva)
	
	-- Sezione 1.2. IVA Differita
	-- Cerco tutte le contabilizzazioni IMPOS e DOCUM della fattura ricadenti 
	-- nel periodo di liquidazione dell'IVA per le quali la reversale è stata
	-- emesse nel range di date fornito in input alla SP
	-- Fatture
	INSERT INTO #invoice
	(
		idinvkind, yinv, ninv, flagdeferred, registerclass, idivaregisterkind,
		ivatotal, taxabletotal, previvatotalpayed, prevtotalpayed,
		currivagrosspayed,
		currivapayed
	)
	(SELECT
		I.idinvkind, I.yinv,I.ninv, 'S', 'V', IRK.idivaregisterkind,
		TIV.ivatotal, TIV.taxabletotal, SUM(I_D.ivatotalpayed), SUM(I_D.totalpayed),
		ISNULL(
			(SELECT SUM(ROUND(ISNULL(I_DET.tax,0) * I2.exchangerate,2))
			FROM invoicedetail I_DET
			JOIN invoice I2
				ON I2.idinvkind = I_DET.idinvkind
				AND I2.yinv = I_DET.yinv
				AND I2.ninv = I_DET.ninv
			JOIN proceedsemitted PE1
				ON PE1.idinc = I_DET.idinc_iva
			WHERE I.idinvkind = I_DET.idinvkind
				AND I.yinv = I_DET.yinv
				AND I.ninv = I_DET.ninv
				AND I_DET.paymentcompetency IS  NULL
				AND PE1.competencydate BETWEEN @datebegin AND @dateend)
		,0) -
		ISNULL(
			(SELECT ISNULL(SUM(I_D1.ivatotalpayed),0)
			FROM invoicedeferred I_D1
			JOIN ivapay IP
				ON I_D1.yivapay = IP.yivapay
				AND I_D1.nivapay = IP.nivapay
			WHERE IP.start >= @datebegin AND IP.stop <= @dateend
				AND I_D1.idinvkind = I.idinvkind
				AND I_D1.yinv = I.yinv
				AND I_D1.ninv = I.ninv)
		,0),
		ISNULL(
			(SELECT SUM(ROUND(ISNULL(I_DET.tax,0) * I2.exchangerate,2))
			FROM invoicedetail I_DET
			JOIN invoice I2
				ON I2.idinvkind = I_DET.idinvkind
				AND I2.yinv = I_DET.yinv
				AND I2.ninv = I_DET.ninv
			JOIN proceedsemitted PE1
				ON PE1.idinc = I_DET.idinc_iva
			WHERE I.idinvkind = I_DET.idinvkind
				AND I.yinv = I_DET.yinv
				AND I.ninv = I_DET.ninv
				AND I_DET.paymentcompetency IS  NULL
				AND PE1.competencydate BETWEEN @datebegin AND @dateend)
		,0) -
		ISNULL(
			(SELECT ISNULL(SUM(I_D1.ivatotalpayed),0)
			FROM invoicedeferred I_D1
			JOIN ivapay IP
				ON I_D1.yivapay = IP.yivapay
				AND I_D1.nivapay = IP.nivapay
			WHERE IP.start >= @datebegin AND IP.stop <= @dateend
				AND I_D1.idinvkind = I.idinvkind
				AND I_D1.yinv = I.yinv
				AND I_D1.ninv = I.ninv)
		,0)
	FROM incomeinvoice MOV
	JOIN proceedsemitted PE
		ON PE.idinc = MOV.idinc
	JOIN invoice I
		ON I.idinvkind = MOV.idinvkind
		AND I.yinv = MOV.yinv
		AND I.ninv = MOV.ninv
	LEFT OUTER JOIN invoicedeferred I_D
		ON I_D.idinvkind = I.idinvkind
		AND I_D.yinv = I.yinv
		AND I_D.ninv = I.ninv
	JOIN totinvoiceview TIV
		ON TIV.idinvkind = I.idinvkind
		AND TIV.yinv = I.yinv
		AND TIV.ninv = I.ninv
	JOIN ivaregister IR
		ON IR.idinvkind = I.idinvkind
		AND IR.yinv = I.yinv
		AND IR.ninv = I.ninv
	JOIN ivaregisterkind IRK
		ON IRK.idivaregisterkind = IR.idivaregisterkind
	WHERE MOV.movkind IN (1, 2)
		AND IRK.registerclass = 'V'
		AND PE.competencydate BETWEEN @datebegin AND @dateend
		AND I.flagdeferred = 'S'
	GROUP BY I.idinvkind,I.yinv,I.ninv,MOV.movkind, IRK.idivaregisterkind,
	TIV.ivatotal, TIV.taxabletotal)
	
	-- Cerco tutti i dettagli delle fatture di vendita ai quali è stata specificata
	-- una data di competenza ricadente nel range di date fornito in input alla SP
	INSERT INTO #invoice
	(
		idinvkind, yinv, ninv, flagdeferred, registerclass, idivaregisterkind,
		ivatotal, taxabletotal, previvatotalpayed, prevtotalpayed,
		currivagrosspayed,
		currivapayed
	)
	(SELECT
		I.idinvkind, I.yinv,I.ninv, 'S', 'V', IRK.idivaregisterkind,
		TIV.ivatotal, TIV.taxabletotal, SUM(I_D.ivatotalpayed), SUM(I_D.totalpayed),
		ISNULL(
		     (SELECT SUM(ROUND(ISNULL(I_DET.tax,0) * I2.exchangerate,2))
			FROM invoicedetail I_DET
			JOIN invoice I2
				ON I2.idinvkind = I_DET.idinvkind
				AND I2.yinv = I_DET.yinv
				AND I2.ninv = I_DET.ninv
			WHERE I.idinvkind = I_DET.idinvkind
				AND I.yinv = I_DET.yinv
				AND I.ninv = I_DET.ninv
				AND I_DET.paymentcompetency BETWEEN @datebegin AND @dateend
				)
		,0) -
		ISNULL(
		     (SELECT ISNULL(SUM(I_D1.ivatotalpayed),0)
			FROM invoicedeferred I_D1
			JOIN ivapay IP
				ON I_D1.yivapay = IP.yivapay
				AND I_D1.nivapay = IP.nivapay
			WHERE IP.start >= @datebegin AND IP.stop <= @dateend
				AND I_D1.idinvkind = I.idinvkind
				AND I_D1.yinv = I.yinv
				AND I_D1.ninv = I.ninv)
		,0),
		ISNULL(
		     (SELECT SUM(ROUND(ISNULL(I_DET.tax,0) * I2.exchangerate,2))
			FROM invoicedetail I_DET
			JOIN invoice I2
				ON I2.idinvkind = I_DET.idinvkind
				AND I2.yinv = I_DET.yinv
				AND I2.ninv = I_DET.ninv
			WHERE I.idinvkind = I_DET.idinvkind
				AND I.yinv = I_DET.yinv
				AND I.ninv = I_DET.ninv
				AND I_DET.paymentcompetency BETWEEN @datebegin AND @dateend)
		,0) -
		ISNULL(
		     (SELECT ISNULL(SUM(I_D1.ivatotalpayed),0)
			FROM invoicedeferred I_D1
			JOIN ivapay IP
				ON I_D1.yivapay = IP.yivapay
				AND I_D1.nivapay = IP.nivapay
			WHERE IP.start >= @datebegin AND IP.stop <= @dateend
				AND I_D1.idinvkind = I.idinvkind
				AND I_D1.yinv = I.yinv
				AND I_D1.ninv = I.ninv)
		,0)
	FROM invoice I
	LEFT OUTER JOIN invoicedeferred I_D
		ON I_D.idinvkind = I.idinvkind
		AND I_D.yinv = I.yinv
		AND I_D.ninv = I.ninv
	--maria
	JOIN invoicedetail I_DET1
		ON I.idinvkind = I_DET1.idinvkind
		AND I.yinv = I_DET1.yinv
		AND I.ninv = I_DET1.ninv
	JOIN totinvoiceview TIV
		ON TIV.idinvkind = I.idinvkind
		AND TIV.yinv = I.yinv
		AND TIV.ninv = I.ninv
	JOIN ivaregister IR
		ON IR.idinvkind = I.idinvkind
		AND IR.yinv = I.yinv
		AND IR.ninv = I.ninv
	JOIN ivaregisterkind IRK
		ON IRK.idivaregisterkind = IR.idivaregisterkind
	JOIN invoicekind IK
		ON IK.idinvkind = I.idinvkind
	WHERE	I_DET1.paymentcompetency BETWEEN @datebegin AND @dateend
		AND IRK.registerclass = 'V'
		AND I.flagdeferred = 'S'
		AND (IK.flag & 1 <> 0)
		AND (IK.flag & 4 = 0)
	GROUP BY I.idinvkind,I.yinv,I.ninv,IRK.idivaregisterkind, 
	TIV.ivatotal, TIV.taxabletotal)
	-- Cerco tutte le contabilizzazioni IMPOS e DOCUM delle note di credito ricadenti 
	-- nel periodo di liquidazione dell'IVA per le quali la reversale è stata
	-- emessa nel range di date fornito in input alla SP
	-- Note di Credito
	INSERT INTO #invoice
	(
		idinvkind, yinv, ninv, flagdeferred, registerclass, idivaregisterkind,
		ivatotal, taxabletotal, previvatotalpayed, prevtotalpayed,
		currivagrosspayed,
		currivapayed
	)
	(SELECT
		I.idinvkind,I.yinv,I.ninv, 'S', 'V', IRK.idivaregisterkind,
		TIV.ivatotal, TIV.taxabletotal, SUM(I_D.ivatotalpayed), SUM(I_D.totalpayed),
		- ISNULL(
			(SELECT SUM(ROUND(ISNULL(I_DET.tax,0) * I2.exchangerate,2))
			FROM invoicedetail I_DET
			JOIN invoice I2
				ON I2.idinvkind = I_DET.idinvkind
				AND I2.yinv = I_DET.yinv
				AND I2.ninv = I_DET.ninv
			JOIN incomevar IVI2
				ON IVI2.idinvkind = I2.idinvkind
				AND IVI2.yinv = I2.yinv
				AND IVI2.ninv = I2.ninv
			JOIN proceedsemitted PE1
				ON PE1.idinc = I_DET.idinc_iva
			WHERE I.idinvkind = I_DET.idinvkind
				AND I.yinv = I_DET.yinv
				AND I.ninv = I_DET.ninv
				AND IVI2.movkind IN (1, 2)
				AND I_DET.paymentcompetency IS  NULL
				AND PE1.competencydate BETWEEN @datebegin AND @dateend)
		,0) -
		ISNULL(
			(SELECT ISNULL(SUM(I_D1.ivatotalpayed),0)
			FROM invoicedeferred I_D1
			JOIN ivapay IP
				ON I_D1.yivapay = IP.yivapay
				AND I_D1.nivapay = IP.nivapay
			WHERE IP.start >= @datebegin AND IP.stop <= @dateend
				AND I_D1.idinvkind = I.idinvkind
				AND I_D1.yinv = I.yinv
				AND I_D1.ninv = I.ninv)
		,0),
		- ISNULL(
			(SELECT SUM(ROUND(ISNULL(I_DET.tax,0) * I2.exchangerate,2))
			FROM invoicedetail I_DET
			JOIN invoice I2
				ON I2.idinvkind = I_DET.idinvkind
				AND I2.yinv = I_DET.yinv
				AND I2.ninv = I_DET.ninv
			JOIN incomevar IVI2
				ON IVI2.idinvkind = I2.idinvkind
				AND IVI2.yinv = I2.yinv
				AND IVI2.ninv = I2.ninv
			JOIN proceedsemitted PE1
				ON PE1.idinc = I_DET.idinc_iva
			WHERE I.idinvkind = I_DET.idinvkind
				AND I.yinv = I_DET.yinv
				AND I.ninv = I_DET.ninv
				AND IVI2.movkind IN (1, 2)
				AND I_DET.paymentcompetency IS  NULL
				AND PE1.competencydate BETWEEN @datebegin AND @dateend)
		,0) -
		ISNULL(
			(SELECT ISNULL(SUM(I_D1.ivatotalpayed),0)
			FROM invoicedeferred I_D1
			JOIN ivapay IP
				ON I_D1.yivapay = IP.yivapay
				AND I_D1.nivapay = IP.nivapay
			WHERE IP.start >= @datebegin AND IP.stop <= @dateend
				AND I_D1.idinvkind = I.idinvkind
				AND I_D1.yinv = I.yinv
				AND I_D1.ninv = I.ninv)
		,0)
	FROM incomevar MOV
	JOIN proceedsemitted PE
		ON PE.idinc = MOV.idinc
	JOIN invoice I
		ON MOV.idinvkind = I.idinvkind
		AND MOV.yinv = I.yinv
		AND MOV.ninv = I.ninv
	LEFT OUTER JOIN invoicedeferred I_D
		ON I_D.idinvkind = I.idinvkind
		AND I_D.yinv = I.yinv
		AND I_D.ninv = I.ninv
	JOIN totinvoiceview TIV
		ON TIV.idinvkind = I.idinvkind
		AND TIV.yinv = I.yinv
		AND TIV.ninv = I.ninv
	JOIN ivaregister IR
		ON IR.idinvkind = I.idinvkind
		AND IR.yinv = I.yinv
		AND IR.ninv = I.ninv
	JOIN ivaregisterkind IRK
		ON IRK.idivaregisterkind = IR.idivaregisterkind
	WHERE MOV.movkind IN (1, 2)
		AND IRK.registerclass = 'V'
		AND PE.competencydate BETWEEN @datebegin AND @dateend
		AND I.flagdeferred = 'S'
	GROUP BY I.idinvkind,I.yinv,I.ninv,MOV.movkind, IRK.idivaregisterkind,
	TIV.ivatotal, TIV.taxabletotal)
	
	-- Note di Credito
	-- Cerco tutti i dettagli delle note di credito emesse ai quali è stata specificata
	-- una data di competenza ricadente nel range di date fornito in input alla SP
	INSERT INTO #invoice
	(
		idinvkind, yinv, ninv, flagdeferred, registerclass, idivaregisterkind,
		ivatotal, taxabletotal, previvatotalpayed, prevtotalpayed,
		currivagrosspayed,
		currivapayed
	)
	(SELECT
		I.idinvkind,I.yinv,I.ninv, 'S', 'V', IRK.idivaregisterkind,
		TIV.ivatotal, TIV.taxabletotal, SUM(I_D.ivatotalpayed), SUM(I_D.totalpayed),
		- ISNULL(
			(SELECT SUM(ROUND(ISNULL(I_DET.tax,0) * I2.exchangerate,2))
			FROM invoicedetail I_DET
			JOIN invoice I2
				ON I2.idinvkind = I_DET.idinvkind
				AND I2.yinv = I_DET.yinv
				AND I2.ninv = I_DET.ninv
			WHERE I.idinvkind = I_DET.idinvkind
				AND I.yinv = I_DET.yinv
				AND I.ninv = I_DET.ninv
				AND I_DET.paymentcompetency BETWEEN @datebegin AND @dateend
				)
		,0) -
		ISNULL(
			(SELECT ISNULL(SUM(I_D1.ivatotalpayed),0)
			FROM invoicedeferred I_D1
			JOIN ivapay IP
				ON I_D1.yivapay = IP.yivapay
				AND I_D1.nivapay = IP.nivapay
			WHERE IP.start >= @datebegin AND IP.stop <= @dateend
				AND I_D1.idinvkind = I.idinvkind
				AND I_D1.yinv = I.yinv
				AND I_D1.ninv = I.ninv)
		,0),
		- ISNULL(
			(SELECT SUM(ROUND(ISNULL(I_DET.tax,0) * I2.exchangerate,2))
			FROM invoicedetail I_DET
			JOIN invoice I2
				ON I2.idinvkind = I_DET.idinvkind
				AND I2.yinv = I_DET.yinv
			WHERE I.idinvkind = I_DET.idinvkind
				AND I.yinv = I_DET.yinv
				AND I.ninv = I_DET.ninv
				AND I_DET.paymentcompetency BETWEEN @datebegin AND @dateend
				)
		,0) -
		ISNULL(
			(SELECT ISNULL(SUM(I_D1.ivatotalpayed),0)
			FROM invoicedeferred I_D1
			JOIN ivapay IP
				ON I_D1.yivapay = IP.yivapay
				AND I_D1.nivapay = IP.nivapay
			WHERE IP.start >= @datebegin AND IP.stop <= @dateend
				AND I_D1.idinvkind = I.idinvkind
				AND I_D1.yinv = I.yinv
				AND I_D1.ninv = I.ninv)
		,0)
	FROM  invoice I
	LEFT OUTER JOIN invoicedeferred I_D
		ON I_D.idinvkind = I.idinvkind
		AND I_D.yinv = I.yinv
		AND I_D.ninv = I.ninv
	JOIN invoicedetail I_DET1
		ON I.idinvkind = I_DET1.idinvkind
		AND I.yinv = I_DET1.yinv
		AND I.ninv = I_DET1.ninv
	JOIN totinvoiceview TIV
		ON TIV.idinvkind = I.idinvkind
		AND TIV.yinv = I.yinv
		AND TIV.ninv = I.ninv
	JOIN ivaregister IR
		ON IR.idinvkind = I.idinvkind
		AND IR.yinv = I.yinv
		AND IR.ninv = I.ninv
	JOIN ivaregisterkind IRK
		ON IRK.idivaregisterkind = IR.idivaregisterkind
	JOIN invoicekind IK
		ON IK.idinvkind = I.idinvkind
	WHERE 	IRK.registerclass = 'V'
		AND I_DET1.paymentcompetency BETWEEN @datebegin AND @dateend
		AND I.flagdeferred = 'S'
		AND (IK.flag & 1 <> 0)
		AND (IK.flag & 4 <> 0)
	GROUP BY I.idinvkind,I.yinv,I.ninv, IRK.idivaregisterkind,
	TIV.ivatotal, TIV.taxabletotal)
	-- Select finale che visualizza l'IVA a debito raggruppata per tipo di registro al quale
	-- appartiene il documento e per IVA differita / immediata
	SELECT #invoice.idivaregisterkind, ivaregisterkind.description,
	SUM(currivapayed)
	- ISNULL(
		(SELECT iva FROM #oldivapay
		WHERE #invoice.idivaregisterkind = #oldivapay.idivaregisterkind
		AND #invoice.flagdeferred = 'N')
	,0) AS iva,
	#invoice.flagdeferred
	FROM #invoice
	JOIN ivaregisterkind
		ON ivaregisterkind.idivaregisterkind = #invoice.idivaregisterkind
	GROUP BY #invoice.idivaregisterkind, ivaregisterkind.description, #invoice.flagdeferred
	HAVING SUM(currivagrosspayed) <> 0
END



GO

print '[compute_ivapayexpense] OK'

