if object_id('compute_allowform') is not null
	drop PROCEDURE compute_allowform
go

CREATE PROCEDURE compute_allowform
(
	@ayear int,
	@iduser varchar(10),
	@idflowchart varchar(34),
	@varname varchar(30)
)
AS BEGIN
CREATE TABLE #outtable
(
	tablename varchar(100)
)
IF (@idflowchart IS NULL)
BEGIN
	INSERT INTO #outtable
	SELECT DISTINCT metadata
	FROM menu
	WHERE metadata IS NOT NULL 
	SELECT tablename FROM #outtable where tablename <>'no_table'
	RETURN
END
-- Vengono considerate solamente le funzioni di restrizione che agiscono sul menu (le individuiamo noi)
-- Per tutte le restrizioni (tranne che per configurazione) prendo i primi 2 livelli di menu
-- Gestione Spese
IF (
	(SELECT COUNT(*)
	FROM flowchartrestrictedfunction FF
	JOIN restrictedfunction RF
		ON RF.idrestrictedfunction = FF.idrestrictedfunction
	WHERE FF.idflowchart = @idflowchart
		AND RF.variablename in ( 'management') ) > 0 )
BEGIN
	INSERT INTO #outtable
	SELECT DISTINCT M2.metadata
	FROM menu M
	JOIN menu M2
		ON M.idmenu = M2.paridmenu
	WHERE M.menucode in ( 'codmanrules','codtransazioni')
	AND M2.metadata IS NOT NULL
	AND NOT EXISTS
		(SELECT * FROM #outtable O
		WHERE O.tablename = M2.metadata)
	INSERT INTO #outtable
	SELECT DISTINCT M3.metadata
	FROM menu M
	JOIN menu M2
		ON M.idmenu = M2.paridmenu
	JOIN menu M3
		ON M2.idmenu = M3.paridmenu
	WHERE M.menucode in ( 'codmanrules','codtransazioni')
	AND M3.metadata IS NOT NULL
	AND NOT EXISTS
		(SELECT * FROM #outtable O
		WHERE O.tablename = M3.metadata)
END
-- Gestione Spese
IF (
	(SELECT COUNT(*)
	FROM flowchartrestrictedfunction FF
	JOIN restrictedfunction RF
		ON RF.idrestrictedfunction = FF.idrestrictedfunction
	WHERE FF.idflowchart = @idflowchart
		AND RF.variablename in ( 'spesa','spesa_read') ) > 0 )
BEGIN
	INSERT INTO #outtable
	SELECT DISTINCT M2.metadata
	FROM menu M
	JOIN menu M2
		ON M.idmenu = M2.paridmenu
	WHERE M.menucode = 'codspese'
	AND M2.metadata IS NOT NULL
	AND NOT EXISTS
		(SELECT * FROM #outtable O
		WHERE O.tablename = M2.metadata)
	INSERT INTO #outtable
	SELECT DISTINCT M3.metadata
	FROM menu M
	JOIN menu M2
		ON M.idmenu = M2.paridmenu
	JOIN menu M3
		ON M2.idmenu = M3.paridmenu
	WHERE M.menucode = 'codspese'
	AND M3.metadata IS NOT NULL
	AND NOT EXISTS
		(SELECT * FROM #outtable O
		WHERE O.tablename = M3.metadata)
END
-- Gestione Entrate
IF (
	(SELECT COUNT(*)
	FROM flowchartrestrictedfunction FF
	JOIN restrictedfunction RF
		ON RF.idrestrictedfunction = FF.idrestrictedfunction
	WHERE FF.idflowchart = @idflowchart
		AND RF.variablename in ('entrata','entrata_read')) > 0   )
BEGIN
	INSERT INTO #outtable
	SELECT DISTINCT M2.metadata
	FROM menu M
	JOIN menu M2
		ON M.idmenu = M2.paridmenu
	WHERE M.menucode = 'codentrate'
	AND M2.metadata IS NOT NULL
	AND NOT EXISTS
		(SELECT * FROM #outtable O
		WHERE O.tablename = M2.metadata)
	INSERT INTO #outtable
	SELECT DISTINCT M3.metadata
	FROM menu M
	JOIN menu M2
		ON M.idmenu = M2.paridmenu
	JOIN menu M3
		ON M2.idmenu = M3.paridmenu
	WHERE M.menucode = 'codentrate'
	AND M3.metadata IS NOT NULL
	AND NOT EXISTS
		(SELECT * FROM #outtable O
		WHERE O.tablename = M3.metadata)
END
-- Gestione IVA
IF (
	(SELECT COUNT(*)
	FROM flowchartrestrictedfunction FF
	JOIN restrictedfunction RF
		ON RF.idrestrictedfunction = FF.idrestrictedfunction
	WHERE FF.idflowchart = @idflowchart
		AND RF.variablename = 'iva')) > 0
BEGIN
	INSERT INTO #outtable
	SELECT DISTINCT M2.metadata
	FROM menu M
	JOIN menu M2
		ON M.idmenu = M2.paridmenu
	WHERE M.menucode = 'codiva'
	AND M2.metadata IS NOT NULL
	AND NOT EXISTS
		(SELECT * FROM #outtable O
		WHERE O.tablename = M2.metadata)
	INSERT INTO #outtable
	SELECT DISTINCT M3.metadata
	FROM menu M
	JOIN menu M2
		ON M.idmenu = M2.paridmenu
	JOIN menu M3
		ON M2.idmenu = M3.paridmenu
	WHERE M.menucode = 'codiva'
	AND M3.metadata IS NOT NULL
	AND NOT EXISTS
		(SELECT * FROM #outtable O
		WHERE O.tablename = M3.metadata)
END
-- Gestione Fatture
IF (
	(SELECT COUNT(*)
	FROM flowchartrestrictedfunction FF
	JOIN restrictedfunction RF
		ON RF.idrestrictedfunction = FF.idrestrictedfunction
	WHERE FF.idflowchart = @idflowchart
		AND RF.variablename = 'fattura')) > 0
BEGIN
    INSERT INTO #outtable 
	SELECT DISTINCT M2.metadata
	FROM menu M
	JOIN menu M2
		ON M.idmenu = M2.paridmenu
	WHERE M2.metadata IN('invoice','invoicedetail','ivaregister')
	AND NOT EXISTS
		(SELECT * FROM #outtable O
		WHERE O.tablename = M2.metadata)
END

-- Gestione Magazzino
IF (
	(SELECT COUNT(*)
	FROM flowchartrestrictedfunction FF
	JOIN restrictedfunction RF
		ON RF.idrestrictedfunction = FF.idrestrictedfunction
	WHERE FF.idflowchart = @idflowchart
		AND RF.variablename IN ('adm_magazzino','config_magazzino'))) > 0
BEGIN
    INSERT INTO #outtable 
	SELECT DISTINCT M2.metadata
	FROM menu M
	JOIN menu M2
		ON M.idmenu = M2.paridmenu
	WHERE M2.metadata IN ('store','stock','list','listclass','bookingdetail','booking', 
						  'ddt_in','storeunload','showcase')
	AND NOT EXISTS
		(SELECT * FROM #outtable O
		WHERE O.tablename = M2.metadata)
END

-- Gestione Card Magazzino
IF (
	(SELECT COUNT(*)
	FROM flowchartrestrictedfunction FF
	JOIN restrictedfunction RF
		ON RF.idrestrictedfunction = FF.idrestrictedfunction
	WHERE FF.idflowchart = @idflowchart
		AND RF.variablename IN ('admin_card','crea_card'))) > 0
BEGIN
    INSERT INTO #outtable 
	SELECT DISTINCT M2.metadata
	FROM menu M
	JOIN menu M2
		ON M.idmenu = M2.paridmenu
	WHERE M2.metadata IN ('lcard')
	AND NOT EXISTS
		(SELECT * FROM #outtable O
		WHERE O.tablename = M2.metadata)
END
-- Gestione Patrimoniale
IF (
	(SELECT COUNT(*)
	FROM flowchartrestrictedfunction FF
	JOIN restrictedfunction RF
		ON RF.idrestrictedfunction = FF.idrestrictedfunction
	WHERE FF.idflowchart = @idflowchart
		AND RF.variablename in ('cespiti','cespiti_read'))) > 0
BEGIN
	INSERT INTO #outtable
	SELECT DISTINCT M2.metadata
	FROM menu M
	JOIN menu M2
		ON M.idmenu = M2.paridmenu
	WHERE M.menucode IN ('codpatrimonio', 'codcons')
	AND M2.metadata IS NOT NULL
	AND NOT EXISTS
		(SELECT * FROM #outtable O
		WHERE O.tablename = M2.metadata)
	AND (M2.metadata <> 'sortingkind')
	INSERT INTO #outtable
	SELECT DISTINCT M3.metadata
	FROM menu M
	JOIN menu M2
		ON M.idmenu = M2.paridmenu
	JOIN menu M3
		ON M2.idmenu = M3.paridmenu
	WHERE M.menucode IN ('codpatrimonio', 'codcons')
	AND M3.metadata IS NOT NULL
	AND NOT EXISTS
		(SELECT * FROM #outtable O
		WHERE O.tablename = M3.metadata)
	AND (M3.metadata <> 'sortingkind')
	INSERT INTO #outtable
	SELECT DISTINCT M4.metadata
	FROM menu M
	JOIN menu M2
		ON M.idmenu = M2.paridmenu
	JOIN menu M3
		ON M2.idmenu = M3.paridmenu
	JOIN menu M4
		ON M3.idmenu = M4.paridmenu
	WHERE M.menucode IN ('codpatrimonio', 'codcons')
	AND M4.metadata IS NOT NULL
	AND NOT EXISTS
		(SELECT * FROM #outtable O
		WHERE O.tablename = M4.metadata)
	AND (M4.metadata <> 'sortingkind')
	INSERT INTO #outtable
	SELECT DISTINCT M5.metadata
	FROM menu M
	JOIN menu M2
		ON M.idmenu = M2.paridmenu
	JOIN menu M3
		ON M2.idmenu = M3.paridmenu
	JOIN menu M4
		ON M3.idmenu = M4.paridmenu
	JOIN menu M5
		ON M4.idmenu = M5.paridmenu
	WHERE M.menucode IN ('codpatrimonio', 'codcons')
	AND M5.metadata IS NOT NULL
	AND NOT EXISTS
		(SELECT * FROM #outtable O
		WHERE O.tablename = M5.metadata)
	AND M5.metadata IS NOT NULL
END
-- Gestione E/P
IF (
	(SELECT COUNT(*)
	FROM flowchartrestrictedfunction FF
	JOIN restrictedfunction RF
		ON RF.idrestrictedfunction = FF.idrestrictedfunction
	WHERE FF.idflowchart = @idflowchart
		AND RF.variablename IN ('econopatr','eco_entry'))) > 0
BEGIN
	INSERT INTO #outtable
	SELECT DISTINCT M2.metadata
	FROM menu M
	JOIN menu M2
		ON M.idmenu = M2.paridmenu
	WHERE M.menucode IN ('ep', 'scrittureEP')
	AND M2.metadata IS NOT NULL
	AND NOT EXISTS
		(SELECT * FROM #outtable O
		WHERE O.tablename = M2.metadata)
	INSERT INTO #outtable
	SELECT DISTINCT M3.metadata
	FROM menu M
	JOIN menu M2
		ON M.idmenu = M2.paridmenu
	JOIN menu M3
		ON M2.idmenu = M3.paridmenu
	WHERE M.menucode IN ('ep', 'scrittureEP')
	AND M3.metadata IS NOT NULL
	AND NOT EXISTS
		(SELECT * FROM #outtable O
		WHERE O.tablename = M3.metadata)
END
-- Gestione Compensi
IF (
	(SELECT COUNT(*)
	FROM flowchartrestrictedfunction FF
	JOIN restrictedfunction RF
		ON RF.idrestrictedfunction = FF.idrestrictedfunction
	WHERE FF.idflowchart = @idflowchart
		AND RF.variablename = 'compensi')) > 0
BEGIN
	INSERT INTO #outtable
	SELECT DISTINCT M2.metadata
	FROM menu M
	JOIN menu M2
		ON M.idmenu = M2.paridmenu
	WHERE M.menucode IN ('codmissioni', 'codcococo', 'codtabseccococo',
	'codContratto', 'codoccasionali', 'codprofessionali', 'coddipendente', 'codadmpay')
	AND M2.metadata IS NOT NULL
	AND NOT EXISTS
		(SELECT * FROM #outtable O
		WHERE O.tablename = M2.metadata)
	INSERT INTO #outtable
	SELECT DISTINCT M3.metadata
	FROM menu M
	JOIN menu M2
		ON M.idmenu = M2.paridmenu
	JOIN menu M3
		ON M2.idmenu = M3.paridmenu
	WHERE M.menucode IN ('codmissioni', 'codcococo', 'codtabseccococo',
	'codContratto', 'codoccasionali', 'codprofessionali', 'coddipendente', 'codadmpay')
	AND M3.metadata IS NOT NULL
	AND NOT EXISTS
		(SELECT * FROM #outtable O
		WHERE O.tablename = M3.metadata)
END

-- Gestione Compensi : solo Missioni
IF (
	(SELECT COUNT(*)
	FROM flowchartrestrictedfunction FF
	JOIN restrictedfunction RF
		ON RF.idrestrictedfunction = FF.idrestrictedfunction
	WHERE FF.idflowchart = @idflowchart
		AND RF.variablename in ( 'missioni'))) > 0
BEGIN
	INSERT INTO #outtable
	SELECT DISTINCT M2.metadata
	FROM menu M
	JOIN menu M2
		ON M.idmenu = M2.paridmenu
	WHERE M.menucode IN ('codmissioni')
	AND M2.metadata IS NOT NULL
	AND NOT EXISTS
		(SELECT * FROM #outtable O
