if object_id('[rpt_certritacconto]') is not null
	drop PROCEDURE [rpt_certritacconto]
go

CREATE     PROCEDURE [rpt_certritacconto]
(
	@ayear smallint, 
	@idreg int, 
	@start datetime,
	@stop datetime,
	@certificatekind char(1)
)
AS BEGIN

/*
	exec rpt_certritacconto 2010,0 ,{ts '2010-01-01 00:00:00'},{ts '2010-12-31 00:00:00'}, 'F'
	exec [rpt_unified_certritacconto] 2010,15317,{ts '2010-01-01 00:00:00'},{ts '2010-12-31 00:00:00'}, 'F', 'S'
*/

CREATE TABLE #expensetax
(
	idexp int,
	idreg int,
	taxdescription varchar(50),
	expensedescription varchar(150),	
	commondetail char(1),
	taxablenet decimal(19,2),
	employtax decimal(19,2),
	admintax decimal(19,2),
	grossamount decimal (19,2),
	service varchar(50),
	module varchar(15),
	idser int,
	npay int
)

CREATE TABLE #address_to_send
(
	idaddresskind int,
	idreg int,
	officename varchar(50),
	address varchar(100),
	location varchar(120),
	cap varchar(20),
	province varchar(2),
	nation varchar(65)
)

IF @ayear = 0
BEGIN
	SET @ayear='1900'
END

DECLARE @dateaddress datetime
SELECT @dateaddress = CONVERT(datetime, '31-12-'+ CONVERT(varchar(4),@ayear), 105)

INSERT INTO #expensetax
(
	idexp,
	idreg,
	taxdescription,
	expensedescription,
	taxablenet,
	employtax, 
	admintax, 
	grossamount,--Importo Lordo del Pagamento
	service,
	idser,
	module,
	npay
)
SELECT
	T.idexp,
	T.idreg,
	T.taxdescription,
	T.expensedescription,
	SUM(T.taxablenet),
	SUM(T.employtax),
	SUM(T.admintax), 
	CASE 
	WHEN service.module in ('OCCASIONALE','DIPENDENTE') THEN
	(ISNULL(expenseyear.amount,0) + 
	 ISNULL(
		(SELECT ISNULL(SUM(v.amount), 0.0)
		FROM expensevar v
		WHERE idexp=T.idexp					
			AND (ISNULL(v.autokind,0)<>4)					
		),0)		
	)
	ELSE NULL
	END,
	service.description,
	service.idser,
	service.module,
	payment.npay
FROM
	(SELECT
		SUM(ISNULL(E.taxablenet,0)) AS taxablenet,
		SUM(ISNULL(E.employtax,0)) AS employtax,
		SUM(ISNULL(E.admintax,0)) AS admintax,
		E.idexp,
		expense.idreg,
		E.description as taxdescription,
		expense.description as expensedescription,
		expenselast.idser,
		expenselast.kpay
	FROM expensetaxofficialview AS E
	JOIN expense 
		ON expense.idexp = E.idexp
	JOIN expenselast
		ON expenselast.idexp = expense.idexp 
	JOIN service
		ON service.idser = expenselast.idser
	WHERE expense.ymov = @ayear  
		AND (expense.idreg=@idreg OR @idreg=0)
		AND service.certificatekind = @certificatekind
		AND E.stop IS NULL
	GROUP BY expense.idreg,E.idexp,expenselast.idser,
		E.description,expense.description,
                expenselast.kpay) AS T
JOIN expensetotal
	ON T.idexp = expensetotal.idexp  
JOIN expenseyear
	ON T.idexp = expenseyear.idexp
JOIN service
	ON T.idser = service.idser  
JOIN payment 
	ON T.kpay = payment.kpay  
JOIN paymenttransmission
	ON payment.kpaymenttransmission = paymenttransmission.kpaymenttransmission  
WHERE (paymenttransmission.transmissiondate BETWEEN @start AND @stop)
	AND service.certificatekind = @certificatekind
	AND expensetotal.ayear = @ayear
	AND expenseyear.ayear = @ayear
GROUP BY T.idreg, T.idexp,
	T.taxdescription, expenseyear.amount, service.description, service.module,
	service.idser,payment.npay,T.expensedescription--,T.taxablegross	

DECLARE  @appropriation tinyint
SELECT  @appropriation = expensephase FROM config WHERE ayear =@ayear

-- VALORIZZAZIONE DEL CAMPO grossamount per i contratti professionali
-- CICLO SU #expensetax

DECLARE  @idreg1 INT
DECLARE  @idexp  INT

DECLARE @spesededucibilifis decimal(19,2)
DECLARE @imponibilereale decimal(19,2)	
DECLARE @impon_spesa decimal(19,2)
DECLARE @impon_contratto decimal(19,2)
DECLARE @quota_contratto float
DECLARE @ypro int
DECLARE @npro int
	SET @ypro = null
	SET @npro = null


DECLARE rowcursor INSENSITIVE CURSOR FOR
SELECT  idreg,idexp
FROM #expensetax
WHERE module = 'PROFESSIONALE'
ORDER BY idreg asc
FOR READ ONLY
OPEN rowcursor
	
FETCH NEXT FROM rowcursor
INTO @idreg1, @idexp
WHILE @@FETCH_STATUS = 0
BEGIN 
SELECT @ypro = ycon, @npro = ncon
		FROM profservice  C
		WHERE EXISTS(select * from expenseprofservice EC
				join expenselink EL on EC.idexp=EL.idparent						
				where EL.idchild=@idexp
					AND C.ycon=EC.ycon and C.ncon=EC.ncon)
		IF (@ypro is not null)  -- si tratta di un contratto professionale
		BEGIN
			SELECT @spesededucibilifis= SUM(amount) FROM profservicerefund PR
				join profrefund P on PR.idlinkedrefund=P.idlinkedrefund
				WHERE P.flagfiscaldeduction='S' AND
					PR.ycon=@ypro and PR.ncon=@npro
--print 'NPRO'		
--print @npro 				
			SET @imponibilereale=0
			SELECT @imponibilereale = SUM(convert(DECIMAL(19,2),
					ROUND(taxablenet*isnull(taxabledenominator,1)/isnull(taxablenumerator,1),2)))
					FROM profservicetax	 
					JOIN tax T ON profservicetax.taxcode=T.taxcode 
				WHERE profservicetax.ycon=@ypro and profservicetax.ncon=@npro and T.taxkind=1 
							and 	isnull(taxablenet,0)<>0 and isnull(taxabledenominator,0)<>0
			
				
			-----------------------------------------------------------------------	
			-- IMPONIBILE DELLA SPESA ---------------------------------------------
			-----------------------------------------------------------------------
		
			select  @impon_spesa = SUM(ET.taxablegross) from expensetaxofficial ET
				JOIN tax T ON ET.taxcode=T.taxcode 	
				WHERE ET.idexp=@idexp and  T.taxkind=1
				AND ET.stop IS NULL
				
			select  @impon_contratto = taxablegross from profservicetax	
				JOIN tax T ON profservicetax.taxcode=T.taxcode 
				WHERE profservicetax.ycon=@ypro and profservicetax.ncon=@npro and T.taxkind=1		
--print @impon_spesa
--print @impon_contratto
			if (isnull(@impon_spesa,0)=0 OR isnull(@impon_contratto,0)=0)
				SET     @quota_contratto=1
			ELSE
				SET     @quota_contratto=isnull(@impon_spesa,0)/isnull(@impon_contratto,0)
--print @quota_contratto
--print '-----------'
			
			--- VALORIZZO L'AMMONTARE LORDO CORRISPOSTO
			UPDATE  #expensetax
			SET grossamount =
				ISNULL(ROUND(@quota_contratto*(isnull(@spesededucibilifis,0)+isnull(@imponibilereale,0) ),2),0)
			WHERE #expensetax.idreg = @idreg1
			AND	  #expensetax.idexp = @idexp
		END
		
FETCH NEXT FROM rowcursor
INTO @idreg, @idexp
END 
DEALLOCATE rowcursor

-- Fondo economale :
UPDATE #expensetax
		SET grossamount = grossamount + isnull(
			(SELECT SUM(pettycashoperation.amount)
		FROM pettycashoperation
		JOIN pettycashoperationcasualcontract
			ON  pettycashoperation.idpettycash = pettycashoperationcasualcontract.idpettycash
			AND pettycashoperation.yoperation  = pettycashoperationcasualcontract.yoperation
			AND pettycashoperation.noperation  = pettycashoperationcasualcontract.noperation
		JOIN casualcontract 
			ON  casualcontract.ycon  = pettycashoperationcasualcontract.ycon
			AND casualcontract.ncon  = pettycashoperationcasualcontract.ncon
		join expensecasualcontract
			ON expensecasualcontract.ycon = casualcontract.ycon
			and expensecasualcontract.ncon = casualcontract.ncon
		join expense
			ON expense.idexp = expensecasualcontract.idexp
		join expenselink 
			on expenselink.idparent = expense.idexp 
 		WHERE 
			expenselink.nlevel = @appropriation
			and casualcontract.idreg = #expensetax.idreg
			AND casualcontract.idser = #expensetax.idser
			AND expenselink.idchild = #expensetax.idexp
			AND (pettycashoperation.adate BETWEEN @start AND @stop) 
                        )
		,0)

UPDATE #expensetax
	SET grossamount =  grossamount + isnull(
		(SELECT SUM(ISNULL(pettycashoperation.amount, 0))
	FROM pettycashoperation
	JOIN pettycashoperationprofservice
		ON pettycashoperation.idpettycash = pettycashoperationprofservice.idpettycash
		AND pettycashoperation.yoperation = pettycashoperationprofservice.yoperation
		AND pettycashoperation.noperation = pettycashoperationprofservice.noperation
	JOIN profservice 
		ON  profservice.ycon  = pettycashoperationprofservice.ycon
		AND profservice.ncon  = pettycashoperationprofservice.ncon
	join expenseprofservice
		ON expenseprofservice.ycon = profservice.ycon
		and expenseprofservice.ncon = profservice.ncon
	join expense
		ON expense.idexp = expenseprofservice.idexp
	join expenselink 
		on expenselink.idparent = expense.idexp 
	WHERE expenselink.nlevel = @appropriation
		AND (profservice.idreg = #expensetax.idreg)
		AND profservice.idser = #expensetax.idser
		AND expenselink.idchild = #expensetax.idexp
		AND (pettycashoperation.adate BETWEEN @start AND @stop)
                    )
	,0)
	
DECLARE @codenostand varchar(20)
SET @codenostand = '07_SW_CER'

DECLARE @codestand varchar(20)
SET @codestand = '07_SW_DEF'

DECLARE @STAND int
SELECT @STAND = idaddress FROM address WHERE codeaddress = @codestand

DECLARE @NOSTAND int
SELECT @NOSTAND = idaddress FROM address WHERE codeaddress = @codenostand

-- Inizio calcolo indirizzi
INSERT INTO #address_to_send
(
	idaddresskind,
	idreg,
	address,
	location,
	cap,
	province
)
SELECT 
	idaddresskind,
	registryaddress.idreg, 
	address,
	ISNULL(geo_city.title + ' ','') + ISNULL(registryaddress.location,'') + 
	CASE 
		WHEN registryaddress.idnation IS NOT NULL THEN ' ' + geo_nation.title ELSE ''
	END,
	registryaddress.cap,
	geo_country.province
FROM registryaddress
LEFT OUTER JOIN geo_city
	ON geo_city.idcity = registryaddress.idcity
LEFT OUTER JOIN geo_country
	ON geo_city.idcountry = geo_country.idcountry
LEFT OUTER JOIN geo_nation
	ON registryaddress.idnation = geo_nation.idnation
WHERE (registryaddress.active <>'N' 
        AND (idreg IN (select idreg from  #expensetax))
	AND registryaddress.start = 
		(SELECT MAX(cdi.start) 
		FROM registryaddress cdi 
		WHERE cdi.idaddresskind = registryaddress.idaddresskind
			AND cdi.active <>'N' 
			AND cdi.start <= @dateaddress
			AND cdi.idreg = registryaddress.idreg)
)

DELETE #address_to_send
WHERE #address_to_send.idaddresskind <> @nostand
AND EXISTS(
	SELECT * FROM #address_to_send r2 
	WHERE #address_to_send.idreg = r2.idreg
		AND r2.idaddresskind = @NOSTAND
	)

DELETE #address_to_send
WHERE #address_to_send.idaddresskind NOT IN (@NOSTAND, @STAND)
AND EXISTS(
	SELECT * FROM #address_to_send r2 
	WHERE #address_to_send.idreg = r2.idreg
		AND r2.idaddresskind = @STAND
	)

DELETE #address_to_send
WHERE (
	SELECT COUNT(*) FROM #address_to_send r2 
	WHERE #address_to_send.idreg = r2.idreg
)>1

	
DECLARE @departmentname varchar(500)
SET  @departmentname  = ISNULL( (SELECT top 1 paramvalue from
    generalreportparameter where idparam='DenominazioneDipartimento' 
    and  (ISNULL(start, {d '1900-01-01'}) = {d '1900-01-01'} or year(start) <= @ayear) 
    and  (ISNULL(stop, {d '2079-06-06'}) = {d '2079-06-06'}  or year(stop) >= @ayear)
    order by ISNULL(stop, {d '2079-06-06'}) desc
    ),'Manca Cfg. Parametri Tutte le stampe')


SELECT
    @departmentname as departmentname,
	#expensetax.idexp,
	#expensetax.idreg,
	registry.title as registry,
	ISNULL(geo_city.title, '') + ' ' + ISNULL(registry.location,'') AS b_city,
	registry.birthdate,
	ISNULL(geo_country.province, '') AS b_province,
	ISNULL(geo_nation.title, 'ITALIA') AS b_nation,
	registry.cf, 
    registry.p_iva,
	#expensetax.taxdescription,
	expensedescription,	
	#expensetax.service,
	#expensetax.idser,
	#expensetax.module,
	#expensetax.npay,
	(#expensetax.taxablenet) as taxablenet,
	(SELECT SUM(TGROSS.expenseamount)
		FROM (	SELECT MAX(E1.grossamount) AS expenseamount
			FROM  #expensetax  E1
			WHERE E1.idreg = #expensetax.idreg
		GROUP BY E1.idexp) AS TGROSS) AS grossamount,--Importo Lordo del Pagamento*/
	(#expensetax.employtax) as employtax,
	(#expensetax.admintax) as admintax,
	#address_to_send.address AS sent_address,
	#address_to_send.location AS sent_location,
	#address_to_send.cap AS sent_cap,
	#address_to_send.province AS sent_province,
	registry.foreigncf,
	registryclass.flaghuman
FROM #expensetax
JOIN registry 
        ON #expensetax.idreg = registry.idreg
JOIN registryclass 
        ON registryclass.idregistryclass = registry.idregistryclass
LEFT OUTER JOIN geo_city
	ON registry.idcity = geo_city.idcity  
LEFT OUTER JOIN geo_country
	ON geo_city.idcountry = geo_country.idcountry
LEFT OUTER JOIN geo_nation
	ON registry.idnation = geo_nation.idnation  
LEFT OUTER JOIN #address_to_send
	ON #address_to_send.idreg = #expensetax.idreg
order by registry.title

DROP TABLE #expensetax
DROP TABLE #address_to_send

END



GO

print '[rpt_certritacconto] OK'

GO
if object_id('[rpt_mov_class_incomplete_o_mancanti]') is not null
	drop PROCEDURE [rpt_mov_class_incomplete_o_mancanti]
go


CREATE                              PROCEDURE [rpt_mov_class_incomplete_o_mancanti]
	@ayear 	           smallint,
	@idsorkind   	   int,
	@incomeorexpense   char(1),
	@start	   smalldatetime,
	@stop	   smalldatetime
AS
BEGIN
/*
exec rpt_mov_class_incomplete_o_mancanti 2007,'SIOPE', 'E',{ts '2007-01-20 00:00:00'},{ts '2007-08-20 00:00:00'}
*/
	DECLARE @sortingkind	 varchar(50)
	SELECT @sortingkind = description 
		FROM sortingkind where idsorkind=@idsorkind
	DECLARE @nphase  tinyint 
	IF (@incomeorexpense = 'E')
	BEGIN
		SELECT @nphase = nphaseincome
		FROM sortingkind where idsorkind=@idsorkind
		SELECT
			@idsorkind as 'idsorkind',
			@sortingkind as 'sortingkind',
			incomeview.adate,
			incomeview.phase,
			incomeview.ymov,
			incomeview.nmov,
			incomeview.registry,
			incomeview.codefin,
			incomeview.codeupb,
			incomeview.description,
			isnull(incomeview.curramount,0) as 'curramount',
			isnull((select isnull(sum(incomesorted.amount),0) from incomesorted
				join sorting on sorting.idsor = incomesorted.idsor
			  where incomesorted.idinc=incomeview.idinc and
			        sorting.idsorkind =@idsorkind  and
				incomesorted.ayear=@ayear
			  ) ,0) as'sortedamount'
		FROM incomeview  
		WHERE incomeview.adate BETWEEN 
			isnull(@start, {d '1900-01-01'}) AND isnull(@stop, {d '2079-06-06'})
			AND incomeview.nphase = @nphase
			AND incomeview.ayear=@ayear
			AND ( isnull(incomeview.curramount,0) <> 
	                    			ISNULL( (SELECT sum(amount) 	FROM incomesorted
					                join sorting ON sorting.idsor = incomesorted.idsor
                       					WHERE sorting.idsorkind = @idsorkind
                         					AND incomesorted.idinc = incomeview.idinc
			 			AND incomesorted.ayear=@ayear),0))
		ORDER BY idsorkind ASC,adate ASC,ymov ASC,nmov ASC
	END
	IF (@incomeorexpense = 'S')
	BEGIN
		SELECT 	@nphase = nphaseexpense
		FROM sortingkind WHERE idsorkind=@idsorkind
		SELECT
			@idsorkind as 'idsorkind',
			@sortingkind as 'sortingkind',
			expenseview.adate,
			expenseview.phase,
			expenseview.ymov,
			expenseview.nmov,
			expenseview.registry,
			expenseview.codefin,
			expenseview.codeupb,
			expenseview.description,
			isnull(expenseview.curramount,0) as 'curramount',
			isnull((select isnull(sum(expensesorted.amount),0) 
			   from expensesorted
				join sorting on sorting.idsor = expensesorted.idsor
			  where expensesorted.idexp=expenseview.idexp and
			        sorting.idsorkind =@idsorkind and
				expensesorted.ayear=@ayear	
			) ,0) as 'sortedamount'
		FROM expenseview  
		WHERE expenseview.adate BETWEEN 
			isnull(@start, {d '1900-01-01'}) AND isnull(@stop, {d '2079-06-06'})
			AND expenseview.ayear = @ayear
			AND expenseview.nphase = @nphase
			AND (isnull(expenseview.curramount,0) <> 
                    			ISNULL( (SELECT sum(amount) 
                        				FROM expensesorted
							join sorting on expensesorted.idsor=sorting.idsor
                      					 WHERE sorting.idsorkind = @idsorkind
                         				AND expensesorted.idexp = expenseview.idexp
			 			AND expensesorted.ayear=@ayear
					),0)
			)
		ORDER BY idsorkind ASC,	adate ASC,ymov ASC,nmov ASC
		END
	END



GO

print '[rpt_mov_class_incomplete_o_mancanti] OK'

GO
if object_id('[show_budget_sorting]') is not null
	drop PROCEDURE [show_budget_sorting]
go

CREATE   PROCEDURE [show_budget_sorting]
(
	@date datetime,
	@idupb varchar(36),
	@idsor int 
)
AS
BEGIN
 -- EXEC [show_budget_sorting]  {ts '2013-06-20 00:00:00'},'0001',1568
DECLARE	@ayear int
SELECT @ayear = YEAR(@date)
DECLARE @idsorkind int
SELECT  @idsorkind = idsorkind FROM sorting WHERE idsor = @idsor 
 
CREATE TABLE #situation (value varchar(250), amount decimal(19,2), kind char(1))
DECLARE @descupb varchar(150)
DECLARE @codeupb varchar(50)
SELECT @descupb = title,
	@codeupb = codeupb
FROM upb
WHERE idupb = @idupb

DECLARE @sortingkind varchar(150)
DECLARE @codesorkind varchar(50)
SELECT  @sortingkind = description,
	    @codesorkind = codesorkind
FROM sortingkind
WHERE idsorkind = @idsorkind
DECLARE @levelusable tinyint -- Livello operativo per le voci di bilancio
SELECT  @levelusable = MIN(nlevel) FROM sortinglevel WHERE (flag & 2)<>0 AND idsorkind = @idsorkind 
 
DECLARE	@nlevel tinyint -- Livello della voce di bilancio
DECLARE	@sortcode varchar(50) -- Codice di classificazione
DECLARE	@description varchar(150) -- Descrizione della voce di classificazione
SELECT @nlevel = nlevel, 
	   @sortcode = sortcode, 
	   @description = description 
FROM sorting WHERE idsor = @idsor
DECLARE	@prevision decimal(19,2)
IF (@nlevel < @levelusable) OR (@nlevel IS NULL)
BEGIN
-- ho scelto la categoria (x es)
	SELECT @prevision = ISNULL(SUM(prevision),0) 
	FROM budgetprevisionview 
	JOIN sortinglink
		ON sortinglink.idchild = budgetprevisionview.idsor
	join sorting
		ON budgetprevisionview.idsor = sorting.idsor
	WHERE budgetprevisionview.nlevel  = @levelusable
	and budgetprevisionview.ayear = @ayear
	AND idupb = @idupb
	AND (
		(sortinglink.idparent = @idsor AND sortinglink.nlevel = @nlevel) 
		OR 
		( @nlevel is null AND sortinglink.nlevel = @levelusable)
	    )
--	AND nlevel = @levelusable
END
ELSE
BEGIN
-- ho scelto la voce operativa
	SELECT @prevision= SUM(prevision) 
	FROM budgetprevision
	WHERE idsor = @idsor
	AND idupb = @idupb
	AND budgetprevision.ayear = @ayear
END
DECLARE	@var_prev_aum decimal(19,2)
SELECT  @var_prev_aum = SUM(BVD.amount)
FROM budgetvardetail BVD
JOIN budgetvar BV
	ON BV.ybudgetvar = BVD.ybudgetvar
	AND BV.nbudgetvar = BVD.nbudgetvar
JOIN sortinglink SLK
	ON SLK.idchild = BVD.idsor
join sorting S
	ON BVD.idsor = S.idsor
WHERE 
	(	(SLK.nlevel = @nlevel AND SLK.idparent = @idsor) OR (@idsor is null AND SLK.nlevel = @levelusable)   )
	AND BV.adate <= @date
	AND BVD.idupb = @idupb
	AND BVD.amount > 0
DECLARE	@var_prev_dim decimal(19,2)
SELECT @var_prev_dim = SUM(BVD.amount)
FROM budgetvardetail BVD
JOIN budgetvar BV
	ON BV.ybudgetvar = BVD.ybudgetvar
	AND BV.nbudgetvar = BVD.nbudgetvar
JOIN sortinglink SLK
	ON SLK.idchild = BVD.idsor
join sorting S
	ON BVD.idsor = S.idsor
WHERE 
	(	(SLK.nlevel = @nlevel AND SLK.idparent = @idsor) OR (@idsor is null AND SLK.nlevel = @levelusable)   )
	AND BV.adate <= @date
	AND BVD.idupb = @idupb
	AND BVD.amount < 0
	
-- Calcolo delle variazioni totali sulla previsione principale date dalla somma algebrica di quelle in aumento e quelle in diminuzione
DECLARE @var_prev decimal(19,2)
SET @var_prev  = ISNULL(@var_prev_aum,0) + ISNULL(@var_prev_dim,0)
-- Calcolo della previsione principale attuale
DECLARE @prev_curr decimal(19,2)
SET @prev_curr = ISNULL(@prevision,0) + ISNULL(@var_prev,0)

DECLARE	@departmentname varchar(150)
SET  @departmentname = ISNULL( (SELECT paramvalue from
			 generalreportparameter where idparam='DenominazioneDipartimento' 
				and (start is null or start <= @date) 
				and (stop is null or stop >= @date)
				),'Manca Cfg. Parametri Tutte le stampe')

INSERT INTO #situation VALUES (@departmentname, NULL, 'H')
INSERT INTO #situation VALUES ('Situazione al ' + CONVERT(char(8), @date, 3), NULL, 'H')
DECLARE	@desc_level varchar(50)
SELECT @desc_level = description 
FROM  sortinglevel 
WHERE idsorkind = @idsorkind
	AND nlevel = @nlevel
INSERT INTO #situation VALUES ('U.P.B. ' + @codeupb + ' - ' + @descupb, NULL, 'H')
INSERT INTO #situation VALUES ('Classificazione '  + @sortingkind, NULL, 'H')
INSERT INTO #situation VALUES ('Livello ' + @desc_level + ' ' + @sortcode, NULL, 'H')
INSERT INTO #situation VALUES (@description,	NULL, 'H')
INSERT INTO #situation VALUES ('Esercizio ' + CONVERT(char(4),	@ayear), NULL, 'H')
INSERT INTO #situation VALUES ('', NULL, 'N')
INSERT INTO #situation VALUES('B U D G E T',NULL,'N')
INSERT INTO #situation VALUES ('Budget iniziale', @prevision, '')
INSERT INTO #situation VALUES ('Variazioni di Budget', @var_prev, '')
INSERT INTO #situation	
	VALUES ('Budget attuale', ISNULL(@prev_curr,0), 'S')
SELECT value, amount, kind FROM #situation	
END

GO

print '[show_budget_sorting] OK'

GO
if object_id('[rpt_riep_liquidazioneiva_sub]') is not null
	drop PROCEDURE [rpt_riep_liquidazioneiva_sub]
go

CREATE     PROCEDURE [rpt_riep_liquidazioneiva_sub]
(
	@ayear int,
	@startmounth int,
	@stopmounth int
)
AS BEGIN

DECLARE @minnivapay int
DECLARE @maxnivapay int
DECLARE @previouscredit decimal(19,2)
DECLARE @previousdebit decimal(19,2)

 DECLARE @amm varchar(100)
 set @amm=user
	CREATE TABLE #liquidazioneiva (
	idivapayperiodicity varchar(50),
	yivapay int,
	nivapay int,
	start datetime,
	stop datetime,
	description varchar(50),
	motive varchar(50),
	debitamount decimal(19,2),
	debitamountdeferred decimal(19,2),
	creditamount decimal(19,2),
	creditamountdeferred decimal(19,2),
	previouscredit decimal(19,2),
	previousdebit decimal(19,2),
	currentcredit decimal(19,2),
	currentdebit decimal(19,2),
	refundamount decimal(19,2),
	paymentamount decimal(19,2),
	paymentdetails varchar(150),
	prorata float,
	iva decimal(19,2),
	ivadeferred decimal(19,2),
	unabatable decimal(19,2), 
	unabatabledeferred decimal(19,2),
	pre_credittotal decimal(19,2),
	ivapaykind varchar(150) 
	)
	select @minnivapay = min(nivapay) from ivapay where month(start) between @startmounth and @stopmounth
	and yivapay = @ayear
	select @maxnivapay = max(nivapay) from ivapay where month(stop) between @startmounth and @stopmounth
	and yivapay = @ayear
	IF (@minnivapay IS NULL) AND (@maxnivapay IS NULL)
	BEGIN
				SELECT	 
					idivapayperiodicity,
					yivapay,
					nivapay ,
					start ,
					stop,
					description ,
					motive ,
					debitamount ,			
					debitamountdeferred ,	
					creditamount ,			
					creditamountdeferred ,	
					previouscredit ,		
					previousdebit ,		
					currentcredit ,		
					currentdebit ,			
					refundamount ,			
					paymentamount ,	
					paymentdetails ,
					prorata ,
					pre_credittotal,
					ivapaykind
				FROM #liquidazioneiva
	END
	ELSE
	BEGIN
		
		DECLARE @number INT
		SET @number = @minnivapay
    
		While ((@number) <= @maxnivapay) 
		BEGIN	
			print @number
			INSERT INTO #liquidazioneiva 
				(idivapayperiodicity,
					yivapay,
					nivapay ,
					start ,
					stop,
					description ,
					motive ,
					debitamount ,			
					debitamountdeferred ,	
					creditamount ,			
					creditamountdeferred ,	
					previouscredit ,		
					previousdebit ,		
					currentcredit ,		
					currentdebit ,			
					refundamount ,			
					paymentamount ,	
					paymentdetails ,
					prorata ,
					pre_credittotal,
					ivapaykind)
			EXEC rpt_liquidazioneiva @ayear, @number, 'N'
			
			SET @number = @number + 1
		END
		SELECT @previouscredit = min(previouscredit) FROM #liquidazioneiva
		WHERE nivapay = @minnivapay 
		SELECT @previousdebit = min(previousdebit) FROM #liquidazioneiva
		WHERE nivapay = @minnivapay 
		
	CREATE TABLE #totali (
		yivapay int,
		nivapay int,
		paymentamount decimal(19,2),
		refundamount decimal(19,2),
		currentcredit decimal(19,2),
		currentdebit decimal(19,2),
		pre_credittotal decimal(19,2)
	)
		DECLARE @pre_credittotal decimal(19,2)
		DECLARE @paymentamount decimal(19,2)
		DECLARE @refundamount decimal(19,2)
		DECLARE @currentcredit decimal(19,2)
		DECLARE @currentdebit decimal(19,2)
		
		INSERT INTO #totali
		(
			yivapay ,
			nivapay ,
			paymentamount,
			refundamount ,
			currentcredit ,
			currentdebit ,
			pre_credittotal
		)
		-- §sommo i valori dati dalle singole liquidazioni
		SELECT yivapay, nivapay,
			   SUM(distinct ISNULL(paymentamount,0)), 
			   SUM(distinct ISNULL(refundamount,0)),
			   SUM(distinct ISNULL(currentcredit,0)),
			   SUM(distinct ISNULL(currentdebit,0)), 
			   SUM(distinct ISNULL(pre_credittotal,0)) 
		FROM #liquidazioneiva
		GROUP BY yivapay, nivapay 
		
		
		-- §sommo i valori dati dalle singole liquidazioni
		SELECT @paymentamount = SUM(ISNULL(paymentamount,0)), @refundamount = SUM(ISNULL(refundamount,0)),
			   @currentcredit = SUM(ISNULL(currentcredit,0)),
			   @currentdebit = SUM(ISNULL(currentdebit,0)), 
			   @pre_credittotal = SUM(ISNULL(pre_credittotal,0)) 
		FROM #totali		
		
		SELECT idivapayperiodicity,
			yivapay,
			nivapay ,
			start ,
			stop,
			description ,
			motive ,
			debitamount ,			
			debitamountdeferred ,	
			creditamount ,			
			creditamountdeferred ,	
			@previouscredit AS previouscredit,		
			@previousdebit AS previousdebit,		
			@currentcredit AS currentcredit ,		
			@currentdebit AS currentdebit ,			
			@refundamount AS refundamount ,			
			@paymentamount AS paymentamount ,		
			paymentdetails ,
			prorata ,
			@pre_credittotal as pre_credittotal,
			ivapaykind
		FROM #liquidazioneiva
		ORDER BY yivapay, nivapay, ivapaykind, motive, description ASC
		
	END
	
END


GO

print '[rpt_riep_liquidazioneiva_sub] OK'

GO
if object_id('closeyear_wageaddition') is not null
	drop procedure closeyear_wageaddition
go



CREATE              procedure closeyear_wageaddition(@esercizio int) as
begin
	declare @maxfasespesa int
	select @maxfasespesa = max(nphase) from expensephase
	declare @eserccontratto int
	declare @numcontratto int
	declare @compensolordo decimal(19,2)
	declare @curscontratto cursor
	set @curscontratto = cursor for select ycon, ncon, feegross from wageaddition where ycon<=@esercizio 
		and not exists (select * from wageadditionyear where wageaddition.ycon=wageadditionyear.ycon and wageaddition.ncon=wageadditionyear.ncon and ayear=@esercizio+1)
	open @curscontratto
	fetch next from @curscontratto into @eserccontratto, @numcontratto, @compensolordo
	while @@fetch_status = 0 begin
		declare @idspesa varchar(40)
		declare @importo decimal(19,2)
		declare @amount decimal(19,2)
		declare @cursspesa cursor
		set @cursspesa = cursor for 
			SELECT expense.idexp, isnull(expenseyear_starting.amount, 0)
			FROM expensewageaddition
			JOIN expenselink
				ON expenselink.idparent = expensewageaddition.idexp
			JOIN expense
				ON expense.idexp = expenselink.idchild 
			LEFT OUTER JOIN expensetotal expensetotal_firstyear(NOLOCK)
  				ON expensetotal_firstyear.idexp = expense.idexp
  				AND ((expensetotal_firstyear.flag & 2) <> 0)
			LEFT OUTER JOIN expenseyear expenseyear_starting(NOLOCK) 
				ON expenseyear_starting.idexp = expensetotal_firstyear.idexp
  				AND expenseyear_starting.ayear = expensetotal_firstyear.ayear
			WHERE ycon=@eserccontratto AND ncon=@numcontratto AND expense.nphase=@maxfasespesa
		open @cursspesa
		fetch next from @cursspesa into @idspesa, @amount
		set @importo = 0;
		while @@fetch_status = 0 begin
			select @importo = @importo + @amount + isnull(sum(amount), 0) from expensevar where idexp=@idspesa and isnull(autokind,0)<> 4 --riten
			fetch next from @cursspesa into @idspesa, @amount
		end
		declare @residuo decimal (19,2)
		set @residuo = @compensolordo - @importo
		if (@residuo>0) begin
			declare @codicedurata varchar(20)
			declare @codicequalifica varchar(20)
			declare @codiceorario varchar(2)
			select 
				@codicedurata = wageadditionyear.idcontractlength, 
				@codicequalifica = wageadditionyear.idposition, 
				@codiceorario = wageadditionyear.idworkingtime
				from wageadditionyear 
				where wageadditionyear.ayear=@esercizio and wageadditionyear.ycon=@eserccontratto and wageadditionyear.ncon=@numcontratto
			insert into wageadditionyear (ayear, ycon, ncon, idcontractlength, idposition, idworkingtime, lt, ct, cu, lu)
				values (@esercizio+1, @eserccontratto, @numcontratto, @codicedurata, @codicequalifica, @codiceorario, getdate(), getdate(), 'sa', 'sa')
		end
		fetch next from @curscontratto into @eserccontratto, @numcontratto, @compensolordo
	end
end



GO

print 'closeyear_wageaddition OK'

