CREATE                TRIGGER [trigger_d_expenseinvoice] ON expenseinvoice 
FOR DELETE 
AS
BEGIN
	DECLARE @idexp int
	SELECT @idexp = idexp
	FROM deleted
	UPDATE invoicedetail SET idexp_iva = NULL
	WHERE idexp_iva = @idexp
	UPDATE invoicedetail SET idexp_taxable = NULL
	WHERE idexp_taxable = @idexp
END


