if object_id('[closeyear_reopenayear]') is not null
	drop PROCEDURE [closeyear_reopenayear]
go


CREATE               PROCEDURE [closeyear_reopenayear]
(
	@ayear int,
	@kind char(1)
)
AS BEGIN
IF @kind = 'F'
BEGIN
	--azzero i bit da 0 a 3 e poi imposto il valore 5 su questi flag
	UPDATE accountingyear SET flag = flag&0xF0 WHERE ayear = @ayear
	UPDATE accountingyear SET flag = flag|0x05 WHERE ayear = @ayear
END
IF @kind = 'P'
BEGIN
	--azzero il bit 4
	UPDATE accountingyear SET flag = flag&0xEF WHERE ayear = @ayear
END
IF @kind = 'E'
BEGIN
	--azzero il bit 5
	UPDATE accountingyear SET flag = flag&0xDF WHERE ayear = @ayear
END
END


GO

print '[closeyear_reopenayear] OK'

GO
if object_id('[rpt_reversale_incasso_siope_sub1]') is not null
	drop PROCEDURE [rpt_reversale_incasso_siope_sub1]
go



CREATE                          PROCEDURE [rpt_reversale_incasso_siope_sub1]
	@y int,
	@n int
AS
BEGIN
DECLARE @sorkind int
DECLARE @npos int
IF (@y <= 2006)
BEGIN
	select @sorkind = idsorkind from sortingkind where codesorkind = 'SIOPE'
	SET @npos = 2
END
ELSE
BEGIN
	select @sorkind = idsorkind from sortingkind where codesorkind = '07E_SIOPE'
	SET @npos = 1
END
DECLARE @sortcode varchar(20)
SELECT @sortcode = sorting.sortcode 
FROM incomesorted
JOIN income 
	ON incomesorted.idinc = income.idinc
JOIN incomelast 
	ON incomelast.idinc = income.idinc
join proceeds on proceeds.kpro = incomelast.kpro
JOIN sorting
	ON sorting.idsor = incomesorted.idsor
WHERE 	incomesorted.ayear = @y
		AND sorting.idsorkind = @sorkind
		AND income.ymov = @y
		AND proceeds.npro = @n
IF (@sortcode is null) 
 SELECT 	sorting.sortcode as sortcode,
	sorting.description as sort,
	sum(incomeyear_starting.amount) as amount
 FROM finsorting
 JOIN sorting 
	ON finsorting.idsor=sorting.idsor
 JOIN incomeyear 
 	ON finsorting.idfin=incomeyear.idfin	
 JOIN income 
	ON incomeyear.idinc=income.idinc 
 JOIN incomelast 
	ON incomelast.idinc = income.idinc
 join proceeds on proceeds.kpro = incomelast.kpro
 LEFT OUTER JOIN incometotal incometotal_firstyear(NOLOCK)
  	ON incometotal_firstyear.idinc = income.idinc
  	AND ((incometotal_firstyear.flag & 2) <> 0 )
 LEFT OUTER JOIN incomeyear incomeyear_starting(NOLOCK) 
	ON incomeyear_starting.idinc = incometotal_firstyear.idinc
  	AND incomeyear_starting.ayear = incometotal_firstyear.ayear
 WHERE proceeds.npro=@n and income.ymov=@y and sorting.idsorkind=@sorkind
 GROUP BY sortcode,sorting.description
 ORDER BY sortcode
ELSE
 SELECT  	
		SUBSTRING(sorting.sortcode,@npos,LEN(sorting.sortcode)) AS sortcode,
		sorting.description AS sort,
		SUM(incomesorted.amount) as amount 
 FROM incomesorted
 JOIN income 
	ON incomesorted.idinc = income.idinc
 JOIN incomelast 
	ON incomelast.idinc = income.idinc
 join proceeds on proceeds.kpro = incomelast.kpro
 JOIN sorting
	ON sorting.idsor = incomesorted.idsor
 WHERE 	incomesorted.ayear = @y
		AND sorting.idsorkind = @sorkind-- Ipotesi fondamentale
		AND income.ymov = @y
		AND proceeds.npro = @n
 GROUP BY sortcode,sorting.description
 ORDER BY sortcode

END


