CREATE             TRIGGER [trigger_d_expensemandate] ON expensemandate 
FOR DELETE 
AS
BEGIN
	DECLARE @idexp int
	SELECT @idexp = idexp
	FROM deleted
	UPDATE mandatedetail SET idexp_iva = NULL
	WHERE idexp_iva = @idexp
	UPDATE mandatedetail SET idexp_taxable = NULL
	WHERE idexp_taxable = @idexp
END


