print '[rpt_registroiva_sub] OK'

GO
if object_id('rpt_partitario_entrata') is not null
	drop PROCEDURE rpt_partitario_entrata
go


CREATE       PROCEDURE rpt_partitario_entrata
	@ayear int,
	@kind char(1),
	@showupb char(1),
	@idupb varchar(36),
	@showchildupb char(1),
	@nlevel tinyint,
	@idfin int,
	@start datetime,
	@stop datetime,
	@suppressifblank char(1),
	@flagnofficial	char(1)
AS
BEGIN
/*
-- exec rpt_partitario_entrata 2006, 'C','N','%','N',3,null,{ts '2006-01-30 00:00:00'},{ts '2006-08-30 00:00:00'},'S','N'
select idparent from finlink where idchild=10675 and nlevel=2
 exec rpt_partitario_entrata 2006, 'C','N','%','N',3,10642,{ts '2006-01-01 00:00:00'},{ts '2006-08-30 00:00:00'},'N','N'
exec rpt_partitario_entrata 2006, 'R','N','%','N',3,NULL,{ts '2006-02-01 00:00:00'},{ts '2006-08-30 00:00:00'},'N','N'
*/
/* Versione 1.0.1 del 17/09/2007 ultima modifica: PINO */
DECLARE @idupboriginal varchar(36)
SET @idupboriginal= @idupb
IF (@showchildupb = 'S')
BEGIN
	SET @idupb=@idupb+'%' 
END
DECLARE @level_input tinyint
SET  @level_input = ISNULL((SELECT nlevel from fin where idfin = @idfin) ,@nlevel)
-- ho scelto come livello 2 e poi ho specificato il capitolo, lui corregge @nlevel dandogli 3
IF (@nlevel < @level_input ) AND (@idfin is not null)
	BEGIN
	SET  @nlevel = @level_input
	END
DECLARE @level 	varchar(50)
SELECT @level = description 
	FROM finlevel
	WHERE nlevel = @nlevel
	AND ayear = @ayear	

DECLARE @levelusable tinyint
SELECT @levelusable = MIN(nlevel)
	FROM finlevel
	WHERE flag&2 <> 0
	AND ayear = @ayear
IF (@levelusable < @nlevel)
	BEGIN
	SET @levelusable = @nlevel
	END

DECLARE	@kind_bit  tinyint 
if @kind='C' set @kind_bit = 0
if @kind='R' set @kind_bit = 1
CREATE TABLE #income	(
	codeupb varchar(50),
	idupb varchar(36),
	upb varchar(150),
	upbprintingorder varchar(50),
	idfin int,
	rowkind int,
	nphase tinyint,
	operationdate datetime,
	operationkind varchar(55),
	idreg int,
	idmov int,
	ymov int,
	nmov int,
	nofficial int,
	nsubmov int,
	ndoc int,  
	description varchar(150),
	doc varchar(150),
	initialprevision decimal(19,2),
	finvar decimal(19,2),
	finphase_amount decimal(19,2),
	cassaphase_amount decimal(19,2),
	emessiondate datetime,
	printeddate datetime,
	trasmitteddate datetime,
	transactiondate datetime,
	annulmentdate datetime,
	annotations varchar(400)
)
DECLARE @firstday datetime
SET @firstday = CONVERT(datetime, '01-01-' + CONVERT(varchar(4),@ayear), 105)
declare @fin_kind tinyint
select @fin_kind = fin_kind 
	FROM config 
	WHERE ayear = @ayear
IF ((@kind IN ('C','S')) AND (DATEDIFF(DAY,@start, @firstday) = 0))
BEGIN
	INSERT INTO #income
		(
		idfin,
		codeupb,
		idupb,
		upb,
		upbprintingorder,
		rowkind,
		operationdate,
		operationkind,
		initialprevision
		)
	SELECT 
		fin.idfin,
		upb.codeupb,
		upb.idupb,
		upb.title,
		upb.printingorder,
		1,
		@firstday,
		'Prev.iniziale',
		CASE
			WHEN @kind = 'C' THEN (SELECT SUM(fy2.prevision) 
						FROM finyear fy2 
						JOIN fin f2
							ON fy2.idfin=f2.idfin
						JOIN finlink FLK
							ON FLK.idchild = fy2.idfin and FLK.nlevel = @nlevel
						WHERE FLK.idparent = fin.idfin
							AND f2.nlevel = @levelusable AND fy2.idupb= upb.idupb
							)
			WHEN (@kind = 'S' and @fin_kind = 2) 
					THEN (SELECT SUM(fy2.prevision) 
						FROM finyear fy2 
						JOIN fin f2
							ON fy2.idfin=f2.idfin
						JOIN finlink FLK
							ON FLK.idchild = fy2.idfin and FLK.nlevel = @nlevel
						WHERE FLK.idparent = fin.idfin 
							AND f2.nlevel = @levelusable AND fy2.idupb= upb.idupb
							)
			WHEN (@kind = 'S' and @fin_kind = 3) 
					THEN (SELECT SUM(fy2.secondaryprev) 
						FROM finyear fy2 
						JOIN fin f2
							ON fy2.idfin=f2.idfin
						JOIN finlink FLK
							ON FLK.idchild = fy2.idfin and FLK.nlevel = @nlevel
						WHERE FLK.idparent = fin.idfin 
							AND f2.nlevel = @levelusable AND fy2.idupb= upb.idupb
							)
			END
	FROM finyear
	JOIN fin
		ON finyear.idfin = fin.idfin
	JOIN finlink 
		ON finlink.idchild = fin.idfin and finlink.nlevel = @level_input
	JOIN upb
		ON finyear.idupb = upb.idupb
	WHERE (upb.idupb like @idupb )
		AND fin.ayear = @ayear
		AND  (( fin.flag & 1)=0)
		AND fin.nlevel = @nlevel
		AND (@idfin IS NULL OR isnull(finlink.idparent, fin.idfin) = @idfin)
END
DECLARE @finphase tinyint
SELECT @finphase = assessmentphasecode
	FROM config
	WHERE ayear = @ayear
IF @finphase IS NULL
	BEGIN
		SELECT @finphase = incomefinphase
			FROM uniconfig
	END
DECLARE @maxincomephase tinyint
SELECT  @maxincomephase = MAX(nphase) FROM incomephase
DECLARE @cashvaliditykind int
SELECT  @cashvaliditykind = cashvaliditykind
FROM config
WHERE ayear = @ayear
IF (DATEDIFF(DAY,@start, @firstday) <> 0)
BEGIN
	CREATE TABLE #previousincome
	(
		idfin int,
		idupb varchar(36),
		initialprevision decimal(19,2),
		finvar decimal(19,2),
		finphase_amount decimal(19,2),
		cassaphase_amount decimal(19,2),
	)
	INSERT INTO #previousincome
		(
		idfin,
		idupb
		)
	SELECT finyear.idfin,
	       finyear.idupb
	FROM finyear
	JOIN fin
		ON finyear.idfin = fin.idfin
	JOIN finlink 
		ON finlink.idchild = fin.idfin and finlink.nlevel = @level_input
	JOIN upb
		ON finyear.idupb = upb.idupb
	WHERE (upb.idupb like @idupb )
		AND fin.ayear = @ayear
		AND  (( fin.flag & 1)=0)
		AND fin.nlevel = @nlevel
		and (@idfin IS NULL OR isnull(finlink.idparent, fin.idfin) = @idfin)
	IF (@kind IN('C','S'))
	BEGIN
		UPDATE #previousincome
		SET initialprevision = 
			(SELECT 
				CASE
					WHEN @kind = 'C' THEN SUM(fy2.prevision) 
					WHEN (@kind = 'S' and @fin_kind = 2) THEN SUM(fy2.prevision) 
					WHEN (@kind = 'S' and @fin_kind = 3) THEN SUM(fy2.secondaryprev) 
				END
				FROM finyear fy2
				JOIN fin f2
					ON fy2.idfin = f2.idfin	
				JOIN finlink FLK
					ON FLK.idchild = fy2.idfin and FLK.nlevel =  @nlevel
			WHERE 	fy2.idupb= #previousincome.idupb
				AND FLK.idparent = #previousincome.idfin 
				AND f2.nlevel = @levelusable),
		finvar = (
			SELECT SUM(finvardetail.amount)
			FROM finvardetail
			JOIN finvar
				ON finvar.yvar = finvardetail.yvar
				AND finvar.nvar = finvardetail.nvar
			JOIN finlink FLK
				ON FLK.idchild = finvardetail.idfin and FLK.nlevel =  @nlevel
			WHERE finvar.flagprevision ='S'
				AND finvar.idfinvarstatus = 5
				AND finvar.variationkind <> 5
				AND finvar.adate < @start
				AND finvar.yvar = @ayear
				AND finvardetail.idupb = #previousincome.idupb
				AND FLK.idparent = #previousincome.idfin 
				)
	END
	ELSE
	BEGIN
		UPDATE #previousincome
		SET initialprevision =(
			SELECT SUM(incomeyear.amount)
			FROM incomeyear
			JOIN income
				ON income.idinc = incomeyear.idinc
			JOIN finlink FLK
				ON FLK.idchild = incomeyear.idfin and FLK.nlevel =  @nlevel
			JOIN incometotal
				ON incomeyear.idinc = incometotal.idinc
				AND incomeyear.ayear = incometotal.ayear
			WHERE  (( incometotal.flag & 1)= @kind_bit)
				AND income.adate < @start
				AND income.nphase = @finphase
				AND incomeyear.idupb = #previousincome.idupb
				AND FLK.idparent = #previousincome.idfin 
				AND incomeyear.ayear = @ayear)
	END
	IF (@kind in ('C','R'))
	BEGIN
	UPDATE #previousincome
		SET finphase_amount = ISNULL((
			SELECT SUM(incomeyear.amount)
			FROM incomeyear
			JOIN income
				ON income.idinc = incomeyear.idinc
			JOIN incometotal
				ON incomeyear.idinc = incometotal.idinc
				AND incomeyear.ayear = incometotal.ayear
			JOIN finlink FLK
				ON FLK.idchild = incomeyear.idfin and FLK.nlevel =  @nlevel
			WHERE  (( incometotal.flag & 1)= @kind_bit)
				AND income.adate < @start
				AND income.nphase = @finphase
				AND incomeyear.idupb = #previousincome.idupb
				AND FLK.idparent = #previousincome.idfin
				AND incomeyear.ayear = @ayear), 0)
			+ 
			ISNULL((
			SELECT SUM(incomevar.amount)
			FROM incomevar
			JOIN incomeyear
				ON incomeyear.idinc = incomevar.idinc
			JOIN income
				ON income.idinc = incomevar.idinc
			JOIN incometotal
				ON incomeyear.idinc = incometotal.idinc
				AND incomeyear.ayear = incometotal.ayear
			JOIN finlink FLK
				ON FLK.idchild = incomeyear.idfin and FLK.nlevel =  @nlevel
			WHERE incomevar.yvar = @ayear
				AND incomeyear.ayear = @ayear
				AND incomeyear.idupb = #previousincome.idupb
				AND FLK.idparent = #previousincome.idfin
				AND (( incometotal.flag & 1)= @kind_bit)
				AND income.nphase = @finphase
				AND incomevar.adate < @start), 0)
	END
	IF (@cashvaliditykind <> 4)
	BEGIN
		UPDATE #previousincome 
		SET cassaphase_amount = ISNULL((
				SELECT SUM(amount)
			 	FROM historyproceedsview 
				JOIN finlink 
					ON idchild = idfin and nlevel =  @nlevel
				WHERE (flagarrear = @kind OR @kind = 'S')
					AND idupb = #previousincome.idupb
					AND competencydate < @start
					AND idparent = #previousincome.idfin
					AND ymov = @ayear)
				, 0)
				+ 
				ISNULL((
				SELECT SUM(incomevar.amount)
				FROM incomevar
				JOIN historyproceedsview HPV
					ON HPV.idinc = incomevar.idinc
				JOIN finlink FLK
					ON FLK.idchild = HPV.idfin and FLK.nlevel =  @nlevel
				WHERE incomevar.yvar = @ayear
					AND HPV.idupb = #previousincome.idupb
					AND HPV.competencydate <= @start AND HPV.ymov = @ayear
					AND FLK.idparent = #previousincome.idfin
					AND (HPV.flagarrear = @kind OR @kind = 'S')
					AND incomevar.adate < @start
				), 0)
	END
	ELSE
	BEGIN
		UPDATE #previousincome 
		SET cassaphase_amount = ISNULL((
				SELECT SUM(amount)
				FROM historyproceedsview 
				JOIN finlink 
					ON idchild = idfin and nlevel =  @nlevel
				WHERE (flagarrear = @kind OR @kind = 'S')
					AND idupb = #previousincome.idupb
					AND competencydate < @start
					AND idparent = #previousincome.idfin
					AND ymov = @ayear)
				, 0)
	END
	INSERT INTO #income
	(
		idfin,
		idupb,
		codeupb,upb,upbprintingorder,
		rowkind,
		operationdate,
		operationkind,
		initialprevision,
		finvar,
		finphase_amount,
		cassaphase_amount
	)
	SELECT
		#previousincome.idfin,
		upb.idupb,
		upb.codeupb,
		upb.title,
		upb.printingorder,
		1,
		DATEADD(dd, -1, @start),
		'Tot.prec.',
		#previousincome.initialprevision,
		#previousincome.finvar,
		#previousincome.finphase_amount,
		#previousincome.cassaphase_amount
	FROM #previousincome
	JOIN fin
		ON fin.idfin = #previousincome.idfin
	JOIN upb 
		ON upb.idupb=#previousincome.idupb
END	
IF (@kind IN ('C','S')) 
BEGIN
-- Variazione di previsione
	INSERT INTO #income
		(
		idfin,
		idupb,codeupb,upb,upbprintingorder,
		rowkind,
		operationdate,
		operationkind,
		ymov,
		nmov,
		nofficial,
		description,
		finvar
		)
	SELECT 
		isnull(FL1.idparent, fin.idfin),
		upb.idupb,
		upb.codeupb,
		upb.title,
		upb.printingorder,
		2,
		finvar.adate,
		'Var.prev.',
		finvar.yvar,
		finvar.nvar,
		CASE	finvar.official 
			WHEN 'S' THEN finvar.nofficial
			ELSE	NULL
		END,
		finvar.description,
		finvardetail.amount
	FROM finvardetail
	JOIN finvar
		ON finvar.yvar = finvardetail.yvar
		AND finvar.nvar = finvardetail.nvar
	left outer JOIN finlink 
		ON finlink.idchild = finvardetail.idfin and finlink.nlevel =  @level_input
	left outer JOIN finlink FL1
		ON FL1.idchild = finvardetail.idfin AND FL1.nlevel = @nlevel
	JOIN fin
		ON fin.idfin = FL1.idparent
	JOIN upb 
		ON upb.idupb=finvardetail.idupb 
	WHERE 	finvar.flagprevision = 'S'
		AND finvar.idfinvarstatus = 5
		AND finvar.variationkind <> 5
		AND finvar.adate BETWEEN @start AND @stop
		AND fin.ayear = @ayear
		AND  (( fin.flag & 1)=0)
		AND fin.nlevel = @nlevel
		and (@idfin IS NULL OR isnull(finlink.idparent, fin.idfin) = @idfin)
		AND (upb.idupb like @idupb )
END
DECLARE @finname varchar(50)
SELECT @finname = description
	FROM incomephase
	WHERE nphase = @finphase
IF (@kind IN ( 'C','R'))
BEGIN
-- Movimenti di entrata / fase bilancio 
	INSERT INTO #income
		(
		idfin,
		idmov,
		idupb,codeupb,upb,upbprintingorder,
		rowkind,
		nphase,
		operationdate,
		operationkind,
		ymov,
		nmov,
		description,
		idreg,
		finphase_amount
		)
	SELECT 
		isnull(FL1.idparent, fin.idfin),
		income.idinc,
		upb.idupb,
		upb.codeupb,
		upb.title,
		upb.printingorder,
		3,
		income.nphase,
		income.adate,
		@finname,
		income.ymov,
		income.nmov,
		income.description,
		income.idreg,
		incomeyear.amount
	FROM income
	JOIN incomeyear
		ON incomeyear.idinc = income.idinc
	JOIN incometotal
		ON incomeyear.idinc = incometotal.idinc
		AND incomeyear.ayear = incometotal.ayear
	left outer JOIN finlink 
		ON finlink.idchild = incomeyear.idfin AND finlink.nlevel = @level_input
	JOIN upb 
		ON upb.idupb=incomeyear.idupb
	left outer JOIN finlink FL1
		ON FL1.idchild = incomeyear.idfin AND FL1.nlevel = @nlevel
	JOIN fin
		ON fin.idfin = FL1.idparent
	WHERE income.nphase = @finphase
		AND incomeyear.ayear = @ayear
		AND fin.ayear = @ayear
		AND  (( fin.flag & 1)=0)
		AND fin.nlevel = @nlevel
		AND (@idfin IS NULL OR isnull(finlink.idparent, fin.idfin) = @idfin)
		AND (( incometotal.flag & 1) = @kind_bit)
		AND (
		(@kind = 'C' AND income.adate BETWEEN @start AND @stop)
		OR 
		(@kind = 'R' AND DATEDIFF(DAY,@start,@firstday) = 0)
		)
		AND (upb.idupb like @idupb )
-- Variazione movimenti di entrata / fase bilancio
	INSERT INTO #income
		(
		idfin,
		idmov,
		idupb,codeupb,upb,upbprintingorder,
		rowkind,
		nphase,
		operationdate,
		operationkind,
		ymov,
		nmov,
		nsubmov,
		description,
		idreg,
		finphase_amount
		)
	SELECT 
		isnull(FL1.idparent, fin.idfin),
		income.idinc,
		upb.idupb,upb.codeupb,upb.title,upb.printingorder,
		4,
		income.nphase,
		incomevar.adate,
		CASE
			WHEN @kind = 'C' 
			THEN 'Var.' + @finname
			WHEN @kind = 'R' 
			THEN 'Var.residuo ' + @finname 
		END,
		income.ymov,
		income.nmov,
		incomevar.nvar,
		incomevar.description,
		income.idreg,
		incomevar.amount
	FROM incomevar
	JOIN income
		ON income.idinc = incomevar.idinc
	JOIN incomeyear
		ON incomeyear.idinc = incomevar.idinc
	JOIN incometotal
		ON incomeyear.idinc = incometotal.idinc
		AND incomeyear.ayear = incometotal.ayear
	left outer JOIN finlink 
		ON finlink.idchild = incomeyear.idfin AND finlink.nlevel =  @level_input
	JOIN upb 
		ON upb.idupb = incomeyear.idupb
	left outer JOIN finlink FL1
		ON FL1.idchild = incomeyear.idfin AND FL1.nlevel = @nlevel
	JOIN fin
		ON fin.idfin = FL1.idparent
	WHERE incomevar.yvar = @ayear
		AND incomeyear.ayear = @ayear
		AND fin.ayear = @ayear
		AND income.nphase = @finphase
		AND (( fin.flag & 1)=0)
		AND fin.nlevel = @nlevel
		AND (@idfin IS NULL OR isnull(finlink.idparent, fin.idfin) = @idfin)
		AND  (( incometotal.flag & 1) = @kind_bit) 
		AND incomevar.adate BETWEEN @start AND @stop
		AND (upb.idupb like @idupb )
END	
DECLARE @phasecassa varchar(50)
SELECT @phasecassa = description FROM incomephase WHERE nphase = @maxincomephase
-- Movimenti di spesa / fase cassa
INSERT INTO #income
(
	idfin,
	idmov,
	idupb,
	codeupb,
	upb,
	upbprintingorder,
	rowkind,
	nphase,
	operationdate,
	operationkind,
	ymov,
	nmov,
	ndoc,
	description,
	doc,
	idreg,
	cassaphase_amount
)
SELECT 
	isnull(FL1.idparent, fin.idfin),
	HPV.idinc,
	upb.idupb,
	upb.codeupb,
	upb.title,
	upb.printingorder,
	5,
	@maxincomephase,	
	HPV.competencydate,
	@phasecassa,
	HPV.ymov,
	HPV.nmov,
	HPV.npro,
	HPV.description,
	CASE
		WHEN HPV.doc IS NOT NULL AND 
			HPV.docdate IS NULL THEN
			'Inc. ' + HPV.doc
		WHEN HPV.doc IS NOT NULL AND
			HPV.docdate IS NOT NULL THEN
			'Inc. ' + HPV.doc + 
			' del ' + CONVERT(varchar(20), HPV.docdate, 105)
		ELSE
			(NULL)
	END,
	HPV.idreg,
	HPV.amount
FROM historyproceedsview HPV
JOIN upb
	ON HPV.idupb = upb.idupb
left outer JOIN finlink
	ON finlink.idchild = HPV.idfin	
	AND finlink.nlevel = @level_input
left outer JOIN finlink FL1
	ON FL1.idchild = HPV.idfin	
	AND FL1.nlevel = @nlevel
JOIN fin
	ON fin.idfin = FL1.idparent
WHERE HPV.competencydate BETWEEN @start AND @stop
	AND (upb.idupb like @idupb )
	AND HPV.ymov = @ayear
	AND (   (@kind IN ('C', 'R') AND (HPV.totflag & 1)= @kind_bit  )   OR @kind = 'S')
	AND fin.ayear = @ayear
	AND (( fin.flag & 1)=0)
	AND fin.nlevel = @nlevel 
	AND (@idfin IS NULL OR isnull(finlink.idparent, fin.idfin) = @idfin)
--	Variazione ai  Movimenti di spesa / fase cassa
IF (@cashvaliditykind <> 4)
BEGIN
	INSERT INTO #income
		(
		idfin,
		idmov,
		idupb, 
		codeupb,
		upb,
		upbprintingorder,
		rowkind,
		nphase,
		operationdate,
		operationkind,
		ymov,
		nmov,
		nsubmov,
		ndoc,
		description,
		doc,
		idreg,
		cassaphase_amount
		)
	SELECT 
		isnull(FL1.idparent, fin.idfin),
		income.idinc,
		upb.idupb, upb.codeupb,upb.title,upb.printingorder,
		6,
		income.nphase,
		incomevar.adate,
		'Var.' + @phasecassa,
		income.ymov,
		income.nmov,
		incomevar.nvar,
		HPV.npro,
		incomevar.description,
		CASE
			WHEN incomevar.doc IS NOT NULL AND 
				incomevar.docdate IS NULL THEN
				'Inc. ' + incomevar.doc
			WHEN incomevar.doc IS NOT NULL AND
				incomevar.docdate IS NOT NULL THEN
				'Inc. ' + incomevar.doc + 
				' del ' + CONVERT(varchar(20), incomevar.docdate, 105)
			ELSE
		(NULL)
		END,
		income.idreg,
		incomevar.amount
	FROM incomevar
	JOIN income
		ON income.idinc = incomevar.idinc
	JOIN historyproceedsview HPV
		ON HPV.idinc = incomevar.idinc
	JOIN upb
		ON upb.idupb = HPV.idupb
	left outer JOIN finlink 
		ON finlink.idchild = HPV.idfin AND finlink.nlevel =  @level_input
	left outer JOIN finlink FL1
		ON FL1.idchild = HPV.idfin AND FL1.nlevel = @nlevel
	JOIN fin
		ON fin.idfin = FL1.idparent
	WHERE incomevar.yvar = @ayear
		AND incomevar.adate BETWEEN @start AND @stop
		AND isnull(incomevar.autokind,'') <>'22'
		AND (upb.idupb like @idupb)
		AND HPV.competencydate BETWEEN @start AND @stop AND HPV.ymov = @ayear
		AND fin.ayear = @ayear
		AND  (( fin.flag & 1)=0)
		AND fin.nlevel = @nlevel
		AND (@idfin IS NULL OR isnull(finlink.idparent, fin.idfin) = @idfin) 
		AND (   (@kind IN ('C', 'R') AND ((HPV.totflag & 1)= @kind_bit)  )   OR @kind = 'S')
END
	
UPDATE #income
SET 	emessiondate = proceedsview.adate,
	printeddate = 	proceedsview.printdate,
	trasmitteddate = proceedsview.transmissiondate,	
	transactiondate =  proceedsperformed.competencydate,
	annulmentdate = proceedsview.annulmentdate
FROM proceedsview
LEFT OUTER JOIN banktransaction
	ON banktransaction.kpro=proceedsview.kpro
	AND ( banktransaction.kind='C' OR banktransaction.kind IS NULL)	
LEFT OUTER JOIN proceedsperformed 
	ON proceedsperformed.npro=proceedsview.npro	
	AND proceedsperformed.ypro=proceedsview.ypro
WHERE #income.ndoc = proceedsview.npro
	AND proceedsview.ypro = @ayear
IF (@suppressifblank = 'N')
BEGIN
	INSERT INTO #income 
		(
			idfin,
			idupb,
			codeupb,
			upb,
			upbprintingorder,
			rowkind
			)
	SELECT 	isnull(FL1.idparent, fin.idfin),
		upb.idupb,
		codeupb,
		upb.title,
		upb.printingorder,
		1
	FROM fin CROSS JOIN upb 
	left outer JOIN finlink
		ON finlink.idchild = fin.idfin 
		and finlink.nlevel =  @level_input
	left outer JOIN finlink FL1
		ON FL1.idchild = fin.idfin	
		AND FL1.nlevel = @nlevel
	WHERE (upb.idupb like @idupb )
		AND fin.ayear = @ayear
		AND  (( fin.flag & 1)=0)
		AND fin.nlevel = @nlevel
		AND (@idfin IS NULL OR isnull(finlink.idparent, fin.idfin) = @idfin)
		and not exists (SELECT *
			FROM #income
			WHERE upb.idupb = #income.idupb 
				AND FL1.idparent = #income.idfin 
			)
END
IF (@showupb <>'S') AND (@idupboriginal <> '%' ) AND (@showchildupb = 'S')
		UPDATE #income SET  
			upbprintingorder = (SELECT TOP 1 upbprintingorder
				FROM #income
				WHERE idupb = @idupboriginal),
			upb = (SELECT TOP 1 upb
				FROM #income
				WHERE idupb = @idupboriginal),
			idupb = @idupboriginal,
			codeupb =(SELECT TOP 1 codeupb
				FROM #income	
				WHERE idupb = @idupboriginal)
IF (@showupb <>'S') and (@idupboriginal = '%')
			UPDATE #income SET  
			upbprintingorder = null	,
			upb =  null,
			idupb = null,
			codeupb = null
-- se ho scelto di nascondere le voci di bilancio non utilizzate:
-- cancello le righe che hanno valori pari a zero 
-- e per cui non esistono variazioni di previzioni (rowkind=2) o movimenti di entrata (rowkind >= 3 )  
IF (@suppressifblank = 'S') AND @nlevel>2	--> se la stampa è x un livello sottostante la categoria cancella le righe
BEGIN
	DELETE FROM #income WHERE 
		ISNULL(initialprevision,0)=0 AND 
		ISNULL(finvar,0)=0 AND 
		ISNULL(finphase_amount,0)=0 AND 
		ISNULL(cassaphase_amount,0)=0 AND
		NOT EXISTS (select * from  #income i
				where #income.idupb=i.idupb AND 
				      #income.idfin=i.idfin AND 
					i.rowkind>1)
END
IF (@showupb <>'S')
	 SELECT 
		#income.idfin,
		idmov,
		@level as levelname,
		F.codefin,
		F.printingorder as finprintingorder,
		F.title,
		codeupb,idupb,upb,upbprintingorder,
		rowkind,
		nphase,operationdate,operationkind,ymov,nmov,nofficial,nsubmov,
		ndoc,description,doc,annotations,
		REG.title as registry,
		sum(initialprevision) as initialprevision,
		sum(finvar) as finvar	,
		sum(finphase_amount) as finphase_amount,
		sum(cassaphase_amount) as cassaphase_amount,
		emessiondate,printeddate,trasmitteddate,transactiondate,annulmentdate,
		@phasecassa as phasecassa,
		@finname as finname			
	FROM #income
	JOIN fin F
		ON F.idfin = #income.idfin
	LEFT OUTER JOIN registry REG
		ON REG.idreg = #income.idreg
	GROUP BY codeupb,idupb,upb,upbprintingorder,
		F.printingorder,#income.idfin,idmov,
		F.codefin,F.title,
		rowkind,nphase,operationdate,operationkind,ymov,nmov,nofficial,nsubmov,ndoc,description,doc,
		annotations,REG.title,finvar,emessiondate,printeddate,
		trasmitteddate,transactiondate,annulmentdate			
	ORDER BY idupb ASC,F.printingorder ASC,
		operationdate ASC,
		rowkind ASC,
		ymov ASC,
		nmov ASC,
		nofficial ASC,
		nsubmov ASC
ELSE
	SELECT #income.idfin,idmov,
		@level as levelname,
		F.codefin,
		F.printingorder as finprintingorder,
		F.title,
		codeupb,idupb,upb,upbprintingorder,rowkind,
		nphase,operationdate,operationkind,ymov,nmov,nofficial,nsubmov,
		ndoc,description,doc,annotations,REG.title as registry,
		initialprevision,finvar,finphase_amount,cassaphase_amount,
		emessiondate,printeddate,trasmitteddate,transactiondate,annulmentdate,
		@phasecassa as phasecassa,
		@finname as finname	
	FROM #income
	JOIN fin F
		ON F.idfin = #income.idfin
	LEFT OUTER JOIN registry REG
		ON REG.idreg = #income.idreg
	ORDER BY idupb ASC, F.printingorder ASC,
		operationdate ASC,
		rowkind ASC,
		ymov ASC,
		nmov ASC,
		nofficial ASC,
		nsubmov ASC
  END



GO

print 'rpt_partitario_entrata OK'

GO
if object_id('[rpt_partitario_anagrafica_entrate]') is not null
	drop PROCEDURE [rpt_partitario_anagrafica_entrate]
go
-- rpt_partitario_anagrafica_entrate 2009,3,null,{d '1900-01-01'}, {d '2009-12-31'},'0'
CREATE      PROCEDURE [rpt_partitario_anagrafica_entrate]
	@ayear int,
	@codelevel tinyint,
	@codefin varchar(50),
	@start datetime,
	@stop datetime,
	@idreg int
AS

BEGIN
DECLARE @idfin int
IF (@codefin IS NULL OR @codefin = '' OR @codefin = '%')
	BEGIN
		SET @idfin = null	
	END
Else
	BEGIN
	   	SET @idfin = (select idfin 
				from fin 
				where codefin = @codefin 
				and ayear=@ayear 
				and (fin.flag&1)=0) -- Entrata
	END
/* Versione 1.0.2 del 14/12/2007 ultima modifica: PIERO */
DECLARE @level_input tinyint
SELECT @level_input = ISNULL(nlevel, @codelevel) from fin where idfin = @idfin
-- ho scelto come livello 2 e poi ho specificato il capitolo, lui corregge @nlevel dandogli 3
IF (@codelevel < @level_input ) AND (@idfin is not null)
BEGIN
	SET  @codelevel = @level_input
END

DECLARE @nfinphase tinyint
SELECT @nfinphase = incomeregphase
FROM uniconfig
DECLARE @maxincomephase tinyint
SELECT  @maxincomephase = MAX(nphase)
FROM    incomephase 
	
CREATE TABLE #income
(
	idfin int,
	nphase tinyint,
	flagarrear char(1),	
	ayear int,
	adate datetime,
	description varchar(300),
	title varchar(100),
	available decimal(19,2),
	rowkind int,
	npro int,
	nassessment int,
	ymovassessment int,
	nmovassessment int,
	assessment_amount decimal(19,2),
	origin_assessment_amount decimal(19,2),
	nproceed int,
	ymovproceed int,
	nmovproceed int,
	proceed_amount decimal(19,2)
)
INSERT INTO #income
(
	idfin,
	nphase, 
	rowkind,
	adate, 
	description, 
	title,
	nassessment, 
	ymovassessment,
	nmovassessment,
	assessment_amount,
	origin_assessment_amount,
	nproceed, 
	ymovproceed,
	nmovproceed,
	proceed_amount,
	npro,
	flagarrear,
	available
)
SELECT 
	ISNULL(FL.idparent, incomeyear.idfin),
	income.nphase,	
	income.nphase,
	income.adate,
	CASE  WHEN (isnull(income.doc,'') = '')
	      THEN income.description 
	      WHEN (isnull(income.doc,'')<> '' AND income.docdate is null) 
	      THEN  income.description + ' (Doc. ' + isnull(Convert (varchar(20),income.doc),'')  +')'
	      ELSE  income.description + ' (Doc. ' + isnull(Convert (varchar(20),income.doc),'')  + ' del '+ 
		Convert (varchar(2),datepart(dd,income.docdate))+'/'+Convert (varchar(2),datepart(mm,income.docdate))+
		'/'+Convert (varchar(4),datepart(yy,income.docdate))+')'
	end,
	registry.title,
	I2.idinc, --Accertamento
	I2.ymov,
	I2.nmov,  
	CASE 
		WHEN income.nphase = @nfinphase THEN incomeyear.amount
		ELSE 0
	END ,
	CASE 
		WHEN income.nphase = @nfinphase THEN incomeyear_starting.amount
		ELSE 0
	END ,
	I3.idinc, --Incasso
	I3.ymov,
	I3.nmov,
	CASE 
		WHEN income.nphase = @maxincomephase THEN incomeyear.amount
		ELSE 0
	END ,
	proceeds.npro,
	CASE
		WHEN ((incometotal.flag&1)=0) THEN 'C'
		WHEN ((incometotal.flag&1)=1) THEN 'R'
	END, 
	CASE 
		WHEN income.nphase = @nfinphase THEN IT2.available
		ELSE 0
	END 
FROM incomeyear
JOIN income
	ON incomeyear.idinc = income.idinc 
JOIN registry 
	ON income.idreg = registry.idreg
JOIN upb 
	ON upb.idupb=incomeyear.idupb
JOIN fin 
	ON incomeyear.idfin = fin.idfin 
JOIN incometotal
	ON  incomeyear.idinc = incometotal.idinc
	AND incomeyear.ayear = incometotal.ayear	
JOIN incomelink IL2
	ON IL2.idchild = income.idinc  
	AND IL2.nlevel = @nfinphase
LEFT  OUTER JOIN finlink FL
	ON FL.idchild = incomeyear.idfin AND FL.nlevel = @codelevel
LEFT  OUTER JOIN finlink FL1
	ON FL1.idchild = incomeyear.idfin AND FL1.nlevel = @level_input
LEFT  OUTER JOIN incomelast
	ON incomelast.idinc = income.idinc
LEFT OUTER 
	JOIN proceeds
	ON incomelast.kpro=proceeds.kpro
LEFT OUTER JOIN income I2
	ON I2.idinc = IL2.idparent
JOIN incometotal IT2
	ON IT2.idinc=I2.idinc
	AND IT2.ayear = incomeyear.ayear
LEFT OUTER JOIN income I3
	 ON I3.idinc = incomelast.idinc 
LEFT OUTER JOIN incometotal incometotal_firstyear
  	ON incometotal_firstyear.idinc = income.idinc
  	AND ((incometotal_firstyear.flag & 2) <> 0 )
LEFT OUTER JOIN incomeyear incomeyear_starting
	ON incomeyear_starting.idinc = incometotal_firstyear.idinc
  	AND incomeyear_starting.ayear = incometotal_firstyear.ayear
WHERE ((fin.flag&1)=0) --Entrata	
	AND (@idfin IS NULL OR isnull(FL1.idparent, fin.idfin) = @idfin)
	AND incomeyear.ayear = @ayear
	AND income.adate <= @stop
	AND ((income.nphase IN (@nfinphase,@maxincomephase )))
	AND ( income.idreg = @idreg OR @idreg = 0 )

UPDATE #income
	SET
	assessment_amount = assessment_amount + 
				(SELECT ISNULL(SUM(amount),0.0) 
				   FROM incomevar
				  WHERE incomevar.idinc = #income.nassessment
				    AND incomevar.adate <= @stop
				    AND incomevar.yvar = @ayear
				    AND #income.nphase = @nfinphase),
	proceed_amount = proceed_amount + 
				(SELECT ISNULL(SUM(amount),0.0) 
				   FROM incomevar
				  WHERE incomevar.idinc = #income.nproceed
				    AND incomevar.adate <= @stop
				    AND incomevar.yvar = @ayear
				    AND #income.nphase = @maxincomephase
				)
DELETE FROM #income
WHERE nphase = @maxincomephase AND npro IS NULL
	SELECT  
		#income.idfin,
		F.codefin,
		F.title as fintitle,
		F.printingorder as finprintingorder,
		nphase,
		rowkind,
		adate,
		description,
		#income.title as registry,
		nassessment,
		ymovassessment,
		nmovassessment,	
		(isnull(assessment_amount,0.0)) as assessment_amount,
		(isnull(origin_assessment_amount,0.0)) as origin_assessment_amount,
		nproceed,
		ymovproceed,
		nmovproceed,	
		(isnull(proceed_amount,0.0)) as proceed_amount,
		sum(isnull(available,0)) as available,
		npro,
		flagarrear,
		@ayear as ayear
	FROM  #income
	JOIN fin F
		ON #income.idfin = F.idfin
	GROUP BY
		F.printingorder,
		#income.idfin,F.codefin,F.title,
		nphase,
		rowkind	,adate,description,#income.title,nassessment,nproceed,npro,flagarrear,
		#income.ayear,
		assessment_amount,origin_assessment_amount,proceed_amount,available,
		ymovassessment, nmovassessment,	ymovproceed, nmovproceed
	ORDER BY 
		F.printingorder, rowkind, adate
END

GO

print '[rpt_partitario_anagrafica_entrate] OK'

GO
if object_id('compute_payment_bank') is not null
	drop PROCEDURE compute_payment_bank
go

CREATE    PROCEDURE compute_payment_bank
(
	@kpay int
)
AS BEGIN
DECLARE @ypay int
DECLARE @npay int
SELECT @ypay = ypay, @npay = npay FROM payment WHERE kpay = @kpay
-- Mandato già esitato (anche parzialmente)
IF (SELECT COUNT(*)
	FROM banktransaction
	WHERE kpay = @kpay) > 0
BEGIN
	
	UPDATE payment_bank
	SET amount =
		(SELECT SUM(e.curramount) 
		FROM expensetotal e
		JOIN expenselast l
			ON e.idexp = l.idexp
		WHERE l.kpay = payment_bank.kpay
			AND l.idpay = payment_bank.idpay)
	WHERE payment_bank.kpay = @kpay
	RETURN
END
-- Mandato non esitato
-- Ripristino situazione iniziale
-- Cancellazione dei movimenti bancari associati al mandato
DELETE FROM payment_bank WHERE kpay = @kpay
-- Scollegamento dei movimenti bancari dai movimenti finanziari associati al mandato
--UPDATE expenselast SET idpay = NULL WHERE ypay = @ypay AND npay = @npay
UPDATE expenselast SET idpay = NULL WHERE kpay = @kpay
DECLARE @groupby char(1)
SELECT @groupby =
CASE
	WHEN ((flagbank_grouping & 1) <> 0) THEN 'N' -- non raggruppare
	WHEN ((flagbank_grouping & 2) <> 0) THEN 'C' -- raggruppa per causale pagamento (significa che accorpa le causali, non che le raggruppa)
	WHEN ((flagbank_grouping & 4) <> 0) THEN 'P' -- raggruppa per modalità pagamento
END
FROM treasurer
WHERE idtreasurer = (SELECT idtreasurer FROM payment WHERE kpay = @kpay)
	
DECLARE @groupbyCupCig char(1)
SELECT @groupbyCupCig =
CASE
	WHEN ((flagbank_grouping & 8) <> 0) THEN 'S'  -- CUP e CIG
	Else 'N'
END
FROM config
WHERE ayear = @ypay
	
--  Mi creo una tabella temporanea in cui inserisco il codice CUP e il codice CIG dopo averli calcolati.
--  Il calcolo del CUP e CIG, ossia la loro lettura, non è immediata perchè vanno letti nel modo seguente:
--  Cup : Spesa -> Contratto passivo -> UPB -> Bilancio
--  Cig : Spesa -> Contratto passivo
DECLARE @expenseregphase	tinyint
SELECT @expenseregphase = expenseregphase FROM  uniconfig
-- Tabella dei pagamenti del mandato in oggetto
CREATE TABLE #CigCup(
	idexp int,
	CUP varchar(15),
	cupcodefin varchar(15),
	cupcodeupb varchar(15),
	cupcodedetail varchar(15),
	cupcodeexpense varchar(15),
	CIG varchar(10),
	cigcodeexpense varchar(10),
	cigcodemandate varchar(10)
)
if (@groupbyCupCig='S')
Begin
		-- Inserimento dei movimenti di spesa presenti nella Mandato di pagamento
		INSERT INTO #CigCup(
			idexp,
			cupcodefin,
			cupcodeupb,
			cupcodeexpense, 
			cigcodeexpense
		)
		SELECT
			E.idexp, 
			FL.cupcode,
			U.cupcode,
			RegPhase.cupcode,
			RegPhase.cigcode
		FROM expense E
		JOIN expenselast EL
			ON E.idexp = EL.idexp
		JOIN expenseyear EY
			ON EY.idexp = E.idexp
		JOIN expenselink as RegPhaseELK	-- Dobbiamo risalire alla fase del creditore per recuperare CUP e CIG
			ON RegPhaseELK.idchild = EL.idexp
			AND RegPhaseELK.nlevel = @expenseregphase
		JOIN expense RegPhase			-- fase del Creditore
			ON RegPhase.idexp = RegPhaseELK.idparent 
		JOIN finlast FL
			ON EY.idfin = FL.idfin
		JOIN upb U
			ON EY.idupb = U.idupb 
		WHERE EL.kpay = @kpay

declare @fasecontrattopassivo int
select @fasecontrattopassivo = expensephase from config where ayear=@ypay

		-- Valorizza codice cCUPup da eventuali contabilizzazioni di dettagli ordine 
		UPDATE #CigCup SET cupcodedetail = 
			   (SELECT MAX(cupcode )
				  FROM mandatedetail
				 WHERE (idexp_taxable IN (SELECT idparent 
											FROM expenselink 
										   WHERE idchild = #CigCup.idexp and nlevel=@fasecontrattopassivo) 
					OR idexp_iva IN (SELECT idparent 
									   FROM expenselink 
									  WHERE idchild = #CigCup.idexp and nlevel=@fasecontrattopassivo))
				   AND cupcode IS NOT NULL)
		where cupcodeexpense is null
		
		-- Valorizza il codice CIG eventualmente presente del contratto passivo
		UPDATE #CigCup SET cigcodemandate = 
			   (SELECT MAX( mandate.cigcode )
					FROM mandate
					JOIN mandatedetail
						ON	mandate.idmankind = mandatedetail.idmankind 
						AND mandate.yman = mandatedetail.yman 
						AND mandate.nman = mandatedetail.nman
				 WHERE (mandatedetail.idexp_taxable IN (SELECT idparent 
											FROM expenselink 
										   WHERE idchild = #CigCup.idexp and nlevel=@fasecontrattopassivo) 
					OR mandatedetail.idexp_iva IN (SELECT idparent 
									   FROM expenselink 
									  WHERE idchild = #CigCup.idexp and nlevel=@fasecontrattopassivo))
				 )
		where cigcodeexpense is null				 
		UPDATE #CigCup SET CIG = ISNULL(cigcodeexpense,ISNULL(cigcodemandate,''))  
		UPDATE #CigCup SET CUP = ISNULL(cupcodeexpense,ISNULL(cupcodedetail, ISNULL(cupcodeupb, ISNULL(cupcodefin,'')))) 
	-- Quindi nella tabella #CigCup ho per ogni pagamento del mandato il relativo CUP e CIG
End

DECLARE @idpay_free int
IF (@groupby = 'N')  -- non raggruppare
BEGIN
	DECLARE @idexp int
	DECLARE @idreg int
	DECLARE @description varchar(150)
	DECLARE @curramount float
	DECLARE @doc varchar(35)
	DECLARE @docdate datetime
	DECLARE @nbill int
	
	DECLARE pay_crs INSENSITIVE CURSOR FOR
	
	SELECT EV.idexp, EV.idreg, EV.description, EV.doc, EV.docdate, EV.curramount, EV.nbill
	FROM expenseview EV
	JOIN expenselast EL 
		ON EV.idexp = EL.idexp
	WHERE EL.kpay = @kpay
	FOR READ ONLY
	
	OPEN pay_crs
	FETCH NEXT FROM pay_crs INTO @idexp, @idreg, @description, @doc, @docdate, @curramount, @nbill
	
	WHILE (@@FETCH_STATUS = 0)
	BEGIN
		IF (@doc IS NOT NULL)
		BEGIN
			SELECT @description = 'Pag. ' + @doc
		END
		IF ((@doc IS NOT NULL) AND (@docdate IS NOT NULL))
		BEGIN
			SELECT @description = @description + ' del ' + CONVERT(varchar(20), @docdate, 105)
		END
		SET @idpay_free = ISNULL((SELECT MAX(idpay) FROM payment_bank WHERE kpay = @kpay),0) + 1
	
		INSERT INTO payment_bank (kpay, idpay, idreg, description, amount, ct, cu, lt, lu) 
		VALUES(@kpay, @idpay_free, @idreg, @description, @curramount,  GETDATE(), 'SP', GETDATE(), '''SP''')
	
		UPDATE expenselast
		SET idpay = @idpay_free
		WHERE idexp = @idexp
	
		FETCH NEXT FROM pay_crs INTO @idexp, @idreg, @description, @doc, @docdate, @curramount, @nbill 
	END
	CLOSE pay_crs
	DEALLOCATE pay_crs
END
DECLARE	@idexp_1 int
DECLARE	@idreg_1 int 
DECLARE	@doc_1 varchar(35) 
DECLARE	@description_1 varchar(150)
DECLARE	@curramount_1 float 
DECLARE	@idpaymethod_1 int
DECLARE	@iban_1 varchar(50) 
DECLARE	@cin_1 varchar(20) 
DECLARE	@idbank_1 varchar(20) 
DECLARE	@idcab_1 varchar(20)
DECLARE	@cc_1 varchar(30) 
DECLARE @biccode_1 varchar(20)
DECLARE @extracode_1 varchar(10)
DECLARE @iddeputy_1 int
DECLARE @flag_girofondo_1 int
DECLARE @flag_girofondo_ord_tabA_1 int
DECLARE @flag_girofondo_vinc_tabA_1 int
DECLARE @flag_girofondo_ord_tabB_1 int
DECLARE @flag_girofondo_vinc_tabB_1 int
DECLARE @destinazione_1 int
 
DECLARE	@paymentdescr_1 varchar(150)
DECLARE @nbill_1 int
DECLARE @docdate_1 datetime
DECLARE @CUP_1 varchar(15)
DECLARE @CIG_1 varchar(10)
DECLARE	@idexp_2 int
DECLARE	@idreg_2 int 
DECLARE	@doc_2 varchar(35) 
DECLARE	@description_2 varchar(150)
DECLARE	@curramount_2 float 
DECLARE	@idpaymethod_2 int
DECLARE	@iban_2 varchar(50)
DECLARE	@cin_2 varchar(20) 
DECLARE	@idbank_2 varchar(20) 
DECLARE	@idcab_2 varchar(20)
DECLARE	@cc_2 varchar(30) 
DECLARE @biccode_2 varchar(20)
DECLARE @extracode_2 varchar(10)
DECLARE @iddeputy_2 int
DECLARE @flag_girofondo_2 int
DECLARE @flag_girofondo_ord_tabA_2 int
DECLARE @flag_girofondo_vinc_tabA_2 int
DECLARE @flag_girofondo_ord_tabB_2 int
DECLARE @flag_girofondo_vinc_tabB_2 int
DECLARE @destinazione_2 int
DECLARE	@paymentdescr_2 varchar(150)
DECLARE @nbill_2 int
DECLARE @docdate_2 datetime
DECLARE @CUP_2 varchar(15)
DECLARE @CIG_2 varchar(10)
DECLARE @flagsingle char(1)
DECLARE @pbank_descr varchar(150)
DECLARE @pbank_amount decimal(19,2)
	
IF (@groupby = 'C') -- in realtà accorpa le causali e raggruppa su beneficiario,delegato, coordinate bancarie ecc. ecc.
BEGIN
	DECLARE @motiveprefix varchar(20)
	DECLARE @motiveseparator char(1)
	DECLARE @motivelen smallint
	
	SELECT 
		@motiveprefix = motiveprefix, 
		@motiveseparator = motiveseparator,
		@motivelen = motivelen
	FROM config
	WHERE ayear = @ypay
	
	SELECT @flagsingle = 'S'
	SELECT @pbank_amount = 0
	SELECT @pbank_descr = @motiveprefix + ' '
	
	DECLARE pay_crs INSENSITIVE CURSOR FOR
	SELECT EV.idexp, EV.idreg, EV.doc, EV.description, EV.curramount, EV.idpaymethod, EV.iban,
		EV.cin, EV.idbank, EV.idcab, EV.cc,EV.biccode, EV.extracode,EV.iddeputy,
		-- girofondo,girof ordin tab A, girof vincol tab A, girof ordin tab B, girof vincol tab B, destinazione (fruttifera/infruttifera)
	    (EV.paymethod_flag&64), (EV.paymethod_flag&256),(EV.paymethod_flag&512),(EV.paymethod_flag&1024),(EV.paymethod_flag&2048),(EV.paymethod_flag&4096),
		EV.paymentdescr, EV.nbill, C.CUP, C.CIG
	FROM expenseview EV
	JOIN expenselast EL
		ON EV.idexp = EL.idexp
	LEFT OUTER JOIN #CigCup C
		ON C.idexp = EL.idexp
	WHERE EL.kpay = @kpay
	ORDER BY EV.idreg, EV.idpaymethod, EV.iban, EV.cin, EV.idbank, EV.idcab, EV.cc, 
	EV.biccode, EV.extracode,EV.iddeputy,
	-- girof.,girof. ordin. tab A, girof. vincol. tab A, girof. ordin. tab B, girof. vincol. tab B, destinazione (fruttifera/infruttifera)
	(EV.paymethod_flag&64), (EV.paymethod_flag&256),(EV.paymethod_flag&512),(EV.paymethod_flag&1024),(EV.paymethod_flag&2048),(EV.paymethod_flag&4096),
	EV.paymentdescr, EV.nbill, C.CUP, C.CIG
	FOR READ ONLY
	
	OPEN pay_crs
	
	FETCH NEXT FROM pay_crs INTO @idexp_1, @idreg_1, @doc_1, @description_1,
			@curramount_1, @idpaymethod_1, @iban_1,
			@cin_1, @idbank_1, @idcab_1, @cc_1, 
			@biccode_1, @extracode_1, @iddeputy_1,@flag_girofondo_1,
			@flag_girofondo_ord_tabA_1, @flag_girofondo_vinc_tabA_1,
			@flag_girofondo_ord_tabB_1,@flag_girofondo_vinc_tabB_1, 
			@destinazione_1,@paymentdescr_1, @nbill_1, @CUP_1, @CIG_1
	
	IF (@@FETCH_STATUS = 0)
	BEGIN
		FETCH NEXT FROM pay_crs INTO @idexp_2, @idreg_2, @doc_2, @description_2,
		@curramount_2, @idpaymethod_2, @iban_2,
		@cin_2, @idbank_2, @idcab_2, @cc_2, 
		@biccode_2, @extracode_2, @iddeputy_2,@flag_girofondo_2,
		@flag_girofondo_ord_tabA_2, @flag_girofondo_vinc_tabA_2,
		@flag_girofondo_ord_tabB_2,@flag_girofondo_vinc_tabB_2, 
		@destinazione_2, @paymentdescr_2, @nbill_2, @CUP_2, @CIG_2
	
		WHILE (@@FETCH_STATUS = 0)
		BEGIN
			SET @idpay_free = ISNULL((SELECT MAX(idpay) FROM payment_bank WHERE kpay = @kpay),0) + 1
	
			SELECT @pbank_amount = ISNULL(@pbank_amount, 0) + @curramount_1
	
			IF ((@doc_1 IS NOT NULL) AND (@doc_1 <> ''))
			BEGIN
				SELECT @pbank_descr = @pbank_descr + @doc_1 + @motiveseparator + ' '
			END
			IF @idreg_1 <> @idreg_2
				OR @idpaymethod_1 <> @idpaymethod_2
				OR ISNULL(@iban_1,'') <> ISNULL(@iban_2,'')
				OR ISNULL(@cin_1,'') <> ISNULL(@cin_2,'')
				OR ISNULL(@idbank_1,'') <> ISNULL(@idbank_2,'')
				OR ISNULL(@idcab_1,'') <> ISNULL(@idcab_2,'')
				OR ISNULL(@cc_1,'') <> ISNULL(@cc_2,'')
				OR ISNULL(@biccode_1,'') <> ISNULL(@biccode_2,'')
				OR ISNULL(@extracode_1,'') <> ISNULL(@extracode_2,'')
				OR ISNULL(@iddeputy_1,0) <> ISNULL(@iddeputy_2,0)
				OR ISNULL(@flag_girofondo_1,0) <> ISNULL(@flag_girofondo_2,0)
				OR ISNULL(@flag_girofondo_ord_tabA_1,0) <> ISNULL(@flag_girofondo_ord_tabA_2,0)
				OR ISNULL(@flag_girofondo_vinc_tabA_1,0) <> ISNULL(@flag_girofondo_vinc_tabA_2,0)
				OR ISNULL(@flag_girofondo_ord_tabB_1,0) <> ISNULL(@flag_girofondo_ord_tabB_2,0)
				OR ISNULL(@flag_girofondo_vinc_tabB_1,0) <> ISNULL(@flag_girofondo_vinc_tabB_2,0)
				OR ISNULL(@destinazione_1,0) <> ISNULL(@destinazione_2,'')
				OR ISNULL(@paymentdescr_1,'') <> isnull(@paymentdescr_2,'')
				OR DATALENGTH(@pbank_descr) > @motivelen
				OR ISNULL(@nbill_1,0) <> ISNULL(@nbill_2,0)
				OR ISNULL(@CUP_1,'') <> ISNULL(@CUP_2,'')
				OR ISNULL(@CIG_1,'') <> ISNULL(@CIG_2,'')
			BEGIN
				IF @flagsingle = 'S'
				BEGIN
					SELECT @pbank_descr = @description_1
				END
				INSERT INTO payment_bank (kpay, idpay, idreg, description, amount, ct, cu, lt, lu) 
				VALUES
				(@kpay, @idpay_free, @idreg_1, @pbank_descr, @pbank_amount, GETDATE(), 'SP', GETDATE(), '''SP''')
				SELECT @pbank_amount = 0
				SELECT @flagsingle = 'S'
				SELECT @pbank_descr = @motiveprefix + ' '
			END
			ELSE
			BEGIN
				SELECT @flagsingle = 'N'
			END
	
			UPDATE expenselast SET idpay = @idpay_free WHERE idexp = @idexp_1
	
			SELECT 
				@idexp_1 = @idexp_2, @idreg_1 = @idreg_2, 
				@doc_1 = @doc_2, @description_1 = @description_2,
				@curramount_1 = @curramount_2, @idpaymethod_1 = @idpaymethod_2,
				@iban_1 = @iban_2, @cin_1 = @cin_2, @idbank_1 = @idbank_2, 
				@idcab_1 = @idcab_2, @cc_1 = @cc_2, 
				@biccode_1= @biccode_2, @extracode_1 = @extracode_2, @iddeputy_1 = @iddeputy_2,
				@flag_girofondo_1 = @flag_girofondo_2,
				@flag_girofondo_ord_tabA_1 = @flag_girofondo_ord_tabA_2, 
				@flag_girofondo_vinc_tabA_1 = @flag_girofondo_vinc_tabA_2,
				@flag_girofondo_ord_tabB_1 = @flag_girofondo_ord_tabB_2,
				@flag_girofondo_vinc_tabB_1 = @flag_girofondo_vinc_tabB_2, 
				@destinazione_1 = @destinazione_2,
				@paymentdescr_1 = @paymentdescr_2, @nbill_1 = @nbill_2,
				@CUP_1 = @CUP_2, @CIG_1 = @CIG_2
	
			FETCH NEXT FROM pay_crs INTO @idexp_2, @idreg_2, @doc_2, @description_2,
			@curramount_2, @idpaymethod_2, @iban_2,
			@cin_2, @idbank_2, @idcab_2, @cc_2, 
			@biccode_2, @extracode_2, @iddeputy_2,@flag_girofondo_2,
			@flag_girofondo_ord_tabA_2, @flag_girofondo_vinc_tabA_2,
			@flag_girofondo_ord_tabB_2,@flag_girofondo_vinc_tabB_2, 
			@destinazione_2,
			@paymentdescr_2, @nbill_2, @CUP_2, @CIG_2
		END
		SET @idpay_free = ISNULL((SELECT MAX(idpay) FROM payment_bank WHERE kpay = @kpay),0) + 1
	
		IF ((@flagsingle = 'S') AND ((@doc_1 IS NULL) OR (@doc_1 = '')))
		BEGIN
			SELECT @pbank_descr = @description_1
		END
		ELSE IF ((@doc_1 IS NOT NULL) AND (@doc_1 <> ''))
		BEGIN
			SELECT @pbank_descr = @pbank_descr + @doc_1
		END
	
		SELECT @pbank_amount = ISNULL(@pbank_amount, 0) + @curramount_1
	
		INSERT INTO payment_bank (kpay, idpay, idreg, description, amount, ct, cu, lt, lu) 
		VALUES (@kpay, @idpay_free, @idreg_1, @pbank_descr, @pbank_amount,  GETDATE(), 'SP', GETDATE(), '''SP''')
	
		UPDATE expenselast SET idpay = @idpay_free WHERE idexp = @idexp_1
	END
	CLOSE pay_crs
	DEALLOCATE pay_crs
END
IF (@groupby = 'P')
BEGIN
	SELECT @flagsingle = 'S'
	SELECT @pbank_amount = 0
	SELECT @pbank_descr = 'Pagamenti diversi'
	
	DECLARE pay_crs INSENSITIVE CURSOR FOR
	SELECT 	v.idexp, v.idreg, v.doc, v.docdate, v.description, v.curramount, v.idpaymethod,
		v.iban, v.cin, v.idbank, v.idcab, v.cc, v.biccode,
		v.extracode,v.iddeputy,
		-- girofondo,girof ordin tab A, girof vincol tab A, girof ordin tab B, girof vincol tab B, destinazione (fruttifera/infruttifera)
	    (v.paymethod_flag&64), (v.paymethod_flag&256),(v.paymethod_flag&512),(v.paymethod_flag&1024),(v.paymethod_flag&2048),(v.paymethod_flag&4096),
		v.paymentdescr, v.nbill, C.CUP, C.CIG
	FROM expenseview v
	JOIN expenselast l
		ON v.idexp = l.idexp
	LEFT OUTER JOIN #CigCup C
		ON C.idexp = L.idexp
	WHERE l.kpay = @kpay
	ORDER BY v.idreg, v.idpaymethod, v.iban, v.cin, v.idbank, v.idcab, v.cc, 
	v.extracode,v.iddeputy,
	-- girofondo,girof ordin tab A, girof vincol tab A, girof ordin tab B, girof vincol tab B, destinazione (fruttifera/infruttifera)
	(v.paymethod_flag&64), (v.paymethod_flag&256),(v.paymethod_flag&512),(v.paymethod_flag&1024),(v.paymethod_flag&2048),(v.paymethod_flag&4096),
	v.paymentdescr, v.nbill, C.CUP, C.CIG
	FOR READ ONLY
	
	OPEN pay_crs
	
	FETCH NEXT FROM pay_crs INTO @idexp_1, @idreg_1, @doc_1, @docdate_1, @description_1,
		@curramount_1, @idpaymethod_1, @iban_1, 
		@cin_1, @idbank_1, @idcab_1, @cc_1, 
		@biccode_1, @extracode_1, @iddeputy_1,@flag_girofondo_1,
		@flag_girofondo_ord_tabA_1, @flag_girofondo_vinc_tabA_1,
		@flag_girofondo_ord_tabB_1,@flag_girofondo_vinc_tabB_1, 
		@destinazione_1,
		@paymentdescr_1, @nbill_1, @CUP_1, @CIG_1
	
	IF (@@FETCH_STATUS = 0)
	BEGIN
		FETCH NEXT FROM pay_crs INTO @idexp_2, @idreg_2, @doc_2, @docdate_2, @description_2,
			@curramount_2, @idpaymethod_2, @iban_2, 
			@cin_2, @idbank_2, @idcab_2, @cc_2, 
			@biccode_2, @extracode_2, @iddeputy_2,@flag_girofondo_2,
			@flag_girofondo_ord_tabA_2, @flag_girofondo_vinc_tabA_2,
			@flag_girofondo_ord_tabB_2,@flag_girofondo_vinc_tabB_2, 
			@destinazione_2,
			@paymentdescr_2, @nbill_2, @CUP_2, @CIG_2
	
		WHILE (@@FETCH_STATUS = 0)
		BEGIN
			SET @idpay_free = ISNULL((SELECT MAX(idpay) FROM payment_bank WHERE kpay = @kpay),0) + 1
	
			SELECT @pbank_amount = ISNULL(@pbank_amount, 0) + @curramount_1
	
			IF @idreg_1 <> @idreg_2
				OR @idpaymethod_1 <> @idpaymethod_2
				OR ISNULL(@iban_1,'') <> ISNULL(@iban_2,'')
				OR ISNULL(@cin_1,'') <> ISNULL(@cin_2,'')
				OR ISNULL(@idbank_1,'') <> ISNULL(@idbank_2,'')
				OR ISNULL(@idcab_1,'') <> ISNULL(@idcab_2,'')
				OR ISNULL(@cc_1,'') <> ISNULL(@cc_2,'')
				OR ISNULL(@biccode_1,'') <> ISNULL(@biccode_2,'')
				OR ISNULL(@extracode_1,'') <> ISNULL(@extracode_2,'')
				OR ISNULL(@iddeputy_1,0) <> ISNULL(@iddeputy_2,0)
				OR ISNULL(@flag_girofondo_1,0) <> ISNULL(@flag_girofondo_2,0)
				OR ISNULL(@flag_girofondo_ord_tabA_1,0) <> ISNULL(@flag_girofondo_ord_tabA_2,0)
				OR ISNULL(@flag_girofondo_vinc_tabA_1,0) <> ISNULL(@flag_girofondo_vinc_tabA_2,0)
				OR ISNULL(@flag_girofondo_ord_tabB_1,0) <> ISNULL(@flag_girofondo_ord_tabB_2,0)
				OR ISNULL(@flag_girofondo_vinc_tabB_1,0) <> ISNULL(@flag_girofondo_vinc_tabB_2,0)
				OR ISNULL(@destinazione_1,0) <> ISNULL(@destinazione_2,'')
				OR ISNULL(@paymentdescr_1,'') <> isnull(@paymentdescr_2,'')
				OR ISNULL(@nbill_1,0) <> ISNULL(@nbill_2,0)
				OR ISNULL(@CUP_1,'') <> ISNULL(@CUP_2,'')
				OR ISNULL(@CIG_1,'') <> ISNULL(@CIG_2,'')
			BEGIN
				IF (@flagsingle = 'S')
				BEGIN
					SELECT @pbank_descr = @description_1
					IF (@doc_1 IS NOT NULL)
					BEGIN
						SELECT @pbank_descr = 'Pag. ' + @doc_1
					END
					IF ((@doc_1 IS NOT NULL) AND (@docdate_1 IS NOT NULL))
					BEGIN
						SELECT @pbank_descr = @pbank_descr + ' del ' + CONVERT(varchar(20), @docdate_1, 105)
					END
				END
				INSERT INTO payment_bank (kpay, idpay, idreg, description, amount, ct, cu, lt, lu) 
				VALUES (@kpay, @idpay_free, @idreg_1, @pbank_descr, @pbank_amount,  GETDATE(), 'SP', GETDATE(), '''SP''')
		
				SELECT @pbank_amount = 0
				SELECT @flagsingle = 'S'
				SELECT @pbank_descr = 'Pagamenti diversi'
		
			END
			ELSE
			BEGIN
				SELECT @flagsingle = 'N'
			END
	
			UPDATE expenselast SET idpay = @idpay_free WHERE idexp = @idexp_1
	
			SELECT 
				@idexp_1 = @idexp_2, @idreg_1 = @idreg_2, 
				@doc_1 = @doc_2, @docdate_1 = @docdate_2,
				@description_1 = @description_2, @curramount_1 = @curramount_2, 
				@idpaymethod_1 = @idpaymethod_2,
				@iban_1 = @iban_2, @cin_1 = @cin_2, 
				@idbank_1 = @idbank_2, @idcab_1 = @idcab_2,
				@cc_1 = @cc_2, 
				@biccode_1= @biccode_2, @extracode_1 = @extracode_2, @iddeputy_1 = @iddeputy_2,
				@flag_girofondo_1 = @flag_girofondo_2,
				@flag_girofondo_ord_tabA_1 = @flag_girofondo_ord_tabA_2, 
				@flag_girofondo_vinc_tabA_1 = @flag_girofondo_vinc_tabA_2,
				@flag_girofondo_ord_tabB_1 = @flag_girofondo_ord_tabB_2,
				@flag_girofondo_vinc_tabB_1 = @flag_girofondo_vinc_tabB_2, 
				@destinazione_1 = @destinazione_2,
				@paymentdescr_1 = @paymentdescr_2,
				@nbill_1 = @nbill_2,
				@CUP_1 = @CUP_2,
				@CIG_1 = @CIG_2
			FETCH NEXT FROM pay_crs INTO @idexp_2, @idreg_2, @doc_2, @docdate_2, @description_2,
				@curramount_2, @idpaymethod_2, @iban_2,
				@cin_2, @idbank_2, @idcab_2, @cc_2, 
				@biccode_2, @extracode_2, @iddeputy_2,@flag_girofondo_2,
				@flag_girofondo_ord_tabA_2, @flag_girofondo_vinc_tabA_2,
				@flag_girofondo_ord_tabB_2,@flag_girofondo_vinc_tabB_2, 
				@destinazione_2,
				@paymentdescr_2, @nbill_2, @CUP_2, @CIG_2
		END
		SET @idpay_free = ISNULL((SELECT MAX(idpay) FROM payment_bank WHERE kpay = @kpay),0) + 1
		
		IF (@flagsingle = 'S')
		BEGIN
			SELECT @pbank_descr = @description_1
		END
		SELECT @pbank_amount = ISNULL(@pbank_amount, 0) + @curramount_1
		
		INSERT INTO payment_bank (kpay, idpay, idreg, description, amount, ct, cu, lt, lu) 
		VALUES (@kpay, @idpay_free, @idreg_1, @pbank_descr, @pbank_amount,  GETDATE(), 'SP', GETDATE(), '''SP''')
		
		UPDATE expenselast SET idpay = @idpay_free WHERE idexp = @idexp_1
	END
CLOSE pay_crs
DEALLOCATE pay_crs
END
END


GO

print 'compute_payment_bank OK'

GO
if object_id('[closeyear_check_finsetupcopy]') is not null
	drop PROCEDURE [closeyear_check_finsetupcopy]
go


CREATE     PROCEDURE [closeyear_check_finsetupcopy]
(
	@ayear int
)
AS BEGIN
CREATE TABLE #errors (errordescr varchar(255))
DECLARE @nextayear int
SET @nextayear = @ayear + 1

DECLARE @nextayearstr varchar(4)
SET @nextayearstr = CONVERT(varchar(4), @nextayear)
/*	
INSERT INTO #errors
SELECT 'Voce di bilancio ' + old.finpart + ' ' + old.codefin +
' non ha voce corrispondente in nuovo esercizio'
FROM finusable old
WHERE old.ayear = @ayear
	AND NOT EXISTS(SELECT * FROM fin new WHERE new.ayear = @ayear + 1
		AND new.finpart = old.finpart AND new.codefin = old.codefin)
	AND NOT EXISTS(SELECT * FROM finlookup WHERE oldidfin = old.idfin)
INSERT INTO #errors
SELECT 'La voce di bilancio ' + old.finpart + ' ' + old.codefin +
' non ha il padre nel nuovo esercizio' 
FROM finusable old
WHERE old.ayear = @ayear
	AND NOT EXISTS(SELECT * FROM fin f2 WHERE ayear = @nextayear AND f2.idfin = 
	SUBSTRING(@nextayearstr,3,2) + SUBSTRING(old.paridfin, 3, LEN(old.paridfin)))
INSERT INTO #errors
SELECT 'Il padre della voce di bilancio ' + old.finpart + ' ' + old.codefin +
' è stato spostato nel nuovo esercizio' 
FROM finusable old
WHERE old.ayear = @ayear
	AND EXISTS(SELECT * FROM finlookup WHERE oldidfin = old.paridfin)
INSERT INTO #errors
SELECT 'La voce di bilancio ' + old.finpart + ' ' + old.codefin +
' ha un codice differente nel nuovo esercizio e non è stata inserita nella tabella di lookup' 
FROM finusable old
WHERE old.ayear = @ayear
	AND EXISTS(SELECT * FROM fin f2 WHERE f2.ayear = @nextayear
			AND SUBSTRING(f2.idfin,3, LEN(f2.idfin)) = SUBSTRING(old.idfin, 3, LEN(old.idfin))
			AND f2.codefin <> old.codefin)
	AND NOT EXISTS(SELECT * FROM finlookup WHERE oldidfin = old.idfin)
*/
IF EXISTS (SELECT * FROM taxsetup WHERE ayear = @ayear + 1)
BEGIN
	INSERT INTO #errors VALUES('Configurazione automatismi ritenute per esercizio ' + @nextayearstr + ' esistente.')
END

IF EXISTS (SELECT * FROM taxregionsetup WHERE ayear = @nextayear)
BEGIN
	INSERT INTO #errors VALUES('Configurazione automatismi ritenute ripartizione regionale per esercizio ' + @nextayearstr + ' esistente.')
END
IF EXISTS (SELECT * FROM taxpaymentpartsetup WHERE ayear = @nextayear)
BEGIN
	INSERT INTO #errors VALUES('Configurazione automatismi ritenute ripartizione percentuale per esercizio ' + @nextayearstr + ' esistente.')
END
IF EXISTS (SELECT * FROM clawbacksetup WHERE ayear = @nextayear)
BEGIN
	INSERT INTO #errors VALUES('Configurazione automatismi recuperi per esercizio ' + @nextayearstr + ' esistente.')
END
IF EXISTS
	(SELECT * FROM autoincomesorting
	JOIN sortingkind
		ON sortingkind.idsorkind = autoincomesorting.idsorkind
	WHERE (autoincomesorting.ayear = @nextayear)
		AND ((@ayear<>2006) OR (sortingkind.codesorkind<>'07E_SIOPE'))
)
BEGIN
	INSERT INTO #errors VALUES('Configurazione automatismi per la classificazione dei mov. di entrata per esercizio ' + @nextayearstr + ' esistente.')
END
IF EXISTS
	(SELECT * FROM autoexpensesorting
	JOIN sortingkind
		ON sortingkind.idsorkind = autoexpensesorting.idsorkind
	WHERE (autoexpensesorting.ayear = @nextayear)
	AND ((@ayear<>2006) or (sortingkind.codesorkind<>'07U_SIOPE'))
)
BEGIN
	INSERT INTO #errors VALUES('Configurazione automatismi per la classificazione dei mov. di spesa per esercizio ' + @nextayearstr + ' esistente.')
END
IF EXISTS
	(SELECT * FROM sortingincomefilter
	JOIN sortingkind
		ON sortingkind.idsorkind = sortingincomefilter.idsorkind
	WHERE (sortingincomefilter.ayear = @nextayear)
	AND ((@ayear<>2006) or (sortingkind.idsorkind<>'07E_SIOPE'))
)
BEGIN
	INSERT INTO #errors VALUES('Configurazione filtri per la classificazione dei mov. di entrata per esercizio ' + @nextayearstr + ' esistente.')
END
IF EXISTS
	(SELECT * FROM sortingexpensefilter
	JOIN sortingkind
		ON sortingkind.idsorkind = sortingexpensefilter.idsorkind
	WHERE (sortingexpensefilter.ayear = @nextayear)
	AND ((@ayear<>2006) or (sortingkind.codesorkind<>'07U_SIOPE'))
)
BEGIN
	INSERT INTO #errors VALUES('Configurazione filtri per la classificazione dei mov. di spesa per esercizio ' + @nextayearstr + ' esistente.')
END
IF EXISTS (SELECT * FROM taxsortingsetup WHERE ayear = @nextayear
	AND (@ayear<>2006 or idsorkind NOT IN ('07E_SIOPE','07U_SIOPE'))
)
BEGIN			
	INSERT INTO #errors VALUES('Configurazione classificazione delle ritenute per esercizio ' + @nextayearstr + ' esistente.')
END

IF EXISTS (SELECT * FROM partincomesetup P join fin fin1 on fin1.idfin= P.idfinincome and fin1.ayear= @nextayear) OR
  EXISTS (SELECT * FROM partincomesetup P join fin fin2 on fin2.idfin= P.idfinexpense and fin2.ayear= @nextayear)
BEGIN
	INSERT INTO #errors VALUES('Ripartizioni assegnazioni entrate per esercizio ' + @nextayearstr + ' esistenti.')
END
IF EXISTS (SELECT * FROM csa_contractkindyear where ayear= @nextayear)
BEGIN
	INSERT INTO #errors VALUES('Tipi contratti CSA ' + @nextayearstr + ' esistenti.')
END

IF EXISTS (SELECT * FROM csa_contractkinddata where ayear= @nextayear)
BEGIN
	INSERT INTO #errors VALUES('Attribuzioni tipi Contratti alle voci CSA ' + @nextayearstr + ' esistenti.')
END

IF EXISTS (SELECT * FROM csa_incomesetup where ayear= @nextayear)
BEGIN
	INSERT INTO #errors VALUES('Configurazione Entrate CSA ' + @nextayearstr + ' esistenti.')
END
IF EXISTS (SELECT * FROM csa_contract where ayear= @nextayear)
BEGIN
	INSERT INTO #errors VALUES('Contratti CSA ' + @nextayearstr + ' esistenti.')
END
IF EXISTS (SELECT * FROM csa_contractregistry where ayear= @nextayear)
BEGIN
	INSERT INTO #errors VALUES('Associazioni Matricole-Contratti CSA ' + @nextayearstr + ' esistenti.')
END
IF EXISTS (SELECT * FROM csa_contracttax where ayear= @nextayear)
BEGIN
	INSERT INTO #errors VALUES('Configurazione Contributi Contratti CSA ' + @nextayearstr + ' esistenti.')
END
INSERT INTO #errors
SELECT distinct ('Tipo contratto di competenza CSA ' + CK1.contractkindcode  + ' corrisponde a più tipi contratto  residui ed è associato a contratti da trasferire')
			FROM csa_contract
			JOIN csa_contractkind CK1
				ON CK1.idcsa_contractkind = csa_contract.idcsa_contractkind
			JOIN  csa_contractkindyear CKY1
					ON CKY1.idcsa_contractkind = CK1.idcsa_contractkind 
					AND CKY1.ayear = @ayear
		WHERE csa_contract.ayear = @ayear
		AND ISNULL(csa_contract.flagkeepalive,'N') = 'S'
		AND ISNULL(CK1.flagcr,'C') = 'C'
	    AND 
( SELECT COUNT(CK2.idcsa_contractkind) 
	FROM csa_contractkind CK2
	JOIN csa_contractkindyear CKY2
		ON CKY2.idcsa_contractkind = CK2.idcsa_contractkind 
		AND CKY2.ayear = CKY1.ayear
WHERE
	ISNULL(CK2.flagcr,'C') = 'R'
	AND ISNULL(CK2.flagkeepalive,'N') = 'S'
	AND  CK1.idcsa_contractkind <> CK2.idcsa_contractkind
	AND  CK1.contractkindcode = CK2.contractkindcode
) > 1
INSERT INTO #errors
SELECT distinct ('Tipo contratto di competenza CSA ' + CK1.contractkindcode  + ' non ha un corrispondente di tipo residui ed è associato a contratti da trasferire')
			FROM csa_contract
			JOIN csa_contractkind CK1
				ON CK1.idcsa_contractkind = csa_contract.idcsa_contractkind
			JOIN  csa_contractkindyear CKY1
					ON CKY1.idcsa_contractkind = CK1.idcsa_contractkind 
					AND CKY1.ayear =@ayear
		WHERE csa_contract.ayear = @ayear
		AND ISNULL(csa_contract.flagkeepalive,'N') = 'S'
		AND ISNULL(CK1.flagcr,'C') = 'C'
	    AND  NOT  EXISTS
( SELECT (CK2.idcsa_contractkind) 
	FROM csa_contractkind CK2
	JOIN csa_contractkindyear CKY2
		ON CKY2.idcsa_contractkind = CK2.idcsa_contractkind 
		AND CKY2.ayear = CKY1.ayear
WHERE
	ISNULL(CK2.flagcr,'C') = 'R'
	AND ISNULL(CK2.flagkeepalive,'N') = 'S'
	AND  CK1.idcsa_contractkind <> CK2.idcsa_contractkind
	AND  CK1.contractkindcode = CK2.contractkindcode
) 
/*
INSERT INTO #errors
SELECT 'Voce del piano dei conti ' + old.codeacc +
' non ha voce corrispondente in nuovo esercizio'
FROM accountusable old
WHERE old.ayear = @ayear
	AND NOT EXISTS(SELECT * FROM account new WHERE new.ayear = @nextayear
		AND new.codeacc = old.codeacc)
	AND NOT EXISTS(SELECT * FROM accountlookup WHERE oldidacc = old.idacc)*/
/*IF EXISTS (SELECT * FROM entrysetup WHERE ayear = @nextayear)
BEGIN
	INSERT INTO #errors VALUES('Configurazione E/P per esercizio ' + @nextayearstr + ' esistente.')
END*/
SELECT * FROM #errors
END


GO

print '[closeyear_check_finsetupcopy] OK'

GO
if object_id('exp_consolidamento') is not null
	drop PROCEDURE exp_consolidamento
go

CREATE PROCEDURE exp_consolidamento
(
	@ayear int,
	@date datetime,
	@finpart char(1),
	@levelusable tinyint
)
AS BEGIN
/* Versione 1.0.1 del 16/11/2007 ultima modifica: Pino */
-- exec exp_consolidamento 2007,{ts '2007-08-30 00:00:00'},'E',3
CREATE TABLE #balance
(
	idfin int,
	code1 varchar(50),
	order1 varchar(50),
	fintitle varchar(150),
	code2 varchar(50),
	order2 varchar(50),
	code3 varchar(50),
	order3 varchar(50),
	code4 varchar(50),
	order4 varchar(50),
	-- flagincomesurplus char(1), NON LO USA MAI	
	mov_finphase_C_univ decimal(19,2),mov_finphase_C_direct decimal(19,2),mov_finphase_C_internal decimal(19,2),
	var_finphase_C_univ decimal(19,2),var_finphase_C_direct decimal(19,2),var_finphase_C_internal decimal(19,2),
	mov_maxphase_C_univ decimal(19,2),mov_maxphase_C_direct decimal(19,2),mov_maxphase_C_internal decimal(19,2),
	var_maxphase_C_univ decimal(19,2),var_maxphase_C_direct decimal(19,2),var_maxphase_C_internal decimal(19,2),
	mov_finphase_R_univ decimal(19,2),mov_finphase_R_direct decimal(19,2),mov_finphase_R_internal decimal(19,2),
	var_finphase_R_univ decimal(19,2),var_finphase_R_direct decimal(19,2),var_finphase_R_internal decimal(19,2),
	mov_maxphase_R_univ decimal(19,2),mov_maxphase_R_direct decimal(19,2),mov_maxphase_R_internal decimal(19,2),
	var_maxphase_R_univ decimal(19,2),var_maxphase_R_direct decimal(19,2),var_maxphase_R_internal decimal(19,2)
)

DECLARE @infoadvance char(1)
SELECT @infoadvance = paramvalue FROM generalreportparameter WHERE   idparam = 'MostraAvanzo'
DECLARE @cashvaliditykind int
SELECT  @cashvaliditykind = cashvaliditykind FROM config WHERE ayear = @ayear
DECLARE @finphase tinyint
DECLARE @maxphase tinyint
DECLARE @registryphase varchar(20)

DECLARE @idregauto  int
SELECT 
	@idregauto = isnull(idregauto,0)
FROM config
WHERE ayear = @ayear
IF (@finpart = 'E')
BEGIN
	-- ricerca la fase equivalente all'accertamento
	-- se è stata inserita nella tabella di configurazione del bilancio
	SELECT @finphase = assessmentphasecode FROM config WHERE ayear = @ayear
	IF @finphase IS NULL
	BEGIN
		-- se non è stata inserita nella tabella di configurazione
		-- ipotizza che si tratti della fase dove viene identificata
		-- la voce di bilancio
		SELECT @finphase = incomefinphase FROM uniconfig
	END
	
	SELECT @registryphase = incomeregphase FROM uniconfig
	-- la fase di cassa è sempre l'ultima fase della procedura
	-- di entrata
	SELECT @maxphase = MAX(nphase) FROM incomephase
END
IF (@finpart = 'S')
BEGIN
	-- ricerca la fase equivalente all'impegno
	-- se è stata inserita nella tabella di configurazione
	-- del bilancio
	SELECT @finphase = appropriationphasecode FROM config WHERE ayear = @ayear
	IF @finphase IS NULL
	BEGIN
		-- se non è stata inserita nella tabella di configurazione
		-- ipotizza che si tratti della fase dove viene identificata
		-- la voce di bilancio
		SELECT @finphase = expensefinphase FROM uniconfig
	END
	SELECT @registryphase = expenseregphase FROM uniconfig
	-- la fase di cassa è sempre l'ultima fase della procedura di spesa
	SELECT @maxphase = MAX(nphase) FROM expensephase
END
DECLARE @supposed_ff_jan01 decimal(19,2)
DECLARE @supposed_aa_jan01 decimal(19,2)
DECLARE @ff_jan01 decimal(19,2)
DECLARE @aa_jan01 decimal(19,2)
IF (@finpart = 'E')
BEGIN
	-- Fondo cassa e avanzo di amministrazione presunti ed effettivi al 01/01
	-- dell'ayear per il quale si effettua il consuntivo.
	SELECT	@supposed_ff_jan01 =
		ISNULL(startfloatfund, 0) +
		ISNULL(proceedstilldate, 0) +
		ISNULL(proceedstoendofyear, 0) -
		ISNULL(paymentstilldate, 0) -
		ISNULL(paymentstoendofyear, 0),
	@supposed_aa_jan01 =
		ISNULL(startfloatfund, 0) +
		ISNULL(proceedstilldate, 0) +
		ISNULL(proceedstoendofyear, 0) -
		ISNULL(paymentstilldate, 0) -
		ISNULL(paymentstoendofyear, 0) +
		ISNULL(supposedpreviousrevenue, 0) +
		ISNULL(supposedcurrentrevenue , 0) -
		ISNULL(supposedpreviousexpenditure, 0) -
		ISNULL(supposedcurrentexpenditure, 0)
	FROM surplus
	WHERE ayear = @ayear - 1
-- Per ulteriori dettagli in merito a questa modifica leggere la Documentazione del task n.4077
	SELECT	@ff_jan01 = ISNULL(startfloatfund, 0) 
	FROM surplus
	WHERE ayear = @ayear
	
	SELECT
	@aa_jan01 = @ff_jan01 +
		ISNULL(previousrevenue, 0) +
		ISNULL(currentrevenue , 0) -
		ISNULL(previousexpenditure, 0) -
		ISNULL(currentexpenditure, 0)
	FROM surplus
	WHERE ayear = @ayear - 1
END

DECLARE	@finpart_bit  tinyint  -- Parte del bilancio (E = Entrata S = Spesa)
if @finpart='E' set @finpart_bit = 0
if @finpart='S' set @finpart_bit = 1
INSERT INTO #balance
(
	idfin,
	code1, order1,
	code2, order2,
	code3, order3,
	code4, order4/*,
	flagincomesurplus*/
)
SELECT 
	f4.idfin, 
	f1.codefin, f1.printingorder,
	f2.codefin, f2.printingorder,
	f3.codefin, f3.printingorder,
	f4.codefin, f4.printingorder/*,
	f4.flagincomesurplus*/
FROM fin f4
JOIN finlevel fl
	ON f4.nlevel = fl.nlevel AND  f4.ayear = fl.ayear
LEFT OUTER JOIN fin f3
	ON f3.idfin = f4.paridfin
LEFT OUTER JOIN fin f2
	ON f2.idfin = f3.paridfin
LEFT OUTER JOIN fin f1
	ON f1.idfin = f2.paridfin
WHERE f4.ayear = @ayear
	AND ((f4.flag & 1)= @finpart_bit) -- AND f4.finpart = @finpart
	AND f4.nlevel = @levelusable
DECLARE @lencod_lev1 int
SELECT @lencod_lev1 = flag / 256 FROM finlevel WHERE ayear = @ayear AND nlevel = 1
DECLARE @startpos1 int
SELECT @startpos1 = 1
DECLARE @lencod_lev2 int
SELECT @lencod_lev2 = flag / 256 FROM finlevel WHERE ayear = @ayear AND nlevel = 2
DECLARE @startpos2 int
SELECT @startpos2 = @startpos1 + @lencod_lev1
DECLARE @lencod_lev3 int
SELECT @lencod_lev3 = flag / 256 FROM finlevel WHERE ayear = @ayear AND nlevel = 3
DECLARE @startpos3 int
SELECT @startpos3 = @startpos2 + @lencod_lev2
DECLARE @lencod_lev4 int
SELECT @lencod_lev4 = flag / 256 FROM finlevel WHERE ayear = @ayear AND nlevel = 4
DECLARE @startpos4 int
SELECT @startpos4 = @startpos3 + @lencod_lev3
DECLARE @lencod_lev5 int 
SELECT @lencod_lev5 = flag / 256 FROM finlevel WHERE ayear = @ayear AND nlevel = 5
DECLARE @startpos5 int 
SELECT @startpos5 = @startpos4 + @lencod_lev4
UPDATE #balance SET code1 = code2, code2 = code3, code3 = code4, code4 = NULL WHERE code1 IS NULL
UPDATE #balance SET code1 = code2, code2 = code3, code3 = code4, code4 = NULL WHERE code1 IS NULL
UPDATE #balance SET code1 = code2, code2 = code3, code3 = code4, code4 = NULL WHERE code1 IS NULL
UPDATE #balance SET code1 = code2, code2 = code3, code3 = code4, code4 = NULL WHERE code1 IS NULL
UPDATE #balance SET code1 = SUBSTRING(code1, @startpos1, @lencod_lev1)
UPDATE #balance SET code2 = SUBSTRING(code2, @startpos2, @lencod_lev2)
UPDATE #balance SET code3 = SUBSTRING(code3, @startpos3, @lencod_lev3)
UPDATE #balance SET code4 = SUBSTRING(code4, @startpos4, @lencod_lev4)
UPDATE #balance SET order1 = order2, order2 = order3, order3 = order4, order4 = NULL WHERE order1 IS NULL
UPDATE #balance SET order1 = order2, order2 = order3, order3 = order4, order4 = NULL WHERE order1 IS NULL
UPDATE #balance SET order1 = order2, order2 = order3, order3 = order4, order4 = NULL WHERE order1 IS NULL
UPDATE #balance SET order1 = order2, order2 = order3, order3 = order4, order4 = NULL WHERE order1 IS NULL
UPDATE #balance SET order1 = SUBSTRING(order1, @startpos1, @lencod_lev1)
UPDATE #balance SET order2 = SUBSTRING(order2, @startpos2, @lencod_lev2)
UPDATE #balance SET order3 = SUBSTRING(order3, @startpos3, @lencod_lev3)
UPDATE #balance SET order4 = SUBSTRING(order4, @startpos4, @lencod_lev4)
CREATE TABLE #mov_finphase_C (idfin int, totuniv decimal(19,2),totinterni decimal(19,2),totdiretti decimal(19,2))
CREATE TABLE #var_finphase_C (idfin int, totuniv decimal(19,2),totinterni decimal(19,2),totdiretti decimal(19,2))
CREATE TABLE #mov_finphase_R (idfin int, totuniv decimal(19,2),totinterni decimal(19,2),totdiretti decimal(19,2))
CREATE TABLE #var_finphase_R (idfin int, totuniv decimal(19,2),totinterni decimal(19,2),totdiretti decimal(19,2))
CREATE TABLE #mov_maxphase_C (idfin int, totuniv decimal(19,2),totinterni decimal(19,2),totdiretti decimal(19,2))
CREATE TABLE #var_maxphase_C (idfin int, totuniv decimal(19,2),totinterni decimal(19,2),totdiretti decimal(19,2))
CREATE TABLE #mov_maxphase_R (idfin int, totuniv decimal(19,2),totinterni decimal(19,2),totdiretti decimal(19,2))
CREATE TABLE #var_maxphase_R (idfin int, totuniv decimal(19,2),totinterni decimal(19,2),totdiretti decimal(19,2))
CREATE TABLE #ava_finphase_C (idfin int, amount decimal(19,2))
CREATE TABLE #ava_finphase_R (idfin int, amount decimal(19,2))
IF @finpart = 'E'
BEGIN
	INSERT INTO #mov_finphase_C
	(
		idfin,
		totuniv,
		totinterni,
		totdiretti
	)
	SELECT
		ISNULL(FLK.idparent,IY.idfin),
		ISNULL(SUM(
			case 
				when R.idcentralizedcategory ='A' then (IY.amount)  
				else 0	
			end),0),
		ISNULL(SUM(
			case 
				when (R.idcentralizedcategory = 'U' and R.idreg <> @idregauto) then (IY.amount)
				else 0	
			end),0),
		ISNULL(SUM(
			case 
				when ((isnull(R.idcentralizedcategory,'X') NOT IN ('A','U')) 
					  or
					  (R.idcentralizedcategory = 'U' and R.idreg = @idregauto)
					 )
				then (IY.amount)
				else 0	
			end),0)
	FROM income I
	JOIN incomeyear IY
		ON IY.idinc = I.idinc
	JOIN registry R 
		ON I.idreg = R.idreg
	JOIN incometotal IT
		ON IT.idinc = IY.idinc
		AND IT.ayear = IY.ayear
	LEFT OUTER JOIN finlink FLK
		ON FLK.idchild = IY.idfin AND FLK.nlevel = @levelusable
	WHERE I.adate <= @date
		AND IY.ayear = @ayear
		AND ( (IT.flag & 1) =0)-- Competenza
		AND I.nphase = @registryphase
	GROUP BY ISNULL(FLK.idparent,IY.idfin)
	INSERT INTO #var_finphase_C
	(
		idfin,
		totuniv,
		totinterni,
		totdiretti
	)
	SELECT 
		ISNULL(FLK.idparent,IY.idfin),
		ISNULL(SUM(
			case 
				when R.idcentralizedcategory ='A' then (IV.amount)  
				else 0	
			end),0),
		ISNULL(SUM(
			case 
				when (R.idcentralizedcategory = 'U' and R.idreg <> @idregauto) then (IV.amount)
				else 0	
			end),0),
		ISNULL(SUM(
			case 
				when ((isnull(R.idcentralizedcategory,'X') NOT IN ('A','U')) 
					  or
					  (R.idcentralizedcategory = 'U' and R.idreg = @idregauto)
					 )
			    then (IV.amount)
				else 0	
			end),0)	
	FROM incomevar IV
	JOIN incomeyear IY
		ON IY.idinc = IV.idinc
	JOIN income I
		ON  I.idinc = IY.idinc
	JOIN registry R 
		ON I.idreg = R.idreg
	JOIN incometotal IT
		ON IT.idinc = IY.idinc
		AND IT.ayear = IY.ayear
	LEFT OUTER JOIN finlink FLK
		ON FLK.idchild = IY.idfin AND FLK.nlevel = @levelusable
	WHERE IV.yvar = @ayear
		AND IY.ayear = @ayear
		AND ( (IT.flag & 1) =0)-- Competenza
		AND I.nphase = @registryphase
		AND IV.adate <= @date 
	GROUP BY ISNULL(FLK.idparent,IY.idfin)
	INSERT INTO #mov_finphase_R
	(
		idfin,
		totuniv,
		totinterni,
		totdiretti
	)
	SELECT
		ISNULL(FLK.idparent,IY.idfin),
		ISNULL(SUM(
			case 
				when R.idcentralizedcategory ='A' then (IY.amount)  
				else 0	
			end),0),
		ISNULL(SUM(
			case 
				when  (R.idcentralizedcategory = 'U' and R.idreg <> @idregauto) then (IY.amount)
				else 0	
			end),0),
		ISNULL(SUM(
			case 
				when ((isnull(R.idcentralizedcategory,'X') NOT IN ('A','U')) 
					  or
					  (R.idcentralizedcategory = 'U' and R.idreg = @idregauto)
					 ) 
				then (IY.amount)
				else 0	
			end),0)
	FROM incomeyear IY
	JOIN income I
		ON I.idinc = IY.idinc
	JOIN registry R 
		ON I.idreg = R.idreg
	JOIN incometotal IT
		ON IT.idinc = IY.idinc
		AND IT.ayear = IY.ayear
	LEFT OUTER JOIN finlink FLK
		ON FLK.idchild = IY.idfin AND FLK.nlevel = @levelusable
	WHERE IY.ayear = @ayear
		AND ( (IT.flag & 1) = 1)-- Residuo
		AND I.nphase = @registryphase
		AND I.adate <= @date
	GROUP BY ISNULL(FLK.idparent,IY.idfin)
	
	INSERT INTO #var_finphase_R
	(
		idfin,
		totuniv,
		totinterni,
		totdiretti
	)
	SELECT 
		ISNULL(FLK.idparent,IY.idfin),
		ISNULL(SUM(
			case 
				when R.idcentralizedcategory ='A' then (IV.amount)  
				else 0	
			end),0),
		ISNULL(SUM(
			case 
				when (R.idcentralizedcategory = 'U' and R.idreg <> @idregauto) then (IV.amount)
				else 0	
			end),0),
		ISNULL(SUM(
			case 
				when ((isnull(R.idcentralizedcategory,'X') NOT IN ('A','U')) 
					  or
					  (R.idcentralizedcategory = 'U' and R.idreg = @idregauto)
					 )
				then (IV.amount)
				else 0	
			end),0)	
	FROM incomevar IV
	JOIN incomeyear IY
		ON IY.idinc = IV.idinc
	JOIN income I
		ON I.idinc = IY.idinc
	JOIN registry R 
		ON I.idreg = R.idreg
	JOIN incometotal IT
		ON IT.idinc = IY.idinc
		AND IT.ayear = IY.ayear
	LEFT OUTER JOIN finlink FLK
		ON FLK.idchild = IY.idfin AND FLK.nlevel = @levelusable
	WHERE IV.yvar = @ayear
		AND IY.ayear = @ayear
		AND ( (IT.flag & 1) = 1)-- Residuo
		AND I.nphase = @registryphase
		AND IV.adate <= @date
	GROUP BY ISNULL(FLK.idparent,IY.idfin)
	-- Caso in cui la fase bilancio e la fase anagrafica sono differenti
	IF (@finphase <> @registryphase)
	BEGIN
		INSERT INTO #ava_finphase_C (idfin, amount)
		SELECT
			ISNULL(FLK.idparent,IY.idfin),
			ISNULL(SUM(IY.amount),0)
		FROM income I
		JOIN incomeyear IY
			ON IY.idinc = I.idinc
		JOIN incometotal IT
			ON IT.idinc = IY.idinc
			AND IT.ayear = IY.ayear
		LEFT OUTER JOIN finlink FLK
			ON FLK.idchild = IY.idfin AND FLK.nlevel = @levelusable
		WHERE I.adate <= @date
			AND IY.ayear = @ayear
			AND ( (IT.flag & 1) = 0)
			AND I.nphase = @finphase
		GROUP BY ISNULL(FLK.idparent,IY.idfin)
		INSERT INTO #ava_finphase_C (idfin, amount)
		SELECT
			ISNULL(FLK.idparent,IY.idfin),
			ISNULL(SUM(IV.amount), 0)
		FROM income I
		JOIN incomevar IV
			ON IV.idinc = I.idinc
		JOIN incomeyear IY
			ON IY.idinc = I.idinc
		JOIN incometotal IT
			ON IT.idinc = IY.idinc
			AND IT.ayear = IY.ayear
		LEFT OUTER JOIN finlink FLK
			ON FLK.idchild = IY.idfin AND FLK.nlevel = @levelusable
		WHERE IV.adate <= @date
			AND IY.ayear = @ayear
			AND IV.yvar = @ayear
			AND ( (IT.flag & 1) = 0)
			AND I.nphase = @finphase
		GROUP BY ISNULL(FLK.idparent,IY.idfin)
		INSERT INTO #ava_finphase_C (idfin, amount)
		SELECT
			ISNULL(FLK.idparent,IY.idfin),
			- ISNULL(SUM(IY.amount), 0)
		FROM income I
		JOIN incomeyear IY
			ON IY.idinc = I.idinc
		JOIN registry R 
			ON I.idreg = R.idreg
		JOIN incometotal IT
			ON IT.idinc = IY.idinc
			AND IT.ayear = IY.ayear
		LEFT OUTER JOIN finlink FLK
			ON FLK.idchild = IY.idfin AND FLK.nlevel = @levelusable
		WHERE I.adate <= @date
			AND IY.ayear = @ayear
			AND ( (IT.flag & 1) = 0)-- Competenza
			AND I.nphase = @registryphase
		GROUP BY ISNULL(FLK.idparent,IY.idfin)
		INSERT INTO #ava_finphase_C (idfin, amount)
		SELECT 
			ISNULL(FLK.idparent,IY.idfin),
			- ISNULL(SUM(IV.amount), 0)
		FROM incomevar IV
		JOIN incomeyear IY
			ON IY.idinc = IV.idinc
		JOIN income I
			ON  I.idinc = IY.idinc
		JOIN registry R 
			ON I.idreg = R.idreg
		JOIN incometotal IT
			ON IT.idinc = IY.idinc
			AND IT.ayear = IY.ayear
		LEFT OUTER JOIN finlink FLK
			ON FLK.idchild = IY.idfin AND FLK.nlevel = @levelusable
		WHERE IV.yvar = @ayear
			AND IY.ayear = @ayear
			AND ( (IT.flag & 1) = 0)-- Competenza
			AND I.nphase = @registryphase
			AND IV.adate <= @date 
		GROUP BY ISNULL(FLK.idparent,IY.idfin)
		INSERT INTO #ava_finphase_R (idfin, amount)
		SELECT
			ISNULL(FLK.idparent,IY.idfin),
			ISNULL(SUM(IY.amount),0)
		FROM income I
		JOIN incomeyear IY
			ON IY.idinc = I.idinc
		JOIN incometotal IT
			ON IT.idinc = IY.idinc
			AND IT.ayear = IY.ayear
		LEFT OUTER JOIN finlink FLK
			ON FLK.idchild = IY.idfin AND FLK.nlevel = @levelusable
		WHERE I.adate <= @date
			AND IY.ayear = @ayear
			AND ( (IT.flag & 1) <> 0)
			AND I.nphase = @finphase
		GROUP BY ISNULL(FLK.idparent,IY.idfin)
		INSERT INTO #ava_finphase_R (idfin, amount)
		SELECT
			ISNULL(FLK.idparent,IY.idfin),
			ISNULL(SUM(IV.amount), 0)
		FROM income I
		JOIN incomevar IV
			ON IV.idinc = I.idinc
		JOIN incomeyear IY
			ON IY.idinc = I.idinc
		JOIN incometotal IT
			ON IT.idinc = IY.idinc
			AND IT.ayear = IY.ayear
		LEFT OUTER JOIN finlink FLK
			ON FLK.idchild = IY.idfin AND FLK.nlevel = @levelusable
		WHERE IV.adate <= @date
			AND IY.ayear = @ayear
			AND IV.yvar = @ayear
			AND ( (IT.flag & 1) <> 0)
			AND I.nphase = @finphase
		GROUP BY ISNULL(FLK.idparent,IY.idfin)
		INSERT INTO #ava_finphase_R (idfin, amount)
		SELECT
			ISNULL(FLK.idparent,IY.idfin),
			- ISNULL(SUM(IY.amount), 0)
		FROM income I
		JOIN incomeyear IY
			ON IY.idinc = I.idinc
		JOIN registry R 
			ON I.idreg = R.idreg
		JOIN incometotal IT
			ON IT.idinc = IY.idinc
			AND IT.ayear = IY.ayear
		LEFT OUTER JOIN finlink FLK
			ON FLK.idchild = IY.idfin AND FLK.nlevel = @levelusable
		WHERE I.adate <= @date
			AND IY.ayear = @ayear
			AND ( (IT.flag & 1) <> 0)-- Residuo
			AND I.nphase = @registryphase
		GROUP BY ISNULL(FLK.idparent,IY.idfin)
		INSERT INTO #ava_finphase_R (idfin, amount)
		SELECT 
			ISNULL(FLK.idparent,IY.idfin),
			- ISNULL(SUM(IV.amount), 0)
		FROM incomevar IV
		JOIN incomeyear IY
			ON IY.idinc = IV.idinc
		JOIN income I
			ON  I.idinc = IY.idinc
		JOIN registry R 
			ON I.idreg = R.idreg
		JOIN incometotal IT
			ON IT.idinc = IY.idinc
			AND IT.ayear = IY.ayear
		LEFT OUTER JOIN finlink FLK
			ON FLK.idchild = IY.idfin AND FLK.nlevel = @levelusable
		WHERE IV.adate <= @date
			AND IV.yvar = @ayear
			AND IY.ayear = @ayear
			AND ( (IT.flag & 1) <> 0)-- Residuo
			AND I.nphase = @registryphase
		GROUP BY ISNULL(FLK.idparent,IY.idfin)
	END
	INSERT INTO #mov_maxphase_C
	(
		idfin,
		totuniv,
		totinterni,
		totdiretti
	)
	SELECT
		ISNULL(FLK.idparent,HPV.idfin),
		ISNULL(SUM(
			case 
				when R.idcentralizedcategory ='A' then (HPV.amount)  
				else 0	
			end),0),
		ISNULL(SUM(
			case 
				when (R.idcentralizedcategory = 'U' and R.idreg <> @idregauto) then (HPV.amount)
				else 0	
			end),0),
		ISNULL(SUM(
			case 
				when ((isnull(R.idcentralizedcategory,'X') NOT IN ('A','U')) 
					  or
					  (R.idcentralizedcategory = 'U' and R.idreg = @idregauto)
					 ) 
				then (HPV.amount)
				else 0	
			end),0)	
	FROM historyproceedsview HPV
	JOIN registry R 
		ON HPV.idreg = R.idreg
	LEFT OUTER JOIN finlink FLK
		ON FLK.idchild = HPV.idfin AND FLK.nlevel = @levelusable
	WHERE HPV.competencydate <= @date
		AND ( (HPV.totflag & 1) = 0)--Competenza
		AND HPV.ymov = @ayear
	GROUP BY ISNULL(FLK.idparent,HPV.idfin)
	INSERT INTO #mov_maxphase_R
	(
		idfin,
		totuniv,
		totinterni,
		totdiretti
	)
	SELECT
		ISNULL(FLK.idparent,HPV.idfin), 
		ISNULL(SUM(
			case 
				when R.idcentralizedcategory ='A' then (HPV.amount)  
				else 0	
			end),0),
		ISNULL(SUM(
			case 
				when (R.idcentralizedcategory = 'U' and R.idreg <> @idregauto) then (HPV.amount)
				else 0	
			end),0),
		ISNULL(SUM(
			case 
				when ((isnull(R.idcentralizedcategory,'X') NOT IN ('A','U')) 
					  or
					  (R.idcentralizedcategory = 'U' and R.idreg = @idregauto)
					 )
				then (HPV.amount)
				else 0	
			end),0)	
	FROM historyproceedsview HPV
	JOIN registry R 
		ON HPV.idreg = R.idreg
	LEFT OUTER JOIN finlink FLK
		ON FLK.idchild = HPV.idfin AND FLK.nlevel = @levelusable
	WHERE HPV.competencydate <= @date
		AND ( (HPV.totflag & 1) = 1)-- Residuo
		AND HPV.ymov = @ayear
	GROUP BY ISNULL(FLK.idparent,HPV.idfin) 
	IF (@cashvaliditykind <> 4)
	BEGIN
		INSERT INTO #var_maxphase_C
		(
			idfin,
			totuniv,
			totinterni,
			totdiretti
		)
		SELECT 
			ISNULL(FLK.idparent,HPV.idfin),
			ISNULL(SUM(
				case 
					when R.idcentralizedcategory ='A' then (IV.amount)  
					else 0	
				end),0),
			ISNULL(SUM(
				case 
					when (R.idcentralizedcategory = 'U' and R.idreg <> @idregauto) then (IV.amount)
					else 0	
				end),0),
			ISNULL(SUM(
				case 
					when ((isnull(R.idcentralizedcategory,'X') NOT IN ('A','U')) 
					  or
					  (R.idcentralizedcategory = 'U' and R.idreg = @idregauto)
					 )
					then (IV.amount)
					else 0	
				end),0)	
		FROM incomevar IV
		JOIN income I
			ON I.idinc = IV.idinc
		JOIN registry R 
			ON I.idreg = R.idreg
		JOIN historyproceedsview HPV
			ON HPV.idinc = IV.idinc
		LEFT OUTER JOIN finlink FLK
			ON FLK.idchild = HPV.idfin AND FLK.nlevel = @levelusable
		WHERE IV.yvar = @ayear
			AND IV.adate <= @date
			AND ( (HPV.totflag & 1) = 0)-- Competenza
			AND HPV.competencydate <= @date AND HPV.ymov = @ayear
		GROUP BY ISNULL(FLK.idparent,HPV.idfin) 
	
		INSERT INTO #var_maxphase_R
		(
			idfin,
			totuniv,
			totinterni,
			totdiretti
		)
		SELECT 
			ISNULL(FLK.idparent,HPV.idfin),
			ISNULL(SUM(
				case 
					when R.idcentralizedcategory ='A' then (IV.amount)  
					else 0	
				end),0),
			ISNULL(SUM(
				case 
					when (R.idcentralizedcategory = 'U' and R.idreg <> @idregauto) then (IV.amount)
					else 0	
				end),0),
			ISNULL(SUM(
				case 
					when ((isnull(R.idcentralizedcategory,'X') NOT IN ('A','U')) 
					  or
					  (R.idcentralizedcategory = 'U' and R.idreg = @idregauto)
					 )
					then (IV.amount)
					else 0	
				end),0)	
		FROM incomevar IV
		JOIN income I
			ON I.idinc = IV.idinc
		JOIN registry R 
			ON I.idreg = R.idreg
		JOIN historyproceedsview HPV
			ON HPV.idinc = IV.idinc
		LEFT OUTER JOIN finlink FLK
			ON FLK.idchild = HPV.idfin AND FLK.nlevel = @levelusable
		WHERE IV.yvar = @ayear
			AND ( (HPV.totflag & 1) = 1)
			AND IV.adate <= @date
			AND HPV.competencydate <= @date AND HPV.ymov = @ayear
		GROUP BY ISNULL(FLK.idparent,HPV.idfin)
	END
END
IF @finpart = 'S'
BEGIN
	INSERT INTO #mov_finphase_C
	(
		idfin,
		totuniv,
		totinterni,
		totdiretti
	)
	SELECT
		ISNULL(FLK.idparent,EY.idfin),
		ISNULL(SUM(
			case 
				when R.idcentralizedcategory ='A' then (EY.amount)  
				else 0	
			end),0),
		ISNULL(SUM(
			case 
				when (R.idcentralizedcategory = 'U' and R.idreg <> @idregauto) then (EY.amount)
				else 0	
			end),0),
		ISNULL(SUM(
			case 
				when ((isnull(R.idcentralizedcategory,'X') NOT IN ('A','U')) 
					  or
					  (R.idcentralizedcategory = 'U' and R.idreg = @idregauto)
					 ) 
				then (EY.amount)
				else 0	
			end),0)
	FROM expense E
	JOIN expenseyear EY
		ON EY.idexp = E.idexp
	JOIN registry R
		ON E.idreg = R.idreg
	JOIN expensetotal ET
		ON ET.idexp = EY.idexp
		AND ET.ayear = EY.ayear
	LEFT OUTER JOIN finlink FLK
		ON FLK.idchild = EY.idfin AND FLK.nlevel = @levelusable
	WHERE E.adate <= @date
		AND EY.ayear = @ayear
		AND ( (ET.flag & 1) = 0) -- Competenza
		AND E.nphase = @registryphase
	GROUP BY ISNULL(FLK.idparent,EY.idfin)
	
	INSERT INTO #var_finphase_C
	(
		idfin,
		totuniv,
		totinterni,
		totdiretti
	)
	SELECT 
		ISNULL(FLK.idparent,EY.idfin),
		ISNULL(SUM(
			case 
				when R.idcentralizedcategory ='A' then (EV.amount)  
				else 0	
			end),0),
		ISNULL(SUM(
			case 
				when (R.idcentralizedcategory = 'U' and R.idreg <> @idregauto) then (EV.amount)
				else 0	
			end),0),
		ISNULL(SUM(
			case 
				when ((isnull(R.idcentralizedcategory,'X') NOT IN ('A','U')) 
					  or
					  (R.idcentralizedcategory = 'U' and R.idreg = @idregauto)
					 )
				then (EV.amount)
				else 0	
			end),0)
	FROM expensevar EV
	JOIN expenseyear EY
		ON EY.idexp = EV.idexp
	JOIN expense E
		ON E.idexp = EY.idexp
	JOIN registry R
		ON E.idreg = R.idreg
	JOIN expensetotal ET
		ON ET.idexp = EY.idexp
		AND ET.ayear = EY.ayear
	LEFT OUTER JOIN finlink FLK
		ON FLK.idchild = EY.idfin AND FLK.nlevel = @levelusable
	WHERE EV.yvar = @ayear
		AND EY.ayear = @ayear
		AND ( (ET.flag & 1) = 0) -- Competenza
		AND E.nphase = @registryphase
		AND EV.adate <= @date 
	GROUP BY ISNULL(FLK.idparent,EY.idfin) 
	INSERT INTO #mov_finphase_R
	(
		idfin,
		totuniv,
		totinterni,
		totdiretti
	)
	SELECT
		ISNULL(FLK.idparent,EY.idfin),
		ISNULL(SUM(
			case 
				when R.idcentralizedcategory ='A' then (EY.amount)  
				else 0	
			end),0),
		ISNULL(SUM(
			case 
				when (R.idcentralizedcategory = 'U' and R.idreg <> @idregauto) then (EY.amount)
				else 0	
			end),0),
		ISNULL(SUM(
			case 
				when ((isnull(R.idcentralizedcategory,'X') NOT IN ('A','U')) 
					  or
					  (R.idcentralizedcategory = 'U' and R.idreg = @idregauto)
					 ) 
				then (EY.amount)
				else 0	
			end),0)
	FROM expenseyear EY
	JOIN expense E
		ON E.idexp = EY.idexp
	JOIN registry R
		ON E.idreg = R.idreg
	JOIN expensetotal ET
		ON ET.idexp = EY.idexp
		AND ET.ayear = EY.ayear
	LEFT OUTER JOIN finlink FLK
		ON FLK.idchild = EY.idfin AND FLK.nlevel = @levelusable
	WHERE EY.ayear = @ayear
		AND ( (ET.flag & 1) = 1) -- Residuo
		AND E.nphase = @registryphase
		AND E.adate <= @date 
	GROUP BY ISNULL(FLK.idparent,EY.idfin)
	
	INSERT INTO #var_finphase_R
	(
		idfin,
		totuniv,
		totinterni,
		totdiretti
	)
	SELECT 
		ISNULL(FLK.idparent,EY.idfin),
		ISNULL(SUM(
			case 
				when R.idcentralizedcategory ='A' then (EV.amount)  
				else 0	
			end),0),
		ISNULL(SUM(
			case 
				when (R.idcentralizedcategory = 'U' and R.idreg <> @idregauto) then (EV.amount)
				else 0	
			end),0),
		ISNULL(SUM(
			case 
				when ((isnull(R.idcentralizedcategory,'X') NOT IN ('A','U')) 
					  or
					  (R.idcentralizedcategory = 'U' and R.idreg = @idregauto)
					 ) 
				then (EV.amount)
				else 0	
			end),0)	
	FROM expensevar EV
	JOIN expenseyear EY
		ON EY.idexp = EV.idexp
	JOIN expense E
		ON E.idexp = EY.idexp
	JOIN registry R 
		ON E.idreg = R.idreg
	JOIN expensetotal ET
		ON ET.idexp = EY.idexp
		AND ET.ayear = EY.ayear
	LEFT OUTER JOIN finlink FLK
		ON FLK.idchild = EY.idfin AND FLK.nlevel = @levelusable
	WHERE EV.yvar = @ayear
		AND EY.ayear = @ayear
		AND ( (ET.flag & 1) = 1) -- Residuo
		AND E.nphase = @registryphase
		AND EV.adate <= @date 
	GROUP BY ISNULL(FLK.idparent,EY.idfin)
	-- Caso in cui la fase bilancio e la fase anagrafica sono differenti
	IF (@finphase <> @registryphase)
	BEGIN
		INSERT INTO #ava_finphase_C (idfin, amount)
		SELECT
			ISNULL(FLK.idparent,IY.idfin),
			ISNULL(SUM(IY.amount),0)
		FROM expense I
		JOIN expenseyear IY
			ON IY.idexp = I.idexp
		JOIN expensetotal IT
			ON IT.idexp = IY.idexp
			AND IT.ayear = IY.ayear
		LEFT OUTER JOIN finlink FLK
			ON FLK.idchild = IY.idfin AND FLK.nlevel = @levelusable
		WHERE I.adate <= @date
			AND IY.ayear = @ayear
			AND ( (IT.flag & 1) = 0)
			AND I.nphase = @finphase
		GROUP BY ISNULL(FLK.idparent,IY.idfin)
		INSERT INTO #ava_finphase_C (idfin, amount)
		SELECT
			ISNULL(FLK.idparent,IY.idfin),
			ISNULL(SUM(IV.amount), 0)
		FROM expense I
		JOIN expensevar IV
			ON IV.idexp = I.idexp
		JOIN expenseyear IY
			ON IY.idexp = I.idexp
		JOIN expensetotal IT
			ON IT.idexp = IY.idexp
			AND IT.ayear = IY.ayear
		LEFT OUTER JOIN finlink FLK
			ON FLK.idchild = IY.idfin AND FLK.nlevel = @levelusable
		WHERE IV.adate <= @date
			AND IY.ayear = @ayear
			AND IV.yvar = @ayear
			AND ( (IT.flag & 1) = 0)
			AND I.nphase = @finphase
		GROUP BY ISNULL(FLK.idparent,IY.idfin)
		INSERT INTO #ava_finphase_C (idfin, amount)
		SELECT
			ISNULL(FLK.idparent,IY.idfin),
			- ISNULL(SUM(IY.amount), 0)
		FROM expense I
		JOIN expenseyear IY
			ON IY.idexp = I.idexp
		JOIN registry R 
			ON I.idreg = R.idreg
		JOIN expensetotal IT
			ON IT.idexp = IY.idexp
			AND IT.ayear = IY.ayear
		LEFT OUTER JOIN finlink FLK
			ON FLK.idchild = IY.idfin AND FLK.nlevel = @levelusable
		WHERE I.adate <= @date
			AND IY.ayear = @ayear
			AND ( (IT.flag & 1) = 0)-- Competenza
			AND I.nphase = @registryphase
		GROUP BY ISNULL(FLK.idparent,IY.idfin)
		INSERT INTO #ava_finphase_C (idfin, amount)
		SELECT 
			ISNULL(FLK.idparent,IY.idfin),
			- ISNULL(SUM(IV.amount), 0)
		FROM expensevar IV
		JOIN expenseyear IY
			ON IY.idexp = IV.idexp
		JOIN expense I
			ON  I.idexp = IY.idexp
		JOIN registry R 
			ON I.idreg = R.idreg
		JOIN expensetotal IT
			ON IT.idexp = IY.idexp
			AND IT.ayear = IY.ayear
		LEFT OUTER JOIN finlink FLK
			ON FLK.idchild = IY.idfin AND FLK.nlevel = @levelusable
		WHERE IV.yvar = @ayear
			AND IY.ayear = @ayear
			AND ( (IT.flag & 1) = 0)-- Competenza
			AND I.nphase = @registryphase
			AND IV.adate <= @date 
		GROUP BY ISNULL(FLK.idparent,IY.idfin)
		INSERT INTO #ava_finphase_R (idfin, amount)
		SELECT
			ISNULL(FLK.idparent,IY.idfin),
			ISNULL(SUM(IY.amount),0)
		FROM expense I
		JOIN expenseyear IY
			ON IY.idexp = I.idexp
		JOIN expensetotal IT
			ON IT.idexp = IY.idexp
			AND IT.ayear = IY.ayear
		LEFT OUTER JOIN finlink FLK
			ON FLK.idchild = IY.idfin AND FLK.nlevel = @levelusable
		WHERE I.adate <= @date
			AND IY.ayear = @ayear
			AND ( (IT.flag & 1) <> 0)
			AND I.nphase = @finphase
		GROUP BY ISNULL(FLK.idparent,IY.idfin)
		INSERT INTO #ava_finphase_R (idfin, amount)
		SELECT
			ISNULL(FLK.idparent,IY.idfin),
			ISNULL(SUM(IV.amount), 0)
		FROM expense I
		JOIN expensevar IV
			ON IV.idexp = I.idexp
		JOIN expenseyear IY
			ON IY.idexp = I.idexp
		JOIN expensetotal IT
			ON IT.idexp = IY.idexp
			AND IT.ayear = IY.ayear
		LEFT OUTER JOIN finlink FLK
			ON FLK.idchild = IY.idfin AND FLK.nlevel = @levelusable
		WHERE IV.adate <= @date
			AND IY.ayear = @ayear
			AND IV.yvar = @ayear
			AND ( (IT.flag & 1) <> 0)
			AND I.nphase = @finphase
		GROUP BY ISNULL(FLK.idparent,IY.idfin)
		INSERT INTO #ava_finphase_R (idfin, amount)
		SELECT
			ISNULL(FLK.idparent,IY.idfin),
			- ISNULL(SUM(IY.amount), 0)
		FROM expense I
		JOIN expenseyear IY
			ON IY.idexp = I.idexp
		JOIN registry R 
			ON I.idreg = R.idreg
		JOIN expensetotal IT
			ON IT.idexp = IY.idexp
			AND IT.ayear = IY.ayear
		LEFT OUTER JOIN finlink FLK
			ON FLK.idchild = IY.idfin AND FLK.nlevel = @levelusable
		WHERE I.adate <= @date
			AND IY.ayear = @ayear
			AND ( (IT.flag & 1) <> 0)-- Residuo
			AND I.nphase = @registryphase
		GROUP BY ISNULL(FLK.idparent,IY.idfin)
		INSERT INTO #ava_finphase_R (idfin, amount)
		SELECT 
			ISNULL(FLK.idparent,IY.idfin),
			- ISNULL(SUM(IV.amount), 0)
		FROM expensevar IV
		JOIN expenseyear IY
			ON IY.idexp = IV.idexp
		JOIN expense I
			ON  I.idexp = IY.idexp
		JOIN registry R 
			ON I.idreg = R.idreg
		JOIN expensetotal IT
			ON IT.idexp = IY.idexp
			AND IT.ayear = IY.ayear
		LEFT OUTER JOIN finlink FLK
			ON FLK.idchild = IY.idfin AND FLK.nlevel = @levelusable
		WHERE IV.adate <= @date
			AND IV.yvar = @ayear
			AND IY.ayear = @ayear
			AND ( (IT.flag & 1) <> 0)-- Residuo
			AND I.nphase = @registryphase
		GROUP BY ISNULL(FLK.idparent,IY.idfin)
	END
	INSERT INTO #mov_maxphase_C
	(
		idfin,
		totuniv,
		totinterni,
		totdiretti
	)
	SELECT
		ISNULL(FLK.idparent,HPV.idfin), 
		ISNULL(SUM(
			case 
				when R.idcentralizedcategory ='A' then (HPV.amount)  
				else 0	
			end),0),
		ISNULL(SUM(
			case 
				when (R.idcentralizedcategory = 'U' and R.idreg <> @idregauto) then (HPV.amount)
				else 0	
			end),0),
		ISNULL(SUM(
			case 
				when ((isnull(R.idcentralizedcategory,'X') NOT IN ('A','U')) 
					  or
					  (R.idcentralizedcategory = 'U' and R.idreg = @idregauto)
					 )
				then (HPV.amount)
				else 0	
			end),0)	
	FROM historypaymentview HPV
	JOIN registry R 
		ON HPV.idreg = R.idreg
	LEFT OUTER JOIN finlink FLK
		ON FLK.idchild = HPV.idfin AND FLK.nlevel = @levelusable
	WHERE HPV.competencydate <= @date
		AND ( (HPV.totflag & 1) = 0)-- Competenza
		AND HPV.ymov = @ayear
	GROUP BY ISNULL(FLK.idparent,HPV.idfin) 
	INSERT INTO #mov_maxphase_R
	(
		idfin,
		totuniv,
		totinterni,
		totdiretti
	)
	SELECT
		ISNULL(FLK.idparent,HPV.idfin),
		ISNULL(SUM(
			case 
				when R.idcentralizedcategory ='A' then (HPV.amount)  
				else 0	
			end),0),
		ISNULL(SUM(
			case 
				when (R.idcentralizedcategory = 'U' and R.idreg <> @idregauto)  then (HPV.amount)
				else 0	
			end),0),
		ISNULL(SUM(
			case 
				when ((isnull(R.idcentralizedcategory,'X') NOT IN ('A','U')) 
					  or
					  (R.idcentralizedcategory = 'U' and R.idreg = @idregauto)
					 )
				then (HPV.amount)
				else 0	
			end),0)	
	FROM historypaymentview HPV
	JOIN registry R 
		ON HPV.idreg = R.idreg
	LEFT OUTER JOIN finlink FLK
		ON FLK.idchild = HPV.idfin AND FLK.nlevel = @levelusable
	WHERE HPV.competencydate <= @date
		AND ( (HPV.totflag & 1) = 1)-- Residuo
		AND HPV.ymov = @ayear
	GROUP BY ISNULL(FLK.idparent,HPV.idfin)
	IF (@cashvaliditykind <> 4)
	BEGIN
		INSERT INTO #var_maxphase_C
		(
			idfin,
			totuniv,
			totinterni,
			totdiretti
		)
		SELECT 
			ISNULL(FLK.idparent,HPV.idfin),
			ISNULL(SUM(
				case 
					when R.idcentralizedcategory ='A' then (EV.amount)  
					else 0	
				end),0),
			ISNULL(SUM(
				case 
					when (R.idcentralizedcategory = 'U' and R.idreg <> @idregauto) then (EV.amount)
					else 0	
				end),0),
			ISNULL(SUM(
				case 
					when ((isnull(R.idcentralizedcategory,'X') NOT IN ('A','U')) 
					  or
					  (R.idcentralizedcategory = 'U' and R.idreg = @idregauto)
					 )
					then (EV.amount)
					else 0	
				end),0)	
		FROM expensevar EV
		JOIN expense E
			ON E.idexp = EV.idexp
		JOIN registry R 
			ON E.idreg = R.idreg
		JOIN historypaymentview HPV
			ON HPV.idexp = EV.idexp
		LEFT OUTER JOIN finlink FLK
			ON FLK.idchild = HPV.idfin AND FLK.nlevel = @levelusable
		WHERE EV.yvar = @ayear
			AND EV.adate <= @date
			AND HPV.competencydate <= @date AND HPV.ymov = @ayear
			AND ( (HPV.totflag & 1) = 0)--Competenza
		GROUP BY ISNULL(FLK.idparent,HPV.idfin)
	
		INSERT INTO #var_maxphase_R
		(
			idfin,
			totuniv,
			totinterni,
			totdiretti
		)
		SELECT 
			ISNULL(FLK.idparent,HPV.idfin),
			ISNULL(SUM(
				case 
					when R.idcentralizedcategory ='A' then (EV.amount)  
					else 0	
				end),0),
			ISNULL(SUM(
				case 
					when (R.idcentralizedcategory = 'U' and R.idreg <> @idregauto) then (EV.amount)
					else 0	
				end),0),
			ISNULL(SUM(
				case 
					when ((isnull(R.idcentralizedcategory,'X') NOT IN ('A','U')) 
					  or
					  (R.idcentralizedcategory = 'U' and R.idreg = @idregauto)
					 )
					then (EV.amount)
					else 0	
				end),0)	
		FROM expensevar EV
		JOIN expense E
			ON E.idexp = EV.idexp
		JOIN registry R 
			ON E.idreg = R.idreg
		JOIN historypaymentview HPV
			ON HPV.idexp = EV.idexp
		LEFT OUTER JOIN finlink FLK
			ON FLK.idchild = HPV.idfin AND FLK.nlevel = @levelusable
		WHERE EV.yvar = @ayear
			AND HPV.competencydate <= @date AND HPV.ymov = @ayear
			AND ( (HPV.totflag & 1) = 1)-- Residuo
			AND EV.adate <= @date
		GROUP BY ISNULL(FLK.idparent,HPV.idfin)
	END
END
