if object_id('[rpt_partitario_class_mov_anal]') is not null
	drop PROCEDURE [rpt_partitario_class_mov_anal]
go


CREATE    PROCEDURE [rpt_partitario_class_mov_anal]
	@ayear smallint,
	@idsorkind int,
	@codefin varchar(30),
	@start smalldatetime,
	@stop smalldatetime,
	@showupb char(1),
	@idupb varchar(36),
	@showchildupb char(1),
	@idman int
AS
BEGIN
--exec rpt_partitario_class_mov_anal 2006, 'MIUR', '',{ts '2006-01-01 00:00:00'}, {ts '2006-12-07 00:00:00'},'S','%','S',null
/* Versione 1.0.12 del 17/09/2007 ultima modifica: SARA */
DECLARE @maxphase tinyint
SET  @maxphase = (SELECT MAX(nphase) FROM expensephase)
DECLARE @movphase tinyint
SET  @movphase = (SELECT nphaseexpense
	FROM sortingkind 
	WHERE idsorkind = @idsorkind)

DECLARE @descfasemovimento varchar(30)
SET @descfasemovimento =  (SELECT  description
	FROM expensephase 
	WHERE nphase = @maxphase) 
	
DECLARE @flagvaliditadoc 	char(1)   	
SET @flagvaliditadoc = (SELECT cashvaliditykind
	FROM config
	WHERE ayear = @ayear)
DECLARE @desctipoclass varchar(35)
SET  @desctipoclass = (SELECT  description
	FROM sortingkind
	WHERE idsorkind = @idsorkind)
IF ISNULL(@codefin,'') = '' SET  @codefin = '%'
	
DECLARE @idupboriginal 	varchar(36)
SET @idupboriginal= @idupb
IF (@showchildupb = 'S') set @idupb=@idupb+'%' 
CREATE TABLE #sorted
(
	sortcode varchar(50), 
	idsor varchar(39),
	sorting varchar(200), 
	idexp int,
	adate smalldatetime,
	phasedescription varchar(35),
	ymov smallint,
	nmov integer,
	idreg integer,
	fintitle varchar(150),
	codefin varchar(50), 
	codeupb varchar(50),
	idupb varchar(36),
	upb varchar(150),
	idman int,
	description varchar(250),  
	curramount decimal(19,2),
	sortedamount decimal(19,2),
	nphase tinyint,
	nphaseclass tinyint,
	tothierarchy varchar (50)
)
		
	INSERT INTO #sorted
	(
		sortcode,
		idsor,
		sorting,
		idexp,
		adate,
		phasedescription,
		nphase,
		ymov,
		nmov,
		idreg,
		codefin,
		fintitle,
		idupb,
		codeupb,
		upb, 
		idman,
		description,
		curramount,
		sortedamount
	)
	SELECT
		sorting.sortcode,
		sorting.idsor,
		sorting.description,
		expense.idexp,
		expense.adate,
		expensephase.description,
		expense.nphase,
		expense.ymov,
		expense.nmov,
		expense.idreg,
		fin.codefin,
		fin.title,
		upb.idupb,
		upb.codeupb,
		upb.title, 
		finlast.idman,
		expense.description,
		expensetotal.curramount,
		SUM(expensesorted.amount)
	FROM expense
	JOIN expensetotal
		ON expensetotal.idexp = expense.idexp
	JOIN expenseyear
		ON expenseyear.idexp = expense.idexp
	JOIN expensesorted
		ON expensesorted.idexp = expense.idexp
	JOIN sorting
		ON sorting.idsor = expensesorted.idsor
	JOIN expensephase
		ON expensephase.nphase = expense.nphase
	LEFT OUTER JOIN upb 		
		ON upb.idupb = expenseyear.idupb
	LEFT OUTER JOIN fin
		ON fin.idfin = expenseyear.idfin
	LEFT OUTER JOIN finlast
		ON finlast.idfin = expenseyear.idfin
	WHERE expense.adate BETWEEN isnull(@start, {d '1900-01-01'}) AND isnull(@stop, {d '2079-06-06'})
		AND fin.codefin like @codefin AND (( fin.flag & 1)=1) 
		AND expensetotal.curramount <> 0
		AND (  (@idman is null) or (finlast.idman = @idman))	
		AND expensetotal.ayear = @ayear
		AND expenseyear.ayear = @ayear
		AND expense.nphase = @movphase
		AND sorting.idsorkind = @idsorkind
		AND expensesorted.ayear = @ayear
		AND ((expenseyear.idupb is null and @idupb='%') or (expenseyear.idupb like @idupb))	
	GROUP BY sorting.idsor,sorting.sortcode,sorting.description,
		expense.idexp,	expense.adate,	expensephase.description,
		expense.nphase,	expense.ymov,expense.nmov,expense.idreg,
		fin.codefin,fin.title,upb.idupb,
		upb.codeupb,upb.title, finlast.idman,expense.description,expensetotal.curramount
		
	IF @maxphase > @movphase
	BEGIN	
		INSERT INTO #sorted
		(
			sortcode,
			idsor,
			sorting,
			idexp,
			adate,
			phasedescription,
			nphase,
			ymov,
			nmov,
			idreg,
			codefin,
			fintitle,
			idupb,
			codeupb,
			upb, 
			idman,
			description,
			curramount,
			sortedamount
		)				
		SELECT 
			DISTINCT 
			#sorted.sortcode,
			#sorted.idsor,
			#sorted.sorting,
			expense.idexp,
			expense.adate,
			@descfasemovimento,
			expense.nphase,
			expense.ymov,
			expense.nmov,
			expense.idreg,
			#sorted.codefin,
			#sorted.fintitle,
			#sorted.idupb,
			#sorted.codeupb,
			#sorted.upb, 
			#sorted.idman,
			expense.description,
			expensetotal.curramount,
			expensetotal.curramount*#sorted.sortedamount/#sorted.curramount
		FROM #sorted
		JOIN expenselink
			ON #sorted.idexp = expenselink.idparent and expenselink.nlevel = @movphase
		JOIN expense
			ON expense.idexp = expenselink.idchild
		JOIN expensetotal
			ON expensetotal.idexp = expense.idexp
		WHERE expensetotal.ayear = @ayear
			AND expense.adate  BETWEEN isnull(@start, {d '1900-01-01'}) AND isnull(@stop, {d '2079-06-06'})
			AND expense.nphase = @maxphase
	END
			
	UPDATE #sorted
		SET description = description +  ISNULL(' - Mandato di pagamento n. '+CONVERT(varchar(6),
			(SELECT i.npay FROM  historypaymentview I
			WHERE i.idexp = #sorted.idexp)),'') + 
				ISNULL(' del '+CONVERT(varchar(10),
					(SELECT i.competencydate FROM  historypaymentview I
						WHERE i.idexp = #sorted.idexp),105),'')
	UPDATE #sorted SET nphaseclass = @movphase
UPDATE #sorted
SET sorting = 'NON CLASSIFICATO',
    sortcode = 'NON-C'
WHERE idsor IS NULL

IF (@showupb <>'S') AND (@idupboriginal <> '%' ) AND (@showchildupb = 'S')
		UPDATE #sorted SET  
			upb = (SELECT TOP 1 upb
				FROM #sorted
				WHERE idupb = @idupboriginal),
			idupb = @idupboriginal,
			codeupb =(SELECT TOP 1 codeupb
				FROM #sorted	
				WHERE idupb = @idupboriginal)
IF (@showupb <>'S') and (@idupboriginal = '%') 
			UPDATE #sorted SET  
			upb =  null,
			idupb = null,
			codeupb = null
-- costruisce la gerarchia del movimento per creare l'ordinamento 
UPDATE #sorted 
SET 
	tothierarchy = 
        Replicate(0,4-len(convert(varchar(4),isnull(E1.ymov,0))))+ convert(varchar(4),isnull(E1.ymov,0))+ '/' + 
        Replicate(0,6-len(convert(varchar(6),isnull(E1.nmov,0))))+ convert(varchar(6),isnull(E1.nmov,0))+ ' '+
        Replicate(0,4-len(convert(varchar(4),isnull(E2.ymov,0))))+ convert(varchar(4),isnull(E2.ymov,0))+ '/' + 
        Replicate(0,6-len(convert(varchar(6),isnull(E2.nmov,0))))+ convert(varchar(6),isnull(E2.nmov,0))+ ' '+
        Replicate(0,4-len(convert(varchar(4),isnull(E3.ymov,0))))+ convert(varchar(4),isnull(E3.ymov,0))+ '/' + 
        Replicate(0,6-len(convert(varchar(6),isnull(E3.nmov,0))))+ convert(varchar(6),isnull(E3.nmov,0))+ ' '+
        Replicate(0,4-len(convert(varchar(4),isnull(E4.ymov,0))))+ convert(varchar(4),isnull(E4.ymov,0))+ '/' + 
        Replicate(0,6-len(convert(varchar(6),isnull(E4.nmov,0))))+ convert(varchar(6),isnull(E4.nmov,0))
FROM expense
JOIN expenselink EL1
	ON EL1.idchild = expense.idexp  AND EL1.nlevel = 1
LEFT OUTER JOIN expenselink EL2
	ON EL2.idchild = expense.idexp  AND EL2.nlevel = 2
LEFT OUTER JOIN expenselink EL3
	ON EL3.idchild = expense.idexp  AND EL3.nlevel = 3
LEFT OUTER JOIN expenselink EL4
	ON EL4.idchild = expense.idexp  AND EL4.nlevel = 4
LEFT OUTER JOIN expense E1
	ON E1.idexp = EL1.idparent
LEFT OUTER JOIN expense E2
	ON E2.idexp = EL2.idparent
LEFT OUTER JOIN expense E4
	ON E4.idexp = EL4.idparent
LEFT OUTER JOIN expense E3
	ON E3.idexp = EL3.idparent
WHERE  EL1.idchild = #sorted.idexp
	SELECT 
		@idsorkind as 'idsorkind', 
      	       	@desctipoclass as 'descriptionsortingkind', 
       	       	#sorted.sortcode,
	       	#sorted.idsor,
	       	#sorted.sorting,
	      	#sorted.idexp,
		#sorted.adate,
		#sorted.phasedescription,
		#sorted.ymov,
		#sorted.nmov,
	       	registry.title as 'registry',
	      	#sorted.codefin,
	       	#sorted.fintitle,
		#sorted.idupb,
		#sorted.codeupb,
		#sorted.upb,
		manager.title as 'manager',
		#sorted.description,  
		#sorted.curramount,
		#sorted.sortedamount,
		#sorted.nphase,
		#sorted.nphaseclass
	FROM #sorted
	JOIN expenseyear
		ON expenseyear.idexp = #sorted.idexp
	LEFT OUTER JOIN registry
		ON registry.idreg = #sorted.idreg
	LEFT OUTER JOIN manager
		ON manager.idman = #sorted.idman
	WHERE expenseyear.ayear = @ayear
	ORDER BY codefin ASC, 
	#sorted.sortcode ASC, 
	#sorted.tothierarchy ASC,
	#sorted.adate ASC,
	#sorted.ymov ASC,
	#sorted.nmov ASC
END


GO

print '[rpt_partitario_class_mov_anal] OK'

GO
if object_id('[rpt_registroiva_sub_old]') is not null
	drop PROCEDURE [rpt_registroiva_sub_old]
go

CREATE    PROCEDURE [rpt_registroiva_sub_old]
	@idivaregisterkind int,
	@year int,
	@month int
AS BEGIN
	
	CREATE TABLE #invoice_finmov
	(
		idinvkind int,		
		yinv int,
		ninv int,
		flagmixed char(1),
		ivatotal decimal(19,2),
		ivagross decimal(19,2),
		ivaabatable decimal(19,2),
		ivaunabatable decimal(19,2),
		totivaunabatable decimal(19,2),
		currivaunabatable decimal(19,2),
		taxabletotal decimal(19,2),
		previvatotalpayed decimal(19,2),
		prevtotalpayed decimal(19,2),
		currivagrosspayed decimal(19,2),
		currivapayed decimal(19,2),
		currtotalpayed decimal(19,2),
		amountlinked decimal(19,2),
		movkind varchar(20),
		rapporto decimal(19,6),
		idmov int,
		nvar int,
		adate smalldatetime,
		movdescription varchar(50),
		movdate datetime
	)
	DECLARE @registerclass char(1)
	SELECT @registerclass = registerclass
	FROM ivaregisterkind
	WHERE idivaregisterkind = @idivaregisterkind
	IF @month IS NULL OR @month < 1
	BEGIN
		SET @month = 1
	END
	IF @month > 12
	BEGIN
		SET @month = 12
	END
	DECLARE @proratarate decimal(19,6)
	SELECT @proratarate = prorata
	FROM iva_prorata
	WHERE ayear = @year
	
	DECLARE @mixedrate decimal(19,6)	
	SELECT @mixedrate = mixed
	FROM iva_mixed
	WHERE ayear = @year
	-- Gestione IVA differita
	DECLARE @deferredexpensephase char(1)
	DECLARE @deferredincomephase char(1)
	SELECT  @deferredexpensephase = deferredexpensephase, 
		@deferredincomephase = deferredincomephase
	FROM config WHERE ayear = @year
	
	CREATE TABLE #invoice
	(
		idinvkind  int,		
		yinv int,
		ninv int,
		flagmixed char(1),
		ivatotal decimal(19,2),
		ivagross decimal(19,2),
		ivaabatable decimal(19,2),
		ivaunabatable decimal(19,2),
		totivaunabatable decimal(19,2),
		currivaunabatable decimal(19,2),
		prorataamount decimal(19,2),
		mixedamount decimal(19,2),
		taxabletotal decimal(19,2),
		amountlinked decimal(19,2),
		movkind varchar(20),
		idivakind  int,		
		adate smalldatetime,
		movdescription varchar(50),
		movdate datetime
	)
	IF (@registerclass = 'A')
	BEGIN
		-- Sezione 2.2. IVA Differita
		INSERT INTO #invoice_finmov (idinvkind, yinv, ninv, movkind, flagmixed, adate,
		ivatotal, taxabletotal, totivaunabatable, amountlinked, idmov, movdescription, movdate)
		(SELECT invoice.idinvkind,invoice.yinv,invoice.ninv,expenseinvoice.movkind, 
	   	CASE
			WHEN ivaregisterkind.flagactivity = 3  THEN 'S'
			ELSE 'N'
		END,	
		invoice.adate,
		totinvoiceview.ivatotal, totinvoiceview.taxabletotal, totinvoiceview.unabatabletotal, 
		paymentcommunicated.amount, expenseinvoice.idexp,
		'Mov. n. ' + CONVERT(varchar(6),paymentcommunicated.nmov) + '/' + CONVERT(varchar(4),paymentcommunicated.ymov),
		paymentcommunicated.competencydate
		FROM expenseinvoice
		JOIN paymentcommunicated
			ON paymentcommunicated.idexp = expenseinvoice.idexp
		JOIN invoice
			ON expenseinvoice.idinvkind = invoice.idinvkind
			AND expenseinvoice.yinv = invoice.yinv
			AND expenseinvoice.ninv = invoice.ninv
		JOIN invoicekind
			ON invoicekind.idinvkind = invoice.idinvkind
		JOIN totinvoiceview
			ON totinvoiceview.idinvkind = invoice.idinvkind
			AND totinvoiceview.yinv = invoice.yinv
			AND totinvoiceview.ninv = invoice.ninv
		JOIN ivaregister
			ON ivaregister.idinvkind = invoice.idinvkind 
			AND ivaregister.yinv = invoice.yinv
			AND ivaregister.ninv = invoice.ninv
		JOIN ivaregisterkind
			ON ivaregisterkind.idivaregisterkind = ivaregister.idivaregisterkind
		WHERE expenseinvoice.movkind IN (1,2)
			AND ivaregisterkind.registerclass = @registerclass
			AND YEAR(paymentcommunicated.competencydate) = @year
			AND MONTH(paymentcommunicated.competencydate) = @month
			AND invoice.flagdeferred = 'S'
			AND ivaregisterkind.idivaregisterkind = @idivaregisterkind)
		-- Calcolo sulle Note di Credito
		INSERT INTO #invoice_finmov (idinvkind, yinv, ninv, movkind, flagmixed, adate,
		ivatotal, taxabletotal, totivaunabatable, amountlinked, idmov, nvar, movdescription, movdate)
		(SELECT invoice.idinvkind,invoice.yinv,invoice.ninv,expensevar.movkind, 
	   	CASE
			WHEN ivaregisterkind.flagactivity = 3  THEN 'S'
			ELSE 'N'
		END,	
		invoice.adate,
		totinvoiceview.ivatotal, totinvoiceview.taxabletotal, totinvoiceview.unabatabletotal, 
		expensevar.amount, expensevar.idexp, expensevar.nvar,
		'Var. n. ' + CONVERT(varchar(6),expensevar.nvar) + '/' + CONVERT(varchar(4),expensevar.yvar),
		paymentcommunicated.competencydate
		FROM expensevar
		JOIN paymentcommunicated
		ON paymentcommunicated.idexp = expensevar.idexp
		JOIN invoice
		ON expensevar.idinvkind = invoice.idinvkind
		AND expensevar.yinv = invoice.yinv
		AND expensevar.ninv = invoice.ninv
		JOIN invoicekind
		ON invoicekind.idinvkind = invoice.idinvkind
		JOIN totinvoiceview
		ON totinvoiceview.idinvkind = invoice.idinvkind
		AND totinvoiceview.yinv = invoice.yinv
		AND totinvoiceview.ninv = invoice.ninv
		JOIN ivaregister
		ON ivaregister.idinvkind = invoice.idinvkind 
		AND ivaregister.yinv = invoice.yinv
		AND ivaregister.ninv = invoice.ninv
		JOIN ivaregisterkind
		ON ivaregisterkind.idivaregisterkind = ivaregister.idivaregisterkind
		WHERE expensevar.movkind IN (1,2)
		AND ivaregisterkind.registerclass = @registerclass
		AND YEAR(paymentcommunicated.competencydate) = @year
		AND MONTH(paymentcommunicated.competencydate) = @month
		AND invoice.flagdeferred = 'S'
		AND ivaregisterkind.idivaregisterkind = @idivaregisterkind)
	END	
	
	IF (@registerclass = 'V')
	BEGIN
		-- Sezione 2.2. IVA Differita
		-- Calcolo sulle Fatture
		INSERT INTO #invoice_finmov (idinvkind, yinv, ninv, movkind, flagmixed, adate,
		ivatotal, taxabletotal, totivaunabatable, amountlinked, idmov, movdescription, movdate)
		(SELECT invoice.idinvkind,invoice.yinv,invoice.ninv,incomeinvoice.movkind,
	   	CASE
			WHEN ivaregisterkind.flagactivity = 3  THEN 'S'
			ELSE 'N'
		END,	
		invoice.adate,
		totinvoiceview.ivatotal, totinvoiceview.taxabletotal, totinvoiceview.unabatabletotal, 
		proceedsemitted.amount, incomeinvoice.idinc,
		'Mov. n. ' + CONVERT(varchar(6),proceedsemitted.nmov) + '/' + CONVERT(varchar(4),proceedsemitted.ymov),
		proceedsemitted.competencydate
		FROM incomeinvoice
		JOIN proceedsemitted
		ON proceedsemitted.idinc = incomeinvoice.idinc
		JOIN invoice
		ON incomeinvoice.idinvkind = invoice.idinvkind
		AND incomeinvoice.yinv = invoice.yinv
		AND incomeinvoice.ninv = invoice.ninv
		JOIN invoicekind
		ON invoicekind.idinvkind = invoice.idinvkind
		JOIN totinvoiceview
		ON totinvoiceview.idinvkind = invoice.idinvkind
		AND totinvoiceview.yinv = invoice.yinv
		AND totinvoiceview.ninv = invoice.ninv
		JOIN ivaregister
		ON ivaregister.idinvkind = invoice.idinvkind 
		AND ivaregister.yinv = invoice.yinv
		AND ivaregister.ninv = invoice.ninv
		JOIN ivaregisterkind
		ON ivaregisterkind.idivaregisterkind = ivaregister.idivaregisterkind
		WHERE incomeinvoice.movkind IN (1,2)
		AND ivaregisterkind.registerclass = @registerclass
		AND YEAR(proceedsemitted.competencydate) = @year
		AND MONTH(proceedsemitted.competencydate) = @month
		AND invoice.flagdeferred = 'S'
		AND ivaregisterkind.idivaregisterkind = @idivaregisterkind)
		-- Calcolo sulle Note di Credito
		INSERT INTO #invoice_finmov (idinvkind, yinv, ninv, movkind, flagmixed, adate,
		ivatotal, taxabletotal, totivaunabatable, amountlinked, idmov, nvar, movdescription, movdate)
		(SELECT invoice.idinvkind,invoice.yinv,invoice.ninv,incomevar.movkind, 
	   	CASE
			WHEN ivaregisterkind.flagactivity = 3  THEN 'S'
			ELSE 'N'
		END,	
		invoice.adate,
		totinvoiceview.ivatotal, totinvoiceview.taxabletotal, totinvoiceview.unabatabletotal, 
		incomevar.amount, incomevar.idinc, incomevar.nvar,
		'Var. n. ' + CONVERT(varchar(6),incomevar.nvar) + '/' + CONVERT(varchar(4),incomevar.yvar),
		proceedsemitted.competencydate
		FROM incomevar
		JOIN proceedsemitted
		ON proceedsemitted.idinc = incomevar.idinc
		JOIN invoice
		ON incomevar.idinvkind = invoice.idinvkind
		AND incomevar.yinv = invoice.yinv
		AND incomevar.ninv = invoice.ninv
		JOIN invoicekind
		ON invoicekind.idinvkind = invoice.idinvkind
		JOIN totinvoiceview
		ON totinvoiceview.idinvkind = invoice.idinvkind
		AND totinvoiceview.yinv = invoice.yinv
		AND totinvoiceview.ninv = invoice.ninv
		JOIN ivaregister
		ON ivaregister.idinvkind = invoice.idinvkind 
		AND ivaregister.yinv = invoice.yinv
		AND ivaregister.ninv = invoice.ninv
		JOIN ivaregisterkind
		ON ivaregisterkind.idivaregisterkind = ivaregister.idivaregisterkind
		WHERE incomevar.movkind IN (1,2)
		AND ivaregisterkind.registerclass = @registerclass
		AND YEAR(proceedsemitted.competencydate) = @year
		AND MONTH(proceedsemitted.competencydate) = @month
		AND invoice.flagdeferred = 'S'
		AND ivaregisterkind.idivaregisterkind = @idivaregisterkind)
	END
	
	DECLARE @datebegin datetime
	DECLARE @dateend datetime
	DECLARE @monthstr varchar(2)
	SET @monthstr = SUBSTRING('00',1,2 - LEN(CONVERT(varchar(2),@month))) + CONVERT(varchar(2),@month)
	SET @datebegin = '01-' + @monthstr + '-' + CONVERT(varchar(4),@year)
	SET @dateend = DATEADD(DAY,-1,DATEADD(MONTH,1,@datebegin))
	
	UPDATE #invoice_finmov
	SET previvatotalpayed =
	ISNULL(
		(SELECT SUM(ivatotalpayed)
		FROM invoicedeferred
		JOIN ivapay
		ON ivapay.yivapay = invoicedeferred.yivapay
		AND ivapay.nivapay = invoicedeferred.nivapay
		WHERE #invoice_finmov.idinvkind = invoicedeferred.idinvkind
		AND #invoice_finmov.yinv = invoicedeferred.yinv
		AND #invoice_finmov.ninv = invoicedeferred.ninv
		AND ivapay.stop < @datebegin)
	,0)
	UPDATE #invoice_finmov
	SET prevtotalpayed =
	ISNULL(
		(SELECT SUM(totalpayed)
		FROM invoicedeferred
		JOIN ivapay
		ON ivapay.yivapay = invoicedeferred.yivapay
		AND ivapay.nivapay = invoicedeferred.nivapay
		WHERE #invoice_finmov.idinvkind = invoicedeferred.idinvkind
		AND #invoice_finmov.yinv = invoicedeferred.yinv
		AND #invoice_finmov.ninv = invoicedeferred.ninv
		AND ivapay.stop < @datebegin)
	,0)
	WHERE #invoice_finmov.movkind = 1
	UPDATE #invoice_finmov
	SET rapporto = 
	CASE
		WHEN ABS(#invoice_finmov.amountlinked) +
		ISNULL(
			(SELECT ABS(SUM(amountlinked))
			FROM #invoice_finmov i2
			WHERE i2.idinvkind = #invoice_finmov.idinvkind
			AND i2.yinv = #invoice_finmov.yinv
			AND i2.ninv = #invoice_finmov.ninv
			AND i2.idmov + CONVERT(varchar(6),ISNULL(i2.nvar,0)) <
			#invoice_finmov.idmov + CONVERT(varchar(6),ISNULL(#invoice_finmov.nvar,0)))
		,0) <> (ISNULL(#invoice_finmov.ivatotal,0) - ISNULL(#invoice_finmov.previvatotalpayed,0))
		THEN ABS(#invoice_finmov.amountlinked) / ISNULL(#invoice_finmov.ivatotal,0)
		ELSE 1
	END
	WHERE movkind = 2
	
	UPDATE #invoice_finmov
	SET rapporto = 
	CASE
		WHEN ABS(#invoice_finmov.amountlinked) +
		ISNULL(
			(SELECT ABS(SUM(amountlinked))
			FROM #invoice_finmov i2
			WHERE i2.idinvkind = #invoice_finmov.idinvkind
			AND i2.yinv = #invoice_finmov.yinv
			AND i2.ninv = #invoice_finmov.ninv
			AND i2.idmov + CONVERT(varchar(6),ISNULL(i2.nvar,0)) <
			#invoice_finmov.idmov + CONVERT(varchar(6),ISNULL(#invoice_finmov.nvar,0)))
		,0) <> (ISNULL(#invoice_finmov.ivatotal,0) + ISNULL(#invoice_finmov.taxabletotal,0) - ISNULL(#invoice_finmov.prevtotalpayed,0)) 
		THEN ABS(#invoice_finmov.amountlinked) / (ISNULL(#invoice_finmov.taxabletotal,0) + ISNULL(#invoice_finmov.ivatotal,0))
		ELSE 1
	END
	WHERE movkind = 1
	
	-- Contabilizzazione IMPOS
	INSERT INTO #invoice (idinvkind,yinv, ninv, taxabletotal, ivagross, ivaabatable, idivakind, adate, movdescription, movdate)
	SELECT #invoice_finmov.idinvkind, #invoice_finmov.yinv, #invoice_finmov.ninv, 
	CASE
		WHEN #invoice_finmov.rapporto <> 1
		THEN
		CONVERT(decimal(19,2),
			SUM(
				ROUND(
					invoicedetail.taxable * invoicedetail.npackage * 
					CONVERT(decimal(19,6),invoice.exchangerate) *
					(1 - CONVERT(decimal(19,6),ISNULL(invoicedetail.discount, 0)))
					* rapporto
				,2)
			)
		)
		ELSE
		CONVERT(decimal(19,2),
			SUM(
				ROUND(
					invoicedetail.taxable * invoicedetail.npackage * 
					CONVERT(decimal(19,6),invoice.exchangerate) *
					(1 - CONVERT(decimal(19,6),ISNULL(invoicedetail.discount, 0)))
				,2)
			)
		)
		-
		(
			CONVERT(decimal(19,2),
				SUM(
			    	ROUND(
						invoicedetail.taxable * invoicedetail.npackage * 
						CONVERT(decimal(19,6),invoice.exchangerate) *
						(1 - CONVERT(decimal(19,6),ISNULL(invoicedetail.discount, 0)))
						*
						(#invoice_finmov.previvatotalpayed / #invoice_finmov.ivatotal)
					,2)
				)
			)
		)
		-
		ISNULL(
			(SELECT 
				CONVERT(decimal(19,2),
					SUM(
						ROUND(
							id2.taxable * id2.npackage * 
							CONVERT(decimal(19,6),i2.exchangerate) *
							(1 - CONVERT(decimal(19,6),ISNULL(id2.discount, 0)))
							* ifm2.rapporto
						,2)
					)
				)
			FROM invoice i2
			JOIN invoicedetail id2
			ON i2.idinvkind = id2.idinvkind
			AND i2.yinv = id2.yinv
			AND i2.ninv = id2.ninv
			JOIN #invoice_finmov ifm2
			ON ifm2.idinvkind = i2.idinvkind
			AND ifm2.yinv = i2.yinv
			AND ifm2.ninv = i2.ninv
			WHERE ifm2.idmov + ISNULL(CONVERT(varchar(6),ifm2.nvar),'')< #invoice_finmov.idmov + ISNULL(CONVERT(varchar(6),#invoice_finmov.nvar),'')
			AND ifm2.idinvkind = #invoice_finmov.idinvkind
			AND ifm2.yinv = #invoice_finmov.yinv
			AND ifm2.ninv = #invoice_finmov.ninv
			AND id2.idivakind = invoicedetail.idivakind)
		,0)
	END,
	CASE
		WHEN #invoice_finmov.rapporto <> 1
		THEN ISNULL(SUM(ROUND(invoicedetail.tax, 2)),0) * rapporto
		ELSE
			ISNULL(
				SUM(
					ROUND(invoicedetail.tax, 2)
				)
			,0)
			-
			(
				ISNULL(
					SUM(
						ROUND(
							invoicedetail.tax
							 * (#invoice_finmov.previvatotalpayed / #invoice_finmov.ivatotal)
						,2)
					)
				,0)
			)
			-
			ISNULL(
				(SELECT 
					CONVERT(decimal(19,2),
						SUM(ROUND(id2.tax * ifm2.rapporto,2))
					)
				FROM invoice i2
				JOIN invoicedetail id2
				ON i2.idinvkind = id2.idinvkind
				AND i2.yinv = id2.yinv
				AND i2.ninv = id2.ninv
				JOIN #invoice_finmov ifm2
				ON ifm2.idinvkind = i2.idinvkind
				AND ifm2.yinv = i2.yinv
				AND ifm2.ninv = i2.ninv
				WHERE ifm2.idmov + ISNULL(CONVERT(varchar(6),ifm2.nvar),'')< #invoice_finmov.idmov + ISNULL(CONVERT(varchar(6),#invoice_finmov.nvar),'')
				AND ifm2.idinvkind = #invoice_finmov.idinvkind
				AND ifm2.yinv = #invoice_finmov.yinv
				AND ifm2.ninv = #invoice_finmov.ninv
				AND id2.idivakind = invoicedetail.idivakind)
			,0)
	END,
	CASE
		WHEN @registerclass = 'A' THEN
		CASE 
			WHEN #invoice_finmov.rapporto <> 1
			THEN 
			ISNULL(
				SUM(
					ROUND(
						(ISNULL(invoicedetail.tax,0) - ISNULL(invoicedetail.unabatable,0))
						* ISNULL(@proratarate,0) *
						CASE
							WHEN (#invoice_finmov.flagmixed ='S')  THEN ISNULL(@mixedrate, 0)
							ELSE 1
						END * rapporto
					, 2) 
				)
			, 0)
			ELSE
			ISNULL(
				SUM(
					ROUND(
						(ISNULL(invoicedetail.tax,0) - ISNULL(invoicedetail.unabatable,0))
						*ISNULL(@proratarate,0) * 
						CASE
							WHEN ( #invoice_finmov.flagmixed ='S') THEN ISNULL(@mixedrate, 0)
							ELSE 1
						END
					,2)
				)
			, 0)
			-
			ISNULL(
				SUM(
					ROUND(
						(ISNULL(invoicedetail.tax,0) - ISNULL(invoicedetail.unabatable,0))
						* ISNULL(@proratarate,0) * 
						CASE
							WHEN ( #invoice_finmov.flagmixed ='S') THEN ISNULL(@mixedrate, 0)
							ELSE 1
						END
						* (#invoice_finmov.previvatotalpayed / #invoice_finmov.ivatotal)
					,2)
				)
			, 0)
			-
			ISNULL(
				(SELECT 
				ISNULL(
					SUM(
						ROUND(
							(ISNULL(id2.tax,0) - ISNULL(id2.unabatable,0))
							* ifm2.rapporto * ISNULL(@proratarate,0) *
							CASE
								WHEN ( ifm2.flagmixed ='S') THEN ISNULL(@mixedrate, 0)
								ELSE 1
							END
						,2) 
					)
				, 0)
				FROM invoice i2
				JOIN invoicedetail id2
				ON i2.idinvkind = id2.idinvkind
				AND i2.yinv = id2.yinv
				AND i2.ninv = id2.ninv
				JOIN #invoice_finmov ifm2
				ON ifm2.idinvkind = i2.idinvkind
				AND ifm2.yinv = i2.yinv
				AND ifm2.ninv = i2.ninv
				WHERE ifm2.idmov + ISNULL(CONVERT(varchar(6),ifm2.nvar),'')< #invoice_finmov.idmov + ISNULL(CONVERT(varchar(6),#invoice_finmov.nvar),'')
				AND id2.idivakind = invoicedetail.idivakind
				AND ifm2.idinvkind = #invoice_finmov.idinvkind
				AND ifm2.yinv = #invoice_finmov.yinv
				AND ifm2.ninv = #invoice_finmov.ninv
				GROUP BY ifm2.flagmixed)
			,0)
		END
		ELSE 
		CASE
			WHEN #invoice_finmov.rapporto <> 1
			THEN ISNULL(SUM(ROUND(invoicedetail.tax * rapporto, 2)),0) 
			ELSE
				ISNULL(
					SUM(
						ROUND(invoicedetail.tax, 2)
					)
				,0)
				-
				(
					ISNULL(
						SUM(
							ROUND(
								invoicedetail.tax
								* (#invoice_finmov.previvatotalpayed / #invoice_finmov.ivatotal)
							,2)
						)
					,0)
				)
			-
			ISNULL(
				(SELECT 
					CONVERT(decimal(19,2),
						SUM(ROUND(id2.tax,2)* ifm2.rapporto)
					)
				FROM invoice i2
				JOIN invoicedetail id2
				ON i2.idinvkind = id2.idinvkind
				AND i2.yinv = id2.yinv
				AND i2.ninv = id2.ninv
				JOIN #invoice_finmov ifm2
				ON ifm2.idinvkind = i2.idinvkind
				AND ifm2.yinv = i2.yinv
				AND ifm2.ninv = i2.ninv
				WHERE ifm2.idmov + ISNULL(CONVERT(varchar(6),ifm2.nvar),'')< #invoice_finmov.idmov + ISNULL(CONVERT(varchar(6),#invoice_finmov.nvar),'')
				AND ifm2.idinvkind = #invoice_finmov.idinvkind
				AND ifm2.yinv = #invoice_finmov.yinv
				AND ifm2.ninv = #invoice_finmov.ninv
				AND id2.idivakind = invoicedetail.idivakind)
			,0)
		END
	END,
	invoicedetail.idivakind, #invoice_finmov.adate, #invoice_finmov.movdescription, #invoice_finmov.movdate
	FROM #invoice_finmov
	JOIN invoicedetail
	ON #invoice_finmov.idinvkind = invoicedetail.idinvkind
	AND #invoice_finmov.yinv = invoicedetail.yinv
	AND #invoice_finmov.ninv = invoicedetail.ninv
	JOIN invoice
	ON #invoice_finmov.idinvkind = invoice.idinvkind
	AND #invoice_finmov.yinv = invoice.yinv
	AND #invoice_finmov.ninv = invoice.ninv
	WHERE #invoice_finmov.movkind = 2
	GROUP BY invoicedetail.idivakind, #invoice_finmov.idinvkind, #invoice_finmov.yinv, #invoice_finmov.ninv, #invoice_finmov.rapporto,
	#invoice_finmov.previvatotalpayed, #invoice_finmov.ivatotal, #invoice_finmov.adate, #invoice_finmov.flagmixed, 
	#invoice_finmov.movdescription, #invoice_finmov.movdate, #invoice_finmov.idmov, #invoice_finmov.nvar
	
	-- Contabilizzazione DOCUM
	INSERT INTO #invoice (idinvkind,yinv, ninv, taxabletotal, ivagross, ivaabatable, idivakind, adate, movdescription, movdate)
