print '[exp_unifiedf24ep] OK'

GO
if object_id('[rpt_partitario_entrata_cassa]') is not null
	drop PROCEDURE [rpt_partitario_entrata_cassa]
go

CREATE     PROCEDURE [rpt_partitario_entrata_cassa]
	@ayear int,
	@kind char(1),
	@idupb	varchar(36),
	@nlevel tinyint,
	@start datetime,
	@stop datetime,
	@showupb char(1),
	@showchildupb char(1),
	@suppressifblank char(1),
	@flagnofficial	char(1),
	@idfin int
AS
BEGIN
/* Versione 1.0.1 del 17/09/2007 ultima modifica: PINO */
DECLARE @idupboriginal varchar(36)
SET @idupboriginal= @idupb
IF (@showchildupb = 'S') 
BEGIN
	SET @idupb=@idupb+'%' 
END
-- exec rpt_partitario_entrata_cassa 2011, 'S', '%', 3, {ts '2011-06-01 00:00:00'}, {ts '2011-12-31 00:00:00'}, 'N', 'N', 'S', 'N', 13550 
DECLARE @level_input tinyint
SET  @level_input = ISNULL((SELECT nlevel from fin where idfin = @idfin) ,@nlevel)
-- ho scelto come livello 2 e poi ho specificato il capitolo, lui corregge @nlevel dandogli 3
IF (@nlevel < @level_input ) AND (@idfin is not null)
	BEGIN
	SET  @nlevel = @level_input
	END

/*DECLARE @kind_bit  tinyint 
IF @kind='C' set @kind_bit = 0
IF @kind='R' set @kind_bit = 1
*/
DECLARE @level varchar(50)
SELECT  @level = description 
FROM 	finlevel
WHERE 	nlevel = @nlevel
AND 	ayear = @ayear
DECLARE @levelusable tinyint
SELECT 	@levelusable = MIN(nlevel)
FROM 	finlevel
WHERE 	flag&2 <> 0
AND 	ayear = @ayear
IF @levelusable < @nlevel
BEGIN	
	SET @levelusable = @nlevel
END
CREATE TABLE #income	(
	codeupb varchar(50),
	idupb varchar(36),
	upb varchar(150),
	upbprintingorder varchar(50),
	idfin int,
	rowkind int,
	nphase tinyint,
	operationdate datetime,
	operationkind varchar(55),
	idmov int,
	idreg int,
	ymov int,
	nmov int,
	nofficial int,
	nsubmov int,
	ndoc int,
	description varchar(150),
	doc varchar(150),
	initialprevision decimal(19,2),
	finvar decimal(19,2),
	cassaphase_amount decimal(19,2),
	emessiondate datetime,
	printeddate datetime,
	trasmitteddate datetime,
	transactiondate datetime,
	annulmentdate datetime,
	annotations varchar(400),
	available decimal(19,2),
	hierarchy varchar (50)
)
DECLARE @firstday datetime
SET 	@firstday = CONVERT(datetime, '01-01-' + CONVERT(varchar(4),@ayear), 105)
DECLARE @previsionkind char(1) 
SELECT  @previsionkind =  
	 CASE 
		WHEN fin_kind IN (1,3) THEN 'C'
		WHEN fin_kind = 2 THEN 'S'
	 END
FROM  config 
WHERE config.ayear = @ayear
DECLARE @secprevisionkind    char(1) 
SELECT  @secprevisionkind  = 
	 CASE 
		WHEN fin_kind = 3 THEN 'S'
		ELSE NULL
	END
FROM 	config 
WHERE   config.ayear = @ayear
DECLARE @finphase tinyint
DECLARE @finname varchar(50)
SELECT @finphase = assessmentphasecode FROM config  WHERE ayear = @ayear
SELECT @finname = description FROM incomephase WHERE nphase = @finphase
DECLARE @phasecassa varchar(50)
DECLARE @maxincomephase tinyint
SELECT @maxincomephase = MAX(nphase) FROM incomephase
SELECT @phasecassa = description FROM incomephase WHERE nphase = @maxincomephase

IF ((@kind IN ('C','S')) AND (DATEDIFF(DAY,@start, @firstday) = 0))
BEGIN
	INSERT INTO #income
		(
		idfin,
		codeupb	,
		idupb,
		upb,
		upbprintingorder,
		rowkind,
		operationdate,
		operationkind,
		initialprevision
		)
	SELECT 
		fin.idfin,
		upb.codeupb,
		upb.idupb,
		upb.title,
		upb.printingorder,
		1,
		@firstday,
		'Prev.iniziale',
		CASE
			WHEN @kind = 'C' THEN (SELECT SUM(fy2.prevision) 
						FROM finyear fy2 
						JOIN fin f2
							ON fy2.idfin=f2.idfin
						JOIN finlink
							ON finlink.idchild = fy2.idfin
							AND finlink.nlevel = @nlevel
						WHERE   finlink.idparent = fin.idfin
							AND f2.nlevel = @levelusable 
							AND fy2.idupb= upb.idupb)
			WHEN (@kind = 'S' and @previsionkind = 'S') 
					THEN (SELECT SUM(fy2.prevision) 
						FROM finyear fy2 
						JOIN fin f2
							ON fy2.idfin=f2.idfin
						JOIN finlink
							ON finlink.idchild = fy2.idfin
							AND finlink.nlevel = @nlevel
						WHERE   finlink.idparent = fin.idfin
							AND f2.nlevel = @levelusable 
							AND fy2.idupb= upb.idupb)
			WHEN (@kind = 'S' and @secprevisionkind = 'S') 
					THEN (SELECT SUM(fy2.secondaryprev) 
						FROM finyear fy2 
						JOIN fin f2
							ON fy2.idfin=f2.idfin
						JOIN finlink
							ON finlink.idchild = fy2.idfin
							AND finlink.nlevel = @nlevel
						WHERE finlink.idparent = fin.idfin
							AND f2.nlevel = @levelusable 
							AND fy2.idupb= upb.idupb)
			END
	FROM finyear
	JOIN fin
		ON finyear.idfin = fin.idfin
	JOIN upb
		ON finyear.idupb = upb.idupb
	left outer JOIN finlink
		ON finlink.idchild = finyear.idfin
		AND finlink.nlevel = @level_input
	WHERE (upb.idupb like @idupb )
		AND fin.ayear = @ayear
		AND ((fin.flag&1)=0) -- Entrata
		AND fin.nlevel = @nlevel
		AND (@idfin IS NULL OR isnull(finlink.idparent, fin.idfin) = @idfin)
END
DECLARE @cashvaliditykind int
SELECT  @cashvaliditykind = cashvaliditykind
FROM config
WHERE ayear = @ayear
IF (DATEDIFF(DAY,@start, @firstday) <> 0)
BEGIN
	CREATE TABLE #previousincome
	(
		idfin 	int,
		idupb 	varchar(36),
		initialprevision decimal(19,2),
		finvar decimal(19,2),
		cassaphase_amount decimal(19,2)
	)
	INSERT INTO #previousincome
		(
		idfin,
		idupb
		)
	SELECT finyear.idfin,
	       finyear.idupb
	FROM finyear
	JOIN fin
		ON finyear.idfin = fin.idfin
	JOIN upb
		ON finyear.idupb = upb.idupb
	left outer JOIN finlink
		ON finlink.idchild = finyear.idfin
		AND finlink.nlevel = @level_input
	WHERE (upb.idupb like @idupb)
		AND fin.ayear = @ayear
		AND ((fin.flag&1)=0) -- Entrata
		AND fin.nlevel = @nlevel
		AND (@idfin IS NULL OR isnull(finlink.idparent, fin.idfin) = @idfin)
-------------------------------------------------------------------------------------------------------------
INSERT INTO #previousincome
	(
	idfin,
	idupb
	)--> Prende quelli che non ha preso prima perchè non presenti in finyear  
SELECT 
	isnull(FL1.idparent, fin.idfin),
	incomeyear.idupb
FROM incomeyear
	JOIN income
		ON income.idinc = incomeyear.idinc
	JOIN incometotal
		ON  incomeyear.idinc = incometotal.idinc
		AND incomeyear.ayear = incometotal.ayear	
	left outer JOIN finlink
		ON finlink.idchild = incomeyear.idfin
		AND finlink.nlevel = @level_input
	left outer JOIN finlink FL1
		ON FL1.idchild = incomeyear.idfin	
		AND FL1.nlevel = @nlevel
	JOIN fin
		ON fin.idfin = isnull(FL1.idparent, fin.idfin)--FL1.idparent
	WHERE /*((incometotal.flag&1) = @kind_bit)
		AND */income.adate < @start
		AND fin.ayear = @ayear
		AND ((fin.flag&1)=0) 
		AND income.nphase = @finphase
		AND incomeyear.ayear = @ayear
		AND (incomeyear.idupb like @idupb )
		AND (@idfin IS NULL OR isnull(finlink.idparent, fin.idfin) = @idfin)	
		AND NOT EXISTS (SELECT #previousincome.idfin,#previousincome.idupb
			FROM #previousincome
			WHERE idupb = incomeyear.idupb AND idfin = isnull(finlink.idparent, fin.idfin))
	GROUP by incomeyear.idupb,isnull(FL1.idparent, fin.idfin)--> altrimenti prende una coppia per ogni stanziamento imputato a quella coppia
------------------------------------------------------------------------------------------------------------------------------
	IF (@kind IN ('C','S'))
		BEGIN
			UPDATE #previousincome
				SET initialprevision =
					(SELECT 
						CASE
							WHEN  @kind = 'C' THEN SUM(u2.prevision) 
							WHEN (@kind = 'S' and @previsionkind = 'S') THEN SUM(u2.prevision) 
							WHEN (@kind = 'S' and @secprevisionkind = 'S') THEN SUM(u2.secondaryprev) 
						END
					FROM finyear u2
					JOIN fin f2
						ON u2.idfin = f2.idfin	
					JOIN finlink
						ON finlink.idchild = f2.idfin 
						and finlink.nlevel =  @nlevel
					WHERE u2.idupb= #previousincome.idupb
						AND finlink.idparent = #previousincome.idfin
						AND f2.nlevel = @levelusable),
				finvar =
					(SELECT SUM(finvardetail.amount)
					FROM finvardetail
					JOIN finvar
						ON finvar.yvar = finvardetail.yvar
						AND finvar.nvar = finvardetail.nvar
					JOIN finlink
						ON finlink.idchild = finvardetail.idfin  
						AND finlink.nlevel = @nlevel
					WHERE finvardetail.idupb = #previousincome.idupb
						AND finvar.flagprevision ='S'
						AND finvar.variationkind <> 5
						AND finvar.adate < @start
						AND finvar.yvar = @ayear
						AND finlink.idparent = #previousincome.idfin)
		END
	ELSE
		BEGIN
			UPDATE #previousincome
				SET initialprevision =
					(SELECT SUM(incomeyear.amount)
					FROM incomeyear
					JOIN income
						ON income.idinc = incomeyear.idinc
					JOIN incometotal
						ON  incomeyear.idinc = incometotal.idinc
						AND incomeyear.ayear = incometotal.ayear	
					JOIN finlink
						ON finlink.idchild = incomeyear.idfin
						AND finlink.nlevel = @nlevel
					WHERE /* ((incometotal.flag&1) = @kind_bit)
						AND */income.adate < @start
						AND income.nphase = @finphase
						AND incomeyear.idupb = #previousincome.idupb
						AND finlink.idparent =  #previousincome.idfin
						AND incomeyear.ayear = @ayear)
		END
	IF (@cashvaliditykind <> 4)
	BEGIN
		UPDATE #previousincome
		SET cassaphase_amount = ISNULL((
			SELECT SUM(HPV.amount)
			FROM historyproceedsview HPV
			JOIN finlink
				ON finlink.idchild = HPV.idfin	
				AND finlink.nlevel = @nlevel
			WHERE (HPV.flagarrear = @kind OR @kind = 'S')
				AND HPV.idupb = #previousincome.idupb
				AND HPV.competencydate < @start
				AND finlink.idparent = #previousincome.idfin
				AND HPV.ymov = @ayear), 0)
			+ 
			ISNULL((
			SELECT SUM(incomevar.amount)
			FROM incomevar
			JOIN historyproceedsview HPV
				ON HPV.idinc = incomevar.idinc
			JOIN finlink
				ON finlink.idchild = HPV.idfin	
				AND finlink.nlevel = @nlevel
			WHERE incomevar.yvar = @ayear
				AND HPV.ymov = @ayear
				AND HPV.idupb = #previousincome.idupb
				AND finlink.idparent = #previousincome.idfin
				AND (HPV.flagarrear = @kind OR @kind = 'S')
				AND incomevar.adate < @start
				AND HPV.competencydate <= @start
				AND HPV.ymov = @ayear
				), 0)	
	END
	ELSE
	BEGIN
		UPDATE #previousincome
		SET cassaphase_amount = ISNULL((
			SELECT SUM(HPV.amount)
			FROM historyproceedsview HPV
			JOIN finlink
				ON finlink.idchild = HPV.idfin	
				AND finlink.nlevel = @nlevel
			WHERE (HPV.flagarrear = @kind OR @kind = 'S')
				AND HPV.idupb = #previousincome.idupb
				AND HPV.competencydate < @start
				AND finlink.idparent = #previousincome.idfin
				AND HPV.ymov = @ayear), 0)
	END
	
		INSERT INTO #income
		(
			idfin,
			idupb,
			codeupb,
			upb,
			upbprintingorder,
			rowkind,
			operationdate,
			operationkind,
			initialprevision,
			finvar,
			cassaphase_amount
		)
		SELECT
			#previousincome.idfin,
			upb.idupb,
			upb.codeupb,
			upb.title,
			upb.printingorder,
			1,
			DATEADD(dd, -1, @start),
		 	'Tot.prec.',
			#previousincome.initialprevision,
			#previousincome.finvar,
			#previousincome.cassaphase_amount
		FROM #previousincome
		JOIN fin
			ON fin.idfin = #previousincome.idfin
		JOIN upb 
			ON upb.idupb=#previousincome.idupb
END 
IF (@kind IN ('C','S')) 
BEGIN
-- Variazione di previsione
	INSERT INTO #income
		(
		idfin,
		idupb,codeupb,upb,upbprintingorder,
		rowkind,
		operationdate,
		operationkind,
		ymov,
		nmov,
		nofficial,
		description,
		finvar
		)
	SELECT 
		isnull(finlink.idparent, fin.idfin),
		upb.idupb,
		upb.codeupb,
		upb.title,
		upb.printingorder,
		2,
		finvar.adate,
		'Var.prev.',
		finvar.yvar,
		finvar.nvar,
		CASE finvar.official
			WHEN 'S' THEN finvar.nofficial
			ELSE NULL
		END,
		finvar.description,
		finvardetail.amount
	FROM finvardetail
	JOIN finvar
		ON finvar.yvar = finvardetail.yvar
		AND finvar.nvar = finvardetail.nvar
	JOIN upb 
		ON upb.idupb=finvardetail.idupb 
	left outer JOIN finlink
		ON finlink.idchild = finvardetail.idfin	
		AND finlink.nlevel = @level_input
	JOIN fin
		ON fin.idfin = finvardetail.idfin
	WHERE (upb.idupb like @idupb )
		AND finvar.flagprevision = 'S'
		AND finvar.variationkind <> 5
		AND finvar.adate BETWEEN @start AND @stop
		AND fin.ayear = @ayear
		AND ((fin.flag&1)=0) -- = 'E'	
		--AND fin.nlevel = @nlevel
		AND (@idfin IS NULL OR isnull(finlink.idparent, fin.idfin) = @idfin)	
END
------------------------
-- Movimenti di Entrata / fase cassa
INSERT INTO #income
	(
	idfin,
	idmov,
	idupb,
	codeupb,
	upb,
	upbprintingorder,
	rowkind,
	nphase,
	operationdate,
	operationkind,
	ymov,
	nmov,
	ndoc,
	description,
 	doc,
	idreg,
	cassaphase_amount
	)
SELECT 
	isnull(FL1.idparent, fin.idfin),
	HPV.idinc,
	upb.idupb,upb.codeupb,upb.title,upb.printingorder,
	15, --> in quella due fasi c'era 5
	@maxincomephase,
	HPV.competencydate,
	@phasecassa,
	HPV.ymov,
	HPV.nmov,
	HPV.npro,
	HPV.description,
	CASE
		WHEN HPV.doc IS NOT NULL AND 
			HPV.docdate IS NULL THEN
			'Inc. ' + HPV.doc
		WHEN HPV.doc IS NOT NULL AND
			HPV.docdate IS NOT NULL THEN
			'Inc. ' + HPV.doc + 
			' del ' + CONVERT(varchar(20), HPV.docdate, 105)
		ELSE
			(NULL)
	END,
	HPV.idreg,
	HPV.amount
FROM historyproceedsview HPV
JOIN upb
	ON HPV.idupb = upb.idupb
left outer JOIN finlink
	ON finlink.idchild = HPV.idfin	
	AND finlink.nlevel = @level_input
left outer JOIN finlink FL1
	ON FL1.idchild = HPV.idfin	
	AND FL1.nlevel = @nlevel
JOIN fin
	ON fin.idfin = FL1.idparent
WHERE HPV.competencydate BETWEEN @start AND @stop
	AND (upb.idupb like @idupb )
	AND HPV.ymov = @ayear
	AND ((@kind IN ('C', 'R') AND HPV.flagarrear = @kind) OR @kind = 'S')
	AND fin.ayear = @ayear
	AND ((fin.flag&1)=0) -- Entrata
	AND fin.nlevel = @nlevel
	AND (@idfin IS NULL OR isnull(finlink.idparent, fin.idfin) = @idfin)
-- Variazione ai Movimenti di Entrata / fase cassa 
IF (@cashvaliditykind <> 4)
BEGIN
	INSERT INTO #income
		(
		idfin,
		idmov,
		idupb, codeupb,upb,upbprintingorder,
		rowkind,
		nphase,
		operationdate,
		operationkind,
		ymov,
		nmov,
		nsubmov,
		ndoc,
		description,
		doc,
		idreg,
		cassaphase_amount
		)
	SELECT 
		isnull(FL1.idparent, fin.idfin),
		HPV.idinc,
		upb.idupb, upb.codeupb,upb.title,upb.printingorder,
		20,-- in quella a due fasi c'era 6
		@maxincomephase, 
		incomevar.adate,
		'Var.' + @phasecassa,
		HPV.ymov,
		HPV.nmov,
		incomevar.nvar,
		HPV.npro,
		incomevar.description,
		CASE
			WHEN incomevar.doc IS NOT NULL AND 
				incomevar.docdate IS NULL THEN
				'Inc. ' + incomevar.doc
			WHEN incomevar.doc IS NOT NULL AND
				incomevar.docdate IS NOT NULL THEN
				'Inc. ' + incomevar.doc + 
				' del ' + CONVERT(varchar(20), incomevar.docdate, 105)
			ELSE
		(NULL)
		END,
		HPV.idreg,
		incomevar.amount
	FROM incomevar
	JOIN historyproceedsview HPV
		ON  HPV.idinc = incomevar.idinc
	JOIN upb
		ON upb.idupb = HPV.idupb
	left outer JOIN finlink
		ON finlink.idchild = HPV.idfin	
		AND finlink.nlevel = @level_input
	left outer JOIN finlink FL1
		ON FL1.idchild = HPV.idfin	
		AND FL1.nlevel = @nlevel
	JOIN fin
		ON fin.idfin = FL1.idparent
	WHERE incomevar.yvar = @ayear
		AND incomevar.adate BETWEEN @start AND @stop
		AND isnull(incomevar.autokind,'') <>'22'
		AND (upb.idupb like @idupb)
		AND HPV.competencydate BETWEEN @start AND @stop
		AND HPV.ymov = @ayear
		AND ((@kind IN ('C', 'R') AND (HPV.flagarrear = @kind)) OR @kind = 'S')
		AND fin.ayear = @ayear
		AND ((fin.flag&1)=0) -- Entrata
		AND fin.nlevel = @nlevel
		AND (@idfin IS NULL OR isnull(finlink.idparent, fin.idfin) = @idfin)
		
END
-- costruisce la gerarchia del movimento per creare l'ordinamento nel report
UPDATE #income 
SET 
	hierarchy = convert(varchar(4),E1.ymov) + '/' + 
	Replicate('0',6-len(convert(varchar(6),E1.nmov)))+ convert(varchar(6),E1.nmov)
FROM income
JOIN incomelink EL1
	ON EL1.idchild = income.idinc  AND EL1.nlevel = 1
LEFT OUTER JOIN incomelink EL2
	ON EL2.idchild = income.idinc  AND EL2.nlevel = 2
LEFT OUTER JOIN incomelink EL3
	ON EL3.idchild = income.idinc  AND EL3.nlevel = 3
LEFT OUTER JOIN incomelink EL4
	ON EL4.idchild = income.idinc  AND EL4.nlevel = 4
LEFT OUTER JOIN income E1
	ON E1.idinc = EL1.idparent
LEFT OUTER JOIN income E2
	ON E2.idinc = EL2.idparent
LEFT OUTER JOIN income E4
	ON E4.idinc = EL4.idparent
LEFT OUTER JOIN income E3
	ON E3.idinc = EL3.idparent
WHERE  EL1.idchild = #income.idmov
-------------------------------------------------------
UPDATE #income
SET 		emessiondate = proceedsview.adate,
		printeddate = 	proceedsview.printdate,
		trasmitteddate = proceedsview.transmissiondate,	
		transactiondate =  proceedsperformed.competencydate,
		annulmentdate = proceedsview.annulmentdate
FROM proceedsview
LEFT OUTER JOIN banktransaction
	ON banktransaction.kpro=proceedsview.kpro	
	AND (banktransaction.kind='C' OR banktransaction.kind IS NULL)	
LEFT OUTER JOIN proceedsperformed 
	ON proceedsperformed.npro=proceedsview.npro	
	AND proceedsperformed.ypro=proceedsview.ypro
WHERE #income.ndoc = proceedsview.npro
	AND proceedsview.ypro=@ayear
	
IF (@suppressifblank = 'N')
BEGIN
--se ho scelto di vedere l'upb inserisco le coppie upb/bilancio altrimenti inserisco solo il bilanico non utilizzato
	IF ( (@showupb <>'S') and (@idupboriginal = '%'))
	Begin
		INSERT INTO #income 
			(
			idfin,
			rowkind
			)
		SELECT 
			fin.idfin,
			1
		FROM fin 
		JOIN finlink
			ON finlink.idchild = fin.idfin	
			AND finlink.nlevel = @level_input
		WHERE  fin.ayear = @ayear
			AND ((fin.flag&1)= 0) -- Entrata
			AND fin.nlevel = @nlevel
			AND (@idfin IS NULL OR isnull(finlink.idparent, fin.idfin) = @idfin)
			and not exists (SELECT *
				FROM #income
				WHERE fin.idfin = #income.idfin )	
	End
	Else
	Begin
		INSERT INTO #income 
			(
				idfin,
				idupb,
				codeupb,
				upb,
				upbprintingorder,
				rowkind
				)
		SELECT 
			isnull(FL1.idparent, fin.idfin),
			upb.idupb,
			codeupb,
			upb.title,
			upb.printingorder,
			1
		FROM fin CROSS JOIN upb 
		left outer JOIN finlink
			ON finlink.idchild = fin.idfin	
			AND finlink.nlevel = @level_input
		left outer JOIN finlink FL1
			ON FL1.idchild = fin.idfin	
			AND FL1.nlevel = @nlevel
		WHERE (upb.idupb like @idupb)
			AND fin.ayear = @ayear
			AND ((fin.flag&1)=0) -- Entrata	
			AND fin.nlevel = @nlevel
			AND (@idfin IS NULL OR isnull(finlink.idparent, fin.idfin) = @idfin)
			and not exists (SELECT *
				FROM #income
				WHERE isnull(#income.idupb,'')=isnull(i.idupb,'')  
				AND FL1.idparent = #income.idfin)
	End
	
END
IF (@showupb <>'S') AND (@idupboriginal <> '%' ) AND (@showchildupb = 'S')
		UPDATE #income SET  
			upbprintingorder = (SELECT TOP 1 upbprintingorder
				FROM #income
				WHERE idupb = @idupboriginal),
			upb = (SELECT TOP 1 upb
				FROM #income
				WHERE idupb = @idupboriginal),
			idupb = @idupboriginal,
			codeupb =(SELECT TOP 1 codeupb
				FROM #income	
				WHERE idupb = @idupboriginal)
IF (@showupb <>'S') and (@idupboriginal = '%')
		UPDATE #income SET  
			upbprintingorder = null	,
			upb =  null,
			idupb = null,
			codeupb = null

-- se ho scelto di nascondere le voci di bilancio non utilizzate:
-- cancello le righe che hanno valori pari a zero 
-- per cui non esistono variazioni di previzioni (rowkind=2) o movimenti di entrata (rowkind >= 3 )  
IF (@suppressifblank = 'S') AND @nlevel>2	--> se la stampa è x un livello sottostante la categoria cancella le righe
BEGIN
	DELETE FROM #income WHERE 
		ISNULL(initialprevision,0)=0 AND 
		ISNULL(finvar,0)=0 AND 
		ISNULL(cassaphase_amount,0)=0 AND
		NOT EXISTS (select * from  #income i
				where isnull(#income.idupb,'')=isnull(i.idupb,'') AND
				      #income.idfin=i.idfin AND 
					i.rowkind>1)
END

IF (@showupb <>'S') 
BEGIN
	SELECT 
		#income.idfin,
		idmov,
		@level as levelname,
		F.codefin,
		F.printingorder as finprintingorder,
		F.title,
		codeupb,idupb,upb,upbprintingorder,rowkind,
		nphase,operationdate,operationkind,ymov,nmov,nofficial,nsubmov,
		ndoc,description,doc,annotations,
		REG.title as registry,	
		isnull(sum(initialprevision),0) as initialprevision,
		isnull(sum(finvar),0) as finvar	,
		isnull(sum(available),0) as available,
		isnull(sum(cassaphase_amount),0) as cassaphase_amount,
		emessiondate,printeddate,trasmitteddate,transactiondate,
		annulmentdate,
		@finname as finname,				
		@phasecassa as phasecassa,
		hierarchy
	FROM #income
	JOIN fin F
		ON F.idfin = #income.idfin
	LEFT OUTER JOIN registry REG
		ON REG.idreg = #income.idreg
	GROUP BY codeupb,idupb,upb,upbprintingorder,hierarchy,
		F.printingorder,#income.idfin,idmov,
		F.codefin,F.title,
		rowkind,nphase,operationdate,operationkind,ymov,nmov,nofficial,nsubmov,ndoc,description,doc,
		annotations,REG.title,emessiondate,printeddate,
		trasmitteddate,transactiondate,annulmentdate
	ORDER BY upbprintingorder ASC, finprintingorder ASC,hierarchy ASC,
		rowkind ASC,
		ymov ASC,
		nmov ASC,
		nsubmov ASC
END
ELSE
BEGIN
	SELECT 	#income.idfin,
		idmov,
		@level as levelname,
		F.codefin,
		F.printingorder as finprintingorder,
		F.title,
		codeupb,idupb,upb,upbprintingorder,rowkind,
		nphase,operationdate,operationkind,ymov,nmov,nofficial,nsubmov,
		ndoc,description,doc,annotations,
		REG.title as registry,	
		isnull(initialprevision,0) as initialprevision,
		isnull(finvar,0) as finvar,
		isnull(available,0) as available,
		isnull(cassaphase_amount,0) as cassaphase_amount,
		emessiondate,printeddate,trasmitteddate,transactiondate,annulmentdate,
		@finname as finname,	
		@phasecassa as phasecassa,
		hierarchy		
	FROM #income
	JOIN fin F
		ON F.idfin = #income.idfin
	LEFT OUTER JOIN registry REG
		ON REG.idreg = #income.idreg
	ORDER BY upbprintingorder ASC, F.printingorder ASC,hierarchy ASC,
		rowkind ASC,
		ymov ASC,
		nmov ASC,
		nofficial ASC,
		nsubmov ASC
END
END


GO

print '[rpt_partitario_entrata_cassa] OK'

GO
if object_id('[exp_consuntivo]') is not null
	drop PROCEDURE [exp_consuntivo]
go


CREATE   PROCEDURE [exp_consuntivo]
(
	@ayear int,
	@date datetime,
	@finpart char(1),
	@levelusable tinyint,
	@idupb varchar(36),
	@showchildupb char(1),
	@officialvar varchar(1)
)
AS BEGIN
/* Versione 1.0.1 del 16/11/2007 ultima modifica: Pino */
CREATE TABLE #balance
(
	idfin int,
	codefin varchar(50),
	description varchar(150),
	printingorder varchar(31),
	initialprevision decimal(19,2),
	var_prev_M_acc decimal(19,2),
	var_prev_M_red decimal(19,2),
	secondaryprev decimal(19,2),
	var_prev_S_acc decimal(19,2),
	var_prev_S_red decimal(19,2),
	mov_finphase_C decimal(19,2),
	var_finphase_C decimal(19,2),
	mov_maxphase_C decimal(19,2),
	var_maxphase_C decimal(19,2),
	mov_finphase_R decimal(19,2),
	var_finphase_acc_R decimal(19,2),
	var_finphase_red_R decimal(19,2),
	mov_maxphase_R decimal(19,2),
	var_maxphase_R decimal(19,2)
)
IF (@showchildupb = 'S')
BEGIN
	SET @idupb = @idupb+'%' 
END
DECLARE	@finpart_bit  tinyint  -- Parte del bilancio (E = Entrata S = Spesa)
if @finpart='E' set @finpart_bit = 0
if @finpart='S' set @finpart_bit = 1
DECLARE @infoadvance char(1)
SELECT  @infoadvance = paramvalue
FROM    generalreportparameter
WHERE   idparam = 'MostraAvanzo'
DECLARE @cashvaliditykind tinyint
SELECT  @cashvaliditykind = cashvaliditykind FROM config WHERE ayear = @ayear
DECLARE @finphase tinyint
DECLARE @maxphase tinyint

DECLARE @idavanzocassa  int
DECLARE @idavanzoamm int
SET @idavanzocassa  = -1
SET @idavanzoamm = -2

IF (@finpart = 'E')
BEGIN
	-- ricerca la fase equivalente all'accertamento
	-- se è stata inserita nella tabella di configurazione del bilancio
	SELECT @finphase = assessmentphasecode FROM config WHERE ayear = @ayear
	IF @finphase IS NULL
	BEGIN
		-- se non è stata inserita nella tabella di configurazione
		-- ipotizza che si tratti della fase dove viene identificata
		-- la voce di bilancio
		SELECT @finphase = incomefinphase FROM uniconfig
	END
	-- la fase di cassa è sempre l'ultima fase della procedura
	-- di entrata
	SELECT @maxphase = MAX(nphase) FROM incomephase
END
IF (@finpart = 'S')
BEGIN
	-- ricerca la fase equivalente all'impegno
	-- se è stata inserita nella tabella di configurazione
	-- del bilancio
	SELECT @finphase = appropriationphasecode FROM config WHERE ayear = @ayear
	IF @finphase IS NULL
	BEGIN
		-- se non è stata inserita nella tabella di configurazione
		-- ipotizza che si tratti della fase dove viene identificata
		-- la voce di bilancio
		SELECT @finphase = expensefinphase FROM uniconfig
	END
	-- la fase di cassa è sempre l'ultima fase della procedura di spesa
	SELECT @maxphase = MAX(nphase) FROM expensephase
END
DECLARE @supposed_ff_jan01 decimal(19,2)
DECLARE @supposed_aa_jan01 decimal(19,2)
DECLARE @ff_jan01 decimal(19,2)
DECLARE @aa_jan01 decimal(19,2)
DECLARE @idfinincomesurplus int -- Flag indicante se l'avanzo di amministrazione è attribuito in previsione ad un capitolo di entrata o no
SELECT  @idfinincomesurplus = isnull(idfinincomesurplus,0) 
	FROM config
	WHERE ayear = @ayear
IF (@finpart = 'E')
BEGIN
	-- Fondo cassa e avanzo di amministrazione presunti ed effettivi al 01/01
	-- dell'ayear per il quale si effettua il consuntivo.
	SELECT	@supposed_ff_jan01 =
		ISNULL(startfloatfund, 0) +
		ISNULL(proceedstilldate, 0) +
		ISNULL(proceedstoendofyear, 0) -
		ISNULL(paymentstilldate, 0) -
		ISNULL(paymentstoendofyear, 0),
	@supposed_aa_jan01 =
		ISNULL(startfloatfund, 0) +
		ISNULL(proceedstilldate, 0) +
		ISNULL(proceedstoendofyear, 0) -
		ISNULL(paymentstilldate, 0) -
		ISNULL(paymentstoendofyear, 0) +
		ISNULL(supposedpreviousrevenue, 0) +
		ISNULL(supposedcurrentrevenue , 0) -
		ISNULL(supposedpreviousexpenditure, 0) -
		ISNULL(supposedcurrentexpenditure, 0)
	FROM surplus
	WHERE ayear = @ayear - 1
-- Per ulteriori dettagli in merito a questa modifica leggere la Documentazione del task n.4077
	SELECT	@ff_jan01 = ISNULL(startfloatfund, 0) 
	FROM surplus
	WHERE ayear = @ayear
	
	SELECT
	@aa_jan01 = @ff_jan01 +
		ISNULL(previousrevenue, 0) +
		ISNULL(currentrevenue , 0) -
		ISNULL(previousexpenditure, 0) -
		ISNULL(currentexpenditure, 0)
	FROM surplus
	WHERE ayear = @ayear - 1
END
INSERT INTO #balance
(
	idfin,
	codefin, printingorder,
	initialprevision,
	secondaryprev
)
SELECT 
	f.idfin, 
	f.codefin, f.printingorder,
	ISNULL(SUM(fy.prevision),0), 
	ISNULL(SUM(fy.secondaryprev),0)
FROM fin f
CROSS JOIN upb 
JOIN finlevel fl
	ON f.nlevel = fl.nlevel AND  f.ayear = fl.ayear
LEFT OUTER JOIN finyear fy
	ON fy.idfin = f.idfin
	AND fy.idupb = upb.idupb
WHERE f.ayear = @ayear
	AND (upb.idupb LIKE @idupb)
	AND ((f.flag & 1)= @finpart_bit)
	AND (f.nlevel = @levelusable
		OR (f.nlevel < @levelusable
			AND EXISTS (SELECT * FROM finlast WHERE finlast.idfin = f.idfin)
			AND (fl.flag&2)<>0
			)
		)
	AND (@infoadvance = 'N' OR @infoadvance = 'B' OR f.idfin <> @idfinincomesurplus )
GROUP BY f.idfin, f.codefin, f.printingorder, f.nlevel
CREATE TABLE #tot_varprev_acc_M (idfin int, total decimal(19,2))
INSERT INTO #tot_varprev_acc_M
(
	idfin,
	total
)
SELECT
	ISNULL(FLK.idparent,FVD.idfin),
	ISNULL(SUM(FVD.amount),0)
FROM finvardetail FVD
JOIN finvar FV
	ON FV.yvar = FVD.yvar
	AND FV.nvar = FVD.nvar
join fin F
	ON FVD.idfin = F.idfin
LEFT OUTER JOIN finlink FLK
	ON FLK.idchild = FVD.idfin AND FLK.nlevel = @levelusable
WHERE FV.yvar = @ayear
	AND FVD.idupb LIKE @idupb
	AND FV.adate <= @date
	AND FV.flagprevision = 'S'
	AND((ISNULL(FV.official,'N') = 'S' AND ISNULL(@officialvar,'N') = 'S') -- consideriamo solo le variazioni ufficiali
	  OR ISNULL(@officialvar,'N') = 'N')
	AND FV.idfinvarstatus = 5
	AND FV.variationkind <> 5
	AND FVD.amount > 0
	AND ((F.flag & 1 ) = @finpart_bit) AND F.ayear = @ayear
GROUP BY FVD.idupb,ISNULL(FLK.idparent,FVD.idfin)
CREATE TABLE #tot_varprev_red_M (idfin int, total decimal(19,2))
INSERT INTO #tot_varprev_red_M
(
	idfin,
	total
)
SELECT
	ISNULL(FLK.idparent,FVD.idfin),
	ISNULL(SUM(FVD.amount),0)
FROM finvardetail FVD
JOIN finvar FV
	ON FV.yvar = FVD.yvar
	AND FV.nvar = FVD.nvar
join fin F
	ON FVD.idfin = F.idfin
LEFT OUTER JOIN finlink FLK
	ON FLK.idchild = FVD.idfin AND FLK.nlevel = @levelusable
WHERE FV.yvar = @ayear
	AND FVD.idupb LIKE @idupb
	AND FV.adate <= @date
	AND FV.flagprevision = 'S'
	AND((ISNULL(FV.official,'N') = 'S' AND ISNULL(@officialvar,'N') = 'S') -- consideriamo solo le variazioni ufficiali
	  OR ISNULL(@officialvar,'N') = 'N')
	AND FV.idfinvarstatus = 5
	AND FV.variationkind <> 5
	AND FVD.amount < 0
	AND ((F.flag & 1 ) = @finpart_bit) AND F.ayear = @ayear
GROUP BY FVD.idupb,ISNULL(FLK.idparent,FVD.idfin)
	
CREATE TABLE #tot_varprev_acc_S (idfin int, total decimal(19,2))
INSERT INTO #tot_varprev_acc_S
(
	idfin,
	total
)
SELECT
	ISNULL(FLK.idparent,FVD.idfin),
	ISNULL(SUM(FVD.amount),0)
FROM finvardetail FVD
JOIN finvar FV
	ON FV.yvar = FVD.yvar
	AND FV.nvar = FVD.nvar
join fin F
	ON FVD.idfin = F.idfin
LEFT OUTER JOIN finlink FLK
	ON FLK.idchild = FVD.idfin AND FLK.nlevel = @levelusable
WHERE FV.yvar = @ayear
	AND FVD.idupb LIKE @idupb
	AND FV.adate <= @date
	AND FV.flagsecondaryprev = 'S'
	AND ((ISNULL(FV.official,'N') = 'S' AND ISNULL(@officialvar,'N') = 'S') -- consideriamo solo le variazioni ufficiali
	  OR ISNULL(@officialvar,'N') = 'N')
	AND FV.idfinvarstatus = 5
	AND FV.variationkind <> 5
	AND FVD.amount > 0
	AND ((F.flag & 1 ) = @finpart_bit) AND F.ayear = @ayear
GROUP BY FVD.idupb,ISNULL(FLK.idparent,FVD.idfin)
CREATE TABLE #tot_varprev_red_S (idfin int, total decimal(19,2))
INSERT INTO #tot_varprev_red_S
(
	idfin,
	total
)
SELECT
	ISNULL(FLK.idparent,FVD.idfin),
	-ISNULL(SUM(FVD.amount),0)
FROM finvardetail FVD
JOIN finvar FV
	ON FV.yvar = FVD.yvar
	AND FV.nvar = FVD.nvar
join fin F
	ON FVD.idfin = F.idfin
LEFT OUTER JOIN finlink FLK
	ON FLK.idchild = FVD.idfin AND FLK.nlevel = @levelusable
WHERE FV.yvar = @ayear
	AND FVD.idupb LIKE @idupb
	AND FV.adate <= @date
	AND FV.flagsecondaryprev = 'S'
	AND ((ISNULL(FV.official,'N') = 'S' AND ISNULL(@officialvar,'N') = 'S') -- consideriamo solo le variazioni ufficiali
	  OR ISNULL(@officialvar,'N') = 'N')
	AND FV.idfinvarstatus = 5
	AND FV.variationkind <> 5
	AND FVD.amount < 0
	AND ((F.flag & 1 ) = @finpart_bit) AND F.ayear = @ayear
GROUP BY FVD.idupb,ISNULL(FLK.idparent,FVD.idfin)

CREATE TABLE #mov_finphase_C (idfin int, total decimal(19,2))
CREATE TABLE #var_finphase_C (idfin int, total decimal(19,2))
CREATE TABLE #mov_finphase_R (idfin int, total decimal(19,2))
CREATE TABLE #var_finphase_acc_R (idfin int, total decimal(19,2))
CREATE TABLE #var_finphase_red_R (idfin int, total decimal(19,2))
CREATE TABLE #mov_maxphase_C (idfin int, total decimal(19,2))
CREATE TABLE #var_maxphase_C (idfin int, total decimal(19,2))
CREATE TABLE #mov_maxphase_R (idfin int, total decimal(19,2))
CREATE TABLE #var_maxphase_R (idfin int, total decimal(19,2))
IF (@finpart = 'E')
BEGIN
	INSERT INTO #mov_finphase_C
	(
		idfin,
		total
	)
	SELECT
		ISNULL(FLK.idparent,IY.idfin),
		ISNULL(SUM(IY.amount),0)
	FROM income I
	JOIN incomeyear IY
		ON IY.idinc = I.idinc
	JOIN incometotal IT
		ON IT.idinc = IY.idinc
		AND IT.ayear = IY.ayear
	LEFT OUTER JOIN finlink FLK
		ON FLK.idchild = IY.idfin AND FLK.nlevel = @levelusable
	WHERE I.adate <= @date
		AND IY.idupb LIKE @idupb
		AND IY.ayear = @ayear
		AND ( (IT.flag & 1) =0)-- Competenza
		AND I.nphase = @finphase
	GROUP BY IY.idupb,ISNULL(FLK.idparent,IY.idfin)
	INSERT INTO #var_finphase_C
	(
		idfin,
		total
	)
	SELECT 
		ISNULL(FLK.idparent,IY.idfin),
		ISNULL(SUM(IV.amount),0)
	FROM incomevar IV
	JOIN incomeyear IY
		ON IY.idinc = IV.idinc
	JOIN income I
		ON IY.idinc = I.idinc
	JOIN incometotal IT
		ON IT.idinc = IY.idinc
		AND IT.ayear = IY.ayear
	LEFT OUTER JOIN finlink FLK
		ON FLK.idchild = IY.idfin AND FLK.nlevel = @levelusable
	WHERE IV.yvar = @ayear
		AND IY.idupb LIKE @idupb
		AND IY.ayear = @ayear
		AND ( (IT.flag & 1) =0)-- Competenza
		AND I.nphase = @finphase
		AND IV.adate <= @date 
	GROUP BY IY.idupb,ISNULL(FLK.idparent,IY.idfin)
	INSERT INTO #mov_finphase_R
	(
		idfin,
		total
	)
	SELECT
		ISNULL(FLK.idparent,IY.idfin),
		ISNULL(SUM(IY.amount),0)
	FROM incomeyear IY
	JOIN income I
		ON I.idinc = IY.idinc
	JOIN incometotal IT
		ON IT.idinc = IY.idinc
		AND IT.ayear = IY.ayear
	LEFT OUTER JOIN finlink FLK
		ON FLK.idchild = IY.idfin AND FLK.nlevel = @levelusable
	WHERE IY.ayear = @ayear
		AND IY.idupb LIKE @idupb
		AND ( (IT.flag & 1) = 1)-- Residuo
		AND I.nphase = @finphase
		AND I.adate <= @date
	GROUP BY IY.idupb,ISNULL(FLK.idparent,IY.idfin)
	INSERT INTO #var_finphase_acc_R
	(
		idfin,
		total
	)
	SELECT 
		ISNULL(FLK.idparent,IY.idfin),
		ISNULL(SUM(IV.amount),0)
	FROM incomevar IV
	JOIN incomeyear IY
		ON IY.idinc = IV.idinc
	JOIN income I
		ON IY.idinc = I.idinc
	JOIN incometotal IT
		ON IT.idinc = IY.idinc
		AND IT.ayear = IY.ayear
	LEFT OUTER JOIN finlink FLK
		ON FLK.idchild = IY.idfin AND FLK.nlevel = @levelusable
	WHERE IV.yvar = @ayear
		AND IY.idupb LIKE @idupb
		AND IY.ayear = @ayear
		AND ( (IT.flag & 1) = 1)-- Residuo
		AND I.nphase = @finphase
		AND IV.adate <= @date 
		AND IV.amount > 0
	GROUP BY IY.idupb,ISNULL(FLK.idparent,IY.idfin)
	INSERT INTO #var_finphase_red_R
	(
		idfin,
		total
	)
	SELECT 
		ISNULL(FLK.idparent,IY.idfin),
		ISNULL(SUM(IV.amount),0)
	FROM incomevar IV
	JOIN incomeyear IY
		ON IY.idinc = IV.idinc
	JOIN income I
		ON IY.idinc = I.idinc
	JOIN incometotal IT
		ON IT.idinc = IY.idinc
		AND IT.ayear = IY.ayear
	LEFT OUTER JOIN finlink FLK
		ON FLK.idchild = IY.idfin AND FLK.nlevel = @levelusable
	WHERE IV.yvar = @ayear
		AND IY.idupb LIKE @idupb
		AND IY.ayear = @ayear
		AND ( (IT.flag & 1) = 1)-- Residuo
		AND I.nphase = @finphase
		AND IV.adate <= @date 
		AND IV.amount < 0
	GROUP BY IY.idupb,ISNULL(FLK.idparent,IY.idfin)
	INSERT INTO #mov_maxphase_C
	(
		idfin,
		total
	)
	SELECT
		ISNULL(FLK.idparent,HPV.idfin),
		SUM(HPV.amount)
	FROM historyproceedsview HPV
	LEFT OUTER JOIN finlink FLK
		ON FLK.idchild = HPV.idfin AND FLK.nlevel = @levelusable
	WHERE HPV.competencydate <= @date
		AND HPV.idupb LIKE @idupb
		AND HPV.flagarrear = 'C'
		AND HPV.ymov = @ayear
	GROUP BY HPV.idupb,ISNULL(FLK.idparent,HPV.idfin)
	INSERT INTO #mov_maxphase_R
	(
		idfin,
		total
	)
	SELECT
		ISNULL(FLK.idparent,HPV.idfin),
		SUM(HPV.amount)
	FROM historyproceedsview HPV
	LEFT OUTER JOIN finlink FLK
		ON FLK.idchild = HPV.idfin AND FLK.nlevel = @levelusable
	WHERE HPV.competencydate <= @date
		AND HPV.idupb LIKE @idupb
		AND HPV.flagarrear = 'R'
		AND HPV.ymov = @ayear
	GROUP BY HPV.idupb,ISNULL(FLK.idparent,HPV.idfin)
	IF (@cashvaliditykind <> 4)
	BEGIN
		INSERT INTO #var_maxphase_C
		(
			idfin,
			total
		)
		SELECT 
			ISNULL(FLK.idparent,HPV.idfin),
			SUM(IV.amount)
		FROM incomevar IV
		JOIN historyproceedsview HPV
			ON HPV.idinc = IV.idinc
		LEFT OUTER JOIN finlink FLK
			ON FLK.idchild = HPV.idfin AND FLK.nlevel = @levelusable
		WHERE IV.yvar = @ayear
			AND HPV.idupb LIKE @idupb
			AND IV.adate <= @date
			AND ( (HPV.totflag & 1) = 0)-- Competenza
			AND HPV.competencydate <= @date AND HPV.ymov = @ayear
		GROUP BY HPV.idupb,ISNULL(FLK.idparent,HPV.idfin)
	
		INSERT INTO #var_maxphase_R
		(
			idfin,
			total
		)
		SELECT 
			ISNULL(FLK.idparent,HPV.idfin),
			SUM(IV.amount)
		FROM incomevar IV
		JOIN historyproceedsview HPV
			ON HPV.idinc = IV.idinc
		LEFT OUTER JOIN finlink FLK
			ON FLK.idchild = HPV.idfin AND FLK.nlevel = @levelusable
		WHERE IV.yvar = @ayear
			AND HPV.idupb LIKE @idupb
			AND IV.adate <= @date
			AND ( (HPV.totflag & 1) = 1)-- Residuo
			AND HPV.competencydate <= @date AND HPV.ymov = @ayear
		GROUP BY HPV.idupb,ISNULL(FLK.idparent,HPV.idfin)
	END
END
IF @finpart = 'S'
BEGIN
	INSERT INTO #mov_finphase_C
	(
		idfin,
		total
	)
	SELECT
		ISNULL(FLK.idparent,EY.idfin),
		ISNULL(SUM(EY.amount),0)
	FROM expense E
	JOIN expenseyear EY
		ON EY.idexp = E.idexp
	JOIN expensetotal ET
		ON ET.idexp = EY.idexp
		AND ET.ayear = EY.ayear
	LEFT OUTER JOIN finlink FLK
		ON FLK.idchild = EY.idfin AND FLK.nlevel = @levelusable
	WHERE E.adate <= @date
		AND EY.idupb LIKE @idupb
		AND EY.ayear = @ayear
		AND ( (ET.flag & 1) = 0) -- Competenza
		AND E.nphase = @finphase
	GROUP BY EY.idupb,ISNULL(FLK.idparent,EY.idfin)
	INSERT INTO #var_finphase_C
	(
		idfin,
		total
	)
	SELECT 
		ISNULL(FLK.idparent,EY.idfin),
		ISNULL(SUM(EV.amount),0)
	FROM expensevar EV
	JOIN expenseyear EY
		ON EY.idexp = EV.idexp
	JOIN expense E
		ON EY.idexp = E.idexp
	JOIN expensetotal ET
		ON ET.idexp = EY.idexp
		AND ET.ayear = EY.ayear
	LEFT OUTER JOIN finlink FLK
		ON FLK.idchild = EY.idfin AND FLK.nlevel = @levelusable
	WHERE EV.yvar = @ayear
		AND EY.idupb LIKE @idupb
		AND EY.ayear = @ayear
		AND ( (ET.flag & 1) = 0) -- Competenza
		AND E.nphase = @finphase
		AND EV.adate <= @date 
	GROUP BY EY.idupb,ISNULL(FLK.idparent,EY.idfin)
	INSERT INTO #mov_finphase_R
	(
		idfin,
		total
	)
	SELECT
		ISNULL(FLK.idparent,EY.idfin),
		ISNULL(SUM(EY.amount),0)
	FROM expense E
	JOIN expenseyear EY
		ON EY.idexp = E.idexp
	JOIN expensetotal ET
		ON ET.idexp = EY.idexp
		AND ET.ayear = EY.ayear
	LEFT OUTER JOIN finlink FLK
		ON FLK.idchild = EY.idfin AND FLK.nlevel = @levelusable
	WHERE E.adate <= @date
		AND EY.idupb LIKE @idupb
		AND EY.ayear = @ayear
		AND ( (ET.flag & 1) = 1)
		AND E.nphase = @finphase
	GROUP BY EY.idupb,ISNULL(FLK.idparent,EY.idfin)
	INSERT INTO #var_finphase_acc_R
	(
		idfin,
		total
	)
	SELECT 
		ISNULL(FLK.idparent,EY.idfin),
		ISNULL(SUM(EV.amount),0)
	FROM expensevar EV
	JOIN expenseyear EY
		ON EY.idexp = EV.idexp
	JOIN expense E
		ON EY.idexp = E.idexp
	JOIN expensetotal ET
		ON ET.idexp = EY.idexp
		AND ET.ayear = EY.ayear
	LEFT OUTER JOIN finlink FLK
		ON FLK.idchild = EY.idfin AND FLK.nlevel = @levelusable
	WHERE EV.yvar = @ayear
		AND EY.idupb LIKE @idupb
		AND EY.ayear = @ayear
		AND ( (ET.flag & 1) = 1) -- Residuo
		AND E.nphase = @finphase
		AND EV.adate <= @date 
		AND EV.amount > 0
	GROUP BY EY.idupb,ISNULL(FLK.idparent,EY.idfin)
	INSERT INTO #var_finphase_red_R
	(
		idfin,
		total
	)
	SELECT 
		ISNULL(FLK.idparent,EY.idfin),
		ISNULL(SUM(EV.amount),0)
	FROM expensevar EV
	JOIN expenseyear EY
		ON EY.idexp = EV.idexp
	JOIN expense E
		ON EY.idexp = E.idexp
	JOIN expensetotal ET
		ON ET.idexp = EY.idexp
		AND ET.ayear = EY.ayear
	LEFT OUTER JOIN finlink FLK
		ON FLK.idchild = EY.idfin AND FLK.nlevel = @levelusable
	WHERE EV.yvar = @ayear
		AND EY.idupb LIKE @idupb
		AND EY.ayear = @ayear
		AND ( (ET.flag & 1) = 1) -- Residuo
		AND E.nphase = @finphase
		AND EV.adate <= @date 
		AND EV.amount < 0
	GROUP BY EY.idupb,ISNULL(FLK.idparent,EY.idfin)
	INSERT INTO #mov_maxphase_C
	(
		idfin,
		total
	)
	SELECT
		ISNULL(FLK.idparent,HPV.idfin),
		SUM(HPV.amount)
	FROM historypaymentview HPV
	LEFT OUTER JOIN finlink FLK
		ON FLK.idchild = HPV.idfin AND FLK.nlevel = @levelusable
	WHERE HPV.competencydate <= @date
		AND HPV.idupb LIKE @idupb
		AND ( (HPV.totflag & 1) = 0)-- Competenza
		AND HPV.ymov = @ayear
	GROUP BY HPV.idupb,ISNULL(FLK.idparent,HPV.idfin)
	INSERT INTO #mov_maxphase_R
	(
		idfin,
		total
	)
	SELECT
		ISNULL(FLK.idparent,HPV.idfin),
		SUM(HPV.amount)
	FROM historypaymentview HPV
	LEFT OUTER JOIN finlink FLK
		ON FLK.idchild = HPV.idfin AND FLK.nlevel = @levelusable
	WHERE HPV.competencydate <= @date
		AND HPV.idupb LIKE @idupb	
		AND ( (HPV.totflag & 1) = 1) -- Residuo
		AND HPV.ymov = @ayear
	GROUP BY HPV.idupb,ISNULL(FLK.idparent,HPV.idfin)
	IF (@cashvaliditykind <> 4)
	BEGIN
		INSERT INTO #var_maxphase_C
		(
			idfin,
			total
		)
		SELECT 
			ISNULL(FLK.idparent,HPV.idfin),
			SUM(EV.amount)
		FROM expensevar EV
		JOIN historypaymentview HPV
			ON HPV.idexp = EV.idexp
		LEFT OUTER JOIN finlink FLK
			ON FLK.idchild = HPV.idfin AND FLK.nlevel = @levelusable
		WHERE EV.yvar = @ayear
			AND  HPV.idupb LIKE @idupb
			AND EV.adate <= @date
			AND ( (HPV.totflag & 1) = 0)--Competenza
			AND HPV.competencydate <= @date AND HPV.ymov = @ayear
		GROUP BY  HPV.idupb,ISNULL(FLK.idparent,HPV.idfin)
	
		INSERT INTO #var_maxphase_R
		(
			idfin,
			total
		)
		SELECT 
			ISNULL(FLK.idparent,HPV.idfin),
			SUM(EV.amount)
		FROM expensevar EV
		JOIN historypaymentview HPV
			ON HPV.idexp = EV.idexp
		LEFT OUTER JOIN finlink FLK
			ON FLK.idchild = HPV.idfin AND FLK.nlevel = @levelusable
		WHERE EV.yvar = @ayear
			AND  HPV.idupb LIKE @idupb
			AND EV.adate <= @date
			AND ( (HPV.totflag & 1) = 1)--Residuo
			AND HPV.competencydate <= @date AND HPV.ymov = @ayear
		GROUP BY  HPV.idupb,ISNULL(FLK.idparent,HPV.idfin)
	END
END
UPDATE #balance
SET var_prev_m_acc =
ISNULL(
	(SELECT SUM(#tot_varprev_acc_M.total) FROM #tot_varprev_acc_M
	WHERE #tot_varprev_acc_M.idfin = #balance.idfin)
, 0),
var_prev_m_red = 
ISNULL(
	(SELECT SUM(#tot_varprev_red_M.total) FROM #tot_varprev_red_M
	WHERE #tot_varprev_red_M.idfin = #balance.idfin),
0),
var_prev_s_acc =
ISNULL(
	(SELECT SUM(#tot_varprev_acc_S.total) FROM #tot_varprev_acc_S
	WHERE #tot_varprev_acc_S.idfin = #balance.idfin),
0),
var_prev_s_red =
ISNULL(
	(SELECT SUM(#tot_varprev_red_S.total) FROM #tot_varprev_red_S
	WHERE #tot_varprev_red_S.idfin = #balance.idfin), 0),
mov_finphase_C =
ISNULL(
	(SELECT SUM(#mov_finphase_C.total) FROM #mov_finphase_C
	WHERE #mov_finphase_C.idfin = #balance.idfin)
, 0),
var_finphase_C =
ISNULL(
	(SELECT SUM(#var_finphase_C.total) FROM #var_finphase_C
	WHERE #var_finphase_C.idfin = #balance.idfin)
, 0),
mov_maxphase_C =
ISNULL(
	(SELECT SUM(#mov_maxphase_C.total) FROM #mov_maxphase_C
	WHERE #mov_maxphase_C.idfin = #balance.idfin)
, 0),
var_maxphase_C =
ISNULL(
	(SELECT SUM(#var_maxphase_C.total) FROM #var_maxphase_C
	WHERE #var_maxphase_C.idfin = #balance.idfin)
, 0),
mov_finphase_R =
ISNULL(
	(SELECT SUM(#mov_finphase_R.total) FROM #mov_finphase_R
	WHERE #mov_finphase_R.idfin = #balance.idfin)
, 0),
var_finphase_acc_R =
ISNULL(
	(SELECT SUM(#var_finphase_acc_R.total) FROM #var_finphase_acc_R
	WHERE #var_finphase_acc_R.idfin = #balance.idfin)
, 0),
var_finphase_red_R =
ISNULL(
	(SELECT SUM(#var_finphase_red_R.total) FROM #var_finphase_red_R
	WHERE #var_finphase_red_R.idfin = #balance.idfin)
, 0),
mov_maxphase_R =
ISNULL(
	(SELECT SUM(#mov_maxphase_R.total) FROM #mov_maxphase_R
        WHERE #mov_maxphase_R.idfin = #balance.idfin)
, 0),
var_maxphase_R =
ISNULL(
	(SELECT SUM(#var_maxphase_R.total) FROM #var_maxphase_R
	WHERE #var_maxphase_R.idfin = #balance.idfin)
, 0)
DECLARE @supposed_cash_jan01 decimal(19,2)
DECLARE @cash_jan01 decimal(19,2)
DECLARE @supposed_amm_jan01 decimal(19,2)
DECLARE @var_ff_acc decimal(19,2)
DECLARE @var_ff_red decimal(19,2)
DECLARE @var_aa_acc decimal(19,2)
DECLARE @var_aa_red decimal(19,2)
DECLARE @fin_kind tinyint
SELECT  @fin_kind = fin_kind
FROM    config
WHERE   ayear = @ayear
print   @fin_kind
-- Competenza Pura
IF (@fin_kind = 1)
BEGIN 
	IF (@finpart = 'E')
	BEGIN   
		IF (@infoadvance <> 'N')
		BEGIN
			IF (@aa_jan01 > 0)
			BEGIN
				SET @supposed_amm_jan01 = @supposed_aa_jan01
				IF (@aa_jan01 - @supposed_aa_jan01) >0 
				BEGIN
					SET @var_aa_acc = (@aa_jan01 - @supposed_aa_jan01)
					SET @var_aa_red = 0
				END
				ELSE
				BEGIN
					SET @var_aa_acc = 0
					SET @var_aa_red = (@aa_jan01 - @supposed_aa_jan01)
				END
			END
		ELSE
		BEGIN
			SET @supposed_amm_jan01 = 0
			SET @var_aa_acc = 0
			SET @var_aa_red = 0
		END
		-- Inserisce la riga relativa all'avanzo di amministrazione
		INSERT INTO #balance
		(
			idfin, codefin, description, 
			initialprevision,
			var_prev_M_acc,
			var_prev_M_red
		)
		VALUES
		(
			@idavanzoamm , ' ', 'Avanzo di Amministrazione', ---avanzo amministrazione 0
			@supposed_amm_jan01,
			@var_aa_acc,
			@var_aa_red)
	END
	
	SELECT
		CASE
			WHEN #balance.idfin = @idavanzoamm   ---avanzo amministrazione 0
			THEN #balance.codefin
			ELSE fin.codefin
		END AS 'Codice Bilancio',
		CASE
			WHEN #balance.idfin = @idavanzoamm   ---avanzo amministrazione 0
			THEN #balance.description
			ELSE fin.title
		END AS 'Denominazione',
		initialprevision AS 'Prev. di competenza iniziale', 
		var_prev_M_acc AS 'Var. aumento prev. Competenza',
		- var_prev_M_red AS 'Var. dimin. prev. Competenza',
		(initialprevision + var_prev_M_acc + var_prev_M_red)  AS 'Prev. Competenza Definitiva',
		(mov_maxphase_C + var_maxphase_C) AS 'Accertamenti riscossi',
		(mov_finphase_C + var_finphase_C - mov_maxphase_C - var_maxphase_C) AS 'Accertamenti da riscuotere',
		(mov_finphase_C + var_finphase_C) AS 'Totale somme accertate',
		CASE #balance.idfin
			WHEN @idavanzoamm  THEN NULL
			ELSE (initialprevision + var_prev_M_acc + var_prev_M_red - mov_finphase_C - var_finphase_C)
		END AS 'Differenza rispetto alle previsioni',
		mov_finphase_R AS 'Residui Attivi Iniziali' ,
		(mov_maxphase_R + var_maxphase_R) AS 'Residui Attivi Riscossi',
		(mov_finphase_R + var_finphase_acc_R + var_finphase_red_R - mov_maxphase_R - var_maxphase_R) AS 'Residui Attivi da riscuotere',
		(mov_finphase_R + var_finphase_acc_R + var_finphase_red_R) AS 'Totale Residui Attivi',
		var_finphase_acc_R AS 'Var. aumento residui attivi',
		- var_finphase_red_R AS 'Var. diminuzione residui attivi' ,
		(var_finphase_acc_R + var_finphase_red_R) AS 'Totale Variazioni Residui Attivi',
		(mov_finphase_C + var_finphase_C - mov_maxphase_C - var_maxphase_C + mov_finphase_R + var_finphase_acc_R + var_finphase_red_R  - mov_maxphase_R - var_maxphase_R) AS 'Tot. res. attivi a fine esercizio'
	FROM #balance
	LEFT OUTER JOIN fin
		ON fin.idfin = #balance.idfin
	ORDER BY #balance.codefin ASC
END
	IF (@finpart = 'S')
	BEGIN
		SELECT
			fin.codefin AS 'Codice Bilancio',
			fin.title AS 'Denominazione',
			initialprevision AS 'Prev. di competenza iniziale', 
			var_prev_M_acc  AS 'Var. aumento prev. competenza',
			- var_prev_M_red  AS 'Var. dimin. prev. competenza',
			(initialprevision + var_prev_M_acc + var_prev_M_red)  AS 'Prev. competenza definitiva',
			(mov_maxphase_C + var_maxphase_C) AS 'Somme impegnate pagate',
			(mov_finphase_C + var_finphase_C - mov_maxphase_C - var_maxphase_C) AS 'Somme impegnate da pagare',
			(mov_finphase_C + var_finphase_C) AS 'Totale somme impegnate',
			(initialprevision + var_prev_M_acc + var_prev_M_red - mov_finphase_C-var_finphase_C) AS 'Differenza rispetto alle previsioni',
			mov_finphase_R AS 'Residui passivi iniziali' ,
			(mov_maxphase_R + var_maxphase_R) AS 'Residui passivi riscossi',
			(mov_finphase_R + var_finphase_acc_R + var_finphase_red_R - mov_maxphase_R - var_maxphase_R) AS 'Residui Passivi da riscuotere',
			(mov_finphase_R + var_finphase_acc_R + var_finphase_red_R) AS 'Totale residui passivi',
			var_finphase_acc_R  AS 'Var. residui passivi in aumento',
			-var_finphase_red_R  AS 'Var. residui passivi in diminuzione',
			(var_finphase_acc_R + var_finphase_red_R) AS 'Totale variazioni residui passivi',
			(mov_finphase_C + var_finphase_C - mov_maxphase_C - var_maxphase_C + mov_finphase_R + var_finphase_acc_R + var_finphase_red_R - mov_maxphase_R - var_maxphase_R) AS 'Tot. res. passivi a fine esercizio'
		FROM #balance
		LEFT OUTER JOIN fin
			ON fin.idfin = #balance.idfin
		ORDER BY #balance.codefin ASC
	END
END 
-- Cassa Pura
IF @fin_kind = 2
BEGIN 
	IF @finpart = 'E'
	BEGIN 
		IF @infoadvance <> 'N'
		BEGIN
			IF @ff_jan01 > 0
			BEGIN
				SET @supposed_cash_jan01 =@supposed_ff_jan01
				SET @cash_jan01 =@ff_jan01
				IF (@ff_jan01 - @supposed_ff_jan01) >0 
					BEGIN
					SET @var_ff_acc = (@ff_jan01 - @supposed_ff_jan01)
					SET @var_ff_red = 0
	      		 	END
				ELSE
				BEGIN
					SET @var_ff_acc = 0
					SET @var_ff_red = (@ff_jan01 - @supposed_ff_jan01)
				END
			END
			ELSE
			BEGIN
			  	SET @supposed_cash_jan01 =0
				SET @cash_jan01 =0
			  	SET @var_ff_acc =0
	  		 	SET @var_ff_red =0
			END
			INSERT INTO #balance
			(
				idfin, codefin, description,
				initialprevision, var_prev_M_acc, var_prev_M_red, mov_maxphase_C) -- Fondo cassa effettivo nella colonna  Totale Riscossioni  
			VALUES
			(
				@idavanzocassa , ' ', 'Avanzo di Cassa',
				@supposed_cash_jan01, @var_ff_acc, @var_ff_red, @cash_jan01
			)
		END
		SELECT  
			CASE
				WHEN #balance.idfin = @idavanzocassa
				THEN #balance.codefin
				ELSE fin.codefin
			END AS 'Codice Bilancio',
			CASE
				WHEN #balance.idfin = @idavanzocassa
				THEN #balance.description
				ELSE fin.title
			END AS 'Denominazione',
			initialprevision AS 'Prev. di cassa iniziale', 
			var_prev_M_acc AS 'Var. aumento prev. cassa',
			-var_prev_M_red AS 'Var. dimin. prev. cassa',
			(initialprevision + var_prev_M_acc + var_prev_M_red) AS 'Prev. cassa definitiva',
			(mov_finphase_C + var_finphase_C) AS 'Totale Somme Accertate',
			CASE #balance.idfin
				WHEN @idavanzocassa   THEN mov_maxphase_C
				ELSE (mov_maxphase_C + var_maxphase_C + mov_maxphase_R + var_maxphase_R)
			END AS 'Totale Riscossioni',
			CASE #balance.idfin 
				WHEN @idavanzocassa   THEN NULL
				ELSE (initialprevision + var_prev_M_acc + var_prev_M_red) -  (mov_maxphase_C + var_maxphase_C + mov_maxphase_R + var_maxphase_R)
			END AS 'Differenza rispetto alle previsioni'
		FROM #balance
		LEFT OUTER JOIN fin
			ON fin.idfin = #balance.idfin
		ORDER BY #balance.codefin ASC
	END
	IF (@finpart = 'S')
	BEGIN
		SELECT
			fin.codefin AS 'Codice Bilancio',
			fin.title AS 'Denominazione',
			initialprevision AS 'Prev. di cassa iniziale', 
			var_prev_M_acc AS 'Var. aumento prev. cassa',
			-var_prev_M_red AS 'Var. dimin. prev. cassa',
			(initialprevision + var_prev_M_acc + var_prev_M_red) AS 'Prev. cassa definitiva',
			(mov_finphase_C + var_finphase_C) AS 'Totale Somme Impegnate',
			(mov_maxphase_C + var_maxphase_C + mov_maxphase_R + var_maxphase_R) AS 'Totale Pagamenti',
			(initialprevision + var_prev_M_acc + var_prev_M_red) - (mov_maxphase_C + var_maxphase_C + mov_maxphase_R + var_maxphase_R) AS 'Differ. rispetto alle previsioni'	 
		FROM #balance
		LEFT OUTER JOIN fin
			ON fin.idfin = #balance.idfin
		ORDER BY #balance.codefin ASC
	END
END
-- Compentenza e Cassa
IF (@fin_kind = 3)
BEGIN 
	IF (@finpart = 'E')
	BEGIN
		IF @infoadvance <> 'N'
		BEGIN
			IF (@aa_jan01 > 0)
			BEGIN
				SET @supposed_amm_jan01 =@supposed_aa_jan01
				IF (@aa_jan01 - @supposed_aa_jan01) >0 
				BEGIN
					SET @var_aa_acc = (@aa_jan01 - @supposed_aa_jan01)
					SET @var_aa_red = 0
				END
				ELSE
				BEGIN
					SET @var_aa_acc = 0
					SET @var_aa_red = (@aa_jan01 - @supposed_aa_jan01)
				END
			END
			ELSE
			BEGIN
				SET @supposed_amm_jan01 = 0
				SET @var_aa_acc = 0
				SET @var_aa_red = 0
			END
			INSERT INTO #balance
			(
				idfin, codefin, description,
				initialprevision, var_prev_M_acc, var_prev_M_red
			)
			VALUES
			(
				@idavanzoamm , ' ', 'Avanzo di Amministrazione',   ---avanzo amministrazione 0
				@supposed_amm_jan01, @var_aa_acc, @var_aa_red
			)
			IF (@ff_jan01 > 0)
			BEGIN
				SET @supposed_cash_jan01 =@supposed_ff_jan01
				SET @cash_jan01 =@ff_jan01
				IF (@ff_jan01 - @supposed_ff_jan01) >0 
				BEGIN
					SET @var_ff_acc = (@ff_jan01 - @supposed_ff_jan01)
					SET @var_ff_red = 0
				END
				ELSE
				BEGIN
					SET @var_ff_acc = 0
					SET @var_ff_red = (@ff_jan01 - @supposed_ff_jan01)
				END
			END
			ELSE
			BEGIN
				SET @supposed_cash_jan01 = 0
				SET @cash_jan01 = 0
				SET @var_ff_acc = 0
				SET @var_ff_red = 0
			END
			INSERT INTO #balance
			(
				idfin, codefin, description,
				secondaryprev, var_prev_S_acc, var_prev_S_red, mov_maxphase_C
			) --Fondo cassa effettivo nella colonna  Totale Riscossioni
			VALUES
			(
				@idavanzocassa  , ' ', 'Avanzo di Cassa',  ---Avanzo di cassa null
				@supposed_cash_jan01, @var_ff_acc, @var_ff_red, @cash_jan01
			)
		END
		SELECT
			CASE
				WHEN #balance.idfin = @idavanzoamm  THEN #balance.codefin
				WHEN #balance.idfin = @idavanzocassa   THEN #balance.codefin
				ELSE fin.codefin
			END AS 'Codice Bilancio',
			CASE
				WHEN #balance.idfin = @idavanzoamm  THEN #balance.description
				WHEN #balance.idfin = @idavanzocassa   THEN #balance.description
				ELSE fin.title
			END AS 'Denominazione',
			initialprevision AS 'Prev. competenza iniziale', 
			var_prev_M_acc AS 'Var. aumento prev. competenza',
			-var_prev_M_red AS 'Var. dimin. prev. competenza',
			(initialprevision + var_prev_M_acc + var_prev_M_red)  AS 'Prev. competenza definitiva',
			CASE #balance.idfin
				WHEN @idavanzocassa  THEN NULL
				ELSE (mov_maxphase_C+var_maxphase_C)
			END AS 'Accertamenti riscossi',
			CASE #balance.idfin
				WHEN @idavanzocassa   THEN NULL
				ELSE (mov_finphase_C+var_finphase_C - mov_maxphase_C - var_maxphase_C)
			END AS 'Accertamenti da riscuotere',
			(mov_finphase_C + var_finphase_C) AS 'Totale somme accertate',
			CASE #balance.idfin
				WHEN @idavanzocassa   THEN NULL
				ELSE (initialprevision + var_prev_M_acc + var_prev_M_red - mov_finphase_C-var_finphase_C)
			END AS 'Differenza rispetto alle previsioni (comp.)',
			secondaryprev AS 'Prev. cassa iniziale', 
			var_prev_S_acc AS 'Var. aumento prev. cassa',
			-var_prev_S_red AS 'Var. dimin. prev. cassa',
			(secondaryprev + var_prev_S_acc + var_prev_S_red) AS 'Prev. cassa definitiva' ,
			CASE #balance.idfin
				WHEN @idavanzocassa   THEN mov_maxphase_C
				ELSE (mov_maxphase_C + var_maxphase_C + mov_maxphase_R + var_maxphase_R)
			END AS 'Totale Riscossioni',
			CASE #balance.idfin
				WHEN @idavanzocassa   THEN NULL
				ELSE (secondaryprev + var_prev_S_acc + var_prev_S_red)- (mov_maxphase_C + var_maxphase_C + mov_maxphase_R + var_maxphase_R)
			END AS 'Differenza rispetto alle previsioni (cassa)',
			mov_finphase_R AS 'Residui Attivi Iniziali' ,
			(mov_maxphase_R + var_maxphase_R) AS 'Residui Attivi Riscossi',
			(mov_finphase_R + var_finphase_acc_R + var_finphase_red_R - mov_maxphase_R - var_maxphase_R) AS 'Residui Attivi da riscuotere',
			(mov_finphase_R + var_finphase_acc_R + var_finphase_red_R) AS 'Totale Residui Attivi',
			var_finphase_acc_R  AS 'Var. residui attivi in aumento',
			-var_finphase_red_R  AS 'Var. residui attivi in diminuzione',
			(var_finphase_acc_R + var_finphase_red_R) AS 'Totale Variazioni Residui Attivi',
			CASE #balance.idfin
				WHEN @idavanzocassa  THEN NULL
				ELSE (mov_finphase_C + var_finphase_C - mov_maxphase_C - var_maxphase_C + mov_finphase_R + var_finphase_acc_R + var_finphase_red_R - mov_maxphase_R - var_maxphase_R)
			END AS 'Tot. res. attivi a fine esercizio'
		FROM #balance
		LEFT OUTER JOIN fin
			ON fin.idfin = #balance.idfin
		ORDER BY #balance.codefin ASC
	END
	IF(@finpart = 'S')
	BEGIN
		SELECT
			fin.codefin AS 'Codice Bilancio',
			fin.title AS 'Denominazione',
			initialprevision AS 'Prev. competenza iniziale', 
			var_prev_M_acc AS 'Var. aumento prev. competenza',
			-var_prev_M_red AS 'Var. dimin. prev. competenza',
			(initialprevision + var_prev_M_acc + var_prev_M_red)  AS 'Prev. competenza definitiva',
			(mov_maxphase_C + var_maxphase_C) AS 'Somme impegnate pagate',
			(mov_finphase_C + var_finphase_C - mov_maxphase_C - var_maxphase_C) AS 'Somme impegnate da pagare',
			(mov_finphase_C + var_finphase_C) AS 'Totale somme impegnate',
			(initialprevision + var_prev_M_acc + var_prev_M_red - mov_finphase_C-var_finphase_C) AS 'Differenza rispetto alle previsioni (comp.)',	 
			secondaryprev AS 'Prev. cassa iniziale', 
			var_prev_S_acc AS 'Var. aumento prev. cassa',
			-var_prev_S_red AS 'Var. dimin. prev. cassa',
			(secondaryprev + var_prev_S_acc - var_prev_S_red)  AS 'Prev. cassa definitiva',
			(mov_maxphase_C + var_maxphase_C + mov_maxphase_R + var_maxphase_R) AS 'Totale Pagamenti',
			(secondaryprev + var_prev_S_acc + var_prev_S_red)- (mov_maxphase_C + var_maxphase_C + mov_maxphase_R + var_maxphase_R) AS 'Differenza rispetto alle previsioni (cassa)',   	
			mov_finphase_R AS 'Residui Passivi Iniziali' ,
			(mov_maxphase_R + var_maxphase_R) AS 'Residui Passivi Pagati',
			(mov_finphase_R + var_finphase_acc_R + var_finphase_red_R - mov_maxphase_R - var_maxphase_R) AS 'Residui Passivi da pagare',
			(mov_finphase_R + var_finphase_acc_R + var_finphase_red_R) AS 'Totale Residui Passivi',
			var_finphase_acc_R AS 'Var. residui passivi in aumento',
			-var_finphase_red_R AS 'Var. residui passivi in diminuzione',
			(var_finphase_acc_R + var_finphase_red_R) AS 'Totale Variazioni Residui Passivi',
			(mov_finphase_C + var_finphase_C - mov_maxphase_C - var_maxphase_C + mov_finphase_R + var_finphase_acc_R + var_finphase_red_R - mov_maxphase_R - var_maxphase_R) AS 'Tot. res. passivi a fine esercizio'
		FROM #balance
		LEFT OUTER JOIN fin
			ON fin.idfin = #balance.idfin
		ORDER BY #balance.codefin ASC
	END
END
END


GO

print '[exp_consuntivo] OK'

