		INSERT INTO #invoice_old (idinvkind, yinv, ninv, movkind, amountlinked)
		SELECT invoice.idinvkind, invoice.yinv, invoice.ninv, incomeinvoice.movkind, 
		SUM(proceedsemitted.amount)
