if object_id('[trigger_i_apfinancialactivity]') is not null
	drop TRIGGER [trigger_i_apfinancialactivity]
go
CREATE   TRIGGER [trigger_i_apfinancialactivity] ON [apfinancialactivity] FOR INSERT
AS BEGIN
IF (@@ROWCOUNT = 0) RETURN
DECLARE @nrowinserted int
SET @nrowinserted = ISNULL((SELECT COUNT(*) FROM inserted),0)
IF (@nrowinserted > 1)
BEGIN
	CREATE TABLE #apfinancialactivity (idapfinancialactivity int, nlevel tinyint)
	
	INSERT INTO #apfinancialactivity (idapfinancialactivity, nlevel)
	SELECT idapfinancialactivity, nlevel FROM inserted
	
	INSERT INTO apfinancialactivitylink (idchild, nlevel, idparent)
	SELECT idapfinancialactivity, nlevel, idapfinancialactivity
	FROM #apfinancialactivity
	
	WHILE(@@ROWCOUNT > 0)
	BEGIN
		INSERT INTO apfinancialactivitylink (idchild, nlevel, idparent)
		SELECT IL.idchild, (I.nlevel - 1), I.paridapfinancialactivity
		FROM apfinancialactivitylink IL
		JOIN apfinancialactivity I
		ON IL.idparent = I.idapfinancialactivity
		WHERE IL.nlevel > 1
		AND NOT EXISTS(SELECT * FROM apfinancialactivitylink IL2 WHERE IL2.idchild = IL.idchild AND IL2.nlevel = (IL.nlevel - 1))
		AND EXISTS(SELECT * FROM #apfinancialactivity WHERE #apfinancialactivity.idapfinancialactivity = IL.idchild)
	END
END
ELSE
BEGIN
	DECLARE @idapfinancialactivity int
	DECLARE @nlevel tinyint
	DECLARE @paridapfinancialactivity int
	SELECT @idapfinancialactivity = idapfinancialactivity, @nlevel = nlevel, @paridapfinancialactivity = paridapfinancialactivity FROM inserted
	INSERT INTO apfinancialactivitylink (idchild, nlevel, idparent)
	VALUES(@idapfinancialactivity, @nlevel, @idapfinancialactivity)
	DECLARE @currlevel tinyint
	SET @currlevel = @nlevel - 1
	DECLARE @currpar int
	SET @currpar = @paridapfinancialactivity
	WHILE (@currlevel >= 1)
	BEGIN
		INSERT INTO apfinancialactivitylink (idchild, nlevel, idparent)
		VALUES(@idapfinancialactivity, @currlevel, @currpar)
		SET @currpar = (SELECT paridapfinancialactivity FROM apfinancialactivity WHERE idapfinancialactivity = @currpar)
		SET @currlevel = @currlevel - 1
	END
END
END



GO

print '[trigger_i_apfinancialactivity] OK'

