if object_id('[rebuild_currentfloatfund]') is not null
	drop PROCEDURE [rebuild_currentfloatfund]
go

CREATE   PROCEDURE [rebuild_currentfloatfund]
(
	@ayear int = NULL
)
AS BEGIN
DECLARE @startfloatfund decimal(19,2)
DECLARE @previsionkind char(1)
DECLARE @secprevisionkind char(1)
DECLARE @fin_kind tinyint
DECLARE @idfinincomesurplus int
DECLARE @locked char(1)
DECLARE @maxexpensephase tinyint
SELECT  @maxexpensephase = MAX(nphase) FROM expensephase
DECLARE @maxincomephase tinyint
SELECT  @maxincomephase = MAX(nphase) FROM incomephase

IF (@ayear IS NOT NULL)
BEGIN
	DELETE FROM currentcashtotal WHERE ayear = @ayear
	set @locked='N'
	SELECT @locked = locked from surplus where ayear = @ayear
	SET @locked= ISNULL(@locked,'N')
	SELECT @fin_kind = ISNULL(fin_kind,0), @idfinincomesurplus = idfinincomesurplus FROM config WHERE ayear = @ayear
	--calcola lo START FLOAT FUND
	IF ((@idfinincomesurplus IS NOT NULL) AND (@idfinincomesurplus <> 0))
	BEGIN
		IF (@fin_kind = 3)
		BEGIN
			SET @startfloatfund =
			ISNULL(
				(SELECT 
				SUM(finyear.secondaryprev) 
				FROM finyear
				WHERE finyear.idfin = @idfinincomesurplus)
			,0)
			SELECT @startfloatfund = 
			@startfloatfund +
			ISNULL(
				(SELECT SUM(d.amount) 
				FROM finvardetail d
				JOIN finvar v
					ON v.yvar = d.yvar
					AND v.nvar = d.nvar
				WHERE (v.flagsecondaryprev = 'S') AND (d.idfin = @idfinincomesurplus)
				       AND (v.idfinvarstatus = 5))
			,0)
		END
		IF (@fin_kind = 2)
		BEGIN
			SET @startfloatfund =
			ISNULL(
				(SELECT SUM(finyear.prevision)
				FROM finyear
					WHERE finyear.idfin = @idfinincomesurplus)
			,0)
	
			SELECT @startfloatfund = 
			@startfloatfund +
				ISNULL(
					(SELECT SUM(d.amount) 
					FROM finvardetail d
					JOIN finvar v
						ON v.yvar = d.yvar
						AND v.nvar = d.nvar
					WHERE (v.flagprevision = 'S') AND (d.idfin = @idfinincomesurplus)
					      AND (v.idfinvarstatus = 5))
				,0)
		END
	END
	ELSE
	BEGIN
		-- Per ulteriori dettagli in merito a questa modifica leggere la Documentazione del task n.4077
		SELECT @startfloatfund = ISNULL(startfloatfund,0) 
		FROM surplus WHERE ayear = @ayear
	END
	
	INSERT INTO currentcashtotal VALUES(@ayear,ISNULL(@startfloatfund,0))
	
	
	IF ((@locked='S') OR (SELECT COUNT(*) FROM fin WHERE ayear = @ayear) = 0 )
	BEGIN
		UPDATE  currentcashtotal
			SET currentfloatfund =  (SELECT
			 (ISNULL(startfloatfund,0) + 
			  ISNULL(competencyproceeds,0) + 
			  ISNULL(residualproceeds,0) - 
			  ISNULL(competencypayments,0) - 
			  ISNULL(residualpayments,0))
			FROM surplus WHERE ayear = @ayear)
		WHERE ayear = @ayear
	END
	ELSE
	BEGIN
		UPDATE currentcashtotal
			SET currentfloatfund =
			currentfloatfund +
			ISNULL(
				(SELECT SUM(i.curramount)
				FROM incometotal i 
				JOIN incomelast IL
					ON IL.idinc = i.idinc
				JOIN proceeds p
					ON p.kpro=IL.kpro
				JOIN proceedstransmission pt
					ON p.kproceedstransmission=pt.kproceedstransmission
				WHERE i.ayear = @ayear)
			,0)
			WHERE ayear = @ayear
		UPDATE currentcashtotal SET currentfloatfund = currentfloatfund -
			ISNULL(
				(SELECT SUM(i.curramount)
				FROM expenselast EL
				JOIN expensetotal i
					ON EL.idexp = i.idexp
				WHERE i.ayear = @ayear)
			,0)
		WHERE ayear = @ayear
	END
	
END	
ELSE -- @ayear non specificato
BEGIN
	DELETE FROM currentcashtotal
	DECLARE @ycursor int
	DECLARE fc INSENSITIVE CURSOR FOR
	SELECT ayear FROM accountingyear
	FOR READ ONLY
	OPEN fc
	FETCH NEXT FROM fc INTO @ycursor
	WHILE (@@FETCH_STATUS = 0)
	BEGIN
		set @locked='N'
		SELECT @locked = locked from surplus where ayear = @ycursor
		SET @locked= ISNULL(@locked,'N')
		SELECT	@fin_kind = ISNULL(fin_kind, 0),@idfinincomesurplus = idfinincomesurplus FROM config WHERE ayear = @ycursor
		IF ((@idfinincomesurplus IS NOT NULL) AND (@idfinincomesurplus <> 0))
		BEGIN
			IF (@fin_kind = 3)
			BEGIN
				SET  @startfloatfund = ISNULL(
					(SELECT SUM(finyear.secondaryprev)
					FROM finyear
					WHERE finyear.idfin = @idfinincomesurplus)
					,0)
				SELECT @startfloatfund = 
				@startfloatfund +
				ISNULL(
					(SELECT SUM(d.amount) 
					FROM finvardetail d
					JOIN finvar v
						ON v.yvar = d.yvar
						AND v.nvar = d.nvar
					WHERE (d.idfin = @idfinincomesurplus)
						AND (v.flagsecondaryprev = 'S')
						AND (v.idfinvarstatus = 5))
				,0)
			END
			IF (@fin_kind = 2)
			BEGIN
				SET @startfloatfund = ISNULL(
					(SELECT SUM(finyear.prevision)
					FROM finyear
					WHERE finyear.idfin = @idfinincomesurplus)
					,0)
				SELECT @startfloatfund = 
				@startfloatfund +
				ISNULL(
					(SELECT SUM(d.amount) 
					FROM finvardetail d
					JOIN finvar v
						ON v.yvar = d.yvar
						AND v.nvar = d.nvar
					WHERE (d.idfin = @idfinincomesurplus)
						AND (v.flagprevision= 'S')
						AND (v.idfinvarstatus = 5))
				,0)
			END
		END
		ELSE
		BEGIN
			SELECT @startfloatfund = ISNULL(startfloatfund,0) 
			FROM surplus WHERE ayear = @ycursor 
		END		
		INSERT INTO currentcashtotal VALUES(@ycursor,ISNULL(@startfloatfund,0))
	

		
		IF ((@locked='S') OR (SELECT COUNT(*) FROM fin WHERE ayear = @ycursor) = 0 )
		BEGIN
			UPDATE  currentcashtotal
				SET currentfloatfund =  (SELECT
				 (ISNULL(startfloatfund,0) + 
				  ISNULL(competencyproceeds,0) + 
				  ISNULL(residualproceeds,0) - 
				  ISNULL(competencypayments,0) - 
				  ISNULL(residualpayments,0))
				FROM surplus WHERE ayear = @ycursor)
			WHERE ayear = @ycursor
		END
		ELSE
		BEGIN
			UPDATE currentcashtotal
			SET currentfloatfund =
				currentfloatfund +
				ISNULL(
					(SELECT SUM(i.curramount)
					FROM incometotal i 
					JOIN incomelast IL
						ON IL.idinc = i.idinc
					JOIN proceeds p
						ON p.kpro=IL.kpro
					JOIN proceedstransmission pt
						ON p.kproceedstransmission=pt.kproceedstransmission
					WHERE i.ayear = @ycursor)
				,0)
			WHERE ayear = @ycursor
	
			UPDATE currentcashtotal SET currentfloatfund = currentfloatfund -
			ISNULL(
				(SELECT SUM(i.curramount)
				FROM expenselast EL
				JOIN expensetotal i
					ON EL.idexp = i.idexp
				WHERE i.ayear = @ycursor)
			,0)
			WHERE ayear = @ycursor
		END
		
	FETCH NEXT FROM fc INTO @ycursor
	END
	DEALLOCATE fc
	
END
END


GO

