if object_id('[rpt_avanzo_ammin_cassa_presunto]') is not null
	drop PROCEDURE [rpt_avanzo_ammin_cassa_presunto]
go

CREATE         PROCEDURE [rpt_avanzo_ammin_cassa_presunto]
  @ayear int
AS
BEGIN

-- Fondo Cassa all'1/1
DECLARE @floatfund_01_jan_used decimal(19,2) 
SELECT @floatfund_01_jan_used = isnull((CONVERT(decimal(19,2), paramvalue)),0) 
FROM generalreportparameter 
WHERE idparam='ff_jan01'
DECLARE @aa_01_jan_used decimal(19,2) 
SELECT @aa_01_jan_used = isnull((CONVERT(decimal(19,2), paramvalue)),0) 
FROM generalreportparameter 
WHERE idparam='aa_jan01'
DECLARE @supposed_ff_01_jan_used decimal(19,2) 
SELECT @supposed_ff_01_jan_used = isnull((CONVERT(decimal(19,2), paramvalue)),0) 
FROM generalreportparameter 
WHERE idparam='supposed_ff_jan01'
DECLARE @supposed_aa_01_jan_used decimal(19,2) 
SELECT @supposed_aa_01_jan_used = isnull((CONVERT(decimal(19,2), paramvalue)),0) 
FROM generalreportparameter 
WHERE idparam='supposed_aa_jan01'
-- Per ulteriori dettagli in merito a questa modifica leggere la Documentazione del task n.4077
DECLARE @floatfund_01_jan decimal(19,2) 
IF (SELECT COUNT(*) FROM surplus WHERE ayear= @ayear) >0
	Begin
		SELECT @floatfund_01_jan = ISNULL(startfloatfund, 0)  
		FROM surplus 
		WHERE ayear = @ayear 
	end
ELSE
	SET @floatfund_01_jan = 0

-- Incassi alla data
DECLARE @proceeds_01_jan decimal(19,2) 
SELECT @proceeds_01_jan = ISNULL(proceedstilldate,0) FROM surplus WHERE ayear = @ayear
-- Pagamenti certi alla data
DECLARE @payments_01_jan decimal(19,2)
SELECT @payments_01_jan = ISNULL(paymentstilldate,0) FROM surplus WHERE ayear = @ayear
-- Fondo Cassa alla data
DECLARE @floatfund_stilldate decimal(19,2) 
SELECT @floatfund_stilldate = @floatfund_01_jan + @proceeds_01_jan - @payments_01_jan
-- Incassi Presunti al 31 Dicembre
DECLARE @proceeds_31_dec decimal(19,2) 
SELECT @proceeds_31_dec = ISNULL(proceedstoendofyear,0) FROM surplus WHERE ayear = @ayear
-- Pagamenti Presunti al 31 Dicembre
DECLARE @payments_31_dec decimal(19,2) 
SELECT @payments_31_dec = ISNULL(paymentstoendofyear,0) FROM surplus WHERE ayear = @ayear
-- Fondo Cassa Presunto al 31 Dicembre
DECLARE @floatfund_supposed_31_dec decimal(19,2) 
SELECT @floatfund_supposed_31_dec = @floatfund_stilldate + @proceeds_31_dec - @payments_31_dec
-- Resuidui Attivi Precedenti Presunti
DECLARE @supposed_previousrevenue decimal(19,2) 
SELECT @supposed_previousrevenue = ISNULL(supposedpreviousrevenue,0) FROM surplus WHERE ayear = @ayear
-- Resuidui Attivi Correnti Presunti
DECLARE @supposed_currentrevenue decimal(19,2)
SELECT @supposed_currentrevenue = ISNULL(supposedcurrentrevenue,0) FROM surplus WHERE ayear = @ayear
-- Resuidui Passivi Precedenti Presunti
DECLARE @supposed_previousexpenditure decimal(19,2)
SELECT @supposed_previousexpenditure = ISNULL(supposedpreviousexpenditure,0) FROM surplus WHERE ayear = @ayear
-- Resuidui Passivi Correnti Presunti
DECLARE @supposed_currentexpenditure decimal(19,2)
SELECT @supposed_currentexpenditure = ISNULL(supposedcurrentexpenditure,0) FROM surplus WHERE ayear = @ayear
-- Avanzo di Amministrazione presunto al 31 Dicembre
DECLARE @supposed_creditsurplus_31_dec decimal(19,2)
SELECT @supposed_creditsurplus_31_dec = 
	@floatfund_supposed_31_dec +
	@supposed_previousrevenue + 
	@supposed_currentrevenue -
	@supposed_previousexpenditure -
	@supposed_currentexpenditure
DECLARE @cashvaliditykind tinyint
SELECT @cashvaliditykind = cashvaliditykind FROM config WHERE ayear = @ayear
-- Data di redazione della situazione
DECLARE @refer_date datetime 
SELECT @refer_date = previsiondate FROM surplus WHERE ayear = @ayear
SELECT 
	@refer_date AS earlydate,
	ISNULL(@floatfund_01_jan,0) AS floatfund_01_jan,
	ISNULL(@floatfund_01_jan_used,0) AS floatfund_01_jan_used,
	ISNULL(@aa_01_jan_used,0) AS aa_01_jan_used,
	isnull(@supposed_aa_01_jan_used,0) as supposed_aa_01_jan_used,		
	isnull(@supposed_ff_01_jan_used,0) as supposed_ff_01_jan_used,
	ISNULL(@proceeds_01_jan,0) AS proceeds_01_jan,
	ISNULL(@payments_01_jan,0) AS payments_01_jan,
	ISNULL(@floatfund_stilldate,0) AS floatfund_stilldate,				
	ISNULL(@proceeds_31_dec,0) AS proceeds_31_dec,
	ISNULL(@payments_31_dec,0) AS payments_31_dec,
	ISNULL(@floatfund_supposed_31_dec,0) AS floatfund_supposed_31_dec,
	ISNULL(@supposed_previousrevenue,0) AS supposed_previousrevenue,
	ISNULL(@supposed_currentrevenue,0) AS supposed_currentrevenue,
	ISNULL(@supposed_previousexpenditure,0)as supposed_previousexpenditure,
	ISNULL(@supposed_currentexpenditure,0) AS supposed_currentexpenditure,
	ISNULL(@supposed_creditsurplus_31_dec,0) AS supposed_creditsurplus_31_dec,
	@cashvaliditykind AS cashvaliditykind
END


GO

print '[rpt_avanzo_ammin_cassa_presunto] OK'

GO
if object_id('exp_check_clientifornitori') is not null
	drop procedure exp_check_clientifornitori
go


CREATE               procedure exp_check_clientifornitori(@declarationyear int) as
begin
declare @ayear int
set @ayear = @declarationyear-1
select invoicekind.description, invoice.yinv, invoice.ninv, invoice.docdate, 
	'AVVISO: Un dettaglio sarà ignorato perchè non è specificato il tipo di imposizione dell''aliquota '+ivakind.description
	from invoice 
	join invoicekind on invoice.idinvkind=invoicekind.idinvkind
	join invoicedetail
		on invoicedetail.idinvkind=invoice.idinvkind
		and invoicedetail.yinv=invoice.yinv
		and invoicedetail.ninv=invoice.ninv
	join ivakind on ivakind.idivakind=invoicedetail.idivakind
	where ivakind.idivataxablekind is null and ((invoicekind.flag&2)=0)
	and (((invoicekind.flag&4)=0) and year(invoice.docdate)=@ayear 
		or ((invoicekind.flag&4)<>0) and 
		exists (select * from invoicedetail
			where invoicedetail.idinvkind=invoice.idinvkind
			and invoicedetail.yinv=invoice.yinv
			and invoicedetail.ninv=invoice.ninv
			and invoicedetail.yinv_main=@ayear))
	and exists (select *
		from invoicekindregisterkind
		join ivaregisterkind on ivaregisterkind.idivaregisterkind=invoicekindregisterkind.idivaregisterkind
		where isnull(ivaregisterkind.flagactivity,2)=2 and ivaregisterkind.registerclass in ('A','V')
		and invoicekindregisterkind.idinvkind=invoicekind.idinvkind)
union
select invoicekind.description, invoice.yinv, invoice.ninv, invoice.docdate, 
	'Nel dettaglio della nota di variazione manca l''anno della fattura di riferimento'
	from invoice 
	join invoicekind on invoice.idinvkind=invoicekind.idinvkind
	join invoicedetail on invoicedetail.idinvkind=invoice.idinvkind
		and invoicedetail.yinv=invoice.yinv
		and invoicedetail.ninv=invoice.ninv
	where ((invoicekind.flag&4)<>0) and invoicedetail.yinv_main is null
		and ((invoicekind.flag&2)=0)
	and exists (select *
		from invoicekindregisterkind
		join ivaregisterkind on ivaregisterkind.idivaregisterkind=invoicekindregisterkind.idivaregisterkind
		where isnull(ivaregisterkind.flagactivity,2)=2 and ivaregisterkind.registerclass in ('A','V')
		and invoicekindregisterkind.idinvkind=invoicekind.idinvkind)
union
select invoicekind.description, invoice.yinv, invoice.ninv, invoice.docdate, 
	'Manca il Tipo di attività del registro "'+isnull(ivaregisterkind.description,'')+'"'
	from invoice 
	join invoicekind on invoicekind.idinvkind=invoice.idinvkind
	join invoicekindregisterkind on invoicekindregisterkind.idinvkind=invoicekind.idinvkind
	join ivaregisterkind on ivaregisterkind.idivaregisterkind=invoicekindregisterkind.idivaregisterkind
	where ivaregisterkind.flagactivity is null and ivaregisterkind.registerclass in ('A','V')
	and ((invoicekind.flag&2)=0)
	and (((invoicekind.flag&4)=0) and year(invoice.docdate)=@ayear 
		or ((invoicekind.flag&4)<>0) and 
		exists (select * from invoicedetail
			where invoicedetail.idinvkind=invoice.idinvkind
			and invoicedetail.yinv=invoice.yinv
			and invoicedetail.ninv=invoice.ninv
			and invoicedetail.yinv_main=@ayear))
	and exists (select *
		from invoicekindregisterkind
		join ivaregisterkind on ivaregisterkind.idivaregisterkind=invoicekindregisterkind.idivaregisterkind
		where isnull(ivaregisterkind.flagactivity,2)=2 and ivaregisterkind.registerclass in ('A','V')
		and invoicekindregisterkind.idinvkind=invoicekind.idinvkind)
union
select invoicekind.description, invoice.yinv, invoice.ninv, invoice.docdate, 
	'Nella fattura non è specificata la data del documento'
	from invoice 
	join invoicekind on invoice.idinvkind=invoicekind.idinvkind
	where ((invoicekind.flag&4)=0) and invoice.docdate is null
	and ((invoicekind.flag&2)=0)
	and exists (select *
		from invoicekindregisterkind
		join ivaregisterkind on ivaregisterkind.idivaregisterkind=invoicekindregisterkind.idivaregisterkind
		where isnull(ivaregisterkind.flagactivity,2)=2 and ivaregisterkind.registerclass in ('A','V')
		and invoicekindregisterkind.idinvkind=invoicekind.idinvkind)
union
select invoicekind.description, invoice.yinv, invoice.ninv, invoice.docdate, 
	'AVVISO: La fattura sarà ignorata perchè manca la partita iva di "'+registry.title+'"'
	from invoice 
	join invoicekind on invoice.idinvkind=invoicekind.idinvkind
	join registry on invoice.idreg=registry.idreg
	where isnumeric(registry.p_iva)=0
	and ((invoicekind.flag&2)=0)
	and (((invoicekind.flag&4)=0) and year(invoice.docdate)<2008 and year(invoice.docdate)=@ayear 
		or ((invoicekind.flag&4)<>0) and 
		exists (select * from invoicedetail
			where invoicedetail.idinvkind=invoice.idinvkind
			and invoicedetail.yinv=invoice.yinv
			and invoicedetail.ninv=invoice.ninv
			and year(invoicedetail.yinv_main)<2008 and invoicedetail.yinv_main=@ayear))
	and exists (select *
		from invoicekindregisterkind
		join ivaregisterkind on ivaregisterkind.idivaregisterkind=invoicekindregisterkind.idivaregisterkind
		where isnull(ivaregisterkind.flagactivity,2)=2 and ivaregisterkind.registerclass in ('A','V')
		and invoicekindregisterkind.idinvkind=invoicekind.idinvkind)
union
select invoicekind.description, invoice.yinv, invoice.ninv, invoice.docdate, 
	'AVVISO: La fattura sarà ignorata perchè manca il codice fiscale di "'+registry.title+'"'
	from invoice 
	join invoicekind on invoice.idinvkind=invoicekind.idinvkind
	join registry on invoice.idreg=registry.idreg
	where registry.cf is null
	and ((invoicekind.flag&2)=0)
	and (((invoicekind.flag&4)=0) and year(invoice.docdate)>=2008 and year(invoice.docdate)=@ayear 
		or ((invoicekind.flag&4)<>0) and 
		exists (select * from invoicedetail
			where invoicedetail.idinvkind=invoice.idinvkind
			and invoicedetail.yinv=invoice.yinv
			and invoicedetail.ninv=invoice.ninv
			and year(invoicedetail.yinv_main)>=2008 and invoicedetail.yinv_main=@ayear))
	and exists (select *
		from invoicekindregisterkind
		join ivaregisterkind on ivaregisterkind.idivaregisterkind=invoicekindregisterkind.idivaregisterkind
		where isnull(ivaregisterkind.flagactivity,2)=2 and ivaregisterkind.registerclass in ('A','V')
		and invoicekindregisterkind.idinvkind=invoicekind.idinvkind)
union
select invoicekind.description, invoice.yinv, invoice.ninv, invoice.docdate, 
	'Non esiste un collegamento tra tipo di documento e registro iva con protocollo vendita'
	from invoice 
	join invoicekind on invoicekind.idinvkind=invoice.idinvkind
	where not exists (select *
		from invoicekindregisterkind 
		join ivaregisterkind on ivaregisterkind.idivaregisterkind=invoicekindregisterkind.idivaregisterkind
		where invoicekindregisterkind.idinvkind=invoicekind.idinvkind)
	and ((invoicekind.flag&2)=0)
	and (((invoicekind.flag&4)=0) and year(invoice.docdate)=@ayear 
		or ((invoicekind.flag&4)<>0) and 
		exists (select * from invoicedetail
			where invoicedetail.idinvkind=invoice.idinvkind
			and invoicedetail.yinv=invoice.yinv
			and invoicedetail.ninv=invoice.ninv
			and invoicedetail.yinv_main=@ayear))
union
select invoicekind.description, invoice.yinv, invoice.ninv, invoice.docdate, 
	'Esiste più di un collegamento tra tipo di documento e registro iva con protocollo vendita'
	from invoice 
	join invoicekind on invoicekind.idinvkind=invoice.idinvkind
	where (select count(*)
		from invoicekindregisterkind 
		join ivaregisterkind on ivaregisterkind.idivaregisterkind=invoicekindregisterkind.idivaregisterkind
		where invoicekindregisterkind.idinvkind=invoicekind.idinvkind and ivaregisterkind.registerclass='V')>1
	and ((invoicekind.flag&2)=0)
	and (((invoicekind.flag&4)=0) and year(invoice.docdate)=@ayear 
		or ((invoicekind.flag&4)<>0) and 
		exists (select * from invoicedetail
			where invoicedetail.idinvkind=invoice.idinvkind
			and invoicedetail.yinv=invoice.yinv
			and invoicedetail.ninv=invoice.ninv
			and invoicedetail.yinv_main=@ayear))
union
select invoicekind.description, invoice.yinv, invoice.ninv, invoice.docdate, 
	'Esiste più di un collegamento tra tipo di documento e registro iva con protocollo acquisto'
	from invoice 
	join invoicekind on invoicekind.idinvkind=invoice.idinvkind
	where (select count(*)
		from invoicekindregisterkind 
		join ivaregisterkind on ivaregisterkind.idivaregisterkind=invoicekindregisterkind.idivaregisterkind
		where invoicekindregisterkind.idinvkind=invoicekind.idinvkind and ivaregisterkind.registerclass='A')>1
	and ((invoicekind.flag&2)=0)
	and (((invoicekind.flag&4)=0) and year(invoice.docdate)=@ayear 
		or ((invoicekind.flag&4)<>0) and 
		exists (select * from invoicedetail
			where invoicedetail.idinvkind=invoice.idinvkind
			and invoicedetail.yinv=invoice.yinv
			and invoicedetail.ninv=invoice.ninv
			and invoicedetail.yinv_main=@ayear))
end




GO

print 'exp_check_clientifornitori OK'

GO
if object_id('rpt_dettvarprevisione_crediti_cassa') is not null
	drop PROCEDURE rpt_dettvarprevisione_crediti_cassa
go

CREATE    PROCEDURE rpt_dettvarprevisione_crediti_cassa
	@yvar int,
	@nvar int,
	@reportkind varchar(20),
	@showupb char(1),
	@compress char(1),
	@showcategory char(1)
AS
BEGIN
-- exec rpt_dettvarprevisione_crediti_cassa 2013, 1, 'PREVISIONE','S','N','N'
/* Versione 1.0.0 del 14/09/2007 ultima modifica: SARA */
DECLARE @nlevelcategory tinyint
set @nlevelcategory = 2
CREATE TABLE #detail
(
	idfin int,
	finpart char(1),
	codefin varchar(50),
	title varchar(150),
	idupb varchar(36),
	codeupb varchar(50),	
	upb varchar(150),
	description varchar(1000),
	amount decimal(19,2),
	manager varchar(150)	
)
IF @reportkind = 'PREVISIONE'
BEGIN
	insert into #detail(
		idfin,
		finpart ,
		codefin ,
		title ,
		idupb ,
		codeupb,	
		upb ,
		description ,
		amount,
		manager
	)
	SELECT   	
		fin.idfin,
		CASE
		when (( fin.flag & 1)=0) then 'E'
		when (( fin.flag & 1)=1) then 'S'
		End,
		fin.codefin,
		fin.title,
		upb.idupb,
		upb.codeupb,
		upb.title,
		finvardetail.description,
		finvardetail.amount,
		manager.title
	FROM finvardetail
	JOIN fin
		ON fin.idfin = finvardetail.idfin
	LEFT OUTER JOIN upb
		ON upb.idupb = finvardetail.idupb
	LEFT OUTER JOIN manager
		on upb.idman = manager.idman
	WHERE finvardetail.yvar = @yvar
		AND finvardetail.nvar = @nvar
	ORDER BY fin.flag, fin.codefin
END
IF (@reportkind = 'CREDITI' OR @reportkind = 'CASSA')
BEGIN
	insert into #detail(
		idfin,
		finpart ,
		codefin ,
		title ,
		idupb ,
		codeupb,	
		upb ,
		description ,
		amount,
		manager 
		)
	SELECT
		fin.idfin,
	   	CASE
			when (( fin.flag & 1)=0) then 'E'
			when (( fin.flag & 1)=1) then 'S'
		End,
		fin.codefin,
		fin.title,
		upb.idupb,
		upb.codeupb,
		upb.title ,
		finvardetail.description,
		finvardetail.amount,
		manager.title
	FROM finvardetail
	JOIN fin
		ON fin.idfin = finvardetail.idfin
		AND (( fin.flag & 1)=1) -- S
	LEFT OUTER JOIN upb
		ON upb.idupb = finvardetail.idupb
	LEFT OUTER JOIN manager
		on upb.idman = manager.idman
	WHERE finvardetail.yvar = @yvar
		AND finvardetail.nvar = @nvar
	ORDER BY fin.flag, fin.codefin
END
	
IF (@showupb='S') --> Rimane come prima
  Begin
	SELECT 
		finpart ,
		CASE 
			WHEN (@showcategory)='S'
			   THEN fin.codefin 
			ELSE  #detail.codefin
		END as codefin,
		CASE 
			WHEN (@showcategory)='S'
			   THEN fin.title 
			ELSE  #detail.title
		END as title,
		idupb ,
		codeupb,	
		upb ,
		description ,
		amount,
		manager 
	FROM #detail
	JOIN finlink
		ON #detail.idfin = finlink.idchild and finlink.nlevel = @nlevelcategory
	JOIN fin
		ON finlink.idparent=fin.idfin
	ORDER BY finpart, #detail.codefin
  End
ELSE  --> Ora non vogliamo vedere l'upb e dobbiamo analizzare @compress
  Begin
	IF (@compress='S') --> Scrive una standard
	  Begin
		IF(@showcategory='S')
		Begin
			SELECT 
			CASE
				when (( fin.flag & 1)=0) then 'E'
				when (( fin.flag & 1)=1) then 'S'
			End AS finpart,
			fin.codefin, 
			fin.title ,
			null as idupb ,
			null as codeupb,	
			null as upb ,
			'Dettagli diversi' as description ,
			isnull(sum(amount),0) as amount,
			null as manager
			FROM #detail
			JOIN finlink
				ON #detail.idfin = finlink.idchild 
			JOIN fin
				ON finlink.idparent = fin.idfin
			WHERE finlink.nlevel = @nlevelcategory
			GROUP BY fin.flag, fin.codefin,fin.title 
			ORDER BY fin.flag, fin.codefin
		End
		IF(@showcategory='N')
		Begin
			SELECT 
			finpart,
			codefin,
			title,
			null as idupb ,
			null as codeupb,	
			null as upb ,
			'Dettagli diversi' as description ,
			isnull(sum(amount),0) as amount,
			null as manager
			FROM #detail
			GROUP BY finpart, codefin, title 
			ORDER BY finpart, codefin
		End
		
	  End
	IF (@compress='N') --> Concatena le descrizioni
	  Begin
		CREATE TABLE #detailcompact
		(
			idfin int ,
			finpart char(1),
			codefin varchar(50),
			title varchar(150),
			description varchar(1000),
			amount decimal(19,2)	
		)
		INSERT INTO #detailcompact(idfin,finpart,codefin,title,amount)
		SELECT 
			idfin, 
		  	finpart,
			codefin ,
			title ,
			isnull(sum(amount),0) 
		FROM #detail
		GROUP BY finpart,idfin, codefin,title
		DECLARE @finpart char(1)
		DECLARE @idfin int
		
		DECLARE @description varchar(200)
		DECLARE @descriptioncompact varchar(1000) 
		DECLARE rowcursor INSENSITIVE CURSOR FOR
			SELECT DISTINCT finpart,idfin,description
			FROM #detail
			FOR READ ONLY
		OPEN rowcursor FETCH  NEXT FROM rowcursor INTO @finpart,@idfin,@description 
		WHILE @@FETCH_STATUS = 0
		BEGIN 
			UPDATE #detailcompact 
			SET description = 
			CASE 
				WHEN ((len(isnull(#detailcompact.description,'')) + len(@description)) < 1000 )
				   THEN ISNULL(#detailcompact.description,'') + @description + ';'
				ELSE  ISNULL(#detailcompact.description,'') + '...;'
			END
			WHERE (idfin = @idfin and finpart = @finpart)
		
			FETCH NEXT FROM rowcursor INTO  @finpart,@idfin,@description
		END 
		DEALLOCATE rowcursor
		
		SELECT 	finpart ,
			CASE 
				WHEN (@showcategory)='S'
				   THEN fin.codefin 
				ELSE  #detailcompact.codefin
			END as codefin,
			CASE 
				WHEN (@showcategory)='S'
				   THEN fin.title
				ELSE  #detailcompact.title
			END as title,
			null as idupb ,
			null as codeupb,	
			null as upb ,
			substring(description,1,len(description)-1) as description,    
			isnull(amount,0) as amount
		FROM #detailcompact
		JOIN finlink
			ON #detailcompact.idfin = finlink.idchild and finlink.nlevel = @nlevelcategory
		JOIN fin
			ON finlink.idparent=fin.idfin
		ORDER BY finpart, #detailcompact.codefin
	  End	
  End
END




GO

print 'rpt_dettvarprevisione_crediti_cassa OK'

