CREATE                TRIGGER [trigger_d_incomeestimate] ON incomeestimate 
FOR DELETE 
AS
	DECLARE @idinc int
	SELECT @idinc = idinc
	FROM deleted
	UPDATE estimatedetail SET idinc_iva = NULL
	WHERE idinc_iva = @idinc
	UPDATE estimatedetail SET idinc_taxable = NULL
	WHERE idinc_taxable = @idinc


