		JOIN finlink FLK2
			ON FLK2.idparent = F.idfin 
		JOIN finvardetail d
			ON ISNULL(FLK2.idchild,F.idfin) = d.idfin
		JOIN finvar v
  			ON v.yvar = d.yvar  
  			AND v.nvar = d.nvar 
		JOIN upb U 
			ON d.idupb = U.idupb
		WHERE v.adate between @start and @stop 
			AND v.yvar = @ayear
			AND ((U.idman = @idman) OR (@idman is null and U.idman is not null))	
			AND (@idfin IS NULL OR FLK.idparent = @idfin)
			AND ((F.flag&1)<>0)
			AND ((@hierarchy ='N' AND F.nlevel = @nlevel) OR (@hierarchy ='S' and F.nlevel >= @nlevel))
			AND (U.idupb like @idupb)
			AND v.idfinvarstatus = 5
			AND v.flagproceeds ='S'
			AND v.variationkind IN (1,4)
			AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
			AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
			AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
			AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
		GROUP BY U.idman,isnull(@fixedidupb, U.idupb),F.idfin, F.nlevel, ISNULL(U.assured,'N')
				
		SET @Incassi = 'S'
	END
ELSE
Begin
  
	SET @Incassi = 'N'		
End       
--	--	--	--	--	-- Aggiunge le voci inutilizzate se @suppressifblank = N --	--	--	--	--	--	

--> Se ho scelto di vedere l'upb inserisco le coppie upb/bilancio altrimenti inserisco solo il bilanico non utilizzato
IF (@suppressifblank = 'N') 
BEGIN
IF ( (@showupb <>'S') and (@idupboriginal = '%'))
Begin
	if(@hierarchy='S')	
		BEGIN
			INSERT INTO #fin_situation(idfin, nlevel,idman)
			SELECT 
				F.idfin, F.nlevel,U.idman
			FROM fin F 
			cross join upb U
			JOIN finlink FLK2
				ON FLK2.idparent = F.idfin 
			JOIN finlink FLK
				ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
				AND (@idfin IS NULL OR FLK.idparent = @idfin)
			WHERE ((F.flag & 1) = 1) and F.ayear = @ayear
				AND (@idfin IS NULL OR  FLK.idparent = @idfin)
				AND (F.nlevel >=  @nlevel)
				AND (U.idupb LIKE @idupb and U.active = 'S')
				AND ((U.idman = @idman) OR (@idman is null and U.idman is not null))	
			GROUP BY F.idfin, F.nlevel, U.idman, F.ayear,F.flag
		END
	ELSE
		BEGIN
			INSERT INTO #fin_situation(idfin,nlevel, idman)
			SELECT F.idfin, F.nlevel,U.idman
			FROM fin F
			cross join upb U
			JOIN finlink FLK
				ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
			LEFT OUTER JOIN finlink FLK2
				ON FLK2.idparent = F.idfin 
			WHERE  	((F.flag & 1 ) <>0) AND F.ayear =@ayear	
				AND (@idfin IS NULL OR  FLK.idparent = @idfin)
				AND (F.nlevel = @nlevel)
				AND (U.idupb LIKE @idupb and U.active = 'S')
				AND ((U.idman = @idman) OR (@idman is null and U.idman is not null))	
			GROUP BY F.idfin, F.nlevel, U.idman		
		END
end
else
begin
	--> @showupb ='S'
	if(@hierarchy='S')	
		BEGIN
			INSERT INTO #fin_situation(
				idfin, nlevel,
				idupb,idman,
				assured,
				flagconsider
			)
			SELECT 
				F.idfin, F.nlevel,
				U.idupb,U.idman,
				ISNULL(U.assured,'N'),
			CASE 
				 WHEN (@hierarchy ='N') Then 'S' 
				 WHEN ( @hierarchy='S' 
						and F.nlevel >= @levelusable 
						and F.idfin IN (SELECT idfin FROM finlast))
					THEN 'S'
				 ELSE 'N'
			END
			FROM fin F cross join upb U
			LEFT OUTER JOIN finlink FLK2
				ON FLK2.idparent = F.idfin 
			JOIN finlink FLK
				ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
				AND (@idfin IS NULL OR FLK.idparent = @idfin)
			WHERE  ((F.flag & 1) = 1) and F.ayear = @ayear
				AND (@idfin IS NULL OR  FLK.idparent = @idfin)
				AND (U.idupb LIKE @idupb and U.active = 'S')
				AND ((U.idman = @idman) OR (@idman is null and U.idman is not null))	
				AND (F.nlevel >=  @nlevel)
				AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
				AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
				AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
				AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
				AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)			
			GROUP BY U.idman,U.idupb,F.idfin,F.nlevel,F.ayear,F.flag, ISNULL(U.assured,'N')
		END
	ELSE
		BEGIN
			INSERT INTO #fin_situation(
				idfin, nlevel,
				idupb,idman,
				assured,
				flagconsider
				)
			SELECT 
				F.idfin, F.nlevel,
				U.idupb,U.idman,
				ISNULL(U.assured,'N'),
				'S'
			FROM upb U
			CROSS JOIN fin F
			JOIN finlink FLK
				ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
			LEFT OUTER JOIN finlink FLK2
				ON FLK2.idparent = F.idfin 
			WHERE  	((F.flag & 1 ) <> 0) AND F.ayear =@ayear	
				AND (@idfin IS NULL OR  FLK.idparent = @idfin)
				AND (U.idupb LIKE @idupb and U.active = 'S')
				AND ((U.idman = @idman) OR (@idman is null and U.idman is not null))	
				AND (F.nlevel = @nlevel)
				AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
				AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
				AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
				AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
				AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)			
			GROUP BY U.idman,U.idupb, F.idfin,F.nlevel,ISNULL(U.assured,'N')
		END
end
END
 DELETE FROM #fin_situation WHERE flagconsider='N'

IF (@suppressifblank = 'S') 	--> cancella le righe sottostanti la categoria 
BEGIN
	DELETE FROM #fin_situation 
	WHERE 
		(isnull(main_initial_prevision,0.0) =0 AND 
		isnull(var_main_prevision,0.0) =0 AND 
		isnull(fin_phase_comp,0.0) =0 AND 
		isnull(var_fin_phase_comp,0.0) =0 AND 
		isnull(max_phase_comp,0.0) =0 AND 
		isnull(var_max_phase_comp,0.0) =0 AND 
		isnull(sec_initial_prevision,0.0) =0 AND 
		isnull(varprevsec,0.0) =0 AND 
		isnull(fin_phase_resid,0.0) =0 AND 
		isnull(var_fin_phase_resid,0.0) =0 AND 
		isnull(max_phase_resid,0.0) =0 AND 
		isnull(var_max_phase_resid,0.0) =0 AND 
		isnull(assign_credit,0.0) =0 AND 
		isnull(var_assign_credit,0.0) =0 AND 
		isnull(assign_cash,0.0) =0 AND 
		isnull(var_assign_cash,0.0) =0 
		AND nlevel >=2
		)--nlevel <>0
END
IF (@showupb <>'S') 
BEGIN
	declare 	@codeupb varchar(50)
	declare		@upb varchar(150)
	declare		@upbprintingorder varchar(50)
	declare		@ext_idupb varchar(50)
	if (@idupboriginal='%')
	begin
		set @codeupb= null
		set @upb= null
		set @upbprintingorder= null
		set @ext_idupb= null
	end
	else
	begin
		SET @upbprintingorder =
			(SELECT TOP 1 printingorder
			FROM upb
			WHERE idupb = @idupboriginal)
		SET  @upb =
			(SELECT TOP 1 title
			FROM upb
			WHERE idupb = @idupboriginal)
		SET  @ext_idupb =	@idupboriginal
		SET  @codeupb =
			(SELECT TOP 1 codeupb
			FROM upb	
			WHERE idupb = @idupboriginal)
	end
	
SELECT 
	#fin_situation.idfin,	
	@codeupb as codeupb,
	@ext_idupb as idupb,
	@upb as upb,
	@upbprintingorder as upbprintingorder,	
	null AS 'idfinlevel0',
	fl1.idparent AS 'idfinlevel1',
	fl2.idparent AS 'idfinlevel2',
	fl3.idparent AS 'idfinlevel3',
	fl4.idparent AS 'idfinlevel4',
	fl5.idparent AS 'idfinlevel5',
	NULL AS 'idfinlevel6',
	NULL AS 'idfinlevel7',
	NULL AS 'idfinlevel8',
	NULL AS 'idfinlevel9',
	fin.codefin,	
	fin.title,	
	fin.printingorder as finprintingorder,	
	#fin_situation.nlevel,	
	sum(isnull(main_initial_prevision,0.0)) 	 'main_initial_prevision',
	sum(isnull(var_main_prevision,0.0)) 		 'var_main_prevision',
	sum(isnull(fin_phase_comp,0.0)) 		 'fin_phase_comp',
	sum(isnull(var_fin_phase_comp,0.0)) 		 'var_fin_phase_comp', 
	@desc_fin_phase 				 'desc_fin_phase',	
	sum(isnull(max_phase_comp,0.0)) 		 'max_phase_comp',
	sum(isnull(var_max_phase_comp,0.0)) 		 'var_max_phase_comp',
	@desc_max_phase 				 'desc_max_phase' 	,					
	sum(isnull(sec_initial_prevision,0.0)) 		 'sec_initial_prevision',
	sum(isnull(varprevsec,0.0)) 			 'varprevsec',
	sum(isnull(fin_phase_resid,0.0)) 		 'fin_phase_resid', 
	sum(isnull(var_fin_phase_resid,0.0)) 		 'var_fin_phase_resid',
	sum(isnull(max_phase_resid,0.0)) 		 'max_phase_resid',
	sum(isnull(var_max_phase_resid,0.0)) 		 'var_max_phase_resid',
	sum(isnull(assign_credit,0.0)) 			 'assign_credit',
	sum(isnull(var_assign_credit,0.0)) 		 'var_assign_credit',
	sum(isnull(assign_cash,0.0)) 			 'assign_cash' ,
	sum(isnull(var_assign_cash,0.0)) 		 'var_assign_cash' ,
	@previsionkind 				 'previsionkind',
	@secprevisionkind 			 'secprevisionkind',
	@Crediti as flag_assign_credit,
	@Incassi as	flag_assign_cash,
	flag_assign_credit,
	flag_assign_cash,
	#fin_situation.idman,
	manager.title as manager	
	FROM #fin_situation
	JOIN fin 
		ON #fin_situation.idfin = fin.idfin	
	JOIN manager
		ON	#fin_situation.idman = manager.idman
		left outer join finlink fl1 on fl1.idchild=#fin_situation.idfin and fl1.nlevel=1
		left outer join finlink fl2 on fl2.idchild=#fin_situation.idfin and fl2.nlevel=2
		left outer join finlink fl3 on fl3.idchild=#fin_situation.idfin and fl3.nlevel=3
		left outer join finlink fl4 on fl4.idchild=#fin_situation.idfin and fl4.nlevel=4
		left outer join finlink fl5 on fl5.idchild=#fin_situation.idfin and fl5.nlevel=5
		GROUP BY #fin_situation.idfin, fin.codefin,	
		fin.title,fin.printingorder,#fin_situation.nlevel,flag_assign_credit,flag_assign_cash,#fin_situation.idman,manager.title,
		fl1.idparent, fl2.idparent, fl3.idparent, fl4.idparent, fl5.idparent 
		ORDER BY #fin_situation.idman,finprintingorder
END
ELSE 
	SELECT  
	#fin_situation.idfin,	
	upb.codeupb,
	#fin_situation.idupb,
	upb.title as upb,
	upb.printingorder as upbprintingorder,
	null AS 'idfinlevel0',
	fl1.idparent AS 'idfinlevel1',
	fl2.idparent AS 'idfinlevel2',
	fl3.idparent AS 'idfinlevel3',
	fl4.idparent AS 'idfinlevel4',
	fl5.idparent AS 'idfinlevel5',
	NULL AS 'idfinlevel6',
	NULL AS 'idfinlevel7',
	NULL AS 'idfinlevel8',
	NULL AS 'idfinlevel9',
	fin.codefin,	
	fin.title,	
	fin.printingorder as finprintingorder,	
	#fin_situation.nlevel,	
	sum(isnull(main_initial_prevision,0.0)) 	 'main_initial_prevision',
	sum(isnull(var_main_prevision,0.0)) 		 'var_main_prevision',
	sum(isnull(fin_phase_comp,0.0)) 		 'fin_phase_comp',
	sum(isnull(var_fin_phase_comp,0.0)) 		 'var_fin_phase_comp', 
	@desc_fin_phase 				 'desc_fin_phase',	
	sum(isnull(max_phase_comp,0.0)) 		 'max_phase_comp',
	sum(isnull(var_max_phase_comp,0.0)) 		 'var_max_phase_comp',
	@desc_max_phase 				 'desc_max_phase' 	,					
	sum(isnull(sec_initial_prevision,0.0)) 		 'sec_initial_prevision',
	sum(isnull(varprevsec,0.0)) 			 'varprevsec',
	sum(isnull(fin_phase_resid,0.0)) 		 'fin_phase_resid', 
	sum(isnull(var_fin_phase_resid,0.0)) 		 'var_fin_phase_resid',
	sum(isnull(max_phase_resid,0.0)) 		 'max_phase_resid',
	sum(isnull(var_max_phase_resid,0.0)) 		 'var_max_phase_resid',
	sum(isnull(assign_credit,0.0)) 			 'assign_credit',
	sum(isnull(var_assign_credit,0.0)) 		 'var_assign_credit',
	sum(isnull(assign_cash,0.0)) 			 'assign_cash' ,
	sum(isnull(var_assign_cash,0.0)) 		 'var_assign_cash' ,
	@previsionkind 			 'previsionkind',
	@secprevisionkind 		 'secprevisionkind',
	case when ((upb.assured is not null) and upb.assured ='S') then 'N'
			else @Crediti
	End as flag_assign_credit,
	case when ((upb.assured is not null) and upb.assured ='S')  then 'N'
			else @Incassi
	End as	flag_assign_cash,
	upb.idman,
	manager.title as manager
FROM #fin_situation 
JOIN fin 
	ON #fin_situation.idfin = fin.idfin	
JOIN upb 
	ON #fin_situation.idupb = upb.idupb
JOIN manager 
	ON upb.idman = manager.idman
		left outer join finlink fl1 on fl1.idchild=#fin_situation.idfin and fl1.nlevel=1
		left outer join finlink fl2 on fl2.idchild=#fin_situation.idfin and fl2.nlevel=2
		left outer join finlink fl3 on fl3.idchild=#fin_situation.idfin and fl3.nlevel=3
		left outer join finlink fl4 on fl4.idchild=#fin_situation.idfin and fl4.nlevel=4
		left outer join finlink fl5 on fl5.idchild=#fin_situation.idfin and fl5.nlevel=5
GROUP BY upb.idman,manager.title, #fin_situation.idupb,upb.codeupb, upb.title,upb.printingorder,
		#fin_situation.idfin, fin.codefin,fin.title,fin.printingorder,#fin_situation.nlevel,
		flag_assign_credit,flag_assign_cash,
		fl1.idparent, fl2.idparent, fl3.idparent, fl4.idparent, fl5.idparent, upb.assured		
ORDER BY upb.idman, upb.printingorder, fin.printingorder
END



GO

print '[rpt_sitbilancio_respons_spesa_2fasi] OK'

GO
if object_id('[exp_modello770_10]') is not null
	drop PROCEDURE [exp_modello770_10]
go

-- exp_modello770_10 'H'
CREATE      PROCEDURE [exp_modello770_10] (
	@recordGH varchar(2)='GH'
	)
AS BEGIN
	declare @statementyear smallint
	set @statementyear = 2010
	CREATE TABLE #modello770
	(
		progr int,
		quadro varchar(3),
		riga int,
		colonna varchar(3),
		stringa varchar(100),
		intero int,
		data smalldatetime
	)
	INSERT INTO #modello770 EXEC exp_modello770_10_a
	DECLARE @progr_raggiunto int
	if @recordGH = 'GH'
	begin
		INSERT INTO #modello770 EXEC exp_modello770_10_g '770'
	end
--	INSERT INTO #modello770 EXEC exp_modello770_10_h
---------------------------------------------------------------------------------------------------------------------------------------------------------------------------
-- Il seguente codice è la sp del reord H, ossia "exp_modello770_10_h"
---------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	declare @SS003001 dec(19,2)
	declare @SS003002 dec(19,2)
	declare @annodichiarazione int
	set @annodichiarazione = 2010
	declare @annoredditi int
	set @annoredditi = 2009
	declare @31dic09_XXX datetime
	set @31dic09_XXX = dateadd(yy, @annoredditi-2000, {d '2000-12-31'})
	declare @expensephase int
	select @expensephase=expensephase from config where ayear = @annodichiarazione-1

CREATE TABLE #annualpayedrefundH
(
	payed_lastyear decimal(19,2),
	payed_lastyear_P decimal(19,2),
	payed_total decimal(19,2),
	payed_total_P decimal(19,2),
	payed_prevyears decimal(19,2),
	F_refund_lastyear decimal(19,2),
	P_refund_lastyear decimal(19,2),
	F_refund_total decimal(19,2),
	P_refund_total decimal(19,2),
	F_refund_residual decimal(19,2),
	P_refund_residual decimal(19,2),
	exemptionquota_applied decimal(19,2)
)
-- Il quadro H è per il lavoro autonomo
	CREATE TABLE #recHNonArrot
	(
		progr int,
		quadro varchar(3),
		riga int,
		colonna varchar(3),
		stringa varchar(100),
		decimfisc decimal(19,2),
		decimprev decimal(19,2),
		data datetime,
		intero int
	)

-- Sezione dichiarativa	
	DECLARE @progrCom int
	DECLARE @codfiscEnte varchar(16)
	DECLARE @idreg int
	DECLARE @au1cf varchar(16)
	DECLARE @au2cognomePercipiente varchar(50)
	DECLARE @au3nomePercipiente varchar(30)
	DECLARE @au4gender char(1)
	DECLARE @au5birthdate datetime
	DECLARE @au6birthplace varchar(61)
	DECLARE @au7birthprovince varchar(2)
	DECLARE @au14foreigncf varchar(25)
	--
	DECLARE @maxexpensephase char(1)
	SELECT  @maxexpensephase = MAX(nphase) FROM expensephase
	CREATE TABLE #expense2009
	(
		idexp int,
		idreg int,
		idser int,
		employtaxamount decimal(19,2),
		motive770 varchar(10)
	)

	INSERT INTO #expense2009
		(
			idexp,--1
			idreg,--2
			idser,--3
			employtaxamount--6
		)
		SELECT
			expense.idexp,--1
			expense.idreg,--2
			expenselast.idser,--3
			ISNULL((SELECT SUM(employtax) FROM expensetaxofficial 
				WHERE expensetaxofficial.idexp = expense.idexp 
				AND expensetaxofficial.stop IS NULL),0)
		FROM expense
		join expenselast on expense.idexp = expenselast.idexp
		join payment 
			on payment.kpay = expenselast.kpay
		join paymenttransmission
			on paymenttransmission.kpaymenttransmission = payment.kpaymenttransmission
		JOIN service on service.idser=expenselast.idser
		JOIN registry ON expense.idreg = registry.idreg
		WHERE 	registry.idregistryclass <> '10' and registry.idregistryclass <> '24'
			--AND NOT EXISTS(SELECT * FROM registryrole WHERE idrole = '16' AND registryrole.idreg = expense.idreg)
			AND year(paymenttransmission.transmissiondate)=@annoredditi
			AND service.rec770kind = 'H'
			AND ((select expenseyear.amount from expenseyear where expenseyear.idexp = expenselast.idexp)
			+ ISNULL(
				(SELECT SUM(amount) FROM expensevar
				WHERE expensevar.idexp = expense.idexp
				-- AND expensevar.yvar <= @annoredditi  superfluo poiché expense di ultima fase
				AND ISNULL(autokind,0) <> 4)
			,0)) > 0
			and (select count(*) from expensetaxofficial 
			      where expensetaxofficial.idexp=expense.idexp
			      AND   expensetaxofficial.stop IS NULL) > 0
	update #expense2009 set motive770 = motive770service.idmot
		from motive770service 
		where motive770service.idser = #expense2009.idser
		AND motive770service.ayear = @annodichiarazione-1
	declare @cognome varchar(60)
	DECLARE registry_crs CURSOR FOR 
		SELECT DISTINCT isnull(cf,p_iva), #expense2009.idreg, surname FROM #expense2009
		join registry on registry.idreg = #expense2009.idreg
		order by surname
	OPEN registry_crs
	
	SET @progrCom = 1
	FETCH NEXT FROM registry_crs into @au1cf, @idreg, @cognome
	
	declare @idcitynascita int
	WHILE (@@FETCH_STATUS = 0)
	BEGIN
		set @au14foreigncf=null
		set @au2cognomePercipiente=null
		set @au3nomePercipiente=null
		set @au4gender=null
		set @au5birthdate=null
		set @au6birthplace=null
		set @au7birthprovince=null
		SELECT
			@au6birthplace =  geo_nation.title,
			@au14foreigncf = registry.foreigncf,
			@au2cognomePercipiente = coalesce(registry.surname, registry.title),
			@au3nomePercipiente = registry.forename,
			@au4gender = registry.gender,
			@au5birthdate = registry.birthdate,
			@idcitynascita= registry.idcity
			FROM registry 		
			LEFT OUTER JOIN geo_nation ON registry.idnation = geo_nation.idnation
			WHERE registry.idreg = @idreg

		
		if (@idcitynascita is not null)
		BEGIN
			while (select newcity from geo_city where idcity=@idcitynascita) is not null
			BEGIN
				select @idcitynascita=newcity from geo_city where idcity=@idcitynascita 
			END
			--sezione di impostazione vecchio comune poiché quello del 770 non è aggiornato, DA RIMUOVERE nel 2010!!
			SELECT
				@au6birthplace = geo_city.title,
				@au7birthprovince = case 
					when geo_city.idcity in (13935, 13936, 13937, 13938, 13940, 13942, 13943) then 'BA'
					when geo_city.idcity in (13939, 13941, 13944) then 'FG'
					else geo_country.province end
				FROM geo_city 
				LEFT OUTER JOIN geo_country ON geo_city.idcountry = geo_country.idcountry
				WHERE geo_city.idcity=@idcitynascita
		END
		SELECT @codfiscEnte = cf FROM license
	--1 Tipo record
		INSERT INTO #recHNonArrot (progr, quadro, riga, colonna, stringa) VALUES(@progrCom, 'HRH', 1, '01', 'H')
	--2 Codice fiscale del soggetto dichiarante
		INSERT INTO #recHNonArrot (progr, quadro, riga, colonna, stringa) VALUES(@progrCom, 'HRH', 1, '02', @codfiscEnte)
	--3 Progressivo comunicazione
		INSERT INTO #recHNonArrot (progr, quadro, riga, colonna, intero)  VALUES(@progrCom, 'HRH', 1, '03', @progrCom)
	--6 Codice fiscale del percipiente
		INSERT INTO #recHNonArrot (progr, quadro, riga, colonna, stringa) VALUES(@progrCom, 'HRH', 1, '06', @au1cf)
		DECLARE @cfsoftwarehouse varchar(16)
		SET @cfsoftwarehouse = '05587470724'
	--9 Identificativo del produttore del software (codice fiscale)
