CREATE   TRIGGER [trigger_d_storeunloaddetail] ON [storeunloaddetail] FOR DELETE
AS BEGIN
DECLARE @oldnumber decimal (19,2)
DECLARE @oldidbooking int
DECLARE @oldidstock int
SELECT  @oldnumber = number , @oldidbooking = idbooking,  @oldidstock = idstock FROM deleted

DECLARE @idstore int
DECLARE @idlist int
SELECT  @idstore = idstore, @idlist = idlist FROM stock WHERE idstock = @oldidstock
UPDATE stocktotal SET number = number + @oldnumber 
 WHERE idstore = @idstore and idlist = @idlist
-- se collegata alla prenotazione devo diminuire anche la q.tà prenotata
IF (@oldidbooking is not null)
Begin
	UPDATE stocktotal SET booked = booked + @oldnumber 
	WHERE idstore = @idstore and idlist = @idlist  

IF EXISTS (SELECT * FROM booktotal 
		   WHERE idstore = @idstore AND 
				 idlist = @idlist AND 
				 idbooking = @oldidbooking)
BEGIN
	UPDATE booktotal 
	SET	number	  = number + @oldnumber, 
		allocated = allocated + @oldnumber 
	WHERE idstore = @idstore AND idlist = @idlist 
	AND idbooking = @oldidbooking
END
ELSE 
BEGIN
	INSERT INTO booktotal (idstore,idlist,idbooking,number,allocated)
	SELECT @idstore, @idlist, @oldidbooking,@oldnumber,@oldnumber
END
End
END


