INSERT INTO #fin_situation(
	idfin, nlevel,
	idupb,
	assured,
	idman,
	sec_initial_prevision,
	flagconsider
)
SELECT 
	F.idfin, F.nlevel,
	isnull(@fixedidupb, U.idupb),
	ISNULL(U.assured,'N'),
