		AND expenseyear.ayear = @ayear
		AND ( (expensetotal.flag & 1) = 0) -- 'C'
		AND expense.nphase >= @finphase
		AND expensevar.amount < 0
	GROUP BY expense.nphase

	INSERT INTO #var_finphase_R
