if object_id('[trigger_i_mandatedetail]') is not null
	drop TRIGGER [trigger_i_mandatedetail]
go
CREATE   TRIGGER [trigger_i_mandatedetail] ON [mandatedetail] FOR INSERT
AS BEGIN
DECLARE @newnumber decimal (19,2)
DECLARE @newidlist int
DECLARE @idstore int
DECLARE @newyman int
DECLARE @newnman int
DECLARE @newidmankind varchar(20)
DECLARE @newrownum int
DECLARE @newidgroup int

SELECT  @newidmankind = idmankind, @newyman = yman , 
		@newnman = nman, @newrownum = rownum, @newidgroup = idgroup  FROM inserted 
SELECT  @idstore = idstore FROM mandate WHERE  @newidmankind = idmankind and @newyman = yman and @newnman = nman
SELECT  @newnumber = number , @newidlist = idlist  FROM inserted
IF ((@newidlist IS NULL) OR ( @idstore IS NULL))	RETURN
IF   (@newrownum <> 
	 (SELECT MIN(ISNULL(rownum, @newrownum)) FROM mandatedetail  
	   WHERE @newidmankind = idmankind and @newyman = yman and 
		     @newnman = nman and @newidgroup = idgroup))
RETURN
IF exists( select * from stocktotal where idstore = @idstore AND idlist = @newidlist) 
Begin
	UPDATE stocktotal SET ordered = ordered + @newnumber WHERE idstore = @idstore AND idlist = @newidlist
End
Else
Begin
	INSERT INTO stocktotal
		(idstore, idlist, number, ordered, booked)
	VALUES (@idstore, @newidlist, 0, @newnumber, 0)
End
END

GO

print '[trigger_i_mandatedetail] OK'

GO
if object_id('exp_f24ep') is not null
	drop procedure exp_f24ep
go

CREATE   procedure exp_f24ep(@idf24ep int) as
begin
	create table #tributi (
		tiporiga char(1),
		codicetributo varchar(4),
		tipoente varchar(4),
		rifA varchar(6),
		rifB  varchar(6)
	)
	--exec exp_f24ep 5
	
	insert into #tributi values ('S','384E','CCCC','00MM','AAAA') -- Addizionale comunale Irpef trattenuta dai sostituti d’imposta -saldo  
	insert into #tributi values ('S','385E','CCCC','00MM','AAAA') -- Addizionale comunale Irpef trattenuta dai sostituti d’imposta- acconto 
	insert into #tributi values ('S','891E','CCCC',  null,'AAAA') -- Sanzioni per ravvedimento su Addizionale comunale Irpef trattenuta dai sostituti d’imposta 
	--insert into #tributi values ('382E',  'EE','00MM','AAAA') -- Addizionale comunale Irpef trattenuta dai sostituti d’imposta  su emolumenti corrisposti nell’anno solare 2007–saldo  	
	--insert into #tributi values ('383E',  'EE','00MM','AAAA') -- Addizionale comunale Irpef trattenuta dai sostituti d’imposta su emolumenti corrisposti nell’anno solare 2007- acconto    
	
	insert into #tributi values ('R','380E',  'RR','00MM','AAAA') -- IRAP  	
	insert into #tributi values ('R','381E',  'RR','00MM','AAAA') -- Addizionale regionale Irpef trattenuta dai sostituti d’imposta  
	insert into #tributi values ('R','892E',  'RR',  null,'AAAA') -- Sanzioni per ravvedimento su IRAP 
	insert into #tributi values ('R','893E',  'RR',  null,'AAAA') -- Sanzioni per ravvedimento Addizionale regionale Irpef trattenuta dai sostituti d’imposta  
	
	insert into #tributi values ('F','100E',  null,'00MM','AAAA') -- Ritenute sui redditi da lavoro dipendente ed assimilati  
	insert into #tributi values ('F','104E',  null,'00MM','AAAA') -- Ritenute sui redditi da lavoro autonomo  
	insert into #tributi values ('F','105E',  null,'00MM','AAAA') -- Ritenute sulle indennità di esproprio, occupazione , etc. - articolo 11, legge 413/91  
	insert into #tributi values ('F','106E',  null,'00MM','AAAA') -- Ritenute sui contributi corrisposti alle imprese - articolo 28 D.P.R. 600/73 
	insert into #tributi values ('F','107E',  null,'00MM','AAAA') -- Altre ritenute alla fonte  
	insert into #tributi values ('F','890E',  null,  null,'AAAA') -- Sanzioni per ravvedimento su ritenute erariali 
	insert into #tributi values ('F','112E',  null,'00MM','AAAA') -- Ritenuta alla fonte su somme pignorate 
	insert into #tributi values ('I','C10',  null,  'MMAAAA',null) -- Sanzioni per ravvedimento su ritenute erariali 
	insert into #tributi values ('I','CXX',  null,  'MMAAAA',null) -- Sanzioni per ravvedimento su ritenute erariali 
	insert into #tributi values ('Q','P101',  null,  'MMAAAA','MMAAAA') -- Sanzioni per ravvedimento su ritenute erariali 
	insert into #tributi values ('Q','P909',  null,  'MMAAAA','MMAAAA') -- Sanzioni per ravvedimento su ritenute erariali 
	
	--declare @annodichiarazione int
	--set @annodichiarazione = 2008
	
	--select * from #tributi
	create table #f24 (
		tiporiga char(1),
		codicetributo varchar(4),
		codice  varchar(4), -- ex codiceEnte
		estremi varchar(17),
		riferimentoA varchar(6),
		riferimentoB varchar(6),
		importoADebito decimal(19,2),
		
	)
           

	create table #errori (
		taxcode int,
		idexp int,
		ytaxpay smallint,
		ntaxpay int,
		message varchar(200)
	)

	insert into #errori (taxcode, idexp, ytaxpay, ntaxpay, message)
		select taxpay.taxcode, null, taxpay.ytaxpay, taxpay.ntaxpay,
		'Il tributo '+isnull(tax.taxref,'')+' ha il codice '+
		isnull(tax.fiscaltaxcode,'')+
		' che non è gestito dalla procedura di generazione del modello f24ep'
		from taxpay 
		join tax on tax.taxcode = taxpay.taxcode
		where idf24ep = @idf24ep
		and not exists (select * from #tributi where #tributi.codicetributo = tax.fiscaltaxcode)
	if (select count(*) from #errori) > 0
	begin
		select * from #errori
		return
	end
	declare @codiceTributo varchar(4)
	declare @importoADebito decimal(19,2)
	declare @tiporiga char(1)
	declare @codice  varchar(4) --ex codiceEnte
	declare @estremi varchar(17)
	declare @riferimentoA varchar(6)
	declare @riferimentoB varchar(6)
	declare @rifA varchar(6)
	declare @rifB varchar(6)

	declare @taxcode int
	declare @idexp int
	declare @transmissiondate datetime
	declare @ytaxpay smallint
	declare @ntaxpay int
	declare @idcity int
	declare @idfiscaltaxregion varchar(5)
	declare @idcountry int
	declare @geoappliance char(1)
	declare @tipoEnte varchar(4)
	declare @sanctioncode varchar(4)
	declare @ayearsanction smallint
	declare @idreg int
	declare @fiscalyear int
	declare @annotrasmissione smallint
	declare @iniziocompetenza datetime
	declare @finecompetenza datetime
	declare @mese int
	declare @anno smallint
	declare @mycity varchar(100)
	declare @mycap	varchar(5)
	--declare @12gen08 datetime
	--select  @12gen08 = dateadd(yy, @annodichiarazione-2000, {d '2000-01-12'})
						
	--declare @idf24ep int
	--set @idf24ep = 1
	create table #versamenti (
		maintaxcode int,
		idcity  int,
		idfiscaltaxregion varchar(5),
		taxcode int,
		idexp int,
		idreg int,
		ytaxpay smallint,
		ntaxpay int,
		sanctioncode varchar(4),
		ayearsanction smallint,
		importoadebito decimal(19,2),
		datatrasmissione datetime,
		annotrasmissione smallint,
		iniziocompetenza datetime,--da expenselast
		finecompetenza datetime, --da expenselast
		anno smallint,
		meseriferimento int
		)
	
	INSERT INTO  #versamenti
	(maintaxcode, idcity, idfiscaltaxregion, taxcode, idexp,idreg, ytaxpay, ntaxpay, 
	importoadebito, datatrasmissione, annotrasmissione, meseriferimento,iniziocompetenza,finecompetenza, anno)
	select  maintaxcode = taxpay.taxcode, expensetax.idcity,
		expensetax.idfiscaltaxregion,expensetax.taxcode, 
		expensetax.idexp, expense.idreg, taxpay.ytaxpay, taxpay.ntaxpay,
		importoadebito = isnull(sum(isnull(admintax,0)+isnull(employtax,0)),0),
		paymenttransmission.transmissiondate, 
		year(paymenttransmission.transmissiondate),
		month(paymenttransmission.transmissiondate),
		expenselast.servicestart,expenselast.servicestop,
		isnull(expensetax.ayear,year(paymenttransmission.transmissiondate))
		--expensetax.ayear
		from taxpay 
		join tax on isnull(tax.maintaxcode, tax.taxcode) = taxpay.taxcode
		join expensetax 
			on expensetax.taxcode = tax.taxcode
			and expensetax.ytaxpay = taxpay.ytaxpay
			and expensetax.ntaxpay = taxpay.ntaxpay
		join expense
			on expense.idexp = expensetax.idexp
		join expenselast 
			on expenselast.idexp = expense.idexp
		join payment 
			on payment.kpay = expenselast.kpay
		join paymenttransmission 
			on paymenttransmission.kpaymenttransmission = 
			payment.kpaymenttransmission
		where taxpay.idf24ep = @idf24ep
		group by expensetax.taxcode, taxpay.taxcode, expensetax.idcity,
		expensetax.idfiscaltaxregion,expensetax.idexp, taxpay.ytaxpay, taxpay.ntaxpay,
		paymenttransmission.transmissiondate, year(paymenttransmission.transmissiondate), 
		month(paymenttransmission.transmissiondate), expenselast.servicestart,expenselast.servicestop,
		isnull(expensetax.ayear,year(paymenttransmission.transmissiondate)), expense.idreg
	--select 1,* from #versamenti
	--insert da expensetaxcorrige
	INSERT INTO  #versamenti
	(maintaxcode, idcity, idfiscaltaxregion, taxcode, idexp, idreg, ytaxpay, ntaxpay, importoadebito,
	 datatrasmissione, annotrasmissione, meseriferimento,iniziocompetenza,finecompetenza, anno)
	select  maintaxcode = taxpay.taxcode, expensetaxcorrige.idcity,
		expensetaxcorrige.idfiscaltaxregion, expensetaxcorrige.taxcode, 
		expensetaxcorrige.idexp,expense.idreg, taxpay.ytaxpay, taxpay.ntaxpay,
		importoadebito = isnull(sum(isnull(adminamount,0)+isnull(employamount,0)),0),
		paymenttransmission.transmissiondate, 
		year(paymenttransmission.transmissiondate),
		month(paymenttransmission.transmissiondate),
		expenselast.servicestart,expenselast.servicestop,
		isnull(expensetaxcorrige.ayear,year(paymenttransmission.transmissiondate))
		--expensetax.ayear
		from taxpay 
		join tax on isnull(tax.maintaxcode, tax.taxcode) = taxpay.taxcode
		join expensetaxcorrige 
			on expensetaxcorrige.taxcode = tax.taxcode
			and expensetaxcorrige.ytaxpay = taxpay.ytaxpay
			and expensetaxcorrige.ntaxpay = taxpay.ntaxpay
		join expense
			on expense.idexp = expensetaxcorrige.idexp
		join expenselast 
			on expenselast.idexp = expense.idexp
		join payment 
			on payment.kpay = expenselast.kpay
		join paymenttransmission 
			on paymenttransmission.kpaymenttransmission = 
			payment.kpaymenttransmission
		where taxpay.idf24ep = @idf24ep
		group by expensetaxcorrige.taxcode, taxpay.taxcode, expensetaxcorrige.idcity,
		expensetaxcorrige.idfiscaltaxregion,expensetaxcorrige.idexp, taxpay.ytaxpay, taxpay.ntaxpay,
		paymenttransmission.transmissiondate, year(paymenttransmission.transmissiondate), 
		month(paymenttransmission.transmissiondate),expenselast.servicestart,expenselast.servicestop,
		isnull(expensetaxcorrige.ayear,year(paymenttransmission.transmissiondate)),expense.idreg
		update #versamenti set meseriferimento=12 where anno<year(datatrasmissione)
		update #versamenti set anno=year(datatrasmissione)-1 where anno<year(datatrasmissione)
	--select * from #versamenti
	-- Sanzioni per Ravvedimento Operoso
	INSERT INTO  #versamenti
		(sanctioncode,idcity,idfiscaltaxregion,importoadebito, ayearsanction)
	SELECT  fiscaltaxcode,
		ISNULL(idcity,0),
		idfiscaltaxregion,
		importoadebito = isnull(amount,0),
		f24epsanction.ayear
		FROM   f24epsanction 
		JOIN   f24epsanctionkind  
		ON f24epsanction.idsanction = f24epsanctionkind.idsanction
		WHERE  f24epsanction.idf24ep = @idf24ep
	
	--select 2,* from #versamenti
	--select * from #versamenti
	--drop table #versamenti
	declare  @myfiscalregion int
	declare @myidcity int
	select @myidcity=max(idcity) from	license
	select @mycity = title from geo_city where idcity= @myidcity
	select @mycap= max(cap) from license
	select @myfiscalregion= idfiscaltaxregion from geo_cityfiscalview where idcity=@myidcity
	declare @cursore cursor

	set @cursore = cursor for 
		select taxcode, idexp, idreg, idcity,idfiscaltaxregion, ytaxpay, ntaxpay, 
		importoadebito, datatrasmissione, annotrasmissione, meseriferimento, anno,
		sanctioncode, ayearsanction, iniziocompetenza,finecompetenza
		from #versamenti
	
	open @cursore
	fetch next from @cursore into @taxcode, @idexp, @idreg, @idcity,
			@idfiscaltaxregion, @ytaxpay, @ntaxpay, 
			@importoADebito, @transmissiondate, @annotrasmissione, 
			@mese, @anno,
			@sanctioncode, @ayearsanction, @iniziocompetenza, @finecompetenza
	while @@fetch_status = 0
	begin
		set @codice = null --ex @codiceEnte
		set @geoappliance = null
		set @riferimentoA=null
		set @riferimentoB=null
		set @estremi=null
		set @tiporiga=null
		set @codiceTributo =null
		set @tipoente=null
		set @rifA =null
		set @rifB =null
		select  @codiceTributo = tax.fiscaltaxcode, 
			@tiporiga = #tributi.tiporiga,
			@tipoente = #tributi.tipoente, 
			@rifA = #tributi.rifA,
			@rifB= #tributi.rifB,
			@geoappliance = tax.geoappliance
			from tax 
			join #tributi on #tributi.codicetributo = tax.fiscaltaxcode
			where tax.taxcode = @taxcode
		
		
		--SANZIONI PER RAVVEDIMENTO OPEROSO
		IF      @sanctioncode IS NOT NULL
		BEGIN
			SELECT @codiceTributo = @sanctioncode,
			@tiporiga = #tributi.tiporiga,
			@tipoente = #tributi.tipoente, 
			@rifA = #tributi.rifA,
			@rifB = #tributi.rifB,
			@anno = @ayearsanction
			FROM #tributi 
			WHERE #tributi.codicetributo = @sanctioncode
		END

		--Per l'irap (380e) facciamo un calcolo a parte per determinare la città e regione
		if (@codiceTributo='380E' )			
		begin
			set @idcity= @myidcity
			set @idfiscaltaxregion=@myfiscalregion
		end
		
	
		if (@codiceTributo='CXX' OR @codiceTributo='C10')			
		begin
			set @estremi= @mycap+substring(@mycity,1,12)
			select  @codice = idinpscenter from config where ayear=@anno
		end
		
		if (@codiceTributo='P101' OR @codiceTributo='P909')			
		begin
			select @codice = max(country) from license
		end
		
		if (@geoappliance ='C' and @idcity is null)
		begin 
		insert into #errori (taxcode, idexp, ytaxpay, ntaxpay, message)
			values (@taxcode, @idexp, @ytaxpay, @ntaxpay, 
			'Per il tributo con codice ' + isnull(@codiceTributo, '')
			+ ' non è stato valorizzato il comune di riferimento');
		end

		if (@geoappliance ='R' and @idfiscaltaxregion is null )
		begin 
		insert into #errori (taxcode, idexp, ytaxpay, ntaxpay, message)
			values (@taxcode, @idexp, @ytaxpay, @ntaxpay, 
			'Per il tributo con codice ' + isnull(@codiceTributo, '')
			+ ' non è stato valorizzata la regione di riferimento');
		end
		if (@rifA = '00MM')
		begin
			if (@mese>9) set @riferimentoA= '00'+convert(varchar(2),@mese)
			if (@mese<=9) set @riferimentoA= '000'+convert(varchar(2),@mese)
		end
		if (@rifA = 'MMAAAA' and @rifB is null)
		begin
			if (@mese>9) set @riferimentoA= convert(varchar(2),@mese)+convert(varchar(4),@anno)
			if (@mese<=9) set @riferimentoA= '0'+convert(varchar(2),@mese)+convert(varchar(4),@anno)
		end
		if (@rifA = 'MMAAAA' and @rifB is not null)
		begin
			if (month(@iniziocompetenza)>9) set @riferimentoA= 
				convert(varchar(2),month(@iniziocompetenza))+convert(varchar(4),year(@iniziocompetenza))
			if (month(@iniziocompetenza)<=9) set @riferimentoA= '0'+
				convert(varchar(2),month(@iniziocompetenza))+convert(varchar(4),year(@iniziocompetenza))
		end
		if (@rifA='00MM' and @riferimentoA is null)
			insert into #errori (taxcode, idexp, ytaxpay, ntaxpay, message)
					values (@taxcode, @idexp, @ytaxpay, @ntaxpay, 
					'Per il tributo con codice ' + isnull(@codiceTributo, '')
					+ ' la procedura non è stata in grado di ricavare il mese di riferimento');
		if (@rifA='MMAAAA' and @riferimentoA is null and @rifB is null)
			insert into #errori (taxcode, idexp, ytaxpay, ntaxpay, message)
					values (@taxcode, @idexp, @ytaxpay, @ntaxpay, 
					'Per il tributo con codice ' + isnull(@codiceTributo, '')
					+ ' la procedura non è stata in grado di ricavare la data di pagamento');
		if (@rifA='MMAAAA' and @riferimentoA is null and @rifB is not null)
			insert into #errori (taxcode, idexp, ytaxpay, ntaxpay, message)
					values (@taxcode, @idexp, @ytaxpay, @ntaxpay, 
					'Per il tributo con codice ' + isnull(@codiceTributo, '')
					+ ' la procedura non è stata in grado di ricavare la data di inizio competenza');

		if (@rifB = 'MMAAAA' )
		begin
			if (month(@finecompetenza)>9) set @riferimentoB= 
				convert(varchar(2),month(@finecompetenza))+convert(varchar(4),year(@finecompetenza))
			if (month(@finecompetenza)<=9) set @riferimentoB= '0'+
				convert(varchar(2),month(@finecompetenza))+convert(varchar(4),year(@finecompetenza))
		end
		if (@rifB = 'AAAA' )
		begin
			set @riferimentoB=convert(varchar(4),@anno)
		end

		if (@rifB='AAAA' and @riferimentoB is null)
			insert into #errori (taxcode, idexp, ytaxpay, ntaxpay, message)
					values (@taxcode, @idexp, @ytaxpay, @ntaxpay, 
					'Per il tributo con codice ' + isnull(@codiceTributo, '')
					+ ' la procedura non è stata in grado di ricavare l''anno di riferimento');
		if (@rifB='MMAAAA' and @riferimentoB is null)
			insert into #errori (taxcode, idexp, ytaxpay, ntaxpay, message)
					values (@taxcode, @idexp, @ytaxpay, @ntaxpay, 
					'Per il tributo con codice ' + isnull(@codiceTributo, '')
					+ ' la procedura non è stata in grado di ricavare la data di fine competenza');

				
		
--sezione: ENTI LOCALI
		if @tipoente in ('CCCC','EE')
		begin
			
			select @fiscalyear = @anno  -- anno fiscale letto da expensetax e non da payroll o dal contratto
			
			
			-- CODICE ENTE LOCALE TAB T1 (EE)  
			-- SOLO 
			if @tipoEnte = 'EE'
			begin
				select @codice = case 
						when geo_country.idcountry = 21 then '03'--Bolzano
						when geo_country.idregion = 6 then '07'--Friuli Venezia Giulia
						when geo_country.idcountry = 22 then '18'--Trento
						when geo_country.idregion = 2 then '20'--Valle d'Aosta
						else '99' 
					end
					from geo_country
					join geo_city 
						on geo_city.idcountry = geo_country.idcountry
					where geo_city.idcity = @idcity
				
				if @codice is null
					begin 
					insert into #errori (taxcode, idexp, ytaxpay, ntaxpay, message)
						values (@taxcode, @idexp, @ytaxpay, @ntaxpay, 
						'Per il tributo con codice ' + isnull(@codiceTributo, '')
						+ ' la procedura non è stata in grado di ricavare il codice dell''ente 
						(provincia autonoma/regione)');
					end
			end
			
			
		end
		
		
		
		
		-- CODICE CATASTALE COMUNE (CCCC)  
		if @tipoEnte = 'CCCC'
		begin
			select @codice = geo_city_agency.value
				from geo_city_agency
				where geo_city_agency.idcity = @idcity
				and geo_city_agency.idagency = 1
				and geo_city_agency.idcode = 1
			
			if @codice is null
				begin 
				insert into #errori (taxcode, idexp, ytaxpay, ntaxpay, message)
					values (@taxcode, @idexp, @ytaxpay, @ntaxpay, 
					'Per il tributo con codice ' + isnull(@codiceTributo, '')
					+ ' la procedura non è stata in grado di ricavare il codice dell''ente 
					(comune)');
				end
		end
			
		--sezione: REGIONI  
		if @tipoente = 'RR'
		begin
			select  @codice = @idfiscaltaxregion
			
			if @codice is null
			begin 
				insert into #errori (taxcode, idexp, ytaxpay, ntaxpay, message)
					values (@taxcode, @idexp, @ytaxpay, @ntaxpay, 
					'Per il tributo con codice ' + isnull(@codiceTributo, '')
					+ ' la procedura non è stata in grado di ricavare il codice dell''ente (regione)');
			end
		end
						
		insert into #f24 (tiporiga,codicetributo, codice, estremi, riferimentoA, riferimentoB, importoADebito)
			values (@tiporiga, @codiceTributo, @codice, @estremi, @riferimentoA, @riferimentoB, @importoADebito)

		fetch next from  @cursore into @taxcode, @idexp, @idreg, @idcity,
			@idfiscaltaxregion, @ytaxpay, @ntaxpay, 
			@importoADebito, @transmissiondate, @annotrasmissione, @mese, @anno,
			@sanctioncode, @ayearsanction, @iniziocompetenza, @finecompetenza
	end
	
  --select  * from #f24 order by codicetributo

	if (select count(*) from #errori) > 0
	begin
		select 
			'Ritenuta' = tax.taxref,
			'Eserc.liquidaz.' = #errori.ytaxpay,
			'Num.liquidaz.' = #errori.ntaxpay,
			'Fase spesa' = expensephase.description,
			'Eserc.movim.' = expense.ymov,
			'Num.movim.' = expense.nmov,
			'Problema riscontrato' = #errori.message
			from #errori
			join expense on expense.idexp = #errori.idexp
			join expensephase on expensephase.nphase = expense.nphase
			join tax on tax.taxcode = #errori.taxcode
	end else begin
		select tiporiga,codicetributo, codice, estremi,riferimentoA,riferimentoB,
		importoadebito = sum(importoADebito)
		from #f24
		group by tiporiga,codicetributo, codice,  estremi,riferimentoA,riferimentoB
	
	end
	
end

GO

print 'exp_f24ep OK'

GO
if object_id('rpt_unified_bilprevisioneriep') is not null
	drop procedure rpt_unified_bilprevisioneriep
go

CREATE procedure rpt_unified_bilprevisioneriep
	@ayear 		int,
	@finpart 	char(1),
	@levelusable 	tinyint,
	@idsor01 int=null,
	@idsor02 int=null,
	@idsor03 int=null,
	@idsor04 int=null,
	@idsor05 int=null
as begin
	create table #bilprevisioneriep (
		idfin			int, 
		code1			varchar(50),
		desc1			varchar(150),
		printorder1 		varchar(50),
		codeupb			varchar(50)	,
		idupb 			varchar(36)	,
		upb   			varchar(150)	,
		upbprintingorder	varchar(50)	,
		prevision		decimal(19,2)	,
		previousprevision	decimal(19,2)	,
		secondaryprevision	decimal(19,2)	,
		previoussecprevision	decimal(19,2)	,
		currentarrears		decimal(19,2)	,
		previousarrears		decimal(19,2)	,
		accretion_var		decimal(19,2)	,
		diminution_var		decimal(19,2)	,
		sec_accretion_var	decimal(19,2)	,
		sec_diminution_var	decimal(19,2)	,
		rep_accretion_var	decimal(19,2)	,
		rep_diminution_var	decimal(19,2)	,
		previsionkind		char,
		display_aa		varchar(50),
		supposed_ff		decimal(19,2),
		supposed_aa		decimal(19,2),
		supposed_ff_prec	decimal(19,2),
		supposed_aa_prec	decimal(19,2)
	)
	
	declare @iddbdepartment varchar(50)
	declare @crsdepartment cursor
	set @crsdepartment = cursor for select  iddbdepartment from dbdepartment
							 where (start is null or start <= @ayear ) AND ( stop is null or stop >= @ayear)
	open @crsdepartment
	fetch next from @crsdepartment into @iddbdepartment
	while @@fetch_status=0 begin
		declare @s varchar(300)
		set @s = @iddbdepartment + '.rpt_bilprevisione_riep'
		insert into #bilprevisioneriep
			(idfin, code1, desc1, printorder1, 
			codeupb, idupb,	upb, upbprintingorder,
			prevision, previousprevision, secondaryprevision, previoussecprevision,
			currentarrears,	previousarrears, 
			accretion_var, diminution_var, sec_accretion_var, sec_diminution_var,
			rep_accretion_var, rep_diminution_var,
			previsionkind, display_aa,
			supposed_ff, supposed_aa,
			supposed_ff_prec, supposed_aa_prec)
			exec @s @ayear, @finpart, @levelusable, '%', 'N', 'N', @idsor01, @idsor02 , @idsor03 , @idsor04 , @idsor05
		fetch next from @crsdepartment into @iddbdepartment
	end
	select * from #bilprevisioneriep
end


GO

print 'rpt_unified_bilprevisioneriep OK'

GO
if object_id('[rpt_partitario_spesa_cassa]') is not null
	drop PROCEDURE [rpt_partitario_spesa_cassa]
go

CREATE    PROCEDURE [rpt_partitario_spesa_cassa]
	@ayear int,
	@kind char(1),
	@idupb	varchar(36),
	@nlevel tinyint,
	@start datetime,
	@stop datetime,
	@showupb char(1),
	@showchildupb char(1),
	@suppressifblank char(1),
	@flagnofficial	char(1),
	@idfin int
AS
BEGIN
--exec rpt_partitario_spesa_cassa 2011, 'S', '%',  3, {ts '2011-06-01 00:00:00'}, {ts '2011-12-31 00:00:00'}, 'N', 'N', 'N', 'N', NULL 		
CREATE TABLE #previousexpense
(
	idfin int,
	idupb varchar(36),
	initialprevision decimal(19,2),
	finvar decimal(19,2),
	cassaphase_amount decimal(19,2)
)
DECLARE @idupboriginal varchar(36)
SET @idupboriginal= @idupb
IF (@showchildupb = 'S') 
BEGIN
	SET @idupb=@idupb+'%' 
END	
DECLARE @kind_bit  tinyint 
IF @kind='C' set @kind_bit = 0
IF @kind='R' set @kind_bit = 1
DECLARE @levelusable tinyint
SELECT 	@levelusable = MIN(nlevel)
FROM 	finlevel
WHERE 	flag&2 <> 0 AND ayear = @ayear
DECLARE @finphase tinyint
DECLARE @finname varchar(50)
SELECT  @finphase = appropriationphasecode FROM config WHERE 	ayear = @ayear
SELECT  @finname = description FROM expensephase WHERE nphase = @finphase
DECLARE @maxexpensephase tinyint 
DECLARE @phasecassa varchar(50)
SELECT  @maxexpensephase = MAX(nphase) FROM 	expensephase
SELECT  @phasecassa = description FROM expensephase WHERE nphase = @maxexpensephase

DECLARE @regphase tinyint 
SELECT  @regphase = expenseregphase FROM uniconfig

DECLARE @level_input tinyint
SET  @level_input = ISNULL((SELECT nlevel from fin where idfin = @idfin) ,@nlevel)
-- ho scelto come livello 2 e poi ho specificato il capitolo, lui corregge @nlevel dandogli 3
IF (@nlevel < @level_input ) AND (@idfin is not null)
BEGIN
	SET  @nlevel = @level_input
END
IF (@levelusable < @nlevel)
BEGIN	
	SET @levelusable = @nlevel
END
 
DECLARE @level varchar(50)
SELECT  @level = description 
	FROM    finlevel
	WHERE   nlevel = @nlevel AND ayear = @ayear
CREATE TABLE #expense
(
	codeupb varchar(50),
	idupb varchar(36),
	upb varchar(150),
	upbprintingorder varchar(50),
	idfin int,
	rowkind	int,
	idmov int,
	nphase tinyint,
	operationdate datetime,
	operationkind varchar(55),
	idreg int,
	ymov int,
	nmov int,
	nofficial int,
	nsubmov int,
	ndoc int,
	description varchar(150),
        doc varchar(150),
	initialprevision decimal(19,2),
	finvar decimal(19,2),
	finphase_amount decimal(19,2),
	cassaphase_amount decimal(19,2),
	emessiondate datetime,
	printeddate datetime,
	trasmitteddate datetime,
	transactiondate datetime,
	annulmentdate datetime,
	annotations varchar(400),
	available decimal(19,2),
	hierarchy varchar (50)
)
DECLARE @firstday datetime
SET 	@firstday = CONVERT(datetime, '01-01-' + CONVERT(varchar(4),@ayear), 105)
DECLARE @cashvaliditykind       	int
SELECT  @cashvaliditykind = cashvaliditykind
FROM    config
WHERE   ayear = @ayear
DECLARE @previsionkind char(1) 
SELECT  @previsionkind =  
	 CASE 
		WHEN fin_kind IN (1,3) THEN 'C'
		WHEN fin_kind = 2 THEN 'S'
	 END
FROM  config 
WHERE config.ayear = @ayear
DECLARE @secprevisionkind    char(1) 
SELECT  @secprevisionkind  = 
	 CASE 
		WHEN fin_kind = 3 THEN 'S'
		ELSE NULL
	END
FROM config 
WHERE config.ayear = @ayear

IF ((@kind IN ('C','S')) AND (DATEDIFF(DAY,@start, @firstday) = 0))
BEGIN
	INSERT INTO #expense
	(
		idfin,
		codeupb,
		idupb,
		upb,
		upbprintingorder,
		rowkind,
		operationdate,
		operationkind,
		initialprevision
	)
	SELECT 
		isnull(finlink.idparent, fin.idfin),
		upb.codeupb,
		upb.idupb,
		upb.title,
		upb.printingorder,
		1,
		@firstday,
		'Prev.iniziale',
		CASE
		WHEN @kind = 'C' THEN (SELECT SUM(fy2.prevision) 
					FROM finyear fy2 
					JOIN fin f2
						ON fy2.idfin=f2.idfin
					left outer JOIN finlink
						ON finlink.idchild = fy2.idfin
						AND finlink.nlevel = @nlevel
					WHERE finlink.idparent = fin.idfin
						AND f2.nlevel  = @levelusable 
						AND fy2.idupb  = upb.idupb)
		WHEN (@kind = 'S' and @previsionkind = 'S') 
				THEN (SELECT SUM(fy2.prevision) 
					FROM finyear fy2 
					JOIN fin f2
						ON fy2.idfin=f2.idfin
					left outer JOIN finlink
						ON finlink.idchild = fy2.idfin
						AND finlink.nlevel = @nlevel
					WHERE finlink.idparent = fin.idfin
						AND f2.nlevel  = @levelusable 
						AND fy2.idupb  = upb.idupb)
		WHEN (@kind = 'S' and @secprevisionkind = 'S') 
				THEN (SELECT SUM(fy2.secondaryprev) 
					FROM finyear fy2 
					JOIN fin f2
						ON fy2.idfin=f2.idfin
					left outer JOIN finlink
						ON finlink.idchild = fy2.idfin
						AND finlink.nlevel = @nlevel
					WHERE finlink.idparent = fin.idfin
						AND f2.nlevel  = @levelusable 
						AND fy2.idupb  = upb.idupb)
		END
	FROM finyear
	JOIN fin
		ON finyear.idfin = fin.idfin
	JOIN upb
		ON finyear.idupb = upb.idupb
	left outer JOIN finlink
		ON finlink.idchild = finyear.idfin
		AND finlink.nlevel = @level_input
	WHERE (upb.idupb like @idupb )
		AND fin.ayear = @ayear
		AND ((fin.flag&1)<>0) 
		AND fin.nlevel = @nlevel
		AND (@idfin IS NULL OR isnull(finlink.idparent, fin.idfin) = @idfin)
END

IF (DATEDIFF(DAY,@start, @firstday) <> 0)
BEGIN
	INSERT INTO #previousexpense
		(
		idfin,
		idupb
		)
	SELECT isnull(finlink.idparent, finyear.idfin),
	       finyear.idupb
	FROM finyear
	JOIN fin
		ON finyear.idfin = fin.idfin
	JOIN upb
		ON finyear.idupb = upb.idupb
	left outer JOIN finlink
		ON finlink.idchild = finyear.idfin
		AND finlink.nlevel = @level_input
	WHERE (upb.idupb like @idupb )
	AND fin.ayear = @ayear
	AND ((fin.flag&1)<>0) 
	AND fin.nlevel = @nlevel
	AND (@idfin IS NULL OR isnull(finlink.idparent, fin.idfin) = @idfin)	

INSERT INTO #previousexpense
	(
	idfin,
	idupb
	)--> Prende quelli che non ha preso prima perchè non presenti in finyear  
	SELECT 
	isnull(FL1.idparent, fin.idfin),
	expenseyear.idupb
	FROM expenseyear
	JOIN expense
		ON expense.idexp = expenseyear.idexp
	JOIN expensetotal
		ON  expenseyear.idexp = expensetotal.idexp
		AND expenseyear.ayear = expensetotal.ayear	
	left outer JOIN finlink
		ON finlink.idchild = expenseyear.idfin
		AND finlink.nlevel = @level_input
	left outer JOIN finlink FL1
		ON FL1.idchild = expenseyear.idfin	
		AND FL1.nlevel = @nlevel
	JOIN fin
		ON fin.idfin = isnull(FL1.idparent, fin.idfin)--FL1.idparent
	WHERE /*((expensetotal.flag&1) = @kind_bit)
		AND */expense.adate < @start
		AND expense.nphase = @finphase
		AND expenseyear.ayear = @ayear
		AND (expenseyear.idupb like @idupb )
		AND fin.ayear = @ayear
		AND ((fin.flag&1)<>0) 
		AND (@idfin IS NULL OR isnull(finlink.idparent, fin.idfin) = @idfin)	
		AND NOT EXISTS (SELECT #previousexpense.idfin,#previousexpense.idupb
			FROM #previousexpense
			WHERE #previousexpense.idupb = expenseyear.idupb 
				AND #previousexpense.idfin = isnull(finlink.idparent, fin.idfin))
	GROUP by expenseyear.idupb,isnull(FL1.idparent, fin.idfin)--> altrimenti prende una coppia per ogni stanziamento imputato a quella coppia
	IF @kind = 'C' OR @kind = 'S'
	BEGIN
		UPDATE #previousexpense
		SET initialprevision =
			(SELECT 
				CASE
					WHEN @kind = 'C' THEN SUM(u2.prevision) 
					WHEN (@kind = 'S' and @previsionkind = 'S') THEN SUM(u2.prevision) 
					WHEN (@kind = 'S' and @secprevisionkind = 'S') THEN SUM(u2.secondaryprev) 
				END
			FROM finyear u2
			JOIN fin f2
				ON u2.idfin = f2.idfin	
			left outer JOIN finlink
				ON finlink.idchild = f2.idfin 
				AND finlink.nlevel =  @nlevel
			WHERE u2.idupb= #previousexpense.idupb
			AND finlink.idparent =  #previousexpense.idfin
			AND f2.nlevel = @levelusable),
		finvar =
			(SELECT SUM(finvardetail.amount)
			FROM finvardetail
			JOIN finvar
				ON finvar.yvar = finvardetail.yvar
				AND finvar.nvar = finvardetail.nvar
			left outer JOIN finlink
				ON finlink.idchild = finvardetail.idfin  
				AND finlink.nlevel = @nlevel	
			WHERE finvardetail.idupb = #previousexpense.idupb 
			AND finvar.flagprevision ='S'
			AND finvar.variationkind <> 5
			AND finvar.adate < @start
			AND finvar.yvar = @ayear
			AND finlink.idparent  = #previousexpense.idfin)
	END
	ELSE
	BEGIN
		UPDATE #previousexpense
		SET initialprevision =
				(SELECT SUM(expenseyear.amount)
				FROM expenseyear
				JOIN expense
					ON expense.idexp = expenseyear.idexp
				JOIN expensetotal
					ON  expenseyear.idexp = expensetotal.idexp
					AND expenseyear.ayear = expensetotal.ayear	
				left outer JOIN finlink
					ON finlink.idchild = expenseyear.idfin
					AND finlink.nlevel = @nlevel
				WHERE  /*((expensetotal.flag&1) = @kind_bit)
					AND*/ expense.adate < @start
					AND expense.nphase = @finphase
					AND expenseyear.idupb = #previousexpense.idupb
					AND finlink.idparent  = #previousexpense.idfin
					AND expenseyear.ayear = @ayear)
	END
	
	IF (@cashvaliditykind <> 4)
	BEGIN
		UPDATE #previousexpense
		SET cassaphase_amount =
			ISNULL((SELECT SUM(HPV.amount)
			FROM historypaymentview HPV
			left outer JOIN finlink
				ON finlink.idchild = HPV.idfin	
				AND finlink.nlevel = @nlevel
			WHERE (HPV.flagarrear = @kind OR @kind = 'S')
				AND HPV.competencydate < @start
				AND HPV.idupb = #previousexpense.idupb
				AND finlink.idparent = #previousexpense.idfin
				AND HPV.ymov = @ayear), 0)
			+ 
			ISNULL((SELECT SUM(expensevar.amount)
			FROM expensevar
			JOIN historypaymentview HPV
				ON HPV.idexp = expensevar.idexp
			left outer JOIN finlink
				ON finlink.idchild = HPV.idfin	
				AND finlink.nlevel = @nlevel
			WHERE HPV.ymov = @ayear
				AND HPV.idupb = #previousexpense.idupb
				AND finlink.idparent = #previousexpense.idfin
				AND (HPV.flagarrear = @kind OR @kind = 'S')
				AND expensevar.yvar = @ayear
				AND expensevar.adate < @start
				AND HPV.competencydate <= @start
				AND HPV.ymov = @ayear
			), 0)
	END
	ELSE
	BEGIN
		UPDATE #previousexpense
		SET cassaphase_amount =
			ISNULL((SELECT SUM(HPV.amount)
			FROM historypaymentview HPV
			left JOIN finlink
				ON finlink.idchild = HPV.idfin	
				AND finlink.nlevel = @nlevel
			WHERE (HPV.flagarrear = @kind OR @kind = 'S')
				AND HPV.competencydate < @start
				AND HPV.idupb = #previousexpense.idupb
				AND finlink.idparent = #previousexpense.idfin
				AND HPV.ymov = @ayear), 0)
	END	
	INSERT INTO #expense
	(
		idfin,
		idupb,
		codeupb,upb,upbprintingorder,
		rowkind,
		operationdate,
		operationkind,
		initialprevision,
		finvar,
		cassaphase_amount
	)
	SELECT
		#previousexpense.idfin,
		upb.idupb,
		upb.codeupb,
		upb.title,
		upb.printingorder,
		1,
		DATEADD(dd, -1, @start),
		'Tot.prec.',
		#previousexpense.initialprevision,
		#previousexpense.finvar,
		#previousexpense.cassaphase_amount
	FROM #previousexpense
	JOIN fin
		ON fin.idfin = #previousexpense.idfin
	JOIN upb 
		ON upb.idupb=#previousexpense.idupb	
END	
--	Variazioni di previsione
IF (@kind IN ('C','S')) 
	BEGIN
	INSERT INTO #expense
		(
		idfin,
		idupb,codeupb,upb,upbprintingorder,
		rowkind,
		operationdate,
		operationkind,
		ymov,
		nmov,
		nofficial,
		description,
		finvar
		)
	SELECT 
		isnull(finlink.idparent, fin.idfin),
		upb.idupb,
		upb.codeupb,
		upb.title,
		upb.printingorder,
		2,
		finvar.adate,
		'Var.prev.',
		finvar.yvar,
		finvar.nvar,
		CASE finvar.official
			WHEN 'S' THEN finvar.nofficial
			ELSE NULL
		END,
		finvar.description,
		finvardetail.amount
	FROM finvardetail
	JOIN finvar
		ON finvar.yvar = finvardetail.yvar
		AND finvar.nvar = finvardetail.nvar
	JOIN upb 
		ON upb.idupb=finvardetail.idupb AND  (upb.idupb like @idupb )
	left outer JOIN finlink
		ON finlink.idchild = finvardetail.idfin	
		AND finlink.nlevel = @level_input
	JOIN fin
		ON fin.idfin = finvardetail.idfin
	WHERE finvar.flagprevision = 'S'	
		AND finvar.adate BETWEEN @start AND @stop
		AND finvar.variationkind <> 5
		AND fin.ayear = @ayear
		AND ((fin.flag&1)<>0) 
		AND (@idfin IS NULL OR isnull(finlink.idparent, fin.idfin) = @idfin)	
END

-- Movimenti di spesa / fase cassa
INSERT INTO #expense
		(
		idfin,
		idmov,
		idupb,
		codeupb,
		upb,
		upbprintingorder,
		rowkind,
		nphase,
		operationdate,
		operationkind,
		ymov,
		nmov,
		ndoc,
		description,
		doc,
		idreg,
		cassaphase_amount
		)
SELECT 
	isnull(FL1.idparent, fin.idfin),
	HPV.idexp,
	upb.idupb,upb.codeupb,upb.title,
	upb.printingorder,
	15,
	@maxexpensephase,
	HPV.competencydate,
	@phasecassa,
	HPV.ymov,
	HPV.nmov,
	HPV.npay,
	HPV.description,
	CASE
		WHEN HPV.doc IS NOT NULL AND 
			HPV.docdate IS NULL THEN
			'Pag. ' + HPV.doc
		WHEN HPV.doc IS NOT NULL AND
			HPV.docdate IS NOT NULL THEN
			'Pag. ' + HPV.doc + 
			' del ' + CONVERT(varchar(20), HPV.docdate, 105)
		ELSE
			(NULL)
	END,
	HPV.idreg,
	HPV.amount
FROM historypaymentview HPV
JOIN upb 
	ON upb.idupb = HPV.idupb		
left outer JOIN finlink
	ON finlink.idchild = HPV.idfin	
	AND finlink.nlevel = @level_input
left outer JOIN finlink FL1
	ON FL1.idchild = HPV.idfin	
	AND FL1.nlevel = @nlevel
JOIN fin
	ON fin.idfin = FL1.idparent
WHERE HPV.competencydate BETWEEN @start AND @stop
	AND (upb.idupb like @idupb )
	AND HPV.ymov = @ayear
	AND ((@kind IN ('C', 'R') AND HPV.flagarrear = @kind) OR @kind = 'S')
	AND fin.ayear = @ayear
	AND ((fin.flag&1)<>0) -- Spesa
	AND (@idfin IS NULL OR isnull(finlink.idparent, fin.idfin) = @idfin)
-- Variazione ai Movimenti di spesa / fase cassa
IF (@cashvaliditykind <> 4)
BEGIN
	INSERT INTO #expense
		(
		idfin,
		idmov,
		idupb, codeupb,upb,upbprintingorder,
		rowkind,
		nphase,
		operationdate,
		operationkind,
		ymov,
		nmov,
		nsubmov,
		ndoc,
		description,
		doc,
		idreg,
		cassaphase_amount
		)
	SELECT 
		isnull(FL1.idparent, fin.idfin),
		expense.idexp,
		upb.idupb, upb.codeupb,upb.title,upb.printingorder,
		20,
		expense.nphase,
		expensevar.adate,
		'Var.' + @phasecassa,
		expense.ymov,
		expense.nmov,
		expensevar.nvar,
		HPV.npay,
		expensevar.description,
		CASE
			WHEN expensevar.doc IS NOT NULL AND 
				expensevar.docdate IS NULL THEN
				'Pag. ' + expensevar.doc
			WHEN expensevar.doc IS NOT NULL AND
				expensevar.docdate IS NOT NULL THEN
				'Pag. ' + expensevar.doc + 
				' del ' + CONVERT(varchar(20), expensevar.docdate, 105)
			ELSE
		(NULL)
		END,
		expense.idreg,
		expensevar.amount
		FROM expensevar
		JOIN historypaymentview HPV
			ON HPV.idexp = expensevar.idexp
		JOIN expense
			ON expense.idexp = expensevar.idexp
		JOIN upb
			ON upb.idupb = HPV.idupb
		left outer JOIN finlink
			ON finlink.idchild = HPV.idfin	
			AND finlink.nlevel = @level_input
		left outer JOIN finlink FL1
			ON FL1.idchild = HPV.idfin	
			AND FL1.nlevel = @nlevel
		JOIN fin
		ON fin.idfin = FL1.idparent
		WHERE expensevar.yvar = @ayear
		AND expensevar.adate BETWEEN @start AND @stop
		AND isnull(expensevar.autokind,'') <>'22' 
		AND (upb.idupb like @idupb )
		AND HPV.ymov = @ayear
		AND fin.ayear = @ayear
		AND ((fin.flag&1)<>0) -- Spesa
		AND (@idfin IS NULL OR isnull(finlink.idparent, fin.idfin) = @idfin) 
		AND ((@kind IN ('C', 'R') AND HPV.flagarrear = @kind) OR @kind = 'S')
		AND HPV.competencydate BETWEEN @start AND @stop
		AND HPV.ymov = @ayear
END

-- costruisce la gerarchia del movimento per creare l'ordinamento nel report
UPDATE #expense 
SET 
	hierarchy = convert(varchar(4),E1.ymov) + '/' + Replicate('0',6-len(convert(varchar(6),E1.nmov)))+ 
		    convert(varchar(6),E1.nmov)
FROM expense
JOIN expenselink EL1
	ON EL1.idchild = expense.idexp  AND EL1.nlevel = 1
LEFT OUTER JOIN expenselink EL2
	ON EL2.idchild = expense.idexp  AND EL2.nlevel = 2
LEFT OUTER JOIN expenselink EL3
	ON EL3.idchild = expense.idexp  AND EL3.nlevel = 3
LEFT OUTER JOIN expenselink EL4
	ON EL4.idchild = expense.idexp  AND EL4.nlevel = 4
LEFT OUTER JOIN expenselink EL5
	ON EL5.idchild = expense.idexp  AND EL4.nlevel = 5
LEFT OUTER JOIN expense E1
	ON E1.idexp = EL1.idparent
LEFT OUTER JOIN expense E2
	ON E2.idexp = EL2.idparent
LEFT OUTER JOIN expense E3
	ON E3.idexp = EL3.idparent
LEFT OUTER JOIN expense E4
	ON E4.idexp = EL4.idparent
LEFT OUTER JOIN expense E5
	ON E5.idexp = EL5.idparent
WHERE  EL1.idchild = #expense.idmov

UPDATE #expense
	SET 	emessiondate = paymentview.adate,
		printeddate = 	paymentview.printdate,
		trasmitteddate = paymentview.transmissiondate,	
		transactiondate = paymentperformed.competencydate,
		annulmentdate = paymentview.annulmentdate
	FROM paymentview
	LEFT OUTER JOIN banktransaction
		ON banktransaction.kpay=paymentview.kpay	
		AND (banktransaction.kind='D' OR banktransaction.kind IS NULL)
	LEFT OUTER JOIN  paymentperformed 
		ON paymentperformed.npay=paymentview.npay
		AND paymentperformed.ypay=paymentview.ypay
	WHERE #expense.ndoc = paymentview.npay and paymentview.ypay=@ayear

IF (@suppressifblank = 'N') 
BEGIN
--se ho scelto di vedere l'upb inserisco le coppie upb/bilancio altrimenti inserisco solo il bilanico non utilizzato
	IF ( (@showupb <>'S') and (@idupboriginal = '%'))
	Begin
		INSERT INTO #expense 
			(
				idfin,
				rowkind
				)
		SELECT 
			fin.idfin,
			1
		FROM fin 
		JOIN finlink
			ON finlink.idchild = fin.idfin	
			AND finlink.nlevel = @level_input
		WHERE  fin.ayear = @ayear
			AND ((fin.flag&1) <>0 ) -- Spesa
			AND fin.nlevel = @nlevel
			AND (@idfin IS NULL OR isnull(finlink.idparent, fin.idfin) = @idfin)
			and not exists (SELECT *
				FROM #expense
				WHERE fin.idfin = #expense.idfin )
		End
	Else
		Begin
		INSERT INTO #expense 
			(
				idfin,
				idupb,
				codeupb,
				upb,
				upbprintingorder,
				rowkind
				)
		SELECT 
			fin.idfin,
			upb.idupb,
			codeupb,
			upb.title,
			upb.printingorder,
			1
		FROM fin CROSS JOIN upb 
		left outer JOIN finlink
			ON finlink.idchild = fin.idfin	
			AND finlink.nlevel = @level_input
		WHERE (upb.idupb like @idupb )
			AND fin.ayear = @ayear
			AND ((fin.flag&1)<>0) -- Spesa
			AND fin.nlevel = @nlevel
			AND (@idfin IS NULL OR isnull(finlink.idparent, fin.idfin) = @idfin)
			and not exists (SELECT *
				FROM #expense
				WHERE upb.idupb = #expense.idupb 
				AND fin.idfin = #expense.idfin )
		End
END
IF (@showupb <>'S') AND (@idupboriginal <> '%' ) AND (@showchildupb = 'S')
	UPDATE #expense 
	SET  
		upbprintingorder = (SELECT TOP 1 upbprintingorder
			FROM #expense
			WHERE idupb = @idupboriginal),
		upb = (SELECT TOP 1 upb
			FROM #expense
			WHERE idupb = @idupboriginal),
		idupb = @idupboriginal,
		codeupb =(SELECT TOP 1 codeupb
			FROM #expense	
			WHERE idupb = @idupboriginal)
IF (@showupb <>'S') and (@idupboriginal = '%')
	UPDATE #expense SET  
		upbprintingorder = null	,
		upb =  null,
		idupb = null,
		codeupb = null
-- se ho scelto di nascondere le voci di bilancio non utilizzate:
-- cancello le righe che hanno valori pari a zero 
-- per cui non esistono variazioni di previzioni (rowkind=2) o movimenti di entrata (rowkind >= 3 )  
IF (@suppressifblank = 'S') AND @nlevel>2	--> se la stampa è x un livello sottostante la categoria cancella le righe
BEGIN
	DELETE FROM #expense WHERE 
		ISNULL(initialprevision,0)=0 AND 
		ISNULL(finvar,0)=0 AND 
		ISNULL(cassaphase_amount,0)=0 AND
		NOT EXISTS (select * from  #expense i
				where isnull(#expense.idupb,'')=isnull(i.idupb,'') AND 
				      #expense.idfin=i.idfin AND 
					i.rowkind>1)
END
IF (@showupb <>'S') 
BEGIN
	SELECT 
		#expense.idfin,
		idmov,
		@level as levelname,
		F.codefin,
		F.printingorder as finprintingorder,
		F.title,
		codeupb,idupb,upb,upbprintingorder,rowkind,
		nphase,
		operationdate,
		operationkind,ymov,nmov,nofficial,nsubmov,
		ndoc,description,doc,annotations,
		REG.title as registry,	
		isnull(sum(initialprevision),0) as initialprevision,
		isnull(sum(finvar),0) as finvar	,
		--isnull(sum(finphase_amount),0) as finphase_amount,
		isnull(sum(available),0) as available,
		isnull(sum(cassaphase_amount),0) as cassaphase_amount,
		emessiondate,printeddate,trasmitteddate,transactiondate,annulmentdate,
		@finname as finname,	
		@phasecassa as phasecassa,
		hierarchy
	FROM #expense
	JOIN fin F
		ON F.idfin = #expense.idfin
	LEFT OUTER JOIN registry REG
		ON REG.idreg = #expense.idreg  
	GROUP BY codeupb,idupb,upb,upbprintingorder,hierarchy,
		F.printingorder,#expense.idfin,idmov,F.codefin,F.title,
		rowkind,nphase,operationdate,operationkind,ymov,nmov,nofficial,nsubmov,ndoc,description,doc,
		annotations,REG.title,emessiondate,printeddate			,
		trasmitteddate,transactiondate,annulmentdate
	ORDER BY upbprintingorder ASC, finprintingorder ASC,hierarchy ASC,
		rowkind ASC,
		ymov ASC,
		nmov ASC,
		nofficial ASC,
		nsubmov ASC
END
ELSE
BEGIN
	SELECT #expense.idfin,
		idmov,
		@level as levelname,
		F.codefin,
		F.printingorder as finprintingorder,
		F.title,
		codeupb,idupb,upb,upbprintingorder,rowkind,
		nphase,operationdate,operationkind,ymov,nmov,nofficial,nsubmov,
		ndoc,description,doc,annotations,
		REG.title as registry,	
		isnull(sum(initialprevision),0) as initialprevision,
		isnull(sum(finvar),0) as finvar,
		--isnull(sum(finphase_amount),0) as finphase_amount,
		isnull(sum(available),0) as available,
		isnull(sum(cassaphase_amount),0) as cassaphase_amount,
		emessiondate,printeddate,trasmitteddate,transactiondate,annulmentdate,
		@finname as finname,	
		@phasecassa as phasecassa,
		hierarchy
 	FROM #expense	
	JOIN fin F
		ON F.idfin = #expense.idfin
	LEFT OUTER JOIN registry REG
		ON REG.idreg = #expense.idreg	
	GROUP BY codeupb,idupb,upb,upbprintingorder,
		hierarchy,
		F.printingorder,#expense.idfin,idmov,F.codefin,F.title,
		rowkind,nphase,operationdate,operationkind,ymov,nmov,nofficial,nsubmov,ndoc,description,doc,
		annotations,REG.title,emessiondate,printeddate			,
		trasmitteddate,transactiondate,annulmentdate
	ORDER BY upbprintingorder ASC, F.printingorder ASC,hierarchy ASC,
		rowkind ASC,
		ymov ASC,
		nmov ASC,
		nofficial ASC,
		nsubmov ASC
END
END


GO

print '[rpt_partitario_spesa_cassa] OK'

