CREATE      PROCEDURE [rpt_asset_label]
(
	@idinventory int,
	@ayear int,
	@idinventoryagency int,
	@start int,
	@stop int
)
AS 
BEGIN
CREATE TABLE #output (agencycode varchar(20), codeinventoryagency varchar(20), nassetload int, yassetload int, 
					  ninventory int, tipoinventario varchar(20), description varchar(150), barcode varchar(100))
DECLARE @agencycode varchar(20) 
DECLARE @codeinventoryagency varchar(20) 
DECLARE @nassetload int
DECLARE @yassetload int
DECLARE @ninventory int
DECLARE @tipoinventario varchar(20)
DECLARE @description varchar(150)
DECLARE @barcode varchar(100)
DECLARE @inventario varchar(100)
DECLARE #con_crs INSENSITIVE CURSOR FOR
SELECT ISNULL(ia.agencycode,'') as agencycode, 
	ia.codeinventoryagency, 
	al.nassetload, 
	al.yassetload, 
	a.ninventory, 
	CASE 
		WHEN (I.CODEINVENTORY like '%ord%') OR (I.CODEINVENTORY like '%MAIN%') THEN 'O'
		WHEN (I.CODEINVENTORY like '%lib%') OR (I.CODEINVENTORY like '%BOOK%') THEN 'L'
	END as 'tipoinventario',
	aq.description 
	FROM asset a
		JOIN assetacquire aq
			ON a.nassetacquire = aq.nassetacquire
		JOIN assetload al
			ON aq.idassetload = al.idassetload
		JOIN inventory i
			ON aq.idinventory = i.idinventory
		JOIN inventoryagency ia 
			ON i.idinventoryagency = ia.idinventoryagency
	WHERE aq.idinventory= @idinventory
	AND a.ninventory between @start and @stop
	AND ia.idinventoryagency= @idinventoryagency
	AND al.yassetload = @ayear
FOR READ ONLY
OPEN #con_crs
FETCH NEXT FROM #con_crs INTO @agencycode, @codeinventoryagency, @nassetload, @yassetload, @ninventory, @tipoinventario, @description 
WHILE(@@FETCH_STATUS = 0)
BEGIN
	
	SET @inventario = convert(varchar(100),@ninventory)
	execute calc_barcode @inventario, @barcode OUTPUT
	INSERT INTO #output (agencycode, codeinventoryagency, nassetload, yassetload, ninventory, tipoinventario, description, barcode )
	values(@agencycode, @codeinventoryagency, @nassetload, @yassetload, @ninventory, @tipoinventario, @description, @barcode)
	
	FETCH NEXT FROM #con_crs INTO @agencycode, @codeinventoryagency, @nassetload, @yassetload, @ninventory, @tipoinventario, @description 
END
CLOSE #con_crs
DEALLOCATE #con_crs
SELECT agencycode, codeinventoryagency, nassetload, yassetload, ninventory, tipoinventario, description, barcode FROM #output
ORDER BY ninventory
END 

GO

print '[rpt_asset_label] OK'

GO
if object_id('exp_consolidamento_bari_residui_var') is not null
	drop PROCEDURE exp_consolidamento_bari_residui_var
go


CREATE            PROCEDURE exp_consolidamento_bari_residui_var
(
	@ayear int,
	@finpart char(1),
	@levelusable tinyint
)
AS 
BEGIN
/* Versione 1.0.0 del 04/03/2008 ultima modifica: GIUSEPPE */
--  exec exp_consolidamento_bari_residui_var 2007,'S',2
CREATE TABLE #output
(
	nrow int,
	ymov int,
	nmov int,
	idmov int,
	idfin int,
	startamount decimal(19,2),
	variationamount decimal(19,2),
	lastphaseamount decimal(19,2)
)
DECLARE @arrearsphase tinyint
DECLARE @maxphase tinyint
IF @finpart = 'E'
BEGIN
	SELECT @arrearsphase = assessmentphasecode FROM config WHERE ayear = @ayear
	SELECT @maxphase = MAX(nphase) FROM incomephase
END
ELSE
BEGIN
	SELECT @arrearsphase = appropriationphasecode FROM config WHERE ayear = @ayear
	SELECT @maxphase = MAX(nphase) FROM expensephase
END
IF @finpart = 'E'
BEGIN
	INSERT INTO #output (nrow, ymov, nmov, idmov, idfin, startamount, variationamount)
	SELECT
		0, incomeview.ymov, incomeview.nmov, incomeview.idinc,
		finlink.idparent, 
		incomeview.ayearstartamount,
		-ISNULL(
			(SELECT SUM(amount) FROM incomevar
			WHERE incomevar.idinc = incomeview.idinc
				AND incomevar.yvar = @ayear)
		,0)
	FROM incomeview
	LEFT OUTER JOIN finlink
		ON finlink.idchild = incomeview.idfin
	WHERE finlink.nlevel = @levelusable
		AND incomeview.nphase = @arrearsphase
		AND ymov < @ayear
		AND ayear = @ayear
	UPDATE #output SET lastphaseamount = 
	ISNULL(
		(SELECT SUM(curramount)
		FROM incomeview
		JOIN incomelink
			ON incomeview.idinc = incomelink.idchild
		WHERE incomelink.idparent = #output.idmov
			AND incomeview.ayear = @ayear
			AND incomeview.nphase = @maxphase)
	,0)
END
ELSE
BEGIN
	INSERT INTO #output (nrow, ymov, nmov, idmov, idfin, startamount, variationamount)
	SELECT
		0, expenseview.ymov, expenseview.nmov, expenseview.idexp,
		finlink.idparent, 
		expenseview.ayearstartamount,
		-ISNULL(
			(SELECT SUM(amount) FROM expensevar
			WHERE expensevar.idexp = expenseview.idexp
				AND expensevar.yvar = @ayear)
		,0)
	FROM expenseview
	LEFT OUTER JOIN finlink
		ON finlink.idchild = expenseview.idfin
	WHERE finlink.nlevel = @levelusable
		AND expenseview.nphase = @arrearsphase
		AND ymov < @ayear
		AND ayear = @ayear
	UPDATE #output SET lastphaseamount = 
	ISNULL(
		(SELECT SUM(curramount)
		FROM expenseview
		JOIN expenselink
			ON expenseview.idexp = expenselink.idchild
		WHERE expenselink.idparent = #output.idmov
			AND expenseview.ayear = @ayear
			AND expenseview.nphase = @maxphase)
	,0)
END
INSERT INTO #output (nrow, startamount, variationamount, lastphaseamount)
SELECT 1, SUM(startamount), SUM(variationamount), SUM(lastphaseamount)
FROM #output
IF @finpart = 'E'
BEGIN
	SELECT 
		#output.ymov as 'Esercizio',
		#output.nmov as 'Numero',
		CASE
			WHEN nrow = 0
			THEN fin.codefin
			ELSE 'TOTALE'
		END  as 'Cod. Bilancio',
		CASE
			WHEN nrow = 0
			THEN fin.title
			ELSE NULL
		END as 'Descr. Bilancio',
		startamount as 'Importo all''1/1',
		variationamount as 'Variazioni in Diminuzione',
		lastphaseamount as 'Incassato',
		ISNULL(startamount,0) - ISNULL(variationamount,0) - ISNULL(lastphaseamount,0) as 'Importo al 31/12'
	FROM #output
	LEFT OUTER JOIN fin
		ON fin.idfin = #output.idfin
	ORDER BY nrow, ymov, nmov
END
ELSE
BEGIN
	SELECT 
		#output.ymov as 'Esercizio',
		#output.nmov as 'Numero',
		CASE
			WHEN nrow = 0
			THEN fin.codefin
			ELSE 'TOTALE'
		END as 'Cod. Bilancio',
		CASE
			WHEN nrow = 0
			THEN fin.title
			ELSE NULL
		END as 'Descr. Bilancio',
		startamount as 'Importo all''1/1',
		variationamount as 'Variazioni in Diminuzione',
		lastphaseamount as 'Pagato',
		ISNULL(startamount,0) - ISNULL(variationamount,0) - ISNULL(lastphaseamount,0) as 'Importo al 31/12'
	FROM #output
	LEFT OUTER JOIN fin
		ON fin.idfin = #output.idfin
	ORDER BY nrow, ymov, nmov
END
END

GO

print 'exp_consolidamento_bari_residui_var OK'

