CREATE      PROCEDURE [rpt_partitario_class_mov]
	@ayear smallint,
	@idsorkind int,
	@incomeorexpense  char(1),
	@start smalldatetime,
	@stop  smalldatetime,
	@showupb char(1),
	@idupb varchar(36),
	@showchildupb char(1)
AS
BEGIN
	DECLARE @idupboriginal 	varchar(36)
	SET @idupboriginal= @idupb
	IF (@showchildupb = 'S') set @idupb=@idupb+'%' 
	
	CREATE TABLE #sortedmov
	(
		idsorkind  varchar(20),
		descriptionsortingkind varchar(50),
		sortcode varchar(50),
		sortingdescription varchar(200),
		adate smalldatetime,
		phasedescription varchar(50),
		ymov smallint,
		nmov int,
		registry varchar(100),
		codefin	varchar(50),
		idupb varchar(36),
		codeupb varchar(50),
		upb varchar(150),
		description varchar(300),  
		curramount decimal(19,2),
		sortedamount decimal(19,2)
	)
	
	DECLARE @descriptionsortingkind	varchar(50)
	SELECT @descriptionsortingkind = description
		FROM sortingkind
		WHERE idsorkind = @idsorkind
	DECLARE @nphasemovimento  tinyint
	IF (@incomeorexpense  = 'E')
	BEGIN
		SELECT @nphasemovimento = nphaseincome
			FROM sortingkind
			WHERE idsorkind = @idsorkind
		INSERT INTO #sortedmov
			(
				idsorkind,
				descriptionsortingkind,
				sortcode,
				sortingdescription,
				adate,
				phasedescription,
				ymov,
				nmov,
				registry,
				codefin,
				idupb,
				codeupb,
				upb, 
				description,
				curramount,
				sortedamount
			)
			SELECT
				@idsorkind,
				@descriptionsortingkind,
			  	sorting.sortcode,
				sorting.description,
				income.adate,
				incomephase.description,
				income.ymov,
				income.nmov,
				registry.title,
				fin.codefin,
				upb.idupb,
				upb.codeupb,
				upb.title, 
				--income.description,
				case 
				when isnull(income.doc,'')='' then income.description 
				when isnull(income.doc,'') <> '' and isnull(income.docdate,'')='' 
					then	income.description + 
						' (Doc. ' 
						+ isnull(Convert (varchar(35),ISNULL(income.doc,'')),'') + ')'
				else  income.description + 
					' (Doc. ' 
					+ isnull(Convert (varchar(35),ISNULL(income.doc,'')),'') + ' del '
					+ iSNULL(Convert (varchar(2),datepart(dd,income.docdate))+'/'+Convert (varchar(2),datepart(mm,income.docdate))+'/'+Convert (varchar(4),datepart(yy,income.docdate)),'')
					+')'	
				end,
				incometotal.curramount,
				incomesorted.amount
			FROM income
			JOIN incometotal
				ON incometotal.idinc = income.idinc
			JOIN incomeyear
				ON incomeyear.idinc = income.idinc
			JOIN incomesorted
				ON incomesorted.idinc = income.idinc
			JOIN sorting
				ON sorting.idsor = incomesorted.idsor
			JOIN incomephase
				ON incomephase.nphase = income.nphase
			LEFT OUTER JOIN registry
				ON registry.idreg = income.idreg
			LEFT OUTER JOIN fin
				ON fin.idfin = incomeyear.idfin
			LEFT OUTER JOIN upb 		
				on upb.idupb = incomeyear.idupb
			WHERE income.adate BETWEEN @start AND @stop
				AND incometotal.ayear = @ayear
				AND incomeyear.ayear = @ayear
				AND incomesorted.ayear=@ayear
				AND sorting.idsorkind = @idsorkind
				AND (  (incomeyear.idupb is null and @idupb='%') or (incomeyear.idupb like @idupb))		
		END
	IF (@incomeorexpense  = 'S')
	BEGIN
		SELECT 	@nphasemovimento = nphaseexpense
			FROM sortingkind
			WHERE idsorkind = @idsorkind
		INSERT INTO #sortedmov
			(
				idsorkind,
				descriptionsortingkind,
				sortcode,
				sortingdescription,
				adate,
				phasedescription,
				ymov,
				nmov,
				registry,
				codefin,
				idupb,
				codeupb,
				upb, 
				description,
				curramount,
				sortedamount
			)
			SELECT
				@idsorkind,
				@descriptionsortingkind,
				sorting.sortcode,
				sorting.description,
				expense.adate,
				expensephase.description,
				expense.ymov,
				expense.nmov,
				registry.title,
				fin.codefin,
				upb.idupb,
				upb.codeupb,
				upb.title, 
				case 
				when isnull(expense.doc,'')='' then expense.description 
				when isnull(expense.doc,'') <> '' and isnull(expense.docdate,'')='' 
					then	expense.description + 
						' (Doc. ' 
						+ isnull(Convert (varchar(35),ISNULL(expense.doc,'')),'') + ')'
				else  expense.description + 
					' (Doc. ' 
					+ isnull(Convert (varchar(35),ISNULL(expense.doc,'')),'') + ' del '
					+ iSNULL(Convert (varchar(2),datepart(dd,expense.docdate))+'/'+Convert (varchar(2),datepart(mm,expense.docdate))+'/'+Convert (varchar(4),datepart(yy,expense.docdate)),'')
					+')'	
				end,
				expensetotal.curramount,
				expensesorted.amount
			FROM expense
			JOIN expensetotal
			ON expensetotal.idexp = expense.idexp
			JOIN expenseyear
				ON expenseyear.idexp = expense.idexp
			JOIN expensesorted
				ON expensesorted.idexp = expense.idexp
			JOIN sorting
				ON sorting.idsor = expensesorted.idsor
			JOIN expensephase
				ON expensephase.nphase = expense.nphase
			LEFT OUTER JOIN registry
				ON registry.idreg = expense.idreg
			LEFT OUTER JOIN fin
				ON fin.idfin = expenseyear.idfin
			LEFT OUTER JOIN upb 		
				ON upb.idupb = expenseyear.idupb
			WHERE expense.adate BETWEEN isnull(@start, {d '1900-01-01'}) AND isnull(@stop, {d '2079-06-06'})
				AND expensetotal.ayear = @ayear
				AND expenseyear.ayear = @ayear
				AND sorting.idsorkind = @idsorkind
				AND expensesorted.ayear = @ayear
				AND (  (expenseyear.idupb is null and @idupb='%') or (expenseyear.idupb like @idupb))	
		END
	
/* nelle altre stampe viene preso il top 1 dalla tabella temporanea non dalla tabella upb. Questo è possibile perchè
	le altre stampe fanno un cross join per riempire la tab temporanea, mentre qui esegue solo una SELECT dei movimenti classificati.
*/
 	IF (@showupb <>'S') AND (@idupboriginal <> '%' ) AND (@showchildupb = 'S')
			UPDATE #sortedmov SET  
				upb = (SELECT TOP 1 title
					FROM upb
					WHERE idupb = @idupboriginal),
				idupb = @idupboriginal,
				codeupb =(SELECT TOP 1 codeupb
					FROM upb
					WHERE idupb = @idupboriginal)
/*	Questo segmento di codice è stato commentato perchè non serve porre a null
	il valore dell'UPB per annullare il raggruppamento nel report inquanto nel report non c'è un 
	raggruppamento ma solo una visualizzazione dell'UPB
	IF (@showupb <>'S') and (@idupboriginal = '%') 
				UPDATE #sortedmov SET  
				upb =  null,
				idupb = null,
				codeupb = null*/
	SELECT * FROM	 #sortedmov 
		ORDER BY idsorkind ASC, 
		sortcode ASC, 
		adate ASC,
		ymov ASC,
		nmov ASC
END



GO

print '[rpt_partitario_class_mov] OK'

GO
if object_id('[rpt_reversale_incasso_siope]') is not null
	drop PROCEDURE [rpt_reversale_incasso_siope]
go

CREATE   PROCEDURE [rpt_reversale_incasso_siope]
	@ayear int,
	@printkind char(1),
	@startnpro int,
	@stopnpro int,
	@printdate datetime,
	@official char(1),
	@oneprint char(1),
	@idtreasurer int
AS
BEGIN
-- exec rpt_reversale_incasso_siope 2012, 'I', 1, 300, null, 'N', 'N',7
IF 	@ayear=0  SET @ayear='1900'
CREATE TABLE #printing (npro int)
		
IF @printkind = 'A' 
BEGIN
	INSERT INTO #printing (npro) 
	SELECT npro FROM proceeds WHERE (ypro = @ayear) and (printdate is null) and idtreasurer = @idtreasurer
END
IF @printkind <> 'A'
BEGIN
	INSERT INTO #printing (npro) 
	SELECT npro FROM proceeds WHERE (ypro=@ayear) and (npro BETWEEN @startnpro AND @stopnpro)
	AND ((printdate IS NULL) OR (@oneprint = 'N')) and idtreasurer = @idtreasurer
END
/*
DECLARE @assessmentphasecode tinyint
SELECT  @assessmentphasecode = assessmentphasecode
FROM 	config
WHERE 	ayear = @ayear
IF 	@assessmentphasecode IS NULL
BEGIN
	SELECT @assessmentphasecode = incomefinphase
	FROM uniconfig
END

DECLARE @assessmentphase varchar(50)
SELECT 	@assessmentphase = description
	FROM incomephase
	WHERE nphase = @assessmentphasecode
SELECT 	@assessmentphase = LTRIM(RTRIM(@assessmentphase))
*/
-- lettura della fase di riferimento valorizzata come parametro aggiuntivo, codice e descrizione
DECLARE @paramphasecode varchar(2)
SELECT 	@paramphasecode =  paramvalue  FROM reportadditionalparam 
	WHERE reportname='reversale_incasso' and paramname='FaseDaVisualizzare'
DECLARE @phasecode int 
IF  (ISNUMERIC(ISNULL(@paramphasecode,'')) = 1 AND CONVERT(int, @paramphasecode)>0)
	SELECT @phasecode = CONVERT (int, @paramphasecode)
ELSE
	SELECT @phasecode = MAX(nphase) FROM incomephase
DECLARE @phasedescription varchar(50)
SELECT 	@phasedescription = description
	FROM incomephase
	WHERE nphase = @phasecode
SELECT 	@phasedescription = LTRIM(RTRIM(@phasedescription))

DECLARE @maxincomephase tinyint
SELECT  @maxincomephase = MAX(nphase) FROM incomephase
DECLARE @maxexpensephase tinyint
SELECT  @maxexpensephase = MAX(nphase) FROM expensephase

DECLARE @phaseexpense varchar(50)
SELECT 	@phaseexpense = description
	FROM expensephase
	WHERE nphase = @maxexpensephase
SELECT 	@phaseexpense = LTRIM(RTRIM(@phaseexpense))
DECLARE @incomeregphase	tinyint
SELECT @incomeregphase = incomeregphase FROM  uniconfig

CREATE TABLE #proceeds
(
	idinc int,
	ypro int, npro int,
	ymov int, nmov int,
	parentymov int, parentnmov int,
	parentdescription varchar(255),
	idman int,
	description varchar(255),
	idreg int,
	codeupb varchar(50),
	titleupb varchar(150),
	idupb varchar(36),
	ayear int,
	idfin int,
	codefin	varchar(50),
	fintitle varchar(150),
	nlevel tinyint,
	paridfin int,
	amount float,
	idtreasurer int,
	data datetime,
    accountkind char(1),        
	kind char(1),
	flagarrear char(1),
	rowkind int,
	autokind int, 
	detaildescription varchar(255),
	detailamount float,
	annulmentdate datetime,
	doc varchar(50), 
	docdate datetime,
	nbill int,
	billadate datetime,
	cupcode varchar(15),
	cupcodeincome varchar(15),
	idstamphandling int,
	flagbankitaliaproceeds char(1),
	flag_ccp char(1))
					
DECLARE @admintaxkind1 int
SELECT  @admintaxkind1 = (automanagekind & 0xf) FROM config WHERE ayear = @ayear
DECLARE @idreg int 
SELECT  @idreg = idregauto FROM config WHERE ayear = @ayear 
INSERT INTO #proceeds
	(
	rowkind, 
	idinc,	idreg,	ypro,	npro,	ymov,	nmov,
	parentymov, parentnmov,parentdescription,
	idman,	description,	idupb,	ayear,	idfin,
	codefin,	fintitle, nlevel,paridfin,	
	amount,
	idtreasurer,	data,	
	accountkind,kind,	
	flagarrear,
	annulmentdate,
	doc,	docdate, nbill, billadate, cupcode, cupcodeincome,
	idstamphandling,	flagbankitaliaproceeds,	flag_ccp 
	)
SELECT  
	0,
	income.idinc, income.idreg, income.ymov, proceeds.npro, income.ymov, income.nmov,
	parentincome.ymov, parentincome.nmov,parentincome.description,
	income.idman, income.description, incomeyear.idupb, incomeyear.ayear, fin.idfin,
	fin.codefin, fin.title, fin.nlevel, fin.paridfin,
	incometotal.curramount,
	proceeds.idtreasurer, proceeds.printdate,
        case proceeds.flag&8 when 0 then 'I' else 'F' end,
	case proceeds.flag&7 
		when 1 then 'C' 
		when 2 then 'R' 
		when 4 then 'M' 
	end,
	CASE
		WHEN ((incometotal.flag&1)=0) THEN 'C'
		WHEN ((incometotal.flag&1)=1) THEN 'R'
	END, 
	proceeds.annulmentdate,
	income.doc,
	income.docdate,	incomelast.nbill, bill.adate, finlast.cupcode, RegPhase.cupcode,
	proceeds.idstamphandling,
	CASE
		WHEN (incomelast.flag&8) <> 0 THEN 'S' -- RISCOSSIONE PRESSO TPS
		ELSE 'N'
	END,
	CASE
		WHEN (incomelast.flag&4) <> 0 THEN 'S' --PRELIEVO DA CONTO CORRENTE POSTALE
		ELSE 'N'
	END 
FROM income
JOIN incomeyear
	ON incomeyear.idinc = income.idinc
	AND incomeyear.ayear = @ayear
JOIN incometotal
	ON incometotal.idinc = incomeyear.idinc
	AND incometotal.ayear = incomeyear.ayear
JOIN incomelast
	ON incomelast.idinc = income.idinc
JOIN incomelink
	ON incomelink.idchild = incomelast.idinc
	AND incomelink.nlevel = @phasecode
JOIN income parentincome
	ON parentincome.idinc = incomelink.idparent
JOIN incomelink as RegPhaseILK	-- Dobbiamo risalire alla fase del creditore
	ON RegPhaseILK.idchild = incomelast.idinc
	AND RegPhaseILK.nlevel = @incomeregphase
JOIN income RegPhase			-- fase del Creditore
	ON RegPhase.idinc = RegPhaseILK.idparent 
 JOIN proceeds
	ON proceeds.kpro = incomelast.kpro
JOIN fin
	ON fin.idfin = incomeyear.idfin
JOIN finlast
	ON finlast.idfin = incomeyear.idfin
LEFT OUTER JOIN bill
	ON incomelast.nbill = bill.nbill and bill.ybill = @ayear and bill.billkind = 'C'
WHERE income.ymov = @ayear
	AND proceeds.npro in (select npro from #printing)
DECLARE @dateaddress datetime
SELECT  @dateaddress= CONVERT( datetime, '31-12-'+ CONVERT(varchar(4),@ayear), 105)
DECLARE @codestand varchar(20)
SET @codestand = '07_SW_DEF'
DECLARE @STAND int
SELECT @STAND = idaddress FROM address WHERE codeaddress = @codestand
CREATE TABLE #address
(
	idaddresskind int, idreg int, address varchar(100), location varchar(120),
	cap varchar(20), province varchar(2), nation varchar(65)	
)	
INSERT INTO #address (idreg, idaddresskind, address, location, cap, province, nation)
SELECT 
	registryaddress.idreg, registryaddress.idaddresskind, registryaddress.address,
	isnull(geo_city.title,'')+' '+isnull(registryaddress.location,''),
	registryaddress.cap, geo_country.province, geo_nation.title
FROM registryaddress
left outer join geo_city
	ON geo_city.idcity = registryaddress.idcity
left outer join geo_country
	ON geo_city.idcountry = geo_country.idcountry
left outer join geo_nation
	ON geo_nation.idnation = registryaddress.idnation
WHERE 
	(
	    registryaddress.active <>'N' 
	AND registryaddress.start = 
	(SELECT MAX(cdi.start) 
	FROM registryaddress cdi 
	WHERE cdi.idaddresskind = registryaddress.idaddresskind
	AND cdi.active <>'N' 
	AND ((cdi.stop is null) OR (cdi.stop >= @dateaddress)) 
	and cdi.idreg = registryaddress.idreg))
	AND (idreg IN (select idreg from  #proceeds))
	
DELETE #address
	WHERE #address.idaddresskind <> @stand
	AND EXISTS(
		SELECT * FROM #address r2 
		WHERE #address.idreg = r2.idreg
		AND r2.idaddresskind = @stand
	)
DELETE #address
	WHERE (
		SELECT COUNT(*) FROM #address r2 
		WHERE #address.idreg = r2.idreg
	)>1

INSERT INTO #proceeds
	(
	ypro, npro, ymov, nmov, 
	--parentymov,parentnmov,parentdescription, 
	autokind, idreg, detaildescription, detailamount, data,accountkind,kind, rowkind, annulmentdate,
	idstamphandling,flagbankitaliaproceeds,	flag_ccp)
SELECT DISTINCT
	income.ymov, proceeds.npro, income.ymov, income.nmov, 
	--parentincome.ymov, parentincome.nmov,parentincome.description, 
	income.autokind, income.idreg,
	CASE 
		WHEN payment.npay IS NOT NULL 
		THEN tax.description + ' (a carico percipiente) - mand. n. ' + CONVERT(varchar(6), payment.npay)
		ELSE tax.description + ' (a carico percipiente)'
	END,
	expensetax.employtax, proceeds.printdate, 
        case proceeds.flag&8 when 0 then 'I' else 'F' end,
	case proceeds.flag&7 
		when 1 then 'C' 
		when 2 then 'R' 
		when 4 then 'M' 
	end,
	1, proceeds.annulmentdate,
	proceeds.idstamphandling,
	CASE
		WHEN (incomelast.flag&8) <> 0 THEN 'S'
		ELSE 'N'
	END,
	CASE
		WHEN (incomelast.flag&4) <> 0 THEN 'S' --PRELIEVO DA CONTO CORRENTE POSTALE
		ELSE 'N'
	END 
	FROM income
	JOIN incomeyear
		ON incomeyear.idinc = income.idinc
	JOIN incomelast
		ON incomelast.idinc = income.idinc
	--JOIN incomelink
		--ON incomelink.idchild = incomelast.idinc
		--AND incomelink.nlevel = @phasecode
	--JOIN income parentincome
		--ON parentincome.idinc = incomelink.idparent
	JOIN proceeds
		ON proceeds.kpro = incomelast.kpro
	JOIN expensetax
		ON expensetax.idexp = income.idpayment
	JOIN tax
		ON tax.taxcode = expensetax.taxcode
	JOIN expense
		ON expense.idexp = income.idpayment
	JOIN expenselast
		ON expenselast.idexp = expense.idexp
	left outer join payment
		on payment.kpay = expenselast.kpay
	LEFT OUTER JOIN incometotal incometotal_firstyear(NOLOCK)
  		ON incometotal_firstyear.idinc = income.idinc
  		AND ((incometotal_firstyear.flag & 2) <> 0 )
	LEFT OUTER JOIN incomeyear incomeyear_starting(NOLOCK) 
		ON incomeyear_starting.idinc = incometotal_firstyear.idinc
  		AND incomeyear_starting.ayear = incometotal_firstyear.ayear
	WHERE income.ymov = @ayear
	AND (income.idreg <> @idreg OR @idreg IS NULL)
		AND expensetax.employtax > 0
		AND expensetax.employtax = incomeyear_starting.amount 
		AND incomeyear.ayear = @ayear
		AND proceeds.npro in (select npro from #printing)
DECLARE @paymentphase	char(1)
SELECT  @paymentphase = MAX(nphase) FROM expensephase
IF @admintaxkind1 <> 4
BEGIN
	INSERT INTO #proceeds
		(
		ypro, npro, ymov, nmov, 
		--parentymov, parentnmov, parentdescription,  
		autokind, idreg, detaildescription, 
		detailamount, data, accountkind,kind, rowkind, annulmentdate,idstamphandling,flagbankitaliaproceeds,
		flag_ccp
	)
	SELECT DISTINCT
		income.ymov, proceeds.npro, income.ymov, income.nmov, 
		income.autokind, income.idreg,
		CASE
			WHEN payment.npay IS NOT NULL 
			THEN tax.description + ' (a carico amministrazione) - mand. n. ' + CONVERT(varchar(6), payment.npay)
			ELSE tax.description + ' (a carico amministrazione)'
		END,
		expensetax.admintax, proceeds.printdate, 
                case proceeds.flag&8 when 0 then 'I' else 'F' end,
		case proceeds.flag&7 
			when 1 then 'C' 
			when 2 then 'R' 
			when 4 then 'M' 
		end,
		1, proceeds.annulmentdate,
		proceeds.idstamphandling,
		CASE
			WHEN (incomelast.flag&8) <> 0 THEN 'S'
		ELSE 'N'
		END,
		CASE
		WHEN (incomelast.flag&4) <> 0 THEN 'S' --PRELIEVO DA CONTO CORRENTE POSTALE
		ELSE 'N'
	END 
	FROM income
	JOIN incomeyear
		ON incomeyear.idinc = income.idinc
	JOIN incomelast
		ON incomelast.idinc = income.idinc
	--JOIN incomelink
		--ON incomelink.idchild = incomelast.idinc
		--AND incomelink.nlevel = @phasecode
	--JOIN income parentincome
		--ON parentincome.idinc = incomelink.idparent
	JOIN proceeds
		ON proceeds.kpro = incomelast.kpro
	JOIN expensetax
		ON expensetax.idexp = income.idpayment
	JOIN tax
		ON tax.taxcode = expensetax.taxcode 
	JOIN expense
		ON expense.idpayment = income.idpayment
		AND expense.autocode = income.autocode
	JOIN expenselast
		ON expenselast.idexp = expense.idexp
	left outer join payment
		on payment.kpay = expenselast.kpay
	LEFT OUTER JOIN incometotal incometotal_firstyear(NOLOCK)
  		ON incometotal_firstyear.idinc = income.idinc
  		AND ((incometotal_firstyear.flag & 2) <> 0 )
	LEFT OUTER JOIN incomeyear incomeyear_starting(NOLOCK) 
		ON incomeyear_starting.idinc = incometotal_firstyear.idinc
  		AND incomeyear_starting.ayear = incometotal_firstyear.ayear
	WHERE income.ymov = @ayear
		AND expensetax.admintax > 0
		AND expensetax.admintax = incomeyear_starting.amount 
		and income.idreg = @idreg	
		AND expense.idreg = @idreg
		AND expense.nphase = @paymentphase
		AND incomeyear.ayear = @ayear
		AND proceeds.npro in (select npro from #printing)
END
ELSE
BEGIN
	INSERT INTO #proceeds
		(
		ypro, npro, ymov, nmov, 
		--parentymov, parentnmov, parentdescription, 
		autokind, idreg, detaildescription, detailamount,
		data,accountkind,kind, rowkind, annulmentdate,
		idstamphandling,flagbankitaliaproceeds,
		flag_ccp
		)
	SELECT DISTINCT
		income.ymov, proceeds.npro, income.ymov, income.nmov, 
		--parentincome.ymov, parentincome.nmov,parentincome.description, 
		income.autokind, income.idreg,
		CASE
			WHEN expenselast.kpay IS NOT NULL 
			THEN tax.description + ' (a carico amministrazione) - mand. n. ' + CONVERT(varchar(6), payment.npay)
			ELSE tax.description + ' (a carico amministrazione)'
		END,
		expensetax.admintax, proceeds.printdate, 
                case proceeds.flag&8 when 0 then 'I' else 'F' end,
		case proceeds.flag&7 
			when 1 then 'C' 
			when 2 then 'R' 
			when 4 then 'M' 
		end,
		1, proceeds.annulmentdate,
		proceeds.idstamphandling,
		CASE
		WHEN (incomelast.flag&8) <> 0 THEN 'S'
		ELSE 'N'
		END,
		CASE
		WHEN (incomelast.flag&4) <> 0 THEN 'S' --PRELIEVO DA CONTO CORRENTE POSTALE
		ELSE 'N'
	END 
	FROM income
	JOIN incomeyear
		ON incomeyear.idinc = income.idinc
	JOIN incomelast
		ON incomelast.idinc = income.idinc
	--JOIN incomelink
		--ON incomelink.idchild = incomelast.idinc
		--AND incomelink.nlevel = @phasecode
	--JOIN income parentincome
		--ON parentincome.idinc = incomelink.idparent
	JOIN proceeds
		ON proceeds.kpro = incomelast.kpro
	JOIN expensetax
		ON expensetax.idexp = income.idpayment
	JOIN tax
		ON expensetax.taxcode = tax.taxcode
	JOIN expense
		ON expense.idexp = income.idpayment
	JOIN expenselast
		ON expenselast.idexp = expense.idexp
	left outer join payment
		on payment.kpay = expenselast.kpay
	LEFT OUTER JOIN incometotal incometotal_firstyear(NOLOCK)
  		ON incometotal_firstyear.idinc = income.idinc
  		AND ((incometotal_firstyear.flag & 2) <> 0 )
	LEFT OUTER JOIN incomeyear incomeyear_starting(NOLOCK) 
		ON incomeyear_starting.idinc = incometotal_firstyear.idinc
  		AND incomeyear_starting.ayear = incometotal_firstyear.ayear
	WHERE income.ymov = @ayear
		AND (income.idreg <> @idreg OR @idreg IS NULL)
		AND incomeyear.ayear = @ayear
		AND expensetax.admintax > 0
		AND expensetax.admintax = incomeyear_starting.amount 
		AND proceeds.npro in (select npro from #printing)
END
INSERT INTO #proceeds (ypro, npro, ymov, nmov, 
	--parentymov,parentnmov,parentdescription,
	autokind, idreg, detaildescription, detailamount, data,accountkind, kind, rowkind, annulmentdate,
	idstamphandling	, flagbankitaliaproceeds,
		flag_ccp 
	)
	SELECT DISTINCT
		income.ymov, proceeds.npro, income.ymov,income.nmov, 
		--parentincome.ymov, parentincome.nmov,parentincome.description, 
		income.autokind, income.idreg,
		CASE
			WHEN payment.npay IS NOT NULL 
			THEN clawback.description + ' (a carico percipiente) - mand. n. ' + CONVERT(varchar(6), payment.npay)
			ELSE clawback.description + ' (a carico percipiente)'
		END,
		expenseclawback.amount, proceeds.printdate, 
                case proceeds.flag&8 when 0 then 'I' else 'F' end, 
		case proceeds.flag&7 
			when 1 then 'C' 
			when 2 then 'R' 
			when 4 then 'M' 
		end,
		1, proceeds.annulmentdate,
		proceeds.idstamphandling,
		CASE
		WHEN (incomelast.flag&8) <> 0 THEN 'S'
		ELSE 'N'
		END,
		CASE
		WHEN (incomelast.flag&4) <> 0 THEN 'S' --PRELIEVO DA CONTO CORRENTE POSTALE
		ELSE 'N'
	END 
	FROM income
	JOIN incomeyear
		ON incomeyear.idinc = income.idinc
	JOIN incomelast
		ON incomelast.idinc = income.idinc
	--JOIN incomelink
		--ON incomelink.idchild = incomelast.idinc
		--AND incomelink.nlevel = @phasecode
	--JOIN income parentincome
		--ON parentincome.idinc = incomelink.idparent
	JOIN proceeds
		ON proceeds.kpro = incomelast.kpro
	JOIN expenseclawback
		ON expenseclawback.idexp = income.idpayment
		AND expenseclawback.idclawback= income.autocode
	JOIN clawback
		ON clawback.idclawback = expenseclawback.idclawback
	JOIN expense
		ON expense.idexp = income.idpayment 
	JOIN expenselast
		ON expenselast.idexp = expense.idexp
	left outer join payment
		on payment.kpay = expenselast.kpay
	LEFT OUTER JOIN incometotal incometotal_firstyear(NOLOCK)
  		ON incometotal_firstyear.idinc = income.idinc
  		AND ((incometotal_firstyear.flag & 2) <> 0 )
	LEFT OUTER JOIN incomeyear incomeyear_starting(NOLOCK) 
		ON incomeyear_starting.idinc = incometotal_firstyear.idinc
  		AND incomeyear_starting.ayear = incometotal_firstyear.ayear
	WHERE income.ymov = @ayear
		AND incomeyear.ayear = @ayear
		AND expenseclawback.amount > 0
		AND expenseclawback.amount = incomeyear_starting.amount 
		AND proceeds.npro in (select npro from #printing)
-- per gli automatismi generici e da CSA  riporto il riferimento al PAGAMENTO e al mandato principale 
INSERT INTO #proceeds (ypro, npro, ymov, nmov, 
	--parentymov,parentnmov,parentdescription,
	autokind, idreg, detaildescription, detailamount, data,accountkind, kind, rowkind, annulmentdate,
	idstamphandling,flagbankitaliaproceeds,
		flag_ccp 
	)
	SELECT DISTINCT
		income.ymov, proceeds.npro, income.ymov,income.nmov, 
		--parentincome.ymov, parentincome.nmov,parentincome.description, 
		income.autokind, income.idreg,
		CASE
			WHEN payment.npay IS NOT NULL 
			THEN @phaseexpense  +   
			     ' eserc. ' + CONVERT(varchar(4), expense.ymov) + ' n. ' + 
			     CONVERT(varchar(6), expense.nmov) +  
			     ' - mand. n. ' + CONVERT(varchar(6), payment.npay)+
			     ': ' + expense.description 
			ELSE @phaseexpense +  
			     ' eserc. ' + CONVERT(varchar(4), expense.ymov) + ' n. ' + 
			     CONVERT(varchar(6), expense.nmov) + 
			     ': ' + expense.description 
		END,
		incometotal_firstyear.curramount, proceeds.printdate, 
                case proceeds.flag&8 when 0 then 'I' else 'F' end, 
		case proceeds.flag&7 
			when 1 then 'C' 
			when 2 then 'R' 
			when 4 then 'M' 
		end,
		1, proceeds.annulmentdate,
		proceeds.idstamphandling,
		CASE
		WHEN (incomelast.flag&8) <> 0 THEN 'S'
		ELSE 'N'
		END,
		CASE
		WHEN (incomelast.flag&4) <> 0 THEN 'S' --PRELIEVO DA CONTO CORRENTE POSTALE
		ELSE 'N'
	END 
	FROM income
	JOIN incomeyear
		ON incomeyear.idinc = income.idinc
	JOIN incomelast
		ON incomelast.idinc = income.idinc
	JOIN proceeds
		ON proceeds.kpro = incomelast.kpro
	JOIN expense
		ON expense.idexp = income.idpayment 
	JOIN expenselast
		ON expenselast.idexp = expense.idexp
	LEFT OUTER JOIN payment
		on payment.kpay = expenselast.kpay
	LEFT OUTER JOIN incometotal incometotal_firstyear(NOLOCK)
  		ON incometotal_firstyear.idinc = income.idinc
  		AND ((incometotal_firstyear.flag & 2) <> 0 )
	LEFT OUTER JOIN incomeyear incomeyear_starting(NOLOCK) 
		ON incomeyear_starting.idinc = incometotal_firstyear.idinc
  		AND incomeyear_starting.ayear = incometotal_firstyear.ayear
	WHERE income.ymov = @ayear
		AND incomeyear.ayear = @ayear
		AND isnull(income.autokind,0) IN (14,20) -- automatismo generico o da CSA
		--AND income.autocode is null
		AND proceeds.npro in (select npro from #printing)
DECLARE @descrlastfase varchar(50)	
SET @descrlastfase = (SELECT description FROM incomephase WHERE nphase = (SELECT MAX(nphase) FROM incomephase))
IF (@official = 'S')
BEGIN
	UPDATE #proceeds
		SET data = @printdate
		WHERE ypro = @ayear
		AND npro  in (select npro from #printing)
		AND data is null
END

DECLARE @codefin varchar(1)
SELECT 	@codefin = paramvalue FROM reportadditionalparam 
WHERE reportname='reversale_incasso' and paramname='MostraPrimoLivelloOperativo'
IF (@codefin='S')
BEGIN
	DECLARE @nlevel	tinyint
	SELECT  @nlevel = MIN(nlevel) 
		FROM finlevel 
		WHERE ayear=@ayear AND (flag&2)<>0
		
	UPDATE  #proceeds
		SET 	codefin = fin.codefin,
			fintitle = fin.title
		FROM #proceeds	
		JOIN finlink
			ON finlink.idchild = #proceeds.idfin AND finlink.nlevel = @nlevel	
		JOIN fin 
			ON fin.idfin = finlink.idparent
END
SELECT 
	#proceeds.idreg ,
	#proceeds.ymov ,
	#proceeds.nmov ,
	@maxincomephase as maxincomephase,
	#proceeds.parentymov ,
	#proceeds.parentnmov ,
	#proceeds.parentdescription,
	@phasecode as codfaseaccertamento, 
	@phasedescription as faseaccertamento ,
	#proceeds.ypro ,
	#proceeds.npro ,
	#proceeds.idinc ,
	#proceeds.doc ,
	#proceeds.docdate ,
	#proceeds.idman ,
	manager.title as manager,	
	#proceeds.description ,
	upb.codeupb ,
	upb.title as titleupb ,
	#proceeds.idupb ,
	--  income -> upb -> fin
	isnull(#proceeds.cupcodeincome, isnull(upb.cupcode, #proceeds.cupcode) )	as cupcode,
	registry.title as registry,
	registry.cf,
	registry.p_iva,
	registry.birthdate,
	isnull(geo_comune1.title, '') + ' ' + isnull(registry.location,'') as birthplace,
	isnull(geo_provincia1.province, '') as birthprovince,
	isnull(geo_nazione1.title, 'Italia') as birthnation,
	#address.address,
	#address.location,
	#address.cap,
	#address.province  as provincia,
	#address.nation,
	#proceeds.ayear,
	#proceeds.codefin,
	#proceeds.fintitle ,
	#proceeds.nlevel,
	#proceeds.amount ,
	treasurerbank.description as treasurerbank,
	treasurercab.description as treasurercab,
	treasurer.address as treasureraddress,
	treasurer.cap as treasurercap,
	treasurer.city as treasurercity,
	treasurer.country as treasurercountry,
	treasurer.cc as treasurercc,
	treasurer.agencycodefortransmission,
 	proceeds.txt  as notes,	
	#proceeds.data ,
	#proceeds.accountkind ,
	#proceeds.kind ,
	#proceeds.flagarrear ,
	#proceeds.rowkind ,
	autokind.code as 'autokind',
	#proceeds.detaildescription ,
	#proceeds.detailamount ,
	#proceeds.annulmentdate ,
	@descrlastfase AS descrlastfase ,
	#proceeds.nbill,
	#proceeds.billadate, 
	stamphandling.description as stamphandling,
	#proceeds.flagbankitaliaproceeds,
	#proceeds.flag_ccp,
	registry.ccp 
FROM #proceeds 
JOIN proceeds
	ON proceeds.ypro = #proceeds.ypro
	AND proceeds.npro = #proceeds.npro
LEFT OUTER JOIN upb
	on upb.idupb = #proceeds.idupb
LEFT OUTER JOIN treasurer
	on treasurer.idtreasurer = #proceeds.idtreasurer
LEFT OUTER JOIN manager
	ON manager.idman = #proceeds.idman
LEFT OUTER JOIN registry
	ON registry.idreg = #proceeds.idreg
LEFT OUTER JOIN bank treasurerbank
	ON treasurerbank.idbank = treasurer.idbank
LEFT OUTER JOIN cab treasurercab
	ON treasurercab.idbank = treasurer.idbank
	AND treasurercab.idcab = treasurer.idcab
LEFT OUTER JOIN #address
	ON #address.idreg = #proceeds.idreg
LEFT OUTER JOIN geo_city geo_comune1
	ON geo_comune1.idcity = registry.idcity
LEFT OUTER JOIN geo_country geo_provincia1
	ON geo_comune1.idcountry = geo_provincia1.idcountry
LEFT OUTER JOIN geo_nation geo_nazione1
	ON geo_nazione1.idnation = registry.idnation
LEFT OUTER JOIN autokind
	ON autokind.idautokind = #proceeds.autokind
LEFT OUTER JOIN stamphandling
	ON stamphandling.idstamphandling = #proceeds.idstamphandling
ORDER BY #proceeds.npro ASC, 
	registry ASC, 
	nmov ASC, 
	rowkind ASC, 
	autokind ASC
END


