go

CREATE             TRIGGER [trigger_d_ivapay] ON ivapay FOR DELETE
AS BEGIN
	DECLARE @yivapay int
	DECLARE @nivapay int
	
	SELECT	
	@yivapay = yivapay,
	@nivapay = nivapay
	FROM deleted
	
	DELETE FROM ivapayincome
	WHERE yivapay = @yivapay
	AND nivapay = @nivapay
	
	DELETE FROM ivapayexpense
	WHERE yivapay = @yivapay
	AND nivapay = @nivapay
	
END


