if object_id('[exp_listing_payment]') is not null
	drop PROCEDURE [exp_listing_payment]
go

CREATE                  PROCEDURE [exp_listing_payment]
(
	@ayear int,
	@unified varchar(1)
)
AS BEGIN
/* Versione 1.0.1 del 12/09/2007 ultima modifica: PINO */
CREATE TABLE #payment
(
	npay int,
	nmov int,
	kind varchar(20),
	adate datetime,
	printdate datetime,
	transmissiondate datetime,
	amount decimal(23,6),
	description varchar(150),
	codefin varchar(31),
	registry varchar(100)
)
IF @unified = 'N'
BEGIN
	INSERT INTO #payment
	(
		npay, adate, printdate, transmissiondate,
		kind, amount, codefin,
		description, registry, nmov
	)
	SELECT 
		P.npay, P.adate, P.printdate, PT.transmissiondate,
		CASE
			when (( ET.flag & 1)=0) then 'C'
			when (( ET.flag & 1)=1) then 'R'
		End,
		EY.amount,-- E.amount, 
		F.codefin,
		E.description, R.title, E.nmov
	FROM expenselast EL
	JOIN expense E
		ON E.idexp = EL.idexp
	JOIN expenseyear EY
		ON EY.idexp = EL.idexp
	JOIN expensetotal ET
		ON ET.idexp = E.idexp
	JOIN fin F
		ON F.idfin = EY.idfin 
	JOIN registry R
		ON R.idreg = E.idreg
	JOIN payment P
		ON EL.kpay = P.kpay
	LEFT OUTER JOIN paymenttransmission PT
		ON PT.kpaymenttransmission = P.kpaymenttransmission
	WHERE E.ymov = @ayear
END
ELSE
BEGIN
	INSERT INTO #payment
	(
		npay, adate, printdate, transmissiondate,
		kind, amount, codefin, registry
	)
	SELECT 
		P.npay, P.adate, P.printdate, PT.transmissiondate,
		case p.flag&7 
			when 1 then 'C' 
			when 2 then 'R' 
			when 4 then 'M' 
		end,
		ISNULL(SUM(EY.amount),0),-- ISNULL(SUM(E.amount),0),
		F.codefin, R.title
	FROM expenselast EL
	JOIN expense E
		ON E.idexp = EL.idexp
	JOIN expenseyear EY
		ON EY.idexp = E.idexp
	JOIN fin F
		ON F.idfin = EY.idfin
	JOIN registry R
		ON R.idreg = E.idreg
	JOIN expensetotal ET
		ON ET.idexp = E.idexp
	JOIN payment P
		ON EL.kpay = P.kpay
	LEFT OUTER JOIN paymenttransmission PT
		ON PT.kpaymenttransmission = P.kpaymenttransmission
	WHERE E.ymov = @ayear
	GROUP BY P.npay,P.adate,P.printdate,PT.transmissiondate,p.flag&7,F.codefin,R.title
END
UPDATE #payment SET kind = 'RESIDUO' WHERE kind = 'R'
UPDATE #payment SET kind = 'COMPETENZA' WHERE kind = 'C'              	
SELECT 
	npay as 'Numero Mandato',
	adate as 'Data Contabile',
	printdate as 'Data Stampa',
    	transmissiondate as 'Data Trasmissione',
	kind as 'Tipo Pagamento',
	amount as 'Importo Lordo',
	codefin as 'Capitolo',
    	description as 'Descrizione',
	registry as 'Percipiente',
	nmov as 'Numero Movimento'
FROM #payment
ORDER BY npay
	       	
END    


GO

print '[exp_listing_payment] OK'

