if object_id('[exp_listing_proceed]') is not null
	drop PROCEDURE [exp_listing_proceed]
go

CREATE                PROCEDURE [exp_listing_proceed]
(
	@ayear int,
	@unified varchar(1)
)
AS BEGIN
/* Versione 1.0.1 del 12/09/2007 ultima modifica: PINO */
CREATE TABLE #proceeds
(
	npro int,
	adate datetime,
	printdate datetime,
	transmissiondate datetime,
	kind varchar(20),
	amount decimal(23,6),
	codefin varchar(50),
	description varchar(150),
  	registry varchar(100),
	nmov int
)
IF @unified = 'N'
BEGIN
	INSERT INTO #proceeds
	(
		npro, adate, printdate, transmissiondate,
		kind, amount, codefin,
		description, registry, nmov
	)
	SELECT 
		P.npro, P.adate, P.printdate, PT.transmissiondate,
		CASE
			when (( IT.flag & 1)=0) then 'C'
			when (( IT.flag & 1)=1) then 'R'
		End,
		IY.amount,-- I.amount, 
		F.codefin,
		I.description, R.title, I.nmov
	FROM incomelast IL
	JOIN income I
		ON I.idinc = IL.idinc
	JOIN incomeyear IY
		ON IY.idinc = IL.idinc
	JOIN incometotal IT
		ON IT.idinc = I.idinc
	JOIN fin F
		ON F.idfin = IY.idfin 
	JOIN registry R
		ON R.idreg = I.idreg
	JOIN proceeds P
		ON IL.kpro = P.kpro
	LEFT OUTER JOIN proceedstransmission PT
		ON PT.kproceedstransmission = P.kproceedstransmission
	WHERE I.ymov = @ayear
END
ELSE
BEGIN
	INSERT INTO #proceeds
	(
		npro, adate, printdate, transmissiondate,
		kind, amount, codefin, registry
	)
	SELECT 
		P.npro, P.adate, P.printdate, PT.transmissiondate,
		case P.flag&7 
			when 1 then 'C' 
			when 2 then 'R' 
			when 4 then 'M' 
		end,
		ISNULL(SUM(IY.amount),0),-- ISNULL(SUM(E.amount),0),
		F.codefin, R.title
	FROM incomelast IL
	JOIN income I
		ON I.idinc = IL.idinc
	JOIN incomeyear IY
		ON IY.idinc = I.idinc
	JOIN fin F
		ON F.idfin = IY.idfin
	JOIN registry R
		ON R.idreg = I.idreg
	JOIN incometotal IT
		ON IT.idinc = I.idinc
	JOIN proceeds P
		ON IL.kpro = P.kpro
	LEFT OUTER JOIN proceedstransmission PT
		ON PT.kproceedstransmission = P.kproceedstransmission
	WHERE I.ymov = @ayear
	GROUP BY P.npro,P.adate,P.printdate,PT.transmissiondate,P.flag&7,F.codefin,R.title
END
UPDATE #proceeds SET kind = 'RESIDUO' WHERE kind = 'R'
UPDATE #proceeds SET kind = 'COMPETENZA' WHERE kind = 'C'
SELECT 
	npro AS 'Numero Reversale',	 	
	adate AS 'Data Contabile',		
	printdate AS 'Data Stampa',        	
    	transmissiondate AS 'Data Trasmissione', 	
	kind AS 'Tipo Incasso',		
	amount AS 'Importo Lordo',	        
	codefin AS 'Capitolo',		
    	description AS 'Descrizione',             
	registry AS 'Versante',
	nmov AS 'Numero Movimento'
FROM #proceeds
ORDER BY npro
       	
END    


GO

print '[exp_listing_proceed] OK'

GO
if object_id('rpt_partitario_generale_sub_variazioni_confin') is not null
	drop PROCEDURE rpt_partitario_generale_sub_variazioni_confin
go


--exec rpt_partitario_generale_sub_variazioni_confin 2013, '%', null,3, {ts '2013-07-04 00:00:00'}, 'P', NULL
--EXEC rpt_partitario_generale_sub_variazioni_confin 2013, '%', 35, 3, {ts '2013-07-16 00:00:00'}, 'I', NULL
CREATE                    PROCEDURE rpt_partitario_generale_sub_variazioni_confin
	@ayear int,			
	@idupb	varchar(36),	
	@idunderwriting int,  
	@nlevel tinyint ,	-- livello di bilancio:lo prende dal report principale
	@stop datetime,
	@variationtype char(1),		-- P : prev. Principale, S : prev. Secondaria, I : Crediti E Incassi
	@idfin int
AS
BEGIN
DECLARE @firstday datetime
SET @firstday = CONVERT(datetime, '01-01-' + CONVERT(varchar(4),@ayear), 105)
DECLARE @MostraVarBilancio varchar(50)
DECLARE @MostraVarDotazione varchar(50)
SELECT @MostraVarBilancio = isnull(paramvalue,'N') 
FROM reportadditionalparam WHERE paramname='MostraVarBilancio'
PRINT @MostraVarBilancio
SELECT @MostraVarDotazione = isnull(paramvalue,'N') 
FROM reportadditionalparam WHERE paramname='MostraVarDotazione'
PRINT @MostraVarDotazione
IF ( @variationtype = 'P' and @MostraVarBilancio='S')
BEGIN
	SELECT 										
		finvardetail.idfin,
		finvardetail.idupb,
		upb.codeupb,
		finvar.adate,
		finvar.yvar,
		finvar.nvar,
		finvar.official as flagnofficial,
		finvar.description,
		finvardetail.amount,
		'Prev. Principale' as flagvariation,
		finvar.nofficial,
		finvar.variationkind,
		finvar.enactment,
		underwriting.codeunderwriting,
		underwriting.title as underwriting
	FROM finvardetail
	JOIN finvar
		ON finvar.yvar = finvardetail.yvar
		AND finvar.nvar = finvardetail.nvar
	JOIN upb 
		ON upb.idupb=finvardetail.idupb 
	JOIN underwriting	
		ON underwriting.idunderwriting = finvardetail.idunderwriting
	WHERE finvar.flagprevision = 'S'	
		AND finvar.idfinvarstatus = 5
		AND finvar.variationkind <> 5
		AND finvar.adate BETWEEN @firstday AND @stop
		AND (finvardetail.idunderwriting = @idunderwriting OR @idunderwriting is null)
		AND (finvardetail.idfin  = @idfin)
		AND (finvardetail.idupb = @idupb)
	ORDER BY finvar.adate,finvar.yvar,finvar.nvar
	RETURN
END
IF  (@variationtype = 'S' and @MostraVarBilancio='S')
BEGIN
	SELECT 										
		finvardetail.idfin,
		finvardetail.idupb,
		upb.codeupb,
		finvar.adate,
		finvar.yvar,
		finvar.nvar,
		finvar.official as flagnofficial,
		finvar.description,
		finvardetail.amount,
		'Prev. Secondaria' as flagvariation,
		finvar.nofficial,
		finvar.variationkind,
		finvar.enactment,
		underwriting.codeunderwriting,
		underwriting.title as underwriting
	FROM finvardetail
	JOIN finvar
		ON finvar.yvar = finvardetail.yvar
		AND finvar.nvar = finvardetail.nvar
	JOIN upb 
		ON upb.idupb=finvardetail.idupb 
	JOIN underwriting	
		ON underwriting.idunderwriting = finvardetail.idunderwriting
	WHERE finvar.flagsecondaryprev = 'S'	
		AND finvar.idfinvarstatus = 5
		AND finvar.variationkind <> 5
		AND finvar.adate BETWEEN @firstday AND @stop
		AND (finvardetail.idupb = @idupb)
		AND (finvardetail.idfin = @idfin)
		AND (finvardetail.idunderwriting = @idunderwriting OR @idunderwriting is null)
	ORDER BY finvar.adate,finvar.yvar,finvar.nvar
	RETURN
END
print @MostraVarDotazione
IF ( @variationtype='I' and @MostraVarDotazione ='S')
BEGIN
	SELECT 										
		finvardetail.idfin,
		finvardetail.idupb,
		upb.codeupb,
		finvar.adate,
		finvar.yvar,
		finvar.nvar,
		finvar.official as flagnofficial,
		finvar.description,
		finvardetail.amount,
		CASE	WHEN  ( finvar.flagcredit = 'S' AND finvar.flagproceeds = 'S' )THEN 'Dot.Crediti e Dot. Cassa'
			WHEN  finvar.flagcredit = 'S'	THEN 'Dot.Crediti             '
			WHEN  finvar.flagproceeds = 'S'	THEN 'Dot.Cassa               '	
		END AS  flagvariation,
		finvar.nofficial,
		finvar.variationkind,
		finvar.enactment,
		underwriting.codeunderwriting,
		underwriting.title as underwriting
	FROM finvardetail
	JOIN finvar
		ON finvar.yvar = finvardetail.yvar
		AND finvar.nvar = finvardetail.nvar
	JOIN upb 
		ON upb.idupb=finvardetail.idupb 
	JOIN underwriting	
		ON underwriting.idunderwriting = finvardetail.idunderwriting
	WHERE ( finvar.flagcredit = 'S'	OR finvar.flagproceeds = 'S') 
		AND finvar.idfinvarstatus = 5
		AND finvar.adate <= @stop
		AND finvar.yvar = @ayear
		AND (finvardetail.idupb = @idupb)
		AND (finvardetail.idfin  = @idfin)
		AND (finvardetail.idunderwriting = @idunderwriting OR @idunderwriting is null)
	ORDER BY finvar.adate,finvar.yvar,finvar.nvar
	RETURN
END
SELECT 										
	NULL AS idfin,
	NULL AS idupb,
	NULL AS codeupb,
	NULL AS adate,
	NULL AS yvar,
	NULL AS nvar,
	NULL AS flagnofficial,
	NULL AS description,
	NULL AS amount,
	NULL AS flagvariation,
	NULL AS nofficial,
	NULL AS variationkind,
	NULL AS enactment,
	NULL as codeunderwriting,
	NULL as underwriting
END


GO

print 'rpt_partitario_generale_sub_variazioni_confin OK'

GO
if object_id('[rpt_sitbilancio_spesa]') is not null
	drop PROCEDURE [rpt_sitbilancio_spesa]
go

/* 
exec rpt_sitbilancio_spesa 2013, {ts '2013-12-31 00:00:00'}, 3, 'S', '%', 'N', 'N', 'S',2007, null,null,null,null,null
*/
CREATE  PROCEDURE [rpt_sitbilancio_spesa]
	@ayear			int,
	@date			datetime,
	@nlevel			tinyint,
	@hierarchy		char(1),
	@idupb			varchar(36),
	@showupb 		char(1),
	@showchildupb 		char(1), 
	@suppressifblank 	char(1),
	@idfin			int,
	
	@idsor01 int,
	@idsor02 int,
	@idsor03 int,
	@idsor04 int,
	@idsor05 int 
AS
BEGIN
CREATE TABLE #situation_fin
(
	idupb 			varchar(36),
	assured			char(1),
	idfin			int,
	nlevel			tinyint,
	main_initial_prevision	decimal(19,2),
	var_main_prevision	decimal(19,2),
	fin_ph_comp		decimal(19,2),
	var_fin_ph_comp		decimal(19,2), 
	desc_fin_ph 		varchar(50),					
	registry_ph_comp	decimal(19,2),
	var_registry_ph_comp	decimal(19,2),
	desc_registry_ph 	varchar(50),					
	max_ph_comp         	decimal(19,2),
	var_max_ph_comp       	decimal(19,2),
	desc_max_ph 		varchar(50),					
	sec_initial_prevision	decimal(19,2),
	varprevsec		decimal(19,2),
	fin_ph_resid		decimal(19,2), 
	var_fin_ph_resid	decimal(19,2),
	registry_ph_resid	decimal(19,2),
	var_registry_ph_resid	decimal(19,2),
	max_ph_resid         	decimal(19,2),
	var_max_ph_resid      	decimal(19,2),
	assign_credit 		decimal(19,2),
	var_assign_credit	decimal(19,2),
	assign_cash		decimal(19,2), 
	var_assign_cash		decimal(19,2),
	previsionkind 		char(1),
	secprevisionkind 	char(1),
	flag_assign_credit 	char(1),
	flag_assign_cash 	char(1),
	flagconsider 		char(1)		
)
IF @ayear IS NULL 
BEGIN
	SELECT * FROM  #situation_fin 
	RETURN
END
DECLARE @idupboriginal 		varchar(36)
SET 	@idupboriginal= @idupb
IF 	(@showchildupb = 'S') set @idupb=@idupb+'%' 
declare @fixedidupb varchar(36)
set @fixedidupb= null
if (@showupb='N') set @fixedidupb='0001'
DECLARE @levelusable tinyint
SELECT  @levelusable = MIN(nlevel) 
FROM 	finlevel
WHERE 	ayear =@ayear and (flag&2)<>0
DECLARE @fin_phase  tinyint -- fase accantonamento precedente alla fase di impegno, Modifica Sara
SELECT 	@fin_phase = expensefinphase FROM uniconfig
DECLARE @desc_fin_phase varchar(50)
SELECT  @desc_fin_phase=description
FROM 	expensephase WHERE nphase=@fin_phase 
DECLARE @registry_phase tinyint
SELECT  @registry_phase = expenseregphase FROM uniconfig
DECLARE @desc_registry_phase varchar(50)
SELECT  @desc_registry_phase=description
FROM    expensephase WHERE nphase=@registry_phase 
DECLARE @max_phase          	tinyint
SELECT  @max_phase = MAX(nphase) FROM expensephase
DECLARE @desc_max_phase    	varchar(50)
SELECT  @desc_max_phase=description 
FROM 	expensephase WHERE nphase=@max_phase 
DECLARE @previsionkind char(1) 
SELECT  @previsionkind =  
	 CASE 
		WHEN fin_kind IN (1,3) THEN 'C'
		WHEN fin_kind = 2 THEN 'S'
	 END
FROM  config 
WHERE config.ayear = @ayear
DECLARE @secprevisionkind    char(1) 
SELECT  @secprevisionkind  = 
	 CASE 
		WHEN fin_kind = 3 THEN 'S'
		ELSE 'N'
	END
FROM config 
WHERE config.ayear = @ayear
DECLARE @flag_cs     		char(1)
SELECT 	@flag_cs =  CASE 
		WHEN fin_kind IN (1,3) THEN 'C'
		WHEN fin_kind = 2 THEN 'S'
	 END
FROM 	config
WHERE 	ayear = @ayear
DECLARE @cashvaliditykind	int
SELECT 	@cashvaliditykind = cashvaliditykind
FROM 	config
WHERE 	ayear = @ayear
DECLARE @level_input tinyint
SET  @level_input = ISNULL((SELECT nlevel from fin where idfin = @idfin) ,@nlevel)
-- ho scelto come livello 2 e poi ho specificato il capitolo, lui corregge @nlevel dandogli 3
IF (@nlevel < @level_input) AND (@idfin is not null)
	BEGIN
	SET  @nlevel = @level_input
	END
INSERT INTO #situation_fin(
	idfin,
	nlevel,
	idupb,
	assured,
	main_initial_prevision,
	flagconsider
)
SELECT 
	F.idfin, 
	F.nlevel,
	isnull(@fixedidupb, U.idupb),
	ISNULL(U.assured,'N'),
	SUM(finyear.prevision),
	CASE 
		 WHEN (@hierarchy ='N') Then 'S' 
		 WHEN ( @hierarchy='S' 
				and F.nlevel >= @levelusable 
				and F.idfin IN (SELECT idfin FROM finlast))
			THEN 'S'
		 ELSE 'N'
	END
FROM finyear
JOIN upb  U
	ON  finyear.idupb = U.idupb
JOIN fin F
	ON finyear.idfin = F.idfin
--JOIN finlast
--	ON  F.idfin = finlast.idfin
JOIN finlink FLK
	ON FLK.idchild = F.idfin and FLK.nlevel=@level_input
WHERE ((F.flag&1)<>0) -- Spesa
	AND (finyear.ayear = @ayear)
	AND (@idfin IS NULL OR FLK.idparent = @idfin)
    AND (U.idupb LIKE @idupb and U.active = 'S')
	AND ((@hierarchy ='N' AND F.nlevel = @nlevel) OR (@hierarchy ='S' and F.nlevel >= @nlevel))
	AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
	AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
	AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
	AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
	AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
GROUP BY isnull(@fixedidupb, U.idupb), F.idfin, F.nlevel,ISNULL(U.assured,'N')
INSERT INTO #situation_fin(
	idfin,
	nlevel,
	idupb,
	assured,
	var_main_prevision,
	flagconsider
)
SELECT 
	F.idfin, 
	F.nlevel,
	isnull(@fixedidupb, U.idupb),
	ISNULL(U.assured,'N'),
	SUM(finvardetail.amount), 
	CASE 
		 WHEN (@hierarchy ='N') Then 'S' 
		 WHEN ( @hierarchy='S' 
				and F.nlevel >= @levelusable 
				and F.idfin IN (SELECT idfin FROM finlast))
			THEN 'S'
		 ELSE 'N'
	END
FROM fin F
JOIN finlink FLK
	ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
JOIN finlink FLK2
	ON FLK2.idparent = F.idfin 
JOIN finvardetail
	ON ISNULL(FLK2.idchild,F.idfin) = finvardetail.idfin
JOIN finvar
  	ON finvar.yvar = finvardetail.yvar  
  	AND finvar.nvar = finvardetail.nvar 
JOIN upb U 
	ON finvardetail.idupb = U.idupb					
WHERE ((F.flag&1)<>0 ) -- Spesa
	AND finvar.yvar = @ayear		
	AND (U.idupb like @idupb and U.active = 'S')
	AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
	AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
	AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
	AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
	AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
	AND (@idfin IS NULL OR isnull(FLK.idparent, F.idfin) = @idfin)
	AND ((@hierarchy ='N' AND F.nlevel = @nlevel) OR (@hierarchy ='S' and F.nlevel >= @nlevel))
	AND finvar.flagprevision ='S'	
	AND finvar.idfinvarstatus = 5
	AND finvar.variationkind <> 5
	AND finvar.adate <= @date
GROUP BY isnull(@fixedidupb, U.idupb), F.idfin,F.nlevel, ISNULL(U.assured,'N')

INSERT INTO #situation_fin(
	idfin, nlevel,
	idupb,
	assured,
	sec_initial_prevision,
	flagconsider
)
