-- GESTIONE FONDO ECONOMALE	
INSERT INTO #situation_fin(
	idfin, nlevel,
	idupb,
	assured,
	fin_ph_comp,
	flagconsider
)
SELECT 
	F.idfin, F.nlevel,
	isnull(@fixedidupb, U.idupb),
	ISNULL(U.assured,'N'),
	SUM(operation.amount),
	CASE 
		 WHEN (@hierarchy ='N') Then 'S' 
		 WHEN ( @hierarchy='S' 
				and F.nlevel >= @levelusable 
				and F.idfin IN (SELECT idfin FROM finlast))
			THEN 'S'
		 ELSE 'N'
	END
FROM fin F
JOIN finlink FLK
	ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
JOIN finlink FLK2
	ON FLK2.idparent = F.idfin 
JOIN pettycashoperation operation
	ON ISNULL(FLK2.idchild,F.idfin) = operation.idfin
JOIN upb U 
	ON operation.idupb = U.idupb
WHERE  operation.adate <= @date
	AND operation.yoperation = @ayear
	AND (@idfin IS NULL OR FLK.idparent = @idfin)
    AND (U.idupb like @idupb and U.active = 'S')
	AND ((@hierarchy ='N' AND F.nlevel = @nlevel) OR (@hierarchy ='S' and F.nlevel >= @nlevel))
	AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
	AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
	AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
	AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
	AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
	AND NOT EXISTS (SELECT * FROM pettycashoperation  
		WHERE pettycashoperation.idpettycash = operation.idpettycash
		AND pettycashoperation.yoperation = operation.yrestore
		AND pettycashoperation.noperation = operation.nrestore
		AND pettycashoperation.adate <= @date
		AND pettycashoperation.yoperation = @ayear)
GROUP BY isnull(@fixedidupb, U.idupb),F.idfin, F.nlevel, ISNULL(U.assured,'N')
		
INSERT INTO #situation_fin(
	idfin, nlevel,
	idupb,
	assured,
	registry_ph_comp,
	flagconsider
)
SELECT 
	F.idfin, F.nlevel,
	isnull(@fixedidupb, U.idupb),
	ISNULL(U.assured,'N'),
	SUM(operation.amount),
	CASE 
		 WHEN (@hierarchy ='N') Then 'S' 
		 WHEN ( @hierarchy='S' 
				and F.nlevel >= @levelusable 
				and F.idfin IN (SELECT idfin FROM finlast))
			THEN 'S'
		 ELSE 'N'
	END
FROM fin F
JOIN finlink FLK
	ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
JOIN finlink FLK2
	ON FLK2.idparent = F.idfin 
JOIN pettycashoperation operation
	ON ISNULL(FLK2.idchild,F.idfin) = operation.idfin
JOIN upb U 
	ON operation.idupb = U.idupb
WHERE  operation.adate <= @date
	AND operation.yoperation = @ayear
	AND (@idfin IS NULL OR FLK.idparent = @idfin)
    AND (U.idupb like @idupb and U.active = 'S')
	AND ((@hierarchy ='N' AND F.nlevel = @nlevel) OR (@hierarchy ='S' and F.nlevel >= @nlevel))
	AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
	AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
	AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
	AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
	AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
	AND NOT EXISTS (SELECT * FROM pettycashoperation  
		WHERE pettycashoperation.idpettycash = operation.idpettycash
		AND pettycashoperation.yoperation = operation.yrestore
		AND pettycashoperation.noperation = operation.nrestore
		AND pettycashoperation.adate <= @date
		AND pettycashoperation.yoperation = @ayear)
GROUP BY isnull(@fixedidupb, U.idupb),F.idfin, F.nlevel, ISNULL(U.assured,'N')
INSERT INTO #situation_fin(
	idfin, nlevel,
	idupb,
	assured,
	max_ph_comp,
	flagconsider
)
SELECT 
	F.idfin, F.nlevel,
	isnull(@fixedidupb, U.idupb),
	ISNULL(U.assured,'N'),
	SUM(HPV.amount),
	CASE 
		 WHEN (@hierarchy ='N') Then 'S' 
		 WHEN ( @hierarchy='S' 
				and F.nlevel >= @levelusable 
				and F.idfin IN (SELECT idfin FROM finlast))
			THEN 'S'
		 ELSE 'N'
	END
FROM fin F
JOIN finlink FLK
	ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
JOIN finlink FLK2
	ON FLK2.idparent = F.idfin 
JOIN historypaymentview HPV
	ON ISNULL(FLK2.idchild,F.idfin) = HPV.idfin
JOIN upb U 
	ON HPV.idupb = U.idupb
WHERE  HPV.ymov = @ayear
	AND HPV.competencydate <= @date
	AND ((HPV.totflag&1) = 0) -- Competenza
	AND (U.idupb like @idupb and U.active = 'S') 
	AND (@idfin IS NULL OR FLK.idparent = @idfin)
	AND ((@hierarchy ='N' AND F.nlevel = @nlevel) OR (@hierarchy ='S' and F.nlevel >= @nlevel))
	AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
	AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
	AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
	AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
	AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
GROUP BY isnull(@fixedidupb, U.idupb),F.idfin, F.nlevel, ISNULL(U.assured,'N')
INSERT INTO #situation_fin(
	idfin, nlevel,
	idupb,
	assured,
	max_ph_resid,
	flagconsider
)
SELECT 
	F.idfin, F.nlevel,
	isnull(@fixedidupb, U.idupb),
	ISNULL(U.assured,'N'),
	SUM(HPV.amount), 
	CASE 
		 WHEN (@hierarchy ='N') Then 'S' 
		 WHEN ( @hierarchy='S' 
				and F.nlevel >= @levelusable 
				and F.idfin IN (SELECT idfin FROM finlast))
			THEN 'S'
		 ELSE 'N'
	END
FROM fin F
JOIN finlink FLK
	ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
JOIN finlink FLK2
	ON FLK2.idparent = F.idfin 
JOIN historypaymentview HPV
	ON ISNULL(FLK2.idchild,F.idfin) = HPV.idfin
JOIN upb U 
	ON HPV.idupb = U.idupb
WHERE  HPV.ymov = @ayear
	AND HPV.competencydate <= @date
	AND ((HPV.totflag&1) <> 0) -- R
	AND (U.idupb like @idupb and U.active = 'S')
	AND (@idfin IS NULL OR FLK.idparent = @idfin)
	AND ((@hierarchy ='N' AND F.nlevel = @nlevel) OR (@hierarchy ='S' and F.nlevel >= @nlevel))
	AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
	AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
	AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
	AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
	AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
GROUP BY isnull(@fixedidupb, U.idupb),F.idfin, F.nlevel, ISNULL(U.assured,'N')
IF @cashvaliditykind <> 4
BEGIN
			INSERT INTO #situation_fin(
				idfin, nlevel,
				idupb,
				assured,
				var_max_ph_comp,
				flagconsider
			)
			SELECT 
				F.idfin, F.nlevel,
				isnull(@fixedidupb, U.idupb),
				ISNULL(U.assured,'N'),
				SUM(expensevar.amount) ,
				CASE 
					 WHEN (@hierarchy ='N') Then 'S' 
					 WHEN ( @hierarchy='S' 
							and F.nlevel >= @levelusable 
							and F.idfin IN (SELECT idfin FROM finlast))
						THEN 'S'
					 ELSE 'N'
				END
			FROM fin F
			JOIN finlink FLK
				ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
			JOIN finlink FLK2
				ON FLK2.idparent = F.idfin 
			JOIN historypaymentview HPV
				ON ISNULL(FLK2.idchild,F.idfin) = HPV.idfin
			JOIN expensevar
				ON HPV.idexp = expensevar.idexp
			JOIN upb U 
				ON HPV.idupb = U.idupb
			WHERE expensevar.yvar = @ayear
				AND HPV.ymov = @ayear
				AND ((HPV.totflag&1) = 0) -- Competenza
				AND HPV.competencydate <= @date
				AND expensevar.adate <= @date
				AND (@idfin IS NULL OR FLK.idparent = @idfin)
				AND (U.idupb like @idupb and U.active = 'S')
				AND ((@hierarchy ='N' AND F.nlevel = @nlevel) OR (@hierarchy ='S' and F.nlevel >= @nlevel))
				AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
				AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
				AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
				AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
				AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
			GROUP BY isnull(@fixedidupb, U.idupb),F.idfin,  F.nlevel,ISNULL(U.assured,'N')
			
			INSERT INTO #situation_fin(
				idfin, nlevel,
				idupb,
				assured,
				var_max_ph_resid,
				flagconsider
			)
			SELECT 
				F.idfin, F.nlevel,
				isnull(@fixedidupb, U.idupb),
				ISNULL(U.assured,'N'),
				SUM(expensevar.amount),
				CASE 
					 WHEN (@hierarchy ='N') Then 'S' 
					 WHEN ( @hierarchy='S' 
							and F.nlevel >= @levelusable 
							and F.idfin IN (SELECT idfin FROM finlast))
						THEN 'S'
					 ELSE 'N'
				END
			FROM fin F
			JOIN finlink FLK
				ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
			JOIN finlink FLK2
				ON FLK2.idparent = F.idfin 
			JOIN historypaymentview HPV
				ON ISNULL(FLK2.idchild,F.idfin) = HPV.idfin
			JOIN expensevar
				ON HPV.idexp = expensevar.idexp
			JOIN upb U 
				ON HPV.idupb = U.idupb
			WHERE expensevar.yvar = @ayear
				AND HPV.ymov = @ayear
				AND ((HPV.totflag&1) <> 0) -- R
				AND HPV.competencydate <= @date
				AND expensevar.adate <= @date
				AND (@idfin IS NULL OR FLK.idparent = @idfin)
				AND (U.idupb like @idupb and U.active = 'S')
				AND ((@hierarchy ='N' AND F.nlevel = @nlevel) OR (@hierarchy ='S' and F.nlevel >= @nlevel))
				AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
				AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
				AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
				AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
				AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
		GROUP BY isnull(@fixedidupb, U.idupb),F.idfin, F.nlevel, ISNULL(U.assured,'N')				
					
					
END
		
-- Controlla che i CREDITI  siano gestiti
DECLARE @Crediti char(1)
SET @Crediti = 'N'
IF 	(EXISTS(SELECT* FROM creditpart WHERE ycreditpart = @ayear AND adate <= @date) 
	OR
	EXISTS (SELECT * FROM finvar WHERE flagcredit ='S' and yvar = @ayear AND adate <= @date AND finvar.idfinvarstatus = 5)
	)
BEGIN
		INSERT INTO #situation_fin(
			idfin, nlevel,
			idupb,
			assured,
			var_assign_credit,
			flagconsider
		)
		SELECT 
			F.idfin, F.nlevel,
			isnull(@fixedidupb, U.idupb),
			ISNULL(U.assured,'N'),
			SUM(finvardetail.amount),
			CASE 
				 WHEN (@hierarchy ='N') Then 'S' 
				 WHEN ( @hierarchy='S' 
						and F.nlevel >= @levelusable 
						and F.idfin IN (SELECT idfin FROM finlast))
					THEN 'S'
				 ELSE 'N'
			END
		FROM fin F
		JOIN finlink FLK
			ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
		JOIN finlink FLK2
			ON FLK2.idparent = F.idfin 
		JOIN finvardetail
			ON ISNULL(FLK2.idchild,F.idfin) = finvardetail.idfin
		JOIN finvar
  			ON finvar.yvar = finvardetail.yvar  
  			AND finvar.nvar = finvardetail.nvar 
		JOIN upb U 
			ON finvardetail.idupb = U.idupb	
		WHERE ((F.flag&1)<>0) -- Spesa
			AND (U.idupb like @idupb and U.active = 'S')
			AND (@idfin IS NULL OR FLK.idparent = @idfin)
			AND ((@hierarchy ='N' AND F.nlevel = @nlevel) OR (@hierarchy ='S' and F.nlevel >= @nlevel))
			AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
			AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
			AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
			AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
			AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
			AND finvar.yvar = @ayear		
			AND finvar.flagcredit ='S'	
			AND finvar.idfinvarstatus = 5
			AND finvar.variationkind IN (2,3)
			AND finvar.adate <= @date
		GROUP BY isnull(@fixedidupb, U.idupb),F.idfin,  F.nlevel,ISNULL(U.assured,'N')	
		
		INSERT INTO #situation_fin(
			idfin, nlevel,
			idupb,
			assured,
			assign_credit,
			flagconsider
		)
		SELECT 
			F.idfin, F.nlevel,
			isnull(@fixedidupb, U.idupb),
			ISNULL(U.assured,'N'),
			SUM(creditpart.amount),
			CASE 
				 WHEN (@hierarchy ='N') Then 'S' 
				 WHEN ( @hierarchy='S' 
						and F.nlevel >= @levelusable 
						and F.idfin IN (SELECT idfin FROM finlast))
					THEN 'S'
				 ELSE 'N'
			END
		FROM fin F
		JOIN finlink FLK
			ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
		JOIN finlink FLK2
			ON FLK2.idparent = F.idfin 
		JOIN creditpart
			ON ISNULL(FLK2.idchild,F.idfin) = creditpart.idfin
		JOIN incomeyear
			ON creditpart.idinc = incomeyear.idinc
			AND creditpart.ycreditpart = incomeyear.ayear
		JOIN upb U 
			ON creditpart.idupb = U.idupb
		WHERE creditpart.adate <= @date 
			AND (@idfin IS NULL OR FLK.idparent = @idfin)
			AND (U.idupb like @idupb and U.active = 'S')
			AND incomeyear.ayear = @ayear
			AND ((@hierarchy ='N' AND F.nlevel = @nlevel) OR (@hierarchy ='S' and F.nlevel >= @nlevel))
			AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
			AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
			AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
			AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
		GROUP BY isnull(@fixedidupb, U.idupb),F.idfin, F.nlevel, ISNULL(U.assured,'N')	
	
		INSERT INTO #situation_fin(
			idfin, nlevel,
			idupb,
			assured,
			assign_credit,
			flagconsider
		)
		SELECT 
			F.idfin, F.nlevel,
			isnull(@fixedidupb, U.idupb),
			ISNULL(U.assured,'N'),
			SUM(d.amount),
			CASE 
				 WHEN (@hierarchy ='N') Then 'S' 
				 WHEN ( @hierarchy='S' 
						and F.nlevel >= @levelusable 
						and F.idfin IN (SELECT idfin FROM finlast))
					THEN 'S'
				 ELSE 'N'
			END
		FROM fin F
		JOIN finlink FLK
			ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
		JOIN finlink FLK2
			ON FLK2.idparent = F.idfin 
		JOIN finvardetail d
			ON ISNULL(FLK2.idchild,F.idfin) = d.idfin
		JOIN finvar v
  			ON v.yvar = d.yvar  
  			AND v.nvar = d.nvar 
		JOIN upb U 
			ON d.idupb = U.idupb	
		WHERE v.adate <= @date
			AND ((F.flag&1)<>0) -- Spesa
			AND (U.idupb like @idupb and U.active = 'S')
			AND v.yvar = @ayear
			AND (@idfin IS NULL OR FLK.idparent = @idfin)
			AND ((@hierarchy ='N' AND F.nlevel = @nlevel) OR (@hierarchy ='S' and F.nlevel >= @nlevel))
			AND v.idfinvarstatus = 5
			AND v.flagcredit ='S'
			AND v.variationkind IN (1,4)
			AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
			AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
			AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
			AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
		GROUP BY isnull(@fixedidupb, U.idupb),F.idfin,  F.nlevel,ISNULL(U.assured,'N')
	SET @Crediti = 'S'
	
END
ELSE
Begin
   
	 SET @Crediti = 'N' 		
End	       
-- Controlla che gli INCASSI siano gestiti
DECLARE @Incassi char(1)
SET @Incassi = 'N'
IF 	(EXISTS(SELECT* FROM proceedspart WHERE yproceedspart = @ayear AND adate <= @date) 
	OR
	EXISTS (SELECT * FROM finvar WHERE flagproceeds='S' and yvar = @ayear AND adate <= @date AND finvar.idfinvarstatus = 5)
	)
	BEGIN
		INSERT INTO #situation_fin(
			idfin, nlevel,
			idupb,
			assured,
			var_assign_cash,
			flagconsider
		)
		SELECT 
			F.idfin, F.nlevel,
			isnull(@fixedidupb, U.idupb),
			ISNULL(U.assured,'N'),
			SUM(finvardetail.amount),
			CASE 
				 WHEN (@hierarchy ='N') Then 'S' 
				 WHEN ( @hierarchy='S' 
						and F.nlevel >= @levelusable 
						and F.idfin IN (SELECT idfin FROM finlast))
					THEN 'S'
				 ELSE 'N'
			END
		FROM fin F
		JOIN finlink FLK
			ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
		JOIN finlink FLK2
			ON FLK2.idparent = F.idfin 
		JOIN finvardetail
			ON ISNULL(FLK2.idchild,F.idfin) = finvardetail.idfin
		JOIN finvar
  			ON finvar.yvar = finvardetail.yvar  
  			AND finvar.nvar = finvardetail.nvar 
		JOIN upb U 
			ON finvardetail.idupb = U.idupb	
		WHERE ((F.flag&1)<>0) -- Spesa
			AND (U.idupb like @idupb and U.active = 'S')
			AND (@idfin IS NULL OR FLK.idparent = @idfin)
			AND ((@hierarchy ='N' AND F.nlevel = @nlevel) OR (@hierarchy ='S' and F.nlevel >= @nlevel))
			AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
			AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
			AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
			AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
			AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
			AND finvar.yvar = @ayear		
			AND finvar.flagproceeds ='S'	
			AND finvar.idfinvarstatus = 5
			AND finvar.variationkind IN (2,3)
			AND finvar.adate <= @date
		GROUP BY isnull(@fixedidupb, U.idupb),F.idfin, F.nlevel, ISNULL(U.assured,'N')	
		
		INSERT INTO #situation_fin(
			idfin, nlevel,
			idupb,
			assured,
			assign_cash,
			flagconsider
		)
		SELECT 
			F.idfin, F.nlevel,
			isnull(@fixedidupb, U.idupb),
			ISNULL(U.assured,'N'),
			SUM(proceedspart.amount),
			CASE 
				 WHEN (@hierarchy ='N') Then 'S' 
				 WHEN ( @hierarchy='S' 
						and F.nlevel >= @levelusable 
						and F.idfin IN (SELECT idfin FROM finlast))
					THEN 'S'
				 ELSE 'N'
			END
		FROM fin F
		JOIN finlink FLK
			ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
		JOIN finlink FLK2
			ON FLK2.idparent = F.idfin 
		JOIN proceedspart
			ON ISNULL(FLK2.idchild,F.idfin) = proceedspart.idfin
		JOIN incomeyear
			ON proceedspart.idinc = incomeyear.idinc
			AND proceedspart.yproceedspart = incomeyear.ayear
		JOIN upb U 
			ON proceedspart.idupb = U.idupb
		WHERE proceedspart.adate <= @date
			AND (U.idupb like @idupb and U.active = 'S')
			AND incomeyear.ayear = @ayear
			AND (@idfin IS NULL OR FLK.idparent = @idfin)
			AND ((@hierarchy ='N' AND F.nlevel = @nlevel) OR (@hierarchy ='S' and F.nlevel >= @nlevel))
			AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
			AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
			AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
			AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
		GROUP BY isnull(@fixedidupb, U.idupb),F.idfin,  F.nlevel,ISNULL(U.assured,'N')
		
		INSERT INTO #situation_fin(
			idfin, nlevel,
			idupb,
			assured,
			assign_cash,
			flagconsider
		)
		SELECT 
			F.idfin, F.nlevel,
			isnull(@fixedidupb, U.idupb),
			ISNULL(U.assured,'N'),
			SUM(d.amount),
			CASE 
				 WHEN (@hierarchy ='N') Then 'S' 
				 WHEN ( @hierarchy='S' 
						and F.nlevel >= @levelusable 
						and F.idfin IN (SELECT idfin FROM finlast))
					THEN 'S'
				 ELSE 'N'
			END
		FROM fin F
		JOIN finlink FLK
			ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
		JOIN finlink FLK2
			ON FLK2.idparent = F.idfin 
		JOIN finvardetail d
			ON ISNULL(FLK2.idchild,F.idfin) = d.idfin
		JOIN finvar v
  			ON v.yvar = d.yvar  
  			AND v.nvar = d.nvar 
		JOIN upb U 
			ON d.idupb = U.idupb	
		WHERE v.adate <= @date
			AND ((F.flag&1)<>0) -- Spesa
			AND (@idfin IS NULL OR FLK.idparent = @idfin)
			AND ((@hierarchy ='N' AND F.nlevel = @nlevel) OR (@hierarchy ='S' and F.nlevel >= @nlevel))
			AND (U.idupb like @idupb and U.active = 'S')
			AND v.yvar = @ayear
			AND v.idfinvarstatus = 5
			AND v.flagproceeds ='S'
			AND v.variationkind IN (1,4)
			AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
			AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
			AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
			AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
		GROUP BY isnull(@fixedidupb, U.idupb),F.idfin, F.nlevel, ISNULL(U.assured,'N')
				
		SET @Incassi = 'S'
	END
ELSE
Begin
  
	SET @Incassi = 'N'		
End       
--	--	--	--	--	-- Aggiunge le voci inutilizzate se @suppressifblank = N --	--	--	--	--	--	
IF (@suppressifblank = 'N') 
BEGIN
--se ho scelto di vedere l'upb inserisco le coppie upb/bilancio altrimenti inserisco solo il bilanico non utilizzato
IF ( (@showupb <>'S') and (@idupboriginal = '%'))
Begin
	if(@hierarchy='S')	
		BEGIN
			INSERT INTO #situation_fin(idfin, nlevel,flagconsider)
			SELECT 
				F.idfin,F.nlevel,
			CASE 
				 WHEN (F.nlevel >= @levelusable and 
				 F.idfin IN (SELECT idfin FROM finlast))
				 THEN 'S'
				 ELSE 'N'
			END
			FROM fin F 
			JOIN finlink FLK
				ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
			LEFT OUTER JOIN finlink FLK2
				ON FLK2.idparent = F.idfin 
			WHERE ((F.flag & 1) <> 0) and F.ayear = @ayear
				AND (@idfin IS NULL OR  FLK.idparent = @idfin)
				AND (F.nlevel >=  @nlevel)
			GROUP BY F.idfin, F.nlevel
		END
	ELSE
		BEGIN
			INSERT INTO #situation_fin(idfin, nlevel, flagconsider)
			SELECT F.idfin, F.nlevel,'S'
			FROM fin F
			JOIN finlink FLK
				ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
			LEFT OUTER JOIN finlink FLK2
				ON FLK2.idparent = F.idfin 
			WHERE  	((F.flag & 1 ) <>0) AND F.ayear =@ayear	
				AND (@idfin IS NULL OR  FLK.idparent = @idfin)
				AND (F.nlevel = @nlevel)
			GROUP BY F.idfin,F.nlevel		
		END
end
else
begin
	--> @showupb ='S'
	if(@hierarchy='S')	
		BEGIN
			INSERT INTO #situation_fin(
				idfin, nlevel	,	
				idupb,
				assured,
				flagconsider
			)
			SELECT 
				F.idfin,F.nlevel		,
				U.idupb,
				ISNULL(U.assured,'N'),
				CASE 
					 WHEN (F.nlevel >= @levelusable and 
					 F.idfin IN (SELECT idfin FROM finlast))
					 THEN 'S'
					 ELSE 'N'
				END
			FROM fin F cross join upb U
			JOIN finlink FLK
				ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
			LEFT OUTER JOIN finlink FLK2
				ON FLK2.idparent = F.idfin 				
			WHERE  ((F.flag & 1) <>0 ) and F.ayear = @ayear
				AND (@idfin IS NULL OR  FLK.idparent = @idfin)
				AND (U.idupb LIKE @idupb and U.active = 'S')
				AND (F.nlevel >=  @nlevel)
				AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
				AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
				AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
				AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
				AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)			
			GROUP BY U.idupb,F.idfin,ISNULL(U.assured,'N'),F.nlevel
		END
	ELSE
		BEGIN
			INSERT INTO #situation_fin(
				idfin, nlevel,
				idupb,
				assured,
				flagconsider
				)
			SELECT 
				F.idfin, F.nlevel		,
				U.idupb,
				ISNULL(U.assured,'N'),
				'S'
			FROM upb U
			CROSS JOIN fin F
			JOIN finlink FLK
				ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
			LEFT OUTER JOIN finlink FLK2
				ON FLK2.idparent = F.idfin 
			WHERE  	((F.flag & 1 ) <> 0) AND F.ayear =@ayear	
				AND (@idfin IS NULL OR  FLK.idparent = @idfin)
				AND (U.idupb LIKE @idupb and U.active = 'S')
				AND (F.nlevel = @nlevel)
				AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
				AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
				AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
				AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
				AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)			
			GROUP BY U.idupb, F.idfin,ISNULL(U.assured,'N'), F.nlevel		
		END
end
END
--	--	--	--	--	--	--	--	--	--	--	--	--	--	--	--	--	--	--	--	--	--	--	--	--	--	--	--	--	--	--	--	--	--	--				
		
		
IF (@suppressifblank = 'S') AND @nlevel>=2	--> se la stampa è x categoria o x un livello sottostante la categoria cancella le righe
BEGIN
	DELETE FROM #situation_fin WHERE 
			(isnull(main_initial_prevision,0.0) =0 AND 
			isnull(var_main_prevision,0.0) =0 AND 
			isnull(registry_ph_comp,0.0) =0 AND 
			isnull(var_registry_ph_comp,0.0) =0 AND 
			isnull(max_ph_comp,0.0) =0 AND 
			isnull(var_max_ph_comp,0.0) =0 AND 
			isnull(sec_initial_prevision,0.0) =0 AND 
			isnull(varprevsec,0.0) =0 AND 
			isnull(registry_ph_resid,0.0) =0 AND 
			isnull(var_registry_ph_resid,0.0) =0 AND 
			isnull(max_ph_resid,0.0) =0 AND 
			isnull(var_max_ph_resid,0.0) =0 AND 
			isnull(assign_credit,0.0) =0 AND 
			isnull(var_assign_credit,0.0) =0 AND 
			isnull(assign_cash,0.0) =0 AND 
			isnull(var_assign_cash,0.0) =0 AND
			isnull(fin_ph_comp,0.0) =0 AND  
			isnull(var_fin_ph_comp,0.0) =0 AND 
			isnull(fin_ph_resid,0.0) =0 AND 
			isnull(var_fin_ph_resid,0.0) =0 AND 			
			nlevel >=2)
END
IF (@showupb ='N') 
BEGIN
	declare 	@codeupb varchar(50)
	declare		@upb varchar(150)
	declare		@upbprintingorder varchar(50)
	declare		@ext_idupb varchar(50)
	if (@idupboriginal='%')
	begin
		set @codeupb= null
		set @upb= null
		set @upbprintingorder= null
		set @ext_idupb= null
	end
	else
	begin
		SET @upbprintingorder =
			(SELECT TOP 1 printingorder
			FROM upb
			WHERE idupb = @idupboriginal)
		SET  @upb =
			(SELECT TOP 1 title
			FROM upb
			WHERE idupb = @idupboriginal)
		SET  @ext_idupb =	@idupboriginal
		SET  @codeupb =
			(SELECT TOP 1 codeupb
			FROM upb	
			WHERE idupb = @idupboriginal)
	end
		
	SELECT 
		#situation_fin.idfin,	
		fin.printingorder 			as 'finprintingorder',
		@codeupb as codeupb,
		@ext_idupb as idupb,
		@upb as upb,
		@upbprintingorder as upbprintingorder,	
		fin.codefin,	
		fin.title,	
		fin.nlevel,	
		sum(isnull(main_initial_prevision,0.0)) as 'main_initial_prevision',
		sum(isnull(var_main_prevision,0.0)) 	as 'var_main_prevision',
		sum(isnull(fin_ph_comp,0.0)) 		as 'fin_ph_comp',
		sum(isnull(var_fin_ph_comp,0.0)) 	as 'var_fin_ph_comp', 
		@desc_fin_phase 			as 'desc_fin_ph',					
		sum(isnull(registry_ph_comp,0.0)) 	as 'registry_ph_comp',
		sum(isnull(var_registry_ph_comp,0.0)) 	as 'var_registry_ph_comp',
		@desc_registry_phase 			as 'desc_registry_ph',					
		sum(isnull(max_ph_comp,0.0)) 		as 'max_ph_comp',
		sum(isnull(var_max_ph_comp,0.0)) 	as 'var_max_ph_comp',
		@desc_max_phase 			as 'desc_max_ph' 	,					
		sum(isnull(sec_initial_prevision,0.0)) 	as 'sec_initial_prevision',
		sum(isnull(varprevsec,0.0)) 		as 'varprevsec',
		sum(isnull(fin_ph_resid,0.0)) 		as 'fin_ph_resid', 
		sum(isnull(var_fin_ph_resid,0.0)) 	as 'var_fin_ph_resid',
		sum(isnull(registry_ph_resid,0.0)) 	as 'registry_ph_resid',
		sum(isnull(var_registry_ph_resid,0.0))  as 'var_registry_ph_resid',
		sum(isnull(max_ph_resid,0.0)) 		as 'max_ph_resid',
		sum(isnull(var_max_ph_resid,0.0)) 	as 'var_max_ph_resid',
		sum(isnull(assign_credit,0.0)) 		as 'assign_credit',
		sum(isnull(var_assign_credit,0.0)) 	as 'var_assign_credit',
		sum(isnull(assign_cash,0.0)) 		as 'assign_cash',
		sum(isnull(var_assign_cash,0.0)) 	as 'var_assign_cash',
		@previsionkind 				as 'previsionkind',
		@secprevisionkind 			as 'secprevisionkind',
		@Crediti as flag_assign_credit,
		@Incassi as	flag_assign_cash,
		flagconsider	
 	FROM #situation_fin 
 	JOIN fin 
		ON #situation_fin.idfin = fin.idfin			
	GROUP BY #situation_fin.idfin,
		fin.printingorder,
		fin.codefin,	
		fin.title,
		fin.nlevel,
		flagconsider			
	ORDER BY finprintingorder
END 
	ELSE
		SELECT 
			#situation_fin.idfin,	
			codeupb,
			#situation_fin.idupb,
			upb.title as 'upb',
			upb.printingorder as 'upbprintingorder',
			fin.codefin,	
			fin.title,	
			fin.printingorder 	as 'finprintingorder',	
			fin.nlevel,	
			sum(isnull(main_initial_prevision,0.0)) as 'main_initial_prevision',
			sum(isnull(var_main_prevision,0.0)) 	as 'var_main_prevision',
			sum(isnull(fin_ph_comp,0.0)) 		as 'fin_ph_comp',
			sum(isnull(var_fin_ph_comp,0.0)) 	as 'var_fin_ph_comp', 
			@desc_fin_phase 	as 'desc_fin_ph',					
			sum(isnull(registry_ph_comp,0.0)) 	as 'registry_ph_comp',
			sum(isnull(var_registry_ph_comp,0.0)) 	as 'var_registry_ph_comp',
			@desc_registry_phase 	as 'desc_registry_ph',					
			sum(isnull(max_ph_comp,0.0)) 		as 'max_ph_comp',
			sum(isnull(var_max_ph_comp,0.0)) 	as 'var_max_ph_comp',
			@desc_max_phase 	as 'desc_max_ph',		
			sum(isnull(sec_initial_prevision,0.0)) 	as 'sec_initial_prevision',
			sum(isnull(varprevsec,0.0)) 		as 'varprevsec',
			sum(isnull(fin_ph_resid,0.0)) 		as 'fin_ph_resid', 
			sum(isnull(var_fin_ph_resid,0.0)) 	as 'var_fin_ph_resid',
			sum(isnull(registry_ph_resid,0.0)) 	as 'registry_ph_resid',
			sum(isnull(var_registry_ph_resid,0.0))  as 'var_registry_ph_resid',
			sum(isnull(max_ph_resid,0.0)) 		as 'max_ph_resid',
			sum(isnull(var_max_ph_resid,0.0)) 	as 'var_max_ph_resid',
			sum(isnull(assign_credit,0.0)) 		as 'assign_credit',
			sum(isnull(var_assign_credit,0.0)) 	as 'var_assign_credit',
			sum(isnull(assign_cash,0.0)) 		as 'assign_cash',
			sum(isnull(var_assign_cash,0.0)) 	as 'var_assign_cash',
			@previsionkind 		as 'previsionkind',
			@secprevisionkind 	as 'secprevisionkind',
			case when ((upb.assured is not null) and upb.assured ='S') then 'N'
					else @Crediti
			End as flag_assign_credit,
			case when ((upb.assured is not null) and upb.assured ='S')  then 'N'
					else @Incassi
			End as	flag_assign_cash,
			flagconsider	
	 	FROM #situation_fin 
		JOIN fin 
			on #situation_fin.idfin = fin.idfin
		JOIN upb
			on #situation_fin.idupb = upb.idupb
		GROUP BY upb.printingorder, codeupb, #situation_fin.idupb,upb.title,upb.assured,
			fin.printingorder, fin.codefin, fin.title, #situation_fin.idfin,
			fin.nlevel,
			flag_assign_credit,
			flag_assign_cash,
			flagconsider			
		ORDER BY upb.printingorder,fin.printingorder
END

GO

print '[rpt_sitbilancio_spesa] OK'

GO
if object_id('[rpt_partitario_spese_intestazione]') is not null
	drop PROCEDURE [rpt_partitario_spese_intestazione]
go

CREATE     PROCEDURE [rpt_partitario_spese_intestazione]
	@ayear int,
	@idupb	varchar(36),
	@adate datetime,
	@codelevel tinyint,
	@showupb char(1),
	@showchildupb char(1),
	@suppressifblank char(1),
	@idfin int
AS
BEGIN
/* Versione 1.0.3 del 27/11/2007 ultima modifica: MARIA */
CREATE TABLE #expense
(
	upb varchar(150),
	codeupb	varchar(50),
	idupb varchar(36),
	upbprintingorder varchar(50),
	nphase tinyint,
	idfin int,
	idappropriation int,
	adate datetime,
	ayear int,
	description varchar(150),
	idreg int,
	rowkind 	  int,
	npay 		  int,
	nappropriation    int,
	ymovappropriation int,
	nmovappropriation int,
	yvarappropriation int,
	nvarappropriation int,
	amount_appropriation decimal(19,2),
	origin_amount_appropriation decimal(19,2),
	available_appropriation decimal(19,2),
	flagarrear char(1),	
	reportdate datetime,
	initialprevisioncomp decimal(19,2),
	initialprevisioncassa decimal(19,2),
	finvar_prevision decimal(19,2),
	finvar_secondaryprev decimal(19,2),
	appropriation_C decimal(19,2),
	var_appropriation_C decimal(19,2),
	payment_C decimal(19,2),
	var_payment_C decimal(19,2),
	appropriation_R decimal(19,2),
	var_appropriation_R decimal(19,2),
	payment_R decimal(19,2),
	var_payment_R decimal(19,2),
	npayment int,
	ymovpayment int,
	nmovpayment int,
	yvarpayment int,
	nvarpayment int,
	payment_amount decimal(19,2),
	assign_credit 		decimal(19,2),
	var_assign_credit	decimal(19,2),
	assign_cash		decimal(19,2), 
	var_assign_cash		decimal(19,2),
	flag_assign_credit 	char(1),
	flag_assign_cash 	char(1),
	emessiondate datetime,
	printeddate datetime,
	trasmitteddate datetime,
	transactiondate datetime,
	annulmentdate datetime,
	doc varchar(150)
)
DECLARE @previsionkind char(1) 
SELECT  @previsionkind =  fin_kind
FROM  config 
WHERE config.ayear = @ayear

DECLARE @idupboriginal varchar(36)
SET @idupboriginal= @idupb
IF (@showchildupb = 'S') 
BEGIN
	SET @idupb=@idupb+'%' 
END
DECLARE @levelusable tinyint
SELECT  @levelusable = MIN(nlevel)
FROM 	finlevel
WHERE 	ayear = @ayear AND (flag&2)<>0
DECLARE @firstday datetime
SET @firstday = CONVERT(datetime, '01-01-' + CONVERT(varchar(4),@ayear), 105)
DECLARE @level_input tinyint
SET  @level_input = ISNULL((SELECT nlevel from fin where idfin = @idfin), @codelevel)
IF (@codelevel < @level_input ) AND (@idfin is not null)
	BEGIN
	SET  @codelevel = @level_input
	END
DECLARE @nfinphase tinyint
SELECT  @nfinphase = appropriationphasecode
FROM config
WHERE ayear = @ayear
IF (@nfinphase IS NULL)
BEGIN
	SELECT @nfinphase = expensefinphase FROM uniconfig
END
  
-- ovvero prendo la massima fase tra quelle che contengono o il codice di bilancio o il creditore perchè questa  è la vera fase di impegno giuridico
DECLARE @maxexpensephase tinyint
SELECT  @maxexpensephase = MAX(nphase)
FROM    expensephase 
--ATTENZIONE L'ipotesi di funzionamento di questa sp è che fase dell' impegno = fase del pagamento - 1.
--ALTRIMENTI SBALLA LE RIGHE DEL PAGAMENTO SUL REPORT (o meglio con un pò di tempo si deve fare un controllo per eliminare tutte le fasi 
--che non sono fasepagamento e faseimpegno, anzi lo faccio subito inserendo alla fine una DELETE WHERE nphase <> fase del pagamento AND nphase <> fase dell'impegno)
INSERT INTO #expense
(
	idfin,
	idupb,
	nphase,
	rowkind, 
	adate, 
	description, 
	idreg,--registry, 
	nappropriation, 
	ymovappropriation,
	nmovappropriation,
	amount_appropriation,
	origin_amount_appropriation,
	npayment, 
	ymovpayment,
	nmovpayment,
	payment_amount,
	npay,
	flagarrear,
	idappropriation,
	doc
)	--> prende quelli movimentati
SELECT 
	ISNULL(FL.idparent, expenseyear.idfin),
	upb.idupb,
	expense.nphase,
	expense.nphase-1,
	expense.adate,
	expense.description,
	expense.idreg,
	E2.idexp, --IMPEGNO
	E2.ymov,
	E2.nmov,  
	expenseyear.amount,
	expenseyear_starting.amount,
	E3.idexp, --PAGAMENTO
	E3.ymov,
	E3.nmov, 
	expenseyear.amount,
	payment.npay,
	CASE
		WHEN ((expensetotal.flag&1)=0) THEN 'C'
		WHEN ((expensetotal.flag&1)=1) THEN 'R'
	END, 
	E2.idexp, --IMPEGNO
	CASE
		WHEN expense.doc IS NOT NULL
			AND expense.docdate IS NULL
			THEN 'Pag. ' + expense.doc
		WHEN expense.doc IS NOT NULL
			AND expense.docdate IS NOT NULL
			THEN 'Pag. ' + expense.doc + 
			' del ' + CONVERT(varchar(20), expense.docdate, 105)
		ELSE NULL
	END
FROM expenseyear
JOIN expense
	ON expenseyear.idexp = expense.idexp 
JOIN upb
	ON upb.idupb = expenseyear.idupb
JOIN fin
	ON expenseyear.idfin = fin.idfin AND expenseyear.ayear = fin.ayear
JOIN expensetotal
	ON  expenseyear.idexp = expensetotal.idexp
	AND expenseyear.ayear = expensetotal.ayear	
JOIN expenselink EL2
	ON EL2.idchild = expense.idexp  AND EL2.nlevel = @nfinphase
LEFT  OUTER JOIN finlink FL
	ON FL.idchild = expenseyear.idfin AND FL.nlevel = @codelevel
LEFT  OUTER JOIN finlink FL1
	ON FL1.idchild = expenseyear.idfin AND FL1.nlevel = @level_input
LEFT  OUTER JOIN expenselast
	ON expenselast.idexp = expense.idexp
LEFT  OUTER JOIN payment
	ON expenselast.kpay = payment.kpay
LEFT OUTER JOIN expense E2
	ON E2.idexp = EL2.idparent
LEFT OUTER JOIN expense E3
	ON E3.idexp = expenselast.idexp	
LEFT OUTER JOIN expensetotal expensetotal_firstyear(NOLOCK)
  	ON expensetotal_firstyear.idexp = expense.idexp
  	AND ((expensetotal_firstyear.flag & 2) <> 0 )
LEFT OUTER JOIN expenseyear expenseyear_starting(NOLOCK) 
	ON expenseyear_starting.idexp = expensetotal_firstyear.idexp
  	AND expenseyear_starting.ayear = expensetotal_firstyear.ayear
WHERE ((fin.flag&1)=1) -- = 'S'	
	AND expenseyear.ayear=@ayear
	AND (@idfin IS NULL OR  isnull(FL1.idparent, expenseyear.idfin) = @idfin)		
	AND expense.adate <= @adate
	AND expense.nphase >= @nfinphase -- le prendo da qui in poi
	AND (upb.idupb like @idupb) 
--- Inserimento delle variazioni dei movimenti
INSERT INTO #expense
(
	idfin,
	idupb,
	nphase,
	rowkind, 
	adate, 
	description, 
	idreg,		
	nappropriation, 
	ymovappropriation,
	nmovappropriation,
	yvarappropriation,
	nvarappropriation,
	amount_appropriation,
	npayment, 
	ymovpayment,
	nmovpayment,
	yvarpayment,
	nvarpayment,
	payment_amount,
	npay,
	idappropriation,
	doc
)	--> prende quelli movimentati

SELECT 
	ISNULL(FL.idparent, expenseyear.idfin),
	expenseyear.idupb,
	expense.nphase,
	expense.nphase-1,
	expensevar.adate,
	expensevar.description,
	expense.idreg,	
	E2.idexp, --IMPEGNO
	E2.ymov,
	E2.nmov,  
	expensevar.yvar,
	expensevar.nvar,
	expensevar.amount,
	E3.idexp, --PAGAMENTO
	E3.ymov,
	E3.nmov, 
	expensevar.yvar,--EV3
	expensevar.nvar,--EV3
	expensevar.amount,--EV3
	payment.npay,
	E2.idexp,
	CASE
		WHEN expensevar.doc IS NOT NULL
			AND expensevar.docdate IS NULL
			THEN 'Pag. ' + expensevar.doc
		WHEN expensevar.doc IS NOT NULL
			AND expensevar.docdate IS NOT NULL
			THEN 'Pag. ' + expensevar.doc + 
			' del ' + CONVERT(varchar(20), expensevar.docdate, 105)
		ELSE NULL
	END
FROM expensevar
join expense 
	on expensevar.idexp = expense.idexp
JOIN expenseyear
	ON expenseyear.idexp = expense.idexp 
JOIN finlast
	ON finlast.idfin = expenseyear.idfin 
JOIN expenselink EL2
	ON EL2.idchild = expensevar.idexp  AND EL2.nlevel = @nfinphase
LEFT  OUTER JOIN finlink FL
	ON FL.idchild = expenseyear.idfin  AND FL.nlevel = @codelevel
LEFT  OUTER JOIN finlink FL1
	ON FL1.idchild = expenseyear.idfin  AND FL1.nlevel = @level_input
LEFT OUTER JOIN expenselast
	ON expenselast.idexp = expense.idexp
LEFT OUTER JOIN expenselink EL3
	ON EL3.idchild = expensevar.idexp  AND EL3.nlevel = @maxexpensephase
LEFT OUTER JOIN expense E2
	ON E2.idexp = EL2.idparent
LEFT OUTER JOIN expense E3
	ON E3.idexp = EL3.idparent
LEFT OUTER JOIN payment
	ON payment.kpay = expenselast.kpay
WHERE	(@idfin IS NULL OR  isnull(FL1.idparent, expenseyear.idfin) = @idfin)		
	AND expensevar.adate between @firstday and @adate
	and expensevar.yvar = @ayear 
	AND isnull(expensevar.autokind,'') <>'22'
	AND ((expense.nphase IN (@nfinphase, @maxexpensephase)))
	AND (expenseyear.idupb like @idupb)
	AND expenseyear.ayear=@ayear

INSERT INTO #expense
	(
	idfin,
	idupb
	)--> Prende quelli non movimentati 
SELECT 
	ISNULL(FL.idparent, fin.idfin),
	upb.idupb
FROM fin CROSS JOIN upb 
LEFT OUTER JOIN finyear
	ON finyear.idfin=fin.idfin 
	AND finyear.idupb = upb.idupb
LEFT  OUTER JOIN finlink FL
	ON FL.idchild = fin.idfin  AND FL.nlevel = @codelevel
LEFT  OUTER JOIN finlink FL1
	ON FL1.idchild = fin.idfin  AND FL1.nlevel = @level_input
WHERE ((fin.flag&1)=1) -- Spesa
	AND (@idfin IS NULL OR  isnull(FL1.idparent, fin.idfin) = @idfin)	
	AND (upb.idupb like @idupb) 
	AND  fin.nlevel = @codelevel
	AND  fin.ayear = @ayear
	and not exists (SELECT #expense.idfin,#expense.idupb
			FROM #expense
			JOIN finyear ff
			ON ff.idupb=#expense.idupb
			AND ff.idfin=#expense.idfin
			WHERE finyear.idupb=ff.idupb 
			AND finyear.idfin=ff.idfin)
CREATE TABLE #finvar_prevision
    (
	idfin  int,
	idupb  varchar(36),
	totale decimal(19,2)			 
    )
INSERT INTO #finvar_prevision
	(
	idfin,
	idupb,
	totale
	)
SELECT
	ISNULL(finlink.idparent,finvardetail.idfin),
	finvardetail.idupb,
	SUM(ISNULL(finvardetail.amount,0.0))
FROM finvardetail
JOIN finvar
	ON finvar.yvar = finvardetail.yvar
	AND finvar.nvar = finvardetail.nvar
LEFT OUTER JOIN finlink 
	ON finlink.idchild = finvardetail.idfin 
	AND finlink.nlevel = @codelevel			
WHERE finvar.flagprevision ='S'
	AND finvar.idfinvarstatus = 5
	AND finvar.variationkind <> 5
	AND finvar.adate <= @adate
	AND finvar.yvar = @ayear
GROUP BY finvardetail.idupb,ISNULL(finlink.idparent,finvardetail.idfin)

CREATE TABLE #finvar_secondaryprev
    (
	idfin  int,
	idupb  varchar(36),
	totale decimal(19,2)			 
    )
INSERT INTO #finvar_secondaryprev
	(
	idfin,
	idupb,
	totale
	)
SELECT
	ISNULL(finlink.idparent,finvardetail.idfin),
	finvardetail.idupb,
	SUM(ISNULL(finvardetail.amount, 0.0))
FROM finvardetail
JOIN finvar
	ON finvar.yvar = finvardetail.yvar
	AND finvar.nvar = finvardetail.nvar
LEFT OUTER JOIN finlink 
	ON finlink.idchild = finvardetail.idfin 
	AND finlink.nlevel = @codelevel			
WHERE finvar.yvar = @ayear
	AND finvar.adate <= @adate
	AND finvar.flagsecondaryprev='S'
	AND finvar.idfinvarstatus = 5
	AND finvar.variationkind <> 5
GROUP BY finvardetail.idupb,ISNULL(finlink.idparent,finvardetail.idfin)
CREATE TABLE #appropriation_C
    (
	idfin  int,
	idupb  varchar(36),
	totale decimal(19,2)			 
    )
INSERT INTO #appropriation_C
	(
	idfin,
	idupb,
	totale
	)
SELECT
	ISNULL(finlink.idparent,expenseyear.idfin),
	expenseyear.idupb,
	SUM(ISNULL(expenseyear.amount, 0.0))
FROM expense
JOIN expenseyear
	ON expenseyear.idexp = expense.idexp AND expenseyear.ayear = @ayear
JOIN expensetotal 
	ON  expenseyear.idexp = expensetotal.idexp AND
	expenseyear.ayear = expensetotal.ayear 
JOIN fin
	ON fin.idfin = expenseyear.idfin
LEFT OUTER JOIN finlink 
	ON finlink.idchild = expenseyear.idfin 
	AND finlink.nlevel = @codelevel
LEFT OUTER JOIN finlink FL
	ON FL.idchild = expenseyear.idfin 
	AND FL.nlevel = @level_input
WHERE expense.adate <= @adate
	AND expenseyear.ayear = @ayear
	AND ((expensetotal.flag&1)=0) --Competenza
	AND expense.nphase = @nfinphase
	AND (@idfin IS NULL OR  isnull(FL.idparent,expenseyear.idfin) = @idfin)	
GROUP BY expenseyear.idupb,ISNULL(finlink.idparent,expenseyear.idfin)
CREATE TABLE #var_appropriation_C
    (
	idfin  int,
	idupb  varchar(36),
	totale decimal(19,2)					 
    )
INSERT INTO #var_appropriation_C
	(
	idfin,
	idupb,
	totale
	)
SELECT 
	ISNULL(finlink.idparent,expenseyear.idfin),
	expenseyear.idupb,
	SUM(ISNULL(expensevar.amount, 0.0))
FROM expensevar
JOIN expenseyear
	ON expenseyear.idexp = expensevar.idexp AND expenseyear.ayear = @ayear
JOIN expensetotal 
	ON  expenseyear.idexp = expensetotal.idexp AND
	expenseyear.ayear = expensetotal.ayear 
JOIN expense
	ON expense.idexp = expenseyear.idexp
JOIN fin
	ON fin.idfin = expenseyear.idfin
LEFT OUTER JOIN finlink 
	ON finlink.idchild = expenseyear.idfin 
	AND finlink.nlevel = @codelevel
LEFT OUTER JOIN finlink FL
	ON FL.idchild = expenseyear.idfin 
	AND FL.nlevel = @level_input
WHERE expensevar.yvar = @ayear
	AND ((expensetotal.flag&1)=0) --Competenza
	AND expense.nphase = @nfinphase
	AND expensevar.adate <= @adate 
	AND (@idfin IS NULL OR  isnull(FL.idparent,expenseyear.idfin) = @idfin)	
GROUP BY expenseyear.idupb,ISNULL(finlink.idparent,expenseyear.idfin)
CREATE TABLE #appropriation_R
    (
	idfin int,
	idupb varchar(36),
	totale decimal(19,2)					 
    )
INSERT INTO #appropriation_R
	(
	idfin,
	idupb,
	totale
	)
SELECT
	ISNULL(finlink.idparent,expenseyear.idfin),
	expenseyear.idupb,
	SUM(ISNULL(expenseyear.amount, 0.0))
FROM expenseyear
JOIN expense
	ON expense.idexp = expenseyear.idexp 
	AND expenseyear.ayear = @ayear
JOIN fin
	ON fin.idfin = expenseyear.idfin
JOIN expensetotal 
	ON  expenseyear.idexp = expensetotal.idexp AND
	expenseyear.ayear = expensetotal.ayear 	
LEFT OUTER JOIN finlink 
	ON finlink.idchild = expenseyear.idfin 
	AND finlink.nlevel = @codelevel
LEFT OUTER JOIN finlink FL
	ON FL.idchild = expenseyear.idfin 
	AND FL.nlevel = @level_input
WHERE ((expensetotal.flag&1)=1) --Residuo
	AND expense.nphase = @nfinphase
	AND (@idfin IS NULL 
	OR  isnull(FL.idparent,expenseyear.idfin) = @idfin)	
	AND expense.adate <= @adate
GROUP BY expenseyear.idupb,ISNULL(finlink.idparent,expenseyear.idfin)
