		--DB001040 Detrazioni per oneri
			INSERT INTO #recordg (progr, quadro, riga, colonna, decimale) VALUES(@progrComunic, 'DB', 1, '040', @wb40detrazioniperoneri )
		--DB001045 Totale Detrazioni 
