if object_id('[entry_shrink]') is not null
	drop PROCEDURE [entry_shrink]
go


CREATE             PROCEDURE [entry_shrink]
(
	@esercizio int
)
AS BEGIN
DECLARE @nentry int
DECLARE @yentry int
DECLARE @max_nentry int
--PRINT   @max_nentry
DECLARE @entry_to_compute int
SET  @entry_to_compute = (SELECT COUNT(*) FROM entry WHERE yentry = 9999)
DECLARE @entrydetail_to_compute int
SET @entrydetail_to_compute = (SELECT COUNT(*) FROM entrydetail WHERE yentry = 9999)
IF (ISNULL(@entry_to_compute,0)> 0 OR ISNULL(@entrydetail_to_compute,0)>0) 
BEGIN 
	RAISERROR('Una procedura di compattazione è già in esecuzione!',16,1)
END
UPDATE entry
SET yentry = 9999
WHERE yentry = @esercizio
UPDATE entrydetail
SET yentry = 9999
WHERE yentry = @esercizio
UPDATE entrydetailaccrual
SET yentry = 9999
WHERE yentry = @esercizio
UPDATE entrydetailaccrual
SET yentrylinked = 9999
WHERE yentrylinked = @esercizio
DECLARE rowcursor INSENSITIVE CURSOR FOR
SELECT yentry,nentry
FROM entry
WHERE yentry = 9999
ORDER BY adate asc
FOR READ ONLY
OPEN rowcursor
FETCH NEXT FROM rowcursor
INTO @yentry, @nentry
WHILE @@FETCH_STATUS = 0
BEGIN 
	SET 	@max_nentry = ISNULL((SELECT MAX(nentry) FROM entry WHERE yentry = @esercizio),0)
	PRINT   @max_nentry
	UPDATE 	entrydetail
	SET 	nentry = @max_nentry + 1,
		yentry = @esercizio
	WHERE 	nentry = @nentry AND
		yentry = 9999
	UPDATE entrydetailaccrual
	SET nentry = @max_nentry + 1, yentry = @esercizio
	WHERE nentry = @nentry AND yentry = 9999
	UPDATE entrydetailaccrual
	SET nentrylinked = @max_nentry + 1,
	yentrylinked = @esercizio
	WHERE nentrylinked = @nentry AND yentrylinked = 9999
	UPDATE 	entry
	SET 	nentry = @max_nentry + 1,
		yentry = @esercizio
	WHERE 	nentry = @nentry AND
		yentry = 9999
	--PRINT   @max_nentry
	FETCH NEXT FROM rowcursor
	INTO @yentry, @nentry
END 
DEALLOCATE rowcursor
END

GO

print '[entry_shrink] OK'

