if object_id('[trigger_u_storeunloaddetail]') is not null
	drop TRIGGER [trigger_u_storeunloaddetail]
go
CREATE   TRIGGER [trigger_u_storeunloaddetail] ON [storeunloaddetail] FOR UPDATE
AS BEGIN
DECLARE @oldnumber decimal (19,2)
DECLARE @oldidbooking int
DECLARE @oldidstock int
SELECT  @oldnumber = number , @oldidbooking = idbooking,  @oldidstock = idstock FROM deleted

DECLARE @oldidstore int
DECLARE @oldidlist int
SELECT  @oldidstore = idstore, @oldidlist = idlist FROM stock WHERE idstock = @oldidstock
DECLARE @newnumber decimal (19,2)
DECLARE @newidbooking int
DECLARE @newidstock int
SELECT  @newnumber = number , @newidbooking = idbooking,  @newidstock = idstock FROM inserted

DECLARE @newidstore int
DECLARE @newidlist int
SELECT  @newidstore = idstore, @newidlist = idlist FROM stock WHERE idstock = @newidstock
UPDATE stocktotal SET number = number + @oldnumber 
 WHERE idstore = @oldidstore and idlist = @oldidlist
-- se collegata alla prenotazione devo diminuire anche la q.tà prenotata
IF (@oldidbooking is not null)
Begin
	UPDATE stocktotal SET booked = booked + @oldnumber 
	WHERE idstore = @oldidstore and idlist = @oldidlist  
	IF EXISTS (SELECT * FROM booktotal 
			   WHERE idstore = @oldidstore AND 
					 idlist = @oldidlist AND 
					 idbooking = @oldidbooking)
	BEGIN
		UPDATE booktotal 
		SET	number	  = number + @oldnumber, 
			allocated = allocated + @oldnumber 
		WHERE idstore = @oldidstore AND idlist = @oldidlist 
		AND idbooking = @oldidbooking
	END
	ELSE 
	BEGIN
		INSERT INTO booktotal (idstore,idlist,idbooking,number,allocated)
		SELECT @oldidstore, @oldidlist, @oldidbooking,@oldnumber,@oldnumber
	END
End
UPDATE stocktotal SET number = number - @newnumber WHERE idstore = @newidstore and idlist = @newidlist
-- se collegata alla prenotazione devo diminuire anche la q.tà prenotata
IF (@newidbooking is not null)
Begin
	UPDATE stocktotal SET booked = booked - @newnumber WHERE idstore = @newidstore and idlist = @newidlist  
	UPDATE booktotal SET
			number	  = number - @newnumber, 
			allocated = allocated - @newnumber 
	WHERE idstore = @newidstore AND idlist = @newidlist AND idbooking = @newidbooking
	DELETE FROM booktotal 
	WHERE number = 0 AND allocated =  0 
	AND  idstore = @newidstore AND idlist = @newidlist AND idbooking = @newidbooking
End

END


GO

print '[trigger_u_storeunloaddetail] OK'

GO
if object_id('[rpt_sitbilancio_spesa_2fasi]') is not null
	drop PROCEDURE [rpt_sitbilancio_spesa_2fasi]
go

CREATE     PROCEDURE  [rpt_sitbilancio_spesa_2fasi] 
	@ayear				int,
	@date				datetime,
	@nlevel				tinyint,
	@hierarchy			char(1),
	@idupb				varchar(36),
	@showupb 			char(1),
	@showchildupb 			char(1),
	@suppressifblank 		char(1),
	@idfin			        int
AS
BEGIN
---exec rpt_sitbilancio_spesa_2fasi 2008, {ts '2008-05-13 00:00:00'}, 1, 'S', '%', 'N', 'S', 'S',null
/* Versione 1.0.5 del 27/11/2007 ultima modifica: MARIA */
CREATE TABLE #fin_situation
(
	idfin				int,
	codeupb				varchar(50),
	idupb 				varchar(36),
	upb   				varchar(150),
	upbprintingorder		varchar(50),
	assured				char(1),
	codefin				varchar(50),
	title				varchar(150),
	finprintingorder		varchar(50),
	nlevel				tinyint,
	main_initial_prevision		decimal(19,2),
	varprevprinc			decimal(19,2),
	appropriation_phase_comp 	decimal(19,2),
	var_appropriation_phase_comp	decimal(19,2),
	desc_appropriation_phase 	varchar(50),					
	max_phase_comp         		decimal(19,2),
	var_max_phase_comp      	decimal(19,2),
	desc_max_phase 			varchar(50),					
	sec_initial_prevision		decimal(19,2),
	varprevsec			decimal(19,2),
	appropriation_phase_resid 	decimal(19,2),
	var_appropriation_phase_resid	decimal(19,2),
	max_phase_resid        		decimal(19,2),
	var_max_phase_resid    		decimal(19,2),
	assign_credit 			decimal(19,2),
	var_assign_credit		decimal(19,2),
	assign_cash			decimal(19,2),
	var_assign_cash			decimal(19,2),
	previsionkind 			char(1),
	secprevisionkind 		char(1),
	flag_assign_credit 		char(1),
	flag_assign_cash 		char(1),
	flagconsider 			char(1) 			
)
IF (@ayear IS NULL) BEGIN
	SELECT * FROM  #fin_situation 
	RETURN
END
DECLARE @idupboriginal 			varchar(36)
SET @idupboriginal= @idupb
IF (@showchildupb = 'S') set @idupb=@idupb+'%' 
DECLARE @appropriation_phase     	tinyint
SELECT  @appropriation_phase = appropriationphasecode
FROM    config WHERE ayear = @ayear
IF @appropriation_phase IS NULL
BEGIN
	SELECT @appropriation_phase = expensefinphase FROM uniconfig
END
DECLARE @desc_appropriation_phase    	varchar(50)
SELECT 	@desc_appropriation_phase=description
FROM 	expensephase WHERE nphase=@appropriation_phase 
DECLARE @max_phase         		tinyint
SELECT  @max_phase = MAX(nphase)
FROM 	expensephase
DECLARE @desc_max_phase    		varchar(50)
SELECT  @desc_max_phase=description 
FROM 	expensephase WHERE nphase=@max_phase 
DECLARE @cashvaliditykind       	int
SELECT  @cashvaliditykind = cashvaliditykind
FROM    config
WHERE   ayear = @ayear
DECLARE @previsionkind char(1) 
SELECT  @previsionkind =  
	 CASE 
		WHEN fin_kind IN (1,3) THEN 'C'
		WHEN fin_kind = 2 THEN 'S'
	 END
FROM  config 
WHERE config.ayear = @ayear
DECLARE @secprevisionkind    char(1) 
SELECT  @secprevisionkind  = 
	 CASE 
		WHEN fin_kind = 3 THEN 'S'
		ELSE 'N'
	END
FROM config 
WHERE config.ayear = @ayear
DECLARE @level_input tinyint
SET  @level_input = ISNULL((SELECT nlevel from fin where idfin = @idfin) ,@nlevel)
-- ho scelto come livello 2 e poi ho specificato il capitolo, lui corregge @nlevel dandogli 3
IF (@nlevel < @level_input ) AND (@idfin is not null)
	BEGIN
	SET  @nlevel = @level_input
	END
DECLARE @levelusable 			tinyint
SELECT  @levelusable = MIN(nlevel) FROM finlevel
WHERE 	ayear =@ayear and (flag&2)<>0
IF (@hierarchy='N')
BEGIN
	IF (@suppressifblank = 'S')
	BEGIN
		INSERT INTO #fin_situation
	      	(
			idfin, 
			idupb,
			assured,
			varprevprinc,
			varprevsec,
			flagconsider
		)
		SELECT 
			F.idfin,  	
			U.idupb,
			ISNULL(U.assured,'N'),
			SUM(CASE WHEN finvar.flagprevision = 'S' then isnull(finvardetail.amount,0) else 0 END),
			SUM(CASE WHEN finvar.flagsecondaryprev = 'S' then isnull(finvardetail.amount,0) else 0 END),
			'S'
		FROM upbtotal
		JOIN upb U
			ON upbtotal.idupb = U.idupb
		JOIN fin F
			ON upbtotal.idfin = F.idfin
		JOIN finlink FLK1
			ON FLK1.idchild = F.idfin AND FLK1.nlevel = @level_input
		LEFT OUTER JOIN finlink FLK2
			ON FLK2.idparent = F.idfin AND FLK2.nlevel = @nlevel
		LEFT OUTER JOIN finvardetail
		  	ON finvardetail.idfin = FLK2.idchild
		  	AND finvardetail.idupb=U.idupb 	
		LEFT OUTER JOIN finvar
		 	ON finvar.yvar = finvardetail.yvar  AND finvar.yvar = @ayear	
	  	  	AND finvar.nvar = finvardetail.nvar AND finvar.adate <= @date
			AND finvar.idfinvarstatus = 5 AND finvar.variationkind <> 5
		WHERE  	((F.flag & 1 ) = 1) and F.ayear =@ayear	
			AND (@idfin IS NULL OR FLK1.idparent = @idfin)
			AND (F.nlevel = @nlevel)
			AND (U.idupb like @idupb  and U.active = 'S')
		GROUP BY U.idupb, F.idfin, ISNULL(U.assured,'N') 
		
		-- Inserisco le voci di bilancio che hanno solo RESIDUI
		INSERT INTO #fin_situation
	      			(idfin, 
				idupb,
				assured,
				varprevprinc,
				varprevsec,
				flagconsider
				)
		SELECT DISTINCT
				F.idfin, 
				U.idupb,
				ISNULL(U.assured,'N'),
				0,
				0,
				'S'
		FROM expenseyear
		JOIN upb U
			ON  expenseyear.idupb = U.idupb 
		JOIN fin F
			ON  expenseyear.idfin = F.idfin 
		JOIN expensetotal ET
			ON ET.idexp = expenseyear.idexp
			AND ET.ayear = expenseyear.ayear
		JOIN finlink FLK
			ON FLK.idparent = expenseyear.idfin AND FLK.nlevel = @level_input 
		WHERE  ((F.flag & 1 ) = 1) and F.ayear = @ayear	
			AND (@idfin IS NULL OR FLK.idparent = @idfin)
			AND (U.idupb like @idupb  and U.active = 'S')
			AND (F.nlevel   = @nlevel)
			AND NOT EXISTS 
				(SELECT *
				 FROM #fin_situation
				 JOIN finlink FLK1 
					ON FLK1.idchild = expenseyear.idfin 
				WHERE expenseyear.idupb = #fin_situation.idupb 
				   AND FLK1.idparent =  #fin_situation.idfin)
			AND expenseyear.ayear=@ayear
			AND ((ET.flag & 1) = 1) -- Residuo
		
	END
	ELSE
	BEGIN
		INSERT INTO #fin_situation
	      	(
			idfin, 
			idupb,
			assured, 
			varprevprinc,
			varprevsec,
			flagconsider
		)
		SELECT 
			F.idfin, 	
			U.idupb,
			ISNULL(U.assured,'N'),
			SUM(CASE WHEN finvar.flagprevision = 'S' then isnull(finvardetail.amount,0) else 0 END),
			SUM(CASE WHEN finvar.flagsecondaryprev = 'S' then isnull(finvardetail.amount,0) else 0 END),
			'S'
		FROM upb U
		CROSS JOIN fin F
		JOIN finlink FLK
			ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
		LEFT OUTER JOIN finlink FLK2
			ON FLK2.idparent = F.idfin 
		LEFT OUTER JOIN finvardetail
		  	ON finvardetail.idfin  = FLK2.idchild 
		  	AND finvardetail.idupb = U.idupb 	
		LEFT OUTER JOIN finvar
		 	ON finvar.yvar  = finvardetail.yvar  AND finvar.yvar = @ayear	
	  	  	AND finvar.nvar = finvardetail.nvar AND finvar.adate <= @date
			AND finvar.idfinvarstatus = 5 AND finvar.variationkind <> 5
		WHERE   ((F.flag & 1 ) = 1) and F.ayear =@ayear	
			AND (@idfin IS NULL OR FLK2.idparent = @idfin)
			AND (U.idupb like @idupb and U.active = 'S')
			AND (F.nlevel = @nlevel)
		GROUP BY U.idupb, F.idfin,ISNULL(U.assured,'N') 
	END
END 
ELSE --> @hierarchy = 'S'
BEGIN
	IF (@suppressifblank = 'S')
	BEGIN
		-----------------------------------
		-----------------------------------
		INSERT INTO #fin_situation
	      			(idfin, 
				idupb,
				assured,
				varprevprinc,
				varprevsec,
				flagconsider
				)
		SELECT 
				F.idfin,
				U.idupb,
				ISNULL(U.assured,'N'),
				SUM(CASE WHEN finvar.flagprevision = 'S' then isnull(finvardetail.amount,0) else 0 END),
				SUM(CASE WHEN finvar.flagsecondaryprev = 'S' then isnull(finvardetail.amount,0) else 0 END),
				CASE 
					WHEN (F.nlevel >= @levelusable and 
					F.idfin IN (SELECT idfin FROM finlast))
					THEN 'S'
					ELSE 'N'
				END
		FROM upbtotal
		JOIN upb U
			ON upbtotal.idupb = U.idupb
		JOIN fin F
			ON upbtotal.idfin = F.idfin
		LEFT OUTER JOIN finlink FLK2
			ON FLK2.idparent = F.idfin 
		LEFT OUTER JOIN finvardetail
		  	ON ISNULL(FLK2.idchild,F.idfin) = finvardetail.idfin
			AND finvardetail.idupb = U.idupb 
		LEFT OUTER JOIN finvar
		  	ON finvar.yvar = finvardetail.yvar  AND finvar.yvar = @ayear	
	  	  	AND finvar.nvar = finvardetail.nvar AND finvar.adate <= @date
			AND finvar.idfinvarstatus = 5 AND finvar.variationkind <> 5
		JOIN finlink FLK
			ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
		WHERE  ((F.flag & 1 ) = 1) AND F.ayear = @ayear
			AND (U.idupb like @idupb and U.active = 'S')
			AND F.nlevel >=  @nlevel
			AND (@idfin IS NULL OR FLK.idparent = @idfin)
		GROUP BY U.idupb,F.idfin,F.nlevel,F.ayear, F.flag, ISNULL(U.assured,'N') --(F.flag & 1) 

		-- Inserisco le coppie che hanno solo RESIDUI
		INSERT INTO #fin_situation
		(
			idfin, 
			idupb,
			assured,
			varprevprinc,
			varprevsec,
			flagconsider
		)
		SELECT distinct
			F.idfin,
			U.idupb,
			ISNULL(U.assured,'N'),
			0,
			0,
			CASE 
				WHEN (F.nlevel >= @levelusable and 
				F.idfin IN (SELECT idfin FROM finlast))
				THEN 'S'
				ELSE 'N'
			END 
		FROM expenseyear
		JOIN upb U
			ON expenseyear.idupb = U.idupb 
		JOIN fin F
			ON expenseyear.idfin = F.idfin 
		JOIN expensetotal ET
			ON ET.idexp = expenseyear.idexp
			AND ET.ayear = expenseyear.ayear
		JOIN finlink FLK
			ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
		WHERE  ((F.flag & 1 ) = 1) and F.ayear = @ayear
			AND (@idfin IS NULL OR FLK.idparent = @idfin)
			AND (U.idupb like @idupb and U.active = 'S')
			AND (F.nlevel >=  @nlevel)
			AND NOT EXISTS (SELECT *
					  FROM #fin_situation
					  jOIN finlink FLK1 
						ON FLK1.idchild = expenseyear.idfin
					 WHERE expenseyear.idupb = #fin_situation.idupb 
					   AND FLK1.idparent  =  #fin_situation.idfin)			
			AND expenseyear.ayear=@ayear
			AND ((ET.flag&1) = 1) -- Residuo
		
		--GROUP BY U.idupb,F.idfin,F.nlevel,F.ayear,(F.flag & 1) 
	END
	ELSE
	BEGIN
		
		INSERT INTO #fin_situation
	      	(
			idfin, 
			idupb,
			assured, 
			varprevprinc,
			varprevsec,
			flagconsider
		)
		SELECT 
			F.idfin,
			U.idupb,
			ISNULL(U.assured,'N'),
			SUM(CASE WHEN finvar.flagprevision = 'S' then isnull(finvardetail.amount,0) else 0 END),
			SUM(CASE WHEN finvar.flagsecondaryprev = 'S' then isnull(finvardetail.amount,0) else 0 END),
			CASE 
				WHEN (F.nlevel >= @levelusable and 
				F.idfin IN (SELECT idfin FROM finlast))
				THEN 'S'
				ELSE 'N'
			END
	        FROM upb U
		CROSS JOIN fin F
		LEFT OUTER JOIN finlink FLK2
			ON FLK2.idparent = F.idfin
		LEFT OUTER JOIN finvardetail
                        ON ISNULL(FLK2.idchild,F.idfin) = finvardetail.idfin
			AND finvardetail.idupb=U.idupb 
		LEFT OUTER JOIN finvar
			ON finvar.yvar = finvardetail.yvar  and finvar.yvar = @ayear
			AND finvar.nvar = finvardetail.nvar and finvar.adate <= @date
			AND finvar.idfinvarstatus = 5 AND finvar.variationkind <> 5
		JOIN finlink FLK
			ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
		WHERE   ((F.flag & 1 ) = 1) and F.ayear = @ayear
			AND (@idfin IS NULL OR FLK.idparent = @idfin)
			AND (U.idupb like @idupb  and U.active = 'S')
			AND (F.nlevel >=  @nlevel) 
		GROUP BY U.idupb,F.idfin,F.nlevel,F.ayear,F.flag, ISNULL(U.assured,'N')
		
	END
END
	UPDATE #fin_situation
		set main_initial_prevision = 
			ISNULL((
			SELECT SUM(finyear.prevision)
			FROM finyear 
			JOIN fin 
				ON finyear.idfin = fin.idfin  		
			JOIN upb
				ON finyear.idupb = upb.idupb 
			JOIN finlevel 
				ON finlevel.ayear = fin.ayear
				AND finlevel.nlevel = fin.nlevel
			JOIN finlast 
				ON finlast.idfin = fin.idfin
			JOIN finlink
				ON finlink.idchild = fin.idfin
			WHERE finlink.idparent = #fin_situation.idfin
				 AND (finlevel.flag&2)<>0
				 AND finyear.idupb =  #fin_situation.idupb 
				 AND finyear.ayear = @ayear), 0.0),
		sec_initial_prevision = 	
				ISNULL((
				SELECT SUM(finyear.secondaryprev)
				FROM finyear 
				JOIN fin 
					ON finyear.idfin = fin.idfin 
				JOIN upb
					ON finyear.idupb = upb.idupb  
				JOIN finlevel 
					ON finlevel.ayear = fin.ayear
					AND finlevel.nlevel = fin.nlevel
				JOIN finlast 
					ON finlast.idfin = fin.idfin
				JOIN finlink
					ON finlink.idchild = fin.idfin
				WHERE finlink.idparent = #fin_situation.idfin
					AND (finlevel.flag&2)<>0
					AND finyear.idupb =  #fin_situation.idupb 
					AND finyear.ayear = @ayear
					), 0.0)
	UPDATE #fin_situation
		SET
		 appropriation_phase_comp = 
			ISNULL((SELECT SUM(expenseyear.amount)
			FROM expense
			JOIN expenseyear
				ON expenseyear.idexp = expense.idexp
			JOIN expensetotal 
				ON expensetotal.idexp = expenseyear.idexp
				AND expensetotal.ayear = expenseyear.ayear
			JOIN finlink
				ON finlink.idchild = expenseyear.idfin
			WHERE expense.adate <= @date 
				AND expenseyear.ayear = @ayear
				AND ((expensetotal.flag&1)=0) -- Competenza
				AND finlink.idparent= #fin_situation.idfin 
				AND expenseyear.idupb = #fin_situation.idupb
				AND expense.nphase = @appropriation_phase), 0.0),
		var_appropriation_phase_comp =
			ISNULL((SELECT SUM(expensevar.amount)
			FROM expensevar
			JOIN expense
				ON expensevar.idexp = expense.idexp
			JOIN expenseyear
				ON expenseyear.idexp = expensevar.idexp
			JOIN expensetotal 
				ON expensetotal.idexp = expenseyear.idexp
				AND expensetotal.ayear = expenseyear.ayear
			JOIN finlink
				ON finlink.idchild = expenseyear.idfin
			WHERE expensevar.adate <= @date 
				AND expenseyear.ayear = @ayear
				AND expense.nphase= @appropriation_phase
				AND ((expensetotal.flag&1)=0) -- Competenza
				AND finlink.idparent = #fin_situation.idfin 
				AND expenseyear.idupb = #fin_situation.idupb
				AND expensevar.yvar = @ayear), 0.0),
		 appropriation_phase_resid = 
			ISNULL((SELECT SUM(expenseyear.amount)
				FROM expense
				JOIN expenseyear
					ON expenseyear.idexp = expense.idexp
				JOIN expensetotal 
					ON expensetotal.idexp = expenseyear.idexp
					AND expensetotal.ayear = expenseyear.ayear
				JOIN finlink
					ON finlink.idchild = expenseyear.idfin
			WHERE expense.adate <= @date 
				AND expenseyear.ayear = @ayear
				AND ((expensetotal.flag&1)=1) -- Residuo
				AND finlink.idparent = #fin_situation.idfin 
				AND expenseyear.idupb = #fin_situation.idupb 
				AND expense.nphase = @appropriation_phase), 0.0),
		var_appropriation_phase_resid =
			ISNULL((SELECT SUM(expensevar.amount)
			FROM expensevar
			JOIN expense
				ON expensevar.idexp = expense.idexp
			JOIN expenseyear
				ON expenseyear.idexp = expensevar.idexp
			JOIN expensetotal 
				ON expensetotal.idexp = expenseyear.idexp
				AND expensetotal.ayear = expenseyear.ayear
			JOIN finlink
				ON finlink.idchild = expenseyear.idfin	 
			WHERE expensevar.adate <= @date 
				AND expenseyear.ayear = @ayear
				AND expense.nphase= @appropriation_phase
				AND ((expensetotal.flag&1)=1) -- Residuo
				AND finlink.idparent = #fin_situation.idfin 
				AND expenseyear.idupb = #fin_situation.idupb
				AND expensevar.yvar   = @ayear), 0.0)
    UPDATE #fin_situation
--  GESTIONE DEL FONDO ECONOMALE
    SET 
		appropriation_phase_comp = 
			ISNULL(appropriation_phase_comp, 0.0) +
			ISNULL((SELECT SUM(operation.amount)
			FROM pettycashoperation operation
			JOIN finlink 
				ON finlink.idchild = operation.idfin
			WHERE finlink.idparent = #fin_situation.idfin
				AND operation.idupb = #fin_situation.idupb
				AND operation.yoperation = @ayear
				AND operation.adate <= @date 
				AND NOT EXISTS (SELECT * FROM pettycashoperation oprestore
						WHERE oprestore.idpettycash = operation.idpettycash
						AND oprestore.yoperation = operation.yrestore
						AND oprestore.noperation = operation.nrestore
						AND oprestore.adate <= @date
						AND oprestore.yoperation = @ayear)), 0.0)
UPDATE #fin_situation
	SET	max_phase_comp=	 
			ISNULL((SELECT SUM(HPV.amount)
			FROM historypaymentview HPV
			JOIN finlink
				ON finlink.idchild = HPV.idfin	 
			WHERE ((HPV.totflag&1)=0) -- Competenza
				AND HPV.ymov = @ayear
				AND HPV.competencydate <= @date
				AND finlink.idparent = #fin_situation.idfin
				AND HPV.idupb = #fin_situation.idupb), 0.0),
		max_phase_resid=	 
				ISNULL((SELECT SUM(HPV.amount)
				FROM historypaymentview HPV
				JOIN finlink
					ON finlink.idchild = HPV.idfin	 
				WHERE ((HPV.totflag&1)=1) -- Residuo
					AND HPV.ymov = @ayear
					AND HPV.competencydate <= @date
					AND finlink.idparent = #fin_situation.idfin
					AND HPV.idupb = #fin_situation.idupb), 0.0)	
	
IF @cashvaliditykind <> 4
BEGIN
	UPDATE #fin_situation
		SET var_max_phase_comp= 
			ISNULL((SELECT SUM(expensevar.amount)
			FROM expensevar
			JOIN historypaymentview HPV
				ON HPV.idexp = expensevar.idexp
			JOIN finlink
				ON finlink.idchild = HPV.idfin	
			WHERE  finlink.idparent = #fin_situation.idfin
				AND HPV.ymov = @ayear AND HPV.competencydate <= @date
				AND ((HPV.totflag&1)=0) -- Copetenza
				AND HPV.idupb = #fin_situation.idupb
				AND expensevar.yvar = @ayear
				AND expensevar.adate <= @date), 0.0),
		var_max_phase_resid= 
			ISNULL((SELECT SUM(expensevar.amount)
			FROM expensevar
			JOIN  historypaymentview HPV
				ON HPV.idexp = expensevar.idexp
			JOIN finlink
				ON finlink.idchild = HPV.idfin	
			WHERE expensevar.yvar = @ayear
				AND HPV.ymov = @ayear AND HPV.competencydate <= @date
				AND ((HPV.totflag&1)=1) -- Residuo
				AND finlink.idparent  = #fin_situation.idfin
				AND HPV.idupb = #fin_situation.idupb 
				AND expensevar.adate <= @date), 0.0)
END
	
-- Controlla che i CREDITI  siano gestiti
IF 	(EXISTS(SELECT* FROM creditpart
		WHERE ycreditpart = @ayear AND adate <= @date) 
	OR
	EXISTS (SELECT * FROM finvar
		WHERE flagcredit ='S' and yvar = @ayear
		AND adate <= @date
		AND finvar.idfinvarstatus = 5)
	--OR  
	--EXISTS (select * from upb where assured='S')
	)
	BEGIN
		UPDATE #fin_situation
		SET var_assign_credit = ISNULL((SELECT SUM(d.amount)
				FROM finvardetail d
				JOIN finvar v 
					ON v.yvar = d.yvar
					AND v.nvar = d.nvar
				JOIN finlink
					ON finlink.idchild = d.idfin
				WHERE finlink.idparent = #fin_situation.idfin
					AND v.idfinvarstatus = 5
					AND d.idupb = #fin_situation.idupb
					AND #fin_situation.assured <> 'S' -- solo upb non a finanziamento certo
					AND v.flagcredit ='S'
					AND v.adate <= @date
					AND v.variationkind IN (2,3)),0.0),
		 assign_credit = ISNULL((SELECT SUM(creditpart.amount)
				FROM creditpart 
				JOIN incomeyear
					ON creditpart.idinc = incomeyear.idinc
					AND creditpart.ycreditpart = incomeyear.ayear
				JOIN finlink
					ON finlink.idchild = creditpart.idfin
				WHERE finlink.idparent = #fin_situation.idfin
					AND creditpart.idupb = #fin_situation.idupb
					AND #fin_situation.assured <> 'S'
					AND adate <= @date),0.0)
				+	
				ISNULL((SELECT SUM(d.amount)
				FROM finvardetail d
				JOIN finvar v
					ON v.yvar = d.yvar
					AND v.nvar = d.nvar
					AND v.flagcredit ='S'
				JOIN finlink
					ON finlink.idchild = d.idfin
				WHERE finlink.idparent = #fin_situation.idfin
					AND v.idfinvarstatus = 5
					AND d.idupb = #fin_situation.idupb
					AND #fin_situation.assured <> 'S'
					AND v.adate <= @date
					AND v.variationkind IN (1,4)),0.0),
		flag_assign_credit='S'
		UPDATE #fin_situation
			SET flag_assign_credit='N'    -- se upb a finanziamento certo, non considero i crediti
			WHERE #fin_situation.assured  = 'S'
	END
ELSE
	UPDATE  #fin_situation
	SET 	var_assign_credit = 0,
		assign_credit =0,
		flag_assign_credit='N'
-- Controlla che gli INCASSI siano gestiti
IF 	(EXISTS(SELECT* FROM proceedspart 
		WHERE yproceedspart	= @ayear
		AND adate <= @date) 
	OR
	EXISTS (SELECT * FROM finvar
		WHERE flagproceeds='S' and 
		yvar = @ayear AND 
		adate <= @date
		AND finvar.idfinvarstatus = 5)
	--OR
	--EXISTS (select * from upb where assured='S')
	)
	BEGIN
	UPDATE #fin_situation
		SET var_assign_cash = 
			ISNULL(( SELECT SUM(d.amount)
			FROM finvardetail d
			JOIN finvar v
				ON v.yvar = d.yvar
				AND v.nvar = d.nvar
				AND v.flagproceeds='S'
			JOIN finlink
				ON finlink.idchild = d.idfin
			WHERE finlink.idparent = #fin_situation.idfin
				AND v.idfinvarstatus = 5
				AND d.idupb = #fin_situation.idupb
				AND #fin_situation.assured <> 'S'
				AND v.adate <= @date
				AND v.variationkind IN (2,3)),0.0),
		 
		assign_cash = ISNULL(( select SUM(proceedspart.amount)
			FROM proceedspart
			JOIN incomeyear
				ON proceedspart.idinc = incomeyear.idinc
				AND proceedspart.yproceedspart = incomeyear.ayear
			JOIN finlink
				ON finlink.idchild = proceedspart.idfin
			WHERE finlink.idparent = #fin_situation.idfin
				AND proceedspart.idupb = #fin_situation.idupb
				AND #fin_situation.assured <> 'S'
				AND adate <= @date),0.0)
			+
			ISNULL((SELECT  SUM(d.amount)
			FROM finvardetail d
			JOIN finvar v
				ON v.yvar = d.yvar
				AND v.nvar = d.nvar
				AND v.flagproceeds='S'
			JOIN finlink
				ON finlink.idchild = d.idfin
			WHERE finlink.idparent = #fin_situation.idfin
				AND v.idfinvarstatus = 5
				AND v.adate <= @date
				AND d.idupb = #fin_situation.idupb
				AND #fin_situation.assured <> 'S'
				AND v.variationkind IN (1,4)),0.0),
		flag_assign_cash='S'
		UPDATE #fin_situation
		SET flag_assign_cash='N' 
		WHERE #fin_situation.assured = 'S'
	END
ELSE
	BEGIN 
	UPDATE #fin_situation
	SET	var_assign_cash = 0,
		assign_cash = 0,
		flag_assign_cash='N'
	END
-- VALORIZZA CAMPI upb
IF (@showupb = 'S')	
	UPDATE #fin_situation 
	SET  upbprintingorder = upb.printingorder,
	upb = upb.title,
	codeupb = upb.codeupb
	FROM upb
	WHERE upb.idupb = #fin_situation.idupb
IF (@showupb <>'S') AND (@idupboriginal <> '%' ) AND (@showchildupb = 'S')
	BEGIN
	UPDATE #fin_situation SET  
	idupb = @idupboriginal,
	upbprintingorder = (SELECT TOP 1 printingorder
				FROM upb
				WHERE idupb = @idupboriginal),
	upb = (SELECT TOP 1 title
				FROM upb
				WHERE idupb = @idupboriginal),
	codeupb =(SELECT TOP 1 codeupb
				FROM upb
				WHERE idupb = @idupboriginal)
	IF  (EXISTS(SELECT* FROM creditpart 
		     WHERE ycreditpart = @ayear AND adate <= @date) 
		OR
		EXISTS (SELECT * FROM finvar
			WHERE flagcredit='S' and 
			yvar = @ayear AND adate <= @date
			AND finvar.idfinvarstatus = 5)
		)
			BEGIN 
				UPDATE #fin_situation
				SET    flag_assign_credit='S'
				FROM   upb
				WHERE  upb.idupb = #fin_situation.idupb    -- ho aggiornato l'upb devo rivalutare flag_assign_credit
				  AND ISNULL(upb.assured, 'N') <> 'S'
				
				UPDATE #fin_situation
				SET    flag_assign_credit='N'
				FROM   upb 
				WHERE  upb.idupb = #fin_situation.idupb 
				  AND  ISNULL(upb.assured, 'N') = 'S'
			END
			ELSE   
			UPDATE #fin_situation
			SET    flag_assign_credit='N'
	
			IF  (EXISTS(SELECT* FROM proceedspart 
				WHERE yproceedspart = @ayear AND adate <= @date) 
			OR
			EXISTS (SELECT * FROM finvar
				WHERE flagproceeds='S' and 
				yvar = @ayear AND adate <= @date
				AND finvar.idfinvarstatus = 5)
			)	
			BEGIN
				UPDATE #fin_situation
				SET    flag_assign_cash='S'
				FROM   upb 
				WHERE  upb.idupb = #fin_situation.idupb  -- ho aggiornato l'upb devo rivalutare flag_assign_cash
				  AND ISNULL(upb.assured, 'N') <> 'S'
				
				UPDATE #fin_situation
				SET    flag_assign_cash='N'
				FROM   upb 
				WHERE  upb.idupb = #fin_situation.idupb 
				  AND  ISNULL(upb.assured, 'N') = 'S'
			END
			ELSE   
			UPDATE #fin_situation
			SET    flag_assign_cash='N'
		END
IF (@showupb <>'S') and (@idupboriginal = '%') 
	BEGIN
		UPDATE #fin_situation SET  
		idupb = 		null,
		upbprintingorder = 	null,
		upb =  			null,
		codeupb = 		null
		-- considero solo se sono gestiti crediti e cassa, non gli upb
		IF  (EXISTS(SELECT* FROM creditpart 
		     WHERE ycreditpart = @ayear AND adate <= @date) 
		OR
		EXISTS (SELECT * FROM finvar
			WHERE flagcredit='S' and yvar = @ayear AND adate <= @date))
			UPDATE #fin_situation
			SET    flag_assign_credit='S'
			ELSE   
			UPDATE #fin_situation
			SET    flag_assign_credit='N'
	
		IF  (EXISTS(SELECT* FROM proceedspart 
			WHERE yproceedspart = @ayear AND adate <= @date) 
		OR
		EXISTS (SELECT * FROM finvar
			WHERE flagproceeds='S' and 
			yvar = @ayear AND adate <= @date
			AND finvar.idfinvarstatus = 5))
			UPDATE #fin_situation
			SET    flag_assign_cash='S'
			ELSE   
			UPDATE #fin_situation
			SET    flag_assign_cash='N'
	END
IF (@suppressifblank = 'S') AND @nlevel>=2 --> se la stampa è x un livello uguale o sottostante la categoria cancella le righe
BEGIN
	DELETE FROM #fin_situation WHERE 
		(isnull(main_initial_prevision,0.0) =0 AND 
		isnull(varprevprinc,0.0) =0 AND 
		isnull(appropriation_phase_comp,0.0) =0 AND 
		isnull(var_appropriation_phase_comp,0.0) =0 AND 
		isnull(max_phase_comp,0.0) =0 AND 
		isnull(var_max_phase_comp,0.0) =0 AND 
		isnull(sec_initial_prevision,0.0) =0 AND 
		isnull(varprevsec,0.0) =0 AND 
		isnull(appropriation_phase_resid,0.0) =0 AND 
		isnull(var_appropriation_phase_resid,0.0) =0 AND 
		isnull(max_phase_resid,0.0) =0 AND 
		isnull(var_max_phase_resid,0.0) =0 AND 
		isnull(assign_credit,0.0) =0 AND 
		isnull(var_assign_credit,0.0) =0 AND 
		isnull(assign_cash,0.0) =0 AND 
		isnull(var_assign_cash,0.0) =0 AND
		(select nlevel from fin FFF where FFF.idfin= #fin_situation.idfin)>=2
)	--AND nlevel >=2)
END
IF (@showupb <>'S') 
BEGIN
	SELECT 	#fin_situation.idfin,	
		codeupb,
		idupb,
		upb,
		upbprintingorder,
		fin.codefin,	
		fin.title,	
		fin.printingorder as 'finprintingorder',	
		fin.nlevel,	
		sum(isnull(main_initial_prevision,0.0)) as 'main_initial_prevision',
		sum(isnull(varprevprinc,0.0)) 		as 'varprevprinc'	,
		sum(isnull(appropriation_phase_comp,0.0)) 	as 'appropriation_phase_comp',
		sum(isnull(var_appropriation_phase_comp,0.0)) 	as 'var_appropriation_phase_comp' ,
		@desc_appropriation_phase  			as 'desc_appropriation_phase',									
		sum(isnull(max_phase_comp,0.0)) 	as 'max_phase_comp',
		sum(isnull(var_max_phase_comp,0.0)) 	as 'var_max_phase_comp',
		@desc_max_phase 			as 'desc_max_phase',										
		sum(isnull(sec_initial_prevision,0.0)) 	as 'sec_initial_prevision',
		sum(isnull(varprevsec,0.0)) 		as 'varprevsec',
		sum(isnull(appropriation_phase_resid,0.0)) 	as 'appropriation_phase_resid',
		sum(isnull(var_appropriation_phase_resid,0.0)) 	as 'var_appropriation_phase_resid',
		sum(isnull(max_phase_resid,0.0)) 	as 'max_phase_resid' ,
		sum(isnull(var_max_phase_resid,0.0)) 	as 'var_max_phase_resid',
		sum(isnull(assign_credit,0.0)) 		as 'assign_credit',
		sum(isnull(var_assign_credit,0.0)) 	as 'var_assign_credit',
		sum(isnull(assign_cash,0.0)) 		as 'assign_cash' ,
		sum(isnull(var_assign_cash,0.0)) 	as 'var_assign_cash',
		@previsionkind 				as 'previsionkind',
		@secprevisionkind 			as 'secprevisionkind',
		flag_assign_credit,
		flag_assign_cash,
		flagconsider			
		FROM #fin_situation 
		JOIN fin 
			ON #fin_situation.idfin = fin.idfin		
		GROUP BY idupb,
			#fin_situation.idfin,
			codeupb,
			upb,
			upbprintingorder,
			fin.codefin,	
			fin.title,
			fin.printingorder,
			fin.nlevel,
			flag_assign_credit,
			flag_assign_cash,
			flagconsider			
		ORDER BY upbprintingorder,finprintingorder
END
ELSE
	SELECT 
		#fin_situation.idfin,	
		codeupb,
		idupb,
		upb,
		upbprintingorder,
		fin.codefin,	
		fin.title,	
		fin.printingorder as 'finprintingorder',	
		fin.nlevel,	
		main_initial_prevision,
		varprevprinc,
		appropriation_phase_comp,
		var_appropriation_phase_comp,
		@desc_appropriation_phase as 'desc_appropriation_phase',					
		max_phase_comp,
		var_max_phase_comp,
		@desc_max_phase as 'desc_max_phase',					
		sec_initial_prevision,
		varprevsec,
		appropriation_phase_resid,
		var_appropriation_phase_resid,
		max_phase_resid,
		var_max_phase_resid,
		assign_credit,
		var_assign_credit,
		assign_cash,
		var_assign_cash,
		@previsionkind as 'previsionkind',
		@secprevisionkind as 'secprevisionkind',
		flag_assign_credit,
		flag_assign_cash,
		flagconsider			
		FROM #fin_situation JOIN fin 
			ON #fin_situation.idfin = fin.idfin		
		ORDER BY upbprintingorder,finprintingorder
END

GO

print '[rpt_sitbilancio_spesa_2fasi] OK'

GO
if object_id('[trigger_d_taxpay]') is not null
	drop TRIGGER [trigger_d_taxpay]
go

CREATE             TRIGGER [trigger_d_taxpay] ON [taxpay] FOR DELETE
AS BEGIN
	IF @@ROWCOUNT > 0
	BEGIN
		DECLARE @ytaxpay int
		DECLARE @ntaxpay integer
		DECLARE @taxcode int
	
		SELECT @ytaxpay = ytaxpay,
		@ntaxpay = ntaxpay,
		@taxcode = taxcode
		FROM deleted
	
		DELETE FROM taxpayexpense
		WHERE ytaxpay = @ytaxpay
		AND ntaxpay = @ntaxpay
		AND taxcode = @taxcode
		
	END
END


GO

print '[trigger_d_taxpay] OK'

GO
if object_id('[rpt_partitario_spese_intestazione_respons]') is not null
	drop PROCEDURE [rpt_partitario_spese_intestazione_respons]
go

CREATE     PROCEDURE [rpt_partitario_spese_intestazione_respons]
	@ayear int,
	@idupb	varchar(36),
	@codelevel tinyint,
	@showupb char(1),
	@showchildupb char(1),
	@idman int,
	@suppressifblank char(1),
	@codefin varchar(50),
	@start datetime,
	@stop datetime
AS
BEGIN
declare @mystart smalldatetime
declare @mystop smalldatetime
set @mystart=convert(smalldatetime,@start)
set @mystop=convert(smalldatetime,@stop)

DECLARE @idfin int
IF (@codefin IS NULL OR @codefin = '' OR @codefin = '%')
	BEGIN
		SET @idfin = null	
	END
Else
	BEGIN
	   	SET @idfin = (select idfin 
				from fin 
				where codefin = @codefin 
				and ayear=@ayear 
				and (fin.flag&1)=1) -- Spesa
	END
DECLARE @level_input tinyint
SET  @level_input = ISNULL((SELECT nlevel from fin where idfin = @idfin) ,@codelevel)
-- ho scelto come livello 2 e poi ho specificato il capitolo, lui corregge @nlevel dandogli 3
IF (@codelevel < @level_input ) AND (@idfin is not null)
	BEGIN
	SET  @codelevel = @level_input
	END

DECLARE @levelusable tinyint
SELECT  @levelusable = MIN(nlevel)
	FROM finlevel
	WHERE (flag&2)<>0  AND ayear = @ayear
IF @levelusable < @codelevel
BEGIN	
	SET @levelusable = @codelevel
END

DECLARE @idupboriginal 	varchar(36)
SET @idupboriginal= @idupb
IF (@showchildupb = 'S') 
BEGIN
	SET @idupb=@idupb+'%' 
END

-- considerare bene cosa succede quando voglio la stampa per articolo e specifico un capitolo in input
-- devo prendere i figli del capitolo specificato, aventi livello @codelevel

----modifica Piero-----

-- Nella logica di questi partitari la fase di spesa interessata deve essere quella di livelloo 
-- corrispondente all'anagrafica
DECLARE @nfinphase tinyint
select @nfinphase = expenseregphase
	FROM uniconfig
----fine modifica-----

-- ovvero prendo la massima fase tra quelle che contengono o il codice di bilancio o il creditore perchÃƒÂ¨ questÃƒÂ  ÃƒÂ¨ la vera fase di impegno giuridico
DECLARE @maxexpensephase tinyint
SELECT  @maxexpensephase = MAX(nphase)
FROM    expensephase 
-- ATTENZIONE L'ipotesi di funzionamento di questa sp è che fase dell'impegno = fase del pagamento - 1.
-- ALTRIMENTI SBALLA LE RIGHE DEL PAGAMENTO SUL REPORT (o meglio con un pò di tempo si deve fare un controllo per eliminare tutte le fasi 
-- che non sono fasepagamento e faseimpegno, anzi lo faccio subito inserendo alla fine una DELETE WHERE nphase <> fase del pagamento AND nphase <> fase dell'impegno)
CREATE TABLE #expense
(
	idfin int ,
	codeupb varchar(50),
	idupb varchar(36),
	upb varchar(150),
	upbprintingorder varchar(50),
	nphase tinyint,
	rowkind int,
	initialprevisioncomp decimal(19,2),
	initialprevisioncash decimal(19,2),
	finvar_prevision decimal(19,2),
	finvar_secondaryprev decimal(19,2),
	appropriation_C decimal(19,2),
	var_appropriation_C decimal(19,2),
	payment_C decimal(19,2),
	var_payment_C decimal(19,2),
	appropriation_R decimal(19,2),
	var_appropriation_R decimal(19,2),
	payment_R decimal(19,2),
	var_payment_R decimal(19,2),
	adate datetime,
	description varchar(300),                   
	idreg int,	
	nappropriation int,
	ymovappropriation int,
	nmovappropriation int,
	appropriation_amount decimal(19,2),
	available decimal(19,2),
	npayment int,
	ymovpayment int,
	nmovpayment int,
	payment_amount decimal(19,2),
	npay int,
	flagarrear char(1),	
	reportdate datetime,
	ayear int,
	idappropriation int,
	idman int,
	manager varchar(150),
	total_appropriation_C decimal(19,2) ,
	total_var_appropriation_C decimal(19,2),
	total_appropriation_R decimal(19,2),
	total_var_appropriation_R decimal(19,2),
	total_payment_C decimal(19,2),
	total_var_payment_C decimal(19,2),
	total_payment_R  decimal(19,2),
	total_var_payment_R decimal(19,2),   -- N.B.: non serve calcolare i totali relativi alle previsioni e alle var di previsione 
	-- in quanto sono gia calcolati indipendentemente dal responsabile.
	emissiondate datetime,
	printeddate datetime,
	transmitteddate datetime,
	transactiondate datetime,
	annulmentdate datetime
)
INSERT INTO #expense
(
	idfin,
	idupb,
	nphase,
	rowkind, 
	adate, 
	description, 
	idreg,		
	nappropriation, 
	ymovappropriation,
	nmovappropriation,
	appropriation_amount,
	npayment, 
	ymovpayment,
	nmovpayment,
	payment_amount,
	npay,
	flagarrear,
	idappropriation,
	available,
	idman
)	--> prende quelli movimentati
SELECT 
	ISNULL(FL.idparent, expenseyear.idfin),
	upb.idupb,
	expense.nphase,
	expense.nphase-1,
	expense.adate,
	case isnull(expense.doc,'') when '' then expense.description 
	else  expense.description + ' (Doc. ' + isnull(Convert (varchar(35),expense.doc),'') + ' del '+ 
		isnull(Convert (varchar(2),datepart(dd,expense.docdate)),'')+ ' '+ 
		isnull(Convert (varchar(2),datepart(mm,expense.docdate)),'')+
		' '+ isnull(Convert (varchar(4),datepart(yy,expense.docdate)),'')+')'
	end,
	expense.idreg,	
	E2.idexp, --IMPEGNO
	E2.ymov,
	E2.nmov,  
	expenseyear.amount,
	E3.idexp, --PAGAMENTO
	E3.ymov,
	E3.nmov, 
	expenseyear.amount,
	payment.npay,
	CASE
		WHEN ((expensetotal.flag&1)=0) THEN 'C'
		WHEN ((expensetotal.flag&1)=1) THEN 'R'
	END, 
	E2.idexp, --IMPEGNO
	ET2.available,
	expense.idman
FROM expenseyear
JOIN expense
	ON expenseyear.idexp = expense.idexp 
JOIN upb
	ON upb.idupb = expenseyear.idupb
JOIN fin
	ON expenseyear.idfin = fin.idfin 
	AND expenseyear.ayear = fin.ayear
JOIN expensetotal
	ON  expenseyear.idexp = expensetotal.idexp
	AND expenseyear.ayear = expensetotal.ayear		
JOIN expenselink EL2
	ON EL2.idchild = expense.idexp  AND EL2.nlevel = @nfinphase  --adesso è la fase di registro (infatti solo il nome è lo stesso)
LEFT  OUTER JOIN finlink FL
	ON FL.idchild = expenseyear.idfin  AND FL.nlevel = @codelevel
LEFT  OUTER JOIN finlink FL1
	ON FL1.idchild = expenseyear.idfin  AND FL1.nlevel = @level_input
LEFT  OUTER JOIN expenselast
	ON expenselast.idexp = expense.idexp
LEFT  OUTER JOIN payment
	ON expenselast.kpay = payment.kpay
LEFT OUTER JOIN expenselink EL3
	ON EL3.idchild = expense.idexp  AND EL3.nlevel = @maxexpensephase
LEFT OUTER JOIN expense E2
	ON E2.idexp = EL2.idparent
JOIN expensetotal ET2
	ON ET2.idexp=E2.idexp
	AND ET2.ayear = expenseyear.ayear
LEFT OUTER JOIN expense E3
	ON E3.idexp = EL3.idparent
WHERE ((fin.flag&1)=1) -- Spesa
	AND expenseyear.ayear = @ayear
	AND (@idfin IS NULL OR  isnull(FL1.idparent, expenseyear.idfin) = @idfin)		
	AND expense.adate between @mystart and @mystop
	AND ((expense.idman  = @idman) OR (@idman is null and expense.idman is not null))	
	AND ((expense.nphase IN (@nfinphase,@maxexpensephase )))
	AND (upb.idupb like @idupb) 

--select  'prima', * from #expense
IF (@suppressifblank = 'S')
BEGIN
	INSERT INTO #expense
		(
		idfin,
		idupb,
		idman
		)	--> Prende quelli non movimentati 1^ parte
	SELECT DISTINCT
		ISNULL(FL2.idparent, FD.idfin),
		upb.idupb,
		upb.idman
	FROM fin 
	JOIN finlink FL1
		ON FL1.idchild = fin.idfin and FL1.nlevel = @level_input
	JOIN finlink FL2
		ON FL2.idchild = fin.idfin AND FL2.nlevel = @codelevel
	JOIN finlink FL3
		ON FL3.idparent = fin.idfin
	join finvardetail FD 
		ON FD.idfin = FL3.idchild
	join finvar FVAR
		ON  FVAR.yvar = FD.yvar
		AND FVAR.nvar = FD.nvar
	JOIN upb 
		on FD.idupb=upb.idupb
	WHERE ((fin.flag&1)=1) --  Spesa	
		AND FVAR.idfinvarstatus = 5
		AND (@idfin IS NULL OR  isnull(FL1.idparent, FD.idfin) = @idfin)	
		AND (upb.idupb like @idupb ) 
		AND ((upb.idman  = @idman) OR (@idman is null and upb.idman is not null))	
		AND fin.ayear = @ayear
		AND NOT EXISTS (SELECT *
			FROM #expense
			WHERE upb.idupb = #expense.idupb 
			AND FL2.idparent = #expense.idfin
			AND upb.idman = #expense.idman)	
--select  'seconda', * from #expense
	INSERT INTO #expense
		(
		idfin,
		idupb,
		idman
		)	--> Prende quelli non movimentati 2^ parte
	SELECT distinct
		ISNULL(FL2.idparent, EY.idfin),
		upb.idupb,
		upb.idman
	FROM fin 
	JOIN finlink FL1
		ON FL1.idchild = fin.idfin and FL1.nlevel = @level_input
	JOIN finlink FL2
		ON FL2.idchild = fin.idfin AND FL2.nlevel = @codelevel
	JOIN finlink FL3
		ON FL3.idparent = fin.idfin
	join expenseyear EY 
		on EY.idfin = FL3.idchild and EY.ayear = fin.ayear
	JOIN upb 
		on EY.idupb=upb.idupb
	WHERE ((fin.flag&1)=1) -- Spesa
		AND (@idfin IS NULL OR isnull(FL1.idparent, EY.idfin) = @idfin)	
		AND (upb.idupb like @idupb ) 
		AND ((upb.idman  = @idman) OR (@idman is null and upb.idman is not null))	
		AND fin.ayear = @ayear
		AND NOT EXISTS (SELECT *
			FROM #expense
			WHERE upb.idupb = #expense.idupb 
			AND FL2.idparent = #expense.idfin
			AND upb.idman = #expense.idman)	
--select  'terza', * from #expense
	INSERT INTO #expense
		(
		idfin,
		idupb,
		idman
		)	--> Prende quelli non movimentati 3^ parte
	SELECT distinct
		isnull(FL2.idparent, FY.idfin),
		upb.idupb,
		upb.idman
	FROM fin 
	JOIN finlink FL1
		ON FL1.idchild = fin.idfin and FL1.nlevel = @level_input
	JOIN finlink FL2
		ON FL2.idchild = fin.idfin AND FL2.nlevel = @codelevel
	JOIN finlink FL3
		ON FL3.idparent = fin.idfin
	JOIN finyear FY 
		on FY.idfin = FL3.idchild   
		and FY.ayear=fin.ayear and
			(isnull(FY.previousprevision,0) <> 0 OR
			 isnull(FY.prevision,0) <> 0 OR
			 isnull(FY.previoussecondaryprev,0) <> 0 OR
			 isnull(FY.secondaryprev,0) <> 0 OR
			 isnull(FY.previousarrears,0) <> 0 OR
			 isnull(FY.currentarrears,0) <> 0					 
			)
	JOIN upb 
		on FY.idupb=upb.idupb
	WHERE ((fin.flag&1)=1) -- Spesa
		AND (@idfin IS NULL OR isnull(FL1.idparent, FY.idfin) = @idfin)	
		AND (upb.idupb like @idupb ) 
		AND ((upb.idman  = @idman) OR (@idman is null and upb.idman is not null))	
		AND fin.ayear = @ayear
		AND NOT EXISTS (SELECT *
			FROM #expense
			WHERE upb.idupb = #expense.idupb 
			AND FL2.idparent = #expense.idfin
			AND upb.idman = #expense.idman)	
	
END
ELSE
BEGIN
	INSERT INTO #expense
		(
		idfin,
		idupb,
		idman
		)	--> Prende quelli non movimentati 
	SELECT 
		fin.idfin,
		upb.idupb,
		upb.idman
	FROM fin CROSS JOIN upb 
	LEFT OUTER JOIN finlink FL1
		ON FL1.idchild = fin.idfin and FL1.nlevel = @level_input
	WHERE ((fin.flag&1)=1) -- Spesa	
		AND (@idfin IS NULL 
		OR  (FL1.idparent = @idfin AND @idfin is NOT NULL))	
		AND (upb.idupb LIKE @idupb ) 
		AND ((upb.idman  = @idman) OR (@idman is null and upb.idman is not null))	
		AND fin.nlevel = @codelevel
		AND fin.ayear = @ayear
		AND NOT EXISTS (SELECT *
			FROM #expense
			WHERE upb.idupb = #expense.idupb 
			AND fin.idfin = #expense.idfin
			AND upb.idman = #expense.idman )
--select  'quinta', * from #expense
END
-- La parte eseguente l'ho commentata perchè dovendo calcolare (non solo le var degli upb con resp.) anche le var. degli upb senza resp movimentati
-- ho sposatto questo calcolo in fondo alla SP come per il calcolo della prev. Alla fine lui calcolerà le var di prev e la prev degli upb 
-- inseriti nel tabellone. Il calcolo sembra anche + veloce.
CREATE TABLE #appropriation_C
    (
	idfin int,
	idupb varchar(36),
	idman int,
	amount decimal(19,2)			 
    )
INSERT INTO #appropriation_C
	(
	idfin,
	idupb,
	idman,
	amount
	)
SELECT
	ISNULL(finlink.idparent,expenseyear.idfin),
	expenseyear.idupb,
	expense.idman,
	SUM(ISNULL(expenseyear.amount, 0))
FROM expense
JOIN expenseyear
	ON expenseyear.idexp = expense.idexp  
	AND expenseyear.ayear = @ayear
JOIN expensetotal 
	ON  expenseyear.idexp = expensetotal.idexp 
	AND expenseyear.ayear = expensetotal.ayear 
LEFT OUTER JOIN finlink 
	ON finlink.idchild = expenseyear.idfin 
	AND finlink.nlevel = @codelevel
LEFT OUTER JOIN finlink FL
	ON FL.idchild = expenseyear.idfin 
	AND FL.nlevel = @level_input
WHERE expense.adate between @mystart and @mystop
	AND (@idfin IS NULL OR isnull(FL.idparent,expenseyear.idfin) = @idfin)	
	AND ((expense.idman  = @idman) OR (@idman is null and expense.idman is not null))	
	AND ((expensetotal.flag&1)=0) --Competenza
	AND expense.nphase = @nfinphase
	AND (expenseyear.idupb like @idupb) 
GROUP BY expenseyear.idupb,ISNULL(finlink.idparent,expenseyear.idfin),expense.idman
--select '#appropriation_C', * from #appropriation_C
CREATE TABLE #var_appropriation_C
    (
	idfin int,
	idupb varchar(36),
	idman int,
	amount decimal(19,2)					 
    )
INSERT INTO #var_appropriation_C
	(
	idfin,
	idupb,
	idman,
	amount
	)
SELECT 
	ISNULL(finlink.idparent,expenseyear.idfin),
	expenseyear.idupb,
	expense.idman,
	SUM(ISNULL(expensevar.amount, 0))
FROM expensevar
JOIN expenseyear
	ON expenseyear.idexp = expensevar.idexp 
	AND expenseyear.ayear = @ayear
JOIN expense 
	ON expense.idexp = expenseyear.idexp
JOIN expensetotal 
	ON  expenseyear.idexp = expensetotal.idexp 
	AND expenseyear.ayear = expensetotal.ayear 
LEFT OUTER JOIN finlink 
	ON finlink.idchild = expenseyear.idfin 
	AND finlink.nlevel = @codelevel
LEFT OUTER JOIN finlink FL
	ON FL.idchild = expenseyear.idfin 
	AND FL.nlevel = @level_input
WHERE expensevar.yvar = @ayear
	AND ((expensetotal.flag&1)=0) --Competenza
	AND expense.nphase = @nfinphase
	AND expensevar.adate between @mystart and @mystop 
	AND (@idfin IS NULL 
	OR  isnull(FL.idparent,expenseyear.idfin) = @idfin)	
	AND (expenseyear.idupb like @idupb) 
	AND ((expense.idman  = @idman) OR (@idman is null and expense.idman is not null))	
GROUP BY expenseyear.idupb,ISNULL(finlink.idparent,expenseyear.idfin),expense.idman
CREATE TABLE #appropriation_R
    (
	idfin int,
	idupb varchar(36), 
	idman int,
	amount decimal(19,2)					 
    )
INSERT INTO #appropriation_R
	(
	idfin,
	idupb,
	idman,
	amount
	)
SELECT
	ISNULL(finlink.idparent,expenseyear.idfin),
	expenseyear.idupb,
	expense.idman,
	SUM(ISNULL(expenseyear.amount, 0))
FROM expenseyear
JOIN expense
	ON expense.idexp = expenseyear.idexp AND expenseyear.ayear = @ayear
JOIN expensetotal 
	ON  expenseyear.idexp = expensetotal.idexp AND
	expenseyear.ayear = expensetotal.ayear 
LEFT OUTER JOIN finlink 
	ON finlink.idchild = expenseyear.idfin 
	AND finlink.nlevel = @codelevel
LEFT OUTER JOIN finlink FL
	ON FL.idchild = expenseyear.idfin 
	AND FL.nlevel = @level_input
WHERE  ((expensetotal.flag&1)=1) --Residuo
	AND expense.nphase = @nfinphase
	AND expense.adate between @mystart and @mystop
	AND (@idfin IS NULL OR isnull(FL.idparent,expenseyear.idfin) = @idfin)
	AND (expenseyear.idupb like @idupb) 
	AND ((expense.idman  = @idman) OR (@idman is null and expense.idman is not null))	
GROUP BY expenseyear.idupb,ISNULL(finlink.idparent,expenseyear.idfin),expense.idman
CREATE TABLE #var_appropriation_R
    (
	idfin int,
	idupb varchar(36),
	idman int,
	amount decimal(19,2)					 
    )
INSERT INTO #var_appropriation_R
	(
	idfin,
	idupb,
	idman,
	amount
	)
SELECT 
	ISNULL(finlink.idparent,expenseyear.idfin),
	expenseyear.idupb,
	expense.idman,
	SUM(ISNULL(expensevar.amount, 0))
FROM expensevar
JOIN expenseyear
	ON expenseyear.idexp = expensevar.idexp	
	AND expenseyear.ayear = @ayear
JOIN expense on expense.idexp = expenseyear.idexp
JOIN expensetotal 
	ON  expenseyear.idexp = expensetotal.idexp AND
	expenseyear.ayear = expensetotal.ayear 
LEFT OUTER JOIN finlink ON finlink.idchild = expenseyear.idfin 
	AND finlink.nlevel = @codelevel
LEFT OUTER JOIN finlink FL
	ON FL.idchild = expenseyear.idfin 
	AND FL.nlevel = @level_input
WHERE expensevar.yvar = @ayear
	AND ((expensetotal.flag&1)=1) --Residuo
	AND expense.nphase = @nfinphase
	AND expensevar.adate between @mystart and @mystop 
	AND (@idfin IS NULL OR isnull(FL.idparent,expenseyear.idfin) = @idfin)	
	AND (expenseyear.idupb like @idupb) 
	AND ((expense.idman  = @idman) OR (@idman is null and expense.idman is not null))	
GROUP BY expenseyear.idupb,ISNULL(finlink.idparent,expenseyear.idfin),expense.idman
CREATE TABLE #payment_C
    (
	idfin int,
	idupb varchar(36),
	idman int,
	amount decimal(19,2)					 
    )
INSERT INTO #payment_C
	(
	idfin,
	idupb,
	idman,
	amount   
	)
SELECT
	ISNULL(finlink.idparent,expenseyear.idfin),
	expenseyear.idupb,
	expense.idman,
	SUM(ISNULL(paymentemitted.amount,0))
FROM expenseyear
JOIN paymentemitted
	ON expenseyear.idexp = paymentemitted.idexp AND expenseyear.ayear = @ayear
JOIN expense on expense.idexp = expenseyear.idexp
JOIN expensetotal 
	ON  expenseyear.idexp = expensetotal.idexp AND
	expenseyear.ayear = expensetotal.ayear 
LEFT OUTER JOIN finlink 
	ON finlink.idchild = expenseyear.idfin 
	AND finlink.nlevel = @codelevel
LEFT OUTER JOIN finlink FL
	ON FL.idchild = expenseyear.idfin 
	AND FL.nlevel = @level_input
WHERE paymentemitted.competencydate between @mystart and @mystop
	AND  ((expensetotal.flag&1)=0) --Competenza
	AND (@idfin IS NULL OR isnull(FL.idparent,expenseyear.idfin) = @idfin)	
	AND (expenseyear.idupb like @idupb) 
	AND ((expense.idman  = @idman) OR (@idman is null and expense.idman is not null))	 
GROUP BY expenseyear.idupb,ISNULL(finlink.idparent,expenseyear.idfin),expense.idman
--select '#payment_C', * from #payment_C
CREATE TABLE #payment_R
    (
	idfin int,
	idupb varchar(36),
	idman int,
	amount decimal(19,2)					 
    )
INSERT INTO #payment_R
	(
	idfin,
	idupb,
	idman,
	amount
	)
SELECT
	ISNULL(finlink.idparent,expenseyear.idfin),
	expenseyear.idupb,
	expense.idman,
	SUM(ISNULL(paymentemitted.amount,0))
FROM paymentemitted
JOIN expenseyear
	ON expenseyear.idexp = paymentemitted.idexp 
	AND expenseyear.ayear = @ayear
JOIN expense 
	ON expense.idexp = expenseyear.idexp
LEFT OUTER JOIN finlink 
	ON finlink.idchild = expenseyear.idfin 
	AND finlink.nlevel = @codelevel
LEFT OUTER JOIN finlink FL
	ON FL.idchild = expenseyear.idfin 
	AND FL.nlevel = @level_input
WHERE paymentemitted.competencydate between @mystart and @mystop
	AND (paymentemitted.flagarrear='R') --Residuo
	AND (@idfin IS NULL OR isnull(FL.idparent,expenseyear.idfin) = @idfin )	
	AND (expenseyear.idupb like @idupb) 
	AND ((expense.idman  = @idman) OR (@idman is null and expense.idman is not null))	
GROUP BY expenseyear.idupb,ISNULL(finlink.idparent,expenseyear.idfin),expense.idman
CREATE TABLE #var_payment_C
    (
	idfin int,
	idupb varchar(36),
	idman int,
	amount decimal(19,2)					 
    )
INSERT INTO #var_payment_C
	(
	idfin,
	idupb,
	idman,
	amount
	)
SELECT 
	ISNULL(finlink.idparent,expenseyear.idfin),
	expenseyear.idupb,
	expense.idman,
	SUM(ISNULL(expensevar.amount, 0))
FROM expensevar
JOIN expenseyear
	ON expenseyear.idexp = expensevar.idexp 
	AND expenseyear.ayear = @ayear
JOIN expense on expense.idexp = expenseyear.idexp
JOIN expensetotal 
	ON  expenseyear.idexp = expensetotal.idexp AND
	expenseyear.ayear = expensetotal.ayear 
LEFT OUTER JOIN finlink 
	ON finlink.idchild = expenseyear.idfin 
	AND finlink.nlevel = @codelevel
LEFT OUTER JOIN finlink FL
	ON FL.idchild = expenseyear.idfin 
	AND FL.nlevel = @level_input
WHERE expensevar.yvar = @ayear
	AND ((expensetotal.flag&1)=0) --Competenza
	AND expensevar.adate between @mystart and @mystop
	AND (@idfin IS NULL OR isnull(FL.idparent,expenseyear.idfin) = @idfin)	
	AND (expenseyear.idupb like @idupb) 
	AND expensevar.idexp IN (select idexp from paymentemitted)
	AND ((expense.idman  = @idman) OR (@idman is null and expense.idman is not null))	
GROUP BY expenseyear.idupb,ISNULL(finlink.idparent,expenseyear.idfin),expense.idman
CREATE TABLE #var_payment_R
    (
	idfin  int,
	idupb  varchar(36),
	idman  int,
	amount decimal(19,2)					 
    )
INSERT INTO #var_payment_R
	(
	idfin,
	idupb,
	idman,
	amount
	)
SELECT 
	ISNULL(finlink.idparent,expenseyear.idfin),
	expenseyear.idupb,
	expense.idman,
	SUM(ISNULL(expensevar.amount, 0))
FROM expensevar
JOIN expenseyear
	ON expenseyear.idexp = expensevar.idexp 
	AND expenseyear.ayear = @ayear
JOIN expense on expense.idexp = expenseyear.idexp
JOIN expensetotal 
	ON  expenseyear.idexp = expensetotal.idexp AND
	expenseyear.ayear = expensetotal.ayear
LEFT OUTER JOIN finlink 
	ON finlink.idchild = expenseyear.idfin 
	AND finlink.nlevel = @codelevel
LEFT OUTER JOIN finlink FL
	ON FL.idchild = expenseyear.idfin 
	AND FL.nlevel = @level_input
WHERE expensevar.yvar = @ayear
	AND ((expensetotal.flag&1)=1) --Residuo
	AND expensevar.adate between @mystart and @mystop
	AND (@idfin IS NULL 
	OR  isnull(FL.idparent,expenseyear.idfin) = @idfin)	
	AND (expenseyear.idupb like @idupb) 
	AND expensevar.idexp IN (select idexp FROM paymentemitted)
	AND ((expense.idman  = @idman) OR (@idman is null and expense.idman is not null))	
GROUP BY expenseyear.idupb,ISNULL(finlink.idparent,expenseyear.idfin),expense.idman

UPDATE #expense
	SET
	codeupb = (select codeupb from upb where upb.idupb = #expense.idupb),
	upb = (select title from upb where upb.idupb = #expense.idupb),
	upbprintingorder = (select printingorder from upb where upb.idupb = #expense.idupb)
IF (@showupb ='S') 
BEGIN
UPDATE #expense
	SET
	finvar_prevision = ISNULL((SELECT SUM(ISNULL(finvardetail.amount,0))
				FROM finvardetail
				JOIN finvar
					ON finvar.yvar = finvardetail.yvar
					AND finvar.nvar = finvardetail.nvar
				LEFT OUTER JOIN finlink 
					ON finlink.idchild = finvardetail.idfin 
					AND finlink.nlevel = @codelevel
				WHERE finvar.flagprevision ='S'	
					AND finvar.idfinvarstatus = 5
					AND finvar.variationkind <> 5
					AND finvar.adate between @mystart and @mystop
					AND finvar.yvar = @ayear
					AND ISNULL(finlink.idparent,finvardetail.idfin) = #expense.idfin 
					AND finvardetail.idupb = #expense.idupb), 0),
	finvar_secondaryprev = ISNULL((SELECT SUM(ISNULL(finvardetail.amount,0))
				FROM finvardetail
				JOIN finvar
					ON finvar.yvar = finvardetail.yvar
					AND finvar.nvar = finvardetail.nvar
				LEFT OUTER JOIN finlink 
					ON finlink.idchild = finvardetail.idfin 
					AND finlink.nlevel = @codelevel
				WHERE finvar.flagsecondaryprev ='S'	
					AND finvar.idfinvarstatus = 5
					AND finvar.variationkind <> 5
					AND finvar.adate between @mystart and @mystop
					AND finvar.yvar = @ayear
					AND ISNULL(finlink.idparent,finvardetail.idfin) = #expense.idfin 
					AND finvardetail.idupb = #expense.idupb), 0),
	
	appropriation_C =ISNULL((SELECT #appropriation_C.amount 
				FROM #appropriation_C
				WHERE #appropriation_C.idupb = #expense.idupb
					and #appropriation_C.idfin = #expense.idfin 
					and #appropriation_C.idman = #expense.idman), 0),
	var_appropriation_C =ISNULL((SELECT #var_appropriation_C.amount 
				FROM #var_appropriation_C
				WHERE #var_appropriation_C.idupb = #expense.idupb
					and #var_appropriation_C.idfin = #expense.idfin 
					and #var_appropriation_C.idman = #expense.idman), 0),
	payment_C =ISNULL((SELECT #payment_C.amount 
				FROM #payment_C
				WHERE #payment_C.idupb = #expense.idupb
					and #payment_C.idfin = #expense.idfin
					and #payment_C.idman = #expense.idman), 0),
	var_payment_C =ISNULL((SELECT #var_payment_C.amount 
				FROM #var_payment_C
				WHERE #var_payment_C.idupb = #expense.idupb
					and  #var_payment_C.idfin = #expense.idfin
					and  #var_payment_C.idman = #expense.idman), 0),
  	appropriation_R =ISNULL((SELECT #appropriation_R.amount 
				FROM #appropriation_R
				WHERE #appropriation_R.idupb = #expense.idupb
					and #appropriation_R.idfin = #expense.idfin
					and #appropriation_R.idman = #expense.idman), 0),
	var_appropriation_R =ISNULL((SELECT #var_appropriation_R.amount 
				FROM #var_appropriation_R
				WHERE #var_appropriation_R.idupb = #expense.idupb
					and #var_appropriation_R.idfin = #expense.idfin
					and #var_appropriation_R.idman = #expense.idman), 0),
	payment_R =ISNULL((SELECT #payment_R.amount 
				FROM #payment_R					
				WHERE #payment_R.idupb = #expense.idupb
					and #payment_R.idfin = #expense.idfin
					and #payment_R.idman = #expense.idman), 0),
	var_payment_R = ISNULL((SELECT #var_payment_R.amount 
			FROM #var_payment_R
			WHERE #var_payment_R.idupb = #expense.idupb
				and #var_payment_R.idfin = #expense.idfin
				and #var_payment_R.idman = #expense.idman), 0)
	
	IF @codelevel >= @levelusable
		BEGIN	
		UPDATE #expense
		SET	initialprevisioncomp= ISNULL((SELECT finyear.prevision 
					FROM finyear
					JOIN fin
						ON finyear.idfin = fin.idfin
					JOIN upb
						ON finyear.idupb = upb.idupb
					WHERE finyear.idupb = #expense.idupb AND 
						finyear.idfin = #expense.idfin),0),
	
			initialprevisioncash = ISNULL((SELECT finyear.secondaryprev 
					FROM finyear
					JOIN fin
						ON finyear.idfin = fin.idfin
					JOIN upb
						ON finyear.idupb = upb.idupb
					WHERE finyear.idupb = #expense.idupb AND 
						finyear.idfin = #expense.idfin),0)
		
		END  
	ELSE 
	BEGIN
		UPDATE #expense
		SET initialprevisioncomp = ISNULL((SELECT SUM(isnull(finyear.prevision,0)) 
					FROM finyear
					JOIN fin
						ON finyear.idfin = fin.idfin
					JOIN upb
						ON finyear.idupb = upb.idupb
					JOIN finlink 
						ON finlink.idchild = finyear.idfin 
					WHERE finyear.idupb = #expense.idupb AND 
						finlink.idparent =  #expense.idfin
						AND fin.nlevel = @levelusable),0) ,
		initialprevisioncash = ISNULL((SELECT SUM(isnull(finyear.secondaryprev,0)) 
					FROM finyear
					JOIN fin
						ON finyear.idfin = fin.idfin
					JOIN upb
						ON finyear.idupb = upb.idupb
					JOIN finlink 
						ON finlink.idchild = finyear.idfin 
					WHERE finyear.idupb = #expense.idupb AND 
						finlink.idparent =  #expense.idfin
						AND fin.nlevel = @levelusable),0)
		
		END 
	
