					WHERE ((expensetotal.flag&1)=1) --Residuo
						AND expense.nphase = @nfinphase
						AND expense.adate between @mystart and @mystop
						AND expenseyear.ayear = @ayear
						AND expenseyear.idupb like @idupb
						AND ISNULL(finlink.idparent,expenseyear.idfin) = #expense.idfin),
		total_var_appropriation_R = ( SELECT SUM(ISNULL(expensevar.amount, 0))
					FROM expensevar
					JOIN expenseyear
						ON expenseyear.idexp = expensevar.idexp 
						AND expenseyear.ayear = @ayear
					JOIN expense
						ON expense.idexp = expensevar.idexp
					JOIN expensetotal 
						ON  expenseyear.idexp = expensetotal.idexp AND
						expenseyear.ayear = expensetotal.ayear
					LEFT OUTER JOIN finlink 
						ON finlink.idchild = expenseyear.idfin AND 
						finlink.nlevel = @codelevel
					WHERE expensevar.yvar = @ayear
						AND ((expensetotal.flag&1)=1) --Reesiduo
						AND expense.nphase = @nfinphase
						AND expensevar.adate between @mystart and @mystop 
						AND expenseyear.idupb like @idupb 
						AND ISNULL(finlink.idparent,expenseyear.idfin) = #expense.idfin),
	
		total_payment_C = (SELECT SUM(ISNULL(paymentemitted.amount,0))
					FROM expenseyear
					JOIN paymentemitted
						ON expenseyear.idexp = paymentemitted.idexp AND expenseyear.ayear = @ayear
					LEFT OUTER JOIN finlink 
						ON finlink.idchild = expenseyear.idfin AND 
						finlink.nlevel = @codelevel
					WHERE paymentemitted.competencydate between @mystart and @mystop
						AND (paymentemitted.flagarrear= 'C') --Comptenza
						AND expenseyear.idupb like @idupb
						AND ISNULL(finlink.idparent,expenseyear.idfin) = #expense.idfin),
		total_var_payment_C = (SELECT SUM(ISNULL(expensevar.amount, 0))
					FROM expensevar
					JOIN expense
						ON expense.idexp = expensevar.idexp
					JOIN expenseyear
						ON expenseyear.idexp = expensevar.idexp 
						AND expenseyear.ayear = @ayear
					JOIN expensetotal 
						ON  expenseyear.idexp = expensetotal.idexp AND
						expenseyear.ayear = expensetotal.ayear
					LEFT OUTER JOIN finlink 
						ON finlink.idchild = expenseyear.idfin AND 
						finlink.nlevel = @codelevel
					WHERE expensevar.yvar = @ayear
						AND ((expensetotal.flag&1)=0) --Comptenza
						AND expense.nphase = @maxexpensephase
						AND expensevar.adate between @mystart and @mystop
						AND expensevar.idexp IN (select idexp from paymentemitted)
						and expenseyear.idupb like @idupb
						and ISNULL(finlink.idparent,expenseyear.idfin)= #expense.idfin),
		total_payment_R = (SELECT SUM(ISNULL(paymentemitted.amount,0))
					FROM paymentemitted
					JOIN expenseyear
						ON expenseyear.idexp = paymentemitted.idexp AND expenseyear.ayear = @ayear
					LEFT OUTER JOIN finlink 
						ON finlink.idchild = expenseyear.idfin AND 
						finlink.nlevel = @codelevel
					WHERE paymentemitted.competencydate between @mystart and @mystop
						AND (paymentemitted.flagarrear='R') --Residuo
						AND paymentemitted.nphase = @maxexpensephase
						and expenseyear.idupb like @idupb
						and ISNULL(finlink.idparent,expenseyear.idfin) = #expense.idfin),
		total_var_payment_R = ( SELECT SUM(ISNULL(expensevar.amount, 0))
					FROM expensevar
					JOIN expenseyear
						ON expenseyear.idexp = expensevar.idexp 
						AND expenseyear.ayear = @ayear
					JOIN expense
						ON expense.idexp = expensevar.idexp
					JOIN expensetotal 
						ON  expenseyear.idexp = expensetotal.idexp AND
						expenseyear.ayear = expensetotal.ayear
					LEFT OUTER JOIN finlink 
						ON finlink.idchild = expenseyear.idfin AND 
						finlink.nlevel = @codelevel
					WHERE expensevar.yvar = @ayear
						AND ((expensetotal.flag&1)=1) --Residuo
						AND expense.nphase = @maxexpensephase
						AND expensevar.adate between @mystart and @mystop
						AND expensevar.idexp IN (select idexp from paymentemitted)
						AND expenseyear.idupb like @idupb
						AND ISNULL(finlink.idparent,expenseyear.idfin) = #expense.idfin)
					
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--select * from #expense
END
-- cancello le righe dei figli di @idupboriginal aventi idappropriation = NULL
-- Se ho scelto l'upb ne cancello i figli perchè li ho totalizzati tramite la nuova UPDATE
/*IF (@showupb <>'S') and (@idupboriginal <> '%' ) AND (@showchildupb = 'S')
		DELETE FROM #expense WHERE idappropriation is null 
						AND substring(idupb,1,len(@idupboriginal))= @idupboriginal 	
						AND idupb <>@idupboriginal
*/						
-- cancello solo le righe che sono upb-figli aventi idappropriation = NULL
-- Se non ho scelto alcun upb cancello solo gli upb padri con lo stesso resp. del figlio perchè li ho totalizzati tramite la nuova UPDATE
   
/*IF (@showupb <>'S') 
		DELETE FROM #expense WHERE idappropriation IS NULL 
			AND EXISTS (SELECT * FROM #expense R 
					join upb U 
					on U.idupb=R.idupb  
					WHERE U.paridupb = #expense.idupb 
					and U.idman=#expense.idman )
*/					
-- se questa condizione è soffisfatta è significa che avrò (x es.) due roghe, di cui una ha l0info dell'impegno
-- l'altra ma entrambe avranno i medesimi importi per le prev. e gli importi dei mov. in quanto li ho totalizzate sopra
-- Se non procedo con questa cancellazione nell'istruzione succezziva sui esegue l'update sull'idupb
-- poi farà il raggruppamento finale raddoppiando (erroneamente) gli importi.
IF (@showupb <>'S') 
		DELETE FROM #expense WHERE idappropriation IS NULL 
			AND EXISTS (SELECT * FROM #expense S 
					WHERE S.idfin = #expense.idfin 
					and S.idman = #expense.idman 
					and S.idupb <>	#expense.idupb)
----------------------------------------------------------------------------------------------------------------------------------
	IF (@showupb <>'S') AND (@idupboriginal <> '%' ) AND (@showchildupb = 'S')
			UPDATE #expense SET  
				upbprintingorder = (SELECT TOP 1 printingorder
					FROM upb--#expense -- perchè nel tabellone posso non avere il padre quindi non avrò le info che mi servono
					WHERE idupb = @idupboriginal),
				upb = (SELECT TOP 1 title
					FROM upb
					WHERE idupb = @idupboriginal),
				idupb = @idupboriginal,
				codeupb =(SELECT TOP 1 codeupb
					FROM upb	
					WHERE idupb = @idupboriginal)
	
	IF (@showupb <>'S') and (@idupboriginal = '%')
				UPDATE #expense SET  
				upbprintingorder = null	,
				upb =  null,
				idupb = null,
				codeupb = null
	
---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--  ****************************************************************************************************************** --
---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

CREATE TABLE #expenseprec
(
	idupb varchar(36),
	prevision decimal(19,2),
	finvar_prevision decimal(19,2),
	appropriation decimal(19,2),
	var_appropriation decimal(19,2)
)
-- questi calcoli li fa solo se vuoi vedere l'upb,perchè sono info relative ad essso
-- IF parametto mostra info = S  and mostra upb = S
DECLARE @secprevisionkind    char(1) 
SELECT  @secprevisionkind  = 
	 CASE 
		WHEN fin_kind = 3 THEN 'S'
		ELSE NULL
	END
FROM config 
WHERE config.ayear = @ayear
DECLARE @param char
SELECT  @param = isnull(paramvalue,'N') FROM reportadditionalparam 
WHERE paramname = 'MostraInfoAnniPrecedenti'
AND (
	(@secprevisionkind is not null AND reportname='partitario_spese_intestazione_respons')
	OR
	 (@secprevisionkind is null and reportname= 'partitario_spese_intestazione_respons_singprev')
	)
IF (@param='S' and @showupb ='S')
BEGIN
	insert into #expenseprec
	(
	idupb,
	prevision 
	)
	SELECT 
		FY.idupb,
		ISNULL(SUM(FY.prevision),0)
	FROM finyearview FY 
	WHERE  FY.finpart = 'S'
		AND FY.ayear = @ayear
		AND FY.nlevel = (SELECT MIN(nlevel) FROM finlevel 
				WHERE FY.ayear = @ayear   AND (flag&2)<>0)
	AND FY.idupb in (select distinct idupb from #expense)
	GROUP BY FY.idupb
	UPDATE #expenseprec
	SET finvar_prevision = (SELECT ISNULL(SUM(d.amount),0)
				FROM finvar v
				JOIN finvardetail d
					ON v.yvar = d.yvar
					AND v.nvar = d.nvar
				JOIN fin f
					ON f.idfin = d.idfin 
				WHERE d.idupb = #expenseprec.idupb
					AND v.idfinvarstatus = 5
					AND ((f.flag & 1) = 1 )
					AND v.yvar = @ayear
					AND v.adate <= @mystop
					AND v.variationkind <> 5
					AND v.flagprevision = 'S'),
	
	appropriation = (SELECT ISNULL(SUM(expenseyear.amount),0)
				FROM expense
				JOIN expenseyear
					ON expense.idexp = expenseyear.idexp
					AND expense.ymov = expenseyear.ayear
				WHERE expense.ymov < @ayear
					AND expenseyear.idupb = #expenseprec.idupb
					AND expense.nphase = @nfinphase ),
	var_appropriation = (SELECT ISNULL(SUM(expensevar.amount),0)
				FROM expense
				JOIN expensevar
					ON expense.idexp = expensevar.idexp
				JOIN expenseyear
					ON expense.idexp = expenseyear.idexp
					AND expense.ymov = expenseyear.ayear
				WHERE expense.ymov < @ayear
					AND expensevar.yvar <= @ayear
					AND expenseyear.ayear < @ayear
					AND expensevar.adate <= @mystop
					AND expenseyear.idupb = #expenseprec.idupb
					AND expense.nphase = @nfinphase)
	
END
--previsione iniziale : SET @expenseprevision = @expenseprevision + @prev_arrears
--Variazioni: @expensevar
--Tot Previsione  ISNULL(@expenseprevision, 0) + ISNULL(@expensevar, 0)
---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--  ****************************************************************************************************************** --
---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
if (@suppressifblank = 'S') and @codelevel>2	--> se la stampa è x un livello sottostante la categoria cancella le righe
	BEGIN
		DELETE 
		FROM  #expense   
		WHERE  
		(ISNULL(initialprevisioncomp,0)= 0 AND 
		ISNULL(initialprevisioncash,0)= 0 AND 
		ISNULL(finvar_prevision,0)= 0 AND
		ISNULL(finvar_secondaryprev,0)= 0 AND
		ISNULL(appropriation_C,0) = 0 AND
		ISNULL(var_appropriation_C,0)= 0 AND
		ISNULL(payment_C,0)= 0 and
		ISNULL(var_payment_C,0)= 0 AND
		ISNULL(appropriation_R,0)= 0 AND
		ISNULL(var_appropriation_R,0)= 0 AND
		ISNULL(payment_R,0)= 0 AND
		ISNULL(var_payment_R,0)= 0 AND
		ISNULL(appropriation_amount,0)=0 AND
		ISNULL(payment_amount,0)=0 
		AND (select nlevel from fin FFF where FFF.idfin= #expense.idfin)>=2
		)
	END
UPDATE #expense
	SET 	emissiondate = paymentview.adate,
		printeddate = 	paymentview.printdate,
		transmitteddate = paymentview.transmissiondate,	
		transactiondate = paymentperformed.competencydate,
		annulmentdate = paymentview.annulmentdate
FROM paymentview
LEFT OUTER JOIN banktransaction
	ON banktransaction.kpay=paymentview.kpay	
	AND (banktransaction.kind='D' OR banktransaction.kind IS NULL)
LEFT OUTER JOIN paymentperformed 
	ON paymentperformed.npay=paymentview.npay
	AND paymentperformed.ypay=paymentview.ypay
WHERE #expense.npay = paymentview.npay
	AND paymentview.ypay=@ayear
IF (@showupb <>'S')
BEGIN
	SELECT 
		#expense.idfin,
		F.codefin,
		F.title as fintitle,
		F.printingorder as finprintingorder,
		codeupb,
		idupb,
		upb,
		upbprintingorder,
		nphase,
		rowkind,
		sum(isnull(initialprevisioncomp,0)) as initialprevisioncomp,
		sum(isnull(initialprevisioncash,0)) as  initialprevisioncash , 
		sum(isnull(finvar_prevision,0)) as  finvar_prevision ,
		sum(isnull(finvar_secondaryprev,0)) as  finvar_secondaryprev ,	
		sum(isnull(appropriation_C,0)) as  appropriation_C ,
		sum(isnull(var_appropriation_C,0)) as  var_appropriation_C ,
		sum(isnull(payment_C,0)) as  payment_C ,
		sum(isnull(var_payment_C,0))as  var_payment_C ,
		sum(isnull(appropriation_R,0)) as  appropriation_R ,
		sum(isnull(var_appropriation_R,0)) as  var_appropriation_R ,
		sum(isnull(payment_R,0)) as  payment_R ,
		sum(isnull(var_payment_R,0)) as  var_payment_R ,
		adate,
		description,
		REG.title as registry,
		nappropriation,
		ymovappropriation,
		nmovappropriation,	
		sum(isnull(appropriation_amount,0)) as appropriation_amount,
		sum(isnull(available,0)) as available,
		npayment,
		ymovpayment,
		nmovpayment,
		sum(isnull(payment_amount,0)) as  payment_amount,
		npay,
		flagarrear,
		reportdate,
		#expense.ayear,
		idappropriation,
		MAN.title as manager,
		#expense.idman,
		sum(isnull(total_appropriation_C,0)) as total_appropriation_C,
		sum(isnull(total_var_appropriation_C,0)) as total_var_appropriation_C,
		sum(isnull(total_appropriation_R,0)) as  total_appropriation_R,
		sum(isnull(total_var_appropriation_R,0))as total_var_appropriation_R,
		sum(isnull(total_payment_C,0)) as total_payment_C,
		sum(isnull(total_var_payment_C,0)) as total_var_payment_C,
		sum(isnull(total_payment_R,0)) as  total_payment_R,
		sum(isnull(total_var_payment_R,0))as total_var_payment_R  ,
		0 as  prevision_prec,
		0 as  appropriation_prec,
		emissiondate,printeddate,transmitteddate,transactiondate,annulmentdate
	FROM #expense
	JOIN fin F
		ON #expense.idfin = F.idfin
	JOIN manager MAN  
		ON #expense.idman = MAN.idman
	LEFT OUTER JOIN registry REG
		On #expense.idreg = REG.idreg
	GROUP BY  #expense.idman,MAN.title,		
		#expense.idfin,F.codefin,F.title,
		F.printingorder,codeupb,idupb,upb,upbprintingorder,nphase,
		rowkind,adate,description,REG.title,nappropriation,npayment,
		npay,flagarrear,reportdate,#expense.ayear,idappropriation,
		ymovappropriation,nmovappropriation,ymovpayment,nmovpayment,
		emissiondate,printeddate,transmitteddate,transactiondate,annulmentdate	
	ORDER BY manager,upbprintingorder,F.printingorder, rowkind, adate
END
ELSE
BEGIN
	SELECT
		#expense.idfin,
		F.codefin,
		F.title as fintitle,
		F.printingorder as finprintingorder,
		codeupb,
		#expense.idupb,
		upb,
		upbprintingorder,
		nphase,
		rowkind,
		initialprevisioncomp,
		initialprevisioncash , 
		#expense.finvar_prevision,
		finvar_secondaryprev,	
		appropriation_C,
		var_appropriation_C,
		payment_C,
		var_payment_C,
		appropriation_R,
		var_appropriation_R,
		payment_R,
		var_payment_R,
		adate,
		description,
		REG.title as registry,
		nappropriation,
		ymovappropriation,
		nmovappropriation,
		appropriation_amount ,
		available,
		npayment,
		ymovpayment,
		nmovpayment,
		payment_amount, 
		npay,
		flagarrear,
		reportdate,
		#expense.ayear,
		idappropriation,
		MAN.title as manager,
		#expense.idman,
		total_appropriation_C ,	
		total_var_appropriation_C,
		total_appropriation_R,
		total_var_appropriation_R,
		total_payment_C,
		total_var_payment_C,
		total_payment_R,
		total_var_payment_R  ,
		isnull(prec.prevision,0) + isnull(prec.finvar_prevision,0) 
		+ isnull(prec.appropriation,0)+isnull(prec.var_appropriation,0) as  prevision_prec,
		isnull(prec.appropriation,0)+isnull(prec.var_appropriation,0) as  appropriation_prec,
		emissiondate,printeddate,transmitteddate,transactiondate,annulmentdate
	FROM #expense
	JOIN fin F
		ON #expense.idfin = F.idfin
	JOIN manager MAN  
		ON #expense.idman = MAN.idman
	LEFT OUTER JOIN registry REG
		ON #expense.idreg = REG.idreg
	LEFT OUTER JOIN #expenseprec prec
		ON #expense.idupb = prec.idupb
	ORDER BY MAN.title,upbprintingorder,F.printingorder, rowkind, adate
END
END

GO

print '[rpt_partitario_spese_intestazione_respons] OK'

GO
if object_id('[rpt_sitbilancio_spesa_4fasi]') is not null
	drop PROCEDURE [rpt_sitbilancio_spesa_4fasi]
go

-- exec rpt_sitbilancio_spesa_4fasi 2007, {ts '2008-07-13 00:00:00'}, 3, 'N', '000100010013', 'S', 'N', 'S',null
CREATE    PROCEDURE [rpt_sitbilancio_spesa_4fasi]
	@ayear			int,
	@date			datetime,
	@nlevel			tinyint,
	@hierarchy		char(1),
	@idupb			varchar(36),
	@showupb 		char(1),
	@showchildupb 		char(1), 
	@suppressifblank 	char(1),
	@idfin			int  --prima era @codefin
AS
BEGIN
CREATE TABLE #situation_fin
(
	idupb 			varchar(36),
	codeupb			varchar(50),
	upb   			varchar(150),
	upbprintingorder	varchar(50),
	assured			char(1),
	idfin			int,
	codefin			varchar(50),
	title			varchar(150),
	finprintingorder	varchar(50),
	nlevel			tinyint,
	main_initial_prevision	decimal(19,2),
	var_main_prevision	decimal(19,2),
	sec_initial_prevision	decimal(19,2),
	varprevsec		decimal(19,2),
	fin_ph_comp		decimal(19,2),
	var_fin_ph_comp		decimal(19,2), 
	fin_ph_resid		decimal(19,2), 
	var_fin_ph_resid	decimal(19,2),
	desc_fin_ph 		varchar(50),					
	second_ph_comp	decimal(19,2),
	var_second_ph_comp	decimal(19,2),
	second_ph_resid	decimal(19,2),
	var_second_ph_resid	decimal(19,2),
	desc_second_ph 	varchar(50),					
	third_ph_comp	decimal(19,2),
	var_third_ph_comp	decimal(19,2),
	third_ph_resid	decimal(19,2),
	var_third_ph_resid	decimal(19,2),
	desc_third_ph 	varchar(50),		
	max_ph_comp         	decimal(19,2),
	var_max_ph_comp       	decimal(19,2),
	max_ph_resid         	decimal(19,2),
	var_max_ph_resid      	decimal(19,2),
	desc_max_ph 		varchar(50),					
	assign_credit 		decimal(19,2),
	var_assign_credit	decimal(19,2),
	assign_cash		decimal(19,2), 
	var_assign_cash		decimal(19,2),
	previsionkind 		char(1),
	secprevisionkind 	char(1),
	flag_assign_credit 	char(1),
	flag_assign_cash 	char(1),
	flagconsider 		char(1)		
)
IF @ayear IS NULL 
BEGIN
	SELECT * FROM  #situation_fin 
	RETURN
END
DECLARE @idupboriginal 		varchar(36)
SET 	@idupboriginal= @idupb
IF 	(@showchildupb = 'S') set @idupb=@idupb+'%' 
DECLARE @levelusable tinyint
SELECT  @levelusable = MIN(nlevel) 
FROM 	finlevel
WHERE 	ayear =@ayear and (flag&2)<>0
-- L'ipotesi di questa stampa a 4 fasi è che 
-- ( @residualphase < @secondphase) AND (@secondphase<@thirdphase)AND (@thirdphase<@maxphase)
-- 
-- dove fase 1 = @nfinphase, fase 4 = maxphase, fase 2 = @nfinphase+1,  fase 3 = @maxexpensephase-1
DECLARE @nfinphase  tinyint
SELECT 	@nfinphase = expensefinphase FROM uniconfig
DECLARE @nmaxphase tinyint
SELECT  @nmaxphase = MAX(nphase) FROM expensephase
DECLARE @nsecondphase tinyint
SELECT  @nsecondphase = nphase FROM expensephase  WHERE nphase = @nfinphase + 1
DECLARE @nthirdphase INT
SELECT  @nthirdphase = nphase FROM expensephase  WHERE nphase = @nmaxphase - 1 

DECLARE @finphase varchar(50)
SELECT  @finphase=description FROM expensephase WHERE nphase=@nfinphase 
DECLARE @secondphase varchar(50)
SELECT  @secondphase=description FROM  expensephase WHERE nphase=@nsecondphase 
DECLARE @thirdphase varchar(50)
SELECT @thirdphase = description from  expensephase where nphase = @nthirdphase
DECLARE @max_phase varchar(50)
SELECT  @max_phase=description  FROM expensephase WHERE nphase=@nmaxphase 

DECLARE @previsionkind char(1) 
SELECT  @previsionkind =  
	 CASE 
		WHEN fin_kind IN (1,3) THEN 'C'
		WHEN fin_kind = 2 THEN 'S'
	 END
FROM  config 
WHERE config.ayear = @ayear
DECLARE @secprevisionkind    char(1) 
SELECT  @secprevisionkind  = 
	 CASE 
		WHEN fin_kind = 3 THEN 'S'
		ELSE 'N'
	END
FROM config 
WHERE config.ayear = @ayear
DECLARE @flag_cs     		char(1)
SELECT 	@flag_cs =  CASE 
		WHEN fin_kind IN (1,3) THEN 'C'
		WHEN fin_kind = 2 THEN 'S'
	 END
FROM 	config
WHERE 	ayear = @ayear
DECLARE @cashvaliditykind	int
SELECT 	@cashvaliditykind = cashvaliditykind
FROM 	config
WHERE 	ayear = @ayear
DECLARE @level_input tinyint
SET  @level_input = ISNULL((SELECT nlevel from fin where idfin = @idfin) ,@nlevel)
-- ho scelto come livello 2 e poi ho specificato il capitolo, lui corregge @nlevel dandogli 3
IF (@nlevel < @level_input) AND (@idfin is not null)
	BEGIN
	SET  @nlevel = @level_input
	END
IF (@hierarchy='N')
BEGIN
	IF (@suppressifblank = 'S')
	BEGIN
		INSERT INTO #situation_fin
			(idfin, 
			idupb,
			assured,
			var_main_prevision,
			varprevsec,  
			flagconsider
			)
		SELECT 
			F.idfin, 
			U.idupb,
			ISNULL(U.assured,'N'),
			SUM(CASE WHEN finvar.flagprevision = 'S' then isnull(finvardetail.amount,0) ELSE 0 END),
			SUM(CASE WHEN finvar.flagsecondaryprev = 'S' then isnull(finvardetail.amount,0) ELSE 0 END),
			'S'
		FROM upbtotal
		JOIN upb U
			ON upbtotal.idupb = U.idupb
		JOIN fin F
			ON upbtotal.idfin = F.idfin
		JOIN finlink FLK1
			ON FLK1.idchild = F.idfin AND FLK1.nlevel = @level_input
		LEFT OUTER JOIN finlink FLK2
			ON FLK2.idparent = F.idfin AND FLK2.nlevel = @nlevel
		LEFT OUTER JOIN finvardetail
			ON finvardetail.idfin = FLK2.idchild 
			AND finvardetail.idupb=U.idupb 	
		LEFT OUTER JOIN finvar
			ON finvar.yvar = finvardetail.yvar  AND finvar.yvar = @ayear	
		  	AND finvar.nvar = finvardetail.nvar AND finvar.adate <= @date
			AND finvar.idfinvarstatus = 5 AND finvar.variationkind <> 5
		WHERE  	((F.flag & 1 ) = 1) AND F.ayear =@ayear	
			AND (@idfin IS NULL OR  FLK1.idparent = @idfin)
			AND (U.idupb LIKE @idupb and U.active = 'S')
			AND (F.nlevel = @nlevel)
		GROUP BY U.idupb, F.idfin, ISNULL(U.assured,'N')
	--- Inserisco le coppie che hanno solo i RESIDUI
		INSERT INTO #situation_fin
			(	
			idfin, 
			idupb,
			assured,
			var_main_prevision,
			varprevsec,
			flagconsider
			)
		SELECT DISTINCT
			F.idfin,	
			U.idupb,
			ISNULL(U.assured,'N'),
			0,
			0,
			'S'
		FROM expenseyear
		JOIN upb U
			ON  expenseyear.idupb = U.idupb 
		JOIN fin F
			ON  expenseyear.idfin = F.idfin 
		JOIN expensetotal 
			ON expensetotal.idexp = expenseyear.idexp
			AND expensetotal.ayear = expenseyear.ayear
		JOIN finlink
			ON finlink.idparent = F.idfin AND finlink.nlevel = @level_input
		WHERE  ((F.flag & 1 ) = 1) AND F.ayear =@ayear	
			AND (@idfin IS NULL OR  finlink.idparent = @idfin)
			AND (U.idupb LIKE @idupb  and U.active = 'S')
			AND (F.nlevel = @nlevel)
			AND NOT EXISTS (SELECT *
					  FROM #situation_fin
					  LEFT OUTER JOIN finlink FLK1 
					    ON FLK1.idchild = expenseyear.idfin 
					 WHERE expenseyear.idupb = #situation_fin.idupb 
					   AND ISNULL(FLK1.idparent,F.idfin)=  #situation_fin.idfin)
			AND expenseyear.ayear=@ayear
			AND ((expensetotal.flag & 1) = 1) --Residuo
		--GROUP BY U.idupb, ISNULL(finlink.idparent,F.idfin) 
	END
	ELSE
	BEGIN
		INSERT INTO #situation_fin
			(idfin, 
			idupb,
			assured,
			var_main_prevision,
			varprevsec,  
			flagconsider
			)
		SELECT 
			F.idfin, 
			U.idupb,
			ISNULL(U.assured,'N'),
			SUM(CASE WHEN finvar.flagprevision = 'S' then isnull(finvardetail.amount,0) ELSE 0 END),
			SUM(CASE WHEN finvar.flagsecondaryprev = 'S' then isnull(finvardetail.amount,0) ELSE 0 END),
			'S'
		FROM upb U
		CROSS JOIN fin F
		JOIN finlink FLK
			ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
		LEFT OUTER JOIN finlink FLK2
			ON FLK2.idparent = F.idfin 
		LEFT OUTER JOIN finvardetail
			ON finvardetail.idfin = FLK2.idchild
			AND finvardetail.idupb=U.idupb 	
		LEFT OUTER JOIN finvar
			ON finvar.yvar = finvardetail.yvar  AND finvar.yvar = @ayear	
		  	AND finvar.nvar = finvardetail.nvar AND finvar.adate <= @date
			AND finvar.idfinvarstatus = 5 AND finvar.variationkind <> 5
		WHERE  	((F.flag & 1 ) = 1) AND F.ayear =@ayear	
			AND (@idfin IS NULL 
		        OR  FLK.idparent = @idfin)
			AND (U.idupb LIKE @idupb and U.active = 'S')
			AND (F.nlevel = @nlevel)
		GROUP BY U.idupb, F.idfin,ISNULL(U.assured,'N')
	END
END 
ELSE -- @hierarchy ='S'
BEGIN 
	IF (@suppressifblank = 'S')
	BEGIN
		INSERT INTO #situation_fin
	      		(
				idfin, 
				idupb,
				assured,
				var_main_prevision,
				varprevsec,
				flagconsider
			)
			SELECT 
				F.idfin,
				U.idupb,
				ISNULL(U.assured,'N'),
				SUM(CASE WHEN finvar.flagprevision = 'S' THEN isnull(finvardetail.amount,0) ELSE 0 END),
				SUM(CASE WHEN finvar.flagsecondaryprev = 'S' THEN isnull(finvardetail.amount,0) ELSE 0 END),
				CASE 
					WHEN (F.nlevel >= @levelusable and 
					F.idfin IN (SELECT idfin FROM finlast))
					THEN 'S'
					ELSE 'N'
				END
			FROM upbtotal
			JOIN upb U
				ON upbtotal.idupb = U.idupb
			JOIN fin F
				ON upbtotal.idfin = F.idfin
			JOIN finlink FLK
				ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
			LEFT OUTER JOIN finlink FLK2
				ON FLK2.idparent = F.idfin 
			LEFT OUTER JOIN finvardetail
		  		ON ISNULL(FLK2.idchild,F.idfin) = finvardetail.idfin
				AND finvardetail.idupb = U.idupb 
			LEFT OUTER JOIN finvar
			  	ON finvar.yvar = finvardetail.yvar  and finvar.yvar = @ayear	
		  	  	AND finvar.nvar = finvardetail.nvar and finvar.adate <= @date
				AND finvar.idfinvarstatus = 5 AND finvar.variationkind <> 5
			WHERE  ((F.flag & 1 ) = 1) AND F.ayear = @ayear
				AND (@idfin IS NULL OR FLK.idparent = @idfin)
				AND (U.idupb like @idupb and U.active = 'S')
				AND (F.nlevel >=  @nlevel)
				
			GROUP BY U.idupb,F.idfin,F.nlevel,F.ayear,F.flag,ISNULL(U.assured,'N')
		-- Inserisco le coppie che hanno solo i RESIDUI
		INSERT INTO #situation_fin
			(idfin, 
			idupb,
			assured,
			var_main_prevision,
			varprevsec,
			flagconsider
			)
		SELECT DISTINCT
			F.idfin,
			U.idupb,
			ISNULL(U.assured,'N'),
			0,
			0,
			CASE 
				WHEN (F.nlevel >= @levelusable and 
				F.idfin IN (SELECT idfin FROM finlast))
				THEN 'S'
				ELSE 'N'
			END
		FROM expenseyear
		JOIN upb U
			ON  expenseyear.idupb = U.idupb 
		JOIN fin F
			ON  expenseyear.idfin = F.idfin 
		JOIN expensetotal 
			ON expensetotal.idexp = expenseyear.idexp
			AND expensetotal.ayear = expenseyear.ayear
		JOIN finlink 
			ON finlink.idchild = F.idfin AND finlink.nlevel = @level_input 
		WHERE  (F.flag & 1 ) = 1 and F.ayear = @ayear
			AND (@idfin IS NULL OR finlink.idparent = @idfin)
			AND (U.idupb like @idupb and U.active = 'S')
			AND (F.nlevel >=  @nlevel)
			AND NOT EXISTS (SELECT *
					  FROM #situation_fin
					  LEFT OUTER JOIN finlink FLK1 ON FLK1.idchild = expenseyear.idfin
					 WHERE expenseyear.idupb = #situation_fin.idupb 
					   AND ISNULL(FLK1.idparent,F.idfin) =  #situation_fin.idfin)			
			AND expenseyear.ayear = @ayear
			AND (F.nlevel >=  @nlevel)
			AND ((expensetotal.flag & 1) = 1)
		--GROUP BY U.idupb,F.idfin,F.nlevel,F.ayear,(F.flag & 1) 
	END
	ELSE
	BEGIN
		INSERT INTO #situation_fin
      		(
			idfin, 
			idupb,
			assured,
			var_main_prevision,
			varprevsec,
			flagconsider
		)
		SELECT 
			F.idfin,
			U.idupb,
			ISNULL(U.assured,'N'),
			SUM(CASE WHEN finvar.flagprevision = 'S' THEN isnull(finvardetail.amount,0) ELSE 0 END),
			SUM(CASE WHEN finvar.flagsecondaryprev = 'S' THEN isnull(finvardetail.amount,0) ELSE 0 END),
			CASE 
				 WHEN (F.nlevel >= @levelusable and 
				 F.idfin IN (SELECT idfin FROM finlast))
				 THEN 'S'
				 ELSE 'N'
			END
		FROM fin F cross join upb U
		LEFT OUTER JOIN finlink FLK2
			ON FLK2.idparent = F.idfin 
		LEFT OUTER JOIN finvardetail
		  	ON ISNULL(FLK2.idchild,F.idfin) = finvardetail.idfin
			AND finvardetail.idupb = U.idupb 
		LEFT OUTER JOIN finvar
		  	ON finvar.yvar = finvardetail.yvar  and finvar.yvar = @ayear	
	  	  	AND finvar.nvar = finvardetail.nvar and finvar.adate <= @date
			AND finvar.idfinvarstatus = 5 AND finvar.variationkind <> 5
		JOIN finlink FLK
			ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
			AND (@idfin IS NULL OR FLK.idparent = @idfin)
		WHERE  ((F.flag & 1) = 1) and F.ayear = @ayear
			AND (@idfin IS NULL OR  FLK.idparent = @idfin)
			AND (U.idupb LIKE @idupb and U.active = 'S')
			AND (F.nlevel >=  @nlevel)
		GROUP BY U.idupb,F.idfin,F.nlevel,F.ayear,F.flag, ISNULL(U.assured,'N')
	END
END
UPDATE #situation_fin 
	SET main_initial_prevision = 
		ISNULL((
		SELECT SUM(finyear.prevision)
		from finyear 
		JOIN fin 
			ON finyear.idfin = fin.idfin  				
		JOIN upb
			ON finyear.idupb = upb.idupb 
		JOIN finlevel 
			ON finlevel.ayear = fin.ayear
			AND finlevel.nlevel = fin.nlevel
			AND (finlevel.flag&2)<>0
		JOIN finlast 
			ON finlast.idfin = fin.idfin
		JOIN finlink
			ON finlink.idchild = fin.idfin
		WHERE finlink.idparent 	  = #situation_fin.idfin
			AND finyear.idupb =  #situation_fin.idupb 
			AND fin.ayear = @ayear
			AND finyear.ayear = @ayear), 0.0)
UPDATE #situation_fin 
	SET sec_initial_prevision= 
		ISNULL((
		SELECT SUM(finyear.secondaryprev)
		FROM finyear 
		JOIN fin 
			ON finyear.idfin = fin.idfin 
		JOIN upb
			ON finyear.idupb = upb.idupb  
		JOIN finlevel 
			ON finlevel.ayear = fin.ayear
			AND finlevel.nlevel = fin.nlevel
			AND (finlevel.flag&2)<>0
		JOIN finlast 
			ON finlast.idfin = fin.idfin
		JOIN finlink
			ON finlink.idchild = fin.idfin
		WHERE finlink.idparent = #situation_fin.idfin
			AND finyear.idupb =  #situation_fin.idupb 
			AND finyear.ayear = @ayear
			), 0.0)
UPDATE #situation_fin 
	SET fin_ph_comp =                                                
		ISNULL((
		SELECT SUM(expenseyear.amount)
		FROM expense
		JOIN expenseyear
			ON expenseyear.idexp = expense.idexp
			AND expenseyear.ayear = @ayear
		JOIN expensetotal 
			ON expensetotal.idexp = expenseyear.idexp
			AND expensetotal.ayear = expenseyear.ayear
		JOIN finlink
			ON finlink.idchild = expenseyear.idfin
		WHERE finlink.idparent = #situation_fin.idfin 
			AND ((expensetotal.flag&1)=0) -- Competenza
			AND expenseyear.idupb = #situation_fin.idupb
			AND expense.adate <= @date 
			AND expense.nphase = @nfinphase), 0.0),
	 var_fin_ph_comp=					
		ISNULL((
		SELECT SUM(expensevar.amount)
		FROM expensevar
		JOIN expense
			ON expensevar.idexp = expense.idexp
