			AND expensetotal.ayear = expenseyear.ayear
		JOIN finlink
			ON finlink.idchild = expenseyear.idfin
		WHERE expensevar.adate <= @date 
			AND expense.nphase= @nthirdphase
			AND ((expensetotal.flag&1)=0) -- Competenza
			AND finlink.idparent  = #situation_fin.idfin 
			AND expenseyear.idupb = #situation_fin.idupb
			AND expensevar.yvar = @ayear), 0.0),
	third_ph_resid = 
		ISNULL((
		SELECT SUM(expenseyear.amount)
		FROM expense
		JOIN expenseyear
			ON expenseyear.idexp = expense.idexp
			AND expenseyear.ayear = @ayear
		JOIN expensetotal 
			ON expensetotal.idexp = expenseyear.idexp
			AND expensetotal.ayear = expenseyear.ayear
		JOIN finlink
			ON finlink.idchild = expenseyear.idfin
		WHERE expense.adate <= @date 
			AND ((expensetotal.flag&1)=1) -- Residuo
			AND finlink.idparent  = #situation_fin.idfin 
			AND expenseyear.idupb = #situation_fin.idupb
			AND expense.nphase = @nthirdphase), 0.0),
	var_third_ph_resid =
		ISNULL((
		SELECT SUM(expensevar.amount)
		FROM expensevar
		JOIN expense
			ON expensevar.idexp = expense.idexp
		JOIN expenseyear
			ON expenseyear.idexp = expensevar.idexp
			AND expenseyear.ayear = @ayear
		JOIN expensetotal 
			ON expensetotal.idexp = expenseyear.idexp
			AND expensetotal.ayear = expenseyear.ayear
		JOIN finlink
			ON finlink.idchild = expenseyear.idfin
		WHERE expensevar.adate <= @date 
			AND expense.nphase= @nthirdphase
			AND ((expensetotal.flag&1)=1) -- Residuo
			AND finlink.idparent  = #situation_fin.idfin 
			AND expenseyear.idupb = #situation_fin.idupb
			AND expensevar.yvar = @ayear), 0.0)
UPDATE #situation_fin
--  GESTIONE DEL FONDO ECONOMALE
	SET fin_ph_comp=   
		ISNULL(fin_ph_comp, 0.0) +
		ISNULL((SELECT SUM(operation.amount)
			FROM pettycashoperation operation
			JOIN finlink 
				ON finlink.idchild = operation.idfin
			WHERE finlink.idparent = #situation_fin.idfin	
				AND operation.idupb = #situation_fin.idupb
				AND operation.adate <= @date
				AND operation.yoperation = @ayear
				AND NOT EXISTS 
					(SELECT * FROM pettycashoperation oprestore
						WHERE oprestore.idpettycash = operation.idpettycash
						AND oprestore.yoperation = operation.yrestore
						AND oprestore.noperation = operation.nrestore
						AND oprestore.adate <= @date
						AND oprestore.yoperation = @ayear)), 0.0),
     second_ph_comp = ISNULL(second_ph_comp, 0.0) +
			ISNULL((SELECT SUM(operation.amount)
				FROM pettycashoperation operation
				JOIN finlink 
					ON finlink.idchild = operation.idfin
				WHERE finlink.idparent = #situation_fin.idfin	
					AND operation.idupb = #situation_fin.idupb
					AND operation.adate <= @date 
					AND operation.yoperation = @ayear
				AND NOT EXISTS 
					(SELECT * FROM pettycashoperation oprestore
						WHERE oprestore.idpettycash = operation.idpettycash
						AND oprestore.yoperation = operation.yrestore
						AND oprestore.noperation = operation.nrestore
						AND oprestore.adate <= @date
						AND oprestore.yoperation = @ayear)), 0.0),
     third_ph_comp = ISNULL(third_ph_comp, 0.0) +
			ISNULL((SELECT SUM(operation.amount)
				FROM pettycashoperation operation
				JOIN finlink 
					ON finlink.idchild = operation.idfin
				WHERE finlink.idparent = #situation_fin.idfin	
					AND operation.idupb = #situation_fin.idupb
					AND operation.adate <= @date 
					AND operation.yoperation = @ayear
				AND NOT EXISTS 
					(SELECT * FROM pettycashoperation oprestore
						WHERE oprestore.idpettycash = operation.idpettycash
						AND oprestore.yoperation = operation.yrestore
						AND oprestore.noperation = operation.nrestore
						AND oprestore.adate <= @date
						AND oprestore.yoperation = @ayear)), 0.0)
UPDATE #situation_fin
	SET	
	max_ph_comp =	 
		ISNULL((SELECT SUM(HPV.amount)	
		FROM historypaymentview HPV
		JOIN finlink
			ON finlink.idchild = HPV.idfin	 
		WHERE  HPV.ymov = @ayear
			AND HPV.competencydate <= @date
			AND ((HPV.totflag&1)=0) -- Competenza 
			AND finlink.idparent  = #situation_fin.idfin
			AND HPV.idupb = #situation_fin.idupb), 0.0),
	max_ph_resid =	 
		ISNULL((SELECT SUM(HPV.amount)
		FROM historypaymentview HPV
		JOIN finlink
			ON finlink.idchild = HPV.idfin	 
		WHERE  HPV.ymov = @ayear
			AND HPV.competencydate <= @date
			AND ((HPV.totflag&1)=1) -- Residuo
			AND finlink.idparent  = #situation_fin.idfin
			AND HPV.idupb = #situation_fin.idupb), 0.0)
IF @cashvaliditykind <> 4
BEGIN
	UPDATE #situation_fin
		SET	
		var_max_ph_comp = 
			ISNULL((
			SELECT SUM(expensevar.amount)
			FROM expensevar
			JOIN historypaymentview HPV
				ON HPV.idexp = expensevar.idexp
			JOIN finlink
				ON finlink.idchild = HPV.idfin	 
			WHERE expensevar.yvar = @ayear
				AND expensevar.adate <= @date
				AND HPV.ymov = @ayear AND HPV.competencydate <= @date
				AND ((HPV.totflag&1)=0) -- Competenza
				AND finlink.idparent  = #situation_fin.idfin
				AND HPV.idupb = #situation_fin.idupb), 0.0),
		var_max_ph_resid = 
			ISNULL((
			SELECT SUM(expensevar.amount)
			FROM expensevar
			JOIN historypaymentview HPV
				ON HPV.idexp = expensevar.idexp
			JOIN finlink
				ON finlink.idchild = HPV.idfin	
			WHERE expensevar.yvar = @ayear
				AND HPV.ymov = @ayear AND HPV.competencydate <= @date
				AND ((HPV.totflag&1)=1) --Residuo  
				AND expensevar.adate <= @date
				AND finlink.idparent  = #situation_fin.idfin
				AND HPV.idupb = #situation_fin.idupb), 0.0)
END		
-- Controlla che i CREDITI  siano gestiti
IF 	
	(EXISTS(SELECT* FROM creditpart
		WHERE ycreditpart = @ayear AND adate <= @date) 
	OR
	EXISTS (SELECT * FROM finvar
		WHERE flagcredit ='S' and yvar = @ayear
		AND adate <= @date
		AND finvar.idfinvarstatus = 5)
	--OR  
	--EXISTS (select * from upb where assured='S')
	)
		BEGIN
			UPDATE #situation_fin
			SET var_assign_credit = isnull((
				SELECT SUM(d.amount)
				FROM finvardetail d
				JOIN finvar v 
					ON v.yvar = d.yvar
					AND v.nvar = d.nvar
					AND v.flagcredit ='S'
				JOIN finlink
					ON finlink.idchild = d.idfin
				WHERE finlink.idparent  = #situation_fin.idfin
					AND v.idfinvarstatus = 5
					AND d.idupb = #situation_fin.idupb
					AND #situation_fin.assured <> 'S' -- solo upb non a finanziamento certo
					AND v.adate <= @date
					AND v.variationkind IN (2,3)),0.0),
			     assign_credit = isnull((
				SELECT SUM(creditpart.amount)
				FROM creditpart 
				JOIN incomeyear
					ON creditpart.idinc = incomeyear.idinc
					AND creditpart.ycreditpart = incomeyear.ayear
				JOIN finlink
					ON finlink.idchild = creditpart.idfin
				WHERE finlink.idparent = #situation_fin.idfin
					AND creditpart.idupb = #situation_fin.idupb
					AND #situation_fin.assured <> 'S'
					AND adate <= @date),0.0)
				+	
				ISNULL((
				SELECT SUM(d.amount)
				FROM finvardetail d
				JOIN finvar v
					ON v.yvar = d.yvar
					AND v.nvar = d.nvar
					AND v.flagcredit ='S'
				JOIN finlink
					ON finlink.idchild = d.idfin
				WHERE finlink.idparent  = #situation_fin.idfin
					AND v.idfinvarstatus = 5
					AND d.idupb = #situation_fin.idupb
					AND #situation_fin.assured <> 'S'
					AND v.adate <= @date
					AND v.variationkind IN (1,4)),0.0),
			flag_assign_credit='S'
			
			UPDATE #situation_fin
			SET flag_assign_credit='N' 
			WHERE #situation_fin.assured  = 'S' -- se upb a finanziamento certo, non considero i crediti
		END
ELSE
	BEGIN
		
		UPDATE #situation_fin
		SET 	var_assign_credit = 0,
			assign_credit =0,
			flag_assign_credit='N'
	END
IF 	(EXISTS(SELECT* FROM proceedspart 
		WHERE yproceedspart	= @ayear
		AND adate <= @date) 
	OR
	EXISTS (SELECT * FROM finvar
		WHERE flagproceeds='S' and 
		yvar = @ayear AND adate <= @date
		AND finvar.idfinvarstatus = 5)
	--OR
	--EXISTS (select * from upb where assured='S')
	)
	BEGIN
		UPDATE #situation_fin
		SET var_assign_cash = ISNULL(( 
			SELECT SUM(d.amount)
			FROM finvardetail d
			JOIN finvar v
				ON v.yvar = d.yvar
				AND v.nvar = d.nvar
				AND v.flagproceeds='S'
			JOIN finlink
				ON finlink.idchild = d.idfin
			WHERE finlink.idparent = #situation_fin.idfin
				AND v.idfinvarstatus = 5
				AND d.idupb = #situation_fin.idupb
				AND v.adate <= @date
				AND #situation_fin.assured <> 'S'
				AND v.variationkind IN (2,3)),0.0),
		 	assign_cash = isnull (( 
			SELECT SUM(proceedspart.amount)
				FROM proceedspart
			JOIN incomeyear
				ON proceedspart.idinc = incomeyear.idinc
				AND proceedspart.yproceedspart = incomeyear.ayear
			JOIN finlink
				ON finlink.idchild = proceedspart.idfin
			WHERE 	finlink.idparent  = #situation_fin.idfin
				AND #situation_fin.assured <> 'S'
				AND proceedspart.idupb = #situation_fin.idupb
				AND adate <= @date),0.0)
				+
			ISNULL((
			SELECT  SUM(d.amount)
			FROM finvardetail d
			JOIN finvar v
				ON v.yvar = d.yvar
				AND v.nvar = d.nvar
				AND v.flagproceeds='S'
			JOIN finlink
				ON finlink.idchild = d.idfin
			WHERE finlink.idparent = #situation_fin.idfin
				AND v.idfinvarstatus = 5
				AND #situation_fin.assured <> 'S'
				AND v.adate <= @date
				AND d.idupb = #situation_fin.idupb
				AND v.variationkind IN (1,4)),0.0),
			flag_assign_cash='S' 
			UPDATE #situation_fin
			SET flag_assign_cash='N' 
			WHERE #situation_fin.assured = 'S'
	END
ELSE
	BEGIN 
	UPDATE #situation_fin
	SET	var_assign_cash = 0,
		assign_cash = 0,
		flag_assign_cash='N'
	END
-- VALORIZZA CAMPI upb
	IF (@showupb = 'S')	
		UPDATE #situation_fin SET  upbprintingorder = upb.printingorder,
					upb = upb.title,
					codeupb = upb.codeupb
					FROM upb
					WHERE upb.idupb = #situation_fin.idupb
	IF (@showupb <>'S') AND (@idupboriginal <> '%' ) AND (@showchildupb = 'S')
		BEGIN
		UPDATE #situation_fin SET  
		idupb = @idupboriginal,
		upbprintingorder = (SELECT TOP 1 printingorder
					FROM upb
					WHERE idupb = @idupboriginal),
		upb = (SELECT TOP 1 title
					FROM upb
					WHERE idupb = @idupboriginal),
		codeupb =(SELECT TOP 1 codeupb
					FROM upb
					WHERE idupb = @idupboriginal)
	
		IF  (EXISTS(SELECT* FROM creditpart 
		     WHERE ycreditpart = @ayear AND adate <= @date) 
		OR
		EXISTS (SELECT * FROM finvar
			WHERE flagcredit='S' and 
			yvar = @ayear AND adate <= @date
			AND finvar.idfinvarstatus = 5)
		)
			BEGIN 
				UPDATE #situation_fin
				SET    flag_assign_credit='S'  -- ho aggiornato l'upb devo rivalutare flag_assign_credit
				FROM   upb
				WHERE  upb.idupb = #situation_fin.idupb 
				  AND ISNULL(upb.assured, 'N') <> 'S'
				
				UPDATE #situation_fin
				SET    flag_assign_credit='N'
				FROM   upb 
				WHERE  upb.idupb = #situation_fin.idupb 
				  AND  ISNULL(upb.assured, 'N') <> 'N'
			END
			ELSE   
			UPDATE #situation_fin
			SET    flag_assign_credit='N'
	
			IF  (EXISTS(SELECT* FROM proceedspart 
				WHERE yproceedspart = @ayear AND adate <= @date) 
			OR
			EXISTS (SELECT * FROM finvar
				WHERE flagproceeds='S' and 
				yvar = @ayear AND adate <= @date
				AND finvar.idfinvarstatus = 5)
			)	
			BEGIN
				UPDATE #situation_fin
				SET    flag_assign_cash='S' -- ho aggiornato l'upb devo rivalutare flag_assign_credit
				FROM   upb 
				WHERE  upb.idupb = #situation_fin.idupb 
				  AND ISNULL(upb.assured, 'N') <> 'S'
				
				UPDATE #situation_fin
				SET    flag_assign_cash='N'
				FROM   upb 
				WHERE  upb.idupb = #situation_fin.idupb 
				  AND  ISNULL(upb.assured, 'N') = 'S'
			END
			ELSE   
			UPDATE #situation_fin
			SET    flag_assign_cash='N'
		END
	
	IF (@showupb <>'S') and (@idupboriginal = '%') 
		BEGIN
		UPDATE #situation_fin SET  
			idupb = null,
			upbprintingorder = null,
			upb =  null,
			codeupb = null
		-- considero solo se sono gestiti crediti e cassa, non gli upb
		IF  (EXISTS(SELECT* FROM creditpart 
		     WHERE ycreditpart = @ayear AND adate <= @date) 
		OR
		EXISTS (SELECT * FROM finvar
			WHERE flagcredit='S' and 
			yvar = @ayear AND adate <= @date
			AND finvar.idfinvarstatus = 5))
			UPDATE #situation_fin
			SET    flag_assign_credit='S'
			ELSE   
			UPDATE #situation_fin
			SET    flag_assign_credit='N'
	
		IF  (EXISTS(SELECT* FROM proceedspart 
			WHERE yproceedspart = @ayear AND adate <= @date) 
		OR
		EXISTS (SELECT * FROM finvar
			WHERE flagproceeds='S' and 
			yvar = @ayear AND adate <= @date
			AND finvar.idfinvarstatus = 5))
			UPDATE #situation_fin
			SET    flag_assign_cash='S'
			ELSE   
			UPDATE #situation_fin
			SET    flag_assign_cash='N'
		END
IF (@suppressifblank = 'S') AND @nlevel>=2	--> se la stampa è x categoria o x un livello sottostante la categoria cancella le righe
BEGIN
	DELETE FROM #situation_fin WHERE 
			(isnull(main_initial_prevision,0.0) =0 AND 
			isnull(var_main_prevision,0.0) =0 AND 
			isnull(sec_initial_prevision,0.0) =0 AND 
        		isnull(varprevsec,0.0) =0 AND 
			isnull(fin_ph_comp,0.0) =0 AND  
			isnull(var_fin_ph_comp,0.0) =0 AND 
			isnull(fin_ph_resid,0.0) =0 AND 
			isnull(var_fin_ph_resid,0.0) =0 AND 			
			isnull(second_ph_comp,0.0) =0 AND 
			isnull(var_second_ph_comp,0.0) =0 AND 
			isnull(second_ph_resid,0.0) =0 AND 
			isnull(var_second_ph_resid,0.0) =0 AND 
			isnull(third_ph_comp,0.0) =0 AND 
			isnull(var_third_ph_comp,0.0) =0 AND 
			isnull(third_ph_resid,0.0) =0 AND 
			isnull(var_third_ph_resid,0.0) =0 AND 
			isnull(max_ph_comp,0.0) =0 AND 
			isnull(var_max_ph_comp,0.0) =0 AND 
			isnull(max_ph_resid,0.0) =0 AND 
			isnull(var_max_ph_resid,0.0) =0 AND 
			isnull(assign_credit,0.0) =0 AND 
        		isnull(var_assign_credit,0.0) =0 AND 
			isnull(assign_cash,0.0) =0 AND 
			isnull(var_assign_cash,0.0) =0 AND
			(select nlevel from fin FFF where FFF.idfin= #situation_fin.idfin)>=2)
END
IF (@showupb <>'S') 
BEGIN
	
	SELECT 
		#situation_fin.idfin,	
		fin.printingorder 			as 'finprintingorder',
		codeupb,
		idupb,
		upb,
		upbprintingorder,
		fin.codefin,	
		fin.title,	
		fin.nlevel,	
		sum(isnull(main_initial_prevision,0.0)) as 'main_initial_prevision',
		sum(isnull(var_main_prevision,0.0)) 	as 'var_main_prevision',
		sum(isnull(sec_initial_prevision,0.0)) 	as 'sec_initial_prevision',
		sum(isnull(varprevsec,0.0)) 		as 'varprevsec',
		sum(isnull(fin_ph_comp,0.0)) 		as 'fin_ph_comp',
		sum(isnull(var_fin_ph_comp,0.0)) 	as 'var_fin_ph_comp', 
		sum(isnull(fin_ph_resid,0.0)) 		as 'fin_ph_resid', 
		sum(isnull(var_fin_ph_resid,0.0)) 	as 'var_fin_ph_resid',
		@finphase 			        as 'desc_fin_ph',					
		sum(isnull(second_ph_comp,0.0)) 	as 'second_ph_comp',
		sum(isnull(var_second_ph_comp,0.0)) 	as 'var_second_ph_comp',
		sum(isnull(second_ph_resid,0.0)) 	as 'second_ph_resid',
		sum(isnull(var_second_ph_resid,0.0))    as 'var_second_ph_resid',
		@secondphase 			        as 'desc_second_ph',					
		sum(isnull(third_ph_comp,0.0)) 	        as 'third_ph_comp',
		sum(isnull(var_third_ph_comp,0.0)) 	as 'var_third_ph_comp',
		sum(isnull(third_ph_resid,0.0)) 	as 'third_ph_resid',
		sum(isnull(var_third_ph_resid,0.0))     as 'var_third_ph_resid',
		@thirdphase 			        as 'desc_third_ph',					
		sum(isnull(max_ph_comp,0.0)) 		as 'max_ph_comp',
		sum(isnull(var_max_ph_comp,0.0)) 	as 'var_max_ph_comp',
		sum(isnull(max_ph_resid,0.0)) 		as 'max_ph_resid',
		sum(isnull(var_max_ph_resid,0.0)) 	as 'var_max_ph_resid',
		@max_phase 			        as 'desc_max_ph' 	,					
		sum(isnull(assign_credit,0.0)) 		as 'assign_credit',
		sum(isnull(var_assign_credit,0.0)) 	as 'var_assign_credit',
		sum(isnull(assign_cash,0.0)) 		as 'assign_cash',
		sum(isnull(var_assign_cash,0.0)) 	as 'var_assign_cash',
		@previsionkind 				as 'previsionkind',
		@secprevisionkind 			as 'secprevisionkind',
		flag_assign_credit,
		flag_assign_cash,
		flagconsider	
	 	FROM #situation_fin JOIN fin 
		ON #situation_fin.idfin = fin.idfin			
		GROUP BY idupb,
			#situation_fin.idfin,
			codeupb,
			upb,
			upbprintingorder,
			fin.printingorder,
			fin.codefin,	
			fin.title,
			fin.nlevel,
			flag_assign_credit,
			flag_assign_cash,
			flagconsider			
		ORDER BY upbprintingorder,
			finprintingorder
END 
	ELSE
		SELECT 
			#situation_fin.idfin,	
			codeupb,
			idupb,
			upb,
			upbprintingorder,
			fin.codefin,	
			fin.title,	
			fin.printingorder 	as 'finprintingorder',	
			fin.nlevel,	
			main_initial_prevision,
			var_main_prevision,
			sec_initial_prevision,
			varprevsec,
			fin_ph_comp,
			var_fin_ph_comp, 
			fin_ph_resid, 
			var_fin_ph_resid,
			@finphase 	as 'desc_fin_ph',					
			second_ph_comp,
			var_second_ph_comp,
			second_ph_resid,
			var_second_ph_resid,
			@secondphase 	as 'desc_second_ph',	
			third_ph_comp,
			var_third_ph_comp,
			third_ph_resid,
			var_third_ph_resid,
			@thirdphase 	as 'desc_third_ph',					
			max_ph_comp,
			var_max_ph_comp,
			max_ph_resid,
			var_max_ph_resid,
			@max_phase 	as 'desc_max_ph',					
			assign_credit,
			var_assign_credit,
			assign_cash,
        		var_assign_cash,
			@previsionkind 		as 'previsionkind',
			@secprevisionkind 	as 'secprevisionkind',
			flag_assign_credit,
			flag_assign_cash,
			flagconsider	
		 	FROM #situation_fin 
			JOIN fin on #situation_fin.idfin = fin.idfin
			ORDER BY upbprintingorder,finprintingorder
END

GO

print '[rpt_sitbilancio_spesa_4fasi] OK'

GO
if object_id('[trasmele_expense_unicredit_XXX]') is not null
	drop PROCEDURE [trasmele_expense_unicredit_XXX]
go

-- EXEC trasmele_expense_unicredit_XXX 2011, 13
CREATE          PROCEDURE [trasmele_expense_unicredit_XXX]
(
	@y int,
	@n int
)
AS BEGIN
/* Versione 1.0.0 del 05/09/2007 ultima modifica: SARA */
-- Inizio Sezione Dichiarativa
DECLARE @docversion varchar(5)
SET @docversion = '2.100'
DECLARE @len_npay_trans int
SET @len_npay_trans = 6
DECLARE @len_ndoc int
SET @len_ndoc = 7
DECLARE @len_committeeamount int
SET @len_committeeamount = 7
DECLARE @len_amount int
SET @len_amount = 15
DECLARE @len_desc_dept int
SET @len_desc_dept = 30
DECLARE @len_address_dept int
SET @len_address_dept = 30
DECLARE @len_location_dept int
SET @len_location_dept = 35
DECLARE @len_idpay int
SET @len_idpay = 7
DECLARE @len_idpro int
SET @len_idpro = 7
DECLARE @len_registry_title int
SET @len_registry_title = 140
DECLARE @len_address int
SET @len_address = 30
DECLARE @len_cap int
SET @len_cap = 5
DECLARE @len_location int
SET @len_location = 30
DECLARE @len_province int
SET @len_province = 2
DECLARE @len_cf int
SET @len_cf = 16
DECLARE @len_pi int
SET @len_pi = 11
DECLARE @len_ABI int
SET @len_ABI = 5
DECLARE @len_CAB int
SET @len_CAB = 5
DECLARE @len_cc int
SET @len_cc = 12
DECLARE @len_cin int
SET @len_cin = 1
DECLARE @len_desc_paymethod int
SET @len_desc_paymethod = 30
DECLARE @len_desc_payment int
SET @len_desc_payment = 370
DECLARE @len_sortcode int
SET @len_sortcode = 10
DECLARE @len_desc_sort int
SET @len_desc_sort = 60
DECLARE @len_deputy int
SET @len_deputy = 140
DECLARE @len_bank_title int
SET @len_bank_title = 100
DECLARE @len_refexternaldoc int
SET @len_refexternaldoc = 1
DECLARE @len_idstamphandling int
SET @len_idstamphandling = 1
DECLARE @ABI_codeunicredit varchar(5)
SET @ABI_codeunicredit = '02008'
DECLARE @idtreasurer int
DECLARE @kpaymenttransmission int
DECLARE @lencodicecontabilitaspeciale int
SET @lencodicecontabilitaspeciale = 7	
DECLARE @len_codiceoperatore int 
SET @len_codiceoperatore = 12
SELECT @idtreasurer = idtreasurer, @kpaymenttransmission = kpaymenttransmission FROM paymenttransmission
WHERE ypaymenttransmission = @y
	AND npaymenttransmission = @n
IF (@idtreasurer IS NULL) 
BEGIN
	SELECT @idtreasurer = MAX(idtreasurer) FROM treasurer WHERE flagdefault = 'S'
END
IF (@idtreasurer IS NULL) 
BEGIN
	SELECT @idtreasurer = MAX(idtreasurer) FROM treasurer
END
DECLARE @opkind char(2) -- Può assumere i valori I, A, S, N (vedere specifiche tracciato)
SET @opkind = 'I ' -- Attualmente può assumere solamente valore ' I'
-- Fine Sezione Dichiarativa
DECLARE @lenCC_vincolato int
SET @lenCC_vincolato = 7
DECLARE @cc_vincolato varchar(7)

DECLARE @cod_department varchar(9) -- Codice dell'ente da esportare
DECLARE @ABI_code varchar(5)
SELECT @cod_department = ISNULL(agencycodefortransmission,''),
	@ABI_code = SUBSTRING(REPLICATE('0',@len_ABI),1,@len_ABI - DATALENGTH(ISNULL(idbank,'')))+ ISNULL(idbank,''),
	@cc_vincolato = SUBSTRING( REPLICATE(' ',7), 1, @lenCC_vincolato - DATALENGTH(SUBSTRING(ISNULL(trasmcode,''), DATALENGTH(ISNULL(trasmcode,''))-6,@lenCC_vincolato))) + substring(ISNULL(trasmcode,''), DATALENGTH(ISNULL(trasmcode,''))-6,@lenCC_vincolato)
FROM treasurer WHERE idtreasurer = @idtreasurer

DECLARE @cf_dept varchar(16)
DECLARE @desc_dept varchar(30)
DECLARE @address_dept varchar(30)
DECLARE @location_dept varchar(35)
SELECT @cf_dept = ISNULL(cf,'') + SUBSTRING(SPACE(@len_cf),1,@len_cf - DATALENGTH(ISNULL(cf,''))) ,
@desc_dept = 
CASE
	WHEN DATALENGTH(ISNULL(agencyname,'')) <= @len_desc_dept
	THEN ISNULL(agencyname,'') + SUBSTRING(SPACE(@len_desc_dept),1,@len_desc_dept - DATALENGTH(ISNULL(agencyname,'')))
	ELSE SUBSTRING(agencyname,1,@len_desc_dept)
END,
@address_dept =
CASE 
	WHEN DATALENGTH(ISNULL(address1,'')) <= @len_address_dept
	THEN ISNULL(address1,'') + SUBSTRING(SPACE(@len_address_dept),1,@len_address_dept - DATALENGTH(ISNULL(address1,'')))
	ELSE SUBSTRING(address1,1,@len_address_dept)
END,
@location_dept = 
CASE 
	WHEN DATALENGTH(ISNULL(location,'')) <= @len_location_dept
	THEN ISNULL(location,'') + SUBSTRING(SPACE(@len_location_dept),1,@len_location_dept - DATALENGTH(ISNULL(location,'')))
	ELSE SUBSTRING(location,1,@len_location_dept)
END
FROM license
DECLARE @len_agencycode int
SET @len_agencycode = 7
CREATE TABLE #error (message varchar(400))
-- Inizio Sezione Controlli
-- CONTROLLO N. 0 -- Distinta di Trasmissione vuota
IF(
(SELECT COUNT(*) FROM payment
WHERE kpaymenttransmission = @kpaymenttransmission) = 0)
BEGIN
	INSERT INTO #error
	VALUES('La distinta di trasmissione ' + CONVERT(varchar(4),@y) + '/'
	+ CONVERT(varchar(6),@n) + ' è vuota')
END
-- CONTROLLO N. 1. Presenza dei dati dell'ente
DECLARE @error char(1)
SET @error = 'N'
DECLARE @message varchar(400)
SET @message = 'Mancano i seguenti dati: '
IF (@cod_department IS NULL OR @cod_department = '')
BEGIN
	SET @message = @message + ' Il Codice Ente'
	SET @error = 'S'
END
IF (@ABI_code IS NULL OR @ABI_code = '')
BEGIN
	SET @message = @message + ' Il codice ABI'
	SET @error = 'S'
END
IF (@error = 'S')
BEGIN
	SET @message = @message + ' Andare nella maschera CONFIGURAZIONE - CASSIERE - CASSIERE ed inserire i dati'
	INSERT INTO #error VALUES(@message)
END
-- CONTROLLO N. 2. Lunghezza del codice ente
IF (DATALENGTH(@cod_department) > @len_agencycode)
BEGIN
	INSERT INTO #error
	VALUES ('Il codice Ente inserito è superiore alla lunghezza massima fissata a '
	+ CONVERT(varchar(2),@len_agencycode))
END
-- CONTROLLO N. 3. Movimento di Spesa senza Modalità di Pagamento
INSERT INTO #error (message)
(SELECT 'Per il movimento n.' + CONVERT(varchar(6),nmov) 
+ '/' + CONVERT(varchar(4),ymov) + ' non è stata scelta una modalità di pagamento'
FROM paymentcommunicated
WHERE ypaymenttransmission = @y
	AND npaymenttransmission = @n
	AND idpaymethod IS NULL)
-- CONTROLLO N. 4. Movimento di spesa con refexternaldoc che eccede la lunghezza consentita
INSERT INTO #error (message)
(SELECT 'Nel movimento n.' + CONVERT(varchar(6),nmov) 
+ '/' + CONVERT(varchar(4),ymov) + ' il riferimento al doc. esterno eccede la lunghezza di '
+ CONVERT(varchar(3),@len_refexternaldoc) + ' caratteri'
FROM paymentcommunicated
WHERE ypaymenttransmission = @y
	AND npaymenttransmission = @n
	AND DATALENGTH(ISNULL(RTRIM(refexternaldoc),''))> @len_refexternaldoc)
-- CONTROLLO N. 5. Movimento di Spesa con Modalità di Pagamento non configurata
INSERT INTO #error (message)
(SELECT 'Nel movimento n.' + CONVERT(varchar(6),paymentcommunicated.nmov) 
+ '/' + CONVERT(varchar(4),paymentcommunicated.ymov) + ' la modalità di pagamento scelta non è configurata, Andare in Configurazione - Anagrafica - Modalità di Pagamento'
FROM paymentcommunicated
JOIN paymethod
	ON paymentcommunicated.idpaymethod = paymethod.idpaymethod
WHERE paymentcommunicated.ypaymenttransmission = @y
	AND paymentcommunicated.npaymenttransmission = @n
	AND (paymethod.methodbankcode IS NULL OR REPLACE(paymethod.methodbankcode,' ','') = '')
)
-- CONTROLLO N. 6. Codice IBAN o ABI o CAB devono essere valorizzati nel caso di modalità di pagamento 53 e 63
INSERT INTO #error (message)
(SELECT 'Al movimento n.' + CONVERT(varchar(6),paymentcommunicated.nmov) 
+ '/' + CONVERT(varchar(4),paymentcommunicated.ymov) + ' nella modalità di pagamento scelta non è stato assegnato il codice ABI / CAB.'
FROM paymentcommunicated
	JOIN paymethod
	ON paymentcommunicated.idpaymethod = paymethod.idpaymethod
WHERE paymentcommunicated.ypaymenttransmission = @y
	AND paymentcommunicated.npaymenttransmission = @n
	AND paymethod.methodbankcode IN ('53','63')
	AND (
		(paymentcommunicated.idcab IS NULL OR REPLACE(paymentcommunicated.idcab,' ','') = '')
		OR (paymentcommunicated.idbank IS NULL OR REPLACE(paymentcommunicated.idbank,' ','') = '')
-- N.B. Giuseppe Rusciano scrive: Su richesta dell'Università di Bari, stiamo commentando l'obbligatorietà dell'IBAN, 
-- negli ultimi giorni di maggio la rimettiamo e nel caso la vogliono togliere di nuovo ci facciamo mandare una mail
-- in quanto dal 3 giugno 2008 chi non mette l'IBAN è soggetto ad una sanzione di 1 euro
--		OR (paymentcommunicated.iban IS NULL OR REPLACE(paymentcommunicated.iban,' ','') = '')
	)
)
-- CONTROLLO N. 7. Il codice ABI, CAB e il CIN non devono eccedere la lunghezza massima nel caso di modalità di pagamento 53 e 63
INSERT INTO #error (message)
(SELECT 'Al movimento n.' + CONVERT(varchar(6),paymentcommunicated.nmov) 
+ '/' + CONVERT(varchar(4),paymentcommunicated.ymov) + ' nella modalità di pagamento il codice ABI eccede la lunghezza di '
+ CONVERT(varchar(3),@len_ABI) + ' caratteri e/o il codice CAB eccede la lunghezza di '
+ CONVERT(varchar(3),@len_CAB) + ' caratteri e/o il CIN eccede la lunghezza di '
+ CONVERT(varchar(3),@len_cin) + ' caratteri'
FROM paymentcommunicated
JOIN paymethod
	ON paymentcommunicated.idpaymethod = paymethod.idpaymethod
WHERE paymentcommunicated.ypaymenttransmission = @y
	AND paymentcommunicated.npaymenttransmission = @n
	AND paymethod.methodbankcode IN ('53','63')
	AND (
	(DATALENGTH(paymentcommunicated.idcab) > @len_CAB)
	OR (DATALENGTH(paymentcommunicated.idbank) > @len_ABI)
	OR (DATALENGTH(paymentcommunicated.cin) > @len_cin)
		)
	)
-- CONTROLLO N. 8. Conto Corrente valorizzato e di lunghezza massima 12 caratteri nel caso di modalità di pagamento 52, 53 e 63
IF EXISTS
(SELECT * FROM paymentcommunicated
JOIN paymethod
	ON paymentcommunicated.idpaymethod = paymethod.idpaymethod
WHERE paymentcommunicated.ypaymenttransmission = @y
	AND paymentcommunicated.npaymenttransmission = @n
	AND paymethod.methodbankcode IN ('52','53','63') 
AND (paymentcommunicated.cc IS NULL
	OR REPLACE(paymentcommunicated.cc,' ','') = ''
	OR DATALENGTH(ISNULL(
	REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(
	REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(paymentcommunicated.cc,',',''),'.',''),'_',''),'-',''),'*',''),'+',''),
	'/',''),':',''),';',''),' ','')
	,'')) > @len_cc)
)
BEGIN
	INSERT INTO #error (message)
	(SELECT 'Al movimento n.' + CONVERT(varchar(6),paymentcommunicated.nmov) 
	+ '/' + CONVERT(varchar(4),paymentcommunicated.ymov)
	+ ' nella modalità di pagamento non è stato il C/C o la lunghezza del C/C eccede i '
	+ CONVERT(varchar(2),@len_cc) + ' caratteri'
	FROM paymentcommunicated
	JOIN paymethod
		ON paymentcommunicated.idpaymethod = paymethod.idpaymethod
	WHERE paymentcommunicated.ypaymenttransmission = @y
	AND paymentcommunicated.npaymenttransmission = @n
	AND paymethod.methodbankcode IN ('52','53','63')
	AND (paymentcommunicated.cc IS NULL
		OR REPLACE(paymentcommunicated.cc,' ','') = ''
		OR DATALENGTH(ISNULL(paymentcommunicated.cc,'')) > @len_cc)
	)
END
-- CONTROLLO N. 9. Presenza tipologia dei beneficiari
DECLARE @denomcred_err varchar(200)
INSERT INTO #error (message)
SELECT 'Il beneficiario ' + ISNULL(R.title,'XXX') + ' con codice ' + CONVERT(varchar(6),R.idreg) + ' non ha una tipologia associata. E'' necessario inserirla'
FROM expense E
JOIN expenselast EL
	ON E.idexp = EL.idexp
JOIN payment P
	ON P.kpay = EL.kpay
JOIN registry R
	ON R.idreg = E.idreg
WHERE R.idregistryclass IS NULL
	AND P.kpaymenttransmission = @kpaymenttransmission
-- CONTROLLO N. 10
INSERT INTO #error (message)
SELECT distinct 'Correggere il codice della modalità di pagamento ' + pm.description + '. La lunghezza deve essere 2. '
FROM expenselast el
JOIN payment p
	ON p.kpay = el.kpay
JOIN paymethod pm
	ON el.idpaymethod = pm.idpaymethod
WHERE p.kpaymenttransmission = @kpaymenttransmission 
        AND len(pm.methodbankcode)<>2
INSERT INTO #error (message)
SELECT distinct 'Correggere il codice delle Commissioni Bancarie per la mod. di pagamento ' + pm.description + '. La lunghezza deve essere 1. '
FROM expenselast el
JOIN payment p
	ON p.kpay = el.kpay
JOIN paymethod pm
	ON el.idpaymethod = pm.idpaymethod
WHERE p.kpaymenttransmission = @kpaymenttransmission 
        AND len(pm.committeecode)<>1

-- CONTROLLO N. 11. Uso di modlaità di pagamento NON ammesse dalla banca-  vedi 'MIF ABI-USI txt Multirecord - note V2200.pdf'
INSERT INTO #error (message)
(SELECT 'Nel movimento n.' + CONVERT(varchar(6),paymentcommunicated.nmov) 
+ '/' + CONVERT(varchar(4),paymentcommunicated.ymov) + ' è stata usata una modalità di pagamento non prevista dalla banca.'
FROM paymentcommunicated
JOIN paymethod
	ON paymentcommunicated.idpaymethod = paymethod.idpaymethod
WHERE paymentcommunicated.ypaymenttransmission = @y
	AND paymentcommunicated.npaymenttransmission = @n
	AND paymethod.methodbankcode NOT IN ('51','52','53','55','57','61','63','64','65','67','68','69','71','72')
)
-- CONTROLLO N. 12. Modalità di Pagamento Esclusiva Cassiere
INSERT INTO #error (message)
(SELECT 'Nel movimento n.' + CONVERT(varchar(6),paymentcommunicated.nmov) 
+ '/' + CONVERT(varchar(4),paymentcommunicated.ymov) + ' la modalità di pagamento scelta è Esclusiva Cassiere. Sostituirla con una più adeguata, al fine di attribuirne un significato più consono nella trasmissione telematica. '
FROM paymentcommunicated
JOIN paymethod
	ON paymentcommunicated.idpaymethod = paymethod.idpaymethod
WHERE paymentcommunicated.ypaymenttransmission = @y
	AND paymentcommunicated.npaymenttransmission = @n
	AND (paymethod.description like 'Esclusiva%Cassiere')
)
-- CONTROLLO N. 13. codice contabilita speciale errato o mancante
IF EXISTS
(SELECT * FROM paymentcommunicated
        join expenselast
        	ON paymentcommunicated.idexp = expenselast.idexp
        join expense
              on expenselast.idexp = expense.idexp 
        join registrypaymethod
                on registrypaymethod.idreg = expense.idreg
                and registrypaymethod.idpaymethod = expenselast.idpaymethod
				and registrypaymethod.idregistrypaymethod = expenselast.idregistrypaymethod
        JOIN paymethod
        	ON expenselast.idpaymethod = paymethod.idpaymethod
WHERE paymentcommunicated.kpaymenttransmission = @kpaymenttransmission
	AND paymethod.methodbankcode = '61'
	AND (registrypaymethod.extracode IS NULL
		OR REPLACE(registrypaymethod.extracode,' ','') = ''
		OR DATALENGTH(ISNULL(
		REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(
		REPLACE(REPLACE(REPLACE(REPLACE(registrypaymethod.extracode,',',''),'.',''),'_',''),'-',''),'*',''),'+',''),
		'/',''),':',''),';','')
		,'')) > @lencodicecontabilitaspeciale)
)
BEGIN
	INSERT INTO #error (message)
		(SELECT 'Al movimento n.' + CONVERT(varchar(6),paymentcommunicated.nmov) 
		+ '/' + CONVERT(varchar(4),paymentcommunicated.ymov)
		+ ' nella modalità di pagamento non è stato inserito il Codice contabilità speciale o la sua lunghezza supera i '
		+ CONVERT(varchar(7),@lencodicecontabilitaspeciale) + ' caratteri'
		FROM paymentcommunicated
        join expenselast
        	ON paymentcommunicated.idexp = expenselast.idexp
        join expense
              on expenselast.idexp = expense.idexp 
        join registrypaymethod
                on registrypaymethod.idreg = expense.idreg
                and registrypaymethod.idpaymethod = expenselast.idpaymethod
				and registrypaymethod.idregistrypaymethod = expenselast.idregistrypaymethod
        JOIN paymethod
        	ON expenselast.idpaymethod = paymethod.idpaymethod
		WHERE paymentcommunicated.kpaymenttransmission = @kpaymenttransmission
			AND paymethod.methodbankcode = '61'
			AND (registrypaymethod.extracode IS NULL
				OR REPLACE(registrypaymethod.extracode,' ','') = ''
				OR DATALENGTH(ISNULL(registrypaymethod.extracode,'')) > @lencodicecontabilitaspeciale)
		)
END

IF (SELECT COUNT(*) FROM #error) > 0
BEGIN
	SELECT * FROM #error
	RETURN
END
-- Attenzione! Altri controlli sono presenti nel testo della SP in quanto non era possibile calcolarli a priori
