if object_id('[compute_root_idsor_income]') is not null
	drop PROCEDURE [compute_root_idsor_income]
go


CREATE           PROCEDURE [compute_root_idsor_income]
(
	@idsorkind_target int,
	@ayear int,
	@idinc int,
	@idreg int,
	@idupb varchar(36),
	@nphase tinyint,
	@idfin int,
	@idman int,
	@amount decimal
)
AS
-- Il concetto di base è che l'assenza di configurazione sulla n-pla in ingresso significhi ' FAI QUALSIASI COSA SU QUEL MOVIMENTO '
CREATE TABLE #tmp (
	[idautosort] [int],
	[idfin] [int],
	[idupb][varchar](36),
	[idsorkindreg] [int],
	[idsorreg][int],
	[idman] [int],
	[idsorkind] [int],
	[idsor] [int],
	[jointolessspecifics] [char] (1)
)
INSERT INTO #tmp 
	(idautosort,idfin,idupb,idsorkindreg,idsorreg,idman,
	idsorkind,idsor,jointolessspecifics
) 
SELECT 
	A.idautosort,F.idparent,--A.idfin,
	A.idupb,A.idsorkindreg,A.idsorreg,A.idman,
	A.idsorkind,A.idsor,A.jointolessspecifics
FROM sortingincomefilter A
JOIN sortingkind T
	ON A.idsorkind = T.idsorkind 
LEFT OUTER JOIN finlink F 
	ON F.idparent = A.idfin
WHERE T.idsorkind = @idsorkind_target AND
	((A.idfin IS NULL) OR (@idfin = F.idchild )) AND
	((A.idman IS NULL)OR( idman =  A.idman)) AND
	((A.idupb IS NULL)OR( @idupb LIKE  A.idupb+'%')) AND
	((A.idsorkindreg IS NULL) OR 
		EXISTS (SELECT * FROM registrysorting C
			JOIN sorting sc
				ON sc.idsor = C.idsor
			JOIN sortinglink
				ON sortinglink.idchild = C.idsor
			where C.idreg=@idreg
			AND sc.idsorkind=A.idsorkindreg
			AND ((A.idsorreg IS NULL) OR (sortinglink.idparent = A.idsorreg))
			)
	)
	
--rimuove quelli meno specifici ove presenti altri più specifici
DELETE from #tmp where 
	(select count(*) from #tmp T2 
	JOIN finlink FLK 
		ON FLK.idparent = T2.idfin
	JOIN sortinglink SLK
		ON SLK.idparent = T2.idsorreg
	WHERE 
			-- se #tmp ha il jointolessspecifics='S' non deve essere cancellata
			(T2 .jointolessspecifics = 'N') AND
			--l'insieme individuato da T2 deve essere diverso da quello di #tmp
			( (#tmp.idfin IS NULL and T2.idfin IS NOT NULL) or (#tmp.idfin IS NOT NULL and T2.idfin IS NULL) or (#tmp.idfin<>T2.idfin) or
			  (#tmp.idman IS NULL and T2.idman IS NOT NULL) or (#tmp.idman IS NOT NULL and T2.idman IS NULL) or (#tmp.idman<>T2.idman) or
			  (#tmp.idupb IS NULL and T2.idupb IS NOT NULL) or (#tmp.idupb IS NOT NULL and T2.idupb IS NULL) or (#tmp.idupb<>T2.idupb) or
			  (#tmp.idsorkindreg IS NULL and T2.idsorkindreg IS NOT NULL) or (#tmp.idsorkindreg IS NOT NULL and T2.idsorkindreg IS NULL) or (#tmp.idsorkindreg<>T2.idsorkindreg) or
			  (#tmp.idsorreg IS NULL and T2.idsorreg IS NOT NULL) or (#tmp.idsorreg IS NOT NULL and T2.idsorreg IS NULL) or (#tmp.idsorreg<>T2.idsorreg) 
			) AND
			--l'insieme individuato da T2  deve essere più specifico di quello di #tmp
			(#tmp.idautosort<>T2.idautosort) AND
			((#tmp.idfin IS NULL) or (FLK.idchild = #tmp.idfin )) AND 
			((#tmp.idman IS NULL) or (T2.idman = #tmp.idman)) AND 
			((#tmp.idupb IS NULL)or(T2.idupb LIKE #tmp.idupb+'%') ) AND
			(   ((#tmp.idsorkindreg IS NULL)or
			      ( 
				 (T2.idsorkindreg = #tmp.idsorkindreg) AND 
				(SLK.idchild = #tmp.idsorreg)
			      )		
			   )	
			) 		
		)>0
if (SELECT COUNT(*) from #tmp) =0 
BEGIN
	SELECT * FROM sorting WHERE idsorkind = @idsorkind_target and (movkind IS NULL or movkind='E')AND
		(start is null or start <= @ayear) AND
		(stop is null or  stop >= @ayear) 
END
ELSE
BEGIN
	--Elimina i fitri a NULL
	DELETE from #tmp where idsor IS NULL
	--Prende solo le foglie 	
	SELECT * FROM sorting C
	JOIN #tmp T
		ON C.idsorkind=T.idsorkind 
	JOIN sortinglevel L
		ON C.idsorkind=L.idsorkind
		AND L.nlevel = C.nlevel
	JOIN sortinglink
		ON sortinglink.idchild = C.idsor
	WHERE T.idsor = sortinglink.idparent
		AND ((L.flag & 2) <> 0)
		AND NOT EXISTS(SELECT * FROM sorting C2 WHERE C2.paridsor=C.idsor and C2.idsorkind=C.idsorkind) 
		AND (C.start is null or C.start <= @ayear) 
		AND (C.stop is null or  C.stop >= @ayear) 
END


GO

print '[compute_root_idsor_income] OK'

GO
if object_id('[rpt_sitbilancioarticoli_respons_operation_2fasi]') is not null
	drop PROCEDURE [rpt_sitbilancioarticoli_respons_operation_2fasi]
go

CREATE     PROCEDURE [rpt_sitbilancioarticoli_respons_operation_2fasi]
	@ayear			int,
	@nlevel			tinyint,
	@hierarchy		char(1),
	@idman			int,
	@suppressifblank 	char(1),
	@codefin		varchar(50),
	@start 			datetime,
	@stop 			datetime
AS
BEGIN
/* Versione 1.0.6 del 27/11/2007 ultima modifica: MARIA */
DECLARE @idfin int
IF (@codefin IS NULL OR @codefin = '' OR @codefin = '%')
	BEGIN
		SET @idfin = null	
	END
Else
	BEGIN
	   	SET @idfin = (select idfin 
				from fin 
				where codefin = @codefin 
				and ayear=@ayear 
				and (fin.flag&1)=1) --Spesa
	END
CREATE TABLE #fin_situation
(
	idfin			int,
	codefin			varchar(50),
	title			varchar(150),
	finprintingorder	varchar(50),
	nlevel			tinyint,
	main_initial_prevision	decimal(19,2),
	var_main_prevision	decimal(19,2),
	fin_phase_comp		decimal(19,2),
	var_fin_phase_comp	decimal(19,2),
	desc_fin_phase 		varchar(50),					
	max_phase_comp         	decimal(19,2),
	var_max_phase_comp     	decimal(19,2),
	desc_max_phase 		varchar(50),					
	sec_initial_prevision	decimal(19,2),
	varprevsec		decimal(19,2),
	fin_phase_resid		decimal(19,2),
	var_fin_phase_resid	decimal(19,2),
	max_phase_resid         decimal(19,2),
	var_max_phase_resid     decimal(19,2),
	assign_credit 		decimal(19,2),
	var_assign_credit	decimal(19,2),
	assign_cash		decimal(19,2),
	var_assign_cash		decimal(19,2),
	previsionkind 		char(1),
	secprevisionkind 	char(1),
	flag_assign_credit 	char(1),
	flag_assign_cash 	char(1),
	idman			int,
	manager			varchar(150)						
)
IF @ayear IS NULL 
BEGIN
	SELECT 		
		idfin, 
		NULL as idfinlevel0, NULL as idfinlevel1, NULL as idfinlevel2,
		NULL as idfinlevel3, NULL as idfinlevel4, NULL as idfinlevel5,
		NULL as idfinlevel6, NULL as idfinlevel7, NULL as idfinlevel8,
		NULL as idfinlevel9, codefin, title, finprintingorder,	
		nlevel, main_initial_prevision, var_main_prevision,
		fin_phase_comp, var_fin_phase_comp, desc_fin_phase,
		max_phase_comp, var_max_phase_comp,
		desc_max_phase,	sec_initial_prevision, varprevsec,
		fin_phase_resid, var_fin_phase_resid, max_phase_resid,
		var_max_phase_resid,assign_credit, var_assign_credit, assign_cash,
		var_assign_cash, previsionkind, secprevisionkind,
		flag_assign_credit, flag_assign_cash, idman, manager	 
	FROM    #fin_situation 
	RETURN
END
DECLARE @level_input tinyint
SET  @level_input = ISNULL((SELECT nlevel from fin where idfin = @idfin) ,@nlevel)
-- ho scelto come livello 2 e poi ho specificato il capitolo, lui corregge @nlevel dandogli 3
IF (@nlevel < @level_input ) AND (@idfin is not null)
	BEGIN
	SET  @nlevel = @level_input
	END
DECLARE @fin_phase     tinyint
SELECT  @fin_phase = appropriationphasecode
FROM    config
WHERE   ayear = @ayear
IF 	@fin_phase IS NULL
BEGIN
	SELECT @fin_phase = expensefinphase FROM uniconfig
END
DECLARE @desc_fin_phase    	varchar(50)
SELECT 	@desc_fin_phase=description
FROM 	expensephase WHERE nphase=@fin_phase 
DECLARE @max_phase          	tinyint
SELECT  @max_phase = MAX(nphase)
FROM 	expensephase
DECLARE @desc_max_phase    	varchar(50)
SELECT  @desc_max_phase=description 
FROM 	expensephase WHERE nphase=@max_phase 
DECLARE @cashvaliditykind       int
SELECT 	@cashvaliditykind = cashvaliditykind
FROM 	config WHERE ayear = @ayear
DECLARE @previsionkind char(1) 
SELECT  @previsionkind =  
	 CASE 
		WHEN fin_kind IN (1,3) THEN 'C'
		WHEN fin_kind = 2 THEN 'S'
	 END
FROM  config 
WHERE config.ayear = @ayear
DECLARE @secprevisionkind    char(1) 
SELECT  @secprevisionkind  = 
	 CASE 
		WHEN fin_kind = 3 THEN 'S'
		ELSE 'N'
	END
FROM config 
WHERE config.ayear = @ayear
		
IF(@suppressifblank = 'S')
BEGIN
	INSERT INTO #fin_situation
		(
		idfin, 
		idman
		)
	SELECT  DISTINCT
		fin.idfin,
		finlast.idman
		FROM fin
		JOIN finlink
			ON  finlink.idparent = fin.idfin
		JOIN finlink FL
			ON  FL.idchild = fin.idfin AND FL.nlevel = fin.nlevel
		JOIN finlast
			ON finlink.idchild = finlast.idfin
		WHERE  ((fin.flag&1)=1) -- Spesa
			AND ((finlast.idman = @idman) OR (@idman is null and finlast.idman is not null))	
			AND fin.ayear = @ayear 
			AND (@idfin IS NULL OR FL.idparent = @idfin)
			AND ((@hierarchy ='N' and fin.nlevel = @nlevel) OR (@hierarchy ='S' and fin.nlevel >=  @nlevel))
			AND EXISTS (select idfin from upbtotal where idfin = fin.idfin) 	
			
	-- prende le voci di bilancio che hanno solo i residui
	INSERT INTO #fin_situation
		(
		idfin, 
		idman
		)
	SELECT  DISTINCT
		fin.idfin,
		finlast.idman
	FROM    fin	
		JOIN finlink
			ON  finlink.idparent = fin.idfin
		JOIN finlink FL
			ON  FL.idchild = fin.idfin
		JOIN finlast
			ON  finlink.idchild = finlast.idfin 
		JOIN expenseyear
			ON expenseyear.idfin = fin.idfin
		JOIN expensetotal
			ON  expenseyear.idexp = expensetotal.idexp
			AND expenseyear.ayear = expensetotal.ayear
	WHERE ((fin.flag&1)=1) -- Spesa
		AND ((finlast.idman = @idman) OR  (@idman is null and finlast.idman is not null))	
		AND fin.ayear = @ayear
		AND (@idfin IS NULL 
		OR  (FL.idparent = @idfin and @idfin is not null))
		AND ((@hierarchy ='N' and fin.nlevel = @nlevel) OR (@hierarchy ='S' and fin.nlevel >=  @nlevel))
		AND   expenseyear.ayear = @ayear 
		AND ((expensetotal.flag&1)=1)
		AND NOT EXISTS (SELECT *
				FROM  #fin_situation
				WHERE finlink.idparent = #fin_situation.idfin)
END
ELSE
BEGIN
	INSERT INTO #fin_situation
	(
		idfin, 
		idman
	)
	SELECT DISTINCT
		fin.idfin,
		finlast.idman
	FROM fin 
	JOIN finlink
		ON  finlink.idparent = fin.idfin
	JOIN finlink FL
		ON  FL.idchild = fin.idfin and FL.nlevel = fin.nlevel
	JOIN finlast
		ON  finlink.idchild = finlast.idfin 
	WHERE  ((fin.flag&1)=1) -- Spesa
		AND ((finlast.idman = @idman) OR  (@idman is null and finlast.idman is not null))	
		AND fin.ayear = @ayear 
		AND (@idfin IS NULL 
		OR  (FL.idparent = @idfin and @idfin is not null))
		AND ((@hierarchy ='N' and fin.nlevel = @nlevel) OR (@hierarchy ='S' and fin.nlevel >=  @nlevel))
END
-------------------------------------------------------------------------------		
UPDATE #fin_situation
	SET  main_initial_prevision =
		ISNULL((SELECT SUM(finyear.prevision)
			FROM finyear
			JOIN fin 
				ON finyear.idfin = fin.idfin
			JOIN finlast
				ON  finlast.idfin  = fin.idfin 
			JOIN finlink
				ON  finlink.idchild = fin.idfin   
				AND finlink.idparent = #fin_situation.idfin
			WHERE finlast.idman = #fin_situation.idman
			      AND fin.ayear = @ayear
			      AND finyear.ayear = @ayear), 0.0),
	var_main_prevision  =   
		ISNULL((SELECT SUM(finvardetail.amount) 
			FROM finvardetail
			JOIN finvar
				ON finvardetail.yvar = finvar.yvar 
				AND finvardetail.nvar = finvar.nvar
			JOIN finlast
				ON  finlast.idfin  = finvardetail.idfin 
			JOIN finlink
				ON  finlink.idchild = finvardetail.idfin   
				AND finlink.idparent = #fin_situation.idfin
			WHERE finlast.idman = #fin_situation.idman
			      AND finvar.idfinvarstatus = 5
			      AND finvar.yvar = @ayear		
			      AND finvar.flagprevision ='S'	
			      AND finvar.variationkind <> 5
			      AND finvar.adate between @start and @stop), 0.0),
	sec_initial_prevision = 	
		ISNULL((SELECT SUM(finyear.secondaryprev)
			FROM finyear
			JOIN finlast
				ON  finlast.idfin  = finyear.idfin 
			JOIN finlink
				ON  finlink.idchild = finyear.idfin   
				AND finlink.idparent = #fin_situation.idfin
			WHERE  finlast.idman = #fin_situation.idman
				AND finyear.ayear = @ayear), 0.0),
	varprevsec =
		ISNULL((SELECT SUM(finvardetail.amount) 
			FROM finvardetail
			JOIN finvar
				ON finvardetail.yvar = finvar.yvar 
				AND finvardetail.nvar = finvar.nvar
			JOIN finlast
				ON  finlast.idfin  = finvardetail.idfin 
			JOIN finlink
				ON  finlink.idchild = finvardetail.idfin
				AND finlink.idparent = #fin_situation.idfin
			WHERE finlast.idman = #fin_situation.idman	
			      AND finvar.idfinvarstatus = 5
			      AND finvar.yvar = @ayear 
			      AND finvar.flagsecondaryprev = 'S'
			      AND finvar.variationkind <> 5
			      AND finvar.adate between @start and @stop), 0.0)
UPDATE #fin_situation
	SET 
	fin_phase_comp = 
				ISNULL((SELECT SUM(expenseyear.amount)
			FROM expense
			JOIN expenseyear
				ON expenseyear.idexp = expense.idexp
			JOIN expensetotal
				ON expenseyear.idexp = expensetotal.idexp
				AND expenseyear.ayear = expensetotal.ayear
			JOIN finlast
				ON finlast.idfin = expenseyear.idfin 
			JOIN finlink
				ON finlink.idchild = expenseyear.idfin   
				AND finlink.idparent  = #fin_situation.idfin
			WHERE expense.adate between @start and @stop 
				AND expense.nphase = @fin_phase
				AND finlast.idman = #fin_situation.idman
				AND expenseyear.ayear = @ayear
				AND ((expensetotal.flag&1) = 0) -- Competenza
				), 0.0),
	var_fin_phase_comp =
				ISNULL((SELECT SUM(expensevar.amount)
			FROM expensevar
			JOIN expenseyear
				ON expenseyear.idexp = expensevar.idexp
			JOIN expense
				ON expenseyear.idexp = expense.idexp
			JOIN expensetotal
				ON  expenseyear.idexp = expensetotal.idexp
				AND expenseyear.ayear = expensetotal.ayear
			JOIN finlast
				ON  finlast.idfin  = expenseyear.idfin 
			JOIN finlink
				ON  finlink.idchild = expenseyear.idfin   
				AND finlink.idparent = #fin_situation.idfin
			WHERE expensevar.adate between @start and @stop 
				AND expenseyear.ayear = @ayear
				AND expense.nphase= @fin_phase
				AND ((expensetotal.flag&1) = 0) -- Competenza
				AND finlast.idman = #fin_situation.idman
				AND expensevar.yvar = @ayear), 0.0),
	 fin_phase_resid = 
				ISNULL((SELECT SUM(expenseyear.amount)
			FROM expense
			JOIN expenseyear
				ON expenseyear.idexp = expense.idexp
			JOIN expensetotal
				ON  expenseyear.idexp = expensetotal.idexp
				AND expenseyear.ayear = expensetotal.ayear
			JOIN finlast
				ON  finlast.idfin  = expenseyear.idfin 
			JOIN finlink
				ON  finlink.idchild = expenseyear.idfin   
				AND finlink.idparent = #fin_situation.idfin
			WHERE expense.adate between @start and @stop
				AND expenseyear.ayear = @ayear
				AND finlast.idman = #fin_situation.idman
				AND ((expensetotal.flag&1) = 1) -- Residuo
				AND expense.nphase = @fin_phase), 0.0),
	var_fin_phase_resid =
		ISNULL((SELECT SUM(expensevar.amount)
			FROM expensevar
			JOIN expenseyear
				ON expenseyear.idexp = expensevar.idexp
			JOIN expense
				ON expenseyear.idexp = expense.idexp
			JOIN expensetotal
				ON  expenseyear.idexp = expensetotal.idexp
				AND expenseyear.ayear = expensetotal.ayear
			JOIN finlast
				ON  finlast.idfin  = expenseyear.idfin 
			JOIN finlink
				ON  finlink.idchild = expenseyear.idfin   
			WHERE expensevar.adate between @start and @stop 
			     	AND expenseyear.ayear = @ayear
				AND expense.nphase= @fin_phase
				AND ((expensetotal.flag&1) = 1) -- Residuo
				AND finlink.idparent = #fin_situation.idfin
				AND finlast.idman = #fin_situation.idman
				AND expensevar.yvar = @ayear), 0.0)
--  GESTIONE DEL FONDO ECONOMALE 
UPDATE #fin_situation
	SET fin_phase_comp = 
		ISNULL(fin_phase_comp, 0.0) +
		ISNULL((SELECT SUM(operation.amount)
			FROM pettycashoperation operation
			JOIN finlast
				ON  finlast.idfin  = operation.idfin 
			JOIN finlink
				ON  finlink.idchild = operation.idfin   
			WHERE 	finlink.idparent = #fin_situation.idfin
				AND finlast.idman = #fin_situation.idman
				AND operation.adate between @start and @stop 
				AND operation.yoperation = @ayear
				AND NOT EXISTS (SELECT * FROM pettycashoperation  
						WHERE pettycashoperation.idpettycash = operation.idpettycash
						AND pettycashoperation.yoperation = operation.yrestore
						AND pettycashoperation.noperation = operation.nrestore
						AND pettycashoperation.adate between @start and @stop
						AND pettycashoperation.yoperation = @ayear)), 0.0)
UPDATE #fin_situation
	SET max_phase_comp=	 
		ISNULL((SELECT SUM(HPV.amount)
			FROM historypaymentview HPV
			JOIN finlast
				ON  finlast.idfin  = HPV.idfin 
			JOIN finlink
				ON  finlink.idchild = HPV.idfin   
				AND finlink.idparent = #fin_situation.idfin
			WHERE HPV.ymov = @ayear
				AND HPV.competencydate between @start and @stop
				AND ((HPV.totflag&1) = 0) -- Competenza
				AND finlast.idman = #fin_situation.idman
				), 0.0),
	   max_phase_resid=	 
			ISNULL((SELECT SUM(HPV.amount)
				FROM historypaymentview HPV
				JOIN finlast
					ON  finlast.idfin  = HPV.idfin 
				JOIN finlink
					ON  finlink.idchild = HPV.idfin   
					AND finlink.idparent = #fin_situation.idfin
				WHERE  HPV.ymov = @ayear
					AND finlast.idman = #fin_situation.idman
					AND HPV.competencydate between @start and @stop
					AND ((HPV.totflag&1) = 1) -- Residuo
					), 0.0)
IF @cashvaliditykind <> 4
BEGIN
	UPDATE #fin_situation
		SET  var_max_phase_comp= 
			ISNULL((SELECT SUM(expensevar.amount)
				FROM expensevar
				JOIN historypaymentview HPV
					ON HPV.idexp = expensevar.idexp
					AND HPV.ymov = @ayear 
				JOIN finlast
					ON  finlast.idfin  = HPV.idfin 
				JOIN finlink
					ON  finlink.idchild = HPV.idfin   
					AND finlink.idparent    = #fin_situation.idfin
				WHERE 	 finlast.idman = #fin_situation.idman
					AND expensevar.yvar = @ayear
					AND ((HPV.totflag&1) = 0) -- Competenza
					AND HPV.ymov = @ayear
					AND HPV.competencydate between @start and @stop
					AND expensevar.adate between @start and @stop), 0.0),
		var_max_phase_resid= 
			ISNULL((SELECT SUM(expensevar.amount)
				FROM expensevar
				JOIN historypaymentview HPV
					ON HPV.idexp = expensevar.idexp 
				JOIN finlast
					ON  finlast.idfin  = HPV.idfin 
				JOIN finlink
					ON  finlink.idchild = HPV.idfin  
					AND finlink.idparent = #fin_situation.idfin
				WHERE expensevar.yvar = @ayear
				    	AND finlast.idman = #fin_situation.idman
					AND finlink.idparent = #fin_situation.idfin
					AND ((HPV.totflag&1) = 1) -- Residuo
					AND HPV.ymov = @ayear
					AND HPV.competencydate between @start and @stop
					AND expensevar.adate between @start and @stop), 0.0)
END
-- Controlla che i CREDITI  siano gestiti
IF 	(EXISTS(SELECT* FROM creditpart
		WHERE ycreditpart = @ayear AND adate between @start and @stop) 
	OR
	EXISTS (SELECT * FROM finvar
		WHERE flagcredit ='S' and yvar = @ayear
		AND adate between @start and @stop
		AND finvar.idfinvarstatus = 5)
	)
BEGIN
	UPDATE #fin_situation
	SET var_assign_credit = 
		isnull((select SUM(d.amount)
			FROM finvardetail d
			JOIN finvar v 
				ON v.yvar = d.yvar
				AND v.nvar = d.nvar
				AND v.flagcredit ='S'
			JOIN finlast
				ON  finlast.idfin  = d.idfin 
			JOIN finlink
				ON  finlink.idchild = d.idfin   
			where 	finlink.idparent = #fin_situation.idfin
				AND finvar.idfinvarstatus = 5
				AND finlast.idman = #fin_situation.idman	
				AND v.adate between @start and @stop
				AND v.variationkind IN (2,3)),0.0),
	  assign_credit = 	
		isnull((select SUM(creditpart.amount)
			FROM creditpart 
			JOIN incomeyear
				on creditpart.idinc = incomeyear.idinc
				and creditpart.ycreditpart = incomeyear.ayear
			JOIN finlast
				ON  finlast.idfin  = creditpart.idfin 
			JOIN finlink
				ON  finlink.idchild = creditpart.idfin   
			where 	finlink.idparent = #fin_situation.idfin
				AND finlast.idman = #fin_situation.idman
				AND adate between @start and @stop),0.0)
		+	
		isnull((select SUM(d.amount)
			FROM finvardetail d
			JOIN finvar v
				ON v.yvar = d.yvar
				AND v.nvar = d.nvar
				AND v.flagcredit ='S'
			JOIN finlast
				ON  finlast.idfin  = d.idfin 
			JOIN finlink
				ON  finlink.idchild = d.idfin   
			where 	finlink.idparent = #fin_situation.idfin
				AND finvar.idfinvarstatus = 5
				AND finlast.idman = #fin_situation.idman
				AND v.adate between @start and @stop
				AND v.variationkind IN (1,4)),0.0),
	flag_assign_credit='S'
END
ELSE
	UPDATE #fin_situation SET flag_assign_credit='N'
-- Controlla che gli max_phase siano gestiti
IF 	(EXISTS(SELECT* FROM proceedspart 
		WHERE yproceedspart	= @ayear
		AND adate between @start and @stop) 
	OR
	EXISTS (SELECT * FROM finvar
		WHERE flagproceeds='S' and 
		yvar = @ayear AND 
		adate between @start and @stop
		AND finvar.idfinvarstatus = 5)
	)
	BEGIN
	UPDATE #fin_situation
		SET var_assign_cash = 
			isnull(( select SUM(d.amount)
				FROM finvardetail d
				JOIN finvar v
					ON v.yvar = d.yvar
					AND v.nvar = d.nvar
				JOIN finlast
					ON  finlast.idfin  = d.idfin 
				JOIN finlink
					ON  finlink.idchild = d.idfin   
				where finlink.idparent = #fin_situation.idfin
					AND v.idfinvarstatus = 5
					AND finlast.idman = #fin_situation.idman
					AND v.flagproceeds='S'
					AND v.adate between @start and @stop
					AND v.variationkind IN (2,3)),0.0),
		assign_cash = 
			isnull(( select SUM(proceedspart.amount)
				FROM proceedspart
				JOIN incomeyear
					on proceedspart.idinc = incomeyear.idinc
					and proceedspart.yproceedspart = incomeyear.ayear
				JOIN finlast
					ON  finlast.idfin  = proceedspart.idfin 
				JOIN finlink
					ON  finlink.idchild = proceedspart.idfin  
				where finlink.idparent = #fin_situation.idfin
					AND finlast.idman = #fin_situation.idman
					AND adate between @start and @stop),0.0)
			+
			isnull((SELECT  SUM(d.amount)
				FROM finvardetail d
				JOIN finvar v
					ON v.yvar = d.yvar
					AND v.nvar = d.nvar
				JOIN finlast
					ON  finlast.idfin  = d.idfin 
				JOIN finlink
					ON  finlink.idchild = d.idfin  
				where finlink.idparent = #fin_situation.idfin
					AND v.idfinvarstatus = 5
					AND finlast.idman = #fin_situation.idman
					AND v.flagproceeds='S'
					AND v.adate between @start and @stop
					AND v.variationkind IN (1,4)),0.0),
		flag_assign_cash='S'
	END
ELSE
	UPDATE #fin_situation SET flag_assign_cash='N'

--> cancella le righe sottostanti la categoria 
IF (@suppressifblank = 'S') 	
BEGIN
	DELETE FROM #fin_situation 
	WHERE 
		(isnull(main_initial_prevision,0.0) =0 AND 
		isnull(var_main_prevision,0.0) =0 AND 
		isnull(fin_phase_comp,0.0) =0 AND 
		isnull(var_fin_phase_comp,0.0) =0 AND 
		isnull(max_phase_comp,0.0) =0 AND 
		isnull(var_max_phase_comp,0.0) =0 AND 
		isnull(sec_initial_prevision,0.0) =0 AND 
		isnull(varprevsec,0.0) =0 AND 
		isnull(fin_phase_resid,0.0) =0 AND 
		isnull(var_fin_phase_resid,0.0) =0 AND 
		isnull(max_phase_resid,0.0) =0 AND 
		isnull(var_max_phase_resid,0.0) =0 AND 
		isnull(assign_credit,0.0) =0 AND 
		isnull(var_assign_credit,0.0) =0 AND 
		isnull(assign_cash,0.0) =0 AND 
		isnull(var_assign_cash,0.0) =0 
		AND nlevel >=2)
END

SELECT 
	#fin_situation.idfin,	
	fin.codefin,	
	fin.title,	
	fin.printingorder as finprintingorder,	
	fin.nlevel,		
	sum(isnull(main_initial_prevision,0.0)) as 'main_initial_prevision',
	sum(isnull(var_main_prevision,0.0)) 	as 'var_main_prevision'	,
	sum(isnull(fin_phase_comp,0.0)) 	as 'fin_phase_comp',
	sum(isnull(var_fin_phase_comp,0.0)) 	as 'var_fin_phase_comp',
	@desc_fin_phase 			as'desc_fin_phase',					
	sum(isnull(max_phase_comp,0.0)) 	as 'max_phase_comp',
	sum(isnull(var_max_phase_comp,0.0)) 	as 'var_max_phase_comp',
	@desc_max_phase 			as 'desc_max_phase',					
	sum(isnull(sec_initial_prevision,0.0)) 	as 'sec_initial_prevision',
	sum(isnull(varprevsec,0.0)) 		as 'varprevsec',
	sum(isnull(fin_phase_resid,0.0)) 	as 'fin_phase_resid',
	sum(isnull(var_fin_phase_resid,0.0)) 	as 'var_fin_phase_resid',
	sum(isnull(max_phase_resid,0.0)) 	as 'max_phase_resid' ,
	sum(isnull(var_max_phase_resid,0.0)) 	as 'var_max_phase_resid' ,
	sum(isnull(assign_credit,0.0)) 		as 'assign_credit',
	sum(isnull(var_assign_credit,0.0)) 	as 'var_assign_credit' ,
	sum(isnull(assign_cash,0.0)) 		as 'assign_cash'	 ,
	sum(isnull(var_assign_cash,0.0)) 	as 'var_assign_cash'	 ,
	@previsionkind 				as 'previsionkind',
	@secprevisionkind 			as 'secprevisionkind',
	flag_assign_credit,
	flag_assign_cash,
	#fin_situation.idman,
	manager.title as manager	
 	FROM #fin_situation
	JOIN fin ON fin.idfin = #fin_situation.idfin
	JOIN manager ON manager.idman = #fin_situation.idman
	GROUP BY #fin_situation.idfin,fin.codefin,	
	fin.title,fin.printingorder,fin.nlevel,flag_assign_credit,flag_assign_cash,#fin_situation.idman,manager.title		
	ORDER BY #fin_situation.idman,fin.printingorder
END

GO

print '[rpt_sitbilancioarticoli_respons_operation_2fasi] OK'

GO
if object_id('[esporta_accessori_non_caricati]') is not null
	drop PROCEDURE [esporta_accessori_non_caricati]
go


CREATE                     PROCEDURE [esporta_accessori_non_caricati]  
AS BEGIN
SELECT 
	accessorio.idasset 		AS 'Idasset',
	accessorio.idpiece 		AS 'Idpiece',
	accessorio.lifestart 		AS 'Data Creazione Cespite', 
	accessorio.cu 			AS 'Creato da' , 
	b.idinventory   		AS 'Codice Inventario', 
	ti.description			AS 'Tipo Inventario',
	cespite.ninventory 		AS 'Num. inventario Cespite',
	accessorio.nassetacquire 	AS 'Carico Accessorio', 
	assetunloadkind.codeassetunloadkind 	AS 'Tipo Buono Scarico',
	assetunload.yassetunload 	AS 'Eserc. Buono Scarico',
	assetunload.nassetunload 	AS 'Num. Buono Scarico'
FROM  asset accessorio 
left outer join assetunload on accessorio.idassetunload=assetunload.idassetunload
left outer join assetunloadkind on assetunloadkind.idassetunloadkind=assetunload.idassetunloadkind
JOIN  asset cespite ON accessorio.idasset = cespite.idasset
JOIN  assetacquire b ON cespite.nassetacquire=b.nassetacquire
LEFT  OUTER JOIN inventory  
	ON b.idinventory=inventory.idinventory
LEFT  OUTER JOIN inventorykind ti
	ON inventory.idinventorykind= ti.idinventorykind   
WHERE accessorio.idpiece >1 and cespite.idpiece = 1
     	AND accessorio.nassetacquire IS NULL
ORDER BY accessorio.idasset,accessorio.idpiece
END


GO

print '[esporta_accessori_non_caricati] OK'

GO
if object_id('calc_csaimport') is not null
	drop PROCEDURE calc_csaimport
go

CREATE    PROCEDURE calc_csaimport
(
	@idcsa_import int,
	@ayear smallint
)
AS 
BEGIN
----------------------------------------------------------------
------- ELABORAZIONE VERSAMENTI,  TABELLA CSA_IMPORTVER --------
----------------------------------------------------------------
update csa_importver set ayear= @ayear
update csa_importver set competency=  convert(int,competenza)
update csa_importver set flagcr= 'C' where competency= @ayear and flagcr is null
update csa_importver set flagcr= 'R' where competency< @ayear and flagcr is null
--calcola idcsa_contractkind (caso tutti e due not null)
update csa_importver  set 
	idcsa_contractkind= csa_contractkind.idcsa_contractkind
	FROM csa_importver  
	JOIN csa_contractkindrules
		ON  csa_importver.capitolocsa=  csa_contractkindrules.capitolocsa 
		AND csa_importver.ruolocsa=  csa_contractkindrules.ruolocsa
	JOIN csa_contractkind
		ON csa_contractkindrules.idcsa_contractkind=csa_contractkind.idcsa_contractkind
		AND csa_importver.flagcr = csa_contractkind.flagcr	 
	JOIN csa_contractkindyear
		ON csa_contractkindyear.idcsa_contractkind=csa_contractkind.idcsa_contractkind
	WHERE 	csa_importver.idcsa_contractkind is null
		AND csa_importver.idcsa_import = @idcsa_import
		AND csa_contractkindyear.ayear=@ayear
		AND csa_contractkindrules.ayear=@ayear
		AND isnull(csa_contractkind.active, 'N')='S'
--calcola idcsa_contractkind (caso capitolocsa null)
update csa_importver  set idcsa_contractkind= csa_contractkind.idcsa_contractkind
	FROM csa_importver  
	JOIN csa_contractkindrules
		ON  csa_importver.ruolocsa=  csa_contractkindrules.ruolocsa
	JOIN csa_contractkind
		ON csa_contractkindrules.idcsa_contractkind=csa_contractkind.idcsa_contractkind
		AND csa_importver.flagcr = csa_contractkind.flagcr	
	JOIN csa_contractkindyear
		ON csa_contractkindyear.idcsa_contractkind=csa_contractkind.idcsa_contractkind
	WHERE   csa_importver.idcsa_contractkind is null
		AND csa_importver.idcsa_import = @idcsa_import
		AND csa_contractkindrules.capitolocsa is null
		AND csa_contractkindyear.ayear=@ayear
		AND csa_contractkindrules.ayear=@ayear
		AND isnull(csa_contractkind.active, 'N')='S'
--calcola idcsa_contractkind (caso ruolocsa null)
update csa_importver  set idcsa_contractkind= csa_contractkind.idcsa_contractkind
	FROM csa_importver  
	JOIN csa_contractkindrules
		ON  csa_importver.capitolocsa=  csa_contractkindrules.capitolocsa 
	JOIN csa_contractkind
		ON csa_contractkindrules.idcsa_contractkind=csa_contractkind.idcsa_contractkind
		AND csa_importver.flagcr = csa_contractkind.flagcr	
	JOIN csa_contractkindyear
		ON csa_contractkindyear.idcsa_contractkind=csa_contractkind.idcsa_contractkind
	WHERE 	csa_importver.idcsa_contractkind is null
		AND csa_importver.idcsa_import = @idcsa_import
		AND csa_contractkindrules.ruolocsa is null
		AND csa_contractkindyear.ayear=@ayear
		AND csa_contractkindrules.ayear=@ayear
		AND isnull(csa_contractkind.active, 'N')='S'
--calcola idcsa_contract ove trova un match con la matricola
update csa_importver set idcsa_contract = csa_contract.idcsa_contract,
		idreg= csa_contractregistry.idreg 
	FROM csa_importver
	JOIN csa_contract 
		ON   csa_contract.idcsa_contractkind = csa_importver.idcsa_contractkind		
		AND csa_contract.ycontract = csa_importver.competency
	JOIN csa_contractregistry
		ON csa_contract.idcsa_contract= csa_contractregistry.idcsa_contract
		AND csa_contract.ayear= csa_contractregistry.ayear
	WHERE 	csa_importver.idcsa_contract is null
		AND csa_importver.idcsa_contractkind is not null
		AND csa_contract.ayear=@ayear
		AND csa_contractregistry.extmatricula=csa_importver.matricola		
		AND csa_importver.idcsa_import = @idcsa_import
		AND isnull(csa_contract.active, 'N')='S'
--calcola idcsa_contract ove trova un match con contratti senza matricole
 update csa_importver set 
		idcsa_contract = csa_contract.idcsa_contract
 FROM   csa_importver
 JOIN   csa_contract 
   ON   csa_contract.idcsa_contractkind = csa_importver.idcsa_contractkind		
 		AND csa_contract.ycontract = csa_importver.competency
   WHERE 	csa_importver.idcsa_contract is null
		AND csa_importver.idcsa_contractkind is not null
		AND csa_contract.ayear=@ayear
		AND csa_importver.idcsa_import = @idcsa_import
		AND (SELECT COUNT(*) from csa_contractregistry C where 
			 C.idcsa_contract=csa_contract.idcsa_contract)=0
		AND isnull(csa_contract.active, 'N')='S'
 --Calcolo enti (idcsa_agency)  in base a campo ENTE
 update csa_importver set idcsa_agency = csa_agency.idcsa_agency, 
			flagclawback=csa_agency.isinternal,
			idreg_agency= csa_agency.idreg
	FROM csa_importver JOIN csa_agency 
			ON csa_importver.ente= csa_agency.ente 
	WHERE csa_importver.idcsa_agency IS NULL
		AND csa_importver.idcsa_import = @idcsa_import

--Calcolo mod.pagamento (idcsa_agencymethod)  in base a campo ENTE e VOCE CSA
update csa_importver set idcsa_agencypaymethod= csa_agencypaymethod.idcsa_agencypaymethod
	from csa_importver JOIN csa_agencypaymethod 
			ON csa_importver.idcsa_agency= csa_agencypaymethod.idcsa_agency
			AND csa_importver.vocecsa= csa_agencypaymethod.vocecsa
	WHERE csa_importver.idcsa_agency IS NOT NULL 
		AND  csa_importver.idcsa_agencypaymethod IS NULL
		AND csa_importver.idcsa_import = @idcsa_import
--ASSOCIA IL FINANZIAMENTO O DA CONTRATTO O DA TIPO CONTRATTO
update csa_importver set idunderwriting = csa_contract.idunderwriting
from csa_importver JOIN csa_contract
  ON   csa_contract.idcsa_contractkind = csa_importver.idcsa_contractkind	
 AND  csa_contract.idcsa_contract  = csa_importver.idcsa_contract 	
 AND csa_contract.ycontract = csa_importver.competency
where  csa_importver.idunderwriting is null and csa_importver.idcsa_contract is not null
AND csa_importver.idcsa_import = @idcsa_import
update csa_importver set idunderwriting = csa_contractkind.idunderwriting
from csa_importver JOIN csa_contractkind
  ON   csa_contractkind.idcsa_contractkind = csa_importver.idcsa_contractkind	
where  csa_importver.idunderwriting is null and csa_importver.idcsa_contractkind is not null
AND csa_importver.idcsa_import = @idcsa_import

-- se non ha individuato l'ente assegno un default pari a N a flagclawback
UPDATE csa_importver SET flagclawback = 'N' where flagclawback is null
--NOTA: per i recuperi "DIRETTI" (ove manca cap. di spesa) questo passo potrebbe non trovare la modalità o trovarne una fittizia			  
--caso CONTRIBUTI/RECUPERI - A : valorizzo idfin_cost, idacc_cost, idexp_cost da csa_contract se trovo corrispondenza con vocecsa e idcsa_contract e anno
UPDATE csa_importver SET 
		idfin_cost = csa_contracttax.idfin ,
		idsor_siope_cost = csa_contracttax.idsor_siope,
		idacc_cost = csa_contracttax.idacc ,
		idexp_cost = csa_contracttax.idexp ,
		idupb      = csa_contracttax.idupb,
		idcsa_contracttax=csa_contracttax.idcsa_contracttax
	FROM csa_importver
	JOIN csa_contracttax 
		ON csa_importver.idcsa_contract=csa_contracttax.idcsa_contract
		AND csa_importver.vocecsa= csa_contracttax.vocecsa
WHERE  	csa_importver.idcsa_contracttax is null
		AND	csa_contracttax.ayear =  @ayear
		AND csa_importver.idcsa_import = @idcsa_import
		
--caso CONTRIBUTI/RECUPERI - B : valorizzo idfin_cost, idacc_cost  da csa_contractkind se trovo corrispondenza con vocecsa e idcsa_contractkind e anno
UPDATE csa_importver SET 
		idfin_cost = csa_contractkinddata.idfin ,
		idsor_siope_cost = csa_contractkinddata.idsor_siope,
		idacc_cost = csa_contractkinddata.idacc, 
		idupb      = csa_contractkinddata.idupb,
		idcsa_contractkinddata=csa_contractkinddata.idcsa_contractkinddata
	FROM csa_importver
	JOIN csa_contractkinddata 
		ON csa_importver.idcsa_contractkind=csa_contractkinddata.idcsa_contractkind		
		AND csa_importver.vocecsa= csa_contractkinddata.vocecsa		
WHERE  	
	idcsa_contracttax is null
	AND csa_contractkinddata.ayear = @ayear
	AND csa_importver.idcsa_import = @idcsa_import

-- caso RITENUTE / CONTRIBUTI / RECUPERI
UPDATE csa_importver SET 		
	idfin_income  =  csa_incomesetup.idfin_income,
	idsor_siope_income  =  csa_incomesetup.idsor_siope_income,
	idacc_debit   =  csa_incomesetup.idacc_debit,	
	idfin_expense = csa_incomesetup.idfin_expense,
	idsor_siope_expense = csa_incomesetup.idsor_siope_expense,
	idacc_expense = csa_incomesetup.idacc_expense,
	idfin_incomeclawback = csa_incomesetup.idfin_incomeclawback,
	idsor_siope_incomeclawback = csa_incomesetup.idsor_siope_incomeclawback,
	idacc_internalcredit = csa_incomesetup.idacc_internalcredit,
	idacc_revenue =  csa_incomesetup.idacc_revenue,
	idacc_agency_credit = csa_incomesetup.idacc_agency_credit,
	idcsa_incomesetup = csa_incomesetup.idcsa_incomesetup
	from csa_importver
	JOIN csa_incomesetup
		ON csa_importver.vocecsa=csa_incomesetup.vocecsa
		AND csa_importver.ayear=csa_incomesetup.ayear		
WHERE  	csa_importver.idcsa_incomesetup is null 
AND		csa_importver.idcsa_import = @idcsa_import
-- RECUPERO, valorizzo il campo idupb, sulla base della scheda conf. incassi CSA individuata
-- Se si tratta di un recupero su partita di giro. L'upb sarà usato per il
-- movimento finanziario di entrata post-versamento
-- Se si tratta di un recupero diretto, allora sarà usato per l'incasso diretto (fase lordi)
DECLARE @flagdirectcsaclawback char(1)  -- configurazione gestione recupero CSA
-- IN PRIMA ISTANZA SI CONSIDERA IL FLAG SPECIFICO DI csa_incomesetup, SE NON è VALORIZZATO SI PRENDE
-- IL FLAG DI CONFIG, SE E' NULL SI CONSIDERA N
SELECT 
		@flagdirectcsaclawback = flagdirectcsaclawback
FROM config
WHERE ayear = @ayear
UPDATE csa_importver SET 
       idupb = csa_incomesetup.idupb,
	   flagdirectcsaclawback = ISNULL(csa_incomesetup.flagdirectcsaclawback,ISNULL(@flagdirectcsaclawback,'N'))
FROM   csa_incomesetup
WHERE  csa_importver.idcsa_incomesetup = csa_incomesetup.idcsa_incomesetup
AND	   csa_importver.ayear = csa_incomesetup.ayear
AND    csa_incomesetup.idupb IS NOT NULL 
AND	   ISNULL(csa_importver.flagclawback,'N') = 'S'
AND (
	(ISNULL(csa_incomesetup.flagdirectcsaclawback,ISNULL(@flagdirectcsaclawback,'N'))= 'N' AND csa_importver.idfin_income IS NOT NULL) OR 
	(ISNULL(csa_incomesetup.flagdirectcsaclawback,ISNULL(@flagdirectcsaclawback,'N'))= 'S' AND csa_importver.idfin_incomeclawback IS NOT NULL) 
	)
AND    csa_importver.idcsa_import = @idcsa_import
-- IN CASO DI CONTRIBUTI FIGURATIVI, EVENTUALMENTE ASSOCIATI A ENTE INTERNO  CONTROLLO idcsa_incomesetup, 
-- SE NON è VALORIZZATO LA RIGA NON DEVE ESSERE TRATTATA  COME RECUPERO IN QUANTO NON ESISTE 
-- LA RELATIVA SCHEDA CONFIGURAZIONE INCASSI
 
UPDATE csa_importver 
	SET csa_importver.flagclawback = 'N'
WHERE ISNULL(csa_importver.flagclawback,'N') = 'S'
AND idcsa_incomesetup IS NULL

-- caso CONTRIBUTI/RITENUTE  - C : valorizzo idupb  
-- da csa_contract (le voci principali del  contratto) , 
-- in mancanza dell'upb in una di scheda contributi più specifica 
UPDATE csa_importver SET 
	idupb      = csa_contract.idupb
	FROM csa_importver
	JOIN csa_contract 
		ON csa_importver.idcsa_contract=csa_contract.idcsa_contract	
WHERE  	
	idcsa_contracttax IS NULL AND idcsa_contractkinddata IS NULL 
	AND	ISNULL(csa_importver.flagclawback,'N') = 'N'
	AND csa_importver.idupb IS NULL
	AND csa_importver.idcsa_import = @idcsa_import
	AND csa_contract.ayear=@ayear

-- caso CONTRIBUTI/RITENUTE - D : valorizzo idupb  
-- da csa_contractkindyear (le voci principali del tipo contratto) , 
-- in mancanza dell'upb in una di scheda contributi più specifica 
update csa_importver SET 
		idupb      = csa_contractkindyear.idupb
	from csa_importver
	JOIN csa_contractkindyear 
		ON csa_importver.idcsa_contractkind=csa_contractkindyear.idcsa_contractkind		
WHERE  	
	idcsa_contracttax IS NULL  AND idcsa_contractkinddata IS NULL 
	AND csa_importver.idupb IS NULL 
	AND	ISNULL(csa_importver.flagclawback,'N') = 'N'
    AND csa_importver.idcsa_import = @idcsa_import
	AND csa_contractkindyear.ayear = @ayear
 --------------------------------------------------------
 ------- ELABORAZIONE LORDI , TABELLA CSA_IMPORTRIEP
 --------------------------------------------------------
update csa_importriep set ayear=  @ayear
update csa_importriep set competency=  convert(int,competenza)
update csa_importriep set flagcr= 'C' where competency= @ayear and flagcr is null
update csa_importriep set flagcr= 'R' where competency< @ayear and flagcr is null
--calcola idcsa_contractkind (caso tutti e due not null)
update csa_importriep  set idcsa_contractkind= csa_contractkind.idcsa_contractkind,
			idfin = csa_contractkindyear.idfin_main  ,
			idsor_siope = csa_contractkindyear.idsor_siope_main,
			idacc = csa_contractkindyear.idacc_main ,
			idupb = csa_contractkindyear.idupb ,
			idunderwriting = csa_contractkind.idunderwriting
	FROM csa_importriep  
	JOIN csa_contractkindrules
		ON  csa_importriep.capitolocsa=  csa_contractkindrules.capitolocsa 
		AND csa_importriep.ruolocsa=  csa_contractkindrules.ruolocsa
	JOIN csa_contractkind
		ON csa_contractkindrules.idcsa_contractkind=csa_contractkind.idcsa_contractkind
		AND csa_importriep.flagcr = csa_contractkind.flagcr	 
	JOIN csa_contractkindyear
		ON csa_contractkindyear.idcsa_contractkind=csa_contractkind.idcsa_contractkind
	WHERE csa_importriep.idcsa_contractkind is null
		AND csa_contractkindyear.ayear=@ayear
		AND csa_contractkindrules.ayear=@ayear
		AND csa_importriep.idcsa_import = @idcsa_import
		AND isnull(csa_contractkind.active, 'N')='S'
--calcola idcsa_contractkind (caso capitolocsa null)
update csa_importriep  set idcsa_contractkind= csa_contractkind.idcsa_contractkind,
			idfin = csa_contractkindyear.idfin_main  ,
			idsor_siope = csa_contractkindyear.idsor_siope_main,
			idacc = csa_contractkindyear.idacc_main ,
			idupb = csa_contractkindyear.idupb ,
			idunderwriting = csa_contractkind.idunderwriting
	FROM csa_importriep  
	JOIN csa_contractkindrules
		ON  csa_importriep.ruolocsa=  csa_contractkindrules.ruolocsa
	JOIN csa_contractkind
		ON csa_contractkindrules.idcsa_contractkind=csa_contractkind.idcsa_contractkind
		AND csa_importriep.flagcr = csa_contractkind.flagcr	
	JOIN csa_contractkindyear
		ON csa_contractkindyear.idcsa_contractkind=csa_contractkind.idcsa_contractkind
	WHERE csa_importriep.idcsa_contractkind is null
		AND csa_contractkindyear.ayear=@ayear
		AND csa_importriep.idcsa_import = @idcsa_import
		AND csa_contractkindrules.capitolocsa is null
		AND csa_contractkindrules.ayear=@ayear
		AND isnull(csa_contractkind.active, 'N')='S'
--calcola idcsa_contractkind (caso ruolocsa null)
update csa_importriep  set idcsa_contractkind= csa_contractkind.idcsa_contractkind,
			idfin = csa_contractkindyear.idfin_main  ,
			idsor_siope = csa_contractkindyear.idsor_siope_main,
			idacc = csa_contractkindyear.idacc_main ,
			idupb = csa_contractkindyear.idupb ,
			idunderwriting = csa_contractkind.idunderwriting
	FROM csa_importriep  
	JOIN csa_contractkindrules
		ON  csa_importriep.capitolocsa=  csa_contractkindrules.capitolocsa 
	JOIN csa_contractkind
		ON csa_contractkindrules.idcsa_contractkind=csa_contractkind.idcsa_contractkind
		AND csa_importriep.flagcr = csa_contractkind.flagcr	
	JOIN csa_contractkindyear
		ON csa_contractkindyear.idcsa_contractkind=csa_contractkind.idcsa_contractkind
	WHERE csa_importriep.idcsa_contractkind is null
		AND csa_contractkindyear.ayear=@ayear
		AND csa_importriep.idcsa_import = @idcsa_import
		AND csa_contractkindrules.ruolocsa is null
		AND csa_contractkindrules.ayear=@ayear
		AND isnull(csa_contractkind.active, 'N')='S'
--calcola idcsa_contract ove trova un match con la matricola
update csa_importriep set idcsa_contract = csa_contract.idcsa_contract,
			idexp= csa_contract.idexp_main,
			idfin= csa_contract.idfin_main,
			idsor_siope = csa_contract.idsor_siope_main,
			idacc= csa_contract.idacc_main,
			idupb= csa_contract.idupb,
			idreg= csa_contractregistry.idreg,
			idunderwriting = csa_contract.idunderwriting
	FROM csa_importriep
	JOIN csa_contract 
		ON   csa_contract.idcsa_contractkind = csa_importriep.idcsa_contractkind		
		AND   csa_contract.ycontract = csa_importriep.competency	
	JOIN csa_contractregistry
		ON csa_contract.idcsa_contract= csa_contractregistry.idcsa_contract
		AND csa_contract.ayear= csa_contractregistry.ayear
	WHERE 	csa_importriep.idcsa_contract is null
		AND csa_importriep.idcsa_contractkind is not null
		AND csa_contract.ayear=@ayear
		AND csa_contractregistry.extmatricula=csa_importriep.matricola		
		AND csa_importriep.idcsa_import = @idcsa_import
		AND csa_contractregistry.ayear=@ayear
		AND isnull(csa_contract.active, 'N')='S'

--calcola idcsa_contract ove trova un match con contratti senza matricole
update csa_importriep set idcsa_contract = csa_contract.idcsa_contract,
			idexp= csa_contract.idexp_main,
			idfin= csa_contract.idfin_main,
			idsor_siope = csa_contract.idsor_siope_main,
			idacc= csa_contract.idacc_main,
			idupb= csa_contract.idupb ,
			idunderwriting = csa_contract.idunderwriting
			--,idreg= csa_contractregistry.idreg
	FROM csa_importriep
	JOIN csa_contract 
		ON   csa_contract.idcsa_contractkind = csa_importriep.idcsa_contractkind		
		AND   csa_contract.ycontract = csa_importriep.competency	
    WHERE 	csa_importriep.idcsa_contract is null
		AND csa_importriep.idcsa_contractkind is not null
		AND csa_contract.ayear=@ayear
		AND csa_importriep.idcsa_import = @idcsa_import
		AND (SELECT COUNT(*) from csa_contractregistry C where C.idcsa_contract=csa_contract.idcsa_contract)=0
		AND isnull(csa_contract.active, 'N')='S'
END

