print '[exp_modello770_13_h] OK'

GO
if object_id('[rpt_sitbilancioarticoli_respons_spesa]') is not null
	drop PROCEDURE [rpt_sitbilancioarticoli_respons_spesa]
go


CREATE    PROCEDURE [rpt_sitbilancioarticoli_respons_spesa]
	@ayear			int,
	@nlevel			tinyint,
	@hierarchy		char(1),
	@idman			int,
	@suppressifblank 	char(1),
	@codefin		varchar(50),
	@start datetime,
	@stop datetime
AS
BEGIN
/* Versione 1.0.5 del 27/11/2007 ultima modifica: MARIA */
DECLARE @idfin int
IF (@codefin IS NULL OR @codefin = '' OR @codefin = '%')
	BEGIN
		SET @idfin = null	
	END
Else
	BEGIN
	   	SET @idfin = (select idfin 
				from fin 
				where codefin = @codefin 
				and ayear=@ayear 
				and (fin.flag&1)=1) -- Spesa
	END
CREATE TABLE #fin_situation
(
	idfin				int,
	codefin				varchar(50),
	title				varchar(150),
	finprintingorder		varchar(50),
	nlevel				tinyint,
	main_initial_prevision		decimal(19,2),
	var_main_prevision		decimal(19,2),
	fin_phase_comp			decimal(19,2),
	var_fin_phase_comp		decimal(19,2), 
	desc_fin_phase 			varchar(50),					
	registry_phase_comp		decimal(19,2),
	var_registry_phase_comp		decimal(19,2),
	desc_registry_phase 		varchar(50),					
	max_phase_comp       		decimal(19,2),
	var_max_phase_comp     	 	decimal(19,2),
	desc_max_phase 			varchar(50),					
	sec_initial_prevision		decimal(19,2),
	varprevsec			decimal(19,2),
	fin_phase_resid			decimal(19,2), 
	var_fin_phase_resid		decimal(19,2),
	registry_phase_resid		decimal(19,2),
	var_registry_phase_resid	decimal(19,2),
	max_phase_resid         	decimal(19,2),
	var_max_phase_resid          	decimal(19,2),
	assign_credit 			decimal(19,2),
	var_assign_credit		decimal(19,2),
	assign_cash			decimal(19,2),
	var_assign_cash			decimal(19,2),
	previsionkind 			char(1),
	secprevisionkind 		char(1),
	flag_assign_credit 		char(1),
	flag_assign_cash 		char(1),
	idman				int,
	manager				varchar(150)						
)
IF @ayear IS NULL 
BEGIN
	SELECT 		
		idfin,
		NULL as idfinlevel0, NULL as idfinlevel1, NULL as idfinlevel2,
		NULL as idfinlevel3, NULL as idfinlevel4, NULL as idfinlevel5,
		NULL as idfinlevel6, NULL as idfinlevel7, NULL as idfinlevel8,
		NULL as idfinlevel9, codefin, title, finprintingorder,	
		nlevel, main_initial_prevision, var_main_prevision,
		fin_phase_comp, var_fin_phase_comp, desc_fin_phase,
		registry_phase_comp, var_registry_phase_comp,
		desc_registry_phase, max_phase_comp, var_max_phase_comp,
		desc_max_phase,	sec_initial_prevision, varprevsec,
		fin_phase_resid, var_fin_phase_resid, registry_phase_resid,
		var_registry_phase_resid, max_phase_resid,var_max_phase_resid,
		assign_credit, var_assign_credit, assign_cash,
		var_assign_cash, previsionkind, secprevisionkind,
		flag_assign_credit, flag_assign_cash, idman, manager	 
	FROM    #fin_situation 
	RETURN
END
DECLARE @level_input tinyint
SET  @level_input = ISNULL((SELECT nlevel from fin where idfin = @idfin) ,@nlevel)
-- ho scelto come livello 2 e poi ho specificato il capitolo, lui corregge @nlevel dandogli 3
IF (@nlevel < @level_input ) AND (@idfin is not null)
	BEGIN
	SET  @nlevel = @level_input
	END
DECLARE @fin_phase   		tinyint -- accantonamento precedente alla fase di impegno, Modifica Sara
SELECT  @fin_phase = expensefinphase FROM uniconfig
DECLARE @desc_fin_phase     	varchar(50)
SELECT  @desc_fin_phase=description
FROM 	expensephase WHERE nphase=@fin_phase 
DECLARE @registry_phase     	tinyint
SELECT  @registry_phase = expenseregphase FROM uniconfig
DECLARE @desc_registry_phase    varchar(50)
SELECT 	@desc_registry_phase=description
FROM 	expensephase WHERE nphase=@registry_phase 
DECLARE @max_phase          	tinyint
SELECT  @max_phase = MAX(nphase) FROM expensephase
DECLARE @desc_max_phase    	varchar(50)
SELECT  @desc_max_phase=description 
FROM 	expensephase WHERE nphase=@max_phase 
DECLARE @flag_cs     		char(1)
SELECT 	@flag_cs = CASE 
		WHEN fin_kind IN (1,3) THEN 'C'
		WHEN fin_kind = 2 THEN 'S'
	 END
FROM 	config
WHERE 	ayear = @ayear
DECLARE @cashvaliditykind	int
SELECT 	@cashvaliditykind = cashvaliditykind
FROM 	config
WHERE 	ayear = @ayear
DECLARE @previsionkind char(1) 
SELECT  @previsionkind =  
	 CASE 
		WHEN fin_kind IN (1,3) THEN 'C'
		WHEN fin_kind = 2 THEN 'S'
	 END
FROM  config 
WHERE config.ayear = @ayear
DECLARE @secprevisionkind    char(1) 
SELECT  @secprevisionkind  = 
	 CASE 
		WHEN fin_kind = 3 THEN 'S'
		ELSE 'N'
	END
FROM config 
WHERE config.ayear = @ayear
IF (@hierarchy ='S')
BEGIN
		IF(@suppressifblank = 'S')
		BEGIN
			INSERT INTO #fin_situation
				(
				idfin, 
				idman 
				)
			SELECT  DISTINCT
				F.idfin,
				finlast.idman 
				FROM fin F
				JOIN finlink FLK2
					ON  FLK2.idparent = F.idfin 
				JOIN finlink FLK
					ON  FLK.idchild = F.idfin AND FLK.nlevel = @nlevel
				JOIN finlast
					ON F.idfin = finlast.idfin
				WHERE ((F.flag&1)<>0) 
					  AND ((finlast.idman = @idman) OR (@idman is null and finlast.idman is not null))	
					  AND F.ayear = @ayear 
					  AND (@idfin IS NULL OR  FLK.idparent = @idfin )
					  AND F.nlevel >=  @nlevel 
					  AND EXISTS (select idfin from upbtotal where idfin = F.idfin ) 
			-- prende le voci di bilancio che hanno solo i residui
			INSERT INTO #fin_situation
				(
				idfin, 
				idman 
				)
			SELECT  DISTINCT
				F.idfin, 
				finlast.idman
			FROM fin F
				JOIN finlink FLK2
					ON  FLK2.idparent = F.idfin 
				JOIN finlink FLK
					ON  FLK.idchild = F.idfin and FLK.nlevel = @nlevel 
				JOIN finlast
					ON  F.idfin = finlast.idfin 
				JOIN expenseyear
					ON expenseyear.idfin = F.idfin
				JOIN expensetotal
					ON  expenseyear.idexp = expensetotal.idexp
					AND expenseyear.ayear = expensetotal.ayear
						
			WHERE  ((F.flag&1)<>0) -- Spesa
				   AND ((finlast.idman = @idman) OR  (@idman is null and finlast.idman is not null))	
					   AND F.ayear = @ayear
				   AND (@idfin IS NULL OR  (FLK.idparent = @idfin and @idfin is not null))
				   AND F.nlevel >=  @nlevel
				   AND NOT EXISTS (SELECT *
						FROM  #fin_situation
						WHERE FLK2.idparent = #fin_situation.idfin)  
				AND ((expensetotal.flag&1)=1)
				AND expenseyear.ayear=@ayear
		END
		ELSE
		BEGIN
			INSERT INTO #fin_situation
			(
				idfin, 
				idman 
			)
			SELECT DISTINCT
				F.idfin, 
				finlast.idman
			FROM fin F
			JOIN finlink FLK2
				ON  FLK2.idparent = F.idfin
			JOIN finlink FLK
				ON  FLK.idchild = F.idfin and FLK.nlevel = @nlevel
			JOIN finlast
				ON  F.idfin = finlast.idfin 
			WHERE ((F.flag&1)<>0) -- Spesa
				AND ((finlast.idman = @idman) OR  (@idman is null and finlast.idman is not null))	
				AND F.ayear = @ayear 
				AND (@idfin IS NULL OR FLK.idparent = @idfin )
				AND F.nlevel >=  @nlevel
		END
END
ELSE	--> NON ESPANDE LA GERARCHIA
BEGIN
		IF(@suppressifblank = 'S')
		BEGIN
			INSERT INTO #fin_situation
				(
				idfin, 
				idman 
				)
			SELECT  DISTINCT
				F.idfin,
				finlast.idman 
				FROM fin F
				JOIN finlink FLK2
					ON  FLK2.idparent = F.idfin 
				JOIN finlink FLK
					ON  FLK.idchild = F.idfin AND FLK.nlevel = @nlevel 
				JOIN finlast
					ON FLK2.idchild = finlast.idfin
				WHERE ((F.flag&1)<>0) -- Spesa
					  AND ((finlast.idman = @idman) OR (@idman is null and finlast.idman is not null))	
					  AND F.ayear = @ayear 
					  AND (@idfin IS NULL OR  FLK2.idparent = @idfin )
					  AND F.nlevel = @nlevel
					  AND EXISTS (select idfin from upbtotal where idfin = F.idfin ) 
			-- prende le voci di bilancio che hanno solo i residui
			INSERT INTO #fin_situation
				(
				idfin, 
				idman 
				)
			SELECT  DISTINCT
				F.idfin, 
				finlast.idman
			FROM fin F
				JOIN finlink FLK2
					ON  FLK2.idparent = F.idfin 
				JOIN finlink FLK
					ON  FLK.idchild = F.idfin and FLK.nlevel = @nlevel
				JOIN finlast
					ON  FLK2.idchild = finlast.idfin 
				JOIN expenseyear
					ON expenseyear.idfin = F.idfin
				JOIN expensetotal
					ON  expenseyear.idexp = expensetotal.idexp
					AND expenseyear.ayear = expensetotal.ayear
			WHERE  ((F.flag&1)<>0) -- Spesa
				   AND ((finlast.idman = @idman) OR  (@idman is null and finlast.idman is not null))	
					   AND F.ayear = @ayear
				   AND (@idfin IS NULL OR  (FLK2.idparent = @idfin and @idfin is not null))
				   AND F.nlevel = @nlevel
				   AND NOT EXISTS (SELECT *
						FROM  #fin_situation
						WHERE FLK2.idparent = #fin_situation.idfin)  
				AND ((expensetotal.flag&1)=1)
				AND expenseyear.ayear=@ayear
		END
		ELSE
		BEGIN
			INSERT INTO #fin_situation
			(
				idfin, 
				idman 
			)
			SELECT DISTINCT
				F.idfin, 
				finlast.idman
			FROM fin F
			JOIN finlink FLK2
				ON  FLK2.idparent = F.idfin
			JOIN finlink FLK
				ON  FLK.idchild = F.idfin and FLK.nlevel = @nlevel
			JOIN finlast
				ON FLK2.idchild = finlast.idfin 
			WHERE ((F.flag&1)<>0) -- Spesa
				AND ((finlast.idman = @idman) OR  (@idman is null and finlast.idman is not null))	
				AND F.ayear = @ayear 
				AND (@idfin IS NULL OR FLK2.idparent = @idfin )
				AND F.nlevel = @nlevel
		END
END
----------------------------------------------------------------------------------------------------------------		
UPDATE #fin_situation
	SET  main_initial_prevision =
			ISNULL((
			SELECT SUM(finyear.prevision)
			FROM finyear
			JOIN fin 
				ON finyear.idfin = fin.idfin
			JOIN finlast
				ON  finlast.idfin  = fin.idfin 
			JOIN finlink
				ON  finlink.idchild = fin.idfin  
			WHERE finlink.idparent = #fin_situation.idfin
			      AND finlast.idman = #fin_situation.idman
			      AND fin.ayear = @ayear
			      AND finyear.ayear = @ayear	
			      ), 0.0),
		var_main_prevision  =   
			ISNULL((SELECT SUM(finvardetail.amount) 
				FROM finvardetail
				JOIN finvar
      					ON finvardetail.yvar = finvar.yvar 
					AND finvardetail.nvar = finvar.nvar
				JOIN finlast
					ON  finlast.idfin  = finvardetail.idfin 
				JOIN finlink
					ON  finlink.idchild = finvardetail.idfin   
				WHERE finlink.idparent = #fin_situation.idfin
				      AND finvar.idfinvarstatus = 5
				      AND finlast.idman = #fin_situation.idman
				      AND finvar.yvar = @ayear 
				      AND finvar.flagprevision ='S'	
				      AND finvar.variationkind <> 5
				      AND finvar.adate between @start and @stop), 0.0),
		sec_initial_prevision = 	
			ISNULL((SELECT SUM(finyear.secondaryprev)
				FROM finyear
				JOIN finlast
					ON  finlast.idfin  = finyear.idfin 
				JOIN finlink
					ON  finlink.idchild = finyear.idfin   
				WHERE finlink.idparent = #fin_situation.idfin
					AND finlast.idman = #fin_situation.idman
					AND finyear.ayear = @ayear), 0.0),
		varprevsec =
			ISNULL((SELECT SUM(finvardetail.amount) 
				FROM finvardetail
				JOIN finvar
      					ON finvardetail.yvar = finvar.yvar 
					AND finvardetail.nvar = finvar.nvar
				JOIN finlast
					ON  finlast.idfin  = finvardetail.idfin 
				JOIN finlink
					ON  finlink.idchild = finvardetail.idfin   
				WHERE finlink.idparent = #fin_situation.idfin
					AND finvar.idfinvarstatus = 5
					AND finlast.idman = #fin_situation.idman
					AND finvar.yvar = @ayear 
					AND finvar.variationkind <> 5
					AND finvar.flagsecondaryprev = 'S'
					AND finvar.adate between @start and @stop), 0.0)
		
UPDATE #fin_situation
	SET fin_phase_comp=                                                
		ISNULL((SELECT SUM(expenseyear.amount)
			FROM expense
			JOIN expenseyear
				ON expenseyear.idexp = expense.idexp
				AND expenseyear.ayear = @ayear
			JOIN expensetotal
				ON  expenseyear.idexp = expensetotal.idexp
				AND expenseyear.ayear = expensetotal.ayear
			JOIN finlast
				ON  finlast.idfin  = expenseyear.idfin 
			JOIN finlink
				ON  finlink.idchild = expenseyear.idfin  
				AND finlink.idparent  = #fin_situation.idfin
			WHERE finlast.idman = #fin_situation.idman
				AND expenseyear.ayear = @ayear
				AND ((expensetotal.flag&1) = 0) --Competenza
				AND expense.adate between @start and @stop 
				AND expense.nphase = @fin_phase), 0.0),
	 var_fin_phase_comp=					
		ISNULL((SELECT SUM(expensevar.amount)
			FROM expensevar
			JOIN expenseyear
				ON expenseyear.idexp = expensevar.idexp
			JOIN expense
				ON expenseyear.idexp = expense.idexp
			JOIN expensetotal
				ON  expenseyear.idexp = expensetotal.idexp
				AND expenseyear.ayear = expensetotal.ayear
			JOIN finlast
				ON  finlast.idfin  = expenseyear.idfin 
			JOIN finlink
				ON  finlink.idchild = expenseyear.idfin   
				AND finlink.idparent = #fin_situation.idfin
			WHERE expensevar.adate between @start and @stop 
				AND expenseyear.ayear = @ayear
				AND expense.nphase= @fin_phase
				AND ((expensetotal.flag&1) = 0) -- Competenza
				AND finlast.idman = #fin_situation.idman
				AND expensevar.yvar = @ayear), 0.0),
	fin_phase_resid=                                               
		ISNULL((SELECT SUM(expenseyear.amount)
			FROM expense
			JOIN expenseyear
				ON expenseyear.idexp = expense.idexp
			JOIN expensetotal
				ON  expenseyear.idexp = expensetotal.idexp
				AND expenseyear.ayear = expensetotal.ayear
			JOIN finlast
				ON  finlast.idfin  = expenseyear.idfin 
			JOIN finlink
				ON  finlink.idchild = expenseyear.idfin   
				AND finlink.idparent = #fin_situation.idfin
			WHERE finlast.idman = #fin_situation.idman
			      AND ((expensetotal.flag&1) = 1) -- Residuo
			      AND expenseyear.ayear = @ayear
			      AND expense.adate between @start and @stop 
			      AND expense.nphase = @fin_phase), 0.0),
	 var_fin_phase_resid=					
		ISNULL((SELECT SUM(expensevar.amount)
			FROM expensevar
			JOIN expenseyear
				ON expenseyear.idexp = expensevar.idexp
	 		JOIN expense
				ON expenseyear.idexp = expense.idexp
			JOIN expensetotal
				ON  expenseyear.idexp = expensetotal.idexp
				AND expenseyear.ayear = expensetotal.ayear
			JOIN finlast
				ON  finlast.idfin  = expenseyear.idfin 
			JOIN finlink
				ON  finlink.idchild = expenseyear.idfin   	 
				AND finlink.idparent = #fin_situation.idfin
			WHERE expensevar.adate between @start and @stop 
			      AND expenseyear.ayear = @ayear 
			      AND expense.nphase= @fin_phase
			      AND ((expensetotal.flag&1) = 1) -- Residuo
			      AND finlast.idman = #fin_situation.idman
			      AND expensevar.yvar = @ayear), 0.0),
	 registry_phase_comp = 
		ISNULL((SELECT SUM(expenseyear.amount)
			FROM expense
			JOIN expenseyear
				ON expenseyear.idexp = expense.idexp
			JOIN expensetotal
				ON  expenseyear.idexp = expensetotal.idexp
				AND expenseyear.ayear = expensetotal.ayear
			JOIN finlast
				ON  finlast.idfin  = expenseyear.idfin 
			JOIN finlink
				ON  finlink.idchild = expenseyear.idfin   	 	
				AND finlink.idparent = #fin_situation.idfin
			WHERE expense.adate between @start and @stop 
			      AND expenseyear.ayear = @ayear
			      AND ((expensetotal.flag&1) = 0) -- Competenza
			      AND finlast.idman = #fin_situation.idman
			      AND expense.nphase = @registry_phase), 0.0),
	var_registry_phase_comp =
		ISNULL((SELECT SUM(expensevar.amount)
			FROM expensevar
			JOIN expense
				ON expense.idexp = expensevar.idexp
			JOIN expenseyear
				ON expenseyear.idexp = expensevar.idexp
			JOIN expensetotal
				ON  expenseyear.idexp = expensetotal.idexp
				AND expenseyear.ayear = expensetotal.ayear
			JOIN finlast
				ON  finlast.idfin  = expenseyear.idfin 
			JOIN finlink
				ON  finlink.idchild = expenseyear.idfin   	 	
				AND finlink.idparent = #fin_situation.idfin
			WHERE expensevar.adate between @start and @stop 
				AND expenseyear.ayear = @ayear
				AND expense.nphase= @registry_phase
				AND ((expensetotal.flag&1) = 0) -- Competenza
				AND finlast.idman = #fin_situation.idman
				AND expensevar.yvar = @ayear), 0.0),
	 registry_phase_resid = 
		ISNULL((SELECT SUM(expenseyear.amount)
			FROM expense
			JOIN expenseyear
				ON expenseyear.idexp = expense.idexp
			JOIN expensetotal
				ON  expenseyear.idexp = expensetotal.idexp
				AND expenseyear.ayear = expensetotal.ayear
			JOIN finlast
				ON  finlast.idfin  = expenseyear.idfin 
			JOIN finlink
				ON  finlink.idchild = expenseyear.idfin   	
				AND finlink.idparent = #fin_situation.idfin 	
			WHERE expense.adate between @start and @stop 
				AND expenseyear.ayear = @ayear
				AND ((expensetotal.flag&1) = 1) --Residuo
			      	AND finlast.idman = #fin_situation.idman
				AND expense.nphase = @registry_phase), 0.0),
	var_registry_phase_resid =
			ISNULL((SELECT SUM(expensevar.amount)
				FROM expensevar
				JOIN expense
					ON expense.idexp = expensevar.idexp
				JOIN expenseyear
					ON expenseyear.idexp = expensevar.idexp
				JOIN expensetotal
					ON  expenseyear.idexp = expensetotal.idexp
					AND expenseyear.ayear = expensetotal.ayear
				JOIN finlast
					ON  finlast.idfin  = expenseyear.idfin 
				JOIN finlink
					ON  finlink.idchild = expenseyear.idfin   	
					AND finlink.idparent = #fin_situation.idfin 		
				WHERE expensevar.adate between @start and @stop 
					AND expenseyear.ayear = @ayear
					AND expense.nphase= @registry_phase
					AND ((expensetotal.flag&1) = 1) -- Residuo 
			      		AND finlast.idman = #fin_situation.idman
					AND expensevar.yvar = @ayear), 0.0)
--  GESTIONE DEL FONDO ECONOMALE
UPDATE #fin_situation
	SET fin_phase_comp=   	
		ISNULL(fin_phase_comp, 0.0) +
		ISNULL((SELECT SUM(operation.amount)
			FROM pettycashoperation operation
			JOIN finlast
				ON  finlast.idfin  = operation.idfin 
			JOIN finlink
				ON  finlink.idchild = operation.idfin  
				AND finlink.idparent = #fin_situation.idfin 
			WHERE 	finlast.idman = #fin_situation.idman
				AND operation.adate between @start and @stop
				AND operation.yoperation = @ayear
				AND NOT EXISTS (SELECT * FROM pettycashoperation  
						WHERE pettycashoperation.idpettycash = operation.idpettycash
						AND pettycashoperation.yoperation = operation.yrestore
						AND pettycashoperation.noperation = operation.nrestore
						AND pettycashoperation.adate between @start and @stop
						AND pettycashoperation.yoperation = @ayear)), 0.0),
	 registry_phase_comp = 
		ISNULL(registry_phase_comp, 0.0) +
		ISNULL((SELECT SUM(operation.amount)
			FROM pettycashoperation operation
			JOIN finlast
				ON  finlast.idfin  = operation.idfin 
			JOIN finlink
				ON  finlink.idchild = operation.idfin   
				AND finlink.idparent = #fin_situation.idfin
			WHERE finlast.idman = #fin_situation.idman
				AND operation.adate between @start and @stop 
				AND operation.yoperation = @ayear
				AND NOT EXISTS (SELECT * FROM pettycashoperation oprestore
						WHERE oprestore.idpettycash = operation.idpettycash
						AND oprestore.yoperation = operation.yrestore
						AND oprestore.noperation = operation.nrestore
						AND oprestore.adate between @start and @stop
						AND oprestore.yoperation = @ayear)), 0.0)
UPDATE #fin_situation
	SET max_phase_comp=	 
		ISNULL((SELECT SUM(HPV.amount)
			FROM historypaymentview HPV
			JOIN finlast
				ON  finlast.idfin  = HPV.idfin 
			JOIN finlink
				ON  finlink.idchild = HPV.idfin   
				AND finlink.idparent = #fin_situation.idfin
			WHERE 	HPV.ymov = @ayear
				AND HPV.competencydate between @start and @stop
				AND ((HPV.totflag&1) = 0) -- Competenza
				AND finlast.idman = #fin_situation.idman
			), 0.0),
	max_phase_resid=	 
		ISNULL((SELECT SUM(HPV.amount)
			FROM historypaymentview HPV
			JOIN finlast
				ON  finlast.idfin  = HPV.idfin 
			JOIN finlink
				ON  finlink.idchild = HPV.idfin   
				AND finlink.idparent = #fin_situation.idfin
			WHERE HPV.ymov = @ayear
				AND HPV.competencydate between @start and @stop
				AND ((HPV.totflag & 1) = 1) -- Residuo
				AND finlast.idman = #fin_situation.idman
				), 0.0)
IF @cashvaliditykind <> 4
BEGIN
	UPDATE #fin_situation
		SET var_max_phase_comp= 
			ISNULL((SELECT SUM(expensevar.amount)
				FROM expensevar
				JOIN historypaymentview HPV
					ON HPV.idexp = expensevar.idexp
					AND HPV.ymov = @ayear 
				JOIN finlast
					ON  finlast.idfin  = HPV.idfin 
				JOIN finlink
					ON  finlink.idchild = HPV.idfin   
					AND finlink.idparent = #fin_situation.idfin
				WHERE expensevar.yvar = @ayear
					AND ((HPV.totflag&1) = 0) -- Competenza
					AND HPV.ymov = @ayear
					AND HPV.competencydate between @start and @stop
					AND expensevar.adate between @start and @stop
					AND finlast.idman = #fin_situation.idman), 0.0),
		var_max_phase_resid= 
			ISNULL((SELECT SUM(expensevar.amount)
				FROM expensevar
				JOIN historypaymentview HPV
					ON HPV.idexp = expensevar.idexp
				JOIN finlast
					ON  finlast.idfin  = HPV.idfin 
				JOIN finlink
					ON  finlink.idchild = HPV.idfin   
					AND finlink.idparent = #fin_situation.idfin
				WHERE   ((HPV.totflag&1) = 1) -- Residuo 
					AND HPV.ymov = @ayear
					AND HPV.competencydate between @start and @stop
					AND finlast.idman = #fin_situation.idman
					AND expensevar.yvar = @ayear
					AND expensevar.adate between @start and @stop), 0.0)
END
		
-- Controlla che i CREDITI  siano gestiti
IF 	(EXISTS(SELECT* FROM creditpart
		WHERE ycreditpart = @ayear AND adate between @start and @stop) 
	OR
	EXISTS (SELECT * FROM finvar
		WHERE flagcredit ='S' and yvar = @ayear
		AND adate between @start and @stop
		AND finvar.idfinvarstatus = 5)
	
		)
	BEGIN
		UPDATE #fin_situation
		SET var_assign_credit = 
			ISNULL((SELECT SUM(d.amount)
				FROM finvardetail d
				JOIN finvar v 
					ON v.yvar = d.yvar
					AND v.nvar = d.nvar
					AND v.flagcredit ='S'
				JOIN finlast
					ON  finlast.idfin  = d.idfin 
				JOIN finlink
					ON  finlink.idchild = d.idfin   
					AND finlink.idparent = #fin_situation.idfin
				WHERE 	finlast.idman = #fin_situation.idman	
					AND v.idfinvarstatus = 5
					AND v.adate between @start and @stop
					AND v.variationkind IN (2,3)),0.0),
		 assign_credit = 	
			ISNULL((SELECT SUM(creditpart.amount)
				FROM creditpart 
				JOIN incomeyear
					ON creditpart.idinc = incomeyear.idinc
					and creditpart.ycreditpart = incomeyear.ayear
				JOIN finlast
					ON  finlast.idfin  = creditpart.idfin 
				JOIN finlink
					ON  finlink.idchild = creditpart.idfin   
					AND finlink.idparent = #fin_situation.idfin
				WHERE 	finlast.idman = #fin_situation.idman
					AND adate between @start and @stop),0.0)
			+	
			ISNULL((SELECT SUM(d.amount)
				FROM finvardetail d
				JOIN finvar v
					ON v.yvar = d.yvar
					AND v.nvar = d.nvar
					AND v.flagcredit ='S'
				JOIN finlast
					ON  finlast.idfin  = d.idfin 
				JOIN finlink
					ON  finlink.idchild = d.idfin 
					AND finlink.idparent = #fin_situation.idfin  
				WHERE 	 finlast.idman = #fin_situation.idman
					AND v.idfinvarstatus = 5
					AND v.adate between @start and @stop
					AND v.variationkind IN (1,4)),0.0),
		flag_assign_credit='S'
	END
ELSE
	UPDATE #fin_situation SET flag_assign_credit='N'
-- Controlla che gli INCASSI siano gestiti
IF 	(EXISTS(SELECT * FROM proceedspart 
		WHERE yproceedspart	= @ayear
		AND adate between @start and @stop) 
	OR
	EXISTS (SELECT * FROM finvar
		WHERE flagproceeds='S' and 
		yvar = @ayear AND adate between @start and @stop
		AND finvar.idfinvarstatus = 5)
	)
	BEGIN
		UPDATE #fin_situation
			SET var_assign_cash = 
				isnull((SELECT SUM(d.amount)
					FROM finvardetail d
					JOIN finvar v
						ON v.yvar = d.yvar
						AND v.nvar = d.nvar
						AND v.flagproceeds='S'
					JOIN finlast
						ON  finlast.idfin  = d.idfin 
					JOIN finlink
						ON  finlink.idchild = d.idfin   
						AND finlink.idparent = #fin_situation.idfin		
					WHERE 	finlast.idman = #fin_situation.idman
						AND v.idfinvarstatus = 5
						AND v.adate between @start and @stop
						AND v.variationkind IN (2,3)),0.0),
			 assign_cash = 
				isnull ((SELECT SUM(proceedspart.amount)
					FROM proceedspart
					JOIN incomeyear
						ON proceedspart.idinc = incomeyear.idinc
						AND proceedspart.yproceedspart = incomeyear.ayear
					JOIN finlast
						ON  finlast.idfin  = proceedspart.idfin 
					JOIN finlink
						ON  finlink.idchild = proceedspart.idfin  
						AND finlink.idparent = #fin_situation.idfin	
					WHERE finlast.idman = #fin_situation.idman
						AND adate between @start and @stop),0.0)
					+
				isnull ((SELECT  SUM(d.amount)
					FROM finvardetail d
					JOIN finvar v
						ON v.yvar = d.yvar
						AND v.nvar = d.nvar
						AND v.flagproceeds='S'
					JOIN finlast
						ON  finlast.idfin  = d.idfin 
					JOIN finlink
						ON  finlink.idchild = d.idfin  
						AND finlink.idparent = #fin_situation.idfin
					WHERE finlast.idman = #fin_situation.idman
						AND v.idfinvarstatus = 5
						AND v.adate between @start and @stop
						AND v.variationkind IN (1,4)),0.0),
			flag_assign_cash='S'
	END
ELSE
UPDATE #fin_situation	SET flag_assign_cash='N'

IF (@suppressifblank = 'S') --> cancella le righe sottostanti la categoria 
BEGIN
	DELETE FROM #fin_situation 
	WHERE 
		(isnull(main_initial_prevision,0.0) =0 AND 
		isnull(var_main_prevision,0.0) =0 AND 
		isnull(registry_phase_comp,0.0) =0 AND 
		isnull(var_registry_phase_comp,0.0) =0 AND 
		isnull(max_phase_comp,0.0) =0 AND 
		isnull(var_max_phase_comp,0.0) =0 AND 
		isnull(sec_initial_prevision,0.0) =0 AND 
		isnull(varprevsec,0.0) =0 AND 
		isnull(registry_phase_resid,0.0) =0 AND 
		isnull(var_registry_phase_resid,0.0) =0 AND 
		isnull(max_phase_resid,0.0) =0 AND 
		isnull(var_max_phase_resid,0.0) =0 AND 
		isnull(assign_credit,0.0) =0 AND 
		isnull(var_assign_credit,0.0) =0 AND 
		isnull(assign_cash,0.0) =0 AND 
		isnull(var_assign_cash,0.0) =0 AND
		isnull(fin_phase_comp,0.0) =0 AND  
		isnull(var_fin_phase_comp,0.0) =0 AND 
		isnull(fin_phase_resid,0.0) =0 AND 
		isnull(var_fin_phase_resid,0.0) =0 AND 			
		nlevel >=2
		)
END
	SELECT 
		#fin_situation.idfin,	
		fin.codefin,	
		fin.title,	
		fin.printingorder as finprintingorder,	
		fin.nlevel,	
		sum(isnull(main_initial_prevision,0.0)) 	 'main_initial_prevision',
		sum(isnull(var_main_prevision,0.0)) 		 'var_main_prevision',
		sum(isnull(fin_phase_comp,0.0)) 		 'fin_phase_comp',
		sum(isnull(var_fin_phase_comp,0.0)) 		 'var_fin_phase_comp', 
		@desc_fin_phase 				 'desc_fin_phase',	
		sum(isnull(registry_phase_comp,0.0)) 		 'registry_phase_comp',
		sum(isnull(var_registry_phase_comp,0.0)) 	 'var_registry_phase_comp',
		@desc_registry_phase 				 'desc_registry_phase',		
		sum(isnull(max_phase_comp,0.0)) 		 'max_phase_comp',
		sum(isnull(var_max_phase_comp,0.0)) 		 'var_max_phase_comp',
		@desc_max_phase 				 'desc_max_phase' 	,					
		sum(isnull(sec_initial_prevision,0.0)) 		 'sec_initial_prevision',
		sum(isnull(varprevsec,0.0)) 			 'varprevsec',
		sum(isnull(fin_phase_resid,0.0)) 		 'fin_phase_resid', 
		sum(isnull(var_fin_phase_resid,0.0)) 		 'var_fin_phase_resid',
		sum(isnull(registry_phase_resid,0.0)) 		 'registry_phase_resid'   ,
		sum(isnull(var_registry_phase_resid,0.0)) 	 'var_registry_phase_resid',
		sum(isnull(max_phase_resid,0.0)) 		 'max_phase_resid',
		sum(isnull(var_max_phase_resid,0.0)) 		 'var_max_phase_resid',
		sum(isnull(assign_credit,0.0)) 			 'assign_credit',
		sum(isnull(var_assign_credit,0.0)) 		 'var_assign_credit',
		sum(isnull(assign_cash,0.0)) 			 'assign_cash' ,
		sum(isnull(var_assign_cash,0.0)) 		 'var_assign_cash' ,
		@previsionkind 					 'previsionkind',
		@secprevisionkind 				 'secprevisionkind',
		flag_assign_credit,
		flag_assign_cash,
		#fin_situation.idman,
		manager.title as manager	
		FROM #fin_situation
		JOIN fin ON fin.idfin = #fin_situation.idfin
		JOIN manager ON manager.idman = #fin_situation.idman
		GROUP BY #fin_situation.idfin,fin.codefin,	
		fin.title,fin.printingorder,fin.nlevel,flag_assign_credit,flag_assign_cash,#fin_situation.idman,manager.title 
		ORDER BY #fin_situation.idman,fin.printingorder
END



GO

print '[rpt_sitbilancioarticoli_respons_spesa] OK'

GO
if object_id('[esporta_accessori_senza_beni]') is not null
	drop PROCEDURE [esporta_accessori_senza_beni]
go




CREATE                     PROCEDURE [esporta_accessori_senza_beni]  
AS BEGIN
SELECT 
	accessorio.idpiece 		AS 'Idpiece',
	accessorio.idasset 		AS 'Idasset',
	accessorio.nassetacquire	AS 'Carico Accessorio', 
	assetloadkind.codeassetloadkind 	AS 'Tipo Buono Carico',
	assetload.yassetload 	AS 'Eserc. Buono Carico',
	assetload.nassetload 	AS 'Num. Buono Carico',
	assetunloadkind.codeassetunloadkind 	AS 'Tipo Buono Scarico',
	assetunload.yassetunload 	AS 'Eserc. Buono Scarico',
	assetunload.nassetunload 	AS 'Num. Buono Scarico'
FROM asset accessorio 
	LEFT OUTER JOIN assetacquire on accessorio.nassetacquire=assetacquire.nassetacquire
	left outer join assetload on assetacquire.idassetload=assetload.idassetload
	left outer join assetloadkind on assetloadkind.idassetloadkind=assetload.idassetloadkind
	left outer join assetunload on assetunload.idassetunload=accessorio.idassetunload
	left outer join assetunloadkind on assetunloadkind.idassetunloadkind=assetunload.idassetunloadkind
WHERE 	accessorio.idpiece>1
	AND accessorio.idasset not in (select idasset from asset where idpiece = 1)
ORDER BY accessorio.idasset,accessorio.idpiece
END


GO

print '[esporta_accessori_senza_beni] OK'

GO
if object_id('[rpt_sit_residui_per_anno_riep]') is not null
	drop PROCEDURE [rpt_sit_residui_per_anno_riep]
go


CREATE   PROCEDURE [rpt_sit_residui_per_anno_riep]
	@ayear 		int,
	@date		datetime,
	@finpart 	char(1),
	@levelusable 	tinyint,
	@idupb		varchar(36),
	@showupb 	char(1),
	@showchildupb 	char(1)
AS
BEGIN
/* Versione 1.0.2 del 16/11/2007 ultima modifica: MARIA */							
DECLARE @finphase		tinyint
DECLARE @cash_phase		tinyint
DECLARE @idupboriginal 		varchar(36)
SET @idupboriginal= @idupb
IF (@showchildupb = 'S') set @idupb=@idupb + '%' 		
CREATE TABLE #report_residual
(
	ayear			int,
	codeupb			varchar(50),
	idupb 			varchar(36),
	upb   			varchar(150),
	upbprintingorder	varchar(50),
	idfin			int,
	codefin			varchar(12),
	title			varchar(150),
	initial_residual	decimal(19,2),
	var_residual		decimal(19,2),
	cash_residual		decimal(19,2),
	var_cash_residual	decimal(19,2)
)
CREATE TABLE #initial_residual
	(ayear int, idfin int, idupb varchar(36), total decimal(19,2))
CREATE TABLE #var_residual
	(ayear int, idfin int, idupb varchar(36), total decimal(19,2))
CREATE TABLE #cash_residual
	(ayear int, idfin int, idupb varchar(36), total decimal(19,2))
CREATE TABLE #var_cash_residual
    	(ayear int, idfin int, idupb varchar(36), total decimal(19,2))
DECLARE @cashvaliditykind int
SELECT	@cashvaliditykind = cashvaliditykind
FROM 	config
WHERE 	ayear = @ayear
IF @finpart = 'E'
	BEGIN
		SELECT @finphase = assessmentphasecode
		FROM config
		WHERE ayear = @ayear
		IF @finphase IS NULL
			BEGIN
				SELECT @finphase = incomefinphase
				FROM uniconfig
			END
		SELECT @cash_phase = MAX(nphase)
		FROM incomephase
	END
ELSE
	BEGIN
		SELECT @finphase = appropriationphasecode
		FROM config
		WHERE ayear = @ayear
		IF @finphase IS NULL
			BEGIN
				SELECT @finphase = expensefinphase
				FROM uniconfig
			END
		SELECT @cash_phase = MAX(nphase)
		FROM expensephase
	END
IF @finpart = 'E'
BEGIN
	
	INSERT INTO #initial_residual
		(
		ayear,
		idfin,
		idupb,
		total
		)
	SELECT
		income.ymov,
		ISNULL(finlink.idparent,incomeyear.idfin), 
		incomeyear.idupb,
		SUM(ISNULL(incomeyear.amount, 0.0))
	FROM incomeyear
	JOIN income
		ON income.idinc = incomeyear.idinc
        JOIN incometotal
		ON  incomeyear.idinc = incometotal.idinc
		AND incomeyear.ayear = incometotal.ayear			
	LEFT OUTER JOIN finlink
		ON finlink.idchild = incomeyear.idfin  AND finlink.nlevel = @levelusable
	WHERE 	incomeyear.ayear = @ayear
		AND (incomeyear.idupb like @idupb )
		AND ((incometotal.flag&1) = 1) -- Residuo
		AND income.nphase = @finphase
		AND income.adate <= @date
	GROUP BY income.ymov,incomeyear.idupb,ISNULL(finlink.idparent,incomeyear.idfin)
	
	INSERT INTO #var_residual
		(
		ayear,
		idfin,
		idupb,
		total
		)
	SELECT
		income.ymov,
		ISNULL(finlink.idparent,incomeyear.idfin), 
		incomeyear.idupb,
		SUM(ISNULL(incomevar.amount, 0.0))
	FROM incomevar
	JOIN incomeyear
		ON incomeyear.idinc = incomevar.idinc
		AND incomeyear.ayear = @ayear
	JOIN income
		ON incomeyear.idinc = income.idinc
	JOIN incometotal
		ON  incomeyear.idinc = incometotal.idinc
		AND incomeyear.ayear = incometotal.ayear			
	LEFT OUTER JOIN finlink
		ON finlink.idchild = incomeyear.idfin  AND finlink.nlevel = @levelusable
	WHERE incomevar.yvar = @ayear
		AND incomevar.adate <= @date 
		AND (incomeyear.idupb like @idupb )
		AND ((incometotal.flag&1) = 1) -- Residuo
		AND income.nphase = @finphase
	GROUP BY income.ymov, incomeyear.idupb,ISNULL(finlink.idparent,incomeyear.idfin)
	
	INSERT INTO #cash_residual
		(
		ayear,
		idfin,
		idupb,
		total
		)
	SELECT
		I.ymov,
		ISNULL(FL1.idparent,IY.idfin),
		IY.idupb,
		SUM(HPV.amount)
	FROM historyproceedsview HPV
	JOIN incomeyear IY
		ON  IY.idinc = HPV.idinc
		AND HPV.ymov = @ayear
	JOIN incomelink IL 
		ON IL.idchild = IY.idinc AND IL.nlevel = @finphase
	JOIN income I
		ON IL.idparent = I.idinc 
	LEFT OUTER JOIN finlink  FL1
		ON FL1.idchild = IY.idfin AND FL1.nlevel = @levelusable
	WHERE HPV.competencydate <= @date
		AND IY.idupb like @idupb
		AND IY.ayear = @ayear
		AND HPV.flagarrear = 'R'
	GROUP BY I.ymov, IY.idupb,ISNULL(FL1.idparent,IY.idfin)
	
	IF @cashvaliditykind <> 4
	BEGIN
		INSERT INTO #var_cash_residual
			(
			ayear,
			idfin,
			idupb,
			total
			)
		SELECT
			I.ymov,
			ISNULL(FL1.idparent,IY.idfin),
			IY.idupb,
			SUM(ISNULL(IV.amount, 0.0))
		FROM incomevar IV
		JOIN incomeyear IY
			ON  IY.idinc = IV.idinc
			AND IY.ayear = @ayear
		JOIN incomelink IL 
			ON IL.idchild = IY.idinc AND IL.nlevel = @finphase
		JOIN income I
			ON I.idinc = IL.idparent
		JOIN historyproceedsview HPV
			ON HPV.idinc = IV.idinc
			AND HPV.ymov = @ayear
		LEFT OUTER JOIN finlink  FL1
			ON FL1.idchild = IY.idfin AND FL1.nlevel = @levelusable
		WHERE 	IV.yvar = @ayear
			AND IY.idupb like @idupb
			AND IV.adate <= @date
			AND HPV.flagarrear = 'R'
		 	AND HPV.competencydate <= @date
		GROUP BY I.ymov, IY.idupb,ISNULL(FL1.idparent,IY.idfin)
	END
END
-- PARTE SPESA
IF @finpart = 'S'
BEGIN
	
	INSERT INTO #initial_residual
		(
		ayear,
		idfin,
		idupb,
		total
		)
	SELECT
		expense.ymov,
		ISNULL(finlink.idparent,expenseyear.idfin), 
		expenseyear.idupb,
		SUM(ISNULL(expenseyear.amount, 0.0))
	FROM expenseyear
	JOIN expense
		ON expense.idexp = expenseyear.idexp
        JOIN expensetotal
		ON  expenseyear.idexp = expensetotal.idexp
		AND expenseyear.ayear = expensetotal.ayear			
	LEFT OUTER JOIN finlink
		ON finlink.idchild = expenseyear.idfin AND finlink.nlevel = @levelusable
	WHERE expenseyear.ayear = @ayear
		AND expenseyear.idupb like @idupb
		AND ((expensetotal.flag&1) = 1) -- Residuo
		AND expense.nphase = @finphase
		AND expense.adate <= @date
	GROUP BY expense.ymov, expenseyear.idupb,ISNULL(finlink.idparent,expenseyear.idfin)
	INSERT INTO #var_residual
		(
		ayear,
		idfin,
		idupb,	
		total
		)
	SELECT
		expense.ymov,
		ISNULL(finlink.idparent,expenseyear.idfin), 
		expenseyear.idupb,
		SUM(ISNULL(expensevar.amount, 0.0))
	FROM expensevar
	JOIN expenseyear
		ON expenseyear.idexp = expensevar.idexp
		AND expenseyear.ayear = @ayear
	JOIN expense
		ON expenseyear.idexp = expense.idexp
	JOIN expensetotal
		ON  expenseyear.idexp = expensetotal.idexp
		AND expenseyear.ayear = expensetotal.ayear			
	LEFT OUTER JOIN finlink
		ON finlink.idchild = expenseyear.idfin AND finlink.nlevel = @levelusable
	WHERE expensevar.yvar = @ayear
		AND expenseyear.idupb like @idupb
		AND expensevar.adate <= @date 
		AND ((expensetotal.flag&1) = 1) -- Residuo
		AND expense.nphase = @finphase
	GROUP BY expense.ymov, expenseyear.idupb,ISNULL(finlink.idparent,expenseyear.idfin)
	
	INSERT INTO #cash_residual
		(
		ayear,
		idfin,
		idupb,
		total
		)
	SELECT
		E.ymov,
		ISNULL(FL1.idparent,EY.idfin), 
		EY.idupb,
		SUM(HPV.amount)
	FROM historypaymentview HPV 
	JOIN expenseyear EY
		ON  EY.idexp = HPV.idexp
		AND EY.ayear = @ayear
	JOIN expenselink EL 
		ON EL.idchild = EY.idexp AND EL.nlevel = @finphase
	JOIN expense E
		ON EL.idparent = E.idexp
	LEFT OUTER JOIN finlink  FL1
		ON FL1.idchild = EY.idfin AND FL1.nlevel = @levelusable
	WHERE HPV.competencydate <= @date
		AND EY.idupb like @idupb
		AND HPV.flagarrear = 'R'
	GROUP BY E.ymov, EY.idupb,ISNULL(FL1.idparent,EY.idfin)
	
	IF @cashvaliditykind <> 4
	BEGIN
		INSERT INTO #var_cash_residual
		    (
			ayear,
			idfin,
			idupb,
			total
		    )
		SELECT 
			E.ymov,
			ISNULL(FL1.idparent,EY.idfin), 
			EY.idupb,
			SUM(ISNULL(EV.amount, 0.0))
		FROM expensevar EV
		JOIN expenseyear EY
			ON EY.idexp = EV.idexp
			AND EY.ayear = @ayear
		JOIN expenselink EL 
			ON EL.idchild = EY.idexp AND EL.nlevel = @finphase
		JOIN expense E
			ON EL.idparent = E.idexp
		JOIN historypaymentview HPV
			ON HPV.idexp = EV.idexp
			AND HPV.ymov = @ayear
		LEFT OUTER JOIN finlink  FL1
			ON FL1.idchild = EY.idfin AND FL1.nlevel = @levelusable
		WHERE EV.yvar = @ayear
			AND EY.idupb like @idupb
			AND EV.adate <= @date
			AND (HPV.flagarrear = 'R')
			AND HPV.competencydate <= @date
		GROUP BY E.ymov, EY.idupb, ISNULL(FL1.idparent,EY.idfin)
	END
END
INSERT INTO #report_residual(ayear, idfin,idupb)
SELECT DISTINCT ayear,idfin,idupb 
	FROM #initial_residual
INSERT INTO #report_residual(ayear, idfin,idupb)
SELECT DISTINCT ayear,idfin,idupb 
FROM #var_residual
WHERE not exists(SELECT *
		FROM #report_residual i1
		where i1.idfin = #var_residual.idfin
		and i1.idupb = #var_residual.idupb
		and i1.ayear = #var_residual.ayear
		)
/*	WHERE  (
		#var_residual.idfin
		) 
		NOT IN (
			SELECT idfin  
			FROM #report_residual
			)
*/
INSERT INTO #report_residual(ayear, idfin,idupb)
SELECT DISTINCT ayear,idfin,idupb 
FROM #cash_residual
WHERE not exists(SELECT *
		FROM #report_residual i1
		where i1.idfin = #cash_residual.idfin
		and i1.idupb = #cash_residual.idupb
		and i1.ayear = #cash_residual.ayear
		)
/*	WHERE (
		#cash_residual.idfin
		) 
		NOT IN (
			SELECT idfin  
			FROM #report_residual
			)*/
INSERT INTO #report_residual(ayear, idfin,idupb)
SELECT DISTINCT ayear,idfin,idupb 
FROM #var_cash_residual
WHERE not exists(SELECT *
		FROM #report_residual i1
		where i1.idfin = #var_cash_residual.idfin
		and i1.idupb = #var_cash_residual.idupb
		and i1.ayear = #var_cash_residual.ayear
		)
/*	WHERE  (
		#var_cash_residual.idfin
		) 
		NOT IN (
		SELECT idfin  FROM #report_residual
			)
*/
UPDATE #report_residual
SET initial_residual = ISNULL((SELECT #initial_residual.total FROM #initial_residual
		WHERE #initial_residual.idfin = #report_residual.idfin
		and #initial_residual.idupb = #report_residual.idupb
		AND #initial_residual.ayear = #report_residual.ayear), 0.0)
UPDATE #report_residual
SET var_residual = ISNULL((SELECT #var_residual.total FROM #var_residual
		WHERE #var_residual.idfin = #report_residual.idfin
		and #var_residual.idupb = #report_residual.idupb
		AND #var_residual.ayear = #report_residual.ayear), 0.0)
		
UPDATE #report_residual
SET cash_residual = ISNULL((SELECT #cash_residual.total FROM #cash_residual
		WHERE #cash_residual.idfin = #report_residual.idfin
		and #cash_residual.idupb = #report_residual.idupb
		AND #cash_residual.ayear = #report_residual.ayear), 0.0)
UPDATE #report_residual
SET var_cash_residual = ISNULL((SELECT #var_cash_residual.total FROM #var_cash_residual
		WHERE #var_cash_residual.idfin = #report_residual.idfin
		and #var_cash_residual.idupb = #report_residual.idupb
		AND #var_cash_residual.ayear = #report_residual.ayear), 0.0)
UPDATE #report_residual SET codeupb = upb.codeupb ,
			upbprintingorder = upb.printingorder,			
			upb = upb.title
		 from upb where upb.idupb = #report_residual.idupb

IF (@showupb <>'S') AND (@idupboriginal <> '%' ) AND (@showchildupb = 'S')
		UPDATE #report_residual SET  
			upbprintingorder = (SELECT TOP 1 upbprintingorder
				FROM #report_residual
				WHERE idupb = @idupboriginal),
			upb = (SELECT TOP 1 upb
				FROM #report_residual
				WHERE idupb = @idupboriginal),
			idupb = @idupboriginal,
			codeupb =(SELECT TOP 1 codeupb
				FROM #report_residual	
				WHERE idupb = @idupboriginal)
IF (@showupb <>'S') and (@idupboriginal = '%') 
			UPDATE #report_residual SET  
			upbprintingorder = null,
			upb =  null,
			idupb = null,
			codeupb = null
SELECT 
	ayear,    
	codeupb,		
	idupb,	
	upb,
	upbprintingorder,
	sum(initial_residual) initial_residual,
	sum(var_residual) var_residual,
	sum(cash_residual) cash_residual,
	sum(var_cash_residual) var_cash_residual
FROM #report_residual
GROUP BY upbprintingorder,
ayear,codeupb,idupb,upb   			
ORDER BY ayear ASC,upbprintingorder ASC
END

