if object_id('[esporta_buoni_ratificati]') is not null
	drop PROCEDURE [esporta_buoni_ratificati]
go



CREATE               PROCEDURE [esporta_buoni_ratificati]
	 @start smalldatetime,
	 @stop  smalldatetime
AS BEGIN
SELECT
	assetloadkind.description 'Tipo Buono',
	assetload.yassetload 'Eserc.Buono',
	assetload.nassetload 'Num.Buono',
	assetload.ratificationdate as 'Data Ratifica'
FROM assetload 
JOIN assetloadkind 
ON assetloadkind.idassetloadkind = assetload.idassetloadkind
WHERE	assetload.ratificationdate between @start and @stop
END




GO

print '[esporta_buoni_ratificati] OK'

