if object_id('compute_parasubcontractcommunicated') is not null
	drop PROCEDURE compute_parasubcontractcommunicated
go

CREATE    PROCEDURE compute_parasubcontractcommunicated
(
	@ayear int,
	@idcon varchar(8),
	@iddbdepartment varchar(50),
	@res char(1) output
)
AS BEGIN
-- @res resituisce S se il cedolino di conguaglio è stato trasmesso in banca; N altrimenti
DECLARE @stringaSQL nvarchar(4000)
SET @stringaSQL = N'SELECT P.npayroll FROM [' + @iddbdepartment + '].payroll P
	WHERE P.idcon = ''' + @idcon + '''
	AND P.fiscalyear = ' + CONVERT(varchar(4), @ayear) + '
	AND P.flagbalance = ''S'''
CREATE TABLE #temp (value int)
INSERT INTO #temp (value)
EXEC SP_EXECUTESQL @stringaSQL
DECLARE @npayroll_C int
SELECT @npayroll_C = value
FROM #temp
DELETE FROM #temp
DECLARE @idpayroll_R int
SET @stringaSQL = N'SELECT P.idpayroll FROM [' + @iddbdepartment + '].payroll P
	WHERE P.idcon = ''' + @idcon + '''
	AND P.fiscalyear = ' + CONVERT(varchar(4), @ayear) + '
	AND P.flagbalance <> ''S''
	AND P.npayroll = ' + CONVERT(varchar(10), @npayroll_C)
INSERT INTO #temp (value)
EXEC SP_EXECUTESQL @stringaSQL
SELECT @idpayroll_R = value
FROM #temp
IF (@idpayroll_R IS NULL)
BEGIN
	SET @res = 'N'
	DROP TABLE #temp
	RETURN
END
DELETE FROM #temp
SET @stringaSQL = N'SELECT U.idexp FROM [' + @iddbdepartment + '].payroll R
	JOIN [' + @iddbdepartment + '].expensepayroll E
		ON E.idpayroll = R.idpayroll
	JOIN [' + @iddbdepartment + '].expenselink L
		ON L.idparent = E.idexp
	JOIN [' + @iddbdepartment + '].expenselast U
		ON U.idexp = L.idchild
	JOIN [' + @iddbdepartment + '].payment P
		ON P.kpay = U.kpay
	JOIN [' + @iddbdepartment + '].paymenttransmission T
		ON T.kpaymenttransmission = P.kpaymenttransmission
	WHERE R.idpayroll = ' + CONVERT(varchar(10), @idpayroll_R)
INSERT INTO #temp (value)
EXEC SP_EXECUTESQL @stringaSQL
IF ((SELECT COUNT(*) FROM #temp) > 0)
BEGIN
	SET @res = 'S'
END
ELSE
BEGIN
	SET @res = 'N'
END
DROP TABLE #temp
END


GO

print 'compute_parasubcontractcommunicated OK'

GO
if object_id('rpt_verifica_saldo_cc') is not null
	drop PROCEDURE rpt_verifica_saldo_cc
go

--exec rpt_verifica_saldo_cc 2009, {ts '2009-02-16 00:00:00'}

CREATE 	PROCEDURE rpt_verifica_saldo_cc
	@ayear 	int,
	@date 	datetime
AS
	BEGIN
		DECLARE @date_3112_previous_year datetime
		
		DECLARE @yprev int
		SET 	@yprev = @ayear - 1
	
	-- Leggere la Documentazione del task n.4077
		DECLARE @ff_jan01 decimal(19,2)
		SELECT 	@ff_jan01 = 
			ISNULL(startfloatfund, 0.0) 
		FROM 	surplus
		WHERE 	ayear = @ayear 
		
		DECLARE @display_previous_year  char(1)
		IF EXISTS(SELECT * FROM accountingyear WHERE ayear = @ayear - 1)
			BEGIN
				SELECT 	@display_previous_year = 'S'
				SET 	@date_3112_previous_year =CONVERT(datetime, '12/31/' + CONVERT(char(4), @yprev),101) 
				
				DECLARE @previous_proc_communicated 	decimal(19,2)
				-- Reversali Trasmesse nell'anno precedente
				SELECT 	@previous_proc_communicated =
						SUM(et.curramount) from
						incometotal et 
						JOIN income e on et.idinc = e.idinc and et.ayear = (@ayear - 1)
						JOIN incomelast el on el.idinc = e.idinc 
						JOIN proceeds p on el.kpro = p.kpro
						JOIN proceedstransmission pt
							ON pt.kproceedstransmission = p.kproceedstransmission
						WHERE p.ypro = (@ayear  - 1)
							AND pt.transmissiondate <= @date_3112_previous_year
							AND PT.yproceedstransmission = (@ayear - 1)
				
				DECLARE @previous_pay_communicated 	decimal(19,2)
				-- Mandati Trasmessi nell'anno precedente
				SELECT 	@previous_pay_communicated =
						SUM(et.curramount) from
						expensetotal et 
						JOIN expense e on et.idexp=e.idexp  and et.ayear = (@ayear - 1)
						JOIN expenselast el on el.idexp = e.idexp 
						JOIN payment p on el.kpay=p.kpay
						JOIN paymenttransmission pt
							ON pt.kpaymenttransmission = p.kpaymenttransmission
						WHERE p.ypay = (@ayear - 1) 
							AND pt.transmissiondate <= @date_3112_previous_year
							AND PT.ypaymenttransmission = (@ayear - 1)
				DECLARE @previous_proc_not_performed decimal(19,2)
				-- Reversali di anno precedente non  esitate entro il 31/12/anno prec 
				SELECT 	@previous_proc_not_performed = 
						SUM(et.curramount)
						FROM incometotal et 
						JOIN income e
							ON et.idinc=e.idinc and et.ayear=@ayear-1
						JOIN incomelast el on el.idinc = e.idinc 
						JOIN proceeds p on el.kpro = p.kpro
						JOIN proceedstransmission pt
							ON pt.kproceedstransmission = p.kproceedstransmission
						WHERE pt.transmissiondate <= @date_3112_previous_year
							AND p.ypro = @ayear-1
							AND pt.yproceedstransmission=@ayear-1
							AND
							(SELECT COUNT(*) FROM banktransaction PD
							WHERE PD.kpro=P.kpro AND 
							PD.transactiondate <= @date_3112_previous_year) = 0
				
				DECLARE @previous_pay_not_performed decimal(19,2)
				-- Mandati di anno precedente non  esitati entro il 31/12/anno prec 
				SELECT 	@previous_pay_not_performed = 
						SUM(et.curramount)
						FROM expensetotal et 
						JOIN expense e
							ON et.idexp=e.idexp and et.ayear=@ayear-1
						JOIN expenselast el on el.idexp = e.idexp 
						JOIN payment p on el.kpay=p.kpay
						JOIN paymenttransmission pt
							ON pt.kpaymenttransmission = p.kpaymenttransmission
						WHERE pt.transmissiondate <= @date_3112_previous_year
							AND p.ypay = @ayear-1
							AND pt.ypaymenttransmission=@ayear-1
							AND
							(SELECT COUNT(*) FROM banktransaction PD
							WHERE PD.kpay=P.kpay AND
							PD.transactiondate <= @date_3112_previous_year) = 0
				DECLARE @previous_proc_partially_performed 	decimal(19,2)
				-- Reversali di anni precedenti trasmesse e parzialmente esitate (importo rimasto da esitare)
				SET 	@previous_proc_partially_performed = 
				ISNULL(@previous_proc_communicated,0) - ISNULL(@previous_proc_not_performed,0) -
				ISNULL(
					(SELECT
					SUM(bt.amount)
					FROM banktransaction bt
					JOIN proceeds p
						ON p.kpro = bt.kpro
					JOIN proceedstransmission pt
						ON pt.kproceedstransmission = p.kproceedstransmission
					WHERE bt.transactiondate <= @date_3112_previous_year
						AND pt.transmissiondate <= @date_3112_previous_year
						AND p.ypro = (@ayear - 1))
					,0)
				
				DECLARE @previous_pay_partially_performed 	decimal(19,2)
				-- Mandati di anni precedenti trasmessi e parzialmente esitati (importo rimasto da esitare)
				SET 	@previous_pay_partially_performed =
				ISNULL(@previous_pay_communicated,0) - ISNULL(@previous_pay_not_performed,0) -
				ISNULL(
					(SELECT
					SUM(bt.amount)
					FROM banktransaction bt
					JOIN payment p
						ON p.kpay = bt.kpay
					JOIN paymenttransmission pt
						ON pt.kpaymenttransmission = p.kpaymenttransmission
					WHERE bt.transactiondate <= @date_3112_previous_year
						AND pt.transmissiondate <= @date_3112_previous_year
						AND p.ypay = (@ayear - 1))
				,0)
				
				DECLARE @treasurer_start 	decimal(19,2)
				SELECT 	@treasurer_start =
					ISNULL(@ff_jan01, 0.0) -
					ISNULL(@previous_proc_not_performed, 0.0) -
					ISNULL(@previous_proc_partially_performed, 0.0) +
					ISNULL(@previous_pay_not_performed, 0.0) +
					ISNULL(@previous_pay_partially_performed, 0.0)
				
				DECLARE @previous_proc_performed decimal(19,2)
				--esiti di reversali di anno precedente
				SELECT 	@previous_proc_performed =
					ISNULL(SUM(pd.amount),0) 
					FROM banktransaction pd 
					JOIN proceeds p
						ON p.kpro=pd.kpro 
					JOIN proceedstransmission pt
						ON pt.kproceedstransmission = p.kproceedstransmission
					WHERE 	p.ypro=@ayear-1
						AND PD.transactiondate > @date_3112_previous_year
						AND PD.transactiondate <= @date 
						AND pt.transmissiondate <= @date 
				DECLARE @previous_pay_performed decimal(19,2)
				--esiti di mandati di anno precedente
				SELECT 	@previous_pay_performed = 
					ISNULL(SUM(pd.amount),0)
					FROM banktransaction pd 
					JOIN payment p
						ON p.kpay=pd.kpay
					JOIN paymenttransmission pt
						ON pt.kpaymenttransmission = p.kpaymenttransmission
					WHERE 	p.ypay=@ayear-1
						AND PD.transactiondate > @date_3112_previous_year
						AND PD.transactiondate <= @date 
						AND pt.transmissiondate <= @date 
			END
		ELSE
			BEGIN
				SELECT @display_previous_year = 'N'
				SET @treasurer_start = ISNULL(
					(SELECT	
					SUM(treasurerstart.amount)
					FROM treasurerstart
					JOIN treasurer
						ON treasurer.idtreasurer = treasurerstart.idtreasurer
						--AND treasurer.flagdefault = 'S'
					WHERE treasurerstart.ayear = @ayear),0)
			END
		DECLARE @proc_communicated decimal(19,2)
		-- Reversali Trasmesse
		SELECT 	@proc_communicated =
			SUM(et.curramount) from
			incometotal et 
			JOIN income e on et.idinc=e.idinc and et.ayear=@ayear
			JOIN incomelast el on el.idinc = e.idinc 
			JOIN proceeds p on el.kpro = p.kpro
			JOIN proceedstransmission pt
				ON pt.kproceedstransmission = p.kproceedstransmission
			WHERE 	p.ypro = @ayear 
				AND pt.transmissiondate <= @date
				AND PT.yproceedstransmission=@ayear
		
		DECLARE @pay_communicated decimal(19,2)
		-- Mandati Trasmessi
		SELECT 	@pay_communicated =
			SUM(et.curramount) from
			expensetotal et 
			JOIN expense e on et.idexp=e.idexp  and et.ayear=@ayear
			JOIN expenselast el on el.idexp = e.idexp 
			JOIN payment p on el.kpay=p.kpay	
			JOIN paymenttransmission pt
				ON pt.kpaymenttransmission = p.kpaymenttransmission
			WHERE 	p.ypay = @ayear 
				AND pt.transmissiondate <= @date
				AND PT.ypaymenttransmission=@ayear
	
		DECLARE @proc_not_performed decimal(19,2)
		-- Reversali di anno corrente NON ESITATE alla data  
		SELECT 	@proc_not_performed = 
			SUM(et.curramount) from
			incometotal et 
			JOIN income e on et.idinc=e.idinc and et.ayear=@ayear
			JOIN incomelast el on el.idinc = e.idinc 
			JOIN proceeds p on el.kpro = p.kpro
			JOIN proceedstransmission pt
				ON pt.kproceedstransmission = p.kproceedstransmission
			WHERE pt.transmissiondate <= @date
				AND p.ypro=@ayear
				AND PT.yproceedstransmission=@ayear
				AND
				(SELECT COUNT(*) from banktransaction PD
				where PD.kpro=P.kpro and 
				PD.transactiondate <= @date) = 0
		
		
		DECLARE @pay_not_performed decimal(19,2)
		-- Mandati di anno corrente  NON ESITATI alla data  
		SELECT 	@pay_not_performed = 
			SUM(et.curramount) from
			expensetotal et 
			JOIN expense e on et.idexp=e.idexp and et.ayear=@ayear
			JOIN expenselast el on el.idexp = e.idexp 
			JOIN payment p on el.kpay=p.kpay	
			JOIN paymenttransmission pt
			ON pt.kpaymenttransmission = p.kpaymenttransmission
			WHERE pt.transmissiondate <= @date
			AND p.ypay=@ayear
			AND PT.ypaymenttransmission=@ayear
			AND
				(SELECT COUNT(*) from banktransaction PD
				where PD.kpay=P.kpay and 
				PD.transactiondate <= @date) =0
		DECLARE @proc_partially_performed decimal(19,2)
		SET 	@proc_partially_performed = 
		ISNULL(@proc_communicated,0) - ISNULL(@proc_not_performed,0) -
		ISNULL(
			(SELECT
			SUM(bt.amount)
			FROM banktransaction bt
			JOIN proceeds p
				ON p.kpro = bt.kpro
			JOIN proceedstransmission pt
				ON pt.kproceedstransmission = p.kproceedstransmission
			WHERE 	bt.transactiondate <= @date
				AND pt.transmissiondate <= @date
				AND p.ypro = @ayear)
			,0)
		
		
		DECLARE @pay_partially_performed decimal(19,2)
		SET 	@pay_partially_performed =
		ISNULL(@pay_communicated,0) - ISNULL(@pay_not_performed,0) -
		ISNULL(
			(SELECT
			SUM(bt.amount)
			FROM banktransaction bt
			JOIN payment p
				ON p.kpay = bt.kpay
			JOIN paymenttransmission pt
				ON pt.kpaymenttransmission = p.kpaymenttransmission
			WHERE 	bt.transactiondate <= @date
				AND pt.transmissiondate <= @date
				AND p.ypay = @ayear)
			,0)
		
		DECLARE @active_pendings decimal(19,2)
		-- SOSPESI ATTIVI (mov. bancari a credito non collegati a reversali o collegati a reversali trasmessi dopo la data)
		SELECT 	@active_pendings =
				ISNULL(sum(pd.amount),0) from 
				banktransaction pd 
				WHERE pd.yban<= @ayear
					AND kind='C' 
					AND pd.transactiondate <= @date
					AND 	(pd.kpro is null OR 
						  (SELECT PT.transmissiondate from proceeds P 
								join proceedstransmission PT  
								ON pt.kproceedstransmission = p.kproceedstransmission
							WHERE PD.kpro=P.kpro)>@date
						)
		DECLARE @passive_pendings decimal(19,2)
		-- SOSPESI PASSIVI (mov. bancari a debito non collegati a mandati o collegati a mandati  trasmessi dopo la data)
		SELECT 	@passive_pendings =
				ISNULL(sum(pd.amount),0) from 
				banktransaction pd 
				where 
					pd.yban<= @ayear
					and  kind='D' 
					and pd.transactiondate <= @date
					AND 	(pd.kpay is null OR 
						  (SELECT PT.transmissiondate from payment P 
								join paymenttransmission PT  
								ON pt.kpaymenttransmission = p.kpaymenttransmission
							WHERE PD.kpay=P.kpay)>@date
						)
		-- PARTITE PENDENTI ATTIVE (importo non regolarizzato delle partite pendenti aperte per chi usa tale gestione)
		-- calcolo prima l'importo TOTALE delle partite pendenti attive
		-- calcolo l'importo REGOLARIZZATO delle partite pendenti attive
		-- importo da regolarizzare = importo totale - importo regolarizzato
		DECLARE @tot_partite_pendenti_attive decimal(19,2)
		DECLARE @covered_partite_pendenti_attive decimal(19,2)
		DECLARE @partite_pendenti_attive decimal(19,2)
		
		SELECT  @tot_partite_pendenti_attive = ISNULL(SUM(bill.total), 0)
		FROM bill WHERE bill.ybill = @ayear 
			AND bill.billkind='C' 
			AND active = 'S'
			AND bill.adate <= @date
		
		SET @tot_partite_pendenti_attive = ISNULL(@tot_partite_pendenti_attive,0)
		
		/*
		SELECT  @covered_partite_pendenti_attive = ISNULL(SUM(incometotal.curramount), 0)
			FROM income
			JOIN incomelast
				ON income.idinc = incomelast.idinc
			JOIN incometotal incometotal(NOLOCK)
  				ON incometotal.idinc = income.idinc
  				AND ((incometotal.flag & 2) <> 0 )
			JOIN proceeds
				ON incomelast.kpro = proceeds.kpro
			JOIN proceedstransmission 
				ON proceedstransmission.kproceedstransmission = proceeds.kproceedstransmission
			JOIN bill ON bill.ybill = @ayear 
				AND income.ymov = bill.ybill
				AND incomelast.nbill = bill.nbill
				AND bill.billkind='C' 
				AND bill.active = 'S'
				AND bill.adate <= @date
		*/
				
		SELECT  @covered_partite_pendenti_attive = 
		ISNULL((SELECT
			SUM(bt.amount)
			FROM banktransaction bt
			JOIN proceeds p
				ON p.kpro = bt.kpro
			JOIN incomelast
				ON incomelast.kpro = p.kpro
			JOIN bill 
				ON bill.ybill  = @ayear
				AND bill.nbill = incomelast.nbill
			WHERE 	bt.transactiondate <= @date
				AND bt.yban = @ayear
				AND bt.idinc = incomelast.idinc
				AND bill.billkind='C' 
				AND bill.active = 'S'
				AND bill.adate <= @date
				)
			,0)
		SET @covered_partite_pendenti_attive = ISNULL(@covered_partite_pendenti_attive,0)
		
		
		-- Partite Pendenti regolarizzate le cui reversali sono state trasmesse DOPO la data di stampa
		DECLARE @covered_partite_pendenti_attive_PostDate decimal(19,2)
		SELECT  @covered_partite_pendenti_attive_PostDate = 
		ISNULL((SELECT
			SUM(bt.amount)
			FROM banktransaction bt
			JOIN proceeds p
				ON p.kpro = bt.kpro
			JOIN incomelast
				ON incomelast.kpro = p.kpro
			JOIN bill 
				ON bill.ybill  = @ayear
				AND bill.nbill = incomelast.nbill
			JOIN proceedstransmission t
				ON t.kproceedstransmission = p.kproceedstransmission
			WHERE t.transmissiondate > @date
				AND bt.yban = @ayear
				AND bt.idinc = incomelast.idinc
				AND bill.billkind='C' 
				AND bill.active <> 'S'
				AND bill.adate <= @date
				)
			,0)
		
		-- Importo scoperto (da regolarizzare) delle partite pendenti attive +  P.P.regolarizzate le cui reversali sono state trasmesse DOPO la data di stampa
		-- l'aggiunta del terzo addendo consente di storicizzare la stampa
		SELECT 	@partite_pendenti_attive =  @tot_partite_pendenti_attive - @covered_partite_pendenti_attive + @covered_partite_pendenti_attive_PostDate

		-- PARTITE PENDENTI PASSIVE (importo non regolarizzato delle partite pendenti aperte per chi usa tale gestione)
		-- calcolo prima l'importo TOTALE delle partite pendenti passive
		-- calcolo l'importo REGOLARIZZATO delle partite pendenti passive
		-- importo da regolarizzare = importo totale - importo regolarizzato
		DECLARE @tot_partite_pendenti_passive decimal(19,2)
		DECLARE @covered_partite_pendenti_passive decimal(19,2)
		DECLARE @partite_pendenti_passive decimal(19,2)
		
		SELECT  @tot_partite_pendenti_passive = ISNULL(SUM(bill.total), 0)
		FROM bill WHERE bill.ybill = @ayear 
			AND bill.billkind='D' 
			AND active = 'S'
			AND bill.adate <= @date
	
		SET @tot_partite_pendenti_passive = ISNULL(@tot_partite_pendenti_passive,0)
		
		/*
		SELECT @covered_partite_pendenti_passive = 
		ISNULL(SUM(expensetotal.curramount), 0)
		FROM expense
		JOIN expenselast
			ON expense.idexp = expenselast.idexp 
		JOIN expensetotal expensetotal(NOLOCK)
			ON expensetotal.idexp = expense.idexp
			AND ((expensetotal.flag & 2) <> 0 )
		JOIN payment 
			ON expenselast.kpay = payment.kpay
		JOIN paymenttransmission 
			ON paymenttransmission.kpaymenttransmission = payment.kpaymenttransmission
		JOIN bill ON bill.ybill = @ayear 
			AND expense.ymov = bill.ybill
			AND expenselast.nbill = bill.nbill
			AND bill.billkind='D' 
			AND bill.active  = 'S'
			AND bill.adate <= @date*/
		SELECT  @covered_partite_pendenti_passive = 
		ISNULL((SELECT
			SUM(bt.amount)
			FROM banktransaction bt
			JOIN payment p
				ON p.kpay = bt.kpay
			JOIN expenselast
				ON expenselast.kpay = p.kpay
			JOIN bill 
				ON bill.ybill  = @ayear
				AND bill.nbill = expenselast.nbill
			WHERE 	bt.transactiondate <= @date
				AND bt.yban = @ayear
				AND bt.idexp = expenselast.idexp
				AND bill.billkind='D' 
				AND bill.active = 'S'
				AND bill.adate <= @date
				)
			,0)
			
		SET @covered_partite_pendenti_passive = ISNULL(@covered_partite_pendenti_passive,0)
		-- Partite Pendenti regolarizzate i cui mandati sono stati trasmessi DOPO la data di stampa
		DECLARE @covered_partite_pendenti_passive_PostDate decimal(19,2)
		SELECT  @covered_partite_pendenti_passive_PostDate = 
		ISNULL((SELECT
			SUM(bt.amount)
			FROM banktransaction bt
			JOIN payment p 
				ON p.kpay = bt.kpay
			JOIN expenselast
				ON expenselast.kpay = p.kpay
			JOIN bill 
				ON bill.ybill  = @ayear
				AND bill.nbill = expenselast.nbill
			JOIN paymenttransmission t
				ON t.kpaymenttransmission = p.kpaymenttransmission
			WHERE t.transmissiondate > @date -- solo > e non >= perchè se =, ossia se le ho trasmesse nel giorno della stampa, le troverò nella sezione incassate ma non trasmesse
				AND bt.yban = @ayear
				AND bt.idexp = expenselast.idexp
				AND bill.billkind='D' 
				AND bill.active <> 'S'
				AND bill.adate <= @date
				)
			,0)
		
		-- Importo scoperto (da regolarizzare) delle partite pendenti passive +  P.P. regolarizzate i cui mandati sono stati trasmessi DOPO la data di stampa
		-- l'aggiunta del terzo addendo consente di storicizzare la stampa
		SELECT 	@partite_pendenti_passive =  @tot_partite_pendenti_passive - @covered_partite_pendenti_passive + @covered_partite_pendenti_passive_PostDate
	
		SELECT
		 	@ff_jan01 					 'floatfundinitial',
			@previous_proc_not_performed 			 'previousprocnotperformed',
			@previous_proc_partially_performed 		 'revprecparzesitate',
			@previous_pay_not_performed 			 'previouspaynotperformed',
			@previous_pay_partially_performed 		 'previouspaypartialperformed',
			@treasurer_start 				 'initialbalance',
			@proc_communicated 				 'proctransmitted',
			@proc_not_performed 				 'procnotperformed',
			@proc_partially_performed 			 'procpartiallyperformed',
			@pay_communicated 				 'paytransmitted',
			@pay_not_performed 				 'paynotperformed',
			@pay_partially_performed 			 'paypartiallyperformed',
			@active_pendings 				 'activependings',
			@passive_pendings 				 'passivependings',
			ISNULL(@previous_proc_performed, 0.0) 		 'previousprocperformed',
			ISNULL(@previous_pay_performed, 0.0) 		 'previouspayperformed',
			@display_previous_year 				 'previousyeardisp',
			@partite_pendenti_attive 			 'pendenti_attive',
			@partite_pendenti_passive 			 'pendenti_passive'
	END


GO

print 'rpt_verifica_saldo_cc OK'

