if object_id('rpt_sitbilancio_respons') is not null
	drop PROCEDURE rpt_sitbilancio_respons
go

CREATE     PROCEDURE rpt_sitbilancio_respons
	@ayear				int,
	@nlevel				tinyint,
	@hierarchy			char(1),
	@idman				int,
	@idupb				varchar(36),
	@showupb 			char(1),
	@showchildupb 			char(1),
	@suppressifblank 		char(1),
	@codefin			varchar(50),
	@start datetime,
	@stop datetime
	AS
	BEGIN
/* Versione 1.0.3 del 17/10/2007 ultima modifica: SARA */
DECLARE @idfin int
IF (@codefin IS NULL OR @codefin = '' OR @codefin = '%')
	BEGIN
		SET @idfin = null	
	END
Else
	BEGIN
	   	SET @idfin = (select idfin 
				from fin 
				where codefin = @codefin 
				and ayear=@ayear 
				and (fin.flag&1)=0) -- Entrata
	END
	CREATE TABLE #fin_situation
	(
		idupb 			varchar(36),
		codeupb			varchar(50),
		upb   			varchar(150),
		upbprintingorder	varchar(50),
		idfin			int,
		codefin			varchar(50),
		title			varchar(150),
		finprintingorder	varchar(50),
		nlevel			varchar(20),
		idman			int,
		manager			varchar(150),
		initialprevision	decimal(19,2),
		var_prevision		decimal(19,2),
		assessments		decimal(19,2),
		var_assessments		decimal(19,2),
		proceeds         	decimal(19,2),
		var_proceeds          	decimal(19,2)
	)
		
	
	DECLARE @idupboriginal 		varchar(36)
	SET @idupboriginal= @idupb
	IF (@showchildupb = 'S') set @idupb=@idupb+'%' 
	
	DECLARE @assessmentphase	tinyint
	SELECT  @assessmentphase = assessmentphasecode
	FROM    config
	WHERE   ayear = @ayear
	DECLARE @phasemax		tinyint
	SELECT  @phasemax = MAX(nphase)
	FROM    incomephase
	DECLARE @flag_cs		char(1)
	SELECT 	@flag_cs =  
	CASE 
		WHEN fin_kind IN (1,3) THEN 'C'
		WHEN fin_kind = 2 THEN 'S'
	END
	FROM 	config
	WHERE 	ayear = @ayear
	DECLARE @cashvaliditykind	int
	SELECT 	@cashvaliditykind = cashvaliditykind
	FROM 	config
	WHERE 	ayear = @ayear
	declare @levelidfin int
	select  @levelidfin = nlevel from fin where idfin=@idfin
	IF (@suppressifblank = 'S')
	BEGIN
		INSERT INTO #fin_situation
	    	  (	idfin, 
			codeupb,	
			idupb,
			upb,
			upbprintingorder,
			codefin,
			title,
			finprintingorder,
			nlevel,
			idman,
			manager)
		  SELECT 
			fin.idfin,
			codeupb,	
			upb.idupb,
			upb.title ,
			upb.printingorder,
			fin.codefin,
			fin.title, 
			fin.printingorder,
			fin.nlevel,
			manager.idman,
			manager.title
		FROM upbtotal
		join upb 
			on  upbtotal.idupb = upb.idupb
		JOIN fin
			ON  upbtotal.idfin = fin.idfin
		JOIN finlast
			ON  fin.idfin = finlast.idfin
		JOIN finlevel
			ON finlevel.nlevel = fin.nlevel
			AND finlevel.ayear = fin.ayear
			AND (finlevel.flag&2)<>0
		LEFT OUTER JOIN finlink
			ON  finlink.idchild = fin.idfin and finlink.nlevel>=@levelidfin
		JOIN manager
			ON upb.idman = manager.idman
		WHERE ((fin.flag&1)=0) --  'E'
			AND ((upb.idman = @idman) OR  (@idman is null and upb.idman is not null))	
			AND (fin.ayear = @ayear)
			AND (@idfin IS NULL OR ISNULL(finlink.idparent,fin.idfin) = @idfin)
	    		AND (upb.idupb like @idupb )
			AND ((@hierarchy ='N' AND fin.nlevel = @nlevel)OR (@hierarchy ='S' and fin.nlevel >=  @nlevel))
END	
	ELSE
	BEGIN
		INSERT INTO #fin_situation
	    	  (	idfin, 
			codeupb,	
			idupb,
			upb,
			upbprintingorder,
			codefin,
			title,
			finprintingorder,
			nlevel,
			idman,
			manager)
		  SELECT 
			fin.idfin,
			upb.codeupb,	
			upb.idupb,
			upb.title ,
			upb.printingorder,
			fin.codefin,
			fin.title, 
			fin.printingorder,
			fin.nlevel,
			manager.idman,
			manager.title
		FROM fin 
		CROSS JOIN upb
		JOIN finlast
			ON  fin.idfin = finlast.idfin
		JOIN finlevel
			ON  finlevel.nlevel = fin.nlevel
			AND finlevel.ayear = fin.ayear
			AND (finlevel.flag&2)<>0
		LEFT OUTER JOIN finlink
			ON  finlink.idchild = fin.idfin and finlink.nlevel=@levelidfin
		JOIN manager 
			ON upb.idman = manager.idman
		LEFT OUTER JOIN finyear
			ON finyear.idfin = fin.idfin
			AND finyear.idupb = upb.idupb and finyear.ayear = @ayear	
		WHERE ((fin.flag&1)=0) -- Entrata
			AND ((upb.idman = @idman) OR (@idman is null and upb.idman is not null))	
			AND (fin.ayear = @ayear)
			AND (@idfin IS NULL OR ISNULL(finlink.idparent,fin.idfin) = @idfin)
			AND (upb.idupb like @idupb)
			AND ((@hierarchy ='N' and fin.nlevel = @nlevel)OR (@hierarchy ='S' and fin.nlevel >=  @nlevel))
		END
	UPDATE #fin_situation
	SET initialprevision = 
			ISNULL((SELECT SUM(finyear.prevision)
			FROM finyear 
			join fin 
				on finyear.idfin = fin.idfin  				
			JOIN upb
				on finyear.idupb = upb.idupb 
			JOIN finlevel 
				ON finlevel.ayear = fin.ayear
				AND finlevel.nlevel = fin.nlevel
				AND (finlevel.flag&2)<>0
			JOIN finlink
				ON  finlink.idchild = fin.idfin 
			JOIN finlast
				ON  fin.idfin 	= finlast.idfin
			WHERE finlink.idparent  = #fin_situation.idfin
				AND upb.idupb 	=  #fin_situation.idupb
				AND fin.ayear 	= @ayear
				AND finyear.ayear = @ayear), 0.0),
 	var_prevision = 
			ISNULL((SELECT SUM(finvardetail.amount) 
			FROM finvardetail
			JOIN finvar
      				ON finvardetail.yvar = finvar.yvar 
				AND finvardetail.nvar = finvar.nvar
			JOIN finlink
				ON  finlink.idchild = finvardetail.idfin 
			WHERE finvar.yvar = @ayear 
				AND finlink.idparent = #fin_situation.idfin
				AND finvardetail.idupb = #fin_situation.idupb 
				AND finvar.flagprevision ='S'	
				AND finvar.idfinvarstatus = 5	
				AND finvar.variationkind <> 5
				AND finvar.adate between @start and @stop), 0.0)
	UPDATE #fin_situation
		SET assessments = 
			ISNULL((SELECT SUM(incomeyear.amount)
			FROM incomeyear
			JOIN income
				ON income.idinc = incomeyear.idinc
				AND income.adate between @start and @stop 
				AND income.nphase = @assessmentphase
			JOIN incometotal
				ON  incomeyear.idinc = incometotal.idinc
				AND incomeyear.ayear = incometotal.ayear
			JOIN finlink
				ON  finlink.idchild = incomeyear.idfin 
			WHERE incomeyear.ayear = @ayear
				AND (((incometotal.flag&1)= 0)
				OR @flag_cs = 'S')
				AND finlink.idparent = #fin_situation.idfin
				and incomeyear.idupb = #fin_situation.idupb), 0.0),
		var_assessments =
			ISNULL((SELECT SUM(incomevar.amount)
			FROM incomevar
			JOIN incomeyear
				ON incomeyear.idinc = incomevar.idinc
				AND incomeyear.ayear = @ayear
			JOIN income
				ON income.idinc = incomeyear.idinc
			JOIN finlink
				ON  finlink.idchild = incomeyear.idfin 
			JOIN incometotal
				ON incomeyear.idinc = incometotal.idinc
				AND incomeyear.ayear = incometotal.ayear
			WHERE incomevar.adate between @start and @stop 
			AND income.nphase = @assessmentphase
			AND incomevar.yvar = @ayear
			AND finlink.idparent = #fin_situation.idfin
			AND incomeyear.idupb = #fin_situation.idupb
			AND (((incometotal.flag&1)= 0) -- Competenza
			OR @flag_cs = 'S')), 0.0)
	
	UPDATE #fin_situation
		SET proceeds = 
			ISNULL((SELECT SUM(HPV.amount)
				FROM historyproceedsview HPV
				JOIN finlink
					ON  finlink.idchild = HPV.idfin 
				WHERE   HPV.ymov  = @ayear
					AND HPV.competencydate between @start and @stop
					AND (((HPV.totflag&1)= 0) -- Competenza
					OR  @flag_cs = 'S')
					AND finlink.idparent = #fin_situation.idfin
					AND HPV.idupb = #fin_situation.idupb), 0.0)
	IF @cashvaliditykind <> 4
	BEGIN	
		UPDATE #fin_situation
			SET var_proceeds =
				ISNULL((SELECT SUM(incomevar.amount)
					FROM incomevar
					JOIN historyproceedsview HPV 						
						ON HPV.idinc = incomevar.idinc
						AND HPV.ymov = @ayear
					JOIN finlink
						ON  finlink.idchild = HPV.idfin 
					WHERE incomevar.yvar = @ayear
						AND incomevar.adate between @start and @stop
						AND HPV.competencydate between @start and @stop
						AND (((HPV.totflag&1)= 0) -- Competenza
						OR @flag_cs = 'S')
						AND finlink.idparent = #fin_situation.idfin
						AND HPV.idupb = #fin_situation.idupb), 0.0)
	END
	IF (@showupb <>'S') AND (@idupboriginal <> '%' ) AND (@showchildupb = 'S')
			UPDATE #fin_situation SET  
				upbprintingorder = (SELECT TOP 1 upbprintingorder
					FROM #fin_situation
					WHERE idupb = @idupboriginal),
				upb = (SELECT TOP 1 upb
					FROM #fin_situation
					WHERE idupb = @idupboriginal),
				idupb = @idupboriginal,
				codeupb =(SELECT TOP 1 codeupb
					FROM #fin_situation	
					WHERE idupb = @idupboriginal)
	
	IF (@showupb <>'S') and (@idupboriginal = '%') 
				UPDATE #fin_situation SET  
				upbprintingorder = null	,
				upb =  null,
				idupb = null,
				codeupb = null
IF (@suppressifblank = 'S') 	--> cancella le righe  sottostante la categoria
BEGIN
	DELETE FROM #fin_situation WHERE 
			(isnull(initialprevision,0.0) =0 AND 
			isnull(var_prevision,0.0) =0 AND 
			isnull(assessments,0.0) =0 AND 
			isnull(var_assessments,0.0) =0 AND 
			isnull(proceeds,0.0) =0 AND 
			isnull(var_proceeds,0.0) =0 
			AND nlevel >=2)
END
			
IF (@showupb <>'S') 
BEGIN		
	SELECT 
		idfin,
		codeupb,
		idupb,
		upb,
		upbprintingorder,
		codefin,
		title,
		finprintingorder,
		nlevel,
		idman,
		manager,
		sum(isnull(initialprevision,0.0)) as 'initialprevision',
		sum(isnull(var_prevision,0.0)) as 'var_prevision',
		sum(isnull(assessments,0.0)) as 'assessments',
		sum(isnull(var_assessments,0.0)) as 'var_assessments',		
		sum(isnull(proceeds,0.0)) as 'proceeds',
		sum(isnull(var_proceeds,0.0)) as 'var_proceeds'
	FROM #fin_situation 
		group by upbprintingorder,finprintingorder,
		idfin,
		codeupb,
		idupb,
		upb,
		codefin,
		title,
		nlevel,
		idman,
		manager		
	ORDER BY manager
END
ELSE
	SELECT 
		idfin,
		codeupb,
		idupb,
		upb,
		upbprintingorder,
		codefin,
		title,
		finprintingorder,
		nlevel,
		idman,
		manager,
		initialprevision,
		var_prevision,
		assessments,
		var_assessments,
		proceeds,
		var_proceeds  
	FROM #fin_situation ORDER BY manager
END


GO

print 'rpt_sitbilancio_respons OK'

