CREATE               PROCEDURE [esporta_buoni_senza_ratifica]
AS BEGIN
SELECT
	assetloadkind.description 'Tipo Buono',
	assetload.yassetload 'Eserc.Buono',
	assetload.nassetload 'Num.Buono',
	assetload.adate 'Data Contabile'
