if object_id('[rpt_residui_per_anno]') is not null
	drop PROCEDURE [rpt_residui_per_anno]
go


CREATE     PROCEDURE [rpt_residui_per_anno]
	@ayear 		int,
	@date		datetime,
	@finpart 	char(1),
	@levelusable 	tinyint,
	@idupb		varchar(36),
	@showupb 	char(1),
	@showchildupb 	char(1)
AS
BEGIN
DECLARE @idupboriginal varchar(36)
SET @idupboriginal= @idupb
IF (@showchildupb = 'S') set @idupb=@idupb + '%' 

DECLARE @cash_phase tinyint
DECLARE @finphase   tinyint
IF @finpart = 'E'
	BEGIN
		SELECT @finphase = assessmentphasecode
		FROM config
		WHERE ayear = @ayear
		IF @finphase IS NULL
			BEGIN
				SELECT @finphase = incomefinphase
				FROM uniconfig
			END
		SELECT @cash_phase = MAX(nphase)
		FROM incomephase
	END
ELSE
	BEGIN
		SELECT @finphase = appropriationphasecode
			FROM config
			WHERE ayear = @ayear
		IF @finphase IS NULL
			BEGIN
				SELECT @finphase = expensefinphase
				FROM uniconfig
			END
		SELECT @cash_phase = MAX(nphase)
		FROM expensephase
	END
CREATE TABLE #initial_residual
	(ayear int, idfin int, idupb varchar(36), total decimal(19,2))
CREATE TABLE #var_residual
	(ayear int, idfin int, idupb varchar(36), total decimal(19,2))
	
CREATE TABLE #cash_residual
	(ayear int, idfin int, idupb varchar(36), total decimal(19,2))
CREATE TABLE #var_cash_residual
    	(ayear int, idfin int, idupb varchar(36), total decimal(19,2))
IF @finpart = 'E'
BEGIN
	INSERT INTO #initial_residual
		(
		ayear,
		idfin,
		idupb,
		total
		)
	SELECT
		income.ymov,
		finlink.idparent, 
		incomeyear.idupb,
		SUM(ISNULL(incomeyear.amount, 0.0))
	FROM incomeyear
	JOIN income
		ON income.idinc = incomeyear.idinc
	JOIN finlink
		ON finlink.idchild = incomeyear.idfin  AND finlink.nlevel = @levelusable
	JOIN incometotal
		ON  incomeyear.idinc = incometotal.idinc
		AND incomeyear.ayear = incometotal.ayear			
	WHERE incomeyear.ayear = @ayear
		AND (incomeyear.idupb like @idupb )
		AND income.adate <= @date
		AND ((incometotal.flag&1) = 1) -- Residuo
		AND income.nphase = @finphase
	GROUP BY income.ymov,incomeyear.idupb,finlink.idparent
	INSERT INTO #var_residual
		(
		ayear,
		idfin,
		idupb,
		total
		)
	SELECT
		income.ymov,
		finlink.idparent,
		incomeyear.idupb,
		SUM(ISNULL(incomevar.amount, 0.0))
	FROM incomevar
	JOIN incomeyear
		ON incomeyear.idinc = incomevar.idinc
		AND incomeyear.ayear = @ayear
	JOIN income
		ON incomeyear.idinc = income.idinc
	JOIN finlink
		ON finlink.idchild = incomeyear.idfin  AND finlink.nlevel = @levelusable
	JOIN incometotal
		ON  incomeyear.idinc = incometotal.idinc
		AND incomeyear.ayear = incometotal.ayear			
	WHERE incomevar.yvar = @ayear
		AND incomevar.adate <= @date 
		and (incomeyear.idupb like @idupb )
		AND ((incometotal.flag&1) = 1) -- Residuo
		AND income.nphase = @finphase
	GROUP BY income.ymov,incomeyear.idupb, finlink.idparent
	INSERT INTO #cash_residual
		(
		ayear,
		idfin,
		idupb,
		total
		)
	SELECT
		I.ymov,
		FL1.idparent,
		IY.idupb,
		SUM(HPV.amount)
	FROM historyproceedsview HPV
	JOIN incomeyear IY
		ON IY.idinc = HPV.idinc
		AND HPV.ymov = @ayear
	JOIN incomelink IL 
		ON IL.idchild = IY.idinc AND IL.nlevel = @finphase
	JOIN finlink  FL1
		ON FL1.idchild = IY.idfin AND FL1.nlevel = @levelusable
	JOIN income I
		ON IL.idparent = I.idinc 
	JOIN income I1
		ON IY.idinc = I1.idinc 
	JOIN incometotal
		ON  IY.idinc = incometotal.idinc
		AND IY.ayear = incometotal.ayear
	WHERE HPV.competencydate <= @date
		AND IY.idupb LIKE @idupb 
		AND IY.ayear = @ayear
		AND ((incometotal.flag&1) = 1) -- Residuo
		AND I1.nphase = @cash_phase
	GROUP BY I.ymov, IY.idupb,FL1.idparent
	INSERT INTO #var_cash_residual
	    	(
	   	ayear,
	    	idfin,
		idupb,
	    	total
	    	)
	SELECT
			I.ymov,
			FL1.idparent,
			IY.idupb,
			SUM(ISNULL(IV.amount, 0.0))
		FROM incomevar IV
		JOIN incomeyear IY
			ON  IY.idinc = IV.idinc
			AND IY.ayear = @ayear
		JOIN incomelink IL 
			ON IL.idchild = IY.idinc AND IL.nlevel = @finphase
		JOIN finlink  FL1
			ON FL1.idchild = IY.idfin AND FL1.nlevel = @levelusable
		JOIN income I
			ON I.idinc = IL.idparent
		JOIN income I1
			ON I1.idinc = IY.idinc 
		JOIN incometotal
			ON  IY.idinc = incometotal.idinc
			AND IY.ayear = incometotal.ayear
		JOIN historyproceedsview HPV
			ON HPV.idinc = IV.idinc
			AND HPV.ymov = @ayear
		WHERE IV.yvar = @ayear
			AND IV.adate <= @date
			AND IY.idupb like @idupb
			AND ((incometotal.flag&1) = 1) -- Residuo
			AND I1.nphase = @cash_phase
			AND HPV.competencydate <= @date
		GROUP BY I.ymov, IY.idupb,FL1.idparent
END
IF @finpart = 'S'
BEGIN
	INSERT INTO #initial_residual
		(
		ayear,
		idfin,
		idupb,
		total
		)
	SELECT
		expense.ymov,
		finlink.idparent,
		expenseyear.idupb,
		SUM(ISNULL(expenseyear.amount, 0.0))
	FROM expenseyear
	JOIN expense
		ON expense.idexp = expenseyear.idexp
	JOIN finlink
		ON finlink.idchild = expenseyear.idfin  AND finlink.nlevel = @levelusable
	JOIN expensetotal
		ON  expenseyear.idexp = expensetotal.idexp
		AND expenseyear.ayear = expensetotal.ayear			
	WHERE expenseyear.ayear = @ayear
		AND (expenseyear.idupb like @idupb )
		AND ((expensetotal.flag&1) = 1) -- Residuo
		AND expense.nphase = @finphase
		AND expense.adate <= @date
	GROUP BY expense.ymov,expenseyear.idupb, finlink.idparent
	INSERT INTO #var_residual
		(
		ayear,
		idfin,idupb,
		total
		)
	SELECT
	  	expense.ymov,
		finlink.idparent, 
		expenseyear.idupb,
		SUM(ISNULL(expensevar.amount, 0.0))
	FROM expensevar
	JOIN expenseyear
		ON expenseyear.idexp = expensevar.idexp
		AND expenseyear.ayear = @ayear
	JOIN expense
		ON expenseyear.idexp = expense.idexp
	JOIN finlink
		ON finlink.idchild = expenseyear.idfin  AND finlink.nlevel = @levelusable
	JOIN expensetotal
		ON  expenseyear.idexp = expensetotal.idexp
		AND expenseyear.ayear = expensetotal.ayear			
	WHERE expensevar.yvar = @ayear
		AND (expenseyear.idupb like @idupb )
		AND expensevar.adate <= @date 
		AND ((expensetotal.flag&1) = 1) -- Residuo
		AND expense.nphase = @finphase
		GROUP BY expense.ymov, expenseyear.idupb,finlink.idparent
	
	INSERT INTO #cash_residual
		(
		ayear,
		idfin,
		idupb,
		total
		)
	SELECT
		E.ymov,
		FL1.idparent, 
		EY.idupb,
		SUM(HPV.amount)
	FROM historypaymentview HPV
	JOIN expenseyear EY
		ON  EY.idexp = HPV.idexp
		AND HPV.ymov = @ayear
	JOIN expenselink EL 
		ON EL.idchild = EY.idexp AND EL.nlevel = @finphase
	JOIN finlink  FL1
		ON FL1.idchild = EY.idfin AND FL1.nlevel = @levelusable
	JOIN expense E
		ON EL.idparent = E.idexp
	JOIN expense E1
		ON EY.idexp = E1.idexp 
	JOIN expensetotal
		ON  EY.idexp = expensetotal.idexp
		AND EY.ayear = expensetotal.ayear
	WHERE 	HPV.competencydate <= @date
		AND EY.idupb like @idupb
		AND EY.ayear = @ayear
		AND ((expensetotal.flag&1) = 1) -- Residuo
		AND E1.nphase = @cash_phase
	GROUP BY E.ymov, EY.idupb, FL1.idparent
	INSERT INTO #var_cash_residual
		    (
			ayear,
			idfin,
			idupb,
			total
		    )
	SELECT 
			E.ymov,
			FL1.idparent,
			EY.idupb,
			SUM(ISNULL(EV.amount, 0.0))
		FROM expensevar EV
		JOIN expenseyear EY 
			ON EY.idexp = EV.idexp
			AND EY.ayear = @ayear
		JOIN expenselink EL 
			ON EL.idchild = EY.idexp AND EL.nlevel = @finphase
		JOIN finlink  FL1
			ON FL1.idchild = EY.idfin AND FL1.nlevel = @levelusable
		JOIN expense E
			ON EL.idparent = E.idexp
		JOIN expense E1
			ON EY.idexp = E1.idexp 
		JOIN expensetotal
			ON  EY.idexp = expensetotal.idexp
			AND EY.ayear = expensetotal.ayear
		JOIN historypaymentview HPV
			ON HPV.idexp = EV.idexp
			AND HPV.ymov = @ayear
		WHERE EV.yvar = @ayear
			AND EV.adate <= @date
			AND ((expensetotal.flag&1) = 1) -- Residuo
			AND E1.nphase = @cash_phase
			AND HPV.competencydate <= @date
			AND (EY.idupb like @idupb )
		GROUP BY E.ymov, EY.idupb,FL1.idparent
END
	
CREATE TABLE #report_residual
(
	ayear			int,
	codeupb			varchar(50),
	idupb 			varchar(36),
	upb   			varchar(100),
	upbprintingorder	varchar(36),
	idfin			varchar(39),
	codefin			varchar(12),
	title			varchar(100),
	finprintingorder	varchar(12),
	initial_residual	decimal(19,2),
	var_residual		decimal(19,2),
	cash_residual		decimal(19,2),
	var_cash_residual	decimal(19,2)				
)
INSERT INTO #report_residual
	(ayear, idfin,idupb)
SELECT DISTINCT ayear,idfin,idupb 
	FROM #initial_residual
INSERT INTO #report_residual
	(ayear, idfin,idupb)
SELECT DISTINCT ayear,idfin,idupb 
	FROM #var_residual
	WHERE (	
		#var_residual.idfin	
		) 
		NOT IN (
			SELECT 	#report_residual.idfin  
			FROM #report_residual	
			)
INSERT INTO #report_residual
 (ayear, idfin,idupb)
SELECT DISTINCT ayear,idfin,idupb
	FROM #cash_residual
	WHERE (
		#cash_residual.idfin
		) 
		NOT IN (
			SELECT 
		 	#report_residual.idfin  
			FROM #report_residual)
		
INSERT INTO #report_residual
(ayear, idfin, idupb)
SELECT DISTINCT ayear,idfin ,idupb
	FROM #var_cash_residual
	WHERE (
		#var_cash_residual.idfin
		) 
		NOT IN (
			SELECT 
		 	#report_residual.idfin  
			FROM #report_residual
			)
UPDATE #report_residual 
SET initial_residual = ISNULL((SELECT #initial_residual.total FROM #initial_residual
		WHERE #initial_residual.idfin = #report_residual.idfin
		and #initial_residual.idupb = #report_residual.idupb
		AND #initial_residual.ayear = #report_residual.ayear), 0.0)
UPDATE #report_residual 
SET var_residual = ISNULL((SELECT #var_residual.total FROM #var_residual
	WHERE #var_residual.idfin = #report_residual.idfin
	and #var_residual.idupb = #report_residual.idupb
	AND #var_residual.ayear = #report_residual.ayear), 0.0)
UPDATE #report_residual
SET cash_residual =	ISNULL((SELECT #cash_residual.total FROM #cash_residual
	WHERE #cash_residual.idfin = #report_residual.idfin
	and #cash_residual.idupb = #report_residual.idupb
	AND #cash_residual.ayear = #report_residual.ayear), 0.0)
UPDATE #report_residual
SET var_cash_residual =	ISNULL((SELECT #var_cash_residual.total FROM #var_cash_residual
	WHERE #var_cash_residual.idfin = #report_residual.idfin
	and #var_cash_residual.idupb = #report_residual.idupb
	AND #var_cash_residual.ayear = #report_residual.ayear), 0.0)
	UPDATE #report_residual SET title = fin.title ,
			finprintingorder = fin.printingorder,
			codefin = fin.codefin	
		 	from fin where fin.idfin = #report_residual.idfin
	UPDATE #report_residual SET codeupb = upb.codeupb ,
			upbprintingorder = upb.printingorder,			
			upb = upb.title
		 from upb where upb.idupb = #report_residual.idupb

	IF (@showupb <>'S') AND (@idupboriginal <> '%' ) AND (@showchildupb = 'S')
			UPDATE #report_residual SET  
				upbprintingorder = (SELECT TOP 1 upbprintingorder
					FROM #report_residual
					WHERE idupb = @idupboriginal),
				upb = (SELECT TOP 1 upb
					FROM #report_residual
					WHERE idupb = @idupboriginal),
				idupb = @idupboriginal,
				codeupb =(SELECT TOP 1 codeupb
					FROM #report_residual	
					WHERE idupb = @idupboriginal)
	
	IF (@showupb <>'S') and (@idupboriginal = '%') 
				UPDATE #report_residual SET  
				upbprintingorder = null	,
				upb =  null,
				idupb = null,
				codeupb = null
IF (@showupb <>'S') 
BEGIN
	SELECT 
		ayear,
		idfin,
		codefin,
		title,
		finprintingorder,
		codeupb,		
		idupb,	
		upb,
		upbprintingorder,
		SUM(ISNULL(initial_residual,0.0)) 	as 'initial_residual',
		SUM(ISNULL(var_residual,0.0)) 		as 'var_residual',
		SUM(ISNULL(cash_residual,0.0)) 		as 'cash_residual',
		SUM(ISNULL(var_cash_residual,0.0)) 	as 'var_cash_residual'
	FROM #report_residual
	group by upbprintingorder,finprintingorder,
	ayear,idfin,codefin,title,codeupb,idupb,upb   			
	ORDER BY ayear ASC,upbprintingorder ASC,finprintingorder ASC
END 
ELSE
	SELECT 
		ayear,
		idfin,
		codefin,
		title,
		finprintingorder,
		codeupb,		
		idupb,	
		upb,
		upbprintingorder,
		initial_residual,
		var_residual,
		cash_residual,
		var_cash_residual
	FROM #report_residual
	ORDER BY ayear ASC,upbprintingorder ASC,finprintingorder ASC
END


GO

print '[rpt_residui_per_anno] OK'

GO
if object_id('[compute_transf_finvar_in_budgetvar]') is not null
	drop PROCEDURE [compute_transf_finvar_in_budgetvar]
go

CREATE PROCEDURE [compute_transf_finvar_in_budgetvar]
(
	@ayear int,
	@idsorkind int,
	@replace char(1)
)
AS BEGIN
-- compute_transf_finvar_in_budgetvar 2013, 21, 'N'
CREATE TABLE #budgetvar
(
	ybudgetvar int,
	nbudgetvar int,
	yvar int,
	nvar int,
	adate smalldatetime ,
	description varchar(150),
	official char(1),
	nofficial int,
	idsor02	int,
	idsor03	int,
	idsor04	int,
	idsor05	int,
	new char(1)
)
CREATE TABLE #budgetvardetail
(
	ybudgetvar int,
	nbudgetvar int,
	yvar int,
	nvar int,
	rownum int,
	idupb varchar(36),
	idfin int,
	amount decimal (19,2),
	idsor int,
	description varchar(150)
)

INSERT INTO #budgetvardetail
(	yvar,	nvar,	rownum,	idupb,	idfin,	amount,	idsor,	description )
SELECT 
	fd.yvar,	fd.nvar,	fd.rownum,	u.idupb,	f.idfin,	fd.amount,	s.idsor,	fd.description
FROM finvardetail fd
JOIN finvar fv			ON fv.yvar = fd.yvar AND fv.nvar = fd.nvar
JOIN fin f		        ON f.idfin = fd.idfin 
JOIN finlast fl			ON f.idfin = fl.idfin
JOIN upb u				ON u.idupb = fd.idupb
JOIN finsorting fs		ON f.idfin = fs.idfin
JOIN sorting s			ON  s.idsor = fs.idsor
WHERE f.ayear = @ayear
  AND s.idsorkind = @idsorkind
  AND ISNULL(fv.official,'N') = 'S'
  AND fv.idfinvarstatus = 5
  AND ISNULL(fv.flagprevision,'N') = 'S'
  
INSERT INTO #budgetvar
(	yvar,	nvar,	adate ,	description,	idsor02,	idsor03,	idsor04,	idsor05,	new)
SELECT 
	fv.yvar,	fv.nvar,	fv.adate,	fv.description,	fv.idsor02,	fv.idsor03,	fv.idsor04,	fv.idsor05,	'N'
FROM finvar fv
WHERE EXISTS (SELECT * 
				FROM #budgetvardetail 
			   WHERE #budgetvardetail.yvar = fv.yvar AND
					 #budgetvardetail.nvar = fv.nvar)
UPDATE #budgetvar set new = 'S'
WHERE  NOT EXISTS (SELECT * FROM budgetvar B 
					WHERE B.yvar = #budgetvar.yvar AND
					      B.nvar = #budgetvar.nvar AND
					      B.idsorkind = @idsorkind)
					         
UPDATE #budgetvar 
   SET 
		ybudgetvar = B.ybudgetvar,
		nbudgetvar = B.nbudgetvar
FROM budgetvar B 
WHERE B.yvar = #budgetvar.yvar AND
	  B.nvar = #budgetvar.nvar AND
      B.idsorkind = @idsorkind AND
      #budgetvar.new = 'N'
UPDATE #budgetvardetail 
   SET 
		ybudgetvar = B.ybudgetvar,
		nbudgetvar = B.nbudgetvar
FROM #budgetvar B 
WHERE B.yvar = #budgetvardetail.yvar AND
	  B.nvar = #budgetvardetail.nvar AND
      B.new = 'N'
--SELECT * FROM #budgetvar
--SELECT * FROM #budgetvardetail 

DECLARE @insertdate datetime
--SET		@insertdate = CONVERT(datetime, CONVERT(char(2),Day(GetDate())) +  '-' + CONVERT(char(2),Month(GetDate()))  + '-' + Convert(char(4),Year(GetDate())) ,105)
set @insertdate = CAST(FLOOR(CAST( getdate() AS float )) AS datetime)	
DECLARE @yvar int
DECLARE @nvar int
DECLARE @nbudgetvar   int 
DECLARE rowcursor INSENSITIVE CURSOR FOR
SELECT  yvar,nvar
FROM    #budgetvar 
WHERE   #budgetvar.new = 'S'
ORDER BY yvar, nvar
FOR READ ONLY
OPEN rowcursor
FETCH NEXT FROM rowcursor
INTO @yvar, @nvar
WHILE @@FETCH_STATUS = 0
BEGIN 

	
		SET 	@nbudgetvar   = ISNULL((SELECT MAX(nbudgetvar) FROM budgetvar WHERE ybudgetvar = @ayear),0) +1
		PRINT 	@nbudgetvar
		
		INSERT INTO budgetvar 
		(
				nbudgetvar,	ybudgetvar,
				yvar,		nvar,		adate,		description,
				rtf,		txt,
				official,		nofficial,
				idbudgetvarstatus,
				idsorkind,
				ct,			cu,			lt,			lu
		)
		SELECT 
				@nbudgetvar,	@ayear,
				yvar,			nvar,	@insertdate,		#budgetvar.description,
				null,		null,
				'N',
				null,
				5,
				@idsorkind,
				GetDate(),	'finvar_trasf',		GetDate(),	'finvar_trasf'	
				FROM  #budgetvar 
				WHERE #budgetvar.yvar = @yvar 
				AND   #budgetvar.nvar = @nvar
			
			INSERT INTO budgetvardetail
			(
				nbudgetvar,	ybudgetvar,	idupb,amount,	description,idsor,	rownum,
				ct,				cu,				lt,				lu
			)
			SELECT 
				@nbudgetvar,	@ayear,	#budgetvardetail.idupb,	#budgetvardetail.amount,	#budgetvardetail.description,
				#budgetvardetail.idsor,	#budgetvardetail.rownum,
				GetDate(),		'finvar_trasf',			GetDate(),			'finvar_trasf'
			FROM #budgetvardetail
		   WHERE #budgetvardetail.yvar = @yvar
			 AND #budgetvardetail.nvar = @nvar	
	
	FETCH NEXT FROM rowcursor
	INTO @yvar, @nvar
END 
DEALLOCATE rowcursor
 
IF (UPPER(@replace) = 'S')
BEGIN
	DELETE FROM budgetvardetail WHERE 
		ybudgetvar = @ayear 
	AND NOT EXISTS (SELECT * 
			 FROM #budgetvardetail
			WHERE #budgetvardetail.ybudgetvar = budgetvardetail.ybudgetvar AND  
			      #budgetvardetail.nbudgetvar = budgetvardetail.nbudgetvar 
			 )
	DELETE FROM budgetvar WHERE 
		ybudgetvar = @ayear 
	AND NOT EXISTS (SELECT * 
			 FROM #budgetvardetail
			WHERE #budgetvardetail.ybudgetvar = budgetvar.ybudgetvar AND  
			      #budgetvardetail.nbudgetvar = budgetvar.nbudgetvar 
			 )
			 			

	DELETE FROM budgetvardetail WHERE 
	EXISTS (SELECT * 
			 FROM #budgetvardetail
			WHERE #budgetvardetail.ybudgetvar = budgetvardetail.ybudgetvar AND  
			      #budgetvardetail.nbudgetvar = budgetvardetail.nbudgetvar 
			 )
			 			      
    INSERT INTO  budgetvardetail
		(
    		nbudgetvar,	ybudgetvar,		idupb,	amount,		
			description,	idsor,	rownum,
			ct,			cu,			lt,			lu
		)
	SELECT 
			#budgetvardetail.nbudgetvar,	#budgetvardetail.ybudgetvar,	#budgetvardetail.idupb,	#budgetvardetail.amount,
			#budgetvardetail.description,	#budgetvardetail.idsor,		#budgetvardetail.rownum,
			GetDate(),			'finvar_trasf',			GetDate(),			'finvar_trasf'
		FROM #budgetvardetail
		JOIN #budgetvar 	  ON #budgetvar.yvar = #budgetvardetail.yvar	 AND #budgetvar.nvar = #budgetvardetail.nvar	
		WHERE #budgetvar.new = 'N'    
END
	
--select * from budgetvar where ybudgetvar = @ayear
--select * from budgetvardetail where ybudgetvar = @ayear
END

GO

print '[compute_transf_finvar_in_budgetvar] OK'

GO
if object_id('[rpt_riepilogoiva]') is not null
	drop PROCEDURE [rpt_riepilogoiva]
go

--setuser 'amministrazione'
--exec rpt_riepilogoiva  1, 2012, 4 , 4,'N','S','PROACQCOMM'
--exec rpt_riepilogoregistroacquisti  1,2009,8,8,'S'
CREATE PROCEDURE [rpt_riepilogoiva]
	@idivaregisterkind int,
	@year int,
	@startmonth int,
	@stopmonth int,
	@official char(1),
    @unified  char(1),
	@codeivaregisterkind  varchar(20)     
AS 
 BEGIN
	CREATE TABLE #ivaregisterkind (
	idivaregisterkind int,
	flagactivity int,
	registerclass char(1),
	description varchar(50)
	)
	IF (@unified ='S')  --Aggiunta Unified
	Begin
		--in questo caso in @idivaregisterkind c'è l'idivaregisterkindunified ed il codice iva del tipo iva scelto  
--		SET @idivaregisterkind = ISNULL((SELECT idivaregisterkind FROM ivaregisterkind WHERE idivaregisterkindunified = @idivaregisterkind)
--										, (SELECT idivaregisterkind FROM ivaregisterkind WHERE codeivaregisterkind = @codeivaregisterkind))
		--se uno non usa i codici di consolidamento, allora deve prendere quello con pari codice
		-- se uno usa i codici, deve prendere TUTTI quelli aventi pari codice  (attualmente ne prende uno solo)
		insert into #ivaregisterkind (idivaregisterkind, flagactivity, registerclass,description)
			select idivaregisterkind, flagactivity, registerclass,description from ivaregisterkind
					where idivaregisterkindunified=@idivaregisterkind OR 
							(idivaregisterkindunified is null and codeivaregisterkind = @codeivaregisterkind)
	End
	ELSE
	BEGIN
		insert into #ivaregisterkind (idivaregisterkind, flagactivity, registerclass,description)
			select idivaregisterkind, flagactivity, registerclass,description from ivaregisterkind
					where idivaregisterkind=@idivaregisterkind 
	END
	
	IF @startmonth IS NULL OR @startmonth < 1
	BEGIN
		SET @startmonth = 1
	END
	IF @startmonth > 12
	BEGIN
		SET @startmonth = 12
	END
	IF @stopmonth IS NULL OR @stopmonth < 1
	BEGIN
		SET @stopmonth = 1
	END
	IF @stopmonth > 12
	BEGIN
		SET @stopmonth = 12
	END

CREATE TABLE #invoice
(
	idinvkind int,		
	yinv int,
	ninv int,
	idivaregisterkind int,	
	registerclass char(1), --tipo registro A/V
	kind char(1), --tipo fattura A/V
	flagdeferred char(1),
	ivagross decimal(19,2),
	ivaabatable decimal(19,2),
	ivaunabatable decimal(19,2),
	taxabletotal decimal(19,2),
	idivakind int		
)
	
	-- Tabella di output dove confluiscono tutte le fatture e note di credito partecipanti alla liquidazione
	CREATE TABLE #invoicedet
	(
		idinvkind int,
		yinv int,
		ninv int,
		rownum int,
		adate datetime,
		registerclass char(1), --tipo registro A/V
		kind char(1), --tipo fattura A/V
		flagmixed char(1),
		flagdeferred char(1),
		flagvariation char(1),
		taxabletotal decimal(19,2),
		ivagross decimal(19,2),
		ivaunabatable decimal(19,2), --unabatable corrente, applicare segno
		ivaabatable decimal(19,2),   -- calcolato qui
		idivaregisterkind int, 
		idivakind int,
		flagintracom char(1)		
	)
	-- il segno è da cambiare se flagdeferred oppure se kind<>registerclass
	-- inoltre per le fatture non intracom con la doppia presenza A/V è da cancellare la riga in vendita
	

	--1)  Fatture registrate nel corso dell'anno e nel periodo di riferimento
	INSERT INTO #invoicedet
	(
		idinvkind, yinv, ninv, rownum, flagdeferred, flagmixed,
		registerclass,kind,flagvariation,
		taxabletotal,ivagross,	ivaunabatable,
		idivakind,idivaregisterkind, flagintracom,adate
	)
	(SELECT
		I.idinvkind,I.yinv,I.ninv, IDET.rownum, I.flagdeferred,
		CASE
			WHEN IRK.flagactivity = 3  THEN 'S'
			ELSE 'N'
		END,
		IRK.registerclass,		--tipo registro (A/V)
		CASE WHEN (IK.flag & 1)=0 THEN 'A'
		     ELSE 'V'
		END, 		--tipo fattura (A/V)
		CASE
			WHEN (IK.flag & 4) = 0 THEN 'N'
			ELSE 'S'
		END, 	
		ROUND(IDET.taxable * IDET.npackage * 
		 CONVERT(decimal(19,6),I.exchangerate) *
		  (1 - CONVERT(decimal(19,6),ISNULL(IDET.discount, 0.0))),2
		 ), 
		ISNULL(IDET.tax,0), 
		ISNULL(IDET.unabatable,0)  , --cambiare segno				
		IDET.idivakind,IRK.idivaregisterkind,
		I.flagintracom,I.adate
	FROM invoice I
	join invoicedetail IDET
		ON IDET.idinvkind=I.idinvkind
		AND IDET.yinv=I.yinv
		AND IDET.ninv=I.ninv
	JOIN invoicekind IK
		ON I.idinvkind = IK.idinvkind
	JOIN ivaregister IR
		ON IR.idinvkind = I.idinvkind
		AND IR.yinv = I.yinv
		AND IR.ninv = I.ninv
	JOIN #ivaregisterkind IRK
		ON IRK.idivaregisterkind = IR.idivaregisterkind
	WHERE 	
		YEAR(I.adate) = @year 
		AND MONTH(I.adate) BETWEEN @startmonth AND @stopmonth		
	)
	-- chiamiamo 'T' le fatture differite, a prescindere da quando vengono pagate
	UPDATE #invoicedet set flagdeferred='T' where flagdeferred='S'
	
