INSERT INTO #assetload
(
	aliquota,
	idassetloadkind,
	yassetload,
	nassetload,
	idmot,
	idinventoryagency,
	inventoryagency,
	idinventorykind,
	inventorykind,
	idreg,
	doc,
	docdate,
	description,
	annotation,
	enactment,
