if object_id('[esporta_cespiti_accessori_non_ammortizzati_ente]') is not null
	drop PROCEDURE [esporta_cespiti_accessori_non_ammortizzati_ente]
go



CREATE                     PROCEDURE [esporta_cespiti_accessori_non_ammortizzati_ente]
@year			int,
@idinventoryagency	int,
@idinventoryamortization int,
@idinv			int,
@flagcategory		char(1)
AS BEGIN
-------------------------------------------------------------------------------------
-------------- Elenco cespiti e accessori non ammortizzati nell'anno ----------------
-------------------------------------------------------------------------------------
	declare @firstlevelidinv int
	select @firstlevelidinv = idparent
		from inventorytreelink
		where idchild = @idinv
		and nlevel = 1
	DECLARE @firstday datetime
	SET @firstday = CONVERT(datetime, '01/01/' + CONVERT(char(4),@year), 105)
	
	DECLARE @amortizationkind  varchar(50)
	SELECT @amortizationkind = description 
		FROM inventoryamortization
		WHERE idinventoryamortization = @idinventoryamortization
   	SELECT
		@amortizationkind			as 'Tipo rivalutazione',
		CASE 
			WHEN cespite_o_accessorio.idpiece = 1 THEN     'Cespite' 
			WHEN cespite_o_accessorio.idpiece > 1 THEN     'Accessorio'
		END					as 'Tipo Carico',
		inventoryagency.codeinventoryagency	as 'Cod. Ente Inventario',
		inventoryagency.description  		as 'Ente Inventario', 
		inventory.description      		as 'Inventario',  
		inventorykind.description  		as 'Tipo Inventario',
		cespite.ninventory			as 'Numero inventario Cespite',
		carico.description   			as 'Descrizione',
		CASE 
			WHEN cespite_o_accessorio.idpiece = 1 THEN     NULL
			WHEN cespite_o_accessorio.idpiece > 1 THEN     caricocespite.description
		END					as 'Descrizione Cespite Associato',
		categoriainventariale.codeinv		as 'Categoria Inventariale'
	FROM asset as cespite_o_accessorio 
	JOIN assetacquire as carico
		ON carico.nassetacquire = cespite_o_accessorio.nassetacquire
	JOIN asset as cespite
		ON cespite.idasset = cespite_o_accessorio.idasset
	JOIN assetacquire as caricocespite
		ON caricocespite.nassetacquire = cespite.nassetacquire
	JOIN inventory
		ON carico.idinventory = inventory.idinventory
	JOIN inventoryagency
		ON inventory.idinventoryagency = inventoryagency.idinventoryagency
	JOIN inventorykind
		ON inventory.idinventorykind = inventorykind.idinventorykind   
	join inventorytreelink as linkcategoria
		on linkcategoria.idchild = carico.idinv and linkcategoria.nlevel = 1
	join inventorytree as categoriainventariale
		on categoriainventariale.idinv = linkcategoria.idparent
	WHERE   cespite.idpiece = 1 
		-- in carico
		AND (carico.idassetload is not null or carico.flag & 3 = 0) 
		AND inventory.idinventoryagency = isnull(@idinventoryagency, inventory.idinventoryagency)
		AND NOT EXISTS (SELECT  *
				FROM    assetamortization
				JOIN 	inventoryamortization
					ON assetamortization.idinventoryamortization = inventoryamortization.idinventoryamortization
				WHERE 	assetamortization.idasset = cespite_o_accessorio.idasset AND 
				   	assetamortization.idpiece = cespite_o_accessorio.idpiece AND
					assetamortization.idinventoryamortization = isnull(@idinventoryamortization, assetamortization.idinventoryamortization) AND
					YEAR(assetamortization.adate) = @year AND
		 			assetamortization.adate >= @firstday
				)
		AND (@idinv is null
			or categoriainventariale.idinv = @firstlevelidinv and @flagcategory = 'S'
	        	OR carico.idinv = @idinv AND @flagcategory = 'N' )
	ORDER BY carico.nassetacquire
END



GO

print '[esporta_cespiti_accessori_non_ammortizzati_ente] OK'

GO
if object_id('[rpt_buono_scarico]') is not null
	drop PROCEDURE [rpt_buono_scarico]
go
--setuser 'amm'
--exec rpt_buono_scarico 2009, 'I', 1, 1, 3000, {d '2010-01-31'},'N'
CREATE  PROCEDURE [rpt_buono_scarico]
(
	@ayear int,
	@printkind char(1),
	@idassetunloadkind int,
	@startassetunload int,
	@stopassetunload int,
	@printdate datetime,
	@official char(1)		
)
AS BEGIN
DECLARE @cod_univ char(1)
-- Università degli Studi di Bari
IF EXISTS(SELECT * FROM [license] WHERE ISNULL(p_iva,'P') = '01086760723')
BEGIN
	SET @cod_univ = 'B'
END
IF EXISTS(SELECT * FROM [license] WHERE ISNULL(p_iva,'P') = '80008870752')
BEGIN
	SET @cod_univ = 'L'
END
IF @cod_univ IS NULL 
	SET @cod_univ = 'G'
DECLARE @flagdiscount float  
IF (SELECT  TOP 1 (inventorykind.flag & 1)
	FROM inventorykind 
	JOIN inventory 
		ON inventory.idinventorykind= inventorykind.idinventorykind
	JOIN assetacquire 
		ON assetacquire.idinventory=inventory.idinventory
	JOIN assetunloadkind 
		ON assetunloadkind.idinventory=inventory.idinventory
	WHERE idassetunloadkind=@idassetunloadkind
	)<> 0
BEGIN
	SET @flagdiscount = 1 
END
ELSE 
BEGIN
	SET @flagdiscount = 0
END
	
IF (@ayear<2005) SET @flagdiscount = 1 
-- Contiene i numeri di Buoni di Scarico da stampare
CREATE TABLE #printing (num int)
IF @printkind = 'A' 
	INSERT INTO #printing (num) 
	SELECT nassetunload from  assetunload  where (yassetunload=@ayear) and (printdate IS NULL)
	
IF @printkind <> 'A'
	INSERT INTO #printing (num) 
	SELECT nassetunload from  assetunload where (yassetunload=@ayear) and (nassetunload BETWEEN @startassetunload AND @stopassetunload)
-----------------------------------------------------------------------------------------------
-- Valore degli accessori CARICATI collegati ai cespiti principali attualmente in scarico ----- 
-- Si considerano quelli inseriti in buoni di carico ------------------------------------------
-----------------------------------------------------------------------------------------------
--
--select 'pieceunloaded_load',* from #pieceunloaded_load
--------------------------------------------------------------------------------------
--Rivalutazioni / Svalutazioni dei cespiti e degli accessori attualmente in scarico --
--------------------------------------------------------------------------------------
CREATE TABLE #amortization
(
	idasset int,
	idpiece	int,
	amount decimal(19,2)
)
INSERT INTO #amortization
(
	idasset,
	idpiece,
	amount
)
SELECT
	asset.idasset,
	asset.idpiece,
	convert(decimal(19,2),SUM(ROUND(ISNULL(assetamortization.assetvalue,0) * ISNULL(assetamortization.amortizationquota,0),2)))
FROM assetamortization
JOIN asset
	ON asset.idasset = assetamortization.idasset
	AND asset.idpiece = assetamortization.idpiece
JOIN inventoryamortization
	ON inventoryamortization.idinventoryamortization = assetamortization.idinventoryamortization
JOIN assetunload
	ON asset.idassetunload = assetunload.idassetunload
WHERE 	( 
		  (ISNULL(assetamortization.amortizationquota,0) > 0 AND assetamortization.idassetload IS NOT NULL) 
		  OR
		  (ISNULL(assetamortization.amortizationquota,0) < 0 AND assetamortization.idassetunload IS NOT NULL) 
		  OR
		 (assetamortization.flag & 1 = 0)
	    )
	AND (inventoryamortization.flag & 2 <> 0)
	AND assetunload.idassetunloadkind = @idassetunloadkind
	AND assetunload.yassetunload = @ayear
	AND assetunload.nassetunload IN (SELECT num from #printing)
GROUP BY asset.idasset,asset.idpiece

CREATE TABLE #reduction
(
	idasset int,
	amount decimal(23,6)
)
INSERT INTO #reduction
(
	idasset,
	amount
)
SELECT
	AMAIN.idasset,
	-AC.start
from assetacquire B
JOIN assetview A
	on B.nassetacquire = A.nassetacquire
join assetview_current AC 
	on A.idasset=AC.idasset and A.idpiece=AC.idpiece	
JOIN asset AMAIN
	ON AMAIN.idasset = A.idasset
	AND AMAIN.idpiece = 1
JOIN assetunload 
	ON AMAIN.idassetunload = assetunload.idassetunload
WHERE 	
	A.idpiece >1
	and   A.idassetunload IS NOT NULL
	and  ((B.flag & 1 <> 1) AND (B.flag & 2 <> 0))
	AND assetunload.idassetunloadkind = @idassetunloadkind
	AND assetunload.yassetunload = @ayear
	AND assetunload.nassetunload IN (SELECT num from #printing)
--select 'amortization',* from #amortization
	
--------------------------------------------------------------------------------------
--------------------------------Scarichi cespiti principali---------------------------
--------------------------------------------------------------------------------------	
CREATE TABLE #asset_unload
(
	idassetunloadkind int,
	yassetunload int,
	nassetunload int,
	idmot int,
	idinventoryagency int,
	codeinventoryagency varchar(20),
	idinventorykind int,
	doc varchar(35),
	docdate datetime,
	description varchar(150),
	enactment varchar(150),
	enactmentdate datetime,
	adate datetime,
	printdate datetime,
	operationorder int,	
	kind varchar(50),
	idinventory int,
	idasset int,
	idpiece int,
	ninventory int,
	idinv int,
	assetdescription varchar(210),
	unitvalue decimal(23,2),
	nassetacquire int
)
INSERT INTO #asset_unload
(
	idassetunloadkind,
	yassetunload,
	nassetunload,
	idmot,
	idinventoryagency,
	codeinventoryagency,
	idinventorykind,
	doc,
	docdate,
	description,
	enactment,
	enactmentdate,
	adate,
	printdate,
	operationorder,
	kind,
	idinventory,
	idasset,
	idpiece,	
	ninventory,
	idinv,
	assetdescription,
	unitvalue ,
	nassetacquire
)
SELECT 
	assetunload.idassetunloadkind,
	assetunload.yassetunload,
	assetunload.nassetunload,
	assetunload.idmot,
	inventory.idinventoryagency,
	inventoryagency.codeinventoryagency,
	inventory.idinventorykind,
	assetunload.doc,
	assetunload.docdate,
	assetunload.description,
	assetunload.enactment,
	assetunload.enactmentdate,
	assetunload.adate,
	assetunload.printdate,
	1,
	'Scarico bene',
	assetacquire.idinventory, 
	asset.idasset,
	asset.idpiece,
	asset.ninventory,
	assetacquire.idinv,
	assetacquire.description,
	AC.start,	
	asset.nassetacquire
FROM assetunload
JOIN asset
	ON assetunload.idassetunload = asset.idassetunload
join assetview_current AC 
	on asset.idasset=AC.idasset and asset.idpiece=AC.idpiece		
JOIN assetacquire
	ON asset.nassetacquire = assetacquire.nassetacquire
LEFT OUTER JOIN assetload
	ON assetload.idassetload = assetacquire.idassetload
JOIN inventory
	ON assetacquire.idinventory = inventory.idinventory	
JOIN inventoryagency
	ON inventory.idinventoryagency = inventoryagency.idinventoryagency	
WHERE asset.idpiece=1
	and assetunload.idassetunloadkind = @idassetunloadkind
	AND assetunload.yassetunload = @ayear
	AND assetunload.nassetunload IN (SELECT num from #printing)
--select * from #asset_unload
--------------------------------------------------------------------------------------
--------------------------------Scarichi accessori -----------------------------------
--------------------------------------------------------------------------------------	
INSERT INTO #asset_unload
(
	idassetunloadkind,
	yassetunload,
	nassetunload,
	idmot,
	idinventoryagency,
	codeinventoryagency,
	idinventorykind,
	doc,
	docdate,
	description,
	enactment,
	enactmentdate,
	adate,
	printdate,
	operationorder,
	kind,
	idinventory,
	idasset,
	idpiece,
	ninventory,
	idinv,
	assetdescription,
	unitvalue 
)
SELECT
	assetunload.idassetunloadkind,
	assetunload.yassetunload,
	assetunload.nassetunload,
	assetunload.idmot,
	inventory.idinventoryagency,
	inventoryagency.codeinventoryagency,
	inventory.idinventorykind,
	assetunload.doc,
	assetunload.docdate,
	assetunload.description,
	assetunload.enactment,
	assetunload.enactmentdate,
	assetunload.adate,
	assetunload.printdate,
	2,
	'Scarico accessorio',
	assetacquire.idinventory, 
	asset.idasset,
	asset.idpiece,
	assetmain.ninventory,
	assetacquire.idinv,
	assetacquire.description,
	AC.start	
FROM assetacquire
JOIN asset
	ON asset.nassetacquire = assetacquire.nassetacquire
join assetview_current AC 
	on asset.idasset=AC.idasset and asset.idpiece=AC.idpiece		
JOIN asset as assetmain
	ON asset.idasset=assetmain.idasset
JOIN assetunload
	ON assetunload.idassetunload = asset.idassetunload
JOIN inventory
	ON inventory.idinventory = assetacquire.idinventory
JOIN inventoryagency
	ON inventory.idinventoryagency = inventoryagency.idinventoryagency	
WHERE asset.idpiece>1
	and assetunload.idassetunloadkind = @idassetunloadkind
	AND assetunload.yassetunload = @ayear
	AND assetunload.nassetunload IN (SELECT num from #printing)
	AND assetmain.idpiece=1
--------------------------------------------------------------------------------------
--------------------------------Scarichi ammortamenti---------------------------------
--------------------------------------------------------------------------------------
	
INSERT INTO #asset_unload
(
	idassetunloadkind,
	yassetunload,
	nassetunload,
	idmot,
	idinventoryagency,
	codeinventoryagency,
	idinventorykind,
	doc,
	docdate,
	description,
	enactment,
	enactmentdate,
	adate,
	printdate,
	operationorder,
	kind,
	idinventory,
	idasset,
	idpiece,	
	ninventory,
	idinv,
	assetdescription,
	unitvalue ,
	nassetacquire
)
SELECT 
	assetunload.idassetunloadkind,
	assetunload.yassetunload,
	assetunload.nassetunload,
	assetunload.idmot,
	inventory.idinventoryagency,
	inventoryagency.codeinventoryagency,
	inventory.idinventorykind,
	assetunload.doc,
	assetunload.docdate,
	assetunload.description,
	assetunload.enactment,
	assetunload.enactmentdate,
	assetunload.adate,
	assetunload.printdate,
	3,
	'Ammortamento cespite',
	assetacquire.idinventory, 
	asset.idasset,
	asset.idpiece,
	asset.ninventory,
	assetacquire.idinv,
	inventoryamortization.description + ' n. '+ convert(varchar(4),namortization) + char(13) + assetamortization.description,
	ROUND(ISNULL(assetamortization.assetvalue,0) * ISNULL(assetamortization.amortizationquota,0),2),
	assetamortization.namortization
FROM assetunload
JOIN assetamortization
	ON assetunload.idassetunload = assetamortization.idassetunload
JOIN inventoryamortization
	ON inventoryamortization.idinventoryamortization = assetamortization.idinventoryamortization
JOIN asset 
	ON asset.idasset = assetamortization.idasset
	AND asset.idpiece = assetamortization.idpiece
JOIN assetacquire
	ON asset.nassetacquire = assetacquire.nassetacquire
JOIN inventory
	ON assetacquire.idinventory = inventory.idinventory	
JOIN inventoryagency
	ON inventory.idinventoryagency = inventoryagency.idinventoryagency	
WHERE 	asset.idpiece = 1 
	AND assetunload.idassetunloadkind = @idassetunloadkind
	AND assetunload.yassetunload = @ayear
	AND assetunload.nassetunload IN (SELECT num from #printing)

INSERT INTO #asset_unload
(
	idassetunloadkind,
	yassetunload,
	nassetunload,
	idmot,
	idinventoryagency,
	codeinventoryagency,
	idinventorykind,
	doc,
	docdate,
	description,
	enactment,
	enactmentdate,
	adate,
	printdate,
	operationorder,
	kind,
	idinventory,
	idasset,
	idpiece,	
	ninventory,
	idinv,
	assetdescription,
	unitvalue ,
	nassetacquire
)
SELECT 
	assetunload.idassetunloadkind,
	assetunload.yassetunload,
	assetunload.nassetunload,
	assetunload.idmot,
	inventory.idinventoryagency,
	inventoryagency.codeinventoryagency,
	inventory.idinventorykind,
	assetunload.doc,
	assetunload.docdate,
	assetunload.description,
	assetunload.enactment,
	assetunload.enactmentdate,
	assetunload.adate,
	assetunload.printdate,
	4,
	'Ammortamento accessorio',
	assetacquire.idinventory, 
	asset.idasset,
	asset.idpiece,
	assetcespite.ninventory,
	assetacquire.idinv,
	inventoryamortization.description + ' n. '+ convert(varchar(4),namortization) + char(13) + assetamortization.description,
	ROUND(ISNULL(assetamortization.assetvalue,0) * ISNULL(assetamortization.amortizationquota,0),2),
	assetamortization.namortization
FROM assetunload
JOIN assetamortization
	ON  assetunload.idassetunload = assetamortization.idassetunload
JOIN inventoryamortization
	ON inventoryamortization.idinventoryamortization = assetamortization.idinventoryamortization
JOIN asset 
	ON asset.idasset = assetamortization.idasset
	AND asset.idpiece = assetamortization.idpiece
JOIN asset AS assetcespite 
	ON asset.idasset = assetcespite.idasset
JOIN assetacquire
	ON asset.nassetacquire = assetacquire.nassetacquire
JOIN inventory
	ON assetacquire.idinventory = inventory.idinventory	
JOIN inventoryagency
	ON inventory.idinventoryagency = inventoryagency.idinventoryagency	
WHERE 	asset.idpiece >1 AND assetcespite.idpiece = 1 
	AND assetunload.idassetunloadkind = @idassetunloadkind
	AND assetunload.yassetunload = @ayear
	AND assetunload.nassetunload IN (SELECT num from #printing)
IF @official = 'S'
BEGIN
	UPDATE #asset_unload
	SET printdate = @printdate
	WHERE yassetunload = @ayear 
	AND nassetunload IN (SELECT num from #printing)
	AND printdate IS NULL
END
--select * from #asset_unload
-------------------------------------------------------------------------------------------------
--1. Variazioni del cespite scaricato
--   + Valore accessori CARICATI legati al cespite  
--   + Rivalutazioni positive e negative del cespite
--   + Rivalutazioni positive e negative di tutti gli accessori CARICATI collegati
--   - Valore accessori SCARICATI legati al cespite, presenti in questo o altri buoni di scarico
--   - Rivalutazioni positive e negative di accessori SCARICATI legati al cespite, 
--     presenti in questo o in altri buoni di scarico
--------------------------------------------------------------------------------------------------
--2. Variazioni dell' accessorio scaricato
--   + Rivalutazioni positive e negative dell'accessorio
--------------------------------------------------------------------------------------------------
SELECT  
	idassetunloadkind ,
	yassetunload ,
	nassetunload ,
	#asset_unload.idmot ,
	MOTIVE.description as assetunloadmotive ,
	#asset_unload.idinventoryagency ,
	AGENCY.description as inventoryagency,
	#asset_unload.idinventorykind ,
	INVKIND.description as inventorykind,
	doc ,
	docdate ,
	#asset_unload.description ,
	enactment ,
	enactmentdate ,
	adate ,
	printdate ,
	operationorder ,
	kind ,
	#asset_unload.idinventory ,
	idasset ,
	idpiece ,
	ninventory ,
	#asset_unload.idinv ,
	inventory.codeinventory,
	inventorytree.codeinv, 
	assetdescription ,
	unitvalue ,
	nassetacquire,
	CASE #asset_unload.kind 
		WHEN  'Scarico bene' THEN
			ISNULL((SELECT SUM(amount)
				FROM  #reduction
				WHERE #reduction.idasset = #asset_unload.idasset),0) 
			+
			ISNULL((SELECT SUM(amount)
				FROM   #amortization
				WHERE  #amortization.idasset = #asset_unload.idasset
				AND    #amortization.idpiece   = #asset_unload.idpiece),0) 			
		WHEN  'Scarico accessorio' THEN
			ISNULL((SELECT SUM(amount) FROM #amortization
				WHERE  #amortization.idasset = #asset_unload.idasset
				AND    #amortization.idpiece = #asset_unload.idpiece),0) 
		ELSE 0
	END as amortization ,
	@cod_univ as cod_univ,
	#asset_unload.codeinventoryagency
FROM #asset_unload
JOIN inventorytree
	ON inventorytree.idinv = #asset_unload.idinv
JOIN inventory
	on #asset_unload.idinventory = inventory.idinventory
LEFT OUTER JOIN assetunloadmotive MOTIVE
	ON #asset_unload.idmot = MOTIVE.idmot
LEFT OUTER JOIN inventoryagency AGENCY
	ON #asset_unload.idinventoryagency = AGENCY.idinventoryagency
LEFT OUTER JOIN inventorykind INVKIND
	ON #asset_unload.idinventorykind = INVKIND.idinventorykind  
ORDER BY nassetunload,ninventory,operationorder
END


