if object_id('[check_csa_individuazione]') is not null
	drop PROCEDURE [check_csa_individuazione]
go

CREATE    PROCEDURE [check_csa_individuazione]
(
	@idcsa_import int,
	@ayear		  int,
	@res          int out
)
AS BEGIN
SET      @res = 0	
--1) Esercizio non valorizzato
 if exists (
  SELECT * FROM csa_importriep WHERE idcsa_import = @idcsa_import 
  AND ayear  is null
) set @res = 1
--2) Esercizio non valorizzato
 if exists (
  SELECT * FROM csa_importver WHERE idcsa_import = @idcsa_import 
  AND ayear is null
) set @res = 1
--3) Contratto/tipo contratto non determinato
 if exists (
  SELECT * FROM csa_importriep WHERE idcsa_import = @idcsa_import 
  AND idcsa_contract is null AND idcsa_contractkind is null
) set @res = 1
 if exists (
  SELECT * FROM csa_importver WHERE idcsa_import = @idcsa_import 
  AND idcsa_contract is null AND idcsa_contractkind is null
) set @res = 1

--4) Ritenuta o Contributo senza imputazione
 if exists (
  SELECT * FROM csa_importver WHERE idcsa_import = @idcsa_import 
  AND idcsa_contracttax is null AND idcsa_incomesetup is null 
  and idcsa_contractkinddata is null and idfin_cost is null and idexp_cost is null
) set @res = 1

--5) Versamenti con Ente o Anagrafica Ente non valorizzati
 if exists (  SELECT * FROM csa_importver WHERE idcsa_import = @idcsa_import 
  AND (idcsa_agency is null OR idreg_agency is null)
) set @res = 1
DECLARE @flagdirectcsaclawback CHAR(1)
SELECT 
	@flagdirectcsaclawback = flagdirectcsaclawback
FROM config
WHERE ayear = @ayear

--6) Recupero Senza Capitolo di Entrata Lordi idfin_income o idfin_incomeclawback a seconda dei casi
 if exists (SELECT * FROM csa_importver WHERE idcsa_import = @idcsa_import 
 AND ISNULL(flagclawback,'N') = 'S' 
AND (
	(ISNULL(@flagdirectcsaclawback,'N')= 'N' AND idfin_income IS NULL) OR  --partita di giro
	(ISNULL(@flagdirectcsaclawback,'N')= 'S' AND idfin_incomeclawback IS NULL)  --recupero diretto
	)
) set @res = 1
--7) Recupero: idfin_expense --> idfin_income e viceversa
 if exists (SELECT * FROM csa_importver WHERE idcsa_import = @idcsa_import 
 AND ISNULL(flagclawback,'N') = 'S' and 
  ((idfin_expense IS NULL AND idfin_income IS NOT NULL) OR 
   (idfin_expense IS NOT NULL AND idfin_income IS NULL))
) set @res = 1
----8) Ritenuta o Contributo senza voce di bilancio di spesa valorizzata (idfin_cost o idfin_expense)
--  lo commentiamo per introdurre la gestione dei contributi figurativi che non devono generare 
--  movimenti finanziari
--  if exists (SELECT * FROM csa_importver WHERE idcsa_import = @idcsa_import  
--  AND ISNULL(flagclawback,'N') = 'N' and idfin_cost IS NULL and idfin_expense IS NULL
--) set @res = 1
--9) Ritenuta o Contributo: idfin_income -> idfin_expense
 if exists (SELECT * FROM csa_importver WHERE idcsa_import = @idcsa_import  
 AND ISNULL(flagclawback,'N') = 'N' and idfin_income IS NOt NULL and idfin_expense IS NULL
) set @res = 1
--10)  Ritenuta o Contributo: idfin_expense --> idfin_income
 if exists (SELECT * FROM csa_importver WHERE idcsa_import = @idcsa_import  
  AND ISNULL(flagclawback,'N') = 'N' and idfin_income is  null 
  and idfin_expense is NOT null
) set @res = 1
END

GO

print '[check_csa_individuazione] OK'

