CREATE TABLE #asset_unload
(
	idassetunloadkind int,
	yassetunload int,
	nassetunload int,
	idmot int,
	idinventoryagency int,
	codeinventoryagency varchar(20),
	idinventorykind int,
	doc varchar(35),
	docdate datetime,
	description varchar(150),
	enactment varchar(150),
	enactmentdate datetime,
	adate datetime,
	printdate datetime,
	operationorder int,	
	kind varchar(50),
	idinventory int,
	idasset int,
	idpiece int,
	ninventory int,
	idinv int,
	assetdescription varchar(210),
	unitvalue decimal(23,2),
	nassetacquire int,
	typeoperation varchar(2)
)
INSERT INTO #asset_unload
(
	idassetunloadkind,
	yassetunload,
	nassetunload,
	idmot,
	idinventoryagency,
	codeinventoryagency,
	idinventorykind,
	doc,
	docdate,
	description,
	enactment,
	enactmentdate,
	adate,
	printdate,
	operationorder,
	kind,
	idinventory,
	idasset,
	idpiece,	
	ninventory,
	idinv,
	assetdescription,
	unitvalue ,
	nassetacquire,
	typeoperation
)
SELECT DISTINCT
	assetunload.idassetunloadkind,
	assetunload.yassetunload,
	assetunload.nassetunload,
	assetunload.idmot,
	inventory.idinventoryagency,
	inventoryagency.codeinventoryagency,
	inventory.idinventorykind,
	assetunload.doc,
	assetunload.docdate,
	assetunload.description,
	assetunload.enactment,
	assetunload.enactmentdate,
	assetunload.adate,
	assetunload.printdate,
	1,
	'Scarico bene',
	assetacquire.idinventory, 
	asset.idasset,
	asset.idpiece,
	asset.ninventory,
	assetacquire.idinv,
	assetacquire.description,
	CASE 
		WHEN @flagdiscount = 1
		THEN
			ROUND(ISNULL(assetacquire.taxable, 0)
			* (1 - CONVERT(decimal(19,6),ISNULL(assetacquire.discount, 0))),2)
			+ ROUND(ISNULL(assetacquire.tax,0) / assetacquire.number,2)
			- ROUND(ISNULL(assetacquire.abatable,0) / assetacquire.number,2)
		WHEN   @flagdiscount = 0
		THEN
			ISNULL(assetacquire.taxable, 0)
			+ ROUND(ISNULL(assetacquire.tax,0) / assetacquire.number,2)
			- ROUND(ISNULL(assetacquire.abatable,0) / assetacquire.number,2)
	END,
	asset.nassetacquire,
	'CP'
FROM assetunload
JOIN asset
	ON assetunload.idassetunload = asset.idassetunload
JOIN assetacquire
	ON asset.nassetacquire = assetacquire.nassetacquire
LEFT OUTER JOIN assetload
	ON assetload.idassetload = assetacquire.idassetload
JOIN inventory
	ON assetacquire.idinventory = inventory.idinventory	
JOIN inventoryagency
	ON inventory.idinventoryagency = inventoryagency.idinventoryagency	
WHERE asset.idpiece=1
	and assetunload.idassetunloadkind = @idassetunloadkind
	AND assetunload.yassetunload = @ayear
	AND assetunload.nassetunload IN (SELECT num from #printing)
