		ON IY.idinc = I.idinc
	JOIN finsorting FS
		ON FS.idfin = IY.idfin
	JOIN sorting S
		ON FS.idsor = S.idsor
	JOIN upb U
		ON IY.idupb = U.idupb
	JOIN incometotal IT
