	INSERT INTO #data(
		idsor,
		idupb,
		S_var_maxphase_C
	)
	SELECT
		FS.idsor,
		isnull(@fixedidupb,EY.idupb),
		SUM(EV.amount)
	FROM expensevar EV
	JOIN expense E
		ON EV.idexp = E.idexp
	JOIN expenseyear EY
		ON EY.idexp = EV.idexp
	JOIN finsorting FS
		ON FS.idfin = EY.idfin
	JOIN sorting S
