	FROM historypaymentview HPV
	JOIN expenseyear EY
		ON EY.idexp = HPV.idexp
	JOIN finsorting FS
		ON FS.idfin = HPV.idfin
	JOIN sorting S
		ON S.idsor = FS.idsor
	JOIN upb U
