if object_id('[trigger_u_epexpsorting]') is not null
	drop TRIGGER [trigger_u_epexpsorting]
go


CREATE       TRIGGER [trigger_u_epexpsorting] ON epexpsorting FOR UPDATE
AS BEGIN
IF UPDATE(amount)
BEGIN
	DECLARE @idsor int
	DECLARE @oldidacc varchar(38)
	DECLARE @newidacc varchar(38)
	DECLARE @newamount decimal(19,2)
	DECLARE @oldamount decimal(19,2)
	DECLARE @amount decimal(19,2)
	SELECT 
		@newidacc = idacc, 
		@idsor = idsor, 
		@newamount = amount
	FROM inserted
	
	SELECT   @oldidacc = idacc,
		 @oldamount = -amount
	FROM deleted
	
	EXEC trg_upd_sortingmovtotal 'E',  @idsor, @oldamount, @amount	
	EXEC trg_upd_sortingmovtotal 'E',  @idsor, @newidacc, @amount	
	
END
END

