if object_id('[rpt_sitbilancio_residui]') is not null
	drop PROCEDURE [rpt_sitbilancio_residui]
go

CREATE    PROCEDURE [rpt_sitbilancio_residui]
	@ayear			int,
	@date			datetime,
	@nlevel			tinyint,
	@hierarchy		char(1),
	@idupb			varchar(36),
	@showupb 		char(1),
	@showchildupb 		char(1),
	@suppressifblank 	char(1),
	@idfin			int
AS
BEGIN
/* Versione 1.0.4 del 15/11/2007 ultima modifica: Pino */
	CREATE TABLE #fin_residual
	(
		idupb 			varchar(36),
		codeupb			varchar(50),
		upb   			varchar(150),
		upbprintingorder	varchar(50),
		idfin			int,
		nlevel			tinyint,
		codefin			varchar(50),
		title			varchar(150),
		finprintingorder	varchar(50),
		assessments		decimal(19,2),
		var_assessments		decimal(19,2),
		proceeds         	decimal(19,2),
		var_proceeds       	decimal(19,2),
		flagconsider 		char(1) 			
	)
	IF (@ayear IS NULL) 
	BEGIN
		SELECT * FROM  #fin_residual 
		RETURN
	END
	DECLARE @level_input tinyint
	SELECT @level_input = ISNULL(nlevel ,@nlevel) from fin where idfin = @idfin
	-- ho scelto come livello 2 e poi ho specificato il capitolo, lui corregge @nlevel dandogli 3
	IF (@nlevel < @level_input ) AND (@idfin is not null)
	BEGIN
		SET  @nlevel = @level_input
	END
	DECLARE @levelusable 		tinyint
	SELECT  @levelusable = MIN(nlevel) FROM finlevel where flag&2 <> 0
	DECLARE @idupboriginal 		varchar(36)
	SET 	@idupboriginal= @idupb
	IF (@showchildupb = 'S') set @idupb=@idupb+'%' 
	DECLARE @assessmentphase     	tinyint
	DECLARE @phasemax          	tinyint
	
	SELECT 	@assessmentphase =  assessmentphasecode
	FROM 	config
	WHERE 	ayear = @ayear
	IF @assessmentphase IS NULL
	BEGIN
		SELECT 	@assessmentphase = incomefinphase
		FROM 	uniconfig
	END
	SELECT 	@phasemax = MAX(nphase)
	FROM 	incomephase
	
	DECLARE @cashvaliditykind int
	SELECT	@cashvaliditykind = cashvaliditykind
	FROM 	config
	WHERE 	ayear = @ayear
	INSERT INTO #fin_residual
		(
		idfin			, 
		codefin			,
		title			,
		finprintingorder	,
		nlevel			,
		codeupb			,
		idupb 			,
		upb   			,
		upbprintingorder	,
		flagconsider	
		)
	SELECT DISTINCT
		F.idfin			,
		F.codefin		,
		F.title			, 
		F.printingorder		,
		F.nlevel		,
		U.codeupb		,
		U.idupb 		,
		U.title  		,
		U.printingorder	,
		CASE	WHEN (@hierarchy ='N') THEN 'S' 
			WHEN (@hierarchy ='S') AND (F.nlevel >= @levelusable) 
				AND 	(finlast.idfin is not null)
				THEN 'S'	
			ELSE 'N'						
		END		
	FROM incomeyear
	JOIN upb U
		on  incomeyear.idupb = U.idupb 
	JOIN fin F
		on  incomeyear.idfin = F.idfin 
	JOIN finlink
		ON  finlink.idchild = F.idfin and finlink.nlevel = @nlevel
	JOIN incometotal
		ON  incomeyear.idinc = incometotal.idinc
		AND incomeyear.ayear = incometotal.ayear
	LEFT OUTER JOIN finlast 
		ON F.idfin = finlast.idfin
	WHERE F.ayear =@ayear AND ((F.flag&1)=0) --  Entrata
		AND (@idfin IS NULL  OR finlink.idparent = @idfin )
	    	AND (U.idupb like @idupb and U.active='S')
		AND ((@hierarchy ='N' AND F.nlevel = @nlevel) OR (@hierarchy ='S' and F.nlevel >=  @nlevel))
		AND ((incometotal.flag&1)= 1) --Residuo
		AND incomeyear.ayear=@ayear

	UPDATE #fin_residual
		SET assessments = 
			ISNULL((SELECT SUM(incomeyear.amount)
				FROM incomeyear
				JOIN income
					ON  income.idinc = incomeyear.idinc
					AND incomeyear.ayear = @ayear
				JOIN incometotal
					ON  incomeyear.idinc = incometotal.idinc
					AND incomeyear.ayear = incometotal.ayear
				JOIN finlink
					ON  finlink.idchild  = incomeyear.idfin 
				WHERE 	income.adate <= @date 
					AND income.nphase = @assessmentphase
					AND ((incometotal.flag&1)= 1) --Residuo
					AND finlink.idparent = #fin_residual.idfin
					AND incomeyear.idupb = #fin_residual.idupb), 0.0),
		var_assessments =
			ISNULL((SELECT SUM(incomevar.amount)
				FROM incomevar
				JOIN incomeyear
					ON  incomeyear.idinc = incomevar.idinc
					AND incomeyear.ayear = @ayear
				JOIN income
					ON income.idinc = incomeyear.idinc
				JOIN finlink
					ON  finlink.idchild = incomeyear.idfin 
				JOIN incometotal
					ON incomeyear.idinc = incometotal.idinc
					AND incomeyear.ayear = incometotal.ayear
				WHERE 	incomevar.yvar = @ayear
				AND incomevar.adate <= @date
				AND income.nphase = @assessmentphase
				AND ((incometotal.flag&1)= 1) -- Residuo
				AND finlink.idparent = #fin_residual.idfin
				AND incomeyear.idupb = #fin_residual.idupb), 0.0)
	
	UPDATE #fin_residual
		SET proceeds = 
			ISNULL((SELECT SUM(HPV.amount)
				FROM historyproceedsview HPV
				JOIN finlink
					ON  finlink.idchild = HPV.idfin 
				WHERE 	HPV.ymov = @ayear
					AND HPV.competencydate <= @date
					AND ((HPV.totflag&1)= 1) --Residuo
					AND finlink.idparent = #fin_residual.idfin
					AND HPV.idupb = #fin_residual.idupb), 0.0)
	
	IF @cashvaliditykind <> 4
	BEGIN 
		UPDATE #fin_residual
		SET  var_proceeds =
			ISNULL((SELECT SUM(incomevar.amount)
				FROM incomevar
				JOIN historyproceedsview HPV 						
					ON HPV.idinc = incomevar.idinc
					AND HPV.ymov = @ayear
				JOIN finlink
					ON  finlink.idchild = HPV.idfin 
			WHERE 	incomevar.yvar = @ayear
				AND incomevar.adate <= @date
				AND HPV.competencydate <= @date
				AND ((HPV.totflag&1)= 1) -- Residuo
				AND finlink.idparent = #fin_residual.idfin
				AND HPV.idupb = #fin_residual.idupb), 0.0)
	END
	IF (@showupb <>'S') AND (@idupboriginal <> '%' ) AND (@showchildupb = 'S')
		UPDATE #fin_residual SET  
			upbprintingorder = (SELECT TOP 1 upbprintingorder
				FROM #fin_residual
				WHERE idupb = @idupboriginal),
			upb = (SELECT TOP 1 upb
				FROM #fin_residual
				WHERE idupb = @idupboriginal),
			idupb = @idupboriginal,
			codeupb =(SELECT TOP 1 codeupb
				FROM #fin_residual	
				WHERE idupb = @idupboriginal)
	
	IF (@showupb <>'S') and (@idupboriginal = '%') 
		UPDATE 	#fin_residual 
		SET  
			upbprintingorder = null,
			upb =  null,
			idupb = null,
			codeupb = null
	IF (@suppressifblank = 'S') -->  cancella le righe sottostanti la categoria
	BEGIN
		DELETE 
		FROM #fin_residual 
		WHERE 
			(isnull(assessments,0.0) =0 AND 
			isnull(var_assessments,0.0) =0 AND 
			isnull(proceeds,0.0) =0 AND 
			isnull(var_proceeds,0.0) =0 AND
			(select nlevel from fin FFF where FFF.idfin= #fin_residual.idfin)>=2
			) 
	END
IF (@showupb <>'S') 
	BEGIN
	SELECT 
	idfin,
	codeupb,
	idupb,
	upb,
	upbprintingorder,
	codefin,
	title,
	finprintingorder,
	nlevel,
	sum(isnull(assessments,0.0)) 		as	'assessments',
	sum(isnull(var_assessments,0.0)) 	as	'var_assessments',
	sum(isnull(proceeds,0.0)) 		as	'proceeds',
	sum(isnull(var_proceeds,0.0)) 		as	'var_proceeds',  
	flagconsider
	FROM #fin_residual 
	GROUP BY idupb,
		idfin,
		codeupb,
		upbprintingorder,
		upb,
		codefin,
		title,
		finprintingorder,
		nlevel,
		flagconsider	
	ORDER BY upbprintingorder,finprintingorder
	END
ELSE
	SELECT 
		idfin,
		codeupb,
		idupb,
		upb,
		upbprintingorder,
		codefin,
		title,
		finprintingorder,
		nlevel,
		assessments,
		var_assessments,
		proceeds,
		var_proceeds,
		flagconsider
	FROM #fin_residual 
	ORDER BY upbprintingorder,finprintingorder
END

GO

print '[rpt_sitbilancio_residui] OK'

GO
if object_id('[exp_contabilitaeconomicadallafinanziaria_bil]') is not null
	drop PROCEDURE [exp_contabilitaeconomicadallafinanziaria_bil]
go


CREATE     PROCEDURE [exp_contabilitaeconomicadallafinanziaria_bil]
(
	@ayear smallint,
	@adate datetime,
	@idsorkind int,
	@showupb char(1)='N',
	@idupb varchar(36)='%',
	@showchildupb char(1)='N',
	@officialvar  char(1)='S',
	@showmissioneprogrammi char(1)='S',
	@idsorkindmissioneprogrammi int,
	@idsor01 int=null,
	@idsor02 int=null,
	@idsor03 int=null,
	@idsor04 int=null,
	@idsor05 int=null
)
AS BEGIN
 -- exec exp_contabilitaeconomicadallafinanziaria_bil 2013, {ts '2013-12-31 00:00:00'}, 16, 'S','%','S','S','N',null,null,null,null,null,null
-- exec exp_contabilitaeconomicadallafinanziaria_bil 2013, {ts '2013-12-31 00:00:00'}, 16, 'S','%','S','S','S',5,null,null,null,null,null

DECLARE @idupboriginal varchar(36)
SET @idupboriginal = @idupb
declare @fixedidupb varchar(36)
set @fixedidupb= null
if (@showupb='N') set @fixedidupb='0001'
IF (@showchildupb = 'S')
BEGIN
	SET @idupb = @idupb + '%' 
END
DECLARE @MostraTutteVoci char(1)
SELECT @MostraTutteVoci = isnull(paramvalue,'N') 
FROM generalreportparameter WHERE idparam = 'MostraTutteVoci'
DECLARE @oplevel tinyint
SELECT @oplevel = MAX(nlevel) --> Prendiamo il max perchè le prev. vengono messe sui nodi foglia, enon sui capitolo come avviene per il bilancio.
FROM sortinglevel
WHERE  (flag&2)<>0 and idsorkind = @idsorkind
	
	
declare @fin_kind tinyint
SELECT  @fin_kind = isnull(fin_kind,0) FROM config WHERE ayear = @ayear
/*DECLARE @minoplevelfin tinyint
SELECT  @minoplevelfin = min(nlevel)
FROM 	finlevel
WHERE 	ayear = @ayear and flag&2 <> 0
*/
DECLARE @cashvaliditykind int
SELECT  @cashvaliditykind = cashvaliditykind FROM config WHERE ayear = @ayear
DECLARE @incomefinphase tinyint
DECLARE @expensefinphase tinyint
DECLARE @maxincomephase tinyint
DECLARE @maxexpensephase tinyint
SELECT @incomefinphase = assessmentphasecode FROM config WHERE ayear = @ayear
IF @incomefinphase IS NULL
BEGIN
	SELECT @incomefinphase = incomefinphase FROM uniconfig
END
SELECT @maxincomephase = MAX(nphase) FROM incomephase
SELECT @expensefinphase = appropriationphasecode FROM config WHERE ayear = @ayear
IF @expensefinphase IS NULL
BEGIN
	SELECT @expensefinphase = expensefinphase FROM uniconfig
END
SELECT @maxexpensephase = MAX(nphase) FROM expensephase
DECLARE @idfinincomesurplus int -- Flag indicante se l'avanzo di amministrazione è attribuito in previsione ad un capitolo di entrata o no --M. Smaldino
SELECT  @idfinincomesurplus = isnull(idfinincomesurplus,0) 
FROM config
WHERE ayear = @ayear
DECLARE @infoadvance char(1)
SELECT @infoadvance = paramvalue
FROM    generalreportparameter
WHERE   idparam = 'MostraAvanzo'
CREATE TABLE #data
(
	idsor int,
	idupb varchar(36),
	idsormissioneprogrammi int,
	quota decimal(19,2),
	prevision decimal(19,2),
	varprevision decimal (19,2),
	prevision2 decimal(19,2),
	prevision3 decimal(19,2),
	idfin int,
	E_mov_finphase_C decimal(19,2),
	E_var_finphase_C decimal(19,2),
	E_mov_maxphase_C decimal(19,2),	--> Ultima fase
	E_var_maxphase_C decimal(19,2),
	proceeds_C decimal(19,2),	
	var_proceeds_C decimal(19,2),	--> Incasso in base alla configurazione
	S_mov_finphase_C decimal(19,2),
	S_var_finphase_C decimal(19,2),
	S_mov_maxphase_C decimal(19,2),	--> Ultima fase
	S_var_maxphase_C decimal(19,2),
	payment_C decimal(19,2),		--> Pagamento in base alla configurazione
	var_payment_C decimal(19,2)
)

-- Inserisce previsione iniziale, previsione precedente, previsione anno+1, previsione anno+2
insert into #data (
	idfin,
	idsor,
	idupb,
	prevision,
	prevision2,
	prevision3
)
select finyear.idfin,
	FS.idsor,
	isnull(@fixedidupb,finyear.idupb),
	ISNULL(SUM(finyear.prevision),0),
	ISNULL(SUM(finyear.prevision2),0),
	ISNULL(SUM(finyear.prevision3),0)
from finyear 
	join fin f5 on finyear.idfin=f5.idfin
JOIN upb U
	ON finyear.idupb = U.idupb
/*JOIN finlevel fl
	ON f5.nlevel = fl.nlevel AND  f5.ayear = fl.ayear*/
join finsorting FS
	on finyear.idfin = FS.idfin
join sorting S
	on S.idsor = FS.idsor
where f5.ayear = @ayear
		and S.idsorkind = @idsorkind
		AND isnull(U.active,'N')='S'
		AND (finyear.idupb LIKE @idupb)	
		AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
		AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
		AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
		AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
		AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
		/*AND (f5.nlevel = @minoplevelfin
			OR (f5.nlevel < @minoplevelfin
				AND EXISTS (SELECT * FROM finlast WHERE finlast.idfin = f5.idfin)
				AND (fl.flag&2)<>0
			   )
			)*/
		AND (@infoadvance = 'N' OR @infoadvance = 'B' OR f5.idfin <> @idfinincomesurplus )
group by isnull(@fixedidupb,finyear.idupb),finyear.idfin, FS.idsor


INSERT INTO #data
(
	idfin,
	idsor,
	idupb,
	varprevision
)
SELECT
	FVD.idfin, ---ISNULL(FLK.idparent,FVD.idfin),
	FS.idsor,
	isnull(@fixedidupb,FVD.idupb),
	SUM(FVD.amount)
FROM finvardetail FVD
JOIN finvar FV
	ON FV.yvar = FVD.yvar
	AND FV.nvar = FVD.nvar
JOIN fin F
	ON FVD.idfin = F.idfin
JOIN upb U
	ON FVD.idupb = U.idupb
join finsorting FS
	on F.idfin = FS.idfin
join sorting S
	on S.idsor = FS.idsor
/*LEFT OUTER JOIN finlink FLK
	ON FLK.idchild = FVD.idfin AND FLK.nlevel = @minoplevelfin*/
WHERE FV.yvar = @ayear
	and S.idsorkind = @idsorkind
	AND FV.adate <= @adate
	AND FV.flagprevision = 'S'
	AND isnull(U.active,'N')='S'
	AND FV.idfinvarstatus = 5
	AND FV.variationkind <> 5
	AND
	((ISNULL(FV.official,'N') = 'S' AND ISNULL(@officialvar,'N') = 'S') -- consideriamo solo le variazioni ufficiali
	  OR ISNULL(@officialvar,'N') = 'N')
	AND (FVD.idupb LIKE @idupb)
	AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
	AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
	AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
	AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
	AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
GROUP BY isnull(@fixedidupb,FVD.idupb),FVD.idfin,/*ISNULL(FLK.idparent,FVD.idfin),*/ FS.idsor
-- Se deve mostrare anche i codice della class. Missioni Programmi, inserisce anche questi.
 CREATE TABLE #missioniprogrammi(
	idsor int NOT NULL,
	sortcode varchar(50),
	idupb varchar(36) NOT NULL,
	quota decimal(19,6) NULL,
	PRIMARY KEY (idsor,idupb)
)
if (@showmissioneprogrammi ='S')
Begin
	insert into #missioniprogrammi (
		idupb,
		idsor,
		sortcode,
		quota
	)
	select	
			isnull(@fixedidupb,US.idupb),
			US.idsor,
			sorting.sortcode,
			isnull(US.quota,1)
	from upbsorting US
	join sorting 
		on US.idsor = sorting.idsor
	join sortingkind K
		ON sorting.idsorkind = K.idsorkind
	JOIN upb U
		ON US.idupb = U.idupb
	where  K.idsorkind = @idsorkindmissioneprogrammi
			AND (US.idupb LIKE @idupb)	
			AND isnull(U.active,'N')='S'
			AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
			AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
			AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
			AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
			AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
End

-- PARTE ENTRATA
	INSERT INTO #data(
		idsor,
		idfin,
		idupb,
		E_mov_finphase_C
	)
	SELECT
		FS.idsor,
		IY.idfin,--ISNULL(FLK.idparent,IY.idfin),
		isnull(@fixedidupb,IY.idupb),
		SUM(IY.amount)
	FROM income I
	JOIN incomeyear IY
		ON IY.idinc = I.idinc
	JOIN finsorting FS
		ON FS.idfin = IY.idfin
	JOIN sorting S
		ON FS.idsor = S.idsor
	JOIN upb U
		ON IY.idupb = U.idupb
	JOIN incometotal IT
		ON IT.idinc = IY.idinc
		AND IT.ayear = IY.ayear
	/*LEFT OUTER JOIN finlink FLK
		ON FLK.idchild = IY.idfin AND FLK.nlevel = @minoplevelfin*/
	WHERE I.adate <= @adate
		AND IY.ayear = @ayear
		AND S.idsorkind = @idsorkind
		AND isnull(U.active,'N')='S'
		AND ( (IT.flag & 1) =0)	--> Competenza
		AND I.nphase = @incomefinphase
