if object_id('[trg_upd_upbunderwritingtotal]') is not null
	drop PROCEDURE [trg_upd_upbunderwritingtotal]
go

CREATE    PROCEDURE [trg_upd_upbunderwritingtotal]
(
	@idfin int,
	@idupb varchar(36),
	@idunderwriting int,
	@updatefield varchar(255),
	@amount decimal(19,2)
)
AS BEGIN
	DECLARE @cmd1 varchar(255)
	DECLARE @cmd2 varchar(255)
	DECLARE @cmd3 varchar(255)
	IF @idfin IS NOT NULL
	BEGIN
		DECLARE @nlevel tinyint
		SELECT @nlevel = nlevel FROM fin WHERE idfin = @idfin
		WHILE(@nlevel > 0)
		BEGIN
			IF NOT EXISTS (SELECT * FROM upbunderwritingtotal WHERE idfin = @idfin AND idupb = @idupb and idunderwriting = @idunderwriting)
			BEGIN
				SELECT @cmd1 = 'INSERT INTO upbunderwritingtotal'
				SELECT @cmd2 = '(idfin, idupb, idunderwriting, ' + @updatefield + ')'
				SELECT @cmd3 = 'VALUES (' + CONVERT(varchar(10),@idfin) + ', ''' + @idupb + ''','  + 
				CONVERT(varchar(10),@idunderwriting) + ','  + STR(@amount, 20, 4) + ')'
			END
			ELSE
			BEGIN
				SELECT @cmd1 = 'UPDATE upbunderwritingtotal SET '
				SELECT @cmd2 = @updatefield + ' = ISNULL(' + @updatefield + ', 0) + ' + STR(@amount, 20, 4)
				SELECT @cmd3 = ' WHERE idfin = ' + CONVERT(varchar(10),@idfin)
				SELECT @cmd3 = @cmd3 + ' AND idupb = ''' + @idupb + ''''
				SELECT @cmd3 = @cmd3 + ' AND idunderwriting = ' + CONVERT(varchar(10),@idunderwriting)
			END
			print @cmd1
			print @cmd2
			print @cmd3
			print @cmd1 + @cmd2 + @cmd3
			EXEC (@cmd1 + @cmd2 + @cmd3)
			-- Se modifico i campi delle variazioni di bilancio
			-- DEVO PROPAGARE LE MODIFICHE FINO AL TITOLO!
			-- Diversamente la modifica viene effettuata SOLO sul livello di pertinenza!
			IF (@updatefield = 'previsionvariation' OR @updatefield = 'secondaryvariation' OR 
				@updatefield = 'currentprev' OR @updatefield = 'currentsecondaryprev')
			BEGIN
				SET @nlevel = @nlevel - 1
				SELECT @idfin = idparent FROM finlink WHERE idchild = @idfin AND nlevel = @nlevel
			END
			ELSE
			BEGIN
				SET @nlevel = 0
			END
		END
	END
END


GO

print '[trg_upd_upbunderwritingtotal] OK'

GO
if object_id('rpt_sitbilancio_residui_respons') is not null
	drop PROCEDURE rpt_sitbilancio_residui_respons
go

CREATE  	PROCEDURE rpt_sitbilancio_residui_respons
	@ayear			int,
	@nlevel			tinyint,
	@hierarchy		char(1),
	@idman			int,
	@idupb			varchar(36),
	@showupb 		char(1),
	@showchildupb 		char(1),
	@suppressifblank 	char(1),
	@codefin		varchar(50),
	@start datetime,
	@stop datetime
AS
BEGIN
/* Versione 1.0.5 del 17/10/2007 ultima modifica: SARA */
DECLARE @idfin int
IF (@codefin IS NULL OR @codefin = '' OR @codefin = '%')
	BEGIN
		SET @idfin = null	
	END
Else
	BEGIN
	   	SET @idfin = (select idfin 
				from fin 
				where codefin = @codefin 
				and ayear=@ayear 
				and (fin.flag&1)=0) -- Entrata
	END
	CREATE  TABLE #fin_residual
	(
		idupb 			varchar(36),
		codeupb			varchar(50),
		upb   			varchar(150),
		upbprintingorder	varchar(50),
		idfin			int,
		codefin			varchar(50),
		title			varchar(150),
		finprintingorder	varchar(50),
		nlevel			tinyint,
		idman			int,
		manager			varchar(150),
		assessments		decimal(19,2),
		var_assessments		decimal(19,2),
		proceeds         	decimal(19,2),
		var_proceeds          	decimal(19,2)
	)
	
	IF (@ayear IS NULL) 
	BEGIN
		SELECT * FROM  #fin_residual 
		RETURN
	END
	
	DECLARE @idupboriginal 	varchar(36)
	SET @idupboriginal= @idupb
	IF (@showchildupb = 'S') set @idupb=@idupb+'%' 
	DECLARE @assessmentphase tinyint
	DECLARE @phasemax tinyint
	
	SELECT  @assessmentphase = assessmentphasecode
	FROM 	config
	WHERE 	ayear = @ayear
	SELECT  @phasemax = MAX(nphase)
	FROM 	incomephase
	
	DECLARE @cashvaliditykind int
	SELECT	@cashvaliditykind = cashvaliditykind
	FROM 	config
	WHERE 	ayear = @ayear
	declare @levelidfin tinyint
	select @levelidfin = nlevel from fin where idfin = @idfin
	INSERT INTO #fin_residual
		(
		idfin, 
		codefin,
		title,
		finprintingorder,
		codeupb	,	
		idupb,
		upb  ,
		upbprintingorder,
		nlevel,
		idman,
		manager)
	SELECT distinct
		fin.idfin,
		fin.codefin,
		fin.title, 
		fin.printingorder,
		upb.codeupb,	
		upb.idupb,
		upb.title ,
		upb.printingorder,
		fin.nlevel,
		manager.idman,
		manager.title
	FROM incomeyear
	join upb 
		ON  incomeyear.idupb = upb.idupb 
	JOIN fin
		ON  incomeyear.idfin = fin.idfin
	JOIN finlast
		ON  fin.idfin = finlast.idfin
	JOIN finlevel
		ON finlevel.nlevel = fin.nlevel
		AND finlevel.ayear = fin.ayear
		AND (finlevel.flag&2)<>0
	left outer JOIN finlink
		ON  finlink.idchild = fin.idfin and finlink.nlevel>=@levelidfin
	JOIN manager
		ON upb.idman = manager.idman
	JOIN incometotal
		ON  incomeyear.idinc = incometotal.idinc
		AND incomeyear.ayear = incometotal.ayear
	WHERE ((fin.flag&1)=0) --  Entrata
		AND ((upb.idman = @idman) OR  (@idman is null and upb.idman is not null))	
		AND fin.ayear = @ayear
		AND (@idfin IS NULL OR ISNULL(finlink.idparent,fin.idfin) = @idfin)
	    	AND (upb.idupb like @idupb )
		AND ((@hierarchy ='N' AND fin.nlevel = @nlevel) OR (@hierarchy ='S' AND fin.nlevel >=  @nlevel))
		AND ((incometotal.flag&1)= 1) --Residuo
		AND incomeyear.ayear=@ayear
	
	UPDATE #fin_residual
		SET assessments = 
			ISNULL((SELECT SUM(incomeyear.amount)
				FROM incomeyear
				JOIN income
					ON income.idinc = incomeyear.idinc
					AND incomeyear.ayear = @ayear
				JOIN incometotal
					ON  incomeyear.idinc = incometotal.idinc
					AND incomeyear.ayear = incometotal.ayear
				JOIN finlink
					ON  finlink.idchild = incomeyear.idfin 
				WHERE income.adate between @start and @stop 
					AND income.nphase = @assessmentphase
					AND  ((incometotal.flag&1)= 1) --Residuo
					AND finlink.idparent = #fin_residual.idfin
					AND incomeyear.idupb = #fin_residual.idupb), 0.0),
		var_assessments =
			ISNULL((SELECT SUM(incomevar.amount)
				FROM incomevar
				JOIN incomeyear
					ON incomeyear.idinc = incomevar.idinc
					AND incomeyear.ayear = @ayear
				JOIN income
					ON income.idinc = incomeyear.idinc
				JOIN finlink
					ON  finlink.idchild = incomeyear.idfin 
				JOIN incometotal
					ON incomeyear.idinc = incometotal.idinc
					AND incomeyear.ayear = incometotal.ayear
				WHERE 	incomevar.adate between @start and @stop 
					AND income.nphase = @assessmentphase
					AND finlink.idparent = #fin_residual.idfin
					AND incomeyear.idupb = #fin_residual.idupb
					AND ((incometotal.flag&1)= 1) --Residuo
					AND incomevar.yvar = @ayear), 0.0)
	
	UPDATE #fin_residual
		SET proceeds = 
			ISNULL((SELECT SUM(HPV.amount)
				FROM historyproceedsview HPV
				JOIN finlink
					ON  finlink.idchild = HPV.idfin 
				WHERE 	HPV.ymov = @ayear
					AND HPV.competencydate between @start and @stop
					AND ((HPV.totflag&1)= 1) --Residuo
					AND finlink.idparent = #fin_residual.idfin
					AND HPV.idupb = #fin_residual.idupb), 0.0)
	IF @cashvaliditykind <> 4
	BEGIN 
		UPDATE #fin_residual
		SET  var_proceeds =
			ISNULL((SELECT SUM(incomevar.amount)
				FROM incomevar
				JOIN historyproceedsview HPV 						
					ON HPV.idinc = incomevar.idinc
					AND HPV.ymov = @ayear
				JOIN finlink
					ON  finlink.idchild = HPV.idfin 
				WHERE incomevar.yvar = @ayear
				AND incomevar.adate between @start and @stop
				AND HPV.competencydate between @start and @stop
				AND HPV.ymov = @ayear
				AND ((HPV.totflag&1)= 1) -- Residuo
				AND finlink.idparent = #fin_residual.idfin
				AND HPV.idupb = #fin_residual.idupb), 0.0)
	END
IF (@showupb <>'S') AND (@idupboriginal <> '%' ) AND (@showchildupb = 'S')
	UPDATE #fin_residual SET  
		upbprintingorder = (SELECT TOP 1 upbprintingorder
			FROM #fin_residual
			WHERE idupb = @idupboriginal),
		upb = (SELECT TOP 1 upb
			FROM #fin_residual
			WHERE idupb = @idupboriginal),
		idupb = @idupboriginal,
		codeupb =(SELECT TOP 1 codeupb
			FROM #fin_residual	
			WHERE idupb = @idupboriginal)
	IF (@showupb <>'S') and (@idupboriginal = '%') 
		UPDATE #fin_residual SET  
		upbprintingorder = null	,
		upb =  null,
		idupb = null,
		codeupb = null
	IF (@suppressifblank = 'S') 	
	BEGIN
		DELETE 
		FROM #fin_residual 
		WHERE 
			(isnull(assessments,0.0) =0 AND 
			isnull(var_assessments,0.0) =0 AND 
			isnull(proceeds,0.0) =0 AND 
			isnull(var_proceeds,0.0) =0 
			AND nlevel >=2)
	END
IF (@showupb <>'S') 
BEGIN
	SELECT 
		idfin,
		codefin,
		title,
		finprintingorder,
		codeupb,
		idupb,
		upb,
		upbprintingorder,
		nlevel,
		idman,
		manager,
		sum(isnull(assessments,0.0)) 		as 'assessments'			,
		sum(isnull(var_assessments,0.0))	as 'var_assessments'				,
		sum(isnull(proceeds,0.0)) 		as 'proceeds'         			,
		sum(isnull(var_proceeds,0.0)) 		as 'var_proceeds' 
	FROM #fin_residual 
	GROUP BY upbprintingorder,
		finprintingorder,
		idfin,
		codeupb,
		idupb,
		upb,
		codefin,
		title,
		nlevel,
		idman,
		manager	
	ORDER BY finprintingorder
END
ELSE
	SELECT 
		idfin,
		codefin,
		title,
		finprintingorder,
		codeupb,
		idupb,
		upb,
		upbprintingorder,
		nlevel,
		idman,
		manager,
		assessments,
		var_assessments,
		proceeds,
		var_proceeds 
	FROM #fin_residual 
	ORDER BY manager
--EXEC rpt_sitbilancio_residui_respons @ayear=2007, @date={d '2007-09-10'}, @idfin=null, @nlevel=1, @hierarchy='S', @idman=null, @idupb=null, @showupb='S', @showchildupb='S', @suppressifblank='S'
END

GO

print 'rpt_sitbilancio_residui_respons OK'

GO
if object_id('[exp_invoicedet_prorata]') is not null
	drop PROCEDURE [exp_invoicedet_prorata]
go
CREATE  PROCEDURE [exp_invoicedet_prorata] 
(
		@year int 
)
AS
BEGIN
-- [exp_invoicedet_prorata] 2012
CREATE TABLE #invoicedet
	(
		idinvkind int,
		yinv int,
		ninv int,
		rownum int,
		adate datetime,
		registerclass char(1), --tipo registro A/V
		kind char(1), --tipo fattura A/V
		flagdeferred char(1),
		collected char(1),
		flagvariation char(1),
		flagintracom char(1),
		taxabletotal decimal(19,2),
		idivaregisterkindunified int, 
		codeivaregisterkind varchar(20),
		codeivakind varchar(20)
	)
INSERT INTO #invoicedet
	(
		idinvkind, yinv, ninv, rownum,
		registerclass,kind,flagdeferred, collected,flagvariation,flagintracom,
		taxabletotal,codeivakind,
		idivaregisterkindunified,codeivaregisterkind,adate
	)
	(SELECT
		I.idinvkind,I.yinv,I.ninv, IDET.rownum, 
		IRK.registerclass,		--tipo registro (A/V)
		CASE WHEN (IK.flag & 1)=0 THEN 'A'
		     ELSE 'V'
		END, 		--tipo fattura (A/V)
		I.flagdeferred,
		CASE 
			WHEN  	(I.flagdeferred = 'S') AND (Year(IDET.paymentcompetency) = @year OR IDET.idinc_taxable is not null) THEN 'S'
			ELSE 'N'
		END,
		CASE
			WHEN (IK.flag & 4) = 0 THEN 'N'
			ELSE 'S'
		END, 	
		I.flagintracom,
		ROUND(IDET.taxable * IDET.npackage * 
		 CONVERT(decimal(19,6),I.exchangerate) *
		  (1 - CONVERT(decimal(19,6),ISNULL(IDET.discount, 0.0))),2
		 ), 
		IVK.codeivakind,
		IRK.idivaregisterkindunified,
		IRK.codeivaregisterkind,
		I.adate
	FROM invoice I
	join invoicedetail IDET
		ON IDET.idinvkind=I.idinvkind
		AND IDET.yinv=I.yinv
		AND IDET.ninv=I.ninv
	JOIN invoicekind IK
		ON I.idinvkind = IK.idinvkind
	JOIN ivaregister IR
		ON IR.idinvkind = I.idinvkind
		AND IR.yinv = I.yinv
		AND IR.ninv = I.ninv
	JOIN ivaregisterkind IRK
		ON IRK.idivaregisterkind = IR.idivaregisterkind
	JOIN ivakind IVK
		ON IDET.idivakind = IVK.idivakind
	WHERE 	
		YEAR(I.adate) = @year 
		AND IRK.registerclass = 'V'
		-- con la condizione seguente intendiamo escludere le fatture che 
		-- sono soggette a doppia registrazione sia nel registro acquisti 
		-- che nel registro vendite (INTRACOM), infatti sono fatture di acquisto
		AND (SELECT COUNT(*) FROM ivaregister RA 
			 JOIN ivaregisterkind RAK
				ON RAK.idivaregisterkind = RA.idivaregisterkind
			 WHERE RA.idinvkind = I.idinvkind
			   AND RA.yinv = I.yinv
			   AND RA.ninv = I.ninv
			   AND RAK.registerclass = 'A'
			   ) = 0
		)
		
DECLARE @iddbdepartment varchar(50)
DECLARE @dbdepartment varchar(150)
--SELECT @iddbdepartment = iddbdepartment, @dbdepartment = description FROM dbdepartment
--WHERE iddbdepartment = user
SELECT 
@iddbdepartment,
@dbdepartment,
idinvkind,
yinv,
ninv,
rownum,
adate,
registerclass, --tipo registro A/V
kind, --tipo fattura A/V
flagdeferred,
collected, 
flagvariation,
flagintracom,
taxabletotal,
idivaregisterkindunified, 
codeivaregisterkind,
codeivakind
FROM #invoicedet


DROP TABLE #invoicedet
END


GO

print '[exp_invoicedet_prorata] OK'

