if object_id('[check_unified_totivapay]') is not null
	drop procedure [check_unified_totivapay]
go

-- exec check_unified_totivapay 2010,1
CREATE    procedure [check_unified_totivapay] (	
	@ayear int,
	@nmonth int
) as begin
	CREATE TABLE #currivapayed (
		iddbdepartment varchar(50),
		idivaregisterkindunified varchar(20),	
		description varchar(50)
)
	declare @query nvarchar(3000)
	declare @iddbdepartment varchar(50)
	declare @ivapay varchar(50)
	declare @ivapaydetail varchar(50)
	declare @ivaregisterkind varchar(50)
	declare @crsdepartment cursor
	set 	@crsdepartment = cursor for select  iddbdepartment from dbdepartment order by iddbdepartment
	open 	@crsdepartment
	fetch next from @crsdepartment into @iddbdepartment
	while @@fetch_status=0 begin
		declare @s varchar(300)
    	SET @ivapay = @iddbdepartment + '.ivapay'
    	SET @ivapaydetail = @iddbdepartment + '.ivapaydetail'
		SET @ivaregisterkind = @iddbdepartment + '.ivaregisterkind'
        SET  @query = 
		' SELECT 
			'''+@iddbdepartment+''',
		--  Nome registro
			R.idivaregisterkindunified,
			R.description
		FROM '+ @ivapay + ' I
		JOIN ' + @ivapaydetail + ' D
			ON I.nivapay = D.nivapay AND I.yivapay = D.yivapay
		JOIN '+ @ivaregisterkind +' R
			ON R.idivaregisterkind = D.idivaregisterkind
		WHERE MONTH(I.stop) = ' + CONVERT(varchar(4),@nmonth) + ' ' + ' AND YEAR(I.stop) = ' + CONVERT(varchar(4),@ayear) + ' '       
		insert into #currivapayed 
			(
			iddbdepartment,
			idivaregisterkindunified,
			description
			)
		EXEC sp_executesql @query
		fetch next from @crsdepartment into @iddbdepartment
	end
SELECT
		I.iddbdepartment, 
		D.description as department,
		I.description AS description
FROM #currivapayed I
JOIN dbdepartment D
	ON D.iddbdepartment=I.iddbdepartment
WHERE idivaregisterkindunified IS NULL
DROP TABLE #currivapayed
END

GO

print '[check_unified_totivapay] OK'

