if object_id('[doupdate_buono_ordine]') is not null
	drop PROCEDURE [doupdate_buono_ordine]
go

CREATE             PROCEDURE [doupdate_buono_ordine]
(
	@ayear int,
	@printkind char(1),
	@mandatekind varchar(20),
	@startnman int,
	@stopnman int
)
AS BEGIN
CREATE TABLE #printingdoc (num int)
IF @printkind = 'A' 
BEGIN
	INSERT INTO #printingdoc (num) 
	SELECT nman FROM mandate
	WHERE yman = @ayear
		AND officiallyprinted <>'S'
		AND idmankind = @mandatekind
END
IF @printkind <> 'A'
BEGIN
	INSERT INTO #printingdoc (num) 
	SELECT nman
	FROM mandate
	WHERE yman = @ayear
		AND nman BETWEEN @startnman AND @stopnman
		AND idmankind = @mandatekind
END
UPDATE mandate SET officiallyprinted = 'S'
WHERE yman = @ayear 
	AND idmankind = @mandatekind
	AND nman IN (SELECT num FROM #printingdoc)
END


GO

print '[doupdate_buono_ordine] OK'

