if object_id('[splitString]') is not null
	drop procedure [splitString]
go

CREATE                                                    procedure [splitString] (@codice varchar(8), @stringa varchar(151), @risultato varchar(240) output)
AS
BEGIN
	set @stringa = LTRIM(@stringa)
	set @stringa = RTRIM(@stringa)
	set @risultato = ''
	if (@stringa is null) or len(@stringa)=0 return
	DECLARE @sub varchar(16)
	declare @pos int
	
	exec allineaASinistra @stringa,16, @sub output
	set @risultato = upper(@codice + @sub)
	if (len(@stringa)<=16) return
	set @pos = 17
	while len(@stringa)-@pos>=15 
	begin
	   set @risultato = @risultato + @codice + '+' + substring(@stringa,@pos,15)
	   set @pos = @pos + 15
	end
	set @sub = substring(@stringa,@pos,len(@stringa))
	exec allineaASinistra @sub,15, @sub output
	set @risultato = upper(@risultato + @codice + '+' + @sub)
END


GO

print '[splitString] OK'

