if object_id('[compute_unified_prorata]') is not null
	drop PROCEDURE [compute_unified_prorata]
go
CREATE  PROCEDURE [compute_unified_prorata] 
(
		@year int
)
AS
BEGIN
--[compute_unified_prorata] 2012
 
CREATE TABLE #invoicedet
	(
		iddbdepartment varchar(50),
		dbdepartment varchar(150),
		idinvkind int,
		yinv int,
		ninv int,
		rownum int,
		adate datetime,
		registerclass char(1), --tipo registro A/V
		kind char(1), --tipo fattura A/V
		flagdeferred char(1),
		collected char(1),
		flagvariation char(1),
		flagintracom char(1),
		taxabletotal decimal(19,2),
		idivaregisterkindunified int, 
		codeivaregisterkind varchar(20),
		codeivakind varchar(20)
	)
	
	CREATE TABLE #groupbyivakind
	(
		iddbdepartment varchar(50),
		dbdepartment varchar(150),
		flagdeferred char(1),
		collected char(1),
		flagvariation char(1),
		flagintracom char(1),
		codeivakind varchar(20),
		description varchar(50),
		numerator char(1),
		denominator char(1),
		taxabletotal decimal(19,2)
	)
	
	-------------------------------------------------------
	------------ LETTURA DAI DIPARTIMENTI -----------------
	-------------------------------------------------------
	
declare @iddbdepartment varchar(50)
	declare @dbdepartment varchar(200)
	declare @crsdepartment cursor
	set 	@crsdepartment = cursor for select  iddbdepartment,description from dbdepartment
	where (start is null or start <= @year ) AND ( stop is null or stop >= @year)
	open 	@crsdepartment
	fetch next from @crsdepartment into @iddbdepartment, @dbdepartment
	while @@fetch_status=0 begin
		declare @dip_nomesp varchar(300)
		set @dip_nomesp = @iddbdepartment + '.[exp_invoicedet_prorata]'
		
		INSERT INTO #invoicedet
		(	
			iddbdepartment,
			dbdepartment,
			idinvkind,
			yinv,
			ninv,
			rownum,
			adate,
			registerclass, --tipo registro A/V
			kind, --tipo fattura A/V
			flagdeferred ,
			collected ,
			flagvariation,
			flagintracom,
			taxabletotal,
			idivaregisterkindunified, 
			codeivaregisterkind,
			codeivakind
		)
		exec @dip_nomesp @year 
		
		update  #invoicedet set iddbdepartment = @iddbdepartment, dbdepartment = @dbdepartment
		where iddbdepartment is null
		fetch next from @crsdepartment into @iddbdepartment,@dbdepartment
	END
	
	-- A questo punto devo cambiare il segno dell'imponibile di alcuni dettagli fattura
	-- in base a registerclass/kind/flagvariation
		update #invoicedet set taxabletotal=-taxabletotal 
		where registerclass<>kind AND flagintracom = 'N'
		update #invoicedet set taxabletotal=-taxabletotal 
		where flagvariation='S'
		
	INSERT INTO #groupbyivakind
	(
	--	iddbdepartment,
		flagdeferred,
		collected,
		flagvariation,
		flagintracom,
		codeivakind,
		description,
		numerator,
		denominator,
		taxabletotal
	)
	SELECT 
	--iddbdepartment, 
	flagdeferred,
	collected,
	flagvariation,
	flagintracom,
	#invoicedet.codeivakind,
	ivakind.description,
	CASE
		WHEN ((ivakind.flag&8)<>0) THEN 'S' 
		ELSE 'N'
	END,
	CASE
		WHEN ((ivakind.flag&16)<>0) THEN 'S' 
		ELSE 'N'
	END,
	SUM(taxabletotal)
	FROM #invoicedet 
	JOIN ivakind -- fa fede la configurazione dell'amministrazione
		ON ivakind.codeivakind = #invoicedet.codeivakind
	GROUP BY --iddbdepartment
	#invoicedet.codeivakind,ivakind.flag,ivakind.description,
	flagdeferred , collected , flagintracom,flagvariation
/*
DECLARE @numerator decimal(19,2)
DECLARE @denominator decimal(19,2)
DECLARE @prorata decimal(19,2)
SET @numerator = (SELECT SUM(taxabletotal) 
					FROM #groupbyivakind 
					WHERE numerator = 'S')
					
SET @denominator = (SELECT SUM(taxabletotal) 
				FROM #groupbyivakind 
				WHERE denominator = 'S')
IF ISNULL(@denominator,0) <> 0
SET @prorata = @numerator / @denominator
*/
SELECT 
flagdeferred,
collected,
flagintracom,
flagvariation,
codeivakind,
description,
numerator,
denominator,
taxabletotal
FROM #groupbyivakind 
ORDER BY codeivakind
DROP TABLE #invoicedet
DROP TABLE #groupbyivakind
END


GO

print '[compute_unified_prorata] OK'

GO
if object_id('[rpt_sitpatrim_ente]') is not null
	drop PROCEDURE [rpt_sitpatrim_ente]
go

--setuser 'amm'
--exec rpt_sitpatrim_ente 2010,1,'31-12-2010','N'
CREATE    PROCEDURE [rpt_sitpatrim_ente]
	@year int,
	@codinventoryagency int=null,
	@date datetime=null,
	@showmotive char(1)='N'
AS BEGIN
DECLARE @firstday datetime
SET @firstday = CONVERT(datetime, '01-01-' + CONVERT(char(4),@year), 105)
if (@date is null) SET @date = CONVERT(datetime, '31-12-' + CONVERT(char(4),@year), 105)
CREATE TABLE #assetloadmotive
(
idmot  int,
codemot varchar(20),
description  varchar(50)
)
INSERT INTO #assetloadmotive
(idmot, codemot, description)
SELECT idmot, codemot, description
FROM assetloadmotive
UNION
SELECT
null, null,null

CREATE TABLE #patrimonio
(
	codinventoryagency int,
	idsor int,
	description varchar(150),
	initial_amount decimal(19,2),
	idmot int,
	var_aum decimal(19,2),
	var_dim decimal(19,2)
)
INSERT INTO #patrimonio
(codinventoryagency,idsor,idmot,description)
SELECT ENTE.idinventoryagency,CLASS.idinv,MOTIVE.idmot,CLASS.description
FROM inventorytree CLASS 
CROSS JOIN inventoryagency ENTE
CROSS JOIN #assetloadmotive MOTIVE
WHERE CLASS.nlevel = 1
AND (ENTE.idinventoryagency = @codinventoryagency OR @codinventoryagency IS NULL )
AND (ENTE.active = 'S'						---Prende in considerazione le strutture attive o quelle inattive che abbiano una variazione nell'anno relativo alla stampa
	OR (ENTE.active = 'N' AND (SELECT COUNT(*) from assetvar AV
									JOIN assetvardetail AVD
										ON AV.idassetvar = AVD.idassetvar
									JOIN inventory I
										ON AVD.idinventory = I.idinventory
									JOIN inventoryagency IA
										ON I.idinventoryagency = IA.idinventoryagency
								WHERE AVD.amount > 0
								AND datepart(yy,AV.adate) = @year
								AND ENTE.idinventoryagency = IA.idinventoryagency
								) >0
		)
	)

CREATE TABLE #tempdata(	idente int, myid int, idmot int, valore decimal(19,2))
	
-------------------------------------------------------------------------------------
-------------------------- Situazione patrim. iniziale-------------------------------
-------------------------------------------------------------------------------------
UPDATE #patrimonio SET initial_amount =
ISNULL((SELECT SUM(assetvardetail.amount)
FROM assetvardetail
JOIN assetvar
	ON assetvar.idassetvar = assetvardetail.idassetvar
JOIN inventorytreelink
	ON inventorytreelink.idchild = assetvardetail.idinv
WHERE (assetvar.flag & 1 = 0)
	AND assetvar.yvar = @year
	AND assetvar.adate <= @date
	AND assetvar.idinventoryagency = #patrimonio.codinventoryagency
	AND ISNULL(assetvardetail.idmot,0) = ISNULL(#patrimonio.idmot,0)
	AND inventorytreelink.idparent = #patrimonio.idsor
	AND inventorytreelink.nlevel = 1),0)
-------------------------------------------------------------------------------------
-------------------------- Variazioni sit. patrim. ----------------------------------
-------------------------------------------------------------------------------------
UPDATE #patrimonio SET var_aum =	
ISNULL(
(SELECT	SUM(assetvardetail.amount)
FROM assetvardetail
JOIN assetvar
	ON assetvar.idassetvar = assetvardetail.idassetvar
JOIN inventorytreelink
	ON inventorytreelink.idchild = assetvardetail.idinv
WHERE (assetvar.flag & 1 <> 0)
	AND assetvar.yvar = @year
	AND assetvar.adate <= @date
	AND assetvardetail.amount > 0
	AND ISNULL(assetvardetail.idmot,0) = ISNULL(#patrimonio.idmot,0)
	AND assetvar.idinventoryagency = #patrimonio.codinventoryagency
	AND inventorytreelink.idparent = #patrimonio.idsor
	AND inventorytreelink.nlevel = 1),0)

UPDATE #patrimonio SET var_dim =	
- ISNULL(
(SELECT SUM(assetvardetail.amount)
FROM assetvardetail
JOIN assetvar
	ON assetvar.idassetvar = assetvardetail.idassetvar
JOIN inventorytreelink
	ON inventorytreelink.idchild = assetvardetail.idinv
WHERE (assetvar.flag & 1 <> 0)
	AND assetvar.yvar = @year
	AND assetvar.adate <= @date
	AND assetvardetail.amount < 0
	AND ISNULL(assetvardetail.idmot,0) = ISNULL(#patrimonio.idmot,0)
	AND assetvar.idinventoryagency = #patrimonio.codinventoryagency
	AND inventorytreelink.idparent = #patrimonio.idsor
	AND inventorytreelink.nlevel = 1),0)
	
-------------------------------------------------------------------------------------
-------------------------- Carichi cespiti E accessori -------------------------------
-------------------------------------------------------------------------------------
INSERT INTO #tempdata(idente,myid,idmot,valore)
SELECT
	inventory.idinventoryagency,
	inventorytreelink.idparent,
	assetacquire.idmot,
	sum(AC.start)
FROM assetacquire 
JOIN asset
	ON assetacquire.nassetacquire = asset.nassetacquire
JOIN assetview_current AC on AC.idasset=asset.idasset and AC.idpiece=asset.idpiece
JOIN assetload
	ON assetload.idassetload = assetacquire.idassetload
JOIN inventory
	ON assetacquire.idinventory = inventory.idinventory
JOIN inventorykind
	ON inventory.idinventorykind= inventorykind.idinventorykind
JOIN inventorytreelink
	ON inventorytreelink.idchild = assetacquire.idinv
WHERE inventorytreelink.nlevel = 1
	AND assetload.yassetload <= @year  
	AND assetload.ratificationdate BETWEEN @firstday AND @date
	AND (inventory.idinventoryagency = @codinventoryagency OR @codinventoryagency IS NULL)
GROUP BY inventory.idinventoryagency, inventorytreelink.idparent, assetacquire.idmot
	
UPDATE #patrimonio SET var_aum = ISNULL(var_aum,0) +
ISNULL( 
	(SELECT SUM(valore) 
	   FROM #tempdata 
	  WHERE idente = #patrimonio.codinventoryagency 
	    AND myid=#patrimonio.idsor
	    AND idmot=#patrimonio.idmot
)
,0)
DELETE FROM #tempdata
	
UPDATE #patrimonio SET var_aum= ISNULL(var_aum,0) +
ISNULL( 
	(SELECT SUM(valore) FROM #tempdata 
	WHERE idente = #patrimonio.codinventoryagency 
	AND myid=#patrimonio.idsor
	AND idmot = #patrimonio.idmot
	)
,0)
DELETE FROM #tempdata
-------------------------------------------------------------------------------------
----- Rivalutazioni positive ufficiali (di BENI E DI ACCESSORI) ---------------------
-------------------------------------------------------------------------------------
INSERT INTO #tempdata(idente,myid,idmot,valore)
SELECT
	inventory.idinventoryagency,
	inventorytreelink.idparent,
	assetacquire.idmot,
	SUM(ROUND(ISNULL(assetamortization.assetvalue,0) * ISNULL(assetamortization.amortizationquota,0),2))
FROM assetacquire
JOIN asset
	ON assetacquire.nassetacquire = asset.nassetacquire
JOIN assetamortization
	ON assetamortization.idasset = asset.idasset and assetamortization.idpiece = asset.idpiece
LEFT OUTER JOIN assetload
	ON  assetamortization.idassetload = assetload.idassetload
JOIN inventory
	ON inventory.idinventory = assetacquire.idinventory
JOIN inventoryamortization
	ON inventoryamortization.idinventoryamortization = assetamortization.idinventoryamortization
JOIN inventorytreelink
	ON inventorytreelink.idchild = assetacquire.idinv
WHERE inventorytreelink.nlevel = 1
	AND (inventoryamortization.flag & 2 <> 0)
	AND assetamortization.amortizationquota >= 0
	AND 
	(
		(
		 ((assetamortization.flag & 1 = 0)
		  AND assetamortization.adate BETWEEN @firstday AND @date) 
		  OR 
		  ((assetamortization.flag & 1 <> 0)
                   AND assetload.ratificationdate BETWEEN @firstday AND @date)
		)
	)
	AND (inventory.idinventoryagency = @codinventoryagency OR @codinventoryagency IS NULL )
GROUP BY inventory.idinventoryagency, inventorytreelink.idparent, assetacquire.idmot
UPDATE #patrimonio SET var_aum= ISNULL(var_aum,0) +
ISNULL( 
	(SELECT SUM(valore) FROM #tempdata 
	  WHERE idente = #patrimonio.codinventoryagency 
	    AND myid=#patrimonio.idsor
	    AND ISNULL(idmot,0)=ISNULL(#patrimonio.idmot,0)
)
,0)
DELETE FROM #tempdata
-------------------------------------------------------------------------------------
-------- Rivalutazioni Negative ufficiali  (di BENI E DI ACCESSORI)
-------------------------------------------------------------------------------------
INSERT INTO #tempdata(idente,myid,idmot,valore)
SELECT
	inventory.idinventoryagency,
	inventorytreelink.idparent,
	assetacquire.idmot,
	SUM(ROUND(ISNULL(assetamortization.assetvalue,0) * ISNULL(assetamortization.amortizationquota,0),2))
FROM assetacquire
JOIN asset
	ON assetacquire.nassetacquire = asset.nassetacquire
JOIN assetamortization
	ON assetamortization.idasset = asset.idasset and assetamortization.idpiece = asset.idpiece
LEFT OUTER JOIN assetunload
	ON  assetamortization.idassetunload = assetunload.idassetunload
JOIN inventory
	ON inventory.idinventory = assetacquire.idinventory
JOIN inventoryamortization
	ON inventoryamortization.idinventoryamortization = assetamortization.idinventoryamortization
JOIN inventorytreelink
	ON inventorytreelink.idchild = assetacquire.idinv
WHERE   inventorytreelink.nlevel = 1
	AND (inventoryamortization.flag & 2 <> 0)
	AND assetamortization.amortizationquota < 0 AND
	(
		(
		 ((assetamortization.flag & 1 = 0)
		  AND assetamortization.adate BETWEEN @firstday AND @date) 
		  OR 
		  ((assetamortization.flag & 1 <> 0)
                   AND assetunload.adate BETWEEN @firstday AND @date)
		)
	)
	AND (inventory.idinventoryagency = @codinventoryagency OR @codinventoryagency IS NULL )
GROUP BY inventory.idinventoryagency, inventorytreelink.idparent, assetacquire.idmot
UPDATE #patrimonio SET var_dim= ISNULL(var_dim,0) -
	ISNULL( 
		(SELECT SUM(valore) FROM #tempdata 
		WHERE idente = #patrimonio.codinventoryagency 
		  AND myid=#patrimonio.idsor
		  AND ISNULL(idmot,0)=ISNULL(#patrimonio.idmot,0)
)
	,0)
DELETE FROM #tempdata

	

-------------------------------------------------------------------------------------
-------------------------- Scarichi Cespite E accessori------------------------------------------
-----------------------------------------------------------------------------------
INSERT INTO #tempdata(idente,myid,idmot,valore)
SELECT
	inventory.idinventoryagency,
	inventorytreelink.idparent,
	assetacquire.idmot,
	sum(AC.currentvalue)
FROM assetacquire
LEFT OUTER JOIN assetload
	ON assetload.idassetload = assetacquire.idassetload
JOIN asset
	ON assetacquire.nassetacquire = asset.nassetacquire
JOIN assetview_current AC on AC.idasset=asset.idasset and AC.idpiece=asset.idpiece	
JOIN assetunload
	ON assetunload.idassetunload = asset.idassetunload
JOIN inventory
	ON assetacquire.idinventory = inventory.idinventory
JOIN inventorykind
	ON inventory.idinventorykind= inventorykind.idinventorykind   
JOIN inventorytreelink
	ON inventorytreelink.idchild = assetacquire.idinv
WHERE inventorytreelink.nlevel = 1
	AND assetunload.yassetunload <= @year
	AND assetunload.adate BETWEEN @firstday AND @date
	AND (inventory.idinventoryagency = @codinventoryagency OR @codinventoryagency IS NULL )
GROUP BY inventory.idinventoryagency, inventorytreelink.idparent,assetacquire.idmot

UPDATE #patrimonio SET var_dim= ISNULL(var_dim,0) +
ISNULL( 
	(SELECT SUM(valore) FROM #tempdata 
	WHERE idente=#patrimonio.codinventoryagency 
	AND myid=#patrimonio.idsor
	AND ISNULL(idmot,0)=ISNULL(#patrimonio.idmot,0)
	)
,0)
DELETE FROM #tempdata


DECLARE @MostraAvanzoCassa char(1)
SELECT  @MostraAvanzoCassa = isnull(paramvalue,'N')
FROM    reportadditionalparam
WHERE   paramname = 'MostraAvanzoCassa' and reportname='situazionepatrim_ente'
IF (Upper(@MostraAvanzoCassa)='S')
Begin
	DECLARE @startfloatfund decimal(19,2)
	DECLARE @aumfloatfund decimal(19,2)
	DECLARE @dimfloatfund decimal(19,2)
	SELECT 
		@startfloatfund = ISNULL(startfloatfund, 0.0),
	        @aumfloatfund = ISNULL(competencyproceeds, 0.0) + ISNULL(residualproceeds, 0.0),
	        @dimfloatfund = ISNULL(competencypayments, 0.0) + ISNULL(residualpayments, 0.0)
	FROM surplus
	WHERE ayear = @year
	
	INSERT INTO #patrimonio (idsor, idmot, description, initial_amount, var_aum, var_dim)
	VALUES('9999','9999','Avanzo di cassa', @startfloatfund, @aumfloatfund, @dimfloatfund)
End

IF (@showmotive= 'S') 
BEGIN
	DELETE FROM #patrimonio 
	WHERE  #patrimonio.idmot IS NULL 
	AND    ISNULL(initial_amount,0) = 0
	AND    ISNULL(var_aum,0) = 0 
	AND    ISNULL(var_dim,0) = 0
	SELECT 
		ENTE.codeinventoryagency AS 'codinventoryagency',
		ENTE.description as 'descinventoryagency',
		#patrimonio.idsor,
		CLASS.codeinv as 'codesor',
		CLASS.nlevel,
		#patrimonio.idmot,
		MOTIVE.description as 'motive',
		#patrimonio.description,
		initial_amount as 'initialamount',
		var_aum as 'amountimprove',
		var_dim as 'amountdecrease',
		@date as 'stop'
	FROM #patrimonio
	LEFT OUTER JOIN inventorytree CLASS 
		ON CLASS.idinv = #patrimonio.idsor
	LEFT OUTER JOIN inventoryagency	ENTE
		ON ENTE.idinventoryagency = #patrimonio.codinventoryagency
	LEFT OUTER JOIN #assetloadmotive MOTIVE
		ON MOTIVE.idmot = ISNULL(#patrimonio.idmot,0)
	ORDER BY #patrimonio.codinventoryagency,#patrimonio.idmot, codesor
END
ELSE
BEGIN
	SELECT 
		ENTE.codeinventoryagency AS 'codinventoryagency',
		ENTE.description as 'descinventoryagency',
		#patrimonio.idsor,
		CLASS.codeinv as 'codesor',
		CLASS.nlevel,
		null as 'idmot',
		null as 'motive',
		#patrimonio.description,
		ISNULL(SUM(initial_amount),0) as 'initialamount',
		ISNULL(SUM(var_aum),0) as 'amountimprove',
		ISNULL(SUM(var_dim),0) as 'amountdecrease',
		@date as 'stop'
	FROM #patrimonio
	LEFT OUTER JOIN inventorytree CLASS 
		ON CLASS.idinv = #patrimonio.idsor
	LEFT OUTER JOIN inventoryagency	ENTE
		ON ENTE.idinventoryagency = #patrimonio.codinventoryagency
	GROUP BY ENTE.codeinventoryagency, ENTE.description,#patrimonio.idsor,
		 CLASS.codeinv, CLASS.nlevel,#patrimonio.description
	ORDER BY  ENTE.codeinventoryagency, codesor
END
END

GO

print '[rpt_sitpatrim_ente] OK'

GO
if object_id('[doupdate_buono_ordine_contabilizzato]') is not null
	drop PROCEDURE [doupdate_buono_ordine_contabilizzato]
go


CREATE             PROCEDURE [doupdate_buono_ordine_contabilizzato]
(
	@ayear int,
	@printkind char(1),
	@mandatekind varchar(20),
	@startnman int,
	@stopnman int
)
AS BEGIN
CREATE TABLE #printingdoc (nman int)
IF @printkind = 'A' 
BEGIN
	INSERT INTO #printingdoc (nman) 
	SELECT nman FROM mandate
	WHERE yman = @ayear
		AND idmankind = @mandatekind
		AND officiallyprinted <>'S'
END
IF @printkind <> 'A'
BEGIN
	INSERT INTO #printingdoc (nman) 
	SELECT nman FROM mandate
	WHERE yman=@ayear
		AND idmankind = @mandatekind
		AND (nman BETWEEN @startnman AND @stopnman)
END
DECLARE @nphase tinyint
SELECT @nphase = expensephase FROM config WHERE ayear = @ayear
DELETE FROM #printingdoc
WHERE #printingdoc.nman NOT IN
	(SELECT mandate.nman
	FROM mandate
	INNER JOIN mandatedetail
		ON mandate.yman = mandatedetail.yman
		AND mandate.nman = mandatedetail.nman
	WHERE mandate.yman = @ayear
		AND mandate.idmankind = @mandatekind
	GROUP BY mandate.yman,mandate.nman, mandate.idmankind
	HAVING SUM(ISNULL(mandatedetail.taxable, 0) * ISNULL(mandatedetail.number,0)
		* (1 - ISNULL(mandatedetail.discount,0)) * (1 + ISNULL(mandatedetail.tax,0)))
		IN
			(SELECT ISNULL(SUM(o.curramount), 0)
			FROM  expensemandateview o 
			WHERE o.yman=mandate.yman
				AND o.nman = mandate.nman
				AND o.idmankind = mandate.idmankind
				AND o.nphase = @nphase
			GROUP BY o.nman, o.yman, o.idmankind)
	)
UPDATE mandate SET officiallyprinted = 'S'
WHERE yman = @ayear 
	AND idmankind = @mandatekind
	AND nman IN (SELECT nman from #printingdoc)
END


GO

print '[doupdate_buono_ordine_contabilizzato] OK'

GO
if object_id('[closeyear_copysortings]') is not null
	drop PROCEDURE [closeyear_copysortings]
go

CREATE        PROCEDURE [closeyear_copysortings]
(
	@ysource int,
	@movementkind char(1),  -- I/E Income / Expense
	@overwrite char(1)   --S/N
)
AS BEGIN
DECLARE @ydest int
SET @ydest = @ysource + 1
DECLARE @maxincomephase tinyint
DECLARE @maxexpensephase tinyint
SELECT @maxincomephase = max(nphase) from incomephase
SELECT @maxexpensephase = max(nphase) from expensephase
IF (@overwrite='S')
BEGIN
	IF (@movementkind='E')
	BEGIN
		DELETE FROM expensesorted WHERE (ayear = @ydest)
		AND EXISTS
			(SELECT * FROM expensesorted I
			JOIN sorting S
				ON S.idsor = I.idsor
			JOIN sorting S_EXT
				ON S_EXT.idsor = expensesorted.idsor
			WHERE (I.idexp = expensesorted.idexp)
				AND (I.ayear = @ysource)
				AND (S.idsorkind = S_EXT.idsorkind))
	END
	ELSE
	BEGIN
		DELETE FROM incomesorted WHERE (ayear = @ydest)
		AND EXISTS
			(SELECT * FROM incomesorted I
			JOIN sorting S
				ON S.idsor = I.idsor
			JOIN sorting S_EXT
				ON S_EXT.idsor = incomesorted.idsor
			WHERE (I.idinc = incomesorted.idinc)
				AND (I.ayear = @ysource)
				AND (S.idsorkind = S_EXT.idsorkind))
	END
END
PRINT 'Inizio: '
PRINT @ysource
-- tabella temporanea per i residui attivi/passivi multiclassificati
CREATE TABLE #movfinsorted
	(
		original_idsor   	int,
		original_idsorkind	int,
		lastphase_idsorkind	int,
		idexp_or_idinc		int,
		idsubclass		int,
		original_amount		decimal(19,2),
		lastphase_amount	decimal(19,2)
	)
IF (@movementkind='I')
BEGIN      
	IF EXISTS
		(SELECT * FROM incomesorted A1 
		JOIN incomeyear A2 
			ON A1.idinc = A2.idinc 
		WHERE (A1.ayear = @ysource)
			AND (A2.ayear = @ydest)
			AND
				(SELECT COUNT(*)
				FROM incomesorted II2
				WHERE (II2.idinc = A1.idinc)
					AND (II2.idsor=A1.idsor)
					AND (II2.ayear= @ydest)) = 0)
	BEGIN
DECLARE @idsorkindInc int
DECLARE @nphaseincome tinyint
DECLARE @siopeI_kind int
DECLARE crskindInc  cursor LOCAL STATIC FOR 
SELECT idsorkind,isnull(nphaseincome,0) FROM sortingkind  FOR READ ONLY
OPEN crskindInc
FETCH NEXT FROM crskindInc INTO @idsorkindInc, @nphaseincome
WHILE @@fetch_status=0 begin
			IF ( 
			EXISTS (select * from sortingkind where idparentkind = @idsorkindInc)
			AND ( (select ISNULL(nphaseincome,0) from sortingkind where idparentkind = @idsorkindInc) = @maxincomephase )
			)
			BEGIN
				SELECT @siopeI_kind = idsorkind from sortingkind where idparentkind = @idsorkindInc
				--Inserisce i dettagli delle classificazioni sull'accertamento, 
				--raggruppati sullo stesso codice, e le classificazioni 
				--degli incassi, raggruppati sullo stesso codice Siope
				DELETE FROM #movfinsorted
				INSERT INTO #movfinsorted
					(
						original_idsor   	,
						original_idsorkind	,
						lastphase_idsorkind	,
						idexp_or_idinc		,
						original_amount		,
						lastphase_amount	,
						idsubclass
					)
				SELECT
						I.idsor,
						@idsorkindInc,
						@siopeI_kind,	
						I.idinc,
						ISNULL(SUM(I.amount),0),
						(SELECT ISNULL(SUM(ES.amount),0)
						FROM incomesorted ES
						JOIN sorting S
							ON ES.idsor = S.idsor and S.idsorkind = @siopeI_kind --@SIOPE
						JOIN incomelast E
							ON E.idinc = ES.idinc 
						JOIN incomelink EL
							ON E.idinc=EL.idchild
							AND EL.nlevel = @nphaseincome --@nphase_eMIUR
						JOIN income EPADRE
							ON EPADRE.idinc=EL.idparent
						JOIN sorting MIUR
							ON  S.sortcode = MIUR.sortcode
						WHERE ES.ayear = @ysource 
							AND MIUR.idsor = I.idsor 
							AND MIUR.idsorkind = @idsorkindInc --@MIUR 
							AND EPADRE.idinc = I.idinc),
						(SELECT MAX(idsubclass) 
							FROM  incomesorted 
							WHERE incomesorted.idsor = I.idsor 
							AND   incomesorted.idinc = I.idinc 
						)
					FROM incomesorted I 
					JOIN incometotal I0
						ON I0.idinc=I.idinc
					JOIN incometotal I1
						ON I1.idinc=I.idinc
					JOIN sorting
						ON sorting.idsor = I.idsor 
					WHERE
						sorting.idsorkind=@idsorkindInc 
					--prende la classificazione dell'esercizio N-mo
						AND (I.ayear=@ysource)
					--esiste l'imputazione nell'anno sorgente
						AND (I0.ayear=@ysource)
					--esiste l'imputazione nell'anno successivo
						AND (I1.ayear=@ysource+1)
					--non esiste l'imputazione di quella classificazione nell'esercizio successivo
						AND (SELECT COUNT(*) FROM incomesorted I2
							WHERE (I2.idinc= I.idinc)
								AND (I2.idsor=I.idsor)	
								AND (I2.ayear= @ydest))=0
						 GROUP BY I.idsor,I.idinc
					
					-- SOTTRAE all'importo dell'accertamento la class.siope dell'Incasso
					INSERT INTO incomesorted 
					(
						idsor,idinc,idsubclass,ct,cu,stop,start,
						description,flagnodate,tobecontinued,amount,
						lt,lu,txt,rtf,
						paridsor,paridsubclass,valuen1,valuen2,valuen3,valuen4,valuen5,
						values1,values2,values3,values4,values5,
						valuev1,valuev2,valuev3,valuev4,valuev5,
						ayear
					)
 					SELECT
						original_idsor,idexp_or_idinc,idsubclass +1,GetDate(),'SortingsCopy',null,null,
						null,null,null, original_amount - lastphase_amount,
						GetDate(),'SortingsCopy',null,null,
						null,null,null,null,null, null,null,
						null,null,null, null,null,
						null,null,null, null,null,
						@ydest
					FROM #movfinsorted
					WHERE (original_amount - lastphase_amount) >0
					
					
				END
			ELSE
			BEGIN
			-- LAVORA COME PRIMA
				
				INSERT INTO incomesorted 
				(
					idsor,idinc,idsubclass,ct,cu,stop,start,
					description,flagnodate,tobecontinued,amount,lt,lu,txt,rtf,
					paridsor,paridsubclass,valuen1,valuen2,valuen3,valuen4,valuen5,
					values1,values2,values3,values4,values5,valuev1,valuev2,valuev3,valuev4,valuev5,ayear
				)
     				SELECT I.idsor,I.idinc,
					ISNULL(
						(SELECT I1.idsubclass FROM incomesorted I1
						WHERE (I1.idsubclass=I.idsubclass)
							AND (I1.idsor=I.idsor)
							AND (I1.idinc=I.idinc))
					,0)
					- ISNULL(
						(SELECT MIN(I1.idsubclass) FROM incomesorted I1
						WHERE (I1.idsor=I.idsor)
							AND (I1.idinc=I.idinc)
							AND (I1.ayear = @ysource))
					,0)
					+ ISNULL(
						(SELECT MAX(IA.idsubclass) FROM incomesorted IA
						WHERE (IA.idsor=I.idsor)
							AND (IA.idinc=I.idinc))
					,0)
					+1,
					I.ct,I.cu,I.stop,I.start,
					I.description,I.flagnodate,I.tobecontinued,
					CASE
						WHEN I1.curramount=I0.curramount THEN I.amount 
						ELSE I.amount*(CONVERT(float,I1.curramount)/CONVERT(float,I0.curramount))
					END,
					I.lt,I.lu,I.txt,I.rtf,
					I.paridsor,I.paridsubclass,I.valuen1,I.valuen2,I.valuen3,I.valuen4,I.valuen5,
					I.values1,I.values2,I.values3,I.values4,I.values5,I.valuev1,I.valuev2,I.valuev3,I.valuev4,I.valuev5,
					@ydest
				FROM incomesorted I 
				JOIN incometotal I0
					ON I0.idinc=I.idinc
				JOIN incometotal I1
					ON I1.idinc=I.idinc
				JOIN sorting
					ON sorting.idsor = I.idsor 
				WHERE
					sorting.idsorkind=@idsorkindInc 
				--prende la classificazione dell'esercizio N-mo
					AND (I.ayear=@ysource)
				--esiste l'imputazione nell'anno sorgente
					AND (I0.ayear=@ysource)
				--esiste l'imputazione nell'anno successivo
					AND (I1.ayear=@ysource+1)
				--non esiste l'imputazione di quella classificazione nell'esercizio successivo
					AND (SELECT COUNT(*) from incomesorted I2
						WHERE (I2.idinc= I.idinc)
							AND (I2.idsor=I.idsor)
							AND (I2.ayear= @ydest))=0
			END
	FETCH NEXT FROM crskindInc INTO @idsorkindInc,@nphaseincome
	end
	deallocate crskindInc
END
END
ELSE
BEGIN
	IF EXISTS(SELECT * FROM expensesorted A1 
		JOIN expenseyear A2
			ON A1.idexp=A2.idexp 
		WHERE (A1.ayear=@ysource)
			AND (A2.ayear=@ydest)
			AND
				(SELECT COUNT(*)
				from expensesorted II2
				where (II2.idexp= A1.idexp)
					AND (II2.idsor=A1.idsor)
					AND (II2.ayear= @ydest))=0)
	BEGIN
declare @idsorkindExp int
declare @nphaseexpense tinyint
declare @siopeE_kind int
declare @counter int
DECLARE crskindExp  cursor LOCAL STATIC FOR 
SELECT idsorkind,isnull(nphaseexpense,0) FROM sortingkind  FOR READ ONLY
OPEN crskindExp
FETCH NEXT FROM crskindExp INTO @idsorkindExp, @nphaseexpense
WHILE @@fetch_status=0 begin
			IF ( 
				EXISTS (select * from sortingkind where idparentkind = @idsorkindExp)
			AND 
				( (select ISNULL(nphaseexpense,0) from sortingkind where idparentkind = @idsorkindExp) = @maxexpensephase )
				)
			BEGIN
				SELECT @siopeE_kind = idsorkind from sortingkind where idparentkind = @idsorkindExp
			--Inserisce i dettagli delle classificazioni sull'impegno, 
			--raggruppati sullo stesso codice, e le classificazioni 
			--dei pagamenti, raggruppati sullo stesso codice Siope
				DELETE FROM #movfinsorted
				INSERT INTO #movfinsorted
					(
						original_idsor   	,
						original_idsorkind	,
						lastphase_idsorkind	,
						idexp_or_idinc		,
						original_amount		,
						lastphase_amount	,
						idsubclass		
					)
				SELECT
						I.idsor,
						@idsorkindExp,
						@siopeE_kind,
						I.idexp,
						ISNULL(SUM(I.amount),0),
						(SELECT ISNULL(SUM(ES.amount),0)
						FROM expensesorted ES
						JOIN sorting S
							ON ES.idsor = S.idsor and S.idsorkind = @siopeE_kind--@SIOPE
						JOIN expenselast E
							ON E.idexp = ES.idexp 
						JOIN expenselink EL
							ON E.idexp=EL.idchild
							AND EL.nlevel = @nphaseexpense--@nphase_eMIUR
						JOIN expense EPADRE
							ON EPADRE.idexp=EL.idparent
						JOIN sorting MIUR
							ON  S.sortcode = MIUR.sortcode
						WHERE ES.ayear = @ysource 
							AND MIUR.idsor = I.idsor 
							AND MIUR.idsorkind = @idsorkindExp--@MIUR 
							AND EPADRE.idexp = I.idexp),
						(SELECT MAX(idsubclass) 
							FROM  expensesorted 
							WHERE expensesorted.idsor = I.idsor 
							AND   expensesorted.idexp = I.idexp 
						)
				FROM expensesorted I 
				JOIN expensetotal I0
					ON I0.idexp=I.idexp
				JOIN expensetotal I1
					ON I1.idexp=I.idexp
				JOIN sorting
					ON sorting.idsor = I.idsor 
				WHERE
				sorting.idsorkind=@idsorkindExp 
				--prende la classificazione dell'esercizio N-mo
				AND (I.ayear=@ysource)
				--esiste l'imputazione nell'anno sorgente
					AND (I0.ayear=@ysource)
				--esiste l'imputazione nell'anno successivo
					AND (I1.ayear=@ysource+1)
				--non esiste l'imputazione di quella classificazione nell'esercizio successivo
					AND (SELECT COUNT(*) FROM expensesorted I2
						WHERE (I2.idexp= I.idexp)
							AND (I2.idsor=I.idsor)	
							AND (I2.ayear= @ydest))=0
				GROUP BY I.idsor,I.idexp
				
				-- SOTTRAE all'importo dell'impegno la class.siope del pagamento
				INSERT INTO expensesorted 
					(
						idsor,idexp,idsubclass,ct,cu,stop,start,
						description,flagnodate,tobecontinued,amount,lt,lu,txt,rtf,
						paridsor,paridsubclass,valuen1,valuen2,valuen3,valuen4,valuen5,
						values1,values2,values3,values4,values5,valuev1,valuev2,valuev3,valuev4,valuev5,ayear
					)
				SELECT 
					original_idsor,idexp_or_idinc,idsubclass +1,GetDate(),'SortingsCopy',null,null,
					null,null,null, original_amount - lastphase_amount,
					GetDate(),'SortingsCopy',null,null,
					null,null,null,null,null, null,null,
					null,null,null, null,null,
					null,null,null, null,null,
					@ydest
				FROM #movfinsorted
				WHERE (original_amount - lastphase_amount) >0
				
			END
			ELSE
			BEGIN
			-- LAVORA COME PRIMA
					INSERT INTO expensesorted 
					(
						idsor,idexp,idsubclass,ct,cu,stop,start,
						description,flagnodate,tobecontinued,amount,lt,lu,txt,rtf,
						paridsor,paridsubclass,valuen1,valuen2,valuen3,valuen4,valuen5,
						values1,values2,values3,values4,values5,valuev1,valuev2,valuev3,valuev4,valuev5,ayear
					)
 					SELECT
						I.idsor,I.idexp,
						ISNULL(
							(SELECT I1.idsubclass FROM expensesorted I1
							WHERE (I1.idsubclass=I.idsubclass)
								AND (I1.idsor=I.idsor)
								AND (I1.idexp=I.idexp))
						,0)
						- ISNULL(
							(SELECT MIN(I1.idsubclass) FROM expensesorted I1
							WHERE (I1.idsor=I.idsor)
								AND (I1.idexp=I.idexp)
								AND (I1.ayear = @ysource))
						,0)
						+ ISNULL(
							(SELECT MAX(IA.idsubclass) FROM expensesorted IA
							WHERE (IA.idsor=I.idsor)
								AND (IA.idexp=I.idexp))
						,0)
						+1,
						getdate(),'SortingsCopy',I.stop,I.start,
						I.description,I.flagnodate,I.tobecontinued,
						CASE
							WHEN I1.curramount=I0.curramount THEN I.amount 
							ELSE I.amount*(CONVERT(float,I1.curramount)/CONVERT(float,I0.curramount))
						END,
						I.lt,I.lu,I.txt,I.rtf,
						I.paridsor,I.paridsubclass,I.valuen1,I.valuen2,I.valuen3,I.valuen4,I.valuen5,
						I.values1,I.values2,I.values3,I.values4,I.values5,I.valuev1,I.valuev2,I.valuev3,I.valuev4,I.valuev5,
						@ydest
					FROM expensesorted I 
					JOIN expensetotal I0
						ON I0.idexp=I.idexp
					JOIN expensetotal I1
						ON I1.idexp=I.idexp
					JOIN sorting
						ON sorting.idsor = I.idsor 
					WHERE
					sorting.idsorkind=@idsorkindExp 
					--prende la classificazione dell'esercizio N-mo
					AND (I.ayear=@ysource)
					--esiste l'imputazione nell'anno sorgente
						AND (I0.ayear=@ysource)
					--esiste l'imputazione nell'anno successivo
						AND (I1.ayear=@ysource+1)
					--non esiste l'imputazione di quella classificazione nell'esercizio successivo
						AND (SELECT COUNT(*) FROM expensesorted I2
							WHERE (I2.idexp= I.idexp)
								AND (I2.idsor=I.idsor)	--
								AND (I2.ayear= @ydest))=0
			END
	
	FETCH NEXT FROM crskindExp INTO @idsorkindExp,@nphaseexpense
end
deallocate crskindExp

	END
END
PRINT 'Finisco: '
PRINT @ysource
END


