print '[closeyear_copysortings] OK'

GO
if object_id('[exp_payment_not_transmitted]') is not null
	drop PROCEDURE [exp_payment_not_transmitted]
go

--exp_payment_not_transmitted 2009,'27-11-2009','T'
CREATE   PROCEDURE [exp_payment_not_transmitted]
(
	@ayear int,	  	-- esercizio
	@printdate datetime,    -- filtro sulla data di stampa ufficiale
	@kind  char(1),         -- T: tutti, R:a regolarizzazione, N:non a regolarizzazione
	@annulled char(1)	-- T: tutti, S:annullati, N: non annullati
)
AS BEGIN
	CREATE TABLE #payment
	(
	phase varchar(50),
	idexp int,
	idreg int,
	registry varchar(100),
	ymov int,
	nmov int,
	doc varchar(35),
	docdate smalldatetime,
	description varchar(150),
	finance varchar(150),
	upb varchar(150),
	curramount decimal(19,2),
	taxamount decimal(19,2),
	netamount decimal(19,2),
	ypay int,
	npay int,
	flagarrear char(1),
	adate smalldatetime,
	printdate smalldatetime,
	transmissiondate smalldatetime,
	annulmentdate	smalldatetime
	)

	INSERT INTO #payment
	(phase,idexp,idreg,registry,ymov,nmov,doc,docdate, 
	description,finance,upb,curramount,ypay,npay,
	flagarrear,adate,printdate,transmissiondate, annulmentdate)
	SELECT 
	EL.phase,EL.idexp, EL.idreg,EL.registry, EL.ymov, EL.nmov,
	EL.doc, EL.docdate, EL.description,EL.finance, EL.upb, EL.curramount,
	EL.ypay,EL.npay, EL.flagarrear,P.adate,P.printdate,PT.transmissiondate,P.annulmentdate
	FROM expenselastview EL
	JOIN payment P
		ON P.kpay = EL.kpay
	LEFT OUTER JOIN paymenttransmission PT
		ON PT.kpaymenttransmission = P.kpaymenttransmission
	WHERE EL.ypay = @ayear 
	AND P.printdate <= @printdate AND
	(
		(EL.nbill IS NULL AND @kind = 'N') OR
		(EL.nbill IS NOT NULL AND @kind = 'R') OR
		(@kind = 'T')
	)
	AND
	(
		((EL.curramount > 0) AND @annulled = 'N') OR
		((EL.curramount = 0) AND @annulled = 'S') OR
		(@annulled = 'T')
	)
	AND ISNULL(PT.transmissiondate,'2079-01-01')>@printdate
	ORDER BY EL.ymov, EL.nmov,EL.ypay,EL.npay
	CREATE TABLE #retensions
	(
		ypro int,
		npro int,
		idexp int,
		idreg int,
		idinc int,
		curramount decimal(19,2)
	)
	
	insert into #retensions
	(idexp,idinc,ypro,npro,idreg,curramount)
	SELECT 
	p.idexp,e.idinc,di.ypro,di.npro,
	c.idreg,ie.curramount
	FROM #payment p
	JOIN income e
		ON e.idpayment = p.idexp
	JOIN incomelast il
		ON il.idinc = e.idinc
	JOIN incometotal ie
		ON e.idinc = ie.idinc
	JOIN proceeds di
		ON di.kpro = il.kpro
	JOIN registry c
		ON e.idreg = c.idreg
	WHERE  (
		(e.autokind = 6)  
		OR (e.autokind = 14) --'GENER' automatismo generico
		OR (e.autokind = 4 AND e.idreg = p.idreg)
	)
	AND ie.ayear = @ayear
	
	-- Calcolo dell'importo delle trattenute
	UPDATE #payment
	SET taxamount = 
	ISNULL(
		(SELECT SUM(curramount)
		FROM #retensions
		WHERE #retensions.idexp = #payment.idexp)
	,0)
	-- Calcolo del netto
	UPDATE #payment 
	SET netamount = ISNULL(curramount,0) - ISNULL(taxamount,0)
	SELECT 
		phase as 'Fase',
		ymov as 'Eserc. Mov.' ,
		nmov as 'Num. Mov',
		registry as 'Anagrafica',
		description as 'Descrizione',
		finance as 'Bilancio',
		upb as 'UPB',
		curramount as 'Importo Corrente',
		netamount as 'Netto a Pagare',
		flagarrear as 'Compet.',
		ypay as 'Eserc. Mandato',
		npay as 'Num. Mandato',
		adate as 'Emissione',
		printdate as 'Stampa Uff.',
		transmissiondate as 'Trasmissione',
		annulmentdate	as 'Annullamento'
	FROM #payment
	ORDER BY ymov, nmov,ypay, npay
END

GO

print '[exp_payment_not_transmitted] OK'

GO
if object_id('[rpt_sitclassificazioneupb]') is not null
	drop PROCEDURE [rpt_sitclassificazioneupb]
go

/* 
exec rpt_sitclassificazioneupb 2013, {ts '2013-12-31 00:00:00'}, 6, 47, 3, '%', 'S', 'S', null, null,null,null,null,null,'A','N'
exec rpt_sitclassificazioneupb 2013, {ts '2013-12-31 00:00:00'}, 6,47,3, '00010007', 'S', 'S', 14862, null,null,null,null,null,'A','N'
exec rpt_sitclassificazioneupb 2013, {ts '2013-12-31 00:00:00'}, 6, 47, 3, '%', 'S', 'S', null, null,null,null,null,null,'A','N'
*/
CREATE  PROCEDURE [rpt_sitclassificazioneupb]
	@ayear			int,
	@date			datetime,
	@idsorkind_cdr	int, --> Classificazione Centro di Responsabilità
	@idsorkind	int, --> Classificazione Missioni Programmi
	@nlevel			tinyint,
	@idupb			varchar(36),
	@showchildupb char(1),
	@suppressifblank 	char(1),
	@idfin			int,
	@idsor01 int,
	@idsor02 int,
	@idsor03 int,
	@idsor04 int,
	@idsor05 int ,
	@printkind char(1),   -- Indica il tipo di importi da visualizzare P = preventivo, C = consuntivo, A = all
	@compatta char(1) -- Sono le stampe 4/prev e 4/cons. mostrano solo i totali su Missioni e Programmi
AS
BEGIN
CREATE TABLE #situation_fin
(
	idupb 			varchar(36),
	idsor int,
	idsor_cdr int,
	assured			char(1),
	idfin			int,
	nlevel			tinyint,
	main_initial_prevision	decimal(19,2),
	var_main_prevision	decimal(19,2),
	fin_ph_comp		decimal(19,2),
	var_fin_ph_comp		decimal(19,2), 
	desc_fin_ph 		varchar(50),					
	registry_ph_comp	decimal(19,2),
	var_registry_ph_comp	decimal(19,2),
	desc_registry_ph 	varchar(50),					
	max_ph_comp         	decimal(19,2),
	var_max_ph_comp       	decimal(19,2),
	desc_max_ph 		varchar(50),					
	sec_initial_prevision	decimal(19,2),
	varprevsec		decimal(19,2),
	fin_ph_resid		decimal(19,2), 
	var_fin_ph_resid	decimal(19,2),
	registry_ph_resid	decimal(19,2),
	var_registry_ph_resid	decimal(19,2),
	max_ph_resid         	decimal(19,2),
	var_max_ph_resid      	decimal(19,2),
	previsionkind 		char(1),
	secprevisionkind 	char(1)
)
IF @ayear IS NULL 
BEGIN
	SELECT * FROM  #situation_fin 
	RETURN
END
IF( @nlevel is null)
Begin
	SELECT  @nlevel = min(nlevel)
	FROM 	finlevel
	WHERE 	ayear = @ayear and flag&2 <> 0
End
IF 	(@showchildupb = 'S') set @idupb=@idupb+'%' 
DECLARE @levelusable tinyint
SELECT  @levelusable = MIN(nlevel) 
FROM 	finlevel
WHERE 	ayear =@ayear and (flag&2)<>0
DECLARE @fin_phase  tinyint -- fase accantonamento precedente alla fase di impegno, Modifica Sara
SELECT 	@fin_phase = expensefinphase FROM uniconfig
DECLARE @desc_fin_phase varchar(50)
SELECT  @desc_fin_phase=description
FROM 	expensephase WHERE nphase=@fin_phase 
DECLARE @registry_phase tinyint
SELECT  @registry_phase = expenseregphase FROM uniconfig
DECLARE @desc_registry_phase varchar(50)
SELECT  @desc_registry_phase=description
FROM    expensephase WHERE nphase=@registry_phase 
DECLARE @max_phase          	tinyint
SELECT  @max_phase = MAX(nphase) FROM expensephase
DECLARE @desc_max_phase    	varchar(50)
SELECT  @desc_max_phase=description 
FROM 	expensephase WHERE nphase=@max_phase 
DECLARE @previsionkind char(1) 
SELECT  @previsionkind =  
	 CASE 
		WHEN fin_kind IN (1,3) THEN 'C'
		WHEN fin_kind = 2 THEN 'S'
	 END
FROM  config 
WHERE config.ayear = @ayear
DECLARE @secprevisionkind    char(1) 
SELECT  @secprevisionkind  = 
	 CASE 
		WHEN fin_kind = 3 THEN 'S'
		ELSE 'N'
	END
FROM config 
WHERE config.ayear = @ayear

DECLARE @flag_cs     		char(1)
SELECT 	@flag_cs =  CASE 
		WHEN fin_kind IN (1,3) THEN 'C'
		WHEN fin_kind = 2 THEN 'S'
	 END
FROM 	config
WHERE 	ayear = @ayear
DECLARE @cashvaliditykind	int
SELECT 	@cashvaliditykind = cashvaliditykind
FROM 	config
WHERE 	ayear = @ayear
DECLARE @level_input tinyint
SET  @level_input = ISNULL((SELECT nlevel from fin where idfin = @idfin) ,@nlevel)
-- ho scelto come livello 2 e poi ho specificato il capitolo, lui corregge @nlevel dandogli 3
IF (@nlevel < @level_input) AND (@idfin is not null)
	BEGIN
	SET  @nlevel = @level_input
	END
INSERT INTO #situation_fin(
	idfin,
	nlevel,
	idupb,
	idsor,
	idsor_cdr,
	assured,
	main_initial_prevision
)
SELECT 
	F.idfin, 
	F.nlevel,
	U.idupb,
	US.idsor,
	US_CdR.idsor,
	ISNULL(U.assured,'N'),
	SUM(isnull(finyear.prevision,0)*isnull(US.quota,0))
FROM finyear
JOIN upb  U
	ON  finyear.idupb = U.idupb
JOIN upbsorting US
	ON U.idupb = US.idupb	
join sorting S
	ON S.idsor = US.idsor	
JOIN upbsorting US_CdR
	ON U.idupb = US_CdR.idupb	
join sorting S_CdR
	ON US_CdR.idsor = S_CdR.idsor	
JOIN fin F
	ON finyear.idfin = F.idfin
JOIN finlink FLK
	ON FLK.idchild = F.idfin and FLK.nlevel=@level_input
WHERE ((F.flag&1)<>0) -- Spesa
	AND (finyear.ayear = @ayear)
	AND (@idfin IS NULL OR FLK.idparent = @idfin)
    AND (U.idupb LIKE @idupb and U.active = 'S')
	AND  F.nlevel = @nlevel
	and S.idsorkind = @idsorkind
	AND S_CdR.idsorkind = @idsorkind_cdr
	AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
	AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
	AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
	AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
	AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
GROUP BY  U.idupb, US.idsor, US_CdR.idsor, F.idfin, F.nlevel,ISNULL(U.assured,'N')

IF(@printkind in ('A','C'))
Begin
	INSERT INTO #situation_fin(
		idfin,
		nlevel,
		idupb,
		idsor,
		idsor_cdr,
		assured,
		var_main_prevision
	)
	SELECT 
		F.idfin, 
		F.nlevel,
		 U.idupb,
		US.idsor,
		US_CdR.idsor,
		ISNULL(U.assured,'N'),
		SUM(isnull(finvardetail.amount,0)*isnull(US.quota,0))
	FROM fin F
	JOIN finlink FLK
		ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
	JOIN finlink FLK2
		ON FLK2.idparent = F.idfin 
	JOIN finvardetail
		ON ISNULL(FLK2.idchild,F.idfin) = finvardetail.idfin
	JOIN finvar
  		ON finvar.yvar = finvardetail.yvar  
  		AND finvar.nvar = finvardetail.nvar 
	JOIN upb U 
		ON finvardetail.idupb = U.idupb		
	JOIN upbsorting US
		ON U.idupb = US.idupb	
	join sorting S
		ON S.idsor = US.idsor	
	JOIN upbsorting US_CdR
		ON U.idupb = US_CdR.idupb	
	join sorting S_CdR
		ON US_CdR.idsor = S_CdR.idsor	
	WHERE ((F.flag&1)<>0 ) -- Spesa
		AND finvar.yvar = @ayear		
		AND (U.idupb like @idupb and U.active = 'S')
		AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
		AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
		AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
		AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
		AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
		AND (@idfin IS NULL OR isnull(FLK.idparent, F.idfin) = @idfin)
		AND  F.nlevel = @nlevel
		and S.idsorkind = @idsorkind
		AND S_CdR.idsorkind = @idsorkind_cdr
		AND finvar.flagprevision ='S'	
		AND finvar.idfinvarstatus = 5
		AND finvar.variationkind <> 5
		AND finvar.adate <= @date
	GROUP BY  U.idupb, US.idsor, US_CdR.idsor, F.idfin,F.nlevel, ISNULL(U.assured,'N')

	INSERT INTO #situation_fin(
		idfin, nlevel,
		idupb,
		idsor,
		idsor_cdr,
		assured,
		fin_ph_comp
	)
	SELECT 
		F.idfin, F.nlevel,
		 U.idupb,
		 US.idsor,
		 US_CdR.idsor,
		ISNULL(U.assured,'N'),
		SUM(isnull(expenseyear.amount,0)*isnull(US.quota,0))
	FROM fin F
	JOIN finlink FLK
		ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
	JOIN finlink FLK2
		ON FLK2.idparent = F.idfin 
	JOIN expenseyear
		ON ISNULL(FLK2.idchild,F.idfin) = expenseyear.idfin
		AND expenseyear.ayear = @ayear
	JOIN expense
		ON expenseyear.idexp = expense.idexp
	JOIN expensetotal
		ON  expenseyear.idexp = expensetotal.idexp
		AND expenseyear.ayear = expensetotal.ayear
	JOIN upb U 
		ON expenseyear.idupb = U.idupb	
	JOIN upbsorting US
		ON U.idupb = US.idupb	
	join sorting S
		ON S.idsor = US.idsor		
	JOIN upbsorting US_CdR
		ON U.idupb = US_CdR.idupb	
	join sorting S_CdR
		ON US_CdR.idsor = S_CdR.idsor	
	WHERE expense.adate <= @date
		AND expense.nphase = @fin_phase
		AND (U.idupb like @idupb and U.active = 'S')
		AND ((expensetotal.flag&1)= 0) -- Competenza
		AND (@idfin IS NULL OR FLK.idparent = @idfin)
		AND  F.nlevel = @nlevel
		and S.idsorkind = @idsorkind
		AND S_CdR.idsorkind = @idsorkind_cdr
		AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
		AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
		AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
		AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
		AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
	GROUP BY  U.idupb, US.idsor, US_CdR.idsor, F.idfin, F.nlevel, ISNULL(U.assured,'N')
	INSERT INTO #situation_fin(
		idfin, nlevel,
		idupb,
		idsor,
		idsor_cdr,
		assured,
		var_fin_ph_comp
	)
	SELECT 
		F.idfin, F.nlevel,
		 U.idupb,
		 US.idsor,
		 US_CdR.idsor,
		ISNULL(U.assured,'N'),
		SUM(isnull(expensevar.amount,0)*isnull(US.quota,0))
	FROM fin F
	JOIN finlink FLK
		ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
	JOIN finlink FLK2
		ON FLK2.idparent = F.idfin 
	JOIN expenseyear
		ON ISNULL(FLK2.idchild,F.idfin) = expenseyear.idfin
		AND expenseyear.ayear = @ayear
	JOIN expensevar
		ON expenseyear.idexp = expensevar.idexp
	JOIN expense
		ON expenseyear.idexp = expense.idexp
	JOIN expensetotal
		ON  expenseyear.idexp = expensetotal.idexp
		AND expenseyear.ayear = expensetotal.ayear
	JOIN upb U 
		ON expenseyear.idupb = U.idupb	
	JOIN upbsorting US
		ON U.idupb = US.idupb	
	join sorting S
		ON S.idsor = US.idsor		
	JOIN upbsorting US_CdR
		ON U.idupb = US_CdR.idupb	
	join sorting S_CdR
		ON US_CdR.idsor = S_CdR.idsor	
	WHERE expensevar.adate <= @date
		AND expense.nphase = @fin_phase
		AND expensevar.yvar = @ayear
		AND ((expensetotal.flag&1)= 0) -- Competenza
		AND (@idfin IS NULL OR FLK.idparent = @idfin)
		AND (U.idupb like @idupb and U.active = 'S')
		AND  F.nlevel = @nlevel
		and S.idsorkind = @idsorkind
		AND S_CdR.idsorkind = @idsorkind_cdr
		AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
		AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
		AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
		AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
		AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)		 		
	GROUP BY  U.idupb, US.idsor, US_CdR.idsor, F.idfin,  F.nlevel,ISNULL(U.assured,'N')
		
	INSERT INTO #situation_fin(
		idfin, nlevel,
		idupb,
		idsor,
		idsor_cdr,
		assured,
		fin_ph_resid
	)
	SELECT 
		F.idfin, F.nlevel,
		 U.idupb,
		 US.idsor,
		 US_CdR.idsor,
		ISNULL(U.assured,'N'),
		SUM(isnull(expenseyear.amount,0)*isnull(US.quota,0))
	FROM fin F
	JOIN finlink FLK
		ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
	JOIN finlink FLK2
		ON FLK2.idparent = F.idfin 
	JOIN expenseyear
		ON ISNULL(FLK2.idchild,F.idfin) = expenseyear.idfin
		AND expenseyear.ayear = @ayear
	JOIN expense
		ON expenseyear.idexp = expense.idexp
	JOIN expensetotal
		ON  expenseyear.idexp = expensetotal.idexp
		AND expenseyear.ayear = expensetotal.ayear
	JOIN upb U 
		ON expenseyear.idupb = U.idupb
	JOIN upbsorting US
		ON U.idupb = US.idupb	
	join sorting S
		ON S.idsor = US.idsor		
	JOIN upbsorting US_CdR
		ON U.idupb = US_CdR.idupb	
	join sorting S_CdR
		ON US_CdR.idsor = S_CdR.idsor	
	WHERE expense.adate <= @date
		AND expense.nphase = @fin_phase
		AND ((expensetotal.flag&1)<> 0) -- R
		AND (@idfin IS NULL OR FLK.idparent = @idfin)
		AND (U.idupb like @idupb and U.active = 'S')
		AND  F.nlevel = @nlevel
		and S.idsorkind = @idsorkind
		AND S_CdR.idsorkind = @idsorkind_cdr
		AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
		AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
		AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
		AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
		AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
	GROUP BY  U.idupb, US.idsor, US_CdR.idsor, F.idfin, F.nlevel, ISNULL(U.assured,'N')
	INSERT INTO #situation_fin(
		idfin, nlevel,
		idupb,
		idsor,
		idsor_cdr,
		assured,
		var_fin_ph_resid
	)
	SELECT 
		F.idfin, F.nlevel,
		 U.idupb,
		 US.idsor,
		 US_CdR.idsor,
		ISNULL(U.assured,'N'),
		SUM(isnull(expensevar.amount,0)*isnull(US.quota,0))
	FROM fin F
	JOIN finlink FLK
		ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
	JOIN finlink FLK2
		ON FLK2.idparent = F.idfin 
	JOIN expenseyear
		ON ISNULL(FLK2.idchild,F.idfin) = expenseyear.idfin
		AND expenseyear.ayear = @ayear
	JOIN expensevar
		ON expenseyear.idexp = expensevar.idexp
	JOIN expense
		ON expenseyear.idexp = expense.idexp
	JOIN expensetotal
		ON  expenseyear.idexp = expensetotal.idexp
		AND expenseyear.ayear = expensetotal.ayear
	JOIN upb U 
		ON expenseyear.idupb = U.idupb
	JOIN upbsorting US
		ON U.idupb = US.idupb	
	join sorting S
		ON S.idsor = US.idsor	
	JOIN upbsorting US_CdR
		ON U.idupb = US_CdR.idupb	
	join sorting S_CdR
		ON US_CdR.idsor = S_CdR.idsor	
	WHERE expensevar.adate<= @date
		AND expense.nphase = @fin_phase
		AND expensevar.yvar = @ayear
		AND ((expensetotal.flag&1)<> 0) -- R
		AND (@idfin IS NULL OR FLK.idparent = @idfin)
		AND (U.idupb like @idupb and U.active = 'S')
		AND F.nlevel = @nlevel
		and S.idsorkind = @idsorkind
		AND S_CdR.idsorkind = @idsorkind_cdr
		AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
		AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
		AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
		AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
		AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)		 		
	GROUP BY  U.idupb, US.idsor,US_CdR.idsor,  F.idfin, F.nlevel, ISNULL(U.assured,'N')
		

	-- GESTIONE FONDO ECONOMALE	
	INSERT INTO #situation_fin(
		idfin, nlevel,
		idupb,
		idsor,
		idsor_cdr,
		assured,
		fin_ph_comp
	)
	SELECT 
		F.idfin, F.nlevel,
		U.idupb,
		US.idsor,
		US_CdR.idsor,
		ISNULL(U.assured,'N'),
		SUM(isnull(operation.amount,0)*isnull(US.quota,0))
	FROM fin F
	JOIN finlink FLK
		ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
	JOIN finlink FLK2
		ON FLK2.idparent = F.idfin 
	JOIN pettycashoperation operation
		ON ISNULL(FLK2.idchild,F.idfin) = operation.idfin
	JOIN upb U 
		ON operation.idupb = U.idupb
	JOIN upbsorting US
		ON U.idupb = US.idupb	
	join sorting S
		ON S.idsor = US.idsor		
	JOIN upbsorting US_CdR
		ON U.idupb = US_CdR.idupb	
	join sorting S_CdR
		ON US_CdR.idsor = S_CdR.idsor	
		
	WHERE  operation.adate <= @date
		AND operation.yoperation = @ayear
		AND (@idfin IS NULL OR FLK.idparent = @idfin)
		AND (U.idupb like @idupb and U.active = 'S')
		AND F.nlevel = @nlevel
		and S.idsorkind = @idsorkind
		AND S_CdR.idsorkind = @idsorkind_cdr	
		AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
		AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
		AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
		AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
		AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
		AND NOT EXISTS (SELECT * FROM pettycashoperation  
			WHERE pettycashoperation.idpettycash = operation.idpettycash
			AND pettycashoperation.yoperation = operation.yrestore
			AND pettycashoperation.noperation = operation.nrestore
			AND pettycashoperation.adate <= @date
			AND pettycashoperation.yoperation = @ayear)
	GROUP BY  U.idupb, US.idsor,US_CdR.idsor,  F.idfin, F.nlevel, ISNULL(U.assured,'N')
			
	INSERT INTO #situation_fin(
		idfin, nlevel,
		idupb,
		idsor,
		idsor_cdr,
		assured,
		max_ph_comp
	)
	SELECT 
		F.idfin, F.nlevel,
		 U.idupb,
		 US.idsor,
		 US_CdR.idsor,
		ISNULL(U.assured,'N'),
		SUM(isnull(HPV.amount,0)*isnull(US.quota,0))
	FROM fin F
	JOIN finlink FLK
		ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
	JOIN finlink FLK2
		ON FLK2.idparent = F.idfin 
	JOIN historypaymentview HPV
		ON ISNULL(FLK2.idchild,F.idfin) = HPV.idfin
	JOIN upb U 
		ON HPV.idupb = U.idupb
	JOIN upbsorting US
		ON U.idupb = US.idupb	
	join sorting S
		ON S.idsor = US.idsor	
	JOIN upbsorting US_CdR
		ON U.idupb = US_CdR.idupb	
	join sorting S_CdR
		ON US_CdR.idsor = S_CdR.idsor	
			
	WHERE  HPV.ymov = @ayear
		AND HPV.competencydate <= @date
		AND ((HPV.totflag&1) = 0) -- Competenza
		AND (U.idupb like @idupb and U.active = 'S') 
		AND (@idfin IS NULL OR FLK.idparent = @idfin)
		AND F.nlevel = @nlevel
		and S.idsorkind = @idsorkind
		AND S_CdR.idsorkind = @idsorkind_cdr	
		AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
		AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
		AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
		AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
		AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
	GROUP BY  U.idupb, US.idsor,US_CdR.idsor,  F.idfin, F.nlevel, ISNULL(U.assured,'N')
	INSERT INTO #situation_fin(
		idfin, nlevel,
		idupb,
		idsor,
		idsor_cdr,
		assured,
		max_ph_resid
	)
	SELECT 
		F.idfin, F.nlevel,
		 U.idupb,
		 US.idsor,
		 US_CdR.idsor,
		ISNULL(U.assured,'N'),
		SUM(isnull(HPV.amount,0)*isnull(US.quota,0))
	FROM fin F
	JOIN finlink FLK
		ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
	JOIN finlink FLK2
		ON FLK2.idparent = F.idfin 
	JOIN historypaymentview HPV
		ON ISNULL(FLK2.idchild,F.idfin) = HPV.idfin
	JOIN upb U 
		ON HPV.idupb = U.idupb
	JOIN upbsorting US
		ON U.idupb = US.idupb	
	join sorting S
		ON S.idsor = US.idsor		
	JOIN upbsorting US_CdR
		ON U.idupb = US_CdR.idupb	
	join sorting S_CdR
		ON US_CdR.idsor = S_CdR.idsor	
		
	WHERE  HPV.ymov = @ayear
		AND HPV.competencydate <= @date
		AND ((HPV.totflag&1) <> 0) -- R
		AND (U.idupb like @idupb and U.active = 'S')
		AND (@idfin IS NULL OR FLK.idparent = @idfin)
		AND F.nlevel = @nlevel
		and S.idsorkind = @idsorkind
		AND S_CdR.idsorkind = @idsorkind_cdr	
		AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
		AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
		AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
		AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
		AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
	GROUP BY  U.idupb, US.idsor, US_CdR.idsor, F.idfin, F.nlevel, ISNULL(U.assured,'N')
	IF @cashvaliditykind <> 4
	BEGIN
				INSERT INTO #situation_fin(
					idfin, nlevel,
					idupb,
					idsor,
					idsor_cdr,
					assured,
					var_max_ph_comp
				)
				SELECT 
					F.idfin, F.nlevel,
					 U.idupb,
					 US.idsor,
					 US_CdR.idsor,
					ISNULL(U.assured,'N'),
					SUM(isnull(expensevar.amount,0)*isnull(US.quota,0))
				FROM fin F
				JOIN finlink FLK
					ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
				JOIN finlink FLK2
					ON FLK2.idparent = F.idfin 
				JOIN historypaymentview HPV
					ON ISNULL(FLK2.idchild,F.idfin) = HPV.idfin
				JOIN expensevar
					ON HPV.idexp = expensevar.idexp
				JOIN upb U 
					ON HPV.idupb = U.idupb
				JOIN upbsorting US
					ON U.idupb = US.idupb	
				join sorting S
					ON S.idsor = US.idsor	
				JOIN upbsorting US_CdR
					ON U.idupb = US_CdR.idupb	
				join sorting S_CdR
					ON US_CdR.idsor = S_CdR.idsor	
				WHERE expensevar.yvar = @ayear
					AND HPV.ymov = @ayear
					AND ((HPV.totflag&1) = 0) -- Competenza
					AND HPV.competencydate <= @date
					AND expensevar.adate <= @date
					AND (@idfin IS NULL OR FLK.idparent = @idfin)
					AND (U.idupb like @idupb and U.active = 'S')
					AND F.nlevel = @nlevel
					and S.idsorkind = @idsorkind
					AND S_CdR.idsorkind = @idsorkind_cdr	
					AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
					AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
					AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
					AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
					AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
				GROUP BY  U.idupb, US.idsor,US_CdR.idsor,  F.idfin,  F.nlevel,ISNULL(U.assured,'N')
				
				INSERT INTO #situation_fin(
					idfin, nlevel,
					idupb,
					idsor,
					idsor_cdr,
					assured,
					var_max_ph_resid
				)
				SELECT 
					F.idfin, F.nlevel,
					 U.idupb,
					 US.idsor,
					 US_CdR.idsor,
					ISNULL(U.assured,'N'),
					SUM(isnull(expensevar.amount,0)*isnull(US.quota,0))
				FROM fin F
				JOIN finlink FLK
					ON FLK.idchild = F.idfin AND FLK.nlevel = @level_input
				JOIN finlink FLK2
					ON FLK2.idparent = F.idfin 
				JOIN historypaymentview HPV
					ON ISNULL(FLK2.idchild,F.idfin) = HPV.idfin
				JOIN expensevar
					ON HPV.idexp = expensevar.idexp
				JOIN upb U 
					ON HPV.idupb = U.idupb
				JOIN upbsorting US
					ON U.idupb = US.idupb	
				join sorting S
					ON S.idsor = US.idsor		
				JOIN upbsorting US_CdR
					ON U.idupb = US_CdR.idupb	
				join sorting S_CdR
					ON US_CdR.idsor = S_CdR.idsor	
				WHERE expensevar.yvar = @ayear
					AND HPV.ymov = @ayear
					AND ((HPV.totflag&1) <> 0) -- R
					AND HPV.competencydate <= @date
					AND expensevar.adate <= @date
