if object_id('rpt_unified_ivaadjustment_riep') is not null
	drop PROCEDURE rpt_unified_ivaadjustment_riep
go

CREATE     PROCEDURE rpt_unified_ivaadjustment_riep
(
	@ayear int
)
AS BEGIN
	-- rpt_unified_ivaadjustment_riep 2011
		
	CREATE TABLE #outtable
	(
        departmentname varchar(500),
		ayear int,
		prorata_rate_provv decimal(19,6),
		prorata_rate decimal(19,6),
		saldo_iniziale decimal(19,2),
		kind char(1),
		flagcurrent char(1),
		flagintracom char(1),
		idivakind varchar(20),
	    ivakinddescr varchar(50),
		rate decimal(19,6),
		flagdeferred char(1),
		unabatabilitypercentage decimal(19,6),
		taxabletotal_imm decimal(19,2), -- Imponibile (dei documenti immediati)
		ivatotal_imm decimal(19,2), -- Iva Totale dei documenti immediati
		ivaunabatable_imm decimal(19,2), -- IVA Indetraibile (dei documenti immediati)
		ivaabatable_imm decimal(19,2), -- IVA Detraibile (dei documenti immediati)
		ivaunabatable_defin_imm decimal(19,2), -- IVA Indetraibile prorata definitivo (dei documenti immediati)
		ivaabatable_defin_imm decimal(19,2),   -- IVA Detraibile prorata definitivo (dei documenti immediati)
		
		-- DIFFERITE DIVENUTE IMMEDIATE REGISTRATE IN ESERCIZIO CORRENTE
		taxabletotal_dif_current decimal(19,2), -- Imponibile (dei documenti differiti divenuti immediati)
		ivatotal_dif_current decimal(19,2), -- Iva Totale dei documenti differiti divenuti immediati
		ivaunabatable_dif_current decimal(19,2), -- IVA Indetrabile (dei documenti differiti divenuti immediati)
		ivaabatable_dif_current decimal(19,2), -- IVA Detraibile (dei documenti differiti divenuti immediati)
		ivaunabatable_defin_dif_current decimal(19,2), -- IVA Indetraibile prorata definitivo (dei documenti differiti divenuti immediati)
		ivaabatable_defin_dif_current decimal(19,2),   -- IVA Detraibile prorata definitivo (dei documenti differiti divenuti immediati)
		
		-- DIFFERITE DIVENUTE IMMEDIATE REGISTRATE IN ESERCIZI PRECEDENTI
		taxabletotal_dif_prec decimal(19,2), -- Imponibile (dei documenti differiti divenuti immediati)
		ivatotal_dif_prec decimal(19,2), -- Iva Totale dei documenti differiti divenuti immediati
		ivaunabatable_dif_prec decimal(19,2), -- IVA Indetrabile (dei documenti differiti divenuti immediati)
		ivaabatable_dif_prec decimal(19,2), -- IVA Detraibile (dei documenti differiti divenuti immediati)
		ivaunabatable_defin_dif_prec decimal(19,2), -- IVA Indetraibile prorata definitivo (dei documenti differiti divenuti immediati)
		ivaabatable_defin_dif_prec decimal(19,2),   -- IVA Detraibile prorata definitivo (dei documenti differiti divenuti immediati)
	
		)
	declare @iddbdepartment varchar(50)
	declare @crsdepartment cursor
	set 	@crsdepartment = cursor for select  iddbdepartment from dbdepartment
	where   (start is null or start <= @ayear ) AND (stop is null or stop >= @ayear)
	open 	@crsdepartment
	fetch next from @crsdepartment into @iddbdepartment
	while @@fetch_status=0 begin
		declare @dip_nomesp varchar(300)
		set @dip_nomesp = @iddbdepartment + '.rpt_ivaadjustment'
		insert into #outtable 
			(
                    departmentname,
					ayear,
					prorata_rate_provv,
					prorata_rate,
					saldo_iniziale,
					kind,
					flagdeferred,
					flagcurrent,
					flagintracom,
					idivakind,
					ivakinddescr,
					rate,
					unabatabilitypercentage,
					taxabletotal_imm, -- Imponibile (dei documenti immediati)
					ivatotal_imm, -- Iva Totale dei documenti immediati
					ivaunabatable_imm, -- IVA Indetraibile (dei documenti immediati)
					ivaabatable_imm, -- IVA Detraibile (dei documenti immediati)
					ivaunabatable_defin_imm, -- IVA Indetraibile prorata definitivo (dei documenti immediati)
					ivaabatable_defin_imm,   -- IVA Detraibile prorata definitivo (dei documenti immediati)
					
					taxabletotal_dif_current, -- Imponibile (dei documenti differiti divenuti immediati)
					ivatotal_dif_current, -- Iva Totale dei documenti differiti divenuti immediati
					ivaunabatable_dif_current, -- IVA Indetrabile (dei documenti differiti divenuti immediati)
					ivaabatable_dif_current, -- IVA Detraibile (dei documenti differiti divenuti immediati)
					ivaunabatable_defin_dif_current, -- IVA Indetraibile prorata definitivo (dei documenti differiti divenuti immediati)
					ivaabatable_defin_dif_current,   -- IVA Detraibile prorata definitivo (dei documenti differiti divenuti immediati)
			
					taxabletotal_dif_prec, -- Imponibile (dei documenti differiti divenuti immediati)
					ivatotal_dif_prec, -- Iva Totale dei documenti differiti divenuti immediati
					ivaunabatable_dif_prec, -- IVA Indetrabile (dei documenti differiti divenuti immediati)
					ivaabatable_dif_prec, -- IVA Detraibile (dei documenti differiti divenuti immediati)
					ivaunabatable_defin_dif_prec, -- IVA Indetraibile prorata definitivo (dei documenti differiti divenuti immediati)
					ivaabatable_defin_dif_prec--,   -- IVA Detraibile prorata definitivo (dei documenti differiti divenuti immediati)
			)
			exec @dip_nomesp  @ayear
			
		fetch next from @crsdepartment into @iddbdepartment
	END
	
		SELECT 
					null as departmentname,
					ayear,
					prorata_rate_provv,
					prorata_rate,
					saldo_iniziale,
					kind,
					flagdeferred,
					flagcurrent,
					flagintracom,
					idivakind,
					ivakinddescr,
					rate,
					unabatabilitypercentage,
					SUM(ISNULL(taxabletotal_imm,0)) AS taxabletotal_imm, -- Imponibile (dei documenti immediati)
					SUM(ISNULL(ivatotal_imm,0)) AS ivatotal_imm, -- Iva Totale dei documenti immediati
					SUM(ISNULL(ivaunabatable_imm,0)) AS ivaunabatable_imm, -- IVA Indetraibile (dei documenti immediati)
					SUM(ISNULL(ivaabatable_imm,0)) AS ivaabatable_imm, -- IVA Detraibile (dei documenti immediati)
					SUM(ISNULL(ivaunabatable_defin_imm,0)) AS ivaunabatable_defin_imm, -- IVA Indetraibile prorata definitivo (dei documenti immediati)
					SUM(ISNULL(ivaabatable_defin_imm,0)) AS ivaabatable_defin_imm,   -- IVA Detraibile prorata definitivo (dei documenti immediati)
					-- DIFFERITE DIVENUTE IMMEDIATE REGISTRATE IN ESERCIZIO CORRENTE
					SUM(ISNULL(taxabletotal_dif_current,0)) AS taxabletotal_dif_current, -- Imponibile (dei documenti differiti divenuti immediati)
					SUM(ISNULL(ivatotal_dif_current,0)) AS ivatotal_dif_current, -- Iva Totale dei documenti differiti divenuti immediati
					SUM(ISNULL(ivaunabatable_dif_current,0)) AS ivaunabatable_dif_current, -- IVA Indetrabile (dei documenti differiti divenuti immediati)
					SUM(ISNULL(ivaabatable_dif_current,0)) AS ivaabatable_dif_current, -- IVA Detraibile (dei documenti differiti divenuti immediati)
					SUM(ISNULL(ivaunabatable_defin_dif_current,0)) AS ivaunabatable_defin_dif_current, -- IVA Indetraibile prorata definitivo (dei documenti differiti divenuti immediati)
					SUM(ISNULL(ivaabatable_defin_dif_current,0)) AS ivaabatable_defin_dif_current,   -- IVA Detraibile prorata definitivo (dei documenti differiti divenuti immediati)
					-- DIFFERITE DIVENUTE IMMEDIATE REGISTRATE IN ESERCIZI PRECEDENTI
					SUM(ISNULL(taxabletotal_dif_prec,0)) AS taxabletotal_dif_prec, -- Imponibile (dei documenti differiti divenuti immediati)
					SUM(ISNULL(ivatotal_dif_prec,0)) AS ivatotal_dif_prec, -- Iva Totale dei documenti differiti divenuti immediati
					SUM(ISNULL(ivaunabatable_dif_prec,0)) AS ivaunabatable_dif_prec, -- IVA Indetrabile (dei documenti differiti divenuti immediati)
					SUM(ISNULL(ivaabatable_dif_prec,0)) AS ivaabatable_dif_prec, -- IVA Detraibile (dei documenti differiti divenuti immediati)
					SUM(ISNULL(ivaunabatable_defin_dif_prec,0)) AS ivaunabatable_defin_dif_prec, -- IVA Indetraibile prorata definitivo (dei documenti differiti divenuti immediati)
					SUM(ISNULL(ivaabatable_defin_dif_prec,0)) AS ivaabatable_defin_dif_prec --,   -- IVA Detraibile prorata definitivo (dei documenti differiti divenuti immediati)
					FROM #outtable
					GROUP BY 		ayear,
					kind, flagdeferred,
					flagcurrent,flagintracom,
					saldo_iniziale,
					idivakind,
					ivakinddescr,
					rate,
					unabatabilitypercentage,
					prorata_rate_provv,
					prorata_rate
					order by kind desc, rate asc
END

GO

print 'rpt_unified_ivaadjustment_riep OK'

GO
if object_id('esporta_cespiti_non_in_buono') is not null
	drop PROCEDURE esporta_cespiti_non_in_buono
go



CREATE        PROCEDURE esporta_cespiti_non_in_buono
AS BEGIN
SELECT AQ.nassetacquire as 'Num. carico cespite', AQ.description as 'Descrizione', 
	AQ.startnumber as 'Num. Inv. Iniziale',AQ.number as 'Quantità', I.codeinventory as 'Codice Inventario'
	FROM assetacquire AQ 
	JOIN inventory I
		ON I.idinventory = AQ.idinventory
WHERE 	AQ.idassetload IS NULL
	AND AQ.flag & 1 !=0
ORDER BY AQ.nassetacquire
END




GO

print 'esporta_cespiti_non_in_buono OK'

GO
if object_id('[exp_invoice_intrastat]') is not null
	drop PROCEDURE [exp_invoice_intrastat]
go
CREATE    PROCEDURE [exp_invoice_intrastat] (
-- A seconda della periodicità ossia T o M, si dovrà indicare il periodo di riferimento
	@anno int,
	@mese int, 
	@trimestre int,
	@tipoRiepilogo char(1),	-- A = acquisti, C = cessioni
	@periodicita char(1),	-- M = dichiarazione Mensile, T = dichiarazione Trimestrale, A = dichiarazione Annuale >> NON PIU' DISPONIBILE
	@tipoRecord char(1)		-- B -->Beni, S -->Servizi, T -- >Beni e Servizi
)
AS
BEGIN
CREATE TABLE #Dettaglio1_BENI
(	
	idreg int,
	kind char(1),
	flagvariation char(1),
	annorif int,
	meserif int,
	trimrif int,
	segno_variazione char(1),
	is_variation char(1),
	flagpaired char(1),
	idinvkind int,						-- tipo fattura
	yinv int,							-- anno fattura
	ninv int,							-- numero fattura	
	rownum int,							-- dettaglio fattura
	numerofattura varchar(15),			-- Numero Protocollo Fattura (Registro)
	datafattura varchar(6),				-- Data fattura formato (ggmmaa)
	codiceIVA varchar(14),				-- Codice dello Stato membro dell'acquirente/fornitore+  Codice IVA dell'acquitente /fornitore =il numero di partita iva del soggetto passivo d’imposta con il quale è stata effettuata 
										-- L’operazione intracomunitaria
	ammontareinEuro int,				-- numerico Len.13 -- Ammontare delle operazioni in euro
	ammontareinValuta int,				-- numerico Len.13 -- Ammontare delle operazioni in valuta
	codTransazione char(1),				-- Codice della natura dela transazione
	codNomenclatura varchar(8),			-- numerico -- codice della nomenclatuta combinata della merce (solo nel caso di elenchi trimestrali)
	massainkg int,						-- numerico Len. 10 -- Massa netta in kilogrammi
	unitasupp int,						-- numerico Len. 10 -- Unità supplementari per l'acquisto / Quantità espressa nell'unità di misura supplementare
	codDest_codProv char(2),			-- Codice del paese di destinazione/provenienza
	codOrigineMerce char(2),			-- Codice del paese di origine della merce
	provOrigine_Dest char (2)			-- Codice della provincia di origine/destinazione della merce	
)
CREATE TABLE #Dettaglio3_SERVIZI
(	
	idreg int,
	kind char(1),
	flagvariation char(1),
	annorif int,
	meserif int,
	trimrif int,	
	segno_variazione char(1),
	is_variation char(1),
	flagpaired char(1),
	codiceIVA varchar(14),				--  Codice dello Stato membro dell'acquirente/fornitore+  Codice IVA dell'acquitente /fornitore =il numero di partita iva del soggetto passivo d’imposta con il quale è stata effettuata 
										--	l’operazione intracomunitaria
	ammontareinEuro int,				-- numerico Len.13 -- Ammontare delle operazioni in euro
	ammontareinValuta int,				-- numerico Len.13 -- Ammontare delle operazioni in valuta > > >  SOLO per i Servizi ricevuti
	idinvkind int,						-- tipo fattura
	yinv int,							-- anno fattura
	ninv int,							-- numero fattura	
	rownum int,					
	numerofattura varchar(15),			-- Numero Protocollo Fattura (Registro)
	datafattura varchar(6),				-- Data fattura formato (ggmmaa)
	codServizio varchar(6),				-- numerico -- Codice del Servizio
	modErogazione char(1),				-- Modalità di erogazione
	modpagamento char(1),				-- Modalità pagamento/incasso 
	codPaesePagamento char(2)			-- Codice del paese di Pagamento
)

DECLARE @lencodNomenclatura int
SET @lencodNomenclatura = 8
DECLARE @lenCodServizi int
SET @lenCodServizi = 6
DECLARE @lenNumFattura int
SET @lenNumFattura = 15
DECLARE @lenweight int
SET @lenweight = 10
DECLARE @lenCodiceIVA int
SET @lenCodiceIVA = 14 -- codice stato membro 2 + p iva 12 = 14
DECLARE @lenunitasupp int 
SET @lenunitasupp = 10
DECLARE @lenanno INT
SET @lenanno = 2
DECLARE @lenmese INT
SET @lenmese = 2
DECLARE @lenday INT
SET @lenday = 2
DECLARE @meseinizio int
DECLARE @mesefine int
DECLARE @idcurrency int
SELECT @idcurrency = idcurrency FROM currency WHERE codecurrency='EUR'
IF (@periodicita = 'T')
begin
	SELECT 
		@meseinizio= (@trimestre-1)*3+1,
		@mesefine = @trimestre*3
end
ELSE 
begin
	SELECT 
		@meseinizio= @mese ,
		@mesefine = @mese
end
declare @flag_A char(1)
declare @flag_V char(1)
declare @flagAV char(1)
if (@tipoRiepilogo = 'C') --VENDITA
BEGIN
 SET @flag_A = 'Q' -- non ci deve essere la riga
 SET  @flag_V = 'V'  -- flag & 1   = 1 se è una vendita
 SET @flagAV = 'V'
END
ELSE  -- ACQUISTO
BEGIN
 SET @flag_A = 'A'    -- flag & 1 = 0 se è un'acquisto
 SET @flag_V = 'Q'	--(non importa)
 SET @flagAV = 'A'
END
-- la condizione è isnull(flag_reg_acquisto , 'Q') = @flag_A  AND (@flag_v = 'Q' OR (flag_reg_vendita  =@flag_v)
-- caso vendita:  isnull(flag_reg_acquisto , 'Q') = 'Q' AND flag_reg_vendita = 'V'
-- caso acquisto:  flag_reg_acquisto  = 'A'     

INSERT INTO #Dettaglio1_BENI
(
	idreg ,
	annorif ,
	meserif ,
	kind,
	flagvariation,
	codiceIVA, 				-- codicestatomembro= Codice dello Stato membro dell'acquirente/fornitore + Codice IVA dell'acquitente /fornitore = DE123456788
	ammontareinEuro,		-- numerico -- Ammontare delle operazioni in euro
	ammontareinValuta,		-- numerico -- Ammontare delle operazioni in valuta
	idinvkind,				-- tipo fattura
	yinv,					-- anno fattura
	ninv,					-- numero fattura
	rownum,					-- dettaglio fattura 
	numerofattura ,			-- Numero Protocollo Fattura
	datafattura ,			-- Data fattura formato (ggmmaa)
	codTransazione,			-- Codice della natura dela transazione
	codNomenclatura,		-- numerico -- codice della nomenclatuta combinata della merce (solo nel caso di elenchi trimestrali)
	massainkg,				-- numerico -- Massa netta in kilogrammi
	unitasupp,				-- numerico -- Unità supplementari per l'acquisto / Quantità espressa nell'unità di misura supplementare
	codDest_codProv,		-- Codice del paese di destinazione/provenienza
	codOrigineMerce,		-- Codice del paese di origine della merce
	provOrigine_Dest		-- Codice della provincia di origine/destinazione della merce	
)
SELECT
	I.idreg,
	ISNULL(YEAR(I_MAIN.adate),YEAR(I.adate)),
	ISNULL(MONTH(I_MAIN.adate),MONTH(I.adate)),
	CASE WHEN (IK.flag & 1)=0 THEN 'A'    ELSE 'V'	END,  --kind (A/V) ossia SPESA/ENTRATA
	CASE	WHEN (IK.flag & 4) = 0 THEN 'N'		ELSE 'S'	END,  --flagvariation
	UPPER( isnull(R.p_iva,'')+ SUBSTRING(replicate(' ',@lenCodiceIVA), 1, @lenCodiceIVA - DATALENGTH(isnull(R.p_iva,''))) ),
	--	ammontareinEuro,	
			ROUND(InvDet.taxable * InvDet.npackage * CONVERT(decimal(19,6),I.exchangerate) *
				(1 - CONVERT(decimal(19,6),ISNULL(InvDet.discount, 0.0)))
			,2),
	--	ammontareinValuta,	
	CASE WHEN I.idcurrency <> @idcurrency
	THEN
			ROUND(InvDet.taxable * InvDet.npackage * (1 - CONVERT(decimal(19,6),ISNULL(InvDet.discount, 0.0)))
			,2)
	ELSE 0
	END,
	I.idinvkind,
	I.yinv,
	I.ninv,	
	InvDet.rownum,
	-- Numero Fattura
	SUBSTRING(REPLICATE('0',@lenNumFattura),1,@lenNumFattura - DATALENGTH(ISNULL(convert(varchar(15),IR.protocolnum),''))) + ISNULL(convert(varchar(15),IR.protocolnum),''),
	--IR.protocolnum + SUBSTRING(SPACE(@lenNumFattura),1,@lenNumFattura - DATALENGTH(IR.protocolnum)),
	-- Data fattura formato (ggmmaa)
		 SUBSTRING(REPLICATE('0',@lenday),1, @lenday - DATALENGTH(CONVERT(varchar(2),DAY(I.adate)))) + CONVERT(varchar(2),DAY(I.adate))
		+ SUBSTRING(REPLICATE('0',@lenmese),1, @lenmese - DATALENGTH(CONVERT(varchar(2),MONTH(I.adate)))) + CONVERT(varchar(2),MONTH(I.adate))
		+ SUBSTRING(CONVERT(varchar(4),YEAR(I.adate)),3,2),
	K.idintrastatkind,	-- codTransazione			
	-- codNomenclatura	-> intrastatcode
	case 
		when @periodicita IN ('M','T') then SUBSTRING(REPLICATE('0',@lencodNomenclatura),1,@lencodNomenclatura - DATALENGTH(ISNULL(C.code,''))) + ISNULL(C.code,'')
		else REPLICATE('0',@lencodNomenclatura)
	end,
	Case
		When InvDet.idintrastatmeasure is not null THEN ROUND(ISNULL(InvDet.weight,0),0)
		Else ROUND (InvDet.npackage,0)
	End,			
	-- Unitasupp -> solo la quantità
	Case 
		When InvDet.idintrastatmeasure is not null THEN		ROUND (InvDet.npackage,0)
		Else 0
	End,
	--codDest_codProv,		
	case 
		when @tipoRiepilogo ='A' then Prov.idintrastatnation
		else Dest.idintrastatnation
	end,
	-- codOrigineMerce,		
	case 
		when @tipoRiepilogo ='A' then Orig.idintrastatnation
		else REPLICATE(' ',2)
	end,
	-- provOrigine_Dest				
	case 
		when @tipoRiepilogo ='A' then geo_country_destination.province
		else geo_country_origin.province
	end
FROM  invoice as I
JOIN registry as R
	ON R.idreg = I.idreg
JOIN invoicekind IK
	ON I.idinvkind = IK.idinvkind
JOIN intrastatkind as K
	ON I.idintrastatkind = K.idintrastatkind
JOIN invoicedetail as InvDet 
	ON I.idinvkind = InvDet.idinvkind AND I.yinv = InvDet.yinv AND I.ninv = InvDet.ninv
JOIN intrastatcode as C 
	ON C.idintrastatcode = InvDet.idintrastatcode
LEFT OUTER JOIN intrastatnation as Dest
	ON I.iso_destination = Dest.idintrastatnation
LEFT OUTER JOIN intrastatnation as Orig	
	ON I.iso_origin = Orig.idintrastatnation
LEFT OUTER JOIN intrastatnation as Prov
	ON I.iso_provenance = Prov.idintrastatnation
LEFT OUTER JOIN geo_country as geo_country_destination
	ON I.idcountry_destination = geo_country_destination.idcountry
LEFT OUTER JOIN geo_country as geo_country_origin
	ON I.idcountry_origin = geo_country_origin.idcountry
join  ivaregister IR
	ON IR.idinvkind=I.idinvkind
	AND IR.yinv = I.yinv
	AND IR.ninv = I.ninv
LEFT OUTER  JOIN 	invoicekindregisterkind IKR_A
	ON IKR_A.idinvkind= I.idinvkind
LEFT OUTER  JOIN 	ivaregisterkind IRK_A
	ON IRK_A.idivaregisterkind= IKR_A.idivaregisterkind AND IRK_A.registerclass='A'
LEFT OUTER  JOIN 	invoicekindregisterkind IKR_V
	ON IKR_V.idinvkind= I.idinvkind
LEFT OUTER  JOIN 	ivaregisterkind IRK_V
	ON IRK_V.idivaregisterkind= IKR_V.idivaregisterkind AND IRK_V.registerclass='V'
LEFT OUTER JOIN invoice I_MAIN
	ON I_MAIN.idinvkind=InvDet.idinvkind_main and I_MAIN.yinv=InvDet.yinv_main and I_MAIN.ninv=InvDet.ninv_main
WHERE I.flagintracom = 'S'
AND InvDet.intrastatoperationkind = 'B'-- >>> Beni
AND YEAR(I.adate) = @anno
AND MONTH(I.adate) between @meseinizio and @mesefine 	
AND isnull(IRK_A.registerclass , 'Q') = @flag_A  AND (@flag_v = 'Q' OR (IRK_V.registerclass =@flag_v))
AND I.idinvkind_real is null
--group by R.p_iva,I.idinvkind,I.yinv, I.ninv,I.idcurrency,K.idintrastatkind,C.code,InvDet.weight,InvDet.npackage,
--		Prov.idintrastatnation, Dest.idintrastatnation, Orig.idintrastatnation,geo_country_destination.province,geo_country_origin.province,
--		I.adate,I_MAIN.adate,IK.flag,IR.protocolnum
INSERT INTO #Dettaglio3_SERVIZI
(
	idreg,
	annorif ,
	meserif ,
	kind,
	flagvariation,
	codiceIVA ,					--  Codice dello Stato membro dell'acquirente/fornitore+  Codice IVA dell'acquitente /fornitore 
	ammontareinEuro ,			-- numerico Len.13 -- Ammontare delle operazioni in euro
	ammontareinValuta ,			-- numerico Len.13 -- Ammontare delle operazioni in valuta > > >  SOLO per i Servizi ricevuti
	idinvkind,					--
	yinv,
	ninv,
	rownum,						-- dettaglio fattura 
	numerofattura ,				-- Numero Fattura
	datafattura ,				-- Data fattura formato (ggmmaa)
	codServizio ,				-- numerico -- Codice del Servizio
	modErogazione ,				-- Modalità di erogazione
	modpagamento ,				-- Modalità pagamento/incasso 
	codPaesePagamento 			-- Codice del paese di Pagamento
)
SELECT 
	I.idreg,
	ISNULL(YEAR(I_MAIN.adate),YEAR(I.adate)),
	ISNULL(MONTH(I_MAIN.adate),MONTH(I.adate)),
	CASE WHEN (IK.flag & 1)=0 THEN 'A'    ELSE 'V'	END,  --kind (A/V) ossia SPESA/ENTRATA
	CASE	WHEN (IK.flag & 4) = 0 THEN 'N'		ELSE 'S'	END,  --flagvariation
	UPPER( isnull(R.p_iva,'')+ SUBSTRING(replicate(' ',@lenCodiceIVA), 1, @lenCodiceIVA - DATALENGTH(isnull(R.p_iva,''))) ),
--	ammontareinEuro,	
			ROUND(InvDet.taxable * InvDet.npackage * CONVERT(decimal(19,6),I.exchangerate) *
				(1 - CONVERT(decimal(19,6),ISNULL(InvDet.discount, 0.0)))
			,2),
--	ammontareinValuta,	
	CASE WHEN I.idcurrency <> @idcurrency
	THEN
		ROUND(InvDet.taxable * InvDet.npackage * (1 - CONVERT(decimal(19,6),ISNULL(InvDet.discount, 0.0))),2)
	ELSE 0
	END,
	I.idinvkind,
	I.yinv,
	I.ninv,	
	InvDet.rownum,
	-- Numero Protocollo Fattura
	SUBSTRING(REPLICATE('0',@lenNumFattura),1,@lenNumFattura - DATALENGTH(ISNULL(convert(varchar(15),IR.protocolnum),''))) + ISNULL(convert(varchar(15),IR.protocolnum),''),
	--IR.protocolnum + SUBSTRING(SPACE(@lenNumFattura),1,@lenNumFattura - DATALENGTH(IR.protocolnum)),
	-- Data fattura formato (ggmmaa)
		 SUBSTRING(REPLICATE('0',@lenday),1, @lenday - DATALENGTH(CONVERT(varchar(2),DAY(I.adate)))) + CONVERT(varchar(2),DAY(I.adate))
		+ SUBSTRING(REPLICATE('0',@lenmese),1, @lenmese - DATALENGTH(CONVERT(varchar(2),MONTH(I.adate)))) + CONVERT(varchar(2),MONTH(I.adate))
		+ SUBSTRING(CONVERT(varchar(4),YEAR(I.adate)),3,2),
	--  Codice del Servizio
	CONVERT(varchar(6),S.code),
	E.code,					-- Modalità di erogazione
	P.code ,				-- Modalità pagamento/incasso 
	Pag.idintrastatnation 	-- Codice del paese di Pagamento
FROM  invoice as I 
JOIN  registry as R
	ON R.idreg = I.idreg
JOIN invoicekind IK
	ON I.idinvkind = IK.idinvkind
JOIN invoicedetail as InvDet 
	ON I.idinvkind = InvDet.idinvkind AND I.yinv = InvDet.yinv AND I.ninv = InvDet.ninv
JOIN intrastatservice as S 
	ON S.idintrastatservice = InvDet.idintrastatservice
JOIN intrastatpaymethod as P 
	ON P.idintrastatpaymethod = I.idintrastatpaymethod
JOIN intrastatsupplymethod E 
	ON InvDet.idintrastatsupplymethod = E.idintrastatsupplymethod
JOIN intrastatnation as Pag	
	ON I.iso_payment = Pag.idintrastatnation
join  ivaregister IR
	ON IR.idinvkind=I.idinvkind
	AND IR.yinv = I.yinv
	AND IR.ninv = I.ninv
join ivaregisterkind IR_MAIN
	ON IR.idivaregisterkind = IR_MAIN.idivaregisterkind
LEFT OUTER  JOIN 	invoicekindregisterkind IKR_A
	ON IKR_A.idinvkind= I.idinvkind
LEFT OUTER  JOIN 	ivaregisterkind IRK_A
	ON IRK_A.idivaregisterkind= IKR_A.idivaregisterkind AND IRK_A.registerclass='A'
LEFT OUTER  JOIN 	invoicekindregisterkind IKR_V
	ON IKR_V.idinvkind= I.idinvkind
LEFT OUTER  JOIN 	ivaregisterkind IRK_V
	ON IRK_V.idivaregisterkind= IKR_V.idivaregisterkind AND IRK_V.registerclass='V'
LEFT OUTER JOIN invoice I_MAIN
	ON I_MAIN.idinvkind=InvDet.idinvkind_main and I_MAIN.yinv=InvDet.yinv_main and I_MAIN.ninv=InvDet.ninv_main
WHERE I.flagintracom = 'S'
AND InvDet.intrastatoperationkind = 'S'-- >>> Servizi
AND YEAR(I.adate) = @anno
AND MONTH(I.adate) between @meseinizio and @mesefine 	
AND isnull(IRK_A.registerclass , 'Q') = @flag_A  AND (@flag_v = 'Q' OR (IRK_V.registerclass =@flag_v))
AND I.idinvkind_real is null
AND IR_MAIN.registerclass = @flagAV
--group by R.p_iva,I.idinvkind,I.yinv, I.ninv,IK.flag,I.idcurrency,IR.protocolnum, I.adate, S.code, 
--	S.idintrastatservice, E.idintrastatsupplymethod, E.code, P.code,InvDet.npackage,	Pag.idintrastatnation,
--	I.adate,I_MAIN.adate,IK.flag
--calcola i trimestri
update #Dettaglio1_BENI set trimrif = ((meserif-1)/3)+1
update #Dettaglio3_SERVIZI set trimrif = ((meserif-1)/3)+1
--calcola is_variation
update #Dettaglio1_BENI set is_variation='N' where kind=@flagav AND flagvariation='N'
update #Dettaglio3_SERVIZI set is_variation='N' where kind=@flagav AND flagvariation='N'
update #Dettaglio1_BENI set is_variation='S' where kind<>@flagav OR flagvariation='S'
update #Dettaglio3_SERVIZI set is_variation='S' where kind<>@flagav OR flagvariation='S'
update #Dettaglio1_BENI set is_variation='N' where kind<>@flagav AND flagvariation='S'
update #Dettaglio3_SERVIZI set is_variation='N' where kind<>@flagav AND flagvariation='S'
--segna quali sono le fatture da compensare nel periodo stesso
update #Dettaglio1_BENI set flagpaired ='N'
update #Dettaglio1_BENI set flagpaired ='S' WHERE 
		flagvariation='S' AND 
		annorif=@anno and meserif between @meseinizio and @mesefine 
 
update #Dettaglio3_SERVIZI set flagpaired ='N'
update #Dettaglio3_SERVIZI set flagpaired ='S' WHERE  
		flagvariation='S' AND
		annorif=@anno and meserif between @meseinizio and @mesefine 
--aggiusta i segni negli importi NOI GESTIAMO SOLO VARIAZIONI NEGATIVE E MAI POSITIVE
update #Dettaglio1_BENI set  segno_variazione='-' where flagvariation='S' and flagpaired='N'
update #Dettaglio3_SERVIZI set segno_variazione='-' where flagvariation='S' and flagpaired='N'
update #Dettaglio1_BENI set  ammontareinEuro=-ammontareinEuro,ammontareinValuta=-ammontareinValuta
				 where flagvariation='S' and flagpaired='S'
update #Dettaglio3_SERVIZI set ammontareinEuro=-ammontareinEuro,ammontareinValuta=-ammontareinValuta
				 where flagvariation='S' and flagpaired='S'
 
--azzera annorif e meserif per tutte le righe tranne che per le variazioni non compensate
update #Dettaglio1_BENI set annorif=null, meserif=null,trimrif=null where flagvariation='N' or flagpaired='S'
update #Dettaglio3_SERVIZI set annorif=null, meserif=null,trimrif=null where flagvariation='N' or flagpaired='S'
--questo perché nella group by vanno raggruppate
--SELECT 'DETTAGLIO BENI', * FROM #Dettaglio1_BENI
--SELECT 'DETTAGLIO SERVIZI', * FROM #Dettaglio3_SERVIZI

IF(@tiporecord = 'B')
BEGIN
SELECT 
	'Beni' as 'Tipo',
	CASE @tipoRiepilogo
		WHEN 'A' THEN 'Acquisti'
		ELSE 'Cessioni'
	END as 'Tipo riep.',
	CASE @periodicita
		WHEN 'T' THEN 'Trimestrale'
		WHEN 'M' THEN 'Mensile'
	END as 'Periodicità',
	@anno as 'Anno',
	(SELECT title from monthname where code=@mese)
		as 'Mese Rif.',
	@trimestre as 'Trimestre Rif.',
	(SELECT title from monthname where code=MONTH(I.adate))
		as 'Mese Fattura',
	segno_variazione as 'Segno Var',
	R.title as 'Cliente/Fornitore',
	R.p_iva as 'P.Iva', 
	R.cf as 'Codice Fiscale',
	R.birthdate as 'Data Nasc.',
	IK.description as 'Tipo Doc. Iva', 
	I.yinv as 'Anno Fattura',
	I.ninv as 'Num. Fattura', 	
	InvDet.rownum as '# Dett.',
	IR.protocolnum as 'Num. Protocollo', 
	Curr.description as 'Valuta',
	CASE WHEN I.idcurrency <> @idcurrency
	THEN I.exchangerate
	ELSE null
	END  as 'Tasso Cambio',
	
	CONVERT(decimal(19,2), ROUND(InvDet.taxable * InvDet.npackage * 
			  CONVERT(DECIMAL(19,6),ISNULL(I.exchangerate,1)) *
			  (1 - CONVERT(DECIMAL(19,6),ISNULL(InvDet.discount, 0.0))),2
		))
	-- + CONVERT(decimal(19,2),ROUND(ISNULL(InvDet.tax,0),2))	
	as 'Ammont. In Euro',
	--	ammontareinValuta,	
	CASE WHEN I.idcurrency <> @idcurrency
	THEN
		CONVERT(decimal(19,2), ROUND(InvDet.taxable * InvDet.npackage * 
			  (1 - CONVERT(DECIMAL(19,6),ISNULL(InvDet.discount, 0.0))),2
		))
	ELSE 0
	END as 'Ammont. In Valuta',
	K.description as 'Natura Transazione',
	InvDet.code as 'Cod. Nomencl. Combinata',
	C.description as 'Nomencl. Combinata',
	InvDet.intrastatmeasure as 'Unità di Misura Suppl.',
	InvDet.weight as 'Peso in Kg',
	Orig.description as 'Paese Orig.',
	Prov.description as 'Paese Proven.',
	geo_country_destination.title as 'Provincia Destin.',
	Dest.description as 'Paese Destin.',
	geo_country_origin.title as 'Provincia Orig.',	
	null as 'Numero Fattura',				
	null as 'Data fattura formato (ggmmaa)',			
	Convert(varchar(6),intrastatservice.code) as 'Codice del Servizio', 	
	intrastatservice.description as 'Servizio',							
	intrastatsupplymethod.description as 'Modalità di erogazione',				
	null as 'Modalità pagamento/incasso',				
	null as 'Codice del paese di Pagamento', 			
	I.adate as 'Data Fattura',
	InvDet.detaildescription as 'Descr. Dettaglio',
	InvDet.taxable as 'Impon. Unitario',
	InvDet.npackage as 'Quantità',
	InvDet.discount as 'Sconto',
	InvDet.ivakind as 'Tipo Iva',
	InvDet.iva_euro as 'Iva',
	InvDet.unabatable_euro as 'Iva Indetr.',
	CASE  InvDet.va3type 
		WHEN 'S' THEN 'Beni Ammortizzabili'
		WHEN 'N' THEN 'Beni strumentali non ammortizzabili'
		WHEN 'R' THEN 'Beni destinati alla rivendita'
		WHEN 'A' THEN 'Altri acquisti e importazioni'
		ELSE 'Non specificato'
	END as 'Tipologia VF24'
FROM registry as R
JOIN #Dettaglio1_BENI as D
	ON R.idreg = D.idreg
JOIN invoicedetailview as InvDet 
	ON D.idinvkind = InvDet.idinvkind AND D.yinv = InvDet.yinv 
	AND D.ninv = InvDet.ninv  AND D.rownum = InvDet.rownum
JOIN invoice as I
	ON InvDet.idinvkind = I.idinvkind
	AND InvDet.yinv = I.yinv 
	AND InvDet.ninv = I.ninv 
JOIN invoicekind IK
	ON I.idinvkind = IK.idinvkind
join  ivaregister IR
	ON IR.idinvkind=I.idinvkind
	AND IR.yinv = I.yinv
	AND IR.ninv = I.ninv
JOIN ivaregisterkind IRK
	ON IRK.idivaregisterkind = IR.idivaregisterkind
LEFT OUTER JOIN intrastatservice
	ON InvDet.idintrastatservice = intrastatservice.idintrastatservice
LEFT OUTER JOIN intrastatsupplymethod
	ON InvDet.idintrastatsupplymethod = intrastatsupplymethod.idintrastatsupplymethod
LEFT OUTER JOIN intrastatkind as K
	ON I.idintrastatkind = K.idintrastatkind
LEFT OUTER JOIN intrastatcode as C 
	ON C.idintrastatcode = InvDet.idintrastatcode
LEFT OUTER JOIN currency as Curr 
	ON Curr.idcurrency = I.idcurrency
LEFT OUTER JOIN intrastatnation as Dest
	ON I.iso_destination = Dest.idintrastatnation
LEFT OUTER JOIN intrastatnation as Orig	
	ON I.iso_origin = Orig.idintrastatnation
LEFT OUTER JOIN intrastatnation as Prov
	ON I.iso_provenance = Prov.idintrastatnation
LEFT OUTER JOIN geo_country as geo_country_destination
	ON I.idcountry_destination = geo_country_destination.idcountry
LEFT OUTER JOIN geo_country as geo_country_origin
	ON I.idcountry_origin = geo_country_origin.idcountry
LEFT OUTER JOIN intrastatnation
	ON I.iso_payment = intrastatnation.idintrastatnation
LEFT OUTER JOIN intrastatpaymethod 
	ON I.idintrastatpaymethod = intrastatpaymethod.idintrastatpaymethod
ORDER BY MONTH(D.meserif), I.idinvkind, I.yinv, I.ninv, InvDet.rownum
END
IF(@tiporecord = 'S')
BEGIN
SELECT 
	'Serv.' as 'Tipo',
	CASE @tipoRiepilogo
		WHEN 'A' THEN 'Acquisti'
		ELSE 'Cessioni'
	END as 'Tipo riep.',
	CASE @periodicita
		WHEN 'T' THEN 'Trimestrale'
		WHEN 'M' THEN 'Mensile'
