CREATE             PROCEDURE [doupdate_mandato_pagamento] 
(
	@ayear int,
	@printkind char(1),
	@startnpay int,
	@stopnpay int,
	@printdate datetime
)
AS BEGIN
CREATE TABLE #printingdoc(npay int)
IF @printkind = 'A' 
BEGIN
	INSERT INTO #printingdoc (npay) 
	SELECT npay FROM payment WHERE (ypay=@ayear) AND (printdate IS NULL)
END
IF @printkind <> 'A'
BEGIN
	INSERT INTO #printingdoc (npay) 
	SELECT npay FROM payment WHERE (ypay=@ayear) AND (npay BETWEEN @startnpay AND @stopnpay)
END
UPDATE payment
SET printdate =	@printdate
WHERE ypay = @ayear
	AND npay IN (SELECT npay FROM #printingdoc)
	AND printdate IS NULL
END


GO

