if object_id('[closeyear_expensearrearscopy]') is not null
	drop PROCEDURE [closeyear_expensearrearscopy]
go


CREATE      PROCEDURE [closeyear_expensearrearscopy]
(
	@ayear int
)
AS BEGIN
	
DECLARE @idexp int
DECLARE @idfin  int
DECLARE @idupb varchar(36)
DECLARE @nphase tinyint
DECLARE @nlevel tinyint
DECLARE @curramount decimal(19,2)
DECLARE @available decimal(19,2)
DECLARE @payed decimal(19,2)
DECLARE @newidfin int
DECLARE @nextayear int
SET @nextayear = @ayear + 1
DECLARE @nextayearstr varchar(4)
SET @nextayearstr = CONVERT(varchar(4),@nextayear)
	
DECLARE @maxexpensephase int
SELECT @maxexpensephase =  MAX(nphase) FROM expensephase
DECLARE exp_crs INSENSITIVE CURSOR FOR
SELECT expense.idexp, curramount, available,nphase
FROM expensetotal
JOIN expense
	ON expense.idexp = expensetotal.idexp
WHERE ayear = @ayear
	AND expense.nphase < @maxexpensephase 
ORDER BY expense.idexp
FOR READ ONLY
	
OPEN exp_crs
FETCH NEXT FROM exp_crs INTO @idexp, @curramount, @available, @nlevel
WHILE (@@FETCH_STATUS = 0)
BEGIN
	IF @nlevel = @maxexpensephase - 1
	BEGIN
		SET @payed = @curramount - @available
	END
	ELSE
	BEGIN
		SELECT @payed = ISNULL(SUM(curramount), 0)
		FROM expensetotal
		JOIN expenselast
			ON     expenselast.idexp = expensetotal.idexp
		JOIN   expenselink
			ON     expenselink.idchild = expenselast.idexp
		WHERE  expensetotal.ayear = @ayear
				AND expenselink.idparent = @idexp and nlevel = @nlevel 
	END
	
	
	IF (@curramount -  @payed) > 0
	BEGIN
		IF NOT EXISTS
			(SELECT * FROM expenseyear 	WHERE idexp = @idexp AND ayear = @nextayear)
		BEGIN
			SELECT 	@idfin = idfin,	@idupb = idupb		FROM expenseyear
					WHERE idexp = @idexp AND ayear = @ayear
	
			SET @newidfin = NULL
			IF @idfin IS NOT NULL
			BEGIN
				SELECT @newidfin = newidfin FROM finlookup WHERE oldidfin = @idfin	
			END
			INSERT INTO expenseyear	(idexp, ayear, idfin, idupb, amount, 
						cu, ct, lu, lt)
			VALUES
			(
				@idexp, @nextayear, @newidfin, @idupb,  @curramount - @payed,
				'ArrearsCopy', GETDATE(), 'ArrearsCopy', GETDATE()
			)
		END
	END
	FETCH NEXT FROM exp_crs INTO @idexp, @curramount, @available, @nlevel
END
DEALLOCATE exp_crs
EXEC closeyear_casualcontract @ayear
EXEC closeyear_wageaddition @ayear
CREATE TABLE #info (msg varchar(800))
INSERT INTO #info
VALUES('I residui passivi sono stati trasferiti all''esercizio ' + @nextayearstr)
	
-- azzero i bit da 0 a 3 e imposto il valore 5 nell'esercizio corrente. 
UPDATE accountingyear SET flag = flag&0xF0 WHERE ayear = @ayear
UPDATE accountingyear SET flag = flag|0x05 WHERE ayear = @ayear
-- azzero i bit da 0 a 3 e imposto il valore 0 nel nuovo esercizio.
UPDATE accountingyear SET flag = flag&0xF0 WHERE ayear = @nextayear
	
SELECT * FROM #info
END


GO

print '[closeyear_expensearrearscopy] OK'

