if object_id('[doupdate_reversale_incasso]') is not null
	drop PROCEDURE [doupdate_reversale_incasso]
go

CREATE             PROCEDURE [doupdate_reversale_incasso]
(
	@ayear int,
	@printkind char(1),
	@startnpro int,
	@stopnpro int,
	@printdate datetime
)
AS BEGIN
CREATE TABLE #printingdoc (npro int)
IF @printkind = 'A' 
BEGIN
	INSERT INTO #printingdoc (npro) 
	SELECT npro FROM proceeds WHERE (ypro=@ayear) AND (printdate IS NULL)
END
IF @printkind <> 'A'
BEGIN
	INSERT INTO #printingdoc (npro) 
	SELECT npro FROM proceeds WHERE (ypro=@ayear) AND (npro BETWEEN @startnpro AND @stopnpro)
END
UPDATE proceeds
SET printdate =	@printdate
WHERE ypro = @ayear
	AND npro IN (SELECT npro FROM #printingdoc)
	AND printdate IS NULL
END


