if object_id('[sp_conguagliatutto]') is not null
	drop PROCEDURE [sp_conguagliatutto]
go


CREATE      PROCEDURE [sp_conguagliatutto]
(
        @ycon smallint, 
        @ncon int,
        @ayear smallint,
        @adate datetime
)
AS BEGIN
/*
Query per l'esecuzione della sp:
DECLARE @RC int
DECLARE @ycon smallint
DECLARE @ncon int
DECLARE @ayear smallint
DECLARE @adate datetime
-- TODO: impostare qui i valori dei parametri.
SET @ycon = ...
SET @ncon = ...
SET @ayear =  ...
SET @adate = '22/12/2008'
EXECUTE @RC = [Pau_Easy_2005].[pau].[sp_conguagliatutto]  @ycon ,@ncon ,@ayear  ,@adate
*/
----INSERIRE ESERCIZIO E NUMERO DEL CONTRATTO, e ESERCIZIO IN CUI EFFETTUARE L'OPERAZIONE
-- inoltre la data contabile per le eventuali correzioni ritenute da contabilizzare

declare @idcon varchar(100)
declare @nconchar varchar(10)
----si calcola l'idcon a partire da ycon/ncon
set @nconchar= convert(varchar(6),@ncon)
set @nconchar= substring('000000',1,6-len(@nconchar))+@nconchar
set @idcon= substring(convert(varchar(4),@ycon),3,2)+@nconchar

declare @npayrollbalance int
declare @idpayrollbalance int
declare @idpayrolltodelete int
declare @idpayrolldest int

select @idpayrollbalance=idpayroll, @npayrollbalance = npayroll 
	from payroll where fiscalyear=@ayear and idcon=@idcon and flagbalance='S'
select @idpayrolltodelete = idpayroll from payroll 
where npayroll=@npayrollbalance and idcon=@idcon and flagbalance='N'  and fiscalyear=@ayear
select @idpayrolldest= idpayroll from payroll 
where npayroll=@npayrollbalance-1 and idcon=@idcon and fiscalyear=@ayear
declare @idexpbalanceImpegno int
select @idexpbalanceImpegno= idexp from expensepayroll where idpayroll=@idpayrolldest
declare @idexpbalance int
select @idexpbalance= ELAST.idexp from expenselink EL 
		join expenselast ELAST ON EL.idchild=ELAST.idexp
		where EL.idparent = @idexpbalanceImpegno
--come prima cosa mette le righe opportune in expensetaxcorrige pari esattamente alla somma dei  valori 
--  presenti in payrolltax e payrolltaxcorrige del cedolino da eliminare
create table #tempexptaxcorrige (
	[idexp] [int] NOT NULL ,
	[idexpensetaxcorrige] [int] IDENTITY(1,1),
	[taxcode] [int] NOT NULL ,
	[ayear] [smallint] NOT NULL ,
	[employamount] [decimal](19, 2) NULL ,
	[adminamount] [decimal](19, 2) NULL ,
	[idcity] [int] NULL ,
	[idfiscaltaxregion] [varchar] (5) ,
	[adate] [datetime] NULL ,
	[ct] [datetime] NOT NULL ,
	[cu] [varchar] (64)  ,
	[lt] [datetime] NOT NULL ,
	[lu] [varchar] (64)  
)
if exists (select * from payrolltax where idpayroll=@idpayrolltodelete and 
			(isnull(admintax,0)<>0 or isnull(employtax,0)<>0) 
		)
BEGIN
 insert into #tempexptaxcorrige(idexp,taxcode,ayear,employamount,adminamount,idcity,idfiscaltaxregion,
			adate,ct,cu,lt,lu) 
 select @idexpbalance, TC.taxcode,@ayear,employtax,admintax,idcity,idfiscaltaxregion, 
	@adate,getdate(),'script',getdate(),'script'
 from  payrolltax TC where TC.idpayroll=@idpayrolltodelete and 
			(isnull(TC.admintax,0)<>0 or isnull(TC.employtax,0)<>0) 
END
insert into #tempexptaxcorrige  (idexp,taxcode,ayear,employamount,adminamount,idcity,idfiscaltaxregion,
			adate,ct,cu,lt,lu) 
 select @idexpbalance, taxcode, ayear,employamount,adminamount,idcity,idfiscaltaxregion, 
	@adate,getdate(),'script',getdate(),'script'
 from  payrolltaxcorrige where idpayroll=@idpayrolltodelete
		and ( 		
			(idcity is null and idfiscaltaxregion is null)
			OR
			( (idcity is not null or idfiscaltaxregion is not null) AND isnull(employamount,0)<>0 )
		    )
insert into expensetaxcorrige (idexp,idexpensetaxcorrige,taxcode,ayear,employamount,adminamount,idcity,idfiscaltaxregion,
			adate,ct,cu,lt,lu) 
select idexp,idexpensetaxcorrige,taxcode,ayear,employamount,adminamount,idcity,idfiscaltaxregion,
			adate,ct,cu,lt,lu from #tempexptaxcorrige
drop table #tempexptaxcorrige

CREATE TABLE [#expensetaxofficial] (
	[idexp] [int] NOT NULL ,
	[idexpensetaxofficial] [int] IDENTITY(1,1), 
	[taxcode] [int] NOT NULL ,
	[nbracket] [int]  null, 
	[ayear] [smallint] NOT NULL ,
	[taxabledenominator] [decimal](19, 6) NULL ,
	[taxablenumerator] [decimal](19, 6) NULL ,
	[taxablegross] [decimal](19, 2) NULL ,
	[exemptionquota] [decimal](19, 2) NULL ,
	[taxablenet] [decimal](19, 2) NULL ,
	[adminrate] [decimal](19, 6) NULL ,
	[admindenominator] [decimal](19, 6) NULL ,
	[adminnumerator] [decimal](19, 6) NULL ,
	[admintax] [decimal](19, 2) NULL ,
	[employrate] [decimal](19, 6) NULL ,
	[employdenominator] [decimal](19, 6) NULL ,
	[employnumerator] [decimal](19, 6) NULL ,
	[employtax] [decimal](19, 2) NULL ,
	[abatements] [decimal](19, 2) NULL ,
	[start] [datetime] NULL ,
	[stop] [datetime] NULL ,
	[ct] [datetime] NOT NULL ,
	[cu] [varchar] (64)  NOT NULL ,
	[lt] [datetime] NOT NULL ,
	[lu] [varchar] (64)  NOT NULL ,
	[idcity] [int] NULL ,
	[idfiscaltaxregion] [varchar] (5) NULL,
	riporto decimal(19,2),
	nettizzato char(1)
) 
--ora si ricalcola expensetaxofficial mettendo come valori quelli presi da:
--  quelli del cedolino destinazione
--  quelli presenti nel cedolino da cancellare e relative corrige
--  in particolare però abatements sarà preso da abatements+annualpayedemploytax del cedolino 
--    ed il suo valore ripartito tra le relative ritenute, decrementandone il valore
 
-- idexpensetaxofficial è per ora valorizzata come IDENTITY, nbracket lo sarà subito dopo
insert into #expensetaxofficial (idexp,taxcode,ayear,
	taxabledenominator,taxablenumerator,taxablegross,exemptionquota,
	taxablenet,
	adminrate,admindenominator,adminnumerator,admintax,
	employrate,employdenominator,employnumerator,employtax,
	abatements,
	start,stop,ct,cu,lt,lu,idcity,idfiscaltaxregion)
select @idexpbalance,taxcode,fiscalyear,
	taxabledenominator,taxablenumerator,sum(taxablegross),sum(deduction),
	sum(taxablenet),
	isnull(adminrate,0),isnull(admindenominator,1),isnull(adminnumerator,1),sum(admintax),
	isnull(employrate,0),isnull(employdenominator,1),isnull(employnumerator,1),sum(employtax),
	sum(abatements),
	@adate,null,getdate(),'script',getdate(),'script',idcity,idfiscaltaxregion 
from  
	payrolltaxbracketview where idpayroll in (@idpayrolltodelete,@idpayrolldest)
group by taxcode,fiscalyear,taxabledenominator,taxablenumerator,
	isnull(adminrate,0),isnull(admindenominator,1),isnull(adminnumerator,1),
	isnull(employrate,0),isnull(employdenominator,1),isnull(employnumerator,1),
	idcity,idfiscaltaxregion 
order by taxcode asc ,isnull(employrate,0) asc, isnull(adminrate,0) asc,sum(employtax) desc --        <-
update #expensetaxofficial set abatements= isnull(abatements,0)+
		isnull( (select isnull(annualpayedemploytax,0) from  
               			 payrolltaxview where idpayroll =@idpayrolltodelete
                                        and #expensetaxofficial.taxcode = payrolltaxview.taxcode),0)
--select * from #expensetaxofficial
update #expensetaxofficial set riporto=0,nettizzato='N'
	
update #expensetaxofficial set 
	nbracket= (select count(*)  from #expensetaxofficial E2 where E2.taxcode=#expensetaxofficial.taxcode and
						E2.idexpensetaxofficial<=#expensetaxofficial.idexpensetaxofficial)
--azzera le detrazioni tranne che nei primi scaglioni di ogni ritenuta
update #expensetaxofficial set abatements=0 where 
	 (select count(*) from #expensetaxofficial E2 where E2.taxcode=#expensetaxofficial.taxcode and
						E2.nbracket<#expensetaxofficial.nbracket)>0

delete from #expensetaxofficial where taxablenet=0 and admintax=0 and employtax=0 and abatements=0

--imposta il riporto ove necessario
update #expensetaxofficial set riporto=isnull(abatements,0)-isnull(employtax,0)
			       where isnull(riporto,0)=0 and (isnull(abatements,0)-isnull(employtax,0))>0
					and (isnull(abatements,0)>0)
					
--applica le detrazioni ove possibile nettizzando la rit.dipendente
update #expensetaxofficial set employtax=isnull(employtax,0)-(isnull(abatements,0)-isnull(riporto,0)),
				nettizzato='S'
			       where isnull(abatements,0)>0
--continua a ripartire la detrazione negli scaglioni sottostanti
while exists(select * from #expensetaxofficial E1 where isnull(E1.riporto,0)>0 and
			exists(select * from #expensetaxofficial E2 where E2.taxcode=E1.taxcode 
					and isnull(E2.riporto,0)=0  and E2.nbracket=E1.nbracket+1)
	     )
BEGIN
update #expensetaxofficial set 
	abatements = isnull((select E1.riporto from #expensetaxofficial E1 where 
						E1.taxcode=#expensetaxofficial.taxcode and E1.nbracket=#expensetaxofficial.nbracket -1),0)
	where nbracket>1 and  isnull(#expensetaxofficial.riporto,0)=0 and
		isnull((select E1.riporto from #expensetaxofficial E1 where 
						E1.taxcode=#expensetaxofficial.taxcode and E1.nbracket=#expensetaxofficial.nbracket -1),0)>0
		and nettizzato='N'
--imposta il riporto ove necessario
update #expensetaxofficial set riporto=isnull(abatements,0)-isnull(employtax,0)
			       where isnull(riporto,0)=0 and (isnull(abatements,0)-isnull(employtax,0))>0
					and (isnull(abatements,0)>0)
					and nettizzato='N'
--applica le detrazioni ove possibile nettizzando la rit.dipendente
update #expensetaxofficial set employtax=isnull(employtax,0)-(isnull(abatements,0)-isnull(riporto,0)),
				nettizzato='S'
			       where isnull(abatements,0)>0 and  nettizzato='N'
END
--sistema tutto il resto, ossia ove ci sia ancora detrazione da applicare la ritenuta rimane negativa
update #expensetaxofficial set employtax=isnull(employtax,0)-isnull(abatements,0),
		nettizzato='S'
	where isnull(abatements,0)<>0 and nettizzato='N' -- <-- CORREGGE employtax = 0 di exepensetaxoffice

delete from #expensetaxofficial where taxablenet=0 and admintax=0 and employtax=0 and abatements=0

declare @maxidexptaxofficial int
select @maxidexptaxofficial= max( idexpensetaxofficial) from expensetaxofficial where idexp=@idexpbalance

update expensetaxofficial set stop=@adate where idexp=@idexpbalance
--delete  from  expensetaxofficial set where idexp=@idexpbalance

insert into expensetaxofficial (idexp,
        idexpensetaxofficial,        --        <--
        taxcode,nbracket,ayear,
	taxabledenominator,taxablenumerator,taxablegross,exemptionquota,
	taxablenet,
	adminrate,admindenominator,adminnumerator,admintax,
	employrate,employdenominator,employnumerator,employtax,
	abatements,
	start,stop,ct,cu,lt,lu,idcity,idfiscaltaxregion)
select idexp,
        @maxidexptaxofficial+idexpensetaxofficial,        --        <--
        taxcode,nbracket,ayear,
	taxabledenominator,taxablenumerator,taxablegross,exemptionquota,
	taxablenet,
	adminrate,admindenominator,adminnumerator,admintax,
	employrate,employdenominator,employnumerator,employtax,
	abatements,
	@adate,null,ct,cu,lt,lu,idcity,idfiscaltaxregion from #expensetaxofficial
		
drop table #expensetaxofficial



--imposta data fine cedolino destinazione
declare @datafine datetime 
select @datafine = stop from payroll where idpayroll=@idpayrolltodelete
update payroll set stop = @datafine where idpayroll=@idpayrolldest

--imposta workingdays cedolino destinazione
declare @workingdays int
select @workingdays = workingdays from payroll where idpayroll=@idpayrolltodelete
update payroll set workingdays = isnull(workingdays,0)+isnull(@workingdays,0) where idpayroll=@idpayrolldest
--imposta feegross cedolino destinazione
declare @feegross decimal(19,2)
select @feegross = feegross from payroll where idpayroll=@idpayrolltodelete
update payroll set feegross = isnull(feegross,0)+isnull(@feegross,0) where idpayroll=@idpayrolldest
--imposta netfee cedolino destinazione
declare @netfee decimal(19,2)
select @netfee = netfee from payroll where idpayroll=@idpayrolltodelete
update payroll set netfee = isnull(netfee,0)+isnull(@netfee,0) where idpayroll=@idpayrolldest

update  payrolltax set
 admintax = isnull(admintax,0)+ isnull( (select admintax from payrolltax P 
				where P.idpayroll=@idpayrolltodelete and P.taxcode = payrolltax.taxcode)
					,0),
 annualpayedemploytax = isnull(annualpayedemploytax,0)+ isnull( (select annualpayedemploytax from payrolltax P 
						where P.idpayroll=@idpayrolltodelete and P.taxcode = payrolltax.taxcode)
					,0),
 employtax = isnull(employtax,0)+ isnull( (select employtax from payrolltax P 
				where P.idpayroll=@idpayrolltodelete and P.taxcode = payrolltax.taxcode)
					,0),
 deduction = isnull(deduction,0)+ isnull( (select deduction from payrolltax P 
				where P.idpayroll=@idpayrolltodelete and P.taxcode = payrolltax.taxcode)
					,0),
 abatements = isnull(abatements,0)+ isnull( (select abatements from payrolltax P 
				where P.idpayroll=@idpayrolltodelete and P.taxcode = payrolltax.taxcode)
					,0),
 employtaxgross = isnull(employtaxgross,0)+ isnull( (select employtaxgross from payrolltax P 
				where P.idpayroll=@idpayrolltodelete and P.taxcode = payrolltax.taxcode)
					,0),
 taxablegross = isnull(taxablegross,0)+ isnull( (select taxablegross from payrolltax P 
				where P.idpayroll=@idpayrolltodelete and P.taxcode = payrolltax.taxcode)
					,0),
 taxablenet = isnull(taxablenet,0)+ isnull( (select taxablenet from payrolltax P 
				where P.idpayroll=@idpayrolltodelete and P.taxcode = payrolltax.taxcode)
					,0)
 
	where idpayroll=@idpayrolldest

--adminrate e employrate se li calcola alla fine
update payrolltax set employrate=(isnull(employtaxgross,0)*isnull(employdenominator,1)/isnull(employnumerator,1))	
					 / isnull(taxablenet,0  )
	where  idpayroll=@idpayrolldest and isnull(taxablenet,0)<>0
update payrolltax set  adminrate=(isnull(admintax,0)*isnull(admindenominator,1)/isnull(adminnumerator,1))
				/ isnull(taxablegross,0  )
	where  idpayroll=@idpayrolldest and isnull(taxablegross,0)<>0

--Attenzione: rimangono ancora fuori i payrolltax che ci sono nel cedolino da cancellare e non in quello di destinazione

--Aggiorna le righe di payrolltaxbracket in comune
update payrolltaxbracket set 
	employtax=isnull(employtax,0)+ isnull(
			(select PT2.employtax from payrolltaxbracket PT2 
                                join payrolltax P2         --         <-
                                        on PT2.idpayroll = P2.idpayroll
                                        and PT2.idpayrolltax = P2.idpayrolltax
                                where PT2.idpayroll=@idpayrolltodelete and 
				P2.taxcode= (select taxcode from payrolltax PT where PT.idpayroll=payrolltaxbracket.idpayroll and
							PT.idpayrolltax=payrolltaxbracket.idpayrolltax)
				and  isnull(PT2.adminrate,0)=isnull(payrolltaxbracket.adminrate,0)
				and  isnull(PT2.employrate,0)=isnull(payrolltaxbracket.employrate,0)
			),0
		),
	admintax=isnull(admintax,0)+ isnull(
			(select PT2.admintax from payrolltaxbracket PT2 
                                join payrolltax P2        --         <-
                                        on PT2.idpayroll = P2.idpayroll
                                        and PT2.idpayrolltax = P2.idpayrolltax
                                where PT2.idpayroll=@idpayrolltodelete and 
				P2.taxcode= (select taxcode from payrolltax PT where PT.idpayroll=payrolltaxbracket.idpayroll and
							PT.idpayrolltax=payrolltaxbracket.idpayrolltax)
				and  isnull(PT2.adminrate,0)=isnull(payrolltaxbracket.adminrate,0)
				and  isnull(PT2.employrate,0)=isnull(payrolltaxbracket.employrate,0)
			),0
		),
	taxable=isnull(taxable,0)+ isnull(
			(select PT2.taxable from payrolltaxbracket PT2 
                                join payrolltax P2        --         <-
                                        on PT2.idpayroll = P2.idpayroll
                                        and PT2.idpayrolltax = P2.idpayrolltax
                                where PT2.idpayroll=@idpayrolltodelete and 
				P2.taxcode= (select taxcode from payrolltax PT where PT.idpayroll=payrolltaxbracket.idpayroll and
							PT.idpayrolltax=payrolltaxbracket.idpayrolltax)
				and  isnull(PT2.adminrate,0)=isnull(payrolltaxbracket.adminrate,0)
				and  isnull(PT2.employrate,0)=isnull(payrolltaxbracket.employrate,0)
			),0
		)
where idpayroll=@idpayrolldest

--cancella le righe da payrolltaxbracket del cedolino da cancellare
delete from payrolltaxbracket
	where idpayroll=@idpayrolltodelete and 
	 exists (select * from payrolltaxbracket PT1 join payrolltax P1 on P1.idpayroll=PT1.idpayroll
			where P1.idpayroll=@idpayrolldest and
				P1.taxcode= (select taxcode from payrolltax PT where PT.idpayroll=payrolltaxbracket.idpayroll and
							PT.idpayrolltax=payrolltaxbracket.idpayrolltax)
				and  isnull(PT1.adminrate,0)=isnull(payrolltaxbracket.adminrate,0)		
				and  isnull(PT1.employrate,0)=isnull(payrolltaxbracket.employrate,0)
		)
declare @maxidpayrolltax int
select @maxidpayrolltax= max(idpayrolltax) from payrolltax where idpayroll= @idpayrolldest
set @maxidpayrolltax= isnull(@maxidpayrolltax,0)
--sposta le righe di payrolltax e payrolltaxbracket di cui payrolltax non ha corrispondenza nel cedolino destinazione
update payrolltax set idpayrolltax=idpayrolltax+@maxidpayrolltax,
			idpayroll=@idpayrolldest 
	where  idpayroll=@idpayrolltodelete and
		not exists(select * from payrolltax PT2 where PT2.idpayroll=@idpayrolldest 
					and PT2.taxcode=payrolltax.taxcode)
		
--sposta gli orfani rimasti in payrolltaxbracket
update payrolltaxbracket set idpayrolltax=idpayrolltax+@maxidpayrolltax,
			idpayroll=@idpayrolldest 
	where  idpayroll=@idpayrolltodelete and
		not exists(select * from payrolltax PT2 where PT2.idpayroll=payrolltaxbracket.idpayroll
					and PT2.idpayrolltax=payrolltaxbracket.idpayrolltax)
--A questo punto rimangono delle righe in payrolltaxbracket del cedolino da cancellare 
--	che sono cmq associabili a payrolltax del cedolino di destinazione
--Calcola il massimo scaglione presente tra i payrolltax del cedolino di destinazione, per essere sicuri di non andare in conflitto
declare @maxnbracket int
select @maxnbracket= max(nbracket) from payrolltaxbracket where idpayroll= @idpayrolldest
set @maxnbracket= isnull(@maxnbracket,0)
--Sposta tutti i payrolltaxbracket rimasti
update payrolltaxbracket set nbracket= isnull(nbracket,0)+@maxnbracket,
		idpayrolltax= (select PT2.idpayrolltax from payrolltax PT2 
			where PT2.idpayroll=@idpayrolldest
				and PT2.taxcode= 
			(select taxcode from payrolltax PT1 where PT1.idpayroll=@idpayrolltodelete and
						PT1.idpayrolltax=payrolltaxbracket.idpayrolltax)
				)			
		,
		idpayroll= @idpayrolldest
	where idpayroll=@idpayrolltodelete 
--cancella tutti i payrolltax e rimasti
delete from payrolltax where idpayroll=@idpayrolltodelete 	

--aggiorna la numerazione dei payrolltaxbracket
while exists (select * from payrolltaxbracket PTB where PTB.idpayroll=@idpayrolldest and PTB.nbracket>1 and
				not exists 
			(select * from  payrolltaxbracket PTB2 where PTB2.idpayroll=@idpayrolldest and 
						PTB2.nbracket=PTB.nbracket-1 and
						PTB2.idpayrolltax=PTB.idpayrolltax
			)
		)
BEGIN 
--        <-
update payrolltaxbracket set nbracket=nbracket-1 where  idpayroll=@idpayrolldest and nbracket>1 and
				not exists 
			(select * from  payrolltaxbracket PTB2 where PTB2.idpayroll=@idpayrolldest and 
						PTB2.nbracket = payrolltaxbracket.nbracket-1 and
						PTB2.idpayrolltax = payrolltaxbracket.idpayrolltax
			)
END
--aggiorna i payrolldeduction 
update payrolldeduction set annualamount = (select annualamount from payrolldeduction PD where
			PD.idpayroll= @idpayrolltodelete and PD.iddeduction=payrolldeduction.iddeduction)
		where idpayroll=@idpayrolldest and
		exists (select * from payrolldeduction PD where
			PD.idpayroll= @idpayrolltodelete and PD.iddeduction=payrolldeduction.iddeduction)
update payrolldeduction set curramount = isnull(curramount,0)+
		isnull(
			(select curramount from payrolldeduction PD where
			PD.idpayroll= @idpayrolltodelete and PD.iddeduction=payrolldeduction.iddeduction)
		,0)
		where idpayroll=@idpayrolldest and
		exists (select * from payrolldeduction PD where
			PD.idpayroll= @idpayrolltodelete and PD.iddeduction=payrolldeduction.iddeduction)
--aggiorna i payrollabatement
update payrollabatement set annualamount = (select annualamount from payrollabatement PD where
			PD.idpayroll= @idpayrolltodelete and PD.idabatement=payrollabatement.idabatement)
		where idpayroll=@idpayrolldest and
		exists (select * from payrollabatement PD where
			PD.idpayroll= @idpayrolltodelete and PD.idabatement=payrollabatement.idabatement)
update payrollabatement set curramount = isnull(curramount,0)+
		isnull(
			(select curramount from payrollabatement PD where
			PD.idpayroll= @idpayrolltodelete and PD.idabatement=payrollabatement.idabatement)
		,0)
		where idpayroll=@idpayrolldest and
		exists (select * from payrollabatement PD where
			PD.idpayroll= @idpayrolltodelete and PD.idabatement=payrollabatement.idabatement)
--cancella i payrolldeduction e abatement comuni dal cedolino da cancellare
delete from payrolldeduction where idpayroll= @idpayrolltodelete and
		exists (select * from payrolldeduction PD where
			PD.idpayroll= @idpayrolldest and PD.iddeduction=payrolldeduction.iddeduction)
delete from payrollabatement where idpayroll= @idpayrolltodelete and
		exists (select * from payrollabatement PD where
			PD.idpayroll= @idpayrolldest and PD.idabatement=payrollabatement.idabatement)
--sposta quelli eventualmente rimasti
update payrolldeduction set idpayroll=@idpayrolldest where idpayroll=@idpayrolltodelete
update payrollabatement set idpayroll=@idpayrolldest where idpayroll=@idpayrolltodelete

--sposta i payrolltaxcorrige eventualmente presenti nel conguaglio ( non credo ve ne possano essere prima)
update payrolltaxcorrige set idpayroll=@idpayrolldest where idpayroll=@idpayrolltodelete

-- sposta il conguaglio indietro di un cedolino
update payroll set npayroll=npayroll-1 where idpayroll=@idpayrollbalance
-- Valorizza la data di erogazione del cedolino di conguaglio
update payroll set disbursementdate = (select adate from expense where idexp = @idexpbalanceImpegno) 
                                where idpayroll=@idpayrollbalance

delete from payroll where idpayroll=@idpayrolltodelete

END


