CREATE                          TRIGGER [trigger_u_audit] ON [audit]
FOR UPDATE
AS BEGIN
	DECLARE @idaudit varchar(25)
	SELECT @idaudit = idaudit FROM inserted
	INSERT INTO [sptocompile]
	SELECT DISTINCT opkind,tablename,GETDATE() FROM auditcheck WHERE idaudit = @idaudit 
	AND NOT EXISTS(SELECT s.opkind,s.tablename FROM sptocompile s WHERE s.opkind = auditcheck.opkind AND s.tablename = auditcheck.tablename)
END

