if object_id('rebuild_expensetotal') is not null
	drop PROCEDURE rebuild_expensetotal
go

CREATE               PROCEDURE  rebuild_expensetotal
(
	@ayear int =  NULL
)
AS BEGIN
	
	DECLARE @curryear int
	DELETE from expensetotal where (@ayear is null)  OR ayear=@ayear
	
	DECLARE @finphase tinyint
	SELECT @finphase = expensefinphase FROM uniconfig
-- Bisogna valorizzare il campo flag
--bit 0: flagarrear
--bit 1: firstyear
		INSERT INTO expensetotal 
		(
			idexp,
			ayear,
			curramount,
			flag
		)
		SELECT
			expenseyear.idexp,
			expenseyear.ayear,
			expenseyear.amount,
		CASE
			WHEN expense.nphase < @finphase
			THEN 0
			WHEN (SELECT e2.ymov
				FROM expenselink
				JOIN expense e2
					ON expenselink.idparent = e2.idexp
				WHERE expenselink.idchild = expense.idexp
				AND expenselink.nlevel = @finphase) = expenseyear.ayear THEN 0
			ELSE 1
		END +
		CASE
			WHEN expense.ymov = expenseyear.ayear THEN 2
			ELSE 0
		END 
		FROM expenseyear
		JOIN expense
			ON expense.idexp = expenseyear.idexp
		WHERE  (@ayear is null)  OR ayear=@ayear
	
		UPDATE expensetotal
		SET curramount = ISNULL(curramount, 0) +
		ISNULL((
			SELECT SUM(amount) 
			FROM expensevar
			WHERE expensevar.idexp = expensetotal.idexp
			AND expensevar.yvar = expensetotal.ayear
		), 0)
		WHERE  (@ayear is null) OR ayear=@ayear
		UPDATE expensetotal
		SET available = ISNULL(curramount, 0) -
		ISNULL(
			(
			SELECT SUM(it2.curramount)
			FROM expensetotal it2
			JOIN expense
			ON expense.idexp = it2.idexp
			WHERE it2.ayear=  expensetotal.ayear
				AND expense.parentidexp = expensetotal.idexp
			)
		, 0)
		WHERE  (@ayear is null) OR ayear=@ayear
END

GO

print 'rebuild_expensetotal OK'

