go
CREATE      PROCEDURE [exp_asset_importazione]
(
	@idinventory int,
	@fromninv int,
	@toninv int
)
AS
BEGIN
--exp_asset_importazione 36,1,1000
-- Tracciato
/*
   string[] tracciato_cespiti = new string[]{
            "tipocespite;Tipo Cespite (Cespite/Accessorio);Codificato;1;C|A",
            "codiceinv;Codice Inventario;Stringa;20",
            "descrinv;Descrizione Inventario;Stringa;50",
            "codeinvkind;Codice Tipo Inventario;Stringa;20",
            "descrinvkind;Descr. Tipo Inventario;Stringa;50",
            "codeinvagency;Codice Ente Inventariale;Stringa;20",
            "descrinvagency;Descrizione Ente Inventariale;Stringa;150",
            "numinv;Numero di inventario;Intero;8",
            "nprogr;Numero progressivo. 1 per i cespiti, 2 o più per gli accessori;Intero;5",
             //
            "codiceinv_prec;Codice Inventario di Provenienza;Stringa;20",
            "descrinv_prec;Descrizione Inventario di Provenienza;Stringa;50",
            "codeinvkind_prec;Codice Tipo Inventario di Provenienza;Stringa;20",
            "descrinvkind_prec;Descr. Tipo Inventario di Provenienza;Stringa;50",
            "codeinvagency_prec;Codice Ente Inventariale di Provenienza;Stringa;20",
            "descrinvagency_prec;Descrizione Ente Inventariale di Provenienza;Stringa;150",
            "numinv_prec;Numero di inventario di Provenienza;Intero;8",
            "nprogr_prec;Numero progressivo. di Provenienza, 1 per i cespiti, 2 o più per gli accessori;Intero;5",
            //
            "codiceinv_succ;Codice Inventario Successivo;Stringa;20",
            "descrinv_succ;Descrizione Inventario Successivo;Stringa;50",
            "codeinvkind_succ;Codice Tipo Inventario Successivo;Stringa;20",
            "descrinvkind_succ;Descr. Tipo Inventario Successivo;Stringa;50",
            "codeinvagency_succ;Codice Ente Inventariale Successivo;Stringa;20",
            "descrinvagency_succ;Descrizione Ente Inventariale Successivo;Stringa;150",
            "numinv_succ;Numero di inventario Successivo;Intero;8",
            "nprogr_succ;Numero progressivo Successivo, 1 per i cespiti, 2 o più per gli accessori;Intero;5",
            //
            "inizioesist;Inizio esistenza;Data;8",
            "codiceclass;Codice classificazione inventariale;Stringa;20",
            "descr;Descrizione Cespite;Stringa;150",
            "impon;Imponibile;Numero;22",
            "iva;Iva;Numero;22",
            "ivadetr;Iva Detraibile;Numero;22",
            "ivaperc;Aliquota Iva;Numero;22",
            "scontoperc;Percentuale Sconto;Numero;22",
            "codicecausalecar;Codice Causale di carico;Stringa;10",
            "descrcausalecar;Descrizione Causale di carico;Stringa;30",
            "codicecedente;Codice Cedente (di anagrafica);Intero;10",
            "datacar;Data di Carico;Data;8",
            "posseduto;Posseduto(S/N);Codificato;1;S|N",
            "includibuonocar;Da includere in buono di carico (S/N);Codificato;1;S|N",
            "codicetipobuonocar;Codice tipo buono carico;Stringa;20",
            "annobuonocar;Anno buono carico;Intero;4",
            "numbuonocar;Numero buono carico;Intero;8",
            "resp;Responsabile;Stringa;150",
            "codeubic;Codice ubicazione;Stringa;50",
            "includibuonoscar;Da includere in buono di scarico (S/N);Codificato;1;S|N",
            "codicetipobuonoscar;Codice tipo buono scarico;Stringa;20",
            "annobuonoscar;Anno buono scarico;Intero;4",
            "numbuonoscar;Numero buono scarico;Intero;8",
            "note;Note;Stringa;400",
            "historical;Valore originale storico;numero;22",
        };
        */

CREATE TABLE  #result
(
	----------------------------------------------------------------------------
	---------------------------- CESPITI O ACCESSORI ---------------------------
	----------------------------------------------------------------------------
	idasset					int,			-- idasset
	idpiece					int,			-- idpiece 
	tipocespite				char(1),		-- cespite o accessorio
	numinv					int,			-- numero inventario
	nprogr					int,			-- numero progressivo accessorio cespite
	inizioesist				smalldatetime,	-- inizio esistenza cespite
	codiceinv				varchar(20),    -- codice inventario di provenienza
    descrinv 				varchar(50),	-- descrizione inventario di provenienza
    codeinvkind 			varchar(20),    -- codice tipo inventario di provenienza
    descrinvkind 			varchar(50),    -- descrizione tipo inventario di provenienza
    codeinvagency 			varchar(20),	-- codice ente inventariale di provenienza
    descrinvagency			varchar(150),   -- descrizione ente inventariale di provenienza
	codiceinv_prec          varchar(20),    -- codice inventario di provenienza
    descrinv_prec			varchar(50),	-- descrizione inventario di provenienza
    codeinvkind_prec		varchar(20),    -- codice tipo inventario di provenienza
    descrinvkind_prec		varchar(50),    -- descrizione tipo inventario di provenienza
    codeinvagency_prec		varchar(20),	-- codice ente inventariale di provenienza
    descrinvagency_prec     varchar(150),   -- descrizione ente inventariale di provenienza
    numinv_prec             int,			-- numinv di provenienza
    nprogr_prec             int,			-- num progr. di provenienza
    codiceinv_succ          varchar(20),	-- codice inventario di destinazione
    descrinv_succ			varchar(50),	-- descrizione inventario di destinazione
    codeinvkind_succ		varchar(20),	-- codice tipo inventario di destinazione
    descrinvkind_succ		varchar(50),	-- descrizione tipo inventario di destinazione
    codeinvagency_succ		varchar(20),	-- codice ente inventariale di destinazione
    descrinvagency_succ     varchar(150),	-- descrizione ente inventariale di destinazione
    numinv_succ             int,			-- numinv di destinazione
    nprogr_succ             int,			-- num prog di destinazione
	categoria				varchar(20),	-- Codice categoria inventariale (materiale bibliografico / non bibliografico)
	codiceclass				varchar(20),	-- Codice classificazione inventariale
	descrizione				varchar(150),	-- Descrizione Cespite
	impon					decimal(19,2),	-- Imponibile
	historical				decimal(19,2),	-- Valore storico
	iva						decimal(19,2),	-- iva
	ivadetr					decimal(19,2),	-- Iva Detraibile
	ivaperc					decimal(19,6),	-- Aliquota Iva
	scontoperc				decimal(19,6),	-- Percentuale Sconto
	includibuonocar			char(1),		-- da includere in un buono di carico (S/N)
	codicecausalecar  		varchar(20),	-- codice della causale di carico
	descrcausalecar			varchar(30),	-- descrizione causale carico
	datacar					varchar(30),	-- data di carico 
	posseduto				char(1),		-- cespite già posseduto(S/N)
	codicecedente			int,			-- codice del fornitore del cespite
	codicetipobuonocar		varchar(20),	-- codice tipo buono di carico
	annobuonocar 			int,			-- anno del buono di carico
	numbuonocar 			int,			-- numero del buono di carico
	includibuonoscar		char(1),		-- da includere in un buono di scarico (S/N)
	codicetipobuonoscar		varchar(20),	-- codice tipo buono di scarico
	annobuonoscar 			int,			-- anno del buono di scarico
	numbuonoscar 			int,			-- numero del buono di scarico
	codicecausalescar  		varchar(30),	-- codice della causale di scarico
	descrcausalescar		varchar(30),	-- descrizione causale scarico
	responsabile			varchar(150),	-- responsabile
	codeubic				varchar(50),	-- codice ubicazione
	note					varchar(1000)	-- annotazioni
)

 --inserisco nella tabella result i dati corrispondenti ai carichi cespite
INSERT INTO #result
(
	tipocespite,numinv,	nprogr, inizioesist,
	codiceinv,descrinv, codeinvkind,descrinvkind, codeinvagency,descrinvagency,
	codiceinv_succ,descrinv_succ, codeinvkind_succ,descrinvkind_succ,
	codeinvagency_succ, descrinvagency_succ, numinv_succ, nprogr_succ,
	codiceinv_prec, descrinv_prec, codeinvkind_prec, descrinvkind_prec,
	codeinvagency_prec,descrinvagency_prec, numinv_prec, nprogr_prec,
	responsabile, codeubic, categoria, codiceclass,descrizione,		
	impon,iva,ivadetr,ivaperc,scontoperc,
	posseduto,		
	includibuonocar,codicecausalecar,descrcausalecar,datacar,			
	codicecedente,codicetipobuonocar,annobuonocar,	numbuonocar,	
	includibuonoscar,codicetipobuonoscar,annobuonoscar,		
	numbuonoscar,codicecausalescar,descrcausalescar,note	
)
SELECT 
	CASE
		WHEN asset.idpiece = 1  THEN 'C'
		ELSE 'A'
	END,
	asset.ninventory,asset.idpiece,asset.lifestart,
	inventory.codeinventory, inventory.description,inventorykind.codeinventorykind,inventorykind.description,
	inventoryagency.codeinventoryagency,inventoryagency.description,
	inventory_next.codeinventory,inventory_next.description,
	inventorykind_next.codeinventorykind,inventorykind_next.description,
	inventoryagency_next.codeinventoryagency,inventoryagency_next.description,
	asset_next.ninventory,asset_next.idpiece,
	inventory_prev.codeinventory,inventory_prev.description,
	inventorykind_prev.codeinventorykind,inventorykind_prev.description,
	inventoryagency_prev.codeinventoryagency,inventoryagency_prev.description,  asset_prev.ninventory,asset_prev.idpiece,
	manager.title, location.locationcode, inventorytree1.codeinv,inventorytree.codeinv,inventorytree.description,
	assetacquire.taxable, assetacquire.tax, assetacquire.abatable,assetacquire.taxrate,assetacquire.discount,
	CASE
			WHEN assetacquire.flag & 2 <> 0 THEN 'R'
			ELSE 'N'
	END,
	CASE
			WHEN assetacquire.flag & 1 <> 0 THEN 'S'
			ELSE 'N'
	END,
	assetloadmotive.codemot, assetloadmotive.description,	assetacquire.adate,
	assetload.idreg, assetloadkind.codeassetloadkind,assetload.yassetload ,assetload.nassetload ,
	CASE
			WHEN asset.flag & 4 <> 0 THEN 'S'
			ELSE 'N'
	END,
	assetunloadkind.codeassetunloadkind, assetunload.yassetunload, assetunload.nassetunload,
	assetunloadmotive.codemot,assetunloadmotive.description,asset.txt	
	FROM asset
	JOIN assetacquire
		ON assetacquire.nassetacquire = asset.nassetacquire
	JOIN inventorytree
		ON inventorytree.idinv = assetacquire.idinv
	JOIN inventory
		ON inventory.idinventory = assetacquire.idinventory
	JOIN inventoryagency
		ON inventoryagency.idinventoryagency = inventory.idinventoryagency
	JOIN inventorykind
		ON inventorykind.idinventorykind = inventory.idinventorykind
	JOIN inventorytreelink
		ON inventorytreelink.idchild = assetacquire.idinv
		AND inventorytreelink.nlevel=1
	JOIN inventorytree inventorytree1
		ON inventorytree1.idinv = inventorytreelink.idparent
	LEFT OUTER JOIN assetload
		ON assetacquire.idassetload = assetload.idassetload
	LEFT OUTER JOIN assetloadkind
		ON assetloadkind.idassetloadkind = assetload.idassetloadkind
	LEFT OUTER JOIN assetunload
		ON asset.idassetunload = assetunload.idassetunload
	LEFT OUTER JOIN assetunloadkind
		ON assetunloadkind.idassetunloadkind = assetunload.idassetunloadkind
	LEFT OUTER JOIN assetlocation
		ON assetlocation.idasset = asset.idasset
		AND assetlocation.start IS NULL
	LEFT OUTER JOIN location
		ON location.idlocation = assetlocation.idlocation
	LEFT OUTER JOIN assetmanager
		ON assetmanager.idasset = asset.idasset
		AND assetmanager.start IS NULL
	LEFT OUTER JOIN asset asset_prev
		ON asset.idasset_prev = asset_prev.idasset
		AND asset.idpiece_prev = asset_prev.idpiece
	LEFT OUTER JOIN assetacquire assetacquire_prev
		ON asset_prev.nassetacquire = assetacquire_prev.nassetacquire
	LEFT OUTER JOIN inventory inventory_prev
		ON inventory_prev.idinventory = assetacquire_prev.idinventory
	LEFT OUTER JOIN inventoryagency as inventoryagency_prev
		ON inventoryagency_prev.idinventoryagency = inventory.idinventoryagency
	LEFT OUTER JOIN  inventorykind as inventorykind_prev
		ON inventorykind_prev.idinventorykind = inventory.idinventorykind
	LEFT OUTER JOIN asset asset_next
		ON asset.idasset = asset_next.idasset_prev
		AND asset.idpiece = asset_next.idpiece_prev
	LEFT OUTER JOIN assetacquire assetacquire_next
		ON asset_next.nassetacquire = assetacquire_next.nassetacquire
	LEFT OUTER JOIN inventory inventory_next
		ON inventory_next.idinventory = assetacquire_next.idinventory
	LEFT OUTER JOIN inventoryagency as inventoryagency_next
		ON inventoryagency_next.idinventoryagency = inventory.idinventoryagency
	LEFT OUTER JOIN  inventorykind  as inventorykind_next
		ON inventorykind_next.idinventorykind = inventory.idinventorykind
	LEFT OUTER JOIN manager
		ON manager.idman = assetmanager.idman
	LEFT OUTER JOIN location CL on CL.idlocation = 
		(SELECT TOP 1 idlocation
		FROM assetlocation WHERE assetlocation.idasset = asset.idasset
		ORDER BY start desc)
	LEFT OUTER JOIN manager CM ON CM.idman = 
		(SELECT TOP 1 idman
		FROM assetmanager
		WHERE assetmanager.idasset = asset.idasset
		ORDER BY start desc)
	LEFT OUTER JOIN assetloadmotive 
		ON assetacquire.idmot = assetloadmotive.idmot
	LEFT OUTER JOIN assetunloadmotive 
		ON assetunload.idmot = assetunloadmotive.idmot
	LEFT OUTER JOIN registry assetunloadreg 
		ON assetunload.idreg = assetunloadreg.idreg
	WHERE (assetacquire.idinventory = @idinventory or @idinventory is null)
AND (asset.ninventory >= @fromninv OR @fromninv is null)
AND (asset.ninventory <= @toninv OR @toninv is null)

-- aggiorna valore originale
	DECLARE @idasset int
	DECLARE @idpiece int
	DECLARE @originalamount  decimal (19,2)
	DECLARE rowcursor INSENSITIVE CURSOR FOR
		SELECT 	idasset,idpiece
		FROM #result
		FOR READ ONLY
	OPEN rowcursor FETCH  NEXT FROM rowcursor 
	INTO @idasset,@idpiece
	WHILE @@FETCH_STATUS = 0
		BEGIN 
			EXECUTE get_originalassetvalue @idasset,@idpiece,'S',@originalamount out 
			UPDATE #result 
			SET	historical = ISNULL(@originalamount,0)
			WHERE 	idasset = @idasset
			FETCH NEXT FROM rowcursor INTO  @idasset,@idpiece
		END 
	DEALLOCATE rowcursor
	
	SELECT
	[dbo].GetStringFormatted(tipocespite,1) as tipocespite,
	[dbo].GetStringFormatted(codiceinv,20) as codiceinv,
	[dbo].GetStringFormatted(descrinv,50)  as descrinv,
	[dbo].GetStringFormatted(codeinvkind,20)  as codeinvkind,
	[dbo].GetStringFormatted(descrinvkind,50) as descrinvkind,
	[dbo].GetStringFormatted(codeinvagency,20) as codeinvagency,
	[dbo].GetStringFormatted(descrinvagency,150) as descrinvagency,
	[dbo].GetStringFormatted(numinv,8)  as numinv,
	[dbo].GetStringFormatted(nprogr,5)  as nprogr,
	[dbo].GetStringFormatted(codiceinv_prec,20)  as codiceinv_prec, 
	[dbo].GetStringFormatted(descrinv_prec,50) as descrinv_prec, 
	[dbo].GetStringFormatted(codeinvkind_prec,2)  as codeinvkind_prec,
	[dbo].GetStringFormatted(descrinvkind_prec,50) as descrinvkind_prec,
	[dbo].GetStringFormatted(codeinvagency_prec,20) as codeinvagency_prec,
	[dbo].GetStringFormatted(descrinvagency_prec,150)  as descrinvagency_prec,
	[dbo].GetStringFormatted(numinv_prec,8) as numinv_prec,
	[dbo].GetStringFormatted(nprogr_prec,5)  as nprogr_prec,
	[dbo].GetStringFormatted(codiceinv_succ,20) as codiceinv_succ,
	[dbo].GetStringFormatted(descrinv_succ,50) as descrinv_succ,
	[dbo].GetStringFormatted(codeinvkind_succ,20) as codeinvkind_succ,
	[dbo].GetStringFormatted(descrinvkind_succ,50)  as descrinvkind_succ,
	[dbo].GetStringFormatted(codeinvagency_succ,20) as codeinvagency_succ,
	[dbo].GetStringFormatted(descrinvagency_succ,150) as descrinvagency_succ, 
	[dbo].GetStringFormatted(numinv_succ,8) as numinv_succ,
	[dbo].GetStringFormatted(nprogr_succ,5) as nprogr_succ,
	[dbo].GetData(inizioesist) as inizioesist,
	[dbo].GetStringFormatted(codiceclass,20) as codiceclass,
	[dbo].GetStringFormatted(descrizione,150) as descrizione,
	[dbo].GetDecimal_19_2(impon,22) as impon,
	[dbo].GetDecimal_19_2(iva,22) as iva, 
	[dbo].GetDecimal_19_2(ivadetr,22) as ivadetr,
	[dbo].GetDecimal_19_2(ivaperc,22) as ivaperc,
	[dbo].GetDecimal_19_2(scontoperc,22) as scontoperc,
	[dbo].GetStringFormatted(codicecausalecar,10)  as codicecausalecar,
	[dbo].GetStringFormatted(descrcausalecar,30) as descrcausalecar,
	[dbo].GetInt(codicecedente,10) as codicecedente,
	[dbo].GetData(datacar) as datacar,
	[dbo].GetStringFormatted(posseduto,1)  as posseduto,
	[dbo].GetStringFormatted(includibuonocar,1)  as includibuonocar,
	[dbo].GetStringFormatted(annobuonocar,4) as annobuonocar,
	[dbo].GetStringFormatted(numbuonocar,8) as numbuonocar,
	[dbo].GetStringFormatted(responsabile,150) as responsabile,
	[dbo].GetStringFormatted(codeubic,50) as codeubic,
	[dbo].GetStringFormatted(includibuonoscar,1) as includibuonoscar,
	[dbo].GetStringFormatted(codicetipobuonoscar,20) as codicetipobuonoscar,
	[dbo].GetStringFormatted(annobuonoscar,4)  as annobuonoscar,
	[dbo].GetStringFormatted(numbuonoscar,8) as numbuonoscar,
	[dbo].GetStringFormatted(note,400) as note,
	[dbo].GetDecimal_19_2(historical,22) as historical 
	FROM #result
END


GO

print '[exp_asset_importazione] OK'

