if object_id('[exp_riepilogoiva]') is not null
	drop PROCEDURE [exp_riepilogoiva]
go

CREATE PROCEDURE [exp_riepilogoiva]
	@idivaregisterkind int,
	@codeinvkind varchar(20),
	@year int,
	@startmonth int,
	@stopmonth int,
    @unified  char(1),
    @codeivaregisterkind  varchar(20)      
AS  BEGIN
	IF (@unified ='S')
	BEGIN
			SET @idivaregisterkind = ISNULL((SELECT idivaregisterkind FROM ivaregisterkind WHERE idivaregisterkindunified = @idivaregisterkind)
										, (SELECT idivaregisterkind FROM ivaregisterkind WHERE codeivaregisterkind = @codeivaregisterkind))
	END
 
	--exec exp_riepilogoiva;1 5, null, 2010, 1, 12, 'S','PROTOVEN'
	--exec [exp_unified_riepilogoiva];1 1, null, 2010, 1, 12,'S' 
	IF @startmonth IS NULL OR @startmonth < 1
	BEGIN
		SET @startmonth = 1
	END
	IF @startmonth > 12
	BEGIN
		SET @startmonth = 12
	END
	IF @stopmonth IS NULL OR @stopmonth < 1
	BEGIN
		SET @stopmonth = 1
	END
	IF @stopmonth > 12
	BEGIN
		SET @stopmonth = 12
	END
	-- Tabella di output dove confluiscono tutte le fatture e note di credito partecipanti alla liquidazione
	CREATE TABLE #invoicedet
	(
		label varchar(50),
		idinvkind int,
		invoicekind varchar(50),
		yinv int,
		ninv int,
		rownum int,
		adate datetime,
		competencydate datetime, 
		registerclass char(1), --tipo registro A/V
		kind char(1), --tipo fattura A/V
		flagmixed char(1),
		flagdeferred char(1),
		flagvariation char(1),
		taxabletotal decimal(19,2),
		ivagross decimal(19,2),
		ivaunabatable decimal(19,2), --unabatable corrente, applicare segno
		ivaabatable decimal(19,2),   -- calcolato qui
		idivaregisterkind int, 
		idivakind int,
		ivakind varchar(50),
		flagintracom char(1),
		reverse_charge char(1),
		doc varchar(35),
		docdate smalldatetime,	
		registry varchar(100),
		description varchar(150),
		va3type char(1),
		intrastatoperationkind  char(1),  -- codice operazione intrastat
