		idintrastatpaymethod, -- dalla fattura
		idintrastatsupplymethod,
		iso_payment,
		idintrastatkind,
		idintrastatmeasure,
		idintrastatcode,
		iso_destination,
		iso_origin,
		iso_provenance,
		idcountry_destination,
		idcountry_origin,
