CREATE     PROCEDURE [rpt_unified_sitpatrim_generale]
(
	@year int,
	@codinventoryagency int,
	@date datetime,
	@showmotive char(1),
	@firstyear int,  ---memorizzare per Lecce l'esercizio 2009 direttamente sui Parametri.
    @unified char(1) -- consolidamento dei dati 
)
AS BEGIN
-- exec [rpt_unified_sitpatrim_generale] 2011, null, '2011-31-12', 'S', 2009, 'N'
IF (@unified <> 'S')
BEGIN
        EXEC rpt_sitpatrim_generale @year,@codinventoryagency, @date, @showmotive,@firstyear
        RETURN
END 

CREATE TABLE #unified (
	iddbdepartment  varchar(50),
    departmentname  varchar(150),
	codinventoryagency varchar(20),
	descinventoryagency varchar(150),
	idsor int,
	codesor varchar(50),
	nlevel int,
	idmot int,
	motive varchar(50),
	description varchar(150),
	initialamount decimal(19,2),
	amountimprove decimal(19,2),
	amountdecrease decimal(19,2),
	ammortizationpre decimal(19,2),
	all_amortization_pre decimal(19,2),
	ammortizationpost decimal(19,2),
	stop datetime
)

DECLARE @iddbdepartment varchar(50)
DECLARE @departmentname varchar(150)
DECLARE crsdepartment  cursor LOCAL STATIC FOR 
SELECT iddbdepartment, description FROM dbdepartment 
WHERE (start is null or start <= @year ) AND ( stop is null or stop >= @year)
FOR READ ONLY
OPEN crsdepartment
FETCH NEXT FROM crsdepartment INTO @iddbdepartment, @departmentname
WHILE @@fetch_status=0 begin
	DECLARE @dip_nomesp varchar(300)
        SET @dip_nomesp = '['+@iddbdepartment+']'+ '.rpt_sitpatrim_generale'
PRINT @iddbdepartment
		INSERT INTO #unified (
                codinventoryagency,
				descinventoryagency,
				idsor,
				codesor,
				nlevel,
				idmot,
				motive,
				description,
				initialamount,
				amountimprove,
				amountdecrease,
				ammortizationpre,
				all_amortization_pre,
				ammortizationpost,
				stop
		)
		EXEC @dip_nomesp  @year,@codinventoryagency, @date, @showmotive,@firstyear
		UPDATE #unified set iddbdepartment = @iddbdepartment,  departmentname  = @departmentname
		WHERE #unified.iddbdepartment is null
	FETCH NEXT FROM crsdepartment INTO @iddbdepartment,@departmentname
end
DEALLOCATE crsdepartment
-- SELECT * FROM #unified
UPDATE #unified set codinventoryagency = null, descinventoryagency = null   -- consolida su tutti gli enti
  
	SELECT 
		#unified.codinventoryagency,
		#unified.descinventoryagency,
		#unified.idsor,
		#unified.codesor,
		#unified.nlevel,
		#unified.idmot,
		#unified.motive,
		#unified.description,
		ISNULL(SUM(#unified.initialamount),0) as 'initialamount',
		ISNULL(SUM(#unified.amountimprove),0) as 'amountimprove',
		ISNULL(SUM(#unified.amountdecrease),0)  as 'amountdecrease',
		ISNULL(SUM(#unified.ammortizationpre),0)  as 'ammortizationpre',
		ISNULL(SUM(#unified.all_amortization_pre),0) as 'all_amortization_pre' ,
		ISNULL(SUM(#unified.ammortizationpost),0)  as 'ammortizationpost',
		#unified.stop as 'stop'
		FROM #unified	
	GROUP BY 	#unified.codinventoryagency,#unified.descinventoryagency,
				#unified.idsor,#unified.codesor, #unified.nlevel, #unified.idmot,
				#unified.motive,#unified.description,#unified.stop
	ORDER BY ISNULL(#unified.codesor,#unified.idsor)
	 
DROP TABLE #unified
END

GO

print '[rpt_unified_sitpatrim_generale] OK'

