if object_id('[compute_csa_versamenti]') is not null
	drop PROCEDURE [compute_csa_versamenti]
go

CREATE  PROCEDURE [compute_csa_versamenti]
(
	@ayear int,
	@idcsa_import int
)
AS BEGIN
-- ELABORAZIONE DEI VERSAMENTI: a partire dal file csa_importver vengono generati i movimenti finanziari 
-- di spesa/entrata relativi a:
-- fase 1) generazione dei movimenti finanziari di spesa per il versamento di CONTRIBUTI E RITENUTE 
-- con transito da partite di giro e righe positive
-- fase 2) generazione dei movimenti finanziari di spesa per il versamento di RECUPERI con transito da partite di giro
-- fase 3) generazione dei movimenti finanziari di spesa per il versamento di CONTRIBUTI 
-- SENZA transito da partite di giro (LIQUID. DIRETTA) e con IMPUTAZIONE NORMALE, righe positive
-- fase 4) generazione dei movimenti finanziari di spesa per il versamento di CONTRIBUTI, righe positive
-- SENZA transito da partite di giro (LIQUID. DIRETTA) e IMPUTAZIONE tramite MOVIMENTO FINANZIARIO COSTO DA AGGANCIARE
-- fase 4BIS) generazione dei movimenti finanziari di spesa per il versamento di CONTRIBUTI, righe positive
-- SENZA transito da partite di giro (LIQUID. DIRETTA) e IMPUTAZIONE 
-- ove presente tabella di ripartizione in csa_contracttaxexpense
-- fase 5) generazione dei movimenti finanziari di entrata per l'incasso di RITENUTE dall'Erario  (righe negative del file versamenti)
-- fase 6) generazione dei movimenti finanziari di entrata per l'incasso di CONTRIBUTI dall'Erario  (righe negative del file versamenti)
-- fase 7) generazione dei movimenti finanziari di entrata post-versamento di RECUPERI con transito da partite di giro
DECLARE @csa_flaggroupby_income char(1)
DECLARE @csa_flaggroupby_expense char(1)
SELECT 
	@csa_flaggroupby_income	 = csa_flaggroupby_income,
	@csa_flaggroupby_expense = csa_flaggroupby_expense
FROM config
WHERE ayear = @ayear
DECLARE @yimportstr varchar(10)
DECLARE @nimportstr varchar(10)
SELECT @yimportstr = CONVERT(varchar(10),yimport),@nimportstr = convert(varchar(10),nimport) FROM  csa_import WHERE idcsa_import = @idcsa_import

CREATE TABLE #automov_exp_ungrouped
(
	parentidexp int, 
	idreg int,
	idfin int,
	idsor_siope int,
	idupb varchar(36),
	amount decimal(19,2),
	movkind	int,
	description varchar(200),
	idcsa_contractkind int,
	idcsa_contract int,
	idcsa_agency int,
	idcsa_agencypaymethod int,
	idacc varchar(36),
	idunderwriting int
)
CREATE TABLE #automov_inc_ungrouped
(
	idreg int,
	idfin int,
	idsor_siope int,
	idupb varchar(36),
	amount decimal(19,2),
	movkind int,
	description varchar(200),
	idacc varchar(36),
	idcsa_agency int,
	idcsa_contractkind int,
	idcsa_contract int,
	idunderwriting int
)
-- fase 1) generazione dei movimenti finanziari di spesa per il versamento di 
-- CONTRIBUTI E RITENUTE con transito da partite di giro
INSERT INTO #automov_exp_ungrouped
(	
	idreg,
	idfin,
	idsor_siope,
	idupb,
	amount,
	movkind,
	description,
	idacc,
	idcsa_agency,
	idcsa_agencypaymethod,
	idcsa_contractkind,
	idcsa_contract
)
SELECT
	idreg_agency,  -- prenderò la modalità di pagamento configurata per l'ente CSA di versamento
	idfin_expense,
	idsor_siope_expense,
	'0001', --SEMPRE PER PARTITE DI GIRO
	importo,
	4,
	CASE ISNULL(@csa_flaggroupby_expense,'N')
		WHEN 'S' THEN SUBSTRING('Versamento Imposte/Recuperi '+ vocecsa +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr,1,150)
		ELSE 'Versamento Imposte/Recuperi ' +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr
	END,
	idacc_expense,
	idcsa_agency,
	idcsa_agencypaymethod,
	idcsa_contractkind,
	idcsa_contract
FROM 	csa_importver
WHERE   
 	idcsa_import = @idcsa_import
AND importo > 0
AND (idfin_expense IS NOT NULL AND idfin_income IS NOT NULL 
AND ISNULL(csa_importver.flagclawback,'N') = 'N') -- escludo i recuperi
-- fase 2) generazione dei movimenti finanziari di spesa per il versamento 
-- di RECUPERI con transito da partite di giro
INSERT INTO #automov_exp_ungrouped
(	
	idreg,
	idfin,
	idsor_siope,
	idupb,
	amount,
	movkind,
	description,
	idacc,
	idcsa_agency,
	idcsa_agencypaymethod,
	idcsa_contractkind,
	idcsa_contract
)
SELECT
	idreg_agency,  -- prenderò la modalità di pagamento configurata per l'ente CSA di versamento
	idfin_expense,
	idsor_siope_expense,
	'0001', --SEMPRE PER PARTITE DI GIRO
	importo,
	4,
	CASE ISNULL(@csa_flaggroupby_expense,'N')
		WHEN 'S' THEN SUBSTRING('Versamento Imposte/Recuperi '+ vocecsa +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr,1,150)
		ELSE 'Versamento Imposte/Recuperi ' +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr
	END,
	idacc_internalcredit,
	idcsa_agency,
	idcsa_agencypaymethod,
	idcsa_contractkind,
	idcsa_contract
FROM 	csa_importver
WHERE   
 	idcsa_import = @idcsa_import
AND importo > 0
AND idfin_expense IS NOT NULL AND idfin_income IS NOT NULL 
--AND idacc_internalcredit IS NOT NULL 
AND idfin_incomeclawback IS NOT NULL
AND ISNULL(flagdirectcsaclawback,'N') = 'N' -- recupero su partite di giro
AND (ISNULL(csa_importver.flagclawback,'N') = 'S') -- recuperi

-- fase 3) generazione dei movimenti finanziari di spesa per il versamento di CONTRIBUTI 
-- SENZA transito da partite di giro (LIQUID. DIRETTA) e con IMPUTAZIONE NORMALE
INSERT INTO #automov_exp_ungrouped
(	parentidexp, 
	idreg,
	idfin,
	idsor_siope,
	idupb,
	amount,
	movkind,
	description,
	idacc,
	idcsa_agency,
	idcsa_agencypaymethod,
	idcsa_contractkind,
	idcsa_contract,
	idunderwriting
)
SELECT
	NULL,
	idreg_agency,  -- modalità pagamento configurata per l'ente CSA di versamento
	idfin_cost,
	idsor_siope_cost,
	idupb, -- CONFIGURATO NELLA SCHEDA CONTRIBUTI DEL CONTRATTO O NEL TIPO CONTRATTO
	importo,
	4,
	CASE ISNULL(@csa_flaggroupby_expense,'N')
		WHEN 'S' THEN SUBSTRING('Versamento Imposte/Recuperi '+ vocecsa +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr,1,150)
		ELSE 'Versamento Imposte/Recuperi ' +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr
	END,
	idacc_expense,
	idcsa_agency,
	idcsa_agencypaymethod,
	idcsa_contractkind,
	idcsa_contract,
	idunderwriting
FROM csa_importver
WHERE   
 	idcsa_import = @idcsa_import
AND importo > 0
AND (idfin_cost IS NOT NULL AND idexp_cost IS NULL AND idfin_income is null) 
-- fase 4) generazione dei movimenti finanziari di spesa per il versamento di CONTRIBUTI 
-- SENZA transito da partite di giro (LIQUID. DIRETTA) e IMPUTAZIONE TRAMITE MOVIMENTO FINANZIARIO COSTO DA AGGANCIARE
INSERT INTO #automov_exp_ungrouped
(	parentidexp, 
	idreg,
	idfin,
	idsor_siope,
	idupb,
	amount,
	movkind,
	description,
	idacc,
	idcsa_agency,
	idcsa_agencypaymethod,
	idcsa_contractkind,
	idcsa_contract,
	idunderwriting
)
SELECT
	E.idexp,
	ISNULL(E.idreg, idreg_agency), -- modalità pagamento configurata per l'ente CSA di versamento
	ISNULL(EY.idfin, csa_importver.idfin_cost), 
	csa_importver.idsor_siope_cost,
	ISNULL(EY.idupb, csa_importver.idupb), -- CONFIGURATO NELLA SCHEDA CONTRIBUTI DEL CONTRATTO O NEL TIPO CONTRATTO
	importo,
	4,
	CASE ISNULL(@csa_flaggroupby_expense,'N')
		WHEN 'S' THEN SUBSTRING('Versamento Imposte/Recuperi '+ vocecsa +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr,1,150)
		ELSE 'Versamento Imposte/Recuperi ' +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr
	END,
	idacc_expense,
	idcsa_agency,
	idcsa_agencypaymethod,
	idcsa_contractkind,
	idcsa_contract,
	csa_importver.idunderwriting
FROM csa_importver
JOIN expense E
	ON csa_importver.idexp_cost = E.idexp
JOIN expenseyear EY
	ON EY.idexp = csa_importver.idexp_cost
WHERE  	
	idcsa_import = @idcsa_import
	AND EY.ayear = @ayear
	AND importo > 0
	AND (idfin_cost IS  NULL AND idexp_cost IS NOT NULL AND idfin_income is null) 
-- fase 4BIS) generazione dei movimenti finanziari di spesa per il versamento di CONTRIBUTI 
-- SENZA transito da partite di giro (LIQUID. DIRETTA) 
--ove presente tabella di ripartizione in csa_contracttaxexpense
INSERT INTO #automov_exp_ungrouped
(	parentidexp, 
	idreg,
	idfin,
	idsor_siope,
	idupb,
	amount,
	movkind,
	description,
	idacc,
	idcsa_agency,
	idcsa_agencypaymethod,
	idcsa_contractkind,
	idcsa_contract,
	idunderwriting
)
SELECT
	E.idexp,
	ISNULL(E.idreg, idreg_agency), -- modalità pagamento configurata per l'ente CSA di versamento
	ISNULL(EY.idfin, csa_importver.idfin_cost), 
	csa_importver.idsor_siope_cost,
	ISNULL(EY.idupb, csa_importver.idupb), -- CONFIGURATO NELLA SCHEDA CONTRIBUTI DEL CONTRATTO O NEL TIPO CONTRATTO
	ROUND(csa_importver.importo*csa_contracttaxexpense.quota,2),
	4,
	CASE ISNULL(@csa_flaggroupby_expense,'N')
		WHEN 'S' THEN SUBSTRING('Versamento Imposte/Recuperi '+ vocecsa +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr,1,150)
		ELSE 'Versamento Imposte/Recuperi ' +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr
	END,
	csa_importver.idacc_expense,
	csa_importver.idcsa_agency,
	csa_importver.idcsa_agencypaymethod,
	csa_importver.idcsa_contractkind,
	csa_importver.idcsa_contract,
	csa_importver.idunderwriting
FROM csa_importver
JOIN csa_contracttaxexpense
		ON csa_importver.idcsa_contract = csa_contracttaxexpense.idcsa_contract
		AND csa_importver.idcsa_contracttax = csa_contracttaxexpense.idcsa_contracttax
		AND csa_importver.ayear = csa_contracttaxexpense.ayear
JOIN expense E
	ON csa_contracttaxexpense.idexp = E.idexp
JOIN expenseyear EY
	ON EY.idexp = E.idexp
WHERE  	
	idcsa_import = @idcsa_import
	AND EY.ayear = @ayear
	AND importo > 0
	AND (idfin_cost IS  NULL AND idexp_cost IS NULL AND idfin_income is null) 
	
-- 5) fase  generazione dei movimenti finanziari di entrata per l'incasso di RITENUTE dall'Erario (negativi) 
INSERT INTO #automov_inc_ungrouped
(	
	idreg,
	idfin,
	idsor_siope,
	idupb,
	amount,
	movkind,
	description,
	idacc,
	idcsa_agency,
	idcsa_contractkind,
	idcsa_contract
)
SELECT
	idreg_agency,  --anagrafica Ente CSA
	idfin_income, 
	idsor_siope_income,
	'0001',
	-importo,
	9,
	CASE ISNULL(@csa_flaggroupby_income,'N')
		WHEN 'S' THEN SUBSTRING('Incasso Ritenute da Erario ' + vocecsa +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr,1,150)
		ELSE 'Incasso Ritenute da Erario' +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr
	END,
	idacc_agency_credit, --credito verso erario
 	idcsa_agency,
	idcsa_contractkind,
	idcsa_contract
FROM csa_importver
WHERE idcsa_import = @idcsa_import
AND (idfin_cost IS NULL AND idexp_cost IS NULL) -- no contributi
AND (idfin_income IS NOT NULL AND importo < 0)
AND (ISNULL(flagclawback,'N') <> 'S') -- no recuperi
-- 6) fase  generazione dei movimenti finanziari di entrata per l'incasso di CONTRIBUTI dall'Erario (negativi)
INSERT INTO #automov_inc_ungrouped
(	
	idreg,
	idfin,
	idsor_siope,
	idupb,
	amount,
	movkind,
	description,
	idacc,
	idcsa_agency,
	idcsa_contractkind,
	idcsa_contract
)
SELECT
	idreg_agency,  --anagrafica Ente CSA
	idfin_incomeclawback, 
	idsor_siope_incomeclawback,
	'0001',
	-importo,
	10,
	CASE ISNULL(@csa_flaggroupby_income,'N')
		WHEN 'S' THEN SUBSTRING('Incasso Ritenute da Erario ' + vocecsa +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr,1,150)
		ELSE 'Incasso Ritenute da Erario' +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr
	END,
	idacc_agency_credit, --credito verso erario
 	idcsa_agency,
 	idcsa_contractkind,
	idcsa_contract
FROM csa_importver
WHERE idcsa_import = @idcsa_import
AND (idfin_cost IS NOT NULL OR idexp_cost IS NOT NULL) -- contributi
AND (idfin_incomeclawback IS NOT NULL AND importo < 0)
AND (ISNULL(flagclawback,'N') <> 'S') -- no recuperi
-- fase 7) generazione dei movimenti finanziari di entrata post-versamento di RECUPERI 
-- con transito da partite di giro
INSERT INTO #automov_inc_ungrouped
(	
	idreg,
	idfin,
	idsor_siope,
	idupb,
	amount,
	movkind,
	description,
	idacc,
	idcsa_agency,
	idcsa_contractkind,
	idcsa_contract
)
SELECT
	idreg_agency, 
	idfin_incomeclawback, 
	idsor_siope_incomeclawback,
	idupb, -- configurato in csa_incomesetup specifico per i Recuperi
	importo,
	6,
	CASE ISNULL(@csa_flaggroupby_income,'N')
		WHEN 'S' THEN SUBSTRING('Incasso Recuperi ' + vocecsa +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr,1,150)
		ELSE 'Incasso Recuperi '  +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr
	END,
	idacc_internalcredit,
	idcsa_agency,
	idcsa_contractkind,
	idcsa_contract
FROM 	csa_importver
WHERE   
 	idcsa_import = @idcsa_import
AND importo > 0
AND (idfin_incomeclawback IS NOT NULL)
AND ISNULL(flagdirectcsaclawback,'N') = 'N' -- recupero su partite di giro
AND (ISNULL(flagclawback,'N') = 'S') --recuperi
CREATE TABLE #automov
( 
	parentidexp int, 
	idreg int,
	idfin int, 
	idsor_siope int,
	idupb varchar(36),
	amount decimal(19,2),
	movkind int,
	description varchar(200),
	idacc varchar(36),
	idcsa_agency int,
	idcsa_agencypaymethod int,
	idcsa_contractkind int,
	idcsa_contract int,
	idunderwriting int
)
INSERT INTO #automov 
(
	parentidexp,
	idreg,
	idfin, 
	idsor_siope,
	idupb,
	amount,
	movkind,
	description,
	idacc,
	idcsa_agency,
	idcsa_agencypaymethod,
	idcsa_contractkind,
	idcsa_contract,
	idunderwriting
)
SELECT  parentidexp, idreg, idfin, idsor_siope, idupb, SUM(amount), movkind, description, idacc, idcsa_agency,
	idcsa_agencypaymethod, idcsa_contractkind,idcsa_contract,idunderwriting
FROM   #automov_exp_ungrouped
GROUP BY idreg, idfin, idsor_siope, idupb, description, movkind,idacc, idcsa_agency,
         idcsa_agencypaymethod, parentidexp, idcsa_contractkind,idcsa_contract,idunderwriting

INSERT INTO #automov 
(
	idreg,
	idfin, 
	idsor_siope,
	idupb,
	amount,
	movkind,
	description,
	idacc,
	idcsa_agency,
	idcsa_contractkind,
	idcsa_contract,
	idunderwriting
)
SELECT idreg, idfin, idsor_siope, idupb, SUM(amount), movkind, description, idacc,idcsa_agency,idcsa_contractkind,
	idcsa_contract,idunderwriting
FROM   #automov_inc_ungrouped
GROUP BY movkind, idreg, idfin, idsor_siope, idupb, description, idacc, idcsa_agency,
		 idcsa_contractkind,idcsa_contract,idunderwriting

SELECT 
	CASE 
	     WHEN #automov.movkind =  4 THEN 'Spesa'
	     WHEN #automov.movkind IN (6,9,10) THEN 'Entrata' 
	END as kind,
	#automov.movkind,
	null as parentidinc,
	parentidexp as parentidexp,
	#automov.idreg,
	R.title AS registry,
	idcsa_agency,
	idcsa_agencypaymethod,
	#automov.idfin,
	F.codefin,
	#automov.idsor_siope as idsor,
	S.sortcode,
	S2.idsor as parentidsor,
	S2.sortcode as parentsortcode,
	ISNULL(#automov.idupb,'0001') as idupb,
	U.codeupb, 
	#automov.description,
	#automov.idacc,
	A.codeacc,
    #automov.amount,
    #automov.idcsa_contractkind,
	#automov.idcsa_contract,
	#automov.idunderwriting,
	UN.codeunderwriting
FROM #automov 
LEFT OUTER JOIN registry R
	ON R.idreg = #automov.idreg
LEFT OUTER JOIN fin F
	ON F.idfin = #automov.idfin
LEFT OUTER JOIN upb U
	ON U.idupb = #automov.idupb
LEFT OUTER JOIN account A
	ON A.idacc = #automov.idacc
LEFT OUTER JOIN sorting S
	ON S.idsor = #automov.idsor_siope
left outer join sortingkind SK 
	on S.idsorkind=SK.idsorkind
left outer join sorting S2 
	on S2.sortcode=S.sortcode and S2.idsorkind=SK.idparentkind
LEFT OUTER JOIN underwriting UN
	ON UN.idunderwriting = #automov.idunderwriting
ORDER BY  R.title,F.codefin, U.codeupb, A.idacc
END


