if object_id('[rebuild_incometotal]') is not null
	drop PROCEDURE [rebuild_incometotal]
go

CREATE                                      PROCEDURE [rebuild_incometotal]
(@ayear int = null
)
AS BEGIN
DELETE from incometotal where ( (@ayear is null) or (ayear=@ayear))
DECLARE @finphase tinyint
SELECT @finphase = incomefinphase FROM uniconfig
INSERT INTO incometotal 
(
	idinc,
	ayear,
	curramount,
	flag
)
SELECT
	incomeyear.idinc,
	incomeyear.ayear,
	incomeyear.amount,
	CASE
		WHEN income.nphase < @finphase
		THEN 0
		WHEN (SELECT e2.ymov
			FROM incomelink
			JOIN income e2
				ON incomelink.idparent = e2.idinc
			WHERE incomelink.idchild = income.idinc
			AND incomelink.nlevel = @finphase) = incomeyear.ayear THEN 0
		ELSE 1
	END +
	CASE
		WHEN income.ymov = incomeyear.ayear THEN 2
		ELSE 0
	END 
FROM incomeyear
JOIN income
	ON incomeyear.idinc = income.idinc
WHERE  ( (@ayear is null) or (ayear=@ayear))
UPDATE incometotal
SET curramount = ISNULL(curramount, 0) +
ISNULL(
(
	SELECT SUM(amount)
	FROM incomevar
	WHERE incomevar.idinc = incometotal.idinc
		AND incomevar.yvar = incometotal.ayear
), 0)
WHERE  ( (@ayear is null) or (ayear=@ayear))
UPDATE incometotal
SET available = ISNULL(curramount, 0) -
ISNULL(
	(
	SELECT SUM(it2.curramount)
	FROM incometotal it2
	JOIN income
		ON income.idinc = it2.idinc
	WHERE it2.ayear=incometotal.ayear
		AND income.parentidinc = incometotal.idinc
	), 0)
WHERE  ( (@ayear is null) or (ayear=@ayear))
UPDATE incometotal
SET partitioned = 
ISNULL(
(
	SELECT SUM(amount)
	FROM creditpart
	JOIN config
		ON config.ayear = creditpart.ycreditpart
	JOIN income
		ON income.idinc = creditpart.idinc
	WHERE creditpart.idinc = incometotal.idinc
		AND creditpart.ycreditpart = incometotal.ayear
		AND income.nphase = config.assessmentphasecode
), 0)
WHERE ((@ayear is null) OR (ayear=@ayear))
AND (SELECT assessmentphasecode FROM config c
	WHERE c.ayear = incometotal.ayear) = 
	(SELECT i.nphase
	FROM income i 
	WHERE i.idinc = incometotal.idinc)
DECLARE @maxphase int
SET @maxphase =
ISNULL(
	(SELECT CONVERT(int,MAX(nphase)) FROM incomephase)
,0)
UPDATE incometotal
SET partitioned = 
ISNULL(
(
	SELECT SUM(amount)
	FROM proceedspart
	JOIN income
		ON income.idinc = proceedspart.idinc
	WHERE proceedspart.idinc = incometotal.idinc
		AND proceedspart.yproceedspart = incometotal.ayear
), 0)
WHERE   ( (@ayear is null) or (ayear=@ayear))
AND (SELECT i.nphase FROM income i WHERE i.idinc = incometotal.idinc) = @maxphase
END

GO

print '[rebuild_incometotal] OK'

