CREATE                TRIGGER [trigger_d_accountvardetail] ON [accountvardetail] FOR DELETE
AS BEGIN
	IF @@ROWCOUNT > 0
	BEGIN
     	DECLARE @yvar int		
		DECLARE @nvar int
		DECLARE @idsor int
		DECLARE @idacc varchar(38)
		DECLARE @amount decimal(19,2)
		DECLARE @paramamount decimal(19,2)
		SELECT 
		@yvar = yvar,
		@nvar = nvar,
		@idacc = idacc, 
		@idsor = idsor,
		@amount = -amount
		FROM deleted
		EXECUTE trg_upd_sortingtotal 
		@idsor,
		@idacc, 
		'previsionvariation', 
		@amount
	END
 END


