if object_id('[rpt_fondopsp_registro]') is not null
	drop PROCEDURE [rpt_fondopsp_registro]
go

CREATE                                  PROCEDURE [rpt_fondopsp_registro]
	@ayear	smallint,
	@idpettycash	int,
	@showupb char(1),
	@idupb varchar(36),
	@showchildupb char(1),
	@start	smalldatetime,
	@stop	smalldatetime
AS BEGIN
DECLARE @idupboriginal varchar(36)
SET @idupboriginal= @idupb
IF (@showchildupb = 'S') 
BEGIN
	SET @idupb=@idupb+'%' 
END
CREATE TABLE #pettycashreg
(
	noperation int,
	operation varchar(20),
	adate datetime,
	operationdescription varchar(200),
	idfin int,
	codefin varchar(50),	
	idupb varchar(36),
	codeupb varchar(50),	
	incomeamount decimal(19,2),	
	expenseamount decimal(19,2),
	doc varchar(50),
	docdate datetime,
	idexp int ,
	detail varchar(2000),
	nrestore int,
	yrestore int,
	kind char,
	idexpIx int,
	payment varchar(600) ,
	idman int
)
IF (DATEPART(yy, @start) <> @ayear OR DATEPART(mm, @start) <> 1	OR DATEPART(dd, @start) <> 1)
BEGIN
INSERT INTO #pettycashreg
(
	noperation,
	operation,
	adate,
	incomeamount,
	expenseamount
)
SELECT
	NULL,
	'Tot. prec.',
	DATEADD(dd, -1, @start),
	ISNULL(
		(SELECT ISNULL(SUM(amount),0)
		FROM pettycashoperation
		WHERE yoperation = @ayear
			AND pettycashoperation.idpettycash = @idpettycash
			AND (flag& 1)<>0 -- Apertura
			AND adate < @start)
	, 0.0) 
	+ 
	ISNULL(
		(SELECT ISNULL(SUM(amount),0)
		FROM pettycashoperation
		WHERE yoperation = @ayear
			AND pettycashoperation.idpettycash = @idpettycash
			AND (flag& 2)<>0 --Reintegro
			AND adate < @start)
	, 0),
	ISNULL(
		(SELECT  ISNULL(SUM(amount) ,0)
		FROM pettycashoperation
		WHERE yoperation = @ayear
			AND pettycashoperation.idpettycash = @idpettycash
			AND (flag& 4)<>0 -- Chiusura
			AND adate < @start)
	, 0) + 
	ISNULL(
		(SELECT ISNULL(SUM(amount),0)
		FROM pettycashoperation
		WHERE yoperation = @ayear
			AND pettycashoperation.idpettycash = @idpettycash
			AND (flag& 8)<>0 --Spesa
			AND adate < @start)
	, 0)
FROM pettycash
WHERE pettycash.idpettycash = @idpettycash
END
INSERT INTO #pettycashreg
(
	noperation,
	operation,
	adate,
	operationdescription,
	codefin,idfin,
	codeupb,idupb,
	incomeamount,
	expenseamount,
	doc,
	docdate,
	idexp,
	nrestore,
	yrestore,
	kind,
	idexpIx,
	idman
)
SELECT
	pettycashoperation.noperation,
	case 
		WHEN (pettycashoperation.flag& 1)<>0  THEN 'Apertura'
		WHEN (pettycashoperation.flag& 4)<>0  THEN 'Chiusura'
		WHEN (pettycashoperation.flag& 2)<>0  THEN 'Reintegro'
		WHEN (pettycashoperation.flag& 8)<>0  THEN 'Spesa'
	END,
	pettycashoperation.adate,
	pettycashoperation.description,
	fin.codefin,fin.idfin,
	upb.codeupb,upb.idupb,
	case 
		WHEN (pettycashoperation.flag& 1)<>0 THEN pettycashoperation.amount
		WHEN (pettycashoperation.flag& 4)<>0 THEN null
		WHEN (pettycashoperation.flag& 2)<>0 THEN pettycashoperation.amount
		WHEN (pettycashoperation.flag& 8)<>0 THEN null
	END,
	case 
		WHEN (pettycashoperation.flag& 1)<>0 THEN null
		WHEN (pettycashoperation.flag& 4)<>0 THEN pettycashoperation.amount
		WHEN (pettycashoperation.flag& 2)<>0 THEN null
		WHEN (pettycashoperation.flag& 8)<>0 THEN pettycashoperation.amount
	END,
	pettycashoperation.doc,
	pettycashoperation.docdate,
	pettycashoperation.idexp,
	pettycashoperation.nrestore,
	pettycashoperation.yrestore,
CASE
		WHEN (pettycashoperation.flag& 1)<>0  THEN 'A'
		WHEN (pettycashoperation.flag& 4)<>0  THEN 'C'
		WHEN (pettycashoperation.flag& 2)<>0  THEN 'R'
		WHEN (pettycashoperation.flag& 8)<>0  THEN 'S'
end ,
	expense.idexp,
	pettycashoperation.idman
FROM pettycashoperation
LEFT OUTER JOIN fin
	ON pettycashoperation.idfin = fin.idfin
LEFT OUTER JOIN upb
	ON pettycashoperation.idupb = upb.idupb
LEFT OUTER JOIN expense
	ON expense.idexp = pettycashoperation.idexp
LEFT OUTER JOIN expenseyear
	ON expense.idexp = expenseyear.idexp
	AND expenseyear.ayear = @ayear
WHERE pettycashoperation.yoperation = @ayear
	AND pettycashoperation.idpettycash = @idpettycash
	AND ((pettycashoperation.flag& 8)<>0 AND (upb.idupb like @idupb)
		OR (pettycashoperation.flag& 8)<>0 AND (expenseyear.idupb like @idupb)
		OR (pettycashoperation.flag& 8) = 0)
	AND pettycashoperation.adate between @start and @stop
-- Aggiornamento della voce di bilancio nel caso di operazione associata ad un movimento di spesa
UPDATE #pettycashreg
SET codefin = fin.codefin,
    codeupb = upb.codeupb,
	idexpIx = expenseyear.idexp,
	idupb = expenseyear.idupb
FROM fin
JOIN expenseyear
	ON fin.idfin = expenseyear.idfin
JOIN upb
	ON upb.idupb = expenseyear.idupb
WHERE expenseyear.idexp = #pettycashreg.idexp
	AND expenseyear.ayear = @ayear
-- Aggiornamento della voce di bilancio alle operazioni di Apertura e Chiusura interrogando le tabelle pettycashexpense e pettycashincome
UPDATE #pettycashreg
SET codefin = fin.codefin,
    codeupb = upb.codeupb,
	idupb = expenseyear.idupb
FROM pettycashexpense
JOIN expenseyear
	ON pettycashexpense.idexp = expenseyear.idexp
JOIN fin
	ON fin.idfin = expenseyear.idfin
JOIN upb
	ON upb.idupb = expenseyear.idupb
WHERE  expenseyear.ayear = @ayear
	and pettycashexpense.yoperation = @ayear 
	and pettycashexpense.noperation = #pettycashreg.noperation  
	and pettycashexpense.idpettycash=@idpettycash 
	and #pettycashreg.kind='A'
UPDATE #pettycashreg
SET codefin = fin.codefin,
    codeupb = upb.codeupb,
	idupb = incomeyear.idupb
FROM pettycashincome
JOIN incomeyear
	ON pettycashincome.idinc = incomeyear.idinc
JOIN fin
	ON fin.idfin = incomeyear.idfin
JOIN upb
	ON upb.idupb = incomeyear.idupb
WHERE  incomeyear.ayear = @ayear
	and pettycashincome.yoperation = @ayear 
	and pettycashincome.noperation = #pettycashreg.noperation  
	and pettycashincome.idpettycash=@idpettycash 
	and #pettycashreg.kind='C'

DECLARE @noperation int
DECLARE @nrestore int 
DECLARE @yrestore int
DECLARE @detail varchar(2000)

UPDATE #pettycashreg
SET detail =' (Op. nn. '
WHERE operation ='Reintegro' 
-- Elenca tutte le operazioni collegate al Reintegro
DECLARE cursore CURSOR FORWARD_ONLY for 
	SELECT noperation,nrestore,yrestore FROM #pettycashreg
	WHERE  nrestore is not null and yrestore is not null and operation!='Reintegro'
		OPEN cursore
	FETCH NEXT FROM cursore 
	INTO @noperation, @nrestore, @yrestore
 
	WHILE (@@fetch_status=0) BEGIN
	
	UPDATE 	#pettycashreg set
	  detail = isnull(detail,'') + isnull(convert(varchar(10),@noperation),'') + ', '
	 WHERE noperation=@nrestore 
		FETCH NEXT FROM cursore 
		INTO @noperation, @nrestore, @yrestore
	END
CLOSE cursore
DEALLOCATE cursore
UPDATE #pettycashreg SET detail =substring(detail,1,len(detail)-1) + ')'
					WHERE operation ='Reintegro' 
-- Elenca i numeri di mandato collegati al Reintegro/Apertura
/*UPDATE #pettycashreg SET detail = isnull(detail,'')+ ' mand. n.'
					WHERE operation='Reintegro' or operation='Apertura'*/
/*
UPDATE #pettycashreg SET payment = ' n° '
					WHERE operation='Reintegro' or operation='Apertura'
*/
DECLARE @npay int
DECLARE @ypay int
DECLARE @nph tinyint
SET @nph= (SELECT MAX(nphase) FROM expensephase)
DECLARE cursore CURSOR FORWARD_ONLY for 
	SELECT  #pettycashreg.noperation, payment.npay, expense.ymov, datepart(yy,#pettycashreg.adate) 
	FROM  #pettycashreg 
	JOIN pettycashexpense 
		ON #pettycashreg.noperation=pettycashexpense.noperation 
		AND datepart(yy,#pettycashreg.adate)=pettycashexpense.yoperation 
	JOIN expense 
		ON pettycashexpense.idexp=expense.idexp
	LEFT OUTER JOIN 
		expenselast
		ON expense.idexp = expenselast.idexp
	left outer join payment 
		on payment.kpay = expenselast.kpay
	WHERE 	expense.nphase=@nph  and pettycashexpense.idpettycash=@idpettycash 
		and #pettycashreg.operation in('Reintegro','Apertura')
	
	OPEN cursore
	FETCH NEXT FROM cursore 
	INTO @noperation, @npay, @ypay, @yrestore
	
	WHILE (@@fetch_status=0) BEGIN
		UPDATE 	#pettycashreg set
		payment = isnull(payment,' n° ') + isnull(convert(varchar(10),@npay),'') + ' '
		WHERE #pettycashreg.operation in('Reintegro','Apertura')
			and noperation=@noperation  and @npay is not null
		FETCH NEXT FROM cursore 
		INTO @noperation, @npay, @ypay, @yrestore
	END
CLOSE cursore
DEALLOCATE cursore
UPDATE #pettycashreg SET
	detail=  (SELECT ' (Reintegro n. ' + convert(varchar(10),nrestore) + ')' FROM pettycashoperation
	WHERE #pettycashreg.noperation=pettycashoperation.noperation and pettycashoperation.yoperation=@ayear and idpettycash=@idpettycash )
WHERE operation='Spesa' 
-- Valorizza il numero del mandato sulle singole operazioni di spesa
DECLARE @nphase INT
SELECT  @nphase = expenseregphase FROM uniconfig
-- al fine di valorizzare il numero di mandato delle operazioni di spesa, serve valorizzare l'idexp dell'impegno
UPDATE #pettycashreg 
SET  #pettycashreg.idexpIx	= e.idexp
FROM #pettycashreg po
	JOIN pettycashexpense pce
		ON  po.yrestore = pce.yoperation
		AND po.nrestore = pce.noperation
		AND @idpettycash = pce.idpettycash
	JOIN expense e
		ON  e.idexp = pce.idexp
		AND e.nphase = @nphase
    JOIN expenseyear EY
        ON EY.idexp = E.idexp
WHERE operation='Spesa' 
        AND EY.idfin = po.idfin AND EY.idupb = po.idupb 
		AND isnull(po.idman,0) = isnull(E.idman,0) -->>  va considerato anche il responsabile
        AND EY.ayear = @ayear
        AND po.nrestore IS NOT NULL

DECLARE @idexpIx int
DECLARE cursore CURSOR FORWARD_ONLY for 
	SELECT distinct payment.npay, #pettycashreg.idexpIx, #pettycashreg.noperation  
	FROM  #pettycashreg  
	JOIN  pettycashexpense pce 
		ON #pettycashreg.yrestore = pce.yoperation
		AND #pettycashreg.nrestore = pce.noperation     
	JOIN expense  
		ON expense.idexp = pce.idexp
	JOIN expenselast
		ON expenselast.idexp = expense.idexp
	JOIN payment
		ON payment.kpay = expenselast.kpay
	JOIN expenselink 
		ON expenselast.idexp = expenselink.idchild 
		AND expenselink.idparent = #pettycashreg.idexpIx 
	WHERE  pce.idpettycash = @idpettycash 
	
	OPEN cursore
	FETCH NEXT FROM cursore INTO @npay, @idexpIx,@noperation
	
 	
	WHILE (@@fetch_status=0) 
	BEGIN
		UPDATE #pettycashreg SET payment = isnull(payment,'') + ' n° '+isnull(convert(varchar(10),@npay),'') + '; '
		WHERE #pettycashreg.idexpIx = @idexpIx and #pettycashreg.noperation  = @noperation 
	FETCH NEXT FROM cursore INTO @npay, @idexpIx, @noperation
	END
CLOSE cursore
DEALLOCATE cursore
IF (@showupb <>'S') AND (@idupboriginal <> '%' ) AND (@showchildupb = 'S')
		UPDATE #pettycashreg SET  
			idupb = @idupboriginal,
			codeupb =(SELECT TOP 1 codeupb
				FROM #pettycashreg	
				WHERE idupb = @idupboriginal)
		WHERE idupb IS NOT NULL--> sul reintegro non deve avere effetto
	
IF (@showupb <>'S') and (@idupboriginal = '%') 
			UPDATE #pettycashreg SET  
			idupb = null,
			codeupb = null
SELECT
	noperation,
	@idpettycash as idpettycash,
	(SELECT description FROM pettycash
		WHERE idpettycash = @idpettycash) 
	AS description,
	operation,
	adate,
	operationdescription,
	codefin,
	codeupb,
	incomeamount,
	expenseamount,
	doc,
	docdate,
	isnull(detail,'') as detail,
	nrestore,
	yrestore,
	case 
		when (ISNULL(payment,'') <> '') then ( 'Mand. ' + payment )
		else ''
	end
		as payment, 
	idexpIx
FROM #pettycashreg 
WHERE (idupb like @idupb OR idupb is null)
ORDER BY idpettycash, adate, noperation

 -- exec rpt_fondopsp_registro 2010, 1, 'S','%', 'S',{ts '2010-01-01 00:00:00'}, {ts '2010-12-31 00:00:00'}

END

GO

print '[rpt_fondopsp_registro] OK'

GO
if object_id('[rpt_bilconsuntivo_cassa_comp_residui_riep]') is not null
	drop PROCEDURE [rpt_bilconsuntivo_cassa_comp_residui_riep]
go

CREATE        PROCEDURE [rpt_bilconsuntivo_cassa_comp_residui_riep]
(
	@ayear int,
	@date datetime,
	@finpart char(1),
	@levelusable tinyint,
	@idupb varchar(36),
	@showupb char(1),
	@showchildupb char(1),
	@officialvar  char(1),
	@suppressifblank char(1),
	@kind char(1),		-- C R S
	@idsor01 int,
	@idsor02 int,
	@idsor03 int,
	@idsor04 int,
	@idsor05 int
)
AS BEGIN
CREATE TABLE #data
(
	idfin int,	--su levelusable
	idupb varchar(36),
	initialprevision decimal(19,2),
	varprev_m_acc decimal(19,2),
	varprev_m_red decimal(19,2),
	secondaryprev decimal(19,2),
	varprev_s_acc decimal(19,2),
	varprev_s_red decimal(19,2),
	currentarrears decimal(19,2),
	mov_finphase_C decimal(19,2),
	var_finphase_acc_C decimal(19,2),
	var_finphase_red_C decimal(19,2),
	mov_maxphase_C decimal(19,2),
	var_maxphase_C decimal(19,2),
	mov_finphase_R decimal(19,2),
	var_finphase_acc_R decimal(19,2),
	var_finphase_red_R decimal(19,2),
	mov_maxphase_R decimal(19,2),
	var_maxphase_R decimal(19,2),
	previsionkind char(1),
	showupb char(1),
	nlevel tinyint,
	prevision_diff_acc_comp decimal(19,2),
	prevision_diff_red_comp decimal(19,2),
	prevision_diff_acc_cassa decimal(19,2),
	prevision_diff_red_cassa decimal(19,2)
)
DECLARE @idfinincomesurplus int -- Flag indicante se l'avanzo di amministrazione è attribuito in previsione ad un capitolo di entrata o no --M. Smaldino
SELECT  @idfinincomesurplus = isnull(idfinincomesurplus,0) 
	FROM config
	WHERE ayear = @ayear
DECLARE	@finpart_bit  tinyint  -- Parte del bilancio (Entrata / Spesa)
if @finpart='E' set @finpart_bit = 0
if @finpart='S' set @finpart_bit = 1
DECLARE @idupboriginal varchar(36)
SET @idupboriginal= @idupb
IF (@showchildupb = 'S' and @idupb<>'%')
BEGIN
	SET @idupb=@idupb+'%' 
END

declare @fixedidupb varchar(36)
set @fixedidupb= null
if (@showupb='N') set @fixedidupb='0001'

DECLARE @infoadvance char(1)
SELECT  @infoadvance = paramvalue
FROM    generalreportparameter
WHERE   idparam = 'MostraAvanzo'
DECLARE @cashvaliditykind tinyint
SELECT  @cashvaliditykind = cashvaliditykind FROM config WHERE ayear = @ayear
DECLARE @finphase tinyint
DECLARE @maxphase tinyint
declare @fin_kind tinyint
select  @fin_kind = fin_kind
FROM config 
WHERE ayear = @ayear

IF (@finpart = 'E')
BEGIN
	-- ricerca la fase equivalente all'accertamento
	-- se è stata inserita nella tabella di configurazione del bilancio
	SELECT @finphase = assessmentphasecode FROM config WHERE ayear = @ayear
	IF @finphase IS NULL
	BEGIN
		-- se non è stata inserita nella tabella di configurazione
		-- ipotizza che si tratti della fase dove viene identificata
		-- la voce di bilancio
		SELECT @finphase = incomefinphase FROM uniconfig
	END
	-- la fase di cassa è sempre l'ultima fase della procedura
	-- di entrata
	SELECT @maxphase = MAX(nphase) FROM incomephase
END
IF (@finpart = 'S')
BEGIN
	-- ricerca la fase equivalente all'impegno
	-- se è stata inserita nella tabella di configurazione
	-- del bilancio
	SELECT @finphase = appropriationphasecode FROM config WHERE ayear = @ayear
	IF @finphase IS NULL
	BEGIN
		-- se non è stata inserita nella tabella di configurazione
		-- ipotizza che si tratti della fase dove viene identificata
		-- la voce di bilancio
		SELECT @finphase = expensefinphase FROM uniconfig
	END
	-- la fase di cassa è sempre l'ultima fase della procedura di spesa
	SELECT @maxphase = MAX(nphase) FROM expensephase
END
-- Se @fin_kind = 1 ==> è stata personalizzata una
-- previsione principale di tipo "competenza", se @fin_kind = 2
-- ==> è stata personalizzata una previsione principale di tipo "cassa", se
-- @fin_kind = 3 ==> è stata personalizzata una
-- previsione principale di tipo "altra previsione". 
DECLARE @supposed_ff_jan01 decimal(19,2)
DECLARE @supposed_aa_jan01 decimal(19,2)
DECLARE @ff_jan01 decimal(19,2)
DECLARE @aa_jan01 decimal(19,2)
DECLARE @floatfund_01_jan_used decimal(19,2) 
DECLARE @supposed_aa_01_jan_used decimal(19,2) 
DECLARE @aa_01_jan_used decimal(19,2) 
DECLARE @supposed_ff_01_jan_used decimal(19,2) 

IF (@finpart = 'E')
BEGIN
	-- Fondo cassa e avanzo di amministrazione presunti ed effettivi al 01/01
	-- dell'ayear per il quale si effettua il consuntivo.
	SELECT	@supposed_ff_jan01 =
		ISNULL(startfloatfund, 0) +
		ISNULL(proceedstilldate, 0) +
		ISNULL(proceedstoendofyear, 0) -
		ISNULL(paymentstilldate, 0) -
		ISNULL(paymentstoendofyear, 0),
	@supposed_aa_jan01 =
		ISNULL(startfloatfund, 0) +
		ISNULL(proceedstilldate, 0) +
		ISNULL(proceedstoendofyear, 0) -
		ISNULL(paymentstilldate, 0) -
		ISNULL(paymentstoendofyear, 0) +
		ISNULL(supposedpreviousrevenue, 0) +
		ISNULL(supposedcurrentrevenue , 0) -
		ISNULL(supposedpreviousexpenditure, 0) -
		ISNULL(supposedcurrentexpenditure, 0)
	FROM surplus
	WHERE ayear = @ayear - 1
	
	
 -- Per ulteriori dettagli in merito a questa modifica leggere la Documentazione del task n.4077
	SELECT	@ff_jan01 = ISNULL(startfloatfund, 0) 
	FROM surplus
	WHERE ayear = @ayear
	
	SELECT
	@aa_jan01 = @ff_jan01 +
		ISNULL(previousrevenue, 0) +
		ISNULL(currentrevenue , 0) -
		ISNULL(previousexpenditure, 0) -
		ISNULL(currentexpenditure, 0)
	FROM surplus
	WHERE ayear = @ayear - 1		

	SELECT @floatfund_01_jan_used = isnull(paramvalue,0) 
	FROM generalreportparameter 
	WHERE idparam='ff_jan01'
	
	SELECT @aa_01_jan_used = isnull(paramvalue,0) 
	FROM generalreportparameter 
	WHERE idparam='aa_jan01'
	SELECT @supposed_ff_01_jan_used = isnull(paramvalue,0) 
	FROM generalreportparameter 
	WHERE idparam='supposed_ff_jan01'
	
	SELECT @supposed_aa_01_jan_used = isnull(paramvalue,0) 
	FROM generalreportparameter 
	WHERE idparam='supposed_aa_jan01'
END

DECLARE @minlevelusable		tinyint
SELECT  @minlevelusable = min(nlevel) FROM finlevel WHERE ayear = @ayear and (flag&2) <> 0
DECLARE @levelusable_original tinyint	
SET @levelusable_original = @levelusable
IF(@levelusable < @minlevelusable)
begin
	SET @levelusable = @minlevelusable
end

----------------------------------------------------------------------------------------------------------------------------------------------------------------
------------------------------------------------- SE SI è DECISO DI NON VEDERE L'UPB ---------------------------------------------------------------------------
----------------------------------------------------------------------------------------------------------------------------------------------------------------
print 'insert prevision'
if (@kind='C')
begin
insert into #data (
	idfin,	idupb,
	initialprevision
)
select finyear.idfin,isnull(@fixedidupb,finyear.idupb),
		ISNULL(SUM(finyear.prevision),0)
from finyear 
	join fin f5 on finyear.idfin=f5.idfin
JOIN upb U
	ON finyear.idupb = U.idupb
JOIN finlevel fl
		ON f5.nlevel = fl.nlevel AND  f5.ayear = fl.ayear
where f5.ayear = @ayear
		AND (finyear.idupb LIKE @idupb)	
		AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
		AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
		AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
		AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
		AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
		AND ((f5.flag & 1)= @finpart_bit) --AND f5.finpart = @finpart
		AND (f5.nlevel = @levelusable
			OR (f5.nlevel < @levelusable
				AND EXISTS (SELECT * FROM finlast WHERE finlast.idfin = f5.idfin)
				AND (fl.flag&2)<>0
			   )
			)
		AND (@infoadvance = 'N' OR @infoadvance = 'B' OR f5.idfin <> @idfinincomesurplus )-- f5.flagincomesurplus = 'N')
group by finyear.idfin,isnull(@fixedidupb,finyear.idupb),
U.idsor01,  U.idsor02,  U.idsor03,  U.idsor04, U.idsor05
end
if (@kind='S')
begin
insert into #data (
	idfin,	idupb,
	secondaryprev
)
select finyear.idfin,isnull(@fixedidupb,finyear.idupb),
		case
			when @fin_kind = 2
				then ISNULL(SUM(finyear.prevision),0) 
				else ISNULL(SUM(finyear.secondaryprev),0)			
		end		
from finyear 
	join fin f5 on finyear.idfin=f5.idfin
JOIN upb U
	ON finyear.idupb = U.idupb
JOIN finlevel fl
		ON f5.nlevel = fl.nlevel AND  f5.ayear = fl.ayear
where f5.ayear = @ayear
		AND (finyear.idupb LIKE @idupb)	
		AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
		AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
		AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
		AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
		AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
		AND ((f5.flag & 1)= @finpart_bit) --AND f5.finpart = @finpart
		AND (f5.nlevel = @levelusable
			OR (f5.nlevel < @levelusable
				AND EXISTS (SELECT * FROM finlast WHERE finlast.idfin = f5.idfin)
				AND (fl.flag&2)<>0
			   )
			)
		AND (@infoadvance = 'N' OR @infoadvance = 'B' OR f5.idfin <> @idfinincomesurplus )-- f5.flagincomesurplus = 'N')
group by finyear.idfin,isnull(@fixedidupb,finyear.idupb),
U.idsor01,  U.idsor02,  U.idsor03,  U.idsor04, U.idsor05
end

if (@kind='R')
begin
insert into #data (
	idfin,	idupb,
	currentarrears
)
select finyear.idfin,isnull(@fixedidupb,finyear.idupb),
		ISNULL(SUM(finyear.currentarrears),0)
from finyear 
	join fin f5 on finyear.idfin=f5.idfin
JOIN upb U
	ON finyear.idupb = U.idupb
JOIN finlevel fl
		ON f5.nlevel = fl.nlevel AND  f5.ayear = fl.ayear
where f5.ayear = @ayear
		AND (finyear.idupb LIKE @idupb)	
		AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
		AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
		AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
		AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
		AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
		AND ((f5.flag & 1)= @finpart_bit) --AND f5.finpart = @finpart
		AND (f5.nlevel = @levelusable
			OR (f5.nlevel < @levelusable
				AND EXISTS (SELECT * FROM finlast WHERE finlast.idfin = f5.idfin)
				AND (fl.flag&2)<>0
			   )
			)
		AND (@infoadvance = 'N' OR @infoadvance = 'B' OR f5.idfin <> @idfinincomesurplus )-- f5.flagincomesurplus = 'N')
group by finyear.idfin,isnull(@fixedidupb,finyear.idupb),
U.idsor01,  U.idsor02,  U.idsor03,  U.idsor04, U.idsor05
end


if (@kind='C')
begin
print 'insert varprev_m_acc'
INSERT INTO #data
(
	idfin,
	idupb,
	varprev_m_acc
)
SELECT
	ISNULL(FLK.idparent,FVD.idfin), 
	isnull(@fixedidupb,FVD.idupb),
	ISNULL(SUM(FVD.amount),0)
FROM finvardetail FVD
JOIN finvar FV
	ON FV.yvar = FVD.yvar
	AND FV.nvar = FVD.nvar
JOIN fin F
	ON FVD.idfin = F.idfin
JOIN upb U
	ON FVD.idupb = U.idupb
LEFT OUTER JOIN finlink FLK
	ON FLK.idchild = FVD.idfin AND FLK.nlevel = @levelusable_original
WHERE FV.yvar = @ayear
	AND FV.adate <= @date
	AND FV.flagprevision = 'S'
	AND FV.idfinvarstatus = 5 
	AND FV.variationkind <> 5
	AND
	((ISNULL(FV.official,'N') = 'S' AND ISNULL(@officialvar,'N') = 'S') -- consideriamo solo le variazioni ufficiali
	  OR ISNULL(@officialvar,'N') = 'N')
	AND ((F.flag & 1 ) = @finpart_bit) AND F.ayear = @ayear
	AND FVD.amount > 0
	AND FVD.idupb like @idupb
	AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
	AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
	AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
	AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
	AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
GROUP BY isnull(@fixedidupb,FVD.idupb),ISNULL(FLK.idparent,FVD.idfin),
U.idsor01,  U.idsor02,  U.idsor03,  U.idsor04, U.idsor05
end

if (@kind='C')
begin
print 'insert varprev_m_red'
INSERT INTO #data
(
	idfin,
	idupb,
	varprev_m_red
)
SELECT
	ISNULL(FLK.idparent,FVD.idfin),
	isnull(@fixedidupb,FVD.idupb),
	ABS(ISNULL(SUM(FVD.amount),0))
FROM finvardetail FVD
JOIN finvar FV
	ON FV.yvar = FVD.yvar
	AND FV.nvar = FVD.nvar
JOIN fin F 
	ON FVD.idfin = F.idfin
JOIN upb U
	ON FVD.idupb = U.idupb
LEFT OUTER JOIN finlink FLK
	ON FLK.idchild = FVD.idfin AND FLK.nlevel = @levelusable_original
WHERE FV.yvar = @ayear
	AND FV.adate <= @date
	AND FV.flagprevision = 'S'
	AND FV.idfinvarstatus = 5 
	AND FV.variationkind <> 5
	AND ((F.flag & 1 ) = @finpart_bit) AND F.ayear = @ayear
	AND ((ISNULL(FV.official,'N') = 'S' AND ISNULL(@officialvar,'N') = 'S') -- consideriamo solo le variazioni ufficiali
	  OR ISNULL(@officialvar,'N') = 'N')
	AND FVD.amount < 0
	AND FVD.idupb like @idupb
	AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
	AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
	AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
	AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
	AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
