if object_id('[rpt_partitario_cassa]') is not null
	drop PROCEDURE [rpt_partitario_cassa]
go

CREATE     PROCEDURE [rpt_partitario_cassa]
	@ayear smallint,
	@kind char(1),
	@idupb	varchar(36),
	@finpart char(1),
	@nlevel tinyint,
	@start smalldatetime,
	@stop smalldatetime,
	@showupb char (1),
	@showchildupb char(1),
	@suppressifblank char(1),
	@flagnofficial	char(1),
	@idfin int
AS
	BEGIN
/* Versione 1.0.1 del 11/09/2007 ultima modifica: SARA */
		IF @finpart = 'E'
			EXEC rpt_partitario_entrata_cassa
				@ayear,
				@kind,
				@idupb,
				@nlevel,
				@start,
				@stop,
				@showupb,
				@showchildupb,
				@suppressifblank,
				@flagnofficial,
				@idfin
		ELSE
			EXEC rpt_partitario_spesa_cassa
				@ayear,
				@kind,
				@idupb,
				@nlevel,
				@start,
				@stop,
				@showupb,
				@showchildupb,
				@suppressifblank,
				@flagnofficial,
				@idfin
  END





GO

print '[rpt_partitario_cassa] OK'

