INSERT INTO #trace(
				   kind,
				   ndoc,
				   idpay,
				   importo_ritenute,
				   numero_reversale,
				   progressivo_versante
				   )
SELECT 
				   'RITENUTE',
				   ndoc,
				   idpay, 
				   SUM(curramount),
				   npro,
				   idpro	   	
FROM #tax 
GROUP BY  #tax.ndoc,#tax.idpay, #tax.npro, #tax.idpro		 
ORDER BY  #tax.ndoc,#tax.idpay, #tax.npro, #tax.idpro		 
SELECT * FROM #trace 
END



