if object_id('[rebuild_upbincometotal]') is not null
	drop PROCEDURE [rebuild_upbincometotal]
go

CREATE              PROCEDURE [rebuild_upbincometotal]
(
	@ayear int = null
)
AS BEGIN
DECLARE @arrearsphase tinyint
SELECT @arrearsphase = 1
SELECT @arrearsphase = incomefinphase FROM uniconfig
IF (@ayear IS NULL) 
BEGIN
	DELETE FROM upbincometotal
	INSERT INTO upbincometotal 
	(
		idupb, idfin, nphase,
		totalcompetency,
		totalarrears
	)
	SELECT 
		IY.idupb, F.idfin, I.nphase,
		ISNULL(
			(SELECT SUM(IT1.curramount)
			FROM incometotal IT1
			JOIN incomeyear IY1
				ON IY1.ayear = IT1.ayear
				AND IY1.idinc = IT1.idinc
			JOIN income I1
				ON I1.idinc = IT1.idinc
			JOIN finlink FL
				ON IY1.idfin = FL.idchild
			WHERE IY1.idupb = IY.idupb
				AND F.idfin = FL.idparent
				AND I1.nphase = I.nphase
				AND ((IT1.flag & 1) = 0))
		,0),
		ISNULL(
			(SELECT SUM(IT1.curramount)
			FROM incometotal IT1
			JOIN incomeyear IY1
				ON IY1.ayear = IT1.ayear
				AND IY1.idinc = IT1.idinc
			JOIN income I1
				ON I1.idinc = IT1.idinc
			JOIN finlink FL1
				ON IY1.idfin = FL1.idchild
			WHERE IY1.idupb = IY.idupb
				AND F.idfin = FL1.idparent
				AND I1.nphase = I.nphase
				AND ((IT1.flag & 1) = 1))
		,0)
	FROM incomeyear IY
	JOIN income I
		ON I.idinc = IY.idinc
	LEFT OUTER JOIN incometotal IT
		ON IT.idinc = IY.idinc
		AND IT.ayear = IY.ayear
	JOIN finlink 
		ON finlink.idchild = IY.idfin
	JOIN fin F
		ON finlink.idparent = F.idfin
	WHERE I.nphase >= @arrearsphase
		AND ((F.flag & 1) = 0)
	GROUP BY IY.idupb, F.idfin, I.nphase
END	
ELSE
BEGIN
	DELETE FROM upbincometotal WHERE EXISTS(SELECT fin.idfin FROM fin WHERE fin.idfin = upbincometotal.idfin
		AND fin.ayear = @ayear)
	INSERT INTO upbincometotal 
	(
		idupb,
		idfin,
		nphase,
		totalcompetency,
		totalarrears			
	)
	SELECT 
		IY.idupb,F.idfin,I.nphase,
		ISNULL(
			(SELECT SUM(IT1.curramount)
			FROM incometotal IT1
			JOIN incomeyear IY1
				ON IY1.ayear = IT1.ayear
				AND IY1.idinc = IT1.idinc
			JOIN income I1
				ON I1.idinc = IT1.idinc
			JOIN finlink FL
				ON IY1.idfin = FL.idchild
			WHERE IY1.idupb = IY.idupb
				AND F.idfin = FL.idparent
				AND I1.nphase = I.nphase
				AND ((IT1.flag & 1) = 0))
		,0),
		ISNULL(
			(SELECT SUM(IT1.curramount)
			FROM incometotal IT1
			JOIN incomeyear IY1
				ON IY1.ayear = IT1.ayear
				AND IY1.idinc = IT1.idinc
			JOIN income I1
				ON I1.idinc = IT1.idinc
			JOIN finlink FL1
				ON IY1.idfin = FL1.idchild
			WHERE IY1.idupb = IY.idupb
				AND F.idfin = FL1.idparent
				AND I1.nphase = I.nphase
				AND ((IT1.flag & 1) = 1))
		,0)
	FROM incomeyear IY
	JOIN income I
		ON I.idinc = IY.idinc
	LEFT OUTER JOIN incometotal IT
		ON IT.idinc = IY.idinc
		AND IT.ayear = IY.ayear
	JOIN finlink 
		ON finlink.idchild = IY.idfin
	JOIN fin F
		ON finlink.idparent = F.idfin
	WHERE I.nphase >= @arrearsphase
		AND F.ayear = @ayear
		AND IY.ayear = @ayear
		AND ((F.flag & 1) = 0)
	GROUP BY IY.idupb, F.idfin, I.nphase
END
	
END


GO

print '[rebuild_upbincometotal] OK'

GO
if object_id('[get_initialamount]') is not null
	drop PROCEDURE [get_initialamount]
go

CREATE     PROCEDURE [get_initialamount]
(
 @idasset int,
 @idpiece int,
 @initialamount decimal (19,2) OUTPUT
)
AS
BEGIN
----------------------------------------------------------------------------------
-------------------- Valore iniziale se cespite ----------------------------------
----------------------------------------------------------------------------------	 
IF      (@idpiece = 1) --Cespite principale
	BEGIN
	SET @initialamount = ISNULL((
	       SELECT 
		CASE	
			----------------------------------------------------------------------------------
			----------------- Considera i buoni di carico precedenti al 2005 -----------------
			----------------------------------------------------------------------------------
			WHEN 
		 	((inventorykind.flag & 1 <> 0) OR ISNULL(assetload.yassetload,2006)<2005 OR(
			assetacquire.idassetload IS NULL AND (assetacquire.flag & 2 <> 0)))	
			THEN
			CONVERT(decimal(19,2),ROUND(
				ROUND(ISNULL(assetacquire.taxable, 0)
				* (1 - CONVERT(decimal(19,6),ISNULL(assetacquire.discount, 0))),2)
				+ ROUND(ISNULL(assetacquire.tax,0) / assetacquire.number,2)
				- ROUND(ISNULL(assetacquire.abatable,0) / assetacquire.number,2) 
			,2))
			----------------------------------------------------------------------------------
			------- Considera i buoni di carico del 2005 e i successivi  SENZA SCONTO --------
			----------------------------------------------------------------------------------			
			WHEN NOT ((inventorykind.flag & 1 <> 0) OR ISNULL(assetload.yassetload,2006)<2005 OR  
			(assetacquire.idassetload IS NULL AND (assetacquire.flag & 2 <> 0)) )	
			THEN
			CONVERT(decimal(19,2),ROUND(
			ROUND(ISNULL(assetacquire.taxable, 0),2)
			+ ROUND(ISNULL(assetacquire.tax,0) / assetacquire.number,2)
			- ROUND(ISNULL(assetacquire.abatable,0) / assetacquire.number,2) 
			,2))
			ELSE 0
			END
		 FROM asset 
		 JOIN assetacquire 
		   ON assetacquire.nassetacquire = asset.nassetacquire
		 LEFT OUTER JOIN assetload
		   ON assetload.idassetload = assetacquire.idassetload
		 JOIN inventory 
		   ON inventory.idinventory = assetacquire.idinventory
		 JOIN inventorykind
		   ON inventory.idinventorykind= inventorykind.idinventorykind  
		WHERE asset.idasset = @idasset
		  AND asset.idpiece = @idpiece),0.0)
	END
----------------------------------------------------------------------------------
---------------------- Valore iniziale se accessorio -----------------------------
----------------------------------------------------------------------------------			
IF   (@idpiece > 1)
	BEGIN
	SET @initialamount = ISNULL((SELECT  CONVERT(decimal(19,2),ROUND(
			        ROUND(ISNULL(assetacquire.taxable, 0)
			        * (1 - CONVERT(decimal(19,6),ISNULL(assetacquire.discount, 0))),2)
				+ ROUND(ISNULL(assetacquire.tax,0) / assetacquire.number,2)
				- ROUND(ISNULL(assetacquire.abatable,0) / assetacquire.number,2) 
				,2))
			 FROM asset 
			 JOIN assetacquire 
			   ON assetacquire.nassetacquire = asset.nassetacquire
			 JOIN inventory 
			   ON inventory.idinventory = assetacquire.idinventory
			 JOIN inventorykind
			   ON inventory.idinventorykind= inventorykind.idinventorykind  
			WHERE asset.idasset = @idasset
			  AND asset.idpiece = @idpiece
			  AND ((assetacquire.flag & 1 <> 1) OR assetacquire.idassetload IS NOT NULL)
			      
			),0.0)
	END
	
END


GO

print '[get_initialamount] OK'

