if object_id('rpt_unified_riepilogoiva_riep') is not null
	drop PROCEDURE rpt_unified_riepilogoiva_riep
go

--setuser'amministrazione'
CREATE     PROCEDURE rpt_unified_riepilogoiva_riep
(
	@idivaregisterkind int,
	@year int,
	@startmonth int,
	@stopmonth int,
	@official char(1),
	@unified char(1)
)
AS BEGIN
    -- rpt_unified_riepilogoiva_riep 1,2011,1,12,'N','S'
	-- rpt_unified_riepilogoiva_riep 1,2011,1,12,'N','N'
	
        IF @startmonth IS NULL OR @startmonth < 1
	BEGIN
		SET @startmonth = 1
	END
	IF @startmonth > 12
	BEGIN
		SET @startmonth = 12
	END
	IF @stopmonth IS NULL OR @stopmonth < 1
	BEGIN
		SET @stopmonth = 1
	END
	IF @stopmonth > 12
	BEGIN
		SET @stopmonth = 12
	END
	
	--	1) Consolidamento MULTI - DIP. sulla base del codice di consolidamento.
	--	2) Consolidamento MONO - DIP. sulla base del codice di consolidamento.
	DECLARE @TipoConsolidamentoRegistriIVA		char(1)
	SELECT  @TipoConsolidamentoRegistriIVA = isnull(paramvalue,'') FROM    generalreportparameter
	WHERE   idparam = 'TipoConsolidamentoRegistriIVA'
	
	IF ((@unified <> 'S') OR ( @unified ='S' and @TipoConsolidamentoRegistriIVA = '2'))
	BEGIN
            SELECT
	        user AS departmentname,
        	0 AS taxabletotal_imm, 
        	0 AS taxabletotal_imm_esente, 
        	0 AS ivaunabatable_imm,
        	0 AS ivaabatable_imm, 
        	0 AS taxabletotal_dif,
        	0 AS taxabletotal_dif_esente,
        	0 AS ivaunabatable_dif,
        	0 AS ivaabatable_dif, 
        	0 AS taxabletotal_totdif, 
        	0 AS taxabletotal_totdif_esente, 
        	0 AS ivaunabatable_totdif,
        	0 AS ivaabatable_totdif 
	        RETURN
	END 
	-- CREAZIONE DELLA TABELLA TEMPORANEA CON L'INFO SUL NOME DEL DIPARTIMENTO
	CREATE TABLE #outtable
	(
		departmentname			varchar(200),
		currmonth 			varchar(50),
		curryear 			int,
		registername 			varchar(50),
		idivakind 			varchar(20),   -- codice IVA
		ivakinddescr 			varchar(50),  
		rate         			decimal(19,6),
		unabatabilitypercentage 	decimal(19,6),
		taxabletotal_imm  		decimal(19,2), -- Imponibile (dei documenti immediati)
		ivaunabatable_imm 		decimal(19,2), -- IVA Indetraibile (dei documenti immediati)
		ivaabatable_imm			decimal(19,2), -- IVA Detraibile (dei documenti immediati)
        taxabletotal_dif                decimal(19,2), -- Imponibile (dei documenti differiti divenuti immediati)
        ivaunabatable_dif               decimal(19,2), -- IVA Indetrabile (dei documenti differiti divenuti immediati)
        ivaabatable_dif                 decimal(19,2), -- IVA Detraibile (dei documenti differiti divenuti immediati)
        taxabletotal_totdif             decimal(19,2), -- Imponibile (dei documenti differiti)
        ivaunabatable_totdif            decimal(19,2), -- IVA Indetraibile (dei documenti differiti)
        ivaabatable_totdif              decimal(19,2)  -- IVA Detraibile (dei documenti differiti)
	)
	DECLARE @codeivaregisterkind varchar(20)
	DECLARE @idivaregisterkindunified int
	SELECT  @codeivaregisterkind		 = codeivaregisterkind,
		    @idivaregisterkindunified = idivaregisterkindunified  FROM ivaregisterkind WHERE idivaregisterkind = @idivaregisterkind

	declare @iddbdepartment varchar(50)
	declare @crsdepartment cursor
	set 	@crsdepartment = cursor for select  iddbdepartment from dbdepartment
							 where (start is null or start <= @year ) AND ( stop is null or stop >= @year)
	open 	@crsdepartment
	fetch next from @crsdepartment into @iddbdepartment
	while @@fetch_status=0 begin
		declare @dip_nomesp varchar(300)
		set @dip_nomesp = @iddbdepartment + '.rpt_riepilogoiva'
		insert into #outtable 
			(
                        departmentname,
                        currmonth,
                        curryear,
                        registername,
                        idivakind,   
                        ivakinddescr,  
                        rate,
                        unabatabilitypercentage,
                        taxabletotal_imm,
                        ivaunabatable_imm,
                        ivaabatable_imm,
                        taxabletotal_dif,
                        ivaunabatable_dif,
                        ivaabatable_dif,
                        taxabletotal_totdif,
                        ivaunabatable_totdif,
                        ivaabatable_totdif 
			)
			exec @dip_nomesp @idivaregisterkindunified, @year, @startmonth, @stopmonth, @official,@unified, @codeivaregisterkind
			
		fetch next from @crsdepartment into @iddbdepartment
	
	END
UPDATE #OUTTABLE set rate = 0 WHERE isnull(rate,0) = 0
	/*SELECT 
                departmentname,
        	SUM(taxabletotal_imm) AS taxabletotal_imm, -- Imponibile (dei documenti immediati)        >>>>>>
        	SUM(ivaunabatable_imm) AS ivaunabatable_imm, -- IVA Indetraibile (dei documenti immediati)
        	SUM(ivaabatable_imm) AS ivaabatable_imm, -- IVA Detraibile (dei documenti immediati)
        	SUM(taxabletotal_dif) AS taxabletotal_dif, -- Imponibile (dei documenti differiti divenuti immediati)        <<<<<<<
        	SUM(ivaunabatable_dif) AS ivaunabatable_dif, -- IVA Indetrabile (dei documenti differiti divenuti immediati)
        	SUM(ivaabatable_dif) AS ivaabatable_dif, -- IVA Detraibile (dei documenti differiti divenuti immediati)
        	SUM(taxabletotal_totdif) AS taxabletotal_totdif, -- Imponibile (dei documenti differiti)        <<<<<<<<<
        	SUM(ivaunabatable_totdif) AS ivaunabatable_totdif, -- IVA Indetraibile (dei documenti differiti)
        	SUM(ivaabatable_totdif) AS ivaabatable_totdif -- IVA Detraibile (dei documenti differiti)
	FROM #outtable
        GROUP BY departmentname*/
	SELECT 
                departmentname,
                (select SUM(taxabletotal_imm) 
                        from #outtable O2 
                        where O2.departmentname  =#outtable.departmentname and isnull(rate,0)<>0 )
                 AS taxabletotal_imm, -- Imponibile (dei documenti immediati)        NON ESENTE
        	(select SUM(taxabletotal_imm) 
                        from #outtable O2
                        where O2.departmentname  =#outtable.departmentname and isnull(rate,0)=0 )
                 AS taxabletotal_imm_esente, -- Imponibile (dei documenti immediati)        ESENTE
        	SUM(ivaunabatable_imm) AS ivaunabatable_imm, -- IVA Indetraibile (dei documenti immediati)
        	SUM(ivaabatable_imm) AS ivaabatable_imm, -- IVA Detraibile (dei documenti immediati)
                (select SUM(taxabletotal_dif)  
                        from #outtable O2
                        where O2.departmentname  =#outtable.departmentname and isnull(rate,0)<>0 )
                AS taxabletotal_dif, -- Imponibile (dei documenti differiti divenuti immediati)        NON ESENTE
               (select SUM(taxabletotal_dif)  
                        from #outtable O2
                        where O2.departmentname  =#outtable.departmentname and isnull(rate,0)=0 )
                AS taxabletotal_dif_esente, -- Imponibile (dei documenti differiti divenuti immediati)     ESENTE
        	SUM(ivaunabatable_dif) AS ivaunabatable_dif, -- IVA Indetrabile (dei documenti differiti divenuti immediati)
        	SUM(ivaabatable_dif) AS ivaabatable_dif, -- IVA Detraibile (dei documenti differiti divenuti immediati)
               (select SUM(taxabletotal_totdif)  
                        from #outtable O2
                        where O2.departmentname  =#outtable.departmentname and isnull(rate,0)<>0 )
                AS taxabletotal_totdif, -- Imponibile (dei documenti differiti)       NON ESENTE 
               (select SUM(taxabletotal_totdif)  
                        from #outtable O2
                        where O2.departmentname  =#outtable.departmentname and isnull(rate,0)= 0 )
        	AS taxabletotal_totdif_esente, -- Imponibile (dei documenti differiti)       ESENTE
        	SUM(ivaunabatable_totdif) AS ivaunabatable_totdif, -- IVA Indetraibile (dei documenti differiti)
        	SUM(ivaabatable_totdif) AS ivaabatable_totdif -- IVA Detraibile (dei documenti differiti)
	FROM #outtable
        GROUP BY departmentname
END

GO

print 'rpt_unified_riepilogoiva_riep OK'

GO
if object_id('[compute_csa_lordi]') is not null
	drop PROCEDURE [compute_csa_lordi]
go

CREATE  PROCEDURE [compute_csa_lordi]
(
	@ayear	      int,
	@idcsa_import int
)
AS BEGIN
-- ELABORAZIONE DEI LORDI: a partire dai file csa_importriep
-- e csa_importver vengono generati i movimenti finanziari 
-- di spesa/entrata relativi a:
-- fase 1) generazione dei movimenti finanziari di spesa per il costo dei LORDI (righe positive e imputazione normale)
-- fase 2) generazione dei movimenti finanziari di spesa per il costo dei LORDI (righe positive e imputazione con  movimento di spesa)
-- fase 2bis) generazione dei movimenti finanziari di spesa ove presente tabella di ripartizione in csa_contractexpense
-- fase 3) generazione dei movimenti finanziari di entrata di ricavo per i LORDI (righe negative)
-- fase 4) generazione dei movimenti finanziari di spesa per il costo dei CONTRIBUTI (imputazione normale, righe positive)
-- fase 5) generazione dei movimenti finanziari di spesa per il costo dei CONTRIBUTI (imputazione con  movimento di spesa, righe positive)
-- fase 5bis) generazione dei movimenti finanziari di spesa per il costo dei CONTRIBUTI ove presente tabella di ripartizione in csa_contracttaxexpense
-- fase 6) generazione dei movimenti finanziari di entrata per RECUPERI (positivi) con o senza transito da partite di giro
-- fase 7) generazione dei movimenti finanziari di entrata per CONTRIBUTI con transito da partita di giro, righe positive
-- fase 8) generazione dei movimenti finanziari di entrata per RITENUTE righe positive 
-- fase 9) generazione dei movimenti finanziari di spesa per RITENUTE E RECUPERI righe negative
DECLARE @idreg_csa  int
DECLARE @idregauto  int
DECLARE @idfinincome_gross_csa int
DECLARE @idsiopeincome_csa int
DECLARE @csa_flaggroupby_income char(1)
DECLARE @csa_flaggroupby_expense char(1)
DECLARE @yimportstr varchar(10)
DECLARE @nimportstr varchar(10)
SELECT @yimportstr = CONVERT(varchar(10),yimport),@nimportstr = convert(varchar(10),nimport) FROM  csa_import WHERE idcsa_import = @idcsa_import
SELECT 
	@idreg_csa = idreg_csa,
	@idregauto = idregauto,
	@idfinincome_gross_csa = idfinincome_gross_csa ,
	--@flagdirectcsaclawback = flagdirectcsaclawback
	@csa_flaggroupby_income	 = csa_flaggroupby_income,
	@csa_flaggroupby_expense = csa_flaggroupby_expense,
	@idsiopeincome_csa = idsiopeincome_csa
FROM config
WHERE ayear = @ayear

CREATE TABLE #automov_exp_ungrouped
(
	parentidexp int, 
	idreg int,
	idfin int,
	idsor_siope int,
	idupb varchar(36),
	amount decimal(19,2),
	movkind	int,
	description varchar(200),
	idcsa_contractkind int,
	idcsa_contract int,
	idacc varchar(36),
	idcsa_agency int,
	idunderwriting int
)
CREATE TABLE #automov_inc_ungrouped
(
	idreg int,
	idfin int,
	idsor_siope int,
	idupb varchar(36),
	amount decimal(19,2),
	movkind int,
	description varchar(200),
	idacc varchar(36),
	idcsa_contractkind int,
	idcsa_contract int,
	idcsa_agency int,
	idunderwriting int 
)

--fase 1) generazione dei movimenti finanziari di spesa per il costo dei LORDI (righe positive e imputazione normale)
-- imputazione UPB/Voce di bilancio
INSERT INTO #automov_exp_ungrouped
(	parentidexp, 
	idreg,
	idfin,
	idsor_siope,
	idupb,
	amount,
	movkind,
	description,
	idcsa_contractkind ,
	idcsa_contract,
	idunderwriting  
)
SELECT
	NULL,
	@idreg_csa,  -- prenderò la modalità di pagamento predefinita per tale anagrafica
	csa_importriep.idfin,
	csa_importriep.idsor_siope,
	csa_importriep.idupb,
	csa_importriep.importo,
	3,
	substring('Lordi ' + 'Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr+'.'+csa_import.description,1,150),
	csa_importriep.idcsa_contractkind ,
	csa_importriep.idcsa_contract,
	csa_importriep.idunderwriting 
FROM 	csa_importriep
	JOIN csa_import 
		on csa_import.idcsa_import = csa_importriep.idcsa_import
WHERE   
 	csa_importriep.idcsa_import = @idcsa_import
AND csa_importriep.importo > 0
AND (csa_importriep.idfin IS NOT NULL ) 
-- fase 2) generazione dei movimenti finanziari di spesa per il costo dei LORDI
-- (righe positive e imputazione con  movimento di spesa da collegare)
INSERT INTO #automov_exp_ungrouped
(	parentidexp, 
	idreg,
	idfin,
	idsor_siope,
	idupb,
	amount,
	movkind,
	description,
	idcsa_contractkind,
	idcsa_contract,
	idunderwriting  
)
SELECT
	E.idexp,
	ISNULL(E.idreg,@idreg_csa),
	ISNULL(EY.idfin, csa_importriep.idfin), 
	csa_importriep.idsor_siope,
	ISNULL(EY.idupb, csa_importriep.idupb),
	csa_importriep.importo,
	3,
	substring('Lordi ' + 'Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr+'.'+csa_import.description,1,150),
	csa_importriep.idcsa_contractkind ,
	csa_importriep.idcsa_contract,
	csa_importriep.idunderwriting 
FROM csa_importriep 
JOIN csa_import 
		on csa_import.idcsa_import = csa_importriep.idcsa_import
JOIN expense E
	ON csa_importriep.idexp = E.idexp
JOIN expenseyear EY
	ON EY.idexp = csa_importriep.idexp
WHERE  	
	csa_importriep.idcsa_import = @idcsa_import
	AND csa_importriep.importo > 0
	AND csa_importriep.idexp IS NOT NULL
	AND EY.ayear = @ayear

-- fase 2 BIS) generazione dei movimenti finanziari di spesa per il costo dei LORDI
-- (righe positive e imputazione con  tabella di ripartizione)
INSERT INTO #automov_exp_ungrouped
(	parentidexp, 
	idreg,
	idfin,
	idsor_siope,
	idupb,
	amount,
	movkind,
	description,
	idcsa_contractkind,
	idcsa_contract,
	idunderwriting  
)
SELECT
	E.idexp,
	ISNULL(E.idreg,@idreg_csa),
	ISNULL(EY.idfin, csa_importriep.idfin), 
	csa_importriep.idsor_siope,
	ISNULL(EY.idupb, csa_importriep.idupb),
	ROUND(csa_importriep.importo*csa_contractexpense.quota,2),
	3,
	substring('Lordi ' + 'Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr+'.'+csa_import.description,1,150),
	csa_importriep.idcsa_contractkind ,
	csa_importriep.idcsa_contract,
	csa_importriep.idunderwriting 
FROM csa_importriep 
JOIN csa_import 
		on csa_import.idcsa_import = csa_importriep.idcsa_import
JOIN csa_contractexpense
		ON csa_importriep.idcsa_contract=csa_contractexpense.idcsa_contract
			AND csa_importriep.ayear=csa_contractexpense.ayear
JOIN expense E
	ON csa_contractexpense.idexp = E.idexp
JOIN expenseyear EY
	ON EY.idexp = E.idexp
WHERE  	
	csa_importriep.idcsa_import = @idcsa_import
	AND csa_importriep.importo > 0
	AND EY.ayear = @ayear
	AND (csa_importriep.idfin IS NULL ) AND  csa_importriep.idexp IS NULL


if (@csa_flaggroupby_expense='S') 
BEGIN
-- valorizzo la descr. con il contratto o, in alternativa, il tipo contratto
UPDATE 	#automov_exp_ungrouped 
SET 	#automov_exp_ungrouped.description = SUBSTRING(#automov_exp_ungrouped.description + 
	' Contr. ' + csa_contract.description,1,150)
FROM 	csa_contract 
WHERE   #automov_exp_ungrouped.movkind = 3 
AND csa_contract.idcsa_contract = #automov_exp_ungrouped.idcsa_contract
AND csa_contract.idcsa_contract is not null
AND csa_contract.ayear = @ayear
UPDATE 	#automov_exp_ungrouped 
SET 	#automov_exp_ungrouped.description = SUBSTRING(#automov_exp_ungrouped.description + 
	' Tipo contr. ' + csa_contractkind.description,1,150)
FROM  	csa_contractkindyear
JOIN  	csa_contractkind 
	ON csa_contractkind.idcsa_contractkind = csa_contractkindyear.idcsa_contractkind
WHERE  #automov_exp_ungrouped.movkind = 3 
AND csa_contractkindyear.idcsa_contractkind = #automov_exp_ungrouped.idcsa_contractkind 
AND #automov_exp_ungrouped.idcsa_contract is  null  
AND #automov_exp_ungrouped.idcsa_contractkind is  not null
AND csa_contractkindyear.ayear = @ayear
END

-- fase 3) generazione dei movimenti finanziari di entrata 
-- di ricavo per i LORDI (righe negative)
-- solo se valorizzo il capitolo di entrata in config
INSERT INTO #automov_inc_ungrouped
(	
	idreg,
	idfin,
	idsor_siope,
	idupb,
	amount,
	movkind,
	description,
	idcsa_contractkind,
	idcsa_contract 
)
SELECT
	@idreg_csa,
	@idfinincome_gross_csa,
	@idsiopeincome_csa,
	'0001', -- sempre '0001'
	- importo,
	7,
	'Ricavo Lordi ' + ' Import. Stipendi   n° ' + @nimportstr + '/' + @yimportstr,
	idcsa_contractkind,
	idcsa_contract
FROM csa_importriep
WHERE   
 	idcsa_import = @idcsa_import
AND @idfinincome_gross_csa IS NOT NULL
AND	csa_importriep.importo < 0

------------------------------------------------------------------------------- 
if (@csa_flaggroupby_income='S') 
BEGIN
UPDATE 	#automov_inc_ungrouped 
SET 	#automov_inc_ungrouped.description = SUBSTRING(#automov_inc_ungrouped.description + 
	    ' Contr. ' + csa_contract.description,1,150)
FROM 	csa_contract 
WHERE   #automov_inc_ungrouped.movkind = 7 
AND csa_contract.idcsa_contract = #automov_inc_ungrouped.idcsa_contract
AND csa_contract.idcsa_contract is not null
AND csa_contract.ayear = @ayear
UPDATE 	#automov_inc_ungrouped 
SET 	#automov_inc_ungrouped.description = SUBSTRING(#automov_inc_ungrouped.description + 
	' Tipo contr. ' + csa_contractkind.description,1,150)
FROM  	csa_contractkindyear
JOIN  	csa_contractkind 
	ON csa_contractkind.idcsa_contractkind = csa_contractkindyear.idcsa_contractkind
WHERE  #automov_inc_ungrouped.movkind = 7 
AND csa_contractkindyear.idcsa_contractkind = #automov_inc_ungrouped.idcsa_contractkind 
AND #automov_inc_ungrouped.idcsa_contract is  null  
AND #automov_inc_ungrouped.idcsa_contractkind is  not null
AND csa_contractkindyear.ayear = @ayear
END
---------------------------------------------------------------------------------
-- fase 4) generazione dei movimenti finanziari di spesa per i CONTRIBUTI
-- in caso di applicazione del contributo con transito su partite di giro no versamento diretto
-- imputazione normale
INSERT INTO #automov_exp_ungrouped
(	parentidexp, 
	idreg,
	idfin,
	idsor_siope,
	idupb,
	amount,
	movkind,
	description,
	idacc,
	idcsa_agency,
	idcsa_contractkind,
	idcsa_contract,
	idunderwriting 
)
SELECT
	NULL,
	@idregauto,  -- modalità pagamento predefinita per essa
	idfin_cost,
	idsor_siope_cost,
	idupb,
	importo,
	2,
	CASE ISNULL(@csa_flaggroupby_expense,'N')
		WHEN 'S' THEN SUBSTRING('Contributi '+ vocecsa +  ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr,1,150)
		ELSE 'Contributi ' +   ' Import. Stipendi n° ' + @nimportstr + '/' + @yimportstr
	END,
	idacc_debit,
	null,
	idcsa_contractkind,
	idcsa_contract,
	idunderwriting
FROM 	csa_importver
WHERE   
 	idcsa_import = @idcsa_import
	AND importo > 0
AND (idfin_cost IS NOT NULL  AND idfin_income is not null) 
-- fase 5) generazione dei movimenti finanziari di spesa per i CONTRIBUTI
-- in caso di applicazione del contributo con transito su partite di giro no versamento diretto
-- imputazione tramite movimento di spesa da collegare
INSERT INTO #automov_exp_ungrouped
(	parentidexp, 
	idreg,
	idfin,
	idsor_siope,
	idupb,
	amount,
	movkind,
	description,
	idacc,
	idcsa_agency,
	idcsa_contractkind,
	idcsa_contract,
	idunderwriting
)
SELECT
	E.idexp,
	ISNULL(E.idreg, @idregauto), -- modalità pagamento predefinita per essa
	ISNULL(EY.idfin, csa_importver.idfin_cost), 
	csa_importver.idsor_siope_cost,
	ISNULL(EY.idupb, csa_importver.idupb),
	importo,
	2,
	CASE ISNULL(@csa_flaggroupby_expense,'N')
		WHEN 'S' THEN SUBSTRING('Contributi '+ vocecsa +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr,1,150)
		ELSE 'Contributi ' +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr
	END,
	idacc_debit,
	null,
	idcsa_contractkind,
	idcsa_contract,
	csa_importver.idunderwriting
FROM 	csa_importver
JOIN expense E
	ON csa_importver.idexp_cost = E.idexp
JOIN expenseyear EY
	ON EY.idexp = csa_importver.idexp_cost
WHERE  	
	idcsa_import = @idcsa_import
	AND EY.ayear = @ayear
	AND importo > 0
	AND (idfin_cost IS NULL AND idexp_cost IS NOT NULL AND idfin_income is not null) 

-- fase 5BIS) generazione dei movimenti finanziari di spesa per i CONTRIBUTI
-- in caso di applicazione del contributo con transito su partite di giro no versamento diretto
-- imputazione tramite tabella di ripartizione
INSERT INTO #automov_exp_ungrouped
(	parentidexp, 
	idreg,
	idfin,
	idsor_siope,
	idupb,
	amount,
	movkind,
	description,
	idacc,
	idcsa_agency,
	idcsa_contractkind,
	idcsa_contract,
	idunderwriting
)
SELECT
	E.idexp,
	ISNULL(E.idreg, @idregauto), -- modalità pagamento predefinita per essa
	ISNULL(EY.idfin, csa_importver.idfin_cost), 
	csa_importver.idsor_siope_cost,
	ISNULL(EY.idupb, csa_importver.idupb),
	ROUND(csa_importver.importo*csa_contracttaxexpense.quota,2),
	2,
	CASE ISNULL(@csa_flaggroupby_expense,'N')
		WHEN 'S' THEN SUBSTRING('Contributi '+ vocecsa +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr,1,150)
		ELSE 'Contributi ' +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr
	END,
	csa_importver.idacc_debit,
	null,
	csa_importver.idcsa_contractkind,
	csa_importver.idcsa_contract,
	csa_importver.idunderwriting
FROM 	csa_importver
JOIN csa_contracttaxexpense
		ON csa_importver.idcsa_contract = csa_contracttaxexpense.idcsa_contract
			AND csa_importver.idcsa_contracttax = csa_contracttaxexpense.idcsa_contracttax
			AND csa_importver.ayear = csa_contracttaxexpense.ayear
JOIN expense E
	ON csa_contracttaxexpense.idexp = E.idexp
JOIN expenseyear EY
	ON EY.idexp = E.idexp
WHERE  	
	idcsa_import = @idcsa_import
	AND EY.ayear = @ayear
	AND importo > 0
	AND (idfin_cost IS NULL AND idexp_cost IS NULL AND idfin_income is not null) 



-- fase 6) generazione dei movimenti finanziari di entrata per RECUPERI con o senza transito da partita di giro
-- (sia recupero diretto che con transito da partita di giro) 
INSERT INTO #automov_inc_ungrouped
(	
	idreg,
	idfin,
	idsor_siope,
	idupb,
	amount,
	movkind,
	description,
	idacc,
	idcsa_agency,
	idcsa_contractkind,
	idcsa_contract
)
SELECT
	@idreg_csa,
	CASE
	WHEN ISNULL(flagdirectcsaclawback,'N')= 'S' THEN idfin_incomeclawback
	ELSE idfin_income
	END ,
	CASE
	WHEN ISNULL(flagdirectcsaclawback,'N')= 'S' THEN idsor_siope_incomeclawback
	ELSE idsor_siope_income
	END ,
	CASE  
		WHEN ISNULL(flagdirectcsaclawback,'N')= 'S'  THEN idupb
		ELSE '0001'
	END,  -- per i movimenti su partita di giro sempre '0001'
	importo,
	5,
	CASE ISNULL(@csa_flaggroupby_income,'N')
		WHEN 'S' THEN SUBSTRING('Incasso Recuperi ' + vocecsa +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr,1,150)
		ELSE 'Incasso Recuperi ' +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr
	END,
	null,
	null,
	idcsa_contractkind,
	idcsa_contract
FROM 	csa_importver
WHERE   
 	idcsa_import = @idcsa_import
AND importo > 0
AND	ISNULL(flagclawback,'N') = 'S'
AND (
	(ISNULL(flagdirectcsaclawback,'N')= 'N' AND idfin_income IS NOT NULL) OR 
	(ISNULL(flagdirectcsaclawback,'N')= 'S' AND idfin_incomeclawback IS NOT NULL) 
	)
-- fase 7) generazione dei movimenti finanziari di entrata per 
-- CONTRIBUTI con transito da partita di giro
-- Movimenti su anagrafica @idregauto 
INSERT INTO #automov_inc_ungrouped
(
	idreg,
	idfin,
	idsor_siope,
	idupb,
	amount,
	movkind,
	description,
	idacc,
	idcsa_agency,
	idcsa_contractkind,
	idcsa_contract
)
SELECT
	@idregauto,  -- applicazione contributi con transito da partita di giro
	idfin_income,
	idsor_siope_income,
	'0001',
	importo,
	1,
	CASE ISNULL(@csa_flaggroupby_income,'N')
		WHEN 'S' THEN SUBSTRING('Ritenute/Contributi ' + vocecsa +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr,1,150)
		ELSE 'Ritenute/Contributi ' +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr
	END,
	idacc_expense,  -- debito VS erario
	idcsa_agency,
	idcsa_contractkind,
	idcsa_contract
FROM 	csa_importver
WHERE   
 	idcsa_import = @idcsa_import
AND importo > 0
AND	ISNULL(flagclawback,'N') = 'N'
AND (idfin_cost IS NOT NULL OR idexp_cost IS NOT NULL)
AND (idfin_income IS NOT NULL) 

-- fase 8) generazione dei movimenti finanziari di entrata per 
-- RITENUTE 
-- Movimenti su anagrafica @idreg_csa IMPORTI POSITIVI
 
INSERT INTO #automov_inc_ungrouped
(
	idreg,
	idfin,
	idsor_siope,
	idupb,
	amount,
	movkind,
	description,
	idacc,
	idcsa_agency,
	idcsa_contractkind,
	idcsa_contract
)
SELECT
	@idreg_csa,  --applicazione ritenute
	idfin_income,
	idsor_siope_income,
	'0001',
	importo,
	1,
	CASE ISNULL(@csa_flaggroupby_income,'N')
		WHEN 'S' THEN SUBSTRING('Ritenute/Contributi ' + vocecsa +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr,1,150)
		ELSE 'Ritenute/Contributi ' +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr
	END,
	idacc_expense,  -- debito VS erario
	idcsa_agency,
	idcsa_contractkind,
	idcsa_contract
FROM 	csa_importver
WHERE   
 	idcsa_import = @idcsa_import
AND	ISNULL(flagclawback,'N') = 'N'
AND importo > 0
AND idfin_cost IS NULL AND idexp_cost IS NULL
AND (idfin_income IS NOT NULL) 

-- fase 9) generazione dei movimenti finanziari di spesa per 
-- RITENUTE  E RECUPERI
-- Movimenti su anagrafica @idreg_csa ad IMPORTI NEGATIVI
INSERT INTO #automov_exp_ungrouped
(
	idreg,
	idfin,
	idsor_siope,
	idupb,
	amount,
	movkind,
	description,
	idacc,
	idcsa_agency,
	idcsa_contractkind,
	idcsa_contract
)
SELECT
	@idreg_csa, --applicazione ritenute
	idfin_expense,
	idsor_siope_expense,
	'0001',
	-importo,
	8,
	CASE ISNULL(@csa_flaggroupby_expense,'N')
		WHEN 'S' THEN SUBSTRING('Rimborso Ritenute ' + vocecsa +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr,1,150)
		ELSE 'Rimborso Ritenute ' +   ' Import. Stipendi  n° ' + @nimportstr + '/' + @yimportstr
	END,
	null, --sarà poi valorizzato con debito verso percipiente "diversi"
	idcsa_agency,
	idcsa_contractkind,
	idcsa_contract
FROM 	csa_importver
WHERE   
 	idcsa_import = @idcsa_import
--   AND	ISNULL(flagclawback,'N') = 'N'
AND importo < 0
AND (idfin_cost IS NULL AND idexp_cost IS NULL)  -- non è un contributo ma una ritenuta
AND (idfin_income IS NOT NULL) 
CREATE TABLE #automov
(
	parentidexp int, 
	idreg int,
	idfin int, 
	idsor_siope int,
	idupb varchar(36),
	amount decimal(19,2),
	movkind int,
	description varchar(200),
	idacc varchar(36),
	idcsa_agency int,
	idcsa_contractkind int,
	idcsa_contract int,
	idunderwriting int
)

INSERT INTO #automov 
(
	parentidexp, 
	idreg,
	idfin, 
	idsor_siope,
	idupb,
	amount,
	movkind,
	description,
	idacc,
	idcsa_agency,
	idcsa_contractkind,
	idcsa_contract,
	idunderwriting
)
	
SELECT parentidexp, idreg, idfin, idsor_siope, idupb, SUM(amount), movkind, description,idacc, idcsa_agency,idcsa_contractkind,idcsa_contract,idunderwriting
FROM   #automov_exp_ungrouped
GROUP BY parentidexp, idreg, idfin, idsor_siope, idupb, description, movkind,idacc, idcsa_agency,
idcsa_contractkind,idcsa_contract, idunderwriting
INSERT INTO #automov 
(
	idreg,
	idfin, 
	idsor_siope,
	idupb,
	amount,
	movkind,
	description,
	idacc,
	idcsa_agency,
	idcsa_contractkind,
	idcsa_contract,
	idunderwriting
)
SELECT idreg, idfin, idsor_siope, idupb, SUM(amount), movkind, description,idacc, idcsa_agency, idcsa_contractkind,idcsa_contract,idunderwriting
FROM   #automov_inc_ungrouped
GROUP BY movkind, idreg, idfin, idsor_siope, idupb, description,idacc, idcsa_agency,idcsa_contractkind,idcsa_contract,idunderwriting

SELECT 
	CASE 
	     WHEN #automov.movkind IN (2,3,8) THEN 'Spesa'
	     WHEN #automov.movkind IN (1,5, 7) THEN 'Entrata' 
	END as kind,
	#automov.movkind,
	null as parentidinc,
	#automov.parentidexp,
	#automov.idreg,
	R.title AS registry,
	idcsa_agency as idcsa_agency,
	null as idcsa_agencypaymethod,
	#automov.idfin,
	F.codefin,
	#automov.idsor_siope as idsor,
	S.sortcode,
	S2.idsor as parentidsor,
	S2.sortcode as parentsortcode,
	#automov.idupb as idupb,
	U.codeupb, 
	#automov.description,
	#automov.idacc,
	A.codeacc,
    #automov.amount,
    #automov.idcsa_contractkind,
    #automov.idcsa_contract,
    #automov.idunderwriting,
	UN.codeunderwriting
FROM #automov 
LEFT OUTER JOIN registry R
	ON R.idreg = #automov.idreg
LEFT OUTER JOIN fin F
	ON F.idfin = #automov.idfin
LEFT OUTER JOIN upb U
	ON U.idupb = #automov.idupb
LEFT OUTER JOIN account A
	ON A.idacc = #automov.idacc
LEFT OUTER JOIN sorting S
	ON S.idsor = #automov.idsor_siope
left outer join sortingkind SK 
	on S.idsorkind=SK.idsorkind
left outer join sorting S2 
	on S2.sortcode=S.sortcode and S2.idsorkind=SK.idparentkind
LEFT OUTER JOIN underwriting UN
	ON UN.idunderwriting = #automov.idunderwriting
ORDER BY  R.title,F.codefin, U.codeupb, A.idacc
END


GO

