FROM #tax 
GROUP BY  #tax.ndoc,#tax.idpay, #tax.npro, #tax.idpro		 
ORDER BY  #tax.ndoc,#tax.idpay, #tax.npro, #tax.idpro
SELECT * FROM #trace 
END



