CREATE  PROCEDURE [rpt_bilanciodiverifica]
	@ayear				int,
	@start				datetime,
	@stop				datetime,
	@nlevel 			varchar(1),
	@idupb				varchar(36),
	@showchildupb		char(1),
	@suppressifblank	char(1)
	AS
	BEGIN
	
	DECLARE @idupboriginal varchar(36)
	SET @idupboriginal= @idupb
	IF (@showchildupb = 'S') 
	BEGIN
		SET @idupb=@idupb+'%' 
	END
--	[rpt_bilanciodiverifica] 2011, {ts '2011-01-20 00:00:00'}, {ts '2011-12-31 00:00:00'}, 3, null, 'S', 'S'
	CREATE TABLE #bilanciodiverifica
		(
		idacc1 		varchar(38), 
		code1		varchar(50), 
		title1		varchar(150), 
		printingordacc1 varchar(50), 
		idacc2	 	varchar(38), 
		code2		varchar(50), 
		title2		varchar(150), 
		printingordacc2 varchar(50), 
		idacc3	 	varchar(38), 
		code3		varchar(50), 
		title3		varchar(150), 
		printingordacc3 varchar(50), 
		idacc4	 	varchar(38), 
		code4		varchar(50), 
		title4		varchar(150), 
		printingordacc4 varchar(50), 
		idacc5	 	varchar(38), 
		code5		varchar(50), 
		title5		varchar(150), 
		printingordacc5 varchar(50), 
		idacc 		varchar(38), 
		code		varchar(50), 
		title		varchar(150), 
		nlevel		varchar(1),
		printingordacc	varchar(50), 
		totaledare 	decimal(19,2),
		totaleavere 	decimal(19,2),
		crpauo		varchar(1),
		placcount_sign	varchar(1),
		patrimony_sign  varchar(1)			
		)
		
	-- Se ho scelto un livello sottostante del livello operativo utilizzo quello, 
	-- altrimenti userò il I liv.operativo
	/*DECLARE @levelusable	varchar(20)
	SELECT @levelusable = MIN(nlevel)
		FROM accountlevel
		WHERE flagusable = 'S'	AND ayear = @ayear
	IF @levelusable < @nlevel
		SELECT @levelusable = @nlevel
	
	SET @nlevel = @levelusable*/
	DECLARE @newnlevel integer
	SET @newnlevel = (CONVERT(int, @nlevel)*4)+2  PRINT @newnlevel
	DECLARE @nlevel1 integer SET @nlevel1 = 6
	DECLARE @nlevel2 integer SET @nlevel2 = 10
	DECLARE @nlevel3 integer SET @nlevel3 = 14
	DECLARE @nlevel4 integer SET @nlevel4 = 18
	DECLARE @nlevel5 integer SET @nlevel5 = 22
	INSERT INTO #bilanciodiverifica
      		(
		idacc1,
		idacc2,
		idacc3,
		idacc4,
		idacc5,
		idacc,
		code,
		title,
		printingordacc,
		nlevel,
		placcount_sign,
		patrimony_sign
		)
		SELECT 
			SUBSTRING(account.idacc, 1, @nlevel1),
			SUBSTRING(account.idacc, 1, @nlevel2),
			SUBSTRING(account.idacc, 1, @nlevel3),
			SUBSTRING(account.idacc, 1, @nlevel4),
			SUBSTRING(account.idacc, 1, @nlevel5),
			SUBSTRING(account.idacc, 1, @newnlevel),  	
			codeacc,
			title,
			printingorder,
			nlevel,
			placcount_sign,
			patrimony_sign		
		FROM account
		where account.ayear = @ayear and
		account.nlevel <=  @nlevel
	 	AND ((account.flag&4)= 0)	-- ESCLUDO I CONTI D'ORDINE
DELETE  FROM  #bilanciodiverifica 
WHERE EXISTS (SELECT * from #bilanciodiverifica RR 
	       WHERE RR.idacc like (#bilanciodiverifica.idacc + '%') AND RR.idacc <> #bilanciodiverifica.idacc)
	update #bilanciodiverifica 
	set    totaledare = -isnull((SELECT SUM(amount) 
			     FROM entrydetail  
			     JOIN entry on
			     entry.nentry = entrydetail.nentry and
			     entry.yentry = entrydetail.yentry 
			     WHERE  amount < 0 AND
			     (entrydetail.idupb like @idupb  OR @idupb is null)
			     AND entrydetail.idacc like (#bilanciodiverifica.idacc  + '%') and
			     entry.yentry = @ayear
		             and entry.adate between @start and @stop
			     ),0)
	update #bilanciodiverifica 
	set    totaleavere = ISNULL((SELECT SUM(amount)
			     FROM entrydetail  
			     JOIN entry on
			     entry.nentry = entrydetail.nentry and
			     entry.yentry = entrydetail.yentry 
			     WHERE  amount > 0 AND
			    (entrydetail.idupb like @idupb OR @idupb is null)
			     AND entrydetail.idacc like (#bilanciodiverifica.idacc  + '%') and
			     entry.yentry = @ayear
			     and entry.adate between @start and @stop
			     ),0) 
	
	IF (	Upper(@suppressifblank)='S')	
	DELETE FROM  #bilanciodiverifica
		where 	isnull(totaledare,0)=0 and  	isnull(totaleavere,0)=0   
	update #bilanciodiverifica 
	set    crpauo = (SELECT ISNULL(SUBSTRING(account.idpatrimony,3,1),SUBSTRING(account.idplaccount,3,1))
			 FROM   account
			 WHERE  account.idacc = #bilanciodiverifica.idacc
			 )
	
	update #bilanciodiverifica 
	set code1  = account.codeacc,
	    title1 = account.title ,
	    printingordacc1 = account.printingorder
	from account 
	where #bilanciodiverifica.idacc1 = account.idacc 
	if (@nlevel >2)
		update #bilanciodiverifica set code2	= account.codeacc ,
				title2	= account.title ,
				printingordacc2 = account.printingorder
				from account 
				where #bilanciodiverifica.idacc2 = account.idacc
		else update #bilanciodiverifica 
		set idacc2 = null
				
	if (@nlevel >3)
		update #bilanciodiverifica set code3	= account.codeacc ,
				title3	= account.title ,
				printingordacc3 = account.printingorder
				from account 
				where #bilanciodiverifica.idacc3 = account.idacc
		else update #bilanciodiverifica
				set idacc3 = null
			
	if (@nlevel >4 )
		update #bilanciodiverifica set code4	= account.codeacc ,
				title4	= account.title ,
				printingordacc4 = account.printingorder
				from account 
				where #bilanciodiverifica.idacc4 = account.idacc
		else update #bilanciodiverifica
				set idacc4 = null
	if (@nlevel >5 )
		update #bilanciodiverifica set code5	= account.codeacc ,
				title5	= account.title ,
				printingordacc5 = account.printingorder
				from account 
				where #bilanciodiverifica.idacc5 = account.idacc
		else update #bilanciodiverifica
				set idacc5 = null 
				
DECLARE @codeupb	varchar(50)
DECLARE @title		varchar(150)
 
SELECT	@codeupb = codeupb,
		@title = title
FROM	upb 
WHERE	idupb = @idupboriginal
--gestione @suppressifblank nel report
SELECT  
	@idupboriginal as idupb,
	@codeupb as codeupb,
	@title as upb,
	idacc1, 
	code1,	
	title1,	
	printingordacc1,	
	idacc2, 
	code2,	
	title2,	
	printingordacc2,	
	idacc3, 
	code3,	
	title3,	
	printingordacc3,	
	idacc4, 
	code4,	
	title4,	
	printingordacc4,	
	idacc5, 
	code5,	
	title5,	
	printingordacc5,	
	idacc,
	code 	as 'codeaccount',	
	title 	as 'titleaccount',	
	printingordacc	,
	nlevel,
	totaledare,
	totaleavere,
	crpauo,
	placcount_sign,
	patrimony_sign
	FROM #bilanciodiverifica
ORDER BY printingordacc,code 
	
END


GO

print '[rpt_bilanciodiverifica] OK'

