CREATE             TRIGGER [trigger_d_incomesorted] ON [incomesorted] FOR DELETE
AS BEGIN
IF @@ROWCOUNT > 0
BEGIN
	DECLARE @idinc int
 	DECLARE @idsor int
 	DECLARE @ayear int
 	DECLARE @amount decimal(19,2)
 	SELECT 
		@idinc = idinc, 
		@idsor = idsor, 
		@amount = -amount,
		@ayear = ayear
	FROM deleted
	IF (@ayear IS NULL)
	BEGIN
		SELECT @ayear = ymov FROM income WHERE idinc = @idinc
	END
	EXECUTE trg_upd_sorttotal 
	@idsor, 
	@ayear, 
	'totalincome', 
	@amount
END
END



