if object_id('[rpt_verbale_consegna_beni]') is not null
	drop PROCEDURE [rpt_verbale_consegna_beni]
go

CREATE   PROCEDURE [rpt_verbale_consegna_beni]
(
	@ayear int,
	@idinventory int,
	@startninventory int,
	@stopninventory int,
	@nassetload int,
	@idman int
)
AS BEGIN
-- exec rpt_verbale_consegna_beni 2011, 1, 1, 3000, null, null
CREATE TABLE #asset
(
	idassetloadkind	int,
	yassetload smallint,
	nassetload int,
	idmot int,
	idinventoryagency int,
	inventoryagency	varchar(150),
	idinventorykind int,
	inventorykind varchar(55),
	idreg int,
	doc varchar(35),
	docdate smalldatetime,
	description varchar(150),
	enactment varchar(150),
	enactmentdate smalldatetime,
	adate smalldatetime,
	startconsignee smalldatetime,
	printdate smalldatetime,
	operationorder int,
	kind varchar(50),
	idinventory int,
	startnumber int,
	number decimal (19,2),
	nassetacquire int,
	aq_startnumber int,
	idinv int,
	idinv1 int,
	idinv2 int,
	idinv3 int,
	idinv4 int,
	aliquota float,
	assetdescription varchar(150),
	idlocation int,
	idman int,
	annotation text
)
	
INSERT INTO #asset
(
	aliquota,
	idassetloadkind,
	yassetload,
	nassetload,
	idmot,
	idinventoryagency,
	inventoryagency,
	idinventorykind,
	inventorykind,
	idreg,
	doc,
	docdate,
	description,
	annotation,
	enactment,
	enactmentdate,
	adate,
	printdate,
	operationorder,
	kind,
	idinventory,
	startnumber,
	number,
	nassetacquire,
	aq_startnumber,
	idinv,
	idinv1,
	idinv2,
	idinv3,
	idinv4,
	assetdescription,
	idlocation,
	idman
	)
SELECT
	assetacquire.taxrate,
	assetload.idassetloadkind,
	assetload.yassetload,
	assetload.nassetload,
	assetload.idmot,
	inventory.idinventoryagency,
	inventoryagency.description,
	inventory.idinventorykind,
	inventorykind.description,
	assetload.idreg,
	assetload.doc,
	assetload.docdate,
	assetload.description,
	assetload.txt,
	assetload.enactment,
	assetload.enactmentdate,
	assetload.adate,
	assetload.printdate,
	1,
	'Carico bene',
	assetacquire.idinventory,
	asset.ninventory,
	assetacquire.number,
	assetacquire.nassetacquire,
	ISNULL(assetacquire.startnumber,asset.ninventory),
	assetacquire.idinv,
	IL1.idparent,
	IL2.idparent,
	IL3.idparent,
	IL4.idparent,
	assetacquire.description,
	(SELECT idlocation FROM assetlocation l WHERE l.idasset = asset.idasset AND l.start IS NULL),
	(SELECT idman FROM assetmanager m WHERE m.idasset = asset.idasset AND m.start IS NULL)
FROM asset  
JOIN assetacquire on assetacquire.nassetacquire = asset.nassetacquire
JOIN assetload on assetload.idassetload = assetacquire.idassetload
JOIN inventory on assetacquire.idinventory = inventory.idinventory
LEFT OUTER JOIN manager R ON R.idman = (select top 1 idman from assetmanager where idasset=asset.idasset and start is null)
JOIN inventoryagency
	ON inventoryagency.idinventoryagency = inventory.idinventoryagency
JOIN inventorykind
	ON inventorykind.idinventorykind = inventory.idinventorykind
LEFT OUTER JOIN inventorytreelink IL1  
    	ON IL1.idchild = assetacquire.idinv AND IL1.nlevel  = 1 
LEFT OUTER JOIN inventorytreelink IL2  
    	ON IL2.idchild = assetacquire.idinv  AND IL2.nlevel = 2
LEFT OUTER JOIN inventorytreelink IL3 
    	ON IL3.idchild = assetacquire.idinv  AND IL3.nlevel = 3 
LEFT OUTER JOIN inventorytreelink IL4  
    	ON IL4.idchild = assetacquire.idinv  AND IL4.nlevel = 4 
WHERE  asset.idpiece=1		
	AND assetacquire.idinventory= @idinventory
	AND assetload.yassetload = @ayear
	AND (assetload.nassetload = @nassetload OR @nassetload is null)
	AND (asset.ninventory >= @startninventory OR @startninventory is null)
	AND (asset.ninventory <= @stopninventory OR @stopninventory is null)
	AND (R.idman = @idman OR @idman IS NULL)

INSERT INTO #asset
(
	aliquota,
	idassetloadkind,
	yassetload,
	nassetload,
	idmot,
	idinventoryagency,
	inventoryagency,
	idinventorykind,
	inventorykind,
	idreg,
	doc,
	docdate,
	description,
	annotation,
	enactment,
	enactmentdate,
	adate,
	printdate,
	operationorder,
	kind,
	idinventory,
	startnumber,
	number,
	nassetacquire,
	aq_startnumber,
	idinv,
	idinv1,
	idinv2,
	idinv3,
	idinv4,
	assetdescription,
	idlocation,
	idman
)
SELECT
	assetacquire.taxrate,	
	assetload.idassetloadkind,
	assetload.yassetload,
	assetload.nassetload,
	assetload.idmot,
	inventory.idinventoryagency,
	inventoryagency.description,
	inventory.idinventorykind,
	inventorykind.description,
	assetload.idreg,
	assetload.doc,
	assetload.docdate,
	assetload.description,
	assetload.txt,
	assetload.enactment,
	assetload.enactmentdate,
	assetload.adate,
	assetload.printdate,
	2,
	'Carico accessorio',
	assetacquire.idinventory,
	assetmain.ninventory,
	assetacquire.number,
	assetacquire.nassetacquire,
	ISNULL(assetacquire.startnumber,assetmain.ninventory),
	assetacquire.idinv, 
	IL1.idparent,
	IL2.idparent,
	IL3.idparent,
	IL4.idparent,
	assetacquire.description,
	(SELECT idlocation FROM assetlocation l WHERE l.idasset = asset.idasset AND l.start IS NULL),
	(SELECT idman FROM assetmanager m WHERE m.idasset = asset.idasset AND m.start IS NULL)
FROM  asset  
JOIN asset as assetmain ON asset.idasset=assetmain.idasset
JOIN assetacquire on assetacquire.nassetacquire = asset.nassetacquire
JOIN assetload on assetload.idassetload = assetacquire.idassetload
JOIN inventory on assetacquire.idinventory = inventory.idinventory
LEFT OUTER JOIN manager R ON R.idman = (select top 1 idman from assetmanager where idasset=asset.idasset and start is null)
JOIN inventoryagency
	ON inventoryagency.idinventoryagency = inventory.idinventoryagency
JOIN inventorykind
	ON inventorykind.idinventorykind = inventory.idinventorykind
LEFT OUTER JOIN inventorytreelink IL1  
    	ON IL1.idchild = assetacquire.idinv AND IL1.nlevel  = 1 
LEFT OUTER JOIN inventorytreelink IL2  
    	ON IL2.idchild = assetacquire.idinv  AND IL2.nlevel = 2
LEFT OUTER JOIN inventorytreelink IL3 
    	ON IL3.idchild = assetacquire.idinv  AND IL3.nlevel = 3 
LEFT OUTER JOIN inventorytreelink IL4  
    	ON IL4.idchild = assetacquire.idinv  AND IL4.nlevel = 4 
WHERE asset.idpiece>1		
	AND assetacquire.idinventory= @idinventory
	AND assetload.yassetload = @ayear
	AND (assetload.nassetload = @nassetload OR @nassetload is null)
	AND assetmain.idpiece=1
	AND (assetmain.ninventory >= @startninventory OR @startninventory is null)
	AND (assetmain.ninventory <= @stopninventory OR @stopninventory is null)
	AND (R.idman = @idman OR @idman IS NULL)
UPDATE #asset
	SET startconsignee = (SELECT MAX(start) 
				FROM assetconsignee 
				WHERE idinventoryagency = #asset.idinventoryagency
					AND start <= #asset.adate)
CREATE TABLE #assetfinal
(
	idassetloadkind int,
	yassetload int,
	nassetload int,
	idmot varchar(20),
	idinventoryagency int,
	inventoryagency	varchar(150),
	idinventorykind int,
	inventorykind varchar(55),
	idreg int,
	doc varchar(35),
	docdate datetime,
	description varchar(150),
	enactment varchar(150),
	enactmentdate datetime,
	adate datetime,
	startconsignee smalldatetime,
	printdate datetime,
	operationorder int,
	kind varchar(50),
	idinventory int,
	startnumber int,
	idinv int,
	idinv1 int,
	idinv2 int,
	idinv3 int,
	idinv4 int,
	aliquota float,
	assetdescription varchar(150),
	idlocation int,
	idman int,
	number int,
	nassetacquire int,
	aq_startnumber int,
	annotation varchar(6000)		
)
INSERT INTO #assetfinal
(
	idassetloadkind,
	yassetload,
	nassetload,
	idmot,
	idinventoryagency,
	idinventorykind,
	inventoryagency,
	inventorykind,
	idreg,
	doc,
	docdate,
	description,
	annotation,
	enactment,
	enactmentdate,
	adate,
	printdate,
	operationorder,
	kind,
	idinventory,
	startnumber,
	idinv,
	idinv1,
	idinv2,
	idinv3,
	idinv4,
	assetdescription,
	idlocation,
	idman,
	number,
	aq_startnumber,
	nassetacquire,
	aliquota,
	startconsignee
)
SELECT
	idassetloadkind,
	yassetload,
	nassetload,
	idmot,
	idinventoryagency,
	idinventorykind,
	inventoryagency,
	inventorykind,
	idreg,
	doc,
	docdate,
	description,
	annotation,
	enactment,
	enactmentdate,
	adate,
	printdate,
	operationorder,
	kind,
	idinventory,
	startnumber,
	idinv,
	idinv1,
	idinv2,
	idinv3,
	idinv4,
	assetdescription,
	idlocation,
	idman,
	number,
	aq_startnumber,
	nassetacquire,
	aliquota,
	startconsignee
FROM  #asset
update #assetfinal 
	SET number = (select sum(number)FROM #assetfinal f
	WHERE 
	f.number <2
	AND f.idassetloadkind =  #assetfinal.idassetloadkind 
	AND f.yassetload =  #assetfinal.yassetload
	AND f.nassetload =  #assetfinal.nassetload
	AND ISNULL(f.idmot,0) =  ISNULL(#assetfinal.idmot,0)
	AND f.idinventoryagency =  #assetfinal.idinventoryagency
        AND f.number  =  #assetfinal.number
	AND f.idinventorykind =  #assetfinal.idinventorykind
	AND ISNULL(f.idreg,0) =  ISNULL(#assetfinal.idreg,0)
	AND isnull(f.description,'')   =  isnull(#assetfinal.description,'')                                                                                     
	AND isnull(f.enactment,'') = isnull( #assetfinal.enactment,'') 
	AND f.aq_startnumber =  #assetfinal.aq_startnumber 
	AND f.operationorder =  #assetfinal.operationorder
	AND f.kind =  #assetfinal.kind
	AND f.idinventory =  #assetfinal.idinventory
	and f.nassetacquire = #assetfinal.nassetacquire   
	and f.idlocation = #assetfinal.idlocation  
	and f.idman = #assetfinal.idman    
	GROUP BY  f.idassetloadkind, 
	f.yassetload ,
	f.nassetload ,
	f.idmot ,
	f.idinventoryagency, 
	f.idinventorykind, 
	f.idreg, 
	f.doc,                 
	f.docdate,                                         
	f.description,                                                                                          
	f.enactment,                                                                                        
	f.enactmentdate,                                      
	f.adate,
	f.printdate,
	f.operationorder,
	f.kind,
	f.idinventory,
	f.nassetacquire  
	) 
	WHERE 
	#assetfinal.number < 2

SELECT 
	idassetloadkind	,
	yassetload,
	nassetload,
	#assetfinal.idmot,
	assetloadmotive.description as assetloadmotive,
	#assetfinal.idinventoryagency,
	inventoryagency,
	#assetfinal.idinventorykind,
	inventorykind ,
	#assetfinal.idreg,
	registry.title,
	doc,
	docdate,
	#assetfinal.description,
	#assetfinal.annotation,
	enactment,
	enactmentdate,
	adate,
	startconsignee ,
	printdate,
	operationorder,
	kind,
	#assetfinal.idinventory,
	--#assetfinal.startnumber,
	#assetfinal.idinv,
	inventory.codeinventory,
	inventorytree.description as descrizioneclassif,
	inventorytree.codeinv,
	INVTREE1.codeinv as codeinv1,
	INVTREE1.description as descrizioneclassif1,
	LV1.description as level1,
	INVTREE2.codeinv as codeinv2,
	INVTREE2.description as descrizioneclassif2,
	LV2.description as level2,
	INVTREE3.codeinv as codeinv3,
	INVTREE3.description as descrizioneclassif3,
	LV3.description as level3,
	INVTREE4.codeinv as codeinv4,
	INVTREE4.description as descrizioneclassif4,
	LV4.description as level4,
	assetdescription,
	#assetfinal.idlocation,
	location.description as location,
	#assetfinal.idman,
	manager.title as manager,
	ISNULL(number, 1) as 'number' ,
	aq_startnumber
FROM #assetfinal
JOIN inventory
	on #assetfinal.idinventory = inventory.idinventory
LEFT OUTER JOIN assetloadmotive
	ON #assetfinal.idmot = assetloadmotive.idmot
LEFT OUTER JOIN registry
	ON #assetfinal.idreg = registry.idreg
LEFT OUTER JOIN inventorytree
	ON inventorytree.idinv = #assetfinal.idinv
LEFT OUTER JOIN inventorytree INVTREE1
	ON INVTREE1.idinv = #assetfinal.idinv1
LEFT OUTER JOIN inventorytree INVTREE2
	ON INVTREE2.idinv = #assetfinal.idinv2
LEFT OUTER JOIN inventorytree INVTREE3
	ON INVTREE3.idinv = #assetfinal.idinv3
LEFT OUTER JOIN inventorytree INVTREE4
	ON INVTREE4.idinv = #assetfinal.idinv4
LEFT OUTER JOIN inventorysortinglevel LV1
	ON LV1.nlevel = INVTREE1.nlevel
LEFT OUTER JOIN inventorysortinglevel LV2
	ON LV2.nlevel = INVTREE2.nlevel
LEFT OUTER JOIN inventorysortinglevel LV3
	ON LV3.nlevel = INVTREE3.nlevel
LEFT OUTER JOIN inventorysortinglevel LV4
	ON LV4.nlevel = INVTREE4.nlevel
LEFT OUTER JOIN location
	ON location.idlocation = #assetfinal.idlocation
LEFT OUTER JOIN manager
	ON manager.idman = #assetfinal.idman
GROUP BY 	idassetloadkind	,yassetload,nassetload,
	#assetfinal.idmot,assetloadmotive.description,#assetfinal.idinventoryagency,
	inventoryagency,#assetfinal.idinventorykind,inventorykind ,
	#assetfinal.idreg,	registry.title,
	doc,docdate,#assetfinal.description,#assetfinal.annotation,enactment,enactmentdate,
	adate,startconsignee ,printdate,operationorder,
	kind,	#assetfinal.idinventory,#assetfinal.idinv,	inventory.codeinventory,
	inventorytree.description,inventorytree.codeinv,INVTREE1.codeinv,
	INVTREE1.description,LV1.description,	INVTREE2.codeinv,	INVTREE2.description,	LV2.description,
	INVTREE3.codeinv,	INVTREE3.description,	LV3.description,	INVTREE4.codeinv,	INVTREE4.description,	LV4.description,
	assetdescription,	#assetfinal.idlocation,	location.description,	#assetfinal.idman,	manager.title,ISNULL(number, 1),	aq_startnumber,
	#assetfinal.nassetacquire
ORDER BY nassetload, aq_startnumber, operationorder
END


GO

