if object_id('rpt_journal_doubleentry') is not null
	drop PROCEDURE rpt_journal_doubleentry
go

CREATE  PROCEDURE rpt_journal_doubleentry
(
	@ayear int,
	@start datetime,
	@end datetime,
	@idupb		varchar(36),
	@showchildupb	char(1)
)
-- exec rpt_journal_doubleentry 2010, {ts '2010-01-27 00:00:00'}, {ts '2010-08-27 00:00:00'}, '0001', 'N'
AS BEGIN
	DECLARE @idupboriginal varchar(36)
	SET @idupboriginal= @idupb
	IF (@showchildupb = 'S') 
	BEGIN
		SET @idupb=@idupb+'%' 
	END
	DECLARE @codeupb	varchar(50)
	DECLARE @title		varchar(150)
	 
	SELECT	@codeupb = codeupb,
			@title = title
	FROM	upb 
	WHERE	idupb = @idupboriginal

	SELECT 
	@idupboriginal as idupb,
	@codeupb as codeupb,
	@title as upb,
	adate,
	nentry,
	ISNULL(entrydetailview.description,'') AS entrydescription,
	ISNULL(doc,'')  AS doc,
	docdate as docdate,
	codeacc,
	account AS accountdescr,
	give,
	have,
	registry
	FROM entrydetailview
	JOIN config
	ON config.ayear = entrydetailview.yentry
	WHERE entrydetailview.adate BETWEEN @start AND @end	
	AND (entrydetailview.idupb like @idupb OR @idupb is null)
	ORDER BY adate, nentry, registry, codeacc 
END

GO

print 'rpt_journal_doubleentry OK'

