if object_id('[rpt_situazioneeconomica]') is not null
	drop PROCEDURE [rpt_situazioneeconomica]
go
 
CREATE PROCEDURE [rpt_situazioneeconomica]
(
	@ayear int,
	@start datetime,
	@stop datetime,
	@levelusable char(1),
	@idupb		varchar(36),
	@showchildupb	char(1),
	@suppressifblank char(1)
)
AS BEGIN
--	[rpt_situazioneeconomica]  2012, {ts '2012-01-20 00:00:00'}, {ts '2012-12-31 00:00:00'}, 3, '0001', 'S', 'N'
	CREATE TABLE #situazioneeconomica
	(
		idupb varchar(36),
		codeupb varchar(50),
		upb varchar(150),
		idacc1 varchar(38),
		code1 varchar(50),
		desc1 varchar(150),
		order1 varchar(50),
		idacc2 varchar(38),
		code2 varchar(50),
		desc2 varchar(150),
		order2 varchar(50),
		idacc3 varchar(38),
		code3 varchar(50),
		desc3 varchar(150),
		order3 varchar(50),
		idacc4 varchar(38),
		code4 varchar(50),
		desc4 varchar(150),
		order4 varchar(50),
		idacc5 varchar(38),
		code5 varchar(50),
		desc5 varchar(150),
		order5 varchar(50),
		idacc varchar(38),
		code varchar(50),
		title varchar(150),
		printingorderacc varchar(50),
		dare decimal(19,2),
		avere decimal(19,2),
		section_cr char(1),
		placcount_sign char(1),
		patrimony_sign char(1),
		nriga int,
		nlevel char(1)
	)
	INSERT INTO #situazioneeconomica (idupb, codeupb, upb,idacc1, code1, desc1, order1, idacc2, code2, desc2, order2, idacc3, code3, desc3, order3, 
	idacc4, code4, desc4, order4, idacc5, code5, desc5, order5, idacc, code, title, printingorderacc, nlevel, dare, avere, section_cr,placcount_sign,patrimony_sign)
	EXEC rpt_bilanciodiverifica @ayear, @start, @stop, @levelusable,@idupb, @showchildupb, @suppressifblank
	UPDATE #situazioneeconomica SET dare = -avere, avere = NULL, section_cr = 'R' WHERE section_cr = 'C' AND dare < 0
	UPDATE #situazioneeconomica SET avere = -dare, dare = NULL, section_cr = 'C' WHERE section_cr = 'R' AND avere < 0
	
	CREATE TABLE #rptfinale
	(
		idupb varchar(36),
		codeupb varchar(50),
		upb varchar(150),
		idacc_c varchar(38),
		idacc_r varchar(38),
		printingorder_c varchar(50),
		printingorder_r varchar(50),
		importo_c decimal(19,2),
		importo_r decimal(19,2),
		nriga int
	)
	UPDATE #situazioneeconomica 
	SET section_cr = 'R'
	WHERE (ISNULL(dare,0) - ISNULL(avere,0)) < 0
	AND section_cr = 'C'
	UPDATE #situazioneeconomica
	SET section_cr = 'C'
	WHERE (ISNULL(avere,0) - ISNULL(dare,0)) < 0
	AND section_cr = 'R' 
	
	UPDATE #situazioneeconomica 
	SET section_cr = 'R'
	WHERE ISNULL(dare,0)=0 AND ISNULL(avere,0)= 0
	AND section_cr = 'C'
	AND placcount_sign = 'N'
	
	
	UPDATE #situazioneeconomica 
	SET section_cr = 'C'
	WHERE ISNULL(dare,0)=0 AND ISNULL(avere,0)= 0
	AND section_cr = 'R'
	AND placcount_sign = 'N'
	UPDATE #situazioneeconomica
	SET nriga =
	1 +
	ISNULL(
		(SELECT COUNT(*) FROM #situazioneeconomica r2
		WHERE r2.printingorderacc < #situazioneeconomica.printingorderacc
		AND r2.section_cr = 'C')
	,0)
	WHERE section_cr = 'C'
	
	UPDATE #situazioneeconomica
	SET nriga =
	1 +
	ISNULL(
		(SELECT COUNT(*) FROM #situazioneeconomica r2
		WHERE r2.printingorderacc < #situazioneeconomica.printingorderacc
		AND r2.section_cr = 'R')
	,0)
	WHERE section_cr = 'R'
	DECLARE @nriga_c int
	DECLARE @nriga_r int
	SET @nriga_c = ISNULL((SELECT MAX(nriga) FROM #situazioneeconomica WHERE section_cr = 'C'),0)
	SET @nriga_r = ISNULL((SELECT MAX(nriga) FROM #situazioneeconomica WHERE section_cr = 'R'),0)
	IF (@nriga_c >= @nriga_r)
	BEGIN
		INSERT INTO #rptfinale (idupb, codeupb, upb,idacc_c, printingorder_c, importo_c, nriga)
		SELECT idupb, codeupb, upb,idacc, printingorderacc, (ISNULL(dare,0) - ISNULL(avere,0)), nriga
		FROM #situazioneeconomica
		WHERE section_cr = 'C'
		ORDER BY nriga
		UPDATE #rptfinale
		SET idacc_r = idacc,
		printingorder_r = printingorderacc,
		importo_r = (ISNULL(avere,0) - ISNULL(dare,0))
		FROM #situazioneeconomica
		WHERE #situazioneeconomica.section_cr = 'R'
		AND #rptfinale.nriga = #situazioneeconomica.nriga
	END
	ELSE
	BEGIN
		INSERT INTO #rptfinale (idupb, codeupb, upb,idacc_r, printingorder_r, importo_r, nriga)
		SELECT idupb, codeupb, upb,idacc, printingorderacc, (ISNULL(avere,0) - ISNULL(dare,0)), nriga
		FROM #situazioneeconomica
		WHERE section_cr = 'R'
		ORDER BY nriga
		UPDATE #rptfinale
		SET idacc_c = idacc,
		printingorder_c = printingorderacc,
		importo_c = (ISNULL(dare,0) - ISNULL(avere,0))
		FROM #situazioneeconomica
		WHERE #situazioneeconomica.section_cr = 'C'
		AND #rptfinale.nriga = #situazioneeconomica.nriga
	END
	SELECT
	rf.idupb,
	rf.codeupb,
	rf.upb,
	rf.nriga,
	rf.idacc_c, r1.code AS code_c, r1.title AS desc_c,
	r1.idacc1 AS idacc1_c, r1.code1 AS code1_c, r1.desc1 AS desc1_c, r1.order1 AS order1_c,
	r1.idacc2 AS idacc2_c, r1.code2 AS code2_c, r1.desc2 AS desc2_c, r1.order2 AS order2_c,
	r1.idacc3 AS idacc3_c, r1.code3 AS code3_c, r1.desc3 AS desc3_c, r1.order3 AS order3_c,
	r1.idacc4 AS idacc4_c, r1.code4 AS code4_c, r1.desc4 AS desc4_c, r1.order4 AS order4_c,
	r1.idacc5 AS idacc5_c, r1.code5 AS code5_c, r1.desc5 AS desc5_c, r1.order5 AS order5_c,
	r1.nlevel AS nlevel_c,
	isnull(rf.importo_c,0) as importo_c,
	rf.printingorder_c,
	rf.idacc_r, r2.code AS code_r, r2.title AS desc_r,
	r2.idacc1 AS idacc1_r, r2.code1 AS code1_r, r2.desc1 AS desc1_r, r2.order1 AS order1_r,
	r2.idacc2 AS idacc2_r, r2.code2 AS code2_r, r2.desc2 AS desc2_r, r2.order2 AS order2_r,
	r2.idacc3 AS idacc3_r, r2.code3 AS code3_r, r2.desc3 AS desc3_r, r2.order3 AS order3_r,
	r2.idacc4 AS idacc4_r, r2.code4 AS code4_r, r2.desc4 AS desc4_r, r2.order4 AS order4_r,
	r2.idacc5 AS idacc5_r, r2.code5 AS code5_r, r2.desc5 AS desc5_r, r2.order5 AS order5_r,
	r2.nlevel AS nlevel_r,
	isnull(rf.importo_r,0) as importo_r,
	rf.printingorder_r
	FROM #rptfinale rf
	LEFT OUTER JOIN #situazioneeconomica r1
	ON r1.idacc = rf.idacc_c
	AND r1.section_cr = 'C'
	LEFT OUTER JOIN #situazioneeconomica r2
	ON r2.idacc = rf.idacc_r
	AND r2.section_cr = 'R'
	ORDER BY rf.nriga
END




GO

print '[rpt_situazioneeconomica] OK'

GO
if object_id('[esporta_fatture_dateincoerenti]') is not null
	drop PROCEDURE [esporta_fatture_dateincoerenti]
go

CREATE    PROCEDURE  [esporta_fatture_dateincoerenti]
	@ayear	int,
	@stop	smalldatetime,
	@idinvkind int,
	@unified char(1)  
AS BEGIN
-- EXEC unified_esporta_fatture_dateincoerenti 2008,{ts '2008-12-31 00:00:00'}, null,'N'
	DECLARE @departmentname varchar(500)
	SET  @departmentname  = ISNULL( (SELECT paramvalue from
			 generalreportparameter where idparam='DenominazioneDipartimento'  
				and  (start is null or year(start) <= @ayear) 
				and (stop is null or year(stop) >= @ayear)
				),'Manca Cfg. Parametri Tutte le stampe')

IF (@unified ='S')
Begin
	SELECT
		@departmentname as 'Dipartimento',
		invoicekind.description 'Tipo Documento',
		invoice.yinv 'Eserc.Documento',
		invoice.ninv 'Num. Documento',
		invoice.adate as 'Data Registrazione'
	FROM invoice 
	JOIN invoicekind 
		ON invoicekind.idinvkind = invoice.idinvkind
	WHERE (invoice.idinvkind = @idinvkind OR @idinvkind IS NULL)
			AND invoice.adate <= @stop			
			AND invoice.yinv = @ayear
		AND ( select count(*) from invoice i2
				where i2.yinv = @ayear
					AND i2.idinvkind = invoice.idinvkind
					AND i2.ninv < invoice.ninv
					AND i2.adate <= invoice.adate )
			<>
			(select count(*) from invoice i3
				where i3.yinv = @ayear
					AND i3.idinvkind = invoice.idinvkind
					AND i3.ninv <invoice.ninv)
	ORDER BY invoicekind.description
End
Else
Begin
	SELECT
		invoicekind.description 'Tipo Documento',
		invoice.yinv 'Eserc.Documento',
		invoice.ninv 'Num. Documento',
		invoice.adate as 'Data Registrazione'
	FROM invoice 
	JOIN invoicekind 
		ON invoicekind.idinvkind = invoice.idinvkind
	WHERE (invoice.idinvkind = @idinvkind OR @idinvkind IS NULL)
			AND invoice.adate <= @stop			
			AND invoice.yinv = @ayear
		AND ( select count(*) from invoice i2
				where i2.yinv = @ayear
					AND i2.idinvkind = invoice.idinvkind
					AND i2.ninv < invoice.ninv
					AND i2.adate <= invoice.adate )
			<>
			(select count(*) from invoice i3
				where i3.yinv = @ayear
					AND i3.idinvkind = invoice.idinvkind
					AND i3.ninv <invoice.ninv)
	ORDER BY invoicekind.description
End
END

GO

print '[esporta_fatture_dateincoerenti] OK'

GO
if object_id('[esporta_rivalutazioni_accessori_beni_scaricati_ente]') is not null
	drop PROCEDURE [esporta_rivalutazioni_accessori_beni_scaricati_ente]
go

CREATE         PROCEDURE [esporta_rivalutazioni_accessori_beni_scaricati_ente]
@year			int,
@idinventoryagency	int,
@date			datetime,
@idinv			int,
@flagcategory		char(1)
AS BEGIN
------------------------------------------------------------------------
--- RIVALUTAZIONI POSITIVE E NEGATIVE di Accessori di beni scaricati ---
------------------------------------------------------------------------
	declare @firstlevelidinv int
	select @firstlevelidinv = idparent from inventorytreelink where idchild=@idinv and nlevel=1
	DECLARE @firstday datetime
	select @firstday = dateadd(yy, @year-1753, {d '1753-01-01'})
   	SELECT
		inventoryamortization.description 	as 'Tipo Rivalutazione',
		assetamortization.namortization		as 'Numero Rivalutazione',
		inventoryagency.codeinventoryagency	as 'Cod. Ente Inventario',
		inventoryagency.description  		as 'Ente Inventario', 
		inventory.description      		as 'Inventario',  
		inventorykind.description  		as 'Tipo Inventario',
		cespite.ninventory			as 'Numero inventario Cespite ',
		caricoaccessorio.nassetacquire 		as 'Carico Accessorio',
		caricoaccessorio.description   		as 'Descrizione',
		assetloadkind.codeassetloadkind 	as 'Codice Tipo Buono',
		assetload.yassetload     	as 'Eserc. Buono Carico',
		assetload.nassetload      	as 'Num. Buono Carico',
		categoriainventariale.codeinv	as 'Categoria Inventariale',
		ISNULL(ROUND(ISNULL(assetamortization.assetvalue,0) * 
		ISNULL(assetamortization.amortizationquota,0),2),0)  as 'Importo Rivalutazione'
	FROM assetacquire as caricoaccessorio
	JOIN asset as accessorio 
		ON caricoaccessorio.nassetacquire = accessorio.nassetacquire
	join assetload on assetload.idassetload = caricoaccessorio.idassetload
	join assetloadkind on assetloadkind.idassetloadkind = assetload.idassetload
	
	JOIN asset as cespite
		ON cespite.idasset = accessorio.idasset
	JOIN assetunload as scaricocespite
		ON scaricocespite.idassetunload = cespite.idassetunload
	JOIN inventory
		ON caricoaccessorio.idinventory = inventory.idinventory
	JOIN inventoryagency
		ON inventory.idinventoryagency = inventoryagency.idinventoryagency
	JOIN inventorykind
		ON inventory.idinventorykind= inventorykind.idinventorykind   
	JOIN assetamortization
		ON assetamortization.idasset = accessorio.idasset and assetamortization.idpiece = accessorio.idpiece
	JOIN inventoryamortization
		ON inventoryamortization.idinventoryamortization = assetamortization.idinventoryamortization
	join inventorytreelink as linkcategoria
		on linkcategoria.idchild = caricoaccessorio.idinv and linkcategoria.nlevel = 1
	join inventorytree as categoriainventariale
		on categoriainventariale.idinv = linkcategoria.idparent
	WHERE 	accessorio.idpiece>1 
		AND cespite.idpiece =1
		AND ((ISNULL(assetamortization.amortizationquota,0)>0) 
			OR (assetamortization.flag & 1 = 0) OR (assetamortization.idassetunload is not null)
		    )
		AND scaricocespite.yassetunload <= @year
		AND scaricocespite.adate <= @date
		AND scaricocespite.adate >= @firstday
		AND inventory.idinventoryagency = isnull(@idinventoryagency, inventory.idinventoryagency)
		AND (@idinv is null 
			or categoriainventariale.idinv = @firstlevelidinv AND @flagcategory = 'S'
	       		OR caricoaccessorio.idinv = @idinv AND @flagcategory = 'N')
END


GO

print '[esporta_rivalutazioni_accessori_beni_scaricati_ente] OK'

