if object_id('[exp_residual_miur]') is not null
	drop PROCEDURE [exp_residual_miur]
go

CREATE     PROCEDURE [exp_residual_miur] 
(
	@ayear int,
	@finpart char(1)
)
AS BEGIN
-- Per natura
DECLARE @iMIUR INT
DECLARE @eMIUR INT
DECLARE @MIUR INT
DECLARE @iSIOPE INT
DECLARE @eSIOPE INT
SELECT @iMIUR = idsorkind from sortingkind where codesorkind = '07E_MIUR'
SELECT @eMIUR = idsorkind from sortingkind where codesorkind = '07U_MIUR'
DECLARE @fase_MIUR varchar(50)
DECLARE @codesorkind varchar(20)
DECLARE @sortingkind varchar(50)

-- Creazione della Tabella che visualizzerà il riepilogo dei dati su foglio Excel
CREATE TABLE #mov_res 
			(idmov varchar(40), 
			 ymov int,
			 nmov int,
			 amount decimal(19,2), 
			 curramount decimal(19,2), 
			 varamount decimal(19,2))
CREATE TABLE #var_res (idmov varchar(40), amount decimal(19,2))
CREATE TABLE #class
(
	idmov int,
	ymov int,
	nmov int,		
	idsor int,
	amount decimal(19,2),
	sortcode varchar(30),
	rowkind char(1) -- Campo che vale 'P' = Movimento Principale, 'V' = Variazioni
)
DECLARE @phaseMIUR tinyint -- Fase di entrata/spesa associata alla classificazione MIUR
-- Codice per i movimenti di entrata 
IF @finpart = 'E'
BEGIN
	SELECT  @phaseMIUR = nphaseincome FROM sortingkind WHERE idsorkind  = @iMIUR
	SELECT  @fase_MIUR = description FROM incomephase WHERE nphase = @phaseMIUR
	SET		@MIUR = @iMIUR
	
	INSERT INTO #mov_res (idmov, ymov, nmov, amount, curramount, varamount)
	SELECT incomeyear.idinc, income.ymov, income.nmov, incomeyear.amount, incometotal.curramount, 
	ISNULL(
		(SELECT SUM(amount)
		FROM incomevar
		WHERE incomevar.idinc = incomeyear.idinc
		AND incomevar.yvar = incomeyear.ayear)
	,0)
	FROM incomeyear
	join income on income.idinc = incomeyear.idinc
	JOIN incometotal
		ON incomeyear.idinc = incometotal.idinc
		AND incomeyear.ayear = incometotal.ayear
	WHERE incomeyear.ayear = @ayear
		AND income.nphase = @phaseMIUR
		AND ((incometotal.flag&1)=1)   ---Residuo
	AND ISNULL(
		(SELECT SUM(amount)
		FROM incomevar
		WHERE incomevar.idinc = incomeyear.idinc
		AND incomevar.yvar = incomeyear.ayear)
	,0) <>0
	INSERT INTO #var_res (idmov, amount)
	SELECT incomeyear.idinc, SUM(incomevar.amount)
	FROM incomeyear
	join income on incomeyear.idinc = income.idinc
	join incometotal on incomeyear.idinc = incometotal.idinc and incomeyear.ayear = incometotal.ayear
	JOIN incomevar
		ON incomevar.idinc = incomeyear.idinc
		AND incomevar.yvar = incomeyear.ayear
	WHERE incomeyear.ayear = @ayear
		AND income.nphase = @phaseMIUR
		AND ((incometotal.flag&1)=1) ---Residuo
	GROUP BY incomeyear.idinc
		
	-- Caso 2. Movimento di Entrata con variazioni
	-- Inserimento di dettagli SIOPE sul mov. principale riferito alle trattenute (calcolo per rapporto)
	INSERT INTO #class (idmov, ymov, nmov, idsor, sortcode)
	SELECT #mov_res.idmov, #mov_res.ymov, #mov_res.nmov, incomesorted.idsor, sorting.sortcode
	FROM #var_res
	JOIN #mov_res
		ON #var_res.idmov = #mov_res.idmov
	JOIN incomesorted
		ON #mov_res.idmov = incomesorted.idinc
	JOIN sorting
		ON sorting.idsor = incomesorted.idsor
	WHERE sorting.idsorkind = @iMIUR
		AND #mov_res.varamount <> 0
		AND incomesorted.ayear = @ayear
		AND (SELECT COUNT(DISTINCT INS.idsor) 
			   FROM incomesorted INS 
			   JOIN sorting S
				 ON S.idsor = INS.idsor
			  WHERE INS.ayear = incomesorted.ayear 
				AND INS.idinc = incomesorted.idinc
				AND S.idsorkind = @iMIUR) > 1
	GROUP BY #mov_res.idmov, #mov_res.ymov, #mov_res.nmov, 
			 sorting.sortcode, #var_res.amount, #mov_res.curramount, incomesorted.idsor
		
END	-- Fine codice per i movimenti di entrata
ELSE
-- Codice per i movimenti di spesa
BEGIN	
	SELECT  @phaseMIUR = nphaseexpense FROM sortingkind WHERE idsorkind  = @eMIUR
	SELECT  @fase_MIUR = description FROM expensephase WHERE nphase = @phaseMIUR
	SET		@MIUR = @eMIUR 
	
	print @phaseMIUR 
	print @fase_MIUR 
	print @MIUR
	
	INSERT INTO #mov_res (idmov, ymov, nmov, amount, curramount, varamount)
	SELECT expenseyear.idexp,expense.ymov, expense.nmov, expenseyear.amount, expensetotal.curramount, 
	ISNULL(
		(SELECT SUM(amount)
		FROM expensevar
		WHERE expensevar.idexp = expenseyear.idexp
		AND expensevar.yvar = expenseyear.ayear)
	,0)
	FROM expenseyear
	join expense on expense.idexp = expenseyear.idexp
	JOIN expensetotal
		ON expenseyear.idexp = expensetotal.idexp
		AND expenseyear.ayear = expensetotal.ayear
	WHERE expenseyear.ayear = @ayear
		AND expense.nphase = @phaseMIUR
		AND ((expensetotal.flag&1)=1)   ---Residuo
	AND ISNULL(
		(SELECT SUM(amount)
		FROM expensevar
		WHERE expensevar.idexp = expenseyear.idexp
		AND expensevar.yvar = expenseyear.ayear)
	,0) <> 0
	INSERT INTO #var_res (idmov, amount)
	SELECT expensevar.idexp, SUM(expensevar.amount)
	FROM expenseyear
	join expense on expense.idexp = expenseyear.idexp
	join expensetotal on expensetotal.idexp=expenseyear.idexp and expensetotal.ayear=expenseyear.ayear
	JOIN expensevar
		ON expenseyear.idexp = expensevar.idexp
		AND expenseyear.ayear = expensevar.yvar
	WHERE expenseyear.ayear = @ayear
		AND ((expensetotal.flag&1)=1)  ---Residuo
		AND expense.nphase = @phaseMIUR
	GROUP BY expensevar.idexp
	INSERT INTO #class (idmov, ymov,nmov,idsor, sortcode)
	SELECT #mov_res.idmov, #mov_res.ymov, #mov_res.nmov, expensesorted.idsor, sorting.sortcode
	FROM #mov_res
	JOIN expensesorted
		ON #mov_res.idmov = expensesorted.idexp
	JOIN sorting
		ON sorting.idsor = expensesorted.idsor
	WHERE sorting.idsorkind = @eMIUR
		AND #mov_res.varamount <> 0
		AND expensesorted.ayear = @ayear
		AND (SELECT COUNT(DISTINCT ES.idsor) 
			   FROM expensesorted ES 
			   JOIN sorting S
				ON  S.idsor = ES.idsor
			  WHERE ES.ayear = expensesorted.ayear 
				AND ES.idexp = expensesorted.idexp
				AND S.idsorkind = @eMIUR) > 1
	GROUP BY #mov_res.idmov, #mov_res.ymov,#mov_res.nmov, expensesorted.idsor, sorting.sortcode	
END	-- Fine codice per i movimenti di spesa
--select * from #mov_res
--select * from #var_res
select @codesorkind = codesorkind from sortingkind where idsorkind = @MIUR
select @sortingkind = description from sortingkind where idsorkind = @MIUR
select  @fase_MIUR + ' residuo ' + CONVERT(varchar(4), #class.ymov) + '/' + 
		CONVERT(varchar(10), #class.nmov) +
	    ' classificato secondo la classificazione '
		+ @sortingkind + ' (' + @codesorkind + ') ' 
		+ ' con codice '  + #class.sortcode
from #class order by #class.ymov, #class.nmov
END
--[exp_residual_miur] 2010, 'S'


GO

print '[exp_residual_miur] OK'

GO
if object_id('[rpt_situazionepatrimoniale]') is not null
	drop PROCEDURE [rpt_situazionepatrimoniale]
go

CREATE  PROCEDURE [rpt_situazionepatrimoniale]
(
	@ayear int,
	@start datetime,
	@stop datetime,
	@levelusable char(1),
	@idupb		varchar(36),
	@showchildupb	char(1),
	@suppressifblank char(1)
)
AS BEGIN
	--[rpt_situazionepatrimoniale]  2011, {ts '2011-01-20 00:00:00'}, {ts '2011-12-31 00:00:00'}, 3, '0001', 'S', 'N'
	CREATE TABLE #situazionepatrimoniale
	(
		idupb varchar(36),
		codeupb varchar(50),
		upb varchar(150),
		idacc1 varchar(38),
		code1 varchar(50),
		desc1 varchar(150),
		order1 varchar(50),
		idacc2 varchar(38),
		code2 varchar(50),
		desc2 varchar(150),
		order2 varchar(50),
		idacc3 varchar(38),
		code3 varchar(50),
		desc3 varchar(150),
		order3 varchar(50),
		idacc4 varchar(38),
		code4 varchar(50),
		desc4 varchar(150),
		order4 varchar(50),
		idacc5 varchar(38),
		code5 varchar(50),
		desc5 varchar(150),
		order5 varchar(50),
		idacc varchar(38),
		code varchar(50),
		title varchar(150),
		printingorderacc varchar(50),
		dare decimal(19,2),
		avere decimal(19,2),
		section_ap char(1),
		placcount_sign char(1),
		patrimony_sign char(1),
		nriga int,
		nlevel char(1)
	)
	INSERT INTO #situazionepatrimoniale (idupb, codeupb, upb,idacc1, code1, desc1, order1, idacc2, code2, desc2, order2, idacc3, code3, desc3, order3, 
	idacc4, code4, desc4, order4, idacc5, code5, desc5, order5, idacc, code, title, printingorderacc, nlevel, dare, avere, section_ap, placcount_sign, patrimony_sign)
	EXEC rpt_bilanciodiverifica @ayear, @start, @stop, @levelusable,@idupb, @showchildupb, @suppressifblank
	
	CREATE TABLE #rptfinale
	(
		
		idupb varchar(36),
		codeupb varchar(50),
		upb varchar(150),
		idacc_a varchar(38),
		idacc_p varchar(38),
		printingorder_a varchar(50),
		printingorder_p varchar(50),
		importo_a decimal(19,2),
		importo_p decimal(19,2),
		nriga int
	)
	UPDATE #situazionepatrimoniale 
	SET section_ap = 'P'
	WHERE (ISNULL(dare,0) - ISNULL(avere,0)) < 0
	AND section_ap = 'A'
	UPDATE #situazionepatrimoniale
	SET section_ap = 'A'
	WHERE (ISNULL(avere,0) - ISNULL(dare,0)) < 0
	AND section_ap = 'P'
	
	UPDATE #situazionepatrimoniale 
	SET section_ap = 'A'
	WHERE ISNULL(dare,0)=0 AND ISNULL(avere,0)= 0
	AND section_ap = 'P'
	AND patrimony_sign = 'N'
	UPDATE #situazionepatrimoniale
	SET section_ap = 'P'
	WHERE ISNULL(dare,0)=0 AND ISNULL(avere,0)= 0
	AND section_ap = 'A'
	AND patrimony_sign = 'N'
	UPDATE #situazionepatrimoniale
	SET nriga =
	1 +
	ISNULL(
		(SELECT COUNT(*) FROM #situazionepatrimoniale r2
		WHERE r2.printingorderacc < #situazionepatrimoniale.printingorderacc
		AND r2.section_ap = #situazionepatrimoniale.section_ap)
	,0)
	WHERE section_ap = 'A'
	
	UPDATE #situazionepatrimoniale
	SET nriga =
	1 +
	ISNULL(
		(SELECT COUNT(*) FROM #situazionepatrimoniale r2
		WHERE r2.printingorderacc < #situazionepatrimoniale.printingorderacc
		AND r2.section_ap = #situazionepatrimoniale.section_ap)
	,0)
	WHERE section_ap = 'P'
	
	DECLARE @nriga_a int
	DECLARE @nriga_p int
	SET @nriga_a = ISNULL((SELECT MAX(nriga) FROM #situazionepatrimoniale WHERE section_ap = 'A'),0)
	SET @nriga_p = ISNULL((SELECT MAX(nriga) FROM #situazionepatrimoniale WHERE section_ap = 'P'),0)
	
	IF (@nriga_a >= @nriga_p)
	BEGIN
		INSERT INTO #rptfinale (idupb, codeupb, upb,idacc_a, printingorder_a, importo_a, nriga)
		SELECT idupb, codeupb, upb,idacc, printingorderacc, (ISNULL(dare,0) - ISNULL(avere,0)), nriga
		FROM #situazionepatrimoniale
		WHERE section_ap = 'A'
		ORDER BY nriga
		UPDATE #rptfinale
		SET idacc_p = idacc,
		printingorder_p = printingorderacc,
		importo_p = (ISNULL(avere,0) - ISNULL(dare,0))
		FROM #situazionepatrimoniale
		WHERE #situazionepatrimoniale.section_ap = 'P'
		AND #rptfinale.nriga = #situazionepatrimoniale.nriga
	
	END
	ELSE
	BEGIN
		INSERT INTO #rptfinale (idupb, codeupb, upb,idacc_p, printingorder_p, importo_p, nriga)
		SELECT idupb, codeupb, upb,idacc, printingorderacc, (ISNULL(avere,0) - ISNULL(dare,0)), nriga
		FROM #situazionepatrimoniale
		WHERE section_ap = 'P'
		ORDER BY nriga
		UPDATE #rptfinale
		SET idacc_a = idacc,
		printingorder_a = printingorderacc,
		importo_a = (ISNULL(dare,0) - ISNULL(avere,0))
		FROM #situazionepatrimoniale
		WHERE #situazionepatrimoniale.section_ap = 'A'
		AND #rptfinale.nriga = #situazionepatrimoniale.nriga
	END
	
	SELECT
	rf.idupb,
	rf.codeupb,
	rf.upb,
	rf.nriga,
	rf.idacc_a, r1.code AS code_a, r1.title AS desc_a,
	r1.idacc1 AS idacc1_a, r1.code1 AS code1_a, r1.desc1 AS desc1_a, r1.order1 AS order1_a,
	r1.idacc2 AS idacc2_a, r1.code2 AS code2_a, r1.desc2 AS desc2_a, r1.order2 AS order2_a,
	r1.idacc3 AS idacc3_a, r1.code3 AS code3_a, r1.desc3 AS desc3_a, r1.order3 AS order3_a,
	r1.idacc4 AS idacc4_a, r1.code4 AS code4_a, r1.desc4 AS desc4_a, r1.order4 AS order4_a,
	r1.idacc5 AS idacc5_a, r1.code5 AS code5_a, r1.desc5 AS desc5_a, r1.order5 AS order5_a,
	r1.nlevel AS nlevel_a,
	isnull(rf.importo_a,0) as importo_a,
	rf.printingorder_a,
	rf.idacc_p, r2.code AS code_p, r2.title AS desc_p,
	r2.idacc1 AS idacc1_p, r2.code1 AS code1_p, r2.desc1 AS desc1_p, r2.order1 AS order1_p,
	r2.idacc2 AS idacc2_p, r2.code2 AS code2_p, r2.desc2 AS desc2_p, r2.order2 AS order2_p,
	r2.idacc3 AS idacc3_p, r2.code3 AS code3_p, r2.desc3 AS desc3_p, r2.order3 AS order3_p,
	r2.idacc4 AS idacc4_p, r2.code4 AS code4_p, r2.desc4 AS desc4_p, r2.order4 AS order4_p,
	r2.idacc5 AS idacc5_p, r2.code5 AS code5_p, r2.desc5 AS desc5_p, r2.order5 AS order5_p,
	r2.nlevel AS nlevel_p,
	isnull(rf.importo_p,0) as importo_p,
	rf.printingorder_p
	FROM #rptfinale rf
	LEFT OUTER JOIN #situazionepatrimoniale r1
	ON r1.idacc = rf.idacc_a
	AND r1.section_ap = 'A'
	LEFT OUTER JOIN #situazionepatrimoniale r2
	ON r2.idacc = rf.idacc_p
	AND r2.section_ap = 'P'
	ORDER BY rf.nriga
END




