if object_id('esporta_anagrafica_ascii') is not null
	drop PROCEDURE esporta_anagrafica_ascii
go

--sp_help registryaddress

CREATE    PROCEDURE esporta_anagrafica_ascii AS
BEGIN
-- E' la tabella contenete l'output finale
CREATE TABLE  #result
(
	--------------------------------------------------------------
	-----------------------INFORMAZIONI ANAGRAFICHE---------------
	--------------------------------------------------------------
	idreg int,   			--lunghezza 10
	idregistryclass varchar(2),	--tipologia lunghezza 2
	residence	char,		--tipo residenza I J X poi sarà char
	title varchar(100),   		--denominazione
	surname varchar(50),		--cognome
	forename varchar(50),		--nome
	gender char,			--sesso
	p_iva	varchar(15),		--partita iva
	cf      varchar(16),		--codice fiscale
	foreigncf varchar(40),		--codice fiscale estero dovrà avere lunghezza 20 nel tracciato	
	b_date datetime,		--data di nascita
	location varchar(50),		--località nascita
	codice_catastale varchar(4),	--generalmente sono gli ultimi 4 caratteri del codice fiscale
	matricola  varchar(40),		--numero di matricola
	note varchar(400),		--note
	esente_equitalia char,		--S/N
	ammetti_cf_duplicato  char,	--S/N
	attiva		char,		--S/N
	---------------------------------------------------------------
	----------INDIRIZZO PREDEFINITO/RESIDENZA----------------------
	---------------------------------------------------------------
	start_def	datetime,	-- inizio validità predefinito/residenza
	address_def	varchar(100),	-- indirizzo predefinito/residenza
	cap_def		varchar(5),	-- CAP predefinito/residenza
	officename_def	varchar(50),	-- nome ufficio predefinito/residenza
	codice_catastale_def varchar(4),-- codice catastale predefinito/residenza
	location_def	varchar(50),	-- localita dell'indirizzo di residenza
	---------------------------------------------------------------
	----------DOMICILIO FISCALE OVE DIVERSO DAL PREDEFINITO--------
	---------------------------------------------------------------
	start_domfis	datetime,	-- inizio validità domicilio fiscale
	address_domfis	varchar(100),	-- indirizzo  domicilio fiscale
	cap_domfis	varchar(5),	-- CAP  domicilio fiscale
	officename_domfis varchar(50),	-- nome ufficio  domicilio fiscale
	codice_catastale_domfis varchar(4),-- codice catastale  domicilio fiscale
	location_domfis varchar(50),	-- localita dell'indirizzo di residenza
	---------------------------------------------------------------
	---------------------MODALITA' DI PAGAMENTO--------------------
	---------------------------------------------------------------
	idpaymethod int,		-- tipo codificato della modalità di pagamento
	paymethod   varchar(50),	-- nome della modalità di pagamento
	abi	 varchar(20),		-- codice ABI Ist. Bancario
	cab	varchar(20), 		-- codice CAB Sportello
	cc	varchar(30),		-- codice del conto corrente
	cin	varchar(20),		-- codice CIN deve essere di 5 caratteri
	delegate int,			-- codice di un delegato (riferito ad altra anagrafica)
	currency varchar(3), 		-- codice ISO 4217 della valuta
	idexpirationkind int,	 	-- tipo scadenza codificato
	ggscadenza	int,		-- numero dei giorni scadenza
	iban		varchar(50)	-- codice IBAN
)


CREATE TABLE #trace
(
	out_str varchar(1381)
)
INSERT INTO #result
(
idreg, idregistryclass, residence,title,
surname,forename,gender,p_iva,
cf,foreigncf,b_date,location,
codice_catastale,matricola,note,esente_equitalia,
ammetti_cf_duplicato,attiva,
start_def,address_def,cap_def,officename_def,codice_catastale_def,location_def,
start_domfis,address_domfis,cap_domfis,officename_domfis,codice_catastale_domfis,location_domfis,
idpaymethod,paymethod,abi,cab,
cc,cin,delegate,currency,
idexpirationkind,
ggscadenza,
iban
)
SELECT 
R.idreg, R.idregistryclass, 
--residence.coderesidence, 
CASE
	WHEN residence.description like '%in Italia%' then 'I'
	WHEN residence.description like '%altri paesi dell''UE%' then 'J'
	WHEN residence.description like '%fuori dall''UE%' then 'X'
	WHEN residence.description like '%trasferimenti interni%' then 'I'
	ELSE 'I' -- metto I in caso di altri valori
	End,
R.title,
R.surname, R.forename,R.gender,R.p_iva,
R.cf,R.foreigncf,R.birthdate,R.location,
convert(varchar(4),CITY_BIRTH.value),R.extmatricula,R.annotation, R.authorization_free, 
R.multi_cf,R.active,
RA_DEF.start, RA_DEF.address, RA_DEF.cap,RA_DEF.officename, 
convert(varchar(4),CITY_DEF.value),RA_DEF.location,
RA_DOMFIS.start, RA_DOMFIS.address, RA_DOMFIS.cap,RA_DOMFIS.officename, 
convert(varchar(4),CITY_DOMFIS.value),RA_DOMFIS.location,
CASE
	WHEN PM.description like '%Assegno circolare%' then 1
	WHEN PM.description like '%Bonifico presso altre banche%' then 3
	WHEN PM.description like '%Bonifico presso istituto cassiere%' then 4
	WHEN PM.description like '%Conto corrente postale%' then 5
	WHEN PM.description like '%Esclusiva cassiere%' then 6
	WHEN PM.description like '%Sportello%' then 7
	Else null
	End,
PM.description,RPM.idbank,RPM.idcab,
RPM.cc,RPM.cin,RPM.iddeputy,CURR.codecurrency,
RPM.idexpirationkind,  
RPM.paymentexpiring, 
RPM.iban
FROM registry R
LEFT OUTER JOIN registryaddress RA_DEF 
	ON R.idreg = RA_DEF.idreg
	AND RA_DEF.active = 'S'
	AND RA_DEF.stop is null
	AND RA_DEF.start = (SELECT MAX(start) 
		     FROM registryaddress RA_DEF1 
		     WHERE  RA_DEF1.idreg =  RA_DEF.idreg 
		     AND  RA_DEF1.idaddresskind =  RA_DEF.idaddresskind )
JOIN address AD_DEF
	ON AD_DEF.idaddress = RA_DEF.idaddresskind
	AND AD_DEF.codeaddress = '07_SW_DEF'
LEFT OUTER JOIN residence  
	ON residence.idresidence = R.residence
LEFT OUTER JOIN registryaddress RA_DOMFIS
	ON R.idreg = RA_DOMFIS.idreg
	AND RA_DOMFIS.active = 'S'
	AND RA_DOMFIS.stop is null
	AND RA_DOMFIS.start = (SELECT MAX(start) 
		     FROM registryaddress RA_DOMFIS1 
		     WHERE  RA_DOMFIS1.idreg =  RA_DOMFIS.idreg 
		     AND  RA_DOMFIS1.idaddresskind =  RA_DOMFIS.idaddresskind )
	AND RA_DOMFIS.address <> RA_DEF.address
JOIN address AD_DOMFIS
	ON AD_DOMFIS.idaddress = RA_DOMFIS.idaddresskind
	AND AD_DOMFIS.codeaddress = '07_SW_DOM'
LEFT OUTER JOIN registrypaymethod RPM
	ON R.idreg = RPM.idreg
	AND RPM.flagstandard = 'S'
	AND RPM.active = 'S'
JOIN paymethod PM 
	ON RPM.idpaymethod = PM.idpaymethod
LEFT OUTER JOIN currency CURR 
	ON RPM.idcurrency = CURR.idcurrency
LEFT OUTER JOIN geo_city_agencyview CITY_BIRTH 
	ON CITY_BIRTH.idcity = R.idcity
	AND CITY_BIRTH.codename = 'fiscale'
LEFT OUTER JOIN geo_city_agencyview CITY_DEF 
	ON CITY_DEF.idcity = RA_DEF.idcity
	AND CITY_DEF.codename = 'fiscale'
LEFT OUTER JOIN geo_city_agencyview CITY_DOMFIS 
	ON CITY_DOMFIS.idcity = RA_DOMFIS.idcity
	AND CITY_DOMFIS.codename = 'fiscale'


DECLARE @cursore cursor

	--------------------------------------------------------------
	-----------------------INFORMAZIONI ANAGRAFICHE---------------
	--------------------------------------------------------------
DECLARE @idreg int   			
DECLARE @idregistryclass varchar(2)	
DECLARE	@residence	char		
DECLARE	@title varchar(100)   		
DECLARE	@surname varchar(50)		
DECLARE	@forename varchar(50)		
