DECLARE	@cab	varchar(20) 		
DECLARE	@cc	varchar(30)		
DECLARE	@cin	varchar(20)		
DECLARE	@delegate int	
DECLARE	@currency varchar(3) 		
DECLARE	@idexpirationkind int 	
DECLARE	@ggscadenza	int	
DECLARE	@iban		varchar(50)	

SET @cursore = CURSOR FOR
SELECT  
	idreg,idregistryclass,residence,title,
	surname,forename,gender,p_iva,
	cf,foreigncf,b_date,location,
	codice_catastale,matricola,note,esente_equitalia,
	ammetti_cf_duplicato,attiva,
	start_def,address_def,cap_def,officename_def,
	codice_catastale_def,location_def,
	start_domfis,address_domfis,cap_domfis,officename_domfis,
	codice_catastale_domfis,location_domfis,
	idpaymethod,paymethod,abi,cab,
	cc,cin,delegate,currency,
	idexpirationkind,
	ggscadenza,
	iban
FROM #result
ORDER BY idreg

OPEN @cursore
FETCH NEXT FROM @cursore INTO 
	  @idreg, @idregistryclass, @residence, @title, @surname, @forename, @gender --213
	, @p_iva, @cf, @foreigncf, @b_date, @location --109
	, @codice_catastale, @matricola, @note, @esente_equitalia --445
	, @ammetti_cf_duplicato, @attiva --2
	, @start_def, @address_def, @cap_def, @officename_def --163
	, @codice_catastale_def, @location_def --57
	, @start_domfis, @address_domfis, @cap_domfis, @officename_domfis --163
	, @codice_catastale_domfis, @location_domfis --57
	, @idpaymethod, @paymethod, @abi, @cab --71
	, @cc, @cin, @delegate, @currency --48
	, @idexpirationkind, @ggscadenza, @iban -- 53
WHILE (@@FETCH_STATUS = 0)
BEGIN
	--select * from paymethod
	DECLARE @string  varchar(1381)
	SET @string = 
	  [dbo].GetInt(@idreg, 10)  + [dbo].GetStringFormatted(@idregistryclass,2) + 
	  [dbo].GetStringFormatted(@residence,1) + 
	  [dbo].GetStringFormatted(@title,100) + [dbo].GetStringFormatted(@surname,50) + [dbo].GetStringFormatted(@forename,50) + 
	  [dbo].GetStringFormatted(@gender,1) +
	  [dbo].GetStringFormatted(@p_iva,15) + [dbo].GetStringFormatted(@cf,16) + 
	  [dbo].GetStringFormatted(@foreigncf,20) + [dbo].GetData(@b_date) +
	  [dbo].GetStringFormatted(@location, 50)+ [dbo].GetStringFormatted(@codice_catastale,4) + 
