	  [dbo].GetStringFormatted(@esente_equitalia,1) + [dbo].GetStringFormatted(@ammetti_cf_duplicato,1) +
	  [dbo].GetStringFormatted(@attiva,1) +  [dbo].GetData(@start_def) + 
	  [dbo].GetStringFormatted(@address_def,100) + [dbo].GetStringFormatted(@cap_def,5)+
	  [dbo].GetStringFormatted(@officename_def,50) + [dbo].GetStringFormatted(@codice_catastale_def,4) +
	  [dbo].GetStringFormatted(@location_def,50) +
	  [dbo].GetData(@start_domfis) + [dbo].GetStringFormatted(@address_domfis,100)+ 
	  [dbo].GetStringFormatted(@cap_domfis,5)+
	  [dbo].GetStringFormatted(@officename_domfis,50) + 
	  [dbo].GetStringFormatted(@codice_catastale_domfis,4)+
	  [dbo].GetStringFormatted(@location_domfis,50) +
	  [dbo].GetInt(@idpaymethod,1) + [dbo].GetStringFormatted(@paymethod,50)+  
	  [dbo].GetStringFormatted(@abi,10)+ [dbo].GetStringFormatted(@cab,10)+
	  [dbo].GetStringFormatted(@cc,30) + [dbo].GetStringFormatted(@cin,5)+ 
	  [dbo].GetInt(@delegate,10)+ [dbo].GetStringFormatted(@currency,3) +
	  [dbo].GetInt(@idexpirationkind,1) + [dbo].GetInt(@ggscadenza,2) + [dbo].GetStringFormatted(@iban,50)
	
/*
	print len(@string)
	select @idreg,[dbo].GetInt(@idreg, 10)  
	select @idregistryclass,[dbo].GetStringFormatted(@idregistryclass,2) 
	select @residence,[dbo].GetStringFormatted(@residence,1) 
	select @title,[dbo].GetStringFormatted(@title,100) 
	select @surname,[dbo].GetStringFormatted(@surname,50) 
	select @forename,[dbo].GetStringFormatted(@forename,50) 
	select @gender,[dbo].GetStringFormatted(@gender,1) 
	select @p_iva,[dbo].GetStringFormatted(@p_iva,15) 
	select @cf,[dbo].GetStringFormatted(@cf,16) 
	select @foreigncf,[dbo].GetStringFormatted(@foreigncf,20) 
	select @b_date,[dbo].GetData(@b_date) 
	select @location,[dbo].GetStringFormatted(@location, 50)
        select @codice_catastale,[dbo].GetStringFormatted(@codice_catastale,4) 
        select @matricola,[dbo].GetStringFormatted(@matricola,40) 
        select @note,[dbo].GetStringFormatted(@note,400)
        select @esente_equitalia,[dbo].GetStringFormatted(@esente_equitalia,1) 
        select @ammetti_cf_duplicato,[dbo].GetStringFormatted(@ammetti_cf_duplicato,1) 
        select @attiva,[dbo].GetStringFormatted(@attiva,1) 
        select @start_def,[dbo].GetData(@start_def) 
        select @address_def,[dbo].GetStringFormatted(@address_def,100) 
	select @cap_def,[dbo].GetStringFormatted(@cap_def,5)
	select @officename_def,[dbo].GetStringFormatted(@officename_def,50) 
	select @codice_catastale_def,[dbo].GetStringFormatted(@codice_catastale_def,4) 
	select @location_def,[dbo].GetStringFormatted(@location_def,50) 
	select @start_domfis,[dbo].GetData(@start_domfis) 
	select @address_domfis,[dbo].GetStringFormatted(@address_domfis,100)
	select @cap_domfis,[dbo].GetStringFormatted(@cap_domfis,5)
	select @officename_domfis,[dbo].GetStringFormatted(@officename_domfis,50) 
	select @codice_catastale_domfis,[dbo].GetStringFormatted(@codice_catastale_domfis,4)
	select @location_domfis,[dbo].GetStringFormatted(@location_domfis,50) 
	select @idpaymethod,[dbo].GetInt(@idpaymethod,1) 
	select @paymethod,[dbo].GetStringFormatted(@paymethod,50)
	select @abi,[dbo].GetStringFormatted(@abi,10)
	select @cab,[dbo].GetStringFormatted(@cab,10)
	select @cc,[dbo].GetStringFormatted(@cc,20) 
	select @cin,[dbo].GetStringFormatted(@cin,5)
	select @delegate,[dbo].GetStringFormatted(@delegate,10)
	select @currency,[dbo].GetStringFormatted(@currency,3) 
	select @idexpirationkind,[dbo].GetInt(@idexpirationkind,1) 
	select @ggscadenza,[dbo].GetInt(@ggscadenza,2) 
	select @iban,[dbo].GetStringFormatted(@iban,50)
	*/

	INSERT INTO #trace SELECT @string

	FETCH NEXT FROM @cursore INTO 
	  @idreg, @idregistryclass, @residence, @title, @surname, @forename, @gender, @p_iva, @cf, @foreigncf, @b_date, @location
	, @codice_catastale, @matricola, @note, @esente_equitalia
	, @ammetti_cf_duplicato, @attiva
	, @start_def, @address_def, @cap_def, @officename_def
	, @codice_catastale_def, @location_def
	, @start_domfis, @address_domfis, @cap_domfis, @officename_domfis
	, @codice_catastale_domfis, @location_domfis
	, @idpaymethod, @paymethod, @abi, @cab
	, @cc, @cin, @delegate, @currency
	, @idexpirationkind
	, @ggscadenza
	, @iban
END --WHILE

CLOSE @cursore
DEALLOCATE @cursore

SELECT out_str FROM #trace

DROP TABLE #result
DROP TABLE #trace
END



