-- exec rpt_statopatrimoniale_dm2012 2012, {ts '2012-01-01 00:00:00'}, {ts '2012-12-31 00:00:00'},'0001','S'
CREATE  PROCEDURE rpt_statopatrimoniale_dm2012
(
	@ayear int,
	@start datetime,
	@stop datetime,
	@idupb		varchar(36),
	@showchildupb	char(1)	
)
AS BEGIN
DECLARE @idupboriginal varchar(36)
SET @idupboriginal= @idupb
IF (@showchildupb = 'S') 
BEGIN
	SET @idupb=@idupb+'%' 
END
	
-- Stato Patrimoniale Anno Precedente
DECLARE @firstdayPY datetime
DECLARE @lastdayPY datetime
SET @firstdayPY = CONVERT(datetime,'01-01-' + CONVERT(varchar(4),@ayear-1),105)
SET @lastdayPY = CONVERT(datetime,'31-12-' + CONVERT(varchar(4),@ayear-1),105)
DECLARE @sk_prec char(2)
SET @sk_prec = SUBSTRING(CONVERT(varchar(4),@ayear-1),3,2)

DECLARE @PY_A_AI_aI1 decimal(19,2)
SET @PY_A_AI_aI1 = 
ISNULL(
	(SELECT -SUM(amount)
	FROM entrydetail
	JOIN entry
	ON entry.yentry = entrydetail.yentry
	AND entry.nentry = entrydetail.nentry
	JOIN account
	ON account.idacc = entrydetail.idacc
	JOIN patrimony
	ON patrimony.idpatrimony = account.idpatrimony
	WHERE entry.adate BETWEEN @firstdayPY AND @lastdayPY
	AND  (entrydetail.idupb like @idupb  OR @idupb is null)
	AND entry.identrykind <> 6 -- DEVO ESCLUDERE LE SCRITTURE DI EPILOGO
	AND ((account.flag&4)= 0)	-- ESCLUDO I CONTI D'ORDINE 
	AND patrimony.idpatrimony = @sk_prec + 'A000400010001')
,0)
DECLARE @PY_A_AI_aI2 decimal(19,2)
SET @PY_A_AI_aI2 = 
ISNULL(
	(SELECT -SUM(amount)
	FROM entrydetail
	JOIN entry
	ON entry.yentry = entrydetail.yentry
	AND entry.nentry = entrydetail.nentry
	JOIN account
	ON account.idacc = entrydetail.idacc
	JOIN patrimony
	ON patrimony.idpatrimony = account.idpatrimony
	WHERE entry.adate BETWEEN @firstdayPY AND @lastdayPY
	AND  (entrydetail.idupb like @idupb  OR @idupb is null)
	AND entry.identrykind <> 6 -- DEVO ESCLUDERE LE SCRITTURE DI EPILOGO
	AND ((account.flag&4)= 0)	-- ESCLUDO I CONTI D'ORDINE 
	AND patrimony.idpatrimony = @sk_prec + 'A000400010002')
,0)
DECLARE @PY_A_AI_aI3 decimal(19,2)
SET @PY_A_AI_aI3 = 
ISNULL(
	(SELECT -SUM(amount)
	FROM entrydetail
	JOIN entry
	ON entry.yentry = entrydetail.yentry
	AND entry.nentry = entrydetail.nentry
	JOIN account
	ON account.idacc = entrydetail.idacc
	JOIN patrimony
	ON patrimony.idpatrimony = account.idpatrimony
	WHERE entry.adate BETWEEN @firstdayPY AND @lastdayPY
	AND  (entrydetail.idupb like @idupb  OR @idupb is null)
	AND entry.identrykind <> 6 -- DEVO ESCLUDERE LE SCRITTURE DI EPILOGO
	AND ((account.flag&4)= 0)	-- ESCLUDO I CONTI D'ORDINE 
	AND patrimony.idpatrimony = @sk_prec + 'A000400010003')
,0)
DECLARE @PY_A_AI_aI4 decimal(19,2)
SET @PY_A_AI_aI4 = 
ISNULL(
	(SELECT -SUM(amount)
	FROM entrydetail
	JOIN entry
	ON entry.yentry = entrydetail.yentry
	AND entry.nentry = entrydetail.nentry
	JOIN account
	ON account.idacc = entrydetail.idacc
	JOIN patrimony
	ON patrimony.idpatrimony = account.idpatrimony
	WHERE entry.adate BETWEEN @firstdayPY AND @lastdayPY
	AND  (entrydetail.idupb like @idupb  OR @idupb is null)
	AND entry.identrykind <> 6 -- DEVO ESCLUDERE LE SCRITTURE DI EPILOGO
	AND ((account.flag&4)= 0)	-- ESCLUDO I CONTI D'ORDINE 
	AND patrimony.idpatrimony = @sk_prec + 'A000400010004')
,0)
DECLARE @PY_A_AI_aI5 decimal(19,2)
SET @PY_A_AI_aI5 = 
ISNULL(
	(SELECT -SUM(amount)
	FROM entrydetail
	JOIN entry
	ON entry.yentry = entrydetail.yentry
	AND entry.nentry = entrydetail.nentry
	JOIN account
	ON account.idacc = entrydetail.idacc
	JOIN patrimony
	ON patrimony.idpatrimony = account.idpatrimony
	WHERE entry.adate BETWEEN @firstdayPY AND @lastdayPY
	AND  (entrydetail.idupb like @idupb  OR @idupb is null)
	AND entry.identrykind <> 6 -- DEVO ESCLUDERE LE SCRITTURE DI EPILOGO
	AND ((account.flag&4)= 0)	-- ESCLUDO I CONTI D'ORDINE 
	AND patrimony.idpatrimony = @sk_prec + 'A000400010005')
,0)
DECLARE @PY_A_AI decimal(19,2)
SET @PY_A_AI = @PY_A_AI_aI1 + @PY_A_AI_aI2 + @PY_A_AI_aI3 + @PY_A_AI_aI4 + @PY_A_AI_aI5

DECLARE @PY_A_AII_aII1 decimal(19,2)
SET @PY_A_AII_aII1 = 
ISNULL(
	(SELECT -SUM(amount)
	FROM entrydetail
	JOIN entry
	ON entry.yentry = entrydetail.yentry
	AND entry.nentry = entrydetail.nentry
	JOIN account
	ON account.idacc = entrydetail.idacc
	JOIN patrimony
	ON patrimony.idpatrimony = account.idpatrimony
	WHERE entry.adate BETWEEN @firstdayPY AND @lastdayPY
	AND  (entrydetail.idupb like @idupb  OR @idupb is null)
	AND entry.identrykind <> 6 -- DEVO ESCLUDERE LE SCRITTURE DI EPILOGO
	AND ((account.flag&4)= 0)	-- ESCLUDO I CONTI D'ORDINE 
	AND patrimony.idpatrimony = @sk_prec + 'A000400020001')
,0)
DECLARE @PY_A_AII_aII2 decimal(19,2)
SET @PY_A_AII_aII2 = 
ISNULL(
	(SELECT -SUM(amount)
	FROM entrydetail
	JOIN entry
	ON entry.yentry = entrydetail.yentry
	AND entry.nentry = entrydetail.nentry
	JOIN account
	ON account.idacc = entrydetail.idacc
	JOIN patrimony
