	WHERE entry.adate BETWEEN @firstdayPY AND @lastdayPY
	AND  (entrydetail.idupb like @idupb  OR @idupb is null)
	AND entry.identrykind <> 6 -- DEVO ESCLUDERE LE SCRITTURE DI EPILOGO
