	AND entry.identrykind <> 6 -- DEVO ESCLUDERE LE SCRITTURE DI EPILOGO
	AND ((account.flag&4)= 0)	-- ESCLUDO I CONTI D'ORDINE 
	AND patrimony.idpatrimony = @sk + 'P00090006')
,0)
