	@ayear int, 
	@startmonth int, 
	@stopmonth int
) 
AS BEGIN
CREATE TABLE #enterprise
(
	annodenuncia int,
	mesedenuncia int,
	cfazienda varchar(16) NOT NULL,
	ragsocazienda varchar(50) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL
