if object_id('[rpt_statopatrimoniale_cdo]') is not null
	drop PROCEDURE [rpt_statopatrimoniale_cdo]
go

CREATE  PROCEDURE [rpt_statopatrimoniale_cdo]
(
	@ayear int,
	@start datetime,
	@stop datetime,
	@idupb		varchar(36),
	@showchildupb	char(1)	
)
AS BEGIN
-- exec rpt_statopatrimoniale_cdo 2013, {ts '2013-01-01 00:00:00'}, {ts '2013-12-31 00:00:00'}, '0001','S'
-- Stato Patrimoniale Anno Precedente
DECLARE @firstdayPY datetime
DECLARE @lastdayPY datetime
SET @firstdayPY = CONVERT(datetime,'01-01-' + CONVERT(varchar(4),@ayear-1),105)
SET @lastdayPY = CONVERT(datetime,'31-12-' + CONVERT(varchar(4),@ayear-1),105)

DECLARE @sk_prec char(2)
SET @sk_prec = SUBSTRING(CONVERT(varchar(4),@ayear-1),3,2)

-- Stato Patrimoniale Anno Corrente
DECLARE @sk char(2)
SET @sk = SUBSTRING(CONVERT(varchar(4),@ayear),3,2)
DECLARE @idupboriginal varchar(36)
SET @idupboriginal= @idupb
IF (@showchildupb = 'S') 
BEGIN
	SET @idupb=@idupb+'%' 
END
DECLARE @codeupb	varchar(50)
DECLARE @title		varchar(150)
 
SELECT	@codeupb = codeupb,
		@title = title
FROM	upb 
WHERE	idupb = @idupboriginal
CREATE TABLE #conti_d_ordine
	(
		idacc 		varchar(38), 
		code	varchar(50), 
		title		varchar(150), 
		printingordacc varchar(50), 
		py_totaledare decimal(19,2),
		py_totaleavere decimal(19,2),
		p_totaledare decimal(19,2),
		p_totaleavere decimal(19,2)
	)
		
INSERT INTO #conti_d_ordine
(
		idacc, 
		code, 
		title, 
		printingordacc
)
SELECT
	idacc,
	codeacc,
	title,
	printingorder
FROM 
	account
WHERE ((account.flag&4)<> 0)
AND account.ayear = @ayear 
UPDATE #conti_d_ordine
SET   p_totaledare = -isnull((SELECT SUM(amount) 
			     FROM entrydetail  
			     JOIN entry on
			     entry.nentry = entrydetail.nentry and
			     entry.yentry = entrydetail.yentry 
			     WHERE  amount < 0 AND
				(entrydetail.idupb like @idupb  OR @idupb is null) AND
			     entrydetail.idacc = #conti_d_ordine.idacc and
		         entry.adate between @start and @stop
			     ),0)

UPDATE #conti_d_ordine
SET   p_totaleavere =  isnull((SELECT SUM(amount) 
			     FROM entrydetail  
			     JOIN entry on
			     entry.nentry = entrydetail.nentry and
			     entry.yentry = entrydetail.yentry 
			     WHERE  amount > 0 
			     AND entrydetail.idacc = #conti_d_ordine.idacc 
			     AND  (entrydetail.idupb like @idupb  OR @idupb is null)
			     AND entry.identrykind <> 6 -- DEVO ESCLUDERE LE SCRITTURE DI EPILOGO
		         AND entry.adate between @start and @stop
			     ),0)
			     
UPDATE #conti_d_ordine
SET   py_totaledare = -isnull((SELECT SUM(amount) 
			     FROM entrydetail  
			     JOIN entry on
			     entry.nentry = entrydetail.nentry and
			     entry.yentry = entrydetail.yentry 
			     WHERE  amount < 0 
			     AND entrydetail.idacc =  @sk_prec + SUBSTRING(#conti_d_ordine.idacc, 3,LEN(#conti_d_ordine.idacc) -2) 
			     AND  (entrydetail.idupb like @idupb  OR @idupb is null)
			     AND entry.identrykind <> 6 -- DEVO ESCLUDERE LE SCRITTURE DI EPILOGO
		         AND entry.adate between @firstdayPY and @lastdayPY
			     ),0)

UPDATE #conti_d_ordine
SET   py_totaleavere = isnull((SELECT SUM(amount) 
			     FROM entrydetail  
			     JOIN entry on
			     entry.nentry = entrydetail.nentry and
			     entry.yentry = entrydetail.yentry 
			     WHERE  amount > 0 
			     AND entrydetail.idacc =  @sk_prec + SUBSTRING(#conti_d_ordine.idacc, 3,LEN(#conti_d_ordine.idacc) -2) 
			     AND  (entrydetail.idupb like @idupb  OR @idupb is null)
			     AND entry.identrykind <> 6 -- DEVO ESCLUDERE LE SCRITTURE DI EPILOGO
				 AND entry.adate between  @firstdayPY and @lastdayPY
			     ),0)
			     
			     
 

SELECT * FROM

#conti_d_ordine

END


GO

print '[rpt_statopatrimoniale_cdo] OK'

GO
if object_id('[rpt_4certificazioni_dett]') is not null
	drop PROCEDURE [rpt_4certificazioni_dett]
go

CREATE     PROCEDURE [rpt_4certificazioni_dett]
(
	@ayear smallint, 
	@start datetime,
	@stop datetime,
	@idreg int, 
	@certificatekind char(1)--@idser int,
	
)
AS BEGIN
-- exec rpt_4certificazioni_dett 2010,{ts '2010-01-20 00:00:00'},{ts '2010-12-31 00:00:00'},21,'F'
CREATE TABLE #expensetax
(
	idexp varchar(40),
	idreg int,
	registry varchar(100),
	--taxcode int,
	taxdescription varchar(50),
	expensedescription varchar(150),	
	commondetail char(1),
	taxablenet decimal(19,2),
	employtax decimal(19,2),
	grossamount decimal (19,2),
	taxablegross decimal (19,2),
	service varchar(50),
	--idser int,
	npay int,
	countidser int,
	taxkind int
)
IF @ayear = 0
BEGIN
	SET @ayear='1900'
END
INSERT INTO #expensetax
(
	idexp,
	idreg,
	registry,
	--taxcode,
	taxdescription,
	expensedescription,
	taxablenet,
	employtax, 
	taxablegross,
	grossamount,
	service,
	--idser,
	npay,
	taxkind
)
SELECT
	T.idexp,
	T.idreg,
	registry.title,
	--T.taxcode,
	T.taxdescription,
	T.expensedescription,
	SUM(T.taxablenet),
	SUM(T.employtax),
	T.taxablegross,
	expensetotal.curramount,
	service.description,
	--service.idser,
	payment.npay,
	T.taxkind
FROM
	(SELECT
		SUM(ISNULL(E.taxablenet,0)) AS taxablenet,
		SUM(ISNULL(E.employtax,0)) AS employtax,
		isnull(E.taxablegross,0) as taxablegross,
		E.idexp,
		--E.taxcode,
		expense.idreg,
		case 
			when E.taxkind in (1,2,3) then E.description
			Else 'Altre Ritenute'
		end as taxdescription,
		expense.description as expensedescription,
		expense.idman,
		expenselast.idser,
		expenselast.kpay,
		case 
			when E.taxkind in (1,2,3) then E.taxkind
			Else 99
		end as taxkind
	FROM expensetaxofficialview AS E
	JOIN expense 
		ON expense.idexp = E.idexp
	JOIN expenselast
		ON expense.idexp = expenselast.idexp
	JOIN service
		ON service.idser = expenselast.idser
	WHERE expense.ymov = @ayear  
		AND expense.idreg=@idreg 
		--AND expenselast.idser = @idser   
		AND service.certificatekind = @certificatekind
		AND E.stop IS NULL
	GROUP BY expense.idreg,E.idexp,--E.taxcode,
		E.description,expense.description,
		expense.idman, expenselast.idser,
		expense.ymov,expenselast.kpay,e.taxablegross,E.taxkind	) AS T
JOIN registry 
	ON T.idreg = registry.idreg  
JOIN expensetotal
	ON T.idexp = expensetotal.idexp  
JOIN expenseyear
	ON T.idexp = expenseyear.idexp
JOIN service
	ON T.idser = service.idser  
JOIN payment 
	ON T.kpay = payment.kpay  
JOIN paymenttransmission
	ON payment.kpaymenttransmission = paymenttransmission.kpaymenttransmission  
WHERE (paymenttransmission.transmissiondate BETWEEN @start AND @stop)
	--AND service.idser = @idser
	AND service.certificatekind = @certificatekind
	AND expensetotal.ayear = @ayear
	AND expenseyear.ayear = @ayear
GROUP BY T.idreg, T.idexp, registry.title, registry.birthdate, registry.cf,
	--T.taxcode, 
	T.taxdescription, expensetotal.curramount, service.description,
	service.idser,
	payment.npay,
	T.taxablegross,T.expensedescription,T.taxkind		
	
/*
Nel report non è + usato
update #expensetax set countidser = (select count(distinct i.idexp)
					from #expensetax i
					where i.idreg = #expensetax.idreg
					)	
*/ 
SELECT countidser,
	#expensetax.idreg,
	#expensetax.registry,
	-- #expensetax.taxcode,   
	#expensetax.taxdescription,
	sum(isnull(#expensetax.taxablenet,0)) AS taxablenet,
	sum(isnull(#expensetax.taxablegross,0)) AS taxablegross ,
	sum(isnull(#expensetax.employtax,0)) as employtax,
	taxkind
FROM #expensetax
--WHERE employtax <>0
group by #expensetax.idreg,#expensetax.registry,
	--#expensetax.taxcode,
	#expensetax.taxdescription,countidser,taxkind
ORDER BY #expensetax.registry,taxkind
END



GO

print '[rpt_4certificazioni_dett] OK'

