go

CREATE    PROCEDURE closeyear_check_commontable
(
	@ayear int
)
AS
BEGIN
CREATE TABLE #errors (errordescr varchar(255))
IF ((SELECT COUNT(*) FROM dbdepartment) > 1 AND (UPPER(USER) <> 'AMMINISTRAZIONE'))
BEGIN
	INSERT INTO #errors VALUES('L''utente non ha i diritti per effettuare questa fase della chiusura')
END
DECLARE @nextayear int
SET @nextayear = @ayear + 1
	
DECLARE @nextayearstr varchar(4)
SET @nextayearstr = CONVERT(varchar(4), @nextayear)

IF EXISTS (SELECT * FROM patrimonylevel WHERE ayear = @nextayear)
BEGIN
	INSERT INTO #errors VALUES('Livelli dello stato patrimoniale annuale per esercizio ' + @nextayearstr + ' esistenti.')
END
IF EXISTS (SELECT * FROM placcountlevel WHERE ayear = @nextayear)
BEGIN
	INSERT INTO #errors VALUES('Livelli del conto economico annuale per esercizio ' + @nextayearstr + ' esistenti.')
END
IF EXISTS (SELECT * FROM accountlevel WHERE ayear = @nextayear)
BEGIN
	INSERT INTO #errors VALUES('Livelli del piano dei conti annuale per esercizio ' + @nextayearstr + ' esistenti.')
END
IF EXISTS (SELECT * FROM finlevel WHERE ayear = @nextayear )
BEGIN
	INSERT INTO #errors VALUES('Livelli del bilancio annuale per esercizio ' + @nextayearstr + ' esistenti.')
END
IF EXISTS (SELECT * FROM patrimony WHERE ayear = @nextayear)
BEGIN
	INSERT INTO #errors VALUES('Voci dello stato patrimoniale annuale per esercizio ' + @nextayearstr + ' esistenti.')
END
IF EXISTS (SELECT * FROM placcount WHERE ayear = @nextayear)
BEGIN
	INSERT INTO #errors VALUES('Voci dello conto economico annuale per esercizio ' + @nextayearstr + ' esistenti.')
END
IF EXISTS (SELECT * FROM account WHERE ayear = @nextayear)
BEGIN
	INSERT INTO #errors VALUES('Voci del piano dei conti annuale per esercizio ' + @nextayearstr + ' esistenti.')
END
IF EXISTS (SELECT * FROM fin WHERE ayear = @nextayear )
BEGIN
	INSERT INTO #errors VALUES('Voci del bilancio annuale per esercizio ' + @nextayearstr + ' esistenti.')
END
IF EXISTS (SELECT * FROM accountsorting WHERE idacc LIKE SUBSTRING(@nextayearstr, 3, 2) + '%')
BEGIN
	INSERT INTO #errors VALUES('Classificazioni piano dei conti per esercizio ' + @nextayearstr + ' esistenti.')
END
IF EXISTS (SELECT * FROM accmotivedetail WHERE idacc LIKE SUBSTRING(@nextayearstr, 3, 2) + '%')
BEGIN
	INSERT INTO #errors VALUES('Config. causali EP - conti da movimentare per esercizio ' + @nextayearstr + ' esistenti.')
END
IF EXISTS (SELECT * FROM csa_contractkindrules where ayear= @nextayear)
BEGIN
	INSERT INTO #errors VALUES('Regole di individuazione dei tipi di contratti CSA ' + @nextayearstr + ' esistenti.')
END
SELECT * FROM #errors
END


GO

print 'closeyear_check_commontable OK'

GO
if object_id('compute_serviceregistry') is not null
	drop PROCEDURE compute_serviceregistry
go

CREATE         PROCEDURE compute_serviceregistry(
	@ayear	smallint ,
	@semestre int,
	@tipo char(1)
)
AS BEGIN
-- exec compute_serviceregistry 2011, 2,'C'
CREATE TABLE #MYserviceregistry(
	iddbdepartment varchar(50),
	annotation	varchar(400),
	authorizationdate	datetime,
	birthdate	datetime,
	cf	varchar(16),
	codcity	varchar(20),
	description	varchar(200),
	employkind	char(1),
	expectedamount	decimal(19,2),
	flagforeign	char(1),
	forename	varchar(60),
	gender	char(1),
	id_service	varchar(50),
	idacquirekind	varchar(20),
	idapactivitykind	varchar(20),
	idapcontractkind	varchar(20),
	idapmanager	varchar(20),
	idapregistrykind	varchar(20),
	idcity	int,
	idconsultingkind	varchar(20),
	iddepartment	int,
	idfinancialactivity	varchar(20),
	idreg	int,
	idrelated	varchar(50),
	is_annulled	char(1),
	is_blocked	char(1),
	is_changed	char(1),
	is_delivered	char(1),
	nservreg	int,
	officeduty	char(1),
	p_iva	varchar(15),
	pa_cf	varchar(16),
	pa_code	varchar(50),
	pa_title	varchar(80),
	payment	char(1),
	referencerule	varchar(500),
	referencesemester	int,
	regulation	char(1),
	servicevariation	varchar(200),
	start	datetime,
	stop	datetime,
	surname	varchar(60),
	title	varchar(150),
	ypay	int,
	yservreg int,
	paragraph	varchar(50),
	article	varchar(50),
	articlenumber	varchar(50),
	referencedate	datetime,
	idreferencerule	varchar(20),
	idapfinancialactivity	int,
	rulespecifics	char(1),
	expectationsdate	datetime,
	senderreporting	varchar	(20)
)
DECLARE @iddbdepartment varchar(50)
DECLARE @dip_nome varchar(300)
DECLARE @description varchar(150)
DECLARE @name varchar(150)
declare @query nvarchar(4000)
DECLARE crsdepartment INSENSITIVE CURSOR FOR
	SELECT iddbdepartment FROM dbdepartment
	WHERE (start is null or start <= @ayear ) AND ( stop is null or stop >= @ayear)
	OPEN crsdepartment 
FETCH NEXT FROM crsdepartment INTO @iddbdepartment
        WHILE @@fetch_status=0 begin
        	SET @dip_nome = @iddbdepartment + '.serviceregistry'
			
                SET  @query = ' 
							INSERT INTO #MYserviceregistry(iddbdepartment,
							annotation, authorizationdate, birthdate, cf, codcity, description, employkind,expectedamount,
							flagforeign, forename, gender, id_service, idacquirekind, idapactivitykind, idapcontractkind, idapmanager,
							idapregistrykind,  idcity, idconsultingkind, iddepartment, idfinancialactivity, idreg,idrelated,
							is_annulled, is_blocked, is_changed, is_delivered,  nservreg, officeduty, p_iva, pa_cf,	pa_code,
							pa_title, payment, 	referencerule, referencesemester,   regulation, servicevariation, start, stop,
							surname, title, ypay, yservreg,
							paragraph,article,articlenumber,referencedate,idreferencerule,idapfinancialactivity,rulespecifics,expectationsdate,senderreporting
							)'
							+
							'select ' +''''+ @iddbdepartment+'''' +'as iddbdepartment,
							annotation, authorizationdate, birthdate, cf, codcity,  description, employkind,expectedamount,
							flagforeign, forename, gender, id_service, idacquirekind, idapactivitykind, idapcontractkind, idapmanager,
							idapregistrykind,  idcity, idconsultingkind, iddepartment, idfinancialactivity, idreg,idrelated,
							is_annulled, is_blocked, is_changed, is_delivered,  nservreg, officeduty, p_iva, pa_cf,	pa_code,
							pa_title, payment, 	referencerule, referencesemester,   regulation, servicevariation, start, stop,
							surname, title, ypay, yservreg,
							paragraph,article,articlenumber,referencedate,idreferencerule,idapfinancialactivity,rulespecifics,expectationsdate,senderreporting
							from '       
                                + @dip_nome
                                + ' where yservreg =  '+ convert(varchar(4), @ayear)
               EXEC sp_executesql @query
PRINT @query
	FETCH NEXT FROM crsdepartment INTO @iddbdepartment
end
deallocate crsdepartment
-- Per i dipendenti filtri solo quelli che non appartengono ad altra amministrazione
-- ovvero non hanno un indirizzo del tipo anagrafe delle prestazioni
DECLARE @codeaddress varchar(20)
SET @codeaddress = '07_SW_ANP'
DECLARE @idaddress int
SELECT @idaddress = idaddress from address WHERE @codeaddress = '07_SW_ANP'
if (@tipo='d')
Begin
	DELETE FROM #MYserviceregistry WHERE idreg not in (select idreg from address where idaddress = @idaddress)
End

SELECT 
	iddbdepartment,
	annotation, authorizationdate, birthdate, cf, codcity,  description, employkind,expectedamount,
	flagforeign, forename, gender, id_service, idacquirekind, idapactivitykind, idapcontractkind, idapmanager,
	idapregistrykind,  idcity, idconsultingkind, iddepartment, idfinancialactivity, idreg,idrelated,
	is_annulled, is_blocked, is_changed, is_delivered,  nservreg, officeduty, p_iva, pa_cf,	pa_code,
	pa_title, payment, 	referencerule, referencesemester,   regulation, servicevariation, start, stop,
	surname, title, ypay, yservreg,
	paragraph,article,articlenumber,referencedate,idreferencerule,idapfinancialactivity,
	rulespecifics,expectationsdate,senderreporting  
FROM #MYserviceregistry
WHERE employkind = @tipo
	AND ( referencesemester = @semestre OR @semestre IS NULL) 
-- DROP TABLE #MYserviceregistry

END



GO

print 'compute_serviceregistry OK'

GO
if object_id('[esporta_cespiti_note]') is not null
	drop PROCEDURE [esporta_cespiti_note]
go

CREATE                  PROCEDURE [esporta_cespiti_note]
@idinventory	int,
@fromninv		int,
@toninv			int
AS BEGIN
SELECT 
	asset.idasset AS 'Idasset',
	lifestart AS 'Data Creazione', 
	asset.cu AS 'Creato da' , 
	inventory.description as 'Inventario',
	ninventory AS 'Num. inventario',
	asset.nassetacquire AS 'Carico Bene', 
	assetloadkind.codeassetloadkind as 'Tipo Buono Carico',
	assetload.yassetload as 'Eserc. Buono Carico',
	assetload.nassetload as 'Num. Buono Carico',
	assetunloadkind.codeassetunloadkind as 'Tipo Buono Scarico',
	assetunload.yassetunload as 'Eserc. Buono Scarico',
	assetunload.nassetunload as 'Num. Buono Scarico',
	asset.txt as 'Annotazioni'
FROM asset  
join assetacquire on assetacquire.nassetacquire = asset.nassetacquire
join inventory on assetacquire.idinventory = inventory.idinventory
left outer join manager R ON R.idman = (select top 1 idman from assetmanager where idasset=asset.idasset and start is null)
LEFT OUTER JOIN location U ON U.idlocation = (select top 1 idlocation from assetlocation where idasset = asset.idasset and start is null)
left outer join assetload on assetload.idassetload = assetacquire.idassetload
left outer join assetloadkind on assetloadkind.idassetloadkind = assetload.idassetloadkind
left outer join assetunload on assetunload.idassetunload = asset.idassetunload
left outer join assetunloadkind on assetunloadkind.idassetunloadkind = assetunload.idassetunloadkind
WHERE idpiece = 1 
AND (assetacquire.idinventory = @idinventory or @idinventory is null)
AND (asset.ninventory >= @fromninv OR @fromninv is null)
AND (asset.ninventory <= @toninv OR @toninv is null)
ORDER BY idasset
END


GO

print '[esporta_cespiti_note] OK'

