CREATE                      PROCEDURE clear_table_info
(
	@stringa varchar(1000)
)
AS BEGIN
	DECLARE @stringaSQL nvarchar(1500)
	SET @stringa = '''' + @stringa + ''''
	SET @stringa = REPLACE(@stringa,' ','')
	SET @stringa = REPLACE(@stringa,',',''',''')
	SET @stringaSQL = 'DELETE FROM columntypes WHERE tablename IN (' + @stringa + ')'
	EXEC sp_executesql  @stringaSQL
	SET @stringaSQL = 'DELETE FROM customobject WHERE objectname IN ('+ @stringa + ')'
	EXEC sp_executesql @stringaSQL
END


