CREATE                     TRIGGER [trigger_i_epexpvar] ON [epexpvar] FOR INSERT
AS BEGIN
	DECLARE @yepexp smallint
	DECLARE	@nepexp int
	DECLARE	@amount decimal(19, 2)
	SELECT	@yepexp=yepexp,
                @nepexp=nepexp,
                @amount=amount
	FROM inserted
	UPDATE epexptotal
	SET curramount = ISNULL(curramount, 0) + ISNULL(@amount,0)
        WHERE yepexp=@yepexp AND nepexp=@nepexp
END



