if object_id('[send_cdosysmail]') is not null
	drop PROCEDURE [send_cdosysmail]
go

CREATE                                                     PROCEDURE [send_cdosysmail] 
   @smtp varchar(150),
   @From varchar(150) ,
   @To varchar(150) ,
   @Subject varchar(150)=" ",
   @Body varchar(8000) =" "
/*********************************************************************
http://support.microsoft.com/default.aspx?scid=kb;en-us;312839&sd=tech
This stored procedure takes the parameters and sends an e-mail. 
All the mail configurations are hard-coded in the stored procedure. 
Comments are added to the stored procedure where necessary.
References to the CDOSYS objects are at the following MSDN Web site:
http://msdn.microsoft.com/library/default.asp?url=/library/en-us/cdosys/html/_cdosys_messaging.asp
***********************************************************************/ 
   AS
   Declare @iMsg int
   Declare @hr int
   Declare @errorcode int
   Declare @source varchar(255)
   Declare @description varchar(500)
   Declare @helpfile varchar(150)
   Declare @helpid int
--************* Create the CDO.Message Object ************************
   EXEC @hr = sp_OACreate 'CDO.Message', @iMsg OUT
--***************Configuring the Message Object ******************
-- This is to configure a remote SMTP server.
-- http://msdn.microsoft.com/library/default.asp?url=/library/en-us/cdosys/html/_cdosys_schema_configuration_sendusing.asp
   EXEC @hr = sp_OASetProperty @iMsg, 'Configuration.fields("http://schemas.microsoft.com/cdo/configuration/sendusing").Value','2'
-- This is to configure the Server Name or IP address. 
-- Replace MailServerName by the name or IP of your SMTP Server.
   EXEC @hr = sp_OASetProperty @iMsg, 'Configuration.fields("http://schemas.microsoft.com/cdo/configuration/smtpserver").Value', @smtp 
-- Save the configurations to the message object.
   EXEC @hr = sp_OAMethod @iMsg, 'Configuration.Fields.Update', null
-- Set the e-mail parameters.
-- http://msdn.microsoft.com/library/default.asp?url=/library/en-us/cdosys/html/_cdosys_imessage_subject.asp
   EXEC @hr = sp_OASetProperty @iMsg, 'To', @To
   EXEC @hr = sp_OASetProperty @iMsg, 'From', @From
   EXEC @hr = sp_OASetProperty @iMsg, 'Subject', @Subject
-- If you are using HTML e-mail, use 'HTMLBody' instead of 'TextBody'.
   EXEC @hr = sp_OASetProperty @iMsg, 'TextBody', @Body
   EXEC @hr = sp_OAMethod @iMsg, 'Send', NULL
-- Sample error handling.
   IF @hr <> 0 
     BEGIN
       set @errorcode=@hr
       EXEC @hr = sp_OAGetErrorInfo NULL, @source OUT, @description OUT, @helpfile OUT, @helpid OUT
       SELECT errorcode=@errorcode, source=@source, description=@description, helpfile=@helpfile, helpid=@helpid
       IF @hr <> 0
         BEGIN
           RETURN
         END
     END
-- Do some error handling after each step if you have to.
-- Clean up the objects created.
   EXEC @hr = sp_OADestroy @iMsg
   

GO

print '[send_cdosysmail] OK'

GO
if object_id('exp_interscambio_csa_dipendentiassimilato_single') is not null
	drop PROCEDURE exp_interscambio_csa_dipendentiassimilato_single
go

CREATE   PROCEDURE exp_interscambio_csa_dipendentiassimilato_single
 (
	@datagenerazione datetime,
	@ayear int,
	@ateneo varchar(5),
	@tipoCompenso char(1),-- Assume valori T = Conto Terzi, C = CO.CO.CO. , B = Borse di studio
	@start datetime,
	@stop datetime
)
AS 
-- exec exp_interscambio_csa_dipendentiassimilato_single {ts '2010-12-31 01:02:03'} ,2010, '70012'
BEGIN
-- ATTENZIONE: Questa sp è chiamata anche da 'exp_interscambio_csa_dipendentiassimilato_dati'. Quest'ultima mostra i dati che stiamo comunicando attraverso il file.
DECLARE @annoredditi int
SET @annoredditi = @ayear
CREATE TABLE #pagamenti(
		idexp int,
		idregistrylegalstatus int,
		voce8000 varchar(4),
		importo decimal(19,2),
		idreg int
		)
---------------------------------------------------------------------------------------- CONTO TERZI ---------------------------------------------------------------------
if (@tipoCompenso ='T')
Begin
		-- 8177 - Imp.Ass.ac-no ded-lett.E (intram.,dpr382/80)
		INSERT INTO #pagamenti(
				idexp,
				idregistrylegalstatus,
				voce8000,
				importo,
				idreg
				)
		SELECT 
				EL.idexp,
				W.idregistrylegalstatus,
				'8177',
				MAX(ETO.taxablegross),
				W.idreg
		FROM wageaddition W
		JOIN wageadditionyear WY
			ON W.ycon = WY.ycon AND W.ncon = WY.ncon 
		JOIN expensewageaddition EW
			ON EW.ncon = W.ncon	AND EW.ycon = W.ycon 
		join expenselink ELK
			ON ELK.idparent = EW.idexp
		join expenselast EL
			on EL.idexp = ELK.idchild
		JOIN expensetaxofficial ETO
			ON ETO.idexp = EL.idexp
		JOIN tax T
			ON ETO.taxcode = T.taxcode
		JOIN voce8000lookup V
			ON V.taxref = T.taxref
		join payment P
			on P.kpay = EL.kpay
		JOIN service S
			ON S.idser = W.idser
		WHERE  P.ypay = @ayear
			AND T.taxkind = 2	-- > Serve l'imponibile Assistenziale = IRAP
			AND S.voce8000='8177'
			AND V.servicekind = 'DIPENDENTE'
			AND P.kpaymenttransmission IS NOT NULL
			AND P.adate between @start and @stop
			AND ETO.stop is null
			AND W.idregistrylegalstatus IS NOT NULL
		GROUP BY W.idreg, W.idregistrylegalstatus, EL.idexp
		-- Inserisce le ritenute c/Amm
		INSERT INTO #pagamenti(
				idexp,
				idregistrylegalstatus,
				voce8000,
				importo,
				idreg
				)
		SELECT 	
				EL.idexp,
				W.idregistrylegalstatus,
				V.voce,
				SUM(ETO.admintax),
				W.idreg
		FROM wageaddition W
		JOIN wageadditionyear WY
			ON W.ycon = WY.ycon AND W.ncon = WY.ncon 
		JOIN expensewageaddition EW
			ON EW.ncon = W.ncon	AND EW.ycon = W.ycon 
		join expenselink ELK
			ON ELK.idparent = EW.idexp
		join expenselast EL
			on EL.idexp = ELK.idchild
		JOIN expensetaxofficial ETO
			ON ETO.idexp = EL.idexp
		JOIN tax T
			ON ETO.taxcode = T.taxcode
		JOIN voce8000lookup V
			ON V.taxref = T.taxref
		join payment P
			on P.kpay = EL.kpay
		JOIN service S
			ON S.idser = W.idser
		WHERE P.ypay = @ayear
			AND V.servicekind = 'DIPENDENTE'
			AND S.voce8000='8177'		-- Prende solo le ritenute di quelle prestazioni mappate con l'imponibile CSA
			AND V.conto  = 'A' 
			AND isnull(ETO.admintax,0) >= 0
			AND P.kpaymenttransmission IS NOT NULL
			AND P.adate between @start and @stop
			AND W.idregistrylegalstatus IS NOT NULL
			AND ETO.stop is null
		GROUP BY EL.idexp, W.idregistrylegalstatus, V.voce,	W.idreg
		-- la Group By la faccio per la presenza di eventuali scaglioni 
		-- Inserisce le ritenute c/Dip
		INSERT INTO #pagamenti(
				idexp,
				idregistrylegalstatus,
				voce8000,
				importo,
				idreg
				)
		SELECT 	
				EL.idexp,
				W.idregistrylegalstatus,
				V.voce,
				SUM(ETO.employtax),
				W.idreg
		FROM wageaddition W
		JOIN wageadditionyear WY
			ON W.ycon = WY.ycon AND W.ncon = WY.ncon 
		JOIN expensewageaddition EW
			ON EW.ncon = W.ncon	AND EW.ycon = W.ycon 
		join expenselink ELK
			ON ELK.idparent = EW.idexp
		join expenselast EL
			on EL.idexp = ELK.idchild
		JOIN expensetaxofficial ETO
			ON ETO.idexp = EL.idexp
		JOIN tax T
			ON ETO.taxcode = T.taxcode
		JOIN voce8000lookup V
			ON V.taxref = T.taxref
		join payment P
			on P.kpay = EL.kpay
		JOIN service S
			ON S.idser = W.idser
		WHERE  P.ypay = @ayear
			AND V.servicekind = 'DIPENDENTE'
			AND V.conto  = 'D' 
			AND S.voce8000='8177'		-- Prende solo le ritenute di quelle prestazioni mappate con l'imponibile CSA
			AND isnull(ETO.employtax,0) >= 0
			AND P.kpaymenttransmission IS NOT NULL
			AND P.adate between @start and @stop
			AND ETO.stop is null
			AND W.idregistrylegalstatus IS NOT NULL
		GROUP BY EL.idexp, W.idregistrylegalstatus, V.voce,	W.idreg
		-- la Group By la faccio per la presenza di eventuali scaglioni 
End
---------------------------------------------------------------------------------------- CO.CO.CO.  ----------------------------------------------------------------------------------------------------
IF (@tipoCompenso='C')
Begin
		-- considera solo le prestazioni di COLLABORAZIONE...
		-- Inserisce l'imponibile IRAP:
		-- 8186 Imp.Ass.ac-si ded-lett.Cbis (collab.,revisori) 
		INSERT INTO #pagamenti(
				idexp,
				idregistrylegalstatus,
				voce8000,
				importo,
				idreg
				)
		SELECT 
				EL.idexp,
				C.idregistrylegalstatus,
				'8186',
				MAX(ETO.taxablegross),
				C.idreg
		FROM expensepayroll EP
		JOIN payroll P
			on P.idpayroll = EP.idpayroll
		JOIN parasubcontract C
			ON C.idcon = P.idcon
		JOIN parasubcontractyear CY
			ON C.idcon = CY.idcon AND CY.ayear = @annoredditi
		JOIN expenselink ELK
			ON ELK.idparent = EP.idexp
		JOIN expenselast EL
			on EL.idexp = ELK.idchild
		JOIN expensetaxofficial ETO
			ON ETO.idexp = EL.idexp
		JOIN tax T
			ON ETO.taxcode = T.taxcode
		JOIN voce8000lookup V
			ON V.taxref = T.taxref
		JOIN payment 
			on payment.kpay = EL.kpay
		JOIN service S
			ON S.idser = C.idser
		WHERE payment.ypay = @ayear---fiscalyear = @annoredditi
			AND T.taxkind = 2	-- > Serve l'imponibile Assistenziale = IRAP
			AND geoappliance IS NULL
			AND V.servicekind = 'ASSIMILATO'
			AND S.voce8000='8186'		-- Prende solo le ritenute di quelle prestazioni mappate con l'imponibile assicutarivo CSA
			AND C.idregistrylegalstatus IS NOT NULL
			AND payment.kpaymenttransmission IS NOT NULL
			AND payment.adate between @start and @stop
			AND ETO.stop is null
		GROUP BY C.idreg, C.idregistrylegalstatus, EL.idexp
		-- 8011 Rit. IRPeF ac - ASSIMILATI
		INSERT INTO #pagamenti(
				idexp,
				idregistrylegalstatus,
				voce8000,
				importo,
				idreg
				)
		SELECT 	
				EL.idexp,
				C.idregistrylegalstatus,
				'8011',
				SUM(ETO.employtax),
				C.idreg
		FROM expensepayroll EP
		JOIN payroll P
			on P.idpayroll = EP.idpayroll
		JOIN parasubcontract C
			ON C.idcon = P.idcon
		JOIN parasubcontractyear CY
			ON C.idcon = CY.idcon AND CY.ayear = @annoredditi
		JOIN expenselink ELK
			ON ELK.idparent = EP.idexp
		JOIN expenselast EL
			on EL.idexp = ELK.idchild
		JOIN expensetaxofficial ETO
			ON ETO.idexp = EL.idexp
		JOIN tax T
			ON ETO.taxcode = T.taxcode
		JOIN voce8000lookup V
			ON V.taxref = T.taxref
		JOIN payment 
			on payment.kpay = EL.kpay
		JOIN service S
			ON S.idser = C.idser
		WHERE payment.ypay = @ayear--fiscalyear = @annoredditi
			AND V.voce = '8011'
			AND V.servicekind = 'ASSIMILATO'
			AND S.voce8000='8186'		-- Prende solo le ritenute di quelle prestazioni mappate con l'imponibile assicutarivo CSA
			AND isnull(ETO.employtax,0) >= 0
			AND taxkind = 1 
			AND geoappliance IS NULL
			AND ETO.stop is null
			AND payment.kpaymenttransmission IS NOT NULL
			AND payment.adate between @start and @stop
			AND C.idregistrylegalstatus IS NOT NULL
		GROUP BY EL.idexp, C.idregistrylegalstatus, V.voce,	C.idreg
		-- la Group By la faccio per la presenza di eventuali scaglioni 
		-- 8185 Rit. Add.Reg.IRPef - ASSIMILATI
		INSERT INTO #pagamenti(
				idexp,
				idregistrylegalstatus,
				voce8000,
				importo,
				idreg
				)
		SELECT 
				EL.idexp,
				C.idregistrylegalstatus,
				'8185',
				SUM(ETO.employtax),
				C.idreg
		FROM expensepayroll EP
		JOIN payroll P
			on P.idpayroll = EP.idpayroll
		JOIN parasubcontract C
			ON C.idcon = P.idcon
		JOIN parasubcontractyear CY
			ON C.idcon = CY.idcon AND CY.ayear = @annoredditi
		JOIN expenselink ELK
			ON ELK.idparent = EP.idexp
		JOIN expenselast EL
			on EL.idexp = ELK.idchild
		JOIN expensetaxofficial ETO
			ON ETO.idexp = EL.idexp
		JOIN tax T
			ON ETO.taxcode = T.taxcode
		JOIN voce8000lookup V
			ON V.taxref = T.taxref
		JOIN payment 
			on payment.kpay = EL.kpay
		JOIN service S
			ON S.idser = C.idser
		WHERE payment.ypay = @ayear--fiscalyear = @annoredditi
			AND  taxkind = 1 
			AND geoappliance = 'R' 
			AND ETO.stop is null
			AND isnull(ETO.employtax,0) >= 0
			AND payment.kpaymenttransmission IS NOT NULL
			AND payment.adate between @start and @stop
			AND V.voce = '8185'
			AND V.servicekind='ASSIMILATO'
			AND S.voce8000='8186'		-- Prende solo le ritenute di quelle prestazioni mappate con l'imponibile assicutarivo CSA
			AND C.idregistrylegalstatus IS NOT NULL
		GROUP BY EL.idexp, C.idregistrylegalstatus, V.voce,	C.idreg
		-- 8221 Rit.Add.Com. 
		INSERT INTO #pagamenti(
				idexp,
				idregistrylegalstatus,
				voce8000,
				importo,
				idreg
				)
		SELECT 
				EL.idexp,
				C.idregistrylegalstatus,
				'8221',
				SUM(ETO.employtax),
				C.idreg
		FROM expensepayroll EP
		JOIN payroll P
			on P.idpayroll = EP.idpayroll
		JOIN parasubcontract C
			ON C.idcon = P.idcon
		JOIN parasubcontractyear CY
			ON C.idcon = CY.idcon AND CY.ayear = @annoredditi
		JOIN expenselink ELK
			ON ELK.idparent = EP.idexp
		JOIN expenselast EL
			on EL.idexp = ELK.idchild
		JOIN expensetaxofficial ETO
			ON ETO.idexp = EL.idexp
		JOIN tax T
			ON ETO.taxcode = T.taxcode
		JOIN voce8000lookup V
			ON V.taxref = T.taxref
		JOIN payment
			on payment.kpay = EL.kpay
		JOIN service S
			ON S.idser = C.idser
		WHERE T. taxkind = 1 
			AND payment.ypay = @ayear--
			AND isnull(ETO.employtax,0) >= 0
			AND geoappliance = 'C'
			AND V.voce = '8221'
			AND V.servicekind='ASSIMILATO'
			AND S.voce8000='8186'		-- Prende solo le ritenute di quelle prestazioni mappate con l'imponibile assicutarivo CSA
			AND ETO.stop is null
			AND payment.kpaymenttransmission IS NOT NULL
			AND payment.adate between @start and @stop
			AND C.idregistrylegalstatus IS NOT NULL
		GROUP BY EL.idexp, C.idregistrylegalstatus, V.voce,	C.idreg
					
		-- 8193 IRAP ac lav.ass.
		INSERT INTO #pagamenti(
				idexp,
				idregistrylegalstatus,
				voce8000,
				importo,
				idreg
				)
		SELECT 
				EL.idexp,
				C.idregistrylegalstatus,
				'8193',
				SUM(ETO.admintax),
				C.idreg
		FROM expensepayroll EP
		JOIN payroll P
			on P.idpayroll = EP.idpayroll
		JOIN parasubcontract C
			ON C.idcon = P.idcon
		JOIN parasubcontractyear CY
			ON C.idcon = CY.idcon AND CY.ayear = @annoredditi
		JOIN expenselink ELK
			ON ELK.idparent = EP.idexp
		JOIN expenselast EL
			on EL.idexp = ELK.idchild
		JOIN expensetaxofficial ETO
			ON ETO.idexp = EL.idexp
		JOIN tax T
			ON ETO.taxcode = T.taxcode
		JOIN voce8000lookup V
			ON V.taxref = T.taxref
		JOIN payment 
			on payment.kpay = EL.kpay
		JOIN service S
			ON S.idser = C.idser
		WHERE T. taxkind = 2 
			AND isnull(ETO.admintax,0) >= 0
			AND geoappliance is null
			AND V.voce = '8193'
			AND payment.ypay = @ayear
			AND V.servicekind='ASSIMILATO'
