if object_id('[trigger_i_accountyear]') is not null
	drop TRIGGER [trigger_i_accountyear]
go

CREATE                TRIGGER [trigger_i_accountyear] ON [accountyear] FOR INSERT
AS BEGIN
IF @@ROWCOUNT > 0
BEGIN
	DECLARE @ayear int
	DECLARE @idsor int
	DECLARE	@idacc varchar(38)
	DECLARE	@prevision decimal(19, 2)
	DECLARE	@previousprevision decimal(19, 2)
	DECLARE	@expiration datetime
	DECLARE	@cu varchar(64)
	DECLARE	@ct datetime
	DECLARE	@lu varchar(64)
	DECLARE	@lt datetime
	SELECT	@idsor = idsor, @idacc = idacc, @ayear=ayear,
		@prevision=prevision, @previousprevision=previousprevision, 
		@cu=cu, @ct=ct, @lu=lu, @lt=lt
	FROM inserted
	-- Se sto inserendo un capitolo devo propagare la modifica fino al primo livello
	-- altrimenti inserisco in UPBTOTAL solo la voce di bilancio appena inserita
	IF (LEN(@idacc)-2)/4 = CONVERT(int,(SELECT MIN(nlevel) FROM accountlevel WHERE flagusable='S' AND ayear = @ayear)) 
	BEGIN
		EXEC trg_upd_sortingextended @idsor, @idacc, @previousprevision,@prevision
	END
	ELSE
	BEGIN
		IF EXISTS(SELECT * FROM sortingtotal
			WHERE idacc = @idacc AND idsor = @idsor)
		BEGIN
			INSERT INTO sortingtotal
			(
				idsor,
				idacc,
				currentprev,
				previousprev
			)
			VALUES
			(
				@idsor,
				@idacc,
				@prevision,
				@previousprevision
			)
		END
		ELSE
		BEGIN
			UPDATE sortingtotal SET currentprev = @prevision, previousprev = @previousprevision
			WHERE idsor = @idsor AND idacc = @idacc
		END
	END
-- Inserimento righe in ACCOUNTYEAR a zero sugli IDSOR padre di quello che sto inserendo nel caso in cui
-- tale voce non esiste
	DECLARE @curridsor int
	SELECT @curridsor = paridsor FROM sorting WHERE idsor = @idsor
	-- Livello di curridsor
	DECLARE @currlevel tinyint
	SELECT @currlevel = nlevel FROM sorting WHERE idsor = @curridsor
	IF (@curridsor IS NOT NULL) AND (@currlevel >= 1)
	BEGIN
		IF NOT EXISTS(SELECT * FROM accountyear WHERE idsor = @curridsor AND idacc = @idacc)
		BEGIN
			INSERT INTO accountyear
			(
				idsor, idacc,
				prevision, previousprevision,
				ct, cu, lt, lu,
				ayear
			)
			VALUES
			(
				@curridsor, @idacc,
				0, 0,
				GETDATE(), 'TRIGGER', GETDATE(), '''TRIGGER''',
				@ayear
			)
			SET @currlevel = @currlevel - 1
			SELECT @curridsor = idparent FROM sortinglink WHERE idchild = @idsor AND nlevel = @currlevel
		END
	END
END
END


GO

print '[trigger_i_accountyear] OK'

