CREATE   PROCEDURE exp_interscambio_csa_dipendentiassimilato
 (
	@datagenerazione datetime,
	@ayear int,
	@ateneo varchar(5),
	@tiporecord varchar(2) ,
	@tipoCompenso char(1), -- Assume valori T = Conto Terzi, C = CO.CO.CO. , B = Borse di studio
	@start datetime,
	@stop datetime
)
AS 
/*
exec exp_interscambio_csa_dipendentiassimilato {ts '2010-12-31 01:02:03'} ,2010, '70136','15', 'C',{ts '2010-01-01 01:02:03'},{ts '2010-12-31 01:02:03'}
