if object_id('check_emens') is not null
	drop PROCEDURE check_emens
go

CREATE    PROCEDURE check_emens
(
	@datacontabile datetime,
	@anno int,
	@meseinizio int,
	@mesefine int,
        @unified char(1)
)
AS BEGIN
--        exec check_emens  {ts '2012-12-31 00:00:00'},2012,1,12,'N'
CREATE TABLE #logerror(
	severity char(1),
        departmentname varchar(500),
	errore varchar(400),
	soluzione varchar(400)
)
CREATE TABLE #mittente(
	cfpersonamittente varchar(16),
	ragsocmittente varchar(50),
	cfmittente varchar(16),
	cfsoftwarehouse varchar(16),
	flagesisteresponsabile char(1)
)
INSERT INTO #mittente
EXEC emens_getdatimittente @anno
DECLARE @curr_departmentname varchar(500)
SET  @curr_departmentname = ISNULL( (SELECT paramvalue from
			 generalreportparameter where idparam='DenominazioneDipartimento' and 
				(start is null or start <= @datacontabile) and
				(stop is null or stop >= @datacontabile)
				),'Manca Cfg. Parametri Tutte le stampe')

-- Controllo degli errori su #mittente
INSERT INTO #logerror
SELECT 'S',@curr_departmentname,'Non è stato selezionato un responsabile per la trasmissione dell''E-Mens',
'Andare in ''Configurazione - Responsabile Trasmissione - Configurazione'', ed inserire un responsabile per la trasmissione del modello E-Mens'
FROM #mittente WHERE flagesisteresponsabile = 'N'
INSERT INTO #logerror
SELECT 'S',@curr_departmentname,'Non è stato inserito il codice fiscale del mittente',
'Andare in ''Configurazione - Informazioni Ente'' ed inserire il codice fiscale'
FROM #mittente WHERE (cfmittente = '' OR cfmittente IS NULL)
INSERT INTO #logerror
SELECT 'S',@curr_departmentname,'Il codice fiscale del mittente non ha lunghezza pari a 11',
'Andare in ''Configurazione - Informazioni Ente'' e correggere il codice fiscale'
FROM #mittente WHERE (DATALENGTH(cfmittente) <> 11)
INSERT INTO #logerror
SELECT 'S',@curr_departmentname,'Non è stato inserito il codice fiscale del responsabile alla trasmissione dell''E-Mens',
'Andare in ''Anagrafiche - Anagrafica - Anagrafica'', scegliere il responsabile della trasmissione dell''E-Mens
 (precedentemente configurato in Configurazione - Responsabile Trasmissione - Configurazione) ed inserire il codice fiscale.'
FROM #mittente WHERE (cfpersonamittente = '' OR cfpersonamittente IS NULL)

CREATE TABLE #listacollaboratori(
    departmentname varchar(500),
	cfcollaboratore varchar(16),
	cognome varchar(50),
	nome varchar(20),
	tiporapporto varchar(2),
	codiceattivita varchar(2),
	imponibile decimal(19,2),
	aliquota decimal(19,6),
	altraass varchar(3),
	dal smalldatetime,
	al smalldatetime,
	codicecomune varchar(20),
	codcalamita varchar(2),
	codcertificazione varchar(3)
)
DECLARE @parentsp char(1)
SET @parentsp = 'E'
DECLARE @iddbdepartment varchar(50)
DECLARE @crsdepartment cursor
DECLARE @dip_nomesp varchar(300)
SET @crsdepartment = cursor FOR SELECT iddbdepartment FROM dbdepartment
where (start is null or start <= @anno ) AND ( stop is null or stop >= @anno)
OPEN @crsdepartment
FETCH NEXT FROM @crsdepartment INTO @iddbdepartment
WHILE @@fetch_status=0 
Begin
		DELETE FROM #listacollaboratori
        IF (@unified = 'N') SET @iddbdepartment = user-- Se non deve consolidare, esegue la sp per 'user' ed esce dal WHILE tramite il BREAK.
        SET @dip_nomesp = @iddbdepartment + '.emens_daticollaboratore'
        
        INSERT INTO #listacollaboratori
        EXEC @dip_nomesp @anno,@meseinizio,@mesefine,@parentsp,@datacontabile
        DECLARE @epsilon decimal (19,4)
        SET @epsilon = 0.0005
        
	if (@anno >= Year(GetDate()))
	BEGIN
	        -- Controllo degli errori su #listacollaboratori
	        INSERT INTO #logerror
	        SELECT 'S',departmentname,'L''aliquota applicata a ' + cognome + ' ' + nome + ' è errata. Le aliquote riconosciute sono il 20% ed il  27.72% e non ' + CONVERT(varchar(20),aliquota*100)+ '%','Chiamare l''assistenza'
	        FROM #listacollaboratori
	        WHERE 
				aliquota NOT BETWEEN (0.2772- @epsilon) AND (0.2772 + @epsilon)
				AND aliquota NOT BETWEEN (0.2 - @epsilon) AND (0.2 + @epsilon)
	
--	        INSERT INTO #logerror
--	        SELECT 'S',departmentname,'Al percipiente ' + cognome + ' ' + nome + ' non è stata selezionata l''altra forma assicurativa ',
--	        ' Controllare le prestazioni effettuate '
--	        FROM #listacollaboratori
--	        WHERE altraass IS NULL --AND aliquota BETWEEN (0.2 - @epsilon) AND (0.2772 + @epsilon)
    END

        INSERT INTO #logerror
        SELECT 'S',departmentname,'Codice fiscale del collaboratore ' + cognome + ' ' + nome + ' assente',
        'Andare in in ''Anagrafiche - Anagrafica - Anagrafica e aggiungere il codice fiscale'
        FROM #listacollaboratori WHERE (cfcollaboratore = '' OR cfcollaboratore IS NULL)
        
        INSERT INTO #logerror
        SELECT 'S',departmentname,'Codice fiscale del collaboratore ' + cognome + ' ' + nome + ' non ha lunghezza pari a 16',
        'Andare in in ''Anagrafiche - Anagrafica - Anagrafica e correggere il codice fiscale'
        FROM #listacollaboratori WHERE (DATALENGTH(cfcollaboratore) <> 16)
        
        INSERT INTO #logerror
        SELECT 'S',departmentname,'La lunghezza del codice del comune per il collaboratore ' + cognome + ' ' + nome + 
        ' nel periodo ' + CONVERT(varchar(16),dal) + ' è differente dalla lunghezza standard di 4 caratteri',
        'Controllare il codice Belfiore del comune (idagency = 1, idcode = 1)'
        FROM #listacollaboratori WHERE DATALENGTH(codicecomune) <> 4
        
        INSERT INTO #logerror
        SELECT 'S',departmentname,'Al collaboratore ' + cognome + ' ' + nome + 
        ' non è stato associato il codice comune',
        'Andare in Configurazione\Informazioni ente ed inserire il comune dell''Ente. '
        FROM #listacollaboratori WHERE codicecomune IS NULL
		
		INSERT INTO #logerror
        SELECT 'S',departmentname,'Al percipiente ' + cognome + ' ' + nome + 
        ' non è stato associato il tipo rapporto Emens in corrispondenza ' + 
		' di una prestazione con ritenuta INPS effettuata presso ' + departmentname ,
        ' Controllare le prestazioni effettuate '
        FROM #listacollaboratori WHERE tiporapporto IS NULL
   
      
        DECLARE @cf varchar(16)
        DECLARE @cognome varchar(40)
        DECLARE @nome varchar(40)
        DECLARE @posizione char(1)
        DECLARE @departmentname varchar(500)
        -- Il cursore viene costruito in modo da considerare tutti i percipienti e il responsabile della trasmissione.
        -- Il responsabile della trasmissione è marcato con il valore R mentre i percipienti con P, in modo da parametrizzare
        -- il messaggio di output
        DECLARE listacoll_cursor INSENSITIVE CURSOR FOR
        SELECT DISTINCT cfcollaboratore,cognome,nome,'P' AS posizione,departmentname FROM #listacollaboratori
        UNION SELECT cfpersonamittente,NULL AS cognome,NULL AS nome,'R' AS posizione, @curr_departmentname AS departmentname FROM #mittente
        FOR READ ONLY
        OPEN listacoll_cursor
        FETCH NEXT FROM listacoll_cursor INTO @cf,@cognome,@nome,@posizione,@departmentname
        WHILE(@@FETCH_STATUS = 0)
         BEGIN
          DECLARE @i int
          DECLARE @tot_codfisc int
          DECLARE @sum_disp	int
          DECLARE @sum_pari	int
          DECLARE @lf char(1)
          SET @i = 0
          SET @tot_codfisc = 0
          SET @sum_disp = 0
          SET @sum_pari = 0
        	
          WHILE (@i < 8)
           BEGIN
        		SELECT @sum_disp = @sum_disp + oddposition
        		FROM buildcf
        		WHERE letter = SUBSTRING(@cf,2 * @i + 1,1)
        	
        		IF @i > 0
        		 BEGIN
        			SELECT @sum_pari = @sum_pari + evenposition
        			FROM buildcf
        			WHERE letter = SUBSTRING(@cf,2 * @i,1)
        		 END
        		SELECT @i = @i + 1
           END
           SELECT @tot_codfisc = @sum_disp + @sum_pari
           SELECT @lf = letter FROM buildcf WHERE evenposition = (@tot_codfisc % 26) AND kind <> 'N'
           DECLARE @cf_built varchar(16)
           SET @cf_built = SUBSTRING(@cf,1,LEN(@cf) - 1) + @lf
           SET @cf = UPPER(@cf)
           SET @cf_built = UPPER(@cf_built)
           IF (@cf <> @cf_built)
        	BEGIN
        		IF (@posizione = 'P')
        		 BEGIN
            		INSERT INTO #logerror
        			VALUES('S',@departmentname,'L''ultimo carattere del codice fiscale di ' + @cognome + ' ' + @nome + ' non è corretto',
        			'Andare in in ''Anagrafiche - Anagrafica - Anagrafica e correggere il codice fiscale')
        		 END
        		IF (@posizione = 'R')
        		 BEGIN
            		INSERT INTO #logerror
        			VALUES('S',@departmentname,'L''ultimo carattere del codice fiscale del responsabile della trasmissione non è corretto',
        			'Andare in in ''Anagrafiche - Anagrafica - Anagrafica e correggere il codice fiscale')
        		 END
        	END
           FETCH NEXT FROM listacoll_cursor INTO @cf,@cognome,@nome,@posizione,@departmentname	
         END
        CLOSE listacoll_cursor
        DEALLOCATE listacoll_cursor
        
-- cursore dipartimento
        IF (@unified = 'N') BREAK -- Se non deve consolidare esegue solo la sp per 'user'.
	FETCH NEXT FROM @crsdepartment INTO @iddbdepartment
END
CLOSE @crsdepartment
DEALLOCATE @crsdepartment
SELECT severity,
        departmentname as dipartimento,
	errore,
	soluzione 
FROM #logerror
ORDER BY dipartimento
END


GO

print 'check_emens OK'

GO
if object_id('[compute_flowchartcopy]') is not null
	drop PROCEDURE [compute_flowchartcopy]
go

CREATE    PROCEDURE [compute_flowchartcopy]
(
    @source	varchar(50),
	@dest	varchar(50),
	@startayear int,
	@stopayear  int
	
)
AS BEGIN
CREATE TABLE #log (messaggio varchar(255))
CREATE TABLE #ayearDipDest(ayear int )
/*
IF (@source <> @dest)
BEGIN
	INSERT INTO #log(messaggio)
	VALUES('Il dipartimento di partenza deve essere uguale a quello di destinazione')
	
	SELECT * FROM #log
	RETURN
END
*/
-- Inserisce in #ayearDipDest tutti gli esercizi in cui deve copiare la config. dell'organigramma. 
-- Prende tutti gli esercizi per cui è stata fatta la fase "Creazione nuovo esercizio"
-- Se non ho specificato l'esercizio di destinazione, e quindi '@stopayear IS NULL' devo copiare la config. in tutti gli esercizi (sia precedenti che successivi),
-- tranne quello di origine.
SET @stopayear = ISNULL(@stopayear,0)
DECLARE @query nvarchar(4000)
IF (@source = @dest)
BEGIN
-- se dipartimneto parteza = dipartimneto arrivo => esclude l'esercizio di partenza @startayear.
	SET @query =
	'SELECT ayear FROM '+ @dest+'.accountingyear'+
	' WHERE ( '+ CONVERT(varchar(4),@stopayear) +' = 0 AND ((flag&0x0F)>=1) AND ayear <> '+ CONVERT(varchar(4),@startayear) +' ) 
			OR
		 ( ayear = '+ CONVERT(varchar(4),@stopayear) +' ) '
END
ELSE
BEGIN
	SET @query =
	'SELECT ayear FROM '+ @dest+'.accountingyear'+
	' WHERE ( '+ CONVERT(varchar(4),@stopayear) +' = 0 AND ((flag&0x0F)>=1)  ) 
			OR
		 ( ayear = '+ CONVERT(varchar(4),@stopayear) +' ) '
END
 
INSERT INTO #ayearDipDest(ayear)
EXEC (@query)
-- Controlla che nel Dip. di partenza ci sia l'esercizio che vogliamo copiare
SET @query =
	'IF NOT EXISTS (SELECT * FROM ' + @source+'.accountingyear WHERE ayear = '+CONVERT(varchar(4),@startayear)+') 
	BEGIN	INSERT INTO #log(messaggio)
			VALUES(''Non esiste nel dipartimento : ' + @source+', l''''esercizio '' + ''' + CONVERT(varchar(4),@startayear) +''' )
	END'
EXEC (@query)
IF (SELECT COUNT(*) FROM #log) > 0
BEGIN
	SELECT * FROM #log
	RETURN
END
DECLARE @ayearcopying int
DECLARE crsayear INSENSITIVE CURSOR FOR
	SELECT ayear FROM #ayearDipDest
ORDER BY ayear
OPEN crsayear 
FETCH NEXT FROM crsayear INTO @ayearcopying
        WHILE @@fetch_status=0 begin
-- Se nel dip. di destinazione non ci sono righe nelle tab. dei livelli - struttura dell'organigrammam - funzioni,
-- allora fa la copia, anche se i dip. sono diversi.
 
				SET @query =
				'IF ( NOT EXISTS (SELECT * FROM ' +@dest+'.flowchartlevel WHERE ayear = '+CONVERT(varchar(4),@ayearcopying)+') 
				AND 
					NOT EXISTS (SELECT * FROM '+@dest+'.flowchart WHERE ayear = '+CONVERT(varchar(4),@ayearcopying)+')
				AND 
					NOT EXISTS (SELECT * FROM  '+@dest+'.flowchartrestrictedfunction WHERE idflowchart like SUBSTRING('''
					+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + ''%'') 
					)
				BEGIN
					INSERT INTO '+@dest+'.flowchartlevel(ayear, nlevel, description, flagusable,cu, ct, lu, lt)
					SELECT '+CONVERT(varchar(4),@ayearcopying)+', nlevel, description,flagusable,''compute_flowchartcopy'', GETDATE(), lu, GETDATE()
					FROM '+@source+'.flowchartlevel
					WHERE ayear = '+CONVERT(varchar(4),@startayear)+'
					INSERT INTO #log
					VALUES(''Trasferiti livelli organigramma annuale per esercizio '' + ''' + CONVERT(varchar(4),@ayearcopying) +''' )
					INSERT INTO '+@dest+'.flowchart
							(
								idflowchart,
								ayear, codeflowchart,
								nlevel, paridflowchart, printingorder, title, 
								fax, phone, address, idcity, cap, location,
								cu, ct, lu, lt
							)
						SELECT
							SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + SUBSTRING(idflowchart, 3, 32),'+CONVERT(varchar(4),@ayearcopying)+', codeflowchart, nlevel,
							SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + SUBSTRING(paridflowchart, 3, 32),printingorder, title,
							fax, phone, address, idcity, cap, location,
							''compute_flowchartcopy'', GETDATE(), lu, GETDATE()
						FROM '+@source+'.flowchart
						WHERE ayear = '+CONVERT(varchar(4),@startayear)+'
					INSERT INTO #log
					VALUES(''Trasferito Struttura Oganigramma annuale per esercizio '' + ''' + CONVERT(varchar(4),@ayearcopying) +''' )
					INSERT INTO  '+@dest+'.flowchartrestrictedfunction
						(
							idflowchart,
							idrestrictedfunction,
							ct,cu,lt,lu
						)
					SELECT
							SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + SUBSTRING(idflowchart, 3, 32),
							idrestrictedfunction,
							GETDATE(), ''compute_flowchartcopy'', GETDATE(), lu
					FROM '+@source+'.flowchartrestrictedfunction
					WHERE idflowchart like SUBSTRING('''+CONVERT(varchar(4),@startayear)+''', 3, 2) + ''%''
					INSERT INTO #log
					VALUES(''Trasferita restrizioni sicurezza esportazioni nel nuovo esercizio '' + ''' + CONVERT(varchar(4),@ayearcopying)+''' )
				END'
				print @query
				EXEC (@query)
-- Questi trasferimenti li fa solo se è l'operazione la si sta facendo all'interno dello stesso dipartimento, perchè
-- le tabelle hanno dei riferimenti esterni a tabelle NON dbo.
	if(@source = @dest)
	begin
				SET @query =
					'IF NOT EXISTS (SELECT * FROM '+@dest+'.flowchartexportmodule WHERE idflowchart like SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + ''%'')
					BEGIN
						INSERT INTO '+@dest+'.flowchartexportmodule
							(
								idflowchart,
								modulename,
								lu,
								lt
							)
						SELECT
								SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + SUBSTRING(idflowchart, 3, 32),
								modulename,
								lu, GETDATE()
							FROM '+@source+'.flowchartexportmodule
							WHERE idflowchart like SUBSTRING('''+CONVERT(varchar(4),@startayear)+''', 3, 2) + ''%''
							INSERT INTO #log
							VALUES(''Trasferite configurazioni sicurezza stampe nel nuovo esercizio '' + ''' + CONVERT(varchar(4),@ayearcopying)+''' )
					END'
				print @query
				EXEC (@query)
				SET @query =
					'IF NOT EXISTS (SELECT * FROM '+@dest+'.flowchartmanager WHERE idflowchart like SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + ''%'')
					BEGIN
						INSERT INTO '+@dest+'.flowchartmanager
							(
								idflowchart,
								idman,
								cu, ct, lu, lt
							)
						SELECT
							SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + SUBSTRING(idflowchart, 3, 32),
							idman,
							''compute_flowchartcopy'', GETDATE(), lu, GETDATE()
						FROM '+@source+'.flowchartmanager
						WHERE idflowchart like SUBSTRING('''+CONVERT(varchar(4),@startayear)+''', 3, 2) + ''%''
						INSERT INTO #log
						VALUES(''Trasferiti responsabili organigramma nel nuovo esercizio '' + ''' + CONVERT(varchar(4),@ayearcopying)+''' )
					END'
				print @query
				EXEC (@query)
				SET @query =
					'IF NOT EXISTS (SELECT * FROM  '+@dest+'.flowchartmodulegroup WHERE idflowchart like SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + ''%'')
					BEGIN
						INSERT INTO  '+@dest+'.flowchartmodulegroup
							(
								idflowchart,
								modulename,
								groupname,
								lu,
								lt
							)
						SELECT
								SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + SUBSTRING(idflowchart, 3, 32),
								modulename,
								groupname,
								lu, GETDATE()
						FROM '+@source+'.flowchartmodulegroup
						WHERE idflowchart like SUBSTRING('''+CONVERT(varchar(4),@startayear)+''', 3, 2) + ''%''
							INSERT INTO #log
							VALUES(''Trasferita configurazione sicurezza stampe nel nuovo esercizio '' + ''' + CONVERT(varchar(4),@ayearcopying)+''' )
					END'
					print @query
					EXEC (@query)

				SET @query =
					'IF NOT EXISTS (SELECT * FROM ' +@dest+'.flowchartsorting WHERE idflowchart like SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + ''%'')
					BEGIN
						INSERT INTO ' +@dest+'.flowchartsorting
							(
								idflowchart,
								quota,
								idsor,
								ct,cu,lt,lu
							)
						SELECT
								SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + SUBSTRING(idflowchart, 3, 32),
								quota,
								idsor,
								GETDATE(), ''compute_flowchartcopy'', GETDATE(), lu
						FROM '+@source+'.flowchartsorting
						WHERE idflowchart like SUBSTRING('''+CONVERT(varchar(4),@startayear)+''', 3, 2) + ''%''
						INSERT INTO #log
						VALUES(''Trasferita Classificazione organigramma nel nuovo esercizio '' + ''' + CONVERT(varchar(4),@ayearcopying)+''' )
					END'
					print @query
					EXEC (@query)
				SET @query =
					'IF NOT EXISTS (SELECT * FROM ' +@dest+'.flowchartupb WHERE idflowchart like SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + ''%'')
					BEGIN
						INSERT INTO ' +@dest+'.flowchartupb
							(
								idflowchart,
								idupb,
								ct,cu,lt,lu
							)
						SELECT
							SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + SUBSTRING(idflowchart, 3, 32),
							idupb,
							GETDATE(), ''compute_flowchartcopy'', GETDATE(), lu
						FROM '+@source+'.flowchartupb
						WHERE idflowchart like SUBSTRING('''+CONVERT(varchar(4),@startayear)+''', 3, 2) + ''%''
						INSERT INTO #log
						VALUES(''Trasferita associazione UPB organigramma nel nuovo esercizio '' + ''' + CONVERT(varchar(4),@ayearcopying)+''' )
					END'
					print @query
					EXEC (@query)

				SET @query =
					'IF NOT EXISTS (SELECT * FROM ' +@dest+'.flowchartmandatekind WHERE idflowchart like SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + ''%'')
					BEGIN
						INSERT INTO ' +@dest+'.flowchartmandatekind
							(
								idflowchart,
								idmankind,
								cu, ct, lu, lt
							)
						SELECT
							SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + SUBSTRING(idflowchart, 3, 32),
							idmankind,
							''compute_flowchartcopy'', GETDATE(), lu, GETDATE()
						FROM '+@source+'.flowchartmandatekind
						WHERE idflowchart like SUBSTRING('''+CONVERT(varchar(4),@startayear)+''', 3, 2) + ''%''
						INSERT INTO #log
						VALUES(''Trasferita associazione Tipi Contratto passivo  organigramma nel nuovo esercizio '' + ''' + CONVERT(varchar(4),@ayearcopying)+''' )
					END'
					print @query
					EXEC (@query)
				SET @query =
					'IF NOT EXISTS (SELECT * FROM ' +@dest+'.flowchartestimatekind WHERE idflowchart like SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + ''%'')
					BEGIN
						INSERT INTO ' +@dest+'.flowchartestimatekind
							(
								idflowchart,
								idestimkind,
								cu, ct, lu, lt
							)
						SELECT
							SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + SUBSTRING(idflowchart, 3, 32),
							idestimkind,
							''compute_flowchartcopy'', GETDATE(), lu, GETDATE()
						FROM '+@source+'.flowchartestimatekind
						WHERE idflowchart like SUBSTRING('''+CONVERT(varchar(4),@startayear)+''', 3, 2) + ''%''
						INSERT INTO #log
						VALUES(''Trasferita associazione Tipi Contratto attivo organigramma nel nuovo esercizio '' + ''' + CONVERT(varchar(4),@ayearcopying)+''' )
					END'
					print @query
					EXEC (@query)

				SET @query =
					'IF NOT EXISTS (SELECT * FROM ' +@dest+'.flowchartinvoicekind WHERE idflowchart like SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + ''%'')
					BEGIN
						INSERT INTO ' +@dest+'.flowchartinvoicekind
							(
								idflowchart,
								idinvkind,
								cu, ct, lu, lt
							)
						SELECT
							SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + SUBSTRING(idflowchart, 3, 32),
							idinvkind,
							''compute_flowchartcopy'', GETDATE(), lu, GETDATE()
						FROM '+@source+'.flowchartinvoicekind
						WHERE idflowchart like SUBSTRING('''+CONVERT(varchar(4),@startayear)+''', 3, 2) + ''%''
						INSERT INTO #log
						VALUES(''Trasferita associazione Documenti IVA organigramma nel nuovo esercizio '' + ''' + CONVERT(varchar(4),@ayearcopying)+''' )
					END'
					print @query
					EXEC (@query)
				SET @query =
					'IF NOT EXISTS (SELECT * FROM ' +@dest+'.flowchartauthagency WHERE idflowchart like SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + ''%'')
					BEGIN
						INSERT INTO ' +@dest+'.flowchartauthagency
							(
								idflowchart,
								idauthagency,
								lu, lt
							)
						SELECT
							SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + SUBSTRING(idflowchart, 3, 32),
							idauthagency,
						    ''compute_flowchartcopy'', GETDATE()
						FROM '+@source+'.flowchartauthagency
						WHERE idflowchart like SUBSTRING('''+CONVERT(varchar(4),@startayear)+''', 3, 2) + ''%''
						INSERT INTO #log
						VALUES(''Trasferita associazione Agenti autorizzatori Missioni organigramma nel nuovo esercizio '' + ''' + CONVERT(varchar(4),@ayearcopying)+''' )
					END'
						
				print @query
				EXEC (@query)
					
				SET @query =
					'IF NOT EXISTS (SELECT * FROM ' +@dest+'.flowchartauthmodel WHERE idflowchart like SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + ''%'')
					BEGIN
						INSERT INTO ' +@dest+'.flowchartauthmodel
							(
								idflowchart,
								idauthmodel,
								cu, ct, lu, lt
							)
						SELECT
							SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + SUBSTRING(idflowchart, 3, 32),
							idauthmodel,
							''compute_flowchartcopy'', GETDATE(), lu, GETDATE()
						FROM '+@source+'.flowchartauthmodel
						WHERE idflowchart like SUBSTRING('''+CONVERT(varchar(4),@startayear)+''', 3, 2) + ''%''
						INSERT INTO #log
						VALUES(''Trasferita associazione Modelli autorizzativi Missioni organigramma nel nuovo esercizio '' + ''' + CONVERT(varchar(4),@ayearcopying)+''' )
					END'
					
					print @query
					EXEC (@query)
									SET @query =
					'IF NOT EXISTS (SELECT * FROM ' +@dest+'.flowchartpettycash WHERE idflowchart like SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + ''%'')
					BEGIN
						INSERT INTO ' +@dest+'.flowchartpettycash
							(
								idflowchart,
								idpettycash,
								cu, ct, lu, lt
							)
						SELECT
							SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + SUBSTRING(idflowchart, 3, 32),
							idpettycash,
							''compute_flowchartcopy'', GETDATE(), lu, GETDATE()
						FROM '+@source+'.flowchartpettycash
						WHERE idflowchart like SUBSTRING('''+CONVERT(varchar(4),@startayear)+''', 3, 2) + ''%''
						INSERT INTO #log
						VALUES(''Trasferita associazione Fondi Economale organigramma nel nuovo esercizio '' + ''' + CONVERT(varchar(4),@ayearcopying)+''' )
					END'
					print @query
					EXEC (@query)
				----------------------------------------------------------------------------------
				----------------- FLOWCHARTFIN DOPO IL TRASFERIMENTO DEL BILANCIO-----------------
				----------------------------------------------------------------------------------
/* 
SE  ( @startayear < @ayearcopying ) vuol dire che stiamo trasferendo negli esercizio successivi, in avanti, 2006->2007,2008,...
		l'IF controlla che in allfinlookup esista la voce di bilancio come old nell'anno start (2006) e come new nell'anno copying(2007,2008,...)
		perchè deve fare	old = 2006 -> new = 2007
							old = 2006 -> new = 2008
SE  ( @startayear > @ayearcopying ) vuol dire che stiamo trasferendo negli esercizio precedenti, in dietro, 2006->2005,2004,...
		l'IF controlla che in allfinlookup esista la voce di bilancio come new nell'anno start (2006) e come old nell'anno copying(2004,2005,...)
		perchè deve fare new = 2006 -> old = 2004
						 new = 2006 -> old = 2005
*/
		IF(@startayear<@ayearcopying)
		begin
				SET @query =
					'IF (
						EXISTS (SELECT * 
										FROM '+@dest+'.allfinlookup FK
										JOIN '+@dest+'.fin Fold ON FK.oldidfin = Fold.idfin
										JOIN '+@dest+'.fin Fnew ON FK.newidfin = Fnew.idfin
										WHERE Fold.ayear = '+CONVERT(varchar(4),@startayear)+'
											AND Fnew.ayear = '+ CONVERT(varchar(4), @ayearcopying) +'	)		
							
						AND 
						NOT EXISTS (SELECT * 
							  FROM ' +@dest+'.flowchartfin 
								 WHERE idflowchart like SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + ''%'')
						)
					BEGIN
						INSERT INTO ' +@dest+'.flowchartfin
							(
								idflowchart,
								idfin,
								ct,cu,lt,lu
							)
						SELECT
							SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + SUBSTRING(FC.idflowchart, 3, 32),
							FL.newidfin,
							GETDATE(), ''compute_flowchartcopy'', GETDATE(), FC.lu
						FROM '+@source+'.flowchartfin FC
						JOIN '+@source+'.fin F 
								ON FC.idfin = F.idfin
						JOIN '+@source+'.allfinlookup FL 
								ON FC.idfin = FL.oldidfin
						JOIN '+@source+'.fin Fnew
							ON FL.newidfin = Fnew.idfin
						WHERE F.ayear = '+ CONVERT(varchar(4),@startayear) +'
							AND Fnew.ayear = '+ CONVERT(varchar(4), @ayearcopying) +'
							AND FC.idflowchart like SUBSTRING('''+CONVERT(varchar(4),@startayear)+''', 3, 2) + ''%''
					INSERT INTO #log
					VALUES(''Trasferita Sicurezza Bilancio nel nuovo esercizio '' + ''' + CONVERT(varchar(4),@ayearcopying)+''' )
					END'
					print @query
					EXEC (@query)
		End
		IF(@startayear > @ayearcopying)-- 2009 -> 2008
		Begin
				SET @query =
					'IF (
						EXISTS (SELECT * 
										FROM '+@dest+'.allfinlookup FK
										JOIN '+@dest+'.fin Fnew ON FK.newidfin = Fnew.idfin
										JOIN '+@dest+'.fin Fold ON FK.oldidfin = Fold.idfin
										WHERE Fnew.ayear = '+CONVERT(varchar(4),@startayear)+'
										AND Fold.ayear = '+ CONVERT(varchar(4), @ayearcopying) +'	)		
						AND 
						NOT EXISTS (SELECT * 
							  FROM ' +@dest+'.flowchartfin 
								 WHERE idflowchart like SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + ''%'')
						)
					BEGIN
						INSERT INTO ' +@dest+'.flowchartfin
							(
								idflowchart,
								idfin,
								ct,cu,lt,lu
							)
						SELECT
							SUBSTRING('''+CONVERT(varchar(4),@ayearcopying)+''', 3, 2) + SUBSTRING(FC.idflowchart, 3, 32),
							FL.oldidfin,
							GETDATE(), ''compute_flowchartcopy'', GETDATE(), FC.lu
						FROM '+@source+'.flowchartfin FC
						JOIN '+@source+'.fin F 
								ON FC.idfin=F.idfin
						JOIN '+@source+'.allfinlookup FL 
								ON FC.idfin = FL.newidfin
						JOIN '+@source+'.fin Fold
							ON FL.oldidfin = Fold.idfin
						WHERE F.ayear = '+ CONVERT(varchar(4), @startayear) +'
							AND Fold.ayear = '+ CONVERT(varchar(4), @ayearcopying) +'
							AND FC.idflowchart like SUBSTRING('''+CONVERT(varchar(4),@startayear)+''', 3, 2) + ''%''
						INSERT INTO #log
						VALUES(''Trasferita Sicurezza Bilancio nel nuovo esercizio '' + ''' + CONVERT(varchar(4),@ayearcopying)+''' )
					END'
					print @query
					EXEC (@query)
			end
	end
	FETCH NEXT FROM crsayear INTO @ayearcopying
end
deallocate crsayear
SELECT * FROM #log
DROP TABLE #log
DROP TABLE #ayearDipDest
END


GO

print '[compute_flowchartcopy] OK'

