if object_id('[rpt_4certificazioni]') is not null
	drop PROCEDURE [rpt_4certificazioni]
go


CREATE       PROCEDURE [rpt_4certificazioni]
(
	@ayear smallint, 
	@idreg int, 
	@start datetime,
	@stop datetime,
	@certificatekind char(1)
)
AS BEGIN
/*
	exec rpt_4certificazioni 2008,732,{ts '2008-01-20 00:00:00'},{ts '2008-12-31 00:00:00'}, 'f'
*/
CREATE TABLE #expensetax
(
	idexp int,
	idreg int,
	taxdescription varchar(50),
	expensedescription varchar(150),	
	commondetail char(1),
	taxablenet decimal(19,2),
	employtax decimal(19,2),
	admintax decimal(19,2),
	grossamount decimal (19,2),
	--taxablegross decimal (19,2), IL REPORT NON LO USA !
	service varchar(50),
	idser int,
	npay int
)
CREATE TABLE #address_to_send
(
	idaddresskind int,
	idreg int,
	officename varchar(50),
	address varchar(100),
	location varchar(120),
	cap varchar(20),
	province varchar(2),
	nation varchar(65)
)
IF @ayear = 0
BEGIN
	SET @ayear='1900'
END
DECLARE @dateaddress datetime
SELECT @dateaddress = CONVERT(datetime, '31-12-'+ CONVERT(varchar(4),@ayear), 105)
INSERT INTO #expensetax
(
	idexp,
	idreg,
	taxdescription,
	expensedescription,
	taxablenet,
	employtax, 
	admintax, 
	--taxablegross,-- Imponibile Lordo
	grossamount,--Importo Lordo del Pagamento
	service,
	idser,
	npay
)
SELECT
	T.idexp,
	T.idreg,
	T.taxdescription,
	T.expensedescription,
	SUM(T.taxablenet),
	SUM(T.employtax),
	SUM(T.admintax), 
	--T.taxablegross,
	ISNULL(expensetotal.curramount,0),
	service.description,
	service.idser,
	payment.npay
FROM
	(SELECT
		SUM(ISNULL(E.taxablenet,0)) AS taxablenet,
		SUM(ISNULL(E.employtax,0)) AS employtax,
		SUM(ISNULL(E.admintax,0)) AS admintax,
		--isnull(E.taxablegross,0) as taxablegross,
		E.idexp,
		expense.idreg,
		E.description as taxdescription,
		expense.description as expensedescription,
		expenselast.idser,
		expenselast.kpay
	FROM expensetaxofficialview AS E
	JOIN expense 
		ON expense.idexp = E.idexp
	JOIN expenselast
		ON expenselast.idexp = expense.idexp 
	JOIN service
		ON service.idser = expenselast.idser
	WHERE expense.ymov = @ayear  
		AND (expense.idreg=@idreg OR @idreg=0)
		AND service.certificatekind = @certificatekind
		AND E.stop IS NULL
	GROUP BY expense.idreg,E.idexp,expenselast.idser,
		E.description,expense.description,
                expenselast.kpay) AS T
JOIN expensetotal
	ON T.idexp = expensetotal.idexp  
JOIN expenseyear
	ON T.idexp = expenseyear.idexp
JOIN service
	ON T.idser = service.idser  
JOIN payment 
	ON T.kpay = payment.kpay  
JOIN paymenttransmission
	ON payment.kpaymenttransmission = paymenttransmission.kpaymenttransmission  
WHERE (paymenttransmission.transmissiondate BETWEEN @start AND @stop)
	AND service.certificatekind = @certificatekind
	AND expensetotal.ayear = @ayear
	AND expenseyear.ayear = @ayear
GROUP BY T.idreg, T.idexp,
	T.taxdescription, expensetotal.curramount, service.description,
	service.idser,payment.npay,T.expensedescription--,T.taxablegross	
DECLARE  @appropriation tinyint
SELECT  @appropriation = expensephase FROM config WHERE ayear =@ayear
-- Fondo economale :
UPDATE #expensetax
		SET grossamount = grossamount + isnull(
			(SELECT SUM(pettycashoperation.amount)
		FROM pettycashoperation
		JOIN pettycashoperationcasualcontract
			ON  pettycashoperation.idpettycash = pettycashoperationcasualcontract.idpettycash
			AND pettycashoperation.yoperation  = pettycashoperationcasualcontract.yoperation
			AND pettycashoperation.noperation  = pettycashoperationcasualcontract.noperation
		JOIN casualcontract 
			ON  casualcontract.ycon  = pettycashoperationcasualcontract.ycon
			AND casualcontract.ncon  = pettycashoperationcasualcontract.ncon
		join expensecasualcontract
			ON expensecasualcontract.ycon = casualcontract.ycon
			and expensecasualcontract.ncon = casualcontract.ncon
		join expense
			ON expense.idexp = expensecasualcontract.idexp
		join expenselink 
			on expenselink.idparent = expense.idexp 
 		WHERE 
			expenselink.nlevel = @appropriation
			and casualcontract.idreg = #expensetax.idreg
			AND casualcontract.idser = #expensetax.idser
			AND expenselink.idchild = #expensetax.idexp
			AND (pettycashoperation.adate BETWEEN @start AND @stop) 
                        )
		,0)
UPDATE #expensetax
		SET grossamount =  grossamount + isnull(
			(SELECT SUM(ISNULL(pettycashoperation.amount, 0))
		FROM pettycashoperation
		JOIN pettycashoperationprofservice
			ON pettycashoperation.idpettycash = pettycashoperationprofservice.idpettycash
			AND pettycashoperation.yoperation = pettycashoperationprofservice.yoperation
			AND pettycashoperation.noperation = pettycashoperationprofservice.noperation
		JOIN profservice 
			ON  profservice.ycon  = pettycashoperationprofservice.ycon
			AND profservice.ncon  = pettycashoperationprofservice.ncon
		join expenseprofservice
			ON expenseprofservice.ycon = profservice.ycon
			and expenseprofservice.ncon = profservice.ncon
		join expense
			ON expense.idexp = expenseprofservice.idexp
		join expenselink 
			on expenselink.idparent = expense.idexp 
		WHERE expenselink.nlevel = @appropriation
			AND (profservice.idreg = #expensetax.idreg)
			AND profservice.idser = #expensetax.idser
			AND expenselink.idchild = #expensetax.idexp
			AND (pettycashoperation.adate BETWEEN @start AND @stop)
                        )
		,0)
		
UPDATE #expensetax
		SET grossamount =  grossamount + isnull(
			(SELECT SUM(ISNULL(pettycashoperation.amount, 0))
		FROM pettycashoperation
		JOIN pettycashoperationitineration
			ON pettycashoperation.idpettycash = pettycashoperationitineration.idpettycash
			AND pettycashoperation.yoperation = pettycashoperationitineration.yoperation
			AND pettycashoperation.noperation = pettycashoperationitineration.noperation
		JOIN itineration 
			ON itineration.iditineration  = pettycashoperationitineration.iditineration
		join expenseitineration
			ON expenseitineration.iditineration = itineration.iditineration
		join expense
			ON expense.idexp = expenseitineration.idexp
		join expenselink 
			on expenselink.idparent = expense.idexp 
		WHERE expenselink.nlevel = @appropriation
			AND (itineration.idreg = #expensetax.idreg)
			AND itineration.idser = #expensetax.idser
			AND expenselink.idchild = #expensetax.idexp
			AND (pettycashoperationitineration.movkind = 6)
			AND (pettycashoperation.adate BETWEEN @start AND @stop)	
                        )
			,0)
---------------------------------
    
DECLARE @codenostand varchar(20)
SET @codenostand = '07_SW_CER'
DECLARE @codestand varchar(20)
SET @codestand = '07_SW_DEF'
DECLARE @STAND int
SELECT @STAND = idaddress FROM address WHERE codeaddress = @codestand
DECLARE @NOSTAND int
SELECT @NOSTAND = idaddress FROM address WHERE codeaddress = @codenostand
-- Inizio calcolo indirizzi
INSERT INTO #address_to_send
(
	idaddresskind,
	idreg,
	address,
	location,
	cap,
	province
)
SELECT 
	idaddresskind,
	registryaddress.idreg, 
	address,
	ISNULL(geo_city.title + ' ','') + ISNULL(registryaddress.location,'') + 
	CASE 
		WHEN registryaddress.idnation IS NOT NULL THEN ' ' + geo_nation.title ELSE ''
	END,
	registryaddress.cap,
	geo_country.province
FROM registryaddress
LEFT OUTER JOIN geo_city
	ON geo_city.idcity = registryaddress.idcity
LEFT OUTER JOIN geo_country
	ON geo_city.idcountry = geo_country.idcountry
LEFT OUTER JOIN geo_nation
	ON registryaddress.idnation = geo_nation.idnation
WHERE (registryaddress.active <>'N' 
        AND (idreg IN (select idreg from  #expensetax))
	AND registryaddress.start = 
		(SELECT MAX(cdi.start) 
		FROM registryaddress cdi 
		WHERE cdi.idaddresskind = registryaddress.idaddresskind
			AND cdi.active <>'N' 
			AND cdi.start <= @dateaddress
			AND cdi.idreg = registryaddress.idreg)
)
DELETE #address_to_send
WHERE #address_to_send.idaddresskind <> @nostand
AND EXISTS(
	SELECT * FROM #address_to_send r2 
	WHERE #address_to_send.idreg = r2.idreg
		AND r2.idaddresskind = @NOSTAND
	)
DELETE #address_to_send
WHERE #address_to_send.idaddresskind NOT IN (@NOSTAND, @STAND)
AND EXISTS(
	SELECT * FROM #address_to_send r2 
	WHERE #address_to_send.idreg = r2.idreg
		AND r2.idaddresskind = @STAND
	)
DELETE #address_to_send
WHERE (
	SELECT COUNT(*) FROM #address_to_send r2 
	WHERE #address_to_send.idreg = r2.idreg
)>1
		
				
DECLARE @departmentname varchar(500)
SET  @departmentname  = ISNULL( (SELECT top 1 paramvalue from
    generalreportparameter where idparam='DenominazioneDipartimento' 
    and  (ISNULL(start, {d '1900-01-01'}) = {d '1900-01-01'} or year(start) <= @ayear) 
    and  (ISNULL(stop, {d '2079-06-06'}) = {d '2079-06-06'}  or year(stop) >= @ayear)
    order by ISNULL(stop, {d '2079-06-06'}) desc
    ),'Manca Cfg. Parametri Tutte le stampe')

SELECT
        @departmentname as departmentname,
	#expensetax.idexp,
	#expensetax.idreg,
	registry.title as registry,
	ISNULL(geo_city.title, '') + ' ' + ISNULL(registry.location,'') AS b_city,
	registry.birthdate,
	ISNULL(geo_country.province, '') AS b_province,
	ISNULL(geo_nation.title, 'ITALIA') AS b_nation,
	registry.cf, 
        registry.p_iva,
	#expensetax.taxdescription,
	expensedescription,	
	#expensetax.service,
	#expensetax.idser,
	#expensetax.npay,
	(#expensetax.taxablenet) as taxablenet,
	#expensetax.grossamount,--Importo Lordo del Pagamento
	(#expensetax.employtax) as employtax,
	(#expensetax.admintax) as admintax,
	--#expensetax.taxablegross, -- Imponibile Lordo        IL REPORT NON LO USA
	#address_to_send.address AS sent_address,
	#address_to_send.location AS sent_location,
	#address_to_send.cap AS sent_cap,
	#address_to_send.province AS sent_province,
	registry.foreigncf
FROM #expensetax
JOIN registry 
        ON #expensetax.idreg = registry.idreg
LEFT OUTER JOIN geo_city
	ON registry.idcity = geo_city.idcity  
LEFT OUTER JOIN geo_country
	ON geo_city.idcountry = geo_country.idcountry
LEFT OUTER JOIN geo_nation
	ON registry.idnation = geo_nation.idnation  
LEFT OUTER JOIN #address_to_send
	ON #address_to_send.idreg = #expensetax.idreg
order by registry.title
DROP TABLE #expensetax
DROP TABLE #address_to_send
END


GO

print '[rpt_4certificazioni] OK'

GO
if object_id('count_table_twofield') is not null
	drop procedure count_table_twofield
go


CREATE     procedure count_table_twofield (
@tablenames varchar(800),
@fieldname varchar(50),
@fieldname1 varchar(50),
@fieldvalue varchar(100),
@fieldvalue1 varchar(100),
@res int out
) as
BEGIN
declare @iddbdepartment varchar(50)
create table #mytable (nrows int)
select  @fieldvalue = REPLACE(@fieldvalue,'''','''''')
select  @fieldvalue1 = REPLACE(@fieldvalue1,'''','''''')
declare @cursore cursor
set @cursore = cursor for select  iddbdepartment from dbdepartment
open @cursore
fetch next from @cursore into @iddbdepartment
while @@fetch_status=0 begin
	declare @startpos int
	declare @nextcomma int
	declare @currtablename varchar(40)
	
	declare @currstmt nvarchar(1000)
	set @startpos=0
	set @nextcomma= charindex(',', @tablenames,@startpos)
	
	while (@startpos>=0) begin
		if (@nextcomma>0)
			SET @currtablename = SUBSTRING(@tablenames,@startpos,@nextcomma-@startpos)
		else
			SET @currtablename = SUBSTRING(@tablenames,@startpos,50)
		
		IF EXISTS(select * from sysobjects where id = object_id(@iddbdepartment+'.'+@currtablename) 
				and (OBJECTPROPERTY(id, N'IsUserTable') = 1 or OBJECTPROPERTY(id, N'IsView') = 1)
			and (uid=user_id(@iddbdepartment))) begin
			--print @iddbdepartment+'.'+@currtablename
			SET @currstmt= 'SELECT  COUNT(*) FROM '+ @iddbdepartment + '.' + @currtablename +
					' where '+@fieldname+' = '''+@fieldvalue+'''' +
					' and   '+@fieldname1+' = '''+@fieldvalue1+'''' 
			--print @currstmt
			insert into #mytable exec sp_executesql @currstmt
			if (select max(nrows) from #mytable)>0 break
			delete from #mytable 
		end
	
		if (@nextcomma=0) break;
		set @startpos=@nextcomma+1
		set @nextcomma= charindex(',', @tablenames,@startpos)
	end
	
	fetch next from @cursore into @iddbdepartment	
	if (select max(nrows) from #mytable)>0 break
		
end
--si occupa delle tabelle dbo
	set @startpos=0
	set @nextcomma= charindex(',', @tablenames,@startpos)
	set @iddbdepartment='dbo'	
	while (@startpos>=0) begin
		if (@nextcomma>0)
			SET @currtablename = SUBSTRING(@tablenames,@startpos,@nextcomma-@startpos)
		else
			SET @currtablename = SUBSTRING(@tablenames,@startpos,50)
		
		IF EXISTS(select * from sysobjects where id = object_id(@iddbdepartment+'.'+@currtablename) 
				and (OBJECTPROPERTY(id, N'IsUserTable') = 1 or OBJECTPROPERTY(id, N'IsView') = 1)
			and (uid=user_id(@iddbdepartment))) begin
			--print @iddbdepartment+'.'+@currtablename
			SET @currstmt= 'SELECT  COUNT(*) FROM '+ @iddbdepartment + '.' + @currtablename +
					' where '+@fieldname+' = '''+@fieldvalue+'''' +
					' and   '+@fieldname1+' = '''+@fieldvalue1+'''' 
			--print @currstmt
			insert into #mytable exec sp_executesql @currstmt
			if (select max(nrows) from #mytable)>0 break
			delete from #mytable 
		end
	
		if (@nextcomma=0) break;
		set @startpos=@nextcomma+1
		set @nextcomma= charindex(',', @tablenames,@startpos)
	end
	
SET @res= ISNULL((SELECT max(nrows) from #mytable), 0)
END



GO

print 'count_table_twofield OK'

GO
if object_id('[exp_riepilogo_ritenute_applicate_occasionali]') is not null
	drop PROCEDURE [exp_riepilogo_ritenute_applicate_occasionali]
go
CREATE      PROCEDURE [exp_riepilogo_ritenute_applicate_occasionali]
  @ayear                 int, 
  @registry              varchar(100), 
  @tax                   int, 
  @start              datetime,
  @stop                datetime
AS
  BEGIN
-- exec exp_riepilogo_ritenute_applicate_occasionali 2007,'%',null,{ts '2007-01-01 00:00:00'} , {ts '2007-12-31 00:00:00'}
DECLARE @departmentname varchar(150)
SET  @departmentname  = ISNULL( (SELECT paramvalue from
			 generalreportparameter where idparam='DenominazioneDipartimento' 
				and  (start is null or year(start) <= @ayear) 
				and (stop is null or year(stop) >= @ayear)
				),'Manca Cfg. Parametri Tutte le stampe')
DECLARE @idreg int
IF @registry = '%' 
BEGIN
	SET  @idreg = 0
END
ELSE
BEGIN
	SET  @idreg = (SELECT idreg FROM registry WHERE title like @registry)
END
DECLARE @codenostand varchar(20)
SET @codenostand = '07_SW_DOM'
DECLARE @codestand varchar(20)
SET @codestand = '07_SW_DEF'
DECLARE @STAND int
SELECT @STAND = idaddress FROM address WHERE codeaddress = @codestand
DECLARE @NOSTAND int
SELECT @NOSTAND = idaddress FROM address WHERE codeaddress = @codenostand

CREATE TABLE #casualcontract
(
	monthtaxpay int,
	taxablegross decimal(19,2),
	taxablenet decimal(19,2),
	employtax decimal(19,2),
	admintax decimal(19,2),
	abatements decimal(19,2),
	idexp int,
	taxcode int,
	idser int,
	idreg int,
	ycon int,
	ncon int,
	cc_start datetime,
	cc_stop datetime,
	idaddresskind int,
	start datetime,
	idcity int,
	idfiscaltaxregion varchar(5)
)
INSERT INTO #casualcontract
(
	monthtaxpay,
	taxablegross,
	taxablenet,
	employtax,
	admintax,
	abatements,
	idexp,
	taxcode,
	idser,
	idreg,
	ycon,
	ncon,
	cc_start,
	cc_stop,
	idaddresskind,
	start,
	idcity,
	idfiscaltaxregion
)
SELECT 	month(E.datetaxpay) as monthtaxpay,
	max(isnull(CCT.taxablegross,0)) as 'taxablegross',
	sum(isnull(CCT.taxablenet,0))   as 'taxablenet',
	sum(isnull(CCT.employtax,0))    as 'employtax',
	sum(isnull(CCT.admintax,0))     as 'admintax',
	sum(isnull(E.abatements,0))   as 'abatements',
	E.idexp,
	ISNULL(T.maintaxcode,T.taxcode) as taxcode,
	EL.idser,
        expense.idreg,
	CC.ycon ,
	CC.ncon ,
	CC.start as cc_start, 
	CC.stop as cc_stop,
	idaddresskind = @NOSTAND,
	start = (select max(registryaddress.start) from registryaddress 
		where registryaddress.idreg = expense.idreg
		and registryaddress.idaddresskind = @NOSTAND
		and year(registryaddress.start) <= @ayear
		AND registryaddress.active = 'S'),
	E.idcity,
	E.idfiscaltaxregion
FROM expensetaxview as E
JOIN expense 
	ON expense.idexp = E.idexp
JOIN expenselast EL
	ON E.idexp = EL.idexp
JOIN tax T
	ON T.taxcode = E.taxcode
join expenselink elk
	on elk.idchild = el.idexp	
JOIN expensecasualcontract EC
	ON EC.idexp = ELK.idparent
JOIN casualcontract CC
	ON CC.ycon = EC.ycon and  CC.ncon = EC.ncon
JOIN casualcontracttax CCT
	ON CCT.ycon  = CC.ycon 
	AND CCT.ncon  = CC.ncon  
	AND CCT.taxcode = T.taxcode
WHERE expense.ymov = @ayear  
	AND E.datetaxpay BETWEEN @start AND @stop 
	AND (@tax is null OR ISNULL(T.maintaxcode,T.taxcode) = @tax )
	AND (cc.idreg=@idreg OR @idreg=0)
GROUP BY expense.idreg, E.idexp, ISNULL(T.maintaxcode,T.taxcode), E.datetaxpay, EL.idser,CC.ycon,CC.ncon, 
	CC.start,CC.stop, E.idcity, E.idfiscaltaxregion
INSERT INTO #casualcontract
(
	monthtaxpay,
	taxablegross,
	taxablenet,
	employtax,
	admintax,
	abatements,
	idexp,
	taxcode,
	idser,
	idreg,
	ycon,
	ncon,
	cc_start,
	cc_stop,
	idaddresskind,
	start,
	idcity,
	idfiscaltaxregion
)
SELECT 	month(E.adate) as monthtaxpay,
	0,
	0,
	sum(isnull(E.employamount,0)),
	sum(isnull(E.adminamount,0)),
	0,
	E.idexp,
	ISNULL(T.maintaxcode,T.taxcode) as taxcode,
	EL.idser,
        expense.idreg,
	CC.ycon ,
	CC.ncon ,
	CC.start,
	CC.stop,
	idaddresskind = @NOSTAND,
	start = (select max(registryaddress.start) from registryaddress 
		where registryaddress.idreg = expense.idreg
		and registryaddress.idaddresskind = @NOSTAND
		and year(registryaddress.start) <= @ayear
		AND registryaddress.active = 'S'),
	E.idcity,
	E.idfiscaltaxregion
FROM expensetaxcorrigeview as E
JOIN expense 
	ON expense.idexp = E.idexp
JOIN expenselast EL
	ON E.idexp = EL.idexp
JOIN tax T
	ON T.taxcode = E.taxcode
join expenselink elk
	on elk.idchild = el.idexp	
JOIN expensecasualcontract EC
	ON EC.idexp = ELK.idparent
JOIN casualcontract CC
	ON CC.ycon = EC.ycon and  CC.ncon = EC.ncon
JOIN casualcontracttax CCT
	ON CCT.ycon  = CC.ycon 
	AND CCT.ncon  = CC.ncon  
	AND CCT.taxcode = T.taxcode
WHERE expense.ymov = @ayear  
	AND E.adate BETWEEN @start AND @stop 
	AND (@tax is null OR ISNULL(T.maintaxcode,T.taxcode) = @tax )
	AND (cc.idreg=@idreg OR @idreg=0)
GROUP BY expense.idreg, E.idexp, ISNULL(T.maintaxcode,T.taxcode), E.adate, EL.idser,CC.ycon,CC.ncon, 
	CC.start,CC.stop, E.idcity, E.idfiscaltaxregion
update #casualcontract set
	idaddresskind = @STAND,
	start = (select max(registryaddress.start)
from registryaddress 
where registryaddress.idreg = #casualcontract.idreg
	and registryaddress.idaddresskind = @STAND
	and year(registryaddress.start) <= @ayear
	AND registryaddress.active = 'S')
where start is null
update #casualcontract set
	start = (select max(registryaddress.start)
from registryaddress 
where registryaddress.idreg = #casualcontract.idreg
	and year(registryaddress.start) <= @ayear
	AND registryaddress.active = 'S')
where start is null
update #casualcontract set
	idaddresskind = registryaddress.idaddresskind
from registryaddress 
where registryaddress.idreg = #casualcontract.idreg
	and registryaddress.start = #casualcontract.start
	AND registryaddress.active = 'S'
	and #casualcontract.idaddresskind is null
SELECT
	monthtaxpay as 'Mese', 
	@departmentname 'Dipartimento',
	registry.cf 'Codice Fiscale',
	registry.title as 'Percipiente',
	service.description as 'Prestazione',
	#casualcontract.cc_start as 'Inizio Prestazione',
	#casualcontract.cc_stop as 'Fine Prestazione',
	tax.description as 'Ritenuta',
	SUM(#casualcontract.taxablegross) as 'Imponibile Lordo' ,
	SUM(#casualcontract.taxablenet) as 'Imponibile Netto' ,
	SUM(#casualcontract.employtax) as  'Rit/Dipendente',
	SUM(#casualcontract.admintax) as 'Rit/Amministrazione',
	SUM(#casualcontract.abatements) as 'Detrazioni applicate',
	geo_city.title as 'Comune',
	geo_region.title as 'Regione',
	gf.title as 'Comune Fiscale',
	fiscaltaxregion.title as 'Regione Fiscale',
	otherinsurance.description as 'Altra forma Ass.',
	emenscontractkind.description as 'Tipo Rapporto'
FROM #casualcontract
join registry 
	on #casualcontract.idreg = registry.idreg 
JOIN casualcontractyear 
	ON #casualcontract.ycon = casualcontractyear.ycon
	AND #casualcontract.ncon = casualcontractyear.ncon
	AND casualcontractyear.ayear= @ayear
left outer join tax 
	on #casualcontract.taxcode = tax.taxcode
left outer join service 
	on #casualcontract.idser = service.idser
left outer join registryaddress 
	on registryaddress.idaddresskind=#casualcontract.idaddresskind
	and registryaddress.idreg=#casualcontract.idreg
	and registryaddress.start=#casualcontract.start
left outer join geo_city 
	on geo_city.idcity=registryaddress.idcity
left outer join geo_country 
	on geo_country.idcountry=geo_city.idcountry
left outer join geo_region
	on geo_region.idregion=geo_country.idregion
left outer join geo_city gf
	on geo_city.idcity=#casualcontract.idcity
left outer join fiscaltaxregion 
	on fiscaltaxregion.idregion=#casualcontract.idfiscaltaxregion
LEFT OUTER JOIN otherinsurance 
	ON otherinsurance.idotherinsurance = casualcontractyear.idotherinsurance
	AND otherinsurance.ayear = casualcontractyear.ayear
LEFT OUTER JOIN inpsactivity 
	ON inpsactivity.activitycode = casualcontractyear.activitycode
	AND inpsactivity.ayear = casualcontractyear.ayear
LEFT OUTER JOIN emenscontractkind 
	ON emenscontractkind.idemenscontractkind = casualcontractyear.idemenscontractkind
	AND emenscontractkind.ayear = casualcontractyear.ayear
WHERE (registry.idreg=@idreg OR @idreg=0)
GROUP BY cf, registry.title, tax.description, monthtaxpay, service.description, geo_city.title, geo_region.title,
	gf.title, fiscaltaxregion.title,
	#casualcontract.cc_start,#casualcontract.cc_stop,otherinsurance.description,emenscontractkind.description
ORDER BY tax.description, registry.title

END

GO

print '[exp_riepilogo_ritenute_applicate_occasionali] OK'

