if object_id('[trigger_u_accountvardetail]') is not null
	drop TRIGGER [trigger_u_accountvardetail]
go

CREATE                 TRIGGER [trigger_u_accountvardetail] ON [accountvardetail] FOR UPDATE
AS BEGIN
IF UPDATE(amount)
BEGIN
	DECLARE @yvar int
	DECLARE @nvar int
	DECLARE @idsor int
	DECLARE @idacc varchar(38)
	DECLARE @newamount decimal(19,2)
	DECLARE @oldamount decimal(19,2)
	DECLARE @differenceamount decimal(19,2)
	SELECT 
		@yvar = yvar,
		@nvar = nvar,
		@idsor = idsor,
		@idacc = idacc,
		@newamount = amount
	FROM inserted
	SELECT @oldamount = -amount
	FROM deleted
	SET @differenceamount = @oldamount + @newamount	
	EXECUTE trg_upd_sortingtotal 
	@idsor,
	@idacc,
	'previsionvariation', 
	@differenceamount
END
END


