if object_id('[esporta_buoni_ratifiche_successive]') is not null
	drop PROCEDURE [esporta_buoni_ratifiche_successive]
go

CREATE         PROCEDURE  [esporta_buoni_ratifiche_successive]
	@start smalldatetime,
	@stop  smalldatetime
AS BEGIN
-- exec esporta_buoni_ratifiche_successive {ts '2008-01-01 00:00:00'},{ts '2008-08-20 00:00:00'}
	SELECT
		assetloadkind.description 'Tipo Buono',
		assetload.yassetload 'Eserc.Buono',
		assetload.nassetload 'Num.Buono',
		assetload.ratificationdate as 'Data Ratifica'		
	FROM assetload 
	JOIN assetloadkind 
		ON assetloadkind.idassetloadkind = assetload.idassetloadkind
	WHERE	( YEAR(assetload.ratificationdate) > assetload.yassetload )
		AND assetload.adate between @start and @stop		
	UNION 
	SELECT
		assetunloadkind.description 'Tipo Buono',
		assetunload.yassetunload 'Eserc.Buono',
		assetunload.nassetunload 'Num.Buono',
		assetunload.ratificationdate as 'Data Ratifica'		
	FROM assetunload 
	JOIN assetunloadkind 
		ON assetunloadkind.idassetunloadkind = assetunload.idassetunloadkind
	WHERE	( YEAR(assetunload.ratificationdate) > assetunload.yassetunload )
		AND assetunload.adate between @start and @stop		
END


GO

print '[esporta_buoni_ratifiche_successive] OK'

