go

CREATE                TRIGGER [trigger_u_accountyear] ON [accountyear] FOR UPDATE
AS BEGIN
	DECLARE @ayear int
	DECLARE @newamount decimal(19,2)
	DECLARE @oldamount decimal(19,2)
	DECLARE @updatefc char(1)
	DECLARE @idsor int
	DECLARE @idacc varchar(38)
	DECLARE	@prevision decimal(19,2)
	DECLARE	@previousprevision decimal(19,2)
	SELECT @updatefc = 'N' 
	SELECT @ayear = ayear, @idacc = idacc, @idsor = idsor FROM inserted
	SELECT
	@prevision = -ISNULL(prevision,0),
	@previousprevision = -ISNULL(previousprevision,0)
	FROM deleted
	SELECT
	@prevision = @prevision + ISNULL(prevision,0), 
	@previousprevision = @previousprevision + ISNULL(previousprevision,0)
	FROM inserted
	-- Se mi trovo sul minimo livello operativo devo propagare la modifica fino al primo livello
	-- altrimenti devo modificare solamente il livello modificato
	IF (LEN(@idacc)-2)/4 = CONVERT(int,(SELECT MIN(nlevel) FROM accountlevel WHERE flagusable='S' AND ayear = @ayear)) 
	BEGIN
		EXEC trg_upd_sortingextended @idsor, @idacc, @previousprevision, @prevision
	END
	ELSE
	BEGIN
		UPDATE sortingtotal SET
		currentprev = @prevision + ISNULL(currentprev,0), 
		previousprev = @previousprevision + ISNULL(previousprev,0)
		WHERE idsor = @idsor AND idacc = @idacc
	END
END


GO

print '[trigger_u_accountyear] OK'

