if object_id('[exp_unifiedf24ep_ritenute]') is not null
	drop PROCEDURE [exp_unifiedf24ep_ritenute]
go

CREATE    PROCEDURE [exp_unifiedf24ep_ritenute]
	  @ayear int, 
	  @idunifiedf24ep int,
	  @tax int,
	  @departmentname varchar(50),
	  @showdepartment char(1)
AS
BEGIN
CREATE TABLE #unifiedtax
(
	department 	varchar(150),
	idunifiedtax 	int,
	fiscaltaxcode 	varchar(20),
	taxref  	varchar(20),
	description  	varchar(50),
	employtax 	decimal(19,2),
	admintax  	decimal(19,2),
	total		decimal(19,2),
	payed_city	varchar(65),
	payed_country	varchar(20),
	payed_fiscaltaxregion varchar(50)
)
	
	INSERT INTO #unifiedtax
	(
		department,
		idunifiedtax,
		fiscaltaxcode,
		taxref,
		description,
		employtax,
		admintax,
		total,
		payed_city,
		payed_country,
		payed_fiscaltaxregion
	)
	SELECT 
		department,
		idunifiedtax,
		fiscaltaxcode,
		taxref,
		description,
		employtax,
		admintax,
		ISNULL(employtax,0) + ISNULL(admintax,0),
		payed_city,
		payed_country,
		payed_fiscaltaxregion
	FROM  unifiedtaxview 
	WHERE ayear = @ayear 
	AND   idunifiedf24ep = @idunifiedf24ep
	AND   (@tax is null OR unifiedtaxview.taxcode = @tax )
        AND  (unifiedtaxview.department = @departmentname  OR @departmentname is null) 
	INSERT INTO #unifiedtax
	(
		department,
		idunifiedtax,
		fiscaltaxcode,
		taxref,
		description,
		employtax,
		admintax,
		total,
		payed_city,
		payed_country,
		payed_fiscaltaxregion	
	)
	SELECT 
		department,
		idunifiedtaxcorrige,
		fiscaltaxcode,
		taxref,
		description,
		employamount,
		adminamount,
		ISNULL(employamount,0) + ISNULL(adminamount,0),
		payed_city,
		payed_country,
		payed_fiscaltaxregion
	FROM  unifiedtaxcorrigeview 
	WHERE ayear = @ayear 
	AND   idunifiedf24ep = @idunifiedf24ep
	AND   (@tax is null OR unifiedtaxcorrigeview.taxcode = @tax )
        AND  (unifiedtaxcorrigeview.department = @departmentname  OR @departmentname is null) 
	
	IF (ISNULL(@showdepartment,'N') = 'S')
	BEGIN
		SELECT 
			department AS 'Dipartimento',
			fiscaltaxcode AS 'Codice Tributo',
			taxref AS 'Codice ritenuta',
			description AS 'Ritenuta',
			payed_city AS 'Comune',
			payed_country AS 'Prov.',
			payed_fiscaltaxregion as 'Regione Fiscale',
			ISNULL(SUM(employtax),0) AS 'C/Percip.',
			ISNULL(SUM(admintax),0) AS 'C/Ammin.',
			ISNULL(SUM(employtax),0) + ISNULL(SUM(admintax),0) AS 'Totale'
		FROM  #unifiedtax
		GROUP BY department, taxref,fiscaltaxcode, description, 
			payed_city, payed_fiscaltaxregion, payed_country
		ORDER BY department,fiscaltaxcode,taxref
	END
	ELSE
	BEGIN
		SELECT 
			fiscaltaxcode AS 'Codice Tributo',
			taxref AS 'Codice ritenuta',
			description AS 'Ritenuta',
			payed_city AS 'Comune',
			payed_country AS 'Prov.',
			payed_fiscaltaxregion as 'Regione Fiscale',
			ISNULL(SUM(employtax),0) AS 'C/Percip.',
			ISNULL(SUM(admintax),0) AS 'C/Ammin.',
			ISNULL(SUM(employtax),0) + ISNULL(SUM(admintax),0) AS 'Totale'
		FROM  #unifiedtax
		GROUP BY taxref,fiscaltaxcode, description, 
			 payed_city, payed_fiscaltaxregion, payed_country
		ORDER BY fiscaltaxcode,taxref
	END
END

GO

print '[exp_unifiedf24ep_ritenute] OK'

GO
if object_id('exp_interscambio_csa_dipendentiassimilato_dati') is not null
	drop PROCEDURE exp_interscambio_csa_dipendentiassimilato_dati
go

CREATE   PROCEDURE exp_interscambio_csa_dipendentiassimilato_dati
 (
	@datagenerazione datetime,
	@ayear int,
	@ateneo varchar(5),
--	@tiporecord varchar(2) ,
	@tipoCompenso char(1), -- Assume valori T = Conto Terzi, C = CO.CO.CO. , B = Borse di studio
	@start datetime,
	@stop datetime
)
AS 
/*
exec exp_interscambio_csa_dipendentiassimilato_dati {ts '2010-12-31 01:02:03'} ,2010, '70136', 'C', {ts '2010-01-01 01:02:03'} , {ts '2010-12-31 01:02:03'} 
 */
BEGIN
DECLARE @annoredditi int
SET @annoredditi = @ayear
--------------------------------------------------------------------------------------- Interroghiamo i singoli dipartimenti ----------------------------------------------------------------
CREATE TABLE #Compensi(
		departmentname varchar(500),
		iddb_idexp varchar(60),-- iddb(50) + idexp(10)
		idregistrylegalstatus int,
		voce8000 varchar(4),
		importo decimal(19,2),
		idreg int,
		ymov smallint,
		nmov int,
		paymentdate smalldatetime
		)
	declare @iddbdepartment varchar(50)
	declare @crsdepartment cursor
	set 	@crsdepartment = cursor for select  iddbdepartment from dbdepartment
			where (start is null or start <= @ayear ) AND ( stop is null or stop >= @ayear)
	open 	@crsdepartment
	fetch next from @crsdepartment into @iddbdepartment
	while @@fetch_status=0 begin
		declare @dip_nomesp varchar(300)
		set @dip_nomesp = @iddbdepartment + '.exp_interscambio_csa_dipendentiassimilato_single'
		INSERT INTO #Compensi(
				idreg,
				departmentname,
				iddb_idexp,
				idregistrylegalstatus,
				voce8000,
				importo,
				ymov,
				nmov,
				paymentdate
		)
		exec @dip_nomesp @datagenerazione, @ayear, @ateneo, @tipoCompenso, @start, @stop
		fetch next from @crsdepartment into @iddbdepartment
	
	END
SELECT 
	C.departmentname as 'Dip.',
	R.title as Anagrafica,
	R.idreg as 'Cod.Anagr.',
	RLS.csa_role as Ruolo,
	V.voce as voce,
	V.description as Descrizione,
	C.Importo,
	C.ymov as'Eserc.',
	C.nmov as 'N.Mov.',
	SUBSTRING('00',1,2 - DATALENGTH(CONVERT(varchar(2),DAY(C.paymentdate)))) +
	CONVERT(varchar(2),DAY(C.paymentdate)) + '/'+
	SUBSTRING('00',1,2 - DATALENGTH(CONVERT(varchar(2),MONTH(C.paymentdate)))) +
	CONVERT(varchar(2),MONTH(C.paymentdate))+'/'+
	+CONVERT(varchar(4),YEAR(C.paymentdate))
	 as'Data Pag.'
FROM #Compensi C
JOIN registry R
	ON R.idreg = C.idreg
JOIN voce8000 V
	ON V.voce = C.voce8000
JOIN registrylegalstatus RLS
	ON C.idreg = RLS.idreg
	AND C.idregistrylegalstatus = RLS.idregistrylegalstatus
WHERE R.extmatricula IS NOT NULL
		AND RLS.csa_role IS NOT NULL
		AND RLS.csa_compartment IS NOT NULL
ORDER BY R.title, C.nmov, C.voce8000
END


GO

print 'exp_interscambio_csa_dipendentiassimilato_dati OK'

GO
if object_id('rpt_corrispettivi') is not null
	drop PROCEDURE rpt_corrispettivi
go

CREATE       PROCEDURE rpt_corrispettivi
(
	@year int,
	@month int,	
	@idivaregisterkind int
)
AS BEGIN
-- exec rpt_corrispettivi 2009, 9, 1
-- exec rpt_corrispettivi 2009, 9, 5
CREATE TABLE #sales
(
	codeinvkind varchar(20),idinvkind int,	
	codeivaregisterkind varchar(20),	
	yinv int,
	reg_day int,
	reg_month varchar(20),
	taxable decimal(19,2),
	description  varchar(300),
	tax_with_rate1 decimal(19,2),
	tax_with_rate2 decimal(19,2),
	tax_with_rate3 decimal(19,2),
	tax_with_rate4 decimal(19,2),
	zerorated decimal(19,2),
	flagintracom char(1),
	registerclass char(1),	--tipo registro A/V
	kind char(1),			--tipo fattura A/V
	flagvariation char(1)
)
DECLARE @paramvalue1 varchar(10)
DECLARE @rate1 decimal(19,3)
SELECT @paramvalue1 = paramvalue
FROM reportadditionalparam  
WHERE reportname = 'registrocorrispettivi' AND paramname = 'Aliquota1'
IF ( ISNUMERIC(@paramvalue1) = 1 ) 
BEGIN
	SET @rate1 = CONVERT(decimal(19,3),@paramvalue1)
END
DECLARE @rate2 decimal(19,3)
DECLARE @paramvalue2 varchar(10)
SELECT @paramvalue2 = paramvalue
FROM reportadditionalparam  
WHERE reportname = 'registrocorrispettivi' AND paramname = 'Aliquota2'
IF ( ISNUMERIC(@paramvalue2) = 1 )
BEGIN
	SET @rate2 = CONVERT(decimal(19,3),@paramvalue2)
END
DECLARE @rate3 decimal(19,3)
DECLARE @paramvalue3 varchar(10)
SELECT @paramvalue3 = paramvalue
FROM reportadditionalparam  
WHERE reportname = 'registrocorrispettivi' AND paramname = 'Aliquota3'

IF ( ISNUMERIC(@paramvalue3) = 1 )
BEGIN
	SET @rate3 = CONVERT(decimal(19,3),@paramvalue3)
END
DECLARE @rate4 decimal(19,3)
DECLARE @paramvalue4 varchar(10)
SELECT @paramvalue4 = paramvalue
FROM reportadditionalparam  
WHERE reportname = 'registrocorrispettivi' AND paramname = 'Aliquota4'
IF ( ISNUMERIC(@paramvalue4) = 1 )
BEGIN
	SET @rate4 = CONVERT(decimal(19,3),@paramvalue4)
END
DECLARE @rate5 decimal(19,3)
SELECT  @rate5 = CONVERT(decimal(19,3),0)
DECLARE @monthname varchar(20)
SELECT  @monthname = title FROM monthname WHERE code = @month
-- Dati relativi ai mesi precedenti
INSERT INTO #sales
(
	codeinvkind,			
	codeivaregisterkind,	
	yinv,
	reg_month,
	taxable,
	flagintracom,
	registerclass,	--tipo registro A/V
	kind, 			--tipo fattura A/V
	flagvariation
)
SELECT
	'RIPORTO',
	'RIPORTO',
	@year,
	@monthname,
	CONVERT(decimal(19,2),
		ISNULL(SUM(
			ROUND(invoicedetail.taxable * invoicedetail.npackage * 
				CONVERT(decimal(19,6),ISNULL(invoice.exchangerate,1)) *
					(1 - CONVERT(decimal(19,6),ISNULL(invoicedetail.discount, 0))),2
			)
		),0)
	)
	+
	ISNULL(SUM(invoicedetail.tax),0),
	invoice.flagintracom,
	ivaregisterkind.registerclass,		--tipo registro (A/V)
	CASE WHEN (invoicekind.flag & 1)=0 THEN 'A'
		 ELSE 'V'
	END ,--kind		--tipo fattura (A/V)
	CASE
		WHEN (invoicekind.flag & 4) = 0 THEN 'N'
		ELSE 'S'
	END --flagvariation	
FROM ivaregister
JOIN invoice
	ON invoice.idinvkind = ivaregister.idinvkind
	AND invoice.yinv = ivaregister.yinv
	AND invoice.ninv = ivaregister.ninv
JOIN invoicekind
	ON invoicekind.idinvkind = invoice.idinvkind
JOIN invoicedetail
	ON invoicedetail.idinvkind = invoice.idinvkind
	AND invoicedetail.yinv = invoice.yinv
	AND invoicedetail.ninv = invoice.ninv
JOIN ivaregisterkind
	ON ivaregisterkind.idivaregisterkind = ivaregister.idivaregisterkind
WHERE ivaregister.idivaregisterkind = @idivaregisterkind
	AND DATEPART(year,invoice.adate) = @year
	AND DATEPART(month,invoice.adate) < @month
GROUP BY ivaregister.idivaregisterkind, ivaregister.yinv,
		invoice.flagintracom,ivaregisterkind.registerclass, (invoicekind.flag & 1), (invoicekind.flag & 4)
-- Stessa INSERT precedente ma interroga SOLO le Autofatture senza dettagli
UNION 
SELECT
	'RIPORTO',
	'RIPORTO',
	@year,
	@monthname,
	CONVERT(decimal(19,2),
		ISNULL(SUM(
			ROUND(invoicedetail.taxable * invoicedetail.npackage * 
				CONVERT(decimal(19,6),ISNULL(invoice.exchangerate,1)) *
					(1 - CONVERT(decimal(19,6),ISNULL(invoicedetail.discount, 0))),2
			)
		),0)
	)
	+
	ISNULL(SUM(invoicedetail.tax),0),
	M.flagintracom,
	ivaregisterkind.registerclass,		--tipo registro (A/V)
	CASE WHEN (invoicekind.flag & 1)=0 THEN 'A'
		 ELSE 'V'
	END ,--kind		--tipo fattura (A/V)
	CASE
		WHEN (invoicekind.flag & 4) = 0 THEN 'N'
		ELSE 'S'
	END --flagvariation	
FROM invoice M --> fattura Madre
JOIN invoice 
	ON invoice.idinvkind_real = M.idinvkind
	AND invoice.yinv_real = M.yinv
	AND invoice.ninv_real = M.ninv
join invoicedetail 
	ON invoicedetail.idinvkind = M.idinvkind
	AND invoicedetail.yinv = M.yinv
	AND invoicedetail.ninv = M.ninv
JOIN ivaregister
	ON invoice.idinvkind = ivaregister.idinvkind
	AND invoice.yinv = ivaregister.yinv
	AND invoice.ninv = ivaregister.ninv
JOIN invoicekind
	ON invoicekind.idinvkind = invoice.idinvkind
JOIN ivaregisterkind
	ON ivaregisterkind.idivaregisterkind = ivaregister.idivaregisterkind
WHERE ivaregister.idivaregisterkind = @idivaregisterkind
	AND DATEPART(year,M.adate) = @year
	AND DATEPART(month,M.adate) < @month
GROUP BY ivaregister.idivaregisterkind, ivaregister.yinv,
		M.flagintracom, ivaregisterkind.registerclass, (invoicekind.flag & 1), (invoicekind.flag & 4)
-- Dati del mese corrente
INSERT INTO #sales
(
	codeinvkind,
	idinvkind,
	codeivaregisterkind,	
	yinv,
	reg_day,
	reg_month,
	flagintracom,
	registerclass,	--tipo registro A/V
	kind, 			--tipo fattura A/V
	flagvariation
)
SELECT
	invoicekind.codeinvkind,
	ivaregister.idinvkind,
	ivaregisterkind.codeivaregisterkind,	
	ivaregister.yinv,
	datepart(dd,invoice.adate),
	@monthname,
	invoice.flagintracom,
	ivaregisterkind.registerclass,		--tipo registro (A/V)
	CASE WHEN (invoicekind.flag & 1)=0 THEN 'A'
		 ELSE 'V'
	END ,--kind		--tipo fattura (A/V)
	CASE
		WHEN (invoicekind.flag & 4) = 0 THEN 'N'
		ELSE 'S'
	END --flagvariation	
FROM ivaregister
JOIN invoice
	ON invoice.idinvkind = ivaregister.idinvkind
	AND invoice.yinv = ivaregister.yinv
	AND invoice.ninv = ivaregister.ninv
JOIN invoicekind
	ON invoicekind.idinvkind = ivaregister.idinvkind
JOIN ivaregisterkind
	ON ivaregisterkind.idivaregisterkind = ivaregister.idivaregisterkind
WHERE ivaregister.idivaregisterkind = @idivaregisterkind
	AND DATEPART(year,invoice.adate) = @year
	AND DATEPART(month,invoice.adate) = @month
GROUP BY 
	invoicekind.codeinvkind,ivaregister.idinvkind,
	ivaregisterkind.codeivaregisterkind,	
	ivaregister.yinv,
	ivaregisterkind.description,
	DATEPART(dd,invoice.adate),
	invoice.flagintracom,ivaregisterkind.registerclass, (invoicekind.flag & 1), (invoicekind.flag & 4)

UPDATE #sales
SET tax_with_rate1 =
ISNULL(
	(SELECT ISNULL(SUM(invoicedetail.tax),0)
	FROM invoicedetail
	JOIN ivakind
		ON ivakind.idivakind = invoicedetail.idivakind
	JOIN invoice
		ON invoice.idinvkind = invoicedetail.idinvkind
		AND invoice.yinv = invoicedetail.yinv
		AND invoice.ninv = invoicedetail.ninv
	JOIN ivaregister
		ON invoice.idinvkind = ivaregister.idinvkind
		AND invoice.yinv = ivaregister.yinv
		AND invoice.ninv = ivaregister.ninv
	JOIN invoicekind
		ON invoicekind.idinvkind = invoice.idinvkind
	JOIN ivaregisterkind
		ON ivaregisterkind.idivaregisterkind = ivaregister.idivaregisterkind
	WHERE DATEPART(year,invoice.adate) = @year
		AND DATEPART(month,invoice.adate) = @month
		AND ROUND(ivakind.rate,3) = @rate1
		AND DATEPART(dd,invoice.adate) = #sales.reg_day
		AND invoicedetail.idinvkind = #sales.idinvkind
		AND invoice.flagintracom = #sales.flagintracom
		AND ivaregisterkind.registerclass = #sales.registerclass
		AND ((invoicekind.flag & 1)=0  AND  #sales.kind = 'A'
			OR 
			(invoicekind.flag & 1)<> 0  AND  #sales.kind = 'V'
			)
		AND ((invoicekind.flag & 4)=0  AND  #sales.flagvariation = 'N'
			OR 
			(invoicekind.flag & 4)<> 0  AND  #sales.flagvariation = 'S'
			)
)
,0)
+
-- Aggiungiamo lo stesso valore leggendolo dalle Autofatture senza dettagli
ISNULL(
	(SELECT ISNULL(SUM(invoicedetail.tax),0)
	FROM invoice M --> fattura Madre
	JOIN invoice
		ON invoice.idinvkind_real = M.idinvkind
		AND invoice.yinv_real = M.yinv
		AND invoice.ninv_real = M.ninv
	join invoicedetail 
		ON invoicedetail.idinvkind = M.idinvkind
		AND invoicedetail.yinv = M.yinv
		AND invoicedetail.ninv = M.ninv
	JOIN ivakind
		ON ivakind.idivakind = invoicedetail.idivakind
	JOIN ivaregister
		ON invoice.idinvkind = ivaregister.idinvkind
		AND invoice.yinv = ivaregister.yinv
		AND invoice.ninv = ivaregister.ninv
	JOIN invoicekind
		ON invoicekind.idinvkind = invoice.idinvkind
	JOIN ivaregisterkind
		ON ivaregisterkind.idivaregisterkind = ivaregister.idivaregisterkind
	WHERE DATEPART(year,invoice.adate) = @year
		AND DATEPART(month,invoice.adate) = @month
		AND ROUND(ivakind.rate,3) = @rate1
		AND DATEPART(dd,invoice.adate) = #sales.reg_day
		--AND invoicedetail.idinvkind = #sales.idinvkind
		AND invoice.idinvkind = #sales.idinvkind
		AND invoice.flagintracom = #sales.flagintracom
		AND ivaregisterkind.registerclass = #sales.registerclass
