if object_id('exp_impegninonfinanziati_parzfinanziati') is not null
	drop PROCEDURE exp_impegninonfinanziati_parzfinanziati
go

CREATE PROCEDURE exp_impegninonfinanziati_parzfinanziati
@ayear int,
@ymov int -- Eserc. competenza
AS BEGIN

DECLARE @finphase tinyint
SELECT @finphase = appropriationphasecode
FROM config
WHERE ayear = @ayear
IF @finphase IS NULL
BEGIN
	SELECT @finphase = expensefinphase FROM uniconfig
END
	
SELECT 
	E.ymov as 'Eser.Mov.',
	E.nmov as 'N.mov.',
	E.nphase as'Fase',
	isnull(ET.curramount,0) as 'Importo Movimento',
	(ISNULL((SELECT SUM(W.amount) FROM underwritingappropriation W WHERE W.idexp= E.idexp),0)
		+
	ISNULL ((SELECT SUM(EV.amount) FROM expensevar EV WHERE EV.idexp = E.idexp and	EV.idunderwriting is not null),0)
	)
		as 'Importo Finanziato'
FROM expense E
JOIN expenseyear EY
	ON EY.idexp = E.idexp
JOIN expensetotal ET
	ON ET.idexp = E.idexp
	AND ET.ayear = EY.ayear
JOIN upb U
	ON EY.idupb = U.idupb	
WHERE EY.ayear = @ayear
	AND (@ymov is not null and E.ymov = @ymov or @ymov is null )
	AND isnull(U.assured,'N') = 'N'
	AND E.nphase = @finphase
	AND 
		(ISNULL((SELECT SUM(W.amount) FROM underwritingappropriation W WHERE W.idexp= E.idexp),0)
			+
		ISNULL ((SELECT SUM(EV.amount) FROM expensevar EV WHERE EV.idexp = E.idexp and	EV.idunderwriting is not null),0)
		)
	<> ISNULL(ET.curramount,0)
ORDER BY E.ymov, E.nmov

END

GO

print 'exp_impegninonfinanziati_parzfinanziati OK'

