if object_id('rpt_performed') is not null
	drop PROCEDURE rpt_performed
go

CREATE    PROCEDURE rpt_performed
	@ydoc		int,
	@kind		char(1),
	@performed	char(1),
	@start          smalldatetime,
  	@stop           smalldatetime 
AS
/* Versione 1.0.1 del 17/10/2007 ultima modifica: MARIA */
BEGIN
CREATE TABLE #performed
(
	ydoc int, 	
	ndoc int,	
	stamphandling varchar(50),
	registry varchar(100),
	codefin	varchar(50),
	fin varchar(150),
	manager varchar(150),
	ytransmission int, 	
	ntransmission int,	
	transmissiondate smalldatetime,	
	adate smalldatetime,	
	printdate smalldatetime, 	
	annulmentdate smalldatetime,	
	transactiondate smalldatetime, 
	total decimal(19,2),
	performed decimal(19,2),
	notperformed decimal(19,2),
	yban int,
	nban int,
	banktransaction decimal(19,2),
	communicatedperformed decimal(19,2),
	communicatednotperformed decimal(19,2),
	notcommunicated decimal(19,2)
)
IF UPPER(@kind) = 'D'
BEGIN
	INSERT INTO #performed
	(
		yban,
		nban,
		ydoc,	
		ndoc,
		stamphandling,
		registry,
		codefin,
		fin,
		manager,
		ytransmission,
		ntransmission,
		transmissiondate,
		adate,
		printdate,
		annulmentdate,
		transactiondate,
		total,
		performed,
		notperformed,
		banktransaction,
		communicatedperformed,
		communicatednotperformed,
		notcommunicated
	) 
	SELECT
		banktransaction.yban,
		banktransaction.nban,
		payment.ypay, 
		payment.npay,
		stamphandling.description ,
		registry.title , 
		fin.codefin,
		fin.title,
		manager.title,
		paymenttransmission.ypaymenttransmission, 
		paymenttransmission.npaymenttransmission,
		paymenttransmission.transmissiondate,
		payment.adate,
		payment.printdate, 
		payment.annulmentdate,
		banktransaction.transactiondate,
		-- Total
		ISNULL(
			(SELECT SUM(curramount)
			FROM expensetotal I 
			JOIN expense S
				ON S.idexp = I.idexp 
			JOIN expenselast ESL
				ON ESL.idexp = S.idexp 
			WHERE S.ymov = payment.ypay
				AND ESL.kpay = payment.kpay)
		,0),
		-- Performed
		ISNULL(
			(SELECT SUM(P.amount)
			FROM banktransaction P
			WHERE P.kpay = payment.kpay
				AND P.transactiondate BETWEEN @start AND @stop)
		,0),
		-- Not performed
		ISNULL(
			(SELECT SUM(curramount)
			FROM expensetotal I
			JOIN expense S
				ON I.idexp=S.idexp
			JOIN expenselast ESL
				ON ESL.idexp = S.idexp 
			WHERE S.ymov=payment.ypay
				AND ESL.kpay = payment.kpay)
		,0)
		-ISNULL(
			(SELECT SUM(P.amount)
			FROM banktransaction P
			WHERE P.kpay = payment.kpay
				AND P.transactiondate BETWEEN @start AND @stop)
		,0),
                -- Banktransaction
		banktransaction.amount,
		
		-- Communicated Performed
		ISNULL(
			(SELECT SUM(amount)
			FROM banktransaction P
			JOIN payment T
				ON P.kpay=T.kpay
			 WHERE 
				T.kpay=payment.kpay 
				AND P.transactiondate BETWEEN @start AND @stop
				AND T.kpaymenttransmission is not null)
		,0),
		-- Communicated Not Performed
		ISNULL(
			(SELECT SUM(curramount)
			FROM expensetotal I
			JOIN expense S
				ON I.idexp = S.idexp
			JOIN expenselast ESL
				ON ESL.idexp = S.idexp 
			WHERE S.ymov = payment.ypay
				AND ESL.kpay=payment.kpay
				AND payment.kpaymenttransmission is not null)
		,0)
		- ISNULL(
			(SELECT SUM(P.amount)
			FROM banktransaction P
			WHERE P.kpay=payment.kpay
				AND P.transactiondate BETWEEN @start AND @stop
				AND payment.kpaymenttransmission is not null)
		,0),
		-- Not Communicated
		ISNULL(
			(SELECT SUM(curramount)
			FROM expensetotal I
			JOIN expense S
				ON I.idexp=S.idexp
			JOIN expenselast ESL
				ON ESL.idexp = S.idexp 
			JOIN payment T
				ON ESL.kpay=T.kpay
			WHERE 
				T.kpay=payment.kpay
				AND (transmissiondate IS NULL OR transmissiondate > @stop))
		,0)

	FROM payment 
	LEFT OUTER JOIN registry 
		ON registry.idreg = payment.idreg
	LEFT OUTER JOIN fin 
		ON fin.idfin = payment.idfin 
	LEFT OUTER JOIN manager 
		ON manager.idman = payment.idman
	LEFT OUTER JOIN stamphandling 
		ON stamphandling.idstamphandling = payment.idstamphandling
	LEFT OUTER JOIN paymenttransmission
		ON paymenttransmission.kpaymenttransmission = payment.kpaymenttransmission
	LEFT OUTER JOIN banktransaction
		ON banktransaction.kpay = payment.kpay
		AND banktransaction.transactiondate BETWEEN @start AND @stop
	WHERE payment.ypay = @ydoc and (UPPER(@performed)='S' or transmissiondate <= @stop)
	ORDER BY payment.ypay,payment.npay, banktransaction.idpay
END
ELSE
BEGIN
	INSERT INTO #performed
	(
		yban,
		nban,
		ydoc,	
		ndoc,
		stamphandling,
		registry,
		codefin,
		fin,
		manager,
		ytransmission,
		ntransmission,
		transmissiondate,
		adate,
		printdate,
		annulmentdate,
		transactiondate,
		total,
		performed,
		notperformed,
		banktransaction,
		communicatedperformed,
		communicatednotperformed,
		notcommunicated
	
	)
	SELECT	
		banktransaction.yban,
		banktransaction.nban,
		proceeds.ypro, 
		proceeds.npro,
		'' ,
		registry.title ,
		fin.codefin,
		fin.title,
		manager.title,
		proceedstransmission.yproceedstransmission,
		proceedstransmission.nproceedstransmission,
		proceedstransmission.transmissiondate,
		proceeds.adate,
		proceeds.printdate,
		proceeds.annulmentdate,
		banktransaction.transactiondate,
		-- Total
		ISNULL(
			(SELECT SUM(curramount)
			FROM incometotal I 
			JOIN income S
				ON S.idinc = I.idinc
			JOIN incomelast ISL
				ON ISL.idinc = S.idinc
			WHERE S.ymov = proceeds.ypro
				AND ISL.kpro = proceeds.kpro)
		,0),
		-- Performed
		ISNULL(
			(SELECT SUM(P.amount)
			FROM banktransaction P
			WHERE P.kpro=proceeds.kpro
				AND P.transactiondate BETWEEN @start AND @stop)
		,0),
		-- Not Performed
		ISNULL(
			(SELECT SUM(curramount)
			FROM incometotal I
			JOIN income S
				ON I.idinc = S.idinc
			JOIN incomelast ISL
				ON ISL.idinc = S.idinc
			WHERE S.ymov = proceeds.ypro
				AND ISL.kpro=proceeds.kpro)
		,0)
		- ISNULL(
			(SELECT SUM(P.amount)
			FROM banktransaction P
			WHERE P.kpro=proceeds.kpro
				AND P.transactiondate BETWEEN @start AND @stop)
		,0),
                --banktransaction
		banktransaction.amount,
		
		--Communicated Performed						---- DA MANTENERE
		ISNULL(
			(SELECT SUM(amount)
			FROM banktransaction P
			JOIN proceeds T
				ON P.kpro=T.kpro
			 WHERE 
				T.kpro=proceeds.kpro 
				AND P.transactiondate BETWEEN @start AND @stop
				AND T.kproceedstransmission is not null)
		,0),
		--Communicated Not Performed						---- DA MANTENERE
		ISNULL(
			(SELECT SUM(curramount)
			FROM incometotal I
			JOIN income S
				ON I.idinc = S.idinc
			JOIN incomelast ISL
				ON ISL.idinc = S.idinc
			WHERE ISL.kpro=proceeds.kpro
				AND I.ayear = proceeds.ypro
				AND proceeds.kproceedstransmission is not null)
		,0)
		- ISNULL(
			(SELECT SUM(P.amount)
			FROM banktransaction P
			WHERE P.kpro=proceeds.kpro
				AND P.transactiondate BETWEEN @start AND @stop
				AND proceeds.kproceedstransmission is not null)
		,0),
		-- Not Communicated
		ISNULL(
			(SELECT SUM(curramount)
			FROM incometotal I
			JOIN income S
				ON I.idinc=S.idinc
			JOIN incomelast ISL
				ON ISL.idinc = S.idinc
			JOIN proceeds T
				ON ISL.kpro=T.kpro
			WHERE 
				T.kpro=proceeds.kpro
				AND (transmissiondate IS NULL OR transmissiondate>@stop))
		,0)
		
 		FROM proceeds 
		LEFT OUTER JOIN banktransaction
			ON banktransaction.kpro = proceeds.kpro
			AND banktransaction.transactiondate BETWEEN @start AND @stop
		LEFT OUTER JOIN registry 
			ON registry.idreg = proceeds.idreg
		LEFT OUTER JOIN fin 
			ON fin.idfin = proceeds.idfin 
		LEFT OUTER JOIN manager 
			ON manager.idman = proceeds.idman
		LEFT OUTER JOIN proceedstransmission
			ON proceedstransmission.kproceedstransmission = proceeds.kproceedstransmission
		WHERE proceeds.ypro=@ydoc and (UPPER(@performed)='S' or transmissiondate <= @stop)
		ORDER BY proceeds.ypro,proceeds.npro,banktransaction.idpro
		End

if (UPPER(@performed)='S')
BEGIN
	SELECT 
		yban, nban,
		ydoc,	
		ndoc,
		stamphandling,
		registry,
		codefin,
		fin,
		manager,
		ytransmission,
		ntransmission,
		transmissiondate,
		adate,
		printdate,
		annulmentdate,
		transactiondate,
		ISNULL(total,0)        			'total',
		ISNULL(performed,0)    			'performed',
		ISNULL(notperformed,0)   		'notperformed',
		ISNULL(banktransaction,0) 		'banktransaction',
		ISNULL(communicatedperformed,0)		'communicatedperformed',
		ISNULL(communicatednotperformed,0) 	'communicatednotperformed',
		ISNULL(notcommunicated,0) 		'notcommunicated'
	FROM #performed
	WHERE ISNULL(total,0) = ISNULL(performed,0) 
	AND ISNULL(total,0) <> 0  -- non visualizzo i documenti vuoti o azzerati
END
ELSE 
BEGIN
--Partially Performed
	SELECT 
		yban, 
		nban,
		ydoc,	
		ndoc,
		stamphandling,
		registry,
		codefin,
		fin,
		manager,
		ytransmission,
		ntransmission,
		transmissiondate,
		adate,
		printdate,
		annulmentdate,
		transactiondate,	
		ISNULL(total,0)        			'total',
		ISNULL(performed,0)    			'performed',
		ISNULL(notperformed,0)   		'notperformed',
		ISNULL(banktransaction,0) 		'banktransaction',
		ISNULL(communicatedperformed,0)		'communicatedperformed',
		ISNULL(communicatednotperformed,0) 	'communicatednotperformed',
		ISNULL(notcommunicated,0) 		'notcommunicated'
	FROM #performed
	WHERE ISNULL(total,0) <> ISNULL(performed,0)
	AND ISNULL(total,0) <> 0 -- non visualizzo i documenti vuoti o azzerati
END
END


GO

print 'rpt_performed OK'

