if object_id('[rpt_anagrafeprestazionicomunicazione]') is not null
	drop PROCEDURE [rpt_anagrafeprestazionicomunicazione]
go

CREATE   PROCEDURE [rpt_anagrafeprestazionicomunicazione]
(
	@ayear smallint, 
	@idreg int, 
	@show_addr_anagp char(1)
)
AS BEGIN
-- Questa stampa considera SOLO i dipendenti
-- exec rpt_anagrafeprestazionicomunicazione 2008,732,{ts '2008-01-01 00:00:00'},{ts '2008-12-31 00:00:00'}, 'S'
CREATE TABLE #serviceregistry
(
	idreg int,
	registry varchar(100),
	cf varchar(16),
	nservreg int,
	birthdate smalldatetime,
	grossamount decimal (19,2),
	service varchar(50),
	npay int,
	start smalldatetime,
	stop smalldatetime,
    apactivitykind varchar(150),
    authorizationdate smalldatetime,
    annoliquidazione smallint,
    department varchar(150),
    description varchar(200)
)
CREATE TABLE #address_to_send
(
	idaddresskind int,
	idreg int,
	officename varchar(50),
	address varchar(100),
	location varchar(120),
	cap varchar(20),
	province varchar(2),
	nation varchar(65),
	recipientagency varchar(50)
)
CREATE TABLE #address_residence
(
	idaddresskind int,
	idreg int,
	officename varchar(50),
	address varchar(100),
	location varchar(120),
	cap varchar(20),
	province varchar(2),
	nation varchar(65)
)
CREATE TABLE #registry_birth
(	idreg int,
	city_title varchar(120),
	province varchar(2),
	nation_title varchar(65)
)
IF @ayear = 0
BEGIN
	SET @ayear='1900'
END
DECLARE @dateaddress datetime
SELECT  @dateaddress = CONVERT(datetime, '31-12-'+ CONVERT(varchar(4),@ayear), 105)

INSERT INTO #serviceregistry
(
	idreg,
	registry,
	nservreg,
	cf,
	birthdate ,
	grossamount,
	start,
	stop,
	apactivitykind,
	authorizationdate,
	annoliquidazione,
	description
)
SELECT
	R.idreg,
	R.title,
	R.nservreg,
	R.cf,
	R.birthdate ,
	ISNULL(SUM(payedamount),0),
	R.start,
	R.stop,
	R.apactivitykind,
	R.authorizationdate,
	P.ypay,
	R.description
FROM serviceregistryview R
JOIN servicepayment P
        ON R.yservreg = P.yservreg AND R.nservreg = P.nservreg
WHERE  (R.idreg=@idreg OR @idreg=0)
        AND P.ypay = @ayear
	AND R.employkind = 'C'
GROUP BY R.idreg,R.title, R.cf,R.birthdate,P.ypay,R.nservreg, R.description,
        R.start,R.stop,R.apactivitykind,R.authorizationdate
DECLARE @codenostand varchar(20)
SET @codenostand = '07_SW_ANP'
DECLARE @codestand varchar(20)
SET @codestand = '07_SW_DEF'
DECLARE @STAND int
SELECT @STAND = idaddress FROM address WHERE codeaddress = @codestand
DECLARE @NOSTAND int
SELECT @NOSTAND = idaddress FROM address WHERE codeaddress = @codenostand
-- Inizio calcolo indirizzi
INSERT INTO #address_to_send
(
	idaddresskind,
	idreg,
	officename,
	address,
	location,
	cap,
	province,
	nation,
	recipientagency
)
SELECT 
	idaddresskind,
	idreg, 
	officename, 
	address,
	ISNULL(geo_city.title,'') + ' ' + ISNULL(registryaddress.location,''),
	registryaddress.cap,
	geo_country.province,
	CASE
		WHEN flagforeign = 'N' THEN 'Italia'
		ELSE geo_nation.title
	END,
	recipientagency
FROM registryaddress
LEFT OUTER JOIN geo_city
	ON geo_city.idcity = registryaddress.idcity
LEFT OUTER JOIN geo_country
	ON geo_city.idcountry = geo_country.idcountry
LEFT OUTER JOIN geo_nation
	ON geo_nation.idnation = registryaddress.idnation
WHERE (registryaddress.active <>'N' 
        AND (idreg IN (select idreg from  #serviceregistry))
	AND registryaddress.start = 
		(SELECT MAX(cdi.start) 
		FROM registryaddress cdi 
		WHERE cdi.idaddresskind = registryaddress.idaddresskind
			AND cdi.active <>'N' 
			AND cdi.start <= @dateaddress
			AND cdi.idreg = registryaddress.idreg)
)
DELETE #address_to_send
WHERE #address_to_send.idaddresskind <> @nostand  -- Restano solo 07_SW_ANP
AND EXISTS(
	SELECT * FROM #address_to_send r2 
	WHERE #address_to_send.idreg = r2.idreg
		AND r2.idaddresskind = @nostand
	)  
DELETE #address_to_send
WHERE #address_to_send.idaddresskind NOT IN (@NOSTAND, @STAND)
AND EXISTS(
	SELECT * FROM #address_to_send r2 
	WHERE #address_to_send.idreg = r2.idreg
		AND r2.idaddresskind = @STAND
	)  --restano solo 07_SW_ANP  o solo 07_SW_DEF
DELETE #address_to_send
WHERE (
	SELECT COUNT(*) FROM #address_to_send r2 
	WHERE #address_to_send.idreg = r2.idreg
)>1  -- cancello quelli con più  indirizzi
		
SET @codenostand = '07_SW_DOM'
SELECT @NOSTAND = idaddress FROM address WHERE codeaddress = @codestand
INSERT INTO #address_residence
(
	idaddresskind,
	idreg,
	officename,
	address,
	location,
	cap,
	province,
	nation
)
SELECT 
	idaddresskind,
	idreg, 
	officename, 
	address,
	ISNULL(geo_city.title,'') + ' ' + ISNULL(registryaddress.location,''),
	registryaddress.cap,
	geo_country.province,
	CASE
		WHEN flagforeign = 'N' THEN 'Italia'
		ELSE geo_nation.title
	END
	FROM registryaddress
	LEFT OUTER JOIN geo_city
		ON geo_city.idcity = registryaddress.idcity
	LEFT OUTER JOIN geo_country
		ON geo_city.idcountry = geo_country.idcountry
	LEFT OUTER JOIN geo_nation
		ON geo_nation.idnation = registryaddress.idnation
	WHERE (registryaddress.active <>'N' 
                AND (idreg IN (select idreg from  #serviceregistry))
		AND registryaddress.start = 
			(SELECT MAX(cdi.start) 
			FROM registryaddress cdi 
			WHERE cdi.idaddresskind = registryaddress.idaddresskind
				AND cdi.active <>'N' 
				AND cdi.start <= @dateaddress
				AND cdi.idreg = registryaddress.idreg)
			)
DELETE #address_residence
WHERE #address_residence.idaddresskind <> @NOSTAND
AND EXISTS (
	SELECT * FROM #address_residence r2 
	WHERE #address_residence.idreg = r2.idreg
		AND r2.idaddresskind = @NOSTAND
	)
DELETE #address_residence
WHERE #address_residence.idaddresskind NOT IN (@nostand, @stand)
AND EXISTS (
	SELECT * FROM #address_residence r2 
	WHERE #address_residence.idreg = r2.idreg
		AND r2.idaddresskind = @STAND
	)
DELETE #address_residence
WHERE (
	SELECT COUNT(*) FROM #address_residence r2 
	WHERE #address_residence.idreg = r2.idreg
	)>1
	
-- Fine calcolo indirizzi
INSERT INTO #registry_birth
(
	idreg,
	city_title,
	province,
	nation_title
)
SELECT
	registry.idreg,
	ISNULL(geo_city.title, '') + ' ' + ISNULL(registry.location,''),
	ISNULL(geo_country.province, ''),
	ISNULL(geo_nation.title, 'ITALIA')
FROM registry
LEFT OUTER JOIN geo_city
	ON registry.idcity = geo_city.idcity  
LEFT OUTER JOIN geo_country
	ON geo_city.idcountry = geo_country.idcountry
LEFT OUTER JOIN geo_nation
	ON registry.idnation = geo_nation.idnation  
WHERE  (idreg IN (select idreg from  #serviceregistry))

DECLARE @departmentname varchar(500)
SET  @departmentname  = ISNULL( (SELECT top 1 paramvalue from
    generalreportparameter where idparam='DenominazioneDipartimento' 
    and  (ISNULL(start, {d '1900-01-01'}) = {d '1900-01-01'} or year(start) <= @ayear) 
    and  (ISNULL(stop, {d '2079-06-06'}) = {d '2079-06-06'}  or year(stop) >= @ayear)
    order by ISNULL(stop, {d '2079-06-06'}) desc
    ),'Manca Cfg. Parametri Tutte le stampe')

IF (ISNULL(@show_addr_anagp,'N') = 'N' )
BEGIN	
	SELECT
		@departmentname as departmentname,
		#serviceregistry.idreg,
		ISNULL(#serviceregistry.registry,registry.title) as registry,
		#serviceregistry.nservreg,
		#serviceregistry.cf,
		#serviceregistry.birthdate ,
		#serviceregistry.grossamount,
		#serviceregistry.start,
		#serviceregistry.stop,
		#serviceregistry.apactivitykind,
		#serviceregistry.authorizationdate,
		#serviceregistry.annoliquidazione,
		#registry_birth.city_title AS b_city,
		#registry_birth.province AS b_province,
		#registry_birth.nation_title AS b_nation,
		#address_to_send.recipientagency AS sent_agency,
		#address_to_send.officename AS sent_office,
		#address_to_send.address AS sent_address,
		isnull(add_sen.codeaddress,'') AS sent_idaddresskind, 
		#address_to_send.location AS sent_location,
		#address_to_send.cap AS sent_cap,
		#address_to_send.province AS sent_province,
		#address_to_send.nation AS sent_nation,
		#address_residence.address AS residence_address,
		add_res.codeaddress AS residence_idaddresskind,
		#address_residence.location AS residence_location,
		#address_residence.cap AS residence_cap,
		#address_residence.province AS residence_province,
		#address_residence.nation AS residence_nation,
		#serviceregistry.description
	FROM #serviceregistry
	JOIN registry
		ON #serviceregistry.idreg = registry.idreg
	JOIN #registry_birth
		ON #serviceregistry.idreg = #registry_birth.idreg
	LEFT OUTER JOIN #address_to_send
		ON #address_to_send.idreg = #serviceregistry.idreg
	LEFT OUTER JOIN address add_sen
		ON add_sen.idaddress = #address_to_send.idaddresskind
	LEFT OUTER JOIN #address_residence
		ON #address_residence.idreg = #serviceregistry.idreg
	LEFT OUTER JOIN address add_res
		ON add_res.idaddress = #address_to_send.idaddresskind
END
ELSE
BEGIN
		SELECT
		@departmentname as departmentname,
		#serviceregistry.idreg,
		ISNULL(#serviceregistry.registry,registry.title) as registry,
		#serviceregistry.nservreg,
		#serviceregistry.cf,
		#serviceregistry.birthdate ,
		#serviceregistry.grossamount,
		#serviceregistry.start,
		#serviceregistry.stop,
		#serviceregistry.apactivitykind,
		#serviceregistry.authorizationdate,
		#serviceregistry.annoliquidazione,
		#registry_birth.city_title AS b_city,
		#registry_birth.province AS b_province,
		#registry_birth.nation_title AS b_nation,
		#address_to_send.recipientagency AS sent_agency,
		#address_to_send.officename AS sent_office,
		#address_to_send.address AS sent_address,
		isnull(add_sen.codeaddress,'') AS sent_idaddresskind, 
		#address_to_send.location AS sent_location,
		#address_to_send.cap AS sent_cap,
		#address_to_send.province AS sent_province,
		#address_to_send.nation AS sent_nation,
		#address_residence.address AS residence_address,
		add_res.codeaddress AS residence_idaddresskind,
		#address_residence.location AS residence_location,
		#address_residence.cap AS residence_cap,
		#address_residence.province AS residence_province,
		#address_residence.nation AS residence_nation,
		#serviceregistry.description
	FROM #serviceregistry
	JOIN registry
		ON #serviceregistry.idreg = registry.idreg
	JOIN #registry_birth
		ON #serviceregistry.idreg = #registry_birth.idreg
	LEFT OUTER JOIN #address_to_send
		ON #address_to_send.idreg = #serviceregistry.idreg
	LEFT OUTER JOIN address add_sen
		ON add_sen.idaddress = #address_to_send.idaddresskind
	LEFT OUTER JOIN #address_residence
		ON #address_residence.idreg = #serviceregistry.idreg
	LEFT OUTER JOIN address add_res
		ON add_res.idaddress = #address_to_send.idaddresskind
	WHERE ISNULL(add_sen.codeaddress,'07_SW_DEF') =  '07_SW_ANP'
END
END

GO

print '[rpt_anagrafeprestazionicomunicazione] OK'

GO
if object_id('[sort_auto_allexpense]') is not null
	drop PROCEDURE [sort_auto_allexpense]
go


CREATE            PROCEDURE [sort_auto_allexpense]
(
	@idsorkind int,
	@ayear int
)
AS BEGIN
DECLARE @nlevel tinyint
DECLARE @idexp int
DECLARE @idsormov int
DECLARE @amount decimal(23,6)
DECLARE @sortcode_temp int
DECLARE @nphaseexpense tinyint
SELECT @nphaseexpense = nphaseexpense FROM sortingkind WHERE idsorkind = @idsorkind
CREATE TABLE #finsor (idsor int, quota float)
DECLARE #expense_cursor INSENSITIVE CURSOR FOR
SELECT idexp
FROM expenseview
WHERE ayear = @ayear 
	AND nphase = @nphaseexpense
	AND idexp NOT IN
		(SELECT idexp 
		FROM expensesorted 
		JOIN sorting
			ON sorting.idsor = expensesorted.idsor
		WHERE sorting.idsorkind = @idsorkind AND ayear = @ayear)
FOR READ ONLY
OPEN #expense_cursor
FETCH NEXT FROM #expense_cursor INTO @idexp
WHILE (@@FETCH_STATUS = 0)
BEGIN
	SELECT @nlevel = nlevel 
	FROM fin
	JOIN expenseyear
		ON fin.idfin = expenseyear.idfin
	WHERE expenseyear.idexp = @idexp AND expenseyear.ayear = @ayear
	
	IF (
	SELECT COUNT(*)
	FROM finsorting C
	JOIN expenseyear I 
		ON C.idfin = I.idfin
	JOIN sorting S
		ON S.idsor = C.idsor
	WHERE I.idexp = @idexp 
		AND S.idsorkind = @idsorkind
	AND i.ayear = @ayear) > 0
	BEGIN
		INSERT INTO #finsor
		SELECT C.idsor,quota
		FROM finsorting C
		JOIN expenseyear I 
			ON C.idfin = I.idfin
		JOIN sorting S
			ON S.idsor = C.idsor
		WHERE I.idexp = @idexp 
			AND S.idsorkind = @idsorkind
			AND i.ayear = @ayear
	END
	ELSE IF (
	SELECT COUNT(*)
	FROM finsorting C
	JOIN finlink K
		ON K.idparent = C.idfin
	JOIN expenseyear I 
		ON I.idfin = K.idchild 
	JOIN sorting S
		ON S.idsor = C.idsor
	WHERE I.idexp = @idexp 
		AND K.nlevel = @nlevel-1
		AND S.idsorkind = @idsorkind AND i.ayear = @ayear) > 0
	BEGIN
		INSERT INTO #finsor
		SELECT C.idsor,quota
		FROM finsorting C
		JOIN finlink K
			ON K.idparent = C.idfin
		JOIN expenseyear I 
			ON I.idfin = K.idchild 
		JOIN sorting S
			ON S.idsor = C.idsor
		WHERE I.idexp = @idexp 
			AND K.nlevel = @nlevel-1
			AND S.idsorkind = @idsorkind
			AND i.ayear = @ayear
	END
	ELSE IF (
	SELECT COUNT(*)
	FROM finsorting C
	JOIN finlink K
		ON K.idparent = C.idfin
	JOIN expenseyear I 
		ON I.idfin = K.idchild 
	JOIN sorting S
		ON S.idsor = C.idsor
	WHERE I.idexp = @idexp 
		AND K.nlevel = @nlevel-2
		AND S.idsorkind = @idsorkind
		AND i.ayear = @ayear) > 0
	BEGIN
		INSERT INTO #finsor
		SELECT C.idsor,quota 
		FROM finsorting C 
		JOIN finlink K
			ON K.idparent = C.idfin
		JOIN expenseyear I 
			ON I.idfin = K.idchild 
		JOIN sorting S
			ON S.idsor = C.idsor
		WHERE I.idexp = @idexp 
			AND K.nlevel = @nlevel-2
			AND S.idsorkind = @idsorkind
			AND i.ayear = @ayear
	END
	ELSE IF (
	SELECT COUNT(*)
	FROM finsorting C
	JOIN finlink K
		ON K.idparent = C.idfin
	JOIN expenseyear I 
		ON I.idfin = K.idchild 
	JOIN sorting S
		ON S.idsor = C.idsor
	WHERE I.idexp = @idexp AND K.nlevel = @nlevel-3
		AND S.idsorkind = @idsorkind AND i.ayear = @ayear) > 0
	BEGIN
		INSERT INTO #finsor
		SELECT C.idsor,quota
		FROM finsorting C
		JOIN finlink K
			ON K.idparent = C.idfin
		JOIN expenseyear I -->ISNULL(quota,0)
			ON I.idfin = K.idchild 
		JOIN sorting S
			ON S.idsor = C.idsor
		WHERE I.idexp = @idexp AND K.nlevel = @nlevel-3
			AND S.idsorkind = @idsorkind AND i.ayear = @ayear
	END
	ELSE 
	BEGIN
		FETCH NEXT FROM #expense_cursor INTO @idexp
		CONTINUE	-- Voce di bilancio non classificata
	END
	
	SELECT @amount =
	ISNULL(
		(SELECT curramount
		FROM expensetotal
		WHERE idexp = @idexp
			AND ayear = @ayear)
	,0)
	IF (
	SELECT COUNT(*)
	FROM #finsor
	WHERE ISNULL(@amount,0) * ISNULL(#finsor.quota,1) > 0)>0
	BEGIN
		INSERT INTO expensesorted
		(
			idsor, idexp,
			idsubclass,
			amount,
			description, ayear,
			cu, ct, lu, lt
		)
		SELECT
			idsor, @idexp,
			ISNULL(
				(SELECT MAX(idsubclass)
				FROM expensesorted I
				WHERE I.idsor = #finsor.idsor
					AND I.idexp = @idexp)
			,0) + 1, 
			ISNULL(@amount,0) * ISNULL(#finsor.quota,1),
			'movimento classificato automaticamente dalla voce di bilancio', @ayear,
			'Automatico', GETDATE(), 'Automatico', GETDATE()
		FROM #finsor
		WHERE ISNULL(@amount,0) * ISNULL(#finsor.quota,1) > 0
	END
	IF (SELECT COUNT(*) FROM #finsor)>1	-- esistono almeno due ripartizione del movimento di spesa quindi devo verificare se la somma delle classificazioni quadra con l'importo del movimento di spesa
	BEGIN
		IF (
		SELECT SUM(amount)
		FROM expensesorted
		JOIN sorting S
			ON S.idsor = expensesorted.idsor
		WHERE S.idsorkind = @idsorkind
			AND @idexp = idexp
			AND ayear=@ayear) <> @amount
		BEGIN
			-- non quadra quindi devo compensare automaticamente
			SELECT @sortcode_temp = (SELECT TOP 1 idsor FROM #finsor ORDER BY quota DESC) -- prendo il codice di classificazione con la quota maggiore
			DECLARE @idsubclass int
			SELECT @idsubclass =
			ISNULL(
				(SELECT MAX(idsubclass)
				FROM expensesorted I
				WHERE I.idsor = @sortcode_temp 
					AND I.idexp = @idexp 
					AND I.ayear=@ayear)
			,0)
			UPDATE expensesorted
			SET amount = @amount -
			ISNULL(
				(SELECT SUM(amount)
				FROM expensesorted
				JOIN sorting S
					ON S.idsor = expensesorted.idsor
				WHERE S.idsorkind = @idsorkind
					AND idexp = @idexp
					AND ((expensesorted.idsor <> @sortcode_temp) OR (idsubclass <> @idsubclass))
					AND ayear=@ayear)
			,0)
			WHERE idsor = @sortcode_temp 
				AND idexp = @idexp 
				AND idsubclass = @idsubclass
		END
	END
	DELETE #finsor
	FETCH NEXT FROM #expense_cursor INTO @idexp
END
CLOSE #expense_cursor
DEALLOCATE #expense_cursor
END


GO

print '[sort_auto_allexpense] OK'

