						AND expenselink.nlevel = @expensephase
					LEFT OUTER JOIN expensepayroll
						ON expensepayroll.idexp = expenselink.idparent
					LEFT OUTER JOIN payroll
						ON payroll.idpayroll = expensepayroll.idpayroll
