					AND (
						((YEAR(paymenttransmission.transmissiondate) = @ayear)
						AND (payroll.fiscalyear IS NULL))
						OR (payroll.fiscalyear = @ayear)
					)
				     group by E.idexp
				     ) as tabella)
 
