if object_id('[exp_registrybyresidence]') is not null
	drop PROCEDURE [exp_registrybyresidence]
go
-- exp_registrybyresidence 2009,3,null,{d '1900-01-01'}, {d '2009-12-31'},'0'
CREATE      PROCEDURE [exp_registrybyresidence]
	@ayear int,
	@codelevel tinyint,
	@codefin varchar(50),
	@stop datetime,
--	@idreg int,
	@viewregistry char(1)
AS
BEGIN
-- Per il momento elaboriamo solo le Entrate.
DECLARE @idfin int
IF (@codefin IS NULL OR @codefin = '' OR @codefin = '%')
	BEGIN
		SET @idfin = null	
	END
Else
	BEGIN
	   	SET @idfin = (select idfin 
				from fin 
				where codefin = @codefin 
				and ayear = @ayear 
				and ( fin.flag&1) = 0 ) --> Entrata
	END
DECLARE @level_input tinyint
SELECT @level_input = ISNULL(nlevel, @codelevel) from fin where idfin = @idfin
-- ho scelto come livello 2 e poi ho specificato il capitolo, lui corregge @nlevel dandogli 3
IF (@codelevel < @level_input ) AND (@idfin is not null)
BEGIN
	SET  @codelevel = @level_input
END

DECLARE @nfinphase tinyint
SELECT @nfinphase = incomeregphase
FROM uniconfig
DECLARE @maxincomephase tinyint
SELECT  @maxincomephase = MAX(nphase)
FROM    incomephase 
	
DECLARE @cashvaliditykind int
SELECT  @cashvaliditykind = cashvaliditykind FROM config WHERE ayear = @ayear
CREATE TABLE #income
(
	idfin int,
	flagarrear char(1),	
	idreg int,
	idassessment int,
	assessment decimal(19,2),
	idproceed int,
	proceed decimal(19,2),
	residence int,
	registry varchar(100)
)
INSERT INTO #income
(
	idfin,
	idreg,
	idassessment, 	assessment,
	idproceed,		proceed,
	flagarrear,
	residence,
	registry
)
SELECT 
	ISNULL(FL.idparent, incomeyear.idfin),
	income.idreg,
	I2.idinc, --> id Accertamento
	CASE WHEN income.nphase = @nfinphase 
			THEN incomeyear.amount
			ELSE 0
	END ,
	HPV.idinc, --> id Incasso
	isnull(HPV.amount,0),
	CASE
		WHEN ((incometotal.flag&1)=0) THEN 'C'
		WHEN ((incometotal.flag&1)=1) THEN 'R'
	END ,
	R.residence,
	R.title
FROM incomeyear
JOIN income
	ON incomeyear.idinc = income.idinc 
JOIN incometotal
	ON  incomeyear.idinc = incometotal.idinc
	AND incomeyear.ayear = incometotal.ayear	
JOIN registry R
	ON income.idreg = R.idreg
JOIN incomelink IL2
	ON IL2.idchild = income.idinc  
	AND IL2.nlevel = @nfinphase
LEFT OUTER JOIN income I2
	ON I2.idinc = IL2.idparent
LEFT  OUTER JOIN finlink FL
	ON FL.idchild = incomeyear.idfin AND FL.nlevel = @codelevel
LEFT  OUTER JOIN finlink FL1
	ON FL1.idchild = incomeyear.idfin AND FL1.nlevel = @level_input
LEFT OUTER JOIN historyproceedsview HPV
	ON HPV.idinc = income.idinc
	AND HPV.ymov = @ayear
	AND HPV.competencydate <= @stop
WHERE (@idfin IS NULL OR isnull(FL1.idparent, incomeyear.idfin) = @idfin)
	AND incomeyear.ayear = @ayear
	AND income.adate <= @stop
	AND ((income.nphase IN (@nfinphase,@maxincomephase )))
	--AND ( income.idreg = @idreg OR @idreg = 0 )
UPDATE #income
	SET
-- Questi valori li calcolo in base all'idinc perchè devo distinguerli tra competenza e cassa.
	assessment = assessment + 
				(SELECT ISNULL(SUM(amount),0.0) 
				   FROM incomevar
				  WHERE incomevar.idinc = #income.idassessment
				    AND incomevar.adate <= @stop
				    AND incomevar.yvar = @ayear)
IF (@cashvaliditykind <> 4)
Begin
	UPDATE #income
	SET
		proceed = proceed + 
						ISNULL((
						SELECT SUM(incomevar.amount)
						FROM incomevar
						JOIN historyproceedsview HPV
							ON HPV.idinc = incomevar.idinc
						WHERE incomevar.yvar = @ayear
							AND incomevar.adate <= @stop
							AND HPV.competencydate <= @stop
							AND HPV.idinc = #income.idproceed), 0.0)
End
if(@viewregistry = 'S')
Begin
	SELECT  
		#income.registry AS 'Anagrafica',
		S.description as 'Residenza',
		F.codefin as 'Cod.Bilancio',
		F.title as 'Bilancio',
		SUM(CASE WHEN #income.flagarrear = 'C' 
				then isnull(assessment,0) 
				else 0 
			END) as 'Accertato c/C',
		SUM(CASE WHEN #income.flagarrear = 'R'	
					then isnull(assessment,0) 
					else 0 
			END) as 'Accertato c/R',
		SUM(CASE WHEN #income.flagarrear = 'C' 
				then isnull(proceed,0) 
				else 0 
			END) as 'Incassato c/C',
		SUM(CASE WHEN #income.flagarrear = 'R' 
				then isnull(proceed,0) 
				else 0 
			END) as 'Incassato c/R',
		SUM(Assessment) as 'Tot.Accertato',
		SUM(Proceed) as 'Tot.Incassato'
	FROM  #income
	JOIN residence S
		ON S.idresidence = #income.residence
	JOIN fin F
		ON #income.idfin = F.idfin
	GROUP BY S.description, #income.registry, F.codefin, F.title
End
Else
Begin
	SELECT  
		S.description as 'Provenienza',
		F.codefin as 'Cod.Bilancio',
		F.title as 'Bilancio',
		SUM(CASE WHEN #income.flagarrear = 'C' 
				then isnull(assessment,0) 
				else 0 
			END) as 'Accertato c/C',
		SUM(CASE WHEN #income.flagarrear = 'R'	
					then isnull(assessment,0) 
					else 0 
			END) as 'Accertato c/R',
		SUM(CASE WHEN #income.flagarrear = 'C' 
				then isnull(proceed,0) 
				else 0 
			END) as 'Incassato c/C',
		SUM(CASE WHEN #income.flagarrear = 'R' 
				then isnull(proceed,0) 
				else 0 
			END) as 'Incassato c/R',
		SUM(Assessment) as 'Tot.Accertato',
		SUM(Proceed) as 'Tot.Incassato'
	FROM  #income
	JOIN residence S
		ON S.idresidence = #income.residence
	JOIN fin F
		ON #income.idfin = F.idfin
	GROUP BY  S.description, F.codefin, F.title
End
END

GO

print '[exp_registrybyresidence] OK'

GO
if object_id('exp_invoicepayed_unified') is not null
	drop PROCEDURE exp_invoicepayed_unified
go
CREATE    PROCEDURE exp_invoicepayed_unified(
	@ayear 			int,
	@start 			smalldatetime,
	@stop 			smalldatetime,
	@idivaregisterkind int,
	@deferred 		char(1), --(D = Solo fatture ad iva Differita, I = solo fatture ad iva Immediata, T = Tutte)
	@unified char(1)  ,
	@detail  char(1) --> S = mostra dettagli fattura, N = non mostra i dettagli, fornisce una sintesi.
) 
AS BEGIN
--  exp_invoicepayed_unified '2010', {ts '2010-01-01 00:00:00.000'}, {ts '2010-05-28 00:00:00.000'}, null, 'T','S','N'
	IF (@unified <> 'S')
	BEGIN
			EXEC exp_invoicepayed @ayear,@start,@stop,@idivaregisterkind,@deferred,@unified
			RETURN
	END 
	CREATE TABLE #invoice_main
	(	
		department varchar(250),	
		idinvkind int,
		invoicekind varchar(50),
		yinv int,
		ninv int,
		flagdeferred char(1),
		doc varchar(35),
		docdate smalldatetime,	
		taxabletotal decimal(19,2),
		ivatotal decimal(19,2),
		ivatotalpayed decimal(19,2),
		idivaregisterkindunified int,
		registername varchar(50)
	)
	declare @iddbdepartment varchar(50)
	declare @crsdepartment cursor
	set 	@crsdepartment = cursor for 
	select  iddbdepartment from dbdepartment
	where (start is null or start <= @ayear ) AND ( stop is null or stop >= @ayear)
	open 	@crsdepartment
	fetch next from @crsdepartment into @iddbdepartment
	while @@fetch_status=0 begin
		declare @s varchar(300)
		set @s = @iddbdepartment + '.exp_invoicepayed'
	INSERT INTO #invoice_main
	(
		department,
		invoicekind,
		yinv,
		ninv,
		flagdeferred,
		doc,
		docdate,	
		taxabletotal,
		ivatotal,
		ivatotalpayed,
		idivaregisterkindunified
	)			
	exec @s @ayear,@start,@stop,@idivaregisterkind,@deferred,@unified
		fetch next from @crsdepartment into @iddbdepartment
	end
IF(@detail='S')	
Begin
	SELECT 
	department as 'Dipartimento', 
	ivaregisterkind.description AS 'Registro',
	invoicekind AS 'Tipo', 
	yinv AS 'Esercizio', 
	ninv AS 'Numero', 
	flagdeferred AS 'IVA Differita', 
	doc AS  'Documento',
	docdate AS  'Data Documento',
	taxabletotal AS 'Tot.Imponibile', 
	ivatotal AS 'Tot.IVA', 
	ivatotalpayed AS 'Totale Iva Liquididata' 
	FROM #invoice_main 
	LEFT OUTER JOIN ivaregisterkind -- << LEFT JOUTER JOIN Serve per consentire la visualizzazione dei dip. che non hanno fatture nel periodo.
		ON #invoice_main.idivaregisterkindunified = ivaregisterkind.idivaregisterkindunified
	order by idinvkind, yinv, ninv
End
ELSE
Begin
	SELECT 
	department as 'Dipartimento', 
	ivaregisterkind.description AS 'Registro',
	SUM(taxabletotal) AS 'Tot.Imponibile', 
	SUM(ivatotal) AS 'Tot.IVA', 
	SUM(ivatotalpayed) AS 'Totale Iva Liquididata' 
	FROM #invoice_main 
	LEFT OUTER JOIN ivaregisterkind -- << LEFT JOUTER JOIN Serve per consentire la visualizzazione dei dip. che non hanno fatture nel periodo.
		ON #invoice_main.idivaregisterkindunified = ivaregisterkind.idivaregisterkindunified
	GROUP BY department, ivaregisterkind.description
	order by department, ivaregisterkind.description
End

END

GO

print 'exp_invoicepayed_unified OK'

