if object_id('[sort_auto_allincome]') is not null
	drop PROCEDURE [sort_auto_allincome]
go


CREATE            PROCEDURE [sort_auto_allincome]
(
	@idsorkind int,
	@ayear int
)
AS BEGIN
DECLARE @nlevel tinyint
DECLARE @idinc int
DECLARE @idsormov int
DECLARE @amount decimal(23,6)
DECLARE @sortcode_temp int
DECLARE @nphaseincome tinyint
SELECT  @nphaseincome = nphaseincome FROM sortingkind WHERE idsorkind = @idsorkind
CREATE TABLE #finsor (idsor int, quota float)
DECLARE #income_cursor INSENSITIVE CURSOR FOR
SELECT idinc
FROM incomeview
WHERE ayear = @ayear
	AND nphase = @nphaseincome
	AND idinc NOT IN
		(SELECT idinc
		FROM incomesorted
		JOIN sorting
			ON sorting.idsor = incomesorted.idsor
		WHERE sorting.idsorkind = @idsorkind AND ayear = @ayear)
FOR READ ONLY
OPEN #income_cursor
FETCH NEXT FROM #income_cursor INTO @idinc
WHILE (@@FETCH_STATUS = 0)
BEGIN	
	SELECT @nlevel = nlevel 
	FROM fin
	JOIN incomeyear
		ON fin.idfin = incomeyear.idfin
	WHERE incomeyear.idinc = @idinc AND incomeyear.ayear = @ayear
		
	IF (
	SELECT COUNT(*)
	FROM finsorting C
	JOIN incomeyear I 
		ON C.idfin = I.idfin
	JOIN sorting S
		ON S.idsor = C.idsor
	WHERE I.idinc = @idinc 
		AND S.idsorkind = @idsorkind
		AND i.ayear = @ayear) > 0
	BEGIN
		INSERT INTO #finsor
		SELECT C.idsor,quota
		FROM finsorting C
		JOIN incomeyear I 
			ON C.idfin = I.idfin
		JOIN sorting S
			ON S.idsor = C.idsor
		WHERE I.idinc = @idinc 
			AND S.idsorkind = @idsorkind
			AND i.ayear = @ayear
	END
	ELSE IF (
	SELECT COUNT(*)
	FROM finsorting C
	JOIN finlink K
		ON K.idparent = C.idfin
	JOIN incomeyear I 
		ON I.idfin = K.idchild 
	JOIN sorting S
		ON S.idsor = C.idsor
	WHERE I.idinc = @idinc 
		AND K.nlevel = @nlevel-1
		AND S.idsorkind = @idsorkind
		AND i.ayear = @ayear)>0
	BEGIN
		INSERT INTO #finsor
		SELECT C.idsor,quota FROM finsorting C
		JOIN finlink K
			ON K.idparent = C.idfin
		JOIN incomeyear I 
			ON I.idfin = K.idchild 
		JOIN sorting S
			ON S.idsor = C.idsor
		WHERE I.idinc = @idinc 
			AND K.nlevel = @nlevel-1
			AND S.idsorkind = @idsorkind
			AND I.ayear = @ayear
	END
	ELSE IF (
	SELECT COUNT(*)
	FROM finsorting C
	JOIN finlink K
		ON K.idparent = C.idfin
	JOIN incomeyear I 
		ON I.idfin = K.idchild 
	JOIN sorting S
		ON S.idsor = C.idsor
	WHERE I.idinc = @idinc 
		AND K.nlevel = @nlevel-2
		AND S.idsorkind = @idsorkind
		AND i.ayear = @ayear)>0
	BEGIN
		INSERT INTO #finsor
		SELECT C.idsor,quota 
		FROM finsorting C 
		JOIN finlink K
			ON K.idparent = C.idfin
		JOIN incomeyear I 
			ON I.idfin = K.idchild 
		JOIN sorting S
			ON S.idsor = C.idsor
		WHERE I.idinc = @idinc 
			AND K.nlevel = @nlevel-2
			AND S.idsorkind = @idsorkind
			AND I.ayear = @ayear
	END
	ELSE IF (
	SELECT COUNT(*)
	FROM finsorting C
	JOIN finlink K
		ON K.idparent = C.idfin
	JOIN incomeyear I 
		ON I.idfin = K.idchild 
	JOIN sorting S
		ON S.idsor = C.idsor
	WHERE I.idinc = @idinc AND K.nlevel = @nlevel-3
		AND S.idsorkind = @idsorkind AND i.ayear = @ayear) > 0
	BEGIN
		INSERT INTO #finsor
		SELECT C.idsor,quota
		FROM finsorting C
		JOIN finlink K
			ON K.idparent = C.idfin
		JOIN incomeyear I -->ISNULL(quota,0)
			ON I.idfin = K.idchild 
		JOIN sorting S
			ON S.idsor = C.idsor
		WHERE I.idinc = @idinc AND K.nlevel = @nlevel-3
			AND S.idsorkind = @idsorkind AND i.ayear = @ayear
	END
	ELSE 
	BEGIN
		FETCH NEXT FROM #income_cursor INTO @idinc
		CONTINUE	-- Voce di bilancio non classificata
	END
	SELECT @amount =
	ISNULL(
		(SELECT curramount
		FROM incometotal
		WHERE idinc = @idinc
			AND ayear = @ayear)
	,0)
	IF (
	SELECT COUNT(*)
	FROM #finsor
	WHERE ISNULL(@amount,0)*ISNULL(#finsor.quota,1) > 0)>0
	BEGIN
		INSERT INTO incomesorted
		(
			idsor, idinc,
			idsubclass,
			amount,
			description, ayear,
			cu, ct, lu, lt
		)
		SELECT
			idsor, @idinc,
			ISNULL(
				(SELECT MAX(idsubclass)
				FROM incomesorted I
				WHERE I.idsor = #finsor.idsor 
					AND I.idinc = @idinc)
			,0) + 1,  -- calcolo l'IDSUBCLAS
			ISNULL(@amount,0) * ISNULL(#finsor.quota,1),
			'movimento classificato automaticamente dalla voce di bilancio', @ayear,
			'Automatico', GETDATE(), 'Automatico', GETDATE()
		FROM #finsor
		WHERE ISNULL(@amount,0) * ISNULL(#finsor.quota,1) > 0
	END
	IF (SELECT COUNT(*) FROM #finsor)>1	-- esistono almeno due ripartizione del movimento di spesa quindi devo verificare se la somma delle classificazioni quadra con l'importo del movimento di spesa
	BEGIN
		IF (
		SELECT SUM(amount)
		FROM incomesorted
		JOIN sorting S
			ON S.idsor = incomesorted.idsor
		WHERE ayear=@ayear
			AND S.idsorkind = @idsorkind 
			AND @idinc = idinc ) <> @amount
		BEGIN
			-- non quadra quindi devo compensare automaticamente
			SELECT @sortcode_temp = (SELECT TOP 1 idsor FROM #finsor ORDER BY quota DESC) -- prendo il codice di classificazione con la quota maggiore
			DECLARE @idsubclass int
			SELECT @idsubclass =
			ISNULL(
				(SELECT MAX(idsubclass)
				FROM incomesorted I
				WHERE I.idsor = @sortcode_temp
					AND I.idinc = @idinc
					AND I.ayear=@ayear)
			,0)
	
			UPDATE incomesorted
			SET amount = @amount -
			ISNULL(
				(SELECT SUM(amount)
				FROM incomesorted
				JOIN sorting S
					ON S.idsor = incomesorted.idsor
				WHERE S.idsorkind = @idsorkind
					AND idinc = @idinc
					AND (incomesorted.idsor <> @sortcode_temp OR (idsubclass <>@idsubclass))
					AND ayear=@ayear)
			,0)
			WHERE idsor = @sortcode_temp
				AND idinc = @idinc
				AND idsubclass = @idsubclass 
		END
	END
	DELETE #finsor
	FETCH NEXT FROM #income_cursor INTO @idinc
END
CLOSE #income_cursor
DEALLOCATE #income_cursor
END


GO

print '[sort_auto_allincome] OK'

GO
if object_id('rpt_bolladicarico') is not null
	drop PROCEDURE rpt_bolladicarico
go

CREATE         PROCEDURE rpt_bolladicarico(
	@yddt_in	smallint ,
	@nddt_in	varchar(10),
	@start	datetime,
	@stop	datetime,
	@idstore int
)
AS BEGIN

-- exec rpt_bolladicarico 2010,'0','ZZZ',null
DECLARE @minoplevel tinyint
SELECT @minoplevel = min(nlevel)
FROM  stocklocationlevel
WHERE (flag&2)<>0
SELECT
	D.yddt_in,
	D.nddt_in, 
	D.adate,-- data bolla
	convert(varchar(400),D.terms) as terms, -- termine di consegna
	L.intcode, -- codice articolo
	L.description as list, --- descrizione  articolo
	U.description as unit,-- unita di carico
	ISNULL(SUM(S.number),0) AS number,	-- q.tà caricata
	R.title as registry,-- fornitore
	SL1.stocklocationcode AS stocklocationcode1,
	SL1.description as stocklocation1,
	SL2.stocklocationcode AS stocklocationcode2,
	SL2.description as stocklocation2,
	SL3.stocklocationcode AS stocklocationcode3,
	SL3.description as stocklocation3,
	SL4.stocklocationcode AS stocklocationcode4,
	SL4.description as stocklocation4,
	M.description as store	
FROM ddt_in D
JOIN stock S
	ON D.idddt_in = S.idddt_in
JOIN list L
	ON L.idlist = S.idlist
JOIN unit U
	ON U.idunit = L.idunit
JOIN store M
	ON M.idstore = D.idstore	
JOIN registry R
	ON R.idreg = D.idreg
LEFT OUTER JOIN stocklocation SL4							
	ON SL4.idstocklocation = S.idstocklocation AND SL4.nlevel = @minoplevel
LEFT OUTER JOIN stocklocation SL3
	ON SL3.idstocklocation = SL4.paridstocklocation 
LEFT OUTER JOIN stocklocation SL2
	ON SL2.idstocklocation = SL3.paridstocklocation 
LEFT OUTER JOIN stocklocation SL1
	ON SL1.idstocklocation = SL2.paridstocklocation 
WHERE 
	(@nddt_in IS NULL OR  nddt_in like '%' + @nddt_in + '%')
	AND (@nddt_in IS NOT NULL OR (D.adate BETWEEN isnull(@start, convert(datetime,'01-01-'+convert(varchar(4),datepart(year,@yddt_in),105))) 
			AND 	isnull(@stop, convert(datetime,'31-12-'+convert(varchar(4),datepart(year,@yddt_in),105)))) )
	AND ( D.idstore = @idstore OR @idstore IS NULL )
	AND D.yddt_in = @yddt_in
GROUP BY 	
	D.yddt_in,
	D.nddt_in, 
	D.adate,-- data bolla
	convert(varchar(400),D.terms), -- termine di consegna
	L.intcode, -- codice articolo
	L.description, --- descrizione  articolo
	U.description,-- unita di carico
	R.title,-- fornitore
	SL1.stocklocationcode, SL1.description,
	SL2.stocklocationcode, SL2.description,
	SL3.stocklocationcode, SL3.description,
	SL4.stocklocationcode, SL4.description,
	M.description

END




GO

print 'rpt_bolladicarico OK'

GO
if object_id('[rpt_certfiscale_inps_gestsep]') is not null
	drop PROCEDURE [rpt_certfiscale_inps_gestsep]
go

CREATE      PROCEDURE [rpt_certfiscale_inps_gestsep]
	@ayear int,
	@idreg int
AS BEGIN	
	
--	 exec rpt_certfiscale_inps_gestsep 2007, 6390
 
CREATE TABLE #sendingaddress
(
	idaddresskind int,
	idreg int,
	officename varchar(50),
	sendaddress varchar(100),
	sendlocation varchar(120),
	sendcap varchar(20),
	sendprovince varchar(2),
	sendnation varchar(65)
)
CREATE TABLE #fiscaldeclaration
(
	idreg int,
	registry varchar(100),
	service varchar(50),
	causale varchar(250),
	birthdate datetime,
	b_place varchar(120),
	b_province varchar(2),
	b_nation varchar(65),
	cf varchar(16),
	cfestero varchar(40),
	taxable decimal(19,2),
	adminretension decimal(19,2),
	employretension decimal(19,2),
	amountgross decimal(19,2),
	workperiod varchar(200)
)
	
CREATE TABLE #residenceaddress
(
	idaddresskind int,
	idreg int,
	officename varchar(50),
	residaddress varchar(100),
	residlocation varchar(120),
	residcap varchar(20),
	residprovince varchar(2),
	residnation varchar(65)	
)
IF @ayear  = 0
BEGIN
	SET @ayear='1900'
END
DECLARE @filter varchar(50)
IF @idreg = 0
BEGIN
	SELECT @filter = '%'
END
ELSE
BEGIN
	SELECT @filter = title FROM registry WHERE idreg = @idreg
END
INSERT INTO #fiscaldeclaration
(
	idreg,
	registry,
	service,
	birthdate,
	b_place,
	b_province,  
	b_nation,
	cf
)
SELECT
	expense.idreg,
	registry.title,
	service.description,
	registry.birthdate,
	ISNULL(geo_city.title, '') + ' ' + ISNULL(registry.location,''),
	ISNULL(geo_country.province, ''),
	ISNULL(geo_nation.title, 'ITALIA'),
	registry.cf
FROM expense 
JOIN expenselast
	ON expense.idexp = expenselast.idexp
JOIN payment 
	ON payment.kpay = expenselast.kpay
JOIN paymenttransmission
	ON paymenttransmission.kpaymenttransmission = payment.kpaymenttransmission
JOIN service
	ON service.idser = expenselast.idser				
JOIN registry
	ON registry.idreg = expense.idreg
LEFT OUTER JOIN geo_city
	ON geo_city.idcity = registry.idcity
LEFT OUTER JOIN geo_country
	ON geo_city.idcountry = geo_country.idcountry
LEFT OUTER JOIN geo_nation
	ON geo_nation.idnation = registry.idnation
WHERE service.certificatekind = 'I' AND  
EXISTS (SELECT * FROM expensetaxofficial D 
            JOIN tax t
	      	 ON t.taxcode= D.taxcode 
           WHERE D.idexp = expense.idexp
		AND D.stop IS NULL) AND
	registry.title LIKE @filter AND 
	YEAR(paymenttransmission.transmissiondate) = @ayear
GROUP BY expense.idreg, registry.title, registry.birthdate,
	ISNULL(geo_city.title, '') + ' ' + ISNULL(registry.location,''),
	ISNULL(geo_country.province, ''), ISNULL(geo_nation.title, 'ITALIA'),
	service.description, registry.cf
	
CREATE TABLE #period
(
	idreg int,
	start datetime,
	stop datetime
)
INSERT INTO #period
SELECT
	expense.idreg,
	ISNULL(expenselast.servicestart, expense.adate),
	ISNULL(expenselast.servicestop, expense.adate)
FROM expense 
JOIN #fiscaldeclaration
        ON #fiscaldeclaration.idreg = expense.idreg
JOIN expenselast
	ON expense.idexp = expenselast.idexp
JOIN payment 
	ON payment.kpay = expenselast.kpay
JOIN paymenttransmission
	ON paymenttransmission.kpaymenttransmission = payment.kpaymenttransmission
JOIN service
	ON service.idser = expenselast.idser				
WHERE service.certificatekind = 'I' AND  
EXISTS (SELECT * FROM expensetaxofficial D 
            JOIN tax t
	      	 ON t.taxcode= D.taxcode 
           WHERE D.idexp = expense.idexp
		AND D.stop IS NULL) AND
	YEAR(paymenttransmission.transmissiondate) = @ayear
ORDER BY expense.idreg, expenselast.servicestart, expenselast.servicestop

declare @somethdone int
set @somethdone=1
while (@somethdone>0) 
BEGIN
	--cancella periodi inclusi in altri
	delete from #period where exists (select * from #period p2 where p2.idreg=#period.idreg and p2.start>#period.start and p2.stop<=#period.stop)
	delete from #period where exists (select * from #period p2 where p2.idreg=#period.idreg and p2.start>=#period.start and p2.stop<#period.stop)

	set @somethdone=0
	--concatena periodi adiacenti ad intersezione nulla
	if exists(select * from #period P1 where 
		exists(select * from #period P2 where (P1.idreg=P2.idreg and P1.start<P2.start and DATEADD(DAY, 1, P1.stop)=P2.start) )
		 )
	BEGIN
	   set @somethdone=1
	   update #period set stop= (select max(P2.stop) from #period P2 where #period.idreg=P2.idreg and
				DATEADD(DAY,1, #period.stop)=P2.start and #period.start<P2.start)
		where exists(select * from #period P2 where (#period.idreg=P2.idreg and #period.start<P2.start and DATEADD(DAY, 1, #period.stop)=P2.start) )
	END
	--concatena periodi ad intersezione non nulla
	if exists(select * from #period P1 where 
		exists(select * from #period P2 where P1.idreg=P2.idreg and P1.start<P2.start and p1.stop<p2.stop and p1.stop>=p2.start
		 	)
		)
	BEGIN
	   set @somethdone=1
	   update #period set stop= (select max(P2.stop) from #period P2 where 
				#period.idreg=P2.idreg and  #period.start<P2.start and #period.stop<p2.stop and #period.stop>=p2.start )
		where exists(select * from #period P2 where
				 #period.idreg=P2.idreg and #period.start<P2.start and #period.stop<p2.stop and #period.stop>=p2.start
		 	)
	END

END


/*


