	drop PROCEDURE verify_cap
go


CREATE    PROCEDURE verify_cap (
@idreg 	     int,
@codenostand varchar(20),
@codestand   varchar(20),
@dateindi    datetime,
@res int out
) AS
BEGIN

DECLARE @stand int
SELECT  @stand = idaddress FROM address WHERE codeaddress = @codestand
DECLARE @nostand int
SELECT  @nostand = idaddress FROM address WHERE codeaddress = @codenostand
-- Tabella utilizzata per immagazzinare gli indirizzi dei creditori debitori
CREATE TABLE #address
(
	idaddresskind int,
	idreg int,
	idcity int,
	address varchar(100),
	location varchar(116),
	cap varchar(15),
	province varchar(2),
	nation varchar(65)
)
INSERT INTO #address
(
	idaddresskind,
	idreg,
	idcity,
	address,
	location,
	cap,
	province,
	nation
)
SELECT
	idaddresskind,
	idreg, 
	geo_city.idcity,
	address,
	ISNULL(geo_city.title,'') + ' ' + ISNULL(registryaddress.location,'') ,
	registryaddress.cap,
	geo_country.province,
	CASE 
		WHEN flagforeign = 'N' THEN 'ITALIA'
		ELSE geo_nation.title
	END
FROM registryaddress
LEFT OUTER JOIN geo_city
	ON geo_city.idcity = registryaddress.idcity
LEFT OUTER JOIN geo_country
	ON geo_city.idcountry = geo_country.idcountry
LEFT OUTER JOIN geo_nation 
	ON geo_nation.idnation = registryaddress.idnation
WHERE 
(registryaddress.active <>'N' 
	AND registryaddress.start = 
	(SELECT MAX(cdi.start) 
	FROM registryaddress cdi 
	WHERE cdi.idaddresskind = registryaddress.idaddresskind
		AND cdi.active <>'N' 
		AND ((cdi.stop IS NULL) OR (cdi.stop >= @dateindi))
		AND cdi.idreg = registryaddress.idreg))
		AND idreg = @idreg
DELETE #address
WHERE  #address.idaddresskind <> @nostand
       AND EXISTS(
		SELECT * FROM #address r2 
		WHERE #address.idreg = r2.idreg
		AND r2.idaddresskind = @nostand
	)
DELETE #address
WHERE  #address.idaddresskind NOT IN (@nostand, @stand)
       AND EXISTS(
		SELECT * FROM #address r2 
		WHERE #address.idreg = r2.idreg
		AND r2.idaddresskind = @stand
	)
DELETE #address
WHERE (
	SELECT COUNT(*) FROM #address r2 
	WHERE #address.idreg = r2.idreg
)>1

-- CONTROLLO N. 11 Ogni beneficiario deve avere un indirizzo con CAP valido associato
IF EXISTS
( 
	SELECT * FROM #address ind 
	   JOIN geo_city_agency geo 
	     ON  geo.value = ind.cap
	    AND geo.idcity = ind.idcity
	  WHERE  ind.nation = 'ITALIA' 
	    AND  geo.idagency = 3 
	    AND  geo.stop IS NOT NULL
)
BEGIN
	SET @res = 1 --errore
END
ELSE
BEGIN
	SET @res = 0 --ok
END
print @res
END


GO

print 'verify_cap OK'

