go

CREATE     PROCEDURE [rpt_articolisottoscorta]
	@idlist int,
	@idstore int
AS
BEGIN
/*
Giacenza  
Prenotazioni(booked) 
Disponibilità residua(giancenza - prenotazioni)  
Scorta prevista  = list.nmin 
Q.tà Riordino  = list.ntoreorder
Q.tà ordinata e ancora inevasa(q.tà inevasa)
se e solo se 
giacenza + ordini inevasi < is null(scota minima prevista ,0)
*/

CREATE TABLE #Listino(
	idlist int,
	idstore int,
	residual decimal(38,2), -- Giacenza
	totalresidual decimal(38,2),-- Totale Giacenza riferito al listino
	booked decimal(19,2),	-- Q.tà richiesta = Prenotazione
	ntostock decimal(38,2),	-- Q.tà inevasa	 
	totalntostock decimal(38,2)	-- Totale ordini inevasi, riferito al listino
)
-- Giacenza in Magazzino
INSERT INTO #Listino(
	idlist,
	idstore,	
	residual
)
SELECT 
	S.idlist,
	S.idstore,
	S.residual	--> 'Giacenza'
from stockview S 
where ( S.idlist = @idlist OR @idlist is null )
	AND (S.idstore = @idstore OR @idstore is null)
	AND residual>0
order by S.store asc, S.residual desc
-- Prenotazioni inevase
INSERT INTO #Listino(
	idlist,
	idstore,
	booked
)
SELECT 
	B.idlist,
	B.idstore,
	B.booked		--> 'Q.tà richiesta'= Prenotazione
FROM booktotalview B
WHERE ( B.idlist = @idlist OR @idlist is null)
	AND (B.idstore = @idstore OR @idstore is null)
	AND number > 0
order by store asc,allocated desc
-- Ordini inevasi
INSERT INTO #Listino(
	idlist,
	idstore,
	ntostock
)
SELECT 
	idlist,
	idstore,
	ntostock	--> 'Q.tà inevasa'	
FROM mandatedetail_tostock M
WHERE ( M.idlist = @idlist OR @idlist is null)
	AND (M.idstore = @idstore OR @idstore is null)
	AND ntostock > 0
ORDER BY store asc,ntostock desc

UPDATE #Listino SET totalntostock = (select sum(M2.ntostock) FROM	mandatedetail_tostock M2 
			where M2.idlist = #Listino.idlist AND M2.ntostock > 0)
UPDATE #Listino SET totalresidual = (select sum(R2.residual) from stockview R2 
				where R2.idlist = #Listino.idlist AND R2.residual > 0)

SELECT 
	T.idlist,
	L.intcode,
	L.description as list,
	T.idstore,
	S.description as store,
	isnull(L.nmin, 0) as nmin,-- as 'Scorta minima',
	isnull(L.ntoreorder,0) as ntoreorder,-- as 'Q.tà Riordino',
	isnull(sum(T.residual),0) as residual,-- as  'Giacenza', 
	isnull(sum(T.booked),0) as booked  ,-- as 'Prenotazioni',
	isnull(sum(T.ntostock),0) as ntostock --as 'Q.tà inevasa' 
FROM #listino T
JOIN list L
	ON T.idlist = L.idlist
JOIN store S
	ON S.idstore = T.idstore
GROUP BY T.idlist,L.intcode,L.description,	T.idstore,	S.description,L.nmin,L.ntoreorder,
	T.totalresidual, T.totalntostock
-- SE giacenza + ordini inevasi < Scorta minima prevista
HAVING (isnull(T.totalresidual,0) + isnull(T.totalntostock,0))	<	isnull(L.nmin,0)

DROP TABLE #Listino


END


GO

print '[rpt_articolisottoscorta] OK'

