if object_id('[rpt_articolisottoscorta_dettgiacenza]') is not null
	drop PROCEDURE [rpt_articolisottoscorta_dettgiacenza]
go

CREATE     PROCEDURE [rpt_articolisottoscorta_dettgiacenza]
	@idlist int,
	@idstore int
AS
BEGIN
CREATE TABLE #dettagliogiacenza(
	idlist int,
	idstore int,
	residual decimal(38,2), -- Giacenza
	unit varchar(50),		-- unita di misura
	amount decimal(19,5),	-- costo unitario
	amount_p decimal(19,2)	-- Costo confezione
)
-- Giacenza in Magazzino
INSERT INTO #dettagliogiacenza(
	idlist,
	idstore,
	residual, -- Giacenza
	unit,		-- unita di misura
	amount,	-- costo unitario
	amount_p	-- Costo confezione
)
SELECT 
	S.idlist,
	S.idstore,
	residual,
	unit,
	ROUND((S.amount/S.number),5),
	ROUND((S.amount/S.number)*L.unitsforpackage,2)
from stockview S 
join list L 
	on S.idlist = L.idlist 
where ( S.idlist = @idlist OR @idlist is null )
	AND (S.idstore = @idstore OR @idstore is null)
	AND residual>0

SELECT 
	T.idlist,
	T.idstore,
	S.description as store,
	isnull(residual,0) as residual, -- Giacenza
	isnull(unit,0) as unit,		-- unita di misura
	isnull(amount,0) as amount,	-- costo unitario
	isnull(amount_p,0)	 as amount_p-- Costo confezione
FROM #dettagliogiacenza T
JOIN store S
	ON S.idstore = T.idstore
DROP TABLE #dettagliogiacenza


END


GO

print '[rpt_articolisottoscorta_dettgiacenza] OK'

