if object_id('[allineaADestra]') is not null
	drop procedure [allineaADestra]
go

CREATE                                                     procedure [allineaADestra](@stringa varchar(150), @lunghezza int, @result varchar(150) output)
AS
BEGIN
	declare @lenstr int
	set @lenStr=len(@stringa)
	if (@lenStr>@lunghezza) 
	begin 
		set @result = substring(@stringa,1,@lunghezza)
	end else begin
		set @result = space(@lunghezza-@lenStr)+@stringa
	end
END


