if object_id('[trigger_u_sortingprevexpensevar]') is not null
	drop TRIGGER [trigger_u_sortingprevexpensevar]
go

CREATE             TRIGGER [trigger_u_sortingprevexpensevar] ON [sortingprevexpensevar] FOR UPDATE
AS BEGIN
	IF UPDATE(idsor) OR
	UPDATE(amount)
	BEGIN
		DECLARE @ayear int
		DECLARE @newidsor int
		DECLARE @newamount decimal(19,2)
		DECLARE @oldidsor int
		DECLARE @oldamount decimal(19,2)
	
		SELECT
			@newidsor = idsor, 
			@ayear = ayear, 
			@newamount = amount
		FROM inserted
	
		SELECT
			@oldidsor = idsor,
			@oldamount = -amount
		FROM deleted
	
		EXECUTE trg_upd_sorttotal 
		@newidsor, 
		@ayear, 
		'totexpensevariation', 
		@newamount
	
		EXECUTE trg_upd_sorttotal 
		@oldidsor, 
		@ayear, 
		'totexpensevariation', 
		@oldamount
	END
END


