if object_id('[rpt_articolisottoscorta_dettOrdiniInevasi]') is not null
	drop PROCEDURE [rpt_articolisottoscorta_dettOrdiniInevasi]
go

CREATE     PROCEDURE [rpt_articolisottoscorta_dettOrdiniInevasi]
	@idlist int,
	@idstore int
AS
BEGIN
CREATE TABLE #dettOrdiniInevasi(
	idlist int,
	idstore int,
	adate smalldatetime,	-- Data Ordine
	registry varchar(100),	-- Fornitore
	ordered decimal(19,2),	-- Q.tà Ordinata
	ntostock decimal(38,2), -- Q.tà inevasa
	npackage decimal(19,2)	-- N.confezioni
)

-- Ordini inevasi
INSERT INTO #dettOrdiniInevasi(
	idlist,
	idstore,
	adate ,		-- Data Ordine
	registry,	-- Fornitore
	ordered,	-- Q.tà Ordinata
	ntostock,	-- Q.tà inevasa
	npackage	-- N.confezioni
)
SELECT 
	idlist,
	idstore,
	adate ,		-- Data Ordine
	registry,	-- Fornitore
	ordered,	-- Q.tà Ordinata
	ntostock,	-- Q.tà inevasa
	npackage	-- N.confezioni
FROM mandatedetail_tostock
WHERE ( idlist = @idlist OR @idlist is null )
	AND (idstore = @idstore OR @idstore is null)
	AND ntostock > 0

SELECT 
	idlist,
	T.idstore,
	S.description as store,
	adate ,		-- Data Ordine
	registry,	-- Fornitore
	isnull(ordered,0) as ordered,	-- Q.tà Ordinata
	isnull(ntostock,0) as ntostock,	-- Q.tà inevasa
	isnull(npackage,0) as npackage	-- N.confezioni
FROM #dettOrdiniInevasi T
JOIN store S
	ON S.idstore = T.idstore

DROP TABLE #dettOrdiniInevasi


END


