if object_id('[trigger_u_finvar]') is not null
	drop TRIGGER [trigger_u_finvar]
go

CREATE TRIGGER [trigger_u_finvar] ON [finvar] FOR UPDATE
AS BEGIN
	IF UPDATE(flagprevision)
	OR UPDATE(flagsecondaryprev)
	OR UPDATE(flagcredit)
	OR UPDATE(flagproceeds)
	OR UPDATE(idfinvarstatus)
	BEGIN
		DECLARE @yvar int
		DECLARE @nvar int
		DECLARE @variationkind tinyint
		DECLARE @oldflagprevision char(1)
		DECLARE @oldflagsecondaryprev char(1)
		DECLARE @oldflagcredit char(1)
		DECLARE @oldflagproceeds char(1)
		DECLARE @newflagprevision char(1)
		DECLARE @newflagsecondaryprev char(1)
		DECLARE @newflagcredit char(1)
		DECLARE @newflagproceeds char(1)
		DECLARE @oldidfinvarstatus smallint
		DECLARE @newidfinvarstatus smallint
   		SELECT 
		@yvar = yvar,
		@nvar = nvar,
		@variationkind = ISNULL(variationkind,0),
		@newflagprevision = ISNULL(flagprevision,'N'),
		@newflagsecondaryprev = ISNULL(flagsecondaryprev,'N'),
		@newflagcredit = ISNULL(flagcredit,'N'),
		@newflagproceeds = ISNULL(flagproceeds,'N'),
		@newidfinvarstatus = ISNULL(idfinvarstatus,0)
		FROM inserted
		if (@newidfinvarstatus<>5) BEGIN
			SET @newflagprevision='N'
			SET @newflagsecondaryprev='N'
			SET @newflagcredit='N'
			SET @newflagproceeds='N'
		END
		SELECT
		@oldflagprevision = ISNULL(flagprevision,'N'),
		@oldflagsecondaryprev = ISNULL(flagsecondaryprev,'N'),
		@oldflagcredit = ISNULL(flagcredit,'N'),
		@oldflagproceeds = ISNULL(flagproceeds,'N'),
		@oldidfinvarstatus = ISNULL(idfinvarstatus,0)
		FROM deleted
		if (@oldidfinvarstatus<>5) BEGIN
			SET @oldflagprevision='N'
			SET @oldflagsecondaryprev='N'
			SET @oldflagcredit='N'
			SET @oldflagproceeds='N'
		END
		if (@newflagprevision='S' and @oldflagprevision='N') BEGIN
			update lcardtotal set lcardtotal.amount= lcardtotal.amount - finvardetail.amount
				from lcardtotal join
				finvardetail on finvardetail.idlcard= lcardtotal.idlcard
				where finvardetail.yvar=@yvar
				  and 
				  finvardetail.nvar=@nvar
				and finvardetail.idlcard is not null
		END
		if (@newflagprevision='N' and @oldflagprevision='S') BEGIN
			update lcardtotal set lcardtotal.amount= lcardtotal.amount + finvardetail.amount
				from lcardtotal join
				finvardetail on finvardetail.idlcard= lcardtotal.idlcard
				where finvardetail.yvar=@yvar
				  and 
				  finvardetail.nvar=@nvar
				and finvardetail.idlcard is not null
		END
		DECLARE @idfindetail int
		DECLARE @idupbdetail varchar(36)
		DECLARE @idunderwritingdetail int
		DECLARE @amountdetail decimal(19,2)
		DECLARE @finpart char(1)
		
		
		DECLARE #dettaglio INSENSITIVE CURSOR FOR
		SELECT finvardetail.idfin,finvardetail.idupb,finvardetail.idunderwriting,finvardetail.amount,
				CASE		when (( fin.flag & 1)=0) then 'E'
									when (( fin.flag & 1)=1) then 'S'
						End 
				FROM finvardetail 
				join fin on finvardetail.idfin=fin.idfin
				WHERE yvar = @yvar AND nvar = @nvar
		FOR READ ONLY
		OPEN #dettaglio
		FETCH NEXT FROM #dettaglio INTO @idfindetail, @idupbdetail, @idunderwritingdetail,@amountdetail,@finpart
		WHILE(@@FETCH_STATUS = 0)
		BEGIN
			DECLARE @lessamountdetail decimal(19,2)
			SET @lessamountdetail = -@amountdetail
			-- Cambio FLAGPREVISION
			IF (@variationkind <>5)
				BEGIN
				IF (@oldflagprevision <> @newflagprevision) 
				BEGIN
					IF (@newflagprevision = 'N') 
					BEGIN			
						EXEC trg_upd_upbtotal 	@idfindetail ,	@idupbdetail, 'previsionvariation',	@lessamountdetail
						
					IF (@idunderwritingdetail IS NOT NULL)
					BEGIN
						EXECUTE trg_upd_upbunderwritingtotal 	@idfindetail,	@idupbdetail,	@idunderwritingdetail,
							'previsionvariation',	@lessamountdetail
					END	
				END
					ELSE --(@newflagprevision = 'S')
					BEGIN
						EXEC trg_upd_upbtotal 	@idfindetail,	@idupbdetail,'previsionvariation',	@amountdetail
						
						IF (@idunderwritingdetail IS NOT NULL)
						BEGIN
							EXECUTE trg_upd_upbunderwritingtotal 	@idfindetail,@idupbdetail,	@idunderwritingdetail,
									'previsionvariation',	@amountdetail
						END	
					END
					END
			END
			IF (@variationkind = 5)
				BEGIN
				IF (@oldflagprevision <> @newflagprevision)
					BEGIN
					IF (@newflagprevision = 'N') 
					BEGIN
					IF (@idunderwritingdetail IS NOT NULL)
					BEGIN
						EXECUTE trg_upd_upbunderwritingtotal @idfindetail,	@idupbdetail,@idunderwritingdetail,	'currentprev',	@lessamountdetail
					END	
				END
					ELSE --(@newflagprevision = 'S')
					BEGIN
						IF (@idunderwritingdetail IS NOT NULL)
						BEGIN
							EXECUTE trg_upd_upbunderwritingtotal 	@idfindetail,	@idupbdetail,@idunderwritingdetail,	'currentprev',@amountdetail
						END	
					END
				END
			END
			
			
			-- Cambio FLAGSECONDARYPREV
			IF (@variationkind <>5) AND  (@oldflagsecondaryprev <> @newflagsecondaryprev)
			BEGIN
				IF (@newflagsecondaryprev = 'N')
				BEGIN
					EXEC trg_upd_upbtotal		@idfindetail,@idupbdetail,'secondaryvariation',@lessamountdetail				
					IF (@idunderwritingdetail IS NOT NULL)
					BEGIN
						EXECUTE trg_upd_upbunderwritingtotal 	@idfindetail,@idupbdetail,@idunderwritingdetail,'secondaryvariation',@lessamountdetail
					END	
				
				END
				ELSE --(@newflagsecondaryprev = 'S')
				BEGIN
					EXEC trg_upd_upbtotal	@idfindetail ,	@idupbdetail,'secondaryvariation',	@amountdetail
					
					IF (@idunderwritingdetail IS NOT NULL)
					BEGIN
						EXECUTE trg_upd_upbunderwritingtotal @idfindetail,	@idupbdetail,@idunderwritingdetail,	'secondaryvariation',	@amountdetail
					END	
				END
			END
			
			
		
			
			IF (@variationkind = 5)AND (@oldflagsecondaryprev <> @newflagsecondaryprev) 
			BEGIN
				IF (@newflagsecondaryprev = 'N')
				BEGIN
				
					IF (@idunderwritingdetail IS NOT NULL)
					BEGIN
						EXECUTE trg_upd_upbunderwritingtotal @idfindetail,@idupbdetail,@idunderwritingdetail,'currentsecondaryprev',@lessamountdetail
					END	
				END
				ELSE --(@newflagprevision = 'S')
				BEGIN
					IF (@idunderwritingdetail IS NOT NULL)
					BEGIN
						EXECUTE trg_upd_upbunderwritingtotal 	@idfindetail,@idupbdetail,	@idunderwritingdetail,'currentsecondaryprev',@amountdetail
					
					END	
				END				
			END
			
			
			-- Cambio FLAGCREDIT
			IF (@oldflagcredit <> @newflagcredit  and @finpart='S' and (@variationkind <> 5))
			BEGIN
				IF (@newflagcredit = 'N')
				BEGIN
					EXEC trg_upd_upbtotal	@idfindetail,	@idupbdetail,	'creditvariation',	@lessamountdetail
					
					IF (@idunderwritingdetail IS NOT NULL)
					BEGIN
						EXECUTE trg_upd_upbunderwritingtotal @idfindetail,@idupbdetail,@idunderwritingdetail,'creditvariation',	@lessamountdetail
					END	
				END
				ELSE --(@newflagcredit = 'S')
				BEGIN
				
					EXEC trg_upd_upbtotal	@idfindetail,@idupbdetail,'creditvariation',@amountdetail					
					IF (@idunderwritingdetail IS NOT NULL)
					BEGIN
						EXECUTE trg_upd_upbunderwritingtotal 	@idfindetail,	@idupbdetail,@idunderwritingdetail,	'creditvariation',	@amountdetail
					END	
				END
			END
			
			
			-- Cambio FLAGPROCEEDS
			IF (@oldflagproceeds <> @newflagproceeds and @finpart='S' and (@variationkind <> 5))
			BEGIN
				IF (@newflagproceeds = 'N')
				BEGIN
					EXEC trg_upd_upbtotal @idfindetail, @idupbdetail,'proceedsvariation',	@lessamountdetail
					
					IF (@idunderwritingdetail IS NOT NULL)
					BEGIN
						EXECUTE trg_upd_upbunderwritingtotal @idfindetail,@idupbdetail,	@idunderwritingdetail,'proceedsvariation',	@lessamountdetail
					END	
				END
				ELSE --(@newflagproceeds = 'S')
				BEGIN
					EXEC trg_upd_upbtotal @idfindetail ,@idupbdetail,'proceedsvariation',@amountdetail
					
					IF (@idunderwritingdetail IS NOT NULL)
					BEGIN
						EXECUTE trg_upd_upbunderwritingtotal 	@idfindetail,@idupbdetail,@idunderwritingdetail,	'proceedsvariation',@amountdetail
					END	
				END
			END
			
			FETCH NEXT FROM #dettaglio INTO @idfindetail,@idupbdetail,@idunderwritingdetail,@amountdetail,@finpart
		END
		CLOSE #dettaglio
		DEALLOCATE #dettaglio
	END
END

GO

print '[trigger_u_finvar] OK'

GO
if object_id('[closeyear_asset_ammortization]') is not null
	drop PROCEDURE [closeyear_asset_ammortization]
go

CREATE PROCEDURE [closeyear_asset_ammortization]
(
	@ayear int,
	@buonoscarico char(1) = 'S'
)
AS BEGIN
--la stored procedure GetAssetValue è usata per valutare l'importo corrente dei cespiti
--la stored procedure get_originalassetvalue è usata per valutare l'importo iniziale dei cespiti, su cui calcolare l'ammortamento
-- se l'ammortamento calcolato è tale da rendere il valore corrente viene considerata una base per l'ammortamento opportunamente ridotta
--   in modo da far si che l'aliquota di ammortamento per la base di ammortamento vada ad azzerare il valore residuo del cespite
DECLARE @dec_31 datetime
SELECT  @dec_31 = CONVERT(datetime, '31-12-' + CONVERT(char(4), @ayear), 105)
DECLARE @namortization int
SELECT  @namortization = ISNULL((SELECT MAX(namortization) FROM assetamortization),0) + 1
DECLARE @idinventoryamortization int
DECLARE @idasset int
DECLARE @idpiece int
DECLARE @description varchar(150)
DECLARE @assetvalue decimal(19,2)
DECLARE @amortizationquota float
DECLARE @actualvalue decimal(19,2)
DECLARE @reval decimal(19,2)
declare @startvalue decimal(19,2)
-- Caso in cui il cespite ha data di inizio esistenza a NULL
-- Applico tutte le rivalutazioni UFFICIALI che nell'anno sono associate alla classificazione del cespite e che hanno ETA NULL
DECLARE amt_crs INSENSITIVE CURSOR FOR
SELECT  DISTINCT
	tr.idinventoryamortization,
	b.idasset,	b.idpiece,
	c.description,
	coalesce(t4.amortizationquota,t3.amortizationquota,t2.amortizationquota,t1.amortizationquota)
FROM asset b
JOIN assetacquire c
	ON b.nassetacquire = C.nassetacquire
JOIN assetview_current ac
	ON ac.idasset = b.idasset and ac.idpiece=b.idpiece
JOIN assetload
	ON assetload.idassetload = c.idassetload			
LEFT OUTER JOIN assetunload AU
	ON AU.idassetunload = B.idassetunload
	
LEFT OUTER JOIN inventorytreelink IL1  
    	ON IL1.idchild = C.idinv AND IL1.nlevel  = 1 
LEFT OUTER JOIN inventorytreelink IL2  
    	ON IL2.idchild = C.idinv  AND IL2.nlevel = 2
LEFT OUTER JOIN inventorytreelink IL3 
    	ON IL3.idchild = C.idinv  AND IL3.nlevel = 3 
LEFT OUTER JOIN inventorytreelink IL4  
    	ON IL4.idchild = C.idinv  AND IL4.nlevel = 4 
LEFT OUTER JOIN inventorysortingamortizationyear t1
	ON t1.idinv = IL1.idparent AND t1.ayear = @ayear
LEFT OUTER JOIN inventorysortingamortizationyear t2
	ON t2.idinv = IL2.idparent  AND t2.ayear = @ayear
LEFT OUTER JOIN inventorysortingamortizationyear t3
	ON t3.idinv = IL3.idparent AND t3.ayear = @ayear
LEFT OUTER JOIN inventorysortingamortizationyear t4
	ON t4.idinv = IL4.idparent AND t4.ayear = @ayear 
JOIN inventoryamortization tr
	ON tr.idinventoryamortization = COALESCE(t4.idinventoryamortization,t3.idinventoryamortization,t2.idinventoryamortization,t1.idinventoryamortization)
WHERE   b.lifestart IS NULL
	AND (tr.flag & 2 <> 0) --ufficiale
	AND tr.age IS NULL
	AND ISNULL(tr.active,'S')= 'S'
	AND (b.flag & 1 <> 0)
	AND NOT EXISTS(
		SELECT * FROM assetamortization r
		WHERE r.idasset = b.idasset AND r.idpiece = b.idpiece
			AND YEAR(r.adate) = @ayear)
	AND	((tr.valuemin is null or tr.valuemin<ISNULL(C.historicalvalue,AC.start) ) and (tr.valuemax is null or tr.valuemax>=ISNULL(C.historicalvalue,AC.start)))
	AND YEAR(assetload.ratificationdate)<=@ayear
	AND (AU.adate is null OR YEAR(AU.adate)>@ayear )
FOR READ ONLY
OPEN amt_crs
FETCH NEXT FROM amt_crs INTO @idinventoryamortization, @idasset, @idpiece, @description, @amortizationquota
WHILE (@@FETCH_STATUS = 0)
BEGIN
	execute get_assetvalueatdate @idasset,@idpiece, @dec_31, @assetvalue OUTPUT, @actualvalue OUTPUT 
	--@assetvalue valore ORIGINALE alla data del 31 12 dell'anno
	--@actualvalue valore ATTUALE alla data del 31 12 dell'anno
    if @actualvalue > 0  
	BEGIN
	
		SET @reval=ROUND(ISNULL(@assetvalue, 0.0) * ISNULL(@amortizationquota,0.0) ,2)
		-- Viene sostituito il precedente controllo (@reval > @actualvalue) in quanto @reval nel caso di ammortamenti
		-- è negativo! Quindi la somma algebrica dei due importi deve essere sempre >=0
		IF ( (@reval + @actualvalue) < 0) 
		BEGIN
			SET @amortizationquota  = -@actualvalue/@assetvalue
		END
		SET @reval = ROUND(ISNULL(@assetvalue, 0.0) * ISNULL(@amortizationquota,0.0) ,2) 
		if (@reval <>0) 
		BEGIN
		
			SELECT @namortization = ISNULL((SELECT MAX(namortization) FROM assetamortization),0) + 1
			INSERT INTO assetamortization
				(namortization,	idinventoryamortization,
				idasset,	idpiece,
				description,
				assetvalue,		amortizationquota,
					adate,flag,
				cu, ct, lu, lt
				)
    		VALUES
			( 	@namortization,	@idinventoryamortization,
				@idasset,		@idpiece,
				@description,
				@assetvalue,
				@amortizationquota,
				@dec_31,
				CASE WHEN @buonoscarico='N' THEN 0	ELSE 1		END,
				'GENER.AUTO', GETDATE(), '''GENER.AUTO''', GETDATE()
			)
		
		END
	END
	FETCH NEXT FROM amt_crs INTO @idinventoryamortization, @idasset, @idpiece, @description, @amortizationquota
END
DEALLOCATE amt_crs
-- Caso in cui il cespite ha la data di inizio esistenza NOT NULL 
-- Applico tutte le rivalutazioni UFFICIALI che nell'anno sono associate alla classificazione cespite con età pari alla differenza tra l'anno
-- di acquisizione del cespite e la data contabile
-- In questo caso prima di effettuare le rivalutazioni controllo se ci sono rivalutazioni che hanno il campo ETA' valorizzato,
-- in caso negativo provo ad effettuare rivalutazioni senza ETA' (costanti nel tempo)
IF 
(SELECT COUNT(*)
FROM inventoryamortization I
JOIN inventorysortingamortizationyear A
	ON I.idinventoryamortization = A.idinventoryamortization
WHERE (I.flag & 2 <> 0) AND I.age IS NOT NULL AND A.ayear = @ayear AND ISNULL(I.active,'S')= 'S') > 0
BEGIN
	-- Considero i tipi di rivalutazioni 'ANNUALI' 
	DECLARE amt_crs INSENSITIVE CURSOR FOR
	SELECT  DISTINCT
		tr.idinventoryamortization,	b.idasset,	b.idpiece,
		c.description,
		coalesce(t4.amortizationquota,t3.amortizationquota,t2.amortizationquota,t1.amortizationquota)
	FROM asset b
	JOIN assetacquire c	
		ON b.nassetacquire = C.nassetacquire
	JOIN assetview_current ac
		ON ac.idasset = b.idasset and ac.idpiece=b.idpiece
	JOIN assetload
		ON assetload.idassetload = c.idassetload		
	LEFT OUTER JOIN assetunload AU
		ON AU.idassetunload = B.idassetunload
			
	LEFT OUTER JOIN inventorytreelink IL1  
    		ON IL1.idchild = C.idinv AND IL1.nlevel  = 1 
	LEFT OUTER JOIN inventorytreelink IL2  
	    	ON IL2.idchild = C.idinv  AND IL2.nlevel = 2
	LEFT OUTER JOIN inventorytreelink IL3 
	    	ON IL3.idchild = C.idinv  AND IL3.nlevel = 3 
	LEFT OUTER JOIN inventorytreelink IL4  
	    	ON IL4.idchild = C.idinv  AND IL4.nlevel = 4 
	LEFT OUTER JOIN inventorysortingamortizationyear t1
		ON t1.idinv = IL1.idparent AND t1.ayear = @ayear
	LEFT OUTER JOIN inventorysortingamortizationyear t2
		ON t2.idinv = IL2.idparent  AND t2.ayear = @ayear
	LEFT OUTER JOIN inventorysortingamortizationyear t3
		ON t3.idinv = IL3.idparent AND t3.ayear = @ayear
	LEFT OUTER JOIN inventorysortingamortizationyear t4
		ON t4.idinv = IL4.idparent AND t4.ayear = @ayear 
	JOIN inventoryamortization tr
		ON tr.idinventoryamortization = COALESCE(t4.idinventoryamortization,t3.idinventoryamortization,t2.idinventoryamortization,t1.idinventoryamortization)
	WHERE   b.lifestart IS NOT NULL AND b.lifestart <= @dec_31
		AND (tr.flag & 2 <> 0)		--ufficiale
		AND ISNULL(tr.active,'S')= 'S'
		AND tr.age <= (DATEPART(YEAR,@dec_31) - DATEPART(YEAR,b.lifestart)) + 1
		AND tr.agemax >= (DATEPART(YEAR,@dec_31) - DATEPART(YEAR,b.lifestart)) + 1
		AND (tr.flag & 1 = 0)	--annuale
		and (b.flag & 1 <> 0)
		AND NOT EXISTS(
			SELECT * FROM assetamortization r
					WHERE r.idasset = b.idasset AND r.idpiece = b.idpiece
					AND YEAR(r.adate) = @ayear)
		AND	((tr.valuemin is null or tr.valuemin<ISNULL(C.historicalvalue,AC.start) ) and (tr.valuemax is null or tr.valuemax>=ISNULL(C.historicalvalue,AC.start)))
		AND YEAR(assetload.ratificationdate)<=@ayear
		AND (AU.adate is null OR YEAR(AU.adate)>@ayear )		
		
	FOR READ ONLY
	OPEN amt_crs
	FETCH NEXT FROM amt_crs INTO @idinventoryamortization, @idasset, @idpiece, @description, @amortizationquota
	
	WHILE (@@FETCH_STATUS = 0)
	BEGIN
		execute get_assetvalueatdate @idasset,@idpiece, @dec_31, @assetvalue OUTPUT, @actualvalue OUTPUT 
		--@assetvalue valore ORIGINALE alla data del 31 12 dell'anno
		--@actualvalue valore ATTUALE alla data del 31 12 dell'anno
		if @actualvalue > 0 
		BEGIN
			SET @reval=ROUND(ISNULL(@assetvalue, 0.0) * ISNULL(@amortizationquota,0.0) ,2)
			IF   ((@reval + @actualvalue) < 0) 
			BEGIN
				SET @amortizationquota  = -@actualvalue/@assetvalue
			END
			
			SET @reval = ROUND(ISNULL(@assetvalue, 0.0) * ISNULL(@amortizationquota,0.0) ,2) 
			if (@reval <>0) 
			BEGIN
				SELECT @namortization = ISNULL((SELECT MAX(namortization) FROM assetamortization),0) + 1
				INSERT INTO assetamortization
				(
					namortization,	idinventoryamortization,
					idasset,	idpiece,
					description,
					assetvalue,	amortizationquota,
					adate,flag,
					cu, ct, lu, lt
				)
				VALUES
				(
					@namortization,	@idinventoryamortization,
					@idasset,	@idpiece,
					@description,
					@assetvalue,@amortizationquota,
					@dec_31,
					CASE  when @buonoscarico='N' THEN 0		ELSE 1		END,
					'GENER.AUTO', GETDATE(), '''GENER.AUTO''', GETDATE()
				)
			END
		END
		
		FETCH NEXT FROM amt_crs INTO @idinventoryamortization, @idasset, @idpiece, @description, @amortizationquota
	END
	DEALLOCATE amt_crs

	-- CONSIDERO I TIPI DI RIVALUTAZIONI MENSILI
	DECLARE amt_crs INSENSITIVE CURSOR FOR
	SELECT DISTINCT
		tr.idinventoryamortization,	b.idasset,	b.idpiece,
		c.description,
		ISNULL(t4.amortizationquota,ISNULL(t3.amortizationquota,
	    	ISNULL(t2.amortizationquota,t1.amortizationquota))) /12 *
		CASE 
			WHEN DATEPART(YEAR,b.lifestart) = @ayear THEN DATEPART(MONTH,@dec_31) - DATEPART(MONTH,b.lifestart) + 1
			WHEN DATEPART(YEAR,b.lifestart) < @ayear THEN 12
		END
	FROM asset b
	JOIN assetacquire c
		ON b.nassetacquire = c.nassetacquire
	JOIN assetview_current ac
		ON ac.idasset = b.idasset and ac.idpiece=b.idpiece
	JOIN assetload
		ON assetload.idassetload = c.idassetload			
	LEFT OUTER JOIN assetunload AU
		ON AU.idassetunload = B.idassetunload		
	LEFT OUTER JOIN inventorytreelink IL1  
    		ON IL1.idchild = C.idinv AND IL1.nlevel  = 1 
	LEFT OUTER JOIN inventorytreelink IL2  
	    	ON IL2.idchild = C.idinv  AND IL2.nlevel = 2
	LEFT OUTER JOIN inventorytreelink IL3 
	    	ON IL3.idchild = C.idinv  AND IL3.nlevel = 3 
	LEFT OUTER JOIN inventorytreelink IL4  
	    	ON IL4.idchild = C.idinv  AND IL4.nlevel = 4 
	LEFT OUTER JOIN inventorysortingamortizationyear t1
		ON t1.idinv = IL1.idparent AND t1.ayear = @ayear
	LEFT OUTER JOIN inventorysortingamortizationyear t2
		ON t2.idinv = IL2.idparent  AND t2.ayear = @ayear
	LEFT OUTER JOIN inventorysortingamortizationyear t3
		ON t3.idinv = IL3.idparent AND t3.ayear = @ayear
	LEFT OUTER JOIN inventorysortingamortizationyear t4
		ON t4.idinv = IL4.idparent AND t4.ayear = @ayear 
	JOIN inventoryamortization tr
		ON tr.idinventoryamortization = COALESCE(t4.idinventoryamortization,t3.idinventoryamortization,t2.idinventoryamortization,t1.idinventoryamortization)
	WHERE 
		b.lifestart IS NOT NULL AND b.lifestart <= @dec_31
		AND (tr.flag & 2 <> 0) --ufficiale
		AND ISNULL(tr.active,'S')= 'S'
		AND tr.age <= (DATEPART(YEAR,@dec_31) - DATEPART(YEAR,b.lifestart)) + 1
		AND tr.agemax >= (DATEPART(YEAR,@dec_31) - DATEPART(YEAR,b.lifestart)) + 1
		AND (tr.flag & 1 <> 0)
		AND (b.flag & 1 <> 0)
		AND NOT EXISTS(
			SELECT * FROM assetamortization r
					WHERE r.idasset = b.idasset AND r.idpiece = b.idpiece
					AND YEAR(r.adate) = @ayear)
		AND	((tr.valuemin is null or tr.valuemin<ISNULL(C.historicalvalue,AC.start) ) and (tr.valuemax is null or tr.valuemax>=ISNULL(C.historicalvalue,AC.start) ))
		AND YEAR(assetload.ratificationdate)<=@ayear
		AND (AU.adate is null OR YEAR(AU.adate)>@ayear )
	FOR READ ONLY
	OPEN amt_crs
		FETCH NEXT FROM amt_crs INTO @idinventoryamortization, @idasset, @idpiece, @description, @amortizationquota
	WHILE (@@FETCH_STATUS = 0)
	BEGIN
		execute get_assetvalueatdate @idasset,@idpiece, @dec_31, @assetvalue OUTPUT, @actualvalue OUTPUT 
		--@assetvalue valore ORIGINALE alla data del 31 12 dell'anno
		--@actualvalue valore ATTUALE alla data del 31 12 dell'anno
		
		if @actualvalue > 0 
		BEGIN
			SET @reval=ROUND(ISNULL(@assetvalue, 0.0) * ISNULL(@amortizationquota,0.0) ,2)
			IF ((@reval + @actualvalue) < 0) 
			BEGIN
				SET @amortizationquota  = -@actualvalue/@assetvalue
			END
			
			SET @reval = ROUND(ISNULL(@assetvalue, 0.0) * ISNULL(@amortizationquota,0.0) ,2) 
			if (@reval <>0) 
			BEGIN
				SELECT @namortization = ISNULL((SELECT MAX(namortization) FROM assetamortization),0) + 1
				INSERT INTO assetamortization
					(namortization,	idinventoryamortization,
					idasset,idpiece,
					description,
					assetvalue,	amortizationquota,
					adate,flag,
					cu, ct, lu, lt
					)
				VALUES
					(@namortization,@idinventoryamortization,
						@idasset,@idpiece,
						@description,
						@assetvalue,@amortizationquota,
						@dec_31,
						CASE  when @buonoscarico='N' THEN 0		ELSE 1		END,
						'GENER.AUTO', GETDATE(), '''GENER.AUTO''', GETDATE()
					)
				
			END
		END
		FETCH NEXT FROM amt_crs INTO @idinventoryamortization, @idasset, @idpiece, @description, @amortizationquota
	END
	DEALLOCATE amt_crs
END
