if object_id('[trigger_u_sortingprevincomevar]') is not null
	drop TRIGGER [trigger_u_sortingprevincomevar]
go

CREATE             TRIGGER [trigger_u_sortingprevincomevar] ON [sortingprevincomevar] FOR UPDATE
AS BEGIN
	IF UPDATE(idsor) OR
	UPDATE(amount)
	BEGIN
		DECLARE @ayear int
		DECLARE @newidsor varchar(32)
		DECLARE @newamount decimal(19,2)
		DECLARE @oldidsor varchar(32)
		DECLARE @oldamount decimal(19,2)
	
		SELECT 
			@newidsor = idsor, 
			@ayear = ayear, 
			@newamount = amount
		FROM inserted
	
		SELECT
			@oldidsor = idsor,
			@oldamount = -amount
		FROM deleted
	
		EXECUTE trg_upd_sorttotal 
		@newidsor, 
		@ayear, 
		'totincomevariation',
		@newamount
	
		EXECUTE trg_upd_sorttotal 
		@oldidsor, 
		@ayear, 
		'totincomevariation',
		@oldamount
	END
END


GO

print '[trigger_u_sortingprevincomevar] OK'

