if object_id('[enable_disable_triggers]') is not null
	drop PROCEDURE [enable_disable_triggers]
go

CREATE    PROCEDURE [enable_disable_triggers](
	@owner 			varchar(50),
	@opkind 		char(1)
) as begin
	DECLARE @tablename varchar(50)
	DECLARE @user  varchar(50)
	DECLARE @string varchar(150)
	DECLARE @ownerTableName varchar(150)
	---------SET     @opkind = 'E'
	IF      Upper(@opkind) <> 'E' and Upper(@opkind) <> 'D' RETURN
	DECLARE cur CURSOR
	FOR 
		SELECT sysobjects.name, sysusers.name  
		FROM   sysobjects 
		JOIN   sysusers ON sysobjects.uid = sysusers.uid
		WHERE  sysobjects.id IN(SELECT parent_obj FROM sysobjects WHERE xtype='tr')
		AND    UPPER(ISNULL(sysusers.name,'')) = UPPER(@owner) -- or 
		       --------Upper(ISNULL(sysusers.name,'')) = 'DBO')
	OPEN cur
	FETCH next FROM cur INTO  @tablename, @user
	WHILE @@fetch_status = 0
	BEGIN
		SET @ownerTableName = @user + '.' + @tableName  
		SET @string ='Alter table '+ @ownerTableName 
		IF  Upper(@opkind) = 'D' SET @string = @string + ' Disable trigger all'
		IF  Upper(@opkind) = 'E' SET @string = @string + ' Enable  trigger all'
	
	EXEC (@string) 
	------SELECT * FROM dbo.GetTriggerStatus (@ownerTableName)
	FETCH next FROM cur INTO @tableName, @user
	END
	CLOSE cur
	DEALLOCATE cur
end


GO

print '[enable_disable_triggers] OK'

