if object_id('[rpt_articolisottoscorta_dettprenotazioniinevase]') is not null
	drop PROCEDURE [rpt_articolisottoscorta_dettprenotazioniinevase]
go

CREATE     PROCEDURE [rpt_articolisottoscorta_dettprenotazioniinevase]
	@idlist int,
	@idstore int
AS
BEGIN
CREATE TABLE #dettprenotazioniinevase	(
	idlist int,
	idstore int,
	manager varchar (150),	-- Responsabile,
	number decimal(19,2),	-- Q.tà non evasa,
	allocated decimal(19,2),-- Q.tà allocata,
	booked decimal(19,2)	--Q.tà richiesta
)
-- Prenotazioni inevase
INSERT INTO #dettprenotazioniinevase(
	idlist,
	idstore,
	manager,	-- Responsabile,
	number,		-- Q.tà non evasa,
	allocated,	-- Q.tà allocata,
	booked		--Q.tà richiesta
)
SELECT 
	idlist,
	idstore,
	manager,	-- Responsabile,
	number,		-- Q.tà non evasa,
	allocated,	-- Q.tà allocata,
	booked		--Q.tà richiesta
FROM booktotalview
WHERE ( idlist = @idlist OR @idlist is null )
	AND (idstore = @idstore OR @idstore is null)
	AND number > 0

SELECT 
	T.idlist,
	T.idstore,
	S.description as store,
	manager,	-- Responsabile,
	isnull(number,0) as number,		-- Q.tà non evasa,
	isnull(allocated,0) as allocated,	-- Q.tà allocata,
	isnull(booked,0) as booked		--Q.tà richiesta
FROM #dettprenotazioniinevase T
JOIN store S
	ON S.idstore = T.idstore
DROP TABLE #dettprenotazioniinevase


END


GO

print '[rpt_articolisottoscorta_dettprenotazioniinevase] OK'

