					AND expensetaxofficial.stop IS NULL
			SELECT  @au34ritprevidenzialedip = isnull(SUM(expensetaxofficial.employtax),0),
				@au33ritprevidenzialeamm = isnull(SUM(expensetaxofficial.admintax),0)
				FROM expensetaxofficial
				JOIN tax
