if object_id('[doupdate_contratto_attivo]') is not null
	drop PROCEDURE [doupdate_contratto_attivo]
go

CREATE   PROCEDURE [doupdate_contratto_attivo]
(
	@ayear int,
	@printkind char(1),
	@idestimkind varchar(20),
	@nestim_start int,
	@nestim_stop int
)
AS BEGIN
CREATE TABLE #printingdoc (num int)
IF @printkind = 'A' 
BEGIN
	INSERT INTO #printingdoc (num) 
	SELECT nestim FROM estimate
	WHERE yestim = @ayear
		AND officiallyprinted <>'S'
		AND idestimkind = @idestimkind
END
IF @printkind <> 'A'
BEGIN
	INSERT INTO #printingdoc (num) 
	SELECT nestim
	FROM estimate
	WHERE yestim = @ayear
	AND nestim BETWEEN @nestim_start AND @nestim_stop
		AND idestimkind = @idestimkind
END
UPDATE estimate SET officiallyprinted = 'S'
WHERE yestim = @ayear 
	AND idestimkind = @idestimkind
	AND nestim IN (SELECT num FROM #printingdoc)
END


GO

print '[doupdate_contratto_attivo] OK'

