if object_id('[compute_pettycashrestore]') is not null
	drop PROCEDURE [compute_pettycashrestore]
go

CREATE        PROCEDURE [compute_pettycashrestore]
(
	@ayear smallint,
	@idpettycash int,
	@nlist int
)
AS BEGIN
CREATE TABLE #automov_ungrouped
(
	parentidexp int, 
	idreg int,
	idfin int,
	idupb varchar(36),
	idman int, 
	nbill int,
	amount decimal(19,2)
)
DECLARE @descrpettycash varchar(50)
SELECT @descrpettycash = description FROM pettycash WHERE idpettycash = @idpettycash
DECLARE @idreg int	
SELECT @idreg = registrymanager
FROM pettycashsetupview
WHERE ayear = @ayear
AND idpettycash = @idpettycash
      
INSERT INTO #automov_ungrouped
SELECT
	NULL,
	@idreg,
	idfin,
	idupb,
	idman,
	nbill,
	amount
FROM pettycashoperation
WHERE yoperation = @ayear
	AND yrestore IS NULL AND nrestore IS NULL
	AND idpettycash = @idpettycash
	AND ((flag & 8) <> 0)
	AND (idfin IS NOT NULL AND idexp IS NULL) 
	AND (ISNULL(@nlist,0) = 0 OR pettycashoperation.nlist = @nlist)
INSERT INTO #automov_ungrouped
SELECT
	E.idexp,
	ISNULL(E.idreg,@idreg),
	ISNULL(EY.idfin, PCO.idfin), 
	ISNULL(EY.idupb, PCO.idupb),
	ISNULL(E.idman, PCO.idman),
	PCO.nbill,
	PCO.amount
FROM pettycashoperation PCO
JOIN expense E
	ON PCO.idexp = E.idexp
JOIN expenseyear EY
	ON EY.idexp = PCO.idexp
WHERE yoperation = @ayear
	AND yrestore IS NULL AND nrestore IS NULL
	AND idpettycash = @idpettycash
	AND (ISNULL(@nlist,0) = 0 OR PCO.nlist = @nlist)
	AND (flag & 8)<>0
	AND EY.ayear = @ayear
	
CREATE TABLE #automov
(
	parentidexp int, 
	idreg int,
	idfin int, 
	idupb varchar(36),
	idman int, 
	nbill int,
	amount decimal(19,2)
)
INSERT INTO #automov 
SELECT parentidexp, idreg, idfin, idupb, idman, nbill, SUM(amount)
FROM #automov_ungrouped
GROUP BY parentidexp, idreg, idfin, idupb, idman, nbill
SELECT 
	'Spesa' AS movkind,
	#automov.parentidexp,
	#automov.idreg,
	R.title AS registry,
	#automov.idfin,
	F.codefin,
	#automov.idupb,
	U.codeupb, 
	#automov.idman,
	M.title AS manager ,
	CASE 
		WHEN ISNULL(@nlist,0) = 0 THEN 'Reintegro fondo economale ' + @descrpettycash
		ELSE 'Reintegro fondo economale ' + @descrpettycash + ' Nota spese n° ' + convert(varchar(10),@nlist)
	END as description,
	#automov.nbill,
    #automov.amount
FROM #automov 
LEFT OUTER JOIN registry R
	ON R.idreg = #automov.idreg
LEFT OUTER JOIN fin F
	ON F.idfin = #automov.idfin
LEFT OUTER JOIN upb U
	ON U.idupb = #automov.idupb
LEFT OUTER JOIN manager M
	ON M.idman = #automov.idman
ORDER BY  R.title,F.codefin, U.codeupb
END

GO

print '[compute_pettycashrestore] OK'

GO
if object_id('copyrow_iva_prorata') is not null
	drop PROCEDURE copyrow_iva_prorata
go

CREATE   PROCEDURE			copyrow_iva_prorata
(
		@nprorata	int
)
AS BEGIN
 declare @query nvarchar(3000)
 declare @iddbdepartment varchar(50)
 declare @prorata	decimal(19,6)    
 declare @ayear int
 SELECT  @prorata = prorata, @ayear = ayear FROM iva_prorata WHERE nprorata = @nprorata
 declare @nproratastr varchar(10)
 declare @proratastr varchar(15)
 declare  @ayearstr varchar(10)
 set @ayearstr= convert(varchar,@ayear)
 set @proratastr= convert(varchar,@prorata)
 set @nproratastr= convert(varchar,@nprorata)
  
 declare @amm varchar(100)
 set @amm=user
 declare @crsdepartment cursor
 set 	@crsdepartment = cursor for select  iddbdepartment from dbdepartment where iddbdepartment<>@amm order by iddbdepartment
 open 	@crsdepartment
 fetch next from @crsdepartment into @iddbdepartment
 while @@fetch_status=0 
 begin
  set @query= 
		' if not exists(select * from ['+@iddbdepartment+'].iva_prorata IP where IP.ayear = '+ @ayearstr+ ' ) '
		+ ' Begin '
		+ ' INSERT INTO ['+@iddbdepartment+'].iva_prorata (prorata, ayear, lt, lu, nprorata) '
		+ ' SELECT prorata, ayear, lt, lu, isnull((select max(nprorata) from ['+@iddbdepartment+'].iva_prorata),0)+1 ' 
		+ ' FROM [' + @amm + '].iva_prorata where nprorata = '+ @nproratastr
		+ ' END '
		+ ' ELSE ' 
		+ ' Begin '
		+ ' UPDATE  ['+@iddbdepartment+'].iva_prorata SET lt=IP1.lt, lu=IP1.lu, prorata = IP1.prorata'
		+ ' FROM ['+@iddbdepartment+'].iva_prorata inner join '+
		+ '['+@amm+'].iva_prorata IP1 ON IP1.ayear=['+@iddbdepartment+'].iva_prorata.ayear WHERE  IP1.ayear = '+ @ayearstr
		+ ' END '
			
 print  @query
 EXEC sp_executesql @query

 fetch next from @crsdepartment into @iddbdepartment
 end
END


GO

print 'copyrow_iva_prorata OK'

GO
