if object_id('compute_proceeds_bank') is not null
	drop PROCEDURE compute_proceeds_bank
go


CREATE     PROCEDURE compute_proceeds_bank
(
	@kpro int
)
AS BEGIN
-- Ripristino situazione iniziale
-- Cancellazione dei movimenti bancari associati alla reversale
DECLARE @ypro int
DECLARE @npro int
SELECT @ypro = ypro, @npro = npro FROM proceeds WHERE kpro = @kpro
IF (SELECT COUNT(*) FROM banktransaction WHERE kpro = @kpro) > 0
BEGIN
	
	UPDATE proceeds_bank SET amount =
		(SELECT SUM(i.curramount) 
		FROM incometotal i
		JOIN incomelast l
			ON i.idinc = l.idinc
		WHERE l.kpro = proceeds_bank.kpro
			AND l.idpro = proceeds_bank.idpro)
	WHERE proceeds_bank.kpro = @kpro
	RETURN
END
DELETE FROM proceeds_bank WHERE kpro = @kpro
-- Scollegamento dei movimenti bancari dai movimenti finanziari associati alla reverasle
--UPDATE incomelast SET idpro = NULL WHERE ypro = @ypro AND npro = @npro
UPDATE incomelast SET idpro = NULL WHERE kpro = @kpro
DECLARE @groupby char(1)
SELECT @groupby =
CASE
	WHEN ((flagbank_grouping & 16) <> 0) THEN 'N'
	WHEN ((flagbank_grouping & 32) <> 0) THEN 'V'
	WHEN ((flagbank_grouping & 128) <> 0) THEN 'C'
END
FROM treasurer
WHERE idtreasurer = (SELECT idtreasurer FROM proceeds WHERE kpro = @kpro)
	
DECLARE @groupbyCup char(1)
SELECT @groupbyCup =
CASE
	WHEN ((flagbank_grouping & 64) <> 0) THEN 'S'
	Else 'N'
END
FROM config
WHERE ayear = @ypro
--  Mi creo una tabella temporanea in cui inserisco il codice CUP dopo averlo calcolato.
--  Il calcolo del CUP, ossia la loro lettura, non è immediata perchè vanno letti nel modo seguente:
--  Cup : Spesa -> Contratto passivo -> UPB -> Bilancio
DECLARE @incomeregphase	tinyint
SELECT @incomeregphase = incomeregphase FROM  uniconfig
-- Tabella degli incassi della Reversale
CREATE TABLE #Cup(
	idinc int,
	CUP varchar(15),
	cupcodefin varchar(15),
	cupcodeupb varchar(15),
	cupcodeincome varchar(15)
)
	
IF (@groupbyCup = 'S')
Begin
		-- Inserimento dei movimenti di entrata presenti nella reversale di incasso
		INSERT INTO #Cup(
			idinc,
			cupcodefin,
			cupcodeupb,
			cupcodeincome
		)
		SELECT
			I.idinc, 
			FL.cupcode,
			U.cupcode,
			RegPhase.cupcode
		FROM income I
		JOIN incomelast IL
			ON I.idinc = IL.idinc
		JOIN incomeyear IY
			ON IY.idinc = I.idinc
		JOIN incomelink as RegPhaseELK	-- Dobbiamo risalire alla fase del creditore per recuperare CUP e CIG
			ON RegPhaseELK.idchild = IL.idinc
			AND RegPhaseELK.nlevel = @incomeregphase
		JOIN income RegPhase			-- fase del Creditore
			ON RegPhase.idinc = RegPhaseELK.idparent 
		JOIN finlast FL
			ON IY.idfin = FL.idfin
		JOIN upb U
			ON IY.idupb = U.idupb 
		WHERE IL.kpro = @kpro
			
		UPDATE #Cup SET CUP = ISNULL(cupcodeincome, ISNULL(cupcodeupb, ISNULL(cupcodefin,''))) 
	
	-- Quindi nella tabella #CigCup ho per ogni incasso della reversale il relativo CUP e CIG
End

DECLARE @idpro_free int
	
IF (@groupby = 'N')
BEGIN
	DECLARE @idinc int
	DECLARE @idreg int
	DECLARE @description varchar(150)
	DECLARE @curramount decimal(19,2)
	DECLARE @doc varchar(35)
	DECLARE @docdate datetime
	DECLARE @nbill int
	
	DECLARE pro_crs INSENSITIVE CURSOR FOR
	
	SELECT v.idinc, v.idreg, v.description, v.doc, v.docdate, v.curramount, v.nbill
	FROM incomeview v
	JOIN incomelast	l
		ON v.idinc = l.idinc 
	WHERE l.kpro = @kpro
	FOR READ ONLY
	
	OPEN pro_crs
	FETCH NEXT FROM pro_crs INTO @idinc, @idreg, @description, @doc, @docdate, @curramount, @nbill
	
	WHILE (@@FETCH_STATUS = 0)
	BEGIN
		IF (@doc IS NOT NULL)
		BEGIN
			SELECT @description = 'Pag. ' + @doc
		END
		IF ((@doc IS NOT NULL) AND (@docdate IS NOT NULL))
		BEGIN
			SELECT @description = @description + ' del ' + CONVERT(varchar(20), @docdate, 105)
		END
		SET @idpro_free = ISNULL((SELECT MAX(idpro) FROM proceeds_bank WHERE kpro = @kpro),0) + 1
	
		INSERT INTO proceeds_bank (kpro, idpro, idreg, description, amount, ct, cu, lt, lu) 
		VALUES(@kpro, @idpro_free, @idreg, @description, @curramount,  GETDATE(), 'SP', GETDATE(), '''SP''')
	
		UPDATE incomelast SET idpro = @idpro_free WHERE idinc = @idinc
	
		FETCH NEXT FROM pro_crs INTO @idinc, @idreg, @description, @doc, @docdate, @curramount, @nbill 
	END
	CLOSE pro_crs
	DEALLOCATE pro_crs
END
DECLARE @idinc_1 int
DECLARE @idreg_1 int
DECLARE @description_1 varchar(150)
DECLARE	@doc_1 varchar(35) 
DECLARE @curramount_1 decimal(19,2)
DECLARE @proceedsdescr_1 varchar(150)
DECLARE @CUP_1 varchar(15)
DECLARE @riscossione_cassa_1 int
DECLARE @riscossione_ccp_1 int
DECLARE @riscossione_accredito_tps_1 int
DECLARE @destinazione_vincolata_1 int
DECLARE @CUP_2 varchar(15)
DECLARE @idinc_2 int
DECLARE @idreg_2 int
DECLARE @description_2 varchar(150)
DECLARE	@doc_2 varchar(35) 
DECLARE @curramount_2 decimal(19,2)
DECLARE @proceedsdescr_2 varchar(150)
DECLARE @nbill_1 int
DECLARE @riscossione_cassa_2 int
DECLARE @riscossione_ccp_2 int
DECLARE @riscossione_accredito_tps_2 int
DECLARE @destinazione_vincolata_2 int
DECLARE @nbill_2 int
DECLARE @flagsingle char(1)
SELECT  @flagsingle = 'S'
DECLARE @pbank_amount decimal(19,2)
SELECT  @pbank_amount = 0
DECLARE @pbank_descr varchar(150)
SELECT  @pbank_descr = 'Incassi diversi'

IF (@groupby = 'V') 
BEGIN
	
		DECLARE pro_crs INSENSITIVE CURSOR FOR
		SELECT v.idinc, v.idreg, v.description, v.curramount, v.nbill, C.CUP,
		-- riscossione per cassa, riscossione con prelievo da ccp, riscossione con accredito in BI, destinazione libera o vincolata
		(v.flag&2), (v.flag&4), (v.flag&8),(v.flag&16)
		FROM incomeview v
		JOIN incomelast l
			ON v.idinc = l.idinc
		LEFT OUTER JOIN #Cup C
			ON C.idinc = L.idinc
		WHERE l.kpro = @kpro
		ORDER BY v.idreg, v.nbill
		FOR READ ONLY
	
		OPEN pro_crs
	
		FETCH NEXT FROM pro_crs INTO @idinc_1, @idreg_1, @description_1, @curramount_1, @nbill_1, @CUP_1,
		@riscossione_cassa_1, @riscossione_ccp_1, @riscossione_accredito_tps_1, @destinazione_vincolata_1
		IF (@@FETCH_STATUS = 0)
		BEGIN
			FETCH NEXT FROM pro_crs INTO @idinc_2, @idreg_2, @description_2, @curramount_2, @nbill_2, @CUP_2,
			@riscossione_cassa_2, @riscossione_ccp_2, @riscossione_accredito_tps_2,@destinazione_vincolata_2
			WHILE (@@FETCH_STATUS = 0)
			BEGIN
				SET @idpro_free = ISNULL((SELECT MAX(idpro) FROM proceeds_bank WHERE kpro = @kpro),0) + 1
	
				SELECT @pbank_amount = ISNULL(@pbank_amount, 0) + @curramount_1
	
				IF (@idreg_1 <> @idreg_2)
					OR (ISNULL(@nbill_1,0) <> ISNULL(@nbill_2,0))
					OR (ISNULL(@CUP_1,0) <> ISNULL(@CUP_2,0))
					OR (ISNULL(@riscossione_cassa_1,0) <> ISNULL(@riscossione_cassa_2,0))
					OR (ISNULL(@riscossione_ccp_1,0) <> ISNULL(@riscossione_ccp_2,0))
					OR (ISNULL(@riscossione_accredito_tps_1,0) <> ISNULL(@riscossione_accredito_tps_2,0))
					OR (ISNULL(@destinazione_vincolata_1,0) <> ISNULL(@destinazione_vincolata_2,0))
				BEGIN
					IF (@flagsingle = 'S')
					BEGIN
						SELECT @pbank_descr = @description_1
					END
					INSERT INTO proceeds_bank (kpro, idpro, idreg, description, amount, ct, cu, lt, lu) 
					VALUES
					(@kpro, @idpro_free, @idreg_1, @pbank_descr, @pbank_amount,  GETDATE(), 'SP', GETDATE(), '''SP''')
					SELECT @pbank_amount = 0
					SELECT @flagsingle = 'S'
					SELECT @pbank_descr = 'Incassi diversi'
				END
				ELSE
				BEGIN
					SELECT @flagsingle = 'N'
				END
				UPDATE incomelast SET idpro = @idpro_free WHERE idinc = @idinc_1
	
				SELECT 
					@idinc_1 = @idinc_2, @idreg_1 = @idreg_2, 
					@description_1 = @description_2, @curramount_1 = @curramount_2,
					@nbill_1 = @nbill_2,
					@CUP_1 = @CUP_2,
					@riscossione_cassa_1 = @riscossione_cassa_2,
					@riscossione_ccp_1 = @riscossione_ccp_2,
					@riscossione_accredito_tps_1 = @riscossione_accredito_tps_2,
					@destinazione_vincolata_1 = @destinazione_vincolata_2
				FETCH NEXT FROM pro_crs INTO @idinc_2, @idreg_2, @description_2,
					@curramount_2, @nbill_2, @CUP_2,
					@riscossione_cassa_2, @riscossione_ccp_2, @riscossione_accredito_tps_2,@destinazione_vincolata_2
			END
	
			SET @idpro_free = ISNULL((SELECT MAX(idpro) FROM proceeds_bank WHERE kpro = @kpro),0) + 1
			IF (@flagsingle = 'S')
			BEGIN
				SELECT @pbank_descr = @description_1
			END
	
			SELECT @pbank_amount = ISNULL(@pbank_amount, 0) + @curramount_1
	
			INSERT INTO proceeds_bank (kpro, idpro, idreg, description, amount, ct, cu, lt, lu) 
			VALUES (@kpro, @idpro_free, @idreg_1, @pbank_descr, @pbank_amount,  GETDATE(), 'SP', GETDATE(), '''SP''')
			UPDATE incomelast SET idpro = @idpro_free WHERE idinc = @idinc_1
		END
		CLOSE pro_crs 
		DEALLOCATE pro_crs
	END
	
END

GO

print 'compute_proceeds_bank OK'

GO
if object_id('[exp_unified_incomegerarchico_bari]') is not null
	drop PROCEDURE [exp_unified_incomegerarchico_bari]
go

CREATE       PROCEDURE [exp_unified_incomegerarchico_bari]
(
	@ymin int,
	@ymax int,
	@ayearmin int,
	@ayearmax int,
	@registry varchar(100),
	@adatemin datetime,
	@adatemax datetime,
	@codefin varchar(50),
	@idupb varchar(36),
	@unified char(1)
)
AS BEGIN

IF (@unified <> 'S')
BEGIN
	 EXEC [exp_incomegerarchico_bari]  @ymin , @ymax ,@ayearmin ,@ayearmax ,@registry,@adatemin ,@adatemax ,@codefin ,@idupb  
        RETURN
END
ELSE
BEGIN
CREATE TABLE #unified (
	anno int,
	iddbdepartment  varchar(50),
    departmentname  varchar(150),
	fase_1 varchar(100),
	fase_2 varchar(100),
	fase_3 varchar(100),
	fase_4 varchar(100),
	fase_5 varchar(100),
	reversale varchar(50),
	codefin varchar(50),
	finance varchar(150),
	codeupb varchar(50),
	upb varchar(150),
	registry varchar(150),
	cf varchar(50),
	p_iva varchar(50),
	class_centralizzata varchar(50),
	description varchar(150),
	curramount decimal(19,2),
	available decimal(19,2),
	date datetime,
	doc varchar(150),
	docdate datetime 
)

DECLARE @iddbdepartment varchar(50)
DECLARE crsdepartment  cursor LOCAL STATIC FOR 
SELECT iddbdepartment FROM dbdepartment 
WHERE (start is null or start <= @ayearmax ) AND ( stop is null or stop >= @ayearmin)
FOR READ ONLY
OPEN crsdepartment
FETCH NEXT FROM crsdepartment INTO @iddbdepartment
WHILE @@fetch_status=0 begin
	DECLARE @dip_nomesp varchar(300)
        SET @dip_nomesp = '['+@iddbdepartment+']'+ '.exp_incomegerarchico_bari'
declare @sqlsetuser as varchar(10)
SET @sqlsetuser = 'setuser'
declare @sqlsetuserdip  as varchar(100)
SET @sqlsetuserDIP = 'setuser ' + ''''+ @iddbdepartment + ''''
execute (@sqlsetuser)
execute (@sqlsetuserdip)
print @sqlsetuserdip
PRINT @iddbdepartment

PRINT @iddbdepartment
		INSERT INTO #unified (
                   	anno,
					fase_1,
					fase_2,
					fase_3,
					fase_4,
					fase_5,
					reversale,
					codefin,
					finance,
					codeupb,
					upb,
					registry,
					cf,
					p_iva,
					class_centralizzata,
					description,
					curramount,
					available,
					date ,
					doc,
					docdate  
		)
		EXEC @dip_nomesp @ymin , @ymax ,@ayearmin ,@ayearmax ,@registry,@adatemin ,@adatemax ,@codefin ,@idupb  
	
		
		UPDATE #unified set iddbdepartment = @iddbdepartment,  departmentname  = dbdepartment.description 
		FROM dbdepartment 
		WHERE dbdepartment.iddbdepartment=@iddbdepartment
		AND   #unified.iddbdepartment is null
	FETCH NEXT FROM crsdepartment INTO @iddbdepartment
end
SELECT * FROM #unified
END

DROP TABLE #unified
END

GO

print '[exp_unified_incomegerarchico_bari] OK'

GO
if object_id('[exp_variationunderwritingupbfin]') is not null
	drop PROCEDURE [exp_variationunderwritingupbfin]
go

CREATE    PROCEDURE [exp_variationunderwritingupbfin]
(
	@yvar smallint,
	@nvar int,
	@idsor01 int,
	@idsor02 int,
	@idsor03 int,
	@idsor04 int,
	@idsor05 int
)
AS
BEGIN
DECLARE @finphaseincome tinyint
DECLARE @finphaseexpense tinyint
DECLARE @maxphaseincome tinyint
DECLARE @maxphaseexpense tinyint
SELECT @finphaseincome = assessmentphasecode FROM config WHERE ayear = @yvar
IF @finphaseincome IS NULL
BEGIN
	SELECT @finphaseincome = incomefinphase FROM uniconfig
END
SELECT @maxphaseincome = MAX(nphase) FROM incomephase
SELECT @finphaseexpense = appropriationphasecode FROM config WHERE ayear = @yvar
IF @finphaseexpense IS NULL
BEGIN
	SELECT @finphaseexpense = expensefinphase FROM uniconfig
END
SELECT @maxphaseexpense = MAX(nphase) FROM expensephase

declare @approvata char(1)
if ((select idfinvarstatus from finvar where yvar = @yvar and nvar = @nvar) = '5')
begin
	set @approvata = 'S'
end	
else
begin
	set @approvata = 'N'
end
DECLARE @fin_kind tinyint
SELECT @fin_kind = fin_kind FROM config WHERE ayear = @yvar
CREATE TABLE #DETTAGLIO_VARIAZIONE(
	idunderwriting int, 
	idupb varchar(36),	
	idfin int, 
	previsionvariation decimal(19,2),
	secondaryvariation decimal(19,2),
	creditvariation decimal(19,2),
	proceedsvariation decimal(19,2)
	)  
INSERT INTO #DETTAGLIO_VARIAZIONE(idunderwriting, idupb, idfin,
		previsionvariation,secondaryvariation,creditvariation,proceedsvariation)
select D.idunderwriting, D.idupb, D.idfin, 
		sum( case when V.flagprevision='S' and idfinvarstatus<>5 then amount else 0 end ),
		sum( case when V.flagsecondaryprev='S' and idfinvarstatus<>5  then amount else 0 end ),
		sum( case when V.flagcredit='S' and (F.flag&1<>0 ) and idfinvarstatus<>5 and V.variationkind <> 5 then amount else 0 end ),
		sum( case when V.flagproceeds='S' and (F.flag&1<>0 ) and idfinvarstatus<>5  and V.variationkind <> 5 then amount else 0 end )	
from finvar V
join finvardetail D
	on V.yvar = D.yvar and V.nvar= D.nvar
join upb U
	on U.idupb = D.idupb	
join fin F
	on F.idfin= D.idfin
where V.yvar = @yvar and V.nvar = @nvar
		AND (@idsor01 IS NULL OR U.idsor01 = @idsor01)
		AND (@idsor02 IS NULL OR U.idsor02 = @idsor02)
		AND (@idsor03 IS NULL OR U.idsor03 = @idsor03)
		AND (@idsor04 IS NULL OR U.idsor04 = @idsor04)
		AND (@idsor05 IS NULL OR U.idsor05 = @idsor05)
group by D.idunderwriting, D.idupb, D.idfin

CREATE TABLE #PICCOLE_SPESE(
	idunderwriting int, 
	idupb varchar(36),	
	idfin int, 
	amount decimal(19,2)
	)  
--Il SUM lo mettiamo perchè potrebbero esserci n righe in pettycashoperationunderwriting, ossia n op.imputate alla terna.
INSERT INTO #PICCOLE_SPESE(idunderwriting, idupb, idfin, amount)  
--> Con Finanziamento	
select FV.idunderwriting, FV.idupb, FV.idfin, SUM(U.amount)
	from #DETTAGLIO_VARIAZIONE FV
	join pettycashoperationunderwriting U
		on U.idunderwriting = FV.idunderwriting 
	join pettycashoperation operation
		ON U.yoperation = operation.yoperation
		AND U.noperation = operation.noperation
		AND U.idpettycash = operation.idpettycash
		AND FV.idfin=operation.idfin and FV.idupb=operation.idupb
	join upb 
		on upb.idupb = FV.idupb	
where  (@idsor01 IS NULL OR upb.idsor01 = @idsor01)
		AND (@idsor02 IS NULL OR upb.idsor02 = @idsor02)
		AND (@idsor03 IS NULL OR upb.idsor03 = @idsor03)
		AND (@idsor04 IS NULL OR upb.idsor04 = @idsor04)
		AND (@idsor05 IS NULL OR upb.idsor05 = @idsor05)
		AND NOT	EXISTS (SELECT * FROM pettycashoperation restoreop
							WHERE restoreop.yrestore = operation.yrestore
								AND restoreop.nrestore = operation.nrestore
								AND restoreop.idpettycash = operation.idpettycash)
group by FV.idunderwriting, FV.idupb, FV.idfin
--> Senza Finanziamento	
INSERT INTO #PICCOLE_SPESE(idupb, idfin, amount)  
select FV.idupb, FV.idfin, SUM(operation.amount)
	from #DETTAGLIO_VARIAZIONE FV
	join pettycashoperation operation
		ON FV.idupb = operation.idupb
		AND FV.idfin = operation.idfin
	join upb 
		on upb.idupb = FV.idupb	
where (@idsor01 IS NULL OR upb.idsor01 = @idsor01)
		AND (@idsor02 IS NULL OR upb.idsor02 = @idsor02)
		AND (@idsor03 IS NULL OR upb.idsor03 = @idsor03)
		AND (@idsor04 IS NULL OR upb.idsor04 = @idsor04)
		AND (@idsor05 IS NULL OR upb.idsor05 = @idsor05)
		AND NOT	EXISTS (SELECT * FROM pettycashoperation restoreop
							WHERE restoreop.yrestore = operation.yrestore
								AND restoreop.nrestore = operation.nrestore
								AND restoreop.idpettycash = operation.idpettycash)		
group by FV.idupb, FV.idfin
	
--> COMPETENZA E CASSA 
IF (@fin_kind = 3)
BEGIN
		select   
			CASE
				when (( F.flag & 1)=0) then 'E'
				when (( F.flag & 1)=1) then 'S'
			End as 'E/S',
			W.title as 'Finanziamento',
			U.codeupb as 'UPB',
			F.codefin as 'Bilancio',
			isnull(UUT.currentprev,0)+ISNULL(UUT.previsionvariation, 0)+ 
				isnull(UT.currentprev,0)+ISNULL(UT.previsionvariation, 0)+ 
					isnull(FV.previsionvariation,0)
		   as 'Prev.Competenza',
				isnull(UUT.currentprev,0)+ISNULL(UUT.previsionvariation, 0)+ 
				isnull(UT.currentprev,0)+ISNULL(UT.previsionvariation, 0)+ 
					isnull(FV.previsionvariation,0)
					- (isnull(ACC.totalcompetency,0) + isnull(IMP.totalcompetency,0) 
						+isnull(ACC_.totalcompetency,0) + isnull(IMP_.totalcompetency,0) 
						+ isnull(OPS.amount,0)
					  )
			as 'Prev.Competenza.Disponibile',
			isnull(UUT.currentsecondaryprev,0)+ISNULL(UUT.secondaryvariation, 0)+ 
				isnull(UT.currentsecondaryprev,0)+ISNULL(UT.secondaryvariation, 0)+ 
					isnull(FV.secondaryvariation,0)
				 as 'Prev.Cassa',
			isnull(UUT.currentsecondaryprev,0)+ISNULL(UUT.secondaryvariation, 0)+ 
				isnull(UT.currentsecondaryprev,0)+ISNULL(UT.secondaryvariation, 0)+ 
					isnull(FV.secondaryvariation,0)
					- (isnull(PAG.totalcompetency,0) + isnull(INC.totalcompetency,0) 
						+isnull(PAG_.totalcompetency,0) + isnull(INC_.totalcompetency,0) 
						+isnull(PAG.totalarrears,0) + isnull(INC.totalarrears,0) 
						+isnull(PAG_.totalarrears,0) + isnull(INC_.totalarrears,0) 
						+ isnull(OPS.amount,0)
					  )
			as 'Prev.Cassa.Disponibile',
			CASE 
				when (( F.flag & 1)=1) /* S */
				then
				isnull(UUT.totcreditpart,0)+ISNULL(UUT.creditvariation, 0)+
				isnull(UT.totcreditpart,0)+ISNULL(UT.creditvariation, 0)+
				isnull(FV.creditvariation,0)
				else null
			End	
			as 'Crediti',
			CASE 
				when (( F.flag & 1)=1) /* S */
				then		isnull(UUT.totcreditpart,0)+ISNULL(UUT.creditvariation, 0)+
							isnull(UT.totcreditpart,0)+ISNULL(UT.creditvariation, 0)+
							isnull(FV.creditvariation,0)
							 - (isnull(IMP.totalcompetency,0) +isnull(IMP_.totalcompetency,0) +isnull(OPS.amount,0) )
				else null		
			End
			as 'Crediti Disponibili',
			CASE
				when (( F.flag & 1)=1) /* S */
				then 
					isnull(UUT.totproceedspart,0)+ISNULL(UUT.proceedsvariation, 0)+
					isnull(UT.totproceedspart,0)+ISNULL(UT.proceedsvariation, 0)+
					isnull(FV.proceedsvariation,0)
				else null		
			End
			as 'Incassi',
			CASE
				when (( F.flag & 1)=1) /* S */
				then isnull(UUT.totproceedspart,0)+ISNULL(UUT.proceedsvariation, 0)+
					isnull(UT.totproceedspart,0)+ISNULL(UT.proceedsvariation, 0)+
					isnull(FV.proceedsvariation,0)
					- ( isnull(PAG.totalcompetency,0) +isnull(PAG_.totalcompetency,0)+ isnull(PAG.totalarrears,0) +isnull(PAG_.totalarrears,0)
						+ isnull(OPS.amount,0)  
						)
				else null		
			End
			as 'Incassi Disponibili'			
			from #DETTAGLIO_VARIAZIONE FV 
			join fin F
				on FV.idfin = F.idfin
			join upb U
				on FV.idupb = U.idupb
			left outer join underwriting W
				on FV.idunderwriting = W.idunderwriting
				
		   left outer join upbunderwritingtotal   UUT
   				ON UUT.idunderwriting = FV.idunderwriting and UUT.idupb = FV.idupb and UUT.idfin = FV.idfin 
		   left outer join upbtotal   UT
   				ON UT.idupb = FV.idupb and UT.idfin = FV.idfin AND FV.idunderwriting is null
		   left outer join #PICCOLE_SPESE OPS	
   				ON isnull(OPS.idunderwriting,0)  = isnull(FV.idunderwriting,0) and OPS.idupb = FV.idupb and OPS.idfin = FV.idfin 
		   left outer join underwritingexpensetotal IMP
   				ON IMP.idunderwriting = FV.idunderwriting and IMP.idupb = FV.idupb and IMP.idfin = FV.idfin  and IMP.nphase = @finphaseexpense	
		   left outer join underwritingexpensetotal PAG
   				ON PAG.idunderwriting = FV.idunderwriting and PAG.idupb = FV.idupb and PAG.idfin = FV.idfin  and PAG.nphase = @maxphaseexpense	
		   left outer join upbexpensetotal IMP_
   				ON IMP_.idupb = FV.idupb and IMP_.idfin = FV.idfin  and IMP_.nphase = @finphaseexpense	AND FV.idunderwriting is null
		   left outer join upbexpensetotal PAG_
   				ON PAG_.idupb = FV.idupb and PAG_.idfin = FV.idfin  and PAG_.nphase = @maxphaseexpense	AND FV.idunderwriting is null
		   left outer join underwritingincometotal  ACC
   				ON ACC.idunderwriting = FV.idunderwriting and ACC.idupb = FV.idupb and ACC.idfin = FV.idfin  and IMP.nphase = @finphaseincome	
		   left outer join underwritingincometotal  INC 
   				ON FV.idunderwriting is null and INC.idupb = FV.idupb and INC.idfin = FV.idfin  and INC.nphase = @maxphaseincome	
		   
		   left outer join upbincometotal  ACC_
   				ON ACC_.idupb = FV.idupb and ACC_.idfin = FV.idfin  and ACC_.nphase = @finphaseincome	AND FV.idunderwriting is null
		   left outer join upbincometotal  INC_ 
   				ON INC_.idupb = FV.idupb and INC_.idfin = FV.idfin  and INC_.nphase = @maxphaseincome	AND FV.idunderwriting is null
		  
		  order by  W.title,U.codeupb,F.codefin
END   

--> SOLO COMPETENZA 
IF (@fin_kind = 1) 
BEGIN
		select   
			CASE
				when (( F.flag & 1)=0) then 'E'
				when (( F.flag & 1)=1) then 'S'
			End as 'E/S',
			W.title as 'Finanziamento',
			U.codeupb as 'UPB',
			F.codefin as 'Bilancio',
			isnull(UUT.currentprev,0)+ISNULL(UUT.previsionvariation, 0)+ 
				isnull(UT.currentprev,0)+ISNULL(UT.previsionvariation, 0)+ 
					isnull(FV.previsionvariation,0)
		   as 'Prev.Competenza',
				isnull(UUT.currentprev,0)+ISNULL(UUT.previsionvariation, 0)+ 
				isnull(UT.currentprev,0)+ISNULL(UT.previsionvariation, 0)+ 
					isnull(FV.previsionvariation,0)
					- (isnull(ACC.totalcompetency,0) + isnull(IMP.totalcompetency,0) 
						+isnull(ACC_.totalcompetency,0) + isnull(IMP_.totalcompetency,0) 
						+ isnull(OPS.amount,0)
					  )
			as 'Prev.Competenza.Disponibile',
			CASE 
				when (( F.flag & 1)=1) /* S */
				then
				isnull(UUT.totcreditpart,0)+ISNULL(UUT.creditvariation, 0)+
				isnull(UT.totcreditpart,0)+ISNULL(UT.creditvariation, 0)+
				isnull(FV.creditvariation,0)
				else null
			End	
			as 'Crediti',
			CASE 
				when (( F.flag & 1)=1) /* S */
				then		isnull(UUT.totcreditpart,0)+ISNULL(UUT.creditvariation, 0)+
							isnull(UT.totcreditpart,0)+ISNULL(UT.creditvariation, 0)+
							isnull(FV.creditvariation,0)
							 - (isnull(IMP.totalcompetency,0) +isnull(IMP_.totalcompetency,0) +isnull(OPS.amount,0) )
				else null		
			End
			as 'Crediti Disponibili'			
			from #DETTAGLIO_VARIAZIONE FV 
			join fin F
				on FV.idfin = F.idfin
			join upb U
				on FV.idupb = U.idupb
			left outer join underwriting W
				on FV.idunderwriting = W.idunderwriting
				
		   left outer join upbunderwritingtotal   UUT
   				ON UUT.idunderwriting = FV.idunderwriting and UUT.idupb = FV.idupb and UUT.idfin = FV.idfin 
		   left outer join upbtotal   UT
   				ON UT.idupb = FV.idupb and UT.idfin = FV.idfin AND FV.idunderwriting is null
		   left outer join #PICCOLE_SPESE OPS	
   				ON isnull(OPS.idunderwriting,0)  = isnull(FV.idunderwriting,0) and OPS.idupb = FV.idupb and OPS.idfin = FV.idfin 
		   left outer join underwritingexpensetotal IMP
   				ON IMP.idunderwriting = FV.idunderwriting and IMP.idupb = FV.idupb and IMP.idfin = FV.idfin  and IMP.nphase = @finphaseexpense	
--		   left outer join underwritingexpensetotal PAG
--   				ON PAG.idunderwriting = FV.idunderwriting and PAG.idupb = FV.idupb and PAG.idfin = FV.idfin  and PAG.nphase = @maxphaseexpense	
		   left outer join upbexpensetotal IMP_
   				ON IMP_.idupb = FV.idupb and IMP_.idfin = FV.idfin  and IMP_.nphase = @finphaseexpense	AND FV.idunderwriting is null
--		   left outer join upbexpensetotal PAG_
--   				ON PAG_.idupb = FV.idupb and PAG_.idfin = FV.idfin  and PAG_.nphase = @maxphaseexpense	AND FV.idunderwriting is null
		   left outer join underwritingincometotal  ACC
   				ON ACC.idunderwriting = FV.idunderwriting and ACC.idupb = FV.idupb and ACC.idfin = FV.idfin  and IMP.nphase = @finphaseincome	
--		   left outer join underwritingincometotal  INC 
--   				ON FV.idunderwriting is null and INC.idupb = FV.idupb and INC.idfin = FV.idfin  and INC.nphase = @maxphaseincome	
		   
		   left outer join upbincometotal  ACC_
   				ON ACC_.idupb = FV.idupb and ACC_.idfin = FV.idfin  and ACC_.nphase = @finphaseincome	AND FV.idunderwriting is null
--		   left outer join upbincometotal  INC_ 
--  				ON INC_.idupb = FV.idupb and INC_.idfin = FV.idfin  and INC_.nphase = @maxphaseincome	AND FV.idunderwriting is null
		  
		  order by  W.title,U.codeupb,F.codefin

END   

--> SOLO CASSA 
IF (@fin_kind = 2) 
BEGIN
		select   
			CASE
				when (( F.flag & 1)=0) then 'E'
				when (( F.flag & 1)=1) then 'S'
			End as 'E/S',
			W.title as 'Finanziamento',
			U.codeupb as 'UPB',
			F.codefin as 'Bilancio',
			isnull(UUT.currentprev,0)+ISNULL(UUT.previsionvariation, 0)+ 
				isnull(UT.currentprev,0)+ISNULL(UT.previsionvariation, 0)+ 
					isnull(FV.previsionvariation,0)
		   as 'Prev.Cassa',
				isnull(UUT.currentprev,0)+ISNULL(UUT.previsionvariation, 0)+ 
				isnull(UT.currentprev,0)+ISNULL(UT.previsionvariation, 0)+ 
					isnull(FV.previsionvariation,0)
					- (isnull(ACC.totalcompetency,0) + isnull(IMP.totalcompetency,0) 
					    + isnull(ACC.totalarrears,0) + isnull(IMP.totalarrears,0) 
						+ isnull(ACC_.totalcompetency,0) + isnull(IMP_.totalcompetency,0) 
						+ isnull(ACC_.totalarrears,0) + isnull(IMP_.totalarrears,0) 
						+ isnull(OPS.amount,0)
					  )
			as 'Prev.Cassa.Disponibile',
			CASE
				when (( F.flag & 1)=1) /* S */
				then 
					isnull(UUT.totproceedspart,0)+ISNULL(UUT.proceedsvariation, 0)+
					isnull(UT.totproceedspart,0)+ISNULL(UT.proceedsvariation, 0)+
					isnull(FV.proceedsvariation,0)
				else null		
			End
			as 'Incassi',
			CASE
				when (( F.flag & 1)=1) /* S */
				then isnull(UUT.totproceedspart,0)+ISNULL(UUT.proceedsvariation, 0)+
					isnull(UT.totproceedspart,0)+ISNULL(UT.proceedsvariation, 0)+
					isnull(FV.proceedsvariation,0)
					- ( isnull(PAG.totalcompetency,0) +isnull(PAG_.totalcompetency,0)+ isnull(PAG.totalarrears,0) +isnull(PAG_.totalarrears,0)
						+ isnull(OPS.amount,0)  
						)
				else null		
			End
			as 'Incassi Disponibili'			
			from #DETTAGLIO_VARIAZIONE FV 
			join fin F
				on FV.idfin = F.idfin
			join upb U
				on FV.idupb = U.idupb
			left outer join underwriting W
				on FV.idunderwriting = W.idunderwriting
				
		   left outer join upbunderwritingtotal   UUT
   				ON UUT.idunderwriting = FV.idunderwriting and UUT.idupb = FV.idupb and UUT.idfin = FV.idfin 
		   left outer join upbtotal   UT
   				ON UT.idupb = FV.idupb and UT.idfin = FV.idfin AND FV.idunderwriting is null
		   left outer join #PICCOLE_SPESE OPS	
   				ON isnull(OPS.idunderwriting,0)  = isnull(FV.idunderwriting,0) and OPS.idupb = FV.idupb and OPS.idfin = FV.idfin 
		   left outer join underwritingexpensetotal IMP
   				ON IMP.idunderwriting = FV.idunderwriting and IMP.idupb = FV.idupb and IMP.idfin = FV.idfin  and IMP.nphase = @finphaseexpense	
		   left outer join underwritingexpensetotal PAG
   				ON PAG.idunderwriting = FV.idunderwriting and PAG.idupb = FV.idupb and PAG.idfin = FV.idfin  and PAG.nphase = @maxphaseexpense	
		   left outer join upbexpensetotal IMP_
   				ON IMP_.idupb = FV.idupb and IMP_.idfin = FV.idfin  and IMP_.nphase = @finphaseexpense	AND FV.idunderwriting is null
		   left outer join upbexpensetotal PAG_
   				ON PAG_.idupb = FV.idupb and PAG_.idfin = FV.idfin  and PAG_.nphase = @maxphaseexpense	AND FV.idunderwriting is null
		   left outer join underwritingincometotal  ACC
   				ON ACC.idunderwriting = FV.idunderwriting and ACC.idupb = FV.idupb and ACC.idfin = FV.idfin  and IMP.nphase = @finphaseincome	
		   left outer join underwritingincometotal  INC 
   				ON FV.idunderwriting is null and INC.idupb = FV.idupb and INC.idfin = FV.idfin  and INC.nphase = @maxphaseincome	
		   
		   left outer join upbincometotal  ACC_
   				ON ACC_.idupb = FV.idupb and ACC_.idfin = FV.idfin  and ACC_.nphase = @finphaseincome	AND FV.idunderwriting is null
		   left outer join upbincometotal  INC_ 
   				ON INC_.idupb = FV.idupb and INC_.idfin = FV.idfin  and INC_.nphase = @maxphaseincome	AND FV.idunderwriting is null
		  
		  order by  W.title,U.codeupb,F.codefin

END   

drop table #DETTAGLIO_VARIAZIONE
drop table #PICCOLE_SPESE 
END

GO

print '[exp_variationunderwritingupbfin] OK'

