if object_id('[rpt_cedolino]') is not null
	drop PROCEDURE [rpt_cedolino]
go

CREATE       PROCEDURE [rpt_cedolino]
	@idreg   int, 
	@ayear	 int,
	@start   datetime,
	@stop    datetime,
	@idsor01 int=null,
	@idsor02 int=null,
	@idsor03 int=null,
	@idsor04 int=null,
	@idsor05 int=null
AS
BEGIN
--	exec rpt_cedolino '0',2011, {ts '2011-01-01 00:00:00'}, {ts '2011-12-31 00:00:00'}
create table #rptcedolino
(
	idreg int, 
	surname770 varchar(50),
	forename770 varchar(50),
	cf varchar(16) NULL,
	birthdate smalldatetime,
	service varchar(50),
	datebegin datetime,
	dateend	datetime,
	duty varchar(150),
	grossamount decimal(19,6),	-- totale dell'importo lordo
	taxablegross decimal(19,6),	-- Valore dell'imponibile Lordo
	taxablenet decimal(19,6),	-- Valore dell'imponibile Netto
	taxdescription varchar(50),	-- Descrizione della ritenuta
	taxablecode varchar(20),	-- Valore del codice dell'imponibile
	taxcode	int , 				 
	tax decimal(19,2),		
	employtaxgross decimal(19,2),	-- Il lordo della ritenuta
	taxable_percent	decimal(19,6),	-- percentuale dell'imponibile della ritenuta
	ritdipversataannua decimal(19,2),
	deduction decimal(19,2),
	feegross decimal(19,2),		-- compenso lordo,compenso competenza
	idpayroll int,
	flagbalance char(1),		-- Applicazione o meno del conguaglio
	idpayrolltax int,
	datebegincontract datetime,
	dateendcontract datetime,
	abatements decimal(19,2),
	nbracket int
)
CREATE TABLE #computetax
(
	idpayroll int,
	idpayrolltax int,
	totimportotax decimal(19,2),    -- importo totale sul cedolino della ritenuta c/precipiente 
	importotax decimal(19,2),       -- importo della ritenuta c/precipiente per singolo scaglione 
	employtaxgross decimal(19,2),	-- Importo lordo della ritenuta
	taxable_percent decimal(19,6),	-- Percentuale dell'importo della ritenua
	deduction decimal(19,2),
	abatements decimal(19,2),
	nbracket int,
	taxcode	int
)
CREATE TABLE #indirizzopagamento
(
	idaddresskind int,
	idreg int,
	address	varchar(100) ,
	geo_city varchar(120),	
	geo_country char(2),		
	cap varchar(20)	
)
 INSERT INTO #rptcedolino
(
	idreg, 
	surname770,
	forename770,
	cf,
	birthdate,
	service,
	datebegin,
	dateend,
	duty,
	grossamount,
	taxablegross,	
	taxablenet,
	taxdescription,	
	taxablecode,
	taxcode,					
	ritdipversataannua,
	feegross,			
	idpayroll,
	flagbalance,
	idpayrolltax,
	datebegincontract,
	dateendcontract,
	abatements,	
	nbracket
)
SELECT 
	parasubcontract.idreg, 
	registry.surname,
	registry.forename,
	registry.cf,
	registry.birthdate,
	service.description,	
	payroll.start,
	payroll.stop,
	parasubcontract.duty,
	parasubcontract.grossamount,			-->importo lordo totale
	payrolltax.taxablegross,			--> importo lordo del singolo cedolino
	payrolltax.taxablenet,
	tax.description,
	tax.taxablecode,
	tax.taxcode,						
	isnull(payrolltax.annualpayedemploytax,0.0),
	payroll.feegross,				--> compenso lordo competenza
	payroll.idpayroll,	
	payroll.flagbalance,
	payrolltax.idpayrolltax,
	parasubcontract.start,
	parasubcontract.stop,
	payrolltax.abatements,
	payrolltaxbracket.nbracket
from registry
JOIN parasubcontract 
	ON registry.idreg=parasubcontract.idreg
join parasubcontractyear 
	on parasubcontractyear.idcon=parasubcontract.idcon  
JOIN service
	ON service.idser=parasubcontract.idser
JOIN payroll
	ON payroll.idcon=parasubcontract.idcon
LEFT OUTER JOIN payrolltax			-- Facciamo il LEFT OUTER JOIN in modo da prendere anche i cedolini dei Boristi esenti non soggetti a ritenuta.
	ON payrolltax.idpayroll=payroll.idpayroll
LEFT OUTER JOIN tax
	ON tax.taxcode = payrolltax.taxcode
LEFT OUTER JOIN payrolltaxbracket		
	on payrolltaxbracket.idpayroll = payrolltax.idpayroll
	AND payrolltaxbracket.idpayrolltax = payrolltax.idpayrolltax
	AND isnull(payrolltaxbracket.employtax,0)<>0
WHERE	(registry.idreg=@idreg OR ISNULL(@idreg,0)=0)
	AND parasubcontractyear.ayear=@ayear
	AND (payroll.start>=@start AND payroll.stop<=@stop)
	AND (payroll.fiscalyear=@ayear)	
	AND payroll.flagbalance<>'S'
	AND isnull(payroll.flagcomputed,'N'	)='S'	-- Prendiamo SOLO i cedolini calcolati.
	AND (@idsor01 IS NULL OR parasubcontract.idsor01 = @idsor01)
	AND (@idsor02 IS NULL OR parasubcontract.idsor02 = @idsor02)
	AND (@idsor03 IS NULL OR parasubcontract.idsor03 = @idsor03)
	AND (@idsor04 IS NULL OR parasubcontract.idsor04 = @idsor04)
	AND (@idsor05 IS NULL OR parasubcontract.idsor05 = @idsor05)

INSERT INTO #computetax
(
	idpayroll ,
	idpayrolltax,
	totimportotax,
	importotax,
	employtaxgross,
	taxable_percent,
	deduction,
	abatements,	-- detrazioni
	nbracket,
	taxcode
)
SELECT 
	payrolltaxbracket.idpayroll,
	payrolltaxbracket.idpayrolltax,
	payrolltax.employtax,
	payrolltaxbracket.employtax,  
	payrolltax.employtaxgross,
	case when isnull(payrolltaxbracket.taxable,0.0)=0 then 0
	     else round(isnull(payrolltaxbracket.employtax,0.0)/payrolltaxbracket.taxable,6)*100
	end,
	payrolltax.deduction,
	payrolltax.abatements,
	payrolltaxbracket.nbracket,
	payrolltax.taxcode
FROM payrolltax
join payroll
	on payrolltax.idpayroll=payroll.idpayroll
join payrolltaxbracket		
	on payrolltaxbracket.idpayroll = payrolltax.idpayroll
	and payrolltaxbracket.idpayrolltax = payrolltax.idpayrolltax
where payroll.flagbalance<>'S' and isnull(payrolltaxbracket.employtax,0)<>0
	AND (payroll.start>=@start AND payroll.stop<=@stop)	
	AND (payroll.fiscalyear=@ayear)				
UPDATE #rptcedolino SET	
	tax= ISNULL((
		SELECT #computetax.importotax  
		FROM  #computetax
		WHERE  #computetax.idpayroll=#rptcedolino.idpayroll
			AND #computetax.idpayrolltax=#rptcedolino.idpayrolltax
			AND #computetax.nbracket=#rptcedolino.nbracket),0.0),
	
	employtaxgross= ISNULL((
		SELECT  #computetax.employtaxgross  
		FROM  #computetax
		WHERE  #computetax.idpayroll=#rptcedolino.idpayroll
			AND #computetax.idpayrolltax=#rptcedolino.idpayrolltax
			AND #computetax.nbracket=#rptcedolino.nbracket),0.0),
	taxable_percent=ISNULL((
		SELECT   #computetax.taxable_percent
		FROM #computetax
		WHERE  #computetax.idpayroll=#rptcedolino.idpayroll
			AND #computetax.idpayrolltax=#rptcedolino.idpayrolltax
			AND #computetax.nbracket=#rptcedolino.nbracket),0.0),
	deduction=ISNULL((
		SELECT   #computetax.deduction
		FROM #computetax
		WHERE  #computetax.idpayroll=#rptcedolino.idpayroll
			AND #computetax.idpayrolltax=#rptcedolino.idpayrolltax
			AND #computetax.nbracket=#rptcedolino.nbracket),0.0)
-- per le ritenute 'IRPEF' e le addizionali su 1 o più scaglioni prendo 
-- l'importo totale e non i singoli scaglioni
-- Laddove ci sono più scaglioni non visualizzo l'aliquota perchè non ha senso. 2° UPDATE
UPDATE  #rptcedolino 
SET  	tax =  ISNULL((
		SELECT #computetax.totimportotax  
		FROM   #computetax
		WHERE  #computetax.idpayroll=#rptcedolino.idpayroll
			AND #computetax.taxcode=#rptcedolino.taxcode
			AND #computetax.idpayrolltax=#rptcedolino.idpayrolltax
			AND #computetax.nbracket=#rptcedolino.nbracket),0.0)
WHERE   taxablecode IN ('IRPEF','ADDIRPEF')
UPDATE  #rptcedolino 
SET     taxable_percent = 0
WHERE   taxablecode IN ('IRPEF','ADDIRPEF')
AND     (SELECT count(*) 
		FROM  #rptcedolino R1 
		WHERE 
		 #rptcedolino.idpayroll  = R1.idpayroll AND
		 #rptcedolino.taxcode  = R1.taxcode AND	
		 #rptcedolino.idpayrolltax  = R1.idpayrolltax) >1
-- Per la ritenuta IRPEF mi serve solo una riga ,il valore di ta l'ho preso sopra
delete from #rptcedolino where (taxablecode IN('IRPEF','ADDIRPEF') and nbracket>1)
UPDATE #rptcedolino SET	
	tax= ISNULL((SELECT sum(isnull(i.tax,0) )
		FROM #rptcedolino as i 
		WHERE  i.idpayroll=#rptcedolino.idpayroll
			AND i.idpayrolltax=#rptcedolino.idpayrolltax
			AND i.taxablecode='IRPEF'),0.0)
	WHERE taxablecode='IRPEF'
UPDATE #rptcedolino SET	
	tax= ISNULL((SELECT sum(isnull(i.tax,0) )
		FROM #rptcedolino as i 
		WHERE  i.idpayroll=#rptcedolino.idpayroll
			AND i.idpayrolltax=#rptcedolino.idpayrolltax
			AND i.taxablecode='ADDIRPEF'),0.0)
	WHERE taxablecode='ADDIRPEF'
INSERT INTO #indirizzopagamento
(	idaddresskind,
	idreg	,
	address	,
	geo_city	,	
	geo_country	,		
	cap	)
SELECT
	idaddresskind,
	idreg, 
	registryaddress.address,
	case 
		when flagforeign = 'S' then isnull(geo_nation.title,'')+' '+isnull(registryaddress.location,'')
		else
		geo_city.title
	end,
	case
		when flagforeign = 'S' then ' '
		else
		geo_country.province
		end,	
	case	
		when flagforeign = 'S' then ' '
		else
		registryaddress.cap
	end
FROM registryaddress
left outer join geo_city
	ON geo_city.idcity = registryaddress.idcity
left outer join geo_country
	ON geo_city.idcountry = geo_country.idcountry
LEFT OUTER JOIN geo_nation
	ON geo_nation.idnation = registryaddress.idnation
WHERE 
	( registryaddress.active <>'N' 
	AND registryaddress.start = 
			(SELECT MAX(cdi.start) 
			FROM registryaddress cdi 
			WHERE cdi.idaddresskind = registryaddress.idaddresskind
			AND cdi.active <>'N' 
			AND ((cdi.stop is null) OR (cdi.stop >= @start)) 
			and cdi.idreg = registryaddress.idreg))
	AND (idreg IN (select idreg from  #rptcedolino))
DECLARE @codenostand varchar(20)
SET @codenostand = '07_SW_CER'
DECLARE @codestand varchar(20)
SET @codestand = '07_SW_DEF'
DECLARE @STAND int
SELECT @STAND = idaddress FROM address WHERE codeaddress = @codestand
DECLARE @NOSTAND int
SELECT @NOSTAND = idaddress FROM address WHERE codeaddress = @codenostand
delete #indirizzopagamento
	where #indirizzopagamento.idaddresskind <> @nostand
	and exists (
		select * from #indirizzopagamento r2 
		where #indirizzopagamento.idreg=r2.idreg
		and r2.idaddresskind = @nostand
	)
delete #indirizzopagamento
	where #indirizzopagamento.idaddresskind not in (@nostand, @stand)
	and exists (
		select * from #indirizzopagamento r2 
		where #indirizzopagamento.idreg=r2.idreg
		and r2.idaddresskind = @stand
	)
delete #indirizzopagamento
	where (
		select count(*) from #indirizzopagamento r2 
		where #indirizzopagamento.idreg=r2.idreg
	)>1
-- Cancello quelle righe per cui 'taxcode' è valorizzato ma l'importo della ritenuta è zero. Faccio la delete perchè in seguito all'introduzione del
-- LEFT OUTER JOIN nella SELECT principale potrei avere anche l'IRAP tra le ritenute.
DELETE FROM #rptcedolino where taxablecode is not null and isnull(tax,0) = 0
SELECT  
	C.idreg	,
	surname770	,
	forename770	,
	cf	,
	birthdate	,
	I.address	,
	I.geo_city	,
	I.geo_country	,	
	I.cap	,		
	service ,
	datebegin	,
	dateend	,
	duty	,
	grossamount	,
	taxablegross	,
	taxablenet,
	taxdescription ,
	taxablecode ,
	taxcode	,				
	tax	,	
	employtaxgross ,
	taxable_percent	,
	ritdipversataannua ,
	deduction	,
	feegross	,
	idpayroll	,
	flagbalance ,
	idpayrolltax	,
	datebegincontract	,
	dateendcontract ,
	nbracket 	
FROM  #rptcedolino C
LEFT OUTER JOIN #indirizzopagamento I
	ON C.idreg = I.idreg
ORDER BY idpayroll,idpayrolltax 
END

GO

print '[rpt_cedolino] OK'

GO
if object_id('[rpt_situazionebudget]') is not null
	drop PROCEDURE [rpt_situazionebudget]
go

CREATE   PROCEDURE [rpt_situazionebudget]
	@ayear	    	int,
	@stop    	datetime,
	@idsorkind  	int
	AS
	BEGIN
	CREATE TABLE #budgetsituation
		(
		idacc 			varchar(38), 
		code			varchar(50), 
		title			varchar(150), 
		nlevel			varchar(1),
		printingordacc		varchar(50),
		idsor			varchar(36),
		sortcode		varchar(50),
		description		varchar(200),
		rowkind			int,
		operationdate		datetime,
		operationkind		varchar(55),
		descroperation		varchar(150),
		ymov			int,
		nmov			integer,	
		amount			decimal(19,2),
		--idrelated		varchar(50),
		docrelated		varchar(50),
		datedocrelated		datetime,
		registry		varchar(100),
		initialprevision 	decimal(19,2),
		availableprevision	decimal(19,2) 			
		)
--previsioni iniziali per l'esercizio corrente
	INSERT INTO #budgetsituation
	      (
		idacc, 	
		code,			
		title,			
		nlevel,			
		printingordacc,		
		idsor,			
		sortcode,		
		description,	
		rowkind,
		operationdate,
		operationkind,	
		initialprevision 	
		)
	SELECT 
		accountusable.idacc, 	
		accountusable.codeacc,			
		title,			
		accountusable.nlevel,			
		printingorder,		
		sortingusable.idsor,			
		sortingusable.sortcode,		
		sortingusable.description,	
		1,
		null,
		'Prev. iniziale Budget',	
		isnull(prevision,0) 		
	        FROM accountusable cross join sortingusable
		--left outer join accountyear
		join accountyear
		on accountyear.idacc = accountusable.idacc
		AND accountyear.ayear = accountusable.ayear
		and accountyear.idsor = sortingusable.idsor
	        WHERE accountusable.ayear = @ayear and
	        sortingusable.idsorkind = @idsorkind
--select * from #budgetsituation
INSERT INTO #budgetsituation
	      (
		idacc, 	
		code,			
		title,			
		nlevel,			
		printingordacc,		
		idsor,			
		sortcode,		
		description,	
		rowkind,
		operationdate,
		operationkind,	
		descroperation,
		docrelated,
		datedocrelated,
		ymov,
		nmov,
		amount,
		initialprevision
		)
	SELECT 
		accountvardetail.idacc, 	
		accountusable.codeacc,			
		accountusable.title,			
		accountusable.nlevel,			
		printingorder,		
		accountvardetail.idsor,			
		sortingusable.sortcode,		
		sortingusable.description,	
		2,
		accountvar.adate,
		'Variaz. prev. Budget',	
		accountvar.description,
		isnull(accountvar.enactment,'') + space(1) + isnull(accountvar.nenactment,''),
		accountvar.enactmentdate, 
		accountvar.yvar,
		accountvar.nvar,
		isnull(accountvardetail.amount,0),
		0 		
	from    accountvar
 	join    accountvardetail
	ON      accountvar.yvar = accountvardetail.yvar
	AND     accountvar.nvar = accountvardetail.nvar
	LEFT OUTER JOIN    #budgetsituation R
	ON      R.idacc = accountvardetail.idacc
	AND     R.idsor = accountvardetail.idsor
	AND     R.rowkind = 1
	JOIN  accountusable 
	ON accountusable.idacc = accountvardetail.idacc
	join sortingusable
	ON sortingusable.idsor = accountvardetail.idsor
	
	where   accountvar.adate <= @stop
	and     accountvar.yvar = @ayear
	and      accountusable.ayear = @ayear and
	        sortingusable.idsorkind = @idsorkind
--select * from #budgetsituation where rowkind = 2
INSERT INTO #budgetsituation
	      (
		idacc, 	
		code,			
		title,			
		nlevel,			
		printingordacc,		
		idsor,			
		sortcode,		
		description,	
		rowkind,
		operationdate,
		operationkind,	
		descroperation,
		docrelated,
		datedocrelated,
		ymov,
		nmov,
		registry,
		amount,
		--idrelated 	
		initialprevision
		)
	SELECT 
		epexpsorting.idacc, 	
		accountusable.codeacc,			
		accountusable.title,			
		accountusable.nlevel,			
		printingorder,		
		epexpsorting.idsor,			
		sortingusable.sortcode,		
		sortingusable.description,	
		3,
		epexpsorting.adate,
		'Impegno di Budget',	
		epexp.description,
		epexp.doc,
		epexp.docdate,
		epexpsorting.yepexp,
		epexpsorting.nepexp,
		registry.title,
		isnull(epexpsorting.amount,0),
		--epexp.idrelated 	
		0	
	from epexp
	join epexpsorting
	ON   epexp.yepexp = epexpsorting.yepexp
	AND epexp.nepexp = epexpsorting.nepexp
	AND epexpsorting.kind = 'N'
	LEFT OUTER JOIN   #budgetsituation R
	ON     R.idacc = epexpsorting.idacc
	AND    R.idsor = epexpsorting.idsor
	AND    R.rowkind = 1
	JOIN   registry on 
	epexp.idreg = registry.idreg
	JOIN  accountusable 
	ON accountusable.idacc = epexpsorting.idacc
	join sortingusable
	ON sortingusable.idsor = epexpsorting.idsor
	where epexp.adate <= @stop
	and epexp.yepexp = @ayear
	and accountusable.ayear = @ayear
	and sortingusable.idsorkind = @idsorkind
--select '3',* from #budgetsituation where rowkind = 3
INSERT INTO #budgetsituation
	      (
		idacc, 	
		code,			
		title,			
		nlevel,			
		printingordacc,		
		idsor,			
		sortcode,		
		description,	
		rowkind,
		operationdate,
		operationkind,	
		descroperation,
		docrelated,
		datedocrelated,
		ymov,
		nmov,
		registry,
		amount,
		--idrelated 	
		initialprevision
		)
	SELECT 
		epexpsorting.idacc, 	
		accountusable.codeacc,			
		accountusable.title,			
		accountusable.nlevel,			
		printingorder,		
		epexpsorting.idsor,			
		sortingusable.sortcode,		
		sortingusable.description,	
		4,
		epexpsorting.adate,
		'Variaz. Impegno di Budget',	
		epexp.description,
		epexp.doc,
		epexp.docdate,
		epexpsorting.yepexp,
		epexpsorting.nepexp,
		registry.title,
		isnull(epexpsorting.amount,0),
		--epexp.idrelated 	
		0	
	from epexp
	join epexpsorting
	ON   epexp.yepexp = epexpsorting.yepexp
	AND epexp.nepexp = epexpsorting.nepexp
	AND epexpsorting.kind = 'V'
	LEFT OUTER JOIN   #budgetsituation R
	ON     R.idacc = epexpsorting.idacc
	AND    R.idsor = epexpsorting.idsor
	AND    R.rowkind = 1
	JOIN   registry on 
	epexp.idreg = registry.idreg
	JOIN  accountusable 
	ON accountusable.idacc = epexpsorting.idacc
	join sortingusable
	ON sortingusable.idsor = epexpsorting.idsor
	where epexp.adate <= @stop
	and epexp.yepexp = @ayear
	and accountusable.ayear = @ayear
	and sortingusable.idsorkind = @idsorkind
--select '4',* from #budgetsituation where rowkind = 4
--Inserisco una riga con previsione 0 per quelle coppie conto oper. -  voce di classificazione oper.
--in cui non è stata impostata una previsione iniziale ma sono state movimentate in seguito
--(con variazioni in aumento ecc.)
INSERT INTO #budgetsituation
	      (
		idacc, 	
		code,			
		title,			
		nlevel,			
		printingordacc,		
		idsor,			
		sortcode,		
		description,	
		rowkind,
		operationdate,
		operationkind,	
		initialprevision
		)
	SELECT 
		DISTINCT
		accountusable.idacc, 	
		accountusable.codeacc,			
		accountusable.title,			
		accountusable.nlevel,			
		printingorder,		
		sortingusable.idsor,			
		sortingusable.sortcode,		
		sortingusable.description,	
		1,
		null,
		'Prev. iniziale Budget',	
		0	
	        FROM #budgetsituation R
		JOIN accountusable 
		ON accountusable.idacc = R.idacc
		join sortingusable
		ON sortingusable.idsor = R.idsor
	        WHERE  EXISTS (select * from  #budgetsituation i
				  where R.idacc=i.idacc AND 
				  R.idsor=i.idsor AND 
				  i.rowkind>1) AND
			NOT EXISTS (select * from  #budgetsituation j
				  where R.idacc=j.idacc AND 
				  R.idsor=j.idsor AND 
				  j.rowkind=1) AND
			
		accountusable.ayear = @ayear and
	        sortingusable.idsorkind = @idsorkind
DECLARE @sortingkind varchar(50)
SELECT @sortingkind  = description from sortingkind where idsorkind = @idsorkind
select @sortingkind, * from #budgetsituation
order by printingordacc,sortcode,operationdate,rowkind
END

GO

print '[rpt_situazionebudget] OK'

