if object_id('exp_prevavailable_upb_fin') is not null
	drop PROCEDURE exp_prevavailable_upb_fin
go

--sp_help upbtotal
CREATE       PROCEDURE exp_prevavailable_upb_fin
(
	@ayear int,
	@finpart char(1)
)
AS BEGIN
DECLARE @finphase tinyint
DECLARE @maxphase tinyint
DECLARE @fin_kind tinyint
SELECT  @fin_kind = fin_kind 
FROM    config WHERE ayear = @ayear
CREATE TABLE #previsionupbfin
(
	ayear int,
	idupb varchar(36),
	codeupb varchar(50),
	upb varchar(150),
	idfin int,
	codefin varchar(50),
	fin varchar(150),
	finlevel varchar(50),
	incomeprevavailable_comp decimal(19,2),	
	incomeprevavailable_cash decimal(19,2),
	expenseprevavailable_comp decimal(19,2),
	expenseprevavailable_cash decimal(19,2)
)
--sp_help upb
INSERT INTO #previsionupbfin
(
	ayear,
	idupb,
	codeupb,
	upb,
	idfin,
	codefin,
	fin,
	finlevel
)
SELECT @ayear,
       U.idupb,
       U.codeupb,
       U.title,
       F.idfin,
       F.codefin,
       F.title,
       L.description
FROM   upb U 
CROSS  JOIN   fin F
JOIN finlast FL 
	ON FL.idfin = F.idfin 
JOIN finlevel L
	ON L.nlevel = F.nlevel 
WHERE  F.ayear = @ayear AND L.ayear = @ayear
AND    (((@finpart = 'S') AND ((F.flag & 1) <> 0))  OR
       	((@finpart = 'E') AND ((F.flag & 1) = 0)))
ORDER BY codeupb, codefin
IF (@finpart = 'S') 
BEGIN
	SELECT @finphase = expensefinphase FROM uniconfig
	SELECT @maxphase = MAX (nphase) FROM expensephase
	
	IF (@fin_kind IN (1,3))  
	UPDATE #previsionupbfin 
	SET expenseprevavailable_comp = 
	(SELECT
		ISNULL(UT.currentprev,0) + 
		ISNULL(UT.previsionvariation,0) - 
		ISNULL(UET.totalcompetency,0) 
	FROM  upbtotal UT 
	LEFT OUTER JOIN upbexpensetotal UET 
		ON UET.idfin = UT.idfin
		AND UET.idupb = UT.idupb
		AND UET.nphase = @finphase
	WHERE UT.idupb = #previsionupbfin.idupb AND
	      UT.idfin = #previsionupbfin.idfin) 
	
	IF (@fin_kind = 2 )   
	UPDATE #previsionupbfin 
	SET expenseprevavailable_cash = 
	(SELECT
		ISNULL(UT.currentprev,0) + 
		ISNULL(UT.previsionvariation,0) - 
		ISNULL(UET.totalcompetency,0) -
		ISNULL(UET.totalarrears, 0)
	FROM  upbtotal UT 
	LEFT OUTER JOIN upbexpensetotal UET 
		ON UET.idfin = UT.idfin
		AND UET.idupb = UT.idupb
		AND UET.nphase = @maxphase
	WHERE UT.idupb = #previsionupbfin.idupb AND
	      UT.idfin = #previsionupbfin.idfin) 
	
	
	IF (@fin_kind = 3 )   
	UPDATE #previsionupbfin 
	SET expenseprevavailable_cash = 
	(SELECT
		ISNULL(UT.currentsecondaryprev,0) + 
		ISNULL(UT.secondaryvariation,0) - 
		ISNULL(UET.totalcompetency,0) -
		ISNULL(UET.totalarrears, 0)
	FROM  upbtotal UT 
	LEFT OUTER JOIN upbexpensetotal UET 
		ON UET.idfin = UT.idfin
		AND UET.idupb = UT.idupb
		AND UET.nphase = @maxphase
	WHERE UT.idupb = #previsionupbfin.idupb AND
	      UT.idfin = #previsionupbfin.idfin) 
END
ELSE -- @finpart = 'E'
BEGIN 
	SELECT @finphase = incomefinphase FROM uniconfig
	SELECT @maxphase = MAX (nphase)  FROM  incomephase
	IF (@fin_kind IN (1,3))  
	UPDATE #previsionupbfin 
	SET incomeprevavailable_comp = 
	(SELECT
		ISNULL(UT.currentprev,0) + 
		ISNULL(UT.previsionvariation,0) - 
		ISNULL(UET.totalcompetency,0) 
	FROM  upbtotal UT 
	LEFT OUTER JOIN upbincometotal UET 
		ON UET.idfin = UT.idfin
		AND UET.idupb = UT.idupb
		AND UET.nphase = @finphase
	WHERE UT.idupb = #previsionupbfin.idupb AND
	      UT.idfin = #previsionupbfin.idfin) 
	IF (@fin_kind = 2 )   
	UPDATE #previsionupbfin 
	SET incomeprevavailable_cash = 
	(SELECT
		ISNULL(UT.currentprev,0) + 
		ISNULL(UT.previsionvariation,0) - 
		ISNULL(UET.totalcompetency,0) -
		ISNULL(UET.totalarrears, 0)
	FROM  upbtotal UT 
	LEFT OUTER JOIN upbincometotal UET 
		ON UET.idfin = UT.idfin
		AND UET.idupb = UT.idupb
		AND UET.nphase = @maxphase
	WHERE UT.idupb = #previsionupbfin.idupb AND
	      UT.idfin = #previsionupbfin.idfin) 
	
	IF (@fin_kind = 3 )   
	UPDATE #previsionupbfin 
	SET incomeprevavailable_cash = 
	(SELECT
		ISNULL(UT.currentsecondaryprev,0) + 
		ISNULL(UT.secondaryvariation,0) - 
		ISNULL(UET.totalcompetency,0)-
		ISNULL(UET.totalarrears, 0)
	FROM  upbtotal UT 
	LEFT OUTER JOIN upbincometotal UET 
		ON UET.idfin = UT.idfin
		AND UET.idupb = UT.idupb
		AND UET.nphase = @maxphase
	WHERE UT.idupb = #previsionupbfin.idupb AND
	      UT.idfin = #previsionupbfin.idfin) 
	
END
	IF (@finpart = 'S') 
	BEGIN
		IF (@fin_kind = 1)  BEGIN
			SELECT 
			'Spesa' AS 'Parte Bil.',
			codeupb AS 'Cod. U.P.B.',
			upb AS 'U.P.B.',
			finlevel AS 'Livello',
			codefin AS 'Cod. Bilancio',
			fin AS 'Bilancio',
			expenseprevavailable_comp AS 'Disponibilità ad Impegnare'
			FROM #previsionupbfin
			WHERE ISNULL(expenseprevavailable_comp,0)<>0
		END
		IF (@fin_kind = 2)   BEGIN
			SELECT 'Spesa' AS 'Parte Bil.',
			codeupb AS 'Cod. U.P.B.',
			upb AS 'U.P.B.',
			finlevel AS 'Livello',
			codefin AS 'Cod. Bilancio',
			fin AS 'Bilancio',
			expenseprevavailable_cash AS 'Disponibilità a Pagare'
			FROM #previsionupbfin
			WHERE ISNULL(expenseprevavailable_cash,0)<>0
		END
		IF (@fin_kind = 3)   BEGIN
			SELECT 'Spesa' AS 'Parte Bil.',
			codeupb AS 'Cod. U.P.B.',
			upb AS 'U.P.B.',
			finlevel AS 'Livello',
			codefin AS 'Cod. Bilancio',
			fin AS 'Bilancio',
			expenseprevavailable_comp AS 'Disponibilità ad Impegnare',
			expenseprevavailable_cash AS 'Disponibilità a Pagare'
			FROM #previsionupbfin
			WHERE ISNULL(expenseprevavailable_cash,0)<>0 OR 
			ISNULL(expenseprevavailable_comp,0)<>0
		END
	END
	ELSE
	BEGIN
		IF (@fin_kind = 1)  BEGIN
			SELECT 
			'Entrata' AS 'Parte Bil.',
			codeupb AS 'Cod. U.P.B.',
			upb AS 'U.P.B.',
			finlevel AS 'Livello',
			codefin AS 'Cod. Bilancio',
			fin AS 'Bilancio',
			incomeprevavailable_comp AS 'Disponibilità ad Accertare'
			FROM #previsionupbfin
			WHERE ISNULL(incomeprevavailable_comp,0)<>0
		END
		IF (@fin_kind = 2)   BEGIN
			SELECT 'Entrata' AS 'Parte Bil.',
			codeupb AS 'Cod. U.P.B.',
			upb AS 'U.P.B.',
			finlevel AS 'Livello',
			codefin AS 'Cod. Bilancio',
			fin AS 'Bilancio',
			incomeprevavailable_cash AS 'Disponibilità ad Incassare'
			FROM #previsionupbfin
			WHERE ISNULL(incomeprevavailable_cash,0)<>0
		END
		IF (@fin_kind = 3)   BEGIN
			SELECT 'Entrata' AS 'Parte Bil.',
			codeupb AS 'Cod. U.P.B.',
			upb AS 'U.P.B.',
			finlevel AS 'Livello',
			codefin AS 'Cod. Bilancio',
			fin AS 'Bilancio',
			incomeprevavailable_comp AS 'Disponibilità ad Accertare',
			incomeprevavailable_cash AS 'Disponibilità a Incassare'
			FROM #previsionupbfin
			WHERE ISNULL(incomeprevavailable_cash,0)<>0 OR 
			ISNULL(incomeprevavailable_comp,0)<>0
		END
	END
	
END


GO

print 'exp_prevavailable_upb_fin OK'

GO
if object_id('[exp_unified_riepilogo_ritenute_applicate]') is not null
	drop PROCEDURE [exp_unified_riepilogo_ritenute_applicate]
go

CREATE       PROCEDURE [exp_unified_riepilogo_ritenute_applicate]
  @ayear int, 
  @idreg int,
  @tax int,
  @start datetime,
  @stop datetime,
  @idser int,             
  @unified_mov varchar(1),-- consolidamento dei movimenti del percipiente
  @unified char(1),	  -- consolidamento delle ritenute applicate,
  @show_registry char(1)  -- visualizza o meno le info sul percipiente(può valere N solo in caso di consolidamento)     
AS
BEGIN
--@show_registry se vale N, scelgo di non visualizzare le info sul percipiente e di totalizzare tutto
--sui dipartimenti
IF ((@show_registry = 'N') AND (@unified = 'N'))
BEGIN
	-- solo per la stampa consolidata posso scegliere di non vedere il percipiente 
	SET @show_registry = 'S' 
END

IF (@unified <> 'S')
BEGIN
-- L'ultimo parametro denota la visualizzazione del dipartimento.Sarà sempre NO per la stampa "normale"
        DECLARE @show_department char(1)
        SET @show_department='N'
        EXEC exp_riepilogo_ritenute_applicate @ayear,@idreg,@tax,@start,@stop,@idser,@unified_mov,@show_department
        RETURN
END 
CREATE TABLE #unifiedtax
(
        departmentname varchar(500),
	employtax_liq_periodo decimal(19,2),    --A
	admintax_liq_periodo decimal(19,2),     --A
	employtax_operate_prec decimal(19,2),   --B
	admintax_operate_prec decimal(19,2),    --B
	employtax_non_liq decimal(19,2),        --C
	admintax_non_liq decimal(19,2),         --C
        employtax_liq_tot decimal(19,2),
        admintax_liq_tot decimal(19,2),
-- info relativa ala percipiente
        title varchar(100),
	cf varchar(16),
        surname varchar(50),
        forename varchar(50),
        birthdate datetime, 
        GC_title varchar(65),
        GP_province varchar(2), 
        GN_title varchar(65),
        gender varchar(1),
-- info relative al mov. si spesa servono in caso si decida di consolidare
	nmov int,
	ymov int,
	desc_exp varchar(150),
      	servicedescription varchar(50),
	servicestart datetime,
	servicestop datetime,
-- info relative all'indirizzo
    	address varchar(100),
    	location varchar(65),
    	province varchar(2),
    	nation varchar(65),
    	cap varchar(20),
-- info relative al comune e regione fiscale
        GC_tax_title varchar(65), 
        fiscal_region varchar(50),
        taxdescription varchar(50)
)
DECLARE @iddbdepartment varchar(50)
DECLARE @crsdepartment cursor
SET @crsdepartment = cursor FOR SELECT iddbdepartment FROM dbdepartment
								WHERE (start is null or start <= @ayear ) AND ( stop is null or stop >= @ayear)
OPEN @crsdepartment
FETCH NEXT FROM @crsdepartment INTO @iddbdepartment
WHILE @@fetch_status=0 begin
	DECLARE @dip_nomesp varchar(300)
	SET @dip_nomesp = @iddbdepartment + '.exp_riepilogo_ritenute_applicate'
		INSERT INTO #unifiedtax (
			departmentname,
                        ymov,
                        nmov,
                        title,
                	cf,
                        surname,
                        forename,
                        birthdate, 
                        GC_title,
                        GP_province, 
                        GN_title,
                        gender,
                	servicedescription,
                        desc_exp,
                        servicestart,
                        servicestop,
                        address,
                        location,
                        province,
                        nation,
                        cap,
                        GC_tax_title, 
                        fiscal_region,
                        taxdescription,
                        employtax_liq_periodo,
                        employtax_operate_prec,
                        employtax_non_liq,
                        employtax_liq_tot,
                        
                        admintax_liq_periodo,
                        admintax_operate_prec,
                        admintax_non_liq,
                        admintax_liq_tot
    		)
		EXEC @dip_nomesp @ayear,@idreg,@tax,@start,@stop,@idser,'N','S'
	FETCH NEXT FROM @crsdepartment INTO @iddbdepartment
end
-- NON visualizza le info sul percipiente
IF (@show_registry='N')   
BEGIN
	
	SELECT
        departmentname as 'Dipartimento',
        taxdescription as 'Ritenuta',
        ISNULL(SUM(employtax_liq_periodo),0) AS 'Rit/Dip. applicate e liquidate nel periodo',--A
        ISNULL(SUM(employtax_operate_prec),0) AS 'Rit/Dip. applicate in periodi prec. e liquidate nel periodo',--B
        ISNULL(SUM(employtax_non_liq),0) AS 'Rit/Dip. applicate nel periodo e non liquidate nel periodo',--C
        ISNULL(SUM(employtax_liq_tot),0) AS 'Tot. Rit/Dip. Liquidato',-- A+B
        ISNULL(SUM(admintax_liq_periodo),0) AS 'Contributi applicati e liquidati nel periodo',--A
        ISNULL(SUM(admintax_operate_prec),0) AS 'Contributi applicati in periodi prec. e liquidate nel periodo',--B
        ISNULL(SUM(admintax_non_liq),0) AS 'Contributi applicati nel periodo e non liquidate nel periodo', --C
        ISNULL(SUM(admintax_liq_tot),0) AS 'Tot. Contributi Liquidati'-- A+B
        FROM #unifiedtax
        GROUP BY departmentname, taxdescription
        ORDER BY taxdescription
	
END
ELSE
-- Visualizza le INFO sul percipiente dettagliate o meno a seconda di @unified_mov
BEGIN 
	IF (@unified_mov='N') 
	BEGIN
	       SELECT
	        departmentname as 'Dipartimento',
	        ymov as 'Eserc.Mov',
	        nmov as 'Num.Mov.',
	        title as 'Percipiente',
			cf 'C.F.',
	        surname as 'Cognome', forename as 'Nome',
	        birthdate as 'data Nascita', 
	        GC_title as 'Luogo Nascita',
	        GP_province as 'Prov.Nascita', 
	        GN_title as 'Stato Nascita',
	        gender as 'Sesso',
			servicedescription as 'Prestazione',
	        desc_exp as 'Descr.Spesa',
	        servicestart as 'Inizio Prest.',
	        servicestop as 'Fine Prest.',
	        address as 'Indirizzo',
	        location as 'Località',
	        province as 'Provincia',
	        nation as 'Stato',
	        cap as 'CAP',
	        GC_tax_title as 'Comune', 
	        fiscal_region as 'Regione Fiscale',
	        taxdescription as 'Ritenuta',
	        ISNULL(SUM(employtax_liq_periodo),0) AS 'Rit/Dip. applicate e liquidate nel periodo',--A
	        ISNULL(SUM(employtax_operate_prec),0) AS 'Rit/Dip. applicate in periodi prec. e liquidate nel periodo',--B
	        ISNULL(SUM(employtax_non_liq),0) AS 'Rit/Dip. applicate nel periodo e non liquidate nel periodo',--C
	        ISNULL(SUM(employtax_liq_tot),0) AS 'Tot. Rit/Dip. Liquidato',-- A+B
	
	        ISNULL(SUM(admintax_liq_periodo),0) AS 'Contributi applicati e liquidati nel periodo',--A
	        ISNULL(SUM(admintax_operate_prec),0) AS 'Contributi applicati in periodi prec. e liquidate nel periodo',--B
	        ISNULL(SUM(admintax_non_liq),0) AS 'Contributi applicati nel periodo e non liquidate nel periodo', --C
	        ISNULL(SUM(admintax_liq_tot),0) AS 'Tot. Contributi Liquidati'-- A+B
	      FROM #unifiedtax
		GROUP BY cf,title,departmentname,taxdescription,servicedescription, GC_tax_title ,fiscal_region,
	                surname, forename,birthdate,GC_title,GP_province, 
	                GN_title, gender,address,location,province,nation,cap,
	                ymov, nmov,desc_exp,servicestart,servicestop
	        ORDER BY taxdescription, title
	END
	IF (@unified_mov='S') 
	BEGIN
	      SELECT
	        departmentname as 'Dipartimento',
	        title as 'Percipiente',
			cf 'C.F.',
	        surname as 'Cognome', forename as 'Nome',
	        birthdate as 'data Nascita', 
	        GC_title as 'Luogo Nascita',
	        GP_province as 'Prov.Nascita', 
	        GN_title as 'Stato Nascita',
	        gender as 'Sesso',
	        address as 'Indirizzo',
	        location as 'Località',
	        province as 'Provincia',
	        nation as 'Stato',
	        cap as 'CAP',
	        GC_tax_title as 'Comune', 
	        fiscal_region as 'Regione Fiscale',
	        taxdescription as 'Ritenuta',
	        ISNULL(SUM(employtax_liq_periodo),0) AS 'Rit/Dip. applicate e liquidate nel periodo',--A
	        ISNULL(SUM(employtax_operate_prec),0) AS 'Rit/Dip. applicate in periodi prec. e liquidate nel periodo',--B
	        ISNULL(SUM(employtax_non_liq),0) AS 'Rit/Dip. applicate nel periodo e non liquidate nel periodo',--C
	        ISNULL(SUM(employtax_liq_tot),0) AS 'Tot. Rit/Dip. Liquidato',-- A+B
	
	        ISNULL(SUM(admintax_liq_periodo),0) AS 'Contributi applicati e liquidati nel periodo',--A
	        ISNULL(SUM(admintax_operate_prec),0) AS 'Contributi applicati in periodi prec. e liquidate nel periodo',--B
	        ISNULL(SUM(admintax_non_liq),0) AS 'Contributi applicati nel periodo e non liquidate nel periodo', --C
	        ISNULL(SUM(admintax_liq_tot),0) AS 'Tot. Contributi Liquidati'-- A+B
	        FROM #unifiedtax
	        GROUP BY cf,title,departmentname, taxdescription,GC_tax_title, fiscal_region,
	                surname, forename,birthdate,GC_title,GP_province, 
	                GN_title, gender,address,location,province,nation,cap
	        ORDER BY taxdescription, title
	END
END

END



GO

print '[exp_unified_riepilogo_ritenute_applicate] OK'

