if object_id('[trigger_u_parasubcontract]') is not null
	drop TRIGGER [trigger_u_parasubcontract]
go

CREATE        TRIGGER [trigger_u_parasubcontract] ON [parasubcontract] FOR UPDATE
AS BEGIN
	CREATE TABLE #paras
	(
		idcon varchar(8),
		iddbdepartment varchar(50),
		idreg int 
	)
	INSERT INTO #paras (idcon, iddbdepartment, idreg)
	SELECT I.idcon, USER, I.idreg
	FROM deleted D
	JOIN inserted I
		ON D.idcon = I.idcon
	WHERE D.idreg <> I.idreg
	IF (SELECT COUNT(*) FROM #paras) = 0
	BEGIN
		DROP TABLE #paras
		RETURN
	END
	UPDATE parasubcontractlist
	SET parasubcontractlist.idreg = #paras.idreg
	FROM #paras
	WHERE parasubcontractlist.idcon = #paras.idcon
		AND parasubcontractlist.iddbdepartment = #paras.iddbdepartment
	
	DROP TABLE #paras
END


GO

print '[trigger_u_parasubcontract] OK'

