CREATE           PROCEDURE [esporta_buoni_scarico_ente]
	@year			int,
	@idinventoryagency	int,
	@startnumber		int,
	@stopnumber		int
AS BEGIN
	SELECT
		inventoryagency.codeinventoryagency	as 'Cod. Ente Inventario',
		inventoryagency.description  	as 'Ente Inventario', 
		inventory.description     	as 'Inventario',  
		inventorykind.description  	as 'Tipo Inventario',
		assetunloadkind.codeassetunloadkind 	as 'Codice Tipo Buono',
		assetunloadkind.description 	as 'Tipo Buono',
		assetunload.yassetunload        as 'Eserc. Buono Scarico',
		assetunload.nassetunload        as 'Num. Buono Scarico',
		registry.title			as 'Cessionario',
		assetunloadmotive.codemot	as 'Cod. Causale Scarico',
		assetunloadmotive.description   as 'Causale Scarico', 
		assetunload.doc			as 'Documento',
		assetunload.docdate		as 'Data Doc.',
		assetunload.enactment		as 'Provvedimento',
		assetunload.enactmentdate	as 'Data Provv.',
		assetunload.adate		as 'Emesso',
		assetunload.printdate		as 'Stampato',
		assetunload.ratificationdate	as 'Ratificato',
		assetunload.txt			as 'Note'
	FROM 
		assetunload
	LEFT OUTER JOIN registry
		ON assetunload.idreg = registry.idreg
	LEFT OUTER JOIN assetunloadmotive
		ON assetunload.idmot = assetunloadmotive.idmot 
	JOIN assetunloadkind
		on assetunloadkind.idassetunloadkind = assetunload.idassetunloadkind
 	JOIN inventory
 		ON assetunloadkind.idinventory = inventory.idinventory
	JOIN  inventoryagency
		ON inventory.idinventoryagency = inventoryagency.idinventoryagency
	JOIN  inventorykind
		ON inventorykind.idinventorykind = inventory.idinventorykind
	WHERE assetunload.yassetunload = @year
	AND inventoryagency.idinventoryagency = @idinventoryagency
	AND assetunload.nassetunload BETWEEN @startnumber AND @stopnumber
	
END


GO

