CREATE   PROCEDURE exp_unified_ritenute_applicate_impon
(
  @ayear int, 
  @idreg int, 
  @tax   int,
  @idser int,  
  @start datetime,
  @stop  datetime,
  @mode  char(1),
  @unified_mov char(1), -- consolidamento dei movimenti del percipiente
  @show_department char(1),
  @show_month char(1),
  @unified char(1) -- consolidamento delle ritenute applicate
) 
as begin
CREATE TABLE #unifiedtax 
(
	monthtaxpay varchar(2),
	departmentname  varchar(150),
	nmov int,
	ymov int,
    npay int,
	codefin varchar(50),
	codeupb varchar(50),
	title varchar(100),
	cf varchar(16),
	taxdescription varchar(150),
	surname varchar(50),
	forename varchar(50),
	p_iva varchar(15),
	birthdate datetime,
	GC_title varchar(65),
	GP_province varchar(2),
	GN_title varchar(65),
	gender char(1), 
	desc_exp varchar(150),
	service_description varchar(50),
	servicestart datetime,
	servicestop datetime,
	address varchar(100),
	location varchar(65),
	province varchar(2),
	nation varchar(65),
	cap varchar(20),
	GC_tax_title  varchar(65),  
	fiscale_region varchar(50),
	taxablegross decimal(19,2),
	taxablenet decimal(19,2),
	employtax decimal(19,2),
	admintax decimal(19,2),
	abatements decimal(19,2)
)
IF (@unified <> 'S')
BEGIN
        EXEC exp_riepilogo_ritenute_applicate_impon @ayear,@idreg,@tax,@idser,@start,@stop,@mode,@unified_mov,@show_department,@show_month
        RETURN
END 
DECLARE @iddbdepartment varchar(50)
DECLARE @crsdepartment cursor
SET @crsdepartment = cursor FOR SELECT iddbdepartment FROM dbdepartment
								where (start is null or start <= @ayear ) AND ( stop is null or stop >= @ayear) 
OPEN @crsdepartment
FETCH NEXT FROM @crsdepartment INTO @iddbdepartment
WHILE @@fetch_status=0 begin
	DECLARE @dip_nomesp varchar(300)
	SET @dip_nomesp = @iddbdepartment + '.exp_riepilogo_ritenute_applicate_impon'
-- Chiamo la sp con @unified_mov = N, @show_department = S e @show_month = S per ricevere TUTTI i dati, in output li elaboro.
		INSERT INTO #unifiedtax (
			monthtaxpay,departmentname,
			nmov,ymov,npay,
			codefin, codeupb,
			title,cf,
			taxdescription,
			surname,forename,p_iva,
			birthdate,GC_title,GP_province,GN_title,
			gender,desc_exp,
			service_description,servicestart,servicestop,
			address,location,province,nation,cap,
			GC_tax_title, fiscale_region,
			taxablegross,taxablenet,employtax,admintax,abatements
		)
		EXEC @dip_nomesp @ayear,@idreg,@tax,@idser,@start,@stop,@mode,'N','S','S'
	FETCH NEXT FROM @crsdepartment INTO @iddbdepartment
end
IF (@mode = 'T')
BEGIN
  IF (@unified_mov = 'S')--@unified_mov = 'S' non mostro i dettagli dei movimenti per percipiente.
  BEGIN
        IF( @show_department = 'S') AND @show_month ='S'
        BEGIN
                SELECT
                        monthtaxpay as 'Mese ',
                        departmentname as 'Dipartimento',
                        title as Percipiente,
                		cf as 'CF',
                        taxdescription as 'Ritenuta',  
                        surname as 'Cognome', forename as 'Nome',
                        p_iva as 'P.iva',
                        birthdate as 'data Nascita', GC_title as 'Luogo Nascita',
                        GP_province as 'Prov.Nascita', GN_title as 'Stato Nascita',
                		gender as 'Sesso',
                        address as 'Indirizzo',location as 'Località',province as 'Provincia',
                    	nation as 'Stato',cap as 'CAP',
                        GC_tax_title as 'Comune', 
                        fiscale_region as 'Regione Fiscale',
                        taxablegross as ' Imponibile Lordo',taxablenet as 'Imponibile Netto',
                        employtax as 'Rit.Dip.',admintax as 'Rit.Amm.',
                        abatements as 'Detrazioni Applicate'  
        	FROM #unifiedtax
        	ORDER BY title, cf,taxdescription
        END
        IF( @show_department = 'S') AND @show_month ='N'
        BEGIN
                SELECT
                        departmentname as 'Dipartimento',
                        title as Percipiente,
                		cf as 'CF',
                        taxdescription as 'Ritenuta',  
                        surname as 'Cognome', forename as 'Nome',
                        p_iva as 'P.iva',
                        birthdate as 'data Nascita', GC_title as 'Luogo Nascita',
                        GP_province as 'Prov.Nascita', GN_title as 'Stato Nascita',
                		gender as 'Sesso',
                        address as 'Indirizzo',location as 'Località',province as 'Provincia',
                    	nation as 'Stato',cap as 'CAP',
                        GC_tax_title as 'Comune', 
                        fiscale_region as 'Regione Fiscale',
                        taxablegross as ' Imponibile Lordo',taxablenet as 'Imponibile Netto',
                        employtax as 'Rit.Dip.',admintax as 'Rit.Amm.',
                        abatements as 'Detrazioni Applicate'  
        	FROM #unifiedtax
        	ORDER BY title, cf,taxdescription
        END
        IF( @show_department = 'N') AND @show_month ='S'
        BEGIN
                SELECT
                        monthtaxpay as 'Mese ',
                        title as Percipiente,
                		cf as 'CF',
                        taxdescription as 'Ritenuta',  
                        surname as 'Cognome', forename as 'Nome',
                        p_iva as 'P.iva',
                        birthdate as 'data Nascita', GC_title as 'Luogo Nascita',
                        GP_province as 'Prov.Nascita', GN_title as 'Stato Nascita',
                		gender as 'Sesso',
                        address as 'Indirizzo',location as 'Località',province as 'Provincia',
                    	nation as 'Stato',cap as 'CAP',
                        GC_tax_title as 'Comune', 
                        fiscale_region as 'Regione Fiscale',
                        taxablegross as ' Imponibile Lordo',taxablenet as 'Imponibile Netto',
                        employtax as 'Rit.Dip.',admintax as 'Rit.Amm.',
                        abatements as 'Detrazioni Applicate'  
        	FROM #unifiedtax
        	ORDER BY title, cf,taxdescription
        END
        IF( @show_department = 'N') AND @show_month ='N'
        BEGIN
                SELECT
