                        abatements as 'Detrazioni Applicate'  
        	FROM #unifiedtax
        	ORDER BY title, cf,taxdescription
        END
  END
  ELSE -- ossia : @unified_mov = 'N' mostro anche i dettagli dei movimenti per percipiente.
  BEGIN
        IF( @show_department = 'S') AND @show_month ='S'
        BEGIN
