if object_id('copyrow_invoicekind') is not null
	drop PROCEDURE copyrow_invoicekind
go

CREATE  	PROCEDURE copyrow_invoicekind
(
	@idinvkind int
)
AS BEGIN
 declare @query nvarchar(3000)
 declare @query1 nvarchar(3000)
 declare @iddbdepartment varchar(50)
 declare  @idinvkindstr varchar(10)
 declare @codeinvkindstr varchar(100)
 declare @codeinvkind varchar(100)
 set @idinvkindstr= convert(varchar,@idinvkind)
 SELECT  @codeinvkind = codeinvkind from invoicekind where idinvkind=@idinvkind
 set @codeinvkindstr= ''''+ replace(@codeinvkind,'''','''''')+''''
 
 declare @amm varchar(100)
 set @amm=user
 --set @amm='amm'
 --print user

CREATE TABLE #registerkind (codeivaregisterkind varchar(200))
insert into #registerkind (codeivaregisterkind)
SELECT IRK.codeivaregisterkind from invoicekindregisterkind IKR
		JOIN ivaregisterkind IRK
			ON IKR.idivaregisterkind = IRK.idivaregisterkind
WHERE IKR.idinvkind = @idinvkind
	
		
 DECLARE @crsdepartment CURSOR
 SET 	@crsdepartment = cursor for select  iddbdepartment from dbdepartment where iddbdepartment<>@amm order by iddbdepartment
 OPEN 	@crsdepartment
 fetch next from @crsdepartment into @iddbdepartment
 while @@fetch_status=0 
 begin
  set @query= 
		' DELETE FROM ['+@iddbdepartment+'].invoicekindregisterkind 
		  WHERE ['+@iddbdepartment+'].invoicekindregisterkind.idinvkind IN (SELECT IK.idinvkind FROM ['+@iddbdepartment+'].invoicekind IK
		  WHERE ['+@iddbdepartment+'].invoicekindregisterkind.idinvkind = IK.idinvkind
										AND IK.codeinvkind=' + @codeinvkindstr + ') '+
		' DELETE FROM ['+@iddbdepartment+'].invoicekindyear 
		  WHERE ['+@iddbdepartment+'].invoicekindyear.idinvkind IN (SELECT IK.idinvkind FROM ['+@iddbdepartment+'].invoicekind IK
										WHERE ['+@iddbdepartment+'].invoicekindyear.idinvkind = IK.idinvkind
										AND IK.codeinvkind=' + @codeinvkindstr + ') '+
		' if not exists(select * from ['+@iddbdepartment+'].invoicekind IK where '+
		' IK.codeinvkind= '+@codeinvkindstr+' ) '+
		' insert into ['+@iddbdepartment+'].invoicekind (
		  ct,cu,description,lt,lu,codeinvkind,idinvkind,flag,flag_autodocnumbering,formatstring,active)' +
		' SELECT ct,cu,description,lt,lu,codeinvkind,' + 'isnull((select max(idinvkind) from ['+@iddbdepartment+'].invoicekind),0)+1,' + 
		'flag,flag_autodocnumbering,formatstring,active from ['+@amm+'].invoicekind where idinvkind='+@idinvkindstr+
		' ELSE 
		  BEGIN
			UPDATE  ['+@iddbdepartment+'].invoicekind SET ct=IK1.ct, cu=IK1.cu,description=IK1.description,lt=IK1.lt,lu=IK1.lu,'+
		'	codeinvkind=IK1.codeinvkind, 	flag=IK1.flag, flag_autodocnumbering = IK1.flag_autodocnumbering,formatstring= IK1.formatstring, active= IK1.active
			FROM ['+@iddbdepartment+'].invoicekind inner join '+
			'['+@amm+'].invoicekind IK1 ON IK1.codeinvkind=['+@iddbdepartment+'].invoicekind.codeinvkind  WHERE  IK1.idinvkind='+@idinvkindstr+
			' END' +
		' DECLARE @new_idinvkind int
		  SELECT @new_idinvkind=idinvkind from ['+@iddbdepartment+'].invoicekind where codeinvkind = ' +@codeinvkindstr+
		' INSERT INTO ['+@iddbdepartment+'].invoicekindregisterkind(idinvkind,idivaregisterkind,ct,cu,lt,lu)
		  SELECT @new_idinvkind,idivaregisterkind,ct,cu,lt,lu
		  FROM #registerkind 
			JOIN ['+@iddbdepartment+'].ivaregisterkind
				ON #registerkind.codeivaregisterkind = ['+@iddbdepartment+'].ivaregisterkind.codeivaregisterkind'+
		' INSERT INTO ['+@iddbdepartment+'].invoicekindyear (ayear,idinvkind,ct,cu,idacc,idacc_deferred,idacc_discount,
															 idacc_unabatable,lt,lu,idacc_deferred_intra,idacc_intra,idacc_unabatable_intra)
		  SELECT ayear,@new_idinvkind,ct,cu,idacc,idacc_deferred,idacc_discount,
															 idacc_unabatable,lt,lu,idacc_deferred_intra,idacc_intra,idacc_unabatable_intra
		  FROM ['+@amm+'].invoicekindyear where idinvkind = ' + @idinvkindstr 
	
 print @query
 EXEC sp_executesql @query
 

 fetch next from @crsdepartment into @iddbdepartment
 end
END


GO

print 'copyrow_invoicekind OK'

GO
if object_id('exp_fg_classificatosuesitato') is not null
	drop procedure exp_fg_classificatosuesitato
go

CREATE   procedure exp_fg_classificatosuesitato(
        @idsorkind int,
	@start datetime, 
	@stop datetime,
        @kind char(1)
) 
as 
begin
declare @impegno varchar(20)
select  @impegno  = description from expensephase where nphase = 1
declare @pagamento varchar(20)
select  @pagamento = description from expensephase where nphase = (select max(nphase) from expensephase)
declare @Accertamento varchar(20)
select  @Accertamento  = description from incomephase where nphase = 1
declare @incasso varchar(20)
select  @incasso = description from incomephase where nphase = (select max(nphase) from incomephase)
IF(@kind = 'D')
Begin
        select 
                payment.npay as 'N.Mandato',
                @pagamento +' '+ convert(varchar(20),expense.nmov) + '/'+  convert(varchar(20),expense.ymov)  as 'Pagamento',
                @impegno +' '+ convert(varchar(20),exp2.nmov) + '/'+  convert(varchar(20),exp2.ymov)  as 'Impegno',
                expense.description as 'Descr.Pagamento',
                fin.codefin as 'Bilancio',
                upb.codeupb as 'Cod.UPB',
                upb.title as 'UPB',
        	sortingkind.description as 'Tipo class.',
        	sorting.sortcode as 'Codice class.', 
        	sorting.description as 'Classificazione', 
        	banktransactionsorting.amount as 'Importo',
                banktransaction.transactiondate as 'Esitazione'
         from banktransaction 
        join banktransactionsorting  
                on banktransaction.nban = banktransactionsorting.nban
                and banktransaction.yban = banktransactionsorting.yban
        join sorting 
                ON sorting.idsor = banktransactionsorting.idsor
        join sortingkind 
                ON sortingkind.idsorkind = sorting.idsorkind
        join expense
                on banktransaction.idexp = expense.idexp
        join payment
                on banktransaction.kpay = payment.kpay
        join fin
                on payment.idfin = fin.idfin
        JOIN expenseyear
        	ON expense.idexp = expenseyear.idexp AND expense.ymov = expenseyear.ayear
        join upb
                on expenseyear.idupb = upb.idupb
        join expenselink
                ON expenselink.idchild = expense.idexp and expenselink.nlevel = 1
        join expense exp2
                ON exp2.idexp = expenselink.idparent
        where sorting.idsorkind = @idsorkind
                AND banktransaction.kind = 'D'
                AND banktransaction.transactiondate between @start and @stop
        ORDER BY banktransaction.transactiondate
End
Else
Begin
        select 
                proceeds.npro as 'N.Reversale',
                @incasso +' '+ convert(varchar(20),income.nmov) + '/'+  convert(varchar(20),income.ymov)  as 'Incasso',
                @Accertamento +' '+ convert(varchar(20),inc2.nmov) + '/'+  convert(varchar(20),inc2.ymov)  as 'Accertamento',
                income.description as 'Descr.Incasso',
                fin.codefin as 'Bilancio',
                upb.codeupb as 'Cod.UPB',
                upb.title as 'UPB',
        	sortingkind.description as 'Tipo class.',
        	sorting.sortcode as 'Codice class.', 
        	sorting.description as 'Classificazione', 
        	banktransactionsorting.amount as 'Importo',
                banktransaction.transactiondate as 'Esitazione'
         from banktransaction 
        join banktransactionsorting  
                on banktransaction.nban = banktransactionsorting.nban
                and banktransaction.yban = banktransactionsorting.yban
        join sorting 
                ON sorting.idsor = banktransactionsorting.idsor
        join sortingkind 
                ON sortingkind.idsorkind = sorting.idsorkind
        join income
                on banktransaction.idinc = income.idinc
        join proceeds
                on banktransaction.kpro = proceeds.kpro
        join fin
                on proceeds.idfin = fin.idfin
        JOIN incomeyear
        	ON income.idinc = incomeyear.idinc AND income.ymov =incomeyear.ayear
        join upb
                on incomeyear.idupb = upb.idupb
        join incomelink
                ON incomelink.idchild = income.idinc and incomelink.nlevel = 1
        join income inc2
                ON inc2.idinc = incomelink.idparent
        where sorting.idsorkind = @idsorkind
                AND banktransaction.kind = 'C'
                AND banktransaction.transactiondate between @start and @stop
        ORDER BY banktransaction.transactiondate
End
end



GO

print 'exp_fg_classificatosuesitato OK'

GO
if object_id('exp_unified_ritenute_impon_saldo') is not null
	drop PROCEDURE exp_unified_ritenute_impon_saldo
go

CREATE   PROCEDURE exp_unified_ritenute_impon_saldo
(
  @ayear int, 
  @idreg int, 
  @tax   int,
  @idser int,  
  @start datetime,
  @stop  datetime,
  @show_department char(1),
  @show_month char(1),
  @unified char(1) -- consolidamento delle ritenute applicate
) 
AS
Begin
-- Questa sp è praticamente la exp_riepilogo_ritenute_applicate_impon
-- eseguita con:
-- @mode = Saldo
-- @unified_mov = S consolida dei movimenti del percipiente
-- Ha lo scopo di visualizzare il saldo per Tipo Ritenuta
CREATE TABLE #unifiedtax 
(
	monthtaxpay varchar(2),
	departmentname  varchar(150),
	nmov int,
	ymov int,
	title varchar(100),
	cf varchar(16),
	taxdescription varchar(50),
	surname varchar(50),
	forename varchar(50),
	p_iva varchar(15),
	birthdate datetime,
	GC_title varchar(65),
	GP_province varchar(2),
	GN_title varchar(65),
	gender char(1), 
	desc_exp varchar(150),
	service_description varchar(50),
	servicestart datetime,
	servicestop datetime,
	address varchar(100),
	location varchar(65),
	province varchar(2),
	nation varchar(65),
	cap varchar(20),
	GC_tax_title  varchar(65),  
	fiscale_region varchar(50),
	taxablegross decimal(19,2),
	taxablenet decimal(19,2),
	employtax decimal(19,2),
	admintax decimal(19,2),
	abatements decimal(19,2)
)
IF (@unified <> 'S')
BEGIN
-- Esegue la sp interna SOLO per il dipartimento corrente. Poi depurerà l'output dalle colonne inutili.      
	INSERT INTO #unifiedtax (
                monthtaxpay,
		departmentname,
		title,cf,
		taxdescription,
		surname,forename,p_iva,
		birthdate,GC_title,GP_province,GN_title,
		gender,
		address,location,province,nation,cap,
		GC_tax_title, fiscale_region,
		taxablegross,taxablenet,employtax,admintax,abatements
	)
        EXEC exp_riepilogo_ritenute_applicate_impon @ayear,@idreg,@tax,@idser,@start,@stop,'S','S','S','S'
END 
ELSE -- @unified = 'S'
BEGIN
        DECLARE @iddbdepartment varchar(50)
        DECLARE @crsdepartment cursor
        
        SET @crsdepartment = cursor FOR SELECT iddbdepartment FROM dbdepartment
							 where (start is null or start <= @ayear ) AND ( stop is null or stop >= @ayear) 
        OPEN @crsdepartment
        
        FETCH NEXT FROM @crsdepartment INTO @iddbdepartment
        WHILE @@fetch_status=0 begin
        	DECLARE @dip_nomesp varchar(300)
        	SET @dip_nomesp = @iddbdepartment + '.exp_riepilogo_ritenute_applicate_impon'
        
        		INSERT INTO #unifiedtax (
                                monthtaxpay,
        			departmentname,
        			title,cf,
        			taxdescription,
        			surname,forename,p_iva,
        			birthdate,GC_title,GP_province,GN_title,
        			gender,
        			address,location,province,nation,cap,
        			GC_tax_title, fiscale_region,
        			taxablegross,taxablenet,employtax,admintax,abatements
        		)
                        EXEC @dip_nomesp @ayear,@idreg,@tax,@idser,@start,@stop,'S','S','S','S'
        
        	FETCH NEXT FROM @crsdepartment INTO @iddbdepartment
        end
END
--------------- ELABORAZIONE DELL'OUTPUT FINALE --------------------------------------------
IF (@show_month = 'S')and (@show_department='S')
        SELECT
                monthtaxpay as 'Mese ',
                departmentname as 'Dipartimento',
                taxdescription as 'Ritenuta',  
                isnull(sum(taxablegross),0) as ' Imponibile Lordo',
                isnull(sum(taxablenet),0) as 'Imponibile Netto',
                isnull(sum(employtax),0) as 'Rit.Dip.',
                isnull(sum(admintax),0) as 'Rit.Amm.',
                isnull(sum(abatements),0) as 'Detrazioni Applicate' 
        FROM #unifiedtax
        GROUP BY taxdescription,monthtaxpay,departmentname
        ORDER BY taxdescription
IF (@show_month = 'N') and (@show_department='S')
        SELECT
                departmentname as 'Dipartimento',
                taxdescription as 'Ritenuta',  
                isnull(sum(taxablegross),0) as ' Imponibile Lordo',
                isnull(sum(taxablenet),0) as 'Imponibile Netto',
                isnull(sum(employtax),0) as 'Rit.Dip.',
                isnull(sum(admintax),0) as 'Rit.Amm.',
                isnull(sum(abatements),0) as 'Detrazioni Applicate' 
        FROM #unifiedtax
        GROUP BY taxdescription,departmentname
        ORDER BY taxdescription
IF (@show_month = 'S')and (@show_department='N')
        SELECT
                monthtaxpay as 'Mese ',
                taxdescription as 'Ritenuta',  
                isnull(sum(taxablegross),0) as ' Imponibile Lordo',
                isnull(sum(taxablenet),0) as 'Imponibile Netto',
                isnull(sum(employtax),0) as 'Rit.Dip.',
                isnull(sum(admintax),0) as 'Rit.Amm.',
                isnull(sum(abatements),0) as 'Detrazioni Applicate' 
        FROM #unifiedtax
        GROUP BY taxdescription,monthtaxpay
        ORDER BY taxdescription
IF (@show_month = 'N') and (@show_department='N')
        SELECT
                taxdescription as 'Ritenuta',  
                isnull(sum(taxablegross),0) as ' Imponibile Lordo',
                isnull(sum(taxablenet),0) as 'Imponibile Netto',
                isnull(sum(employtax),0) as 'Rit.Dip.',
                isnull(sum(admintax),0) as 'Rit.Amm.',
                isnull(sum(abatements),0) as 'Detrazioni Applicate' 
        FROM #unifiedtax
        GROUP BY taxdescription
        ORDER BY taxdescription

end



GO

print 'exp_unified_ritenute_impon_saldo OK'

