if object_id('exp_consolidamento_bari_competenza') is not null
	drop PROCEDURE exp_consolidamento_bari_competenza
go


CREATE             PROCEDURE exp_consolidamento_bari_competenza
(
	@ayear int,
	@date datetime,
	@finpart char(1),
	@levelusable tinyint
)
AS 
BEGIN
/* Versione 1.0.0 del 12/09/2007 ultima modifica: PIERO */
-- exec exp_consolidamento_bari_competenza 2006,{ts '2006-08-30 00:00:00'},'S',3
CREATE   TABLE #competency(
	printingorder varchar(50),
	code varchar(50),
	fintitle varchar(150),
	mov_finphase_C_univ decimal(19,2),
	mov_finphase_C_direct decimal(19,2),
	mov_finphase_C_internal decimal(19,2),
	var_finphase_C_univ decimal(19,2),
	var_finphase_C_direct decimal(19,2),
	var_finphase_C_internal decimal(19,2),
	mov_maxphase_C_univ decimal(19,2),
	mov_maxphase_C_direct decimal(19,2),
	mov_maxphase_C_internal decimal(19,2),
	var_maxphase_C_univ decimal(19,2),
	var_maxphase_C_direct decimal(19,2),
	var_maxphase_C_internal decimal(19,2),
	mov_finphase_R_univ decimal(19,2),
	mov_finphase_R_direct decimal(19,2),
	mov_finphase_R_internal decimal(19,2),
	var_finphase_R_univ decimal(19,2),
	var_finphase_R_direct decimal(19,2),
	var_finphase_R_internal decimal(19,2),
	mov_maxphase_R_univ decimal(19,2),
	mov_maxphase_R_direct decimal(19,2),
	mov_maxphase_R_internal decimal(19,2),
	var_maxphase_R_univ decimal(19,2),
	var_maxphase_R_direct decimal(19,2),
	var_maxphase_R_internal decimal(19,2),
	supposed_ff_jan01 decimal(19,2),
	supposed_aa_jan01 decimal(19,2),
	ff_jan01 decimal(19,2),
	aa_jan01 decimal(19,2)
)
INSERT INTO #competency(
	printingorder,
	code,
	fintitle,
	mov_finphase_C_univ ,
	mov_finphase_C_direct ,
	mov_finphase_C_internal ,
	var_finphase_C_univ ,
	var_finphase_C_direct ,
	var_finphase_C_internal,
	mov_maxphase_C_univ ,
	mov_maxphase_C_direct,
	mov_maxphase_C_internal ,
	var_maxphase_C_univ ,
	var_maxphase_C_direct ,
	var_maxphase_C_internal ,
	mov_finphase_R_univ ,
	mov_finphase_R_direct ,
	mov_finphase_R_internal ,
	var_finphase_R_univ ,
	var_finphase_R_direct ,
	var_finphase_R_internal ,
	mov_maxphase_R_univ ,
	mov_maxphase_R_direct ,
	mov_maxphase_R_internal ,
	var_maxphase_R_univ ,
	var_maxphase_R_direct ,
	var_maxphase_R_internal ,
	supposed_ff_jan01,
	supposed_aa_jan01,
	ff_jan01 , -- fondo cassa
	aa_jan01  -- avanzo di amministrazione
	)
	EXEC  exp_consolidamento @ayear, @date,@finpart,@levelusable
        
IF @finpart = 'E'
BEGIN
	SELECT
		code as 'Codice di Bilancio',
   		fintitle as 'Denominazione',
		mov_finphase_C_univ + var_finphase_C_univ as 'Accertamenti di entrate da Amm.ne Centrale (1)',
		mov_finphase_C_internal + var_finphase_C_internal as 'Accertamenti di entrate da altri Dip. e Centri (2)',
		mov_finphase_C_direct + var_finphase_C_direct as 'Accertamenti da entrate proprie (3)' ,
		mov_finphase_C_univ + var_finphase_C_univ + mov_finphase_C_internal + var_finphase_C_internal + 
			mov_finphase_C_direct + var_finphase_C_direct  as 'Totali Accertamenti di COMPETENZA (1+2+3) (4)' 
	FROM #competency
	ORDER BY printingorder ASC,code ASC
END
	
ELSE
BEGIN
	SELECT 
		code as 'Codice di Bilancio',
		fintitle as 'Denominazione',		
		mov_finphase_C_univ + var_finphase_C_univ as 'Somme impegnate a favore della Amm.ne Centrale (1)'	,
		mov_finphase_C_internal + var_finphase_C_internal as 'Somme impegnate a favore di Dip. e Centri (2)',
		mov_finphase_C_direct + var_finphase_C_direct as 'Altri impegni di competenza (3)'	,
		mov_finphase_C_univ + var_finphase_C_univ + mov_finphase_C_internal + var_finphase_C_internal 
			+ mov_finphase_C_direct + var_finphase_C_direct as 'Totale impegni di competenza (1+2+3) (4)'
	FROM #competency
    	ORDER BY printingorder ASC,code ASC
END
END


GO

print 'exp_consolidamento_bari_competenza OK'

GO
if object_id('[trg_evaluatearrears]') is not null
	drop PROCEDURE [trg_evaluatearrears]
go

CREATE        PROCEDURE [trg_evaluatearrears]
(
	@movkind char(1),
	@idmov int,
	@ayear int,
	@nphase tinyint
)
AS BEGIN
DECLARE @oldidfin int
DECLARE @newidfin int
DECLARE @idupb varchar(36)
DECLARE @existyear int
DECLARE @newarrear decimal(19,2)
DECLARE @oldarrear decimal(19,2)
DECLARE @currentamount decimal(19,2)
DECLARE @lastphase tinyint
DECLARE @newayear int
SELECT @newayear = @ayear + 1
IF @movkind = 'I'
BEGIN
	SELECT @lastphase = MAX(nphase) FROM incomephase
	SELECT @existyear = COUNT(*)
	FROM incomeyear
	WHERE idinc = @idmov
		AND ayear = @newayear
	SELECT @oldarrear = ISNULL(amount, 0)
	FROM incomeyear
	WHERE idinc = @idmov
		AND ayear = @newayear
	SELECT
		@oldidfin = idfin,
		@idupb = idupb
	FROM incomeyear
	WHERE idinc = @idmov
		AND ayear = @ayear
	SELECT @currentamount = ISNULL(curramount, 0)
	FROM incometotal
	WHERE idinc = @idmov
		AND ayear = @ayear
	DECLARE @maxincomephase tinyint
	SELECT @maxincomephase = MAX(nphase) FROM incomephase
	DECLARE @proceeded decimal(19,2)
	SELECT @proceeded = ISNULL(SUM(curramount), 0)
	FROM incometotal
	WHERE ayear = @ayear
		AND idinc IN
			(SELECT incomelink.idchild
			FROM incomelink
			JOIN income
				ON income.idinc = incomelink.idchild
			WHERE incomelink.idparent = @idmov
				AND income.nphase = @maxincomephase)
	SELECT @newarrear = ISNULL(@currentamount, 0) - ISNULL(@proceeded, 0)
END
ELSE
BEGIN
	SELECT @lastphase = MAX(nphase) FROM expensephase
	SELECT @existyear = COUNT(*)
	FROM expenseyear
	WHERE idexp = @idmov
		AND ayear = @newayear
	SELECT @oldarrear = ISNULL(amount, 0)
	FROM expenseyear
	WHERE idexp = @idmov
		AND ayear = @newayear
	SELECT
		@oldidfin = idfin,
		@idupb = idupb
	FROM expenseyear
	WHERE idexp = @idmov
		AND ayear = @ayear
	SELECT @currentamount = ISNULL(curramount, 0)
	FROM expensetotal
	WHERE idexp = @idmov
		AND ayear = @ayear
	DECLARE @maxexpensephase tinyint
	SELECT @maxexpensephase = MAX(nphase) FROM expensephase
	DECLARE @payed decimal(19,2)	
	SELECT @payed = ISNULL(SUM(curramount), 0)
	FROM expensetotal
	WHERE ayear = @ayear
		AND idexp IN
			(SELECT expenselink.idchild
			FROM expenselink
			JOIN expense
				ON expense.idexp = expenselink.idchild
			WHERE expenselink.idparent = @idmov
				AND expense.nphase = @maxexpensephase)
	SELECT @newarrear = ISNULL(@currentamount, 0) - ISNULL(@payed, 0)
END
IF (@existyear > 0)
BEGIN
	IF (@newarrear = 0)
	BEGIN
		IF @movkind = 'I'
		BEGIN
			DELETE FROM incomeyear
			WHERE idinc = @idmov
			AND ayear = @newayear
			AND NOT EXISTS
				(SELECT incomeyear.idinc
				FROM incomeyear
				JOIN incomelink
				ON incomelink.idchild = incomeyear.idinc
				WHERE incomelink.idparent = @idmov
					AND incomelink.idchild <> incomelink.idparent
					--AND incomelink.nlevel > @nphase
					AND incomeyear.ayear > @ayear)
			
			UPDATE incomeyear
			SET amount = @newarrear, lu = '''TRIGGER''', lt = GETDATE()
			WHERE idinc = @idmov
			AND ayear = @newayear
			AND EXISTS
				(SELECT incomeyear.idinc
				FROM incomeyear
				JOIN incomelink
				ON incomelink.idchild = incomeyear.idinc
				WHERE incomelink.idparent = @idmov
					AND incomelink.idchild <> incomelink.idparent
					--AND incomelink.nlevel > @nphase
					AND incomeyear.ayear > @ayear)
		END
		ELSE
		BEGIN
			DELETE FROM expenseyear
			WHERE idexp = @idmov
			AND ayear = @newayear
			AND NOT EXISTS
				(SELECT expenseyear.idexp
				FROM expenseyear
				JOIN expenselink
				ON expenselink.idchild = expenseyear.idexp
				WHERE expenselink.idparent = @idmov
					AND expenselink.idchild <> expenselink.idparent
					--AND expenselink.nlevel > @nphase
					AND expenseyear.ayear > @ayear)
			
			UPDATE expenseyear
			SET amount = @newarrear, lu = '''TRIGGER''', lt = GETDATE()
			WHERE idexp = @idmov
			AND ayear = @newayear
			AND EXISTS
				(SELECT expenseyear.idexp
				FROM expenseyear
				JOIN expenselink
				ON expenselink.idchild = expenseyear.idexp
				WHERE expenselink.idparent = @idmov
					AND expenselink.idchild <> expenselink.idparent
					--AND expenselink.nlevel > @nphase
					AND expenseyear.ayear > @ayear)
		END
	END
	ELSE
	BEGIN
		IF @movkind = 'I'
		BEGIN
			UPDATE incomeyear
			SET amount = @newarrear, lu = '''TRIGGER''', lt = GETDATE()
			WHERE idinc = @idmov
			AND ayear = @newayear
		END
		ELSE
		BEGIN
			UPDATE expenseyear
			SET amount = @newarrear, lu = '''TRIGGER''', lt = GETDATE()
			WHERE idexp = @idmov
			AND ayear = @newayear
		END
	END
END
ELSE
BEGIN
	SELECT @newidfin = NULL
	SELECT @newidfin = newidfin
	FROM finlookup
	WHERE oldidfin = @oldidfin
	IF @movkind = 'I'
	BEGIN
		INSERT INTO incomeyear
		(idinc,ayear,idfin,idupb,amount,
		cu,ct,lu,lt)
		VALUES(@idmov,@newayear,@newidfin,@idupb,@newarrear,
		'TRIGGER',GETDATE(),'''TRIGGER_trg_eval''',GETDATE())
	END
	ELSE
	BEGIN
		INSERT INTO expenseyear
		(idexp,ayear,idfin,idupb,amount,
		cu,ct,lu,lt)
		VALUES(@idmov,@newayear,@newidfin,@idupb,@newarrear,
		'TRIGGER',GETDATE(),'''TRIGGER''',GETDATE())
	END
END
END


GO

print '[trg_evaluatearrears] OK'

