if object_id('[trg_upd_registry]') is not null
	drop PROCEDURE [trg_upd_registry]
go

CREATE                     PROCEDURE [trg_upd_registry]
(
	@movkind char(1),
	@idmov varchar(40),
	@nphase varchar(20),
	@idreg int
)
AS BEGIN
DECLARE @currentphase int
DECLARE @maxphase int
IF @movkind = 'I'
BEGIN
	SELECT @maxphase = CONVERT(int, MAX(nphase)) FROM incomephase
	SELECT @currentphase = CONVERT(int, @nphase) + 1
	WHILE (@currentphase <= @maxphase)
	BEGIN
		UPDATE income
		SET idreg = @idreg,
		lu = '''TRIGGER''',
		lt = GETDATE()
		WHERE idinc LIKE @idmov + '%'
			AND nphase = CONVERT(varchar(20),@currentphase)
	
		SET @currentphase = @currentphase + 1
	END
END
ELSE
BEGIN
	SELECT @maxphase = CONVERT(int, MAX(nphase)) FROM expensephase
	
	SELECT @currentphase = CONVERT(int, @nphase) + 1
	WHILE (@currentphase <= @maxphase)
	BEGIN
		UPDATE expense
		SET idreg = @idreg,
		lu = '''TRIGGER''',
		lt = GETDATE()
		WHERE idexp LIKE @idmov + '%'
			AND nphase = CONVERT(varchar(20),@currentphase)
		SET @currentphase = @currentphase + 1
	END
END
END

GO

print '[trg_upd_registry] OK'

