if object_id('exp_consolidamento_bari_residui_3112') is not null
	drop PROCEDURE exp_consolidamento_bari_residui_3112
go


CREATE                  PROCEDURE exp_consolidamento_bari_residui_3112
(
	@ayear int,
	@finpart char(1),
	@levelusable tinyint
)
AS 
BEGIN
/* Versione 1.0.0 del 12/09/2007 ultima modifica: PIERO */
-- exec  exp_consolidamento_bari_residui_0101 2006,'S',3 
CREATE TABLE #residual_3112(
	printingorder varchar(50),
	code varchar(50),
	fintitle varchar(150),
	mov_finphase_C_univ decimal(19,2),
	mov_finphase_C_direct decimal(19,2),
	mov_finphase_C_internal decimal(19,2),
	var_finphase_C_univ decimal(19,2),
	var_finphase_C_direct decimal(19,2),
	var_finphase_C_internal decimal(19,2),
	mov_maxphase_C_univ decimal(19,2),
	mov_maxphase_C_direct decimal(19,2),
	mov_maxphase_C_internal decimal(19,2),
	var_maxphase_C_univ decimal(19,2),
	var_maxphase_C_direct decimal(19,2),
	var_maxphase_C_internal decimal(19,2),
	mov_finphase_R_univ decimal(19,2),
	mov_finphase_R_direct decimal(19,2),
	mov_finphase_R_internal decimal(19,2),
	var_finphase_R_univ decimal(19,2),
	var_finphase_R_direct decimal(19,2),
	var_finphase_R_internal decimal(19,2),
	mov_maxphase_R_univ decimal(19,2),
	mov_maxphase_R_direct decimal(19,2),
	mov_maxphase_R_internal decimal(19,2),
	var_maxphase_R_univ decimal(19,2),
	var_maxphase_R_direct decimal(19,2),
	var_maxphase_R_internal decimal(19,2),
	supposed_ff_jan01  decimal(19,2),
	supposed_aa_jan01  decimal(19,2),
	ff_jan01 decimal(19,2),
	aa_jan01 decimal(19,2)
)
DECLARE @date datetime
SET @date= CONVERT(datetime,'31-12-'+convert(varchar(4),@ayear),105)
INSERT INTO #residual_3112(
	printingorder,
	code,
	fintitle,
	mov_finphase_C_univ , 		
	mov_finphase_C_direct ,	
	mov_finphase_C_internal ,	
	var_finphase_C_univ ,		
	var_finphase_C_direct ,	
	var_finphase_C_internal 	,	
	mov_maxphase_C_univ ,		
	mov_maxphase_C_direct,		
	mov_maxphase_C_internal ,	
	var_maxphase_C_univ ,		
	var_maxphase_C_direct ,	
	var_maxphase_C_internal ,	
	mov_finphase_R_univ ,		
	mov_finphase_R_direct ,	
	mov_finphase_R_internal ,	
	var_finphase_R_univ ,		
	var_finphase_R_direct ,	
	var_finphase_R_internal ,	
	mov_maxphase_R_univ ,		
	mov_maxphase_R_direct ,	
	mov_maxphase_R_internal ,	
	var_maxphase_R_univ ,		
	var_maxphase_R_direct ,	
	var_maxphase_R_internal ,	
	supposed_ff_jan01  ,		
	supposed_aa_jan01  ,		
	ff_jan01 , -- fondo cassa 	
	aa_jan01  -- avanzo di amministrazione	
	)
EXEC  exp_consolidamento @ayear, @date,@finpart,@levelusable
IF @finpart = 'E'
BEGIN
	SELECT
		code as 'Codice di Bilancio',
		fintitle as 'Denominazione',
		mov_finphase_C_univ + var_finphase_C_univ - (mov_maxphase_C_univ + var_maxphase_C_univ) + mov_finphase_R_univ + var_finphase_R_univ - (mov_maxphase_R_univ + var_maxphase_R_univ) 
				as 'Residui attivi da entrate di proven. Amm.ne Centrale (1)'	,
		mov_finphase_C_internal + var_finphase_C_internal -(mov_maxphase_C_internal + var_maxphase_C_internal) + mov_finphase_R_internal + var_finphase_R_internal - (mov_maxphase_R_internal + var_maxphase_R_internal)	
				as 'Residui attivi da entrate di proven. Dip. e Centri (2)',
		mov_finphase_C_direct + var_finphase_C_direct - (mov_maxphase_C_direct + var_maxphase_C_direct) + mov_finphase_R_direct + var_finphase_R_direct - (mov_maxphase_R_direct + var_maxphase_R_direct)	
				as 'Residui attivi da entrate proprie (3)',
		mov_finphase_C_univ + var_finphase_C_univ - (mov_maxphase_C_univ	+var_maxphase_C_univ)
				+ mov_finphase_R_univ + var_finphase_R_univ - (mov_maxphase_R_univ + var_maxphase_R_univ)
				+ mov_finphase_C_internal	+var_finphase_C_internal -(mov_maxphase_C_internal +var_maxphase_C_internal)
				+ mov_finphase_R_internal + var_finphase_R_internal - (mov_maxphase_R_internal + var_maxphase_R_internal)
				+ mov_finphase_C_direct + var_finphase_C_direct - (mov_maxphase_C_direct	+var_maxphase_C_direct)	
				+ mov_finphase_R_direct + var_finphase_R_direct - (mov_maxphase_R_direct + var_maxphase_R_direct) 
				as 'Totali dei residui attivi (1+2+3) (4)' 
	FROM #residual_3112
	ORDER BY printingorder ASC,code ASC
END
	
ELSE
BEGIN
	SELECT 
		code as 'Codice di Bilancio',	
		fintitle as 'Denominazione',
		mov_finphase_C_univ + var_finphase_C_univ - (mov_maxphase_C_univ + var_maxphase_C_univ)
		+ mov_finphase_R_univ + var_finphase_R_univ - (mov_maxphase_R_univ + var_maxphase_R_univ) 
			as 'Residui passivi per somme a favore Amm.ne Centrale (1)',
		
		mov_finphase_C_internal + var_finphase_C_internal -(mov_maxphase_C_internal + var_maxphase_C_internal)
		+ mov_finphase_R_internal + var_finphase_R_internal - (mov_maxphase_R_internal + var_maxphase_R_internal)	
			as 'Residui passivi per somme a favore Dip. e Centri (2)',
		
		mov_finphase_C_direct + var_finphase_C_direct - (mov_maxphase_C_direct + var_maxphase_C_direct)	
		+ mov_finphase_R_direct + var_finphase_R_direct - (mov_maxphase_R_direct + var_maxphase_R_direct)	 
			as 'Altri residui passivi (3)',
		
		mov_finphase_C_univ + var_finphase_C_univ - (mov_maxphase_C_univ + var_maxphase_C_univ)
		+ mov_finphase_R_univ + var_finphase_R_univ - (mov_maxphase_R_univ + var_maxphase_R_univ) 
	 	+ mov_finphase_C_internal + var_finphase_C_internal -(mov_maxphase_C_internal + var_maxphase_C_internal)
		+ mov_finphase_R_internal + var_finphase_R_internal - (mov_maxphase_R_internal + var_maxphase_R_internal)
		+ mov_finphase_C_direct + var_finphase_C_direct - (mov_maxphase_C_direct + var_maxphase_C_direct)	
		+ mov_finphase_R_direct + var_finphase_R_direct - (mov_maxphase_R_direct + var_maxphase_R_direct)
			as 'Totali residui passivi (1+2+3) (4)'
	FROM #residual_3112
	ORDER BY printingorder ASC,code ASC
END
END


GO

print 'exp_consolidamento_bari_residui_3112 OK'

GO
if object_id('exp_incomegerarchico') is not null
	drop PROCEDURE exp_incomegerarchico
go


CREATE    PROCEDURE  exp_incomegerarchico (
	@ymin int,
	@ymax int,
	@ayearmin int,
	@ayearmax int,
	@registry varchar(100),
	@adatemin datetime,
	@adatemax datetime,
	@codefin varchar(50),
	@nphaseparent tinyint,
	@ymovparent  int,
	@nmovparent  int,
	@idupb varchar(36)
) 
as begin
-- exp_incomegerarchico '2005', '2009',2007,2009, '%', {ts '2007-01-01 00:00:00.000'}, {ts '2007-12-31 00:00:00.000'}, '%',null, null, null,'%'
declare @idinc int
IF (@nphaseparent IS NULL OR @ymovparent IS NULL OR @nmovparent IS NULL)
	BEGIN
		SET @idinc = null	
	END
Else
	BEGIN
	   	SET @idinc = (select idinc 
				from income 
				where ymov = @ymovparent 
				and nmov   = @nmovparent 
				and nphase = @nphaseparent) 
	END

declare @descrphase1 varchar(20)
declare @descrphase2 varchar(20)
declare @descrphase3 varchar(20)
declare @descrphase4 varchar(20)
declare @descrphase5 varchar(20)
select @descrphase1 = description from  incomephase where nphase = 1
select @descrphase2 = description from  incomephase where nphase = 2
select @descrphase3 = description from  incomephase where nphase = 3
select @descrphase4 = description from  incomephase where nphase = 4
select @descrphase5 = description from  incomephase where nphase = 5
SELECT  income.idinc, 
	incomeyear.ayear, 
	income.idreg, 
	incomeyear.idfin, 
	incomeyear.idupb 
INTO #prova
	FROM income
	join incomeyear 
		on incomeyear.idinc=income.idinc 
	left outer join registry 
		on income.idreg=registry.idreg 
	left outer join fin 
		on fin.idfin=incomeyear.idfin 
	left outer join upb 
		on upb.idupb = incomeyear.idupb  
	JOIN incomelink 
		ON incomelink.idchild = income.idinc  
		AND incomelink.idparent = ISNULL(@idinc,income.idinc) 
	WHERE (@adatemin is null or adate >= @adatemin) and (@adatemax is null or adate <= @adatemax)
	and (@ymin is null or income.ymov >= @ymin)
	and (@ymax is null or income.ymov <= @ymax)
	and (@ayearmin is null or incomeyear.ayear >= @ayearmin)
	and (@ayearmax is null or incomeyear.ayear <= @ayearmax)	
	and (@registry is null or registry.title like @registry)
	and (@codefin is null or codefin like @codefin)
	AND upb.idupb LIKE @idupb
declare @sqlcmd nvarchar(3000)
SET @sqlcmd= 
'	SELECT 	#prova.ayear as ANNO,
	(select (convert(varchar(4),I1.ymov) + ''/'' + convert(varchar(6),I1.nmov))
		FROM  income I1					 
			JOIN incomelink ilk1
				ON ilk1.idparent = I1.idinc AND ilk1.nlevel = 1
			where ilk1.idchild = #prova.idinc
	) 		
	AS '''+@descrphase1+''','
if (@descrphase2 is not null)
SET @sqlcmd=@sqlcmd+'
	(select (convert(varchar(4),I1.ymov) + ''/'' + convert(varchar(6),I1.nmov))
		FROM  income I1					 
			JOIN incomelink ilk1
				ON ilk1.idparent = I1.idinc AND ilk1.nlevel = 2
			where  ilk1.idchild = #prova.idinc
	) 		
	AS '''+@descrphase2+''','
if (@descrphase3 is not null)
SET @sqlcmd=@sqlcmd+'
	(select (convert(varchar(4),I1.ymov) + ''/'' + convert(varchar(6),I1.nmov))
		FROM  income I1					 
			JOIN incomelink ilk1
				ON ilk1.idparent = I1.idinc AND ilk1.nlevel = 3
			where  ilk1.idchild = #prova.idinc
	) 		
	AS '''+@descrphase3+''','
if (@descrphase4 is not null)
SET @sqlcmd=@sqlcmd+'
	(select (convert(varchar(4),I1.ymov) + ''/'' + convert(varchar(6),I1.nmov))
		FROM  income I1					 
			JOIN incomelink ilk1
				ON ilk1.idparent = I1.idinc AND ilk1.nlevel = 4
			where  ilk1.idchild = #prova.idinc
	) 		
	AS '''+@descrphase4+''','
if (@descrphase5 is not null)
SET @sqlcmd=@sqlcmd+'
	(select (convert(varchar(4),I1.ymov) + ''/'' + convert(varchar(6),I1.nmov))
		FROM  income I1					 
			JOIN incomelink ilk1
				ON ilk1.idparent = I1.idinc AND ilk1.nlevel = 5
			where  ilk1.idchild = #prova.idinc
	) 		
	AS '''+@descrphase5+''','
SET @sqlcmd=@sqlcmd+'
	(convert(varchar(4),proceeds.ypro) + ''/'' + convert(varchar(6),proceeds.npro)) as Reversale,
	codefin as ''Codice bilancio'',
	fin.title as ''Voce di bilancio'',
	codeupb as ''Codice UPB'',
	upb.title as ''UPB'',
	registry.title as ''Beneficiario'',
	income.description as ''Descrizione'',
	incometotal.curramount as ''Importo corrente'',
	case when incomelast.idinc is not null then null else incometotal.available end as ''Disponibile'',
	income.adate as ''Data contabile'',
	income.doc as ''Doc.'',
	income.docdate as ''Data Doc.''
FROM #prova
LEFT OUTER JOIN fin 
	on fin.idfin=#prova.idfin
LEFT OUTER JOIN upb 
	on upb.idupb=#prova.idupb
LEFT OUTER JOIN registry 
	on registry.idreg=#prova.idreg
LEFT OUTER JOIN income 
	on income.idinc=#prova.idinc
LEFT OUTER JOIN incomelast 
	on incomelast.idinc = #prova.idinc
LEFT OUTER JOIN proceeds 
	on incomelast.kpro = proceeds.kpro
LEFT OUTER JOIN incometotal 
	ON incometotal.idinc = #prova.idinc AND incometotal.ayear = #prova.ayear 
order by 1,2,3,4,5
'
--print @sqlcmd
EXECUTE sp_executesql  @sqlcmd
END

GO

print 'exp_incomegerarchico OK'

GO
if object_id('[show_pettycash]') is not null
	drop PROCEDURE [show_pettycash]
go

--  exec show_pettycash  {ts '2012-12-31 00:00:00'},2012,5
CREATE                    PROCEDURE [show_pettycash]
	@date datetime,
	@ayear smallint,
	@idpettycash int
AS BEGIN
DECLARE	@departmentname varchar(150)
SET  @departmentname = ISNULL( (SELECT paramvalue from
			 generalreportparameter where idparam='DenominazioneDipartimento' 
				and (start is null or start <= @date) 
				and (stop is null or stop >= @date)
				),'Manca Cfg. Parametri Tutte le stampe')
CREATE TABLE #situation (value varchar(250), amount decimal(19,2), kind char(1))
INSERT INTO #situation VALUES (@departmentname, NULL, 'H')
INSERT INTO #situation VALUES ('Situazione al ' + CONVERT(char(8), @date, 3), NULL, 'H')
DECLARE @pettycash varchar(50)
SELECT @pettycash = description 
FROM pettycash
WHERE idpettycash = @idpettycash
INSERT INTO #situation VALUES ('Fondo ' + @pettycash, NULL, 'H')
INSERT INTO #situation VALUES ('Esercizio ' + CONVERT(char(4), @ayear), NULL, 'H')
INSERT INTO #situation VALUES ('', NULL, 'N')
-- Apertura
DECLARE @O_amount decimal(19,2)
SELECT @O_amount = SUM(amount)
FROM pettycashoperation
WHERE yoperation = @ayear AND 
	( (flag& 1)<>0 ) AND 
	adate <= @date AND 
	idpettycash = @idpettycash
	
DECLARE @O_amount_emitted decimal(19,2)
SELECT @O_amount_emitted =  SUM(curramount) 
FROM expenselastview
join payment 
  on expenselastview.kpay = payment.kpay
join pettycashexpense 
  on pettycashexpense.idexp = expenselastview.idexp
join pettycashoperation 
  on pettycashoperation.yoperation = pettycashexpense.yoperation
  and pettycashoperation.noperation = pettycashexpense.noperation
  and pettycashoperation.idpettycash = pettycashexpense.idpettycash
WHERE pettycashoperation.yoperation = @ayear AND 
	( (pettycashoperation.flag& 1)<>0 ) AND 
	payment.adate <= @date AND  --- mandati emessi entro la data
	pettycashoperation.idpettycash = @idpettycash  

DECLARE @O_amount_transmitted decimal(19,2)
SELECT @O_amount_transmitted =  SUM(curramount) 
FROM expenselastview
join payment 
  on expenselastview.kpay = payment.kpay
join paymenttransmission 
  on paymenttransmission.kpaymenttransmission = payment.kpaymenttransmission
join pettycashexpense 
  on pettycashexpense.idexp = expenselastview.idexp
join pettycashoperation 
  on pettycashoperation.yoperation = pettycashexpense.yoperation
  and pettycashoperation.noperation = pettycashexpense.noperation
  and pettycashoperation.idpettycash = pettycashexpense.idpettycash
WHERE pettycashoperation.yoperation = @ayear AND 
	( (pettycashoperation.flag& 1)<>0 ) AND 
	paymenttransmission.transmissiondate <= @date AND  --- mandati trasmessi entro la data
	pettycashoperation.idpettycash = @idpettycash   	

-- Reintegro
DECLARE @R_amount decimal(19,2)
SELECT @R_amount = SUM(amount)
FROM pettycashoperation
WHERE yoperation = @ayear AND 
	( (flag& 2)<>0 ) AND 
	adate <= @date AND 
	idpettycash = @idpettycash
INSERT INTO #situation VALUES ('TOTALE ENTRATE', 
	ISNULL(@O_amount, 0) + ISNULL(@R_amount, 0), 'S')
INSERT INTO #situation VALUES ('di cui: ', NULL, 'N')
INSERT INTO #situation VALUES ('Apertura', @O_amount, '')
INSERT INTO #situation VALUES ('Reintegri', @R_amount, '')
INSERT INTO #situation VALUES('',NULL,'H')
-- Spese non attribuite
DECLARE @exp_notassign decimal(19,2)
	SELECT @exp_notassign = SUM(amount)
	FROM pettycashoperation
	WHERE yoperation = @ayear
		AND ( (flag& 8)<>0 )
		AND yrestore IS NULL
		AND nrestore IS NULL
		AND idfin IS NULL
		AND idexp IS NULL
		AND adate <= @date 
		AND idpettycash = @idpettycash
-- Spese non reintegrate
DECLARE @exp_notsheet decimal(19,2)
SELECT @exp_notsheet = SUM(amount)
FROM pettycashoperation
WHERE yoperation = @ayear
	AND ( (flag& 8)<>0 )
	AND yrestore IS NULL
	AND nrestore IS NULL
	AND (idfin IS NOT NULL	OR idexp IS NOT NULL)
	AND adate <= @date
	AND idpettycash = @idpettycash
-- Spese reintegrate
DECLARE @exp_sheet decimal(19,2)
SELECT @exp_sheet = SUM(amount)
FROM pettycashoperation
WHERE yoperation = @ayear 
	AND ( (flag& 8)<>0 )
	AND yrestore IS NOT NULL
	AND nrestore IS NOT NULL
	AND (idfin IS NOT NULL OR idexp IS NOT NULL)
	AND adate <= @date
	AND idpettycash = @idpettycash
	
DECLARE @emitted_payment_sheet decimal(19,2)
SELECT  @emitted_payment_sheet =  SUM(curramount) 
FROM expenselastview
join payment 
  on expenselastview.kpay = payment.kpay
join pettycashexpense 
  on pettycashexpense.idexp = expenselastview.idexp
join pettycashoperation 
  on pettycashoperation.yoperation = pettycashexpense.yoperation
  and pettycashoperation.noperation = pettycashexpense.noperation
  and pettycashoperation.idpettycash = pettycashexpense.idpettycash
WHERE pettycashoperation.yoperation = @ayear AND 
	( (pettycashoperation.flag& 2)<>0 ) AND 
	payment.adate <= @date AND  --- mandati emessi entro la data
	pettycashoperation.idpettycash = @idpettycash   	
	
DECLARE @transmitted_payment_sheet decimal(19,2)
SELECT  @transmitted_payment_sheet =  SUM(curramount) 
FROM expenselastview
join payment 
  on expenselastview.kpay = payment.kpay
join paymenttransmission 
  on paymenttransmission.kpaymenttransmission = payment.kpaymenttransmission
join pettycashexpense 
  on pettycashexpense.idexp = expenselastview.idexp
join pettycashoperation 
  on pettycashoperation.yoperation = pettycashexpense.yoperation
  and pettycashoperation.noperation = pettycashexpense.noperation
  and pettycashoperation.idpettycash = pettycashexpense.idpettycash
WHERE pettycashoperation.yoperation = @ayear AND 
	( (pettycashoperation.flag& 2)<>0 ) AND 
	paymenttransmission.transmissiondate <= @date AND  --- mandati trasmessi entro la data
	pettycashoperation.idpettycash = @idpettycash   	
	
-- Chiusura
DECLARE @C_amount decimal(19,2)
SELECT @C_amount = SUM(amount) 
FROM pettycashoperation
WHERE yoperation = @ayear AND 
	( (flag& 4)<>0 ) AND 
	adate <= @date AND 
	idpettycash = @idpettycash
	
DECLARE @C_amount_emitted decimal(19,2)
SELECT @C_amount_emitted =  SUM(curramount) 
FROM incomelastview
join proceeds 
  on incomelastview.kpro = proceeds.kpro
join pettycashincome
  on pettycashincome.idinc = incomelastview.idinc
join pettycashoperation 
  on pettycashoperation.yoperation = pettycashincome.yoperation
  and pettycashoperation.noperation = pettycashincome.noperation
  and pettycashoperation.idpettycash = pettycashincome.idpettycash
WHERE pettycashoperation.yoperation = @ayear AND 
	( (pettycashoperation.flag& 4)<>0 ) AND 
	proceeds.adate <= @date AND  --- reversali emesse entro la data
	pettycashoperation.idpettycash = @idpettycash   
	
	
DECLARE @C_amount_transmitted decimal(19,2)
SELECT @C_amount_transmitted =  SUM(curramount) 
FROM incomelastview
join proceeds 
  on incomelastview.kpro = proceeds.kpro
join proceedstransmission 
  on proceedstransmission.kproceedstransmission = proceeds.kproceedstransmission
join pettycashincome
  on pettycashincome.idinc = incomelastview.idinc
join pettycashoperation 
  on pettycashoperation.yoperation = pettycashincome.yoperation
  and pettycashoperation.noperation = pettycashincome.noperation
  and pettycashoperation.idpettycash = pettycashincome.idpettycash
WHERE pettycashoperation.yoperation = @ayear AND 
	( (pettycashoperation.flag& 4)<>0 ) AND 
	proceedstransmission.transmissiondate <= @date AND  --- reversali emesse entro la data
	pettycashoperation.idpettycash = @idpettycash   

INSERT INTO #situation VALUES ('TOTALE USCITE', 
	ISNULL(@exp_notassign, 0) + 
	ISNULL(@exp_notsheet, 0) + 
	ISNULL(@exp_sheet, 0) + 
	ISNULL(@C_amount, 0), 'S')
INSERT INTO #situation VALUES ('di cui: ', NULL, 'N')
INSERT INTO #situation VALUES ('Spese non attribuite', @exp_notassign, '')
INSERT INTO #situation VALUES ('Spese attribuite e non reintegrate', @exp_notsheet, '')
INSERT INTO #situation VALUES ('Spese attribuite e reintegrate', @exp_sheet, '')
INSERT INTO #situation VALUES ('di cui: ', NULL, 'N')
INSERT INTO #situation VALUES ('............Mandati emessi', @emitted_payment_sheet, '')
INSERT INTO #situation VALUES ('............Mandati trasmessi', @transmitted_payment_sheet, '')
INSERT INTO #situation VALUES ('Chiusura', @C_amount, '')
INSERT INTO #situation VALUES('',NULL,'H')
INSERT INTO #situation VALUES ('SALDO', 
	ISNULL(@O_amount, 0) - 
	ISNULL(@exp_notassign, 0) - 
	ISNULL(@exp_notsheet, 0) - 
	ISNULL(@exp_sheet, 0) + 
	ISNULL(@R_amount, 0) - 
	ISNULL(@C_amount, 0), 'S')
	
INSERT INTO #situation VALUES ('SALDO FINANZIARIO (Mandati emessi alla data)', 
	-- apertura
	ISNULL(@O_amount_emitted, 0) - 
	-- totale uscite
	ISNULL(@exp_notassign, 0) - 
	ISNULL(@exp_notsheet, 0) - 
	ISNULL(@exp_sheet, 0) + 
	-- reintegri emessi
	ISNULL(@emitted_payment_sheet, 0) - 
	--chiusura
	ISNULL(@C_amount_emitted, 0), 'S')
	
INSERT INTO #situation VALUES ('SALDO FINANZIARIO (Mandati trasmessi alla data)', 
	--apertura 
	ISNULL(@O_amount_transmitted, 0) -
	--totale uscite 
	ISNULL(@exp_notassign, 0) - 
	ISNULL(@exp_notsheet, 0) - 
	ISNULL(@exp_sheet, 0) + 
	--reintegri trasmessi
	ISNULL(@transmitted_payment_sheet, 0) - 
	--chiusura
	ISNULL(@C_amount_transmitted, 0), 'S')
	
SELECT value, amount, kind FROM #situation
END


GO

print '[show_pettycash] OK'

GO
if object_id('exp_asset_subzero') is not null
	drop PROCEDURE exp_asset_subzero
go

CREATE       PROCEDURE exp_asset_subzero
AS BEGIN
	DECLARE @totale decimal(19,2)
	DECLARE @idasset int
	DECLARE @idpiece int
	CREATE TABLE #err (message varchar(1000))
	DECLARE #crs INSENSITIVE CURSOR FOR
	SELECT idasset, idpiece FROM asset
	FOR READ ONLY
	OPEN #crs
	FETCH NEXT FROM #crs INTO @idasset, @idpiece
	WHILE(@@FETCH_STATUS = 0)
	BEGIN
		EXEC getassetvalue @idasset, @idpiece, @totale output
		IF (@totale < 0)
		BEGIN
			INSERT INTO #err
			SELECT 'Cespite ' + CONVERT(varchar(10),@idasset) + '/' + CONVERT(varchar(4), @idpiece)
			+ ' con valore attuale pari a ' + CONVERT(varchar(20), @totale)
		END
		FETCH NEXT FROM #crs INTO @idasset, @idpiece
	END
	CLOSE #crs
	DEALLOCATE #crs
	SELECT message AS 'Errore' FROM #err
END

GO

print 'exp_asset_subzero OK'

