if object_id('emens_getListaCollaboratori_unified') is not null
	drop PROCEDURE emens_getListaCollaboratori_unified
go

CREATE      PROCEDURE emens_getListaCollaboratori_unified
(
	@ycommunication int,
	@mcommunication int,
	@cf_enterprise varchar(16),
        @adate datetime,
	@cap varchar(5) output,
	@istat varchar(5) output
)
AS BEGIN
CREATE TABLE #collaboratoremain
(
        departmentname varchar(500),
	cfcollaboratore varchar(16),
	cognome varchar(50),
	nome varchar(20),
	tiporapporto varchar(2),
	codiceattivita varchar(2),
	imponibile decimal(19,2),
	aliquota decimal(19,6) NOT NULL,
	altraass varchar(3),
	dal smalldatetime,
	al smalldatetime,
	codicecomune varchar(20),
	codcalamita varchar(2),
	codcertificazione varchar(3)
)
DECLARE @parentsp char(1)
SET @parentsp = 'E'

DECLARE @iddbdepartment varchar(50)
DECLARE @crsdepartment cursor
SET @crsdepartment = cursor FOR SELECT iddbdepartment FROM dbdepartment
OPEN @crsdepartment
FETCH NEXT FROM @crsdepartment INTO @iddbdepartment
WHILE @@fetch_status=0 begin
	DECLARE @dip_nomesp varchar(300)
	SET @dip_nomesp = @iddbdepartment + '.emens_daticollaboratore'
		INSERT INTO #collaboratoremain (
                        departmentname,
                        cfcollaboratore,
                        cognome,
                        nome,
                        tiporapporto,
                        codiceattivita,
                        imponibile,
                        aliquota,
                        altraass,
                        dal,
                        al,
                        codicecomune,
                        codcalamita,
                        codcertificazione
    		)
                EXEC @dip_nomesp @ycommunication,@mcommunication,@mcommunication,@parentsp, @adate 
	FETCH NEXT FROM @crsdepartment INTO @iddbdepartment
END

SELECT @cap = cap FROM license
-- Il codice ISTAT è stato preso dalla classificazione per le attività produttive ATECO 2002 
-- (consultabile presso il sito www.istat.it)
SET @istat = '80301'
SELECT
	cfcollaboratore,
	cognome,
	nome,
	codicecomune,
	tiporapporto,
	codiceattivita,
	SUM(imponibile) as imponibile,
	aliquota,
	altraass,
	MIN(dal) as dal,
	MAX(al) as al,
	codcalamita,
	codcertificazione
FROM #collaboratoremain
GROUP BY cfcollaboratore,cognome,nome,codicecomune,tiporapporto,
	codiceattivita,aliquota,altraass,codcalamita,codcertificazione
END


