if object_id('[exp_class_child_inc]') is not null
	drop PROCEDURE [exp_class_child_inc]
go


CREATE        PROCEDURE [exp_class_child_inc]
(
	@ayear int,
	@sourcelevel smallint,
	@destlevel smallint,
	@idsorkind int
)
AS BEGIN
select 
	S.sortcode as codice,
	S.description as descrizione,
 SUM(
	case when (ES.ayear=@ayear) AND (ET_PARENT.flag & 1=0)  then ES.amount else 0 end
 ) as incassato_competenza_annocorr,
 SUM(
	case when (ES.ayear=@ayear) AND (ET_PARENT.flag & 1<>0)   then ES.amount else 0 end
 ) as incassati_residui_annocorr,
 SUM(
	case when (ES.ayear>@ayear) AND (ET_PARENT.flag & 1=0)  then ES.amount else 0 end
 ) as incassato_competenza_annisucc,
 SUM(
	case when (ES.ayear>@ayear) AND (ET_PARENT.flag & 1<>0)   then ES.amount else 0 end
 ) as incassato_residui_annisucc
 from sorting S
 left outer join incomesorted ES on ES.idsor=S.idsor
 join income E on ES.idinc=E.idinc AND  E.nphase= @destlevel 
 join incomelink EL on 
        EL.idchild=E.idinc  AND EL.nlevel= @sourcelevel 
 join incometotal ET_PARENT on 			--filtra l'impegno
        ET_PARENT.idinc=EL.idparent  AND ET_PARENT.ayear=@ayear    --sempre filtrato cosi
 join incomeyear EY_CHILD on  --filtra il pagamento
        EY_CHILD.idinc=E.idinc  AND EY_CHILD.ayear=ES.ayear
 
where S.idsorkind=@idsorkind
group by S.sortcode,S.description
order by S.sortcode
END


