if object_id('[rpt_anagrafica_partitario_unified]') is not null
	drop PROCEDURE [rpt_anagrafica_partitario_unified]
go

CREATE          PROCEDURE [rpt_anagrafica_partitario_unified]
	@ayear int,
	@title varchar(100), 
	@start datetime,
	@stop datetime,
    @unified char(1) -- consolidamento dei dati 
AS
BEGIN
IF (@unified <> 'S')
BEGIN
        EXEC rpt_anagrafica_partitario @ayear, @title, @start, @stop
        RETURN
END 
CREATE TABLE #unified (
    departmentname  varchar(150),
	idreg int,
	title varchar(100),
	cf varchar(16),  
	p_iva varchar(15),
	rowkind int,
	competencydate datetime,
	operationkind varchar(55),
	ymov int,
	nmov int,
	nvar int,
	npro_npay int,
	description varchar(150),
 	doc varchar(35),
	docdate datetime,
	proceeds float,
	payment	float	
)
DECLARE @iddbdepartment varchar(50)
DECLARE crsdepartment  cursor LOCAL STATIC FOR 
SELECT iddbdepartment FROM dbdepartment 
WHERE (start is null or start <= @ayear ) AND ( stop is null or stop >= @ayear)
FOR READ ONLY
OPEN crsdepartment
FETCH NEXT FROM crsdepartment INTO @iddbdepartment
WHILE @@fetch_status=0 begin
	DECLARE @dip_nomesp varchar(300)
        SET @dip_nomesp = '['+@iddbdepartment+']'+ '.rpt_anagrafica_partitario'
PRINT @iddbdepartment
		INSERT INTO #unified (
                departmentname,
				idreg,
				title,
				cf, 
				p_iva,
				rowkind,
				competencydate,
				operationkind ,
				ymov ,
				nmov ,
				nvar ,
				npro_npay ,
				description,
 				doc,
				docdate,
				proceeds,
				payment	
)
		EXEC @dip_nomesp @ayear, @title, @start, @stop
	FETCH NEXT FROM crsdepartment INTO @iddbdepartment
end
DEALLOCATE crsdepartment
SELECT
        departmentname,
		idreg,
		title,
		cf, 
		p_iva,
		rowkind,
		competencydate,
		operationkind ,
		ymov ,
		nmov ,
		nvar ,
		npro_npay ,
		description,
		doc,
		docdate,
		proceeds,
		payment	
FROM #unified
ORDER BY title ASC, 
	competencydate ASC, 
	rowkind ASC,
	ymov ASC,
	nmov ASC,
	nvar ASC
DROP TABLE #unified
END

