CREATE    PROCEDURE [rpt_unifiedanagrafedelleprestazioni]
(
	@ayear smallint, 
	@idreg int, 
	@start datetime,
	@stop datetime,
	@show_addr_anagp char(1),
	@unified char(1)
)
AS BEGIN

IF (@unified <> 'S')
BEGIN
        EXEC rpt_anagrafedelleprestazioni @ayear, @idreg, @start, @stop, @show_addr_anagp
 
        RETURN
END 

CREATE TABLE #outtable(
		departmentname varchar(150),
		idexp int,
		idreg int,
		registry varchar(100),
		b_city varchar(120),
		birthdate datetime,
		b_province varchar(2),
		b_nation varchar(65),
		cf varchar(16),
		taxref varchar(20), 
		description varchar(50),
		service varchar(50),
		codeser varchar(20),
		upb varchar(150),
		fin varchar(150),
		codefin varchar(50),
		npay int,
		manager varchar(150),
		taxablenet decimal(19,2),
		grossamount decimal(19,2),
		employtax decimal(19,2),
		sent_office varchar(50),
		sent_agency varchar(50),
		sent_address varchar(100),
		sent_idaddresskind varchar(20), 
		sent_location varchar(120),
		sent_cap varchar(20),
		sent_province varchar(2),
		sent_nation varchar(65),
		residence_address varchar(100),
		residence_idaddresskind varchar(20),
		residence_location varchar(120),
		residence_cap varchar(20),
		residence_province varchar(2),
		residence_nation varchar(65),
		descriptioncontract varchar(150),
		start datetime,
		stop datetime
)

	declare @iddbdepartment varchar(50)
	declare @crsdepartment cursor
	set 	@crsdepartment = cursor for select  iddbdepartment from dbdepartment
	open 	@crsdepartment
	fetch next from @crsdepartment into @iddbdepartment
	while @@fetch_status=0 begin
		declare @dip_nomesp varchar(300)
		set @dip_nomesp = @iddbdepartment + '.rpt_anagrafedelleprestazioni'
		insert into #outtable 
			(
			departmentname,
			idexp ,
			idreg ,
			registry,
			b_city,
			birthdate,
			b_province,
			b_nation,
			cf,
			taxref, 
			description,
			service,
			codeser,
			upb,
			fin,
			codefin,
			npay,
			manager,
			taxablenet,
			grossamount,
			employtax,
			sent_office,
			sent_agency,
			sent_address,
			sent_idaddresskind, 
			sent_location,
			sent_cap,
			sent_province,
			sent_nation,
			residence_address,
			residence_idaddresskind,
			residence_location,
			residence_cap,
			residence_province,
			residence_nation,
			descriptioncontract,
			start,
			stop
			)

			exec @dip_nomesp @ayear, @idreg, @start, @stop, @show_addr_anagp
			
				fetch next from @crsdepartment into @iddbdepartment
	END

	
SELECT  	
			departmentname,
			idexp ,
			idreg ,
			registry,
			b_city,
			birthdate,
			b_province,
			b_nation,
			cf,
			taxref, 
			description,
			service,
			codeser,
			upb,
			fin,
			codefin,
			npay,
			manager,
			taxablenet,
			grossamount,
			employtax,
			sent_office,
			sent_agency,
			sent_address,
			sent_idaddresskind, 
			sent_location,
			sent_cap,
			sent_province,
			sent_nation,
			residence_address,
			residence_idaddresskind,
			residence_location,
			residence_cap,
			residence_province,
			residence_nation,
			descriptioncontract,
			start,
			stop
FROM #outtable
ORDER BY registry, departmentname











END


