-------------- REVERSALI RECORD 6 ---------------
-------------------------------------------------	
-- RECORD CHE DEVE ESSERE GESTITO PER QUEI 
-- DOCUMENTI  A REGOLARIZZAZIONE DI 
-- PROVVISORI
INSERT INTO #trace (y, n, ndoc, nrow, kind,out_str)
SELECT
	yproceedstransmission, Nproceedstransmission, ndoc, 6,'0',
	-- Tipo Record
	@prefisso_record +
	--NREV
	-- Numero Reversale
	ndocformatted +
	-- Numero Subordinativo (idpro) NSUB
	CONVERT(varchar(7),[dbo].getint(idpro, @len_numericdata)) +
	-- TIPO RECORD CTIPREC
	'6' +
	-- NPRO
	REPLICATE('0',7 - LEN(CONVERT(varchar(7),nbill))) + CONVERT(varchar(7),nbill) + --numero del provvisorio emesso per la riscossione anticipata
	--IREG
	SUBSTRING(REPLICATE('0',@len_amount),1,1 + @len_amount - DATALENGTH(CONVERT(varchar(15),SUM(curramount))))  +
	SUBSTRING(CONVERT(varchar(15),SUM(curramount)),1, DATALENGTH(CONVERT(varchar(15),SUM(curramount)))-3)  +
	SUBSTRING(CONVERT(varchar(15),SUM(curramount)), DATALENGTH(CONVERT(varchar(15),SUM(curramount)))-1,2) + --importo del provvisorio emesso per il pagamento anticipato
	-- FILLER
	SPACE(336) +
	@opkind + 
	'R'
FROM #proceeds
WHERE fulfilled = 'S'
GROUP BY yproceedstransmission, nproceedstransmission, ydoc, ndoc, ndocformatted, idpro, fulfilled, nbill
