if object_id('[trigger_i_incomeyear]') is not null
	drop TRIGGER [trigger_i_incomeyear]
go

CREATE      TRIGGER [trigger_i_incomeyear] ON [incomeyear] FOR INSERT
AS BEGIN
	DECLARE @finphase tinyint
	SELECT @finphase = incomefinphase FROM uniconfig
	DECLARE @proceedsphase tinyint	
	SELECT @proceedsphase = MAX(nphase) FROM incomephase
	DECLARE @ybalance int	
	EXECUTE trg_yearbalance 'I', @ybalance OUTPUT	
	DECLARE @idinc int
	DECLARE @ayear int
	DECLARE @nphase tinyint
	DECLARE @idfin int
	DECLARE @idupb varchar(36)
	DECLARE @amount decimal(19,2)
	DECLARE @ymov int
	DECLARE @parentidinc int
	DECLARE @idunderwriting int
	SELECT @idinc = inserted.idinc, 
	@ayear = inserted.ayear, 
	@nphase = income.nphase, 
	@idfin = inserted.idfin, 
	@idupb = inserted.idupb,
	@amount = inserted.amount,
	@ymov = income.ymov,
	@parentidinc = income.parentidinc,
	@idunderwriting = income.idunderwriting	
	FROM inserted
	JOIN income
	ON income.idinc = inserted.idinc
	IF (SELECT COUNT(*) FROM incomelink WHERE idchild = @idinc) = 0
	BEGIN
		INSERT INTO incomelink (idchild, nlevel, idparent)
		VALUES(@idinc, @nphase, @idinc)
	
		DECLARE @currphase tinyint
		SET @currphase = @nphase - 1
	
		DECLARE @currpar int
		SET @currpar = @parentidinc
	
		WHILE (@currphase >= 1)
		BEGIN
			INSERT INTO incomelink (idchild, nlevel, idparent)
			VALUES(@idinc, @currphase, @currpar)
	
			SET @currpar = (SELECT parentidinc FROM income WHERE idinc = @currpar)
			SET @currphase = @currphase - 1
		END
	END
	DECLARE @firstyear tinyint
	SET @firstyear = CASE WHEN @ymov = @ayear THEN 2 ELSE 0 END
	DECLARE @ymovparfin int
	SELECT @ymovparfin = income.ymov 
	FROM incomelink
	JOIN income
	ON incomelink.idparent = income.idinc
	WHERE idchild = @idinc
		AND nlevel = @finphase
	IF @idfin IS NOT NULL
	BEGIN
		IF (@ymovparfin = @ayear)
		BEGIN
			EXECUTE trg_ins_amount 
			@ayear, 
			'I', 
			@idinc, 
			@parentidinc,
			@amount, 
			0, -- Competenza
			@firstyear
			EXECUTE trg_upd_upbmovtotal 
			'I', 
			@idfin, 
			@idupb,
			'C', 
			@nphase, 
			@amount
		END
		ELSE
		BEGIN
			EXECUTE trg_ins_amount 
			@ayear, 
			'I', 
			@idinc, 
			@parentidinc,
			@amount, 
			1, -- Residuo
			@firstyear
			EXECUTE trg_upd_upbmovtotal 
			'I', 
			@idfin, 
			@idupb,
			'R', 
			@nphase, 
			@amount
		END
	END
	ELSE
	BEGIN
			EXECUTE trg_ins_amount 
			@ayear, 
			'I', 
			@idinc, 
			@parentidinc,
			@amount, 
			0,
			@firstyear
	END
	IF @idunderwriting IS NOT NULL
	BEGIN
		select @idunderwriting
		select 	@nphase
		select @amount
			
		IF (@ymovparfin = @ayear)
		BEGIN
			EXECUTE trg_upd_underwritingmovtotal 
			'I', 
			@idunderwriting,
			@idupb,
			@idfin,
			'C', 
			@nphase, 
			@amount
		END
		ELSE
		BEGIN
			EXECUTE trg_upd_underwritingmovtotal 
			'I', 
			@idunderwriting,
			@idupb,
			@idfin,
			'R', 
			@nphase, 
			@amount
		END
	END
	
	IF @ayear = @ybalance
	BEGIN
		IF @nphase < @proceedsphase
		BEGIN
			EXECUTE trg_evaluatearrears
			'I',
			@idinc,
			@ayear,
			@nphase
		END
		ELSE
		BEGIN
			DECLARE @currentphase tinyint
			DECLARE @idcurrentinc int
			SET @idcurrentinc = @idinc
			SELECT @currentphase = (@proceedsphase - 1)
			WHILE @currentphase > 0 
			BEGIN
				SELECT @idcurrentinc = idparent FROM incomelink WHERE idchild = @idcurrentinc
					AND nlevel = @currentphase
				EXECUTE trg_evaluatearrears
				'I',
				@idcurrentinc,
				@ayear,
				@currentphase
	
				SELECT @currentphase = @currentphase - 1
			END
/*
			DECLARE @currentphase tinyint
			DECLARE @idcurrentinc int
			SET @idcurrentinc = @idinc
			SELECT @currentphase = 1
			WHILE @currentphase < @proceedsphase
			BEGIN
				SELECT @idcurrentinc = idparent FROM incomelink WHERE idchild = @idinc
					AND nlevel = @currentphase
				EXECUTE trg_evaluatearrears
				'I',
				@idcurrentinc,
				@ayear,
				@currentphase
	
				SELECT @currentphase = @currentphase + 1
			END
*/
		END
	END
END

GO

print '[trigger_i_incomeyear] OK'

