-- (PAGAMENTO DI MAV, F23) ECC. CHE VIENE POSTICIPATO
-- AL MOMENTO DELLA RICEZIONE DELL'ALLEGATO CARTACEO
INSERT INTO #trace (y, n, ndoc, nrow, kind,out_str)
