CREATE       PROCEDURE [rpt_unified_certificazione_premi]
(
	@ayear smallint, 
	@idreg int, 
	@certificatekind char(1),
        @unified char(1) -- consolidamento dei dati 
)
AS BEGIN
IF (@unified <> 'S')
BEGIN
        EXEC rpt_certificazione_premi @ayear, @idreg, @certificatekind
        RETURN
END 
CREATE TABLE #unified (
        departmentname  varchar(150),
	idexp int,
	idreg int ,
	registry varchar(100),
	b_city varchar(120),
   	birthdate smalldatetime,
	b_province varchar(2),
	b_nation varchar(65),
	cf varchar(16),
	taxdescription varchar(50),
	expensedescription varchar(150),	
	service varchar(50),
	idser int,
	npay int,
	taxablenet decimal(19,2),
	grossamount decimal(19,2), --Importo Lordo del Pagamento
	employtax decimal(19,2),
	admintax decimal(19,2),
	taxablegross decimal(19,2), -- Imponibile Lordo
	sent_office varchar(50),
	sent_address varchar(100),
	sent_idaddresskind varchar(20),
	sent_location varchar(120),
	sent_cap varchar(20),
	sent_province varchar(2),
	sent_nation varchar(65)
)

DECLARE @iddbdepartment varchar(50)
DECLARE @crsdepartment cursor
SET @crsdepartment = cursor FOR SELECT iddbdepartment FROM dbdepartment
OPEN @crsdepartment
FETCH NEXT FROM @crsdepartment INTO @iddbdepartment
WHILE @@fetch_status=0 begin
	DECLARE @dip_nomesp varchar(300)
	SET @dip_nomesp = @iddbdepartment + '.rpt_certificazione_premi'
PRINT @iddbdepartment
		INSERT INTO #unified (
                        departmentname,
                	idexp,
                	idreg,
                	registry,
                	b_city,
                   	birthdate,
                	b_province,
                	b_nation,
                	cf,
                	taxdescription,
                	expensedescription,	
                	service,
                	idser,
                	npay,
                	taxablenet,
                	grossamount,--Importo Lordo del Pagamento
                	employtax,
                	admintax,
                	taxablegross, -- Imponibile Lordo
                	sent_office,
                	sent_address,
                	sent_idaddresskind, 
                	sent_location,
                	sent_cap,
                	sent_province,
                	sent_nation
		)
		EXEC @dip_nomesp @ayear, @idreg, @certificatekind
	FETCH NEXT FROM @crsdepartment INTO @iddbdepartment
end
SELECT
        departmentname,
	idexp,
	idreg,
	registry,
	b_city,
   	birthdate,
	b_province,
	b_nation,
	cf,
	taxdescription,
	expensedescription,	
	service,
	idser,
	npay,
	taxablenet,
	grossamount,--Importo Lordo del Pagamento
	employtax,
	admintax,
	taxablegross, -- Imponibile Lordo
	sent_office,
	sent_address,
	sent_idaddresskind, 
	sent_location,
	sent_cap,
	sent_province,
	sent_nation
FROM #unified


END


