CREATE   PROCEDURE [exp_mov_blacklist]
(	@anno int,
	@start smalldatetime,
	@stop smalldatetime
)
AS
BEGIN
--sp_help EXPENSEmov
CREATE TABLE #movfin
	(
		idexp int, 
		phase varchar(50), 
		adate smalldatetime,
		ymov  int,
		nmov  int, 
		codefin varchar(50), 
		finance varchar(150), 
		codeupb varchar(50), 
		upb varchar(150), 
		idreg int, 
		registry varchar(100),
		ypay int,
		npay int, 
		description varchar(150),
		curramount decimal(19,2),
		idblacklist int,
		blnation varchar(100),
		blcode char(3)
	)
DECLARE @idexp INT
DECLARE @adate SMALLDATETIME
DECLARE @idreg INT

DECLARE @idblacklist int
DECLARE @blcode char(3)
-- CICLO CON CURSORE PER DETERMINARE IL PAESE DI RESIDENZA DEL CLIENTE/FORNITORE
DECLARE rowcursor INSENSITIVE CURSOR FOR
SELECT idexp,
	   adate,
       idreg
FROM expenselastview E
WHERE YEAR(E.adate) = @anno
AND E.adate BETWEEN @start AND @stop
AND NOT EXISTS (SELECT * FROM expenseinvoice EI WHERE EI.idexp = E.idexp )
--ORDER BY MONTH(E.adate), E.ymov, E.nmov 
FOR READ ONLY
OPEN rowcursor
FETCH NEXT FROM rowcursor
INTO  @idexp,
      @adate,
	  @idreg
WHILE @@FETCH_STATUS = 0
BEGIN 
SET @idblacklist  = NULL
set @blcode  = NULL
EXECUTE [get_address] 
   @idreg
  ,@adate
  ,@idblacklist OUTPUT
  ,@blcode OUTPUT
	
 print @idblacklist
	IF (@idblacklist) IS NOT NULL
	BEGIN
				INSERT INTO #movfin
						(
				idexp, 
				phase, 
				adate,
				ymov,
				nmov, 
				codefin, 
				finance, 
				codeupb, 
				upb, 
				idreg, 
				registry,
				ypay,
				npay, 
				description,
				curramount,
				idblacklist,
				blnation,
				blcode
		)
		SELECT 
				E.idexp, 
				E.phase, 
				E.adate,
				E.ymov,
				E.nmov, 
				E.codefin, 
				E.finance, 
				E.codeupb, 
				E.upb, 
				E.idreg, 
				R.title,
				E.ypay,
				E.npay, 
				E.description,
				E.curramount,
				@idblacklist,
				B.description,
				@blcode
		FROM registry as R
		JOIN expenselastview as E
			ON R.idreg = E.idreg
		JOIN blacklist B ON B.idblacklist = @idblacklist
		WHERE E.idexp = @idexp
	END	
		
	FETCH NEXT FROM rowcursor
	INTO  @idexp,
		  @adate,
		  @idreg
END 
DEALLOCATE rowcursor
SELECT 
		phase as 'Fase',
		ymov as 'Eserc.',
		nmov as 'Numero',
		adate as 'Data Contabile',
		description as 'Descrizione',
		curramount as 'Importo',
		ypay as 'Eserc. Mandato',
		npay as 'Num. Mandato',
		idreg as 'Codice Anagrafica',
		registry as 'Anagrafica',
		blnation as 'Nazione',
		blcode as 'Codice Nazione Black List'
FROM #movfin WHERE blnation is not null
ORDER BY MONTH(adate),ymov,nmov
END

