	weight decimal(19,2),
	OrigDescription varchar(100), 
	ProvDescription varchar(100), 
	geo_country_destination varchar(50), 
	Destination  varchar(100), 
	geo_country_origin varchar(50), 
	numerofattura varchar(15),				
	datafattura  varchar(6),			
