CREATE         TRIGGER [trigger_i_expenseyear] ON [expenseyear] FOR INSERT
AS BEGIN
	DECLARE @finphase int
	SELECT @finphase = expensefinphase FROM uniconfig
	DECLARE @paymentphase tinyint
	SELECT @paymentphase = MAX(nphase) FROM expensephase
	DECLARE @ybalance int
	EXECUTE trg_yearbalance 'E', @ybalance OUTPUT	
	DECLARE @idexp int
	DECLARE @ayear int
	DECLARE @nphase tinyint
	DECLARE @idfin int
	DECLARE @idupb varchar(36)
	DECLARE @amount decimal(19,2)
	DECLARE @ymov int
	DECLARE @parentidexp int
	SELECT @idexp = inserted.idexp, 
	@ayear = inserted.ayear, 
	@nphase = expense.nphase, 
	@idfin = inserted.idfin, 
	@idupb = inserted.idupb,
	@amount = inserted.amount,
	@ymov = expense.ymov,
	@parentidexp = expense.parentidexp
	FROM inserted
	JOIN expense
	ON expense.idexp = inserted.idexp
	IF (SELECT COUNT(*) FROM expenselink WHERE idchild = @idexp) = 0
	BEGIN
		INSERT INTO expenselink (idchild, nlevel, idparent)
		VALUES(@idexp, @nphase, @idexp)
	
		DECLARE @currphase tinyint
		SET @currphase = @nphase - 1
	
		DECLARE @currpar int
		SET @currpar = @parentidexp
	
		WHILE (@currphase >= 1)
		BEGIN
			INSERT INTO expenselink (idchild, nlevel, idparent)
			VALUES(@idexp, @currphase, @currpar)
	
			SET @currpar = (SELECT parentidexp FROM expense WHERE idexp = @currpar)
			SET @currphase = @currphase - 1
		END
	END
	DECLARE @ymovpar int
	SELECT @ymovpar = expense.ymov 
	FROM expenselink
	JOIN expense
	ON expenselink.idparent = expense.idexp
	WHERE idchild = @idexp
		AND nlevel = @finphase
	DECLARE @firstyear tinyint
	SET @firstyear = CASE WHEN @ymov = @ayear THEN 2 ELSE 0 END
	DECLARE @ymovparfin int
	SELECT @ymovparfin = expense.ymov 
	FROM expenselink
	JOIN expense
	ON expenselink.idparent = expense.idexp
	WHERE idchild = @idexp
		AND nlevel = @finphase
	
	IF @idfin IS NOT NULL
	BEGIN
		IF (@ymovparfin = @ayear)
		BEGIN
			EXECUTE trg_ins_amount 
			@ayear, 
			'E', 
			@idexp, 
			@parentidexp, 
			@amount, 
			0, -- Competenza
			@firstyear
			EXECUTE trg_upd_upbmovtotal
			'E', 
			@idfin, 
			@idupb,
			'C', 
			@nphase, 
			@amount
		END
		ELSE
		BEGIN
			EXECUTE trg_ins_amount 
			@ayear, 
			'E', 
			@idexp,
			@parentidexp,
			@amount, 
			1, -- Residuo
			@firstyear
			EXECUTE trg_upd_upbmovtotal
			'E', 
			@idfin, 
			@idupb,
			'R', 
			@nphase, 
			@amount
		END
	END
	ELSE
	BEGIN
			EXECUTE trg_ins_amount 
			@ayear, 
			'E', 
			@idexp, 
			@parentidexp,
			@amount, 
			0,
			@firstyear
	END
	IF @ayear = @ybalance
	BEGIN
		IF @nphase < @paymentphase
		BEGIN
			EXECUTE trg_evaluatearrears
			'E',
			@idexp,
			@ayear,
			@nphase
		END
		ELSE
		BEGIN
			DECLARE @currentphase tinyint
			DECLARE @idcurrentexp int
			SET @idcurrentexp = @idexp
			SELECT @currentphase = (@paymentphase - 1)
			WHILE @currentphase > 0 
			BEGIN
				SELECT @idcurrentexp = idparent FROM expenselink WHERE idchild = @idcurrentexp
					AND nlevel = @currentphase
				EXECUTE trg_evaluatearrears
				'E',
				@idcurrentexp,
				@ayear,
				@currentphase
	
				SELECT @currentphase = @currentphase - 1
			END
/*
			DECLARE @currentphase tinyint
			DECLARE @idcurrentexp int
			SET @idcurrentexp = @idexp
			SELECT @currentphase = 1
			WHILE @currentphase < @paymentphase
			BEGIN
				SELECT @idcurrentexp = idparent FROM expenselink WHERE idchild = @idexp
					AND nlevel = @currentphase
				EXECUTE trg_evaluatearrears
				'E',
				@idcurrentexp,
				@ayear,
				@currentphase
	
				SELECT @currentphase = @currentphase + 1
			END
*/
		END
	END
END


